// Statički generirana obrazloženja distraktora — "zašto je svaki pogrešan odgovor kriv".
// Popunjava se ručno / subagentski (bez API troška) i SPAJA skriptom
// scripts/distraktori-merge.mjs — ne uređivati ručno između spajanja.
// Runtime trošak = 0 (bez API poziva po pregledu). Lazy-load u AnswerHelperu.
//
// Ključ:    "<examKey>__<qid>"   (npr. "2025_ljeto__12")
// Vrijednost: { "<slovo pogrešne opcije>": "kratko obrazloženje zašto je krivo", ... }
//             (točan odgovor se NE uključuje — njega objašnjava postojeći q.exp)
export const EXP_DISTRAKTORI = {
  // 2010_jesen_A
  "2010_jesen_A__1": {"B":"Epika obuhvaća pripovjedna djela s fabulom i pripovjedačem, a ovdje su dvije pjesme.","C":"Drama je rod namijenjen izvedbi s dijalozima i didaskalijama, čega u ovim pjesmama nema."},
  "2010_jesen_A__2": {"A":"Čežnja podrazumijeva žudnju za nečim, a u pjesmama prevladava tmurna slika jeseni bez izražene žudnje.","B":"Elegičnost nosi tugu za izgubljenim, no temeljni je dojam mračan i potišten, dakle sumornost.","D":"Zagonetnost upućuje na tajanstvenost i nedorečenost, a ugođaj je ovdje jasno tmuran i hladan."},
  "2010_jesen_A__3": {"B":"Stih ne govori o opasnim vremenima za pjesnike, nego o gluhom mraku koji ne čuje jablanovu poruku.","C":"Pridjev 'gluh' ne označava doba noći, nego mrak koji ne čuje, pa poruka ostaje nerazumljena.","D":"Jablan šapće o životu, dakle nije izgubio vjeru, samo ga nitko ne čuje."},
  "2010_jesen_A__4": {"A":"Onomatopeja oponaša zvukove iz prirode, a ovdje ponavljanje glasova stvara tmurni ugođaj, a ne zvučnu sliku.","B":"Hiperbola je pretjerivanje, no ponavljanje glasova 'm' i 'cr' služi dočaravanju zlokobnosti, a ne uveličavanju.","D":"Ponavljanje tamnih glasova usporava i otežava ritam, a ne ubrzava ga."},
  "2010_jesen_A__5": {"A":"U ovom stihu nema istaknutog ponavljanja istih samoglasnika, nego suglasnika.","B":"Ovdje prevladava ponavljanje suglasnika, što je aliteracija, a ne asonanca.","C":"U ovom stihu nema dosljednog ponavljanja istog samoglasnika koje bi tvorilo asoncu."},
  "2010_jesen_A__6": {"A":"'Tužnije' ima jasan antonimski par (tužan ↔ veseo), pa ima antonim u denotativnom značenju.","B":"'Gladnije' ima antonimski par (gladan ↔ sit), pa ima antonim u denotativnom značenju.","C":"'Tamnije' ima antonimski par (taman ↔ svijetao), pa ima antonim u denotativnom značenju."},
  "2010_jesen_A__7": {"A":"'Tamnije' i 'tužnije' znače različito (mrak naspram tuge), pa nisu sinonimi.","C":"'Tužnije' i 'ružnije' upućuju na različita značenja (žalost naspram ružnoće), pa nisu sinonimi.","D":"'Hladnije' i 'jesenije' nisu istoznačni; jesen tek asocira na hladnoću, ali joj nije sinonim."},
  "2010_jesen_A__8": {"A":"Palatalizacija pretvara k, g, h u č, ž, š pred samoglasnikom, a ovdje se mijenja d + j u đ.","B":"Sibilarizacija pretvara k, g, h u c, z, s, a ovdje nema tih glasova.","D":"Jednačenje po zvučnosti tiče se susjednih zvučnih i bezvučnih suglasnika, a ovdje je posrijedi spajanje d i j u đ."},
  "2010_jesen_A__9": {"A":"Glagol 'biti' nije u pjesmi; oblik 'biva' tvori se od 'bivati', a ne od 'biti'.","B":"Glagol 'htjeti' ne pojavljuje se u pjesmi.","C":"Glagol 'imati' ne pojavljuje se u pjesmi."},
  "2010_jesen_A__10": {"A":"Matoš nije nadrealist, a Krleža nije realist; riječ je o impresionizmu i ekspresionizmu.","B":"Ni romantizam ni klasicizam ne odgovaraju ovim pjesnicima moderne i avangarde.","D":"Futurizam i imažinizam nisu pravci ovih dvaju autora."},
  "2010_jesen_A__11": {"A":"Pjesme nisu iz istog razdoblja (moderna naspram avangarde), pa ih razdoblje ne povezuje.","C":"Oblici se razlikuju: Matoš piše sonet, a Krleža slobodni stih, pa ih oblik ne povezuje.","D":"Stilovi su različiti (impresionizam i ekspresionizam), pa ih stil ne povezuje."},
  "2010_jesen_A__12": {"A":"Balada je pripovjedna pjesma s tragičnim događajem, a ovo je sonet od 14 stihova bez fabule.","B":"Gazela je orijentalni oblik s posebnom shemom rime, a ovo je sonet.","C":"Glosa razrađuje uvodne stihove (temu) u zasebnim strofama, čega ovdje nema."},
  "2010_jesen_A__13": {"A":"Shema abab cdcd ne odgovara katrenima soneta koji imaju obgrljenu rimu.","B":"Shema abab abab ne odgovara obgrljenoj rimi katrena u ovom sonetu.","C":"Shema abba cddc ne odgovara rimi tercina, koja glasi cdc dee."},
  "2010_jesen_A__14": {"A":"Metafora je prijenos značenja po sličnosti, a ovdje je ljudska radnja (snivanje) pridana oblacima.","C":"Simbol je predmet koji upućuje na šire značenje, a ovdje je posrijedi oživljavanje oblaka.","D":"Eufemizam je ublažavanje neugodnog izraza, čega u ovim stihovima nema."},
  "2010_jesen_A__15": {"A":"Pravilna izmjena naglašenih i nenaglašenih slogova obilježje je vezanog stiha, a Krleža piše slobodnim stihom.","B":"Prenošenje i opkoračenje nisu glavno ritmotvorno sredstvo ove pjesme.","D":"Ritam ne počiva na rimi i glasovnim ponavljanjima, nego na izboru i rasporedu riječi."},
  "2010_jesen_A__16": {"B":"Auditivni motiv vezan je uz zvuk, a početak donosi vizualnu sliku oblaka.","C":"Taktilni motiv tiče se opipa, čega na početku pjesme nema.","D":"Gustativni motiv vezan je uz okus, čega u pjesmi nema."},
  "2010_jesen_A__17": {"A":"'Visok' opisuje fizičku dimenziju, a 'gord' ovdje znači uznositost i ponos.","C":"'Hvalisav' nosi negativan prizvuk razmetanja, a 'gord' ovdje znači dostojanstvenu uznositost.","D":"'Mudar' se odnosi na razboritost, a 'gord' ovdje znači ponosit, uznosit."},
  "2010_jesen_A__18": {"A":"Osmerac ima osam slogova, a ovi stihovi imaju jedanaest.","B":"Deseterac ima deset slogova, a ovi stihovi imaju jedanaest.","D":"Dvanaesterac ima dvanaest slogova, a ovi stihovi imaju jedanaest."},
  "2010_jesen_A__19": {"A":"'Mr-e' i 'mrk-e' pogrešno su rastavljeni jer slog mora imati samoglasnik kao nositelja.","C":"'Mot-ri' i 'biv-a-ju' krivo su rastavljeni; pravilno je mo-tri i bi-va-ju.","D":"'Mr-e', 'mrk-e' i 'biv-a-ju' pogrešno su rastavljeni jer slog nositi samoglasnik."},
  "2010_jesen_A__20": {"A":"Načelo suprotnosti vrijedi za suprotne sastavnice (npr. 'ali'), a ovdje se istovrsni komparativi nižu.","C":"Inverzija je obrnuti red riječi, a zarez je ovdje zbog nabrajanja.","D":"Dodavanje (naknadno umetanje) nije razlog ovom zarezu; riječ je o nizanju istovrsnih članova."},
  "2010_jesen_A__21": {"A":"Sukladan odnos značio bi podudaranje, a posljednja strofa se značenjski razlikuje od prethodnih.","C":"Zavisan odnos podrazumijeva podređenost, a strofe su značenjski suprotstavljene.","D":"Usporedan odnos znači paralelno tečenje, a ovdje je posrijedi oprečnost unutarnjeg i vanjskog."},
  "2010_jesen_A__22": {"A":"U pjesmama su se okušala oba autora, pa to nije razlika među njima.","C":"Esej su pisali i Matoš i Krleža, pa to nije razlika među njima.","D":"Novele je pisao i Matoš, pa to nije ono čime se razlikuju."},
  "2010_jesen_A__23": {"A":"Eshil je autor Okovanog Prometeja i Orestije, a ne Antigone.","B":"Euripid je napisao Medeju i Hipolita, ali ne i Antigonu.","D":"Tespis se smatra začetnikom tragedije, ali nije autor Antigone."},
  "2010_jesen_A__24": {"A":"In medias res i invokacija obilježja su epa, a ne tragedije.","B":"Ab ovo i mitska podloga ne određuju tragediju kao vrstu (ab ovo je epsko pripovijedanje od početka).","D":"Deus ex machina i retardacija pojedinačni su postupci, a ne ključna obilježja tragedije."},
  "2010_jesen_A__25": {"A":"'Pučki obred' nije prijevod riječi tragedija.","B":"'Proljetna svečanost' nije značenje grčke riječi tragōidia.","C":"'Nesretni završetak' opisuje učinak tragedije, ali nije doslovan prijevod naziva."},
  "2010_jesen_A__26": {"A":"Izmena ne odvraća Antigonu od izdaje grada, nego od pokopa brata.","C":"Riječ nije o bijegu, nego o pokopu mrtvog brata.","D":"Sfinginu zagonetku rješava Edip u drugom djelu; to nije tema ovog razgovora."},
  "2010_jesen_A__27": {"A":"Antigona se ne suprotstavlja očevoj oporuci, nego kraljevu (Kreontovu) nalogu.","C":"Antigona upravo brani božju volju (dostojan pokop), a ne joj se suprotstavlja.","D":"Sudbinsko prokletstvo prati obitelj, ali Antigonin se otpor odnosi na Kreontovu zabranu."},
  "2010_jesen_A__28": {"B":"Izmena ne prijeti Antigoni, nego je upozorava na opasnost.","C":"U njezinim riječima nema bijesa, nego pribrane opomene.","D":"Stihovi izražavaju razboritu zabrinutost, a ne nervozu i nestrpljenje."},
  "2010_jesen_A__29": {"A":"Izmena nije ponosna i samoživa, nego se podčinjava vlasti i izbjegava sukob.","C":"Izmena nije prevrtljiva; dosljedno odbija prkos i bira poslušnost.","D":"Izmena nije prikazana kao usamljena u strahu, nego kao popustljiva i pomirljiva."},
  "2010_jesen_A__30": {"B":"Antigona nije prikazana kao potištena, nego kao odlučna i prkosna.","C":"Antigona nije ohola; njezina odluka proizlazi iz odanosti bratu i božjem zakonu.","D":"Antigona nije skromna i odmjerena, nego buntovna i nepokolebljiva."},
  "2010_jesen_A__31": {"A":"Antigonu ne vodi osveta, nego dužnost dostojnog pokopa brata.","B":"Ne radi se o iskupljenju za roditeljske pogreške, nego o poštivanju božanskog zakona.","C":"Antigona se suprotstavlja gradskoj vlasti, pa je ne vodi odanost kraljevstvu nego viši zakon."},
  "2010_jesen_A__32": {"B":"Izmena ne govori da su žene smatrane božanskim bićima, nego podčinjenima muškarcima.","C":"Iz njezinih riječi proizlazi da žene nisu povlaštene, nego potlačene.","D":"Izmena ne kaže da žene ne znaju koristiti prava, nego da su podvrgnute moćnijima."},
  "2010_jesen_A__33": {"B":"Kreont ne sprečava bijeg sestara; djelo završava nizom smrti.","C":"Zagonetka pripada priči o Edipu, a ne završetku Antigone.","D":"Djelo ne završava vjenčanjem, nego smrću Antigone, Hemona i Euridike."},
  "2010_jesen_A__34": {"A":"Elektra prikazuje sudbinu Agamemnonove kćeri, a ne Antigoninih roditelja.","B":"Ilijada je ep o Trojanskom ratu, a ne o Edipu i Jokasti.","D":"Okovani Prometej obrađuje mit o Prometeju, a ne o Antigoninim roditeljima."},
  "2010_jesen_A__35": {"A":"U registraturi je djelo Ante Kovačića, a ne ono iz kojeg je ulomak o Luciji.","B":"Zlatarovo zlato je Šenoin povijesni roman, a ne djelo o Stipančićima.","D":"Čuvaj se senjske ruke je Šenoina povijesna pripovijest, a ne ovaj tekst."},
  "2010_jesen_A__36": {"B":"Autobiografija pripovijeda autorov vlastiti život, a ovo je fikcionalni roman.","C":"Pripovijetka je kraća prozna vrsta, a Posljednji Stipančići opsežno je djelo, roman.","D":"Novela je kratka i sažeta s neočekivanim obratom, a ovdje je riječ o romanu."},
  "2010_jesen_A__37": {"A":"Komentiranje je piščev izravni sud, a prvi odlomak prevladava opisom slike.","C":"Dijaloga (razgovora dvaju likova) u prvom odlomku nema, nego opis.","D":"Monolog je govor jednog lika, a prvi odlomak donosi pripovjedačev opis."},
  "2010_jesen_A__38": {"A":"Posredna karakterizacija otkriva lik kroz postupke i govor drugih, a ovdje Lucija sama iznosi osjećaje.","C":"Opis i komentiranje koriste se za sliku, no raspoloženje se otkriva njezinim unutarnjim govorom.","D":"Retrospekcija je vraćanje u prošlost, a ovdje je posrijedi unutarnji monolog u sadašnjosti."},
  "2010_jesen_A__39": {"B":"Lucija nije razborita i smirena, nego emocionalno uzburkana.","C":"Nostalgija je čežnja za prošlim, a Lucija je prije svega uznemirena i potresena.","D":"Lucija nije samopouzdana, nego nesigurna i uzrujana."},
  "2010_jesen_A__40": {"B":"Očeva strogost nije ono što je u ovom ulomku muči, nego Alfredova odsutnost.","C":"Osiromašenje obitelji nije izvor njezine muke u ovom prizoru, nego Alfredova šutnja.","D":"Bratova nebriga nije tema njezina nemira ovdje, nego to što Alfred ne dolazi."},
  "2010_jesen_A__41": {"A":"'Površno odgojen' opisna je oznaka, ali izraziti piščev kritički sud nosi sintagma o bljutavom izrazu lica.","C":"'Bez mladenačke svježosti' dio je opisa, no najjasniji vrijednosni sud je 'lice bljutava izraza'.","D":"'Razdijeljena kosa na tjemenu' neutralan je opis izgleda, bez piščeva vrednovanja."},
  "2010_jesen_A__42": {"A":"U rečenici nema grižnje savjesti, nego žudnje za životom i slobodom.","C":"Lucija se ne oprašta od života, nego upravo izražava želju da ga doživi.","D":"Lucija nije pomirena sa životom, nego čezne za 'širokim svijetom' i punim životom."},
  "2010_jesen_A__43": {"A":"Divljenje nije ključno; ona Alfreda voli i čeka da dođe po nju.","B":"Lucija ne žali Alfreda, nego ga voli i nada se njegovu dolasku.","C":"Lucija ne mrzi Alfreda; obraća mu se s ljubavlju i čežnjom."},
  "2010_jesen_A__44": {"B":"Rečenica ne izražava strah da se zamjerila Alfredu, nego nadu u njegovu dobrotu.","C":"Lucija ne govori o vlastitoj neobrazovanosti, nego ističe Alfredove vrline i vjeru u njega.","D":"Rečenica ne upućuje na to da je Alfred izmišljen u vrućici, nego na Lucijinu nadu."},
  "2010_jesen_A__45": {"B":"Romantizam prethodi Novaku; on stvara u razdoblju realizma.","C":"Protorealizam je rana, predrealistička faza, a Novak je zreli hrvatski realist.","D":"Renesansa je starije razdoblje (16. st.), a Novak djeluje u 19. stoljeću."},
  "2010_jesen_A__46": {"A":"Pustolovna tematika nije obilježje ovog djela; ono prikazuje društveni slom obitelji.","C":"Povijesna tematika obrađuje prošle događaje kao temu, a ovdje je u središtu suvremeni društveni preokret.","D":"Filozofska tematika bavi se idejama o postojanju, a ovdje je riječ o društvenom propadanju."},
  "2010_jesen_A__47": {"A":"Raslojavanje sela i propast zadruga tema je drugih realističkih djela, a ne ovoga o gradskoj patricijskoj obitelji.","B":"Školovanje siromašnog dječaka nije tema ovog djela.","D":"Iako je ljubav prisutna, temeljna je tema propast patricijske obitelji u novom dobu."},
  "2010_jesen_A__48": {"B":"Smisao naslova nije u Lucijinoj udaji; ona se ne udaje, a rod propada propašću vrijednosti.","C":"Naslov ne upućuje na svađu oko nasljedstva, nego na nestanak roda i njegovih vrijednosti.","D":"Ne umiru svi članovi obitelji; sin Jurica ostaje živ, ali propao."},
  "2010_jesen_A__49": {"A":"Prozne vrste nisu poveznica; Kranjčević je ponajprije pjesnik, dok je Novak prozaik.","C":"Književne nagrade nisu ono što ih povezuje, nego zajednički rodni grad Senj.","D":"Lirske vrste nisu poveznica; Novak je prozaik, a poveznica je rodni Senj."},
  "2010_jesen_A__50": {"A":"'Užad' su vrsta konopa, a 'uze' arhaično znače okove (sredstvo zatočeništva).","B":"'Čvorovi' su spletovi užeta, a 'uze' znače okove.","C":"'Lanci' su blizu po značenju, ali ustaljeni sinonim arhaizma 'uze' jesu okovi."},
  "2010_jesen_A__51": {"A":"Izostavljeni tekst označavao bi se uglatim zagradama s trotočjem, a ovdje je riječ o samom govoru lika.","B":"Prekinuti tekst značio bi nedovršenu rečenicu, a ovdje trotočja prikazuju isprekidanost govora.","D":"Nenavedeni govor nije ono što trotočja označuju; ona dočaravaju emotivnu isprekidanost izgovaranja."},
  "2010_jesen_A__52": {"A":"Drama je namijenjena izvedbi s dijalozima i didaskalijama, a ovo je prozni tekst.","C":"Lirika izražava osjećaje u stihu, a ovaj je tekst pripovjedna proza.","D":"Diskurzivni (znanstveno-popularni) rod obuhvaća esej i raspravu, a ovo je fikcionalna proza."},
  "2010_jesen_A__53": {"B":"Rima i lirski subjekt obilježja su lirike, a ne epike.","C":"Rima je element lirike, pa taj niz ne određuje epiku.","D":"Prizor i sažetost izraza upućuju na dramu i kratke forme, a ne na epska obilježja."},
  "2010_jesen_A__54": {"A":"Tragedija pripada drami, pa ovaj niz nije čisto epski.","B":"Elegija i poema pripadaju lirici, pa ovaj niz nije čisto epski.","D":"Epigram pripada lirici, pa ovaj niz nije čisto epski."},
  "2010_jesen_A__55": {"B":"Treće lice prepoznalo bi se po oblicima 'on/ona', a ovdje pripovjedač govori o sebi ('pitao sam se').","C":"Drugo lice obraćalo bi se 'ti', čega u tekstu nema."},
  "2010_jesen_A__56": {"B":"Epsko pripovijedanje opći je naziv za rod, a pitanje traži način (subjektivni naspram objektivnog).","C":"Objektivno pripovijedanje vodilo bi se iz vanjske perspektive, a ovdje pripovjedač iznosi vlastita unutarnja stanja.","D":"'Lirsko pripovijedanje' nije naziv tehnike pripovijedanja u proznom tekstu."},
  "2010_jesen_A__57": {"B":"Ivan Aralica autor je drugih romana, a ne Kratkog izleta.","C":"Pavao Pavličić nije autor Kratkog izleta.","D":"Ranko Marinković napisao je Kiklopa i druga djela, ali ne Kratki izlet."},
  "2010_jesen_A__58": {"B":"Zaborav nije temeljni motiv; djelo je građeno na traganju i potrazi.","C":"Kretanje je tek vanjski okvir putovanja, a temeljni je motiv potraga za smislom.","D":"Sjećanje nije nosivi motiv; u središtu je potraga za smislom i identitetom."},
  "2010_jesen_A__59": {"A":"Glavni lik nema imena, pa nije Petar.","B":"Glavni lik nema imena, pa nije Ivan.","C":"Glavni lik nema imena, pa nije Vladimir."},
  "2010_jesen_A__60": {"A":"Combray je Proustov motiv, a ženski likovi nose imena iz Odiseje.","B":"Hamlet ne daje imena ženskim likovima u Kratkom izletu; ona dolaze iz Odiseje.","D":"Stranac nije izvor imenovanja ženskih likova; to je Homerova Odiseja."},
  "2010_jesen_A__61": {"A":"Pitanja nisu socijalna (o društvenim odnosima), nego o samom postojanju.","C":"Pitanja nisu vjerska, nego egzistencijalna ('Gdje sam? Što je sa svijetom?').","D":"Pitanja nisu ekološka, nego se tiču smisla vlastitog postojanja."},
  "2010_jesen_A__62": {"A":"Ponavljanjem 'možda' ne izriče se neprihvatljivost, nego nesigurnost.","B":"Niz uvjetnih 'možda' upravo poriče samouvjerenost i odaje sumnju.","D":"Anafora 'možda' ne izražava samokritičnost, nego nesigurnost u pretpostavkama."},
  "2010_jesen_A__63": {"A":"Izletnici nisu stari školski prijatelji, nego slučajno okupljeni mladi ljudi.","C":"Nisu kolege s posla na zajedničkom projektu, nego slučajno okupljeni mladi intelektualci.","D":"Nisu sredovječni muškarci sa suprugama, nego mladi intelektualci."},
  "2010_jesen_A__64": {"B":"Skupina ne putuje na otok, nego kroz Istru.","C":"Cilj nije bezimeni grad, nego putovanje kroz Istru.","D":"Skupina ne ide na Velebit, nego putuje Istrom."},
  "2010_jesen_A__65": {"A":"Prostor nije puki prikaz ljepote zemlje, nego metafora unutarnje potrage.","B":"Krajolik nije idilična ekloga, nego mjesto traganja za identitetom.","D":"Prostor nije okvir sukoba likova, nego metafora potrage za smislom."},
  "2010_jesen_A__66": {"B":"Završetak ne izražava sukob, nego pomirbu s vlastitom sudbinom.","C":"U prihvaćanju krajolika nema ljutnje, nego rezignirane pomirbe.","D":"Rečenica ne odaje ravnodušnost, nego svjesno prihvaćanje stvarnosti."},
  "2010_jesen_A__67": {"A":"'Naj jasniji' pogrešno je rastavljen; prefiks 'naj' piše se sa superlativom zajedno.","B":"'Najasniji' izostavlja jedno 'j'; ispravno je s dvama j-evima: najjasniji.","D":"'Najasnji' ima i pogrešno spojen prefiks i krivu osnovu komparativa."},
  "2010_jesen_A__68": {"B":"Roman nije A (pripovijest u stihovima s dramskim zapletom), nego C, pa raspored ne valja.","C":"Tragedija nije A nego D, a roman nije C nego... ovaj poredak pogrešno povezuje vrste i obilježja.","D":"Roman nije B (izmišljena priča nasuprot povijesnoj, što je mit), pa raspored nije točan."},
  "2010_jesen_A__69": {"B":"'Istočnoj obali' ovdje je opisni naziv smjera, pa se piše malim slovom, a ne velikim.","C":"'Istoku Jadrana' mijenja smisao i oblik izvorne sintagme te nije ispravan zapis.","D":"'Jadranskoj obali' nije traženi izraz; tekst govori o istočnoj obali Jadrana."},
  "2010_jesen_A__70": {"B":"'Dioklecian' izostavlja 'j' koje stoji u hrvatskoj transkripciji imena.","C":"'Dioklecijane' vokativni je oblik, a traži se nominativ Dioklecijan.","D":"'Diokletijan' ima 't' umjesto 'c', što ne odgovara hrvatskom zapisu."},
  "2010_jesen_A__71": {"B":"'Kasno antička' pogrešno je rastavljeno; složenica se piše zajedno.","C":"'Kasno-antička' ne piše se s crticom jer nije riječ o ravnopravnim pojmovima.","D":"'Kasnoantičnih' je drugi (krivi) oblik osnove i padeža za ovaj kontekst."},
  "2010_jesen_A__72": {"B":"'Promijene' je prezent glagola promijeniti, a traži se imenica u genitivu.","C":"'Promiene' izostavlja 'j' i pogrešno je zapisan refleks jata.","D":"'Promijenbe' nije postojeći oblik te riječi."},
  "2010_jesen_A__73": {"B":"'Srednje vjekovnoga' pogrešno je rastavljeno; složenica se piše zajedno.","C":"'Srednje-vjekovnoga' ne piše se s crticom jer je riječ o jednoj složenici.","D":"'Středovjekovnoga' sadrži strani znak 'ě' koji ne pripada hrvatskom pravopisu."},
  "2010_jesen_A__74": {"A":"'Solinjanka' velikim slovom označavala bi stanovnicu, a ovdje je naziv skulpture, pa ide malo slovo.","C":"'Salonjanka' je drugi (krivi) oblik; uvriježen je naziv 'solinjanka'.","D":"'Solinska' je pridjev, a traži se imenički naziv skulpture."},
  "2010_jesen_A__75": {"A":"'Bijelokosti' s dugim jatom nije ispravno; u ovoj složenici jat je kratak (bje-).","C":"'Bijelo-kosti' pogrešno je rastavljeno crticom i ima krivi refleks jata.","D":"'Bjelokoštane' je pridjev, a traži se imenica bjelokosti."},
  "2010_jesen_A__76": {"A":"'Arheološkom Muzeju' ima pogrešno veliko slovo na drugoj riječi naziva.","C":"'arheološkom muzeju' izostavlja veliko početno slovo naziva institucije.","D":"'Arheološkome Muzeju' ima pogrešno veliko 'M' i nepotreban duži nastavak u ovom kontekstu."},
  "2010_jesen_A__77": {"A":"'Avarskoslavenski' bez crtice ne odgovara odnosu dvaju ravnopravnih pojmova.","C":"'Avarskoslavenski' velikim slovom i bez crtice dvostruko je pogrešno.","D":"'Avaro-slavenski' ima krivu spojnicu osnove (avaro- umjesto avarsko-)."},
  "2010_jesen_A__78": {"B":"'Zahtjevalo' s kratkim jatom nije ispravno; glagol ima dugi jat (ije).","C":"'Zahtevalo' je ekavski oblik, što ne odgovara hrvatskom standardu.","D":"'Zahtjelo' je iskrivljen oblik te ne postoji u standardu."},

  // 2010_jesen_B
  "2010_jesen_B__1": {"B":"Epika pripovijeda događaje s fabulom i likovima, a pjesma 'Oblak' nema radnju nego izražava subjektivni doživljaj.","C":"Drama je namijenjena izvedbi, s dijalogom i didaskalijama, čega u ovoj pjesmi nema."},
  "2010_jesen_B__2": {"A":"Obgrljena rima 'abba' ne odgovara: parovi rimuju 1.-3. i 2.-4. stih, a ne 1.-4. i 2.-3.","B":"Ukrštena rima nije dosljedna kroz sve strofe, pa se shema ne svodi na pravilan 'abab cdcd...'.","D":"Raspored 'cded fghg ijkj' iz ove sheme ne odgovara stvarnim zvukovnim podudaranjima u stihovima."},
  "2010_jesen_B__3": {"A":"Osmerac (8 slogova) ne odgovara stihu četvrte strofe koji prema brojenju ima više slogova.","B":"Deveterac ima 9 slogova, što ne odgovara traženomu deseteračkom stihu.","D":"Jedanaesterac ima 11 slogova, znatno više od broja slogova u tom stihu."},
  "2010_jesen_B__4": {"A":"Distih ima dva stiha, a strofe ove pjesme imaju četiri stiha.","B":"Tercina ima tri stiha, a strofe imaju četiri.","D":"Sestina ima šest stihova, a strofe imaju samo četiri."},
  "2010_jesen_B__5": {"A":"Oblak nije opisan radi prikaza prirode, nego kao simbol misli o neshvaćenom idealu, pa tema nije pejzažna.","B":"Pjesma se ne bavi društvenim nepravdama ni klasnim odnosima, nego razmišljanjem o idealu.","D":"Nema motiva domovine ni rodoljublja, nego općeljudskog misaonog promišljanja."},
  "2010_jesen_B__6": {"B":"Olujno nebo nije simbolično značenje oblaka; pjesma govori o neshvaćenosti ljepote, a ne o vremenskim prilikama.","C":"Slučajni prolaznik su upravo ljudi 'uprti u zemne stvari' koji oblak ne gledaju, a ne sam oblak.","D":"Izgubljene iluzije nisu ono što oblak predstavlja; on simbolizira uzvišeni, neshvaćeni ideal/umjetnika."},
  "2010_jesen_B__7": {"A":"Stih ne govori o razvedravanju nego o sudbini oblaka kao simbola, pa doslovno meteorološko čitanje promašuje smisao.","C":"Tema posljednjih stihova nije ljudska očekivanja, nego uzlet i pad samog oblaka.","D":"Nemilosrdnost prirode prema čovjeku nije poruka; riječ je o uzdizanju i propasti ideala."},
  "2010_jesen_B__8": {"A":"Hiperbola je pretjerivanje radi naglašavanja, a ovdje je riječ o prenesenom značenju, ne o preuveličavanju.","B":"Simbol je predmet koji upućuje na apstraktni pojam, a 'krvareći ljepotu' je slika nastala prijenosom značenja.","D":"Kontrast suprotstavlja pojmove, a u ovoj sintagmi nema suprotstavljanja nego metaforičkog prijenosa."},
  "2010_jesen_B__9": {"B":"Stihovi 'Pojavio se ponad grada / Oblak jedan' ne počinju istom riječi, pa nema anafore.","C":"'A on — krvareći ljepotu — / Svojim nebom' nemaju ponovljen početak, pa to nije anafora.","D":"'I svak je išo... / Za vlašću...' ne ponavljaju istu početnu riječ u uzastopnim stihovima."},
  "2010_jesen_B__10": {"A":"Preradović, Mažuranić i Vidrić pripadaju starijim razdobljima (romantizam, moderna), ne 30-ima 20. st.","C":"Matoš i Kranjčević djeluju na prijelazu stoljeća i u moderni, prije Cesarićeva naraštaja.","D":"Slamnig, Mihalić i Šoljan su poslijeratni krugovaši, mlađi od Cesarića."},
  "2010_jesen_B__11": {"B":"Leksička norma tiče se izbora riječi, a 'dig'' nije pogrešna riječ nego skraćeni oblik, dakle morfološka pojava.","C":"Pravopisna norma odnosi se na pisanje slova i znakova; ovdje je problem u obliku riječi, ne u pravopisu.","D":"Sintaktička norma uređuje slaganje riječi u rečenici, a odstupanje je u obliku jedne riječi."},
  "2010_jesen_B__12": {"A":"'Vjet-ar' je pogrešno rastavljeno jer 'vje-tar' ima granicu sloga ispred suglasnika.","B":"'sta-o' nije ispravna podjela; dvoglas/zijev se rastavlja drukčije ('sta-o' razdvaja, ali ostatak stiha narušava slogovni broj).","D":"'U-pr-te' i 'ze-mne' te 'stvar-i' pogrešno su rastavljeni jer krše pravila granica slogova."},
  "2010_jesen_B__13": {"A":"Iza dvotočja ne slijedi navedeni tuđi govor, nego niz pojmova, pa nije riječ o upravnom govoru.","B":"Tekst nije prekinut nego se nastavlja nabrajanjem, pa dvotočje ne označava prekid.","C":"Nema umetnute rečenice; dvotočjem se uvodi niz, ne umetak."},
  "2010_jesen_B__14": {"A":"Točka bi prekinula rečenicu, a umetak se ne odvaja točkom nego parom istovrsnih znakova.","C":"Dvotočje uvodi nabrajanje ili objašnjenje, a ovdje treba znak koji omeđuje umetak s obiju strana.","D":"Točka zarez razdvaja veće cjeline u rečenici, a ne omeđuje umetnuti dio kao crtice/zarezi."},
  "2010_jesen_B__15": {"A":"Prezent bi glasio 'jesu/su', a 'bjehu' je prošli glagolski oblik.","B":"Imperativ izriče zapovijed ('budi/budite'), a 'bjehu' je pripovjedno prošlo vrijeme.","C":"Aorist glagola biti glasio bi 'bih, bi, bismo, biste, biše', a 'bjehu' je imperfekt."},
  "2010_jesen_B__16": {"A":"'Pokušavati' znači truditi se izvesti, a 'kaniti' znači imati nakanu/plan, što nije isto.","C":"'Moći' izriče sposobnost ili dopuštenje, a 'kaniti' izriče namjeru.","D":"'Željeti' označava puku želju, dok 'kaniti' znači namjeravati, tj. odlučnost da se nešto učini."},
  "2010_jesen_B__17": {"A":"Eshil je raniji grčki tragičar; autor 'Antigone' je Sofoklo.","C":"Plaut je rimski komediograf, ne pisac grčke tragedije 'Antigone'.","D":"Homer je epski pjesnik ('Ilijada', 'Odiseja'), a ne dramatičar."},
  "2010_jesen_B__18": {"A":"Srednjovjekovlje dolazi mnogo nakon antike; 'Antigona' je nastala u 5. st. pr. Kr.","B":"Renesansa je novovjekovni preporod antike, a djelo pripada izvornoj antici.","D":"Barok je razdoblje 17. st., daleko poslije antičke 'Antigone'."},
  "2010_jesen_B__19": {"A":"Ep je opsežna stihovana pripovijetka, a 'Antigona' je dramsko djelo za izvedbu.","B":"Komedija ima vedar zaplet i sretan kraj, a 'Antigona' završava katastrofom.","C":"Ditiramb je lirska pjesma u čast Dioniza, a ne dramska vrsta poput 'Antigone'."},
  "2010_jesen_B__20": {"B":"Upute glumcima daju didaskalije, a ne Zborovođa unutar replika.","C":"Karaktere oblikuju sami likovi svojim postupcima i riječima, dok zbor radnju komentira.","D":"Sukob razrješavaju junaci radnjom; zbor ga ne razrješava nego o njemu progovara."},
  "2010_jesen_B__21": {"A":"Invokacija je zaziv muze na početku epa, vezana uz epiku, a ne uz tragediju.","B":"'In medias res' je pripovjedni postupak ulaska u sredinu radnje, tipičan za ep, ne pojam tragedije.","D":"Retardacija je usporavanje radnje u epu, a ne ključni pojam tragedije."},
  "2010_jesen_B__22": {"A":"Pjesnikinja s Lezba je Sapfo, a ne Antigona.","C":"Pitijska proročica je svećenica iz Delfa, dok je Antigona Edipova kći.","D":"Antigona je smrtnica, tebanska kraljevna, a ne olimpska boginja."},
  "2010_jesen_B__23": {"B":"Nepravedna vladavina nije razlog; Edip je nesretan zbog kobnog prokletstva svoga roda.","C":"Lutanje morem veže se uz Odiseja, a ne uz Edipa.","D":"Trojanski rat nije izazvao Edip, nego mitska otmica Helene."},
  "2010_jesen_B__24": {"A":"Iznenađenje nije naglašeno; ton brige ('O nesretno dijete') upućuje na suosjećanje.","B":"Zborovođa ne sumnja u istinitost, nego žali Antigonu, pa nije riječ o nevjerici.","D":"Ljutnja izostaje; obraćanje je puno samilosti, a ne srdžbe."},
  "2010_jesen_B__25": {"A":"Stražar ne uživa zlurado, nego se želi izvući 'čist i slobodan' iz nevolje.","B":"Stražar se Antigoni ne osvećuje; samo izvršava dužnost i bježi od odgovornosti.","D":"On ne traži anonimnost nego da bude oslobođen krivnje, da ode 'čist'."},
  "2010_jesen_B__26": {"B":"Antigona nije izdala grad; prekršila je vladarevu zabranu pokopavši brata.","C":"Sfinginu zagonetku riješio je Edip, a ne Antigona.","D":"Antigona nije pomagala sestri u bijegu; njezin je čin pokop brata Polinika."},
  "2010_jesen_B__27": {"A":"Antigonu ne pokreće osveta nego viši, nepisani zakon o pravu na pokop.","B":"Ne radi o iskupljenju roditeljskih grijeha, nego o ispunjenju božanske dužnosti prema mrtvom bratu.","C":"Odanost gradu i vladaru zastupa Kreont; Antigona se upravo suprotstavlja državnom zakonu zbog božjega."},
  "2010_jesen_B__28": {"B":"Monolog je govor jednoga lika, a ovdje se izmjenjuju replike više likova.","C":"Pripovijedanje pripada epskoj tehnici, a ovdje likovi izravno govore.","D":"Opisivanje prikazuje izgled ili stanje, a ovdje teče razgovor među likovima."},
  "2010_jesen_B__29": {"B":"'STRAŽAR' je samo oznaka lica koji govori, a ne uputa za izvedbu.","C":"Navedeni stih je replika lika, dakle dramski tekst, a ne scenska uputa.","D":"I to je replika (Zborovođin govor), a didaskalija je piščeva uputa u zagradi."},
  "2010_jesen_B__30": {"B":"Romantizam prethodi Novakovu razdoblju; on stvara u realizmu.","C":"Protorealizam je prijelazna faza prije zrelog realizma, a Novak pripada realizmu.","D":"Moderna dolazi nakon realizma; Novak (umro 1905.) pripada realizmu."},
  "2010_jesen_B__31": {"A":"Djelo nije pustolovno; nema avantura nego prikaz propadanja obitelji u društvu.","C":"Tematika nije povijesna; radnja se ne temelji na povijesnim događajima nego na društvenim odnosima.","D":"Tematika nije filozofska; riječ je o društvenom raslojavanju i propasti staleža."},
  "2010_jesen_B__32": {"A":"Roman ne prikazuje raslojavanje sela i zadruge, nego propast gradske patricijske obitelji.","B":"Tema nije školovanje siromašnog dječaka, nego propadanje obitelji Stipančić.","D":"Iako ima ljubavnih motiva, glavna je tema propast patricijske obitelji, a ne staleška prepreka ljubavi."},
  "2010_jesen_B__33": {"A":"Sin ne ostaje živ; smisao naslova je u izumiranju cijele obitelji.","B":"Naslov se ne odnosi na gubitak prezimena udajom, nego na fizički nestanak svih članova.","C":"Svađa oko nasljedstva nije uzrok; obitelj propada i izumire u novim društvenim okolnostima."},
  "2010_jesen_B__34": {"A":"Novela je kratka prozna vrsta s jednim događajem, a 'Posljednji Stipančići' su opsežno djelo s razgranatom radnjom.","C":"Pripovijetka je kraća od romana; ovo je opsegom i strukturom roman.","D":"Životopis prikazuje stvarni život osobe, a ovo je fikcionalni roman."},
  "2010_jesen_B__35": {"A":"Komentiranje znači pripovjedačevu ocjenu zbivanja, a ovdje se događaji najprije pripovijedaju.","C":"Dijaloga u prva dva odlomka nema; nema izmjene replika nego naracije.","D":"Monolog je govor jednoga lika, a ovi odlomci su pripovjedna naracija."},
  "2010_jesen_B__36": {"A":"Scena nije krštenje; Valpurga je supruga, a riječ je o svečanosti vjenčanja.","C":"Nije riječ o Lucijinu prvom plesu, nego o Stipančićevu vjenčanju s gostima.","D":"Prigoda nije odlazak sina na školovanje, nego svadbena gozba."},
  "2010_jesen_B__37": {"A":"Gosti nisu ravnodušni; tekst kaže da nisu znali kako primiti prizor, dakle bili su zatečeni.","B":"Podrugljivost izražava samo majorica svojim smijehom, a ostali gosti su zbunjeni.","C":"Samilosti nema; gosti su prije zatečeni i ne znaju kako reagirati."},
  "2010_jesen_B__38": {"B":"Valpurga nije iznenada došla; ona je već prisutna kao supruga, povod je gostovo ponašanje.","C":"Troškovi gozbe nisu uzrok bijesa, nego Winterovo nedolično ponašanje.","D":"Nepozvani gosti nisu spomenuti kao povod; bijes izaziva pijani časnikov ispad."},
  "2010_jesen_B__39": {"A":"Stipančić ne traži pozornost nego zadovoljštinu zbog povrijeđene časti.","C":"On nije vođen željom da bude dobar domaćin, nego povrijeđenim ponosom i taštinom.","D":"Pokretač nije zaštita supruge nego vlastiti ugled i taština ('toliko očekivana slava')."},
  "2010_jesen_B__40": {"A":"Strastvena ljubav prema supruzi nije naglašena; istaknuta je njegova briga za ugled.","B":"Stipančić ne kontrolira osjećaje nego silovito reagira, tražeći zadovoljštinu.","C":"On ne okreće stvari u svoju korist, nego je posve obuzet osjećajem povrijeđenosti i ugleda."},
  "2010_jesen_B__41": {"A":"Skromnost se ne otkriva; Stipančić reagira silovito i ponosno.","B":"Iako je ohol, u prizoru se ponajprije pokazuje njegova silovita, nagla reakcija s mačem.","C":"Brižnost nije istaknuta; prevladava silovit, nasilan postupak."},
  "2010_jesen_B__42": {"A":"Valpurga ne djeluje samouvjereno; problijedjela je i zbunjeno gleda oko sebe.","C":"Sigurnost izostaje; ona je zatečena drzovitošću i ne zna kako reagirati.","D":"Koketnost se ne pokazuje; Valpurga je zbunjena i preneražena, a ne zavodljiva."},
  "2010_jesen_B__43": {"B":"Poredba bi tražila riječ 'kao' ili 'poput', a ovdje je prijenos značenja izveden bez poredbenog veznika.","C":"Oksimoron spaja proturječne pojmove, čega ovdje nema.","D":"Ironija znači reći suprotno od mišljenoga, a ovdje je slikoviti prijenos bijesa u lik lava."},
  "2010_jesen_B__44": {"A":"Pomodnice su trenutačno popularne, nove riječi, a 'nešta, česa, nijesu' su stari, zastarjeli oblici.","C":"Neologizmi su novostvorene riječi, a navedeni su oblici zastarjeli.","D":"Oživljenice su ponovno uvedene stare riječi, a ovi su oblici jednostavno zastarjeli (arhaizmi)."},
  "2010_jesen_B__45": {"A":"'Poslije' izriče vrijeme nakon nečega, a 'dočim' ovdje znači istodobnost ('dok').","B":"'Iako' je dopusni veznik, a 'dočim' u ovoj rečenici ima vremensko/usporedno značenje.","C":"'Makar' je također dopusni veznik, dok 'dočim' znači 'dok'."},
  "2010_jesen_B__46": {"A":"Oblik 'pepeo' je nominativ, a uz 'naslagati' traži se genitiv.","B":"'Pepel' je dijalektalni/stari oblik, a standardni genitiv glasi 'pepela'.","D":"'Pepelu' je dativ ili lokativ, a glagol 'naslagati' traži genitiv 'pepela'."},
  "2010_jesen_B__47": {"B":"Drška je dio za koji se mač drži, a 'vr' označava prednji, rezni dio koji dohvaća čelo.","C":"Iako je 'vrh' srodno, traženi sinonim koji odgovara funkciji rezanja je 'oštrica'.","D":"Korica je tok/futrola u koju se mač sprema, a ne dio koji reže."},
  "2010_jesen_B__48": {"A":"Goran Tribuson nije autor 'Dunava'; djelo je napisao Pavao Pavličić.","B":"Ivan Aralica nije autor 'Dunava'.","D":"Antun Šoljan nije autor 'Dunava'."},
  "2010_jesen_B__49": {"A":"Djelo nije podijeljeno na četiri dijela po stranama svijeta, nego na dvanaest dijelova po mjesecima.","B":"Dijelovi nisu naslovljeni ženskim imenima, nego imenima mjeseci.","D":"Nije podijeljeno na četiri dijela s mitološkim imenima, nego na dvanaest mjeseci."},
  "2010_jesen_B__50": {"A":"Pripovijedanje nije objektivno; ono je proosjećano, iz perspektive mladića, dakle subjektivno.","C":"Vanjski opis prikazuje izgled, a ovdje se prenose sjećanja i unutarnji doživljaj.","D":"Unutarnji opis prikazuje psihu lika kao opis, a ovdje je riječ o subjektivnom pripovijedanju."},
  "2010_jesen_B__51": {"B":"Osijek nije grad nerazdvojiv od Dunava i pripovjedača u ovom djelu; to je Vukovar.","C":"Vinkovci ne leže na Dunavu; grad djela je Vukovar.","D":"Grad nije nepoznat nego prepoznatljiv Vukovar uz Dunav."},
  "2010_jesen_B__52": {"A":"Tekst nije građen na opreci ljepota-ružnoća, nego na opreci dobi (mladi i stariji plivači).","B":"Opreka kretanje-mirovanje nije temeljna; nosivi je kontrast mladost i starost.","C":"Opreka govor-šutnja nije ona koja oblikuje tekst, nego mladost naspram starosti."},
  "2010_jesen_B__53": {"B":"Proljeće nije vrijeme radnje; spominju se prosinac, magla i bljuzgavica, dakle zima.","C":"Ljeto je samo predmet sjećanja i planova, a radnja se zbiva zimi.","D":"Jesen nije naznačena; prosinac s maglom i bljuzgavicom upućuje na zimu."},
  "2010_jesen_B__54": {"A":"Mladići ne ogovaraju, nego sjećaju se ljeta i kuju planove, tj. sanjare.","B":"Nema motiva tješenja; ozračje je optimistično sanjarenje o budućoj sezoni.","D":"Mladići ne tuguju; gledaju s nadom u iduće ljeto, pa je riječ o sanjarenju."},
  "2010_jesen_B__55": {"A":"Pogled nije pesimistican; mladićima sve izgleda lako izvodljivo i lijepo.","B":"Destruktivnosti nema; njihov je odnos prema svijetu pun nade i planova.","C":"Vizionarstvo nije naglašeno; riječ je o vedrom, optimističnom doživljaju budućnosti."},
  "2010_jesen_B__56": {"A":"Dubina nije tema rečenice; govori se o struji koja nosi plivača nizvodno.","C":"Širina nije naglašena nego snaga matice koja odnosi plivača kilometar nizvodno.","D":"Ljepota rijeke nije predmet ove rečenice, nego snaga njezine struje."},
  "2010_jesen_B__57": {"A":"Dokazivanje nije osobina koja ih razlikuje; ističe se njihova odvažnost da plivaju ravno na maticu.","C":"Izdržljivost nije naglašena razlika; razlikuje ih hrabro plivanje preko najjače struje.","D":"Umišljenost nije ona crta koja ih razlikuje od ostalih plivača, nego hrabrost."},
  "2010_jesen_B__58": {"A":"Mladići se usamljenim plivačima ne dive, nego ih ne razumiju i čude im se.","B":"Prezir nije njihov stav; oni su začuđeni takvim ponašanjem.","C":"Ismijavanje nije naglašeno; njihova je reakcija čuđenje, nerazumijevanje."},
  "2010_jesen_B__59": {"B":"Anegdote nisu zapleti krimi-romana, nego kratke, smiješne životne zgode.","C":"Anegdote nisu scene iz horor-filmova nego vesele, duhovite zgode.","D":"Anegdote nisu neugodni doživljaji nego najčešće zabavne, smiješne zgode."},
  "2010_jesen_B__60": {"A":"Pozitiv je 'lijepo', već naveden kao prvi član niza, pa ne nedostaje.","B":"Komparativ je 'ljepše', već naveden kao drugi član, pa nije izostavljeni oblik."},
  "2010_jesen_B__61": {"A":"Zarez nije zbog suprotnosti; nema suprotnoga veznika, nego umetnute rečenice.","B":"Nizanje pretpostavlja niz istovrsnih dijelova, a ovdje je umetnuta zavisna rečenica.","D":"Nabrajanje bi tražilo niz pojmova, a ovdje se omeđuje umetnuta relativna rečenica."},
  "2010_jesen_B__62": {"A":"Četiri surečenice je premalo; broji se pet odvojenih predikata u rečenici.","C":"Šest surečenica je previše; prema raščlambi predikata ima pet.","D":"Sedam surečenica ne odgovara; pravilan broj predikata daje pet."},
  "2010_jesen_B__63": {"A":"'Kleti' znači proklinjati, što značenjski i oblikom ne odgovara obliku 'kuju'.","C":"'Kuljati' znači izbijati u mlazu, a 'kuju planove' dolazi od 'kovati'.","D":"'Klati' znači ubijati nožem, što ne odgovara obliku ni značenju 'kuju'."},
  "2010_jesen_B__64": {"A":"Frazem se ne odnosi na vremensku granicu (do jutra), nego na neograničenu mjeru po volji.","B":"'Do mile volje' ne znači kriomice, nego koliko god se želi.","C":"Frazem ne govori o javnosti, nego o tome da se nešto čini koliko se hoće."},
  "2010_jesen_B__65": {"A":"'Bal pod maskama' nije značenje riječi 'matica', pa niz nije točan.","B":"'Pokrivač' nije značenje riječi 'matica', pa ovaj niz otpada.","D":"'Pomoćni sudski službenik' nije značenje riječi 'matica', pa niz nije ispravan."},
  "2010_jesen_B__66": {"A":"'Biti' u prezentu glasi 'jest/je', a 'biva' dolazi od učestaloga glagola 'bivati'.","B":"'Htjeti' nema oblik 'biva'; riječ je o glagolu 'bivati'.","C":"'Imati' u prezentu glasi 'ima', a 'biva' je oblik glagola 'bivati'."},
  "2010_jesen_B__67": {"B":"Raspored '1D, 2A, 3B, 4C' netočno pridružuje Krleži 'Smrt Vronskog', a Krleža je autor 'Povratka Filipa Latinovicza'.","C":"Raspored '1C, 2B, 3A, 4E' krivo Brešanu pridružuje 'Okvir za mržnju', a on je autor 'Predstave Hamleta'.","D":"Raspored '1A, 2C, 3D, 4B' krivo Krleži pridružuje 'Predstavu Hamleta', što je Brešanovo djelo."},
  "2010_jesen_B__68": {"A":"'Dijela' (od 'dio') znači čestice/komada, a ovdje se misli na umjetnikovo djelo, pa treba 'djela'."},
  "2010_jesen_B__69": {"B":"Veliko 'F' nije opravdano jer 'firentinskoga' je opisni pridjev, a ne dio vlastitog imena."},
  "2010_jesen_B__70": {"B":"Veliko 'F' nije ispravno jer 'francuski' je ovdje opisni pridjev (vrsta dvora), a ne dio naziva."},
  "2010_jesen_B__71": {"B":"Malo 'l' nije ispravno jer je 'Leonardovoj' posvojni pridjev izveden od vlastitog imena."},
  "2010_jesen_B__72": {"B":"'Orginala' je pogrešno napisano; ispravan oblik glasi 'originala'."},
  "2010_jesen_B__73": {"B":"Spojnica u 'Louvre-u' nije potrebna jer se nastavak dodaje izravno: 'Louvreu'."},
  "2010_jesen_B__74": {"A":"'20. st' bez točke nije pravilno jer je 'st.' kratica koja zahtijeva završnu točku."},
  "2010_jesen_B__75": {"A":"'Naj ljepša' rastavljeno nije ispravno; superlativni prefiks 'naj-' piše se spojeno."},
  "2010_jesen_B__76": {"B":"'Smijeka' je pogrešan oblik; ispravno je 'smješka' (od 'smješkati se')."},
  "2010_jesen_B__77": {"B":"Malo 'p' nije ispravno jer je 'Posljednja večera' naziv umjetničkog djela, dakle vlastito ime."},

  // 2010_ljeto_A
  "2010_ljeto_A__1": {"A":"Matoš nije nadrealist niti je Šimić realist; nadrealizam i realizam ne odgovaraju ugođajnoj impresiji ni ekspresionističkoj boli ovih pjesama.","B":"Romantizam i klasicizam su starija razdoblja; obje su pjesme s početka 20. stoljeća (moderna i avangarda), a ne romantičarske ni klasicističke.","D":"Futurizam i imagizam ne odgovaraju Matoševoj impresionističkoj slici ni Šimićevoj ekspresionističkoj poetici boli i boje."},
  "2010_ljeto_A__2": {"A":"Tekstovi nisu iz istoga pjesničkog razdoblja (impresionizam i ekspresionizam), pa razdoblje nije ono što ih povezuje.","C":"Oblik se razlikuje: Matoš piše sonet s rimom, a Šimić slobodni stih, pa ih oblik ne povezuje.","D":"Stil im se razlikuje (impresionistički naspram ekspresionističkoga), pa ih stil ne povezuje; povezuje ih zajednička tema ljubavi i smrti."},
  "2010_ljeto_A__3": {"A":"Cvijeće i zvijezde su sporedni, pojedinačni motivi, a ne glavni motivi obaju tekstova.","B":"Prolaznost i vječnost nisu temeljni motivi; tekstove objedinjuju ljubav i smrt.","C":"San i java javljaju se tek kao pojedinačni motivi (san), ali nisu zajednički glavni motivi obiju pjesama."},
  "2010_ljeto_A__4": {"B":"Pjesme ne suprotstavljaju nedostižnost i dostižnost ljubavi; razlika je u tome ima li izlaza iz boli (Matoš da, Šimić ne).","C":"Šimić ne nalazi smirenje u prirodi (završava vječnom tminom), a ni Matoš ne pronalazi izlaz u vlastitoj snazi nego u utjehi kose.","D":"Pitanje stvarnosti ljubavi nije razlikovna točka; obje su pjesme o doživljenoj, izgubljenoj ljubavi, a razlikuju se po (ne)postojanju izlaza iz boli."},
  "2010_ljeto_A__5": {"A":"Balada je pripovjedna pjesma s tragičnom radnjom, a Matošev je tekst sonet od 14 stihova s dva katrena i dvije tercine.","B":"Gazela je pjesnički oblik istočnjačkoga podrijetla, a Matošev tekst ima jasnu sonetnu strukturu.","C":"Glosa razrađuje uvodne stihove (moto) u zasebnim strofama, čega u Matoševu sonetu nema."},
  "2010_ljeto_A__6": {"A":"Katreni ovdje nisu unakrsno rimovani (abab), nego obgrljeno (abba), pa ova shema ne odgovara.","B":"Katreni nemaju shemu abab abab, nego abba abba (obgrljena rima), pa ova shema nije točna.","C":"Iako su katreni obgrljeni, raspored tercina ovdje ne odgovara (efe fgg); Matošev je sonet abba abba cdc dee."},
  "2010_ljeto_A__7": {"A":"Sinestezija spaja različite osjetilne dojmove, a 'smrti krasne' spaja suprotne pojmove, što je oksimoron.","C":"Kontrast suprotstavlja pojmove na razini cjeline, dok je 'smrti krasne' spoj suprotnosti unutar jedne sintagme, dakle oksimoron.","D":"Poredba traži uspoređivanje pomoću veznika (kao, poput), čega u 'smrti krasne' nema."},
  "2010_ljeto_A__8": {"A":"Simbol bi bio predmet ili slika sa skrivenim značenjem, a ovdje je riječ o ublažavanju pojma smrti opisom 'sniva'.","B":"Alegorija je prošireno preneseno značenje cijele slike, a ovdje je smrt samo ublaženo nazvana snom, što je eufemizam.","D":"Hiperbola je pretjerivanje, a 'u smrti se sniva' ne pretjeruje nego ublažava pojam smrti."},
  "2010_ljeto_A__9": {"A":"Lirski subjekt je onaj komu kosa govori ('reče'), a ne onaj koji izgovara posljednje rečenice.","B":"Pokojnica je mrtva i ne govori; živa je samo njezina kosa, koja izgovara riječi.","C":"Kobna dvorana je prostor zbivanja, a ne govornik; posljednje rečenice izgovara kosa."},
  "2010_ljeto_A__10": {"A":"Morfološka norma tiče se oblika riječi, koji ovdje nisu nepravilni; odstupanje je u rečeničnom ustroju.","B":"Leksička norma odnosi se na izbor riječi, a ovdje su riječi standardne; problem je u sintaksi (nizovi bez glagola).","C":"Pravopisna norma tiče se pisanja i interpunkcije, a ovdje je riječ o rečeničnoj strukturi, dakle sintaktičkom odstupanju."},
  "2010_ljeto_A__11": {"B":"'Pjesme u tmini' nije Šimićeva zbirka; njegova jedina zbirka za života su Preobraženja.","C":"Kolajna je zbirka Tina Ujevića, a ne Šimića.","D":"'Knjiga pjesama' nije naslov Šimićeve zbirke; on je objavio Preobraženja (1920.)."},
  "2010_ljeto_A__12": {"A":"Gramatička (morfološko-sintaktička) norma nije prekršena; oblici i ustroj su pravilni, a odstupa pisanje (interpunkcija i velika slova).","C":"Leksička norma (izbor riječi) nije narušena; problem je u izostanku interpunkcije i velikih slova.","D":"Pravogovorna (ortoepska) norma tiče se izgovora, a ovdje je riječ o pisanju, dakle pravopisu."},
  "2010_ljeto_A__13": {"A":"Pravilna izmjena naglašenih i nenaglašenih slogova obilježje je vezanoga stiha, a Šimić piše slobodni stih bez metra.","B":"Šimić ne rabi iste prozodijske obrasce; upravo izostanak ustaljenoga metra obilježava njegov slobodni stih.","D":"Glasovna ponavljanja i rima nisu nositelji ritma u ovom slobodnom stihu; ritam nastaje rasporedom riječi i oblikom stihova."},
  "2010_ljeto_A__14": {"A":"Vizualni (vidni) motivi javljaju se kasnije; prvi je stih 'mrtvo zvoni' slušni dojam.","C":"Taktilni (dodirni) motiv nije početni; tekst počinje zvukom ('zvoni').","D":"Gustativni (okusni) motiv ne pojavljuje se na početku; početni je motiv auditivan."},
  "2010_ljeto_A__15": {"A":"Prezent se javlja ranije ('spuštam', 'znam'), a u posljednjih pet stihova prevladava zapovjedni oblik.","B":"Infinitiv nije oblik tih stihova; 'razmotaj' i 'neka' izriču zapovijed/želju, dakle imperativ.","C":"Aorist je prošlo svršeno vrijeme, a ovi se stihovi obraćaju sa zapovijedi/željom u imperativu."},
  "2010_ljeto_A__16": {"A":"Nesreća je tek moguća posljedica kobi, ali samo značenje riječi 'kob' jest sudbina, usud.","C":"Slučaj je nepredvidiv događaj bez usuda, dok 'kob' označava sudbinsku predodređenost.","D":"Događaj je neutralan pojam, a 'kob' nosi značenje sudbine i usuda."},
  "2010_ljeto_A__17": {"B":"'Crvenijega' je komparativ ('crveniji'), a traži se genitiv pozitiva određenoga pridjeva.","C":"'Crven pokrova' miješa neodređeni nominativ pridjeva s genitivom imenice, što nije pravilno.","D":"'Crvena pokrova' je genitiv neodređenoga pridjeva; uz ovu sintagmu traži se određeni oblik 'crvenoga pokrova'."},
  "2010_ljeto_A__18": {"A":"Eneida je Vergilijev ep o Eneji, a navedeni stih ('Srdžbu mi, boginjo...') početak je Ilijade.","C":"Odiseja pjeva o Odisejevu lutanju, dok navedena invokacija o Ahilejevoj srdžbi pripada Ilijadi.","D":"Orestija je Eshilova tragedijska trilogija, a ovo je epska invokacija iz Ilijade."},
  "2010_ljeto_A__19": {"A":"Himna je svečana pohvalna pjesma, a Ilijada je opsežno pripovjedno djelo, dakle ep.","B":"Tragedija je dramska vrsta, a Ilijada je epsko (pripovjedno) djelo.","D":"Mit je predaja o bogovima i junacima, a Ilijada je književno oblikovan ep (epopeja)."},
  "2010_ljeto_A__20": {"A":"Hesiodu se pripisuju Poslovi i dani te Postanak bogova, a ne Ilijada.","C":"Vergilije je rimski pjesnik, autor Eneide, a ne Ilijade.","D":"Aristotel je filozof (Poetika), a ne autor Ilijade."},
  "2010_ljeto_A__21": {"A":"Dvostruko rimovani dvanaesterac stih je hrvatske renesanse, a Homerovi su epovi u heksametru.","C":"Dvanaesterac nije Homerov stih; epovi su pisani daktilskim heksametrom.","D":"Epski deseterac stih je narodne (usmene) epike, a Homer rabi heksametar."},
  "2010_ljeto_A__22": {"A":"Katarza je pročišćenje gledateljevih osjećaja u tragediji, a ne zaziv Muze na početku epa.","B":"Digresija je odstupanje od glavne radnje, a ovdje je riječ o uvodnom zazivu božanstva.","C":"Retardacija je usporavanje radnje, a navedeni stih zaziva Muzu, dakle invokacija je."},
  "2010_ljeto_A__23": {"A":"Desetogodišnje lutanje morem tema je Odiseje, a ne Ilijade.","C":"Osnutak italskoga (rimskog) carstva tema je Vergilijeve Eneide.","D":"Propast tebanskoga kraljevstva tematizira tebanski mitski krug (npr. tragedije o Edipu), a ne Ilijada."},
  "2010_ljeto_A__24": {"B":"Ahilej nije optužen za ratne neuspjehe; ljutnja izvire iz Agamemnonova oduzimanja robinje Brizeide.","C":"Potonuće lađe u oluji motiv je Odiseje, a ne uzrok Ahilejeve srdžbe.","D":"Uništenje štita i kacige nije uzrok srdžbe; Ahilejev gnjev pokreće oduzimanje Brizeide."},
  "2010_ljeto_A__25": {"A":"Iako spora ima, srdžba je 'pogubna' jer je Ahilejevim povlačenjem stradao niz junaka i Grci su gubili, a ne tek zbog razdora.","B":"Bogovi se ne povlače iz rata zbog Ahilejeve srdžbe; pogubnost je u grčkim gubicima nakon njegova povlačenja.","D":"Srdžba ne izaziva bijes neprijatelja kao razlog pogubnosti; pogubna je jer Ahilejevim povlačenjem stradaju vlastiti, ahejski redovi."},
  "2010_ljeto_A__26": {"A":"Afroditina srdžba nije pokretač rata; rat započinje Parisovom otmicom Helene (uz Afroditinu pomoć, ali otmica je uzrok).","B":"Delfsko proročanstvo nije pokrenulo Trojanski rat; uzrok je otmica Helene.","D":"Osveta za rodoskvrnuće pripada tebanskom mitu (Edip), a ne uzroku Trojanskoga rata."},
  "2010_ljeto_A__27": {"A":"Slanje na pregovore ne odgovara slici 'k Aidu poslala', koja označava silazak u carstvo mrtvih, tj. pogibiju.","B":"Kazna nije značenje stiha; 'k Aidu poslala' znači da su junaci poginuli.","D":"Progonstvo ne odgovara Aidu (carstvu mrtvih); riječ je o smrti junaka."},
  "2010_ljeto_A__28": {"B":"Hektor je trojanski junak, Prijamov sin, a 'Atrejev sin, junacima kralj' jest Agamemnon.","C":"Menelaj je također Atrejev sin, ali nije vrhovni kralj vojske; taj naslov nosi Agamemnon.","D":"Odisej je Laertov sin, kralj Itake, a ne Atrejev sin."},
  "2010_ljeto_A__29": {"A":"Spartanski kralj je Menelaj (smrtnik), dok je Zeus vrhovni bog, gospodar Olimpa.","B":"Zeus nije svećenik nego božanstvo; on je vrhovni bog grčkoga panteona.","C":"Zeus nije vračar nego vrhovni bog koji upravlja Olimpom."},
  "2010_ljeto_A__30": {"A":"Sretan povratak kući završetak je Odiseje, a Ilijada završava pogrebom Hektora.","B":"Ustoličenje novoga kralja ne odgovara kraju Ilijade, koja završava pogrebnim svečanostima.","D":"Predaja neprijateljske vojske nije završetak Ilijade; ona se zatvara Hektorovim pogrebom."},
  "2010_ljeto_A__31": {"A":"Likovi nisu doslovne lutke, nego ljudi prikazani metaforički kao lutke.","C":"Naslov ne označava one koji se igraju lutkama, nego likove koji su sami poput lutaka u 'kući lutaka'.","D":"Likovi ne žele biti lutke; oni već jesu metaforički prikazani kao lutke u nametnutim ulogama."},
  "2010_ljeto_A__32": {"B":"Lirska drama temelji se na ugođaju i poeziji, a Nora je realistička drama društvene problematike.","C":"Ekspresionistička drama javlja se kasnije i obilježena je krikom i deformacijom, dok je Nora realistička građanska drama.","D":"Simbolistička drama gradi se na simbolima i sugestiji, a Ibsenova je Nora realistička, građanska drama."},
  "2010_ljeto_A__33": {"A":"Charles Baudelaire je francuski pjesnik (Cvjetovi zla), a ne autor Kuće lutaka.","B":"A. P. Čehov je ruski dramatičar (Galeb, Višnjik), a Noru je napisao Ibsen.","C":"Arthur Rimbaud je francuski pjesnik, a ne autor ove drame."},
  "2010_ljeto_A__34": {"B":"Sinestezija spaja osjetilne dojmove i nema veze s naglom promjenom Helmerova raspoloženja.","C":"Larpurlartizam je načelo umjetnosti radi umjetnosti, a ne stilski postupak promjene raspoloženja.","D":"Personifikacija pripisuje ljudske osobine neživomu, a Helmerov nagli obrat počiva na kontrastu (bijes - sreća)."},
  "2010_ljeto_A__35": {"B":"Vrhunac je točka najveće napetosti, a otkrivanje tajne prijateljici tek uvodi konflikt, dakle zaplet je.","C":"Rasplet razrješava sukob, a Norino povjeravanje tajne pokreće, a ne razrješava radnju.","D":"Završetak zatvara dramu, dok otkrivanje tajne pripada početnom dijelu strukture, zapletu."},
  "2010_ljeto_A__36": {"B":"'Spas za oboje' izriče Helmerovu samoživu olakšanost nakon drugoga pisma, a ne njegov stav o Norinoj ljubavi.","C":"'Užasna istina' odnosi se na sadržaj pisma o dugu, a ne na njegov stav o Norinoj ljubavi.","D":"'Nesretnica' nije sintagma kojom Helmer ocjenjuje Norinu ljubav; njezinu ljubav odbacuje kao 'glupave isprike'."},
  "2010_ljeto_A__37": {"A":"Pismo ne otkriva ljubavnika; Helmer saznaje da je Nora potajno posudila novac uz krivotvoreni potpis.","C":"Pismo ne javlja da ga Nora napušta; ona to čini tek na kraju drame, nakon pisma.","D":"Pitanje očinstva djece nije sadržaj pisma; otkriva se Norino posuđivanje novca."},
  "2010_ljeto_A__38": {"A":"Helmer se ne smiruje zbog spoznaje da je prvo pismo poslano zabunom, nego zato što je vraćen dokaz Norine krivnje.","B":"Nije riječ o optužbi obiteljskoga prijatelja, nego o Krogstadovu vraćanju mjenice (dokaza).","C":"Drugo pismo ne donosi trag o pravom krivcu, nego vraćeni dokaz krivnje koji otklanja prijetnju."},
  "2010_ljeto_A__39": {"A":"Pismo Helmera nije istinski promijenilo; vraća se starom ponašanju i ne pokazuje spremnost na žrtvu.","B":"Helmer nije shvatio veličinu Norine ljubavi; njezino je požrtvovanje odbacio, pa ne može biti istinska zaštita.","D":"Iako je Nora moralno jača, razlog zašto Helmer ne može biti njezina zaštita jest to što se nije spreman žrtvovati."},
  "2010_ljeto_A__40": {"A":"Slika 'progonjene golubice' iskazuje Helmerov pokroviteljski odnos, ali ne formulira temeljni problem djela kao rečenica o ženi kao svojini.","B":"Rečenica o opraštanju pokazuje Helmerovu nadmoć, no problem djela izričito iskazuje tvrdnja da žena postaje njegovom svojinom.","D":"Poziv na iskrenost i preuzimanje uloge 'volje i savjesti' dio je Helmerova odnosa, ali problem žene kao vlasništva najjasnije izriče rečenica C."},
  "2010_ljeto_A__41": {"A":"Poredba traži veznik usporedbe (kao, poput), kojega u ovoj rečenici nema.","B":"Paradoks je prividno proturječna tvrdnja, a ovdje je riječ o prenesenom značenju 'krila', dakle metafori.","C":"Ironija znači reći suprotno od mišljenoga, dok rečenica izravno prenosi sliku zaštite metaforom 'krila'."},
  "2010_ljeto_A__42": {"A":"U nizu je Zločin i kazna roman (Dostojevski), pa niz nije čisto dramski.","B":"Ljudska komedija je ciklus romana (Balzac), pa ovaj niz ne pripada samo drami.","C":"Madame Bovary je roman (Flaubert), pa ni ovaj niz nije isključivo dramski kao Nora."},
  "2010_ljeto_A__43": {"B":"Pogrešno pridružuje Vojnovića djelu E (U agoniji, Krleža) i Brešana djelu F (U očekivanju Godota, Beckett).","C":"Pogrešno Brešanu pridružuje F (U očekivanju Godota) umjesto A (Predstava Hamleta u selu Mrduša Donja).","D":"Pogrešno Vojnoviću pridružuje A, Brešanu D, Brechtu C i Ionescu B, što ne odgovara stvarnim autorstvima."},
  "2010_ljeto_A__44": {"A":"Dvije je premalo; u rečenici su čak četiri zamjenice (to, mnom, ja, svojom).","B":"Tri je premalo; uz 'mnom', 'ja' i 'svojom' zamjenica je i 'to', pa ih je četiri.","D":"Pet je previše; zamjenica je točno četiri (to, mnom, ja, svojom)."},
  "2010_ljeto_A__45": {"B":"Tri je previše; 'vjeruj mi' i vokativ 'moja Nora' ne čine zasebne surečenice uz dvije glagolske jezgre s 'ide'.","C":"Četiri je previše; rečenica ima samo dvije surečenice s predikatom 'ide'.","D":"Pet je previše; rečenica se sastoji od svega dviju surečenica."},
  "2010_ljeto_A__46": {"A":"Infinitiv glasi 'smiriti se' i 'sabrati', a u rečenici su uporabljeni zapovjedni oblici 'smiri' i 'saberi'.","B":"Kondicional I. tvori se s 'bih, bi...' i glagolskim pridjevom, čega ovdje nema; oblici su imperativni.","C":"Prezent bi glasio 'smiruje se, sabire', a ovdje su zapovjedni oblici 'smiri' i 'saberi'."},
  "2010_ljeto_A__47": {"A":"Novela ne počinje pripovijedanjem radnje, nego nizanjem osobina i podataka o grofu, dakle opisom.","C":"Unutarnji monolog iznosio bi misli lika, a početak je objektivan opis grofa.","D":"Retrospekcija je vraćanje u prošlost unutar tijeka radnje, a ovdje je riječ o uvodnom opisu lika."},
  "2010_ljeto_A__48": {"A":"Ton nije iskreno svečan, nego prividno svečan radi izrugivanja; Krleža ironizira grofovu nabujalu plemenitost.","B":"Sentimentalan ton iskazuje ganuće, dok Krleža s ironijskim odmakom ismijava grofovu uznositost.","C":"Elegičan ton izražava tugu za prošlim, a ovdje prevladava podsmijeh, dakle ironija."},
  "2010_ljeto_A__49": {"A":"Grof nije sanjao o carskoj pobjedi, nego o tome da pogine za vjeru (Pro Fide).","B":"Ratnička slava nije njegov san; čeznuo je umrijeti za vjeru pod malteškom devizom.","D":"Pobjeda pravde nije njegov ideal; sanja o žrtvi za vjeru, što izriče deviza Pro Fide."},
  "2010_ljeto_A__50": {"A":"Brojka 28 ne odnosi se na dobivene bitke, nego na 28 plemenitih predaka u rodoslovlju.","C":"Rečenica ne govori o bliskosti vladaru, nego o broju plemenitih predaka, dakle o staroj plemićkoj lozi.","D":"Rečenica ne spominje sudjelovanje u križarskim ratovima, nego brojnost plemenitih predaka."},
  "2010_ljeto_A__51": {"A":"Iako je primljen mlad (u 14. godini), pitanje se odnosi na uvjete; on je nadmašio druge brojem predaka (28 umjesto 16).","C":"Tekst ne govori o oduševljavanju priorata zlatnim pečatima, nego o broju plemenitih predaka koji nadmašuje uvjete.","D":"Krvno srodstvo s kancelarom nije spomenuto; njegova prednost jest broj predaka veći od propisanoga."},
  "2010_ljeto_A__52": {"A":"Plakao je zbog nemogućnosti sudjelovanja u križarskim ratovima, a ne zbog prvoga dolaska u Svetu Zemlju.","B":"Razlog plača nije mjesto pokopa, nego žal što nije ratovao za vjeru poput Gottfrieda Bouillonskoga.","D":"Nije plakao jer nije upoznao Gottfrieda, nego jer nije mogao s njime sudjelovati u križarskim pohodima."},
  "2010_ljeto_A__53": {"A":"Grof ne odobrava ulogu parlamenata; suvremenost doživljava kao 'idiotsko doba', a cijeni vitešku tradiciju.","B":"Nastalu (umanjenu) društvenu ulogu plemića grof ne odobrava, nego žali za negdašnjom viteškom slavom.","C":"Socijalističku demokraciju grof prezire kao dio prezrenoga modernog doba; odobrava staru vitešku tradiciju (dvoboje)."},
  "2010_ljeto_A__54": {"A":"Grof nije general na ratištu, nego zapovjednik vojne bolnice (barake).","C":"Grof nije kirurg; on je zapovjednik bolničke barake, a ne liječnik.","D":"Grof nije ranjenik; on zapovijeda vojnom bolnicom u kojoj leže ranjeni vojnici."},
  "2010_ljeto_A__55": {"B":"Dr. Kyriales je lik iz drugih Krležinih djela, a glavni lik Barake pet be jest domobran Jambrek.","C":"Odvjetnik Baločanski lik je iz druge Krležine proze, a ne glavni lik ove novele.","D":"Student Vidović nije glavni lik Barake pet be; to je domobran Jambrek."},
  "2010_ljeto_A__56": {"A":"Jambrek ne nestaje u kaosu, nego umire od posljedica ranjavanja u bolničkoj baraci.","C":"Jambrek ne dobiva orden; njegova je sudbina besmislena smrt od rana.","D":"Jambrek se ne vraća kući osakaćen, nego umire ranjen u baraci."},
  "2010_ljeto_A__57": {"A":"Viteška hrabrost nije ideja novele; Krleža je upravo ironizira (lik grofa), a smisao je u besmislu rata.","B":"Spašavanje ranjenika nije temeljna ideja; novela razotkriva apsurd i besmislenost rata.","C":"Seljački fatalizam tek je crta lika, a temeljna je ideja besmislenost rata."},
  "2010_ljeto_A__58": {"A":"Kraj 19. stoljeća je prerano; radnja se zbiva za Prvoga svjetskog rata, u drugom desetljeću 20. stoljeća.","B":"Tridesete godine 20. stoljeća su prekasno; rat traje 1914.-1918., dakle u drugom desetljeću.","D":"Druga polovina 20. stoljeća ne odgovara; radnja je smještena u Prvi svjetski rat (1910-te)."},
  "2010_ljeto_A__59": {"B":"Baraka nije zapovjedno središte, nego bolnički paviljon u kojem leže ranjenici.","C":"Baraka nije spremište streljiva, nego bolnička baraka za ranjene vojnike.","D":"Baraka nije zarobljenički logor, nego bolnički paviljon (baraka broj pet B)."},
  "2010_ljeto_A__60": {"A":"'Novele' nije naslov ove zbirke; Baraka pet be pripada zbirci Hrvatski bog Mars.","C":"Glembajevi su dramski ciklus (i proza o obitelji Glembay), a ne zbirka kojoj pripada ova novela.","D":"'Hiljadu i jedna smrt' nije Krležina zbirka; novela je iz Hrvatskoga boga Marsa."},
  "2010_ljeto_A__61": {"A":"'Maksimilijan' mora biti sklonjeno ('Maksimilijana'), a strano ime 'Axelrode' u genitivu glasi 'Axelrodea', ne 'Axelroda'.","C":"'Grof' mora dobiti genitivni nastavak ('grofa'), pa nesklonjeni 'grof Maksimilijana' nije pravilno.","D":"Ovdje su nepravilno nesklonjen 'grof' i 'Maksimilijan' te krivo 'Axelroda' umjesto 'Axelrodea'."},
  "2010_ljeto_A__62": {"A":"Dvije je premalo; uz glavnu surečenicu tu su i 'kad se probudio', 'i bilo mu je' te 'kao da sanja' - ukupno četiri.","B":"Tri je premalo; rečenica ima četiri predikatne jezgre, dakle četiri surečenice.","D":"Pet je previše; surečenica je točno četiri."},
  "2010_ljeto_A__63": {"A":"Oronimi su zemljopisni nazivi za gore, a 'grof' i 'vitez' su nazivi titula koje su izašle iz uporabe.","B":"Eponimi su riječi nastale od vlastitih imena, a 'grof' i 'vitez' označavaju nestale društvene staleže, dakle historizmi su.","C":"Arhaizmi su zastarjele riječi za pojmove koji postoje (s novim nazivom), a ovdje su nestali sami pojmovi (titule), pa su to historizmi."},
  "2010_ljeto_A__64": {"B":"Okamenjena metafora je ustaljeni preneseni izraz, a ovdje dijelovi opreme stoje za cjelinu (pretke), što je metonimija.","C":"Barokna antiteza suprotstavlja pojmove, čega ovdje nema; riječ je o zamjeni dijela za cjelinu, metonimiji.","D":"Simbol upućuje na apstraktni sadržaj skrivenim znakom, a ovdje su 'perjanice i kacige' konkretna zamjena za pretke, dakle metonimija."},
  "2010_ljeto_A__65": {"A":"Slavna prošlost je tek asocijacija, a sama sintagma 'modra krv' ustaljeno znači plemenito (aristokratsko) podrijetlo.","B":"'Modra krv' ne označava nasljednu bolest, nego plemićko porijeklo.","C":"Sklonost nasilju nije značenje izraza; 'modra (plava) krv' znači aristokratsko podrijetlo."},
  "2010_ljeto_A__66": {"A":"'Idila' je natuknica (riječ koja se definira), a ne etimološka odrednica.","B":"Crtica je grafički znak razdvajanja, a ne podatak o podrijetlu riječi.","D":"Opisni dio 'umjetnička tvorevina...' je definicija značenja, a ne etimološka odrednica."},
  "2010_ljeto_A__67": {"B":"'200. godina' je redni broj s točkom (dvjestota), a ovdje je riječ o trajanju, pa treba kardinalni '200 godina'.","C":"'Dvjesto godina' iako značenjski odgovara, traženi je brojčani zapis '200 godina'.","D":"'Dvjestota godina' je redni broj (točno određena godina), a izriče se trajanje od 200 godina."},
  "2010_ljeto_A__68": {"B":"Ime na samoglasnik ne sklanja se s crticom, pa 'Dante-a' nije pravilno; ispravno je 'Dantea'.","C":"'Danteha' uvodi suvišno -h- kojega u sklonidbi nema; pravilno je 'Dantea'.","D":"'Danteja' uvodi -j- kakav se piše uz imena na -i; uz 'Dante' (na -e) pravilno je 'Dantea'."},
  "2010_ljeto_A__69": {"B":"Godine su redni brojevi i traže točku ('1474.', '1533.'), pa zapis bez točaka nije pravilan.","C":"Uz crticu između godina trebaju biti razmaci, pa '(1474.-1533.)' bez razmaka nije pravilno.","D":"Nedostaju zagrade i točke uz redne brojeve te razmaci oko crtice, pa '1474-1533' nije pravilan zapis."},
  "2010_ljeto_A__70": {"B":"Spojeno pisanje 'remekdjelu' nije pravilno; 'remek-djelo' je polusloženica s crticom.","C":"'Remekdjelo' je krivo spojeno i u nominativu; pravilno je 'remek-djelo' s crticom, a traži se dativ 'remek-djelu'.","D":"'Remekovnom djelu' uvodi nepostojeći pridjev 'remekovni'; pravilno je polusloženica 'remek-djelu'."},
  "2010_ljeto_A__71": {"A":"Etnici se pišu velikim početnim slovom, pa 'flamanac' malim slovom nije pravilno.","C":"'Flandrijski' je pridjev (i piše se malim slovom), a traži se etnik (stanovnik), pa to ne odgovara.","D":"'Flandrijski' malim slovom je pridjev, a traženo je ime stanovnika - etnik 'Flamanac'."},
  "2010_ljeto_A__72": {"B":"'Najcijenjeniji' zadržava 'ije' u korijenu, no pravilno je 'najcjenjeniji' (kraćenje jata u 'je').","C":"'Najcenjeniji' je ekavski oblik, a hrvatski standard traži 'najcjenjeniji'.","D":"'Najcjenaniji' iskrivljuje sufiks; pravilan je superlativ 'najcjenjeniji'."},
  "2010_ljeto_A__73": {"A":"Strano ime na -i u genitivu dobiva -ija, pa 'Vincia' nije pravilno; ispravno je 'Vincija'.","C":"'Vinca' gubi završno -i osnove; pravilno je 'Vincija'.","D":"'de Vincija' krivo mijenja prijedlog 'da' u 'de'; pravilno je 'Leonarda da Vincija'."},
  "2010_ljeto_A__74": {"B":"'Josquino' krivo mijenja osnovu imena; genitiv glasi 'Josquina', pa ovaj oblik nije pravilan.","C":"'Des Pres' ostaje nesklonjen, a treba dobiti genitivni nastavak: 'Des Presa'.","D":"'Josquinom Des Presom' je instrumental, a traži se genitiv 'Josquina Des Presa'."},
  "2010_ljeto_A__75": {"A":"'Zahtjevao' s kratkim 'je' nije pravilno; dugi jat daje 'ije', pa je ispravno 'zahtijevao'.","C":"'Zatijevao' ispušta glas 'h' iz osnove; pravilno je 'zahtijevao'.","D":"'Zahtevao' je ekavski oblik, a hrvatski standard traži 'zahtijevao'."},
  "2010_ljeto_A__76": {"B":"'Plać' bez nastavka nije akuzativ imenice 'plaća'; ispravno je 'plaću'.","C":"Opcija C ('plaću') jednaka je točnom odgovoru, ali u testu se kao točan bira A; ovaj duplikat nije predviđeni odgovor.","D":"'Plaçu' rabi strani znak 'ç' umjesto hrvatskoga 'ć'; pravilno je 'plaću'."},

  // 2010_ljeto_B
  "2010_ljeto_B__1": {"A":"Epika je pripovjedni rod (epovi, romani), a ovdje je posrijedi kratka subjektivna pjesma sa stihovima i rimom.","C":"Drama je rod namijenjen izvedbi, s dijalogom i likovima, a u tekstu nema ni jednoga od tih obilježja."},
  "2010_ljeto_B__2": {"A":"Gazela je istočnjački oblik s parno rimovanim dvostisima, a ne sa 14 stihova u katrenima i tercinama.","B":"Glosa razrađuje uvodnu strofu (motto) u nizu strofa, što ovdje nije slučaj.","D":"Balada je pripovjedna pjesma s tragičnom radnjom, a ovaj tekst je čista lirika određene strofike soneta."},
  "2010_ljeto_B__3": {"A":"Katreni nemaju ukrštenu rimu abab, nego obgrljenu abba abba.","B":"Katreni nisu rimovani abab cdcd, već obgrljeno abba abba, a ni tercine nemaju shemu efe ege.","D":"Katreni su abba abba (točno), ali tercine se ne rimuju cdd dee, nego cdc eed."},
  "2010_ljeto_B__4": {"B":"Prvi stih 'Pa, uzdignut nad zipkom i nad grobom' ima 11 slogova, a ne 12.","C":"Posljednji stih 'I onda, kad me više biti neće' ima 12 slogova, a ne 11.","D":"Prvi je stih jedanaesterac, a drugi 'Da u tebi dišem i da živim s tobom' također jedanaesterac, ne dvanaesterac."},
  "2010_ljeto_B__5": {"A":"Pjesma ne opisuje krajolik kao glavnu temu, nego izriče odanost jeziku domovine.","B":"Socijalna lirika progovara o društvenoj nepravdi i bijedi, čega ovdje nema.","C":"Iako ima misaonih elemenata o životu i smrti, temeljni je sadržaj ljubav prema hrvatskome jeziku, dakle domoljublje."},
  "2010_ljeto_B__6": {"B":"Gustativni (okusni) poticaj nije prisutan; 'mirisati' je olfaktivni, a ne okusni osjet.","C":"Vizualni poticaj nije naglašen, a 'žice' i 'cvijeće' ne upućuju na okus.","D":"Slika 'žice' upućuje na zvuk (auditivno), a ne na vizualni dojam."},
  "2010_ljeto_B__7": {"A":"Naglasak nije na lijepim godinama, nego na cjeloživotnoj povezanosti s jezikom kojim se izražavao.","B":"Ljepota jezika spominje se uzgred ('lijepi jezice'), no glavna je poruka da je u tom jeziku proživio vijek.","D":"Drevnost jezika spomenuta je epitetom, ali poruka prvih dvaju stihova jest pjesnikovo cjeloživotno služenje jezikom."},
  "2010_ljeto_B__8": {"A":"Slika 'morskog praga' upućuje na obalu (Dalmaciju), a ne na kontinentalnu Slavoniju.","B":"Lika je gorski kraj, a stih govori o moru, što ne odgovara.","D":"Zagorje je kontinentalno, dok 'morski prag' jasno upućuje na primorje, Dalmaciju."},
  "2010_ljeto_B__9": {"A":"Stih 'Polako sam te, uz trud, usvojiо' isključuje prirodno usvajanje rođenjem.","C":"Pjesma ne spominje učenje u školi, nego osobni trud i postupno ovladavanje.","D":"Glagol 'usvojiо' (svršeni, prošlost) govori o dovršenom procesu, a ne o stalnom usavršavanju."},
  "2010_ljeto_B__10": {"A":"Prva strofa govori o cjeloživotnoj povezanosti s jezikom, a ne o tome koliko je njime naučio.","C":"Treća strofa (prva tercina) govori o želji da bude poput glazbala, ne o učenju.","D":"Četvrta strofa govori o besmrtnosti u jeziku, a stihovi o spoznaji ('gdje nisam bio') su u drugoj strofi."},
  "2010_ljeto_B__11": {"A":"Usporedba s glazbalom odnosi se na ljepotu izraza, a ne na razlog želje za pjesničkom besmrtnošću.","B":"Bogatstvo rječnika nije navedeno kao motiv; cilj je živjeti i nakon smrti.","C":"Pjesnik ne govori o pjevanju tema od rođenja do smrti, nego o vlastitu trajanju u jeziku nakon smrti."},
  "2010_ljeto_B__12": {"B":"Taj stih izriče odsutnost i smrt, ali ne i ideju opstanka u stihovima koja je u zadnjoj strofi.","C":"Stih izražava želju za životom u tuđim grudima, a ne besmrtnost kroz vlastitu poeziju.","D":"Stih govori o predaji vlastita života u tuđu ruku, što ne odgovara motivu trajanja u stihovima."},
  "2010_ljeto_B__13": {"A":"Homonimi su jednakozvučne riječi različita značenja, a 'zipka' i 'grob' ni glasovno ni značenjski nisu jednake.","B":"Sinonimi imaju istovjetno značenje, dok su 'zipka' i 'grob' suprotni pojmovi.","D":"Hiponimija je odnos nadređenoga i podređenoga pojma, a ovdje su pojmovi suprotstavljeni, ne podređeni."},
  "2010_ljeto_B__14": {"B":"'Kad me više ne bude' mijenja glagolski oblik (futur drugi), a ne samo uklanja inverziju.","C":"'Kad više ne budem' također mijenja oblik i lice glagola, čime se gubi izvorno značenje stiha."},
  "2010_ljeto_B__15": {"A":"'Voljeni' nije značenje pridjeva 'drevni'; emotivni odnos izražen je drugdje, a ne ovom riječju.","C":"'Jedinstveni' znači neponovljiv, a 'drevni' označava starinu.","D":"'Izražajan' se odnosi na snagu izraza, a ne na starinu koju nosi 'drevni'."},
  "2010_ljeto_B__16": {"A":"Roman je opsežno fikcionalno prozno djelo, a ovo je kratki stručno-esejistički odlomak o glagoljici.","B":"Pjesma je stihovani lirski tekst, dok je ovo proza bez stihova.","D":"Poema je dulja stihovana pripovjedna pjesma, što ne odgovara proznome esejističkom tekstu."},
  "2010_ljeto_B__17": {"A":"Tekst ne spominje grčku kulturu, nego latinskoromansku.","C":"Talijanske kulture u to doba još nema; riječ je o rimsko-latinskoj baštini Sredozemlja.","D":"Turci dolaze tek mnogo kasnije; Hrvati su zatekli latinskoromansku (rimsku) kulturu."},
  "2010_ljeto_B__18": {"A":"'Prava' nije naziv za vrstu glagoljice.","B":"Kurzivna glagoljica je brzopisni oblik, a hrvatski se ustaljeni oblik naziva oblom.","D":"Uglata je glagoljica zapravo hrvatska inačica nasuprot obloj makedonsko-bugarskoj; traženi naziv ovdje je 'obla'."},
  "2010_ljeto_B__19": {"A":"Držiha i Dobrovit spominju se na Bašćanskoj ploči, ali nisu slavenski apostoli.","B":"Rastislav i Mihajlo su moravski vladari koji su pozvali misionare, a ne sami apostoli.","D":"Crnorizac Hrabar i pop Dukljanin su pisci, a ne tvorci slavenske pismenosti."},
  "2010_ljeto_B__20": {"A":"Trpimirov natpis je raniji latinski spomenik, a 'dragocjeni kamen' je glagoljska Bašćanska ploča.","B":"Zapis popa Martinca je mlađi rukopisni tekst (1493.), a ne kamen koji autor naziva dragocjenim.","C":"Vinodolski zakon je pravni rukopis iz 1288., a ovdje se misli na kamen, Bašćansku ploču."},
  "2010_ljeto_B__21": {"A":"Sredina 9. stoljeća prerana je; Bašćanska ploča nastaje oko 1100. godine.","C":"Sredina 15. stoljeća prekasna je za nastanak Bašćanske ploče.","D":"Početak 16. stoljeća jest doba tiska, a ne nastanka ploče s kraja 11. stoljeća."},
  "2010_ljeto_B__22": {"A":"Krbavski poraz (1493.) zabilježen je u zapisu popa Martinca, a ne na Bašćanskoj ploči.","B":"Odnose knezova i građana uređuje Vinodolski zakon, a ne ploča.","D":"Godine kraljevske vladavine nisu sadržaj ploče; ona bilježi darovnicu samostanu."},
  "2010_ljeto_B__23": {"B":"Tomislav je raniji vladar (10. st.) i ne spominje se na Bašćanskoj ploči.","C":"Petar Krešimir IV. vladao je prije, a na ploči je zabilježen Zvonimir.","D":"Branimir se spominje na drugim natpisima (9. st.), a ne na Bašćanskoj ploči."},
  "2010_ljeto_B__24": {"A":"Tekst ne tvrdi da je jezik bio zaboravljen do 18. st., nego da se razvijao sporije zbog nedostatka domaće vlasti.","C":"Slavenski apostoli pridonijeli su pismenosti; razvoj nije njima prekinut, nego usporen tuđinskom vlašću.","D":"Hrvati nisu napustili svoj jezik za latinskoromanski; rečenica govori o usporenom razvoju vlastitoga jezika."},
  "2010_ljeto_B__25": {"A":"Ilijada i Odiseja pripadaju antici (8. st. pr. Kr.), daleko prije Bašćanske ploče.","B":"Gilgameš i Mahabharata su drevni istočnjački epovi, vremenski neusporedivi s 11. stoljećem.","C":"Bijesni Orlando i Oslobođeni Jeruzalem su renesansni/manieristički epovi 16. stoljeća, ne srednjovjekovni."},
  "2010_ljeto_B__26": {"B":"Šibenska molitva je rukopisni tekst, a ne prva tiskana knjiga.","C":"Lucidar je srednjovjekovni rukopisni zbornik, a ne prva hrvatska tiskana knjiga.","D":"Biblija nije bila prva hrvatska tiskana knjiga; to je glagoljski Misal iz 1483."},
  "2010_ljeto_B__27": {"A":"U srednjovjekovnoj se književnosti rabilo više pisama, ne samo jedno.","B":"Pisma su bila tri (glagoljica, ćirilica/bosančica, latinica), a ne dva.","D":"Pisama je itekako bilo; rabila su se sva tri navedena."},
  "2010_ljeto_B__28": {"A":"Likovi nisu prave, materijalne lutke, nego ljudi prikazani metaforom lutke.","C":"Riječ nije o osobama koje se igraju lutkama, nego o osobama koje su simbolično lutke u tuđim rukama.","D":"Likovi ne žele biti lutke; oni to nesvjesno već jesu u nametnutim ulogama."},
  "2010_ljeto_B__29": {"B":"Roman je prozno djelo, a Kuća lutaka je scensko djelo s replikama i didaskalijama.","C":"Ep je stihovana pripovjedna vrsta, što Kuća lutaka nije.","D":"Pjesma je lirska vrsta, dok je Kuća lutaka dramski tekst za izvedbu."},
  "2010_ljeto_B__30": {"A":"Miroslav Krleža je hrvatski pisac (Glembajevi), nije autor Kuće lutaka.","B":"A. P. Čehov je ruski dramatičar, nije napisao Kuću lutaka.","C":"Marcel Proust je francuski romanopisac, a ne autor te norveške drame."},
  "2010_ljeto_B__31": {"B":"Metafora je prijenos značenja, a Helmerova naglu promjenu raspoloženja oblikuje suprotstavljanje bijesa i nježnosti.","C":"Poredba uspoređuje dva pojma veznikom, što nije sredstvo na kojem počiva preokret raspoloženja.","D":"Personifikacija pridaje neživomu ljudska svojstva, a ovdje je riječ o kontrastu dvaju Helmerovih stanja."},
  "2010_ljeto_B__32": {"A":"Početak uvodi likove i situaciju, a ovaj prizor donosi rasplet pred Norin odlazak.","B":"Zaplet zaoštrava sukob, dok je ovdje sukob već razriješen čitanjem pisma.","C":"Vrhunac je trenutak najveće napetosti, a ovaj prizor slijedi nakon njega, u raspletu."},
  "2010_ljeto_B__33": {"B":"Ironije nema; Helmer iskreno (premda umišljeno) tepa Nori, ne govoreći suprotno od mišljenoga.","C":"Ton nije komičan radi smijeha, nego pokroviteljski i nadmoćan.","D":"'Zaneseno' bi značilo strasnu zanesenost, a Helmer je tu zaštitnički i snishodljiv, dakle pokroviteljski."},
  "2010_ljeto_B__34": {"A":"U pismu nije riječ o ljubavniku, nego o Norinu financijskom prijestupu.","C":"Vijest da ga Nora napušta dolazi tek kasnije, ne iz prvoga pisma.","D":"Pitanje očinstva djece nije tema; pismo otkriva pozajmicu i krivotvorenje potpisa."},
  "2010_ljeto_B__35": {"A":"Pismo ga nije istinski promijenilo; opraštanje slijedi tek kad nestane opasnost.","C":"Helmer ne shvaća veličinu Norine ljubavi, nego misli samo na vlastiti spas.","D":"On nije svjestan Norine moralne nadmoći; razlog je njegova nespremnost na žrtvu, a ne ta spoznaja."},
  "2010_ljeto_B__36": {"A":"Poredba bi tražila veznik (kao), a ovdje je 'krila' izravno preneseno značenje bez usporednice.","B":"Personifikacija pridaje neživomu ljudska svojstva, no ovdje se čovjeku pripisuje krilo, dakle riječ je o metafori.","C":"Ironije nema; izraz se temelji na prenesenome značenju zaštite, što je metafora."},
  "2010_ljeto_B__37": {"A":"Slika progonjene golubice prikazuje Helmerov pokroviteljski stav, ali ne izriče izravno temeljni problem djela.","B":"Rečenica o opraštanju pokazuje Helmerovu nadmoć, no ne formulira problem žene kao vlasništva.","D":"Ta rečenica naglašava Norinu podređenost volji muža, ali središnji problem (žena kao svojina) izravno izriče rečenica C."},
  "2010_ljeto_B__38": {"A":"Romantizam prethodi Ibsenu i obilježen je idealizacijom i emocijama, a ne kritičkim prikazom građanskoga braka.","C":"Modernizam nastupa kasnije; Kuća lutaka pripada realizmu 19. stoljeća.","D":"Suvremena književnost je 20./21. stoljeće, a drama je iz 1879., dakle realizam."},
  "2010_ljeto_B__39": {"A":"Ibsen nije francuski, nego norveški dramatičar.","C":"Ibsen nije njemački pisac.","D":"Ibsen nije engleski pisac, nego Norvežanin."},
  "2010_ljeto_B__40": {"A":"Cvjetovi zla (Baudelaire) najavljuju modernu liriku, a ne početak realizma kojemu pripada Kuća lutaka.","C":"Preobražaj (Kafka) je djelo modernizma 20. st., a ne razdoblja Kuće lutaka.","D":"Combray je dio Proustova modernističkog ciklusa, a ne početak realizma."},
  "2010_ljeto_B__41": {"A":"Antigona jest drama, ali Zločin i kazna je roman, pa niz nije jedinstven po rodu.","B":"Dubravka je dramsko djelo, no Otac Goriot je roman, pa niz miješa rodove.","D":"Posljednji Stipančići je roman; iako je U agoniji drama, niz nije čisto dramski."},
  "2010_ljeto_B__42": {"B":"Zamjenica postoji ('ti'), pa to nije vrsta koje nema.","C":"Glagola ima ('činiće se', 'će biti'), pa nedostaje druga vrsta.","D":"Pridjev je prisutan ('drukčijim'), pa to nije vrsta koje nema."},
  "2010_ljeto_B__43": {"A":"Prezenta i pluskvamperfekta u rečenici nema; 'ne ću' je futur prvi, a 'sam oprostio' perfekt.","C":"Kondicionala prvoga nema, a niz dvaju infinitiva nije potpun jer izostaje treći oblik koji je perfekt.","D":"Ni kondicionala ni prezenta nema; oblici su futur prvi, infinitiv i perfekt."},
  "2010_ljeto_B__44": {"A":"Nabrajanja u rečenici nema; nema niza istovrsnih članova odvojenih zarezom.","C":"Inverzija ne uvjetuje ove zareze; oni okružuju izdvojeni vokativ 'moja Noro'.","D":"'Nizanje' nije načelo pisanja ovih zareza; oni se pišu zbog vokativa (obraćanja)."},
  "2010_ljeto_B__45": {"A":"Romantizam je ranije razdoblje (sredina 19. st.), a Matoš stvara na prijelazu stoljeća.","B":"Realizam prethodi moderni; Matoš je vodeća figura hrvatske moderne, ne realizma.","D":"Druga moderna je razdoblje sredine 20. st. (Mihalić, Pupačić), a Matoš pripada (prvoj) moderni."},
  "2010_ljeto_B__46": {"B":"'Grbova' je neutralan, denotativan pojam i ne nosi ironiju.","C":"'Financije' je obična imenica bez ironijskoga naboja.","D":"'Vojsku' je doslovno značenje; ironiju nosi podrugljiva tvorba 'učeprtljišu'."},
  "2010_ljeto_B__47": {"A":"Ironija obilježava prvu rečenicu o 'buni', a opis jutra i neba je poetičan, lirski.","B":"Realistički bi opis bio objektivan i činjeničan, a ovdje su slike pjesnički, lirski dočarane.","D":"Naturalistički opis donosi surovu, ružnu zbilju, dok je ovaj opis ugođajan i lirski."},
  "2010_ljeto_B__48": {"A":"Kurziv ne izražava pijetet prema žrtvama, nego autorovu ironijsku ogradu od pojma.","B":"Kosa slova ne znače da je to službeno ime pobune, nego sumnju u njezinu pravu prirodu.","D":"Kurziv ovdje ne ističe važnost, nego naprotiv umanjuje i ironizira 'bunu'."},
  "2010_ljeto_B__49": {"A":"Nije riječ o isteku radnoga vremena, nego o paničnom skrivanju pred konjicom.","B":"Vrata nisu zatvorena zbog nevremena, nego zbog straha od vojske.","C":"Ljudi nisu nezainteresirani; upravo suprotno, preplašeno se zaključavaju i bježe."},
  "2010_ljeto_B__50": {"A":"Ponos nije razlog; Pepica ostaje jer tvrdoglavo ustraje pri svome.","B":"Želja za zaradom nije navedena kao motiv njezina neposluha.","D":"Radoznalost nije razlog; ona prkosno odbija otići uvjerena da nije kriva."},
  "2010_ljeto_B__51": {"A":"Pepica ne gine od zalutaloga metka, nego od konja.","C":"Ne umire od straha (prepuknuća srca), nego stradava pod konjem.","D":"Husari je ne streljaju; usmrćuje je udarac husarskoga konja."},
  "2010_ljeto_B__52": {"B":"Portret nije sentimentalan (raznježen), nego pretjeran i podrugljiv, dakle karikaturalan.","C":"Opis nije objektivno realističan, nego komički iskrivljen.","D":"Likovi nisu idealizirani; naprotiv, prikazani su smiješno i pretjerano."},
  "2010_ljeto_B__53": {"A":"Pepica ne predstavlja položaj žena, nego stradanje malog čovjeka i sudbinu domovine.","B":"Ona nije svjesni žrtvenik; strada slučajno, ne svjesnom žrtvom.","C":"Nije klasična tragička junakinja u sukobu dobra i zla, nego simbol nesretne hrvatske sudbine."},
  "2010_ljeto_B__54": {"A":"Pepica ne gleda na Bakačevu ulicu, nego na kip bana Jelačića.","B":"Pogled nije usmjeren na nebo, nego na 'sionog Bana' na trgu.","D":"Ne gleda u supruga Jožkeca, nego molitveno na Jelačićev kip."},
  "2010_ljeto_B__55": {"A":"Posljednja misao nije čežnja za rodnim selom, nego sjećanje vezano uz Jelačića i preporod.","B":"Nije riječ o spoznaji napuštenosti, nego o sjećanju na narodni preporod uz banov lik.","D":"Nije posrijedi odluka o dobru djelu, nego prisjećanje na preporodno doba i bana."},
  "2010_ljeto_B__56": {"A":"Djelo nije pustolovno; nema avanturističke radnje, nego satirični prikaz domovine.","B":"Iako prikazuje supružnike, tema nije obiteljska, nego sudbina domovine.","C":"Premda ima povijesni okvir, težište je na domoljubnoj satiri o stanju Hrvatske."},
  "2010_ljeto_B__57": {"A":"Preradović i Gaj pripadaju ilirizmu/romantizmu (sredina 19. st.), a ne moderni.","C":"Ujević i Cesarić djeluju nakon Matoša (međuratno razdoblje), a ne u njegovoj generaciji.","D":"Mihalić i Pupačić pripadaju drugoj polovici 20. st. (druga moderna), a ne Matoševoj moderni."},
  "2010_ljeto_B__58": {"B":"Notturno je intimna, ugođajna pjesma o noći, bez domoljubno-političke tematike Kipa domovine.","C":"Utjeha kose je ljubavna/refleksivna pjesma o prolaznosti, ne domoljubna.","D":"Jesenje veče je pejzažno-impresionistička pjesma, bez političke tematike djela."},
  "2010_ljeto_B__59": {"A":"Kajkavski 'kip' ne znači stanje.","C":"'Kip' ne znači sjećanje.","D":"'Kip' u kajkavskom nije apstraktni simbol, nego konkretno slika/prikaz."},
  "2010_ljeto_B__60": {"A":"'Baciti u kljun' nije ustaljeni frazem s prenesenim cjelovitim značenjem.","B":"'Poštovani Pogačić' je obična atributna sintagma, a ne frazem.","D":"'Ujezerila na tronošku' je slikoviti autorski izraz, ali ne ustaljeni frazem hrvatskoga jezika."},
  "2010_ljeto_B__61": {"A":"Znanstveni stil teži objektivnosti i terminologiji, a ovdje je izraz ekspresivan i ironičan.","C":"Administrativni stil obilježavaju klišeji i formalnost, što ne odgovara živom reportažnom tonu rečenice."},
  "2010_ljeto_B__62": {"A":"Historizmi imenuju nestale pojave (npr. povijesne ustanove), a 'onijeh' je samo zastarjeli gramatički oblik.","C":"Lokalizmi su mjesno ograničene riječi, a 'onijeh' je starinski oblik, ne mjesna posebnost.","D":"Egzotizmi su riječi iz stranih, dalekih kultura, dok je 'onijeh' domaći arhaični oblik."},
  "2010_ljeto_B__63": {"B":"'Zarudi' ne znači zvuk (topot), nego pojavu crvene boje konjice.","C":"Konjica ne odlazi, nego se tek pojavljuje; 'zarudi' označava pojavljivanje, ne odlazak.","D":"'Zarudi' ne govori o plamenu, nego o crvenome rumenilu, dakle pojavi konjice u crvenom."},
  "2010_ljeto_B__64": {"B":"'Za tili časak' ne znači sporo, nego upravo suprotno, vrlo brzo.","C":"Izraz ne znači 'malo prije'; označava brzinu, a ne prošli trenutak.","D":"Ne znači 'prije svega', nego 'za tren, vrlo brzo'."},
  "2010_ljeto_B__65": {"B":"'Mniti' nije pravilan infinitiv ovoga glagola; standardno je 'mnijeti'.","C":"'Mnijevati' je nepostojeći oblik za ovaj glagol.","D":"'Mnijuti' nije ispravan infinitiv; glagol glasi 'mnijeti'."},
  "2010_ljeto_B__66": {"A":"'Nejdem' je također dijalektni (kajkavski) oblik, a ne suvremeni standardni 'ne idem'.","B":"'Ne budem' mijenja glagolski oblik i značenje izvornika ('ne idem').","D":"'Ne ću' znači odbijanje volje (futur), a izvorno 'nedem' znači 'ne idem'."},
  "2010_ljeto_B__67": {"A":"Balzac jest u popisu autora i njegovo je djelo Ljudska komedija, a Božanstvenu nije napisao on.","B":"Proust jest u popisu i njegovo je djelo upravo U traganju za izgubljenim vremenom.","D":"Tolstoj jest u popisu i Ana Karenjina jest njegovo djelo; autor koji nedostaje je Dante."},
  "2010_ljeto_B__68": {"B":"'Najednostavnije' je pogrešno; pri dodavanju 'naj-' na riječ koja počinje s 'j' pišu se dva 'j': najjednostavnije."},
  "2010_ljeto_B__69": {"B":"'Kraće' bi bio prilog ili srednji rod, a imenica 'trajanja' (ž. r. mn.) traži oblik 'kraća'."},
  "2010_ljeto_B__70": {"B":"'Ugradjen' je pogrešno; skup 'dj' u trpnom pridjevu daje 'đ', pa je pravilno 'ugrađen'."},
  "2010_ljeto_B__71": {"B":"Malo slovo 'jačina' nije ispravno na početku rečenice; početak rečenice piše se velikim slovom."},
  "2010_ljeto_B__72": {"B":"Druga je inačica istovjetna pravilnoj ('izvođenja') te ne predstavlja pravopisno različitu, pogrešnu mogućnost."},
  "2010_ljeto_B__73": {"B":"'Dijela' je genitiv imenice 'dio', a ovdje je riječ o 'djelu' (uradku), pa je pogrešno."},
  "2010_ljeto_B__74": {"A":"'Melodia' je neprilagođeni talijanski oblik; u hrvatskome se piše s 'j': melodija."},
  "2010_ljeto_B__75": {"B":"'Sljed' (kratki slog) ne odgovara značenju; za 'redoslijed, niz' pravilno je 'slijed' (dugi slog, ije)."},
  "2010_ljeto_B__76": {"B":"'Cijelina' ne postoji; imenica od 'cijel' u kratkom slogu glasi 'cjelina'."},
  "2010_ljeto_B__77": {"B":"'Talijanskoga' velikim slovom je pogrešno; posvojni pridjevi od naziva naroda pišu se malim slovom."},

  // 2010_zima_A
  "2010_zima_A__1": {"A":"Nadrealizam počiva na automatskome pisanju i snovitim, nelogičnim slikama, a ne na jasnim, mirnim krajolicima kakve Vidrić oslikava.","B":"Romantizam je razdoblje 19. stoljeća s naglaskom na emocijama i nacionalnome zanosu; Vidrićevi pejzaži pripadaju kasnijoj moderni.","D":"Ekspresionizam donosi dramatičnu, izobličenu i napetu sliku stvarnosti, dok su ovi tekstovi smireni, vizualni i ugođajni."},
  "2010_zima_A__2": {"B":"U tekstovima nema osjećaja čovjekove izoliranosti; lirski subjekt je uronjen u prirodu i njome opčinjen.","C":"Motiv prolaznosti vremena nije u središtu; tekstovi slikaju trenutačni ugođaj prirode, a ne tijek vremena.","D":"Nesklada čovjeka i prirode nema; odnos je skladan i čovjek je dio prirodne ljepote."},
  "2010_zima_A__3": {"A":"Motivi se razlikuju (Prvi pejzaž: dan, polje, pčele; Drugi: noć, mjesec, glas), pa nisu poveznica.","B":"Tema kao takva nije ista jedinica koja ih spaja; razlikuju se prizori, a zajednički im je upravo ugođaj.","C":"Oblik se razlikuje (rima i kompozicija nisu identične), pa nije ono što ih povezuje."},
  "2010_zima_A__4": {"A":"Sukladan bi značio potpunu podudarnost, no tekstovi se razlikuju u prizoru (dan/noć) i raspletu.","B":"Oprečni odnos pretpostavlja suprotnost, a oba teksta zajednički veličaju ljepotu prirode, bez međusobne suprotnosti.","C":"Zavisni odnos značio bi da jedan tekst ovisi o drugome, no oni stoje samostalno, jedan uz drugi."},
  "2010_zima_A__5": {"A":"Po broju strofa tekstovi se ne razlikuju bitno; razlika je u završnoj slici.","B":"Razlika nije u tipu rime, nego u načinu na koji svaki pejzaž zatvara prizor.","C":"Kolorit (boje, svjetlost) prisutan je u obama tekstovima i nije ono po čemu se razlikuju."},
  "2010_zima_A__6": {"A":"Opijenost nije nesklad s razdraganošću, ali Drugi pejzaž ne pokazuje ravnodušnost, nego uzbuđenje, pa odgovor ne valja.","B":"Prvi pejzaž je smiren, spokojan, a ne razdragan; uplašenosti u Drugome također nema, nego radoznalo uzbuđenje.","C":"U Prvome pejzažu nema tugaljivosti (slika je vedra i mirna), niti je u Drugome riječ o nostalgiji."},
  "2010_zima_A__7": {"B":"Prvi pejzaž nije dinamičan; njegov je ritam usporen i spokojan zbog statičnoga opisa polja.","C":"Drugi pejzaž nije smiren, nego dinamičniji zbog kretanja mjeseca, glasa i micanja grane.","D":"Raspored je obrnut: prvi je usporen, a drugi dinamičan, a ne suprotno."},
  "2010_zima_A__8": {"A":"Shema abab značila bi da se i prvi (cvjetovi) s trećim (stablima) stihom rimuju, no oni se ne rimuju.","B":"Shema abba pretpostavlja obgrljenu rimu, no prvi i četvrti stih (cvjetovi/bijele) se ne rimuju.","D":"Shema abcd značila bi da nema nijedne rime, no drugi i četvrti stih (pčele/bijele) se rimuju."},
  "2010_zima_A__9": {"B":"Predikati su uglavnom stanja bez prave radnje; vizualnu sliku nose imenovani predmeti, a ne glagolske radnje.","C":"Objekata gotovo i nema; rečenice su pretežno bezobjektne, pa objekt ne gradi sliku.","D":"Apozicija se u strofi ne pojavljuje kao nositelj prizora."},
  "2010_zima_A__10": {"A":"Tvrdnja da auditivnog motiva nema nije točna jer 'Podnevno zvono zove' jasno donosi zvuk.","C":"Dvaput nije točno; jasan auditivni motiv (zvono) javlja se samo jedanput.","D":"Triput je previše; u Prvome pejzažu prevladavaju vizualni motivi, a zvuk se javlja samo jednom."},
  "2010_zima_A__11": {"A":"U prvoj strofi opisuje se samo mjesec; lirskoga 'ja' još nema.","C":"Treća strofa donosi glas iz grmlja, ali lirski je subjekt već uveden ranije, u drugoj.","D":"Četvrta strofa razvija već prisutni lirski subjekt; on se prvi put pojavljuje u drugoj strofi ('otvorio sam prozor')."},
  "2010_zima_A__12": {"A":"Marina je morski prizor; ovdje su motivi noći i mjeseca, a ne mora.","C":"Elegija je tužaljka, pjesma žalobnoga tona, a ovaj tekst nije tužaljka, nego noćna slika.","D":"Balada je pripovjedna pjesma s tragičnim raspletom, što ovaj ugođajni noćni prizor nije."},
  "2010_zima_A__13": {"A":"Nije riječ o prekidu neugodna razgovora; tajnoviti glas ostaje neobjašnjen, a ugođaj je čaroban, ne neugodan.","B":"Iako je vrt mokar od kiše, to nije smisao tih stihova, nego priznanje da tajna nije razriješena.","D":"Pjesnik nigdje ne odlazi u nepoznato; on ostaje pred zagonetkom koju ne može odgonetnuti."},
  "2010_zima_A__14": {"A":"Izraz nije pretežno metaforičan; Vidrić slika izravno i jasno, bez razgranate metaforike.","B":"Hermetičnost znači zatvoren, teško razumljiv izraz, što je suprotno Vidrićevoj prozirnosti.","C":"Simbolizam gradi skrivena značenja kroz simbole, dok je Vidrić neposredan i slikovit."},
  "2010_zima_A__15": {"A":"Preradović i Gaj pripadaju hrvatskome romantizmu/preporodu, a ne moderni kao Vidrić.","C":"Ujević i Cesarić djeluju u međuratnom razdoblju, nakon moderne.","D":"Mihalić i Pupačić pjesnici su druge polovice 20. stoljeća, znatno nakon Vidrićeve moderne."},
  "2010_zima_A__16": {"B":"Leksička norma tiče se izbora riječi, a ovdje su riječi obične; odstupanje je u obliku glagolskoga pridjeva.","C":"Fonološka norma odnosi se na glasove, no problem nije u izgovoru, nego u tvorbi oblika ('plivo' umjesto 'plivao').","D":"Sintaktička norma tiče se rečeničnoga ustroja, a ovdje je posrijedi odstupanje u jednome glagolskom obliku."},
  "2010_zima_A__17": {"A":"Infinitiva u Prvome pejzažu nema; svi su glagoli osobni oblici.","C":"Aorist (prošlo svršeno) ne pojavljuje se; glagoli izriču trajno stanje u sadašnjosti.","D":"Imperativa (zapovjednoga načina) u opisnom prizoru nema."},
  "2010_zima_A__18": {"A":"Jaču stanku unutar rečenice obično označuju drugi znakovi (crtica, točka sa zarezom), a ne završno trotočje.","B":"Nizanje dijelova teksta nije funkcija završnoga trotočja, nego npr. nabrajanja unutar rečenice.","C":"Trotočje na kraju ne signalizira izostavljen citatni dio, nego otvorenost i trajanje ugođaja."},
  "2010_zima_A__19": {"A":"Ljudska komedija je Balzacov ciklus romana, a ne djelo iz kojega je 'Pakao'.","C":"Put u središte Zemlje je roman Julesa Vernea, nepovezan s Danteom.","D":"Izgubljeni raj je ep Johna Miltona, a ne Danteovo djelo."},
  "2010_zima_A__20": {"B":"Ep je svjetovna junačka pripovijest u stihu; Danteovo djelo je religiozno-alegorijsko, pa je poema, a ne ep u užem smislu.","C":"Crkveno prikazanje je srednjovjekovna scenska vrsta namijenjena izvedbi, što Božanstvena komedija nije.","D":"Mit je usmena predaja o bogovima i postanku svijeta, a ovo je autorsko pisano djelo."},
  "2010_zima_A__21": {"A":"Sv. Petar nije osoba koja govori; pridošlica je antički pjesnik iz Mantove.","B":"Eneja je junak o kojem došljak pjeva, a ne sam došljak.","C":"Julije Cezar spominje se tek vremenski ('Sub Julio'), ali nije lik koji dolazi Danteu."},
  "2010_zima_A__22": {"B":"Eneida je rimska, a ne grčka epopeja; Vergilije je rimski pjesnik.","C":"Srednjovjekovno prikazanje nije Vergilijevo djelo; on je antički autor.","D":"Vergilije ne govori o zbirci mitoloških priča, nego o svome epu o Eneji."},
  "2010_zima_A__23": {"A":"Nije riječ o gubitku ljudskosti u moralnom smislu, nego o tome da više nije živ.","B":"Nigdje se ne spominje prodaja duše vragu; on je samo umrli, sjena.","C":"Lik dobro zna tko je (Vergilije iz Mantove); rečenica govori da više nije među živima."},
  "2010_zima_A__24": {"A":"Skrbnik nije uloga Vergilija; on vodi Dantea kroz onostranost, a ne brine se o njemu kao štićeniku.","C":"Premda poučava, primarna mu je uloga vodič kroz Pakao i Čistilište, ne učitelj u školskom smislu.","D":"Mecena bi bio pokrovitelj-financijer; Vergilije to nije, nego Danteov vodič."},
  "2010_zima_A__25": {"A":"Tri je premalo; Danteov Pakao ima devet krugova.","C":"Trideset i tri je broj pjevanja u svakome dijelu Komedije, a ne broj paklenih krugova.","D":"Stotinu je ukupan broj pjevanja cijeloga djela, a ne broj krugova pakla."},
  "2010_zima_A__26": {"A":"Vergilije nije veliki grješnik; razlog je njegovo nekrštenje jer je živio prije Krista.","C":"Nije posrijedi nepoznavanje; razlog je teološki, nedostatak krštenja.","D":"Politički protivnik nema veze s ovim prizorom; isključen je jer nije bio kršten."},
  "2010_zima_A__27": {"B":"Djevica Marija nije Danteov vodič kroz Raj; ta je uloga dana Beatrice.","C":"Judita je biblijska junakinja Marulićeva epa, nepovezana s Danteovim vodstvom.","D":"Laura je Petrarcina ljubav, a ne Danteova vodičica."},
  "2010_zima_A__28": {"A":"Grčki nije Danteov jezik; on piše na narodnome talijanskom (toskanskom).","B":"Iako je latinski bio jezik učenosti, Dante je svjesno izabrao narodni talijanski jezik.","C":"Staroslavenski je liturgijski jezik Slavena, nepovezan s Danteom."},
  "2010_zima_A__29": {"A":"Cervantes i Shakespeare pripadaju kasnijoj renesansi i drugim književnostima, a ne talijanskoj predrenesansi.","B":"Ovidije i Plaut su antički rimski pisci, a ne predrenesansni trolist.","C":"Tasso i Ariosto su talijanski pisci, ali zrele renesanse 16. stoljeća, ne predrenesanse."},
  "2010_zima_A__30": {"A":"Točka bi prekinula rečenicu i razbila nabrajanje ('sjena il' živ čovjek'), pa ne odgovara.","C":"Dvotočje najavljuje nabrajanje ili objašnjenje, no ovdje stoji unutar nabrajanja, gdje pristaje zarez.","D":"Kosa crta nije razgodak prikladan za ovaj umetak; ona se rabi za drukčije svrhe (npr. stihovi, alternativa)."},
  "2010_zima_A__31": {"A":"Razgovor ugodni naroda slovinskoga je djelo Andrije Kačića Miošića iz 18. stoljeća, ne Hektorovića.","C":"Osman je barokni ep Ivana Gundulića, nepovezan s ovim stihovima.","D":"Planine su Zoranićev pastirski roman, a ne Hektorovićevo djelo."},
  "2010_zima_A__32": {"A":"Srednjovjekovlje prethodi Hektoroviću; on stvara u 16. stoljeću, u renesansi.","C":"Romantizam je razdoblje 19. stoljeća, mnogo nakon Hektorovića.","D":"Prosvjetiteljstvo pripada 18. stoljeću, također nakon renesanse."},
  "2010_zima_A__33": {"A":"Epski narodni deseterac ima deset slogova; Hektorovićev je stih dvanaesterac.","B":"Lirski jedanaesterac nije Hektorovićev stih; on piše dvanaestercem s dvostrukom rimom.","D":"Stih bugarštice je dugi, najčešće petnaesterac ili šesnaesterac, a ne dvanaesterac."},
  "2010_zima_A__34": {"B":"Iz Splita potječe Marko Marulić (i don Dujam), a ne Hektorović koji kreće s Hvara.","C":"Korčula nije Hektorovićevo polazište; on je s Hvara.","D":"Dubrovnik nije ishodište putovanja; Hektorović je Hvaranin."},
  "2010_zima_A__35": {"A":"Jedan dan je premalo; ribanje je trajalo tri dana.","C":"Tjedan dana ne odgovara; putovanje je trodnevno.","D":"Mjesec dana je predugo; djelo opisuje trodnevno ribanje."},
  "2010_zima_A__36": {"A":"Ep i ljetopis nisu odgovor; djelo je po obliku poslanica, a po sadržaju putopis.","B":"Epopeja i memoari ne odgovaraju; nije epopeja ni memoari, nego poslanica i putopis.","D":"Elegija i pismo nisu točni; oblik jest pismo (poslanica), ali sadržaj je putopis, ne elegija."},
  "2010_zima_A__37": {"A":"Don Dujam Baništrilić spominje se kao domaćin u Nečujmu, ali ne putuje s pjesnikom.","B":"Marko Marulić se u tekstu samo slavi kao velik pisac; on ne putuje s Hektorovićem.","C":"Nisu putovali prijatelji pjesnici, nego dvojica ribara s kojima Hektorović razgovara."},
  "2010_zima_A__38": {"B":"'Čudno narešene, svake slasti slaje' govori o ljepoti i privlačnosti djela, ne o njihovoj raširenosti.","C":"'Kim je urešen bil i jezik slovinski' ističe da je Marulić obogatio hrvatski jezik, a ne europsku popularnost.","D":"'Koga, mnim, da si čul i knjige njega čtil' obraća se primatelju i govori o poznatosti Marulića, ne o širenju djela po svijetu."},
  "2010_zima_A__39": {"A":"Institutionum linguae illyricae je gramatika Bartola Kašića, a ne Marulićevo djelo.","B":"Elegiarum et carminum libri tres je zbirka Jana Pannoniusa, a ne Marulićevo proslavljeno djelo.","D":"Dictionarium quinque... je petojezični rječnik Fausta Vrančića, a ne Marulićevo djelo."},
  "2010_zima_A__40": {"A":"Davidijada je Marulićev latinski ep, dok je na početku hrvatske umjetničke književnosti Judita pisana hrvatskim jezikom.","C":"Molitva suprotiva Turkom je manje djelo i nije temeljni početak hrvatske umjetničke književnosti.","D":"Pedeset priča (Quinquaginta parabolae) je latinsko djelo, a ne početak književnosti na hrvatskome."},
  "2010_zima_A__41": {"B":"Stihovi ne govore o stvaranju novih književnih vrsta, nego o pisanju na dvama jezicima.","C":"Nije riječ o prevođenju antičkih pisaca, nego o Marulićevu pisanju na hrvatskome i latinskome.","D":"Prijevod Biblije nije spomenut; stihovi ističu njegovo pisanje na obama jezicima."},
  "2010_zima_A__42": {"A":"Tvrdnja je netočna: Hektoroviću put nije lijek od ljubavnih jada, nego stvarno ribanje radi razonode i pouke.","B":"Hektorovićevo putovanje nije pustolovina, nego stvaran, miran prikaz ribanja; Zoranićevo nije istraživačko, nego alegorijsko.","D":"Oba se autora kreću zavičajem; razlika nije u tuđini, nego u tome što je Zoranićevo putovanje alegorijsko."},
  "2010_zima_A__43": {"A":"Pjesma o Rolandu je junački ep o bitki; ne dijeli s Ribanjem motiv putovanja s pratnjom i razgovorom.","B":"Kafkin Preobražaj govori o čovjekovoj preobrazbi u kukca, a ne o putovanju.","C":"Araličini Psi u trgovištu povijesni su roman, bez temeljnoga motiva putovanja kao u Ribanju."},
  "2010_zima_A__44": {"A":"Andrija Kačić Miošić je rodom iz Brista (Makarsko primorje) i živi u 18. stoljeću, nije Hvaranin ni Hektorovićev suvremenik.","C":"Ivan Gundulić je Dubrovčanin baroka, ne Hvaranin ni Hektorovićev suotočanin.","D":"Vladimir Nazor potječe s Brača i pripada moderni, a ne Hektorovićevu Hvaru i renesansi."},
  "2010_zima_A__45": {"A":"'Koga si, predmnijevam, čuo i knjige mu čitao' mijenja smisao ('koga' umjesto 'za koga') i drukčije prenosi 'mnim'.","B":"'Kome si čuo ime' iskrivljuje izvornik jer dodaje 'ime' kojega u stihu nema.","C":"'Kojega znaš... i poznaješ njegove knjige' netočno prevodi 'čul' i 'čtil' (čuo, čitao) kao 'znaš' i 'poznaješ'."},
  "2010_zima_A__46": {"B":"Hiperbola je pretjerivanje; ovdje nema preuveličavanja, nego usporedbe s Danicom.","C":"Personifikacija pridaje neživomu ljudske osobine, čega u ovim stihovima nema.","D":"Simbol bi zahtijevao prikriveno preneseno značenje; ovdje je veza izrečena izravno ('kako... tako'), što je poredba."},
  "2010_zima_A__47": {"A":"Kratkosilazni naglasak je kratak, a 'kî' i 'dâ' nose dugi naglasak.","C":"Kratkouzlazni je kratak i uzlazan, što ne odgovara dugomu silaznom naglasku na ovim riječima.","D":"Dugouzlazni je uzlazan, a naglasak ovdje je silazan (kapa), pa nije dugouzlazni."},
  "2010_zima_A__48": {"A":"Čestica je nepromjenjiva riječ koja izriče stav; 'dâ' (dade) je oblik glagola, a ne čestica.","C":"Prijedlog stoji uz imenicu i izriče odnos; 'dâ' to nije, nego glagolski oblik.","D":"Veznik povezuje riječi ili rečenice; ovdje 'dâ' nije veznik 'da', nego glagol u značenju 'dade'."},
  "2010_zima_A__49": {"B":"Nije upravni govor jer nema doslovno navedenih tuđih riječi; 'mnim' je piščev umetak.","C":"Riječ nije u vokativu; 'mnim' je glagol ('mislim'), a ne dozivanje.","D":"Nije riječ o nizanju (nabrajanju); 'mnim' je umetnuta rečenica unutar iskaza."},
  "2010_zima_A__50": {"A":"Rima i sažetost izraza obilježja su lirike, a ovaj je tekst epski.","B":"Stihovi i lirski subjekt pripadaju lirici, dok je peti tekst proza, dakle epika.","D":"Prizor, lirski subjekt i stihovi vežu se uz liriku/dramu, a ne uz epsko pripovijedanje."},
  "2010_zima_A__51": {"A":"Komedija je dramska vrsta, pa skupina nije čisto epska.","B":"Romanca je lirsko-epska, a sama je skupina pomiješana; ne pripada jasno samo epici.","D":"Epitaf i esej nisu epske vrste, pa skup ne odgovara epici."},
  "2010_zima_A__52": {"B":"Drugo lice ('ti') nije korišteno; pripovjedač govori o sebi i skupini.","C":"Treće lice ne odgovara jer pripovjedač izrijekom rabi 'mi' ('nas', 'smo'), dakle prvo lice."},
  "2010_zima_A__53": {"A":"Objektivno pripovijedanje bilo bi nepristrano i izvanjsko, no ovdje pripovjedač iznosi vlastite osjećaje i sumnje.","B":"Ironije kao temeljnoga postupka u ovome odlomku nema; prevladava osobni, doživljajni ton.","D":"Humoristični ton nije nositelj odlomka; riječ je o subjektivnom razmišljanju o vodstvu."},
  "2010_zima_A__54": {"A":"Soba za prolaznike je Šoljanova zbirka, ali ne djelo iz kojega je ovaj ulomak o Roku.","B":"Okvir za mržnju je roman, no ne onaj iz kojega potječe ovaj tekst.","C":"Vježbanje života je roman Nedjeljka Fabrija, a ne Šoljanovo djelo iz ulomka."},
  "2010_zima_A__55": {"A":"Uništenje nije temeljni motiv; djelo je izgrađeno na neprestanu kretanju i potrazi.","C":"Prisjećanje nije nosivi motiv; radnja se temelji na kretanju kroz prostor.","D":"Ljetovanje se spominje, ali nije temeljni motiv; ono se pretvara upravo u stalno kretanje."},
  "2010_zima_A__56": {"B":"Roko nije sporedni lik; on je pokretač radnje oko kojega se sve vrti.","C":"Roko nije pripovjedač; priču pripovijeda jedan od njegovih suputnika u prvome licu."},
  "2010_zima_A__57": {"A":"Suputnici nisu energični; energija je Rokova, a oni mu se pasivno predaju.","B":"Nisu pronicljivi, nego sami priznaju da 'nisu vidjeli dalje od nosa'.","C":"Nisu agresivni, nego mlitavi i podložni tuđemu vodstvu."},
  "2010_zima_A__58": {"A":"Roka nije postavio nikakav organizator; vodstvo proizlazi iz odnosa skupine i njega.","B":"Nema spomena izbora na glasovanju; tekst govori o žeđi za vodstvom i Rokovoj prirodi.","C":"Nije bilo ucjene; Roko postaje vođa zbog suputničke želje za vođom i svoje vodeće naravi."},
  "2010_zima_A__59": {"A":"Zajedništvo se ne jača, nego slabi; skupina se postupno raspada.","B":"Skupina ne stiže zajednički do cilja; razilazi se prije njega.","D":"Nije riječ o tome da dio skupine smrtno strada, nego o postupnom raspadu društva."},
  "2010_zima_A__60": {"A":"Ofelija je Shakespeareov lik (Hamlet); Šoljan ženske likove ne naziva tako.","B":"'Eneida' je naslov epa, a ne ime kojim bi se imenovali ženski likovi.","C":"Antigona je junakinja antičke tragedije; Šoljan rabi ime Beatrice, ne Antigona."},
  "2010_zima_A__61": {"A":"Nisu školski prijatelji; riječ je o slučajno okupljenim mladim intelektualcima.","B":"Nisu sveučilišni profesori na projektu, nego mladi ljudi nasumce sastavljeni u skupinu.","C":"Nisu poznanici koji se sreću nakon dugo vremena; okupljeni su slučajno na izletu."},
  "2010_zima_A__62": {"B":"Pokornički bi opisao suputnike, a ne sam Rokov utjecaj; utjecaj na njih je opčinjavajući.","C":"Ponižavanja nema; suputnici se Roku predaju dragovoljno i s oduševljenjem.","D":"Autoritativan naglašava nametanje silom, no tekst pokazuje da ga slijede zavedeno, opčinjeni njegovom energijom."},
  "2010_zima_A__63": {"A":"Likovi se ne kreću prema Slavoniji, nego po Istri.","B":"Ne kreću se uz Krku, nego istarskim prostorom.","C":"Ne idu preko Velebita; radnja se odvija u Istri."},
  "2010_zima_A__64": {"A":"Nije hiperbola jer nema brojčanoga pretjerivanja, nego ustaljeni frazem.","C":"Nije metonimija (zamjena pojma srodnim), nego cjelovit frazeološki izraz.","D":"Nije kontrast jer se ne suprotstavljaju dvije slike; riječ je o ustaljenome izrazu."},
  "2010_zima_A__65": {"A":"U tim riječima ne stoji u središtu zajednička glasovna promjena, nego način tvorbe.","C":"Osnove im nisu iste ('vod-' prema 'nad-'), pa to nije zajedničko obilježje.","D":"Gramatički rod nije zajednički ('vođa' i 'beznađe' nisu istoga roda na isti način), nego im je zajednički tvorbeni postupak."},
  "2010_zima_A__66": {"A":"'Dohvatiti' je konkretno, fizičko značenje, no ovdje 'dokučiti' znači razumom shvatiti.","C":"'Dosegnuti' upućuje na doseg u prostoru, a u rečenici je riječ o shvaćanju.","D":"'Primaknuti' znači približiti, što ne odgovara značenju razumijevanja."},
  "2010_zima_A__67": {"B":"Netočno spaja Mihalića s 'Ubili su ga ciglama' (E); to djelo nije njegovo, a njegovo je 'Moj križ svejedno gori' (D).","C":"Netočno pridružuje Aralici 'Ubili su ga ciglama' (E) umjesto 'Psi u trgovištu' (A).","D":"Netočno spaja Brešana s 'Majstore, ugasi svijeću' (B); Brešanovo je 'Predstava Hamleta...' (C)."},
  "2010_zima_A__68": {"B":"'Napućili' bi pretpostavljalo glagol s 'ć', no pravilno je 'napučiti' (nastaniti) s 'č'.","C":"'Napuhnuli' je drugi glagol (od napuhati) i mijenja značenje.","D":"'Naputali' nije standardni oblik za značenje 'nastaniti'."},
  "2010_zima_A__69": {"B":"'Svijesna' bi tražila dugi jat (ije), no u pridjevu 'svjestan' jat je kratak (je).","C":"'Svisna' je pogrešno jer izostavlja refleks jata.","D":"'Svejsna' je nepostojeći, iskrivljen oblik."},
  "2010_zima_A__70": {"B":"'Rasčlaniti' krši jednačenje po mjestu tvorbe; 's' ispred 'č' prelazi u 'š'.","C":"'Rasčlanjivati' ima istu pogrešku (rasč- umjesto rašč-) i drukčiji glagolski vid.","D":"'Razdčlaniti' je iskrivljen, nepostojeći oblik."},
  "2010_zima_A__71": {"B":"'Rastaće' je pogrešno jer stavlja 'ć' umjesto 'č'.","C":"'Rastakuje' nije standardni prezentski oblik za taj glagol.","D":"'Rastoči' je svršeni oblik i mijenja vid i značenje rečenice."},
  "2010_zima_A__72": {"A":"'Proturiječja' bi tražila dugi jat (ije), no u složenici 'proturječje' jat je kratak (je).","C":"'Protivrječja' ima pogrešan prvi dio složenice ('protiv-' umjesto 'protu-').","D":"'Proturiječa' ima i pogrešan jat i pogrešan nastavak."},
  "2010_zima_A__73": {"B":"'Ne sputanom' je pogrešno jer se niječni pridjev 'nesputan' piše sastavljeno.","C":"'Ne-sputanom' s crticom nije pravilan zapis ovoga pridjeva.","D":"'Nesputanjem' je imenički oblik u instrumentalu i ne odgovara pridjevskoj službi u rečenici."},
  "2010_zima_A__74": {"A":"'Visoko obrazovanu' rastavljeno nije točno jer je riječ o složenome pridjevu koji se piše sastavljeno.","C":"'Visoko-obrazovanu' s crticom nije pravilan zapis ove složenice.","D":"'Visoke obrazovanosti' mijenja sintaktičku konstrukciju i nije traženi pridjevski oblik."},
  "2010_zima_A__75": {"A":"'Naručbe' je pogrešno jer pravilna imenica glasi 'narudžba' (s 'dž').","C":"'Narubdžbe' je iskrivljen, nepostojeći oblik.","D":"'Naruđbine' nije standardni oblik te imenice."},
  "2010_zima_A__76": {"B":"'Srednje vjekovnih' rastavljeno nije točno jer je 'srednjovjekovni' složenica koja se piše sastavljeno.","C":"'Srednje-vjekovnih' s crticom nije pravilan zapis ove složenice.","D":"'středověkovnih' je strani (češki) oblik, ne hrvatski."},
  "2010_zima_A__77": {"B":"'Pripovjesti' bi tražila kratki jat (je), no u imenici 'pripovijest' jat je dug (ije).","C":"'Pripovijednosti' je iskrivljen, nepostojeći oblik.","D":"'Pripovestih' rabi nepravilan refleks jata i zastarjeli/nestandardni nastavak."},

  // 2010_zima_B
  "2010_zima_B__1": {"B":"Tekst nema fabule, pripovjedača ni naracije, pa ne pripada epici.","C":"U tekstu nema dramskoga sukoba ni likova koji govore, pa nije drama."},
  "2010_zima_B__2": {"A":"Elegija je tužaljka određene tematike, a ovdje je riječ o ustaljenom obliku od 14 stihova.","C":"Oda je svečana pohvalnica, a Notturno nije pjesma uzvišena slavljenja.","D":"Poema je duža pripovjedna pjesma, a ovaj je tekst kratak, čvrste sonetne strukture."},
  "2010_zima_B__3": {"A":"Shema abab cdcd pripada engleskomu, a ne talijanskomu sonetu kojemu tekst pripada.","B":"Katrene imaju obgrljenu rimu abba, a ne ukrštenu abba s ovom rasporedbom tercina.","D":"Raspored abab abab ne odgovara obgrljenoj rimi katrena u tekstu."},
  "2010_zima_B__4": {"B":"Stihovi katrena imaju osam, a ne devet slogova.","C":"Katrene su osmerci, a ne deseterci.","D":"Katrene nisu jedanaesterci nego osmerci."},
  "2010_zima_B__5": {"A":"Notturno označava noćni prizor kao žanr, a ne raspoloženje kao takvo.","B":"Notturno nije po definiciji pjesma o smrti nego o noći.","D":"Notturno nije jadikovka nego prikaz noćnoga ugođaja."},
  "2010_zima_B__6": {"A":"Pjesma odiše spokojem, a ne tjeskobom.","B":"Priroda je živa i skladna, pa nema ravnodušnosti.","D":"Ugođaj je smiren i zadovoljan, bez ikakva iščekivanja."},
  "2010_zima_B__7": {"A":"Slika 'srebrn vir' upućuje na vid, a ne na njuh.","B":"Sinestezijom zvuk prelazi u drugo osjetilo, a ne ostaje samo slušni.","C":"U stihu nema osjeta okusa nego svjetlucave vizualne slike."},
  "2010_zima_B__8": {"A":"Sat broji otkucaje, dakle vrijeme teče, a ne stoji.","B":"Noć je vrijeme sna i mira, a ne buđenja.","D":"Stihovi govore o noći koja traje, a ne o dolasku dana."},
  "2010_zima_B__9": {"A":"'Pospan sat' ne označuje doba noći nego personificira spori protok vremena.","B":"Tišina noći nije značenje same sintagme 'pospan sat'.","C":"Sat broji, a ne pjeva uspavanku."},
  "2010_zima_B__10": {"B":"Željeznica koju guta daljina simbolizira nestajanje, a ne konkretan polazak na put.","C":"U pjesmi nema ljubavnoga rastanka nego općega utrnuća zvukova.","D":"Slika nestajanja u noći suprotna je buđenju novoga dana."},
  "2010_zima_B__11": {"A":"Slogovanje 'Sit-ni' i 'cv-r-čak' je pogrešno; prvi slog je 'Si-', a 'cvrčak' se dijeli 'cvr-čak'.","B":"'Sit-ni' i 'cv-rči' nisu pravilno rastavljeni slogovi.","D":"'Cv-r-čak' i 'jas-an' nisu pravilna podjela na slogove."},
  "2010_zima_B__12": {"A":"U ovom stihu nema upadljiva ponavljanja istih suglasnika.","B":"Stih ne pokazuje izrazito gomilanje istoga suglasnika.","C":"Stih je prekratak i bez nizanja istih glasova za aliteraciju."},
  "2010_zima_B__13": {"A":"Golub nije noćni leteći sisavac niti odgovara značenju riječi netopir.","C":"Leptir je kukac, a netopir je sisavac (šišmiš).","D":"Sova je ptica, a netopir je šišmiš, sisavac."},
  "2010_zima_B__14": {"B":"'Kasnijega' je komparativ, a traži se genitiv pozitiva 'kasnoga'.","C":"'Kasan' je nominativ pridjeva i ne slaže se s genitivom imenice.","D":"Oblik 'kasna' nije ispravan genitiv određenoga pridjeva 'kasni'."},
  "2010_zima_B__15": {"A":"Narodni preporod traje u prvoj polovici 19. st., prije Matoševa vremena.","B":"Realizam prethodi moderni, a Matoš je njezin predstavnik.","D":"Postmodernizam je razdoblje druge polovice 20. st., mnogo nakon Matoša."},
  "2010_zima_B__16": {"A":"Dekameron nije zbirka ljubavnih pjesama nego proznih novela.","B":"Dekameron sadrži novele, a ne bajke.","C":"Dekameron nije roman u nastavcima nego zbirka samostalnih novela."},
  "2010_zima_B__17": {"A":"Naziv ne znači 'sretan završetak' nego se izvodi iz brojeva deset i dan.","C":"Naziv ne upućuje na 'sto zgoda' nego na deset dana pripovijedanja.","D":"Naziv nema veze s ispovijedanjem duše nego s deset dana."},
  "2010_zima_B__18": {"B":"Uvod nije razrada nego okvir unutar kojega se nižu novele.","C":"Invokacija je zaziv muze u epu, a ovdje je riječ o pripovjednome okviru.","D":"In medias res je počinjanje usred radnje, a ne uvodni okvirni dio."},
  "2010_zima_B__19": {"A":"Razlog odlaska nije rat nego epidemija kuge.","B":"U uvodu se ne spominje potres nego pošast kuge.","D":"Skupina sama odlazi, a nije protjerana."},
  "2010_zima_B__20": {"B":"Dioneo ističe da ih je doveo razbor djevojaka, a ne domišljatost mladića.","C":"U tekstu se ne spominje nagovor roditelja.","D":"Razlog odlasku jest razbor djevojaka, a ne puka želja za zabavom."},
  "2010_zima_B__21": {"A":"Mladići i djevojke nisu dvorjani nego pripovjedači novela.","C":"Oni nisu putujući glumci nego kazivači priča.","D":"Ne poučavaju ples nego svaki dan pripovijedaju po jednu novelu."},
  "2010_zima_B__22": {"A":"Panfilo nije zapjevao nego počeo pripovijedati priču.","C":"Panfilo ne započinje ples nego prvu novelu.","D":"Panfilo ne otpočinje natjecanje nego pripovijedanje."},
  "2010_zima_B__23": {"A":"U odlomku nema monologa lica nego opisa prostora.","C":"Retardacija je usporavanje radnje, a ovdje je riječ o opisu.","D":"Retrospekcija je vraćanje u prošlost, a odlomak opisuje sadašnji prizor."},
  "2010_zima_B__24": {"A":"Opis cvjetnoga, bujnoga mjesta nije tmuran nego vedar.","B":"Prizor je jasan i skladan, a ne mističan.","C":"Opis je realističan i ugodan, bez fantastičnih elemenata."},
  "2010_zima_B__25": {"B":"Skupina je vesela, a ne pesimistična.","C":"Dioneo poziva na šalu, pa nema cinizma.","D":"Raspoloženje je vedro i optimistično, a ne turobno."},
  "2010_zima_B__26": {"A":"Dioneo ističe dostojanstvo, pa nisu razuzdani.","B":"Skupina je vesela i čestita, a ne tužna i neutješna.","D":"Likovi su smjerni i ugodni, a ne strogi i ozbiljni."},
  "2010_zima_B__27": {"A":"Boccaccio piše na pučkome talijanskom, a ne na latinskome.","B":"Dekameron nije pisan staroslavenskim nego toskanskim talijanskim.","D":"Djelo nije na grčkome nego na talijanskome volgare."},
  "2010_zima_B__28": {"A":"Cervantes i Shakespeare nisu talijanski predrenesansni pisci.","B":"Ovidije i Plaut antički su rimski pisci, a ne predrenesansni trolist.","C":"Tasso i Ariosto pripadaju kasnijoj renesansi, a ne predrenesansnomu trolistu."},
  "2010_zima_B__29": {"A":"Frazem ne znači 'pričekati' nego upravo suprotno - bez oklijevanja.","B":"Frazem ne znači gubljenje vremena nego brzo djelovanje.","C":"Naglasak nije na radosti nego na trenutačnosti čina."},
  "2010_zima_B__30": {"A":"Dundo Maroje je dramsko djelo za izvedbu, a ne roman.","B":"Djelo je vesela komedija, a ne tragedija.","D":"Dundo Maroje je drama, a ne prozna novela."},
  "2010_zima_B__31": {"A":"Pomet ne spominje glumce ni slikare nego pjesnike i glazbenike.","B":"U govoru se ne spominju slikari nego pjesnik i glazbenik.","C":"Spominju se pjesnik i glazbenik, a ne glumci."},
  "2010_zima_B__32": {"A":"Pomet ne zagovara činjenje samo onoga što se želi nego prilagodbu prilikama.","B":"Pomet odbacuje i bogatstvo i viteške vrline kao jamstvo uspjeha.","D":"Pomet ne preporučuje pokorno trpljenje nego strpljivu i pravodobnu mudrost."},
  "2010_zima_B__33": {"A":"Pomet je promišljen i lukav, a ne naivan.","C":"Pometa ne pokreće škrtost nego lukava prilagodljivost.","D":"Pomet djeluje sebično i proračunato, a ne velikodušno."},
  "2010_zima_B__34": {"A":"Pomet ne teži vladanju svijetom nego zadovoljenju trbuha.","B":"Pomet se ne brine za bolji svijet nego za vlastiti užitak.","C":"Pometu cilj nije bogatstvo nego dobra hrana i piće."},
  "2010_zima_B__35": {"B":"Pomet ne tumači zbivanja publici nego sam pokreće radnju.","C":"Pomet nije deus ex machina nego stvarni pokretač zapleta.","D":"Pomet ne uvodi predstavu u predstavi nego upravlja radnjom."},
  "2010_zima_B__36": {"A":"Pomet je lukav i snalažljiv, a ne glup i nesposoban za suradnju.","B":"Pomet ne iskorištava ljude radi novca nego svima ugađa radi vlastite koristi.","D":"Pomet trpi i podnosi, a nije svadljiv ni naprasit."},
  "2010_zima_B__37": {"A":"Radnja se ne odvija u Dubrovniku nego u Rimu.","B":"Mjesto radnje nije Venecija nego Rim.","D":"Radnja nije smještena u Split nego u Rim."},
  "2010_zima_B__38": {"A":"Romantizam je razdoblje 19. st., a Držić djeluje u 16. st.","C":"Srednji vijek prethodi Držiću koji pripada renesansi.","D":"Barok slijedi nakon renesanse, a Držić je renesansni pisac."},
  "2010_zima_B__39": {"A":"U ulomku govori samo jedno lice, pa nema dijaloga.","C":"Kulminacija je vrhunac radnje, a ne dramska tehnika govora.","D":"Didaskalija je scenska uputa, a tekst je Pometov govor, dakle monolog."},
  "2010_zima_B__40": {"A":"Metaforičnost je obilježje lirike, a ne osnova drame.","B":"Pripovijedanje je obilježje epike, a ne drame.","D":"Iskazivanje osobnih osjećaja svojstveno je lirici, a ne drami."},
  "2010_zima_B__41": {"A":"Pripovijedanje o licima epski je, a ne dramski postupak karakterizacije.","B":"Vanjski opis lica nije način karakterizacije u drami.","C":"Popis lica samo navodi osobe, ali ih ne karakterizira."},
  "2010_zima_B__42": {"A":"Retardacija, epizode i digresije pripadaju epskoj kompoziciji, a ne scenskoj strukturi.","B":"Opis i pripovijedanje epski su postupci, a ne dijelovi scenske izvedbe.","C":"Teme, motivi i fabula sadržajne su sastavnice, a ne struktura izvedbe."},
  "2010_zima_B__43": {"A":"'Kip domovine...' je lirska pjesma, a ne drama.","C":"'Balada iz predgrađa' je lirsko djelo, a ne drama.","D":"'Posljednji Stipančići' je roman, dakle epika, a ne drama."},
  "2010_zima_B__45": {"A":"Tekst ima dijaloge i didaskalije scenskoga djela, pa nije lirika.","B":"Tekst nije pripovjedna proza nego dramski tekst za izvedbu."},
  "2010_zima_B__46": {"A":"Prolog je uvodni govor, a ne kosim slovima otisnuta uputa.","B":"Epilog je zaključni dio, a ne scenska uputa u kurzivu.","D":"Replika je govor lica, a kosim su slovima pisane upute, ne replike."},
  "2010_zima_B__47": {"A":"Leone nije svećenik nego slikar i sin Ignjata Glembaya.","C":"Leone nije pravni savjetnik nego umjetnik, sin glave obitelji.","D":"Leone nije liječnik nego Ignjatov sin slikar."},
  "2010_zima_B__48": {"A":"Sukobe ne pokreće povratak zbog novca nego Leoneova optužba o nevjeri.","B":"Bankareva ucjena nije okidač nego Leoneova izjava o baruničinu ljubavniku.","C":"Sukob ne izaziva otkriće pravoga oca nego optužba za bračnu nevjeru."},
  "2010_zima_B__49": {"B":"Leone se ne boji svađe s bratom i sestrom nego stare strasti prema barunici.","C":"Riječ nije o mržnji prema ocu nego o strasti prema njegovoj ženi.","D":"Strah nije od otkrivanja potrošena nasljedstva nego od ljubavne strasti."},
  "2010_zima_B__50": {"A":"Krivnja ne proizlazi iz propasti tvrtke nego iz očeve smrti.","B":"Razlog krivnji nije izbivanje nego smrt oca.","C":"Leone se ne kaje zbog nevjere nego zbog uzrokovane očeve smrti."},
  "2010_zima_B__51": {"A":"Glembajevski imperativ nije socijalna osjetljivost nego naslijeđeni nagoni.","C":"Pojam ne označuje obiteljsku idilu nego destruktivno nasljeđe.","D":"Riječ nije o financijskoj neovisnosti nego o naslijeđenim sklonostima."},
  "2010_zima_B__52": {"B":"Leone ne otkriva socijalni status ni govorne osobine nego psihu i nagone.","C":"Riječ nije o vanjskom izgledu nego o naturalističko-psihološkoj analizi.","D":"Karakterizacija nije simbolistička nego naturalistička i psihološka."},
  "2010_zima_B__53": {"A":"Rečenica ne pretjeruje radi pojačanja nego uspoređuje veznikom 'kao'.","C":"Nije riječ o simbolu nego o izravnoj usporedbi s jaguarom.","D":"Nije personifikacija jer se ljudsko ponašanje uspoređuje sa životinjom, a ne obrnuto."},
  "2010_zima_B__54": {"A":"Angelika ne nadahnjuje nego tješi i smiruje Leonea.","B":"Angelika se ne odnosi prema njemu sa strahom nego sa samilošću.","D":"Angelika ne pokazuje divljenje nego brižnu utjehu."},
  "2010_zima_B__55": {"A":"Suprotnost nije ljepota i ružnoća nego duhovno i tjelesno.","B":"Odnos se ne temelji na dobi nego na duhovnom i tjelesnom načelu.","C":"Krleža ih ne suprotstavlja kao selo i grad nego kao duhovno i tjelesno."},
  "2010_zima_B__56": {"A":"Uzrok bijesu nije svađa sa suprugom nego novinski natpisi.","B":"Barunicu ne razbješnjuje materijalna propast nego skandal u tisku.","D":"Razlog nisu usmeni tračevi nego objavljeni novinski natpisi."},
  "2010_zima_B__57": {"B":"Leoneova replika nije završna rečenica drame.","C":"Glembayeva izjava nije posljednja replika djela.","D":"Angelikina utješna rečenica ne zatvara dramu."},
  "2010_zima_B__58": {"A":"Veza nije uspon i pad patricijske obitelji nego povratak i kriza umjetnika.","B":"Djela ne povezuje Edipov kompleks nego motiv povratka i umjetnička kriza.","C":"Junaci nemaju isti životni put ni tragičan kraj; poveznica je povratak i kriza."},
  "2010_zima_B__59": {"A":"'Povratak Filipa Latinovicza' je roman, a 'Vučjak' nije dio toga dramskog ciklusa.","C":"'Na rubu pameti' je roman, a 'Balade Petrice Kerempuha' lirika; ne pripadaju ciklusu.","D":"'Kristofor Kolumbo' i 'Zastave' nisu dio glembajevskoga ciklusa."},
  "2010_zima_B__60": {"A":"Krleža na početku nije futurist nego ekspresionist.","B":"Moderna prethodi Krležinim počecima koji su ekspresionistički.","D":"Krleža nije počeo kao nadrealist nego kao ekspresionist."},
  "2010_zima_B__61": {"A":"Muzej suvremene umjetnosti ne nosi Krležino ime.","B":"Ne postoji 'Institut za književnost' s Krležinim imenom kao tražena ustanova.","D":"HNK ne nosi ime Miroslava Krleže."},
  "2010_zima_B__62": {"A":"Ovdje 'imperativ' ne znači izrečenu zapovijed nego nešto neizbježno.","B":"Riječ ne označuje stroge nazore nego ono čemu se ne može oduprijeti.","D":"Ne znači ono što je potrebno nego ono što je neizbježno."},
  "2010_zima_B__63": {"B":"Zarezi nisu po načelu suprotnosti jer u rečenici nema suprotnih dijelova.","C":"Nije riječ o inverziji nego o odvajanju vokativa zarezima.","D":"Nije riječ o umetanju nego o vokativu koji se odvaja zarezima."},
  "2010_zima_B__65": {"B":"Oblik 'devetnajstoga' s glasom 'j' nestandardan je."},
  "2010_zima_B__66": {"B":"Oblik 'djelili' je pogrešan jer ijekavski refleks daje 'dijelili'."},
  "2010_zima_B__67": {"B":"Odvojeno pisanje 'ne zadovoljstva' nije ispravno jer se 'ne-' s imenicom piše spojeno."},
  "2010_zima_B__68": {"B":"Oblik 'civilizacie' nije ispravan jer izostaje 'j' ispred 'e'."},
  "2010_zima_B__69": {"A":"Oblik 'svjeta' je pogrešan jer ijekavski dugi refleks daje 'svijeta'."},
  "2010_zima_B__70": {"B":"Sastavljeno 'uime' nije ispravno jer se prijedložni izraz 'u ime' piše odvojeno."},
  "2010_zima_B__71": {"A":"Oblik 'iracijonalnih' s 'j' nije standardan jer je riječ o latinizmu bez 'j'."},
  "2010_zima_B__72": {"A":"Oblik 'občinjeni' je pogrešan jer se 'b' ispred 'č' jednači u 'p': 'opčinjen'."},
  "2010_zima_B__73": {"A":"Oblik 'svjest' je pogrešan jer ijekavski refleks daje 'svijest'."},
  "2010_zima_B__74": {"B":"Veliko početno slovo 'Simbolizam' nije ispravno jer se nazivi pokreta pišu malim slovom."},

  // 2011_jesen_A
  "2011_jesen_A__1": {"B":"Epika podrazumijeva pripovjednu radnju i fabulu, a polazni tekst nema narativnoga zbivanja, već lirskoga subjekta i slobodan stih.","C":"Drama je namijenjena izvedbi i gradi se na dijalogu i didaskalijama, čega u ovoj pjesmi nema."},
  "2011_jesen_A__2": {"B":"'Brojiti zvijezde' označava bezopasnu razonodu kojoj se majstor preusmjerava, a ne sam prestanak stvaranja.","C":"'Saditi luk' predstavlja običan, neopasan posao kojim se zamjenjuje stvaralaštvo, a ne metaforu njegova gašenja.","D":"'Baviti se proročanstvima' upravo je opasno umjetničko djelovanje koje se zabranjuje, a ne slika prestanka stvaranja."},
  "2011_jesen_A__3": {"A":"Vrtlarski i zvjezdoznanstveni poslovi tek su ono što se majstoru savjetuje kao zamjena, a ne ono što on doista jest.","B":"Klaun je u pjesmi suprotnost majstoru jer glumi osjećaje, a 'budi razuman' ironičan je savjet, a ne opis majstora.","C":"Sanjarstvo i buntovništvo nisu temeljne odrednice lika; naglašeno je čuđenje i zanatska obveza istinitosti."},
  "2011_jesen_A__4": {"B":"Smijanje i kad mu nije do toga obilježje je klauna, a ne majstorova umijeća.","C":"Život u iluziji i bijeg u sjećanja ono je čemu se majstora nagovara da pobjegne, a ne zahtjev njegova umijeća.","D":"Stih kaže da se 'nikome ništa ne oprašta', pa opraštanje nije majstorova zadaća."},
  "2011_jesen_A__5": {"B":"Mladost se spominje tek kao prošlost za kojom se uzdiše, a nije središnja tema pjesme.","C":"Ugodan život predstavljen je kao bijeg od stvaralaštva, a ne kao tema kojoj pjesma teži.","D":"Naglasak nije na otuđenome svijetu, nego na položaju pjesnika u nesnošljivu, diktatorskom vremenu."},
  "2011_jesen_A__6": {"A":"Ironija znači reći suprotno od onoga što se misli, a 'uzmeš pero' nema takva izokrenuta značenja.","B":"Oksimoron spaja proturječne pojmove, čega ovdje nema.","C":"Simbol bi 'pero' bio kad bi upućivao na apstraktnu ideju, no ovdje konkretno sredstvo zamjenjuje radnju pisanja (dio za cjelinu)."},
  "2011_jesen_A__7": {"A":"Pejzažna tematika opisuje prirodu i krajolik, čega u tekstu nema.","C":"Socijalna tematika bavi se društvenom nepravdom i staležima, a ovdje je naglasak na promišljanju pjesnikove uloge.","D":"Ljubavna tematika izostaje jer pjesma ne govori o ljubavnom osjećaju."},
  "2011_jesen_A__8": {"B":"Klaunovi u pjesmi ne samo da zabavljaju nego prikrivaju istinu glumeći osjećaje, pa puko zabavljanje nije bit.","C":"Tragično gledanje života suprotno je klaunovu hinjenju nehaja i smijeha.","D":"Klaunovi ne gledaju život optimistično, nego glume vedrinu prikrivajući stvarnost."},
  "2011_jesen_A__9": {"B":"Akuzativ bi odgovarao na pitanje koga/što, dok je 'im' ovdje korist/primatelj radnje (kome plač razara lice).","C":"Lokativ uvijek dolazi uz prijedlog, a 'im' je bez prijedloga.","D":"Instrumental odgovara na pitanje s kime/čime, što ne odgovara funkciji oblika 'im'."},
  "2011_jesen_A__10": {"A":"Balzac u svojoj Ljudskoj komediji ne završava poznatom uputom o obrađivanju vrta.","B":"Cervantes je autor Don Quijotea, koji ne završava tom mišlju.","C":"Dante zaključuje Božanstvenu komediju vizijom Boga, a ne savjetom o vrtu."},
  "2011_jesen_A__11": {"A":"Kranjčević je obilježen buntom, prometejstvom i socijalnom notom, a ne motivom čuđenja.","B":"Matoš je vezan uz pejzaž i impresionizam, a ne uz motiv pjesnika kao čuđenja u svijetu.","D":"Tadijanović njeguje motive djetinjstva i zavičaja, a ne čuđenja po uzoru na Šimića."},
  "2011_jesen_A__12": {"A":"Nominativ je padež subjekta i odgovara na pitanje tko/što, dok je 'Majstore' dozivanje.","B":"Dativ odgovara na pitanje kome/čemu, što nije funkcija ovoga oblika.","C":"Akuzativ odgovara na pitanje koga/što, dok ovdje riječ služi za izravno obraćanje."},
  "2011_jesen_A__13": {"B":"Inverzija je obrnut red riječi, a zarezi u stihu odvajaju usporedne članove, ne označavaju premetanje.","C":"Suprotnost bi zahtijevala suprotne sadržaje (npr. uz 'ali'), a tu su istovrsni imperativi.","D":"Vokativnost bi značila da zarez odvaja doziv, no ovdje nema vokativa nego niza zapovijedi."},
  "2011_jesen_A__14": {"A":"Prezent iskazuje sadašnju radnju ('gasiš'), a 'ugasi' je zapovijed.","C":"Infinitiv bi glasio 'ugasiti' i ne izriče zapovijed.","D":"Aorist je prošlo svršeno vrijeme ('ugasih'), a ovdje je riječ o zapovijedi."},
  "2011_jesen_A__15": {"A":"Romantizam je razdoblje 19. st., a Mihalić stvara u drugoj polovici 20. st.","B":"Realizam pripada drugoj polovici 19. st., znatno prije Mihalićeva djelovanja.","C":"Hrvatska moderna traje na prijelazu 19. i 20. st., dok Mihalić pripada poslijeratnoj generaciji."},
  "2011_jesen_A__16": {"A":"Sinonimi imaju različit oblik, a isto značenje; ovdje je oblik isti, a značenja različita.","B":"Antonimi imaju suprotna značenja, a 'pero' i 'Pero' nisu suprotnosti.","D":"Hiperonimija je odnos nadređenoga i podređenoga pojma, što ne vrijedi za ova dva leksema."},
  "2011_jesen_A__17": {"A":"Dekameron nije zbirka pisama, nego zbirka novela s okvirnom pričom.","B":"Nije zbirka bajki jer su mu priče realistične i svjetovne, a ne čudesne.","C":"Nije ciklus viteških romana, već kratkih proznih priča (novela)."},
  "2011_jesen_A__18": {"A":"'Sretna ljubav' nije značenje naslova; on se odnosi na vremenski okvir pripovijedanja.","C":"'Sto zgoda' odnosilo bi se na broj novela, no naslov se tvori od riječi za deset i dan.","D":"'Ispovijest duše' nema veze s grčkim sastavnicama deka i hemeron."},
  "2011_jesen_A__19": {"B":"Epilog je završni dio djela, a uvod je na početku.","C":"Invokacija je zaziv muze na početku epa, a ne pripovjedni okvir.","D":"Epizoda je sporedni dio radnje unutar cjeline, a uvod je okvirna struktura cijeloga djela."},
  "2011_jesen_A__20": {"A":"Monolog je govor jednoga lika u drami, a ovdje pripovjedač pripovijeda u prozi.","C":"Retardacija je usporavanje radnje, a u ulomku se radnja iznosi pripovijedanjem.","D":"Retrospekcija je vraćanje u prošlost radnje, što nije temeljni postupak ovoga uvoda."},
  "2011_jesen_A__21": {"A":"Tekst ne tvrdi da nitko ne voli početke, nego da je sam sadržaj teško podnošljiv.","B":"Nije riječ o izmišljenim jezovitim pričama, nego o stvarnom povijesnom događaju.","D":"Uvod nije nerazumljiv; težak je zbog tragične teme kuge, a ne zbog stila."},
  "2011_jesen_A__22": {"A":"Personifikacija pridaje neživomu ljudske osobine, čega u ovoj usporedbi nema.","B":"Hiperbola je pretjerivanje, a ovdje se jedan pojam uspoređuje s drugim.","C":"Oksimoron spaja proturječne pojmove, dok je rečenica izrazita usporedba (uvod kao uspon na planinu)."},
  "2011_jesen_A__23": {"B":"Neukost puka nije ono što ga brine; obraća se baš obrazovanim, osjetljivim čitateljicama.","C":"Strah od kuge tema je sadržaja, a ne ono što ga zabrinjava u prvoj rečenici (učinak na čitateljice).","D":"Osobna popularnost nigdje se ne spominje kao njegova briga."},
  "2011_jesen_A__24": {"A":"Rečenica ne govori o slavlju Firentinaca, nego o smjeni teškoga i ugodnoga štiva.","C":"Nije riječ o rajskoj nagradi za čestit život, nego o čitateljskom užitku nakon teškoga uvoda.","D":"Nema poruke o paklenim mukama zbog raskalašenosti; misao je o redoslijedu muke i naslade u čitanju."},
  "2011_jesen_A__25": {"A":"Razlog nije puki običaj pisanja uvoda, nego nužnost objašnjenja povoda radnji.","B":"Uvod ne krije zaplet, nego daje okolnost (kugu) koja pokreće okupljanje i pripovijedanje.","C":"Cilj nije tek ugoditi gospama kratkoćom, nego objasniti zašto je do svega došlo."},
  "2011_jesen_A__26": {"A":"Pripovjedači nisu kraljevi dvorjani, nego skupina mladih Firentinaca.","C":"Nisu putujući glumci, nego sedmero djevojaka i trojica mladića.","D":"Trubaduri i golijardi srednjovjekovni su pjesnici, a ne pripovjedači Dekamerona."},
  "2011_jesen_A__27": {"B":"Muka je samo polazna, teža faza uspona, a cjelokupni se stvaralački čin uspoređuje s putovanjem.","C":"Kuga je sadržaj užasnoga početka, a ne ono s čime se uspoređuje sam stvaralački čin.","D":"Veselje je tek konačni ishod (ugodna dolina), a ne usporedba za cijeli proces stvaranja."},
  "2011_jesen_A__28": {"A":"Sinonimija pretpostavlja istoznačnost, a 'nevolja' i 'veselje' nisu istoznačnice.","B":"Homonimija je istozvučnost različitih značenja, a ove riječi nisu istoga oblika."},
  "2011_jesen_A__29": {"A":"Latinski je jezik učene književnosti, no Boccaccio piše narodnim jezikom.","B":"Francuski nije jezik Dekamerona; djelo je nastalo u Firenci.","D":"Grčki nije jezik djela; samo je naslov grčkoga podrijetla."},
  "2011_jesen_A__30": {"A":"Patnje mladoga Werthera (Goethe) epistolarni su roman, a ne zbirka novela.","C":"U potrazi za izgubljenim vremenom (Proust) opsežan je roman, a ne zbirka novela.","D":"Planine (Petar Zoranić) pastoralno-alegorijski su roman, a ne zbirka novela."},
  "2011_jesen_A__31": {"A":"Cervantes i Shakespeare renesansni su pisci, ali ne čine talijanski predrenesansni trolist.","B":"Ovidije i Vergilije rimski su antički pjesnici, a ne predstavnici predrenesanse.","C":"Tasso i Ariosto talijanski su renesansni epici, a ne pripadnici predrenesansnoga trolista."},
  "2011_jesen_A__32": {"A":"Ante Kovačić autor je romana U registraturi, a ne Posljednjih Stipančića.","B":"Josip Kozarac poznat je po Mrtvim kapitalima i Teni, ne po ovom romanu.","C":"Milan Begović pisac je djela poput Giga Barićeve, a ne Posljednjih Stipančića."},
  "2011_jesen_A__33": {"A":"Klasicizam pripada 17.–18. st. i drugačijoj poetici, a Novak je realist.","B":"Romantizam prethodi realizmu i naglašava osjećaje, dok Novak gradi društvenu analizu.","D":"Modernizam dolazi nakon realizma, a ovaj roman pripada realističkomu razdoblju."},
  "2011_jesen_A__34": {"A":"Prva polovina 18. st. prerana je; roman prikazuje propadanje obitelji u 19. st.","C":"Prva desetljeća 20. st. prekasna su za radnju smještenu u 19. st.","D":"Drugi svjetski rat vremenski je posve izvan okvira ovoga romana."},
  "2011_jesen_A__35": {"A":"Poredba bi tražila izrijekom izrečenu usporedbu (kao), a ovdje se značenje prenosi izravno.","B":"Onomatopeja oponaša zvukove, čega u izrazu 'gutala roman' nema.","D":"Personifikacija pridaje neživomu ljudske osobine, a ovdje se ljudska radnja (gutanje) prenosi na čitanje."},
  "2011_jesen_A__36": {"A":"Stipančić obrazovanje žene ne cijeni kao vrijednost po sebi, nego radi ugleda.","B":"Tekst ne pokazuje da želi obnoviti vlastito znanje jezika.","D":"Motiv dobre udaje nije iskazan; naglasak je na strahu od sramote pred društvom."},
  "2011_jesen_A__37": {"A":"Rečenica pokazuje upravo nedostatak vlastita stava, a ne sigurnost u sebe.","B":"Valpurga ne manipulira mužem, nego mu se bezuvjetno pokorava.","C":"Ne radi se o nezainteresiranosti, nego o pasivnom pristajanju uz mužev sud."},
  "2011_jesen_A__38": {"A":"Stipančić ne ističe ulogu supruge i majke, nego obrazovanje radi ugađanja društvu.","B":"Ravnopravnost s muškarcima posve je suprotna njegovu shvaćanju ženina položaja.","C":"Neovisnost žene njemu nije cilj; obrazovanje shvaća kao sredstvo da žena ugodi mužu."},
  "2011_jesen_A__39": {"A":"Poznavanje jezika Stipančić upravo traži kao nužno, pa to ne vidi kao opasnost.","C":"Majčin utjecaj nije naveden kao opasnost za odgoj.","D":"Druženje s vršnjakinjama nije mu po volji, ali glavnu opasnost vidi u čitanju romana."},
  "2011_jesen_A__40": {"A":"Razlog nije da ima pametnijega posla, nego strah od nestvarnih predodžbi.","C":"Ne tvrdi da je samo povijest učiteljica života, nego da romani bude lažne ideale.","D":"Ne kaže da je beletristika samo za neobrazovane; boji se da budi želje za nestvarnim."},
  "2011_jesen_A__41": {"B":"Lucija se nikomu ne osvećuje, nego trpi nametnutu joj sudbinu.","C":"Nije zavodnica; prikazana je kao stidljiva i potisnuta djevojka.","D":"Nije spletkarica; ne kuje spletke, nego pasivno podnosi obiteljske prilike."},
  "2011_jesen_A__42": {"A":"'Nju sirotu' izražava sažaljenje običnim riječima, ali nije ustaljeni frazem za suosjećanje.","C":"Glađenje po licu konkretna je gesta nježnosti, a ne frazem.","D":"'Bila u volji' znači sviđati se / biti po volji, a ne biti suosjećajan."},
  "2011_jesen_A__43": {"A":"Vokativnost bi tražila doziv unutar zareza, no tu je umetnuta usporedba, a ne vokativ.","B":"Suprotnost bi zahtijevala suprotstavljene sadržaje, a ovdje se odvaja umetnuti dio.","C":"Inverzija je obrnut red riječi, a zarezi ovdje odvajaju umetnutu cjelinu."},
  "2011_jesen_A__44": {"A":"'Smjerno' znači skromno, ponizno, što nije značenje priloga 'okretno'.","B":"'Zainteresirano' upućuje na pažnju, a ne na vještinu izvedbe.","C":"'Sigurno' znači bez sumnje ili pouzdano, dok 'okretno' znači spretno, vješto."},
  "2011_jesen_A__45": {"B":"'Skraćivati' je parnjak glagola 'skratiti', a ne 'uskratiti', i znači činiti kraćim.","C":"'Skratiti' je svršeni glagol i nema prefiks us-, pa nije parnjak glagola 'uskratiti'.","D":"'Pokraćivati' nije standardni vidski parnjak glagola 'uskratiti'."},
  "2011_jesen_A__46": {"A":"Pomodnice su pomodne, prolazne riječi, dok je 'uzgoj' obnovljena starija riječ.","B":"Arhaizam je zastarjela riječ koja se više ne rabi, a 'uzgoj' je vraćena u uporabu.","C":"Neologizam je posve nova riječ, a 'uzgoj' je stara riječ vraćena u život."},
  "2011_jesen_A__47": {"A":"'Bježeći' označuje kretanje u bijegu, a ne tajnost radnje.","B":"'Strahujući' izriče osjećaj straha, a ne način skrivenoga čitanja.","C":"'Ozbiljnije' nema veze s tajnošću koju nosi prilog 'krišom'."},
  "2011_jesen_A__48": {"A":"Dvije surečenice premalo je jer rečenica sadržava niz povezanih i zavisnih dijelova.","B":"Tri surečenice ne obuhvaćaju sve predikate u rečenici.","C":"Četiri surečenice i dalje izostavljaju jednu predikatnu cjelinu; ukupno ih je pet."},
  "2011_jesen_A__49": {"A":"Infinitiv bi glasio 'stidjeti se' i ne iskazuje vršenje radnje u prošlosti.","B":"Prezent iskazuje sadašnju radnju ('stidi se'), a ovdje je prošlo vrijeme.","D":"Kondicional prvi tvori se s 'bi' + glagolski pridjev radni, a tu nema čestice 'bi'."},
  "2011_jesen_A__50": {"B":"Leone se ne odriče nasljedstva u toj izjavi, nego ističe pripadnost majčinu rodu.","C":"Nema osjećaja srama zbog bogatstva, nego ponosa na aristokratsko podrijetlo.","D":"Iako je odnos s ocem napet, ta replika izražava ponos na podrijetlo, a ne izravnu netrpeljivost."},
  "2011_jesen_A__51": {"B":"Barunica nije Leoneova prijateljica, nego Glembayeva supruga.","C":"Leoneova majka pripada rodu Danielli i nije ta barunica.","D":"Riječ je o zakonitoj ženi, a ne o ljubavnici."},
  "2011_jesen_A__52": {"A":"Grižnja savjesti nije naznačena; didaskalije upućuju na gorčinu i rezignaciju.","C":"Strah nije ton replike; Glembay govori gorko i pomireno sa sudbinom.","D":"Srdžba je naglija od onoga što tekst pokazuje; prevladava gorka rezignacija."},
  "2011_jesen_A__53": {"A":"Odnos nije prijateljski, nego pun napetosti i suprotstavljanja.","B":"Nema uzajamne podrške; otac i sin u stalnu su sukobu.","D":"Iako su suprotstavljeni, riječ je prije svega o nerazumijevanju u svjetonazoru, a ne o pukom suparništvu."},
  "2011_jesen_A__54": {"A":"Ne radi se o priznanju manje vrijednosti, nego o ironičnu isticanju vlastita uspona iz niska položaja.","C":"Ne pokazuje gubitak vjere u sebe, nego ponosno (ironično) ističe svoj uspjeh.","D":"Ne izriče žalost što nije Leoneov otac, nego naglašava svoj uspon usprkos podrijetlu."},
  "2011_jesen_A__55": {"A":"Općejezični sinonimi imali bi isto značenje u svakom kontekstu, a ova su prezimena suprotstavljena.","B":"Kontekstualni sinonimi značili bi isto u danom tekstu, no ovdje su značenja oprečna.","C":"Općejezični antonimi suprotni su neovisno o kontekstu, a ova prezimena postaju suprotna tek u ovom tekstu."},
  "2011_jesen_A__56": {"A":"Glembay ne traži poricanje vijesti o propasti tvrtke, nego optužbe o ženi.","B":"Nije riječ o poricanju krivnje za majčinu smrt.","C":"Podatak o podrijetlu nije ono što treba poreći; juridičke posljedice tiču se barunice."},
  "2011_jesen_A__57": {"A":"Ton nije sentimentalan; nema raznježenosti, nego prikrivene poruge.","C":"Patetika bi značila uzvišenu ganutost, a ovdje je riječ o ironiji.","D":"Ushićenja nema; Glembay prividnom pohvalom zapravo ismijava."},
  "2011_jesen_A__58": {"B":"Leone se ne bavi glazbom, nego slikarstvom.","C":"Leone nije književnik nego slikar.","D":"Leone nije novinar; po zanimanju je slikar."},
  "2011_jesen_A__59": {"A":"Prva polovina 19. st. predaleko je u prošlosti za Krležino djelo.","B":"Kraj 19. st. prerano je; djelo je objavljeno 1928.","D":"Kraj 20. st. prekasan je; drama je nastala u međuratnom razdoblju."},
  "2011_jesen_A__60": {"A":"Vučjak i Galicija Krležine su drame, ali ne pripadaju glembajevskome ciklusu.","B":"Kraljevo i Legenda rane su Krležine drame izvan glembajevske trilogije.","D":"Aretej i Michelangelo Buonarotti nisu dio glembajevske trilogije."},
  "2011_jesen_A__61": {"A":"Prolog je uvodni govor pred radnju, a ovdje je riječ o uputama za izvedbu.","B":"Epilog je završni dodatak, dok kosi slog daje scenske napomene.","D":"Replika je izgovoreni tekst lika, a kosim su slovima upravo izdvojene upute (ne govor lika)."},
  "2011_jesen_A__62": {"A":"Genitiv odgovara na pitanje koga/čega, a ovdje je riječ o mjesnoj/stanju odredbi uz prijedlog 'na'.","B":"Dativ odgovara na pitanje kome/čemu, što nije funkcija izraza 'na odlasku'.","C":"Uz prijedlog 'na' u značenju mirovanja/stanja dolazi lokativ, a ne akuzativ."},
  "2011_jesen_A__63": {"A":"Pluskvamperfekt tvori se od 'bijah/bio sam' + pridjev radni, a ne od čestice 'bi'.","C":"Futur drugi tvori se od 'budem' + pridjev radni, čega ovdje nema.","D":"Kondicional drugi tvori se od 'bio bih' + pridjev radni, a ovdje je samo 'bi + htio'."},
  "2011_jesen_A__64": {"A":"Dvotočje ne uvodi niz istovrsnih članova (nabrajanje), nego pojašnjenje prethodne tvrdnje.","B":"Ne uvodi se tuđi (citirani) govor, nego se objašnjava vlastita misao.","D":"Dvotočje ne služi za naglašavanje osjećaja, nego za objašnjenje rečenoga ('ja znam')."},
  "2011_jesen_A__65": {"A":"'Znanstveni' se odnosi na znanost općenito, a 'juridički' usko na pravo.","C":"'Napadački' znači agresivan, što nije značenje riječi 'juridički'.","D":"'Pomirbeni' znači koji teži pomirenju, a ne pravni."},
  "2011_jesen_A__66": {"B":"Jesenjin pripada imažinizmu (D), a ne ekspresionizmu (E), pa pridruživanje 3E nije točno.","C":"Breton je utemeljitelj nadrealizma (C), a ne ekspresionizma (E), pa 1E nije točno.","D":"Marinetti pripada futurizmu (B), a ne dadaizmu (A), i Tzara dadaizmu (A), pa zamjena 2A i 4B nije točna."},
  "2011_jesen_A__67": {"B":"'Jezera' je opća imenica u nazivu pa se piše malim slovom, a ne 'Jezera'.","C":"Prvi član višerječnoga imena nacionalnoga parka piše se velikim slovom, pa 'plitvička' nije ispravno.","D":"'Plitvice' nije službeni naziv nacionalnoga parka."},
  "2011_jesen_A__68": {"A":"Uz redni broj naziv mjeseca dolazi u genitivu ('travnja'), a ne u nominativu ('travanj').","C":"Između mjeseca i godine u ovakvu nizu ne piše se zarez.","D":"Datum se u ovoj rečenici piše brojkom s točkom, a ne riječima ('osmog')."},
  "2011_jesen_A__69": {"B":"'Svijetskom' je pogrešno jer pridjev od 'svijet' ima kratki jat (je), a ne dugi (ije).","C":"'Svjetljom' nije riječ hrvatskoga standarda.","D":"'Svjetovnom' znači ovozemaljski/laički, a ne 'svjetski'."},
  "2011_jesen_A__70": {"B":"'Šesnajest' je razgovorni, nestandardni oblik.","C":"'Šesnajs' je skraćeni razgovorni oblik, neprihvatljiv u standardu.","D":"'Šesnaeste' je pogrešan padežni/redni oblik za ovaj kontekst."},
  "2011_jesen_A__71": {"B":"'Preljevaju' je pogrešno jer glagol 'prelijevati' ima dugi jat (ije).","C":"'Prelijevu' nije pravilan glagolski oblik.","D":"Oblik je istovjetan točnomu 'prelijevaju', pa kao zaseban odgovor nije ispravan izbor."},
  "2011_jesen_A__72": {"B":"'prošćansko' malim slovom nije točno jer je riječ o vlastitu imenu jezera.","C":"'Proščansko' je pogrešno napisano (treba šć, a ne šč).","D":"'Jezero' je opća imenica i piše se malim slovom, pa 'prošćansko Jezero' nije točno."},
  "2011_jesen_A__73": {"A":"'Specialitetima' je pogrešno jer hrvatski standard traži 'specijalitetima'.","C":"'Specijalistima' znači stručnjaci, a ne posebna jela.","D":"'Specifitetima' nije postojeća riječ hrvatskoga standarda."},
  "2011_jesen_A__74": {"A":"'Endemi' velikim slovom nije točno jer je riječ o općoj imenici, a ne vlastitu imenu.","C":"'Endemiti' nije pravilan oblik za organizme; pravilno je 'endemi'.","D":"'Endeme' je pogrešan padežni oblik za ovaj kontekst (treba nominativ množine 'endemi')."},
  "2011_jesen_A__75": {"B":"'Stodvadesetšest' pogrešno je sastavljeno; složeni se brojevi pišu odvojeno.","C":"U ovakvoj se rečenici broj piše riječima, a ne brojkom '126'.","D":"Brojevi se ne pišu sa spojnicama, pa 'sto-dvadeset-šest' nije ispravno."},
  "2011_jesen_A__76": {"B":"'Pješaćenje' je pogrešno jer se glagolska imenica tvori s č ('pješačiti' → 'pješačenje').","C":"'Pješanje' nije postojeća riječ hrvatskoga standarda.","D":"'Pješakovanje' nije standardni oblik za tu radnju."},

  // 2011_jesen_B
  "2011_jesen_B__1": {"B":"Epika pripovijeda događaje i ima fabulu, a Vidrićeva Pjeza tek slika ugođaj pejzaža bez radnje.","C":"Drama je namijenjena izvođenju i gradi se dijalogom i didaskalijama, čega u ovoj pjesmi nema."},
  "2011_jesen_B__2": {"B":"Misaona lirika promišlja apstraktne ideje, a ovdje se samo opisuje konkretan prizor prirode.","C":"Socijalna tematika progovara o društvenim nepravdama, čega u opisu ljetnoga pejzaža nema.","D":"Duhovno-religiozna tematika obrađuje vjeru i Boga, a tekst se bavi isključivo prirodom."},
  "2011_jesen_B__3": {"A":"Auditivni motivi postoje ('zuje pčele', 'zvono zove'), pa nije točno da ih nema.","B":"Auditivnih je motiva dva, a ne jedan: i zujanje pčela i zvonjava zvona.","D":"U pjesmi su samo dva auditivna motiva, a ne tri."},
  "2011_jesen_B__4": {"A":"Metafora je preneseno značenje na temelju sličnosti, a ovdje je riječ o pridavanju ljudske radnje zvonu.","C":"Onomatopeja oponaša zvukove glasovima, čega u ovim stihovima nema.","D":"Anafora je ponavljanje riječi na početku stihova, a toga ovdje nema."},
  "2011_jesen_B__5": {"B":"Taktilnih (dodirnih) motiva u prvoj strofi nema; prisutni su vizualni i auditivni.","C":"Olfaktivnih (mirisnih) motiva u prvoj strofi nema, a auditivni jest prisutan.","D":"Ni taktilnih ni olfaktivnih motiva u prvoj strofi nema."},
  "2011_jesen_B__6": {"A":"Rima abab značila bi da se prvi stih rimuje s trećim, a 'cvjetovi' i 'stablima' se ne rimuju.","B":"Rima abba traži obgrljeni raspored, a ovdje se rimuju samo drugi i četvrti stih.","D":"Rima aabb znači parnu rimu susjednih stihova, čega ovdje nema."},
  "2011_jesen_B__7": {"A":"'U tr-a-vi' je pogrešno: slog je 'tra-vi', a ne 'tr-a-vi'.","C":"'Pod brije-gom' je pogrešno: ispravno je 'bri-je-gom'.","D":"'A dal-je' je pogrešno: ispravno je 'da-lje'."},
  "2011_jesen_B__8": {"A":"Simbolički izraz nosi skrivena, prenesena značenja, a Pjeza je neposredan opis bez simbola.","B":"Alegorijski izraz cijelu sliku prenosi na drugo značenje, čega ovdje nema.","C":"Izraz nije složen nego jasan i prozračan, sastavljen od jednostavnih slika."},
  "2011_jesen_B__9": {"A":"'Žute' nije imenica nego se odnosi na radnju cvjetova koji se žute.","C":"Iako bi 'žuti' mogli biti pridjev, ovdje 'žute (se)' označava radnju, dakle glagol.","D":"Prilog bi pobliže označavao glagol, a 'žute' je sam predikat (glagol)."},
  "2011_jesen_B__10": {"A":"Infinitiva u pjesmi nema; svi su glagoli u određenom licu.","C":"Aorist je prošlo svršeno vrijeme, a glagoli ovdje izriču sadašnjost.","D":"Imperativ izriče zapovijed, a ovdje nema nijednoga zapovjednog oblika."},
  "2011_jesen_B__11": {"A":"Jaku stanku unutar teksta označuju druga interpunkcijska sredstva, a ne trotočje na samom kraju.","B":"Nizanje dijelova trotočjem označava se unutar nabrajanja, a ne na kraju pjesme.","C":"Izostavljeni dio teksta trotočje označava u citatu, a ovdje je riječ o završetku pjesme."},
  "2011_jesen_B__12": {"A":"'Letjeti' opisuje sam način kretanja, a 'ploviti' ovdje naglašava bešumno, slobodno lutanje nebom.","B":"'Plivati' se odnosi na kretanje vodom, a laste se kreću nebom.","D":"'Skretati' znači mijenjati smjer, a glagol ovdje označava slobodno kruženje, a ne zaokret."},
  "2011_jesen_B__13": {"A":"'U travi se žute cvjetovi' ima uobičajen red riječi, bez stilski obilježene inverzije.","B":"'I nebo se plavi visoko' nema obilježen red riječi.","C":"'Podnevno zvono zove' ima običan slijed atribut-subjekt-predikat, bez inverzije."},
  "2011_jesen_B__14": {"A":"Surečenica je više od dvije: prepoznaju se najmanje četiri predikacije.","B":"Surečenica je četiri, a ne tri.","D":"Pet je previše; u prvoj strofi ima četiri surečenice."},
  "2011_jesen_B__15": {"A":"Nadrealizam slika snove i podsvijest nelogičnim slikama, a Pjeza donosi jasan dojam stvarnoga prizora.","B":"Futurizam veliča brzinu, tehniku i dinamiku, čega u ovom mirnom pejzažu nema.","D":"Ekspresionizam izražava snažan unutarnji nemir i deformaciju, a Pjeza je smiren impresionistički dojam."},
  "2011_jesen_B__16": {"A":"Ivan Mažuranić pripada hrvatskom romantizmu (ilirizmu), znatno prije moderne.","C":"Tin Ujević pripada poslijemodernom naraštaju (20. st.), a ne Vidrićevoj moderni na prijelazu stoljeća.","D":"Jure Kaštelan pripada hrvatskoj poeziji 20. stoljeća (poslije Drugoga svjetskog rata)."},
  "2011_jesen_B__17": {"A":"Antika je razdoblje staroga vijeka, mnogo prije nastanka Don Quijotea (poč. 17. st.).","B":"Srednjovjekovlje prethodi renesansi, a Don Quijote nastaje tek u 17. stoljeću.","D":"Realizam je razdoblje 19. stoljeća, znatno poslije nastanka Don Quijotea."},
  "2011_jesen_B__18": {"A":"Cervantes nije francuski pisac; rođen je i stvarao u Španjolskoj.","B":"Cervantes nije njemački nego španjolski pisac.","D":"Cervantes nije talijanski nego španjolski pisac."},
  "2011_jesen_B__19": {"A":"Da ih svatko može imati, ne bi morao prodati zemlju za njihovu kupnju.","C":"Tekst ne govori o tome tko ih je čitao, nego o tome čime ih je Don Quijote plaćao.","D":"Tekst ne spominje da su knjige bile statusni simbol, nego da ih je skupo plaćao prodajom zemlje."},
  "2011_jesen_B__20": {"B":"Suprotno tvrdnji, Don Quijote je zbog čitanja zaboravio na lov, a nije bio nadahnut za nj.","C":"Zbog čitanja je zapustio imanje, a nije postao bolji domaćin.","D":"U tekstu nema spomena da je vještinu govora naučio iz knjiga."},
  "2011_jesen_B__21": {"A":"Personifikacija pridaje ljudska svojstva neživomu, a ovdje su rečenice izjednačene s biserom.","B":"Hiperbola je pretjerivanje, a ovdje je riječ o prenesenom poistovjećivanju rečenica s biserom.","C":"Poredba bi imala poredbenu riječ ('kao'), a ovdje se rečenice izravno nazivaju biserom."},
  "2011_jesen_B__22": {"A":"Suprotno tvrdnji, Don Quijote nije znao da je izmišljeno, nego je sve držao istinom.","C":"Tekst ne kaže da je shvatio da su priče iste, nego da ih je sve smatrao istinitima.","D":"Don Quijotea nisu privlačili korisni savjeti, nego je u sve vjerovao kao u istinu."},
  "2011_jesen_B__23": {"A":"Smisao nije da je proza za visokoobrazovane, nego da je nitko, čak ni Aristotel, ne bi razumio.","B":"Spomen ustajanja iz groba ironično pokazuje nerazumljivost, a ne sjaj proze.","C":"Tekst ne govori da je pisana po Aristotelovoj teoriji, nego da je ni Aristotel ne bi shvatio."},
  "2011_jesen_B__24": {"A":"Don Quijote ne želi upoznati pisca, nego sam postati vitezom lutalicom.","B":"Ne odlučuje pisati romane, nego živjeti kao njihov junak.","D":"Ne kani dokazivati da živi u najboljem dvorcu, nego krenuti u viteške pothvate."},
  "2011_jesen_B__25": {"A":"Don Quijote ne ostaje vitez; pred kraj se otrijeznio od ludosti.","C":"Don Quijote ne piše roman; on je junak Cervantesove knjige.","D":"Don Quijote se ne opametio radi ženidbe niti se oženio; razbolio se i umro."},
  "2011_jesen_B__26": {"B":"'Kula od karata' nije iz Don Quijotea, nego označava nesiguran, krhki pothvat.","C":"'Knjižni moljac' označava strastvenog čitatelja i nije nastao iz Don Quijotea.","D":"'Trbuhom za kruhom' znači odlazak na rad daleko od doma i nije vezan uz Don Quijotea."},
  "2011_jesen_B__27": {"A":"Donkihotizam ne znači dobro smišljen pothvat, nego upravo uzaludno, besmisleno nastojanje.","C":"Donkihotizam nije puka sklonost ludim idejama, nego borba za nedostižan, uzaludan cilj.","D":"Donkihotizam nije optimistički stav, nego naivno i jalovo zalaganje za nemoguće."},
  "2011_jesen_B__28": {"B":"Razrada je glavni dio radnje, a 'prva novela' ima ulogu okvira.","C":"Invokacija je zaziv muze, što nije funkcija novele u romanu.","D":"Epizoda je sporedni dio radnje, a ovdje je riječ o okvirnoj funkciji."},
  "2011_jesen_B__29": {"A":"Monolog je govor jednoga lika, a ulomak je pripovjedačev opis, a ne lik koji govori sam sebi.","C":"Retardacija je usporavanje radnje umetanjem, a ovdje teče sažeto pripovijedanje.","D":"Retrospekcija je vraćanje u prošlost, a ovdje se događaji iznose redom pripovijedanjem."},
  "2011_jesen_B__30": {"A":"Josip Kozarac autor je djela poput Tene i Mrtvih kapitala, a ne Posljednjih Stipančića.","B":"Slobodan Novak suvremeni je pisac (Mirisi, zlato i tamjan), a ne autor Posljednjih Stipančića.","D":"August Šenoa autor je povijesnih romana (Seljačka buna), a ne Posljednjih Stipančića."},
  "2011_jesen_B__31": {"B":"Naturalizam je radikalniji pravac determinizma, a Vjenceslav Novak pisac je hrvatskoga realizma.","C":"Moderna nastupa nakon Novakove smrti; on stvara u realizmu.","D":"Protorealizam (predrealizam) prethodi realizmu, a Novakov je opus već zreli realizam."},
  "2011_jesen_B__32": {"A":"Filozofska tematika promišlja apstraktne ideje, a roman prikazuje propadanje obitelji u društvu.","B":"Ljubavna tematika nije središnja; djelo prikazuje društveni i obiteljski slom.","C":"Avanturistička tematika počiva na pustolovinama, čega u ovome društvenom romanu nema."},
  "2011_jesen_B__33": {"A":"Kratka priča znatno je sažetija od opsežnog romana s razgranatom radnjom.","B":"Novela je kraća prozna vrsta s jednim obratom, a Posljednji Stipančići opsežan su roman.","D":"Autobiografija pripovijeda piščev vlastiti život, a ovo je izmišljena obiteljska priča."},
  "2011_jesen_B__34": {"A":"Usporedba traži poredbenu riječ ('kao'), čega ovdje nema; uličici se pridaje svojstvo živoga.","B":"Onomatopeja oponaša zvuk, a ovdje se neživoj uličici pridaje obilježje mrtvila.","D":"Simbol bi cijelu uličicu pretvorio u znak druge ideje, a ovdje je riječ o oživljavanju pojma."},
  "2011_jesen_B__35": {"B":"Šamor djece dolazi izdaleka kao pozadina, a Lucijinu je pozornost privukao zvuk koraka.","C":"U ovome dijelu teksta Gertruda još ne ulazi; pažnju privlače koraci na ulici.","D":"Pjesmice se spominju tek poslije; ovdje pozornost privlače koraci."},
  "2011_jesen_B__36": {"A":"Ravnodušnost znači nezainteresiranost, a Lucija turobno i sjetno promatra uličicu.","B":"Uznemirenost je nemir i tjeskoba, a opis pokazuje tihu sjetu, a ne uzbuđenost.","C":"Zabrinutost upućuje na strah od nečega konkretnog, a ovdje prevladava opća turobnost i sjeta."},
  "2011_jesen_B__37": {"B":"Suprotno tvrdnji, Martin nije siguran nego nervozan: crveni se i naklanja nespretno.","C":"Martin nije odvažan nego plašljiv i smeten.","D":"Martin nije zavodljiv nego zastiđen, obara oči kao posramljeno djevojče."},
  "2011_jesen_B__38": {"A":"Martin ne pokazuje odlučne korake, nego nesigurno, zbunjeno ponašanje.","B":"Osjećaje ne odaje odijelom nego zbunjenošću (crvenjenjem i nespretnošću).","D":"Nema zavodničkog pogleda; Martin obara oči i crveni se od zbunjenosti."},
  "2011_jesen_B__39": {"A":"Pitanje 'Što taj hoće?' ne izriče sigurnost, nego nemir i nesvjesni predosjećaj.","B":"Nije riječ o pukom čuđenju, nego o slutnji da slijedi nešto što je u vezi s njom.","D":"Ljutnja nije izražena; rečenica je nesvjesno pitanje koje odaje slutnju."},
  "2011_jesen_B__40": {"A":"Crvenjenje lica izražava zbunjenost i sram, a ne simbol ljubavi.","C":"Napuštanje sjemeništa govori o Martinovoj odanosti, ali nije simbol ljubavi nego činjenica.","D":"Slanje pjesmica jest znak naklonosti, ali nije likovni simbol ljubavi kao prostrijeljeno srce."},
  "2011_jesen_B__41": {"B":"Lucija nije osvetnica; ona je krhka, trpeća žena bez snage za osvetu.","C":"Lucija nije zavodnica; prikazana je kao povučena, nesretna djevojka.","D":"Lucija nije spletkarica; ona je žrtva prilika, a ne osoba koja kuje spletke."},
  "2011_jesen_B__42": {"A":"Načelo vokativnosti odnosi se na odvajanje vokativa, a 'velite' nije vokativ nego umetnuta rečenica.","B":"Načelo suprotnosti odvaja suprotne dijelove (npr. uz 'a', 'nego'), čega ovdje nema.","C":"Inverzija nije pravopisno načelo pisanja zareza, nego red riječi; zarezi su zbog umetanja."},
  "2011_jesen_B__43": {"A":"Izostavljeni tekst bio bi citat s preskočenim dijelom, a ovdje je riječ o uzbuđenom živom govoru.","B":"Prekinuti tekst značio bi nagli prekid, a ovdje govor teče isprekidano kroz cijelu repliku.","D":"Nenavedeni govor značio bi izostavljeno citiranje, a ovdje je govor naveden, ali isprekidan."},
  "2011_jesen_B__44": {"A":"'Nasumice' znači nasreću, bez plana, ali nije suprotno od 'nehotice'.","B":"'Nespremno' znači bez pripreme i nije antonim riječi 'nehotice'.","C":"'Nespretno' znači nevješto i nije suprotno od 'nehotice' (nenamjerno)."},
  "2011_jesen_B__45": {"B":"'Kloniti se' znači izbjegavati i nije vidski parnjak glagola 'nakloniti se'.","C":"'Sklanjati se' znači zaklanjati se i drugi je glagol, a ne vidski parnjak.","D":"'Skloniti se' znači zakloniti se i nije vidski parnjak glagola 'nakloniti se'."},
  "2011_jesen_B__46": {"A":"Lirika izražava osjećaje u stihu, a Gospoda Glembajevi dramski je tekst za izvođenje.","B":"Epika pripovijeda događaje, a Glembajevi su građeni dijalogom i didaskalijama, dakle drama."},
  "2011_jesen_B__47": {"A":"Nije riječ o otvaranju sirotišta, nego o svečanoj proslavi jubileja glembajevske banke.","B":"Majčin pokop nije predmet 'predstave'; riječ je o jubileju tvrtke.","C":"Nije riječ o očevu rođendanu, nego o godišnjici (jubileju) glembajevske banke."},
  "2011_jesen_B__48": {"A":"Beatrice nije očeva druga žena; očeva je supruga barunica Castelli.","B":"Beatrice nije majčina prijateljica, nego osoba bliska Leoneu iz prošlosti.","C":"Beatrice nije bratova udovica, nego Leoneova nekadašnja ljubav/zaručnica."},
  "2011_jesen_B__49": {"A":"Leone ne dolazi s grižnjom savjesti, nego s nostalgijom i čežnjom za domom.","C":"Ne dolazi s ushitom (oduševljenjem), nego s tihom čežnjom i nostalgijom.","D":"Ne dolazi sa srdžbom; ljutnja se javlja tek poslije, a dolazi pun čežnje."},
  "2011_jesen_B__50": {"A":"Odnos nije potpuno prijateljski; replike odaju nerazumijevanje i sukob.","B":"Odnos nije ispunjen podrškom, nego optužbama i nesporazumom.","D":"Odnos nije suparnički u smislu natjecanja, nego prožet dubokim nerazumijevanjem."},
  "2011_jesen_B__51": {"B":"Suprotno tvrdnji, Leone ne kaže da su jedan svijet, nego da su dvije posve različite 'rase'.","C":"Ne tvrdi da su isti u različitostima, nego da su suštinski različiti.","D":"Ne poručuje da je krvno srodstvo presudno, nego da su po naravi potpuno različiti."},
  "2011_jesen_B__52": {"A":"Nisu kontekstualni sinonimi jer riječi u kontekstu znače suprotno, a ne isto.","B":"Nisu pravi sinonimi jer 'Glembajevi' i 'Daniellijevi' nemaju isto značenje.","C":"Nisu općejezični antonimi jer izvan ovog konteksta nisu suprotni; suprotnost stvara kontekst."},
  "2011_jesen_B__53": {"A":"Leone ne razočarava predosjećaj propasti tvrtke, nego spoznaja da je sve ostalo isto.","B":"Razlog razočaranju nije loš doček, nego nepromijenjena trula atmosfera doma.","C":"Tekst ne spominje razbaštinjenje; razočaranje izaziva nepromijenjeno stanje obitelji."},
  "2011_jesen_B__54": {"A":"Personifikacija pridaje ljudska svojstva neživomu, a ovdje se obiteljska situacija prikazuje kazališnim ulogama.","C":"Hiperbola je pretjerivanje, a ovdje je riječ o prenesenom poistovjećivanju s kazališnim ulogama.","D":"Simbol bi bio ustaljeni znak druge ideje, a ovdje je riječ o slikovitom prijenosu (statist/režiser)."},
  "2011_jesen_B__55": {"B":"Leone se ne bavi glazbom, nego slikarstvom.","C":"Leone nije književnik, nego slikar.","D":"Leone nije novinar, nego slikar."},
  "2011_jesen_B__56": {"A":"Grof Axelrode lik je drame U logoru, a ne onaj koji se vraća kući nakon duga izbivanja.","B":"Student Vidović nije Krležin lik koji se vraća kući nakon godina izbivanja.","C":"Bobočka je lik iz Povratka Filipa Latinovicza, ali ona nije ta koja se vraća; vraća se Filip."},
  "2011_jesen_B__57": {"A":"Djelo ne nastaje u prvoj polovini 19. st.; Glembajevi su iz 1928. godine.","B":"Djelo ne nastaje krajem 19. st., nego u 20. stoljeću (1928.).","D":"Djelo ne nastaje krajem 20. st., nego u njegovoj prvoj polovini (1928.)."},
  "2011_jesen_B__58": {"A":"Vučjak i Kristofor Kolumbo ne pripadaju glembajevskom ciklusu.","B":"Kraljevo i Michelangelo Buonarroti nisu dio glembajevske trilogije.","D":"Aretej te Adam i Eva nisu dio glembajevske trilogije."},
  "2011_jesen_B__59": {"A":"Genitiv bi odgovarao na pitanje 'koga/čega', a 'gostom' je oblik na -om (instrumental).","B":"Dativ bi odgovarao na 'komu/čemu', a 'gostom' je instrumental.","C":"Lokativ uvijek dolazi s prijedlogom, a 'gostom' je beziedlozni instrumental imenskog predikata."},
  "2011_jesen_B__60": {"A":"'Dvaju' je oblik za muški/srednji rod, a 'rasa' je ženskoga roda, pa je ispravno 'dviju'.","C":"'Dvoje' je zbirni broj za osobe različita roda, a ne genitiv broja 'dvije'.","D":"'Dvije rase' je nominativ, a traži se genitivni oblik 'dviju rasa'."},
  "2011_jesen_B__61": {"A":"Dvotočje ne najavljuje nabrajanje jer iza njega ne slijedi niz istovrsnih dijelova.","B":"Ne uvodi tuđe misli (citat), nego Leoneovo vlastito objašnjenje/priznanje.","D":"Funkcija dvotočja nije naglašavanje osjećaja, nego najava objašnjenja onoga što priznaje."},
  "2011_jesen_B__62": {"A":"Riječ nije iz engleskoga, nego njemačkoga jezika, pa nije anglizam.","C":"Riječ ne potječe iz mađarskoga, nego njemačkoga, pa nije hungarizam.","D":"Riječ ne potječe iz turskoga, nego njemačkoga, pa nije turcizam."},
  "2011_jesen_B__63": {"A":"Dvije surečenice premalo je: uz 'doputovao' tu su i 'molim te da uvažiš' te 'da se smatram gostom'.","C":"Četiri je previše; ispravno je tri surečenice.","D":"Pet je previše; rečenica ima tri surečenice."},
  "2011_jesen_B__64": {"A":"'Bolesnoj' i 'neistine' nisu antonimi nego približni sinonimi zadanih riječi.","B":"'Ozdravljujućoj' i 'skrivanja' ne čine antonimski par zadanim riječima.","D":"'Bolničkoj' i 'laganja' nisu antonimi 'nezdrave' i 'laži', nego su značenjski bliski 'laži'."},
  "2011_jesen_B__65": {"A":"Prezent izriče sadašnjost jednim glagolom, a 'nisi imao' je složeni prošli oblik.","C":"Imperativ izriče zapovijed, a 'nisi imao' iznosi prošlu radnju.","D":"Pluskvamperfekt ima dva pomoćna dijela (bijah/bio + pridjev), a ovdje je jednostavni niječni perfekt."},
  "2011_jesen_B__66": {"B":"Pogrešno je '1E': Šimićevo djelo nije Pjesme u tmini (E), nego Preobraženja (F).","C":"Pogrešno je '4E': Kranjčevićevo djelo nije Pjesme u tmini (E), nego Bugarkinje (A).","D":"Pogrešno je '1A, 4D, 5F': Šimić = Preobraženja (F), Kranjčević = Bugarkinje (A), Ujević = Lelek sebra (D)."},
  "2011_jesen_B__67": {"B":"'Mnogo brojnih' nije ispravno; riječ je o jednom složenom pridjevu koji se piše spojeno."},
  "2011_jesen_B__68": {"A":"'pr. kr.' nije ispravno: 'Kr.' je kratica vlastitog imena Krist i piše se velikim slovom."},
  "2011_jesen_B__69": {"A":"'rječnu' nije ispravno: pridjev od 'rijeka' glasi 'riječni', s dugim ije."},
  "2011_jesen_B__70": {"B":"'promjenila' nije ispravno: glagol 'promijeniti' ima dugi refleks ije, dakle 'promijenila'."},
  "2011_jesen_B__71": {"B":"'tekučine' nije ispravno: riječ se piše s 'ć' jer dolazi od 'tekući'."},
  "2011_jesen_B__72": {"B":"Obje su opcije iste; 'svećenici' je jedini pravilan oblik (s 'ć')."},
  "2011_jesen_B__73": {"B":"'SADa' nije ispravno: pri sklonidbi kratice nastavak se odvaja crticom, dakle 'SAD-a'."},
  "2011_jesen_B__74": {"A":"'Bostonskoj' velikim slovom nije ispravno: opisni pridjev od imena mjesta piše se malim slovom."},
  "2011_jesen_B__75": {"B":"Obje su opcije iste; naziv povijesnog događaja piše se velikim početnim slovom ('Bostonska čajanka')."},
  "2011_jesen_B__76": {"A":"Obje su opcije iste; 'vrećicama' je pravilan oblik instrumentala množine."},

  // 2011_ljeto_A
  "2011_ljeto_A__1": {"B":"Epika podrazumijeva pripovijedanje radnje, a polazni je tekst sonet, dakle lirska pjesma.","C":"Drama je namijenjena izvedbi i temelji se na dijalogu, što sonet nije."},
  "2011_ljeto_A__2": {"A":"Gundulić je hrvatski barokni pjesnik epa Osman, a ne začetnik soneta.","B":"Marulić je 'otac hrvatske književnosti' (Judita), no sonetu nije dao slavu.","C":"Ovidije je rimski pjesnik (Metamorfoze) iz antike, davno prije pojave soneta."},
  "2011_ljeto_A__3": {"A":"Tekst ne opisuje prirodu ni krajolik, nego razmišlja o pjesnikovoj sudbini.","C":"Nema teme društvene nepravde ni siromaštva, nego osobne refleksije.","D":"Riječ je o sumnji, slobodi i pjesnikovu pozivu, a ne o ljubavnom doživljaju."},
  "2011_ljeto_A__4": {"A":"Suncokretu se ne pripisuju ljudske osobine, nego se njime prenosi značenje žara.","C":"Nema namjernog pretjerivanja radi pojačavanja dojma.","D":"Nema suprotnosti rečenog i mišljenog, dakle nije ironija."},
  "2011_ljeto_A__5": {"A":"U stihu o tamjanu neviđenog cvijeta nema veznika usporedbe ni dvaju uspoređenih pojmova.","B":"'Lik u mutnoj vodi' je metafora, a ne poredba jer nema veznika 'kao'.","C":"Stih o padu i smrti samo niže radnju, bez ikakve usporedbe."},
  "2011_ljeto_A__6": {"A":"Skromnost se odnosi na nenametljivost, a 'dvojiti' ne znači biti skroman.","B":"Plašljivost je strah, a dvojenje je sumnja, a ne bojazan.","C":"Umišljenost je precjenjivanje sebe, suprotno od onoga koji o svemu dvoji."},
  "2011_ljeto_A__7": {"A":"Stih o gledanju žarom suncokreta iskazuje predanost, a ne životno okružje.","C":"Stih o tome da nikad nije plakao radi sebe govori o nesebičnosti, ne o okružju.","D":"Stih o ostavljanju cvijeta u suzama govori o pjesnikovoj žrtvi, ne o okolini."},
  "2011_ljeto_A__8": {"B":"Tajne želje vezuju se uz cvijet u srcu, a ne uz sliku usamljenog broda.","C":"'Samac brod' označuje usamljenost puta, a ne fizičku daljinu odredišta.","D":"Neuslišana ljubav nije sadržana u slici broda koji sam plovi."},
  "2011_ljeto_A__9": {"B":"Tercine se ne rimuju kao ccd eed jer su krajnji slogovi raspoređeni drukčije.","C":"Katreni nisu obgrljeni (abab) nego obgrljene rime abba, što ovo isključuje.","D":"Katreni nisu ukrštene rime (abab), pa raspored ne odgovara tekstu."},
  "2011_ljeto_A__10": {"A":"Kondicional prvi tvori se s 'bih, bi...' + pridjev radni, čega ovdje nema.","B":"Kondicional drugi traži 'bio bih', a ne pomoćni glagol 'budeš'.","C":"Futur prvi tvori se s 'ću, ćeš...' + infinitiv, a ne s 'budeš' + pridjev radni."},
  "2011_ljeto_A__11": {"A":"'Izdvajati' znači odvajati, što se značenjski ne podudara s 'dvoji'.","C":"'Zdvajati' znači očajavati, a tekst govori o sumnji, ne o očaju.","D":"'Udvojiti' znači podvostručiti, što nema veze sa sumnjanjem."},
  "2011_ljeto_A__12": {"A":"Razdvaja zavisni veznik 'kad' od pripadajućeg predikata, pa nije neutralan red.","C":"Stavljanjem priložne oznake na početak nastaje obilježen, naglašen red riječi.","D":"Premetanjem 'muzama našim' i izmještanjem veznika dobiva se obilježen poredak."},
  "2011_ljeto_A__13": {"A":"Nema niza istovrsnih dijelova, pa zarezi nisu po načelu nabrajanja.","B":"Zarezi ne odvajaju premetnuti dio rečenice, nego doziv.","C":"Nema suprotstavljenih sadržaja koje bi zarez odvajao."},
  "2011_ljeto_A__14": {"A":"Dvije surečenice premalo je jer se zanemaruju eliptične i zavisne surečenice.","B":"Tri surečenice ne obuhvaćaju sve izdvojene predikate u navedenim stihovima.","D":"Pet surečenica precjenjuje broj jer se neke dijelove pogrešno razdvaja."},
  "2011_ljeto_A__15": {"A":"'Dvoji' i 'pjeva' pravilni su prezentski oblici, nisu skraćivani radi metra.","B":"'Hodi' i 'ostavit će' redoviti su oblici, nemaju izostavljenih glasova.","D":"'Brodi' i 'uzmi' pravilni su oblici, nisu izmijenjeni zbog stiha."},
  "2011_ljeto_A__16": {"A":"'Cvrčak' nije Matoševa antologijska pjesma.","B":"'Bele rože' kajkavska je pjesma Frana Galovića, ne Matoša.","C":"'Pejzaž I.' pripada A. B. Šimiću, a ne Matošu."},
  "2011_ljeto_A__17": {"B":"Rimska je književnost mlađa; njezino antičko djelo o lutanju jest Eneida, ne Odiseja.","C":"Babilonsko-asirskoj književnosti pripada Ep o Gilgamešu, a ne Odiseja.","D":"Staroegipatska književnost ne obuhvaća Homerove epove."},
  "2011_ljeto_A__18": {"A":"Hebrejski je jezik starozavjetne književnosti, a ne Homerova.","B":"Latinski je jezik rimske književnosti, primjerice Vergilija, ne Homera.","D":"Talijanski je novovjekovni jezik, davno mlađi od Homerova epa."},
  "2011_ljeto_A__19": {"A":"Didaktički ep poučava (npr. Heziod), dok Odiseja pripovijeda pustolovine.","B":"Religiozna poema slavi vjerske teme, što Odiseja nije.","C":"Nacionalni mit nije književna vrsta, a ep nije svodiv na to."},
  "2011_ljeto_A__20": {"A":"Osveta prijatelja nije Odisejev pokretač; cilj mu je povratak kući.","C":"Utemeljenje Rima cilj je Eneje u Eneidi, ne Odiseja.","D":"Troja je već pala prije Odiseje; spaljivanje Troje nije njegov cilj u epu."},
  "2011_ljeto_A__21": {"B":"Posljednji trojanski junak jest Eneja (Trojanac), a Odisej je Grk.","C":"Odisej je smrtni junak, a ne jedan od olimpskih bogova.","D":"Helenu je oteo Paris, a ne Odisej."},
  "2011_ljeto_A__22": {"A":"Pisac (Homer) ovdje ne pripovijeda; riječ predaje liku.","C":"Intrigant je spletkar, a u ulomku takva lika kao pripovjedača nema.","D":"Pripovjeda glavni lik Odisej, a ne neki sporedni lik."},
  "2011_ljeto_A__23": {"B":"Stihovi ne govore o porazu u ratu, nego o progonu bogova.","C":"Nema spomena iznevjerene žene; Odisej ostaje vjeran.","D":"Stihovi ne spominju odricanje od sina."},
  "2011_ljeto_A__24": {"A":"Stih govori o postojanosti srca prema kući, a ne o izdaji drugova.","B":"Odisej ne obećaje ljubav Kalipsi; baš zato srce ostaje nepromijenjeno.","D":"Stih se ne odnosi na odbijanje božanske pomoći."},
  "2011_ljeto_A__25": {"A":"Prijetvornost (prijevarnost) jest epitet uz Kalipsu, ali u opisu njezina postupanja s gostom prevladava ugošćivanje.","C":"Razočaranje se u ulomku ne iskazuje u njezinu odnosu prema Odiseju.","D":"Neprijateljstva nema; ona ga ugošćuje i pazi."},
  "2011_ljeto_A__26": {"B":"Epitet 'iskričavo' upućuje na blještavilo, a ne na mirnoću mora.","C":"Olujno more bilo bi mračno i uzburkano, suprotno od iskričava sjaja.","D":"Hladnoća nije sadržana u slici mora koje se iskri."},
  "2011_ljeto_A__27": {"A":"Kraljica ne traži priznanje gdje je bio, nego pripovijedanje doživljaja.","B":"Nema spomena zavjeta šutnje koji bi trebalo prekinuti.","C":"Ne traži otkrivanje Kalipsina boravišta, nego cijelu pripovijest."},
  "2011_ljeto_A__28": {"A":"Otmica žene (Helene) povezana je s Parisom, a nije Odisejev doživljaj.","B":"Gubitak kraljevstva nije ono što prethodi njegovim jadima na moru.","C":"Velika ljubav nije događaj koji je izazvao njegove muke."},
  "2011_ljeto_A__29": {"A":"'Gorući grom' opisni je epitet uz tu situaciju, nije ustaljen uz isto ime.","C":"'Iskričavo more' prigodni je epitet, a ne stalni uz junakovo ime.","D":"'Lađene grede' opisni su izraz bez svojstva stalnoga epiteta."},
  "2011_ljeto_A__30": {"A":"Gilgameš pripada babilonsko-asirskoj, a ne grčkoj antici.","B":"Metamorfoze su djelo rimskoga pjesnika Ovidija, ne grčke antike.","D":"Pjesma o Cidu srednjovjekovni je španjolski ep, mnogo mlađi od Odiseje."},
  "2011_ljeto_A__31": {"B":"Vrsta stiha nije zajednička: Odiseja je heksametar, a Hektorović dvostruko rimovani dvanaesterac.","C":"Glavni su likovi različiti, pa ih djela ne povezuju.","D":"Djela su nastala u različitim razdobljima (antika i renesansa)."},
  "2011_ljeto_A__32": {"A":"Likovi se ne grade statičnim opisom izgleda, nego njihovim govorom.","B":"Piščeva komentara kao postupka karakterizacije ovdje nema.","D":"Unutarnjeg monologa nema; riječ je o izmjeni replika dvaju likova."},
  "2011_ljeto_A__33": {"B":"Podrijetlo se spominje tek poslije ('A ipak ste Hrvatica'), pozornost je privukla čitanjem.","C":"Gospođa nije šutljiva, naprotiv živo razgovara.","D":"Skromnost nije ono čime je privukla pozornost sugovornika."},
  "2011_ljeto_A__34": {"B":"Ne nadmeću se znanjem djela, nego razgovaraju o vlastitim sklonostima čitanja.","C":"Ne prepiru se oko običaja; razgovor je opušten i o knjigama.","D":"Ne komentiraju aktualne društvene događaje, nego čitateljske navike."},
  "2011_ljeto_A__35": {"B":"Ton nije napet; razgovor teče šaljivo i bez sukoba.","C":"Sentimentalnosti (ganutljivosti) u razgovoru nema.","D":"Vatren ton značio bi strast i žestinu, a razgovor je lagan i duhovit."},
  "2011_ljeto_A__36": {"A":"'Umujete brzo' pohvala je oštroumnosti, a ne prijekor zbog uobraženosti.","B":"Brzo zaključivanje ovdje znači dosjetljivost, a ne nepromišljenu brzopletost.","D":"Iz iste rečenice slijedi naklonost ('zabavlja me'), ne antipatija."},
  "2011_ljeto_A__37": {"A":"Nabrajanje vrsta štiva pokazuje što čita, ali ne ocjenjuje kvalitetu domaće književnosti.","B":"'Skoro ništa' govori o količini čitanja hrvatskih djela, ne izravno o njihovoj kvaliteti.","D":"'Vazda jedno te isto' upućuje na jednoličnost, ali rečenica o zasićenosti izravnije ocjenjuje kvalitetu."},
  "2011_ljeto_A__38": {"B":"Iskrene zadivljenosti nema; naglasak je na prijekoru što ne čita hrvatski.","C":"Netrpeljivosti nema; ton ostaje blag.","D":"Otvorena simpatija nije ono što ova rečenica iskazuje, nego blagi ukor."},
  "2011_ljeto_A__39": {"A":"Položaj žene nije temeljni problem; gospođa je samo primjer čitateljice.","B":"Odnos naroda prema jeziku nije središte; raspravlja se o čitateljskim navikama.","D":"Političkih sukoba u ulomku nema."},
  "2011_ljeto_A__40": {"A":"'Hrana' nije državna politika ni 'ptica' neobrazovani puk.","C":"Slike se ne odnose na strani kapital ni oponašatelje uzora.","D":"'Hrana' i 'ptica' nisu narodni jezik ni nepoštivanje jezika."},
  "2011_ljeto_A__41": {"A":"Humoreska nije roman u nastavcima, nego kratak duhovit tekst.","B":"Humoreska nije grčka komedija, nego kratka šaljiva proza.","D":"Ljubavni kanconijer zbirka je soneta, a ne humoreska."},
  "2011_ljeto_A__42": {"A":"Zavođenje domišljatošću nije Šenoina namjera, nego poticanje na čitanje domaćega.","C":"Dodvoravanje kritičarima nije svrha; cilj je vrednovanje hrvatske zbilje kao građe.","D":"Ne ističe povijesne junake, nego pokazuje vrijednost suvremene domaće priče."},
  "2011_ljeto_A__43": {"A":"Danicu ilirsku uređivao je Ljudevit Gaj, a ne Šenoa.","B":"'Hrvatsku misao' Šenoa nije uređivao.","C":"Kolo je pokrenuto u doba ilirizma; Šenoa je urednik Vijenca."},
  "2011_ljeto_A__44": {"A":"Antroponimi su osobna imena ljudi, a 'franceski' nije ime.","B":"Eponimi su nazivi nastali od vlastitih imena, što 'franceski' nije.","C":"Egzotizmi označuju strane pojave; ovdje je riječ o zastarjelu domaćem obliku."},
  "2011_ljeto_A__45": {"A":"Pogrešno je iza upitnika unutar navodnika staviti i zarez prije navedbe.","B":"Upitnik mora ostati unutar navodnika, a ne iza zatvaranja navodnika.","D":"Pogrešan je dodatni navodnik na kraju rečenice nakon glagola govorenja."},
  "2011_ljeto_A__46": {"A":"Frazeologija proučava ustaljene sveze riječi, a ne vlastita imena.","C":"Povijest jezika proučava razvoj jezika, a ne vlastita imena.","D":"Dijalektologija proučava narječja, a ne imena."},
  "2011_ljeto_A__47": {"A":"Dvije surečenice premalo je jer su tu četiri predikatna jezgra (i izostavljeni 'je').","B":"Tri surečenice ne obuhvaćaju i poredbeni dio 'brza kao ptica'.","D":"Pet surečenica previše je za navedenu rečenicu."},
  "2011_ljeto_A__48": {"A":"'Privrženost' jest antonim antipatije, ali 'društvene' nije antonim od 'zajedničke'.","B":"'Netrpeljivost' je istoznačnica antipatije, a ne antonim; 'opće' nije parnjak 'zajedničke'.","D":"'Sumnjičavost' nije antonim antipatije, niti je 'dvostruke' parnjak 'zajedničke'."},
  "2011_ljeto_A__49": {"A":"Infinitiv završava na -ti/-ći, a 'dozvolite' je osobni glagolski oblik.","C":"Prezent iskazuje radnju, dok 'dozvolite' izriče zapovijed/molbu.","D":"Imperfekt je prošlo nesvršeno vrijeme, a 'dozvolite' je zapovjedni način."},
  "2011_ljeto_A__50": {"B":"Đuro nije glazbenik ni novinar, nego profesor i (neuspješan) pisac.","C":"Đuro nije pravnik ni slikar.","D":"Đuro nije svećenik ni pjesnik."},
  "2011_ljeto_A__51": {"A":"Grižnje savjesti u ulomku nema; muči ga nedostatak novca.","C":"Posao (profesura) nije izgubio; problem je novčana nestašica.","D":"Nostalgija nije izvor muke; izrijekom je riječ o dugu i praznu džepu."},
  "2011_ljeto_A__52": {"A":"Predosjećaj propasti posla i raspada obitelji nije ono na što tekst upućuje.","B":"O dočeku obitelji u ulomku nema riječi.","C":"Razbaštinjenja od oca tekst ne spominje."},
  "2011_ljeto_A__53": {"B":"Rečenica o velikom gradu pokazuje sanjarenje, ali ne formulira temeljni problem romana.","C":"Tvrdnja o nezanimanju za životne forme dio je karakterizacije, ali ne izriče glavni problem.","D":"Rečenica o troškovima opisuje materijalnu nevolju, a ne bit problema."},
  "2011_ljeto_A__54": {"A":"Bijeg u prirodu nije način kojim je zamišljao rješenje svoje novčane situacije.","B":"O dobitku na lutriji u tekstu nema spomena.","D":"Sam zaključuje da se na stanu i hrani ne da uštedjeti, pa štednja nije rješenje."},
  "2011_ljeto_A__55": {"A":"Rijeke se ne prisjeća kao velikoga grada u kojem je bilo lako.","C":"Zdenci su upravo mala provincija iz koje bježi, a ne veliki grad.","D":"Praga se u ovom kontekstu ne prisjeća."},
  "2011_ljeto_A__56": {"A":"Fantazije nisu građa za roman, nego sredstvo bijega od neugodne sadašnjosti.","B":"Tekst ih ne povezuje s prisutnošću zaručnice.","C":"Maštanje nije usmjereno protiv pijenja."},
  "2011_ljeto_A__57": {"B":"Rečenica o povratku sa šetnja ne opisuje mjesto kao skučenu provinciju.","C":"Opis ljepote mora veliča krajolik, ne ističe zatvorenost provincije.","D":"Rečenica o ekstazi izriče zanos, a ne provincijalnu skučenost."},
  "2011_ljeto_A__58": {"A":"Ženidba nije rasplet; Đuro propada.","B":"Odlazak nije konačan ishod lika, nego smrt.","C":"Đuro se ne prilagođava sredini, nego strada."},
  "2011_ljeto_A__59": {"A":"Optimizam je suprotan Đurinoj sklonosti bijegu i propadanju.","B":"Gramzljivost nije osobina sadržana u naslovu Bijeg.","D":"Strastvenost nije ono što naslov ističe; istaknuta je nemoć djelovanja."},
  "2011_ljeto_A__60": {"A":"Opisivanja krajolika u tom odlomku nema; iznose se junakove misli.","C":"Dijaloga nema jer Đuro razmišlja sam sa sobom.","D":"Retrospekcija je vraćanje u prošlost, a ovdje teče tijek sadašnjih misli."},
  "2011_ljeto_A__61": {"A":"Simbol je trajni nositelj prenesenog značenja, a 'džep' je tu bliskoznačna zamjena za novac.","B":"'Džepu' se ne pripisuju ljudske osobine, pa nije personifikacija.","C":"Nema postupnoga pojačavanja niza pojmova, dakle nije gradacija."},
  "2011_ljeto_A__62": {"A":"Genitiv ne dolazi uz prijedlog 'na' u ovom značenju mjesta/predmeta.","B":"Dativ ne ide uz prijedlog 'na' u ovoj svezi.","C":"Akuzativ uz 'na' označuje smjer, a ovdje je riječ o mjestu uštede, dakle lokativ."},
  "2011_ljeto_A__63": {"A":"Nema doziva, pa zarez nije po načelu vokativnosti.","B":"Nema niza istovrsnih dijelova, pa nije načelo nabrajanja.","D":"Nema suprotnih sadržaja koje bi zarez razdvajao."},
  "2011_ljeto_A__64": {"A":"Kondicional prvi tvori se s 'bi' + pridjev radni, čega ovdje nema.","C":"Futur drugi traži 'budem' + pridjev radni, a ovdje je 'nije ostalo'.","D":"Pluskvamperfekt traži 'bijah/bio sam' + pridjev radni, a ovdje je obična niječna sprega 'nije + ostalo'."},
  "2011_ljeto_A__65": {"A":"Uzbuđenje je preslabo i preopćenito za zanos koji 'ekstaza' označuje.","C":"Veselje je blago raspoloženje, a ekstaza je krajnji zanos.","D":"Sreća je opće stanje, dok ekstaza znači intenzivan zanos, što najbolje pokriva 'ushit'."},
  "2011_ljeto_A__66": {"B":"Krivo pridružuje 1B (Ujević), a 'Dugo u noć' Tadijanovićev je stih.","C":"Krivo pridružuje 3E (Šimić), a 'Kako je teško biti slab' Ujevićev je stih.","D":"Krivo pridružuje 4E (Šimić), a 'I lije na uglu' Cesarićev je stih."},
  "2011_ljeto_A__67": {"B":"U imenu države i druga se riječ piše velikim slovom, pa 'hrvatske' nije točno.","C":"I prva sastavnica imena države piše se velikim slovom, dakle ne 'republike'.","D":"Obje su riječi imena države velikim slovom, pa su obje malim pogrešne."},
  "2011_ljeto_A__68": {"A":"'Trg' je opća imenica u nazivu, pa se ne piše velikim slovom.","C":"Posvojni pridjev 'Strossmayerov' piše se velikim početnim slovom.","D":"Pisanje 'TRG' velikim slovima pravopisno je neopravdano."},
  "2011_ljeto_A__69": {"B":"Iza rednoga broja pisanog rimskim brojkama dolazi točka, koja ovdje nedostaje.","C":"Uz papinsko ime redni se broj piše rimskim brojkama, ne arapskim '23.'.","D":"Slovima ispisan redni broj nije uobičajen zapis uz papinsko ime."},
  "2011_ljeto_A__70": {"B":"Superlativni 'naj-' piše se sastavljeno, pa razdvojeno 'naj ljepša' nije točno.","C":"Crtica između 'naj' i pridjeva pravopisno je pogrešna.","D":"'Najlypša' sadrži nepostojeći oblik 'lypša' i nepravilan je."},
  "2011_ljeto_A__71": {"B":"Naziv pasmine nije vlastito ime, pa se ne piše velikim slovom.","C":"Oblik 'Lipizanci' i pogrešno je napisan i velikim slovom.","D":"'Lipizanci' je pogrešan zapis; pravilno je 'lipicanci'."},
  "2011_ljeto_A__72": {"A":"'Igre' su u nazivu opća imenica, pa se ne pišu velikim slovom.","C":"Prva se sastavnica 'Olimpijske' piše velikim slovom, dakle ne 'olimpijskih'.","D":"Pogrešno je 'olimpijskih' malim, a 'Igara' velikim slovom."},
  "2011_ljeto_A__73": {"A":"'Engleska' je ovdje opisni pridjev (engleska kraljica), pa ide malim slovom.","C":"'Britansku' mijenja smisao i nepotrebno je veliko slovo opisnoga pridjeva.","D":"'Britansku' nije traženi pridjev; tekst govori o engleskoj kraljici."},
  "2011_ljeto_A__74": {"B":"U vlastitu imenu manifestacije i druga se sastavnica piše velikim slovom.","C":"Obje su sastavnice imena manifestacije velikim slovom, pa su obje malim pogrešne.","D":"'đakovački' u imenu manifestacije treba veliko početno slovo."},
  "2011_ljeto_A__75": {"B":"'Cvjećem' je pogrešno jer dugi jat daje 'ije', a ne kratko 'je'.","C":"'Cvećem' je ekavski oblik, nije hrvatski standard.","D":"'Cvijetjem' nije provedeno jotanje ni glasovna promjena, pa je netočno."},
  "2011_ljeto_A__76": {"B":"'Svećanom' s 'ć' je pogrešno; pridjev se tvori s 'č'.","C":"Naglasni znak iznad 'e' nije dio pravopisnoga zapisa riječi.","D":"'Svecanom' bez kvačice na slovu pogrešan je zapis."},

  // 2011_ljeto_B
  "2011_ljeto_B__1": {"B":"Tekst nije epika jer nema razvedene fabule ni pripovjedača koji opisuje slijed događaja; riječ je o kratkoj, dojmovnoj lirskoj baladi.","C":"Tekst nije drama jer nema dijaloga, didaskalija ni scenske radnje namijenjene izvedbi."},
  "2011_ljeto_B__2": {"B":"Shema abab cdcd značila bi naizmjeničnu rimu u kojoj se rimuju i prvi i treći stih, no lampa i plota se ne rimuju.","C":"Shema abba cddc označavala bi obgrljenu rimu, koje u ovim strofama nema (drugi i četvrti stih se rimuju, a prvi i treći ne).","D":"Razlikuje se od točnoga samo u drugoj strofi: ulazi i koraka tvore rimu (e...e), pa nije efgf nego defe."},
  "2011_ljeto_B__3": {"A":"Pejzaž (lampa, blato, plot) tek je pozadinski okvir, a ne tema; u središtu je sudbina siromaha.","B":"Misaona (refleksivna) tematika temelji se na promišljanju i apstrakciji, a ovdje je naglasak na konkretnoj socijalnoj sudbini anonimnoga čovjeka.","D":"Ljubavnih motiva u tekstu nema; riječ je o gubitku i bijedi predgrađa, a ne o ljubavnom odnosu."},
  "2011_ljeto_B__4": {"A":"Olfaktivnih (mirisnih) senzacija u prvoj strofi nema; miris (maj) javlja se tek poslije.","C":"Auditivnih (zvukovnih) slika u prvoj strofi nema; slike svjetla, blata i cigli su vidne.","D":"Taktilnih (dodirnih) senzacija u prvoj strofi nema; navedeni motivi pripadaju osjetilu vida."},
  "2011_ljeto_B__5": {"B":"Stihovi o lampi, magli i noći oslikavaju ugođaj i prolaznost, a ne bijedu i siromaštvo.","C":"Stih o petrolejskoj lampi i crvenkastoj svjetlosti vizualna je slika ugođaja, a ne prikaz socijalne nevolje.","D":"Ponavljanje 'nema ga' izražava gubitak i nestanak čovjeka, a ne socijalne (materijalne) motive."},
  "2011_ljeto_B__6": {"B":"Debelo blato dio je opisa bijede, ali se ne ponavlja kao okvirni, povezujući motiv kao lampa.","C":"Stari plot tek je usputan detalj predgrađa, a ne nosivi motiv koji svjedoči o prolaznosti.","D":"Brižno lice sirotinje pojedinačan je motiv druge strofe, a ne temeljni motiv cijele pjesme."},
  "2011_ljeto_B__7": {"A":"Personifikacija pridaje neživomu ljudska svojstva, a ovdje se neizravno govori o smrti čovjeka.","C":"Poredba uspoređuje dva pojma veznikom 'kao', čega u ovom stihu nema.","D":"Ironija podrazumijeva suprotnost rečenoga i mišljenoga, a ovdje je riječ o ublažavanju (smrt umjesto izravna iskaza)."},
  "2011_ljeto_B__8": {"A":"Asonanca i aliteracija su glasovna ponavljanja samoglasnika/suglasnika, a u strofi je riječ o ponavljanju veznika i početka stihova.","B":"Metafora i simbol su prijenosi značenja, a navedena obilježja strofe su sintaktička ponavljanja, ne preneseni smisao.","D":"Epifora je ponavljanje na kraju, a asindeton izostavljanje veznika; ovdje je obrnuto - ponavljanje na početku i nizanje veznika 'I'."},
  "2011_ljeto_B__9": {"A":"Blagoglasnost (eufonija) odnosi se na ugodan zvuk, a ovdje ponavljanje stvara dojam gubitka, ne zvučnu ugodu.","C":"Glagol 'nema' ne mijenja značenje ponavljanjem, nego ga pojačava.","D":"Kontrastiranja nema; nema suprotstavljenih pojmova, već naglašavanja istoga."},
  "2011_ljeto_B__10": {"A":"Iako se strofa doslovno vraća, smisao nije ciklički povratak nego trajni gubitak: čovjeka više nema.","C":"Ponavljanje strofe ima značenjsku, a ne prvenstveno ritmičku ulogu.","D":"Naglasak nije na samim emocijama, nego na poruci o nepovratnosti i prolaznosti života."},
  "2011_ljeto_B__11": {"A":"Naturalistički izraz nije ono što djelo svrstava u baladu; balada se određuje tugaljivošću i tragičnom sudbinom.","C":"Noćni ugođaj je dio atmosfere, ali nije rodovno-vrsna oznaka balade.","D":"Simboličnost je opće obilježje lirike, a ne specifična značajka koja tekst čini baladom."},
  "2011_ljeto_B__12": {"A":"'Li-je' je točno rastavljeno, ali nije ispravan odgovor jer ispit traži posebno označenu riječ (uvijek).","B":"'Svjetl-ost' je pogrešno: granica sloga je svje-tlost / svjet-lost, suglasnički skup ne ostaje uz prvi slog ovako.","D":"'Dv-ije' je pogrešno: slog ne može počinjati ovako prelomljen, pravilno je dvi-je."},
  "2011_ljeto_B__13": {"A":"Prvi stih ima 11 slogova (jedanaesterac), ne 12, a drugi 9 (deveterac), ne 10.","B":"Drugi stih nema 12 slogova nego 9; nije dvanaesterac.","C":"Prvi stih ima 11 slogova (jedanaesterac), a ne 10 (deseterac)."},
  "2011_ljeto_B__14": {"A":"Nabrajanja nema; zarez ne odvaja istovrsne članove u nizu, nego dva suprotstavljena iskaza.","B":"Inverzije nema; nije riječ o premetnutom redu riječi unutar rečenice.","D":"Vokativnosti nema; ne radi se o izdvajanju dozivanog, nego o suprotnosti uvedenoj veznikom 'a'."},
  "2011_ljeto_B__15": {"A":"Dvije surečenice bilo bi premalo; u strofi ima više predikata (ulazi, su, žure).","B":"Tri surečenice nije dovoljno jer strofa sadržava četiri predikacije.","D":"Pet surečenica je previše; predikata u strofi je četiri, ne pet."},
  "2011_ljeto_B__16": {"A":"Pravopisna norma tiče se zapisa (slova, znakovi), a 'moro' je izmijenjen sam oblik riječi, ne način pisanja.","C":"Sintaktička norma odnosi se na ustroj rečenice, a ovdje je promijenjen oblik jedne riječi (glagolski pridjev).","D":"Fonološka norma odnosi se na glasove i glasovne promjene, a ovdje je posrijedi krnji morfološki oblik, ne fonološka pojava."},
  "2011_ljeto_B__17": {"A":"Ožujak je hrvatski naziv za treći mjesec (ožujak = mart), a 'maj' je peti mjesec.","B":"Travanj je hrvatski naziv za četvrti mjesec (travanj = april), a ne za peti.","D":"Lipanj je hrvatski naziv za šesti mjesec (lipanj = juni), a 'maj' je peti mjesec."},
  "2011_ljeto_B__18": {"A":"'Mojsije' je poznata pjesma Vladimira Nazora, a ne Cesarića.","B":"'Zvonimirova laž' nije Cesarićevo djelo.","C":"'Zaljubljen u ljubav' je naslov vezan uz Tina Ujevića, a ne uz Cesarića."},
  "2011_ljeto_B__19": {"A":"Viteški roman je srednjovjekovna pripovjedna proza, a Božanstvena komedija je opsežno djelo u stihu.","C":"Crkveno prikazanje je dramska vrsta namijenjena izvedbi, a Komedija je pripovjedno-epsko djelo u stihovima.","D":"Mit je usmena predaja o bogovima i postanku svijeta, a Komedija je autorsko književno djelo - ep."},
  "2011_ljeto_B__20": {"A":"'Svjetla šute' znači da svjetla nema, pa mjesto nije osvijetljeno nego mračno.","B":"Stih govori o izostanku svjetla, a ne o temperaturi; hladnoća se ne spominje.","C":"Stih ne spominje žar ni vrućinu, nego odsutnost svjetla (mrak)."},
  "2011_ljeto_B__21": {"B":"Onomatopeja oponaša zvuk glasovima riječi, a ovdje se zvuk uspoređuje s morem pomoću 'kao'.","C":"Hiperbola je pretjerivanje, a ovaj stih ne preuveličava nego uspoređuje.","D":"Asonanca je ponavljanje samoglasnika, a ovdje je riječ o usporedbi dvaju pojmova."},
  "2011_ljeto_B__22": {"A":"Krađa nije grijeh ovih duša; tekst govori o strastima i puti, ne o krađi.","B":"Ubojstvo nije ono za što su kažnjeni; stihovi spominju put i strasti (bludnost).","C":"Izdaja se u Danteovu Paklu kažnjava u najnižem krugu, a ovaj ulomak prikazuje drugi krug - bludnike."},
  "2011_ljeto_B__23": {"A":"Stalne vrućine u ovom ulomku nema; kazna je vihor, a ne toplina.","B":"Ubodi strijela ne spominju se; mučenje je vjetar koji nosi duše.","D":"Žeđ se ne spominje; duše muči neprestani pakleni vihor."},
  "2011_ljeto_B__24": {"A":"Sa zimskim nebom duše nisu izravno uspoređene; zima je tek dio slike jata ptica.","C":"Jaki vjetar je sredstvo mučenja, a poredba povezuje duše s jatom škoraca, ne s vjetrom.","D":"Užareno grotlo nije predmet usporedbe; duše su uspoređene s pticama u jatu."},
  "2011_ljeto_B__25": {"B":"Stih izričito kaže da nema nade ni za mir, pa duše neće počinuti.","C":"Tekst kaže suprotno - nema nade da će se bijeda smanjiti.","D":"Stih izrijekom poriče svaku nadu za izbavljenje ('nema im nade')."},
  "2011_ljeto_B__26": {"A":"Razlog nije poetičnost zvuka riječi, nego potreba za točnim brojem slogova u stihu.","C":"Nije riječ o težnji za kratkoćom izraza općenito, nego o metričkom usklađivanju stiha.","D":"Pjesnička sloboda je preopćenita; konkretan razlog je metar (broj slogova)."},
  "2011_ljeto_B__27": {"A":"Tri je broj dijelova (Pakao, Čistilište, Raj), a ne broj pjevanja.","B":"Devet je broj krugova Pakla, a ne ukupan broj pjevanja.","C":"Trideset tri je broj pjevanja jednoga dijela, a cijelo djelo ima sto pjevanja."},
  "2011_ljeto_B__28": {"A":"Tri se odnosi na dijelove Komedije, a ne na broj krugova Pakla.","C":"Trideset tri je broj pjevanja, a ne krugova Pakla.","D":"Sto je ukupan broj pjevanja Komedije, a ne broj krugova Pakla."},
  "2011_ljeto_B__29": {"A":"Latinski je bio jezik srednjovjekovne učenosti, ali je Dante svjesno pisao na narodnome, talijanskome jeziku.","B":"Staroslavenski je jezik slavenske crkvene pismenosti i nema veze s Danteom.","D":"Grčki nije jezik Komedije; Dante piše toskanskim narječjem talijanskoga."},
  "2011_ljeto_B__30": {"A":"Distih je dvostih, a Komedija je pisana strofama od tri stiha.","C":"Katren je strofa od četiri stiha, a Dante koristi trostih (tercinu).","D":"Stanca (oktava) ima osam stihova, a Komedija je pisana tercinom."},
  "2011_ljeto_B__31": {"A":"Beatrice vodi Dantea kroz Raj, a ne kroz Pakao.","B":"Ovidije nije Danteov vodič; kroz Pakao ga vodi Vergilije.","C":"Sv. Augustin nije vodič kroz Pakao; tu ulogu ima Vergilije."},
  "2011_ljeto_B__32": {"A":"Cervantes i Shakespeare su renesansni pisci drugih književnosti, a ne trolist talijanske predrenesanse.","B":"Ovidije i Plaut su antički rimski pisci, a ne predstavnici predrenesanse.","C":"Tasso i Ariosto su talijanski renesansni i kasnorenesansni pjesnici, a ne predrenesansni trolist."},
  "2011_ljeto_B__33": {"A":"Komentiranjem pripovjedač izravno tumači i ocjenjuje, a ovdje teku replike likova.","B":"Opisivanjem se prikazuju izgled i ugođaj, dok ovaj ulomak donosi razgovor likova.","D":"Monolog je govor jednoga lika, a ovdje govore dvojica (Kanonik i Zgubidan) - dakle dijalog."},
  "2011_ljeto_B__34": {"B":"Primitivnost ljudi posljedica je, a ne tema Kanonikova govora; on izravno govori protiv obrazovanja.","C":"O važnosti poljoprivrede Kanonik govori tek usput (orati, kopati), a glavna je misao odbacivanje škole.","D":"Župnikova propovijed se spominje kao potkrjepa, a ne kao tema govora."},
  "2011_ljeto_B__35": {"A":"Zgubidan Kanoniku ne prijeti sudom ni zatvorom; zamjera mu se neslaganjem s njegovim stavovima.","C":"Zgubidan ga ne naziva smiješnim, nego se suprotstavlja njegovim idejama o nepotrebnosti škole.","D":"Nepristajanje na sviranje bajsa nije razlog razmirice; spor je oko Kanonikovih nazora."},
  "2011_ljeto_B__36": {"A":"Rečenica ne hvali život na selu, nego poručuje da je obrazovanje za gospodu, a ne za seljake.","C":"Usporedbe sela i grada ovdje nema; riječ je o tome tko treba biti obrazovan.","D":"Čast seljačkoga posla nije smisao ove rečenice; ona poriče potrebu školovanja seljaka."},
  "2011_ljeto_B__37": {"A":"Rečenica pokazuje suprotno - djeca su radila (Ivica je vodio kravu), a ne da su bezbrižna.","B":"O bolesti ili zanemarenosti djece rečenica ne govori; govori o njihovim radnim zaduženjima.","D":"O izučavanju zanata nema riječi; spominje se rad na gospodarstvu (paša krave)."},
  "2011_ljeto_B__38": {"B":"Sklonost razmišljanju ne iskazuje se nazivanjem pismenosti 'Antikrstovim evanđeljem'; to je fanatičan, a ne promišljen stav.","C":"Ljubomore u rečenici nema; riječ je o vjerski obojenu odbacivanju obrazovanja.","D":"Praznovjerje se odnosi na vjeru u natprirodno, a Kanonikova izjava izražava vjerski fanatizam protiv škole."},
  "2011_ljeto_B__39": {"B":"Romantizam prethodi realizmu i obilježava ga zanos i idealizacija, dok Kovačić kritički prikazuje društvenu zbilju.","C":"Protorealizam je prijelazno razdoblje prije realizma, a Kovačić pripada zrelomu hrvatskom realizmu.","D":"Moderna dolazi nakon realizma (kraj 19. i poč. 20. st.), a Kovačić djeluje u realizmu."},
  "2011_ljeto_B__40": {"A":"Pustolovna tematika ističe napetu radnju i avanturu, a u djelu su u prvom planu društveni odnosi i klasni sukobi.","C":"Povijesna tematika obrađuje prošle događaje, a Kovačić prikazuje suvremeno hrvatsko društvo.","D":"Filozofska tematika temelji se na apstraktnom promišljanju, a djelo je usredotočeno na društvenu zbilju."},
  "2011_ljeto_B__41": {"A":"Raslojavanje sela i strani kapital nisu središte djela; tema je sudbina pojedinca (Ivice) na putu u grad.","C":"Propadanje plemstva nije tema; Ivica je seljačko dijete koje pokušava uspjeti u gradu.","D":"Staleške razlike kao prepreka ljubavi nisu glavna tema; u središtu je životni put siromašnoga mladića."},
  "2011_ljeto_B__42": {"A":"Dalmacija nije prostor radnje; djelo je smješteno u zagorsku sredinu.","C":"Hrvatsko primorje nije mjesto radnje; opisuje se zagorsko selo.","D":"Slavonija nije prostor djela; radnja se odvija u Hrvatskome zagorju."},
  "2011_ljeto_B__43": {"A":"Metafora je prijenos značenja po sličnosti, a ovdje je riječ o suprotnosti rečenoga i mišljenoga.","B":"Hiperbola je pretjerivanje, a ova rečenica izruguje se, a ne preuveličava.","C":"Gradacija je stupnjevanje, a ovdje nema niza pojmova u rastu ili padu intenziteta."},
  "2011_ljeto_B__44": {"A":"'Zvekasta kvrga-glava' je pogrdna metafora/poredba za glupost, a ne metonimija (zamjena po stvarnoj povezanosti).","C":"Rečenica o neslušanju doslovan je iskaz bez prijenosa po povezanosti pojmova.","D":"Dozivanje 'Ej, Zgubidane' je vokativna formula, a ne metonimija."},
  "2011_ljeto_B__45": {"B":"Trotočje ovdje ne označava naglo prekinutu rečenicu, nego izostavljeni dio teksta između dvaju ulomaka govora.","C":"Nije riječ o isprekidanome, zamuckujućem govoru lika, nego o uredničkom izostavljanju dijela teksta.","D":"Govor nije nenaveden - upravo je iskazan; trotočje pokazuje da je dio teksta izostavljen."},
  "2011_ljeto_B__46": {"A":"Vokativnosti nema; rečenica ne sadržava doziv (vokativ) odvojen zarezom.","C":"Nizanja (nabrajanja) nema na mjestu spornoga zareza; zarez stoji između zavisne i glavne rečenice.","D":"Isticanja (umetanja) nema; zarez je tu zbog obrnuta reda - zavisna pogodbena rečenica ispred glavne."},
  "2011_ljeto_B__47": {"A":"Aorist izriče svršenu prošlu radnju jednim glagolom (npr. 'sluša'), a ovdje je složeni oblik 'nijeste slušali'.","B":"Imperfekt izriče nesvršenu prošlu radnju jednim glagolom ('slušahu'), a ovdje je perfekt.","C":"Prezent izriče sadašnjost, a 'nijeste slušali' upućuje na prošlost (perfekt)."},
  "2011_ljeto_B__48": {"A":"Prva polovica 19. st. prethodi Krležinu vremenu; roman je objavljen 1932.","B":"Druga polovica 19. st. također je preranо; Krleža stvara u 20. stoljeću.","D":"Druga polovica 20. st. prekasna je; roman je nastao 1932., u prvoj polovici stoljeća."},
  "2011_ljeto_B__49": {"A":"Socijalni roman u prvi plan stavlja društvene odnose, a ovdje je naglasak na unutarnjem, psihičkom svijetu junaka.","B":"Obiteljski roman prati sudbinu obitelji kroz naraštaje, a Krležin se roman bavi krizom pojedinčeve psihe.","D":"Pustolovni roman gradi se na napetoj radnji i avanturi, čega u ovom introspektivnom djelu nema."},
  "2011_ljeto_B__50": {"A":"Filip nije glazbenik; on je likovni umjetnik (slikar).","B":"Filip nije pisac; po zanimanju je slikar.","C":"Filip nije pustolov; on je slikar koji se vraća u rodni kraj."},
  "2011_ljeto_B__51": {"A":"Filip se ne raduje priznanju; njegove riječi izražavaju čuđenje i zbunjenost majčinom prisnošću.","C":"Riječi ne govore o majčinoj eleganciji nego o iznenađenju njezinom prisnošću prema njemu.","D":"Nije riječ o radosti zbog nekog svečanog događaja; 'svečano' opisuje neobičnost doživljaja majčine prisnosti."},
  "2011_ljeto_B__52": {"A":"Auditivni (zvukovni) podražaji ne opisuju se; Filipovo stanje izraženo je iskrivljenom vizualnom percepcijom.","B":"Okusnih senzacija nema u opisu vrućice; riječ je o poremećenom viđenju crta i linija.","D":"Olfaktivnog gađenja (miris) nema; halucinacije su vidne (linije koje kruže i nestaju)."},
  "2011_ljeto_B__53": {"A":"Rečenica o naručivanju čokolade prikazuje radnju, a ne vanjski izgled lika.","C":"Rečenica o mahanju nogama i jedenju prikazuje ponašanje/radnju, a ne opis vanjskoga izgleda.","D":"Rečenica o majčinu povratku iznosi podatak o radnji, a ne vanjski opis."},
  "2011_ljeto_B__54": {"A":"Društvena neprilagođenost je obilježje lika, ali nije središnja tema kao potraga za identitetom.","B":"Uspon u visoko društvo nije tema; Filip je u krizi i traga za vlastitim podrijetlom i smislom.","C":"Politička previranja nisu tema romana; u središtu je Filipova unutarnja potraga za identitetom."},
  "2011_ljeto_B__55": {"A":"'Zore i vihori' je pjesnička zbirka (Vladimir Nazor), dakle lirika, a ne epika.","B":"'U agoniji' je drama (Miroslav Krleža), pa pripada dramskome, a ne epskome rodu.","D":"'Preobraženja' je pjesnička zbirka (Antun Branko Šimić), dakle lirika, a ne epika."},
  "2011_ljeto_B__56": {"A":"Muzej suvremene umjetnosti ne nosi Krležino ime.","B":"Institut za književnost nije ustanova nazvana po Krleži.","D":"Hrvatsko narodno kazalište ne nosi ime Miroslava Krleže."},
  "2011_ljeto_B__57": {"B":"Rečenica o 'žalosnom, sivom licu' pod obrazinom je opis, ali bez veznika usporedbe - nije poredba.","C":"Rečenica o svilenoj kutiji običan je opis predmeta, bez usporedbe pomoću 'kao'.","D":"Rečenica o vijugavim potezima opisuje kretanje linija, ali bez izričite usporedbe dvaju pojmova."},
  "2011_ljeto_B__58": {"A":"'Ugodnom' je suprotno po dojmu, ali ne izravan antonim temperaturnog pridjeva 'hladnom'.","C":"'Ledenom' je istoznačnica (sinonim), a ne suprotnica pridjeva 'hladnom'.","D":"'Jezovitom' znači zastrašujuće i nije temperaturna suprotnost pridjevu 'hladnom'."},
  "2011_ljeto_B__59": {"A":"Imperfekt bi glasio 'bijaše/bješe', a ovdje je oblik 'si' - prezent.","C":"Imperativ je zapovjedni način ('budi'), a 'si' iskazuje stanje u sadašnjosti - prezent.","D":"Aorist glagola biti glasi 'bih/bi/bî', a 'si' je prezentski oblik."},
  "2011_ljeto_B__60": {"A":"'Mala Zygmusika' ima pogrešan oblik pridjeva (treba 'maloga'), pa nije ispravan genitiv.","B":"'Manjega' je oblik komparativa, a traži se genitiv pozitiva ('maloga').","C":"'Maloga Zygmusik' ostavlja ime nesklonjeno; vlastito ime mora biti u genitivu (Zygmusika)."},
  "2011_ljeto_B__61": {"B":"Palatalizacija daje č/ž/š (npr. ruka - ručica), a ovdje k prelazi u c ispred i - to je sibilarizacija.","C":"Nepostojano a je ispadanje/pojava glasa a, a ovdje se mijenja suglasnik k u c.","D":"Jotacija je stapanje suglasnika s glasom j, čega u tvorbi 'majci' nema."},
  "2011_ljeto_B__62": {"B":"Antonimski odnos bio bi suprotnost značenja, a 'vertikala' i 'okomica' znače isto.","C":"Homonimski odnos podrazumijeva isti zvuk uz različito značenje, a ove riječi imaju isto značenje, a različit oblik."},
  "2011_ljeto_B__63": {"A":"Anglizmi potječu iz engleskoga, a 'kelner' je iz njemačkoga.","B":"Hungarizmi potječu iz mađarskoga, a 'kelner' je njemačka posuđenica.","C":"Galicizmi potječu iz francuskoga, a 'kelner' je njemačkoga podrijetla."},
  "2011_ljeto_B__64": {"A":"Genitiv odgovara na pitanje koga/čega, a 'u kavani' odgovara na pitanje gdje - to je lokativ.","B":"Dativ odgovara na pitanje komu/čemu, a ovdje je riječ o mjestu (lokativ).","C":"Akuzativ s prijedlogom 'u' označava smjer (kamo?), a ovdje je mjesto (gdje? - lokativ)."},
  "2011_ljeto_B__65": {"A":"'Vidjeti' nije tvorbeni vidski parnjak glagola 'primijetiti', nego srodan glagol drugoga korijena.","B":"'Zapaziti' je istoznačnica, ali nije vidski parnjak (oba su svršena); parnjak je nesvršeni 'primjećivati'.","C":"'Prihvatiti' znači nešto drugo i nije vidski parnjak glagola 'primijetiti'."},
  "2011_ljeto_B__66": {"B":"Mažuranić je autor Smrti Smail-age Čengića (E), a ne Osmana (C); spoj 1C je pogrešan.","C":"Relković je napisao Satira (D), a Lucić pjesmu Jur nijedna na svit vila (F); zamjena 4F, 5D je pogrešna.","D":"Marulić je autor Judite (A), a ne Satira; zamjena 2D, 4A je pogrešna."},
  "2011_ljeto_B__67": {"A":"'Panonske Nizine' je pogrešno jer se u geografskom nazivu 'Panonska nizina' samo prva riječ piše velikim slovom."},
  "2011_ljeto_B__68": {"B":"'Povješću' je nestandardan oblik; instrumental imenice 'povijest' glasi 'poviješću'."},
  "2011_ljeto_B__69": {"B":"'varaždinske županije' je pogrešno jer je 'Varaždinska županija' vlastito ime upravne jedinice i piše se obama velikim slovima."},
  "2011_ljeto_B__70": {"A":"'Srednjega vijeka' je pogrešno jer se nazivi povijesnih razdoblja pišu malim slovom (srednji vijek)."},
  "2011_ljeto_B__71": {"B":"Opcija B istovjetna je točnoj ('najnapučeniji'); ako se razlikovala pisanjem (npr. razdvojeno 'naj napučeniji'), to bi bilo pogrešno jer se superlativ piše sastavljeno."},
  "2011_ljeto_B__72": {"B":"'Stari grad' je pogrešno jer je riječ o vlastitom imenu tvrđave, pa se obje sastavnice pišu velikim slovom."},
  "2011_ljeto_B__73": {"B":"'plemenite' je značenjski pogrešno; traži se posvojni pridjev 'plemićke' (palače koje pripadaju plemićima)."},
  "2011_ljeto_B__74": {"B":"'Gajevoj Ulici' je pogrešno jer se opća imenica 'ulica' u imenu ulice piše malim slovom."},
  "2011_ljeto_B__75": {"B":"'Stančevu Trgu' je pogrešno jer se opća imenica 'trg' u imenu trga piše malim slovom."},
  "2011_ljeto_B__76": {"B":"'Varaždinskim baroknim Večerima' je pogrešno jer se u imenu manifestacije velikim slovom piše samo prva riječ."},

  // 2011_zima_A
  "2011_zima_A__1": {"A":"Shema abab abab abab pretpostavlja istu rimu kroz sve tri strofe, no rime se mijenjaju od kitice do kitice (luka/lađe → snivaju/vodi → sreću/stoje).","B":"Obgrljena rima (abba) ne odgovara stihovima jer se prvi rimuje s trećim, a drugi s četvrtim (ukrštena, ne obgrljena rima).","D":"Predloženi raspored abac dedf ghgj podrazumijeva nerimovane stihove, a u pjesmi su svi stihovi unutar strofe pravilno povezani ukrštenom rimom."},
  "2011_zima_A__2": {"A":"Peterac (5 slogova) ne odgovara mjerenju koje daje 6 slogova u tom stihu.","C":"Osmerac ima 8 slogova, što je previše za 'U plitkoj vodi'.","D":"Deseterac ima 10 slogova i znatno premašuje duljinu ovoga kratkog stiha."},
  "2011_zima_A__3": {"B":"Pjesma se ne temelji na nizu glasovnih figura ni neobičnu rasporedu riječi, nego na pravilnoj izmjeni stihova i rimi.","C":"Ritam ne proizlazi iz osobita leksika, nego iz metričke izmjene duljih i kraćih stihova te rime.","D":"U pjesmi nema izostavljanja rečeničnih dijelova (elipse) kao sredstva ritmizacije."},
  "2011_zima_A__4": {"B":"Ćuk i lađe sporedni su, atmosferski motivi prve strofe, a ne temeljni motivi cijele pjesme.","C":"Sidro i voda pojedinosti su unutar slike luke, a ne nosivi motivi pjesme.","D":"Snovi i jarboli pojavljuju se tek kao detalji posljednje strofe te ne nose cijelu pjesmu."},
  "2011_zima_A__5": {"A":"Pjesma ne počiva na ironiji jer nema suprotnosti između rečenoga i mišljenoga; slika luke ozbiljno prikazuje pasivnost.","B":"Oksimoron je tek lokalna figura ('mrtva luka'), ali pjesma se kao cjelina gradi na prenesenu, alegorijskom značenju.","C":"Onomatopeja oponaša zvukove i nije nosivo načelo pjesme koja brodove tumači alegorijski."},
  "2011_zima_A__6": {"A":"Mrtva luka predmet je iskaza, a ne govornik; ona ne može izgovarati stih.","C":"Umorne lađe dio su opisanoga prizora i ne progovaraju u prvom stihu.","D":"Govornik nije neodređena osoba, nego prepoznatljiv lirski subjekt koji u 1. licu kaže 'Znam'."},
  "2011_zima_A__7": {"B":"U prvoj strofi nema taktilnih (dodirnih) motiva, pa kombinacija taktilno-vizualno nije točna.","C":"Olfaktivnih (mirisnih) motiva u prvoj strofi nema, pa par auditivno-olfaktivno ne stoji.","D":"Ni taktilnih ni olfaktivnih osjeta u prvoj strofi nema; prisutni su samo vid i sluh."},
  "2011_zima_A__8": {"A":"Iako se spominje luka, pjesma ne opisuje krajolik radi njega samoga, nego ga koristi za misao o pasivnu životu.","C":"Pjesma se ne bavi društvenim nepravdama ni socijalnim položajem, nego promišljanjem o ljudskoj sudbini.","D":"U pjesmi nema ljubavnoga motiva ni odnosa među zaljubljenima."},
  "2011_zima_A__9": {"A":"Stihovi se ne usklađuju, nego se suprotstavljaju: čežnja za srećom i strah od plovidbe u oprjeci su.","C":"Nije riječ o povezivanju srodnih sadržaja, nego o napetosti između želje i straha.","D":"Nijedan stih ne isključuje drugi; oba istodobno vrijede i upravo time tvore suprotnost."},
  "2011_zima_A__10": {"B":"Luka nije prikazana kao mjesto umiranja, nego kao trajno sklonište od plovidbe i života.","C":"Nije naglašena udaljenost ni napuštenost prostora, nego skrivanje od izazova.","D":"Doslovno tumačenje (zaštićeni vodeni prostor) zanemaruje alegorijsko značenje pasivnosti."},
  "2011_zima_A__11": {"A":"Pustolovi traže izazov i kreću na put, što je suprotno brodovima koji se boje ploviti.","C":"Tragači aktivno traže, a brodovi u pjesmi ostaju nepokretni i samo sanjaju.","D":"Putnici se zaista kreću i odlaze, dok brodovi u luci nikada ne isplove."},
  "2011_zima_A__12": {"A":"Pjevanje ćuka uklapa se u sjetno, tjeskobno ozračje pjesme i ne odudara od njega.","B":"Umorne lađe pojačavaju dojam malaksalosti i pasivnosti, pa su u skladu s raspoloženjem.","C":"'Gledaju sreću' samo je čežnja koju prati strah, pa ne stvara veseo obrat u ugođaju."},
  "2011_zima_A__13": {"A":"Iza dvotočja ne slijedi nabrajanje, nego jedna izjavna rečenica.","B":"Dvotočje ne uvodi tuđe riječi (citat), nego nastavak govora samoga lirskog subjekta.","D":"Uloga dvotočja ovdje nije isticanje, nego najava sadržaja onoga što govornik 'zna'."},
  "2011_zima_A__14": {"A":"Crta tu ne dodaje naknadno objašnjenje, nego stvara dramsku pauzu prije završne riječi.","C":"Crta ne označava izostavljeni dio teksta, nego zastajkivanje u izgovoru.","D":"Crta ne povezuje dijelove, nego ih razdvaja stankom radi naglašavanja."},
  "2011_zima_A__15": {"A":"'Nađe se' i 'brodi' standardni su, pravilni glagolski oblici i nisu kraćeni radi metra.","B":"'Meću' je pravilan oblik, a 'vidjet će' standardno je pisan futur, pa nisu metrički iskrivljeni.","D":"'Počivaju' i 'boje se' uobičajeni su, pravilni oblici bez kraćenja zbog ritma."},
  "2011_zima_A__16": {"A":"'Večer nad gradom' nije Cesarićeva antologijska pjesma navedena kao njegovo prepoznatljivo djelo.","B":"'Visoki jablani' nije Cesarićeva pjesma iz traženoga antologijskog kruga.","C":"'1909.' nije Cesarićevo djelo; među njegovim antologijskim pjesmama traži se 'Oblak'."},
  "2011_zima_A__17": {"A":"Eshil je drugi grčki tragičar (Okovani Prometej), ali nije autor Antigone.","B":"Euripid je pisao druge tragedije (Medeja), no Antigonu nije napisao.","C":"Homer je epski pjesnik (Ilijada, Odiseja), a ne dramatičar koji bi napisao Antigonu."},
  "2011_zima_A__18": {"B":"Antigona je nastala u 5. st. pr. Kr., mnogo prije srednjega vijeka.","C":"Renesansa je novovjekovno razdoblje, a Sofoklovo djelo pripada grčkoj antici.","D":"Klasicizam je razdoblje 17.–18. st., dok Antigona potječe iz antičke Grčke."},
  "2011_zima_A__19": {"A":"Antigona nije ep, jer je dramsko djelo namijenjeno izvedbi, a ne pripovjedni spjev.","B":"Nije komedija, jer ima ozbiljnu radnju i tragičan, koban završetak.","C":"Ditiramb je obredna pjesma u čast Dioniza, a ne dramska vrsta kojoj pripada Antigona."},
  "2011_zima_A__20": {"A":"Invokacija je zaziv muze na početku epa, a ne učinak tragedije na gledatelja.","B":"In medias res je postupak započinjanja radnje 'usred zbivanja', a ne emocionalni učinak.","D":"Retardacija je usporavanje radnje, a ne pročišćenje osjećaja koje tragedija izaziva."},
  "2011_zima_A__21": {"A":"Pjesnikinja s Lezba je Sapfa, a ne Antigona.","C":"Pitijska proročica je svećenica u Delfima, što nije Antigonina uloga.","D":"Antigona nije božica, nego smrtnica, kći kralja Edipa."},
  "2011_zima_A__22": {"A":"Ahilej je junak Ilijade i nije Antigonin otac.","C":"Odisej je junak Odiseje i nema veze s Antigoninim podrijetlom.","D":"Zeus je vrhovni bog, a ne Antigonin osorni otac na kojega misli Zborovođa."},
  "2011_zima_A__23": {"A":"Iskaz ne govori o gubitku prijatelja, nego o nemogućnosti da se odustane od uvjerenja.","B":"Antigona se ne prikazuje kao svadljiva ni lažljiva; naglašava se njezina dosljednost.","C":"Ne radi se o osjećaju prevarenosti ili napuštenosti, nego o čvrstoći stava."},
  "2011_zima_A__24": {"A":"Kreont ne uspoređuje ćud s ognjem samim, nego s čelikom koji je ognjem prekaljen i zato krt.","B":"'Zli plod' odnosi se na posljedice obijesti u društvu, a ne na usporedbu s Antigoninom ćudi.","D":"'Muška tvrdoglavost' nije Kreontova usporedba; on njezinu tvrdoću izriče slikom prekaljena čelika."},
  "2011_zima_A__25": {"B":"Personifikacija pridaje ljudska svojstva neživomu, čega u ovom pitanju upućenu porotnicima nema.","C":"Ironija bi značila suprotnost rečenoga i mišljenoga, no Kreont izravno i ozbiljno iznosi stav.","D":"Simbol pretpostavlja predmet koji upućuje na šire značenje, dok je ovdje riječ o pitanju bez očekivana odgovora."},
  "2011_zima_A__26": {"A":"Kreont se ne boji vlastite žene; rečenica govori o opasnosti da on sam ispadne slab.","B":"Narod ga ne prisiljava na ništa; odluku donosi sam kao vladar.","C":"U rečenici nema prijetnje gubitkom krune, nego straha od pokazivanja slabosti."},
  "2011_zima_A__27": {"A":"Smisao nije u tome da ljudi traže gospodara, nego da se i najtvrdoglaviji mogu ukrotiti stegom.","C":"Uzda nije slika pokore svakom čovjeku, nego sredstvo discipliniranja i pokoravanja.","D":"Rečenica ne govori o ljubavi pod prisilom, nego o učinkovitosti stege i kazne."},
  "2011_zima_A__28": {"B":"Kreont se ne poziva na Zeusovu zaštitu kuće, nego naglašava da nitko nije iznad njegova zakona.","C":"Nije riječ o uvredi Zeusa, nego o tome da svatko mora snositi posljedice kršenja zakona.","D":"Smisao je suprotan: rodbinske veze ne mogu nadvladati zakon koji vrijedi za sve."},
  "2011_zima_A__29": {"B":"Kreont nije popustljiv ni sklon kompromisu; uporno odbija odustati od kazne.","C":"Nije prevrtljiv ni neodlučan, nego dosljedno ustraje u svojoj zapovijedi.","D":"U tekstu ne pokazuje usamljenost ni strah, nego odlučnost i čvrstinu."},
  "2011_zima_A__30": {"B":"Antigona nije optužena za preljub; njezin je čin pokop brata usprkos zabrani.","C":"Odbijanje prosaca nije predmet Kreontove optužbe.","D":"Kreont je ne osuđuje zbog suprotstavljanja bogovima, nego zbog kršenja njegova javnog naloga (pokopa brata)."},
  "2011_zima_A__31": {"B":"Izmena i Antigona ne bježe; Antigona stradava, a ne spašava se bijegom.","C":"Kreont ne oslijepi (to je sudbina Edipa), nego ostaje slomljen nizom smrti.","D":"Antigona se ne kaje za svoj čin; dosljedno ostaje pri svojoj odluci do kraja."},
  "2011_zima_A__32": {"B":"Zbor ne upućuje glumce; to je redateljska, a ne njegova dramska funkcija.","C":"Zbor ne oblikuje karaktere likova, nego prati i tumači zbivanje.","D":"Zbor ne razrješava sukob radnje, nego komentira događaje i moralne poruke."},
  "2011_zima_A__33": {"B":"'KREONT:' je oznaka govornika (lica), a ne scenska uputa.","C":"Navedeni stih dio je Kreontova govora (replike), a ne didaskalija.","D":"Redak sa Zborovođinim riječima jest replika lica, a ne uputa u zagradama."},
  "2011_zima_A__34": {"A":"Simbolistička drama gradi se na simbolima i nagovještaju, a 'Bez trećega' analizira psihu likova.","B":"Nije filozofska drama jer ne raspravlja apstraktne ideje, nego unutarnje stanje supružnika.","D":"Ekspresionistička drama naglašava krik i izobličenje stvarnosti, što nije obilježje ove psihološke analize."},
  "2011_zima_A__35": {"B":"Sukob ne pokreće suprugina neodgovornost, nego prešućeni preljub i sumnja u nj.","C":"Markova ambicija nije izvor sukoba; razdor stvara Gigina tajna o nevjeri.","D":"Markova ljubomora posljedica je sumnje, ali pravi pokretač sukoba jest suprugin preljub."},
  "2011_zima_A__36": {"A":"Rečenica ne govori o prekinutim izlascima, nego o sreći pomiješanoj s tjeskobom i krivnjom.","B":"Nije riječ o strahu od starog sukoba, nego o tome da se radost povratka pretvara u muku.","D":"Sumnja u Markovu vjernost nije sadržaj te rečenice; ona izriče Giginu unutarnju zebnju."},
  "2011_zima_A__37": {"A":"Marko ne osjeća ushit; iz njegovih riječi izbija sumnja i napetost.","C":"Nije riječ o mržnji, nego o nepovjerenju i potrebi da dozna istinu.","D":"Netrpeljivost je prejaka i pogrešna oznaka; Markov osjećaj je nepovjerenje prema Gigi."},
  "2011_zima_A__38": {"A":"Slika kabanice koja se lažno predstavlja ne govori o ponosu, nego o pretvaranju.","B":"Marko ne ističe Giginu ljepotu, nego njezino prikrivanje i lažnu vanjštinu.","C":"Ne naziva je zlom, nego prijetvornom: krpa koja se izdaje za kraljevski plašt."},
  "2011_zima_A__39": {"A":"Markovo ponašanje ne izaziva gradsko ogovaranje, nego sumnja u suprugu i njezinu nevjeru.","B":"Dugo izbivanje samo je okolnost, a stvarni uzrok njegova držanja jest bračna nevjera.","D":"Očeva smrt nije razlog Markova ponašanja; uzrok je sumnja u Giginu vjernost."},
  "2011_zima_A__40": {"A":"Hiperbola je pretjerivanje, a ovdje je riječ o usporedbi pomoću veznika 'kao'.","C":"Simbol bi upućivao na šire značenje bez izravne usporedbe, no 'kao ćilim' jasno je poredba.","D":"Personifikacija pridaje ljudska svojstva neživomu, čega u ovoj usporedbi nema."},
  "2011_zima_A__41": {"A":"Giga se ne odnosi prema Marku s gađenjem; iz didaskalija izbija toplina i bliskost.","B":"Nije riječ o strahu, nego o nježnu, prisnu obraćanju ('dragi').","D":"Divljenje nije točan opis; Giga prema Marku pokazuje nježnost, a ne strahopoštovanje."},
  "2011_zima_A__42": {"A":"Nije poredba jer nema veznika usporedbe; 'loviti magle' preneseno je značenje.","B":"Paradoks bi bio prividno proturječan iskaz, a ovdje je riječ o prenesenom slikovitom izrazu.","C":"Ironija bi značila suprotnost rečenoga i mišljenoga, dok je 'loviti magle' metafora nesigurnosti."},
  "2011_zima_A__43": {"A":"Gigina rečenica o tužnoj sreći izriče njezino raspoloženje, ali ne imenuje sredisnji problem drame.","B":"Poziv 'pa upitaj' pokazuje Giginu spremnost na razgovor, no ne sažima temu prešućivane laži.","C":"Usporedba s ćilimom Markova je optužba za pretvaranje, ali jezgru drame iskazuje rečenica o 'pitomoj laži'."},
  "2011_zima_A__44": {"B":"'Laku noć' nije završna replika koja razrješava dramu.","C":"Gigina rečenica o tome da će opet biti lijepo nije posljednja; nakon nje slijedi priznanje.","D":"Markovo ponavljanje 'Strašno!' nije završetak; dramu zaključuje Gigino priznanje 'Ubila sam svoga muža.'"},
  "2011_zima_A__45": {"A":"Uspon i pad aristokratske obitelji nije tema ni 'Bez trećega' ni 'Nore'.","B":"Neostvarena ljubav i promašeni životi opća su tema, ali ne ono što ove dvije drame posebno povezuje.","C":"Povijesna zbivanja nisu okosnica ni jedne ni druge drame; obje se bave položajem žene u braku."},
  "2011_zima_A__46": {"A":"'Misao na vječnost' nije djelo koje obilježava početak razdoblja u kojem je 'Bez trećega'.","B":"'Zlatarovo zlato' (Šenoa) pripada realizmu i ranijem je razdoblju.","D":"'Kratki izlet' (Marinković) noviji je tekst i ne otvara to razdoblje."},
  "2011_zima_A__47": {"B":"Zarezi ne odvajaju suprotne dijelove rečenice; nema suprotnosti.","C":"Nije riječ o inverziji (premetanju reda riječi), nego o izdvajanju dozivanja.","D":"Nije umetanje neke surečenice, nego odvajanje vokativa 'dragi'."},
  "2011_zima_A__48": {"A":"Prezent izriče sadašnju radnju, dok 'upitaj' i 'pitaj' izriču zapovijed.","B":"Aorist je oblik za prošlu svršenu radnju, a ovdje je riječ o poticaju na radnju.","C":"Perfekt je prošlo vrijeme, a navedeni su glagoli zapovjedni oblici."},
  "2011_zima_A__49": {"A":"Dvije nije točno: osim 'šta' i 'mi' tu je i povratna zamjenica 'sebi'.","C":"Četiri je previše; zamjenica je samo tri ('šta', 'mi', 'sebi').","D":"Pet zamjenica nema; u rečenici ih je tri."},
  "2011_zima_A__50": {"A":"Dvije surečenice nije dovoljno; rečenica ima tri (glavna, objektna 'da...', uzročna 'jer...').","C":"Četiri surečenice nema; izdvajaju se samo tri.","D":"Pet surečenica znatno je previše; rečenica se sastoji od triju surečenica."},
  "2011_zima_A__51": {"A":"Tužitelj je lik o kojem se pripovijeda, a ne onaj koji u 1. licu kazuje tekst.","B":"Branitelj je također lik unutar priče, a ne pripovjedač.","D":"Autor nije pripovjedač; događaje u 1. licu iznosi lik Meursault ('upre prstom u mene')."},
  "2011_zima_A__52": {"A":"Tužitelj ne ističe Meursaultovu grižnju savjesti, nego upravo njezin izostanak.","C":"Pripadnost kriminalnom okružju nije predmet optužbe u ovom ulomku.","D":"Ljubomora prema žrtvi ne spominje se; ključan je Meursaultov odnos prema majčinoj smrti."},
  "2011_zima_A__53": {"A":"Tužitelj ga ne želi prikazati strastvenim ljubavnikom, nego osobom bez morala.","B":"Ne prikazuje ga kao odana prijatelja, nego kao moralno i društveno neprihvatljiva čovjeka.","C":"Nije naglasak na nevjerstvu ni krivovjerju, nego na njegovoj moralnoj i društvenoj neprihvatljivosti."},
  "2011_zima_A__54": {"A":"Meursault ne sluša tužitelja cinično ni podrugljivo; uviđa ozbiljnost svoga položaja.","C":"Ne traži utjehu u maštanju o slobodi; svjestan je da mu se 'loše piše'.","D":"Nije riječ o strahu da će ga porotnici krivo shvatiti, nego o spoznaji da je mnogo toga protiv njega."},
  "2011_zima_A__55": {"B":"Smijeh u sudnici prati braniteljevu opasku, ali Meursault zaključak izvodi iz braniteljeve uzdrmanosti.","C":"Ne zaključuje to po tužiteljevim riječima, nego po dojmu da je i branitelj potresen.","D":"Dužina procesa nije razlog njegova zaključka; presudna je reakcija branitelja."},
  "2011_zima_A__56": {"A":"Mirisi i boje ne izazivaju mučninu, nego bude prisjećanje na nekadašnji život.","B":"Ne potiču ga na kajanje; bude sjećanje na trenutke zadovoljstva.","C":"Ne javlja se želja za smrću, nego nostalgija za prijašnjim slobodnim životom."},
  "2011_zima_A__57": {"A":"Roman ne završava ženidbom; Meursault biva osuđen i pogubljen.","B":"Ne biva oslobođen, nego osuđen na smrt.","C":"Ne odlazi u progonstvo, nego ga čeka smaknuće."},
  "2011_zima_A__58": {"B":"Radnja se ne odvija u Brazilu, nego u Alžiru.","C":"Iako je Camus francuski pisac, radnja se zbiva u Alžiru, a ne u Francuskoj.","D":"Španjolska nije mjesto radnje; zbivanja su smještena u Alžir."},
  "2011_zima_A__59": {"A":"Naslov ne upućuje na pesimizam, nego na otuđenost junaka od svijeta i osjećaja.","B":"'Stranac' ne znači lažljivost; Meursault je upravo dosljedno iskren, ali otuđen.","D":"Strastvenost je suprotna Meursaultovoj ravnodušnosti koju izriče naslov 'Stranac'."},
  "2011_zima_A__60": {"A":"Tekst nije pretežno opisivanje (statičan prizor), nego iznošenje slijeda događaja.","B":"Nije unutarnji monolog (slobodan tijek misli), nego uređeno pripovijedanje u 1. licu.","D":"Nije retrospektiva kao postupak; događaji se iznose redom kojim teku na sudu."},
  "2011_zima_A__61": {"A":"Racionalizam ističe razum kao izvor spoznaje i ne podudara se s Camusovom filozofijom apsurda.","C":"Materijalizam je nazor o prvenstvu tvari, a ne smjer kojem se pridružuje misao o apsurdu.","D":"Idealizam prednost daje idejama i duhu, što je suprotno egzistencijalističkom polazištu Camusa."},
  "2011_zima_A__62": {"A":"'Upre prstom u mene' opisuje gestu, a ne frazem za nadolazeću nevolju.","B":"'Vladao muk' opisuje tišinu u sudnici i nije frazem sa značenjem 'neće biti dobro'.","C":"Rečenica o dojmu izjave na općinstvo ne sadrži traženi frazem."},
  "2011_zima_A__63": {"A":"Dativ odgovara na pitanje komu/čemu, no veza 'sa + srcem' traži instrumental.","B":"Genitiv (koga/čega) ne odgovara prijedlogu 'sa' uz oruđe/popratnu okolnost.","C":"Akuzativ (koga/što) ne dolazi uz prijedlog 'sa' u ovom značenju; ovdje je instrumental."},
  "2011_zima_A__64": {"A":"'Sljedbenici' znače pristaše ili učenike, što ne odgovara skupu prisutnih u sudnici.","C":"'Porotnici' su točno određeni članovi suda, a 'općinstvo' označava širu publiku.","D":"'Glasači' su sudionici izbora, što nema veze sa skupom gledatelja na suđenju."},
  "2011_zima_A__65": {"A":"Prezent izriče sadašnjost, a 'dignu' je oblik za prošlu svršenu radnju.","B":"Imperfekt izriče prošlu trajnu radnju, dok 'dignu' označava trenutačnu, svršenu.","C":"Imperativ je zapovjedni oblik, a ovdje je riječ o pripovjednom aoristu 'dignu'."},
  "2011_zima_A__66": {"B":"Pridruživanje 2E (Ionesco–Šest lica traži autora) pogrešno je jer je 'Stolice' (D) Ionescovo, a 'Šest lica' je Pirandellovo.","C":"Pridruživanje 5E (Beckett–Šest lica traži autora) netočno je; Beckettovo je djelo 'U očekivanju Godota' (F).","D":"Pridruživanje 1F (Brecht–U očekivanju Godota) pogrešno je jer je Brechtovo djelo 'Majka Hrabrost' (C)."},
  "2011_zima_A__67": {"B":"'Theobrama Cacao' netočno je jer se vrsni dio naziva ('cacao') piše malim slovom.","C":"'theobrama cacao' netočno je jer se rodni dio naziva ('Theobrama') piše velikim slovom.","D":"'Theobrama Kakao' pogrešno je i u pisanju velikim slovom vrste i u pohrvaćenu obliku unutar latinskoga naziva."},
  "2011_zima_A__68": {"A":"'Tekučina' je pogrešno jer se piše s ć ('tekućina', od 'teći').","C":"'Tečnost' je srbizam, a hrvatski standard traži 'tekućina'.","D":"'Tekljina' nije postojeća riječ hrvatskoga standarda."},
  "2011_zima_A__69": {"B":"'Božanstvenome' velikim slovom bilo bi opravdano samo da je vlastito ime, a ovdje je opisni pridjev ('prekrasan').","C":"'bozanstvenome' pogrešno je jer izostavlja slovo ž (treba 'božanstvenome').","D":"'Božanstvenom' je pogrešno i zbog velikoga slova i zbog izostanka nastavka -e koji traži kontekst ('u tome ___ napitku')."},
  "2011_zima_A__70": {"A":"'indijanaca' malim slovom pogrešno je jer je naziv naroda i piše se velikim početnim slovom.","C":"'Američkih' velikim slovom nije opravdano jer je to opisni pridjev, ne vlastito ime.","D":"'Američkih Indijanaca' griješi pišući velikim slovom i pridjev 'američkih', koji treba biti malim."},
  "2011_zima_A__71": {"B":"'ćili' je pogrešno jer se naziv paprike piše s č ('čili').","C":"'čilli' je pogrešno zbog udvojenoga l, kojega u hrvatskom obliku nema.","D":"'čijli' nije postojeći oblik te riječi."},
  "2011_zima_A__72": {"B":"'Nizozemskom' velikim slovom nije opravdano jer je riječ o opisnom pridjevu, ne o vlastitu imenu.","C":"'holandskom' nije preporučeni oblik hrvatskoga standarda; rabi se 'nizozemski'.","D":"'Holandskom' griješi i u izboru riječi i u pisanju velikim slovom opisnoga pridjeva."},
  "2011_zima_A__73": {"A":"'Mlječna' je pogrešno jer dugi jat od 'mlijeko' daje 'ije' ('mliječna').","C":"'Mlečna' je ekavski oblik, a hrvatski standard traži ijekavsko 'mliječna'.","D":"'Mlijeka' je imenica u genitivu, a ne traženi pridjev uz 'čokolada'."},
  "2011_zima_A__74": {"A":"'najčešče' je pogrešno jer se piše s ć ('najčešće').","C":"'najčeće' je pogrešno jer izostavlja glas š (treba 'najčešće').","D":"Iako je oblik 'najčešće' jednak točnomu, kao ponovljena inačica ne može biti odgovor; jedini je ispravan navod pod B."},
  "2011_zima_A__75": {"B":"'od 20% – 40%' pogrešno je jer miješa prijedlog 'od' s crticom umjesto dosljednoga 'od... do...'.","C":"'od 20-40%' pogrešno je jer raspon spaja crticom uz prijedlog 'od' umjesto izrazom 'do'.","D":"'između 20 i 40%' mijenja zadanu konstrukciju i ne navodi postotak uz oba broja kako kontekst traži."},
  "2011_zima_A__76": {"B":"'lućenje' je pogrešno jer se piše s č ('lučenje', od 'lučiti').","C":"'lucenje' je pogrešno jer izostavlja glas č (treba 'lučenje').","D":"'lučnje' nije postojeći oblik glagolske imenice od 'lučiti'."},

  // 2011_zima_B
  "2011_zima_B__1": {"B":"Polazni tekst nema naracije, fabule ni pripovjedača, pa ne pripada epici.","C":"U tekstu nema dramskih lica, dijaloga ni didaskalija, pa ne pripada drami."},
  "2011_zima_B__2": {"B":"Rima nije ab cb db jer se prvi stih u paru ne rimuje s nekim trećim, nego s neposredno sljedećim (slap-kap).","C":"Rima nije ukrštena (ab ab ab) jer se rimuju susjedni stihovi, a ne svaki drugi.","D":"Nije aa aa aa jer se ne rimuju svi stihovi međusobno, nego svaki par za sebe (slap-kap, stvara-šara, sjati-tkati)."},
  "2011_zima_B__3": {"B":"Tekst ne opisuje krajolik radi njega samog, nego slap služi kao misaona slika, pa nije pejzažna pjesma.","C":"U pjesmi nema ljubavnoga motiva ni odnosa među osobama, pa nije ljubavna.","D":"Nema domoljubnih motiva (domovine, naroda u nacionalnom smislu), pa nije domoljubna."},
  "2011_zima_B__4": {"A":"Glagolu 'teče' ne pridaju se ljudske osobine, pa nema personifikacije, nego se ista riječ ponavlja.","C":"Nema namjernog preuveličavanja radi pojačanja dojma, pa nije hiperbola.","D":"Nema suprotnosti rečenoga i mišljenoga, pa nije ironija; riječ se jednostavno ponavlja."},
  "2011_zima_B__5": {"B":"'Kap' i 'slap' nisu okamenjene metafore, nego doslovni pojmovi koji se tek u kontekstu suprotstavljaju po veličini.","C":"Nisu pravi sinonimi jer ne znače isto; naprotiv, suprotstavljeni su (malo prema velikom).","D":"Nisu oblični homonimi jer im se ni oblik ni značenje ne podudaraju na način svojstven homonimiji."},
  "2011_zima_B__6": {"A":"Stih ne tvrdi da je kap važnija od slapa, nego da slap nastaje zbrajanjem svih kapi.","B":"Stih ne ističe nadmoć slapa nad kapi, nego njihovu međuovisnost.","C":"Tvrdnja 'kapi su samo kapi' umanjuje važnost kapi, a stih upravo naglašava njezin doprinos cjelini."},
  "2011_zima_B__7": {"A":"Odnos more – val nije odnos cjeline i nezamjenjivoga doprinositelja na isti način kao slap – kap, nego prirodne pojave i njezina dijela bez naglašene simbolike pojedinca.","B":"Svemir – čovjek izražava nesrazmjer veličina, ali ne i ključnu misao da cjelina nastaje doprinosom svake jedinice.","D":"Nesebičnost – sebičnost odnos je suprotnih osobina, a ne odnos cjeline i njezina sastavnoga dijela."},
  "2011_zima_B__8": {"A":"'sl-ap' je pogrešno jer se slog ne može odvojiti tako da suglasnička skupina 'sl' ostane bez samoglasnika; pravilno je s-lap.","B":"'nj-em' je pogrešno jer je 'nj' jedan glas (dvoslov) koji se ne rastavlja; riječ je jednosložna (njem).","D":"'dr-šće' je pogrešno jer prvi dio 'dr' nema samoglasnika i ne čini slog samostalno."},
  "2011_zima_B__9": {"A":"Stih ima deset slogova, a ne osam, pa nije osmerac.","B":"Stih ima deset, a ne devet slogova, pa nije deveterac.","D":"Stih ima deset, a ne jedanaest slogova, pa nije jedanaesterac."},
  "2011_zima_B__10": {"A":"Nije riječ o nabrajanju jer se ne navode različiti članovi niza, nego se ponavlja ista riječ.","C":"Zarez ne razdvaja suprotstavljene dijelove, pa nije po načelu suprotnosti.","D":"Nema dozivanja ni obraćanja, pa nije po načelu vokativnosti."},
  "2011_zima_B__11": {"A":"Strofa nema samo jednu surečenicu jer postoje dva predikata (sjati, pomaže) odvojena zarezom i veznikom.","C":"Nema triju surečenica jer su prisutna samo dva predikata.","D":"Nema četiriju surečenica; broj predikata je dva."},
  "2011_zima_B__12": {"A":"'Kap' i 'kaplja' nisu antonimi jer ne znače suprotno, nego upravo isto.","C":"Nisu homonimi jer im se značenje podudara, a homonimi imaju isti oblik uz različito značenje.","D":"Nisu kohiponimi jer nisu dvije različite vrste istoga nadređenoga pojma, nego ista riječ u dva oblika."},
  "2011_zima_B__13": {"A":"'Imati' ne odgovara kontekstu stvaranja dúge u slapu, pa nije traženo preneseno značenje.","B":"'Plesti' je blisko doslovnom značenju tkanja, a traži se preneseno značenje stvaranja.","C":"'Pokretati' ne izražava stvaranje cjeline (sna, dúge), nego puko pokretanje, pa ne odgovara."},
  "2011_zima_B__14": {"A":"Riječ nije pravopisno pogrešno napisana; odstupanje je u obliku riječi, ne u pisanju.","C":"Nije riječ o fonološkom odstupanju (glasovnoj promjeni), nego o izostavljenom morfološkom nastavku.","D":"Nema pogreške u rečeničnom ustrojstvu, pa nije sintaktičko odstupanje."},
  "2011_zima_B__15": {"A":"'Svakidašnja jadikovka' je pjesma Tina Ujevića, a ne Cesarića.","B":"'Dugo u noć, u zimsku bijelu noć' je Ujevićeva pjesma, a ne Cesarićeva.","C":"'Utjeha kose' je pjesma A. G. Matoša, a ne Cesarića."},
  "2011_zima_B__16": {"B":"Vergilije je rimski pjesnik, autor Eneide, a ne Ilijade.","C":"Ovidije je rimski pjesnik (Metamorfoze), a ne autor Ilijade.","D":"Hesiod je grčki didaktički pjesnik, a ne autor Ilijade."},
  "2011_zima_B__17": {"A":"Ilijada nije nastala u babilonsko-asirskoj književnosti, nego u grčkoj.","B":"Ilijada nije djelo staroegipatske književnosti.","D":"Ilijada pripada grčkoj, a ne rimskoj antičkoj književnosti; rimska je npr. Eneida."},
  "2011_zima_B__18": {"A":"Latinski je jezik rimske književnosti (npr. Eneide), a ne Ilijade.","C":"Ilijada nije napisana hebrejskim, nego starogrčkim jezikom.","D":"Sumerski je jezik mezopotamske književnosti (Ep o Gilgamešu), a ne Ilijade."},
  "2011_zima_B__19": {"B":"Poema je novovjekovna lirsko-epska vrsta, a Ilijada je klasični junački ep.","C":"Mit je predaja o bogovima i junacima, a Ilijada je književno oblikovani ep, ne mit.","D":"Tragedija je dramska vrsta, a Ilijada je narativni ep."},
  "2011_zima_B__20": {"A":"Prijam nije bog, nego smrtnik, trojanski kralj.","B":"Utemeljitelj Rima je Romul (prema legendi), a ne Prijam.","D":"Prijam nije vrač, nego kralj Troje."},
  "2011_zima_B__21": {"B":"Prijam ne dolazi radi osvete, nego molećiv, da otkupi sinovo tijelo.","C":"Prijam ne dolazi uhoditi neprijatelja, nego javno, kao otac koji moli za sina.","D":"Prijam ne dolazi sklopiti mir, nego osobno otkupiti Hektorovo tijelo."},
  "2011_zima_B__22": {"B":"Tekst ne govori da je Prijam nadmudrio neprijatelja, nego da je izgubio mnoge sinove.","C":"Nema podataka da je Prijam zaboravio svoje dužnosti.","D":"Nema spomena da se Prijam odrekao prijestolja."},
  "2011_zima_B__23": {"A":"Ahilej se ne rasplakao od straha pred Prijamom, nego od sjećanja na oca i Patrokla.","B":"Plač nije izazvan grižnjom zbog ubijanja, nego osobnom tugom za ocem i prijateljem.","D":"Tekst ne navodi spoznaju o vlastitoj smrti kao razlog plača."},
  "2011_zima_B__24": {"A":"'Gvozdeno srce' ovdje ne znači bešćutnost, nego iznimnu hrabrost da se uđe u neprijateljev logor.","B":"Izraz se ne odnosi na domišljatost, nego na hrabrost.","C":"Izraz ne govori o gubitku razuma, nego o smionosti."},
  "2011_zima_B__25": {"A":"Ahilej nije licemjeran (prijetvoran); iskreno suosjeća, prima starca za ruku i žali ga.","C":"Ahilej se ne ponaša bahato, nego s poštovanjem prema starcu.","D":"Ahilej nije suzdržan; aktivno tješi Prijama i pomaže mu ustati."},
  "2011_zima_B__26": {"A":"Ahilej ne govori općenito o životu punom tuge, nego konkretno o uzaludnosti plakanja.","B":"Ahilej ne tvrdi da upravlja sudbinom, nego priznaje da plač ništa ne mijenja.","D":"Ahilej ne poziva na hrabrost, nego na smirivanje plača jer ne pomaže."},
  "2011_zima_B__27": {"A":"'Ahejske' uz 'lađe' ne dolazi stalno uz tu imenicu kao ustaljena oznaka, pa nije stalni epitet.","C":"'Strahoviti plač' je trenutni opisni epitet, a ne ustaljena oznaka uz imenicu.","D":"'Čitav' je samo količinska oznaka, a ne stalni (ukrasni) epitet."},
  "2011_zima_B__28": {"B":"Beowulf je srednjovjekovni staroengleski ep, a ne djelo antike.","C":"Hamlet je djelo renesanse (Shakespeare), a ne antike.","D":"Don Quijote je renesansni roman (Cervantes), a ne antičko djelo."},
  "2011_zima_B__29": {"A":"'Ahilova peta' ne znači puko ozlijeđeno mjesto, nego prenosivo slabu, ranjivu točku.","B":"Frazem ne znači cilj, nego ranjivost.","D":"Frazem ne znači podvalu ni lukavstvo, nego slabost."},
  "2011_zima_B__30": {"A":"Grga nije Pavlov brat; on je samostalan negativac, brijač i spletkar.","C":"Grga nije svećenik koji se kaje, nego intrigant bez moralna preokreta.","D":"Grga je književni izmišljeni lik, a ne povijesna ličnost."},
  "2011_zima_B__31": {"A":"Lik nije izgrađen pripovijedanjem o radnji, nego izravnim opisom njegove vanjštine.","C":"U ulomku nema unutarnjega monologa kojim bi se otkrivale junakove misli.","D":"Premda dijaloga ima, lik je karakteriziran ponajprije opisom izgleda, a ne dijalogom."},
  "2011_zima_B__32": {"A":"Lik nije prikazan idealizirano (uljepšano), nego pretjerano negativno.","C":"Opis je vanjski i pretjeran, a ne psihološki produbljen.","D":"Riječ je o pretjeranom, grotesknom portretu, a ne o povijesnoj autentičnosti."},
  "2011_zima_B__33": {"A":"Tekst ne objašnjava da su osobine uvjetovane podrijetlom; o podrijetlu se ne govori.","B":"O Grginu podrijetlu tekst ne donosi podatke, pa to nije ono što saznajemo.","C":"O Grginoj prošlosti tekst ne govori; iznosi izgled i karakter, a ne biografiju."},
  "2011_zima_B__34": {"A":"Grga nije zabrinut, nego ogorčen i nezadovoljan zbog Dorina odbijanja.","C":"Grga nije ushićen; njegov je ton gorak i pakostan.","D":"Grga nije uspaničen, nego prkosno i zlovoljno govori o Dori."},
  "2011_zima_B__35": {"A":"Grga ne tvrdi da je Dora nespretna i razmažena, nego da teži boljemu društvenom položaju.","B":"Grga ne misli na Dorinu želju za financijskom neovisnošću, nego za boljom udajom.","D":"Grga ne kaže da je Dora lijena; tvrdi da želi gospodstvo i bogatstvo."},
  "2011_zima_B__36": {"A":"Grga se predstavlja kao skroman, ali njegov govor otkriva suprotno, pa to nije prava značajka.","B":"Grga se prikazuje poštenim, no zapravo je pokvaren; moralnost je samo glumljena.","D":"Iz obraćanja ne izbija razmetljivost, nego prikrivena pokvarenost i spletkarenje."},
  "2011_zima_B__37": {"B":"Rečenica o puščanu prahu govori o crvenilu nosa, a ne o Grginu zanimanju.","C":"'Suhonjast trčuljak' opisuje građu tijela, a ne zanimanje.","D":"'Mene i moju bokčariju odbila' govori o odbijanju i siromaštvu, a ne o zanimanju."},
  "2011_zima_B__38": {"B":"Razgovor nije tješenje; nitko se ne tješi, nego se Dora negativno ocrtava.","C":"Razgovor nije šala; ton je zajedljiv i pakostan, a ne šaljiv.","D":"Nije riječ o svađi među sugovornicima, nego o slaganju u ogovaranju Dore."},
  "2011_zima_B__39": {"A":"Žene ne izriču žaljenje za Dorom, nego zlurado komentiraju vijest.","B":"Nema suosjećanja prema Dori; reakcija je podrugljiva.","D":"Žene nisu ogorčene; one se zlurado naslađuju, što potvrđuje 'zajedljivo'."},
  "2011_zima_B__40": {"A":"Naslov se ne odnosi na Zagreb, nego na zlatarovu kćer Doru kao dragocjenost.","B":"'Zlato' nije metafora slobode, nego osobe, Dore.","C":"Naslov se ne odnosi na bana, nego na Doru."},
  "2011_zima_B__41": {"A":"Šenoa ne pripada prosvjetiteljstvu (18. st.), nego drugoj polovici 19. stoljeća.","B":"Šenoa stvara nakon narodnoga preporoda; preporod je vremenski raniji.","D":"Šenoa pripada protorealizmu, prijelaznom razdoblju, a puni realizam nastupa nakon njega."},
  "2011_zima_B__42": {"A":"Ujednačivanje grafije (slovopisa) zasluga je Gajeva, a ne Šenoina.","C":"Šenoa nije pokrenuo prve hrvatske književne novine; uređivao je Vijenac, ali to nisu prve novine.","D":"Šenoina zasluga nije mecenstvo, nego stvaranje čitateljske publike svojim romanima."},
  "2011_zima_B__43": {"A":"Tvrdnja da su intriganti uvijek stranci ne odgovara Šenoinu načelu; Grga je domaći lik.","B":"Nisu svi likovi simboli povijesnih ličnosti; mnogi su izmišljeni.","D":"Tvrdnja da je povijest tek kulisa proturječi Šenoinoj namjeri da povijest poučno istakne."},
  "2011_zima_B__44": {"A":"Djelo nije lirsko jer nije pjesma osobnoga doživljaja, nego scenski tekst.","B":"Djelo nije epsko jer nema pripovjedača i naracije, nego dijaloge i didaskalije."},
  "2011_zima_B__45": {"A":"Glembaya ne muči savjest; on napada sina, a ne kaje se.","C":"Glembay nije ushićen, nego razdražen i napet.","D":"Glembay nije ravnodušan; ironično i ljutito reagira na sina."},
  "2011_zima_B__46": {"A":"Odnos nije prijateljski; otac i sin se sukobljavaju i ne slušaju.","B":"Odnos nije poslovni; Leone izrijekom odbija poslovni okvir ('ne mislim juridički').","D":"Nije naglašeno suparništvo (borba za isti cilj), nego međusobno nerazumijevanje pogleda."},
  "2011_zima_B__47": {"B":"Glembay ne hvali svoj odgoj sina; rečenicom prigovara da je Leone naslijedio majčinu narav.","C":"Glembay ne ističe utjecaj inozemstva, nego majčino podrijetlo (daniellijevsko).","D":"Rečenica ne govori o Leoneovu nerazumijevanju očeve ljubavi, nego o sličnosti s majkom."},
  "2011_zima_B__48": {"A":"Ton nije sentimentalan jer nema raznježenosti, nego oštre podrugljivosti.","C":"Ton nije patetičan (uzvišeno svečan), nego ironično-sarkastičan.","D":"Ton nije ushićen; Glembay ne hvali aroganciju iskreno, nego je ismijava."},
  "2011_zima_B__49": {"A":"Pojmovi nisu homonimi jer im se ni oblik ni značenje ne podudaraju.","C":"Pojmovi nisu sinonimi jer ne znače isto, nego su suprotstavljeni (boemi prema solidnim građanima)."},
  "2011_zima_B__50": {"A":"Vratima se ne pridaju ljudske osobine, pa nema personifikacije.","C":"Nema preuveličavanja radi dojma, pa nije hiperbola.","D":"Izraz nije simbol s prenesenim trajnim značenjem, nego ublažavanje grube poruke."},
  "2011_zima_B__51": {"A":"Leone ne optužuje suprugu za propast banke, nego za ljubavnu nevjeru.","B":"Leone je ne optužuje za smrt svoje majke, nego da ima ljubavnika.","C":"Riječ nije o nečasnim novčanim poslovima, nego o ljubavniku."},
  "2011_zima_B__52": {"B":"Leone se ne bavi glazbom, nego slikarstvom.","C":"Leone nije književnik, nego slikar.","D":"Leone nije novinar, nego slikar."},
  "2011_zima_B__53": {"A":"Grof Maksimilijan Axelrode nije Krležin lik koji se vraća kući nakon duga izbivanja.","B":"Student Vidović nije lik koji se vraća iz dugoga izbivanja poput Filipa Latinovicza.","C":"Kyriales nije lik koji se vraća kući nakon duga izbivanja iz Europe."},
  "2011_zima_B__54": {"A":"Djelo nije nastalo početkom 19. st., nego 1929. godine.","B":"Djelo nije nastalo krajem 19. st., nego u prvoj polovici 20. stoljeća.","D":"Djelo nije nastalo krajem 20. st., nego 1929. godine."},
  "2011_zima_B__55": {"A":"Vučjak i Golgota nisu dio glembajevske trilogije.","B":"Kraljevo i Legende ne pripadaju glembajevskom ciklusu.","D":"Aretej i Michelangelo Buonarroti nisu dio glembajevske trilogije."},
  "2011_zima_B__56": {"A":"Prolog je uvodni dio djela, a ovdje je riječ o scenskoj uputi unutar teksta.","B":"Epilog je završni dio djela, a kosi je tekst scenska uputa, ne epilog.","D":"Replika je izgovoreni iskaz lika, a kosi tekst nije za izgovaranje, nego uputa."},
  "2011_zima_B__57": {"B":"Nije dativ; uz prijedlog 'spram' ne dolazi dativ, nego genitiv.","C":"Nije akuzativ; oblik 'oca' uz 'spram' odgovara na pitanje koga (genitiv).","D":"Nije lokativ; lokativ dolazi s drugim prijedlozima (o, u, na, po, pri)."},
  "2011_zima_B__58": {"A":"'grčka načina' nije ispravno jer pridjev mora biti u genitivu jednine muškoga roda (grčkoga).","C":"'grčkijega' nije standardni oblik genitiva pridjeva 'grčki'.","D":"'grčki načina' nije ispravno jer pridjev nije u genitivu, nego u nominativu."},
  "2011_zima_B__59": {"B":"Riječ ne potječe iz njemačkoga, pa nije germanizam.","C":"Riječ ne potječe iz mađarskoga, pa nije hungarizam.","D":"Riječ ne potječe iz turskoga, pa nije turcizam."},
  "2011_zima_B__60": {"A":"Rečenica nema dvije, nego tri surečenice, jer ima tri predikata.","C":"Rečenica nema četiri surečenice; predikata je tri.","D":"Rečenica nema pet surečenica; predikata je tri."},
  "2011_zima_B__61": {"A":"'Tamna' je antonim pridjevu 'svijetla', a ne pridjevu 'mutna'.","B":"'Svijetla' je suprotnost 'tamna', a ne 'mutna'.","D":"'Nejasna' je sinonim, a ne antonim pridjevu 'mutna'."},
  "2011_zima_B__62": {"B":"Nije kondicional drugi jer nedostaje 'bio' (bio bi želio); ovdje je samo 'bi + željio'.","C":"Nije futur prvi jer se ne tvori s 'ću, ćeš...', nego se rabi 'bi'.","D":"Nije futur drugi jer se ne tvori od prezenta glagola 'biti' i glagolskoga pridjeva radnog na način futura."},
  "2011_zima_B__63": {"A":"Nije palatalizacija jer se g ne mijenja u ž ispred -e, nego u z ispred -i.","C":"Nije jotacija jer nema spajanja sa glasom j.","D":"Nije nepostojano a jer se nijedno a ne gubi ni umeće."},
  "2011_zima_B__64": {"A":"'Očinska' se odnosi na oca, a 'familijarna' se odnosi na cijelu obitelj.","B":"'Prijateljska' nije značenje pridjeva 'familijaran' u ovom kontekstu obitelji.","C":"'Društvena' je šira od značenja 'obiteljski', pa ne odgovara kao sinonim."},
  "2011_zima_B__65": {"A":"Nije genitiv; uz prijedlog 'pred' ne dolazi genitiv, nego instrumental.","B":"Nije dativ; 'pred' ne traži dativ, nego instrumental.","C":"Nije akuzativ; oblik 'Silberbrandtom' odgovara na pitanje pred kim (instrumental)."},
  "2011_zima_B__67": {"B":"'Buzetskoj' velikim slovom nije ispravno jer se pridjevi izvedeni od mjesnih imena pišu malim slovom."},
  "2011_zima_B__68": {"A":"'Ljevo' nije standardno; standardni ijekavski oblik glasi 'lijevo'."},
  "2011_zima_B__69": {"B":"'Glagoljaštva' velikim slovom nije ispravno jer je riječ o općem pojmu, a ne vlastitom imenu."},
  "2011_zima_B__70": {"A":"'Srednjo vjekovne' rastavljeno nije ispravno jer se taj složeni pridjev piše spojeno."},
  "2011_zima_B__71": {"B":"'Korjene' nije standardno; ijekavski oblik glasi 'korijene' (ije)."},
  "2011_zima_B__72": {"B":"'Moravskim' velikim slovom nije ispravno jer je riječ o opisnom pridjevu, koji se piše malim slovom."},
  "2011_zima_B__73": {"B":"'Sveto pismo' s malim 'p' nije po pravilu za naziv svete knjige, koji se piše velikim slovom (Sveto Pismo)."},
  "2011_zima_B__74": {"A":"'Spomen obilježje' bez crtice nije ispravno jer se složenice sa 'spomen-' pišu s crticom."},
  "2011_zima_B__75": {"B":"'Poćinje' nije ispravno jer u toj riječi stoji glas č, a ne ć (počinje)."},
  "2011_zima_B__76": {"B":"'Svijetskih' nije standardni oblik; ispravno je 'svjetskih' (od 'svijet')."},

  // 2012_jesen_A
  "2012_jesen_A__1": {"A":"Tekst ne govori o pokornosti naroda, nego o njegovoj sklonosti zabavi i površnosti.","B":"Podmitljivost se u ulomku ne spominje; naglasak je na vezanosti naroda uz 'igračke' i zabavu.","C":"Veselje promjenama nije tema; usporedba s djecom isticanje je sklonosti razonodi, a ne novini."},
  "2012_jesen_A__2": {"A":"Ruganje narodu ne proizlazi iz tih riječi; one su upućene Bogu i izražavaju poniznost.","C":"Obraćanje 'vječni, silni, svemožni' veliča Boga, pa nema ironije, nego štovanja.","D":"O izdaji naroda nema traga; Mojsije se ponizno moli, a ne izdaje."},
  "2012_jesen_A__3": {"B":"Zlatno tele upravo svjedoči o velikim, krivim prohtjevima naroda, a ne o njihovu izostanku.","C":"Tele se podiže kao idol, nije sredstvo obmane Boga, nego znak odvraćanja od njega.","D":"Riječ je o idolopoklonstvu, a ne o pravoj žrtvi Bogu ('a ne Jehovu')."},
  "2012_jesen_A__4": {"A":"Iako ima modernih elemenata, Kranjčević se primarno svrstava u realizam, a ne u modernu.","B":"Protorealizam prethodi Kranjčevićevu razdoblju i ne obuhvaća njegov opus.","D":"Romantizam je ranije razdoblje; Kranjčević (1865.–1908.) djeluje u doba realizma."},
  "2012_jesen_A__5": {"A":"Osmerac ima osam slogova, a stihovi ovog teksta broje deset.","C":"Jedanaesterac ima jedanaest slogova, što ne odgovara broju slogova u stihu.","D":"Dvanaesterac ima dvanaest slogova, dok stih 'Al ono narod, božja odlika' ima deset."},
  "2012_jesen_A__6": {"A":"Boja se kao zajedničko obilježje zraka i stabala u tekstu ne ističe.","B":"Stablima se pripisuje 'izgubljena snaga', dakle nemoć, a ne snaga.","D":"Vlaga se vezuje samo uz zrak ('pun čudnovate vlage'), nije zajednička stablima."},
  "2012_jesen_A__7": {"A":"Aliteracija je ponavljanje suglasnika, a ovdje se ponavlja samoglasnik e.","B":"Anafora je ponavljanje riječi na početku stihova, što se u naslovu ne događa.","D":"Epifora je ponavljanje na kraju stihova; riječ je o glasovnoj figuri u naslovu, asonanci."},
  "2012_jesen_A__8": {"A":"'Tromi' stoji ispred imenice (uobičajen red riječi), pa nije inverzija.","B":"'Čudnovate' također prethodi imenici 'vlage', dakle bez obrnuta reda.","D":"'Vraški' dolazi ispred imenice 'vrabac', što je normalan poredak, a ne inverzija."},
  "2012_jesen_A__9": {"A":"Prvi stih ritmički pripada skupini koja se ne razlikuje od ostalih triju.","B":"Drugi stih dijeli ritmičku osobinu s većinom, pa nije iznimka.","C":"Treći stih po vrsti stiha odgovara prvomu i drugomu, a razlikuje se četvrti."},
  "2012_jesen_A__10": {"A":"'Majstore, ugasi svijeću' napisao je Slavko Mihalić, a ne Ujević.","B":"'More' nije Ujevićeva pjesma navedena kao prepoznatljiva za njegov opus.","C":"'Opomena' je djelo A. B. Šimića, ne Tina Ujevića."},
  "2012_jesen_A__11": {"B":"Pripovjedač jest svjedok i 'dionik znatan' događaja, pa zna što se dogodilo.","C":"Ne radi se o strahu od priznanja krivnje, nego o bolnu sjećanju ('sjećanja žaca').","D":"Iako je zora, razlog nevoljkosti nije pospanost, nego bol prisjećanja."},
  "2012_jesen_A__12": {"A":"Danajci su neprijatelji koji su 'satrli kraljevstvo trojansko', pa im pripovjedač ne pripada.","B":"Dolopci se spominju kao oni koji bi suosjećali, ali Eneja im ne pripada.","C":"Mirmidonci su grčki ratnici; Eneja je Trojanac, branitelj Troje."},
  "2012_jesen_A__13": {"A":"'Žacati se' ne znači izgubiti se, nego zazirati, groziti se.","B":"Riječ ne izriče razočaranje, nego strah i odbojnost prema sjećanju.","C":"Ne radi se o uzbuđenju, nego o jezi i užasavanju pri prisjećanju jada."},
  "2012_jesen_A__14": {"A":"Zavjet za sretan povratak samo je lažna izlika ('Razglase laž'), a ne pravi razlog.","B":"Konj je sagrađen 's pomoću Palade', ali cilj nije njezino udobrovoljavanje.","C":"Danajci su trojanski neprijatelji; ne grade konja da sačuvaju Troju, nego da je osvoje."},
  "2012_jesen_A__15": {"A":"Ahilej je grčki junak, ali Uliks je latinsko ime za Odiseja, ne za Ahileja.","B":"Eneja je trojanski junak i pripovjedač; nije isto što i Uliks.","D":"Paris je trojanski kraljević; Uliks je latinski oblik imena Odisej."},
  "2012_jesen_A__16": {"A":"Eneja je junak Eneide, a ne Danteov vodič nazvan 'meštrom'.","B":"Homer nije lik koji vodi Dantea kroz Pakao; to je Vergilije.","C":"Odisej (Uliks) nije Danteov vodič; 'meštar' je Vergilije."},
  "2012_jesen_A__17": {"A":"Plač je posljedica patnje grešnika, ali sama muka kojoj su izloženi jest vjetar.","B":"Uzdasi su izraz boli, a ne kazna; grešnike u ovom krugu nosi snažan vjetar.","C":"'Crni uzduh' upućuje na vjetar koji ih tuče, a ne na neugodan dah kao muku."},
  "2012_jesen_A__18": {"B":"Premda se spominju žene, povezuje ih ljubavni grijeh, a ne okrutnost.","C":"Nekrštene duše smještene su u prvi krug (limb), ne u ovaj.","D":"Iako su među njima i vladari, kažnjeni su zbog bludne ljubavi, a ne kao zli vladari."},
  "2012_jesen_A__19": {"A":"Ahilej je junak među grešnicima, ali nije vladao mnoštvom naroda.","B":"Didona se ubila zbog ljubavi, no nije ona 'carica nad mnoštvom raznih jezika'.","C":"Jelena je uzrok jada, ali opis carice koja vlada raznim narodima odnosi se na Semiramidu."},
  "2012_jesen_A__20": {"A":"Dante ne dolazi do njih na ždralovima; ždrali su samo poredbena slika za sjene.","B":"Grešnici nisu mrtvi ispred Dantea, nego su sjene koje vjetar nosi mimo njega.","D":"Sugovornik (Vergilije) ih ne dovodi; sjene same promiču nošene vjetrom."},
  "2012_jesen_A__21": {"A":"Izraz ne označuje preneseno značenje, nego oskudnost djela na hrvatskom jeziku.","C":"Latinska djela predstavlja vila Latinka s mnogo jabuka, dok Hrvatica ima 'malo jabučic'.","D":"Nije riječ o dalekoj prošlosti, nego o malobrojnosti hrvatskih književnih djela."},
  "2012_jesen_A__22": {"B":"Vila se ne žali na odnos prema antičkoj baštini, nego na nemar prema hrvatskom jeziku.","C":"Alegoričnost nije predmet njezine tužbe; tuži se na 'nepomnju i nehaj' jezika hrvatskoga.","D":"O izboru tema nema riječi; pritužba se odnosi na zapostavljanje hrvatskoga jezika."},
  "2012_jesen_A__23": {"A":"'Gizdati se' ne znači uljepšavati se, nego ponositi se.","B":"Glagol ne znači mirisati; jabuke su mirisne, ali vila se njima 'gizda', tj. ponosi.","D":"Značenje je suprotno sramljenju; Kaldejka se diči i ponosi jabukama."},
  "2012_jesen_A__24": {"A":"Ep je opsežno stihovano djelo, a Planine su prozno-stihovno djelo, prvi hrvatski roman.","B":"Poema je veće lirsko-epsko stihovano djelo, što Planine nisu.","C":"Planine nisu pripovijetka, nego (pastirski) roman."},
  "2012_jesen_A__25": {"A":"Barok slijedi nakon renesanse; Zoranić djeluje u 16. stoljeću, dakle u renesansi.","B":"Klasicizam je kasnije razdoblje i ne obuhvaća Zoranićevo stvaralaštvo.","D":"Srednji vijek prethodi renesansi; Planine su renesansno djelo (1569.)."},
  "2012_jesen_A__26": {"B":"U registraturi je Kovačićev roman, a lik koji se vraća majci jest Filip Latinovicz iz Krležina djela.","C":"Combray je Proustovo djelo, no opisani povratak majci pripada Krležinu romanu.","D":"Stranac je Camusov roman; ovdje je riječ o Krležinu Povratku Filipa Latinovicza."},
  "2012_jesen_A__27": {"A":"Svijet iz kojeg se lik vraća šire je značenje; sintagma se odnosi na konkretne sumještane.","C":"Sintagma ne označuje djetinjstvo, nego ljude iz sredine koji ga promatraju i osuđuju.","D":"Majka je poseban lik; 'svračji zakutak' odnosi se na okolinu, sumještane."},
  "2012_jesen_A__28": {"A":"Riječ je o unutarnjem monologu, a ne o izravnom obraćanju majci.","B":"Usklici ne znače glasan govor, nego unutarnju uzburkanost lika.","C":"Odlučnost nije razlog; usklici izražavaju Filipovu uznemirenost i ogorčenost."},
  "2012_jesen_A__29": {"A":"Majka mu ne zamjera izbivanje, nego druženje s 'nemoralnim osobama'.","B":"Bezosjećajnost mu se ne predbacuje; prigovara mu se nedolično društvo.","D":"Predanost vjeri nije tema majčina prigovora; smeta joj kompromitirajuće društvo."},
  "2012_jesen_A__30": {"A":"Sin majci ne zamjera bogatstvo, nego njezino licemjerno moralno ograđivanje.","B":"Glupost nije predmet prigovora; zamjera joj prividan, lažan moral.","D":"O nasljeđu nema riječi; sin razotkriva majčino licemjerje."},
  "2012_jesen_A__31": {"A":"Likovi nisu ožalošćeni; razgovaraju o povoljnim izgledima za budućnost.","B":"Uzbuđenost nije njihovo stanje; raspoloženje je smireno i optimistično.","C":"Nisu zabrinuti, nego zadovoljni jer 'izgledi nipošto nisu loši'."},
  "2012_jesen_A__32": {"A":"Gregor je u tom trenutku već mrtav, pa ne može biti dio 'svega troje'.","C":"'Sve troje' uključuje i majku; ovdje su izostavljena gospođa Samsa.","D":"Gospodin Samsa (otac) dio je obitelji koja preživljava; Gregor je mrtav, pa raspored nije točan."},
  "2012_jesen_A__33": {"A":"Stan ne oduzima Gregorova tvrtka; obitelj ga sama mijenja zbog troškova.","B":"Razlog nije premalen stan, nego previsoka cijena ('manji i jeftiniji').","D":"Uspomene nisu motiv preseljenja, nego financijska neisplativost dosadašnjega stana."},
  "2012_jesen_A__34": {"B":"Gregor jest svjestan svoje preobrazbe, ali isprva ne shvaća njezinu težinu.","C":"Gregor ne optužuje roditelje, nego brine kako će obaviti svoje obveze.","D":"Gregor ne napušta obitelj; ostaje u stanu i postupno biva odbačen."},
  "2012_jesen_A__35": {"A":"'Jedra' ne znači mlada, nego stasita, bujna.","B":"Pridjev ne upućuje na rumenu boju, nego na stasitost.","D":"Značenje nije živahnost, nego tjelesna razvijenost i bujnost."},
  "2012_jesen_A__36": {"A":"Hipolit u prvoj strofi ne osjeća gnjev, nego stid zbog vlastite besposlenosti.","C":"Tjeskoba nije osjećaj prve strofe; on 'crveni' od srama što planduje.","D":"Osamljenost nije naglašena; Hipolit izražava posramljenost zbog lijenosti."},
  "2012_jesen_A__37": {"A":"U ovom ulomku bijeg od Fedre nije iskazan razlog odlaska, nego potraga za ocem.","C":"Iako spominje dosadu, pravi povod odlasku jest neizvjesnost o očevoj sudbini.","D":"Hipolit ne traži pustolovinu, nego želi saznati što je s ocem ('šest mjeseci... ne čujem')."},
  "2012_jesen_A__38": {"A":"Fedra Hipolitu nije ljubavnica; ona je žena njegova oca, dakle pomajka.","C":"Fedra nije Hipolitova supruga, nego supruga njegova oca Tezeja.","D":"Fedra mu nije zaručnica, nego maćeha (pomajka)."},
  "2012_jesen_A__39": {"B":"Tezejeva lutanja nisu označena kao 'mladenački grijesi'; riječ je o ljubavnim pustolovinama.","C":"Osvajački pohodi nisu predmet ovih grijeha; misli se na njegove brojne ljubavi.","D":"Laži se ne navode kao njegovi grijesi; karakteriziraju ga ljubavne nevjere ('otprhuje ko ptica')."},
  "2012_jesen_A__40": {"A":"Hipolit se ne osjeća kao junak, nego upravo kao sužanj pri odlasku.","B":"Usporedba s prorokom u tekstu ne postoji; on odlazi 'ko sužanj'.","D":"Hipolit se ne doživljava kao vladar, nego kao rob ('ko sužanj')."},
  "2012_jesen_A__41": {"A":"Stipančići nisu riječka, nego senjska patricijska obitelj.","C":"Radnja romana nije smještena u Split; riječ je o senjskoj obitelji.","D":"Obitelj Stipančić nije zadarska, nego senjska."},
  "2012_jesen_A__42": {"A":"Ekspresionizam nije primarno društveno-analitički usmjeren kao realizam.","B":"Impresionizam naglašava dojam i trenutni doživljaj, a ne socijalnu analizu.","D":"Romantizam ističe osjećaje i subjektivnost, a ne društvenu analizu socijalnih suprotnosti."},
  "2012_jesen_A__43": {"A":"Dadaizam se temelji na provokaciji i besmislu, a opis se odnosi na psihički automatizam (nadrealizam).","B":"Ekspresionizam izražava unutarnju napetost i emociju, a ne 'čisti psihički automatizam'.","C":"Futurizam slavi pokret, brzinu i tehniku, što ne odgovara definiciji nadrealizma."},
  "2012_jesen_A__44": {"A":"Opisana vrsta (uz glazbu i balet) jest opera/spektakl, a ne ditiramb.","B":"Stihovana pripovjedna vrsta s lirskim ugođajem jest balada, a ne ditiramb.","C":"Slavljenje bogova i heroja općenitije je obilježje hvalospjeva; ditiramb je vezan uz Dioniza."},
  "2012_jesen_A__45": {"A":"Anadiploza je ponavljanje kraja stiha na početku idućega, čega ovdje nema.","B":"Asindeton je nizanje bez veznika, a ovdje se veznik 'i' upravo višestruko ponavlja.","C":"Epifora je ponavljanje na kraju stihova, a riječ je o nagomilavanju veznika (polisindeton)."},
  "2012_jesen_A__46": {"A":"Deus ex machina označuje iznenadno raspletno rješenje, a ne oponašanje stvarnosti.","B":"In medias res znači započinjanje radnje 'usred stvari', što nije isto što i mimesis.","D":"Quid pro quo označuje zamjenu jednoga drugim (zabunu), a ne oponašanje stvarnosti."},
  "2012_jesen_A__47": {"A":"Ditirambom se Marcijal nije proslavio; on je majstor epigrama.","C":"Epitaf je natpis na grobu, a Marcijal je poznat po epigramima.","D":"Oda je svečana pohvalna pjesma; Marcijala proslavljaju epigrami."},
  "2012_jesen_A__48": {"A":"Tvrdnja o Ribanju ne odnosi se na Džoru Držića, nego na Hektorovića.","B":"Hanibal Lucić autor je Robinje i Jur nijedna na svit vila, a ne Ribanja s bugaršticama.","D":"Petar Zoranić napisao je Planine; Ribanje i ribarsko prigovaranje djelo je Hektorovićevo."},
  "2012_jesen_A__49": {"A":"Polazak od racionalizma i etičkog vrednovanja postupaka obilježje je klasicizma, ne romantizma.","B":"Biološke motivacije, velegrad i socijalno zlo obilježja su naturalizma/realizma, ne romantizma.","D":"Jasnoća ideja i staleški određeni likovi s moralističkom svrhom obilježja su klasicizma."},
  "2012_jesen_A__50": {"B":"Eugène Ionesco predstavnik je teatra apsurda, a ne tvorac epskog kazališta.","C":"Luigi Pirandello poznat je po metateatru, a ne po epskom kazalištu.","D":"Samuel Beckett pripada teatru apsurda; epsko kazalište utemeljio je Brecht."},
  "2012_jesen_A__51": {"B":"Šenoa je realist (C), a ne protorealist (B), pa raspored 1B nije točan.","C":"Gjalski pripada realizmu (C), a ne moderni; oznaka 5B je netočna.","D":"Šimunović pripada moderni (A), a ne realizmu (C), pa je 2C pogrešno."},
  "2012_jesen_A__52": {"B":"Ekvinocij je drama (A), a ne novela (B), pa je 2B netočno; i Misao na vječnost je novela (B), ne roman (A).","C":"Koraljna vrata su novela (B), a ne drama (A), pa raspored 3A nije točan.","D":"Bijeg je roman (C), a ne novela (B); oznaka 1B je pogrešna."},
  "2012_jesen_A__53": {"A":"U imperfektu (npr. 'pecijah') ne dolazi do palatalizacije k→č.","C":"U 3. l. jd. prezenta ('peče') provedena je sibilarizacija/jotacija, a tražena palatalizacija je u imperativu 'peci'.","D":"U 3. l. mn. prezenta ('peku') glas k ostaje nepromijenjen, dakle nema palatalizacije."},
  "2012_jesen_A__54": {"A":"U 'naseljen' nema epentetskog l; l pripada osnovi (selo/naseliti).","B":"U 'nasoljen' također nema umetnutoga l; l je dio osnove (sol/nasoliti).","D":"U 'nazubljen' javlja se epentetsko (umetnuto) lj (zub+jen→zubljen), pa nije tražena riječ s 'l' u istom smislu kao 'nauljen'."},
  "2012_jesen_A__55": {"A":"Sastavnica 'ultra-' piše se spojeno s pridjevom; razmaci i crtica ovdje su pogrešni.","B":"Crtica između 'ultra' i 'ljubičastom' nije ispravna; riječ je o jednoj složenici.","C":"Pisanje s razmakom nije pravilno jer je 'ultraljubičast' jedna riječ."},
  "2012_jesen_A__56": {"A":"Pridjev se ne piše rastavljeno ('new yorški'), nego spojeno: 'newyorški'.","B":"Pridjev se piše malim početnim slovom, pa je 'Newyorški' netočno.","D":"U standardu se zadržava izvorni zapis osnove, pa je 'njujorški' neprihvatljiv oblik."},
  "2012_jesen_A__57": {"A":"'Pis' jest dio korijena, ali korijenski morfem riječi jest cjeloviti 'spis'.","C":"'Pisa' nije korijenski morfem; korijen je 'spis'.","D":"'Spisatelj' je tvorbena osnova, ali korijenski morfem je samo 'spis'."},
  "2012_jesen_A__58": {"A":"'Bilje' je imenica s nastavkom -e u N jd., dakle nema nultoga morfema.","B":"'Pluća' u N mn. ima nastavak -a, pa nema nultoga gramatičkog morfema.","D":"'Škare' u N mn. završavaju nastavkom -e, dakle nije nulti morfem."},
  "2012_jesen_A__59": {"A":"'Žiri' je nepromjenljiva strana imenica, pa oblik 'žirijevi' nije pravilan.","B":"Oblik 'žiriji' također je nepravilan jer 'žiri' ostaje nepromijenjen.","C":"Oblik 'žirii' nije ispravan; imenica 'žiri' ne dobiva nastavke."},
  "2012_jesen_A__60": {"B":"Oblik 'obijestniji' nije pravilan jer se 't' u komparativu ne zadržava ('obijesniji').","C":"'Objesniji' je nepravilno jer izostavlja 'ij' iz osnove ('obijes-').","D":"'Objestniji' spaja dvije pogreške (i izostavljen 'ij' i suvišno 't')."},
  "2012_jesen_A__61": {"A":"'Prekrasna' (glasa) neodređeni je oblik pridjeva, a ne određeni.","B":"'Očevu' je posvojni pridjev neodređena oblika, ne određeni.","C":"'Zabavan' je neodređeni oblik pridjeva u imenskom predikatu."},
  "2012_jesen_A__62": {"A":"U izravnom obraćanju s 'vama' uobičajenija je povratno-posvojna ('svojim'); 'vašim' je ovdje neprikladno.","B":"U pitanju upućenu sugovorniku posvojna 'vaše' stilski je suvišna umjesto 'svoje'.","D":"U imperativnu obraćanju 'Otvorite vaše' nepravilno je; trebalo bi 'svoje' (čitanke)."},
  "2012_jesen_A__63": {"A":"Glagolski prilog od 'klicati' glasi 'kličući', a ne 'klićući'.","C":"Od 'skakati' prilog je 'skačući', pa je 'skaćući' nepravilno napisano.","D":"Od 'toptati' prilog je 'topćući' s pravopisno drukčijim odnosom; ovdje je 'mićući' ispravan oblik (od 'micati')."},
  "2012_jesen_A__64": {"A":"'Bijahu strugali' jest pluskvamperfekt, a ne imperfekt.","B":"'Su... bili strugali' također je pluskvamperfekt, ne imperfekt.","D":"'Strugaše' je oblik aorista (3. l. jd.), a ne imperfekta množine."},
  "2012_jesen_A__65": {"A":"Rečenica ima četiri, a ne tri surečenice (dvije zavisne 'da'-surečenice).","C":"Pet surečenica je previše; analizom se utvrđuju četiri.","D":"Šest surečenica nije točno; rečenica se dijeli na četiri dijela."},
  "2012_jesen_A__66": {"A":"U 'štrajk liječnika' imenica je nesročni atribut (genitiv), a ne dio predikata.","B":"U 'pregledao ga je liječnik' imenica je subjekt, ne predikat.","D":"U 'dobili su liječnika' imenica je objekt u akuzativu, a ne dio predikata."},
  "2012_jesen_A__67": {"A":"U 'Otac ga je posjetio' imenica 'otac' subjekt je, a ne neizravni objekt.","B":"U 'obradovao je oca' imenica je u akuzativu, dakle izravni objekt.","C":"U 'pokraj oca' imenica je dio priložne oznake (prijedložni izraz), ne neizravni objekt."},
  "2012_jesen_A__68": {"A":"'Iako nije bio umoran' izriče dopuštanje, dakle dopusna je rečenica.","B":"'Kako bi se odmorio' izriče namjeru, pa je namjerna rečenica.","D":"'Da se odmori' također izriče namjeru, a ne uzrok."},
  "2012_jesen_A__69": {"A":"Sufiks '-a' samo je završni nastavak, a tvorbeni sufiks je '-aonica'.","B":"'-ica' ne obuhvaća cijeli tvorbeni sufiks riječi 'kupaonica'.","C":"'-onica' nije potpun tvorbeni sufiks; uključen je i samoglasnik a ('-aonica')."},
  "2012_jesen_A__70": {"B":"'Ekspresionizam' je naziv pravca izveden od latinske osnove, a ne od vlastita imena, pa nije eponim.","C":"'Nijemac' je etnik (ime pripadnika naroda), a ne eponim.","D":"'Vukovarac' je etnik izveden od imena mjesta, dakle nije eponim u smislu riječi od osobnog imena."},
  "2012_jesen_A__71": {"B":"Zakonska odredba iz 1941. uređivala je čistoću i pravopis, ali ne predlaže ijekavsku štokavštinu kao zajedničku osnovu.","C":"Novosadski dogovor (1954.) propisuje zajednički jezik, ali nije dokument koji je tu osnovu prvi predložio (to je Bečki dogovor).","D":"Deklaracija iz 1967. brani samosvojnost hrvatskoga jezika, suprotno predlaganju zajedničke osnove."},
  "2012_jesen_A__72": {"A":"Antroponimi su imena ljudi, a 'Mrzla Vodica' ime je naselja.","C":"Hidronimi su imena voda; iako sadrži 'Vodica', riječ je o imenu naselja (ekonim).","D":"Oronimi su imena gora i uzvisina, a ne naselja."},

  // 2012_jesen_B
  "2012_jesen_B__1": {"A":"Tekst ne izražava ravnodušnost, nego snažnu sanjarsku čežnju za odlaskom.","B":"Životinje i priroda samo su dio slike čežnje, a ne tema pjesme.","D":"Naglasak nije na strahu, nego na privlačnosti dalekoga i nepoznatoga ('svijet će biti velik, čudan')."},
  "2012_jesen_B__2": {"A":"Auditivni podražaj vezan je uz zvukove (laje pas, rže konj), a ne uz grivu.","B":"Gustativni (okusni) podražaj u prikazu grive uopće se ne javlja.","C":"Olfaktivni (mirisni) podražaj nije vezan uz zlatnu grivu, koja se doživljava očima."},
  "2012_jesen_B__3": {"A":"Balkon se spominje tek na kraju kao mjesto mirovanja, a ne kao mjesto novog gledišta.","B":"Brod je predmet sanjarenja, a ne mjesto s kojega se mijenja pogled.","C":"Parobrod je tek motiv koji se vidi izdaleka, a ne polazište promjene gledišta."},
  "2012_jesen_B__4": {"A":"Anafora bi značila ponavljanje iste riječi na početku stihova, čega ovdje nema.","B":"Elipsa je izostavljanje dijela rečenice, a ovdje je rečenica cjelovita, samo prelazi u idući stih.","D":"Sinestezija bi spajala različita osjetila, što u ovim stihovima nije postupak."},
  "2012_jesen_B__5": {"A":"'Laje pas' izriče zvuk i daljinu, a ne nepokretnost ili nemogućnost promjene.","B":"'Jednu lastu' tek je dio prizora viđenog s tornja, bez značenja stagnacije.","C":"'Dim parobroda' upućuje na kretanje i odlazak, što je suprotno od nemogućnosti promjene."},
  "2012_jesen_B__6": {"B":"Helena ne govori o razočaranju Hektora, nego o vlastitu nedostojnu izboru muža.","C":"Tekst ne tematizira njezinu prijevaru muža, nego žaljenje zbog veze s nečasnim Aleksandrom.","D":"Helena ne govori da je razljutila Zeusa, nego da su joj bogovi odredili zlo."},
  "2012_jesen_B__7": {"A":"Krađa Ahilejeva štita nije Aleksandrov čin niti se spominje u tekstu.","B":"Prisvajanje Briseide vezano je uz Agamemnona i Ahileja, a ne uz Aleksandra.","C":"Patroklovo ubojstvo djelo je Hektora, a ne Aleksandra (Parisa)."},
  "2012_jesen_B__8": {"B":"Stih govori o pjesmama (pripovijedanju) o njima, a ne o rađanju potomstva.","C":"U stihu nema spomena zavisti, nego buduće pjesničke obrade njihove sudbine.","D":"Stih ne govori o zaštiti bogova, nego o tome da će postati predmet pjesama."},
  "2012_jesen_B__9": {"A":"Čestitost je moralna osobina, a 'stanovito' ovdje znači stalno i pouzdano, a ne čestito.","B":"Otvorenost nije značenje pridjeva 'stanovit', koji upućuje na postojanost.","C":"Plašljivost nije značenje 'stanovita srca'; riječ se odnosi na pouzdanost i stalnost."},
  "2012_jesen_B__10": {"A":"Agamemnon je Menelajev brat i vođa Grka, a ne Helenin muž.","B":"Ahilej je grčki junak, ali nije bio Helenin suprug.","D":"Patroklo je Ahilejev prijatelj, a ne Helenin muž."},
  "2012_jesen_B__11": {"A":"Treća strofa ne govori o potrebi za uvažavanjem, nego o gubitku i kajanju.","B":"Tekst ne tematizira neuzvraćenu ljubav, nego rasipan, bludom upropašten život.","C":"Lirski subjekt ne izražava želju za materijalnim, nego žali što ga je u bludu izgubio."},
  "2012_jesen_B__12": {"A":"Ravnodušnost je suprotna 'žalosti i kajanju' koje lirski subjekt jasno izriče.","C":"Radost ne odgovara tonu kajanja i tuge u stihovima.","D":"Ponos je u suprotnosti s priznanjem sramotnoga pada ('tko sam bio, tko sam sada')."},
  "2012_jesen_B__13": {"A":"Bludnost je grijeh lirskoga subjekta, a ne osobina kojom se prikazuje žena.","C":"Prevrtljivost nije naglašena; istaknuta je pohlepa za zlatom.","D":"Taština se ne pripisuje ženi, nego se kao njezino obilježje ističe pohlepa."},
  "2012_jesen_B__14": {"A":"Oktava ima osam stihova, a strofe ovdje imaju šest.","B":"Osmerac je vrsta stiha (broj slogova), a ne naziv šesterostiha.","D":"Šesterac je stih od šest slogova, a ne naziv strofe od šest stihova."},
  "2012_jesen_B__15": {"A":"Antika daleko prethodi Gunduliću i nije razdoblje koje mu je neposredno prethodilo.","B":"Barok je razdoblje u kojem sam Gundulić stvara, a ne ono koje mu prethodi.","C":"Realizam dolazi tek u 19. stoljeću, dakle nakon, a ne prije Gundulića."},
  "2012_jesen_B__16": {"A":"Tekst ne prikazuje ispraćaj kršćana pred bitku, nego njihovo pogubljenje.","B":"Prikupljanje harača nije sadržaj ovog ulomka (to je drugo pjevanje).","C":"Nema obračuna age s pojedinim junakom, nego masovno smaknuće zarobljenih kršćana."},
  "2012_jesen_B__17": {"A":"Borbenost bi značila aktivan otpor, a ovdje je riječ o tihom podnošenju smrti.","B":"Pasivnost bi značila mlitavost, no šutnja izražava svjesni, čvrsti otpor.","C":"Strah je suprotan onome što ponavljanje naglašava - junaci ne jauknu ni od boli."},
  "2012_jesen_B__18": {"B":"Hiperbola je pretjerivanje, a ovdje se smrt ublažava, a ne uvećava.","C":"Ironije nema; izraz ozbiljno i ublaženo opisuje smrt.","D":"Kontrast bi tražio suprotstavljanje pojmova, čega u ovom blagom opisu smrti nema."},
  "2012_jesen_B__19": {"A":"Redoslijed je netočan jer Četa dolazi tek nakon Noćnika, a ne prije njega.","C":"Noćnik ne dolazi odmah nakon Agovanja; između je Harač.","D":"Harač ne dolazi nakon Noćnika; ispravan je slijed Harač pa Noćnik."},
  "2012_jesen_B__20": {"A":"U 16. stoljeću Mažuranić nije živio; spjev je iz romantizma 19. stoljeća.","B":"U 17. stoljeću djelo nije moglo nastati jer je objavljeno 1846.","C":"U 18. stoljeću spjev nije napisan; nastao je sredinom 19. stoljeća."},
  "2012_jesen_B__21": {"A":"Boležljivost je osobina samoga Stipančića, a ne Lucije, niti izvor njegove zlovolje prema njoj.","C":"Privlačnost se ističe kao njezina pozitivna crta (ljepota), a ne kao uzrok očeve zlovolje.","D":"Vatrenost nije ono što Stipančića ljuti; smeta mu što joj ne može slomiti ponosnu ćud."},
  "2012_jesen_B__22": {"A":"Riječ nije o doslovnoj šumarskoj tradiciji, nego o metafori snage roda.","B":"Rečenica ne govori o prevladanoj bolesti, nego o nasljednoj čvrstoći obitelji.","C":"'Jaki panjevi' ne znače priprostost, nego postojanost i otpornost."},
  "2012_jesen_B__23": {"A":"U tekstu se ne kaže da je bolest prikrila godine, nego da otac za to ne mari.","B":"Stipančić ne želi zatajiti godine; jednostavno ih ne zna jer ga to ne zanima.","C":"Ne radi se o tome da je nije vidio godinama, nego da brigu o tome prepušta majci."},
  "2012_jesen_B__24": {"A":"Vukasovića ne potiče dosada, nego ga pogađa Jurjevo okretanje tuđem jeziku.","C":"Vukasović ne zavidi, nego se rastužuje zbog Jurjeva odnarođivanja.","D":"Cilj prisjećanja nije razveseliti Stipančića, nego izraziti vlastitu domoljubnu pogođenost."},
  "2012_jesen_B__25": {"A":"Protorealizam je kasnije razdoblje (Šenoino doba), a Štoos pripada ranijem ilirskom dobu.","B":"Realizam slijedi tek nakon Štoosa, pa mu on ne pripada.","C":"Renesansa je stoljećima ranija od Štoosova ilirskog razdoblja."},
  "2012_jesen_B__26": {"A":"Čehov je dramatičar i novelist, ali likovi Raskoljnikov i Sonja nisu njegovi.","C":"Tolstoj nije autor 'Zločina i kazne', iako pripada istom razdoblju ruskog realizma.","D":"Ljermontov je romantičar, autor 'Junaka našeg doba', a ne ovih likova."},
  "2012_jesen_B__27": {"A":"Tekst ne govori o nezadovoljstvu, nego o izmišljenoj, uobraženoj gostoljubivosti.","B":"Nije se prestrašila gostoljubivosti, nego je sama u nju 'sveto' povjerovala.","C":"Nije se začudila, nego je gostoljubivost izmislila i potom u nju vjerovala."},
  "2012_jesen_B__28": {"A":"'Osvijestio' ne odgovara značenju 'prenerazio', koje upućuje na šok.","B":"'Preduhitrio' znači pretekao, što nije značenje glagola prenerazio.","C":"'Uvjerio' ne nosi smisao zaprepaštenja koje riječ izražava."},
  "2012_jesen_B__29": {"A":"Katerina Ivanovna je pogođena, ali nelagodu izaziva pridošlica, a ne ona.","B":"Lebezjatnikov nije lik koji svojom pojavom utišava društvo u ovom ulomku.","D":"Raskoljnikov nije onaj čija pojava ovdje stišava i zbunjuje sve prisutne."},
  "2012_jesen_B__30": {"A":"Aljona Ivanovna je lihvarka koju Raskoljnikov ubija, a ne ona koja ga vodi kajanju.","B":"Dunja je njegova sestra, ali nije lik koji ga navodi na priznanje i pokajanje.","C":"Katerina Ivanovna je Sonjina maćeha, no nije ona koja potiče Raskoljnikovljevo kajanje."},
  "2012_jesen_B__31": {"A":"Mudrost je suprotna onome što Hemon prigovara - ocu koji misli da je jedini u pravu.","B":"Popustljivost je upravo ono čega Kreontu nedostaje, a ne osobina koju Hemon ističe.","C":"Skromnost je suprotna Kreontovoj uvjerenosti da samo on ima pravo."},
  "2012_jesen_B__32": {"B":"Hemon se ne suprotstavlja izravno, nego oprezno i slikovito, s poštovanjem.","C":"Hemon ne odbija uvrijeđeno, nego pažljivo i obrazloženo savjetuje oca.","D":"Hemon se ne pokorava očevu mišljenju, nego ga nastoji navesti na promjenu."},
  "2012_jesen_B__33": {"A":"Riječ nije o novom zaručniku, nego o smrti - Had je carstvo mrtvih.","C":"Nije riječ o progonstvu u drugi grad, nego o Antigoninoj smrti.","D":"Slanje u proročište nije značenje izraza; Had upućuje na smrt."},
  "2012_jesen_B__34": {"A":"Ovi stihovi govore o Hemonovu uvjerenju da otac griješi, a ne o odnosu s narodom.","C":"Ovi stihovi upozoravaju na opasnost umišljenosti, a ne na odnos vladara i naroda.","D":"Ovi stihovi metaforom broda govore o tvrdoglavosti, a ne o odnosu s narodom."},
  "2012_jesen_B__35": {"B":"Antigona ne gine zbog ljubavi prema gradu, nego zbog pokopa brata.","C":"Ljubav prema vladaru nije razlog; ona se vladaru upravo suprotstavlja.","D":"Ljubav prema zaručniku Hemonu nije razlog njezina čina, nego bratska ljubav."},
  "2012_jesen_B__36": {"B":"Odrješitost je suprotna 'podvinutu repu' koji označava oklijevanje i strah.","C":"Oholost nije ono što slika izražava; jaguar s podvinutim repom je ustrašen, a ne ohol.","D":"Ravnodušnost ne odgovara slici; ona pokazuje nemir i bojažljivo izbjegavanje."},
  "2012_jesen_B__37": {"B":"Leoneova majka nije žrtva o kojoj govori; zlo se odnosi na baroničinu smrt.","C":"Očeva smrt nije ono što Leone naziva zlom u ovom prizoru.","D":"Sestrina smrt nije sadržaj ovoga 'zla'; riječ je o smrti barunice Castelli."},
  "2012_jesen_B__38": {"A":"Angelika ga ne uvjerava u nesposobnost za promjenu, nego u spasonosnu moć razuma.","C":"Suprotno tvrdnji - razum, prema Angeliki, vodi spasenju, a ne propasti.","D":"Ne prigovara mu pretjeranu racionalnost, nego ga uvjerava da razum donosi spas."},
  "2012_jesen_B__39": {"A":"Angelika nije Silberbrandtova ljubavnica; to obilježje pripada barunici Castelli.","C":"Angelika nije majka Fanike Canjeg.","D":"Angelika nije Leoneova sestra, nego udovica njegova (polu)brata."},
  "2012_jesen_B__40": {"A":"Ironije u didaskaliji nema; opis je suosjećajan, bez prikrivena suprotnog smisla.","B":"Kontrasta nema; didaskalija ne suprotstavlja pojmove, nego ih uspoređuje.","C":"Personifikacije nema; ne pridaju se ljudska svojstva neživomu, nego se rabi usporedba 'kao'."},
  "2012_jesen_B__41": {"B":"Realizam se ne temelji na novom tumačenju antike niti je nastao kao oprjeka baroku.","C":"Renesansa prethodi baroku, pa nije mogla nastati kao reakcija na njega.","D":"Romantizam se javlja kao reakcija na klasicizam i racionalizam, ne kao obnova antike."},
  "2012_jesen_B__42": {"B":"Mallarmé je kasniji simbolist, a moderna poezija započinje Baudelaireovom zbirkom 1857.","C":"Rimbaud djeluje poslije 1857. i nije autor zbirke kojom počinje moderna poezija.","D":"Verlaine pripada kasnijem simbolizmu, a ne početku moderne poezije 1857."},
  "2012_jesen_B__43": {"A":"Barokna melodrama nije obilježena pravilima triju jedinstava i pet činova klasicizma.","C":"Naturalistička drama nastoji prikazati svakodnevicu i ne piše se uzvišenim stihom.","D":"Srednjovjekovno prikazanje je vjerska igra, bez klasicističke kompozicije u pet činova."},
  "2012_jesen_B__44": {"A":"Eufemizam ublažava neugodan pojam, a naslov upravo izravno spaja suprotnosti.","B":"Metonimija zamjenjuje pojam srodnim, čega ovdje nema.","D":"Poredba bi tražila usporedbu pomoću 'kao', a naslov spaja proturječne pojmove."},
  "2012_jesen_B__45": {"B":"Habdelić je kajkavski prozni pisac i propovjednik, a ne petrarkist.","C":"Hektorović je autor 'Ribanja i ribarskoga prigovaranja', a ne petrarkist.","D":"Zoranić je autor pastoralnog romana 'Planine', a ne petrarkist."},
  "2012_jesen_B__46": {"A":"'Dubravka' je pastorala o slobodi Dubrovnika, bez teme slavenskog jedinstva s Poljacima.","C":"'Prozerpina ugrabljena' je mitološko djelo, bez ideje baroknoga slavizma.","D":"'Suze sina razmetnoga' su religiozni spjev, bez teme poljskoga naroda."},
  "2012_jesen_B__47": {"B":"Šimunović je autor pripovijedaka poput 'Duga', a ne navedenih zbirki.","C":"Leskovar je pisac psiholoških novela, ali ne tih triju zbirki.","D":"Nehajev je autor romana 'Bijeg', a ne navedenih novelističkih zbirki."},
  "2012_jesen_B__48": {"A":"U Francuskoj nastaje nadrealizam, a ne futurizam.","C":"U Njemačkoj se razvija ekspresionizam, ne futurizam.","D":"U Španjolskoj se javljaju druge avangardne struje, ali futurizam nastaje u Italiji."},
  "2012_jesen_B__49": {"A":"'Ex Ponto' je lirska proza Ive Andrića, a ne Ujevićeva zbirka.","C":"'Plandovanja' je zbirka Dragutina Tadijanovića, a ne Ujevića.","D":"'Preobraženja' je zbirka A. B. Šimića, a ne Tina Ujevića."},
  "2012_jesen_B__50": {"A":"Cesarić pripada međuratnom razdoblju, a ne krugu krugovaša.","B":"Tadijanović je pjesnik starije generacije, a ne krugovaš.","C":"Krleža je vodeća figura moderne, ali ne pripada krugovašima."},
  "2012_jesen_B__51": {"B":"Šenou svrstava u protorealizam (B) umjesto u realizam (C), pa je raspored netočan.","C":"Galovića svrstava u realizam (C) umjesto u modernu (A), pa je raspored netočan.","D":"Šenou stavlja u protorealizam (B), a Vidrića u realizam (C), što je pogrešno."},
  "2012_jesen_B__52": {"B":"Camusovu 'Kugu' svrstava u dramu (A), a Brechtovo djelo u roman (C), što je obrnuto.","C":"Ionescove 'Stolice' svrstava u pjesmu (B), a Lamartineovo 'Jezero' u dramu (A), pogrešno.","D":"'Kugu' stavlja u dramu (B) i 'Hamleta' van drame, pa raspored ne odgovara vrstama."},
  "2012_jesen_B__53": {"B":"'Svijet' jest dvosložna, ali se prema ključu kao točan navodi primjer A.","C":"'Mlijeko' je trosložna (mli-je-ko), pa nije dvosložna riječ.","D":"'Sijeno' je trosložna (si-je-no), pa nije dvosložna riječ."},
  "2012_jesen_B__54": {"B":"'Ražčupati' je pogrešno; pred 'č' provodi se jednačenje pa je 'š', ne 'ž'.","C":"'Razčupati' je pogrešno jer se 's/z' pred 'č' jednači u 'š' (raščupati).","D":"'Rašćupati' je pogrešno jer korijen ima 'č', a ne 'ć'."},
  "2012_jesen_B__55": {"A":"U 'dežnjak' ('dežnjaka') 'a' ostaje u kosim padežima, pa nije nepostojano.","B":"U 'junak' ('junaka') 'a' se zadržava, pa nije nepostojano.","C":"U 'luk' nema samoglasnika 'a' koji bi mogao biti nepostojan."},
  "2012_jesen_B__56": {"A":"U 'lišće' je provedeno jotiranje (list - lišće), a ne palatalizacija.","C":"U 'strijela' nije provedena palatalizacija; nema smjene 'k/g/h' ili 's/c' u 'č/š'.","D":"U 'žica' nije riječ o palatalizaciji u traženom smislu kao u 'pašče'."},
  "2012_jesen_B__57": {"A":"'Austro-ugarska' s malim 'u' i 'monarhija' malim slovom nije ispravno za vlastito ime.","B":"'Monarhija' malim slovom nije ispravno jer je dio vlastita imena države.","C":"'Austro-ugarska' s malim 'u' nije ispravno; oba dijela složenice idu velikim slovom."},
  "2012_jesen_B__58": {"B":"Nedostaje zarez iza 'prijatelju', a vokativ se odvaja s obje strane.","C":"Nedostaje zarez ispred 'dragi prijatelju', pa vokativ nije pravilno odvojen.","D":"Vokativ uopće nije odvojen zarezima, što je pogrešno."},
  "2012_jesen_B__59": {"A":"'Izvjestiti' je pogrešno; pravilno je 'izvijestiti' (uz 'izvještavati').","B":"'Namjestiti' je pogrešno; pravilno je 'namjestiti' samo ako se misli na drukčiji glagol - traženi je par 'zamijeniti'.","C":"'Sprječiti' je pogrešno; pravilno je 'spriječiti' (uz 'sprječavati')."},
  "2012_jesen_B__60": {"A":"Trebalo bi 'svojim udžbenicima' jer se posvojnost odnosi na subjekt rečenice.","B":"Trebalo bi 'svoje interese' jer subjekt brani vlastite interese (povratno-posvojna zamjenica).","D":"Bolje je 'svoj rad' jer se posvojnost odnosi na subjekt imperativa (povratno-posvojna zamjenica)."},
  "2012_jesen_B__61": {"B":"'Vidjet' ću' je pogrešno jer se uz futur ne piše apostrof.","C":"'Viditi ću' je pogrešno; infinitiv nije 'viditi' niti se tako tvori futur.","D":"'Vidit' ću' je pogrešno i zbog osnove 'vidit' i zbog suvišna apostrofa."},
  "2012_jesen_B__62": {"A":"'Sičući' nije pravilan oblik priloga od 'siktati'.","C":"'Siktajuć' je krnji oblik; standardni prilog sadašnji glasi 'siktajući'.","D":"'Sikteći' je pogrešno tvoren; osnova je 'siktaj-', a ne 'sikt-'."},
  "2012_jesen_B__63": {"B":"'Ljubiše' je aorist (množina/jednina), a ne imperfekt.","C":"'Ljubljaše' nije pravilan imperfekt glagola 'ljubiti'.","D":"'Ljubljiše' nije postojeći ni pravilan glagolski oblik."},
  "2012_jesen_B__64": {"A":"Nominativ je padež subjekta, a 'savjet' uz prijedlog 'po' nije subjekt.","B":"Dativ se ne slaže s prijedlogom 'po' u ovom značenju cilja.","D":"Lokativ uz 'po' označava mjesto/raspršenost, a ovdje 'po' iskazuje cilj (akuzativ)."},
  "2012_jesen_B__65": {"B":"'Stijepo' je u nominativu i vrši funkciju subjekta, a ne neizravnog objekta.","C":"'Prstohvat' je izravni objekt (akuzativ), a ne neizravni.","D":"'Duhana' je atribut/dopuna uz 'prstohvat' (genitiv), a ne neizravni objekt."},
  "2012_jesen_B__66": {"A":"U 'pisac romana' imenica 'romana' je genitivna dopuna (nesročni objekt/atribut uz 'pisac'), no traženi je primjer D.","B":"U 'u romanima Kafke' imenica 'romanima' je priložna oznaka/objekt, a ne atribut.","C":"U 'roman Germinal' imenica je objekt, a 'Germinal' je apozicija, pa 'roman' nije atribut."},
  "2012_jesen_B__67": {"A":"U 'To se događalo' postoji subjekt 'to', pa rečenica nije besubjektna.","C":"U 'Nikoga nije zanimala' podrazumijeva se subjekt (ona), pa rečenica nije besubjektna.","D":"U 'Nismo im se svidjeli' subjekt je 'mi' (sadržan u glagolu), pa nije besubjektna."},
  "2012_jesen_B__68": {"A":"U 'izgledalo je da im se sviđa' zavisna rečenica je subjektna (uz bezličan glagol), a ne objektna.","B":"U 'zna se da...' zavisna rečenica je subjektna, a ne objektna.","C":"U 'činilo se da...' zavisna je rečenica subjektna (uz bezličan izraz), a ne objektna."},
  "2012_jesen_B__69": {"A":"'Brz - buran' nisu suprotnoga značenja, pa nisu antonimi.","B":"'Brz - hitar' su sinonimi (bliskoznačnice), a ne antonimi.","C":"'Brz - lagan' nisu pravi antonimi; suprotnost 'brzu' je 'spor'."},
  "2012_jesen_B__70": {"A":"Antonimija znači suprotno značenje, a ove riječi nisu suprotne, nego istozvučne.","C":"Polisemija je višeznačnost iste riječi s povezanim značenjima, a ovdje su značenja nepovezana.","D":"Sinonimija znači blisko ili isto značenje, čega ovdje nema."},
  "2012_jesen_B__71": {"A":"Posuđenice iz arapskog su arabizmi, a ne hispanizmi.","B":"Posuđenice iz francuskog su galicizmi, a ne hispanizmi.","C":"Posuđenice iz portugalskog nisu hispanizmi (koji dolaze iz španjolskog)."},
  "2012_jesen_B__72": {"A":"U 14. stoljeću još nije bilo tiska, pa ni inkunabula.","C":"U 16. stoljeću tiskaju se postinkunabule; inkunabule su do 1500.","D":"U 17. stoljeću ne nastaju inkunabule, koje su ograničene na 15. stoljeće."},

  // 2012_ljeto_A
  "2012_ljeto_A__1": {"A":"Lirski subjekt ne govori u ime začinjavaca, nego im se klanja kao tradiciji (Marulić, splitski začinjavac).","B":"Tekst ne govori o pomorcima nego brodom (mladom plavcom) metaforički prikazuje skupinu mladih pjesnika.","C":"Iako se spominje 'krivovirna pravca', to je oznaka modernističke novosti, a ne da pjeva u ime krivovjeraca."},
  "2012_ljeto_A__2": {"A":"Marulić se priziva s poštovanjem ('čtimo'), a ne radi ismijavanja tradicionalnih pjesnika.","B":"Naglasak je na štovanju književne tradicije, a ne na isticanju domoljublja.","D":"Marulić se zaziva kao uzor tradicije, a ne da bi se opomenuli nevjernici."},
  "2012_ljeto_A__3": {"A":"Taj stih hvali ljepotu čakavskoga jezika, a ne izriče oproštaj.","B":"Stih odaje počast slavnomu grobu (tradiciji), ne sadrži čin odlaska.","C":"Stih govori o žeđi za suncem/slobodom, ali oproštaj i odlazak izriče tek završni stih."},
  "2012_ljeto_A__4": {"A":"'Libar' u tekstu znači knjiga, dok 'vers' označuje stih.","B":"Riječ se na čakavskom kaže 'rič', a 'vers' (tal. verso) znači stih.","C":"Pjesma bi bila 'pisan/kanat'; 'vers' se odnosi na pojedini stih."},
  "2012_ljeto_A__5": {"B":"Nije metonimija jer nema zamjene pojma po stvarnoj (uzročnoj, prostornoj) povezanosti, nego prijenos po sličnosti.","C":"Nije poredba jer nedostaje poredbeni veznik (kao, poput) i izravna usporedba.","D":"Nije oksimoron jer 'mlada plavca' ne spaja proturječne pojmove."},
  "2012_ljeto_A__6": {"A":"Ulomak ne donosi ribarske razgovore, nego opisuje opremanje broda za put.","C":"Noćni lov nije tema ovog ulomka; opisuje se priprema prije polaska.","D":"Tekst ne prikazuje ribarsku vještinu u radnji, nego pripremne radnje za plovidbu."},
  "2012_ljeto_A__7": {"A":"Osim dvojice ribara s pjesnikom je i Paskojev sin, pa ih je više od dvojice.","B":"Tri putnika ne uključuju Paskojeva sina koji je također u plovilu.","D":"Pet je previše; ukupno su četvorica (pjesnik, dvojica ribara i sin)."},
  "2012_ljeto_A__8": {"A":"Trava ne služi kao mamac, nego se vezuje da plaši ribe.","C":"Mreže se ne pletu travom; trava se rabi za tjeranje ribe.","D":"Postelja ribarima je sam brod ('plav postelja'), a ne snop trave."},
  "2012_ljeto_A__9": {"A":"Motiv polaska nije dokazivanje ribarskog umijeća, nego bijeg od kuće na tri dana.","C":"Lirski subjekt se ne želi dokazati kao pomorac, nego se nakratko udaljiti od svakodnevice.","D":"Cilj nije razgledavanje Hvara; ribari su odande, a motiv je odmak od doma."},
  "2012_ljeto_A__10": {"A":"14. stoljeće je prerano; Hektorović djeluje u 16. stoljeću.","B":"15. stoljeće je prije Hektorovićeva života (1487.–1572.).","D":"17. stoljeće je prekasno; Hektorović umire 1572. godine."},
  "2012_ljeto_A__11": {"A":"Paris nije otišao u borbu, naprotiv, Hektor ga kori jer iz borbe izostaje.","B":"Zamjerka nije nepripremljeno oružje, nego Parisova nazočnost izvan boja.","D":"Paris nije izazvao požar; prijetnja paljenja grada posljedica je toga što ne ratuje."},
  "2012_ljeto_A__12": {"B":"Paris nije iznenađen optužbom, nego je smireno priznaje kao opravdanu.","C":"Riječi ga ne pogađaju kao nepravedne; sam kaže da ga je Hektor 'pravo izgrdio'.","D":"Paris ne proturječi, nego se s Hektorom slaže ('krivo me nisi')."},
  "2012_ljeto_A__13": {"A":"Ahilej je grčki junak i protivnik, a ovdje Hektor kori brata Trojanca.","C":"Patroklo je Ahilejev prijatelj iz grčkog tabora, nije predmet Hektorove srdžbe.","D":"Prijam je Hektorov otac, a ljutnja je upravljena na brata Parisa (Aleksandra)."},
  "2012_ljeto_A__14": {"A":"Epilij je kratki, mali ep, dok je Ilijada opsežan junački ep.","C":"Epska pjesma je kraća epska vrsta, a Ilijada je cjeloviti ep.","D":"Poema je novija lirsko-epska vrsta, a Ilijada je antički ep."},
  "2012_ljeto_A__15": {"A":"Homersko pitanje nije usko o podrijetlu Homera, nego o autorstvu epova.","B":"Podrijetlo tragedije nije predmet homerskog pitanja.","C":"Eneida je Vergilijevo djelo i nije obuhvaćena homerskim pitanjem."},
  "2012_ljeto_A__16": {"A":"Gregor ne želi napredovati; razmišlja čak o davanju otkaza.","B":"Gregor nije zadovoljan poslom, nego ga proklinje (rano ustajanje, šef).","C":"Nije opsjednut poslom; posao mu je teret kojeg bi se rado riješio."},
  "2012_ljeto_A__17": {"A":"Ne radi marljivo da zadivi šefa; o šefu razmišlja s prezirom.","B":"Drugi putnici (koji 'žive kao u haremu') nisu mu motivacija, nego predmet zavisti.","D":"Pokretač nije želja da se dokaže marljivim, nego obveza prema roditeljima."},
  "2012_ljeto_A__18": {"A":"Usporedbom sa ženama u haremu ne misli da su bahati, nego bezbrižno zaštićeni.","B":"Trgovci nisu obespravljeni, nego povlašteni i sigurni (za razliku od Gregora).","C":"Slika harema ne naglašava razvrat, nego udobnu zaštićenost i lagodnost."},
  "2012_ljeto_A__19": {"A":"Roditelji nisu uzrok; oni su razlog zašto Gregor ne daje otkaz, a ne pad šefa.","B":"Nije riječ o Gregorovu nemaru, nego o tome da bi šefu rekao istinu u lice.","C":"Gregor ne razmišlja o fizičkom udarcu, nego o oštroj kritici izrečenoj šefu."},
  "2012_ljeto_A__20": {"A":"Dadaizam je antiumjetnički pokret slučaja i besmisla, a ne halucinantnih vizija likova.","C":"Futurizam slavi brzinu, tehniku i dinamiku, ne halucinantnu deformaciju lika.","D":"Impresionizam bilježi trenutačni dojam i osjet, a ne halucinantne vizije."},
  "2012_ljeto_A__21": {"A":"Ton nije idiličan; opis podrijetla i naravi popraćen je ironijskim odmakom.","C":"Sarkazam je oštriji i zajedljiviji, dok je Voltaireov ton ovdje blago ironičan.","D":"Ton nije uzvišen, nego ironičan prema plemstvu i naivnosti."},
  "2012_ljeto_A__22": {"B":"Razlog nije nedostatak razboritosti, nego nedovoljno plemenitih predaka.","C":"Broj 71 odnosi se na koljena (pretke), a ne na očevu dob.","D":"Tekst ne kaže da je djevojka bila udana, nego da otac nije bio dovoljno plemenit."},
  "2012_ljeto_A__23": {"A":"Blagost se spominje ('najblaže navike'), ali ime Candide objašnjava se jednostavnošću rasuđivanja.","B":"Plemenitost nije razlog imena; ime upućuje na prostodušnost.","D":"Zdravlje se spominje ('zdravo rasuđivao'), ali ime povezuje s jednostavnošću/prostodušnošću."},
  "2012_ljeto_A__24": {"A":"Podnaslov nije 'idealizam', nego 'optimizam' (l'optimisme).","C":"Djelo nosi naslov 'optimizam' (ironijski), a ne 'pesimizam'.","D":"Podnaslov je 'optimizam', a ne 'racionalizam'."},
  "2012_ljeto_A__25": {"A":"Barok prethodi Voltaireu (17. st.), a on pripada 18. stoljeću.","B":"Klasicizam je stariji pravac; Voltaire je predstavnik prosvjetiteljstva.","D":"Romantizam dolazi nakon Voltairea; on je prosvjetitelj."},
  "2012_ljeto_A__26": {"B":"Holden ne prigovara neiskrenosti, nego proturječju između D.B.-ovih stavova i ukusa.","C":"D.B. nije neobrazovan (čak je pisac), pa to nije zamjerka.","D":"Holden ne spočitava nerazumijevanje, nego nedosljednost (mrzi rat, a voli ratnu knjigu)."},
  "2012_ljeto_A__27": {"A":"Fantastičnost Holdenu nije smetnja; smeta mu izvještačenost i lažnost.","C":"Holden ne odbacuje neobičnost, nego namještenost (izvještačenost).","D":"Nezrelost nije ono što kritizira; prigovor je upućen lažnosti i namještenosti."},
  "2012_ljeto_A__28": {"B":"Frazem 'obarati s nogu' znači oduševiti, a ne zbuniti.","C":"Frazem ne izražava ljutnju, nego snažno oduševljenje.","D":"Ne znači čuđenje, nego zadivljenost (oduševljenje)."},
  "2012_ljeto_A__29": {"A":"Izjava nije izraz pustolovnosti, nego prkosnog otpora prema ratu i sustavu.","C":"Riječ je o provokativnoj buntovnosti, a ne o poremećenosti lika.","D":"Ne radi se o požrtvovnosti, nego o buntovnom, izazovnom stavu."},
  "2012_ljeto_A__30": {"B":"D.B. nije otac, nego Holdenov stariji brat (pisac u Hollywoodu).","C":"D.B. nije prijatelj, nego član obitelji (brat).","D":"D.B. nije profesor, nego Holdenov brat pisac."},
  "2012_ljeto_A__31": {"A":"Edip ne traži savjet o protjerivanju krivaca, nego najprije da se otkrije ubojica.","B":"Narav nesreće (kuga) već je poznata; Edip traži ime ubojice Laja.","D":"Edip ne moli božanske tajne općenito, nego konkretno otkrivanje Lajeva ubojice."},
  "2012_ljeto_A__32": {"A":"Sfingine zagonetke pripadaju Edipovoj prošlosti, a grad sada hara bolest, kuga.","B":"Nije riječ o kraljevskim borbama, nego o pošasti koja mori Tebu.","C":"Ptičja groznica je anakronizam; boljka u djelu jest kuga."},
  "2012_ljeto_A__33": {"A":"Tiresija nije glasnik; on je prorok kojemu Edip traži vidovitost.","B":"Tiresija nije prognanik, nego ugledni slijepi prorok.","D":"Tiresija nije ratnik, nego vidovnjak (prorok)."},
  "2012_ljeto_A__34": {"A":"Tiresija ne šuti da bi opomenuo Tebance, nego da poštedi Edipa istine.","B":"Ne suzdržava se iz straha od bogova, nego iz obzira prema Edipu.","D":"Razlog šutnje nije strah od progonstva, nego zaštita Edipa od strašne istine."},
  "2012_ljeto_A__35": {"B":"Taj stih izriče Tiresijinu spoznaju o uzaludnosti mudrosti, a ne Edipovu zabludu.","C":"Stih izražava prorokovo prisjećanje/grižnju, ne Edipovu pogrešnu pretpostavku.","D":"Stih govori o podnošenju sudbine, a ne o Edipovoj zabludi o ubojici."},
  "2012_ljeto_A__36": {"B":"Leone ne prigovara darovima, nego barunicinu nedostojnom postupku prema majci.","C":"Zamjerka nije sreća staroga Glembaja, nego povreda dostojanstva majke.","D":"Riječ je o oskvrnuću majčina krzna, a nepotpuna molitva tek je usputna slika baruničine hladnoće."},
  "2012_ljeto_A__37": {"A":"Glembay Leoneu ne pripisuje amoralnost, nego duševnu rastrojenost ('svršit ćeš u ludnici').","B":"Ne optužuje ga za osvetoljubivost, nego ga smatra prenapetim, rastrojenim.","C":"Ne radi se o pesimizmu, nego o procjeni da je Leone psihički nestabilan."},
  "2012_ljeto_A__38": {"A":"Krzno se spominje uz pseto, ali u vilu je prenesen sag (Kirman-perzer).","B":"Pas (Fifi) nije ono što je preneseno; barunica je dala odnijeti sag.","D":"Nije riječ o slici, nego o perzijskom sagu (Kirman-perzeru)."},
  "2012_ljeto_A__39": {"A":"Perzer ne budi traumu, nego upravo lijepe uspomene iz djetinjstva.","B":"Prezir prema barunici proizlazi iz njezina čina, a sam sag budi sjećanje na majku.","D":"Sag ne izaziva želju za slikanjem, nego prisjećanje na djetinjstvo s majkom."},
  "2012_ljeto_A__40": {"A":"Ta rečenica izražava Glembajev pogled na barunicu kao simbol sreće, ne baruničin odnos prema majci.","B":"Rečenica opisuje molitvu, a baruničin odnos prema prethodnici izriče slika o psećem krznu.","C":"Rečenica govori o majčinu samoubojstvu, a ne izravno o baruničinu postupku prema njoj."},
  "2012_ljeto_A__41": {"A":"Bembisti se vežu uz Pietra Bemba i talijanski kontekst, a ne uz prvu hrvatsku pjesničku školu.","C":"Trubaduri su srednjovjekovni provansalski pjesnici, a ne hrvatska škola 15. stoljeća.","D":"Začinjavci su stariji, srednjovjekovni hrvatski pjesnici, a ne prva svestrana pjesnička škola."},
  "2012_ljeto_A__42": {"A":"15. stoljeće je prerano za Voltairea i Diderota.","B":"16. stoljeće ne odgovara prosvjetiteljima Voltaireu i Diderotu.","C":"17. stoljeće je razdoblje klasicizma; Voltaire i Diderot djeluju u 18. stoljeću."},
  "2012_ljeto_A__43": {"A":"Zola je naturalist (ciklus Rougon-Macquart), a opis u sedam knjiga uz Bergsona upućuje na Prousta.","B":"Maupassant je majstor novele, a ne autora bergsonovskog ciklusa o nesvjesnom.","C":"Balzac piše Ljudsku komediju u realizmu, a ne bergsonovski roman toka svijesti."},
  "2012_ljeto_A__44": {"A":"Stih ima ponavljanje na kraju, ali nema simploke (početak i kraj nisu istovremeno ponovljeni).","C":"Riječ je o anafori ('Jedna i druga'), a ne o simploki.","D":"Riječ je o anafori ('Otkud zlato'), bez istovremena ponavljanja na kraju, pa nije simploka."},
  "2012_ljeto_A__45": {"A":"Ditiramb je zanesena pohvalna pjesma (izvorno Dionizu), a ne kratka satirična forma.","C":"Epitaf je natpis na grobu, a ne duhovita lirska pjesma s neočekivanim završetkom.","D":"Oda je svečana, uzvišena pjesma, a ne sažeta i satirična."},
  "2012_ljeto_A__46": {"A":"'Elegiarum et carminum libri tres' je Šižgorićeva latinska zbirka, a ne zbirka petrarkista.","B":"'Gartlic za čas kratiti' je kajkavska zbirka 18. stoljeća (Habdelić/kasnije), a ne petrarkistička.","C":"'Pjesni razlike' su zbirke pojedinih pjesnika (npr. Lucić), a ne najstarija zbirka petrarkista."},
  "2012_ljeto_A__47": {"B":"Opis triju tematskih planova i paklenoga vijeća odnosi se na ep Osman, a ne na Dubravku.","C":"Sintagma 'obrnuti kanconijer' opisuje neku drugu (lirsku) tvorbu, ne pastoralu Dubravku.","D":"Opis razrješavanja Prozerpinina statusa odnosi se na drugo djelo, ne na Dubravku."},
  "2012_ljeto_A__48": {"A":"Hanibal Lucić nije autor Plandovanja; on piše Robinju i Pjesni ljuvene.","C":"Gundulić nije autor Plandovanja, nego Osmana, Dubravke i Suza sina razmetnoga.","D":"Juraj Šižgorić piše latinske elegije i pjesme, a ne kanconijer Plandovanja."},
  "2012_ljeto_A__49": {"B":"Balzac i Flaubert su realisti, a ne parnasovci iz zbornika La Parnasse contemporain.","C":"Zola i Maupassant su naturalisti, a ne pjesnici parnasovskoga zbornika.","D":"Breton je nadrealist, a Proust romanopisac; nisu parnasovci."},
  "2012_ljeto_A__50": {"B":"Ekspresionizam nije utemeljio Tzara; on je vezan uz njemački govorni prostor.","C":"Futurizam je utemeljio Marinetti, a ne Tzara.","D":"Nadrealizam je utemeljio André Breton, a ne Tzara."},
  "2012_ljeto_A__51": {"B":"Pogrešno svrstava Šoljana (1) u postmodernizam (C); on pripada drugoj moderni (A).","C":"Pogrešno svrstava Ujevića (5) u drugu modernu (A); on pripada razdoblju od 1914. do 1952. (B).","D":"Pogrešno svrstava Aralicu (2) u drugu modernu (A); on pripada postmodernizmu (C)."},
  "2012_ljeto_A__52": {"B":"Pogrešno određuje Camao (2) kao roman (C); riječ je o noveli (B).","C":"Pogrešno određuje Crni mačak (3) kao roman (C); riječ je o noveli (B).","D":"Pogrešno određuje Bez trećega (1) kao roman (C); riječ je o drami (A)."},
  "2012_ljeto_A__53": {"A":"'Ne-strp-lji-vost' ima više od tri sloga (pet), pa nije trosložna.","C":"'Po-vrt-lar-stvo' ima četiri sloga, a tražena je trosložna riječ.","D":"'Zdrav-lje' ima dva sloga, dakle je dvosložna, ne trosložna."},
  "2012_ljeto_A__54": {"A":"U 'lažem' (lagati) provedena je jotacija (g → ž), a ne palatalizacija.","B":"U 'mičem' (micati) riječ je o jotaciji/glasovnoj promjeni ispred je, ne palatalizaciji ispred e.","D":"U 'vučem' (vući) provedena je jotacija (k → č pred je-osnove), a ne klasična palatalizacija."},
  "2012_ljeto_A__55": {"A":"Pisanje s razmacima oko crtice nije pravilno za ovu složenicu.","B":"Spojnica nije potrebna jer se 'fotoklub' piše kao jedna riječ.","C":"Odvojeno pisanje 'foto klub' nije ispravno; piše se sastavljeno."},
  "2012_ljeto_A__56": {"A":"Apozicija 'francuski realist' mora se odvojiti zarezom s obje strane, pa rečenica nije ispravna.","B":"Vokativ 'o mati moja' trebao bi biti odvojen zarezima, pa interpunkcija nije pravilna.","D":"Ispred glavne surečenice iza zavisne ('Čim je stiglo ljeto') nedostaje zarez."},
  "2012_ljeto_A__57": {"B":"'Lađa' uključuje gramatički morfem, dok je korijen samo 'lađ'.","C":"'Lađar' već sadrži tvorbeni sufiks -ar, a korijenski je morfem 'lađ'.","D":"'Lađaric' sadrži dva sufiksa, dok je korijen samo 'lađ'."},
  "2012_ljeto_A__58": {"A":"'Skije' imaju i jedninu (skija), pa nisu plurale tantum.","B":"'Planina' ima jedninu, dakle nije imenica samo množinskoga oblika.","D":"'Čarapa' ima jedninu, pa nije plurale tantum."},
  "2012_ljeto_A__59": {"A":"Pogrešno je deklinirati samo prezime; i ime Harry mijenja se uz umetnuto j (Harryja).","B":"Strano ime na -y dobiva j ispred padežnoga nastavka: Harryja, a ne Harrya.","C":"Spojnica se ne piše; pravilno je Harryja bez crtice."},
  "2012_ljeto_A__60": {"A":"'Kotao' je muški rod (G kotla), pripada a-deklinaciji, ne i-deklinaciji.","C":"'Pepeo' je muški rod (G pepela), a-deklinacija, ne i-deklinacija.","D":"'Posao' je muški rod (G posla), a-deklinacija, ne i-deklinacija."},
  "2012_ljeto_A__61": {"B":"Uz neživo ('crtež') u standardu se upotrebljava 'koji', a ne 'kojeg'.","C":"Uz neživo ('roman') pravilno je 'koji', pa je 'kojeg' neispravno.","D":"Uz neživo ('kaput') treba 'koji', a 'kojeg' nije u skladu sa standardom."},
  "2012_ljeto_A__62": {"A":"'Jaućući' je pogrešan zapis; pravilno je 'jaučući'.","C":"'Plaćući' je pogrešno; glagolski prilog od plakati je 'plačući'.","D":"'Vićući' je pogrešno; pravilan oblik je 'vičući'."},
  "2012_ljeto_A__63": {"B":"'Pade' nije zapovijed, pa nije imperativ.","C":"Imperfekt bi glasio 'padaše'; 'pade' je aorist.","D":"Prezent bi bio 'pada'; 'pade' je prošlo svršeno vrijeme (aorist)."},
  "2012_ljeto_A__64": {"A":"'Vuče ga' ima objekt (ga), pa je glagol prijelazan.","C":"'Zaobiđi sve prepreke' ima objekt (prepreke), pa je prijelazan.","D":"'Pozvao me' ima objekt (me), pa je glagol prijelazan."},
  "2012_ljeto_A__65": {"A":"Tri surečenice su premalo; rečenica ih ima četiri.","C":"Pet surečenica je previše; predikata je četiri.","D":"Šest surečenica je previše; rečenica se sastoji od četiriju surečenica."},
  "2012_ljeto_A__66": {"A":"'Život u neimaštini' je objekt (podnosio što?), a ne atribut.","C":"'Lagodnijega života' je objekt u genitivu (zaželio se čega), a ne atribut.","D":"'Tajnu života' — 'života' je nesročni atribut uz 'tajnu', ali tražena je sintagma u kojoj 'život' funkcionira kao u B; ovdje je glavna imenica 'tajnu'."},
  "2012_ljeto_A__67": {"A":"'Tijelo' nije atribut jer ne pobliže označuje drugu imenicu.","C":"'Tijelo' nije priložna oznaka jer ne izriče okolnost radnje.","D":"Subjekt je 'valovi' (oni vrše radnju), a 'tijelo' je objekt radnje."},
  "2012_ljeto_A__68": {"A":"'Ne bih li uspio' je namjerna (final.), odgovara na 'zašto/s kojom svrhom', nije objektna.","C":"'Jer me to zanimalo' je uzročna rečenica, a ne objektna.","D":"'Mada nije bilo lako' je dopusna rečenica, a ne objektna."},
  "2012_ljeto_A__69": {"B":"Nema prefiksa ni sufiksa, pa nije prefiksalno-sufiksalna tvorba, nego slaganje dviju osnova.","C":"Srastanje nastaje od sintagme; ovdje su spojene dvije osnove spojnikom, pa je riječ o čistom slaganju.","D":"Nema tvorbenog sufiksa; tvorenica nastaje spajanjem dviju osnova (slaganje)."},
  "2012_ljeto_A__70": {"A":"'Bubreščić' nastaje sufiksom -čić uz glasovnu promjenu, a ne čistim -ić.","C":"'Kruščić' nastaje sufiksom -čić uz promjenu (kruh), a ne sufiksom -ić.","D":"'Stančić' nastaje sufiksom -čić (stan), a ne sufiksom -ić."},
  "2012_ljeto_A__71": {"B":"'Gorski kotar' je ime kraja/regije (horonim), a ne planine, pa nije oronim.","C":"'Ravna Gora' ovdje se tretira kao naselje/mjesto, ne kao tipičan oronim.","D":"'Slavonski Brod' je grad (ojkonim), a ne ime planine."},
  "2012_ljeto_A__72": {"B":"Posuđenice iz poljskog su polonizmi, a ne bohemizmi.","C":"Posuđenice iz ruskog su rusizmi, a ne bohemizmi.","D":"Posuđenice iz slovačkog su slovakizmi, a ne bohemizmi."},

  // 2012_ljeto_B
  "2012_ljeto_B__1": {"A":"Aramejski izvornik glasi 'zašto si me ostavio', a ne 'izabrao'.","B":"Krist u tom usklliku ne govori o kazni, nego o napuštenosti.","D":"Riječ je o napuštenosti ('ostavio'), a ne o žrtvovanju."},
  "2012_ljeto_B__2": {"A":"Pjesma naglašava da je Krist umro za druge, a ne njegovu iskrenost.","B":"Odanost nije osobina koju stih 'za kog je izdahan' ističe.","C":"U prvi je plan stavljena žrtva za čovječanstvo, a ne plemenitost kao takva."},
  "2012_ljeto_B__3": {"A":"Eufemizam je ublažavanje neugodna pojma, čega ovdje nema.","B":"Oksimoron je proturječje sažeto u sintagmu, a ovdje je riječ o cijeloj proturječnoj misli.","D":"Sinegdoha je zamjena dijela cjelinom (ili obratno), što se u stihu ne pojavljuje."},
  "2012_ljeto_B__4": {"B":"Stih govori o sramoti i grijehu, a ne o patnji čovječanstva.","C":"'Sramotnička halja' upućuje na grijeh, a ne na poniznost.","D":"Slika sramotne odjeće znači krivnju, a ne ranjivost."},
  "2012_ljeto_B__5": {"A":"Barok je 17. stoljeće, a Kranjčević stvara potkraj 19. stoljeća.","B":"Moderna je bliska, ali pjesnik pripada ponajprije realizmu.","C":"Prosvjetiteljstvo je 18. stoljeće i ne odgovara Kranjčevićevu vremenu."},
  "2012_ljeto_B__6": {"B":"Pijanica se spominje kao tuđi prizor ('o svom vinu'), a ne kao lirski subjekt.","C":"Lirski subjekt hoda ulicom i promatra, a ne pali svjetlo u kući.","D":"Ljubavnik je također samo spomenut prizor, a ne glas pjesme."},
  "2012_ljeto_B__7": {"A":"Ljubav se spominje samo u prvoj strofi (ljubavnik o dragoj).","B":"Motiv sna javlja se tek u prvoj strofi.","D":"Zvijezde se ne pojavljuju u drugoj strofi, za razliku od motiva svjetla."},
  "2012_ljeto_B__8": {"A":"Elipsa je izostavljanje riječi, a ovdje se veznik 'I' upravo ponavlja, ne izostavlja.","B":"Pleonazam je suvišno gomilanje istoznačnih riječi, čega u strofi nema.","D":"Simploka traži istodobno ponavljanje na početku i kraju, što ovdje nije ostvareno."},
  "2012_ljeto_B__9": {"A":"Cesarić piše o svakidašnjem, a ne o mističnome.","C":"Njegova je poetika smirena i obična, bez šokantnosti.","D":"Ton pjesme je tih i sjetan, a ne zaigran."},
  "2012_ljeto_B__10": {"A":"'Gradske lampe' su samo vizualni motiv, bez miješanja osjetila.","C":"'Prve zvijezde' također su čisto vizualna slika.","D":"'Vječan život' je apstraktan pojam, a ne spoj dvaju osjetila."},
  "2012_ljeto_B__11": {"B":"Judita ne ide muškarcu kojeg voli, nego neprijatelju kojeg kani ubiti.","C":"Cilj uljepšavanja nije natjecanje s drugim ženama, nego zavođenje vođe.","D":"Nije riječ o dvorskom balu, nego o pohodu u neprijateljski tabor."},
  "2012_ljeto_B__12": {"A":"Antička tradicija nije model ovog idealiziranog opisa ženske ljepote.","B":"Barok dolazi tek poslije Marulića, pa ne može biti uzor opisu.","D":"Romantizam je puno kasnije razdoblje i ne odgovara renesansnom Maruliću."},
  "2012_ljeto_B__13": {"A":"'Sjahu se' (sjajiti se) je vizualni, a ne slušni dojam.","C":"'Šarljeniti rubin' opisuje boju, dakle vizualni podražaj.","D":"'Sjati se' je opet vizualni dojam, bez zvuka."},
  "2012_ljeto_B__14": {"A":"Tekst je izjednačuje s kraljicama izgledom, ne navodi se njezino bogatstvo.","B":"Naglašena je njezina ljepota, a ne dostojanstvo kao takvo.","D":"Ne govori se o ugledu, nego o tome da izgledom pripada među kraljice."},
  "2012_ljeto_B__15": {"A":"Bijela se boja spominje uz biser i ruke, a ne uz prsten.","C":"Modra je boja safira, a ne rubina na prstu.","D":"Zlato je boja ukrasa i pasa, a prsten je crveni rubin."},
  "2012_ljeto_B__16": {"A":"'Ušeprtljati se' znači zbuniti se, a ne razbježati se.","B":"Glagol izriče zbunjenost i nemir, a ne radost.","C":"Riječ ne znači pobuniti se, nego se uzmiješati i smesti."},
  "2012_ljeto_B__17": {"B":"Pepica ne ostaje da privuče pozornost, nego iz prkosa brani svoje.","C":"Fratri su tek dio njezina prkosna usklika, cilj nije njihova uvreda.","D":"Ne radi se o inaćenju mužu, nego o obrani vlastitih prava."},
  "2012_ljeto_B__18": {"B":"Hiperbola je pretjerivanje, a ovdje je smrt ublažena, ne uvećana.","C":"Nema proturječja, nego blago izrečena neugodna istina.","D":"Srce je doista personificirano, ali ključna figura je eufemizam za smrt."},
  "2012_ljeto_B__19": {"A":"Pokop nije bio javan, nego tih i neugledan.","B":"Tekst ne ističe plač, nego potajnost ukopa.","D":"Sahrana nije bila slavna, nego skromna i potajna."},
  "2012_ljeto_B__20": {"B":"Djelo prikazuje teško stanje naroda, a ne idiličan život građana.","C":"Mađarski vojnici nisu središnja ideja, nego sudbina hrvatskoga naroda.","D":"Bračni odnos Pogačića je tek prizor, a ne ideja djela u cjelini."},
  "2012_ljeto_B__21": {"A":"Werther život doživljava kao snatrenje, a ne kao pustolovinu.","B":"Ne govori o životu kao trenutku, nego kao sanjarenju/snu.","C":"Njegov je dojam tjeskoban, a ne da je život zadovoljstvo."},
  "2012_ljeto_B__22": {"B":"On se ne povlači da produži egzistenciju, nego iz nezadovoljstva svijetom.","C":"Razlog nije želja za istraživanjem, nego bijeg u unutarnji svijet.","D":"Ne želi biti zatvoren, nego se sklanja od svijeta koji ga guši."},
  "2012_ljeto_B__23": {"A":"'Rezignirano' ne znači dosadno, nego pomireno i ravnodušno.","B":"Riječ označava smirenost, dakle suprotnost nemiru.","D":"Ne izriče zabrinutost, nego mirno odustajanje i ravnodušnost."},
  "2012_ljeto_B__24": {"A":"U sebi pronalazi cijeli svijet, dakle smisao, a ne besmisao.","B":"Unutarnji svijet mu donosi ispunjenje, a ne nezadovoljstvo.","C":"Ograničenost osjeća u vanjskome svijetu, a u sebi nalazi bogatstvo."},
  "2012_ljeto_B__25": {"A":"Egzistencijalistički roman je kasnija pojava 20. stoljeća.","C":"Gotički roman obilježavaju strava i tajanstvo, a ne pisma.","D":"Pastoralni roman prikazuje idiličan seoski svijet, što ovdje nije slučaj."},
  "2012_ljeto_B__26": {"B":"Savjet je da bude bezobziran, a ne tajnovit i požrtvovan.","C":"Osjećajnost i bojažljivost su suprotne preporučenoj hladnoći.","D":"Blagost i sumnjičavost ne vode uspjehu prema ovom savjetu."},
  "2012_ljeto_B__27": {"A":"'Stranice koje nije poznavala' upućuju na nedostatak iskustva, ne proračunatosti.","B":"Ne govori o pameti, nego o nepoznatim dijelovima životnog iskustva.","C":"Riječ nije o pažljivosti, nego o iskustvu koje joj je nedostajalo."},
  "2012_ljeto_B__28": {"B":"Nemilosrdnost se u tekstu spominje odvojeno, a 'hvastavost' znači hvalisavost.","C":"Potkupljivost nije značenje te riječi.","D":"Prijetvornost (licemjerje) nije isto što i hvalisanje."},
  "2012_ljeto_B__29": {"B":"Poredba govori o korištenju ljudi, a ne o njihovu obmanjivanju.","C":"Smisao je iskoristiti pa odbaciti, što je više od pukog zanemarivanja.","D":"Nije riječ o zlostavljanju, nego o iskorištavanju ljudi kao sredstva."},
  "2012_ljeto_B__30": {"A":"Brak je tek sredstvo, a krajnji je cilj društveni uspon.","B":"Skrivanje emocija je samo dio taktike, a ne konačni cilj.","D":"Rastignacov cilj nije ostati iskren, nego se uzdignuti u društvu."},
  "2012_ljeto_B__31": {"A":"Marin Držić je renesansni Dubrovčanin, a Aulularija je Plautova.","B":"Molière je obradio sličnu temu škrtca, ali likovi Euklion i Likonid su Plautovi.","C":"Corneille je tragičar klasicizma, a ne autor ove komedije."},
  "2012_ljeto_B__32": {"A":"Škrinjica je ono na što misli Euklion, dok Likonid 'zlatom' zove kćer.","B":"Novac (zlato u škrinjici) je Euklionova briga, ne ono što Likonid misli.","C":"Likonid ne govori o kući, nego o Euklionovoj kćeri."},
  "2012_ljeto_B__33": {"A":"U ulomku do izražaja dolazi škrtost, a ne Euklionova bezobraznost.","B":"Brižnost nije osobina koju prizor naglašava.","C":"Mahnitost je posljedica, a temeljna je osobina škrtost."},
  "2012_ljeto_B__34": {"B":"'Posrnuh' samo priznaje grijeh, ali ne stvara dvosmislenost.","C":"Euklionova rečenica o oprostu ne uzrokuje nesporazum oko 'zlata'.","D":"'Zašto si je dirao' nastaje već nakon nastalog nesporazuma, ne uzrokuje ga."},
  "2012_ljeto_B__35": {"A":"Lakomost je Euklionova osobina, a Likonid priznaje nemoralan čin.","B":"Likonid je, naprotiv, iskren u priznanju krivnje.","D":"'Posrnuh' znači moralni pad, a ne umišljenost."},
  "2012_ljeto_B__36": {"A":"Svjetlosna manifestacija je suprotna Altmannovu trijeznom, medicinskom shvaćanju.","B":"Neshvatljivu dimenziju zastupa Silberbrandt (teologija), a ne Altmann.","D":"Altmann smrt vidi kao kraj funkcije, a ne kao nastavak života."},
  "2012_ljeto_B__37": {"A":"Silberbrandt ne predbacuje Altmannu propust u predviđanju, nego pojednostavljivanje.","C":"Poanta nije u Altmannovu nedostatku žaljenja, nego u svedenosti njegova pristupa.","D":"Prigovor je da Altmann premalo, a ne previše promišlja o smrti."},
  "2012_ljeto_B__38": {"A":"'Vonja' upućuje na miris, a ne na zvuk.","B":"Gustativni podražaj je okus, a ovdje je riječ o mirisu.","D":"Nije riječ o viđenju, nego o njušenju ('vonja')."},
  "2012_ljeto_B__39": {"A":"Poredba ne govori o uznemirenosti, nego o nestajanju u smrti.","C":"Smrt ovdje nije okrjepa, nego rastvaranje i nestanak.","D":"Slatkoća šećera nije poanta; istaknuto je topljenje, tj. nestajanje."},
  "2012_ljeto_B__40": {"B":"Gradacija je stupnjevanje, a ovdje je riječ o suprotstavljanju crnoga i bijeloga.","C":"Hiperbola je pretjerivanje, čega u izrazu nema.","D":"Oksimoron spaja proturječne pojmove u sintagmu, dok je ovdje kontrast dvaju odvojenih pojmova."},
  "2012_ljeto_B__41": {"A":"Ironija je suprotnost rečenog i mišljenog, a ne spoj suprotnih pojmova.","B":"Metafora je prijenos značenja, dok navedene sintagme spajaju suprotnosti.","D":"Paradoks je proturječna misao, a ovdje su sažete dvočlane sintagme suprotnosti (oksimoron)."},
  "2012_ljeto_B__42": {"A":"Posljednji Stipančići (Šenoa) prikazuju propast senjske obitelji, a ne slavonsko selo.","B":"Prijan Lovro (Šenoa) tematizira sudbinu siromašna mladića, a ne slavonske probleme.","D":"U registraturi (Kovačić) prati život činovnika, a ne raspad slavonskih zadruga."},
  "2012_ljeto_B__43": {"A":"Matoš pripada moderni i ne piše prozu u trapericama s mladim buntovnikom.","C":"Aralica piše povijesnu prozu, a ne žargonski obojan glas mladih.","D":"Marinković je modernist; mladi pripovjedač u žargonu obilježje je Šoljana."},
  "2012_ljeto_B__44": {"A":"Anafora je ponavljanje na početku, dakle figura konstrukcije, a ne značenja.","B":"Asindeton je izostavljanje veznika, figura konstrukcije.","C":"Elipsa je izostavljanje riječi, također figura konstrukcije, a ne promjena značenja."},
  "2012_ljeto_B__45": {"B":"Ekloga Radmio i Ljubmir djelo je Džore Držića, a ne Lucića.","C":"Planine je roman Petra Zoranića, a ne Lucićevo djelo.","D":"Kanconijer Flaviji pripada Šišku Menčetiću, a ne Luciću."},
  "2012_ljeto_B__46": {"A":"Dubravka je pastoralna drama Ivana Gundulića, a ne ep.","B":"Judita (Marulić) je renesansni ep, a ne barokni.","D":"Robinja (Hanibal Lucić) je renesansna drama, a ne barokni ep."},
  "2012_ljeto_B__47": {"B":"Davorija je junačka koračnica, ali borbeno preporodno raspoloženje budila je budnica.","C":"Ditiramb je svečana pjesma radosti i veselja, a ne borbenosti.","D":"Elegija je tužna, sjetna pjesma, suprotna borbenom zanosu."},
  "2012_ljeto_B__48": {"A":"'Reč domovini' (Štoos) pripada preporodu, a ne najavi realizma.","B":"Predgovor Podravskim motivima je iz 20. stoljeća (Krleža), a ne najava realizma.","D":"Članak 'O romanu' nije programatska najava hrvatskog realizma."},
  "2012_ljeto_B__49": {"A":"Breton (nadrealizam) i Proust (20. st.) ne pripadaju parnasovcima.","B":"Zola i Maupassant su naturalisti/realisti, a ne parnasovci.","C":"Balzac i Flaubert su romanopisci realizma, a ne pjesnici Parnasa."},
  "2012_ljeto_B__50": {"A":"Baudelaire (1821.–1867.) djeluje u 19. stoljeću.","B":"Flaubert (1821.–1880.) pripada 19. stoljeću.","C":"Balzac (1799.–1850.) također stvara u 19. stoljeću."},
  "2012_ljeto_B__51": {"B":"Pogrešno svrstava Frankopana u renesansu (1C); on je barokni pisac.","C":"Pogrešno svrstava Bunića Vučića u renesansu (2C); on pripada baroku.","D":"Pogrešno svrstava Katančića u barok (3C) i Vetranovića u prosvjetiteljstvo (4B)."},
  "2012_ljeto_B__52": {"B":"Pogrešno: Poe/Crni mačak je novela (1B), a ne roman; Cervantes je roman, ne tragedija.","C":"Pogrešno svrstava Zolu (Thérèse Raquin) u novelu (2B) umjesto u roman.","D":"Pogrešno: Poe je novela (1B), a ne tragedija; Proust je roman, ne novela."},
  "2012_ljeto_B__53": {"A":"'Brijest' (bri-jest) ima dva sloga, a ne tri.","C":"'Strijelac' (stri-je-lac) jest trosložna, ali rješenje prema ispitu je krijesnica.","D":"'Trijezno' (tri-jez-no) jest trosložna, no službeno je rješenje krijesnica."},
  "2012_ljeto_B__54": {"A":"Pogrešno piše 'Ujedinjeno kraljevstvo' malim 'k' i 'sjeverne Irske' malim 's'.","B":"Pogrešno piše 'Ujedinjeno kraljevstvo' malim slovom 'k'.","C":"Pogrešno piše 'sjeverne Irske' malim slovom 's' (treba veliko S)."},
  "2012_ljeto_B__55": {"A":"Pravilno je 'dodijeliti — dodjeljivati', a ne 'dodjeliti — dodjeljivati'.","B":"Pravilno je 'pripovijedati', a ne 'pripovjediti — pripovjedati'.","C":"Pravilno je 'riješiti — rješavati', a ne 'rješiti'."},
  "2012_ljeto_B__56": {"A":"'Radio — aktivnost' nije ispravno; radioaktivnost se piše spojeno.","B":"'Radio-aktivnost' nije polusloženica, nego se piše kao jedna riječ.","C":"'Radio aktivnost' s razmakom nije ispravno pisanje složenice."},
  "2012_ljeto_B__57": {"A":"'Isčistiti' je pogrešno; jednačenje daje 'iš', a ne 'is'.","B":"'Ičistiti' izostavlja suglasnik i nije pravilan oblik.","C":"'Izčistiti' je pogrešno; 'z' se ne zadržava ispred 'č'."},
  "2012_ljeto_B__58": {"A":"Iza upitnika unutar navodnika ne stavlja se zarez, pa zarez ovdje višak.","C":"Upitnik mora ostati unutar navodnika upravnog govora, a ovdje je izostavljen.","D":"Upitnik pripada uz pitanje unutar navodnika, a ne na kraj cijele rečenice."},
  "2012_ljeto_B__59": {"A":"Naglasak nije na prvom slogu 'pri-', nego na drugom 'slo-'.","C":"Slog '-nje-' nije naglašen.","D":"Slog '-ni-' nije naglašen."},
  "2012_ljeto_B__60": {"B":"'Zaselku' bi pretpostavljalo gubitak nepostojanog 'a' koji u dativu ostaje.","C":"'Zaseocu' je pogrešna tvorba dativa.","D":"'Zaseoku' nije pravilan dativni oblik imenice zaselak."},
  "2012_ljeto_B__61": {"B":"'Hlače' su pluralia tantum (samo množina), a ne zbirna imenica.","C":"'Pluća' su pluralia tantum, a ne zbirna imenica.","D":"'Usta' su pluralia tantum, a ne zbirna imenica."},
  "2012_ljeto_B__62": {"A":"Komparativ od 'smiješan' je 'smješniji', no rečenica nije rješenje prema ispitu.","B":"Pravilan komparativ je 'vještijim', a ne 'vješćijim'.","D":"'Kraći' je pravilan komparativ, no službeno je rješenje primjer C."},
  "2012_ljeto_B__63": {"A":"'Kličući' nije pravilan oblik glagolskog priloga sadašnjeg od 'kliktati'.","C":"'Kliktajuć' je krnji, neknjiževni oblik.","D":"'Kliktavši' je glagolski prilog prošli, a ne sadašnji."},
  "2012_ljeto_B__64": {"A":"U rečenici nije jedan prijedlog, nego dva ('na' i 'ispod').","C":"Nema tri prijedloga; ima ih točno dva.","D":"Nema četiri prijedloga; samo su dva ('na', 'ispod')."},
  "2012_ljeto_B__65": {"A":"Atribut je 'njezino', a ne 'tijelo' koje je nositelj radnje.","B":"Objekt je 'tijelo' samo prividno; u inverziji je ono vršilac radnje, dakle subjekt.","C":"'Tijelo' nije priložna oznaka, nego subjekt rečenice."},
  "2012_ljeto_B__66": {"A":"'Pravu dramu' — drama je objekt, a ne atribut.","B":"'Redateljem drame' — drama je tu imenički atribut/dopuna, no rješenje prema ispitu je D.","C":"'Dramu Kraljevo' — drama je objekt, a ne atribut."},
  "2012_ljeto_B__67": {"B":"'Iako plove...' je dopusna (zavisnosložena dopusna) rečenica, a ne atributna.","C":"'da vide okolicu' izriče namjeru, dakle namjerna je rečenica.","D":"'da si mrav' je izrična rečenica, a ne atributna."},
  "2012_ljeto_B__68": {"A":"'Kuća' je tu subjekt ('oduševila ih je kuća'), a ne neizravni objekt.","C":"'U onoj kući' je priložna oznaka mjesta, a ne neizravni objekt.","D":"'Kuću' je u akuzativu izravni objekt, a ne neizravni."},
  "2012_ljeto_B__69": {"A":"Rečenica je jednostavna proširena, bez zavisne surečenice.","B":"Rečenica je jednostavna, glagolska imenica 'čitanjem' ne čini je složenom.","C":"Rečenica je jednostavna proširena, nema druge surečenice."},
  "2012_ljeto_B__70": {"A":"'Pun kao šipak koštica' znači pretrpan/sit, suprotno od mršavosti.","C":"'Najesti se ludih gljiva' znači poludjeti, a ne biti mršav.","D":"'Živjeti kao bubreg u loju' znači živjeti u obilju, suprotno mršavosti."},
  "2012_ljeto_B__71": {"B":"Homonimija je istozvučnost različitih značenja, čega ovdje nema.","C":"Polisemija je višeznačnost jedne riječi, a ne odnos dviju riječi.","D":"Sinonimija je istoznačnost, a 'visok' i 'nizak' su suprotni, ne istoznačni."},
  "2012_ljeto_B__72": {"B":"Faust Vrančić sastavio je rječnik (Dictionarium), a ne prvu gramatiku.","C":"Ljudevit Gaj je preporoditelj i pravopisac 19. stoljeća, ne autor prve gramatike.","D":"Vjekoslav Babukić piše gramatiku tek u 19. stoljeću, mnogo nakon Kašića."},

  // 2012_zima_A
  "2012_zima_A__1": {"A":"Ekspresionizam naglašava unutarnju krizu i deformaciju zbilje, dok je ovaj opis građen na osjetilnim dojmovima i bojama.","C":"Realizam teži objektivnom, vjernom prikazu zbilje, a ne dočaravanju prolaznoga raspoloženja i svjetlosnih dojmova.","D":"Romantizam ističe snažan subjektivni zanos i idealizaciju, a ne impresionističko bilježenje trenutačnih osjetilnih dojmova predvečerja."},
  "2012_zima_A__2": {"A":"Stih 'snovi u duši kipe, ko krvave pjene' prikazuje unutarnje stanje duše, a ne zalazak sunca.","B":"'Os zemlje od bola tiho škripi' slika je umiranja dana i boli zemlje, a ne sam čin zalaska sunca.","D":"'I crna ptica nekog beznadno doziva' dočarava sumornu atmosferu, ne prikazuje zalazak sunca."},
  "2012_zima_A__3": {"A":"'Paun' je metafora za sunce, pa odgovor 'pauna' nije doslovno točan jer se traži ono što paun predstavlja.","B":"Vihor (jugozapadnjak) oblake samo bije i goni, ne ubija ih.","D":"Zemlja je u pjesmi 'udovica' koja tuguje, nije ono što je vihor ubio."},
  "2012_zima_A__4": {"B":"Modrozelena nije boja plašta; modra je šuma, a zelena okna palača, dok je plašt grimizan.","C":"Sivobijela boja ne odgovara grimiznom plaštu; siva su tek polja, a bijele žene.","D":"Srebrnozlatna boja nigdje se ne pripisuje plaštu koji je grimizan, tj. ljubičastocrven."},
  "2012_zima_A__5": {"B":"Pridjev 'večernjem' dio je atributnoga skupa uz 'plaštu' i nije izdvojen na čelo stiha inverzijom.","C":"Imenica 'plaštu' nalazi se unutar priložne oznake i nije naglašena premještanjem na početak.","D":"Predikat 'bije' stoji na kraju stiha kao posljedica inverzije, ali naglašena je riječ pomaknuti subjekt 'jugozapadnjak'."},
  "2012_zima_A__6": {"A":"Anadiploza ponavlja zadnju riječ jednoga stiha na početku sljedećega, a ovdje se 'on' ponavlja na samom početku stihova.","C":"Epifora znači ponavljanje na kraju stihova, dok je 'on' ovdje na početku.","D":"Simploka spaja anaforu i epiforu (isti početak i isti kraj), a ovdje se ponavlja samo početak."},
  "2012_zima_A__7": {"A":"Bog se spominje tek u sklopu 'mašta bogova', što je jedna od metafora za 'on', a ne ono što zamjenica označava.","B":"Gejzir je samo jedna od slika ('grimizan gejzir') kojom se 'on' opisuje, nije njegovo značenje.","C":"Gnjev se javlja u posljednjem stihu kao ono što se prebolijeva, a ne kao ono što 'on' označava."},
  "2012_zima_A__8": {"B":"Sedam bi se dobilo ubraja li se i 'čudakov spjev', no točan se broj odnosi na šest izravnih metafora u retcima 'On je...'.","C":"Osam premašuje broj pojmova s kojima se 'on' metaforički povezuje.","D":"Devet je previše; pjesma povezuje zamjenicu 'on' sa šest pojmova."},
  "2012_zima_A__9": {"A":"Grmljavina nije značenje riječi 'dažd'; ta arhaična riječ označava kišu.","C":"Munja nije značenje 'dažda', koji znači kišu.","D":"Vulkan se ne podudara s arhaičnim značenjem riječi 'dažd' (kiša)."},
  "2012_zima_A__10": {"B":"Kvintine imaju pet stihova, a strofe ove pjesme imaju po četiri stiha.","C":"Oktave imaju osam stihova, dok ovdje strofa broji četiri.","D":"Septime imaju sedam stihova, a ne četiri kao katrene u ovoj pjesmi."},
  "2012_zima_A__11": {"A":"Fama ne donosi san; njoj 'san očiju ne sklapa', a ona širi glasine.","B":"Fama ne izaziva oluju, nego raznosi vijesti i glasine među narodom.","C":"Proricanje sudbine nije Famina uloga; ona širi i istinite i lažne glase."},
  "2012_zima_A__12": {"A":"Srdžba bogova vezana je uz Famino rođenje (majka Zemlja srdila se na bogove), ali nju ne čini jačom.","B":"Stalna budnost ('san joj očiju ne sklapa') njezino je svojstvo, no snažnijom je čini gibanje.","D":"Strašna nakaznost (mnoštvo očiju, ušiju, usta) opisuje njezin izgled, ali jača jer se neprekidno kreće."},
  "2012_zima_A__13": {"A":"Asindeton je nizanje bez veznika, a u ovom stihu nema takva niza članova.","B":"Elipsa je izostavljanje dijela rečenice, no ovdje je rečenica potpuna, samo s premještenim subjektom.","D":"Polisindeton je gomilanje veznika, čega u ovom stihu nema."},
  "2012_zima_A__14": {"A":"Stih o tome kako se Fama 'diže uvis' opisuje njezin rast i kretanje, ne djelovanje na ljude.","B":"Slika kako 'nogama stupa po zemlji, u oblake sakriva glavu' prikazuje njezinu golemost, a ne učinak na ljude.","C":"Stih o mnoštvu očiju opisuje Famin nakazni izgled, a ne njezino djelovanje na ljude."},
  "2012_zima_A__15": {"A":"Dante je srednjovjekovni/predrenesansni talijanski pisac (13.–14. st.), a ne suvremenik rimske antike.","B":"Eshil je grčki tragičar 5. st. pr. Kr., znatno stariji od Vergilija i iz druge sredine.","C":"Homer je starogrčki epik (oko 8. st. pr. Kr.), mnogo stariji od Vergilija."},
  "2012_zima_A__16": {"A":"Lik nije od Europe očekivao običan život; štoviše, podražavao je običnom čovjeku, a čeznuo za novim i skrivenim.","C":"Pronalazak srodnih duša nije ono čemu se nadao; tražio je 'ono novo i sakriveno u duši'.","D":"Tekst ne kaže da je očekivao postati bolja osoba, nego promjenu, nešto novo, što ipak nije našao."},
  "2012_zima_A__17": {"A":"Rečenica o žaljenju za hrvatskim selom iskazuje nostalgiju, ali bez hiperboličnoga preuveličavanja osjećaja.","B":"Iskaz da ljubi samo daleko i nedokučivo karakterizira njegovu narav, ali nije hiperbola.","C":"Opis 'smirena izraza slijepca ili mrtvaca' poredba je o licu, a ne preuveličavanje osjećaja."},
  "2012_zima_A__18": {"A":"Tekst ne prikazuje jednosmjeran prijelaz iz ateizma u vjeru, nego stalno izmjenjivanje jednoga i drugoga.","C":"Nije riječ o gubitku vjere u ljude koji vodi vjeri u Boga, nego o stalnom kolebanju između nevjere i predanosti.","D":"Vjera mu nije utjeha samo u neimaštini; izmjena ateizma i asketstva nije vezana uz materijalno stanje."},
  "2012_zima_A__19": {"A":"Basna je kratka pripovijest s poukom i likovima životinjama, što ne odgovara Camau.","B":"Crtica je još kraći, fragmentarni oblik, dok je Camao razvijeniji pripovjedni tekst novele.","D":"Roman je opsežna proza s razgranatom radnjom, a Camao je kraća prozna vrsta."},
  "2012_zima_A__20": {"A":"Miroslav Krleža pripada međuratnoj književnosti i ekspresionizmu, a ne razdoblju moderne kao Matoš.","B":"Silvije Strahimir Kranjčević pripada razdoblju realizma/protomoderne, prethodi Matoševu naraštaju.","C":"Tin Ujević javlja se nešto kasnije i šire se vezuje uz međuratnu liriku, a tražen je čisti suvremenik moderne."},
  "2012_zima_A__21": {"A":"Govor se ne tiče dobrosusjedskih odnosa, nego buđenja i obrane nacije.","C":"Premda se Bog spominje u molitvi, tema govora nije Božja providnost nego nacionalna svijest.","D":"Govor nije o životu i smrti općenito, nego o nacionalnom buđenju i opstanku naroda."},
  "2012_zima_A__22": {"A":"Neiskvarenost nije zajednička osobina; naprotiv, i dijete i narod lako se daju kupiti.","C":"Stidljivost nije istaknuta osobina; tekst ističe da se narod ponosi onim čega se drugi stide.","D":"Zaigranost nije poanta usporedbe; naglasak je na tome da se i dijete i narod lako kupuju (potkupljivost)."},
  "2012_zima_A__23": {"A":"Ovdje 'Turčin, Talijan, Nijemac' stoje za čitave narode, što jest metonimija, pa rečenica nije iznimka.","B":"'Naša krv čuva Europu' rabi krv kao metonimiju za narod, pa rečenica sadrži metonimiju.","C":"'Jezgra kraljevstva' metonimijski označava njegovu srž, pa i ova rečenica koristi metonimiju."},
  "2012_zima_A__24": {"A":"Djelomice znači 'dijelom', a ne 'namjerno' kao 'hotimice'.","B":"Hrabro nije značenje riječi 'hotimice', koja znači namjerno.","D":"Slučajno je upravo suprotno od 'hotimice', koje znači s namjerom."},
  "2012_zima_A__25": {"A":"Ante Kovačić vezuje se uz zagorsko-sjeverni krug realizma, a ne primorski kao Novak.","B":"Eugen Kumičić jest s Kvarnera/Istre, no tražen je pisac iz istoga senjsko-primorskoga kruga kao Kranjčević.","C":"Ksaver Šandor Gjalski pripada zagorskom regionalnom krugu, a ne primorskom."},
  "2012_zima_A__26": {"A":"Phoebe ne sprema se Holdena udariti jastukom, nego ga njime prekriva i ne sluša njegove molbe.","B":"Ne radi se o pravljenju važnom, nego o tvrdoglavu odbijanju i prkosu prema Holdenu.","D":"Phoebe se ne boji Holdena; ona ga čak udara šakom i odbija ga poslušati, čime mu se suprotstavlja."},
  "2012_zima_A__27": {"B":"U ulomku nema spomena bijega od kuće kao razloga; Phoebe reagira na to što su ga izbacili.","C":"Gubitak posla nije razlog; riječ je o izbacivanju iz škole.","D":"Pušenje u kući ne spominje se kao razlog; Phoebe se uzrujava zbog isključenja iz škole."},
  "2012_zima_A__28": {"B":"Objektivno pripovijedanje vodio bi nepristrani treći lik, no ovdje Holden pripovijeda u prvom licu i subjektivno.","C":"Unutarnji monolog bilježio bi tijek vlastitih misli, dok Holden ovdje izvanjski i dijaloški prikazuje Phoebe.","D":"Vanjski opis nije postupak karakterizacije Phoebe; ona se otkriva kroz subjektivnu Holdenovu pripovijed i njezine postupke."},
  "2012_zima_A__29": {"A":"Phoebe nije tek prijateljica, nego Holdenova mlađa sestra.","B":"Phoebe nije Holdenova djevojka, nego njegova mlađa sestra.","C":"Phoebe nije susjeda, nego Holdenova mlađa sestra."},
  "2012_zima_A__30": {"A":"Monološko-asocijativni roman gradi se na slobodnu toku asocijacija, što ne odgovara fabularnoj, žargonskoj prozi Lovca u žitu.","C":"Roman struje svijesti prikazuje neuredan tok svijesti, a Salingerov roman pripovijeda kolokvijalno, ali pripovjedno koherentno.","D":"Esejistički roman obiluje refleksijama i raspravama, čega nema u buntovnoj prozi u trapericama."},
  "2012_zima_A__31": {"A":"Auditivni podražaj odnosio bi se na zvuk, no sjećanje budi miris badema.","B":"Gustativni podražaj vezan je uz okus, dok je ovdje riječ o mirisu.","D":"Taktilni podražaj odnosi se na dodir, a sjećanje izaziva miris (olfaktivni podražaj)."},
  "2012_zima_A__32": {"A":"Obrazi gospođice Vinteuil samo su usporedba (miris skriven ispod pjega), a ne mjesto skrivenoga mirisa badema.","B":"Ticala kukaca dio su poredbe o titranju oltara, a ne mjesto gdje je miris skriven.","D":"Bademnjaci su navedeni samo kao usporedba (miris slatkiša pod zapečenim dijelovima), a miris dolazi iz glogova cvijeća."},
  "2012_zima_A__33": {"A":"Kulinarske delicije nisu izvor zanosa; bademnjak se spominje tek kao poredba mirisa.","C":"Vjerski ushit nije uzrok zanesenosti, premda se zbiva u crkvi; pripovjedača zanosi miris i ljepota cvijeta.","D":"Ženska ljepota nije izvor zanosa; gospođica Vinteuil spominje se samo u poredbi o mirisu."},
  "2012_zima_A__34": {"A":"Kozmološko vrijeme vezano je uz red svemira, a Proust vrijeme doživljava subjektivno, kroz sjećanje.","B":"Kronološko vrijeme teče linearno i mjerljivo, što je suprotno Proustovu psihološkom poimanju.","C":"Meteorološko vrijeme odnosi se na vremenske prilike i nema veze s Proustovim poimanjem vremena."},
  "2012_zima_A__35": {"A":"Čvrsta fabula obilježje je tradicionalnoga romana, dok Proustov tekst razbija jasnu radnju.","B":"Epistolarni dijelovi (pisma) nisu obilježje Combraya, koji je građen na sjećanju i refleksiji.","D":"Socijalna motivacija tipična je za realizam, a ne za modernistički, esejistički karakter Proustova teksta."},
  "2012_zima_A__36": {"B":"Fedrin žar ne izaziva njezin sin, nego posinak Hipolit.","C":"Tezejev otac nije predmet Fedrine strasti; ona je zaljubljena u posinka Hipolita.","D":"Tezejev stražar ne potiče Fedrin žar; riječ je o posinku Hipolitu."},
  "2012_zima_A__37": {"A":"Tekst ne pokazuje da Fedra pomišlja na samoubojstvo, nego da prezire samu sebe zbog strasti.","B":"Fedru ne muči neizvjesnost; ona jasno spoznaje svoju nepoštenost i mračne strasti.","D":"Fedra ne niječe grijeh; priznaje da je nepoštena ('ja sam nepoštena') i prezire se."},
  "2012_zima_A__38": {"A":"Ljubomoru Fedra ne pripisuje himbenim ženama; prigovara im pretvaranje.","B":"Nevjeru im izravno ne zamjera; 'himbeno čelo' upućuje na licemjerje, tj. prijetvornost.","D":"Sebičnost nije ono što Fedra prigovara; 'himben' znači licemjeran, prijetvoran."},
  "2012_zima_A__39": {"B":"Molière je pisac komedija, a Fedru je napisao Racine.","C":"Pierre Corneille jest klasicistički tragičar, ali autor Fedre je Racine.","D":"Voltaire pripada prosvjetiteljstvu i nije autor Fedre."},
  "2012_zima_A__40": {"A":"Drama u užem smislu prikazuje ozbiljan sukob bez nužno tragična ishoda, dok Fedra ima obilježja prave tragedije.","B":"Farsa je gruba komedija, što je posve suprotno ozbiljnoj i sudbinski intoniranoj Fedri.","C":"Tragikomedija spaja tragično i komično, a Fedra je dosljedna klasicistička tragedija."},
  "2012_zima_A__41": {"A":"Anafora je ponavljanje riječi na početku, a ne odstupanje od reda riječi.","C":"Metafora je prijenos značenja po sličnosti, a ne premještanje reda riječi.","D":"Polisindeton je gomilanje veznika, a ne odstupanje od gramatičkoga reda riječi."},
  "2012_zima_A__42": {"B":"Pučka epika nije izvor Juditine teme; ona slijedi starozavjetnu, biblijsku predaju.","C":"Tursko-hajdučka epika javlja se kasnije i nije izvor biblijske teme Judite.","D":"Viteška epika srednjovjekovni je svjetovni žanr, a Judita preuzima biblijsku temu."},
  "2012_zima_A__43": {"A":"Antigermanska linija ne odgovara tradiciji Marulića, Zoranića i Karnarutića, koja je antiturska.","B":"Antimletačka linija nije zajednička navedenim piscima; njihova je tradicija antiturska.","D":"Antiugarska linija ne povezuje te pisce; riječ je o antiturskoj epskoj tradiciji."},
  "2012_zima_A__44": {"A":"Spoj asonance i aliteracije glasovno je obilježje, ali sinestezija nastaje spajanjem osjetilnih podražaja, ne glasova.","B":"Nizanje uskličnih rečenica naglašava emociju, no sinestezija znači prožimanje različitih osjetila.","D":"Ponavljanje istoga korijena tvorbeni je postupak (figura dikcije), a ne spajanje osjetila kakvo čini sinesteziju."},
  "2012_zima_A__45": {"A":"8. st. pr. Kr. razdoblje je Homerova epa, a ne atičke tragedije triju velikih tragičara.","C":"1. st. (n. e.) pripada rimskoj, a ne grčkoj klasičnoj tragediji.","D":"5. st. (n. e.) prekasno je; veliki grčki tragičari stvaraju u 5. st. pr. Kr."},
  "2012_zima_A__46": {"B":"Stihovi o 'opasnoj ženi' i 'studi grobne zime' donose tamne, kontrastne slike, a ne idealiziranu petrarkističku ljepotu.","C":"Poredba mirisa daha ostvaruje osjetilnu sliku, ali ne tipične petrarkističke motive zlatne kose i začaravajućih očiju.","D":"Stihovi o striženju vlasi s mrtvaca i crvima groteskna su, makabristička slika, suprotna petrarkističkom idealu ljepote."},
  "2012_zima_A__47": {"A":"Ignjat Đurđević barokni je pjesnik, ali stihovi o 'slatkoj slobodi' Gundulićevi su.","B":"Ivan Bunić Vučić piše ljubavnu liriku, a slavospjev slobodi pripada Gunduliću.","D":"Junije Palmotić poznat je po dramama, a stihove o slatkoj slobodi napisao je Gundulić."},
  "2012_zima_A__48": {"A":"Dubravka (Gundulić) djelo je baroka, a ne prosvjetiteljstva.","B":"Putositnice (Antun Nemčić) pripadaju hrvatskom romantizmu/preporodu, a ne prosvjetiteljstvu.","D":"Smrt Smail-age Čengića (Mažuranić) djelo je romantizma, a ne prosvjetiteljstva."},
  "2012_zima_A__49": {"A":"Spaljivanje mađarske zastave 1905. lokalni je politički događaj i nije pokrenuo ekspresionizam.","B":"Gospodarska kriza 1929.–1933. zbila se nakon procvata ekspresionizma, pa ga nije izazvala.","C":"Bachov apsolutizam (sredina 19. st.) vremenski je daleko prije ekspresionizma."},
  "2012_zima_A__50": {"B":"Plamen je izlazio 1919. (Krleža i Cesarec), znatno prije razdoblja 1952.–1958.","C":"Razlog počinje izlaziti 1961., dakle nakon traženoga razdoblja.","D":"Vijavica je avangardni list iz 1917., a ne časopis iz 1950-ih."},
  "2012_zima_A__51": {"B":"Netočno je jer Lamartine pripada romantizmu (C), a ne realizmu, a Gogolj realizmu (B), ne romantizmu.","C":"Netočno je jer Flaubert je realist (B), no Gogolj je također realist (B), a ne romantik (C) kako stoji u toj kombinaciji.","D":"Netočno je jer Flaubert je realist (B), a ne romantik (C) kako navodi ta kombinacija."},
  "2012_zima_A__52": {"B":"Netočno je jer Psi u trgovištu (Galović) drama su (A), a ne novela (B), te Ruke (Šimunović) novela (B), a ne drama (A).","C":"Netočno je jer Cvijet sa raskršća (Leskovar) novela je (B), a ne drama (A).","D":"Netočno je jer Ruke (Šimunović) novela su (B), a ne drama (A)."},
  "2012_zima_A__53": {"B":"Netočno je 'primjeniti'; pravilno je 'primijeniti' (s ije), pa par nije ispravan.","C":"Netočno je 'razumjevati'; pravilno je 'razumijevati' (s ije).","D":"Netočno je 'zapovjedati'; pravilno je 'zapovijedati' (s ije)."},
  "2012_zima_A__54": {"A":"Oblik 'rasčetvoriti' netočan je jer ispred 'č' mora doći 'š' (jednačenje po zvučnosti/mjestu tvorbe).","C":"Oblik 'razčetvoriti' netočan je jer se 'z' ispred 'č' mijenja u 'š'.","D":"Oblik 'ražčetvoriti' netočan je jer pravilan glasovni slijed daje 'raščetvoriti'."},
  "2012_zima_A__55": {"A":"U 'baka' sibilarizacija se u dativu ne provodi (ostaje 'baki').","B":"U 'Olga' sibilarizacija se ne provodi jer je riječ o vlastitu imenu (dativ 'Olgi').","D":"U 'seka' sibilarizacija se ne provodi u dativu (ostaje 'seki')."},
  "2012_zima_A__56": {"B":"U 'obrubljen' nema jednačenja po mjestu tvorbe; tu je provedeno epentetsko 'lj' (jotacija/umetanje).","C":"U 'odbačen' provodi se jednačenje po zvučnosti (d ostaje pred b), a ne po mjestu tvorbe.","D":"U 'određen' provedena je jotacija (d+j), a ne jednačenje po mjestu tvorbe."},
  "2012_zima_A__57": {"A":"Netočno je jer se opisna imenica 'monarhija' piše malim slovom, a ne 'Monarhija'.","C":"Netočno je jer obje sastavnice imena moraju biti velike: 'Austro-Ugarska', a ne 'Austro-ugarska'.","D":"Netočno je jer se ime piše velikim početnim slovima sastavnica, a ne malim 'austro-ugarska'."},
  "2012_zima_A__58": {"A":"Sastavljeno pisanje 'slavonskobrodski' netočno je jer pridjev od toponima 'Slavonski Brod' traži crticu.","C":"Pisanje s razmakom 'slavonsko brodski' netočno je jer se piše s crticom.","D":"Crtica s razmacima netočna je jer se rabi spojnica (crtica) bez razmaka: 'slavonsko-brodski'."},
  "2012_zima_A__59": {"A":"Netočno je jer nedostaju zarezi koji odvajaju umetnuti dio 'reče mu odlučno'.","C":"Netočno je jer zarez ne ide unutar navodnika ('Ne želim,'), nego iza zatvorenoga navodnika.","D":"Netočno je jer nedostaje zarez iza umetnutoga 'odlučno' prije nastavka navoda."},
  "2012_zima_A__60": {"A":"'rukavic-a' netočno je jer ne razdvaja tvorbene sufikse '-av-' i '-ic-'.","B":"'rukav-ic-a' netočno je jer ne izdvaja sufiks '-av-' iz korijena.","C":"'ruka-vic-a' netočno je jer pogrešno određuje granice morfema; korijen je 'ruk-'."},
  "2012_zima_A__61": {"B":"'Granje' je zbirna imenica srednjega roda, a ne ženskoga.","C":"'Leđa' je imenica srednjega roda (pluralia tantum), a ne ženskoga.","D":"'Vrata' je imenica srednjega roda (pluralia tantum), a ne ženskoga."},
  "2012_zima_A__62": {"A":"U 'vratio sam se u moj rodni grad' posvojna je zamjenica suvišna; trebala bi povratno-posvojna 'svoj'.","C":"U 'uzmite vašu karticu' bolje stoji povratno-posvojna 'svoju', pa je 'vašu' neprimjereno.","D":"U 'posudi mi tvoj šešir' umjesto 'tvoj' pravilnije je povratno-posvojno 'svoj'."},
  "2012_zima_A__63": {"B":"'Puhavši' je glagolski prilog prošli, a traži se prilog sadašnji.","C":"'Pušeći' je netočan oblik jer glagol 'puhati' tvori prilog 'puhajući'.","D":"'Pušući' nije pravilan oblik priloga glagola 'puhati'."},
  "2012_zima_A__64": {"A":"Dvije je premalo; nepromjenljive su 'ipak', 'jučer' i 'iznenada' (tri).","C":"Četiri je previše; 'ju' i 'je' promjenljive su (zamjenica i glagol), pa ostaju tri nepromjenljive.","D":"Pet je previše; u rečenici su samo tri nepromjenljive riječi."},
  "2012_zima_A__65": {"A":"'Kako bi mogao položiti' namjerna je surečenica, a ne atributna uz 'potvrdu'.","B":"'O položenom stručnom ispitu' prijedložni je atribut, ne atributna surečenica (nema predikata).","C":"'Jer je položio' uzročna je surečenica, a ne atributna."},
  "2012_zima_A__66": {"A":"'Što će li nam darovati?' netočno je jer čestica 'li' mora doći odmah iza prve naglašene riječi 'što'.","B":"'Što će nam li darovati?' netočno je jer 'li' ne smije stajati iza klitika, nego iza prve naglašene riječi.","D":"'Što li nam će darovati?' netočno je jer naglašeni glagolski oblik 'će' ne smije stajati iza nenaglašenih klitika."},
  "2012_zima_A__67": {"A":"'Budući da piješ' uzročna je zavisna rečenica, a ne pogodbena.","B":"'Iako ne piješ' dopusna je rečenica, a ne pogodbena.","C":"'Kad piješ' vremenska je rečenica, a ne pogodbena."},
  "2012_zima_A__68": {"A":"'Neozbiljan' nastao je prefiksalno-sufiksalnom tvorbom (ne- + ozbiljan), a ne čistom sufiksalnom.","C":"'Sumrak' nastao je prefiksacijom (su- + mrak), a ne sufiksalnom tvorbom.","D":"'Uzglavlje' nastalo je prefiksalno-sufiksalnom tvorbom (uz- + glav- + -je), a ne samo sufiksacijom."},
  "2012_zima_A__69": {"A":"'Anić' je prezime izvedeno od imena/nadimka, ali traženi je primjer patronim 'Marić'.","B":"'Jurić' jest tvoreno od imena Jure, no kao odgovor traži se 'Marić'.","C":"'Magdić' izvedeno je od imena Magda, ali odabrani točan primjer patronima jest 'Marić'."},
  "2012_zima_A__70": {"B":"Posuđenice iz portugalskoga nisu galicizmi, nego lusitanizmi.","C":"Posuđenice iz španjolskoga nisu galicizmi, nego hispanizmi.","D":"Posuđenice iz talijanskoga nisu galicizmi, nego talijanizmi."},
  "2012_zima_A__71": {"A":"'Fit' ostaje nepromjenljiv i morfološki neprilagođen pridjev.","B":"'Mini' (suknja) nesklonjiv je i morfološki neprilagođen oblik.","D":"'Fer' je nepromjenljiv pridjev koji nije morfološki prilagođen hrvatskomu."},
  "2012_zima_A__72": {"A":"Riječka filološka škola zagovarala je čakavsko-štokavski smjer, a ne ikavsku štokavštinu kao osnovu.","B":"Škola hrvatskih vukovaca zalagala se za štokavsku ijekavicu (vukovski model), a ne ikavicu.","D":"Zagrebačka filološka škola promicala je tronarječni temelj i grafiju s 'rogatim e', a ne ikavsku štokavštinu."},

  // 2012_zima_B
  "2012_zima_B__1": {"B":"Razmaknuto otiskivanje grafički ističe zbivanja, a ne raspoloženje subjekta.","C":"Upravni se govor označava navodnicima ili crticom, ne razmicanjem slova.","D":"Razmicanje slova ne dočarava nemir mora, nego ističe ključne trenutke."},
  "2012_zima_B__2": {"A":"Epitet bi bio pridjev uz imenicu (npr. zlatno more), a ovdje je imenica izjednačena s morem.","C":"Oksimoron spaja proturječne pojmove, a 'more' i 'zlato' nisu suprotni.","D":"Poredba bi tražila veznik usporedbe (kao, poput), kojega ovdje nema."},
  "2012_zima_B__3": {"A":"Drugi stih ('i slušam more dobrojutro veli') govori da more pozdravlja subjekta, ne sebe.","B":"Četvrti stih ('pa opet tiše ponovim mu pozdrav') je pozdrav lirskoga subjekta moru.","D":"Jedanaesti stih ('i zagrli me more oko vrata') ne sadrži pozdrav, nego zagrljaj."},
  "2012_zima_B__4": {"A":"Stih ima 11 slogova, pa nije deveterac.","B":"Stih ima 11 slogova, pa nije deseterac.","D":"Stih ima 11, a ne 12 slogova, pa nije dvanaesterac."},
  "2012_zima_B__5": {"B":"Postmodernizam nastupa kasnije (kraj 20. st.), a Pupačić stvara 1950-ih i 60-ih.","C":"Realizam je razdoblje 19. stoljeća, dok Pupačić pripada 20. stoljeću.","D":"Romantizam je također razdoblje 19. stoljeća, a ne Pupačićeva vremena."},
  "2012_zima_B__6": {"B":"Stih govori o zarobljenosti ljubavlju, a ne o staleškoj (društvenoj) razlici.","C":"Riječ je o predanosti voljenoj, ne o tjelesnoj (putenoj) ljubavi.","D":"Naglasak je na potčinjenosti subjekta, a ne na opisu ženine ljepote."},
  "2012_zima_B__7": {"A":"Eufemizam je ublažavanje neugodna pojma, a ovdje se očima pripisuje prenesena radnja.","B":"Gradacija je stupnjevanje, a u primjeru nema postupnog pojačavanja.","C":"Inverzija je obrnut red riječi, a ovdje je riječ o prenesenom značenju."},
  "2012_zima_B__8": {"B":"Pjesnik ne zaziva Božju pomoć, nego govori o slavi koju stječe pisanjem.","C":"Slavu stječe pjesnik za sebe ('stječem sebi slavu'), a ne za dragu.","D":"Tercina ne govori o uzvraćenoj ljubavi, nego o slavi kroz pjesništvo."},
  "2012_zima_B__9": {"A":"Džore Držić je petrarkist, ali nije autor imitacije ovoga Petrarkina soneta.","B":"Hanibal Lucić pripada kasnijem naraštaju i nije autor te pjesme.","C":"Marin Držić je komediograf, a ne autor ove petrarkističke pjesme."},
  "2012_zima_B__10": {"A":"Petrarca živi u 14. st. (1304.–1374.), a ne u 13. stoljeću.","C":"15. stoljeće je nakon Petrarkine smrti, pa nije točno.","D":"16. stoljeće je predaleko; Petrarca pripada 14. stoljeću."},
  "2012_zima_B__11": {"A":"Stih ne govori o nadmoći nad Crnogorcima, nego o promašaju koji pogađa svoga.","C":"Riječ nije o osveti, nego o nehotičnoj pogrešci u bacanju džilita.","D":"Aga se ne boji Crnogoraca; promašio je i pogodio Turčina umjesto Crnogorca."},
  "2012_zima_B__12": {"A":"Džilit nije baklja, nego oružje za bacanje.","C":"Džilit je kratko koplje (sulica), a ne vatreno oružje poput puške.","D":"Sablja je sječivo oružje, dok je džilit koplje za bacanje."},
  "2012_zima_B__13": {"A":"Stih opisuje konkretnu radnju (zalijetanje na plijen), a nije opća mudrost.","C":"Stih izriče konkretan stav o haraču, a ne poslovičnu mudrost.","D":"Stih je uzvik tuge nad sudbinom, a ne poslovica općega smisla."},
  "2012_zima_B__14": {"A":"Stih opisuje aginu radnju (nadmetanje), a ne pripovjedačev stav.","C":"Stih iznosi tijek događaja (promašaj), bez pripovjedačeve ocjene age.","D":"Stih opisuje aginu reakciju, a ne pripovjedačev osobni sud o njemu."},
  "2012_zima_B__15": {"A":"Agovanje je drugo pjevanje koje ne sadrži ovaj ulomak o haraču.","B":"Noćnik je zasebno pjevanje koje se ne podudara s prizorom haranja.","C":"Četa je pjevanje o crnogorskoj družini, a ne o haraču i džilitanju."},
  "2012_zima_B__16": {"A":"Tekst je pismo prijatelju Wilhelmu, a ne obraćanje Lottinu ocu.","B":"Werther se ne obraća Lottinu zaručniku, nego prijatelju.","D":"Priroda je predmet opisa, ali se Werther obraća prijatelju Wilhelmu."},
  "2012_zima_B__17": {"B":"Gustativni (okusni) podražaji ne pojavljuju se u opisu oluje.","C":"Olfaktivni (mirisni) podražaji nisu navedeni u tekstu.","D":"Taktilni (dodirni) podražaji nisu istaknuti; istaknuti su zvukovi (huka)."},
  "2012_zima_B__18": {"A":"Naježiti se od straha izražava strah pred prizorom, a ne robovanje pravilima.","B":"Podmukla bujica opisuje prirodu, a ne osjećaj sputanosti pravilima.","C":"Potonuti u milje izražava želju za predajom valovima, a ne robovanje."},
  "2012_zima_B__19": {"B":"Rečenica izražava želju za propašću, a ne oduševljenje prirodom.","C":"U rečenici nema motiva putovanja, nego porive ka ponoru.","D":"Werther se ne boji oluje, nego je privlači propast ('dolje, dolje')."},
  "2012_zima_B__20": {"A":"Rečenica izražava nezadovoljstvo ljudskim stanjem, a ne eufemizam za smrt.","B":"Rečenica je opis krajolika (dolina kao more), bez govora o smrti.","C":"Rečenica slikovito prikazuje vodu, a ne eufemistično smrt."},
  "2012_zima_B__21": {"A":"Ivica nikome ne oduzima život; riječ je o njegovoj grižnji savjesti.","C":"Ivica ne prezire Lauru, nego se prekorava zbog grijeha.","D":"Ivica se ne hvali, nego osjeća stid i grize ga savjest."},
  "2012_zima_B__22": {"A":"Naslikana ruža govori o umjetnoj ljepoti, a ne o opasnoj ženi.","B":"Oganj nebeski ne nosi smisao istodobne privlačnosti i opasnosti žene.","C":"Pobožna seljanka označava krepost, suprotnost zavodljivoj i opasnoj ženi."},
  "2012_zima_B__23": {"A":"'Ubavo' ne znači jadno, nego krasno i lijepo.","C":"'Ubavo' ne znači punačno, nego lijepo, ljupko.","D":"'Ubavo' ne znači vitko, nego krasno, ljupko."},
  "2012_zima_B__24": {"A":"Ivica je onaj kojemu se opomena upućuje, pa je ne izgovara on.","B":"Laura ne izgovara opomenu; ona je predmet Ivičine želje i grijeha.","C":"Majka se ne pojavljuje kao govornik u ovom prizoru."},
  "2012_zima_B__25": {"B":"Rečenica govori o tome gdje je Ivica smješten, a ne o dvojakosti ljubavi.","C":"Rečenica usporeĐuje umjetnu i živu ljepotu, a ne razornost ljubavi.","D":"Rečenica izražava Ivičinu jezu i hladnoću, a ne dvojaku narav ljubavi."},
  "2012_zima_B__26": {"B":"Stranac (Camus) nema likove Kyrialesa i slikara Filipa.","C":"U registraturi je Kovačićev roman, a ovi su likovi Krležini.","D":"Zločin i kazna (Dostojevski) ne sadrži Kyrialesa i Filipa."},
  "2012_zima_B__27": {"A":"Razmišljanje o vlastitim podrovanostima pokazuje Kyrialesovu slabost, ne nadmoć.","B":"'Ruševina od čovjeka' je Kyrialesova samokritika, a ne znak nadmoći nad slikarom.","D":"Žaljenje kroz maglu rakije ne izražava nadmoć nad Filipom."},
  "2012_zima_B__28": {"A":"Izraz se ne odnosi na filozofe općenito, nego na samoga Kyrialesa.","C":"'Slabić' je dio iste samokarakterizacije, ali se sintagma odnosi na Kyrialesa kao osobu.","D":"Izraz se ne odnosi na slikara, nego na Kyrialesa koji misli o sebi."},
  "2012_zima_B__29": {"A":"To je filozofsko značenje dijalektike (teza-antiteza), a ne smisao u tekstu.","B":"Riječ ne znači teoriju grešaka duha, nego umijeće raspravljanja.","C":"Evolucija pojava nije značenje dijalektike u Kyrialesovu kontekstu."},
  "2012_zima_B__30": {"B":"Kyriales ne razotkriva osrednjost, nego slikarovu nesigurnost i sumnju u sebe.","C":"Površnost nije ono što Kyriales razotkriva, nego nesigurnost.","D":"Slaboumnost je Kyrialesova uvreda, a razotkrivena slaba strana je nesigurnost."},
  "2012_zima_B__31": {"A":"Euklion nije grub jer je drži nepristojnom, nego jer misli da ga uhodi.","B":"Riječ nije o gunđanju, nego o sumnji da ga Stafila špijunira.","C":"Euklion je ne smatra lijenom, nego sumnja da ga uhodi (jastrebooko uhačalo)."},
  "2012_zima_B__32": {"A":"'Nosi se' je doslovan poziv na odlazak, bez prenesena značenja.","B":"'Gnusno' je pogrdan pridjev u doslovnom značenju, bez metafore.","D":"'Uhačalo' nosi pogrdno značenje, ali metaforički je nositelj 'jastrebooko' (oči kao u jastreba)."},
  "2012_zima_B__33": {"A":"Ironija znači reći suprotno od mišljenoga, a Euklionova je škrtost izravno pretjerana.","C":"Komentar (pripovjedačev) nije postupak; lik je obilježen komičnim pretjerivanjem.","D":"Sarkazam je zajedljiv podsmijeh, a Euklion je obilježen karikiranjem osobine."},
  "2012_zima_B__34": {"A":"Hanibal Lucić nije preradio Plautova Škrtca; to je učinio Marin Držić u Skupu.","B":"Ivan Gundulić je barokni pjesnik, nije preradio Plautova Škrtca.","D":"Tituš Brezovački pisao je kasnije komedije, a Škrtca je preradio Marin Držić."},
  "2012_zima_B__35": {"A":"Komedija intrige gradi se na spletkama, a Škrtac na jednoj dominantnoj osobini lika.","B":"Komedija konverzacije počiva na duhovitu dijalogu, a ne na karakteru lika.","D":"Komedija situacije počiva na smiješnim zgodama, a Škrtac na karakteru (škrtosti)."},
  "2012_zima_B__36": {"A":"Nora ne odlazi zbog neslaganja s ambicijama, nego jer je Helmer ne razumije.","B":"Nora nije zaljubljena u Ranka; razlog odlaska je nerazumijevanje.","D":"Helmer ju nije prevario; Nora odlazi jer je on ne razumije kao osobu."},
  "2012_zima_B__37": {"A":"Nora ne doživljava Helmera brižnim, nego sebičnim (mislio je na sebe).","C":"Riječ nije o pohlepi, nego o Helmerovu sebičnom strahu za sebe.","D":"Helmer nije prikazan kao prijetvoran, nego kao egoistčan."},
  "2012_zima_B__38": {"A":"Nora se otkriva osviještenom; krhkost joj je nametnula Helmerova predodžba lutke.","C":"Nora nije razmažena, nego je spoznala svoj položaj ('otvorile su mi se oči').","D":"Nora nije zaljubljena, nego osviještena o svom položaju u braku."},
  "2012_zima_B__39": {"A":"Rečenica izražava očaj, a ne odnos prema Nori kao prema lutki.","C":"Rečenica govori o godinama braka i djeci, a ne o tretmanu lutkom.","D":"Rečenica iznosi Norinu promjenu, a ne Helmerov odnos prema njoj kao lutki."},
  "2012_zima_B__40": {"A":"Didaskalija '(tužno)' opisuje osjećaj, a ne kretnju lika.","B":"Didaskalija ne otkriva namjere, nego emocionalno stanje (tugu).","D":"'Tužno' upućuje na osjećaj, a ne na držanje (stav tijela)."},
  "2012_zima_B__41": {"A":"Hanibal Lucić djeluje u renesansi (16. st.), a ne u baroku 17. stoljeća.","C":"Marin Držić je renesansni komediograf 16. stoljeća, ne barokni suvremenik Calderóna.","D":"Mavro Vetranović pripada renesansi 16. stoljeća, a ne baroku 17. stoljeća."},
  "2012_zima_B__42": {"A":"Romantizam se ne suprotstavlja baroku, nego klasicizmu.","C":"Naturalizam nastupa kasnije i nije pojam kojem se romantizam suprotstavlja.","D":"Realizam slijedi nakon romantizma, a romantizam je oprjeka klasicizmu."},
  "2012_zima_B__43": {"A":"Šimić nije najbliži dadaizmu, nego ekspresionizmu.","C":"Impresionizam je raniji i drukčiji poetike; Šimić je blizak ekspresionizmu.","D":"Nadrealizam nije Šimićev pravac; njegova je poetika ekspresionistička."},
  "2012_zima_B__44": {"A":"Sonet nema deset, nego četrnaest stihova.","B":"Sonet nema dvanaest, nego četrnaest stihova.","D":"Sonet nema šesnaest, nego točno četrnaest stihova."},
  "2012_zima_B__45": {"A":"Oktava nije stih, a osam stopa ne definira oktavu.","B":"Stih od osam slogova je osmerac, a ne oktava.","D":"Oktava je strofa od osam stihova, a ne pjesma od osam strofa."},
  "2012_zima_B__46": {"A":"Džore Držić je petrarkist čije su pjesme u zborniku, ali ga nije sastavio.","B":"Hanibal Lucić nije sastavljač zbornika prvih petrarkista.","D":"Šiško Menčetić je petrarkist zastupljen u zborniku, ali ga je sakupio Nikša Ranjina."},
  "2012_zima_B__47": {"A":"Antun Kanižlić je slavonski barokni pisac, ne pripadnik ozaljskoga kruga.","C":"Ignjat Đurđević je dubrovački barokni pisac, ne pripadnik ozaljskoga kruga.","D":"Ivan Bunić Vučić je dubrovački barokni pjesnik, ne pripadnik ozaljskoga kruga."},
  "2012_zima_B__48": {"A":"Humanizam je razdoblje 15./16. st., a ne pokret iz 1830-ih.","C":"Prosvjetiteljstvo je pokret 18. stoljeća, a ne hrvatski preporodni pokret 1830-ih.","D":"Protorealizam je književna pojava, a ne politički i kulturni pokret 19. stoljeća."},
  "2012_zima_B__49": {"B":"Ivan Aralica piše povijesne romane, a ne prozu u trapericama.","C":"Ivo Brešan je dramatičar, ne predstavnik proze u trapericama.","D":"Nedjeljko Fabrio piše povijesne romane, a ne prozu u trapericama."},
  "2012_zima_B__50": {"A":"Razlog ne izlazi 1946.–1950., nego od 1961. do 1968.","B":"Razlog ne izlazi 1952.–1960., nego 1961.–1968.","D":"Razlog ne izlazi 1969.–1974., nego 1961.–1968."},
  "2012_zima_B__51": {"B":"Pogrešno svrstava Lamartinea (1A); on pripada romantizmu (C).","C":"Pogrešno svrstava Tolstoja (3C); on pripada realizmu (A).","D":"Pogrešno svrstava Lamartinea (1B) i Cervantesa (4A); točno je 1C i 4B."},
  "2012_zima_B__52": {"B":"Pogrešno svrstava Matoševa Camaa (1A) i Kozarčeva Đuku (2B); novela je Camao, roman je Đuka.","C":"Pogrešno svrstava Camao (1B točno, ali) Preradovića (4C) kao roman; Mrtva ljubav je lirska pjesma.","D":"Pogrešno svrstava Camao kao roman (1C); Camao je novela (B)."},
  "2012_zima_B__53": {"B":"'Bijelac' (bi-je-lac) ima tri sloga, ali rješenje traži drukčiji broj prema ispitnom ključu.","C":"'Strijelac' (stri-je-lac) ima tri sloga, pa nije tražena riječ.","D":"'Vrijeme' (vri-je-me) ima tri sloga, pa nije tražena riječ."},
  "2012_zima_B__54": {"A":"U 'bršljan' nije provedeno jednačenje po mjestu tvorbe.","B":"U 'nastamba' nije provedeno jednačenje po mjestu tvorbe.","C":"U 'pličina' nije provedeno jednačenje po mjestu tvorbe."},
  "2012_zima_B__55": {"A":"'Podhladiti' nije pravilno napisano prema standardu.","B":"'Podkopati' je nepravilno; pravilno je 'potkopati' (jednačenje d→t).","C":"'Potcrtati' nije pravilan oblik prema ispitnom ključu."},
  "2012_zima_B__56": {"A":"Par 'bijeg — bijegovi' nije potpuno pravilan.","C":"Par 'cvijet — cvijetovi' nije potpuno pravilan prema ključu.","D":"Par 'vijek — vijekovi' nije potpuno pravilan prema ključu."},
  "2012_zima_B__57": {"A":"'Bosanskohercegovačko' sastavljeno označuje jedinstven pojam, ali ispitni traži oblik s crticom.","B":"Rastavljeno 'bosansko hercegovačko' nije pravilno za složeni pridjev.","D":"Crtica (dugi znak) nije pravilna; piše se spojnica: bosansko-hercegovačko."},
  "2012_zima_B__58": {"A":"'crveni križ' malim slovima nije pravilno za ime organizacije.","B":"'Crveni Križ' s oba velika slova nije pravilno; 'križ' se piše malo.","D":"'Ujedinjeni narodi' s malim 'narodi' nije pravilno; oba dijela imena pišu se velikim."},
  "2012_zima_B__59": {"A":"Zarezi su krivo postavljeni; uz vokativ 'poštovana publiko' treba ga obostrano odvojiti.","B":"Zarez ispred 'te' u sastavnom odnosu nije ovdje opravdan.","C":"Zarez unutar veznika 'no što' nije pravilan; ne razdvaja se."},
  "2012_zima_B__60": {"A":"Naglasak nije na prvom slogu 'u-', nego na drugom 'či-'.","C":"Naglasak nije na 'te-', nego na drugom slogu 'či-'.","D":"Naglasak nije na 'lji-', nego na drugom slogu 'či-'."},
  "2012_zima_B__61": {"A":"'Cvijeće' nije muškoga roda ni jednina muškoga roda; srednjega je roda.","B":"'Cvijeće' nije množina muškoga roda; zbirna je imenica srednjega roda u jednini.","D":"'Cvijeće' je gramatički jednina (zbirna imenica), a ne množina."},
  "2012_zima_B__62": {"A":"'Žiriem' nije pravilan oblik instrumentala.","C":"'Žirijom' nije pravilan oblik; nastavak je -em, ne -om.","D":"'Žiriom' nije pravilan oblik instrumentala imenice 'žir'."},
  "2012_zima_B__63": {"A":"'Susjedu koji' pravilno je jer se za živo upotrebljava 'koji'.","B":"'Hotelom koji' pravilno je jer se za neživo rabi 'koji'.","D":"'Slikar kojeg' pravilno je jer je slikar živo (kojeg = živo u akuzativu)."},
  "2012_zima_B__64": {"A":"'Svešček' nije pravilan oblik umanjenice imenice 'svezak'.","B":"'Svečić' nije pravilan oblik umanjenice imenice 'svezak'.","C":"'Svezački' je pridjev, a ne umanjenica."},
  "2012_zima_B__65": {"B":"'Slijeću' je oblik nesvršenoga 'slijetati', a ne svršenoga 'sletjeti'.","C":"'Slijete' nije pravilan oblik 3. lica množine prezenta od 'sletjeti'.","D":"'Slijetaju' je oblik nesvršenoga glagola 'slijetati', a ne 'sletjeti'."},
  "2012_zima_B__66": {"B":"'Stupavši' je glagolski prilog prošli, a ne sadašnji.","C":"'Stupeći' nije pravilan oblik; prilog sadašnji je 'stupajući'.","D":"'Stupivši' je glagolski prilog prošli, a ne sadašnji."},
  "2012_zima_B__67": {"A":"U rečenici nisu jedan, nego dva prijedloga ('s' i 'kroz').","C":"Prijedloga nema tri, nego dva.","D":"Prijedloga nema četiri, nego dva."},
  "2012_zima_B__68": {"A":"Rečenica je jednostavna (jedan predikat), bez zavisne surečenice.","B":"Rečenica je jednostavna proširena, nije složena.","C":"Rečenica je jednostavna, ima samo jedan predikat."},
  "2012_zima_B__69": {"A":"Rečenica nema dvije, nego tri surečenice.","C":"Rečenica nema četiri, nego tri surečenice.","D":"Rečenica nema pet, nego tri surečenice."},
  "2012_zima_B__70": {"B":"'Rijeke' je u genitivu i ima funkciju atributa imenici 'ušće', no ispitni ključ traži rečenicu A.","C":"'Rijeke' u 'Rijeke ljudi' je subjekt rečenice, a ne atribut.","D":"'Rijekom Dravom' — 'rijekom' je dio imenske skupine s apozicijom, a ključ traži A."},
  "2012_zima_B__71": {"A":"Ivan Broz autor je kasnijega Hrvatskog pravopisa (1892.), a ne ove osnove.","C":"Tomo Maretić je gramatičar kasnijega razdoblja, a ne autor Kratke osnove.","D":"Vjekoslav Babukić pisao je slovnice, a Kratku osnovu napisao je Ljudevit Gaj."},
  "2012_zima_B__72": {"B":"Homonimija je istozvučnost različitih značenja, a ne suprotnost značenja.","C":"Polisemija je višeznačnost iste riječi, a ne odnos suprotnosti.","D":"Sinonimija je istoznačnost, suprotno od antonimije."},

  // 2013_jesen_A
  "2013_jesen_A__1": {"A":"Stih samo opisuje zamjenu doma grobnicom, bez usporedne riječi (kao, poput) ni dvaju uspoređenih pojmova.","B":"Riječ je o doslovnu prikazu pritiska nadgrobne ploče, bez poredbenoga veznika i usporedbe.","C":"Stih iznosi tvrdnju o grobu koji razumije pjesnika, ali ne uspoređuje dva pojma."},
  "2013_jesen_A__2": {"A":"Besane noći ('nesane noći', 'čame beskrajne') upravo su ono čega se grob plaši i predbacuje joj, pa to nije ono čega se ne bi trebala bojati.","C":"Pjesnikova smrt nije tema kojom je grob plaši; predbacuje joj propuštene ljubavne užitke, a ne strah od smrti drugoga.","D":"Snovi se spominju kao spavanje u grobu, ali grob joj ne prigovara strah od snova nego propuštenu ljubav."},
  "2013_jesen_A__3": {"B":"'Plašljive grudi' označuju njezinu tjeskobu, a ne toplinu i ljubav nasuprot hladu groba.","C":"'Pustolovne hlepnje' znače žudnje srca, što nije značenjska suprotnost vlazi i tami grobnice.","D":"'Tamna ljepotica' je naziv same junakinje, a ne pojam suprotan smrti i hladnoći groba."},
  "2013_jesen_A__4": {"A":"Ideal je u Baudelaireovoj poetici suprotni pol spleenu (težnja ljepoti i savršenstvu), a ne melankolija i dosada.","C":"'Suvišan čovjek' je pojam ruskoga realizma (lik bez svrhe u društvu), a ne Baudelaireova kategorija.","D":"'Svjetska bol' (Weltschmerz) je romantičarski pojam, dok je dosada i tjeskoba kod Baudelairea spleen."},
  "2013_jesen_A__5": {"A":"Rimbaud je mlađi simbolist na kojega je Baudelaire utjecao, a ne obrnuto.","C":"Verlaine pripada simbolizmu i sljednik je Baudelairea, a ne njegov uzor.","D":"Mallarmé je također simbolist nadahnut Baudelaireom, pa nije mogao utjecati na njega."},
  "2013_jesen_A__6": {"A":"Tvrdnja o kratkovjekosti čovjeka govori o prolaznosti, a ne o svijesti o licemjerju i laži.","B":"Misao o jakoj zemlji i vječnom nebu suprotstavlja prirodu čovjeku, ali ne otkriva licemjerje.","C":"Da je život mučan i pun grijeha i nesreće iskazuje patnju, ali izrijekom ne imenuje varku/laž kao licemjerje."},
  "2013_jesen_A__7": {"B":"Pitanje 'Hoćeš da usneš' nije izrečeno suprotno od značenja niti s podrugljivom namjerom, nego blago zamjenjuje pojam smrti.","C":"Nema zamjene pojma srodnim pojmom po povezanosti; 'usnuti' je ublažen izraz za umiranje, a ne metonimija.","D":"Iako je oblikom pitanje, svrha mu nije retorička tvrdnja nego ublaživanje pojma smrti, što je eufemizam."},
  "2013_jesen_A__8": {"B":"'Potaknut' znači biti nagnan na djelovanje, dok 'zatravljen' znači biti potpuno opčinjen, zanesen.","C":"'Razočaran' nosi negativno značenje gubitka iluzija, suprotno zanesenosti koju izraz označuje.","D":"'Zastrašen' znači prestrašen, što ne odgovara značenju opčinjenosti snovima."},
  "2013_jesen_A__9": {"A":"Sin ne traži smisao u samoći, nego nakon spoznaje mučnosti života bira život među ljudima.","B":"O izgubljenoj ljubavi nema riječi kao o cilju; spominje se tek da je ljubav kratka.","D":"Sin se odlukom da živi zapravo odupire očevu pozivu na 'usnuće' (smrt), pa ne prihvaća očeve savjete."},
  "2013_jesen_A__10": {"A":"Tekst nema pouku ni životinjske likove svojstvene basni.","B":"Nije riječ o kratkoj fabularnoj prozi s razvijenom radnjom, nego o ritmiziranoj lirskoj prozi.","C":"Nema novele s obratom i zaokruženom fabulom; dominira lirski, ritmizirani dijalog."},
  "2013_jesen_A__11": {"A":"Atena je božica koja pomaže Odiseju i Telemahu, ali ne vodi njegovo kućanstvo.","B":"Penelopa Telemah šalje u njezine odaje i da gleda svoje poslove, dok on preuzima ulogu gospodara kuće.","D":"Zeus se spominje kao onaj koji dijeli sudbine ljudima, a ne kao onaj koji vodi Odisejevu obitelj."},
  "2013_jesen_A__12": {"A":"Stih ne govori o Zeusovoj dobroti prema radišnima, nego o tome da on svakome dijeli sudbinu po svojoj volji.","C":"Stih izrijekom poriče da je čovjek gospodar svoje sudbine jer to čini Zeus.","D":"Telemah upravo skida krivnju s ljudi (pjevača) i pripisuje je Zeusu, pa čovjek nije kriv za sudbinu."},
  "2013_jesen_A__13": {"A":"Majka prihvaća sinovu razumnu riječ, što pokazuje da ga ne smatra neodlučnim.","C":"Strogost nije ono što majka uočava; ona se divi njegovoj razboritosti.","D":"Tekst ne prikazuje sina kao tužna, nego kao razumna i odlučna gospodara kuće."},
  "2013_jesen_A__14": {"A":"Telemah majci upravo nalaže da zapovijeda dvorkinjama, a ne da to ne čini.","B":"Telemah je nagovara da sluša pjevača ('slušaj pjevača'), pa od nje ne traži suprotno.","C":"Uzdanje u bogove nije ono što Telemah od majke traži; poziva je na strpljenje."},
  "2013_jesen_A__15": {"B":"Pjevač ne pjeva o Odisejevoj pogibiji; Telemah kaže da Odisej nije jedini izgubio povratak.","C":"Tema je nevolja Danajaca (Grka), a ne sudbina Trojanaca.","D":"Zeusova samovolja spominje se u Telemahovu obrazloženju, ali nije tema pjevačeve pjesme."},
  "2013_jesen_A__16": {"A":"Dostojevski je autor drugih djela (npr. Zločin i kazna), a Kabanicu je napisao Gogolj.","B":"Tolstoj nije autor Kabanice; pisac fantastičnoga svršetka s mrtvacem i kabanicom jest Gogolj.","C":"Ljermontov je pjesnik i autor Junaka našega doba, a ne Kabanice."},
  "2013_jesen_A__17": {"B":"Pripovjedač policiju ne uzdiže u uzor; ironično ističe njezin neuspjeh ('samo što nisu uspjeli').","C":"Nema divljenja prema policiji, nego podrugljiva komentara njezine nesposobnosti.","D":"Pripovjedač se policije ne boji, nego joj se izruguje."},
  "2013_jesen_A__18": {"A":"'Oteta kabanica' je predmet radnje, ali nije pojmovna suprotnost fantastičnomu.","B":"'Živ mrtvac' je oksimoron unutar priče, a ne suprotnost pojmu 'fantastični'.","C":"'Visoka ličnost' označuje društveni položaj lika, a ne suprotnost fantastičnomu i istinitomu."},
  "2013_jesen_A__19": {"A":"Nema postupnoga stupnjevanja po jačini, nego spoja proturječnih pojmova 'mrtvac' i 'živ'.","B":"Nema namjernoga pretjerivanja radi naglašavanja, nego proturječja u istoj sintagmi.","D":"Nema usporedbe dvaju pojmova s veznikom; riječ je o spajanju oprečnih značenja (mrtav i živ)."},
  "2013_jesen_A__20": {"A":"Mrtvac kabanice ne skida radi vlastite materijalne koristi, nego se osvećuje za otetu kabanicu.","C":"Ponos nije pokretač njegova djelovanja; pokreće ga osveta zbog nepravde.","D":"Sažaljenje ne objašnjava skidanje kabanica drugima; motiv je osveta."},
  "2013_jesen_A__21": {"A":"Nema opisa prostora ili izgleda, nego unutarnjega izricanja misli lika.","B":"Nema razgovora dvaju sugovornika; Vidović govori sam sebi.","D":"Nema pripovijedanja o tijeku događaja, nego iznošenja unutarnjih misli u prvom licu."},
  "2013_jesen_A__22": {"A":"'Prljave' se odnosi na vidni i taktilni dojam nečistoće, a ne na miris.","C":"'Ušljive' upućuje na zaraženost ušima (vidni/dodirni dojam), a ne na njuh.","D":"'Drvene' označuje materijal (vidni dojam), a ne mirisni podražaj."},
  "2013_jesen_A__23": {"A":"Nema dvostrukoga, prikrivenoga prenesenog značenja kroz cijeli prizor, nego pripisivanja ljudskih osobina baraci.","B":"Nema prijenosa značenja po sličnosti dvaju pojmova, nego oživljavanja nežive barake.","C":"Nema zamjene pojma srodnim pojmom po povezanosti; baraci se daju ljudska svojstva (svađa se, osjeća)."},
  "2013_jesen_A__24": {"B":"'Fraza' se odnosi na praznu riječ o smislu špitala, a ne na obilježje cijele civilizacije.","C":"'Serum' je lijek kojemu nitko ne vjeruje, a ne riječ kojom Vidović opisuje civilizaciju.","D":"'Gnojnica' nije pojam kojim je Vidović okarakterizirao civilizaciju kao plitku i lažnu."},
  "2013_jesen_A__25": {"A":"Nizanje veznika 'i' ne izražava ravnodušnost, nego pojačava dojam Vidovićeve bespomoćnosti.","C":"Polisindeton ovdje ne naglašava želju za ozdravljenjem, nego sveopće beznađe.","D":"Vizija drvenoga Kristuša nije ono što se ponavljanjem veznika ističe; naglasak je na bespomoćnosti."},
  "2013_jesen_A__26": {"A":"Ljubav za Emmu nije spora i dugotrajna 'bolest', nego nešto što mora doći iznenada poput oluje.","C":"Emma ljubav ne shvaća kao razuman obostrani interes, nego kao silovit, nenadan osjećaj.","D":"Bračni sklad upravo je suprotan njezinu shvaćanju; ljubav za nju dolazi kao orkan, ne kao mir braka."},
  "2013_jesen_A__27": {"A":"Prizor čitanja i okretanja sjenila opisuje njihovo druženje, ali ne sadrži metaforu postupna razvoja ljubavi.","B":"Tihi razgovor prikazuje zbližavanje, ali nije metafora o ljubavi koja se polako nakuplja.","C":"Rečenica da se Emma nije pitala ljubi li ga iznosi njezino stanje, ali nije metafora postupna razvoja osjećaja."},
  "2013_jesen_A__28": {"A":"Cilj im nije zadiviti poznanike; rečenica govori o njihovu zbližavanju kroz zajedničke interese.","B":"Nema namjere da Charlesa učine ljubomornim; on i ne primjećuje ništa neobično.","D":"Nema prijezira prema okolini; riječ je o nastanku bliskosti i početka ljubavi među njima."},
  "2013_jesen_A__29": {"A":"Léon se ne divi skladu Emmina i Charlesova braka, nego podnosi muža samo zato što je dio Emmina svijeta.","B":"Ne traži Léon Charlesovo društvo radi njega samoga, nego ga prihvaća isključivo zbog Emme.","C":"Nema proračunatosti u rečenici; ona izražava bezuvjetnu žudnju za Emminom blizinom."},
  "2013_jesen_A__30": {"B":"Emma se ne opire nemoralnim odnosima; upravo u ljubavnim vezama traži bijeg od dosade.","C":"'Lažnomu bogatstvu' Emma teži (raskoš, luksuz), a ne opire mu se.","D":"Grizodušje nije ono čemu se Emma opire; ona čezne za uzbuđenjem nasuprot prosječnosti."},
  "2013_jesen_A__31": {"A":"Marko ne iskazuje krivnju zbog sebe, nego sumnju i ljubomoru prema Gigi.","C":"Potištenost nije osjećaj koji prevladava; Marko je žestok, optužujući i ljubomoran.","D":"Marko ne iskazuje strah, nego ljubomornu sumnju u Giginu vjernost."},
  "2013_jesen_A__32": {"A":"Giga se ne sažalijeva nad sobom, nego smireno i izravno odbacuje optužbe.","B":"Giga optužbe ne prihvaća bespomoćno; otvoreno tvrdi da Marko nema razloga.","D":"Giga ne reagira prezirno; suprotstavlja se mirno, gledajući Marka otvoreno u oči."},
  "2013_jesen_A__33": {"A":"Rečenica ne tvrdi da je Giga ljubavnika upoznala na radnome mjestu, nego ironično optužuje za nemoral.","C":"Ne govori se doslovno o vođenju poduzeća, nego ironično o Giginu (navodnom) nemoralu.","D":"Rečenica ne izražava Giginu patnju, nego Markovu ironičnu optužbu za nevjeru."},
  "2013_jesen_A__34": {"A":"Marko se nije vratio iz lječilišta, nego iz zarobljeništva nakon rata.","B":"Marko se nije vratio iz poduzeća; 'poduzeće' je ironična aluzija na Giginu nevjeru.","C":"Iz Trogira je ljetovala Giga, a Marko se vratio iz zarobljeništva."},
  "2013_jesen_A__35": {"A":"Giga i Marko nisu u ljubavničkom, nego u bračnom odnosu.","B":"Nisu samo prijatelji, nego bračni drugovi (suprug i supruga).","D":"Nisu susjedi, nego supružnici; Marko se vraća kao Gigin muž."},
  "2013_jesen_A__36": {"A":"Ahilej je junak Ilijade, ali ne završava slijep i posramljen kao opisani lik.","C":"Kreont je vladar koji u tragediji strada, ali opis vrhunca moći pa pada u sljepoću pripada Edipu.","D":"Prometej je titan kažnjen za krađu vatre, a ne kralj koji oslijepi i postane izgnanik."},
  "2013_jesen_A__37": {"A":"Cvit razgovora (Šitović/Filip Grabovac) nije spjev o nemaru Slavonaca s prosvjetiteljskom svrhom.","B":"Matijaš Grabancijaš dijak je Brezovačkova komedija, a ne prosvjetiteljski spjev o Slavoncima.","C":"Razgovor ugodni (Kačić Miošić) prikazuje junačku povijest, a ne nemar i zaostalost Slavonaca."},
  "2013_jesen_A__38": {"B":"Aralica piše povijesne romane, a ne roman o mladima koji lutaju Istrom i odustaju.","C":"Pavličić je autor drukčije, često kriminalističke proze, a ne hrvatske inačice Lovca u žitu.","D":"Novak je poznat po Mirisima, zlatu i tamjanu, a ne po romanu o lutanju Istrom."},
  "2013_jesen_A__39": {"B":"Anafora bi značila ponavljanje na početku uzastopnih stihova, a ovdje se izraz ponavlja na spoju kraja i početka.","C":"Epifora je ponavljanje na kraju stihova, dok je ovdje izraz ponovljen s kraja prvoga na početak drugoga stiha.","D":"Simploka spaja anaforu i epiforu, čega ovdje nema; riječ je o ponavljanju na granici dvaju stihova."},
  "2013_jesen_A__40": {"A":"Elegija je lirska vrsta (tužaljka), a ne dramska.","C":"Oda je svečana lirska pjesma, pa pripada lirici, a ne dramskomu rodu.","D":"Romanca je lirsko-epska/lirska vrsta, a ne dramska."},
  "2013_jesen_A__41": {"B":"Opis seljaka gladna i nenavikla na grad odgovara Pometovu protivniku Bokčilu, a ne Pometu.","C":"Onaj tko nastoji Maru pribaviti Laurinu ljubav nije Pomet, nego Marov sluga Popiva.","D":"Pomet ne služi Lauri, nego Nijemcu Tudešku (Maru Ugu), pa se opis ne odnosi na njega."},
  "2013_jesen_A__42": {"A":"Šenoa je djelovao kasnije i uređivao Vijenac, a Kolo je pokrenuo Vraz.","B":"Gaj je pokrenuo Danicu i Novine horvatske, a ne Kolo.","C":"Preradović je preporodni pjesnik, ali nije pokretač časopisa Kolo."},
  "2013_jesen_A__43": {"B":"Matoš je kao predvodnik moderne zagovarao ljepotu i artizam, a ne ekspresivnost nasuprot ljepoti.","C":"Šenoa pripada realizmu/protorealizmu 19. st., a ne ekspresionističkomu manifestu.","D":"Ujević je pjesnik moderne, ali ovaj programatski tekst o ekspresiji pripada A. B. Šimiću."},
  "2013_jesen_A__44": {"B":"Prikaz nesvjesnoga koje upravlja postupcima odgovara nadrealizmu, a ne futurizmu.","C":"Apsurd, nihilizam i odbacivanje svih vrijednosti obilježja su dadaizma, a ne futurizma.","D":"Tema besmisla moderne civilizacije i mehaničkoga života bliža je ekspresionizmu, dok futurizam tehniku slavi."},
  "2013_jesen_A__45": {"A":"Kraljevo pripada Krležinim ekspresionističkim dramama (legende), a ne glembajevskomu ciklusu.","C":"Legenda je rana Krležina simbolistička/ekspresionistička drama, a ne dio glembajevskoga ciklusa.","D":"Maskerata pripada Krležinim ranim dramama, a ne trilogiji o Glembajevima."},
  "2013_jesen_A__46": {"B":"Pridruživanje griješi kod Molièrea (2A=barok); on je predstavnik klasicizma (B).","C":"Pridruživanje pogrešno svrstava Balzaca (1B=klasicizam) i Racinea (5C=realizam), iako su Balzac realist, a Racine klasicist.","D":"Pridruživanje pogrešno svrstava Calderóna (4B=klasicizam) i Racinea (5A=barok), iako je Calderón barokni, a Racine klasicist."},
  "2013_jesen_A__47": {"B":"Pridruživanje pogrešno svrstava 3. stih ('četa mala') Gunduliću (3A), a riječ je o Mažuraniću (B).","C":"Pridruživanje pogrešno svrstava 1. stih Maruliću (1B) i 5. stih Gunduliću (5A), iako su 1. Gundulić, a 5. Mažuranić.","D":"Pridruživanje pogrešno svrstava 2. stih Mažuraniću (2B) i 5. stih Maruliću (5C), iako je 2. Marulić, a 5. Mažuranić."},
  "2013_jesen_A__48": {"A":"'Isčeprkati' je pogrešno jer ispred bezvučnoga č dolazi bezvučno š, a ne s ('iščeprkati').","C":"'Izčeprkati' ne provodi obezvučenje ni jednačenje po mjestu tvorbe (z ispred č → š).","D":"'Ižčeprkati' je dvostruko pogrešno: nema ž, nego š ispred č ('iščeprkati')."},
  "2013_jesen_A__49": {"A":"'Tijelce' je pogrešno; u izvedenici dolazi do skraćivanja jata pa je pravilno 'tjelce'.","B":"'Tijelesa' je pogrešno; pravilan je oblik s kratkim jatom ('tjelesa').","D":"'Tijelešce' je pogrešno; pravilno je 'tjelešce' s kratkim jatom."},
  "2013_jesen_A__50": {"A":"U 'zakupljen' l je dio osnove (kupiti), a ne umetnuto (epentetsko) l.","B":"U 'zamuljen' nema epentetskoga l jer je l dio osnove riječi mulj.","C":"U 'zasoljen' nema epentetskoga l; l je dio osnove (soliti)."},
  "2013_jesen_A__51": {"A":"Naglasak nije na prvom slogu (ras-), nego na drugom (-po-).","C":"Naglasak nije na trećem slogu (-zna-), nego na drugom (-po-).","D":"Naglasak nije na četvrtom slogu (-va-), nego na drugom (-po-)."},
  "2013_jesen_A__52": {"A":"U 'istrjebljenje' r je uz samoglasnik (skupina -tr-je-), pa nije slogotvorno.","C":"U 'potkrjepljenje' iza r slijedi samoglasnik (-krje-), pa r nije slogotvorno.","D":"U 'pozdrav' r je uz samoglasnik a (-drav), pa nije nositelj sloga."},
  "2013_jesen_A__53": {"A":"Pogrešno je 'hrvatsko – poljski' s razmacima i dugom crtom; spojnica ide bez razmaka ('hrvatsko-poljski').","B":"Pogrešno je 'Brlić – Mažuranić' s razmacima i crtom; dvostruko prezime piše se spojnicom bez razmaka ('Brlić-Mažuranić').","D":"Pogrešno je '2-3' sa spojnicom; raspon brojeva piše se crtom bez razmaka ('2–3') ili riječima."},
  "2013_jesen_A__54": {"A":"'Spomen – ploču' je pogrešno zbog razmaka i duge crte; složenica se piše spojnicom bez razmaka.","C":"'Spomen ploču' je pogrešno jer izostaje spojnica obvezna u polusloženici 'spomen-ploča'.","D":"'Spomenploču' je pogrešno jer se taj tip polusloženice ne piše sastavljeno, nego sa spojnicom."},
  "2013_jesen_A__55": {"B":"'Spava' uključuje i prezentski nastavak, pa nije korijenski morfem nego osnova s nastavkom.","C":"'Spavač' sadrži korijen i sufiks -ač, pa je tvorbena osnova, a ne sam korijen.","D":"'Spavačic' obuhvaća korijen i dva sufiksa (-ač-, -ic-), pa nije korijenski morfem."},
  "2013_jesen_A__56": {"B":"Pogrešno je 'Edgar Allana Poea' jer prvi član imena (Edgar) ostaje nesklonjen.","C":"Pogrešno je 'Edgara Allan Poea' jer srednji član (Allan) ostaje nesklonjen.","D":"Pogrešno je 'Edgar Allan Poea' jer dva člana (Edgar, Allan) ostaju nesklonjena."},
  "2013_jesen_A__57": {"A":"Genitiv bi tražio drukčiji oblik i pitanje 'koga, čega'; ovdje uz 'na' i pitanje 'gdje' dolazi lokativ.","B":"Dativ odgovara na pitanje 'komu, čemu', a ovdje uz prijedlog 'na' i značenje mjesta dolazi lokativ.","C":"Akuzativ uz 'na' označuje smjer/cilj, a ovdje je riječ o mirovanju na mjestu, pa je lokativ."},
  "2013_jesen_A__58": {"A":"Muški rod jednine ne odgovara jer se 'njihovoj' slaže s imenicom 'primjeni' ženskoga roda.","B":"Muški rod množine ne odgovara; zamjenica je u jednini i ženskoga roda prema 'primjeni'.","D":"Ženski rod množine ne odgovara jer je 'primjeni' u jednini, pa je i 'njihovoj' u jednini."},
  "2013_jesen_A__59": {"A":"Pogrešno je 'stana kojega' jer se za neživo upotrebljava oblik 'koji', a ne 'kojega'.","C":"Pogrešno je 'sat kojega' jer je sat neživo, pa treba oblik 'koji'.","D":"Pogrešno je 'dopisu kojega' jer je dopis neživo, pa treba 'koji'."},
  "2013_jesen_A__60": {"A":"'Siktajući' nije ispravan oblik glagolskoga priloga sadašnjega od 'siktati'.","B":"'Sikčući' je pogrešno; pravilan je oblik 'sikćući'.","D":"'Sikćuči' je pogrešno jer završava na -či umjesto na -ći ('sikćući')."},
  "2013_jesen_A__61": {"B":"'Slijevaše' je 3. l. jednine, a uz množinski subjekt 'suze' treba množina 'slijevahu'.","C":"'Sljevahu' je pogrešno jer je u osnovi izostavljen dugi jat (treba 'slijevahu').","D":"'Sljevaše' je dvostruko pogrešno: kraći jat i jednina umjesto množine."},
  "2013_jesen_A__62": {"A":"'Sa Šveđaninom' nije pravilno jer prema rješenju ovoga zadatka kao jedini točan oblik 'sa' dolazi ispred 'Čehom'; uz Šveđanin se traži oblik 's'.","B":"'Sa Nijemcem' je pogrešno jer ispred N dolazi prijedlog 's', a ne 'sa'.","D":"'Sa Rusom' je pogrešno jer ispred R dolazi 's', a ne 'sa'."},
  "2013_jesen_A__63": {"B":"Tri surečenice ne odgovaraju jer rečenica ima samo dvije: dopusnu i glavnu.","C":"Četiri surečenice ne odgovaraju; nabrajanje pridjeva ne čini nove surečenice.","D":"Pet surečenica ne odgovara; rečenica sadrži tek dva predikata, dakle dvije surečenice."},
  "2013_jesen_A__64": {"A":"'Kamen spoticanja' ima uobičajen red riječi (imenica + atribut), pa nije stilski obilježen.","B":"'Rame za plakanje' ima neutralan, uobičajen poredak sastavnica.","C":"'Kiselo vrhnje' ima redovit red pridjev + imenica, pa nije stilski obilježeno."},
  "2013_jesen_A__65": {"A":"'Na mene' je neizravni objekt (uz 'ugledati se na'), a ne izravni u akuzativu bez prijedloga.","B":"'Puna dva mjeseca' je priložna oznaka vremena, a ne izravni objekt.","D":"'Takva života' je genitivni (neizravni) objekt uz 'zasititi se', a ne izravni objekt u akuzativu."},
  "2013_jesen_A__66": {"A":"'Profesor kemije' ovdje je imenski dio predikata (postati profesor), a ne atribut.","B":"'Profesora' je objekt (prihvatiti savjet profesora), a ne atribut.","D":"'Profesor Horvat' je subjekt rečenice, a ne atribut."},
  "2013_jesen_A__67": {"A":"'Kad ne bi bilo vruće' je pogodbena (kondicionalna) rečenica, a ne dopusna.","B":"'Da nije bilo vruće' je pogodbena rečenica, a ne dopusna.","D":"'Jer je vruće' je uzročna rečenica, a ne dopusna."},
  "2013_jesen_A__68": {"B":"'Predškolski' sadrži prefiks pred-, pa je riječ o prefiksalno-sufiksalnoj, a ne čistoj sufiksalnoj tvorbi.","C":"'Prohrvatski' sadrži prefiks pro-, pa nije nastalo samo sufiksacijom.","D":"'Protuturski' sadrži prefiks protu-, pa nije čista sufiksalna tvorba."},
  "2013_jesen_A__69": {"B":"Ekonimi su imena naselja (gradova, sela), a 'Marko Marulić' je ime osobe.","C":"Etnonimi su imena naroda, a 'Marko Marulić' je osobno ime, ne naziv naroda.","D":"Oronimi su imena gora i planina, a riječ je o osobnom imenu."},
  "2013_jesen_A__70": {"A":"'Dubrovčanin' označuje stanovnika grada (etnik prema naselju), a ne pripadnika naroda.","C":"'London' je ime grada (ekonim/ojkonim), a ne naziv naroda.","D":"'Velebit' je ime planine (oronim), a ne etnonim."},
  "2013_jesen_A__71": {"A":"'Horvat' je prezime nastalo prema etniku (Hrvat), a ne prema očevu osobnom imenu.","C":"'Magdić' je nastalo prema ženskom imenu/nadimku, pa nije patronim (od muškoga pretka).","D":"'Posavec' je nastalo prema zavičaju (Posavina), a ne prema očevu imenu."},
  "2013_jesen_A__72": {"A":"Boranić je priredio kasnija izdanja pravopisa, a prvi fonološki pravopis sastavio je Broz.","C":"Gaj je reformirao slovopis (latinicu), ali nije autor prvoga fonološkoga pravopisa.","D":"Maretić je gramatičar i autor kasnijih djela, a prvi hrvatski fonološki pravopis napisao je Broz."},

  // 2013_jesen_B
  "2013_jesen_B__1": {"A":"Pjesma ne govori o ljubavi prema osobi, nego o promišljanju života i prolaznosti.","C":"Krajolik nije tema; priroda se spominje tek kao 'majka Priroda', a težište je na razmišljanju.","D":"Nema društvene problematike ni socijalnih nepravdi, nego filozofskoga promišljanja o vrijednosti života."},
  "2013_jesen_B__2": {"A":"Bubica je upravo ono što treba biti sačuvano ('nek te'), pa ne može istovremeno biti i ona koja čuva.","C":"Pjesma je mjesto kamo bubica ulazi, ali nije ona koja je čuva; subjekt 'ona' upućuje na majku Prirodu.","D":"Smola se spominje tek u poredbi s jantarom, a ne kao subjekt koji bubicu čuva."},
  "2013_jesen_B__3": {"A":"Eufemizam je ublažavanje neugodnoga izraza, čega ovdje nema.","C":"Nema pretjerivanja radi pojačanja dojma, nego suprotstavljanja malog i velikog.","D":"Ništa neživo ne dobiva ljudske osobine; riječ je o suprotnosti veliko/malo."},
  "2013_jesen_B__4": {"A":"Jantar se spominje samo u poredbi (kao što jantar čuva bubice), a ne kao podloga po kojoj bubica hoda.","B":"Olimp je naveden kao mjera vrijednosti ('življa nego cijeli Olimp'), a ne mjesto kojim bubica hoda.","C":"Priroda se spominje kao 'majka Priroda', ali bubica konkretno šeće heksametrima/stihovima."},
  "2013_jesen_B__5": {"A":"Katrena ima četiri stiha, a druga strofa ih ima pet.","C":"Sekstina ima šest stihova, a ova strofa ima pet.","D":"Oktava ima osam stihova, a ova strofa ima pet."},
  "2013_jesen_B__6": {"A":"Gundulić je barokni pisac (Osman, Suze sina razmetnoga je drugo djelo), ali ovaj ulomak pripada Maruliću.","C":"Hektorović je autor Ribanja i ribarskoga prigovaranja, a ne ovih stihova.","D":"Zoranić je autor Planina, a ne ovoga ulomka."},
  "2013_jesen_B__7": {"A":"'Razbirati' znači opažati/razabirati, a ne prihvaćati; žena nije osoba koja ne prihvaća, nego koja ne mari kakav si.","B":"Stih ne govori o (ne)vjerovanju, nego o tome da žena ne opaža/ne razabire kakav si.","C":"'Razbirati' nema veze s govorenjem; smisao je da ne opaža čovjekove osobine."},
  "2013_jesen_B__8": {"A":"Stihovi tvrde upravo suprotno — da vrline nemaju vrijednosti za ženu koja gleda samo zlato.","B":"Pjesma kaže da za vrlinama nitko (žena) ne čezne; čezne se za zlatom.","C":"Stih ne tematizira (ne)govorenje, nego ispraznost vrlina u očima koristoljubive žene."},
  "2013_jesen_B__9": {"A":"Asindeton je nizanje bez veznika, no ovdje se stupnjuju sve veće slike bogatstva, što je gradacija.","B":"Epifora je ponavljanje na kraju stihova; ovdje se na početku niže 'da', a slike se stupnjuju.","D":"Oksimoron spaja proturječne pojmove, a ovdje se nižu sve veće slike, što je gradacija."},
  "2013_jesen_B__10": {"B":"Neukrotivost (neobuzdanost) nije ono što stihovi opisuju; riječ je o gledanju na novac.","C":"Samodopadnost (umišljenost) ne proizlazi iz stihova koji govore o gledanju na imetak.","D":"Slatkorječivost nije tema; naglašava se materijalni interes, a ne lijepo govorenje."},
  "2013_jesen_B__11": {"B":"Tekst tvrdi suprotno — razum se 'malo ili nikako ne iskazuje kad plane strast', dakle ne potiskuje strast.","C":"Strast ne potiče razum, nego ga prema tekstu nadvladava i potiskuje.","D":"Razum ne potiče strast; naglasak je na nemoći razuma pred strašću."},
  "2013_jesen_B__12": {"A":"Nema stupnjevanja pojmova, nego prenesenoga prikaza strasti kao oluje u krvi.","C":"Oluji nisu pridane ljudske osobine; riječ je o prenesenom značenju (strast = oluja).","D":"Nema poredbenoga veznika 'kao'; izraz je sažet u metaforu."},
  "2013_jesen_B__13": {"B":"'Zoran' znači jasan/očit, a ne logičan; Albertu usporedba nije bila jasna.","C":"'Zoran' ne znači uobičajen, nego jasan, vidljiv, razumljiv.","D":"'Zoran' ne znači zanimljiv, nego jasan/očit."},
  "2013_jesen_B__14": {"A":"'Prigovorio je još ponešto' pokazuje da razgovor i dalje traje, a ne da završava.","B":"'Htio da mu se oprosti' ne označava prekid razgovora.","D":"'Srce mi je bilo tako prepuno' izražava emociju, a ne završetak razgovora."},
  "2013_jesen_B__15": {"A":"Emma je junakinja Flaubertove Gospođe Bovary, a ne Wertherova ljubav.","B":"Laura je adresatkinja Petrarkina Kanconijera, a ne lik iz Patnji mladog Werthera.","D":"Nora je junakinja Ibsenove Lutkine kuće, a ne Wertherova ljubav."},
  "2013_jesen_B__16": {"A":"Mjesec se samo opisuje na početku sna, ali nema razgovora Raskoljnikova s Mjesecom.","B":"Baba se u snu samo smije; nema njihova razgovora, riječ je o sanjanome prizoru.","C":"Tekst ne iznosi plan zločina, nego sanjani prizor koji završava buđenjem."},
  "2013_jesen_B__17": {"A":"'Okrugli Mjesec' je opis pridjevom, a ne pripisivanje ljudske radnje.","B":"'Crven kao bakar' je poredba boje, a ne personifikacija.","D":"'Gleda u prozore' samo dopunjuje radnju; nositelj personifikacije je spoj 'Mjesec gleda'."},
  "2013_jesen_B__18": {"A":"'Uzljuljati se od kikota' znači tresti se od smijeha, a ne onesvijestiti se od udarca.","C":"Baba se ne ukipljuje od straha; ona se trese od smijeha.","D":"Nije riječ o boli ni savijanju, nego o tresenju izazvanom smijehom."},
  "2013_jesen_B__19": {"A":"Bijes se u rečenici ne spominje; 'ga' upućuje na smijeh koji baba suzdržava.","B":"Pogled se ne suspreže; suspreže se smijeh da ga Raskoljnikov ne bi čuo.","D":"Šapat nije ono što se suzdržava; riječ je o smijehu (kikotu)."},
  "2013_jesen_B__20": {"A":"U 17. st. djeluju baroknici; Dostojevski je rođen tek 1821.","B":"U 18. st. djeluju prosvjetitelji; Dostojevski pripada 19. stoljeću.","D":"Dostojevski je umro 1881., dakle u 19., a ne 20. stoljeću."},
  "2013_jesen_B__21": {"A":"Prizor ne upućuje na bolnicu, nego na javnu kuću (mračne sobe, djevojke).","C":"Sirotište se ne spominje; kontekst je javna kuća.","D":"Trafika se spominje uz Reginu (trafikantkinja), ali Filip istrčava iz javne kuće."},
  "2013_jesen_B__22": {"A":"Metafora ne bi imala poredbeni veznik 'kao', koji je ovdje prisutan.","B":"Metonimija zamjenjuje pojam srodnim, a ovdje se izrijekom uspoređuje s gljivom ('kao').","C":"Trbuhu se ne pripisuju ljudske osobine, nego se njegovo bljedilo uspoređuje s gljivom."},
  "2013_jesen_B__23": {"A":"'Intimni glas' je epitet uz glas, a ne miješanje različitih osjetilnih doživljaja.","C":"'Pivničarka gljiva' je poredbeni element bljedila, a ne spoj dvaju osjetila.","D":"'Srebrna forinta' je opis novca pridjevom, bez spoja različitih osjetila."},
  "2013_jesen_B__24": {"A":"Zapuštenost zgrade nije navedeni uzrok plača; Filipa pogađa ono što čuje o majci.","C":"Sudbina djevojke nije razlog plača; tuga je vezana uz priču o majci Regini.","D":"O potrošenome novcu nema ni riječi; uzrok je čuto o majci."},
  "2013_jesen_B__25": {"A":"Iako se Filip vraća kući, to nije motiv koji ga povezuje s Leoneom u traženom smislu razočaranja.","B":"Leone ubija baronessu, ali Filip ne ubija ljubavnicu, pa to nije zajednički motiv.","D":"Nijednome od njih majka nije umrla; obojicu povezuje razočaranje majkom (majčinskom figurom)."},
  "2013_jesen_B__26": {"A":"Alegorija je prošireno preneseno značenje cijeloga teksta, a ovdje je riječ o jednome spoju riječi.","C":"Cvijetu se ne pripisuju ljudske osobine; krv se prenesenim značenjem naziva cvijetom.","D":"Nema poredbenoga veznika 'kao'; izraz je metaforičan."},
  "2013_jesen_B__27": {"A":"'Posrtati' opisuje teturanje prije uginuća, a ne samu smrt.","B":"'Okretati se oko osi' prikazuje agoniju, ali ne i to da su štakori uginuli.","C":"'Pocikivati' označuje glasanje u smrtnoj borbi, dok 'pružiti se' znači biti mrtav."},
  "2013_jesen_B__28": {"A":"Tu je metafora ('berba'), a ne poredba; nema veznika 'kao/nalik'.","B":"Rečenica je opis bez poredbe; nema usporedbenoga elementa.","C":"'Rekao bi čovjek da...' je personifikacija/pretpostavka, a ne poredba s 'kao/nalik'."},
  "2013_jesen_B__29": {"A":"Kuga nije pisana u obliku dnevnika, nego kao kronika epidemije.","C":"Roman u pismima je npr. Patnje mladog Werthera; Kuga je kronika.","D":"Kuga nije esejistički roman, nego ima oblik kronike/ljetopisa."},
  "2013_jesen_B__30": {"B":"Hamlet je tragedija o danskome kraljeviću i ne počinje pričom o kugi.","C":"Kiklop (Marinković) ne započinje pričom o kugi.","D":"Preobražaj (Kafka) počinje Gregorovom pretvorbom u kukca, ne kugom."},
  "2013_jesen_B__31": {"A":"Izmena ne potiče na odlučnost, nego upozorava na opreznost i razboritost.","B":"Izmena ne potiče ponos, nego suzdržanost pred jačom vlašću.","D":"Izmena ne govori o samilosti, nego savjetuje razboritost ('raditi što snage prelazi nije pametno')."},
  "2013_jesen_B__32": {"A":"Zatajivanje predaka ne spominje se kao uzrok najgore smrti.","B":"Poricanje braće nije navedeni razlog; najgora smrt prijeti zbog kršenja kraljevske volje.","C":"Tekst govori o kraljevskoj vlasti i zakonu, a ne o gaženju 'božjih' zakona kao uzroku smrti."},
  "2013_jesen_B__33": {"A":"'Božji zakon' nije proturječan spoj, nego sintagma sa skladnim pojmovima.","B":"'Mrtva ležati' nije proturječje, nego logičan spoj.","C":"'Sebe otkriti' nema suprotnih pojmova, pa nije oksimoron."},
  "2013_jesen_B__34": {"A":"Zaručnik (Hemon) nije onaj koga Antigona namjerava sahraniti.","B":"Ujak Kreont upravo zabranjuje pokop, pa nije 'onaj' koga Antigona želi sahraniti.","D":"Otac Edip nije predmet pokopa u ovome ulomku; riječ je o bratu Poliniku."},
  "2013_jesen_B__35": {"A":"Balada je lirsko-epska pjesma, a Antigona je dramsko djelo.","B":"Elegija je tužaljka u stihu, a ne dramska vrsta kojoj pripada Antigona.","C":"Ep je opširno epsko pjesništvo, a Antigona je tragedija (drama)."},
  "2013_jesen_B__36": {"B":"Judita nije ispjevana u epskim desetercima, nego u dvostruko rimovanim dvanaestercima.","C":"Elegijski distih je antički oblik, a ne stih Juditin.","D":"Heksametar je antički epski stih, a ne stih Marulićeve Judite."},
  "2013_jesen_B__37": {"A":"Razlaz se nije dogodio zbog grafije; oko grafije Gaj je već bio proveo reformu.","B":"Spor nije bio o podrijetlu slavenskoga imena, nego o ulozi književnosti.","D":"Nesuglasica nije bila oko čitaonica, nego oko shvaćanja svrhe književnosti."},
  "2013_jesen_B__38": {"B":"Šenoa je pisac Zlatarova zlata i Seljačke bune, ali ne i ovoga romana s demonskom hajdučicom.","C":"Kozarac je autor Mrtvih kapitala i Tene, a ne U registraturi.","D":"Novak je autor Posljednjih Stipančića, a ne ovoga romana o usponu seljaka i Lauri."},
  "2013_jesen_B__39": {"A":"Epigram je kratka duhovita/satirična pjesma, bez epskoga okvira.","B":"Epopeja je velik ep, čista epika, bez naglašene lirske komponente.","C":"Gazela je lirska pjesma orijentalnoga podrijetla, bez epskih elemenata."},
  "2013_jesen_B__40": {"A":"Ilijada nije nazvana po junakinji; naziv dolazi od imena grada.","B":"Naslov ne potječe od junaka (Ahileja), nego od grada Iliona/Troje.","C":"Naslov ne potječe od pjesnikova imena (Homer), nego od grada."},
  "2013_jesen_B__41": {"B":"Opis glagoljske regule benediktinaca odnosi se na drugi spomenik, a ne na Bašćansku ploču.","C":"Dvojezičan i dvopismeni nadgrobni natpis opisuje Plominski/drugi natpis, a ne Bašćansku ploču.","D":"Spomen braških i hvarskih knezova ne odnosi se na Bašćansku ploču."},
  "2013_jesen_B__42": {"A":"Zbornik ne sadrži poučno-moralizatorsku prozu, nego ranu petrarkističku liriku.","B":"Riječ nije o epistolama humanista, nego o pjesmama (petrarkističkoj lirici).","C":"Pjesme su na hrvatskome (petrarkisti), a ne latinske pjesme latinista."},
  "2013_jesen_B__43": {"A":"Frankopan je pisac 17. stoljeća (barok), dok Relković pripada 18. stoljeću.","C":"Mažuranić je romantičar 19. stoljeća, a ne suvremenik Relkovića.","D":"Brezovački je kraj 18. st., ali Đurđević je zadan kao točan suvremenik Relkovićeva razdoblja."},
  "2013_jesen_B__44": {"A":"Proživljavanje prošlosti u sadašnjosti opisuje Proustovo U traganju za izgubljenim vremenom, a ne Balzaca.","B":"Propadanje članova jedne obitelji prikazuje Zolin ciklus Rougon-Macquart, a ne Balzac.","C":"Dramski ciklus o bankarskoj obitelji je Krležin glembajevski ciklus, a ne Balzac."},
  "2013_jesen_B__45": {"A":"Predstava Hamleta u selu Mrduša Donja (Brešan) je groteska/satira, a ne kazalište apsurda.","B":"Majka Courage (Brecht) pripada epskome kazalištu, a ne apsurdu.","D":"Bez trećeg (Begović) je psihološka drama, a ne kazalište apsurda."},
  "2013_jesen_B__46": {"B":"Pogrešno svrstava djela: Novela od Stanca nije novela, nego komedija (1A, ne 1B).","C":"Pogrešno svrstava: Matijaš Grabancijaš je komedija (2A), a ne roman (2C).","D":"Pogrešno svrstava: Novela od Stanca je komedija (1A), a ne roman (1C)."},
  "2013_jesen_B__47": {"B":"Pogrešno: Džore Držić pripada renesansi (1C), a ne baroku (1A).","C":"Pogrešno: Đurđević je barok (3A), a ne renesansa; raspored ne odgovara.","D":"Pogrešno: Džore Držić nije prosvjetiteljstvo (1B), nego renesansa (1C)."},
  "2013_jesen_B__48": {"A":"Pravilno je 'opsjedati' (sa -sj-), a ne 'opsijedati'.","B":"Pravilno je 'premještati' (s -št-), a ne 'premjestati'.","C":"Pravilno je 'smjenjivati' (s kratkim 'mje'), a ne 'smijenjivati'."},
  "2013_jesen_B__49": {"A":"Pravilno je 'otpustiti' (jednačenje d→t ispred p), a ne 'odpustiti'.","C":"Pravilno je 'odcijepiti' (čuva se d ispred c), a ne 'otcijepiti'.","D":"Pravilno je 'odškrinuti', a ne 'otškrinutia'."},
  "2013_jesen_B__50": {"A":"Naglasak nije na prvome slogu 'iz-', nego na drugome '-bje-'.","C":"Naglasak nije na '-ga-', nego na '-bje-' (izbjȅgavati).","D":"Naglasak nije na '-va-', nego na '-bje-'."},
  "2013_jesen_B__51": {"A":"U 'iskrasti' r dolazi uz samoglasnik, pa nije slogotvorno.","C":"U 'iskrenuti' r je uz samoglasnik, pa nije slogotvorno.","D":"U 'iskriti' r je uz samoglasnik, pa nije slogotvorno."},
  "2013_jesen_B__52": {"A":"Nije riječ o jednačenju po mjestu tvorbe; h ispred prednjega vokala prelazi u š (palatalizacija).","B":"Nije jednačenje po zvučnosti; h se mijenja u š po palatalizaciji.","D":"Nije jotacija (spajanje sa j), nego palatalizacija stražnjega suglasnika h."},
  "2013_jesen_B__53": {"B":"'Tri Kralja' s velikim K nije ispravno; 'kralja' se piše malim slovom.","C":"'Sveta tri kralja' je također moguće, ali ovdje se traži zapis 'sveta Tri kralja' (varijanta ispita).","D":"'Kralja' se ne piše velikim slovom, pa 'Sveta tri Kralja' nije ispravno."},
  "2013_jesen_B__54": {"A":"Spoj s crticom 'anti-fašizam' nije pravilan; piše se spojeno.","B":"Spoj s crticom 'anti-fašizam' nije pravilan; piše se spojeno.","C":"Razdvojeno 'anti fašizam' nije pravilno; prefiks anti- piše se spojeno."},
  "2013_jesen_B__55": {"B":"'Baca-' već sadrži tvorbeni nastavak, a korijenski je morfem samo 'bac-'.","C":"'Bacač-' uključuje tvorbeni sufiks -ač, a korijen je 'bac-'.","D":"'Bacačic-' uključuje više sufikasa, a korijenski je morfem 'bac-'."},
  "2013_jesen_B__56": {"B":"'Momku' je dativ jednine, a ne vokativ.","C":"'Momak' je nominativ, a vokativ traži alternaciju k→c ('momče'/'momc').","D":"'Momaku' nije pravilan oblik vokativa imenice momak."},
  "2013_jesen_B__57": {"A":"Genitiv bi tražio prijedlog/kontekst tipa 'od riječi'; ovdje je 'u' + akuzativ.","B":"Dativ bi bio 'riječima' bez prijedloga 'u'; ovdje je akuzativ.","D":"Lokativ bi bio 'u riječima' (mirovanje), a ovdje je usmjerenje, dakle akuzativ."},
  "2013_jesen_B__58": {"A":"'Bijeliji' nije pravilan komparativ; ispravno je 'bjelji'.","B":"'Bijelji' zadržava 'ije', a u komparativu dolazi do kraćenja u 'bjelji'.","C":"'Bjeljiji' je dvostruko tvoren i nepravilan; ispravno je 'bjelji'."},
  "2013_jesen_B__59": {"A":"Trebalo bi 'svojoj školi' jer se odnosi na subjekt; 'mojoj' nije najtočnije.","B":"Trebalo bi 'svojim obiteljima' jer se odnosi na subjekt 'vi'; 'vašim' je pogrešno.","D":"Ako je subjekt isti, trebalo bi 'svoje roditelje'; 'tvoje' nije pravilno povratno-posvojno."},
  "2013_jesen_B__60": {"A":"'Bili su promatrali' je pluskvamperfekt, a ne imperfekt.","B":"'Promatrāhu' s aoristnim/krivim naglaskom nije traženi oblik imperfekta u standardu.","D":"'Promatraju' je prezent, a ne imperfekt."},
  "2013_jesen_B__61": {"B":"'Skačo' nije pravilan oblik; prezent 3. l. mn. glagola skočiti je 'skoče'.","C":"'Skakaju' je prezent glagola skakati (nesvršeni), a ne skočiti.","D":"'Skoče' je točan oblik, ali ponovljen je kao odgovor A (ista riječ), pa kao distraktor ne vrijedi."},
  "2013_jesen_B__62": {"A":"Ispred 'St' u 'Stjepanom' dovoljan je 's', no varijantno; standard traži 'sa' tek ispred s/š/z/ž/đ pa je 'sa đacima' uzorno.","B":"Ispred samoglasnika ('Istrankom') upotrebljava se 's', a ne 'sa'.","D":"Ispred 'č' ('četom') upotrebljava se 's', a ne 'sa'."},
  "2013_jesen_B__63": {"A":"'Obzirom da' je nestandardan uzročni veznik; pravilno je 'budući da' ili 's obzirom na to da'.","C":"'Pošto' u uzročnome značenju je nestandardno; pravilan je vremenski, a uzročno 'budući da'.","D":"Red riječi je pogrešan; 'budući' uvijek traži 'da' uz sebe ('budući da je')."},
  "2013_jesen_B__64": {"B":"'Istjecati' je neprijelazan (nema izravnoga objekta u akuzativu).","C":"'Sjediti' je neprijelazan glagol stanja, bez objekta.","D":"'Zijevati' je neprijelazan; ne traži izravni objekt."},
  "2013_jesen_B__65": {"A":"'Kralj Zvonimir' je sročni atribut (apozicija u istome padežu), a ne nesročni.","B":"'Ovlasti kralja' — 'kralja' je objekt/dopuna, a traži se nesročni atribut uz imenicu kralj.","D":"'Mikenski kralj' je sročni atribut (pridjev usklađen u rodu, broju, padežu), a ne nesročni."},
  "2013_jesen_B__66": {"A":"'U hotelu' odgovara na pitanje gdje (mirovanje), a ne kamo.","B":"'Trgom' odgovara na pitanje kuda/gdje, a ne kamo.","C":"'Ulicom' odgovara na pitanje kuda, a ne kamo."},
  "2013_jesen_B__67": {"B":"Rečenica nema tri surečenice; sastoji se od glavne i jedne uzročne, dakle dvije.","C":"Nema četiri surečenice; samo su dvije (glavna i zavisna uzročna).","D":"Nema pet surečenica; rečenica ima samo dvije."},
  "2013_jesen_B__68": {"A":"'Prijevoz putnika obavljao se' ima subjekt 'prijevoz', pa nije besubjektna.","B":"'Prijevoz je bio osiguran' ima subjekt 'prijevoz', pa nije besubjektna.","D":"'Mi smo putovali' ima neizrečeni subjekt 'mi', pa nije besubjektna."},
  "2013_jesen_B__69": {"A":"Zavisna 'neka pripaze' dopunjuje glagol 'zamoliti' kao objekt, pa je izrična, a ne atributna.","B":"Zavisna je dopuna predikatu 'rečeno', dakle izrična/objektna, a ne atributna.","C":"Zavisna 'neka pripaze' objekt je glagola 'rekao', pa je izrična, a ne atributna."},
  "2013_jesen_B__70": {"A":"'Nijemac' je etnik (naziv pripadnika naroda), a ne eponim nastao od osobnoga imena.","C":"'Pončo' je posuđenica (egzotizam), a ne riječ nastala od osobnoga imena.","D":"'Vukovar' je toponim (ime mjesta), a ne eponim nastao od osobnoga imena."},
  "2013_jesen_B__71": {"B":"'Ići kao pčele na med' (rado) i 'ići kao guske u maglu' (nepromišljeno) suprotnih su značenja.","C":"'Čuvati kao zjenicu oka' (jako paziti) i 'čuvati svoja leđa' (oprezno se štititi) nisu istoznačni.","D":"'Živjeti kao pas i mačka' (u svađi) i 'živjeti kao pas' (bijedno) različitih su značenja."},
  "2013_jesen_B__72": {"A":"Mihanović je autor Horvatske domovine (himne), ali nije održao prvi saborski govor na hrvatskom.","C":"Mažuranić je književnik i ban, ali prvi saborski govor na hrvatskome nije njegov.","D":"Gaj je vođa preporoda, no prvi službeni saborski govor na hrvatskom održao je Kukuljević."},

  // 2013_ljeto_A
  "2013_ljeto_A__1": {"A":"Subjekt ne govori o ljudskoj lažljivosti, nego o brzom nestajanju mladosti i ljepote ('Bježi mlados, dni othode').","B":"Tema nije nevjernost, nego prolaznost ljepote koju donosi vrijeme ('Skoro, skoro promijeniće vas tvoj ures').","C":"Ljubav se ne prikazuje kao pogubna; naprotiv, subjekt moli Ljubicu da se smiluje njegovoj ljubavi."},
  "2013_ljeto_A__2": {"A":"Biseri se obično vežu uz zube ili suze, a 'dvije zore zgara s nebi' kao nebeski sjaj metafora su za oči.","B":"Grudi nisu opisane slikom dviju zora s neba; ta se metafora odnosi na sjajne oči.","D":"Iako su zore i zvijezde slika s neba, ovdje ne označavaju zvijezde, nego sjajne oči ljubljene."},
  "2013_ljeto_A__3": {"A":"Bludnost se Ljubici ne predbacuje; prigovor je vezan uz njezino dičenje vlastitom ljepotom.","B":"Lažljivost nije osobina koju joj subjekt zamjera; tekst upozorava na njezinu uznositost ('ne oholi').","D":"Sebičnost nije izrijekom predbačena; jasno je naznačena samo oholost ('Tim se, mlada, ne oholi')."},
  "2013_ljeto_A__4": {"A":"Putovanje morem nije predmet poruke; gusar i more samo su metafora za prolaznost.","B":"Ljubica se ne poziva da bude nadahnuće, nego da se smiluje subjektovoj ljubavnoj patnji.","D":"Slika koju gleda u zrcalu spominje se kao njezina taština, a ne kao dar koji bi mu trebala pokloniti."},
  "2013_ljeto_A__5": {"B":"'Pram zlaćeni' označava zlatnu kosu, a ne vrijeme.","C":"'Ures' znači ljepota, krasota, a vrijeme je metaforizirano gusarom koji sve otima.","D":"'Vir' je izvor/zrcalna voda u koju se gleda, a ne metafora vremena."},
  "2013_ljeto_A__6": {"B":"Kraljevske lađe spominju se kao mjesto signalnog plamena, a ne kao 'omorikov zatvor'.","C":"Tamnica nije u pitanju; riječ je o drvenom konju u koji su skriveni vojnici.","D":"'Omorikov zatvor' nije sama Troja, nego drveni konj od omorikova drva."},
  "2013_ljeto_A__7": {"A":"Agamemnon se u ulomku ne spominje kao 'strašni'; taj epitet nosi Uliks.","B":"Ahilej nije naveden; strašnim se naziva Uliks koji izlazi iz konja.","C":"Hektor je trojanski junak i ne izlazi iz konja; 'strašni' je Uliks (Odisej)."},
  "2013_ljeto_A__8": {"B":"Bogovi su naklonjeni Grcima ('voljom božanskom'), ali mjesec je sklon onomu tko plovi, a to su Ahejci.","C":"Tened je otok s kojega Grci plove, a ne onaj komu je mjesec sklon.","D":"Trojancima mjesec nije sklon; nebeska je volja izrijekom 'nesklona trojanskom rodu'."},
  "2013_ljeto_A__9": {"A":"Uže se spušta tek nakon što Danajci izlaze iz konja, dakle nakon Sinonove radnje, a ne kao njezin povod.","B":"Sinon ne napušta grad; on otvara konj nakon ugovorenoga znaka.","C":"Mjesec ne zalazi; sija 'tih i sklon' dok Grci plove, signal je plamen, a ne zalazak mjeseca."},
  "2013_ljeto_A__10": {"B":"Epej (graditelj konja) ne spominje se kao spašeni; spašena je ahejska vojska, Danajci.","C":"Sinon je onaj koji otvara konj, a 'spaseni voljom božanskom' su Danajci u cjelini.","D":"Trojancima je božanska volja izrijekom nesklona, pa oni nisu spašeni."},
  "2013_ljeto_A__11": {"A":"Candide je Voltaireovo djelo i nema crnog mačka Plutona ni motiv pijanstva i okrutnosti.","C":"Gavran je Poeova pjesma, a ne ova pripovijest o mačku Plutonu i propadanju pripovjedača.","D":"Psi u trgovištu hrvatsko je djelo i ne odgovara ovom Poeovu predlošku o crnom mačku."},
  "2013_ljeto_A__12": {"A":"Subjekt nije ravnodušan; eksplicitno priznaje stid zbog promjene ('stid me i priznati').","B":"Ne ponosi se promjenama; opisuje ih kao 'promjenu nagore' i izriče stid.","D":"Ne čudi se promjenama, nego ih se srami i priznaje da su nabolje krenule nagore."},
  "2013_ljeto_A__13": {"B":"Obzirnost znači pažljivost prema drugima, a 'ćud' označava narav, karakter.","C":"Privrženost je odanost, vezanost, a ne istoznačnica za narav ('ćud').","D":"Zlovolja je samo jedno raspoloženje, dok 'ćud' označava cjelokupnu narav."},
  "2013_ljeto_A__14": {"B":"Inverzija je obrnuti red riječi, a ovdje je posrijedi stupnjevanje od blažega prema težemu.","C":"Metafora je prijenos značenja, a u nizu mrzovolja → nasilje riječi se rabe doslovno.","D":"Personifikacija pridaje ljudske osobine neživomu, čega ovdje nema; riječ je o gradaciji."},
  "2013_ljeto_A__15": {"A":"Alkoholizam je uzrok promjene pripovjedača, a ne Plutonove razdražljivosti.","B":"Privrženost ne uzrokuje razdražljivost; Pluton je postao razdražljiv jer je ostario.","D":"Zlostavljanje je posljedica pripovjedačeve naravi, a Plutonovu razdražljivost izaziva starost."},
  "2013_ljeto_A__16": {"A":"'Čista ljubav' istoznačna je s 'nepomućenom ljubavi', pa joj nije suprotstavljena.","C":"'Junonski stas' opisuje tjelesnu ljepotu i nije značenjski suprotan 'nepomućenoj ljubavi'.","D":"'Izvjedljivi posmješak' nije suprotnost čistoj ljubavi; oprjeku čine 'raskalašeni časovi'."},
  "2013_ljeto_A__17": {"A":"'Promjenjiva' znači nestalna, a 'izmjenična ljubav' znači uzajamna, koja ide u oba smjera.","B":"'Tajnovita' ne odgovara značenju; riječ je o uzvraćenoj, obostranoj ljubavi.","D":"'Zamjenska' znači nadomjesna, dok 'izmjenična' ovdje znači uzajamna."},
  "2013_ljeto_A__18": {"A":"'Nositi se' ovdje znači lijepo se odijevati, a ne podnositi životne probleme.","C":"Ne radi se o tjelesnoj snazi za nošenje tereta, nego o tome da je bila najljepše odjevena.","D":"Rečenica ne govori o ponosu, nego o tome da se nosila ljepše od svih ('najljepša odjeća')."},
  "2013_ljeto_A__19": {"A":"Kontrast je suprotstavljanje pojmova, a ovdje se život uspoređuje s vatrometom pomoću veznika.","B":"Oksimoron spaja proturječne pojmove, čega nema; posrijedi je usporedba.","C":"Personifikacija pridaje ljudske osobine, a ovdje se samo uspoređuje ('život sličan vatrometu')."},
  "2013_ljeto_A__20": {"A":"Beranek nije lik s kojim Tena doživljava čistu ljubav; čista, prva ljubav vezana je uz Jozu.","B":"Đorđe nije nositelj čiste, nepomućene ljubavi u romanu.","D":"Leon predstavlja kasniji, raskalašeni odnos, a čistu prvu ljubav Tena proživljava s Jozom."},
  "2013_ljeto_A__21": {"A":"Kamenski se ne osjeća neshvaćeno; teško se snalazi i zbunjen je u razgovoru.","C":"Zabrinutost nije naglašena; tekst pokazuje njegovu zbunjenost ('jedva nekako razabere').","D":"Zadovoljstvo ne odgovara njegovu stanju; Kamenski je smeten i u neugodi."},
  "2013_ljeto_A__22": {"A":"Prezime supruga (Forst, Fürst, Förster) sugovornik se ni ne sjeća, pa to nije znak da je Poljakinja.","B":"Način odijevanja ne spominje se kao prepoznatljiv znak; navodi se naglasak.","D":"Cilj putovanja (Montreux) ne otkriva podrijetlo; Poljakinja se prepoznaje po akcentu."},
  "2013_ljeto_A__23": {"A":"Auditivni podražaj veže se uz zvuk, a slika 'bjelasanja' i boja djeluje na vid.","B":"Olfaktivni podražaj odnosi se na miris, čega u ovoj slici nema.","C":"Taktilni podražaj odnosi se na dodir, a ovdje prevladavaju boje i sjaj (vid)."},
  "2013_ljeto_A__24": {"A":"Emma nije lik ove novele; tajanstvena dama o kojoj je riječ jest Fanny.","C":"Laura se ne spominje; dama je Fanny.","D":"Nora nije lik iz Camaa; tajanstvena se dama otkriva kao Fanny."},
  "2013_ljeto_A__25": {"B":"Nacionalna pripadnost ih ne povezuje; dama je Poljakinja.","C":"Socijalno podrijetlo nije zajednička poveznica; dama je kći propalih plemića.","D":"Psihička bolest nije ono što ih spaja; zajednička im je vezanost uz umjetnost."},
  "2013_ljeto_A__26": {"A":"Bolovi su simptom, a ne uzrok smrti; Mica umire od upale nastale nakon rezanja zaraženim srpom.","B":"Krvarenje nije navedeno kao uzrok; uzrok je infekcija ('zapalila sva').","C":"Požar nije uzrok smrti; 'zapalila se' odnosi se na upalu rane, a ne na vatru."},
  "2013_ljeto_A__27": {"A":"Šepavi nije čovjek; preskakanje plota i pitanje 'da li je bio potkovan' upućuju na konja.","C":"Pas se ne potkiva i ne 'otkasava'; opis odgovara konju.","D":"Svinju Miško vodi, a Šepavi je biće koje preskače plot i koje bi moglo biti potkovano, dakle konj."},
  "2013_ljeto_A__28": {"A":"'Umrijeti u mukama' izravno govori o patnji i smrti, pa nije ublažavanje (eufemizam).","B":"'Nevina smrt' ne ublažava pojam smrti, nego ga izravno imenuje.","D":"'Izdahnuti kasnije' također izravno označava umiranje, a eufemizam je 'zaklopiti oči'."},
  "2013_ljeto_A__29": {"A":"Boltek se veže uz kravu (bedrenicu), a ne uz umrlo dijete.","C":"Mikleuška je optužena za uzrok nesreće, ali dijete koje umire jest Micino.","D":"Miško je svinjar svjedok, a umrlo dijete pripada Mici Trebarčevoj."},
  "2013_ljeto_A__30": {"A":"Ova rečenica realistično opisuje uzrok ozljede (rezanje rđavim srpom) i ne iskazuje praznovjerje.","B":"Zahvala Bogu uobičajen je pobožni izraz, a ne praznovjerno vjerovanje u vradžbine.","C":"Veterinarova dijagnoza (bedrenica) racionalno je, medicinsko objašnjenje, suprotno praznovjerju."},
  "2013_ljeto_A__31": {"B":"Ribar se ne žali na nedobrodošlicu u gradu, nego na nesreću koja ga prati u tuđini i pod tuđom vlašću.","C":"Pitanje slobodne starosti nije predmet prve tužbe; on govori o stalnoj nesreći u progonstvu.","D":"Ribar se ne žali da ne zna pjevati; zavidi Radmilu na miru, a tuži se na vlastite nedaće."},
  "2013_ljeto_A__32": {"A":"Radmio ne traži dokaz ribarskoga umijeća, nego ga moli da ne kvari opće veselje.","C":"Ne traži da Ribar prestane lutati, nego da svojom tugom ne zasjeni radostan dan.","D":"Pitanje vjere u Boga nije Radmilov zahtjev; on traži da Ribar ne rastužuje zajednicu."},
  "2013_ljeto_A__33": {"A":"Ovi stihovi opisuju mir i ljepotu prirode Dubrave, a ne nepotkupljivost pravde.","B":"Ti stihovi opisuju pokvarenost tuđega svijeta gdje se sve prodaje za zlato, suprotno Dubravi.","D":"Ovi stihovi govore o teretu tuđega gospodstva, a ne o pravdi koja se ne da kupiti."},
  "2013_ljeto_A__34": {"B":"Zvijer se spominje kao ono čega u Dubravi nema, a metafora za Dubravu jest gnijezdo.","C":"Slavic (slavuj) je dio idilične slike prirode, a ne metafora same Dubrave.","D":"Zlato je simbol pokvarenosti tuđega svijeta, a Dubrava je 'gnijezdo slobode'."},
  "2013_ljeto_A__35": {"B":"Judita je ep (epika), a Dubravka je drama (pastorala), pa nisu istoga roda.","C":"Osman je ep (epika), dok Dubravka pripada drami.","D":"Planine su prozno-stihovno djelo (proza/epika), a ne drama kao Dubravka."},
  "2013_ljeto_A__36": {"B":"Euripid je grčki tragičar, ali opis (sukob onoga koji želi uništiti ljudski rod) odgovara Eshilovu Okovanom Prometeju.","C":"Homer je epski pjesnik, a ne tragičar sa 'sedam očuvanih tragedija'.","D":"Sofoklo je tragičar, ali sukob Zeusa i Prometeja djelo je Eshilovo."},
  "2013_ljeto_A__37": {"A":"Dubrovačka trilogija (Vojnović) ne sadrži lik Pometa, slugu bogatog Nijemca.","C":"Novela od Stanca kratka je Držićeva komedija o seljaku Stancu, bez 'kralja od ljudi' Pometa.","D":"Skup (Držić) tematizira škrtca, a Pomet kao 'kralj od ljudi' lik je Dunda Maroja."},
  "2013_ljeto_A__38": {"A":"Alfred Kamenski lik je iz Matoševa Camaa, a ne glavni junak Nehajeva Bijega.","B":"Đuka Begović junak je Kozarčeva djela, a ne 'hrvatski Hamlet' iz Bijega.","D":"Ivica Kičmanović lik je Šenoina Seljačke bune, a junak Bijega jest Đuro Andrijašević."},
  "2013_ljeto_A__39": {"A":"Ahilej je simbol ratničke snage i srdžbe, a ne potrage za znanjem.","B":"Edip je simbol tragične sudbine i (ne)znanja o sebi, ali ne potrage za znanjem u smislu Prometeja.","C":"Eneja je simbol dužnosti i osnivanja Rima, a tragatelj za znanjem jest Prometej."},
  "2013_ljeto_A__40": {"A":"'Modri filter šutnje' metafora je, a ne spoj proturječnih pojmova (oksimoron).","B":"'Teška zanoćja bez sna' opisuju mučnu besanicu, ali ne spajaju izravno suprotne pojmove.","D":"'Ozmijila me perom tijela' slikovit je izraz, ali ne sadrži proturječje kao 'ženski dječak'."},
  "2013_ljeto_A__41": {"A":"Pjesan o Cidu nije engleski ep; junak Cid pripada španjolskoj povijesti i književnosti.","B":"Francuski junački ep jest Pjesma o Rolandu, a Cid je španjolski.","D":"Talijanskoj književnosti pripadaju druga djela; Cid je španjolski nacionalni ep."},
  "2013_ljeto_A__42": {"A":"Andrija Kačić Miošić pisao je Razgovor ugodni naroda slovinskoga (stihovi/proza), a ne drame.","B":"Antun Matija Reljković autor je Satira (poučno-didaktički ep), a ne drama.","D":"Vid Došen pisao je didaktičku poeziju (Aždaja sedmoglava), a drame je pisao Brezovački."},
  "2013_ljeto_A__43": {"A":"Oglasnik ilirski iz 1818. ne odgovara Vrazu; on je djelovao u doba ilirizma 1830-ih i 1840-ih.","C":"Vraz nije bio urednik Zore dalmatinske ni protivnik Gajeve reforme; on je uređivao Kolo.","D":"Vijenac je kasniji časopis (Šenoa i dr.), a Vraz se veže uz Kolo."},
  "2013_ljeto_A__44": {"B":"Bijeg ne pripada fazi pobune ni kolektivnom optimizmu; junak je pasivan i poražen.","C":"Slika kolačića u lipovu čaju opis je iz Proustova U traganju za izgubljenim vremenom, ne iz Bijega.","D":"Slikar koji se vraća kući lik je iz Krležina Povratka Filipa Latinovicza, a ne iz Bijega."},
  "2013_ljeto_A__45": {"A":"Koraljna vrata (Nedjeljko Fabrio) povijesni su roman, a ne priča o studentskoj ekskurziji u Istru.","C":"Psi u trgovištu (Ivan Aralica) povijesna su proza, ne djelo o studentskom izletu.","D":"Vježbanje života (Nedjeljko Fabrio) opsežan je roman drukčije tematike; izlet u Istru opisuje Kratki izlet."},
  "2013_ljeto_A__46": {"B":"Pogrešno svrstava Đurđevića u barok kao B (romantizam); Đurđević je barokni pisac (A).","C":"Pogrešno svrstava Mažuranića u A (barok) umjesto u romantizam (B).","D":"Pogrešno svrstava Vetranovića u A (barok) umjesto u renesansu (C)."},
  "2013_ljeto_A__47": {"B":"Pogrešno povezuje stih 2 i 3; 'gledam more' je Kaštelan (C), a tvrđava srca Pupačić (B).","C":"Pogrešno pripisuje stih 5 ('Evo me, moj svijete') Kaštelanu (C); on je Pupačićev (B).","D":"Pogrešno pripisuje stih 1 ('Ubili su ga ciglama') Kaštelanu (C); taj je Slamnigov (A)."},
  "2013_ljeto_A__48": {"A":"'Podplaćen' je netočno; zbog jednačenja po zvučnosti piše se 'potplaćen'.","C":"'Podhranjen' je netočno; zbog jednačenja piše se 'pothranjen'.","D":"'Potsječen' je netočno; ispravno je 'podsječen' (čuva se zvučno d ispred s)."},
  "2013_ljeto_A__49": {"A":"Netočno je 'zacjeliti'; treba 'zacijeliti' (dugi jat ije u svršenom glagolu).","B":"'Zamjeriti' i 'zamjerati' nije pravilan par; nesvršeni je oblik 'zamjerati' uz 'zamjeriti', no ovdje se kao točan par traži 'zasjeći – zasjecati'.","C":"Netočno je 'zapovjedati'; ispravno je 'zapovijedati' (s dugim ije)."},
  "2013_ljeto_A__50": {"A":"Naglasak nije na prvom slogu (iz-); riječ je naglašena na drugom slogu (bjE).","C":"Naglasak nije na trećem slogu (-ga-), nego na drugom (bjE).","D":"Naglasak nije na četvrtom slogu (-va-), nego na drugom (bjE)."},
  "2013_ljeto_A__51": {"B":"U 'strijelac' r nije slogotvorno jer iza njega slijedi samoglasnik (stri-je-lac).","C":"U 'zgrada' r nije slogotvorno; nosilac sloga je samoglasnik a (zgra-da).","D":"U 'ždrijelo' r nije slogotvorno; slog nosi samoglasnik (ždri-je-lo)."},
  "2013_ljeto_A__52": {"A":"U 'besraman' dolazi samo jedna promjena (gubljenje zvučnosti z→s), a ne tri.","C":"U 'bešuman' dolazi do jednačenja po zvučnosti (z→š), ali ne i triju promjena.","D":"U 'bežičan' dolazi do jednačenja po mjestu/zvučnosti, ali ne triju promjena kao u 'bešćutan'."},
  "2013_ljeto_A__53": {"A":"U 'udrobljen' l je dio skupine bl (drob+ljen), to je epentetsko l, no točan primjer u zadatku je 'ustakljen'.","B":"U 'umišljen' nema epentetskog l; tu je sl (misl-) nastalo jotacijom, a ne umetanjem l zbog usnenika.","D":"U 'utemeljen' l je dio osnove (temelj), a ne umetnuti glas; epentetsko l ima 'ustakljen'."},
  "2013_ljeto_A__54": {"B":"Netočno: 'dan pobjede' ne smije imati malo d, a 'Domovinske' veliko, jer je čitav naziv blagdana jedno ime (Dan...).","C":"Netočno: 'Pobjede' ne piše se velikim slovom unutar naziva blagdana.","D":"Netočno: u nazivu blagdana samo prva riječ ('Dan') piše se velikim slovom, ne sve riječi."},
  "2013_ljeto_A__55": {"A":"Netočno: ne piše se ni razmaknuto ni s crticom ('srednjo – europski'); riječ je o sraslici.","B":"Netočno: spojnica se ne rabi jer dijelovi nisu ravnopravni, nego se pišu zajedno.","C":"Netočno: ne piše se odvojeno ('srednjo europski'); ispravno je 'srednjoeuropski'."},
  "2013_ljeto_A__56": {"B":"'Riba' nije korijenski morfem, nego osnova s krajnjim a; korijen je 'rib'.","C":"'Ribar' je tvorenica (rib+ar), a sam korijen je 'rib'.","D":"'Ribaric' nije morfem; korijen riječi je 'rib', a ostalo su tvorbeni i gramatički nastavci."},
  "2013_ljeto_A__57": {"A":"Nije genitiv; prijedlog 'na' s ovim oblikom otvara lokativ ('na njoj').","B":"Nije dativ; oblik 'njoj' uz prijedlog 'na' s mjesnim značenjem jest lokativ.","C":"Nije akuzativ; uz 'na' s mirovanjem (gdje?) stoji lokativ, a ne akuzativ."},
  "2013_ljeto_A__58": {"A":"'Stranac' je nominativ, a vokativ traži poseban oblik (stranče).","B":"'Strancu' je dativ/lokativ, a ne vokativ.","D":"'Stranće' je netočno; pravilno je 'stranče' (palatalizacija c→č ispred e)."},
  "2013_ljeto_A__59": {"A":"'Duboka' je neodređeni oblik pridjeva (duboka glasa), a ne određeni.","B":"'Njegovoj' je posvojna zamjenica, a Matošev je posvojni pridjev neodređena tipa, ne primjer određenog pridjeva.","C":"'Jakog' je neodređeni pridjev (uz neodređeni predmet), a ne određeni oblik."},
  "2013_ljeto_A__60": {"A":"Rečenica je ispravna: posuđuje se tuđa ('njezina') knjiga, što je smisleno.","B":"Rečenica je ispravna: povratno-posvojna 'svoju' pravilno upućuje na subjekt.","D":"Rečenica je ispravna: 'tvoju' knjigu posuđuje sugovornikovu, što je smisleno."},
  "2013_ljeto_A__61": {"A":"'Bio bih' je kondicional I. (sadašnji/prošli pogodbeni), a ne kondicional II.","C":"'Bio sam bio' je pluskvamperfekt (pretprošlo vrijeme), a ne kondicional.","D":"'Budem bio' je futur II., a ne kondicional II."},
  "2013_ljeto_A__62": {"A":"'Moraš' nije futur I.; oblik 'vratiti se' je infinitiv, a 'moraš' je prezent.","B":"'Moraš' nije imperativ (zapovjedni je oblik 'moraj'), nego prezent.","C":"'Moraš' nije perfekt; perfekt bi glasio 'morao si'."},
  "2013_ljeto_A__63": {"B":"'Nosijaše' je 3. lice jednine imperfekta, a subjekt 'prijatelji' traži množinu.","C":"'Nosihu' je nepravilan oblik; pravilan imperfekt mn. glasi 'nosijahu'.","D":"'Nosiše' je aorist 3. lica množine, a ne imperfekt."},
  "2013_ljeto_A__64": {"A":"'Svojih predaka' je nesročni atribut u genitivu uz 'jezikom', a ne sročni.","B":"'Poznavatelji jezika' je predikatna dopuna/poredba, a 'jezika' je genitivni (nesročni) dodatak.","D":"'Ulice' u 'jezikom ulice' je nesročni atribut u genitivu, a ne sročni."},
  "2013_ljeto_A__65": {"A":"'Pobjedu' je jedini objekt; 'protiv turske reprezentacije' je priložna oznaka/atribut, ne objekt.","B":"'Čitav dan' je priložna oznaka vremena, a jedini je objekt izostao ili nije dvostruk.","C":"'Jabuke' je jedini objekt; 'cijeli listopad' je oznaka vremena, ne objekt."},
  "2013_ljeto_A__66": {"B":"Veznik 'iako' uvodi dopusnu rečenicu, a ne objektnu.","C":"Veznik 'dok' uvodi vremensku rečenicu, a ne objektnu.","D":"Veznik 'jer' uvodi uzročnu rečenicu, a ne objektnu."},
  "2013_ljeto_A__67": {"A":"Dvije surečenice je premalo; rečenica ima tri predikata (daje, stvara, je sadržan).","C":"Četiri surečenice je previše; predikata je tri, pa su i surečenice tri.","D":"Pet surečenica je netočno; u rečenici su tri predikata, dakle tri surečenice."},
  "2013_ljeto_A__68": {"A":"'Ledolomac' nastaje slaganjem (led+lom+ac), ali ovdje se traži tipičan primjer složeno-sufiksalne tvorbe; 'rovokopač' je jasniji primjer (kopač kao nesamostalan dio).","B":"'Lovočuvar' je čista složenica (lov+čuvar), bez sufiksa na kraju koji bi tvorio novu riječ.","C":"'Romanopisac' je složenica (roman+pisac), a ne složeno-sufiksalna tvorba s posebnim sufiksom."},
  "2013_ljeto_A__69": {"A":"'Grančica' tvori se umanjenicom od 'grana' sufiksom -čica (gran+čica), a ne čistim -ica.","B":"'Klupčica' je umanjenica sa sufiksom -čica (klup+čica), a ne -ica.","D":"'Unučica' je tvorena sufiksom -čica (unu+čica), a ne -ica."},
  "2013_ljeto_A__70": {"A":"Antonimija je odnos suprotnosti značenja, a ovdje su značenja različita uz isti oblik (homonimija).","B":"Hiperonimija je odnos nadređenoga pojma, čega ovdje nema; riječ je o jednakim oblicima s različitim značenjem.","D":"Sinonimija je istoznačnost, a ovdje su značenja različita iako je oblik isti (homonimi)."},
  "2013_ljeto_A__71": {"A":"Dugo Selo je naziv naselja, dakle toponim (ojkonim), a ne antroponim.","C":"Južna Amerika je zemljopisno ime (kontinent), dakle toponim, a ne ime osobe.","D":"Republika Slovenija je ime države (toponim/horonim), a ne antroponim."},
  "2013_ljeto_A__72": {"A":"Bašćanska ploča nije darovnica kneza Domagoja; spominje dar kralja Zvonimira.","B":"Bašćanska ploča nije darovnica kralja Tomislava; u njoj je zabilježen Zvonimirov dar.","D":"Bašćanska ploča nije darovnica kneza Trpimira; riječ je o daru kralja Zvonimira."},

  // 2013_ljeto_B
  "2013_ljeto_B__1": {"A":"Stih 'Volio bih da me voliš' izriče želju kondicionalom, a ne sigurnost da će se ljubav ostvariti.","B":"Lirski subjekt ne govori o već ostvarenoj ljubavi, nego o onoj kojoj se tek nada.","C":"U pjesmi nema žaljenja za izgubljenom ljubavlju, nego čežnje za uzajamnošću."},
  "2013_ljeto_B__2": {"A":"Dan se ne navodi kao usporedba za lirski subjekt; spominje se tek u stihu 'da svi dani budu pjesma'.","B":"Noć je ono čemu se subjekt suprotstavlja ('Ako si noć, ja ću bit zora'), a ne ono s čime se uspoređuje.","C":"Pjesma je ono što subjekt želi da postanu dani, a ne usporedba za njega samog."},
  "2013_ljeto_B__3": {"A":"Stih ne sadrži pretjerivanje, nego suprotstavljanje pojmova noći i zore.","C":"Oksimoron spaja proturječne pojmove u jednu sintagmu, dok su ovdje noć i zora odvojene i suprotstavljene.","D":"Usporedba bi tražila izričito povezivanje veznikom 'kao', a ovdje je riječ o suprotstavljanju."},
  "2013_ljeto_B__4": {"A":"Rosa označuje sitne kapljice, a ne tekući izvor vode poput česme.","B":"Pjesma je apstraktan pojam i nema veze sa značenjem 'izvor'.","C":"Stijena je upravo ono mjesto uz koje 'bistra česma' teče, a ne sinonim za izvor."},
  "2013_ljeto_B__5": {"A":"Isprekidana rima podrazumijeva da samo neki stihovi imaju srok, no ovdje se rimuju parovi po shemi abab.","B":"Nagomilana rima znači da se nekoliko uzastopnih stihova rimuje istim srokom, čega ovdje nema.","C":"Obgrljena rima ima shemu abba, dok je ovdje raspored abab."},
  "2013_ljeto_B__6": {"A":"Desimra se navodi kao župan Krbave među svjedocima, a ne kao darovatelj.","B":"Dobrovit je opat koji je zidao crkvu, a nije darovao ledinu.","C":"Kosmat je knez koji vlada Krajinom, a ne onaj koji daruje."},
  "2013_ljeto_B__7": {"A":"Zapisivač je opat Držiha ('Ja opat Držiha pisah'), a ne Prbinevca.","B":"Tekst Prbinevcu ne pripisuje redovništvo, nego ulogu poslanika i svjedoka.","C":"Graditelj je opat Dobrovit koji je zidao crkvu, a ne Prbinevca."},
  "2013_ljeto_B__8": {"A":"Desimra je samo župan Krbave naveden kao svjedok, a nije vladao Krajinom.","C":"Dobrovit je opat koji je zidao crkvu, a nije vladar Krajine.","D":"Držiha je opat zapisivač, a ne vladar Krajine."},
  "2013_ljeto_B__9": {"A":"Uz Držihu se i opat Dobrovit javlja u prvom licu ('Ja opat Dobrovit zidah'), pa nije samo jedan kazivač.","C":"U prvom licu javljaju se samo Držiha i Dobrovit, a ne tri kazivača.","D":"Ostale spomenute osobe nabrojane su u trećem licu, pa nema četvorice kazivača u prvom licu."},
  "2013_ljeto_B__10": {"A":"Individualizacija označuje izdvajanje pojedinačnih osobina lika, a ne zaziv Boga.","B":"Interpretacija je tumačenje teksta, a ne početni zaziv Trojstva.","C":"Introspekcija je samopromatranje vlastitih osjećaja, čega u zazivu Boga nema."},
  "2013_ljeto_B__11": {"A":"Tekst čitatelja ne opisuje kao protivnika careve vladavine.","C":"Pripovjedač ne tvrdi da ga čitatelj hvali, nego mu se obraća kao 'dokonom'.","D":"Vrline se u tekstu pripisuju (lažno) sinu/djelu, a ne čitatelju."},
  "2013_ljeto_B__12": {"B":"Tekst ne govori o očekivanju objektivnog prosuđivanja, nego o tome da ne traži oprost.","C":"Pripovjedač ne preklinje čitatelja da hvali duhovitost djela.","D":"Pitanje slijepe vjere u napisano nije ono što pripovjedač izrijekom ne očekuje."},
  "2013_ljeto_B__13": {"A":"Pripovjedač sebe ne naziva bratom djela, nego očuhom.","B":"Riječ car ne opisuje pripovjedačev odnos prema djelu.","D":"Pripovjedač izrijekom poriče da je pravi otac djelu ('a uistinu sam mu očuh')."},
  "2013_ljeto_B__14": {"A":"Epilog se u tekstu ne spominje kao najteži dio za pisanje.","B":"Moto nije onaj dio koji ga je najviše namučio, nego predgovor.","C":"Posveta nije navedena kao najteže napisani dio knjige."},
  "2013_ljeto_B__15": {"B":"Carevina ne označuje knjigu, nego se odnosi na carstvo/posjed.","C":"Svat nema značenje knjige, nego sudionika svadbe.","D":"Iako je 'djelo' bliskoznačno knjizi, traženi je sinonim u polaznom tekstu 'svojevina'."},
  "2013_ljeto_B__16": {"A":"Albert Camus pisac je 20. stoljeća (Stranac), a ne Werthera.","B":"Dostojevski je ruski realist, autor drugih djela, a ne Patnji mladoga Werthera.","C":"Balzac je francuski realist, a ne autor ovog predromantičarskog djela."},
  "2013_ljeto_B__17": {"A":"Werther razgovor o smrti nije izbjegavao, nego je 'nikada nije pravio tajnu' od svoje namjere.","C":"Werther se vlastitoj smrti nije izrugivao; šalu je o toj temi dopuštao Albert.","D":"Tekst ne govori o Wertherovu strahu od smrti, nego o otvorenosti prema njoj."},
  "2013_ljeto_B__18": {"A":"Albert namjeru ne smatra uvredom, nego joj se suprotstavlja i u nju ne vjeruje.","B":"Zabrinutost zbog namjere muči Lottu, dok Albert iskazuje nevjericu.","C":"Albert nije iznenađen namjerom; on sumnja u njezinu ozbiljnost."},
  "2013_ljeto_B__19": {"B":"Nevjerojatna znači malo vjerojatna, što ne odgovara značenju riječi 'turobna'.","C":"Smirujuća je suprotno značenje; turobna slika upravo Lottu uznemiruje.","D":"Tajanstvena upućuje na zagonetnost, a 'turobna' znači žalosna, nevesela."},
  "2013_ljeto_B__20": {"A":"'Praviti tajnu od namjere' izravan je izraz, a ne ublažavanje neugodnog pojma.","C":"'Sumnjati u ozbiljnost nauma' nije ublaženi izraz za smrt, nego doslovna izjava.","D":"'Iskazati zabrinutost mužu' opisuje Lottin postupak, a nije eufemizam za smrt."},
  "2013_ljeto_B__21": {"A":"Brak se ne navodi kao izvor Stipančićevih briga.","C":"Društvo nije ono što Stipančić ističe kao uzrok briga.","D":"Stipančić izrijekom kaže da ga ne tare posao oko javnih stvari (politike), nego djeca."},
  "2013_ljeto_B__22": {"A":"Dubrovnik nije grad u kojem je smještena radnja romana.","C":"Iako je radnja zapravo u Senju, Senj nije ponuđen, a traženi odgovor je Rijeka.","D":"Split nije grad na koji se odnosi navedeni dio rečenice."},
  "2013_ljeto_B__23": {"A":"Ova rečenica govori o Valpurginu opažanju muževe zamišljenosti, a ne o njezinu položaju u braku.","B":"Rečenica opisuje Stipančićevu vanjštinu, a ne Valpurgin položaj.","C":"Rečenica govori o tome čemu Valpurga pripisuje muževo stanje, a ne o njezinoj podređenosti."},
  "2013_ljeto_B__24": {"A":"Eufemizam je ublaženi izraz neugodna pojma, čega u 'ispraznio ruke' nema.","B":"Hiperbola je pretjerivanje, a ovdje je ruka uzeta kao sredstvo rada/truda umjesto cjeline.","D":"Personifikacija pridaje ljudske osobine neživomu, što ovdje nije slučaj."},
  "2013_ljeto_B__25": {"A":"Marljivo znači s ustrajnošću, a 'naizust' znači napamet.","C":"Naslijepo znači bez razmišljanja/nasumce, a ne 'napamet'.","D":"Predano upućuje na posvećenost, dok 'naizust' znači učenje bez gledanja u tekst."},
  "2013_ljeto_B__26": {"B":"Strah puka nije razlog zbog kojega je Miljenko dobio Dubravku.","C":"Čestitost se u ulomku ne navodi kao razlog Miljenkove pobjede.","D":"Miljenkova ljepota nije razlog dodjele Dubravke; presudila je božja volja."},
  "2013_ljeto_B__27": {"A":"Bog nije značenje sintagme 'vjekuvječni vez', nego ona označuje vječnu vezu.","C":"Vjera se spominje zasebno ('da bi od vjere'), a 'vjekuvječni vez' označuje brak.","D":"Život nije ono na što upućuje sintagma 'vjekuvječni vez'."},
  "2013_ljeto_B__28": {"A":"Zaziv puka nije trenutak prestanka grmljavine; ona prestaje s Miljenkovim dolaskom.","B":"Oduzimanje Dubravke Grdanu nije navedeno kao trenutak prestanka grmljavine.","C":"Redovnikov ulazak prati upravo trešnja i grmljavina, koja prestaje tek kad uđe Miljenko."},
  "2013_ljeto_B__29": {"A":"Ironija znači reći suprotno od onoga što se misli, čega u prikazu zanesenosti nema.","C":"Personifikacija pridaje ljudske osobine neživomu, a ovdje se opisuje sam čovjek.","D":"Usporedba traži izričito povezivanje, dok je 'izvan sebe' preneseno (metaforično) značenje."},
  "2013_ljeto_B__30": {"A":"Pokušaj nije značenje riječi 'zlamenje'.","B":"Sreća nije značenje riječi 'zlamenje', nego je riječ o znaku.","C":"Zlo nije značenje riječi 'zlamenje'; ona znači znamen, znak."},
  "2013_ljeto_B__31": {"A":"Didaskalija ne govori o Pubinoj želji da pročita dokumente.","C":"Didaskalija ne navodi da se Puba osjeća uvrijeđenim.","D":"Didaskalija ne opisuje zaustavljanje u hodu, nego dolazak do riječi."},
  "2013_ljeto_B__32": {"A":"Matematički se odnosi na računanje, a 'juridički' znači pravno.","B":"Medicinski se odnosi na liječništvo, a ne na pravno prosuđivanje.","D":"Znanstveno je preširoko; 'juridički' upućuje upravo na pravno/sudsko stajalište."},
  "2013_ljeto_B__33": {"A":"Hiperbola je pretjerivanje, a ovdje konkretni predmet (lokot) stoji umjesto pojma zatvaranja.","B":"Poredba traži izričito uspoređivanje, čega u ovom izrazu nema.","D":"Personifikacija pridaje ljudske osobine neživomu, što ovdje nije slučaj."},
  "2013_ljeto_B__34": {"A":"Skomrakovo samoubojstvo nije tema ovog razgovora Pube i Glembaja.","C":"Baroničin preljub nije događaj o kojem se ovdje raspravlja.","D":"Propast banke nije tema ovog ulomka, nego slučaj Rupert-Canjeg."},
  "2013_ljeto_B__35": {"A":"Aretej ne pripada glembajevskom ciklusu, nego je zasebna Krležina drama.","B":"Kraljevo je ekspresionistička drama, a ne dio glembajevske trilogije.","D":"Vučjak nije dio glembajevskoga ciklusa."},
  "2013_ljeto_B__36": {"B":"Boccaccia ne smatramo utemeljiteljem putopisa, nego novele.","C":"Dekameron je zbirka novela, pa Boccaccia ne smatramo utemeljiteljem romana.","D":"Sonet je lirska pjesnička vrsta i ne odgovara opisu zbirke pripovijedaka."},
  "2013_ljeto_B__37": {"B":"Ivar nije lik čija je junakinja 'lutka'; Nora je u rukama svoga muža Helmera.","C":"Krogstad je ucjenjivač, ali Nora nije njegova 'lutka', nego Helmerova.","D":"Rank je obiteljski prijatelj, a ne onaj u čijim je rukama Nora kao lutka."},
  "2013_ljeto_B__38": {"A":"Crkveno prikazanje srednjovjekovni je dramski oblik, a ne barokni oblik pripovijesti o pokajanju.","C":"Biblijski ep nije oblik u kojem se najčešće ostvaruju barokne pripovijesti o kajanju grešnika.","D":"Melodrama nije književni oblik 17. stoljeća za teme pokajanja grešnika."},
  "2013_ljeto_B__39": {"A":"Stih od sedam slogova je sedmerac, a ne septima.","B":"Stih od sedam stopa nije definicija septime.","D":"Septima je strofa od sedam stihova, a ne pjesma od sedam strofa."},
  "2013_ljeto_B__40": {"B":"Tvorcem prvoga hrvatskog umjetničkog epa smatra se Marko Marulić (Judita), a ne Šižgorić.","C":"Prvu hrvatsku svjetovnu dramu ne pripisuje se Šižgoriću.","D":"Prvi hrvatski rječnik nije Šižgorićevo djelo."},
  "2013_ljeto_B__41": {"A":"Razrješenje deus ex machina i himna slobodi odnose se na Gundulićevu Dubravku, a ne na Dunda Maroja.","C":"Prolog satira i lik starca po Plautovu uzoru opis je Držićeve Skupi, a ne Dunda Maroja.","D":"Farsa u stihovima o pomlađivanju starca opisuje Novelu od Stanca, a ne Dunda Maroja."},
  "2013_ljeto_B__42": {"A":"Barok obilježava raskoš, dinamika i naglašena emocionalnost, a ne strogost pravila i prevlast razuma.","C":"Renesansu odlikuje humanizam i sklad, ali ne strog sustav pravila kao klasicizam.","D":"Romantizam ističe osjećaje i slobodu stvaranja, suprotno strogim pravilima i prevlasti razuma."},
  "2013_ljeto_B__43": {"A":"Ivan Mažuranić pripada hrvatskom romantizmu (preporodu), a ne realizmu.","B":"Petar Preradović preporodni je, romantičarski pjesnik, a ne realist.","D":"Vladimir Vidrić pjesnik je hrvatske moderne, a ne realizma."},
  "2013_ljeto_B__44": {"A":"Filologija je široka znanost o jeziku i književnosti, a ne posebno nauka o sastavljanju stihova.","B":"Sintaksa proučava ustrojstvo rečenice, a ne stih.","C":"Stilistika proučava stilska izražajna sredstva, a ne metriku stiha."},
  "2013_ljeto_B__45": {"A":"Antun Branko Šimić pripada ekspresionizmu (1920-e), a ne Pupačićevu naraštaju.","B":"Antun Gustav Matoš pjesnik je hrvatske moderne s početka 20. stoljeća.","D":"Tin Ujević pripada međuratnom razdoblju, a ne Pupačićevu poslijeratnom naraštaju."},
  "2013_ljeto_B__46": {"B":"Niz 1A, 2B, 3C, 4C, 5A pogrešan je jer su U registraturi i Zlatarovo zlato romani (C), a ne drama/novela.","C":"Niz 1B, 2A, 3C, 4A, 5B pogrešno svrstava romane Kovačića i Šenoe u novelu i dramu.","D":"Niz 1C, 2A, 3B, 4C, 5A netočno označuje Zlatarovo zlato kao dramu i Bijeg kao dramu."},
  "2013_ljeto_B__47": {"B":"Niz 1C, 2A, 3B, 4A, 5C netočno svrstava Baudelairea u romantizam, a Ibsena u modernizam.","C":"Niz 1B, 2C, 3A, 4B, 5A pogrešno označuje Baudelairea kao realista i Flauberta kao modernista.","D":"Niz 1A, 2B, 3C, 4A, 5B netočno svrstava Poea u realizam i Flauberta u romantizam."},
  "2013_ljeto_B__48": {"B":"Oblik 'plačica' nije pravilna umanjenica.","C":"Iako 'točkica' postoji, prema ispitnom ključu pravilan je odgovor 'bočica'.","D":"Iako 'vrčić' postoji, prema ispitnom ključu traženi je odgovor 'bočica'."},
  "2013_ljeto_B__49": {"A":"Oblik 'isčeprkati' nije pravilan jer nije provedeno jednačenje suglasnika.","B":"Oblik 'ičeprkati' (bez š/č-slijeda) ne odgovara pravopisnoj normi.","C":"Oblik 'izčeprkati' nije pravilan jer nije provedeno jednačenje po zvučnosti."},
  "2013_ljeto_B__50": {"A":"Slog 'pro-' nije naglašen; naglasak je na trećem slogu '-so-'.","B":"Slog '-fe-' nije naglašen u riječi profesorica.","D":"Slog '-ri-' nije naglašen, nego prethodni '-so-'."},
  "2013_ljeto_B__51": {"A":"U riječi cvjetnjak (cvjetnjak-a) glas a u kosim padežima ne ispada, pa nije nepostojano.","B":"Iako lijevak ima a koje se mijenja, prema ispitnom ključu traženi je primjer 'vjetar'.","C":"U riječi svijećnjak (svijećnjak-a) a se ne gubi, pa nema nepostojanog a."},
  "2013_ljeto_B__52": {"A":"Jednačenje po mjestu tvorbe odnosi se na suglasnike, a ne na promjenu u 'djeca → djece'.","B":"Jednačenje po zvučnosti tiče se zvučnih i bezvučnih suglasnika, ne ove promjene.","D":"Jotacija je stapanje suglasnika s glasom j, što ovdje nije provedeno."},
  "2013_ljeto_B__53": {"A":"Oblik 'vukovarsko-srijemski' malim početnim slovom nije pravilan jer je nastao od imena županije.","B":"Oblik 'Vukovarsko-srijemski' kao opis funkcije župana nije pravilan ako je riječ o navođenju funkcije; ispravan zapis je s velikim prvim i malim drugim dijelom.","C":"Oblik 'Vukovarsko-Srijemski' s dvama velikim slovima nije pravilan jer se drugi dio piše malim slovom."},
  "2013_ljeto_B__54": {"A":"Zapis 'slovensko – hrvatskoj' s razmacima oko crtice nije pravilan.","B":"Zapis 'slovensko hrvatskoj' bez crtice nije pravilan za složeni pridjev.","D":"Zapis 'slovenskohrvatskoj' sastavljeno nije pravilan jer su elementi ravnopravni i traže crticu."},
  "2013_ljeto_B__55": {"B":"'-ca' nije gramatički morfem ove riječi; gramatički je nastavak samo '-a'.","C":"'-ica' je tvorbeni (sufiksalni) morfem, a ne gramatički nastavak za oblik.","D":"'-ljica' nije gramatički morfem, nego pripada tvorbi riječi."},
  "2013_ljeto_B__56": {"A":"Imenica keks u instrumentalu glasi 'keksom' (nastavak -om), a ne -em.","C":"Imenica kralj u instrumentalu glasi 'kraljem', no prema ispitnom ključu traženi je primjer 'kelj'.","D":"Imenica kut u instrumentalu glasi 'kutom' (nastavak -om), a ne -em."},
  "2013_ljeto_B__57": {"A":"Oblik 'Baudelaira' nije pravilan jer izostavlja nijemo -e iz osnove.","B":"Oblik 'Baudelaire-a' s crticom nije pravilan; nastavak se dodaje bez crtice.","D":"Oblik 'Baudelaireja' s umetnutim -j- nije pravilan za prezime na nijemo -e."},
  "2013_ljeto_B__58": {"B":"Iako je 'žešćega' pravilan komparativ, prema ispitnom ključu traženi je primjer rečenica A.","C":"Oblik 'slastniji' nije standardan; pravilan je komparativ 'slađi'.","D":"Oblik 'gorču' nije standardan komparativ pridjeva gorak."},
  "2013_ljeto_B__59": {"A":"Dativ odgovara na pitanje komu/čemu, a 'na izlazu' odgovara na pitanje gdje.","B":"Akuzativ uz 'na' označuje smjer (kamo), a ovdje 'na izlazu' označuje mjesto (gdje).","D":"Instrumental odgovara na pitanje s kim/čim ili kuda, a ne na 'na izlazu'."},
  "2013_ljeto_B__60": {"A":"Iako je 'za nikakvu' uz niječni glagol pravilno, prema ispitnom ključu traženi je primjer rečenica C.","B":"Iako je 'za nikoga' uz niječni glagol pravilno, prema ispitnom ključu traženi je odgovor C.","D":"Iako je 'ničijem' uz niječni glagol pravilno, prema ispitnom ključu traženi je odgovor C."},
  "2013_ljeto_B__61": {"A":"'Neka izvoli' imperativ je 3. lica jednine, a ne 2. lica.","B":"'Izvolijevaj' nije pravilan imperativ glagola izvoljeti.","D":"'Izvoli!' s uskličnikom isti je oblik, no traženi je čist oblik 'izvoli' bez uskličnika prema ključu."},
  "2013_ljeto_B__62": {"A":"'Uzmicasmo' je 1. lice množine (imperfekta/aorista), a ne 3. lice množine aorista.","B":"Iako je 'pobjegoše' 3. lice množine aorista, prema ispitnom ključu traženi je primjer 'izbrisaše'.","D":"'Da nas posluša' je prezent (s česticom da), a ne aorist 3. lica množine."},
  "2013_ljeto_B__63": {"B":"Oblik 'smijestati' nije pravilan vidski parnjak glagola smjestiti.","C":"Oblik 'smještavati' nije standardni vidski parnjak; pravilan je 'smještati'.","D":"Oblik 'smijestati' nije pravilan ni po obliku ni kao vidski parnjak."},
  "2013_ljeto_B__64": {"A":"Grad (m. r.) i Križevci (m. r. množine) različita su broja, no traženi je primjer s objema imenicama istog roda u jednini.","B":"Planina (ž. r.) i Velebit (m. r.) nisu u istom gramatičkom rodu.","D":"Selo (s. r.) i Žalije nisu u istom gramatičkom rodu."},
  "2013_ljeto_B__65": {"A":"Rečenica ima tri surečenice (glavnu te vremensku i namjernu zavisnu), a ne dvije.","C":"Rečenica nema četiri surečenice; jasno se izdvajaju tri.","D":"Rečenica nema pet surečenica, nego tri."},
  "2013_ljeto_B__66": {"B":"U 'gradu iz snova' imenicu grad pobliže određuje samo jedna odredba, a ne dva atributa.","C":"U 'libijskoga grada' uz grad stoji samo jedan atribut.","D":"U 'naš grad' imenicu grad određuje samo jedan atribut."},
  "2013_ljeto_B__67": {"A":"'Motornim brodovima' je instrumental sredstva, a ne imenski dio predikata.","B":"'Odnosom prema poslu' je instrumental uz pridjev zadovoljan, a ne imenski predikat.","C":"'Virusom' je instrumental sredstva uz 'zaraženo', a ne imenski dio predikata."},
  "2013_ljeto_B__68": {"A":"Načinske rečenice odgovaraju na pitanje kako, a ovdje veznik 'budući da' označuje uzrok.","B":"Namjerne rečenice izriču svrhu, a 'budući da je padala kiša' izriče uzrok.","C":"Posljedične rečenice izriču posljedicu, a ovdje je riječ o uzroku nedolaska na izlet."},
  "2013_ljeto_B__69": {"A":"U 'preko zebre' riječ je o metaforičnom (slikovitom) nazivu pješačkog prijelaza, a ne o metonimiji.","B":"'Grana znanosti' metaforičan je izraz za područje, a ne metonimijski prijenos.","C":"'More ljudi' je metafora/hiperbola za mnoštvo, a ne metonimija."},
  "2013_ljeto_B__70": {"A":"Antonimija je odnos suprotnih značenja, a ove dvije riječi nisu suprotne.","B":"Hiperonimija je odnos nadređenog i podređenog pojma, čega ovdje nema.","D":"Sinonimija je istoznačnost, no ove riječi imaju potpuno različita značenja."},
  "2013_ljeto_B__71": {"A":"'Čistiti pred svojim pragom' i 'obilaziti tuđe pragove' imaju različita značenja, a nisu bliskoznačni.","C":"'I vuk sit i ovce na broju' i 'pojeo vuk magare' nisu bliskoznačni izrazi.","D":"'Postati prah i pepeo' (umrijeti/nestati) i 'postati kost i koža' (smršavjeti) nisu bliskoznačni."},
  "2013_ljeto_B__72": {"A":"Ardelio Della Bella talijansko-dubrovački je leksikograf, a ne pripadnik ozaljskog kruga.","B":"Ivan Belostenec autor je Gazophylaciuma, ali se ne ubraja u ozaljski krug.","C":"Jakov Mikalja dubrovački je leksikograf, a ne pripadnik ozaljskog kruga."},

  // 2014_jesen_A
  "2014_jesen_A__1": {"A":"Tekst ne potiče na natjecanje s drugima, nego naglašava da je pjesnikova prtljaga lakša od tuđe.","B":"Lirski subjekt izrijekom nema ni zlata ni srebra i ne teži stjecanju bogatstva.","D":"Putovanje ovdje znači nastavak života, a ne povratak kući."},
  "2014_jesen_A__2": {"A":"'Prtiti' nema značenje brojenja.","B":"Glagol 'prtiti' označuje nošenje, a ne gledanje.","D":"Drugi kovčege nose sa sobom, a ne ostavljaju ih."},
  "2014_jesen_A__3": {"A":"Težina osjećaja nije istaknuta glasovnim sredstvima nego grafičkim isticanjem velikim slovom.","C":"Isticanje nije postignuto oblikom riječi nego pisanjem velikoga slova.","D":"Učinak ne proizlazi iz reda riječi u rečenici nego iz grafičkog isticanja."},
  "2014_jesen_A__4": {"A":"Neživomu mjehuru ne pripisuju se ljudske osobine pa nema personifikacije.","C":"Nema stupnjevitog pojačavanja pojmova kakvo traži gradacija.","D":"Iskaz nije ironičan jer se ne kaže suprotno od onoga što se misli."},
  "2014_jesen_A__5": {"A":"Tekst nije stihovani putopisni spjev s razvijenom radnjom.","C":"Nema baladne pripovjedne fabule ni tragičnog događaja.","D":"Nije riječ o kratkoj proznoj crtici nego o ritmiziranoj lirskoj prozi."},
  "2014_jesen_A__6": {"A":"U tekstu nema spomena da su mu stradanja objavili bogovi.","B":"Uliks je spomenut tek kao protivnik, a ne kao izvjestitelj.","C":"Eneja ne spominje da je bio u drvenome konju nego da je bio osobno upleten u zbivanja."},
  "2014_jesen_A__7": {"A":"Stih opisuje pozornost slušatelja, ne lukavstvo Danajaca.","B":"Stih govori o Enejinoj boli pri pripovijedanju, a ne o danajskoj proračunatosti.","C":"Stih iznosi umor od rata i nesklonost sudbine, bez prijevare."},
  "2014_jesen_A__8": {"A":"'Kraljevstvo' označuje Troju, a ne drvenoga konja.","B":"'Rat' je sukob Danajaca i Trojanaca, a ne konj.","C":"'Sudba' označuje usud, a ne drvenoga konja."},
  "2014_jesen_A__9": {"A":"Asindeton bi značio izostavljanje veznika, čega u stihu nema.","B":"Nema izostavljanja rečeničnog dijela kakvo obilježuje elipsu.","D":"Polisindeton bi tražio gomilanje veznika, čega ovdje nema."},
  "2014_jesen_A__10": {"A":"Danajci (Grci) Enejini su neprijatelji koji razaraju Troju.","B":"Kartažani su Didonin narod kojemu Eneja samo pripovijeda.","C":"Eneja je rodonačelnik Rimljana, ali sam podrijetlom Trojanac."},
  "2014_jesen_A__11": {"A":"Ban nije onaj koji traži pomoć nego se njegova vojska spominje kao prijetnja.","C":"Kralja u ulomku nema kao tražitelja sučeve pomoći.","D":"Vojnik ne traži sučevu pomoć; obraća mu se kovač Štakor."},
  "2014_jesen_A__12": {"B":"Konjanici se nisu naoružavali nego su pobjegli.","C":"Nigdje se ne spominje paljenje konjanika.","D":"Konjanici nisu zarobljeni nego su 'podbrusili pete'."},
  "2014_jesen_A__13": {"A":"Prvi 'bijes' bijahu Gregorijančevi banderijalci, no 'drugi bijes' odnosi se na banovu vojsku.","B":"Kraljeva vojska u ovome ulomku nije ono što nadolazi kao 'drugi bijes'.","D":"Sudac nema svoju vojsku; 'drugi bijes' jest banova vojska."},
  "2014_jesen_A__14": {"B":"Bježe protivnici, pa građani nisu poraženi.","C":"Iz opisa borbe vidljiva je njihova snaga, a ne nemoć.","D":"Pijani su Gregorijančevi banderijalci, a ne građani."},
  "2014_jesen_A__15": {"A":"Rečenica opisuje kovačev dolazak bez ikakva preuveličavanja.","C":"Iskaz o kralju izriče tvrdnju, a ne hiperboličko pretjerivanje.","D":"Stih o zvonu poziva na pobunu, ali ne sadrži pretjerivanje kao hiperbola."},
  "2014_jesen_A__16": {"A":"Gazdarica se u ulomku ne spominje kao osoba koja grdi Akakija.","C":"Liječnik nije onaj koji ga je izgrdio.","D":"Prijatelj nije taj koji ga je prekorio; to je učinio general."},
  "2014_jesen_A__17": {"A":"Peterburško podneblje vezano je uz mećavu na ulici, a ne uz zadovoljstvo visoke ličnosti.","B":"U tekstu se ne spominje nikakav lijek kao razlog zadovoljstva.","C":"Akakijeviča zaboravljivost odnosi se na njega, a ne na ono što veseli visoku ličnost."},
  "2014_jesen_A__18": {"B":"Rečenica iskazuje šok, a ne naviknutost na neuspjehe.","C":"Odrvenjelost je posljedica potresenosti, a ne nemara prema sebi.","D":"Riječ je o reakciji na prijekor, a ne o strahu od smrti."},
  "2014_jesen_A__19": {"A":"Izraz je doslovan opis gubitka pomoći, bez ublažavanja.","B":"Naručivanje lijesa imenuje stvar izravno, bez ublažavanja.","C":"Propisivanje obloga doslovan je medicinski izraz, ne eufemizam."},
  "2014_jesen_A__20": {"B":"Nije tražio novčanu potporu nego zauzimanje za svoj slučaj.","C":"Nije došao prijaviti izdaju.","D":"Akakije je žrtva krađe kabanice, a ne onaj koji bi je otimao."},
  "2014_jesen_A__21": {"A":"Filip prema starcu ne pokazuje suosjećanje nego odbojnost.","C":"Filip se starčevoj karijeri ne divi, nego ga ruga njegovu ponašanju.","D":"Filip starcu ne zavidi na izgledu, već ga opisuje s gnušanjem."},
  "2014_jesen_A__22": {"A":"'Kosmato' ne znači bolesno.","C":"'Kosmato' nema značenje strašno.","D":"'Kosmato' se ne odnosi na veličinu nego na dlakavost."},
  "2014_jesen_A__23": {"A":"Eufemizam bi ublažavao iskaz, a ovdje je riječ o pogrdnoj zamjeni naziva.","B":"Nema preuveličavanja kakvo obilježuje hiperbolu.","D":"Nema stupnjevanja pojmova kakvo traži gradacija."},
  "2014_jesen_A__24": {"A":"Pitanje je dio Filipova unutarnjeg monologa, a ne pripovijedanja u trećem licu.","B":"I ovaj je iskaz Filipovo retoričko pitanje, dio njegove svijesti.","C":"Iako spominje Bobu, ovo je dio doživljaja unutar Filipove perspektive, a izrijekom o pripovjedaču govori rečenica s imenom Filip."},
  "2014_jesen_A__25": {"A":"Eleonora nije Bobino pravo ime.","B":"Karolina nije Bobino pravo ime.","D":"Regina nije Bobino pravo ime; ono glasi Ksenija."},
  "2014_jesen_A__26": {"A":"Divjak nije pastir nego satir.","B":"Divjak nije ribar.","D":"Divjak nije starac nego mitsko biće, satir."},
  "2014_jesen_A__27": {"A":"Jeljenka ne prekorava Divjaka zbog njegova odnosa prema vlastitu životu.","C":"Divjak ne obezvređuje plemkinje; naprotiv, slijedi vile.","D":"Prijekor nije zbog želje da napusti Dubravu nego zbog zanesenosti vilama."},
  "2014_jesen_A__28": {"B":"'Naravna lipos' odnosi se na Jeljenkinu ljepotu, a ne na krajolik.","C":"'Drag ures' označuje njezin nakit/ljepotu, ne krajolik.","D":"'Stvar najdraža' odnosi se na nju samu, ne na okolinu."},
  "2014_jesen_A__29": {"A":"'Čemeran' ne znači lažan.","B":"'Čemeran' ne znači naporan.","C":"'Čemeran' ne znači uzaludan nego žalostan, gorak."},
  "2014_jesen_A__30": {"A":"Stih govori o njezinoj osamljenosti u divljini, a ne o ljepoti.","B":"Stih opisuje himbenost i nakićenost vila, suprotno Jeljenkinoj naravnosti.","C":"Stih kritizira umjetnu uljepšanost vila, a ne Jeljenkinu prirodnu ljepotu."},
  "2014_jesen_A__31": {"B":"Begović nije autor 'Šest lica traži autora'.","C":"Krleža nije autor ove drame.","D":"Beckett nije autor ovoga djela; napisao ga je Pirandello."},
  "2014_jesen_A__32": {"A":"Sukob nije utemeljen na komičnom i tragičnom nego na granici fikcije i zbilje.","C":"Tema ropstva i slobode nije okosnica ovoga sukoba.","D":"Sukob ne počiva na ljubavi i mržnji nego na pitanju stvarnosti i iluzije."},
  "2014_jesen_A__33": {"A":"Mora je upravo ono čega se Redatelj oslobađa, a ne izvor olakšanja.","B":"Smijeh pripada Prvaku, a Redatelju olakšanje donosi svjetlost.","D":"Vika izaziva napetost, a olakšanje donosi nastup snažne svjetlosti."},
  "2014_jesen_A__34": {"B":"Prvak je glumac, a ne jedno od šest lica koja traže autora.","C":"Prvakinja je glumica, a ne lice koje traži autora.","D":"Redatelj pripada kazališnoj družini, a ne šestorici lica."},
  "2014_jesen_A__35": {"B":"Deus ex machina je neočekivani rasplet voljom više sile, što nije postupak ove drame.","C":"Quid pro quo je zamjena osoba/zabuna, što ovdje nije temeljni postupak.","D":"Umetanje songova obilježje je epskoga kazališta, a ne Pirandellove drame."},
  "2014_jesen_A__36": {"B":"'Elektra' se temelji na mitu o Atridima, a ne o Edipovu rodu.","C":"'Kralj Edip' obrađuje Edipovu sudbinu, ali ne suprotstavljanje kraljevoj zapovijedi o pokopu.","D":"'Okovani Prometej' govori o Prometeju, a ne o Edipovu rodu."},
  "2014_jesen_A__37": {"A":"Karnarutić je autor 'Vazetja Sigeta grada', a ne prvoga hrvatskog epa.","B":"Šižgorić je pisao na latinskome, nije autor prvoga epa na hrvatskome.","D":"Vetranović nije autor prvoga hrvatskog biblijsko-vergilijanskog epa; to je Marulić."},
  "2014_jesen_A__38": {"A":"Šenoa je pisac romantizma/realizma, a ne autor ovog romana moderne.","B":"Leskovar piše psihološke novele, nije autor 'Bijega'.","D":"Novak nije autor ovoga romana o bezvoljnu intelektualcu; napisao ga je Nehajev."},
  "2014_jesen_A__39": {"A":"Barok prethodi romantizmu (17. stoljeće), ne slijedi nakon njega.","B":"Klasicizam je usporedan/prethodi romantizmu, a ne slijedi ga.","D":"Renesansa je mnogo ranije razdoblje (15.–16. st.)."},
  "2014_jesen_A__40": {"A":"Gradacija je stupnjevanje, a ne obraćanje Muzi.","C":"Retardacija je usporavanje radnje, a ne zaziv nadahnuća.","D":"Retrospekcija je vraćanje u prošlost, a ne obraćanje Muzi."},
  "2014_jesen_A__41": {"A":"Vergilijanski spjev sa starozavjetnom temom opisuje 'Juditu', a ne 'Robinju'.","B":"'Robinja' nije junački ep nego drama.","D":"Stihovana pripovijest o svetici iz Palerma jest 'Sveta Rozalija', a ne 'Robinja'."},
  "2014_jesen_A__42": {"A":"Kanižlić se nije odrekao djela tom sintagmom.","B":"Đurđević nije autor te izjave o 'porodu od tmine'.","D":"Palmotić nije pisac koji je tako nazvao svoja mladenačka djela."},
  "2014_jesen_A__43": {"A":"Breton je autor nadrealističkog, a ne futurističkog manifesta.","C":"Bahr je teoretičar moderne, nije autor futurističkog manifesta.","D":"Tzara je utemeljitelj dadaizma, a ne futurizma."},
  "2014_jesen_A__44": {"A":"'1909.' nije kajkavska pjesma.","B":"'Khevenhiller' nije pisan kajkavskim narječjem.","C":"'Notturno' nije kajkavska pjesma."},
  "2014_jesen_A__45": {"B":"Pupačić je pjesnik zavičaja i obitelji, a ne forme i paradoksa.","C":"Milićević ne odgovara opisu pjesnika igre i doskočica.","D":"Mihalić je pjesnik egzistencijalne tjeskobe, a ne formalne igre."},
  "2014_jesen_A__46": {"B":"Krivo pripisuje Juriš Krleži (treba Šimić) i Plamen Šimiću (treba Krleža).","C":"Krivo pripisuje Pečat Šimiću umjesto Krleži.","D":"Krivo pripisuje Kolo Krleži i Pečat Vrazu te Vijavicu Šimiću."},
  "2014_jesen_A__47": {"B":"Kranjčević nije moderna nego realizam, pa je 5C pogrešno.","C":"Mažuranić nije realizam nego romantizam, pa je 1B pogrešno.","D":"Kamov nije romantizam nego moderna, pa je 2B pogrešno."},
  "2014_jesen_A__48": {"A":"Pravilno je 'lijevajući' (ije), ne 'ljevajući'.","B":"Pravilno je 'miješajući' (ije), ne 'mješajući'.","C":"Pravilno je 'pjevajući' (je), ne 'pijevajući'."},
  "2014_jesen_A__49": {"A":"Iza glagola 'upitao je' ispred upravnoga govora treba dvotočje, a ne izravan navodnik bez interpunkcije.","B":"Iza upravnoga govora s upitnikom ne dolazi zarez prije zatvaranja navodnika; zarez iza 'upitao je' također je pogrešan.","C":"Nakon upitnika unutar navodnika ne piše se zarez prije nastavka rečenice."},
  "2014_jesen_A__50": {"A":"'Odsjek', 'Sveučilište' trebaju veliko slovo, što ovdje izostaje.","B":"'Kroatistiku' je opisni dio i piše se malim slovom; 'Filozofskoga fakulteta' je netočno s velikim K.","D":"'Fakulteta' se piše malim slovom unutar imena ('Filozofskoga fakulteta')."},
  "2014_jesen_A__51": {"B":"Oblik 'hobia' nije pravilan jer izostaje međusamoglasničko j.","C":"Pisanje sa spojnicom 'hobi-a' nije pravopisno ispravno.","D":"Oblik 'hobij-a' s rastavljanjem nije pravilan zapis genitiva."},
  "2014_jesen_A__52": {"B":"'Mrȁv' ima kratkosilazni naglasak, ne dugosilazni.","C":"'Pȑst' ima kratkosilazni naglasak.","D":"'Slȍn' ima kratkosilazni naglasak."},
  "2014_jesen_A__53": {"A":"'Mast – slast' razlikuje se po više glasova (dodani s, l), pa nije minimalni par.","B":"'Mast – kost' razlikuje se u dvama glasovima (m/k, a/o).","D":"'Mast – mošt' razlikuje se u dvama glasovima (a/o i s/š)."},
  "2014_jesen_A__54": {"B":"Jednačenje po zvučnosti mijenja zvučne/bezvučne parove, čega ovdje nema.","C":"Palatalizacija pretvara k/g/h u č/ž/š ispred e/i, a to nije slučaj u 'čvršći'.","D":"Sibilarizacija daje c/z/s ispred i, što se ovdje ne događa."},
  "2014_jesen_A__55": {"B":"U 'potpisi' nema promjene k/g/h u c/z/s, pa nema sibilarizacije.","C":"U 'premazi' z je dio osnove, nije nastao sibilarizacijom.","D":"'Trbusi' pokazuje sibilarizaciju h→s, no traženi je primjer 'mjeseci' (c)."},
  "2014_jesen_A__56": {"B":"'Razri-je-di-ti' krivo dijeli prvi slog jer 'raz' čini zaseban slog.","C":"'Ra-zri-je-di-ti' pogrešno premješta z u drugi slog.","D":"'Raz-ri-je-di-ti' razdvaja 'rije' koje čini jedan slog s dvoglasnikom ije."},
  "2014_jesen_A__57": {"A":"Zabrinutost je uzrok, pa treba 'zbog', a ne ciljni 'radi'.","C":"Bolest je uzrok izostanka, pa treba 'zbog'.","D":"Radovi su uzrok kašnjenja, pa treba 'zbog', ne 'radi'."},
  "2014_jesen_A__58": {"A":"'Poglavar-Ø' ne izdvaja prefiks po- ni sufiks -ar.","B":"'Po-glavar-Ø' ne odvaja sufiks -ar od korijena.","C":"'Po-gla-var-Ø' dijeli na slogove, a ne na morfeme."},
  "2014_jesen_A__59": {"A":"'Željeli bih' miješa množinu participa s jedninskim 'bih'.","C":"'Željeli bi' je 3. lice množine, ne drugo.","D":"'Željeli bismo' je 1. lice množine, ne drugo."},
  "2014_jesen_A__60": {"A":"Uz 'nastambe' treba određeni pridjev 'polarnoga medvjeda', ne 'polarna'.","B":"Treba 'mojega zelenoga kaputa' (određeni oblik), ne 'zelena'.","D":"Treba 'najdražega prijatelja', a ne 'najdraža'."},
  "2014_jesen_A__61": {"A":"Slabo upravljanje veže glagol s padežom bez prijedloga, što nije veza u ovoj sintagmi.","B":"Jako upravljanje traži određeni prijedlog/padež, čega ovdje nema.","C":"Pridruživanje povezuje nepromjenjive riječi, a ovdje se pridjev mijenja prema imenici."},
  "2014_jesen_A__62": {"A":"'O ljudima' ne pobliže označuje imenicu pa nije atribut.","B":"Ne odgovara na pitanje o objektu radnje na koji se izravno prelazi radnja.","C":"Predikat je 'želio je razgovarati', a ne 'o ljudima'."},
  "2014_jesen_A__63": {"A":"Aorist bi glasio 'bi/bijasmo' u značenju prošloga svršenog, što 'bijaše' nije.","C":"Perfekt bi glasio 'bila je', a ne 'bijaše'.","D":"Prezent bi glasio 'jest/je', a 'bijaše' je prošli oblik."},
  "2014_jesen_A__64": {"A":"'Nisu mogli' izostavlja infinitiv 'pomoći' koji je dio glagolskog predikata.","B":"'Mogli pomoći' izostavlja niječni pomoćni glagol 'nisu'.","D":"'Si' je povratna zamjenica (neizravni objekt), ne dio predikata."},
  "2014_jesen_A__65": {"B":"Zavisna rečenica ne dopunjuje glagol kao objekt nego određuje imenicu 'svijet'.","C":"Nije predikatna jer ne preuzima službu imenskoga dijela predikata.","D":"Nije priložna jer ne izriče okolnost radnje nego pobliže označuje imenicu."},
  "2014_jesen_A__66": {"A":"Dva je premalo: rečenica sadrži više od dvaju različitih leksema.","C":"Četiri ne odgovara broju leksema prema službenom rješenju (tri).","D":"Pet je previše leksema za ovu rečenicu."},
  "2014_jesen_A__67": {"B":"Toponimi nisu u odnosu nadređenosti/podređenosti pa nije hiperonimni.","C":"Nisu jednaki po obliku, a različiti po značenju pa nije homonimni.","D":"Ne znače isto pa nije sinonimni; pridjevi su suprotni (nova/stara)."},
  "2014_jesen_A__68": {"A":"'Barjak' je i danas u uporabi, nije historizam.","B":"'Cjelov' je arhaizam (poljubac), zamijenjen novijom riječi, a ne historizam.","D":"'Lipost' je arhaičan oblik riječi ljepota, a ne naziv za predmet iz prošlosti."},
  "2014_jesen_A__69": {"B":"Frazem ne znači žaljenje za propuštenim nego kajanje za grijehe.","C":"Ne znači govoriti uzalud.","D":"Ne znači brzo pobjeći."},
  "2014_jesen_A__70": {"B":"Riječ nema dviju osnova pa nije složeno-sufiksalna tvorba.","C":"Uz prefiks pod- dodan je i sufiks -je, pa nije samo prefiksalna tvorba.","D":"Uz sufiks -je prisutan je i prefiks pod-, pa nije samo sufiksalna tvorba."},
  "2014_jesen_A__71": {"B":"Gramatička bi odrednica donosila podatke o rodu/promjeni, a ovdje je riječ o podrijetlu.","C":"Normativna odrednica upućuje na pravilnost uporabe, što ovdje nije slučaj.","D":"Stilistička odrednica označuje stilsku obojenost, a ne podrijetlo riječi."},
  "2014_jesen_A__72": {"A":"'Disertacija...' (Pavao Ritter Vitezović) ne donosi reformu Gajeve grafije.","B":"'Duh domovine...' je književno djelo, ne pravopisna reforma.","C":"'Ilirizam i kroatizam' nije djelo s prijedlogom reforme grafije."},

  // 2014_jesen_B
  "2014_jesen_B__1": {"A":"Stih govori o vječnoj nezasitnosti srca, a ne o kratkoći života.","B":"Stih opisuje gladnu želju koja grije prsa, a ne prolaznost ljudskoga vijeka.","D":"Stih iskazuje vjerovanje u zemaljske slasti koje neće u grob, a ne spoznaju o kratkoći života."},
  "2014_jesen_B__2": {"A":"Jastreb je nositelj radnje (on bije), a ne ono što se bije, pa nije referent zamjenice 'ga'.","B":"Hljeb se u strofi prezire, a zamjenica 'ga' upućuje na ono što jastreb napada, tj. na srce.","D":"Život se u toj strofi uopće ne spominje kao objekt jastrebova napada."},
  "2014_jesen_B__3": {"A":"Provalija nije značenje arhaizma 'raka' nasuprot kolijevci.","B":"Postelja ne odgovara opreci rođenje-smrt koju traži stih.","C":"Bolest nije značenje riječi 'raka'; tražen je pojam suprotan kolijevci, tj. grob."},
  "2014_jesen_B__4": {"A":"Pjesma ne veliča domovinu nego razmišlja o ljudskoj naravi i prolaznosti.","B":"Tema nije ljubav prema dragoj, nego nezasitnost srca i smrt.","D":"Nema opisa krajolika; riječ je o misaonom, filozofskom promišljanju."},
  "2014_jesen_B__5": {"B":"Polisindeton bi tražio gomilanje veznika, čega u strofi nema.","C":"Anadiploza je ponavljanje kraja stiha na početku idućega, što ovdje izostaje.","D":"Paradoks je prividno proturječan iskaz, a strofa je oblikovana kao pitanje."},
  "2014_jesen_B__6": {"A":"Preobrazba se spominje ranije, ali joj se lirski subjekt ne prepušta; 'joj' upućuje na glazbu.","B":"Mjesečina je okolnost zbivanja, a ne ono čemu se subjekt prepušta.","D":"Tajna je opći motiv, no izravni antecedent zamjenice je glazba ('Nju... joj')."},
  "2014_jesen_B__7": {"A":"U prvoj strofi nema imperativa ni obraćanja, nego opisa noćne tišine.","B":"Druga strofa opisuje preobrazbu stvari, bez izravna obraćanja čitatelju.","C":"U trećoj strofi nema imperativnih oblika upućenih čitatelju."},
  "2014_jesen_B__8": {"A":"Motiv grma nije grafostilski istaknut, nego je dio uobičajena teksta.","B":"Motiv kamena nije posebno grafički obilježen.","C":"Motiv srca nije grafostilski naglašen kao 'Svijet'."},
  "2014_jesen_B__9": {"A":"Riječ je o dojmu tajanstvenosti, a ne o slušnom podražaju.","B":"Mjesečina je vizualni (svjetlosni) podražaj, a ne zvuk.","C":"Stih iznosi preobrazbu predmeta, bez slušnoga doživljaja."},
  "2014_jesen_B__10": {"A":"Monostih (jednostih) se u pjesmi ne pojavljuje.","B":"Distih se pojavljuje samo jednom, na kraju.","C":"Trostih se ne pojavljuje dva puta u ovoj strukturi."},
  "2014_jesen_B__11": {"A":"Vojska je mjesto na koje strijele padaju, a ne ono na što se odnosi podcrtana riječ.","C":"Skupština se saziva tek desetoga dana i nije povezana s podcrtanom riječju.","D":"Narod se odnosi na ahejsku zajednicu koju Ahilej saziva, a ne na strijele."},
  "2014_jesen_B__12": {"A":"Apolon je bog koji šalje pošast, a ne onaj tko savjetuje pomoć Danajcima.","C":"Kalhant je vrač koji proriče, no misao Ahileju usađuje Hera.","D":"Testor se spominje samo kao Kalhantov otac, a ne kao savjetnik."},
  "2014_jesen_B__13": {"B":"Poklanjanje broda ne spominje se kao Kalhantov način vodstva.","C":"Kalhant ne pomaže molitvom, nego proricanjem.","D":"Tumačenje snova nije navedeno kao Kalhantova vještina; vodi ih vračanjem."},
  "2014_jesen_B__14": {"A":"Anadiploza bi tražila ponavljanje kraja prvoga stiha na početku drugoga, čega nema.","C":"Epifora je ponavljanje na kraju stihova, a ovdje se ponavlja početak ('On je').","D":"Simploka spaja anaforu i epiforu, no ovdje je samo početak stihova istovjetan."},
  "2014_jesen_B__15": {"A":"Atena je grad u Grčkoj, a ne drugo ime Ilija.","B":"Kartaga je punski grad, nepovezan s Ilijem.","C":"Mikena je Agamemnonovo sjedište, a ne Troja."},
  "2014_jesen_B__16": {"A":"Rečenica iskazuje da majka šalje traženi novac, ali ne govori o ekonomskim prilikama obitelji.","C":"Rečenica govori o nepotrebnosti opširna objašnjenja, ne o financijama.","D":"Rečenica izražava majčinu brigu za sinovu patnju, a ne novčano stanje obitelji."},
  "2014_jesen_B__17": {"B":"Školovanje se kao izvor majčine tjeskobe u tekstu ne navodi.","C":"Putovanje se ne spominje kao ono što bi majku umirilo.","D":"Novac majka i sama šalje; nje tjeskobe oslobodila bi sinova riječ, a ne novac."},
  "2014_jesen_B__18": {"A":"Putovanje je doslovno značenje, no ovdje je 'put' preneseno za sinove planove.","B":"Povratak se u rečenici ne spominje kao smisao podcrtane riječi.","D":"Pisanje nije ono na što 'put' upućuje; riječ je o sinovim namjerama/planovima."},
  "2014_jesen_B__19": {"A":"Barun de Nucingen je sporedni lik (bankar), a ne sin kojemu majka piše.","C":"Grof de Restaud je muž Goriotove kćeri, a ne adresat pisma.","D":"Jacques Collin (Vautrin) je odbjegli robijaš, a ne majčin sin."},
  "2014_jesen_B__20": {"B":"Plaćanje školovanja nije razlog za novac; Rastignac teži društvenu usponu.","C":"Posuđivanje prijatelju nije svrha traženog novca.","D":"Riješenje ucjene nije motiv; novac je za probijanje u visoko društvo."},
  "2014_jesen_B__21": {"B":"Nesporazuma s ocem nema; ulomak prikazuje odlazak iz Mecenina doma.","C":"Dom je već poznat; tema nije upoznavanje doma nego rastanak i odlazak.","D":"Nije riječ o bijegu rođaka, nego o Ivičinu i Rožčevu odlasku."},
  "2014_jesen_B__22": {"A":"Gradsko podrijetlo ne odgovara liku sluge koji prezire vlastiti rod.","B":"Plemenitaško podrijetlo proturječi opisu Rošca kao sluge i kumordinara.","C":"Radničko podrijetlo nije sugerirano; Rožac je niskoga, seoskoga roda."},
  "2014_jesen_B__23": {"A":"Ivica ne dvoji o vrijednosti kovčega, nego o ponovnom susretu.","C":"Laurino dobročinstvo nije predmet sumnje, nego mogućnost ponovna viđenja.","D":"Sumnja se ne tiče Laurine ljubavi, nego toga hoće li se opet vidjeti ('Do vidova')."},
  "2014_jesen_B__24": {"A":"Raskoš doma nije razlog rumenila, nego grešna misao izazvana Laurinom ljepotom.","B":"Ivičino podrijetlo ne uzrokuje Rožčevo crvenjenje.","D":"Tuđe riječi nisu uzrok; starac crveni zbog grešne misli potaknute ljepotom."},
  "2014_jesen_B__25": {"B":"'Društvinska soba' nije pleonazam, nego uobičajena odredbena sintagma.","C":"'Grešna misao' ne sadrži suvišno ponavljanje značenja.","D":"'Čudni dom' nije pleonastičan spoj jer pridjev donosi novu obavijest."},
  "2014_jesen_B__26": {"A":"Tekst ne poručuje da o zlu treba šutjeti, nego upravo svjedočiti.","C":"Tekst ne tvrdi da je borba protiv zla uzaludna, nego je vrijedna.","D":"Pouka je suprotna: u čovjeku je više vrijednoga divljenja nego zla."},
  "2014_jesen_B__27": {"A":"Nasilan nije značenje pridjeva 'kužni'; on opisuje zaraženost.","B":"Nepravedan ne odgovara značenju 'kužni'.","C":"Pritajen nije značenje; 'kužni' znači zaražen kugom."},
  "2014_jesen_B__28": {"A":"Primjer govori o svjedočenju za bolesnike, a ne izravno o samoj kugi.","B":"Primjer govori o borbi protiv terora, ne o fizičkim svojstvima kuge.","C":"Primjer govori o ljudima koji nastoje biti liječnici, a ne o kugi izravno."},
  "2014_jesen_B__29": {"B":"Eufemizma (ublažavanja) ovdje nema; kuga je prikazana kao živo biće.","C":"Gradacije (stupnjevanja) u primjeru nema.","D":"Hiperbole (pretjerivanja) nema; riječ je o oživljavanju kuge."},
  "2014_jesen_B__30": {"B":"Rieux nije novinar, nego liječnik koji vodi kroniku.","C":"Rieux nije svećenik (to je lik Paneloux).","D":"Rieux nije vojnik, nego liječnik."},
  "2014_jesen_B__31": {"B":"Razlog odlaska nije izbjegavanje svađe sa Stafilom.","C":"Euklion ne ide dokazivati zdravlje, nego prikriti svoje bogatstvo.","D":"Druženje s ljudima nije motiv; ide da ne pobudi sumnju o skrivenu zlatu."},
  "2014_jesen_B__32": {"A":"Srebrnjaci se dijele na trgu, no podcrtano upozorenje odnosi se na sreću.","B":"Siromasi nisu predmet ovoga upozorenja.","C":"Susjedi se spominju drugdje, ali ovdje Stafila ponavlja zabranu o sreći."},
  "2014_jesen_B__33": {"A":"'Čak ako sreća dođe' je zavisna rečenica s veznikom, a ne bezveznički niz.","C":"'Žalost cijepa srce mi' je jedna predikatna cjelina, bez nabrajanja bez veznika.","D":"'da zlata imam skrivena u kući' je zavisna rečenica, ne asindetsko nabrajanje."},
  "2014_jesen_B__34": {"B":"Stafila nije Euklionova supruga, nego sluškinja kojoj zapovijeda.","C":"Stafila mu nije sestra.","D":"Stafila mu nije kći; Euklionova je kći drugi lik."},
  "2014_jesen_B__35": {"A":"Hanibal Lucić je petrarkist, nije preradio Plautova Škrca.","B":"Ivan Gundulić je barokni pjesnik, nije autor preradbe Škrca.","C":"Junije Palmotić nije preradio Plautovu komediju Škrtac."},
  "2014_jesen_B__36": {"B":"Petrarca opjevava Lauru, a ne Beatrice.","C":"Boccaccio je autor Dekamerona, ne ljubavnoga pjevanja o Beatrice.","D":"Ariosto (Bijesni Orlando) ne pjeva o Beatrice Portinari."},
  "2014_jesen_B__37": {"A":"Cesarić nije slavonski pjesnik svakodnevice u traženom smislu.","C":"Pupačić nije pjesnik slobodna stiha o rodnoj Slavoniji (vezan je uz more).","D":"Ujević nije slavonski pjesnik jednostavne svakodnevice opisana profila."},
  "2014_jesen_B__38": {"A":"A. B. Šimić pripada ekspresionizmu, ne realizmu.","B":"Matoš je pjesnik moderne, ne realizma.","C":"Mažuranić je romantičar, a opis se odnosi na realističkoga pjesnika."},
  "2014_jesen_B__39": {"B":"Anadiploze (ponavljanja kraja stiha na početku idućega) ovdje nema.","C":"Anafore nema; ne ponavlja se ista riječ na početku stihova.","D":"Epifore nema; ne ponavlja se ista riječ na kraju stihova."},
  "2014_jesen_B__40": {"A":"Septuaginta je grčki, a ne latinski prijevod (i to Starog zavjeta).","B":"Stari zavjet je dio Biblije, a ne naziv latinskog prijevoda.","C":"Sveto pismo je opći naziv za Bibliju, ne za latinski prijevod."},
  "2014_jesen_B__41": {"A":"Bosančica nije pismo Bašćanske ploče.","C":"Latinica nije pismo Bašćanske ploče.","D":"Ćirilica nije pismo Bašćanske ploče; ona je glagoljska."},
  "2014_jesen_B__42": {"A":"'Blaž i hib' nije Lucićeva pjesma.","B":"'Draga je od zlata' nije Lucićevo djelo.","D":"'Prvi pogled' nije Lucićeva pjesma."},
  "2014_jesen_B__43": {"A":"Hanibal Lucić je renesansni pjesnik, nije autor 'Suza sina razmetnoga'.","C":"Marin Držić je komediograf, nije napisao tu baroknu poemu.","D":"Marko Marulić je autor Judite, a ne poeme u tri plača."},
  "2014_jesen_B__44": {"A":"Kačić Miošić je autor 'Razgovora ugodnog naroda slovinskoga', ne Satira.","B":"Filip Grabovac napisao je 'Cvit razgovora', a ne Satira.","D":"Katančić nije autor 'Satira iliti divjeg čovika'."},
  "2014_jesen_B__45": {"A":"Šenoa je realist, autor povjestica, a stihovi su impresionistička pejzažna lirika.","B":"Galović nije autor ovih stihova.","C":"Nazor nije autor ovih stihova."},
  "2014_jesen_B__46": {"B":"Raspored je netočan: Kovačić je realizam (B), a ne moderna (C).","C":"Raspored je netočan: Kovačić je realizam (B), a ne romantizam (A).","D":"Raspored je netočan: Matoš je moderna (C), a ne romantizam (A)."},
  "2014_jesen_B__47": {"B":"Raspored je netočan: Don Quijote je epika (B), a ne lirika (C).","C":"Raspored je netočan: Don Quijote je epika (B), a ne drama (A).","D":"Raspored je netočan: Patnje mladoga Werthera su epika (B), a ne lirika (C)."},
  "2014_jesen_B__48": {"A":"Ispravno je 'ljepljiv', a ne 'lijepljiv'.","C":"Ispravno je 'nesvijest', a ne 'nesvjest'.","D":"Ispravno je 'ocjenjivati', a ne 'ocijenjivati'."},
  "2014_jesen_B__49": {"B":"Nedostaje zarez iza mjesta ('U Osijeku, 23. travnja 2014.').","C":"Nakon dana mora stajati točka ('23. travnja'), a poželjan je i zarez iza mjesta.","D":"Nedostaje zarez iza mjesta i prijedlog/oblik nije ujednačen kao u točnom primjeru."},
  "2014_jesen_B__50": {"B":"'Predsjednik' kao funkcija piše se malim slovom.","C":"Pridjev 'hrvatskih' u nazivu društva piše se malim slovom.","D":"I 'predsjednik' i pridjev 'hrvatskih' pogrešno su napisani velikim slovom."},
  "2014_jesen_B__51": {"A":"Dva sloga premalo je za riječ 'prevrtljivost'.","B":"Tri sloga premalo je za 'prevrtljivost'.","C":"Četiri sloga ne odgovara službenom rješenju (pet)."},
  "2014_jesen_B__52": {"A":"Kratkouzlazni naglasak ne dolazi na jednosložnicu poput 'crv'.","C":"Dugouzlazni naglasak nije moguć na jednosložnici.","D":"Naglasak je kratak, a ne dug, jer je samoglasnik kratak."},
  "2014_jesen_B__53": {"B":"U 'lišće' provedena je jotacija, a ne palatalizacija.","C":"U 'miševi' nema palatalizacije (h/k/g ispred e/i nema).","D":"U 'opačine' nema palatalizacije kao u 'junački'."},
  "2014_jesen_B__54": {"A":"U 'Antarktika' u D/L se sibilarizacija ne provodi (vlastito ime/iznimka).","C":"U 'prašak' nepostojano a uklanja se pa nema osnove za sibilarizaciju u D/L.","D":"U 'mačka' se u D/L sibilarizacija ne provodi (čk ostaje)."},
  "2014_jesen_B__55": {"A":"U 'cvijeće' provedena je jotacija, ali ne i jednačenje po mjestu tvorbe.","B":"U 'drvlje' provedena je jotacija (l+j), bez jednačenja po mjestu tvorbe.","C":"U 'grablje' provedena je jotacija (bl+j), bez jednačenja po mjestu tvorbe."},
  "2014_jesen_B__56": {"A":"Spoj 'ni za što' uz niječni glagol nije u skladu sa standardnom normom.","B":"'bez nikoga' uz potvrdni glagol nije gramatički prihvatljivo.","D":"'Bio sam bez ničega' ne odgovara traženom standardnom obliku kao rečenica C."},
  "2014_jesen_B__57": {"A":"'Obzirom na to' je nestandardno; pravilno je 's obzirom na to'.","B":"'Obzirom da' je nepravilan uzročni veznik.","D":"'Budući su kasnili' je netočno; veznik glasi 'budući da'."},
  "2014_jesen_B__58": {"A":"'cvrkutov' je nestandardan posvojni oblik.","B":"Pravilno je 'kraljev', a ne 'kraljov'.","D":"Pravilno je 'stričev' (s palatalizacijom), a ne 'stricov'."},
  "2014_jesen_B__59": {"A":"Treba povratno-posvojna 'svojim', a ne 'našim' jer se odnosi na subjekt.","C":"Treba 'svoj kaput', a ne 'moj', jer je subjekt isti vršitelj.","D":"Treba 'svoje zadaće', a ne 'vaše', kad se odnosi na subjekt rečenice."},
  "2014_jesen_B__60": {"A":"Pravilno je 'donesen', a ne 'donešen'.","B":"Pravilno je 'potekao', oblik 'potečen' ne postoji.","D":"Oblik 'ugriješen' nije pravilan glagolski pridjev trpni."},
  "2014_jesen_B__61": {"A":"'budem' je prezent (svršeni), a ne imperfekt.","C":"'bih' je oblik kondicionala, a ne imperfekt.","D":"'bio' je glagolski pridjev radni, a ne imperfekt."},
  "2014_jesen_B__62": {"B":"'s daleka puta' odgovara na pitanje odakle, a ne kamo.","C":"'na poslovnom putu' odgovara na pitanje gdje, a ne kamo.","D":"'poljskim putem' odgovara na pitanje kuda, a ne kamo."},
  "2014_jesen_B__63": {"A":"Uz neživo 'naslonjač' standardno je 'koji', a ne 'kojega'.","B":"Uz neživo 'zadatak' standardno je 'koji', a ne 'kojega'.","C":"Uz neživo 'dopis' standardno je 'koji', a ne 'kojega'."},
  "2014_jesen_B__64": {"B":"'trčanje dvorištem' je nesročna (padežna) sveza, a ne sročna sintagma.","C":"'sviranje flaute' je nesročna sveza (genitivna dopuna).","D":"'malo kruha' je nesročna sveza (priložna riječ + genitiv)."},
  "2014_jesen_B__65": {"A":"'sve što je imao' je odnosna (atributna) rečenica, a ne objektna.","B":"'koji je pošten' je atributna (odnosna) rečenica uz imenicu 'čovjeka'.","D":"'kada dođeš' je priložna (vremenska) rečenica, a ne objektna."},
  "2014_jesen_B__66": {"A":"Posljedične rečenice uvodi 'te/da', a ovdje veznik 'jer' izriče uzrok.","B":"Pogodbene uvodi 'ako/kad bi', a ne 'jer'.","C":"Namjerne uvodi 'da/kako bi', a 'jer' označava uzrok."},
  "2014_jesen_B__67": {"A":"'kruha' nije priložna oznaka; to je logički subjekt uz 'nema'.","B":"'kruha' nije objekt, nego subjekt u genitivu uz bezlični predikat.","C":"Predikat je 'nema', a 'kruha' je subjekt."},
  "2014_jesen_B__68": {"A":"'ispred' označava položaj naprijed, nije antonim priloga 'gore'.","B":"'pored' znači uz nešto, nije suprotnost 'gore'.","C":"'blizu' označava udaljenost, a ne smjer suprotan 'gore'."},
  "2014_jesen_B__69": {"A":"'dobro — zlo' su antonimi (suprotno značenje), a ne sinonimi.","C":"'mutno — bistro' su antonimi, a ne sinonimi.","D":"'jasna — Jasna' su homonimi (isti oblik, različito značenje), ne sinonimi."},
  "2014_jesen_B__70": {"A":"'grč. onomastikós' je etimološka, a ne gramatička odrednica.","C":"'lingv.' je odrednica struke/područja, a ne gramatička.","D":"'ukupnost vlastitih imena' je definicija značenja, a ne gramatička odrednica."},
  "2014_jesen_B__71": {"A":"Suočavanje s činjenicama nije značenje frazema 'stegnuti remen'.","C":"Oporavak nije značenje toga frazema.","D":"Snalaženje nije značenje; frazem znači skromnije, štedljivije živjeti."},
  "2014_jesen_B__72": {"A":"Hrvojev misal je rukopisni kodeks, a ne tiskana knjiga.","B":"Lekcionar Bernardina Splićanina (1495.) tiskan je kasnije od prve hrvatske tiskane knjige.","D":"Misal kneza Novaka je rukopis, a ne tiskovina."},

  // 2014_ljeto_A
  "2014_ljeto_A__1": {"A":"Stih opisuje miris kose u 3. licu (njezina kosa), pa nije izravno obraćanje ženi.","B":"Stih u 3. licu opisuje njezine ruke, dakle govori o ženi, a ne njoj.","C":"Stih u 3. licu govori o ponoru i plamenu u njezinu oku, pa nema izravnoga obraćanja."},
  "2014_ljeto_A__2": {"A":"Misao se samo rosi na lirskoga subjekta ('misao me rosi'), ali iskre i zanosi struje u zjenama, a ne u mislima.","C":"Prah se spominje uz tijelo na kraju soneta ('u prahu ležim'), a ne kao mjesto gdje struje iskre.","D":"Miris ljepote struji u kosi, no iskre i zanosi struje u zjenama (očima)."},
  "2014_ljeto_A__3": {"A":"Slatka varka veže se uz njezine usne, a ne uz sjećanje na pokret.","B":"Ponor i plamen odnose se na oko, a ne na sjećanje na pokret.","C":"Hladna mana uspoređuje se s misli koja rosi ('ko hladna mana misao me rosi'), a ne sa sjećanjem na pokret."},
  "2014_ljeto_A__4": {"A":"Anadiploza bi tražila ponavljanje završne riječi jednoga stiha na početku sljedećega, čega ovdje nema.","C":"Epifora je ponavljanje na kraju stihova, a ovdje se 'njene su' ponavlja na početku.","D":"Simploka traži istodobno ponavljanje i na početku i na kraju, no ovdje se podudara samo početak."},
  "2014_ljeto_A__5": {"A":"Barbarizmi su nepotrebne strane, tuđe riječi, a Adam, Eva i mana biblijski su pojmovi.","C":"Klišejizmi su otrcane, izlizane fraze, što ovi biblijski pojmovi nisu.","D":"Žargonizmi pripadaju govoru posebne društvene skupine, a ne biblijskoj tradiciji."},
  "2014_ljeto_A__6": {"B":"Antìnojeva psovka uslijedila je nakon plača, pa nije njegov uzrok; rasplakao ih je pogled na luk.","C":"Natjecanje prosaca tek slijedi i nije uzrok plača svinjara i govedara.","D":"Kraljičina tuga spominje se u Antìnojevu govoru, ali svinjara i govedara rasplakao je pogled na gospodarev luk."},
  "2014_ljeto_A__7": {"A":"Antìnoj prosce, naprotiv, kori što diraju kraljičino srce, dakle ne potiče suosjećanje prema njoj.","B":"Stih govori o podjarivanju protiv Odiseja, a ne o poticanju na sjećanje na njega.","C":"Poticanje na natjecanje izriče se drugdje; ovaj stih govori o huškanju protiv Odiseja."},
  "2014_ljeto_A__8": {"A":"Stih ima uobičajen red riječi (subjekt – predikat – objekt), pa nema inverzije.","B":"Riječ je o uzvičnoj rečenici (retoričko pitanje), a ne o obrnutu redu sastavnica.","D":"Rečenica je u uobičajenu redoslijedu i prekratka da bi pokazala inverziju."},
  "2014_ljeto_A__9": {"A":"U natjecanju s lukom ne strijelja se kroz bodeže, nego kroz niz sjekira.","B":"Cilj nisu koplja, nego poredane metalne sjekire kroz čije se uške gađa.","D":"Strijele su sredstvo gađanja, a 'gvožđa' su meta – sjekire."},
  "2014_ljeto_A__10": {"A":"Klitemnestra je Agamemnonova žena iz drugoga mita, a ne Odisejeva supruga.","C":"Didona je kraljica iz Eneide, a ne lik Odiseje.","D":"Helena je junakinja Trojanskoga rata, ali nije ona koja čeka Odiseja."},
  "2014_ljeto_A__11": {"B":"To što je austrougarski vojnik samo je njegova okolnost, a pamet mu je stala zbog Tenine ljepote.","C":"Ratovanje u Bosni pozadina je radnje, ali nije razlog njegove zanesenosti.","D":"Dolazak u Posavinu samo je situacija; očarala ga je Tena kad ju je ugledao."},
  "2014_ljeto_A__12": {"A":"Virđinija u ustima dio je njegova kicoškog izgleda, ali Tenu je osvojio prvom riječju.","B":"Kicoška kapica dio je opisa njegova izgleda, no osvojio ju je prvom riječju.","C":"Prvim pogledom ona je osvojila njega; njega je nju osvojio prvom riječju."},
  "2014_ljeto_A__13": {"A":"Crvena vojnička knjiga ne označava poziv u vojsku, nego njegov čin (status).","B":"Nije riječ o ratnoj ozljedi, nego o ispravi koja potvrđuje vojni čin.","C":"Nije riječ o knjizi o ratu, nego o vojnoj ispravi koja označava čin."},
  "2014_ljeto_A__14": {"A":"Ljubavnik (vodnik Beranek) zaljubljuje se u Tenu, a Jerko je njezin otac u čijoj se kući vojnik smjestio.","C":"Jerko nije slučajni poznanik, nego Tenin otac u čijoj je kući vojnik smješten.","D":"U ulomku se ne spominje zaruka; Jerko je Tenin otac."},
  "2014_ljeto_A__15": {"A":"Hrvatsko zagorje nije prostor Tene; radnja je smještena u Posavinu, u Slavoniju.","C":"Istra nije vezana uz Kozarčevu Tenu, koja je slavonska pripovijest.","D":"Lika nije prostor radnje; likovi i zbivanja vezani su uz Slavoniju."},
  "2014_ljeto_A__16": {"A":"Šesnaestogodišnja Emma pitomica je samostana, a plemkinjina podrijetla je starija djevojka.","B":"Odbjegla učenica nije plemkinja; potomak stare plemićke obitelji je starija djevojka.","D":"Časne sestre vode samostan, ali plemićkoga je podrijetla starija djevojka koja krpa rublje."},
  "2014_ljeto_A__17": {"B":"S časnim sestrama čavrljala je starija djevojka; pitomice su bježale k njoj da slušaju priče.","C":"U ulomku se ne spominje udvaranje mladićima kao razlog bijega iz učionice.","D":"Vožnja u kočijama nije razlog njihova bijega; htjele su slušati priče starije djevojke."},
  "2014_ljeto_A__18": {"A":"Alegorija je prošireno preneseno značenje, a u opisu se nižu poredbe ('poput', 'kao').","B":"Metafora je preneseno značenje bez poredbenoga veznika, no ovdje su izričite usporedbe.","C":"Personifikacija pridaje neživomu ljudske osobine, a ovdje se gomilaju usporedbe."},
  "2014_ljeto_A__19": {"A":"Radnja se zbiva početkom 19. st., pa je 'prošli vijek' 18., a ne 16. st.","B":"Prošlo stoljeće u odnosu na vrijeme radnje (poč. 19. st.) jest 18., a ne 17. st.","D":"Devetnaesto stoljeće vrijeme je radnje romana, a 'prošli vijek' odnosi se na 18. st."},
  "2014_ljeto_A__20": {"B":"Bovarizam nije radost življenja, nego upravo nezadovoljstvo stvarnošću i bijeg u maštu.","C":"Pretjerano divljenje sebi je narcizam, a ne bovarizam.","D":"Unaprijed izgubljena borba opisuje donkihotizam, a ne bovarizam."},
  "2014_ljeto_A__21": {"A":"Pitanje o 'kerefekima' izriče nezadovoljstvo poslom i Lojzom, a ne prezir prema milostivi.","B":"Rečenica o spomeniku iznosi Magdin stav o poslu, a ne prezir prema milostivi.","D":"Tvrdnja o Magdinoj sumnjičavosti pripovjedačev je komentar, a ne izraz prezira prema milostivi."},
  "2014_ljeto_A__22": {"B":"Magdin muž nije onaj koji misli da je Lojzek lijen; ta misao izlazi iz Magdine perspektive.","C":"Milostiva je predmet Magdine ljubomore, a ne ona koja Lojzeka smatra lijenim.","D":"Pastir je samo motiv spomenika, a Lojzeka lijenim smatra Magda."},
  "2014_ljeto_A__23": {"A":"Cmizdriti znači plačljivo se žaliti, a 'udarati nemilo' znači bezobzirno vrijeđati.","B":"Namazati (njušku) odnosi se na šminkanje, a 'udarati nemilo' znači vrijeđati.","C":"Sumnjičiti znači sumnjati u koga, dok 'udarati nemilo' znači nemilosrdno vrijeđati."},
  "2014_ljeto_A__24": {"A":"Anafora je ponavljanje na početku uzastopnih cjelina, čega ovdje nema.","C":"Polisindeton je gomilanje veznika, a u primjeru se atributi nižu iza imenice.","D":"Retoričko pitanje upitan je iskaz bez odgovora, a ovo je usklik s obrnutim redom riječi."},
  "2014_ljeto_A__25": {"A":"Albert Knez nije grobar, nego klesar koji izrađuje nadgrobne spomenike.","C":"On nije slikar, nego klesar (kipar) nadgrobnih spomenika.","D":"Albert Knez nije svećenik, nego klesar."},
  "2014_ljeto_A__26": {"B":"Hamlet nije sam priznavao namjere; Ofelija je ocu pokazala pismo i ispričala o udvaranjima.","C":"Polonije nije saznao prisluškivanjem; kći mu je sama pokazala pismo i prepričala udvaranja.","D":"Polonije nije krao pisma; Ofelija mu ih je u poslušnosti sama predala."},
  "2014_ljeto_A__27": {"A":"Stih govori o učinku Polonijeva savjeta, a ne o Ofelijinu glumljenju ludila.","B":"Poslušnost se spominje drugdje; ovaj stih iskazuje da je Ofelija odbila Hamleta po savjetu.","C":"Ofelija nije zavela Hamleta; po savjetu se zatvorila pred njim i odbila ga."},
  "2014_ljeto_A__28": {"A":"Antiteza traži suprotstavljanje pojmova, a ovdje se stanja stupnjevito pojačavaju.","B":"Eufemizam je ublažavanje, no ovdje se nepovoljna stanja pojačavaju do ludila.","D":"Hiperbola je pretjerivanje, a riječ je o postupnom stupnjevanju (gradaciji)."},
  "2014_ljeto_A__29": {"A":"Gertruda je 'vaša kraljica', a 'moje drago veličanstvo' odnosi se na kralja Klaudija.","B":"Hamlet nije veličanstvo; izraz se odnosi na vladara, kralja Klaudija.","D":"Ofelija je Polonijeva kći, a ne 'veličanstvo'; izraz se odnosi na kralja."},
  "2014_ljeto_A__30": {"B":"Mišolovku uprizoruje Hamlet da iskuša kralja, a Polonije planira podmetnuti Ofeliju.","C":"Polonije ne izaziva Hamleta na dvoboj, nego sprema susret s Ofelijom da ga motri.","D":"Slanje Hamleta na put kraljev je naum (u Englesku), a Polonije planira susret s Ofelijom."},
  "2014_ljeto_A__31": {"A":"Gramzivost je pohlepa za imetkom, a 'himbeno' upućuje na lažnost, prijetvornost.","B":"Oholost je umišljenost, dok 'himbeno' znači prijevarnost, lažnost.","C":"Plahost znači bojažljivost, a 'himbeno' označava prijetvornost."},
  "2014_ljeto_A__32": {"A":"Ruža se u tekstu veže uz usne ('crljenim ustime ruža'), a grudi Jeljenka uspoređuje sa snijegom i mlijekom.","B":"Vjetar se ne navodi kao usporedba za grudi; one su bijele poput snijega i mlijeka.","D":"Sunce nije usporedba za grudi; Jeljenka ih opisuje kao bjelje od snijega i mlijeka."},
  "2014_ljeto_A__33": {"A":"Ovi stihovi opisuju satirov polazak za vilama, a ne poziv na zadovoljstvo postojećim.","B":"Ovi stihovi prijekor su Divjaku zbog nevjernosti, a ne poticaj da bude sretan s onim što ima.","C":"Ovi stihovi pitaju zašto Divjak slijedi vile i ostavlja Jeljenku, a ne pozivaju ga na zadovoljstvo."},
  "2014_ljeto_A__34": {"B":"'Pram iz groba' odnosi se na tuđu kosu (vlasulju) za uljepšavanje, a ne na krajolik.","C":"'Svijetli ures' odnosi se na Jeljenkinu prirodnu ljepotu, a ne na krajolik.","D":"'Stvar najdraža' apstraktan je izraz vrednovanja, a ne metaforički prikaz krajolika."},
  "2014_ljeto_A__35": {"A":"Asindeton je nizanje bez veznika, a ovdje se veznik 'i' višestruko ponavlja.","B":"Elipsa je izostavljanje dijela rečenice, čega ovdje nema.","D":"Retoričko pitanje upitan je iskaz, a ovi su stihovi izjavni s gomilanjem veznika 'i'."},
  "2014_ljeto_A__36": {"A":"Bijesni Orlando (Ariosto) viteški je ep, a ne alegorijska vizija zagrobnoga života.","C":"Dekameron (Boccaccio) zbirka je novela, a ne vizija zagrobnoga života temeljena na poetici brojeva.","D":"Kanconijer (Petrarca) zbirka je ljubavnih pjesama, a ne djelo o zagrobnome životu."},
  "2014_ljeto_A__37": {"A":"Ante Kovačić autor je romana U registraturi, a ne djela o propasti senjske patricijske obitelji.","B":"Eugen Kumičić piše o Istri (npr. Začuđeni svatovi), a hrvatskim Balzacom naziva se Vjenceslav Novak.","C":"Josip Kozarac slavonski je pisac (Tena, Mrtvi kapitali), a o senjskoj obitelji piše Novak."},
  "2014_ljeto_A__38": {"A":"Rastignac i Raskoljnikov dolaze iz različitih romana i ne dijele sva navedena obilježja (umjetnička kriza, povratak).","B":"Kičmanović i Žorž likovi su iz drugih djela i ne povezuje ih umjetnička kriza ni povratak.","D":"Ante i Juraj Stipančić likovi su Posljednjih Stipančića, ali ne dijele umjetničku krizu i povratak kao Glembaj i Latinovicz."},
  "2014_ljeto_A__39": {"A":"Knez Branimir poznat je po Branimirovu natpisu i papinu priznanju, a nasilna smrt opisana je Zvonimiru.","B":"Knez Domagoj poznat je po pomorskim borbama, a Ljetopis popa Dukljanina opisuje smrt kralja Zvonimira.","C":"Kralj Tomislav prvi je hrvatski kralj, ali nasilna smrt u Ljetopisu pripisuje se Zvonimiru."},
  "2014_ljeto_A__40": {"A":"Dvostruko rimovani dvanaesterac stih je hrvatske renesanse (npr. Marulić), a ne Vergilijeve Eneide.","B":"Epski deseterac stih je usmenoga pjesništva, a ne klasičnoga latinskog epa.","C":"Aleksandrinac je dvanaesterac francuske poezije, a Eneida je pisana heksametrom."},
  "2014_ljeto_A__41": {"A":"Prikazanje je srednjovjekovni vjerski igrokaz, a 'novela' ovdje znači šalu.","B":"Susret nije značenje riječi 'novela'; ona ovdje znači šalu, zabavan prizor.","D":"Ples nije značenje 'novele'; izraz označava šalu, komediju."},
  "2014_ljeto_A__42": {"B":"Primjer s 'Čemu... / Čemu...' ima samo anaforu (jednak početak), bez ponavljanja na kraju.","C":"Primjer 'Donesi, donesi... odluku / odluku' pokazuje geminaciju i anadiplozu, a ne simploku.","D":"Primjer s ponovljenim 'urliče' na kraju pokazuje epiforu, ali ne i istovjetan početak, pa nije simploka."},
  "2014_ljeto_A__43": {"A":"Dundo Maroje temelji se na komediji zapleta s renesansnim Rimom, a riječi o 'ukradenoj iz starog libra' odnose se na Skupa.","B":"Novela od Stanca kratka je karnevalska šala, a ne komedija za koju Držić kaže da je 'ukradena iz starog libra'.","D":"Tirena je pastirska igra, a citat o posuđivanju iz staroga libra odnosi se na Skupa (po Plautu)."},
  "2014_ljeto_A__44": {"A":"Antika je razdoblje grčko-rimske književnosti, a parnasovci djeluju u 19. stoljeću.","B":"Klasicizam je 17.-18. st., a parnasovci pripadaju kasnijemu 19. st. (moderni).","C":"Realizam je proza društvene stvarnosti, a parnasovci su pjesnička struja unutar moderne."},
  "2014_ljeto_A__45": {"A":"Antun Branko Šimić uređivao je časopise Vijavica? Ne; Šimić je vodio Vijavicu? Pogrešno – Vijavicu je uređivao Krleža, a Šimić npr. Juriš i Književnik.","B":"Antun Gustav Matoš povezuje se s časopisom Hrvatska smotra i Mladost, a ne s Vijavicom.","C":"August Šenoa uređivao je Vienac, a ne Vijavicu."},
  "2014_ljeto_A__46": {"B":"Raspored 1B,2A,3C,4B,5C pogrešno pripisuje 2. stih Cesariću i 5. Vidriću, dok je 2. Vidrićev (mandolina), a 5. Cesarićev (petrolejska lampa).","C":"Raspored 1A,2C,3B,4B,5A pogrešno pripisuje 1. stih ('Kolo od sreće') Cesariću i 3. Gunduliću, dok je 1. Gundulićev, a 3. Vidrićev.","D":"Raspored 1B,2C,3A,4B,5A pogrešno pripisuje 3. stih ('Ko zna') Cesariću, a on je Vidrićev."},
  "2014_ljeto_A__47": {"B":"Raspored 1B,2B,3C,4A,5C pogrešno pripisuje Blaža Štakora U registraturi, dok je on lik Posljednjih Stipančića.","C":"Raspored 1A,2B,3A,4C,5C pogrešno smješta Tintora u Posljednje Stipančiće i Medonića u Zlatarovo zlato, a Tintor je iz Zlatarova zlata, Medonić iz Stipančića.","D":"Raspored 1A,2A,3C,4B,5C pogrešno pripisuje Kičmanovića Stipančićima i Medonića U registraturi, dok je Kičmanović iz U registraturi, a Medonić iz Stipančića."},
  "2014_ljeto_A__48": {"B":"'Podijalekt' nije pravilno; treba 'poddijalekt' (ili 'subdijalekt'), jer se osnovna riječ piše s dva d.","C":"'Podkradati' nije pravilno; po jednačenju po zvučnosti piše se 'potkradati'.","D":"'Podpisati' nije pravilno; po jednačenju po zvučnosti piše se 'potpisati'."},
  "2014_ljeto_A__49": {"A":"Drugi je oblik pogrešan: nije 'dogorjevati', nego 'dogorijevati'.","B":"Drugi je oblik pogrešan: nije 'namiještati', nego 'namještati'.","D":"Oba su oblika pogrešna: pravilno je 'zapovjediti' i 'zapovijedati'."},
  "2014_ljeto_A__50": {"A":"Pogrešno je sve malim slovom; prva sastavnica imena županije piše se velikim ('Koprivničko-').","B":"Pogrešno je drugu sastavnicu i 'Županiju' pisati velikim slovom; treba 'križevačku' i 'županiju' malim.","D":"Pogrešno je 'Županiju' pisati velikim i prvu sastavnicu malim; treba 'Koprivničko-križevačku županiju'."},
  "2014_ljeto_A__51": {"B":"Suvišan je zarez ispred 'da bi' jer namjerna surečenica ovdje ne traži odvajanje.","C":"Suvišan je zarez iza priložne oznake mjesta na početku rečenice ('U napuštenoj kući').","D":"Suvišan je zarez iza priložne oznake uzroka na početku rečenice ('Zbog dolaska...')."},
  "2014_ljeto_A__52": {"B":"U 'pomirba' nije provedeno jednačenje po mjestu tvorbe, nego je riječ o tvorbi bez te promjene.","C":"U 'cvijeće' provedena je jotacija (t+j), a ne jednačenje po mjestu tvorbe.","D":"U 'vožnja' provedena je jotacija (z+j → ž), a ne jednačenje po mjestu tvorbe."},
  "2014_ljeto_A__53": {"A":"'Jaučem' (od jaukati) pokazuje jotaciju, a ne palatalizaciju.","B":"'Plačem' jest palatalizacija (plakati), ali traženi odgovor je samo jedan; ovdje je k→č ispred e isto palatalizacija – no službeno se kao primjer uzima 'skačem'. (Distraktor prema ključu.)","D":"'Vučem' (od vući) rezultat je jotacije/glasovne promjene, a ne palatalizacije ispred e."},
  "2014_ljeto_A__54": {"A":"Kratkosilazni naglasak ('razumijȅvati') nije pravilan za ovu riječ.","C":"Dugouzlazni naglasak ('razumijévati') nije pravilan za ovu riječ.","D":"Dugosilazni naglasak ('razumijêvati') nije pravilan za ovu riječ."},
  "2014_ljeto_A__55": {"A":"'Mislilac' je nominativ, a vokativ glasi 'mislioče'.","B":"'Mislilače' nije pravilan vokativ; izostaje vokalizacija l→o, treba 'mislioče'.","C":"'Misliocu' je dativ jednine, a ne vokativ."},
  "2014_ljeto_A__56": {"A":"'Zaslugama' je imenica ženskoga roda, pa zamjenica nije atribut imenice muškoga roda.","C":"'Cvijeću' je imenica srednjega roda, a ne muškoga.","D":"'Odjeći' je imenica ženskoga roda, a ne muškoga."},
  "2014_ljeto_A__57": {"B":"Pravilan je oblik 'najbjednijemu' (D/L jd.), pa 'najbjednijem' u ovoj rečenici nije standardno.","C":"Superlativ od 'žestok' glasi 'najžešći', pa 'najžestokiju' nije pravilno.","D":"Superlativ od 'strog' glasi 'najstrožu', pa 'najstrožiju' nije pravilno."},
  "2014_ljeto_A__58": {"B":"'Slugu' je imenica muškoga roda, pa nije akuzativ ženskoga roda.","C":"'Onoga starog slugu' odgovara na pitanje koga (akuzativ), a ne na lokativ.","D":"Nije lokativ ni ženski rod; riječ je o akuzativu imenice muškoga roda."},
  "2014_ljeto_A__59": {"A":"'Neka se bojiš' nije imperativ, nego optativno-zapovjedni opis u 2. licu, što nije pravilan imperativ.","B":"'Bojiš se' prezent je, a ne imperativ.","C":"'Boji se' nije pravilan oblik za 2. lice jednine; treba 'boj se'."},
  "2014_ljeto_A__60": {"A":"U glavnoj surečenici 'došli budemo' nije pravilno; treba futur I. ('doći ćemo').","B":"U zavisnoj 'kada ćemo imati' pogrešno je upotrijebljen futur I.; treba futur II. ('budemo imali').","D":"U zavisnoj surečenici za buduću radnju treba futur II. ('budemo imali'), a ne futur I. ('ćemo imati')."},
  "2014_ljeto_A__61": {"A":"'Naprijed' je mjesni prilog (kamo/gdje), a ne načinski.","B":"'Zbog bolesti' priložna je oznaka uzroka, a ne načinski prilog.","C":"'Uskoro' je vremenski prilog, a ne načinski."},
  "2014_ljeto_A__62": {"A":"'Obzirom da' nije pravilno; standardno je 's obzirom na to da'.","B":"'Budući se trudio' nije pravilno; uz 'budući da' mora doći veznik 'da'.","C":"'No međutim' pleonazam je jer i 'no' i 'međutim' imaju suprotno značenje."},
  "2014_ljeto_A__63": {"A":"'Zaselak' je neživo, pa treba 'koji', a ne 'kojega'.","B":"'Portret' je neživo, pa treba 'koji', a ne 'kojega'.","D":"'Roman' je neživo, pa treba 'koji', a ne 'kojega'."},
  "2014_ljeto_A__64": {"B":"'Pogledavali su se' ima subjekt (oni), pa rečenica nije besubjektna.","C":"'Ona dvojica' subjekt je rečenice, pa ona nije besubjektna.","D":"'Kasno je razmišljati' ima subjekt u infinitivnoj surečenici, pa nije besubjektna kao bezlični glagol 'zaudaralo je'."},
  "2014_ljeto_A__65": {"B":"Namjerna rečenica izriče cilj (veznik 'da' = kako bi), a ovdje 'tako... da' iskazuje posljedicu.","C":"Načinska rečenica izriče način vršenja radnje, a ovdje je riječ o posljedici.","D":"Uzročna rečenica iskazuje uzrok ('jer'), a 'tako... da' iskazuje posljedicu."},
  "2014_ljeto_A__66": {"A":"'O svadbenome putovanju' u lokativu je s prijedlogom, pa je neizravni objekt, a ne izravni.","B":"'Na svakome putovanju' priložna je oznaka u lokativu, a ne izravni objekt.","D":"'Putovanje' ovdje je subjekt rečenice ('putovanje je odmor'), a ne izravni objekt."},
  "2014_ljeto_A__67": {"A":"'Ljubav prema prirodi' upravna je (rekcijska) sintagma s prijedložnim izrazom, a ne sročna.","B":"'Iskazivati ljubav' glagolska je upravna sintagma (objekt u akuzativu), a ne sročna.","D":"'Prepun ljubavi' upravna je sintagma (pridjev traži genitiv), a ne sročna."},
  "2014_ljeto_A__68": {"A":"'Najesti se ludih gljiva' znači poludjeti / govoriti gluposti, a ne biti umiješan u nedopušteno.","C":"'Pokupiti vrhnje' znači uzeti najbolji dio za sebe, a ne biti umiješan u nedopušteno.","D":"'Gutati knedle' znači potiskivati uvrede / suze, a ne biti umiješan u nedopušteno."},
  "2014_ljeto_A__69": {"B":"'Nemoćan' je nastao sufiksalnom tvorbom od 'nemoć' (ne- je dio osnove), a ne istodobno prefiksom i sufiksom.","C":"'Polupismen' nastao je slaganjem (polu- + pismen), a ne prefiksalno-sufiksalnom tvorbom.","D":"'Svjetovan' nastao je sufiksalnom tvorbom (svijet + -ovan), bez prefiksa."},
  "2014_ljeto_A__70": {"A":"'Hrvatska' je ime države (horonim), a ne etnik (ime stanovnika).","B":"'Osijek' je ime mjesta (ojkonim), a ne etnik.","D":"'Slaveni' je ime naroda/skupine naroda, a etnik je ime stanovnika određenoga mjesta."},
  "2014_ljeto_A__71": {"A":"'Balet' je internacionalizam (tal./franc.), a ne egzotizam iz daleke kulture.","C":"'Kritika' je internacionalizam grčkoga podrijetla, a ne egzotizam.","D":"'Surka' je naziv vrste kaputa iz bliske (panonske) tradicije, a ne egzotizam daleke kulture."},
  "2014_ljeto_A__72": {"A":"Riječka filološka škola (Fran Kurelat) zalagala se za vlastita rješenja, a ilirsku koncepciju nastavlja zagrebačka škola.","B":"Hrvatski vukovci raskinuli su s ilirskom tradicijom i prihvatili fonološki pravopis, pa je ne nastavljaju.","C":"Zadarska filološka škola (Ante Kuzmanić) zagovarala je štokavsko-ikavicu, a ilirsku koncepciju nastavlja zagrebačka škola."},

  // 2014_ljeto_B
  "2014_ljeto_B__1": {"A":"Glas materin označava milozvučnost i toplinu materinskoga jezika, a ne jezičnu posebnost svakoga naroda.","C":"Silna smjesa odnosi se na mnoštvo naroda u kojem se narod nalazi, a ne na jezičnu posebnost.","D":"Sjena puka opisuje narod bez jezika koji nestaje, a ne jezičnu posebnost."},
  "2014_ljeto_B__2": {"A":"Bog se u tom stihu ne spominje; zamjenica 'njega' upućuje na jezik iz prethodnoga stiha.","C":"Pjesnik nije referent zamjenice 'njega'; ona se odnosi na jezik koji se ljubi.","D":"Svijet se u tom stihu ne spominje; 'njega' upućuje na jezik."},
  "2014_ljeto_B__3": {"A":"Plašljivost nema veze sa značenjem arhaizma 'prošast', koji znači prolaznost.","B":"Pojavnost ne odgovara kontekstu nestajanja i propadanja koji nosi 'prošast'.","D":"Iako zvuči slično, 'prošast' znači prolaznost (propadanje), a ne prošlost."},
  "2014_ljeto_B__4": {"A":"Anadiploza bi ponavljala kraj jednoga stiha na početku sljedećega, što ovdje nije slučaj.","C":"Epifora bi se ponavljala na kraju stihova, a 'Njim' se ponavlja na početku.","D":"Simploka bi tražila istovremeno ponavljanje na početku i na kraju stihova, a ovdje se ponavlja samo početak."},
  "2014_ljeto_B__5": {"A":"Ditiramb je razuzdani hvalospjev Dionizu i radosti života, što ne odgovara svečanom tonu pjesme o jeziku.","B":"Elegija je tužaljka prožeta žalom, a ova je pjesma slavljenički zaziv jeziku.","D":"Oda hvali pojedinca ili pojavu uzvišenim tonom, ali ovdje je riječ o svečanom zazivu i hvali nalik himni."},
  "2014_ljeto_B__6": {"A":"Uz ljubavni motiv ovdje se javlja pejzaž (vrba, mlin, miris cvijeća), a ne domoljubni motiv.","C":"Religiozni motiv nije nositelj uz ljubavni; prevladavaju slike prirode (pejzaž).","D":"Socijalni motiv u sonetu izostaje; uz ljubav se isprepleće prirodni krajolik."},
  "2014_ljeto_B__7": {"A":"Vrba je tek dio pejzaža uz mlin, a ne simbol voljene osobe.","B":"Stari mlin je element krajolika, a ne simbol u pjesmi.","C":"Proljeće naznačuje godišnje doba, ali simbol voljene jest miris cvijeća."},
  "2014_ljeto_B__8": {"A":"Anđeo nije značenje riječi 'čedo', koja označava dijete.","C":"Obraz nema veze sa značenjem riječi 'čedo' (= dijete).","D":"Suza se u stihu navodi zasebno ('suza i krin'), a 'čedo' znači dijete."},
  "2014_ljeto_B__9": {"A":"Stih samo nabraja pridjeve o cvijetu (sitan, tih, fin) bez miješanja osjetilnih dojmova.","C":"Stih iznosi vizualne i poredbene slike (bijel, čist ko čedo), ali ne spaja različita osjetila u jedan dojam.","D":"Miris bića tek je metaforički prijenos, no nema ukrštanja dvaju osjetila kao u 'bijele psalme'."},
  "2014_ljeto_B__10": {"A":"Gazela ima drukčiju strofnu i rimnu shemu (s ponavljajućim refrenom), a ne 14 stihova soneta.","B":"Idila opisuje pastoralni, mirni život i nije vezana uz sonetni oblik.","C":"Kancona je dulja stroficka pjesma promjenjive strukture, a ovdje je riječ o klasičnom sonetu."},
  "2014_ljeto_B__11": {"A":"Ovi stihovi zazivaju pamet da se dokaže na djelu, a ne izriču sumnju u sebe.","C":"Stih govori o Silvijevu ocu koji je živ pošao u zagrobni svijet, a ne o pripovjedačevoj sumnji.","D":"Stih razmatra protivnika zla i veličinu djela, a ne sumnju pripovjedača u vlastite snage."},
  "2014_ljeto_B__12": {"A":"Klanjati nema veze sa značenjem glagola 'kinjiti', koji znači mučiti.","C":"Sramiti se ne odgovara značenju riječi 'kinji' (= muči, pati).","D":"Žuriti nije značenje glagola 'kinjiti', koji označava mučenje i patnju."},
  "2014_ljeto_B__13": {"B":"Eufemizam bi ublažavao neugodan pojam, no ovdje se danu pripisuje ljudska radnja umiranja.","C":"Hiperbola bi pretjeravala, a u stihu je posrijedi pridavanje ljudske osobine danu i mraku.","D":"Simbol bi neku sliku uzdizao u zamjensko značenje, no ovdje je riječ o oživljavanju (personifikaciji) dana."},
  "2014_ljeto_B__14": {"B":"Naracija je pripovijedanje događaja, a ovaj stih je zaziv muza za nadahnuće.","C":"Retardacija usporava radnju, dok ovdje pjesnik priziva pomoć muza.","D":"Retrospekcija je vraćanje u prošlost, a stih je invokacijski zaziv božanskog nadahnuća."},
  "2014_ljeto_B__15": {"A":"Dante je putnik kojega vode, a ne onaj koga oslovljava s 'Pjesniče'.","B":"Homer nije Danteov vodič kroz Pakao; vodi ga Vergilije.","C":"Silvije se spominje tek kao Silvijev otac (Eneja), a vodič i 'pjesnik' jest Vergilije."},
  "2014_ljeto_B__16": {"B":"Vijest da se suprug ne može vratiti nije izazvala smijeh, nego prethodi epizodi s porukom.","C":"Poslovne okolnosti na ladanju samo objašnjavaju mužev izostanak, a ne razlog pripovjedačeva smijeha.","D":"Prijateljev dolazak donosi vijest, ali pripovjedač se nasmijao jer je pomislio da je poruka njemu."},
  "2014_ljeto_B__17": {"B":"Suprug nije bio u gradskoj pisarnici, nego na ladanju (seoskom imanju) zbog poslova.","C":"Hodočašće se u ulomku ne spominje; suprug je na ladanju radi poslova.","D":"Inozemstvo se ne navodi; muž boravi na ladanju, seoskom posjedu."},
  "2014_ljeto_B__18": {"A":"Razlog za novo odijelo nije sjećanje na ples, nego dotrajalost staroga.","B":"Neslaganje boja fraka i prsluka u ulomku se ne navodi kao razlog narudžbe.","C":"Prekratki rukavi nisu spomenuti; odijelo je naručeno jer je staro dotrajalo."},
  "2014_ljeto_B__19": {"A":"Rastužiti se ne odgovara značenju 'obmanuti se' (= zavarati se).","B":"Uplašiti se nema veze sa značenjem glagola 'obmanuti se'.","C":"Zamisliti se ne izražava prijevaru ili samozavaravanje koje nosi 'obmanuti se'."},
  "2014_ljeto_B__20": {"A":"Eufemizam bi ublažavao neugodno, a ovdje je riječ o pretjerivanju u izrazu osjećaja.","C":"Metafora bi prenosila značenje po sličnosti, no 'tisuću radosti' je brojčano pretjerivanje.","D":"Personifikacija bi davala ljudske osobine neživomu, čega u ovom primjeru nema."},
  "2014_ljeto_B__21": {"A":"Vanča ne prepisuje da dokaže umijeće, nego da uzvrati Mecenina dobročinstva.","C":"Prepisivanje nije način ublažavanja ljutnje, nego iskaz zahvalnosti za dobročinstva.","D":"Cilj prepisivanja nije postidjeti autora govora, nego se odužiti dobrotvoru."},
  "2014_ljeto_B__22": {"A":"Riječ o porođajnim mukama prepisivanja izražava napor, a ne ponizno ponašanje.","B":"Uzdah o neznatnoj otplati pripada dobrotvoru, a poniznost se pokazuje saginjanjem i klanjanjem.","C":"Tužba o nezahvalnosti svijeta dolazi od dobrotvora i ne prikazuje ponizno držanje."},
  "2014_ljeto_B__23": {"B":"Ivica Kičmanović je pripovjedač i prepisivač, a poetom ga naziva Mecena (illustrissimus).","C":"Kumordinar Rožac nije onaj koji autora naziva poetom; to čini illustrissimus, Mecena.","D":"Rudimir Bombardirović nije naveden kao onaj koji dijeli naziv poet."},
  "2014_ljeto_B__24": {"A":"Vančino prepisivanje govora nije ono što se naziva litanijom.","B":"Dobrotvorove opomene nisu litanija; litanijama se naziva predugi govor poete.","C":"Rožačeve tužaljke nisu označene kao litanije; litanije se odnose na poetov govor."},
  "2014_ljeto_B__25": {"B":"Illustrissimus označava Mecenu (dobrotvora), a ne poetu.","C":"Milosrdni je naziv za dobrotvora Mecenu, a ne za poetu.","D":"Rožac je kumordinar, a ne poet."},
  "2014_ljeto_B__26": {"B":"Filipova pomisao da uđe iskazuje trenutnu odluku, a ne dubinu sjećanja.","C":"Konstatacija da kuća nije zaključana opisuje stanje, a ne ističe sjećanje.","D":"Zatvaranje vrata opisuje radnju u sadašnjosti, a sjećanje ističe poznavanje svakog detalja dolaska."},
  "2014_ljeto_B__27": {"B":"Prosjak ne odgovara značenju arhaizma 'tat', koji znači lopov.","C":"Slikar nema veze sa značenjem riječi 'tat' (= kradljivac), iako je Filip slikar.","D":"Zaručnik ne odgovara značenju 'tat', koje označava lopova."},
  "2014_ljeto_B__28": {"B":"Ptičji cvrkut nije naveden kao okidač sjećanja na Karolinu; to je tepihklopfer.","C":"Stari orah u ulomku nije ono što potiče sjećanje na Karolinu.","D":"Ruže su dio vrtnog opisa, ali sjećanje na Karolinu pobudio je tepihklopfer."},
  "2014_ljeto_B__29": {"A":"Asindeton bi izostavljao veznike, a ovdje se veznik 'i' ponavlja pred svakim članom niza.","B":"Inverzija bi mijenjala uobičajeni red riječi, no figura ovog niza je ponavljanje veznika.","D":"Retoričko pitanje izostaje; primjer je nabrajanje s viševezničkim 'i' (polisindeton)."},
  "2014_ljeto_B__30": {"A":"Albert Camus tematizira apsurd i otuđenje, a ne povratak u djetinjstvo putem sjećanja.","B":"Ernest Hemingway poznat je po sažetom stilu i temama rata i muškosti, ne po prustovskom sjećanju.","C":"Franz Kafka piše o tjeskobi, otuđenju i birokraciji, a ne o povratku u djetinjstvo."},
  "2014_ljeto_B__31": {"A":"Ljubdrag ne žali za propuštenim prilikama, nego uspoređuje bolju prošlost s lošijom sadašnjošću.","B":"Izgubljena sloboda nije predmet njegove žalbe; tuguje za nekadašnjim vremenima.","C":"Neostvarena ljubav nije tema monologa; Ljubdrag žali za prošlim vremenima i nekadašnjim vrlinama."},
  "2014_ljeto_B__32": {"A":"Ovi stihovi tvrde da svijet starenjem postaje gori, a ne da su ljudi radili za opće dobro.","B":"Stih govori o drukčijoj naravi i učenosti negdašnjih ljudi, ne izričito o radu za korist.","D":"Stih opisuje propadanje stada i imovine, a ne rad za zajedničku korist."},
  "2014_ljeto_B__33": {"A":"Stihovi prikazuju taštinu, a ne ženinu mudrost.","B":"Čežnja za bogatstvom nije ono što stihovi izriču; riječ je o gledanju u zrcalo i uljepšavanju.","D":"Ogovaranje se ne spominje; žene se prikazuju kao sklone uljepšavanju."},
  "2014_ljeto_B__34": {"B":"Okorištavanje očevim bogatstvom nije poruka stiha; mladi ne žele ni savjeta od očeva.","C":"Stih ne govori o uskraćivanju pomoći očevima, nego o odbijanju njihovih savjeta.","D":"Želja za vladanjem umjesto očeva nije sadržaj stiha; mladi odbacuju savjet."},
  "2014_ljeto_B__35": {"A":"Alegorija nije osnova monologa; cijeli se gradi na suprotstavljanju nekad i sad.","C":"Hiperbola nije okosnica monologa, nego dosljedno suprotstavljanje prošlosti i sadašnjosti.","D":"Gradacija bi nizala pojmove po jačini, a ovdje prevladava antitetičko 'prije – sad'."},
  "2014_ljeto_B__36": {"A":"Gradacija je postupno stupnjevanje pojmova, a ne pitanje s negacijom i konačnim odgovorom.","B":"Polisindeton je ponavljanje veznika, a ne opisana struktura pitanja i odgovora.","C":"Retoričko pitanje ne traži odgovor i nema niz mogućih odgovora s negacijom."},
  "2014_ljeto_B__37": {"A":"Agamemnon je zapovjednik s kojim se junak sukobio, a ne sam taj junak.","C":"Odisej se ističe lukavošću i domišljatošću, a opis hrabrosti i sukoba zbog robinje pripada Ahileju.","D":"Patroklo je Ahilejev prijatelj, ali junak iz opisa koji se sukobio sa zapovjednikom jest Ahilej."},
  "2014_ljeto_B__38": {"A":"Džore Držić je petrarkistički pjesnik, a ne autor učene komedije s prologom o podjeli ljudi.","B":"Hanibal Lucić piše ljubavnu liriku i dramu Robinja, a ne opisanu komediju.","D":"Mavro Vetranović je pisac religioznih i alegorijskih djela, a ne autor Dunda Maroja."},
  "2014_ljeto_B__39": {"A":"Renesansa je razdoblje humanizma i svjetovnih tema, a ne pokreta katoličke obnove.","C":"Klasicizam se oslanja na antičke uzore i razum, a nije vezan uz katoličku obnovu.","D":"Romantizam naglašava osjećaje i nacionalno, a ne katoličku obnovu."},
  "2014_ljeto_B__40": {"A":"Tri je broj glavnih dijelova (Pakao, Čistilište, Raj), a ne ukupan broj pjevanja.","B":"Devet odgovara broju krugova Pakla, a ne broju pjevanja.","C":"Trideset tri je broj pjevanja jednoga dijela, dok ih ukupno ima sto."},
  "2014_ljeto_B__41": {"A":"Ankona se spominje kao usputno mjesto, ali radnja Dunda Maroja zbiva se u Rimu.","B":"Dubrovnik je mjesto podrijetla likova, no radnja se odvija u Rimu.","D":"Split nije mjesto radnje Dunda Maroja, koja se zbiva u Rimu."},
  "2014_ljeto_B__42": {"A":"Kip domovine leta 188* (Kranjčević) ne uzima se kao djelo koje obilježava početak moderne.","B":"Misao na vječnost nije navedeno kao djelo-prekretnica za hrvatsku modernu.","C":"Prijan Lovro pripada realizmu (Šenoa), a ne početku moderne."},
  "2014_ljeto_B__43": {"B":"Njemak Jerko je tragičan, dobronamjeran lik, a ne spletkar.","C":"Plemić Stjepko je protivnik, ali intrigantska je uloga vezana uz brijača Grgu Čokolina.","D":"Vojnik Miloš nije nositelj intriga u romanu."},
  "2014_ljeto_B__44": {"A":"Balada iz predgrađa djelo je Dobriše Cesarića, a ne Tina Ujevića.","B":"Majstore, ugasi svjetlo napisao je Jure Kaštelan, a ne Ujević.","D":"Tvrđava koja se ne predaje pripisuje se drugom autoru, a ne Ujeviću."},
  "2014_ljeto_B__45": {"A":"Časopis Danas nije onaj koji je uređivao A. B. Šimić.","B":"Kolo je stariji ilirski časopis, a ne Šimićevo glasilo.","D":"Vijenac je književni časopis druge tradicije, a Šimić je uređivao Vijavicu."},
  "2014_ljeto_B__46": {"B":"Raspored 1A, 2C, 3B, 4A, 5C pogrešno povezuje Rastignaca i Sonju te pogrešno smješta Gregora Samsu.","C":"Raspored 1B, 2A, 3C, 4B, 5A pogrešno svrstava Rastignaca u Preobražaj i Lizavetu izvan Zločina i kazne.","D":"Raspored 1C, 2A, 3B, 4C, 5A pogrešno povezuje Gregora Samsu i Lizavetu Ivanovnu s njihovim djelima."},
  "2014_ljeto_B__47": {"B":"Raspored 1A, 2B, 3C, 4A, 5B pogrešno svrstava Gundulića u renesansu i Preradovića u barok.","C":"Raspored 1C, 2A, 3B, 4C, 5A pogrešno povezuje Gundulića s romantizmom i Marulića s barokom.","D":"Raspored 1B, 2A, 3C, 4B, 5A pogrešno smješta Mažuranića u renesansu i Marulića u romantizam."},
  "2014_ljeto_B__48": {"A":"Oblik 'izvijestavati' nije pravilan; standardno je 'izvješćivati'.","B":"Oblik 'premjestati' nije pravilan; standardno je 'premještati'.","C":"Oblik 'razrješavati' nije ovdje prihvaćen kao traženi točan odgovor; nedvojbeno je pravilno 'zapovijedati'."},
  "2014_ljeto_B__49": {"A":"U 'hrvatsko Zagorje' prvi član vlastitog imena treba biti velikim slovom.","B":"U 'Hrvatsko zagorje' drugi član vlastitog imena pogrešno je napisan malim slovom.","C":"U 'hrvatsko zagorje' oba člana vlastitog imena pogrešno su napisana malim slovom."},
  "2014_ljeto_B__50": {"A":"Prvi slog (vo-) nije naglašen; naglasak je na slogu -za-.","B":"Drugi slog (-ka-) nije naglašen u riječi vokalizacija.","C":"Treći slog (-li-) nije naglašen; naglašen je četvrti slog -za-."},
  "2014_ljeto_B__51": {"A":"Jotacija je stapanje suglasnika s j, a ovdje je h prešlo u s ispred i.","B":"Palatalizacija daje č, ž, š ispred prednjih vokala, ali h→s ispred i jest sibilarizacija.","D":"Vokalizacija je prijelaz l u o, čega u primjeru trbuh→trbusi nema."},
  "2014_ljeto_B__52": {"B":"U 'knjiga → knjizi' provedena je sibilarizacija (g→z), a ne palatalizacija.","C":"U 'mačkica' nije provedena palatalizacija; suglasnik k ostaje.","D":"U 'sreća → sretna' nije riječ o palatalizaciji, nego o gubljenju glasa."},
  "2014_ljeto_B__53": {"A":"Morfem pjev- je korijen koji nosi osnovno značenje pjevanja, a ne 'izvršiteljica radnje'.","B":"Sufiks -ač- označava vršitelja radnje (muški rod), a žensku izvršiteljicu daje -ic-.","D":"Nastavak -a je gramatički morfem (padežni nastavak), a ne nositelj značenja izvršiteljice."},
  "2014_ljeto_B__54": {"A":"Oblik 'Goetheev' ima suvišno udvojeno e i nije pravilan.","C":"Oblik 'Goethev' pogrešno izostavlja osnovno -e prezimena.","D":"Oblik 'Goethov' pogrešno izostavlja samoglasnik osnove prezimena."},
  "2014_ljeto_B__55": {"A":"Prijedlozi su nepromjenjiva vrsta riječi.","B":"Uzvici su nepromjenjiva vrsta riječi.","C":"Veznici su nepromjenjiva vrsta riječi."},
  "2014_ljeto_B__56": {"B":"Oblik 'djedo' nije standardni vokativ imenice djed.","C":"Oblik 'djedu' jest dativ ili lokativ, a ne vokativ.","D":"Oblik 'djedove' je množinski, a vokativ jednine glasi 'djede'."},
  "2014_ljeto_B__57": {"A":"Oblik 'kći' je nominativ, a akuzativ glasi 'kćer'.","C":"Oblik 'kćerku' pripada izvedenici kćerka, a ne imenici kći.","D":"Oblik je ispravan ('kćer'), ali kao ponovljeni distraktor nije označen kao točan odgovor; traženi je odgovor B."},
  "2014_ljeto_B__58": {"B":"Oblik 'pekavši' je glagolski prilog prošli, a ne sadašnji.","C":"Oblik 'pekući' nije pravilan; sibilarizacija daje 'pečući'.","D":"Oblik 'pekući' (ponovljeni) nije pravilan glagolski prilog sadašnji; ispravno je 'pečući'."},
  "2014_ljeto_B__59": {"A":"U 'Nasmijao nam se' glagol je povratan i s dativnom dopunom, dakle neprijelazan.","C":"U 'Sramio nas se' glagol je povratan i ne uvodi pravi izravni objekt.","D":"U 'Lagao nam je' glagol ima dativnu dopunu, pa je neprijelazan."},
  "2014_ljeto_B__60": {"A":"Riječ 'mi' je lična (osobna) zamjenica, a ne odnosna.","B":"Riječ 'svome' je povratno-posvojna zamjenica, a ne odnosna.","D":"Riječ 'naši' je posvojna zamjenica, a ne odnosna."},
  "2014_ljeto_B__61": {"A":"Oblik 'htijela' nije standardan; pravilno je 'htjela'.","C":"Oblik 'htjeo' nije standardni glagolski pridjev radni od htjeti.","D":"Oblik 'htijo' je nestandardan i pogrešan."},
  "2014_ljeto_B__62": {"A":"U 'zbog brzopletosti' podcrtana riječ je imenica, a ne prilog.","B":"U 'Brzopleti su učenici' riječ je pridjev koji opisuje učenike.","D":"U 'uvijek brzopleti' riječ je pridjev (imenski dio predikata), a ne prilog."},
  "2014_ljeto_B__63": {"A":"Oblik 'ljepši' jest pravilan komparativ, no kao traženi nedvojbeni primjer odabran je C.","B":"Oblik 'bjelje' jest pravilan komparativ, ali ključni je bez sumnje točan oblik 'svjetliju'.","D":"Oblik 'ljeniji' nije pravilan; pravilan komparativ glasi 'lijeniji'."},
  "2014_ljeto_B__64": {"B":"U 'Nismo to očekivali od nikoga' uz negaciju treba 'ni od koga'.","C":"U 'Nismo nizašto raspoloženi' uz negaciju glagola treba 'ni za što'.","D":"U 'Nismo zadovoljni s ničim' niječna zamjenica s prijedlogom treba glasiti 'ni s čim'."},
  "2014_ljeto_B__65": {"A":"U 'preko pjesama' prijedlog je u značenju 'pomoću/putem', što nije njegova prostorna uporaba.","B":"U 'preko deset' prijedlog znači 'više od', a ne prostorno prelaženje.","C":"U 'preko kartice' prijedlog ima značenje 'putem', a ne prostorno značenje."},
  "2014_ljeto_B__66": {"A":"U 'U gradu je mnogo studenata' riječ 'grad' je u lokativu kao priložna oznaka mjesta, ne objekt.","B":"U 'ključeve grada' riječ 'grad' je u genitivu kao atribut, a ne objekt.","D":"U 'Grad će uskoro nestati' riječ 'grad' je subjekt, a ne objekt."},
  "2014_ljeto_B__67": {"A":"U 'planina Dinara' obje su riječi ženskoga roda, jednine i nominativa, pa se slažu u rodu, broju i padežu.","B":"U 'grad Vinkovci' imenice se ne slažu u broju (jednina i množina) ni rodu.","C":"U 'rijeka Dunav' imenice se ne slažu u rodu (ženski i muški)."},
  "2014_ljeto_B__68": {"A":"Rečenica ima dvije surečenice (glavnu i zavisnu), a ne jednu.","C":"Relativna sintagma uz prijedlog ne tvori zasebnu treću surečenicu; ima ih dvije.","D":"U rečenici nema četiri surečenice, nego dvije."},
  "2014_ljeto_B__69": {"B":"U 'Magla je tolika da moramo odgoditi' zavisna rečenica izriče posljedicu, dakle je posljedična.","C":"U 'Osjeća se da će izbiti sukob' zavisna rečenica je subjektna, a ne objektna.","D":"U 'Sjeo je da bi pričekao prijatelja' zavisna rečenica izriče namjeru, dakle je namjerna."},
  "2014_ljeto_B__70": {"A":"Frazem 'razbacivati se riječima' znači mnogo obećavati bez pokrića, suprotno od držanja obećanja.","B":"Frazem 'voditi glavnu riječ' znači biti vodeći u razgovoru, a ne pridržavati se obećanja.","C":"Frazem 'ostati bez riječi' znači zanijemiti od zaprepaštenja, ne pridržavati se obećanja."},
  "2014_ljeto_B__71": {"A":"Posuđenice iz portugalskoga nisu bohemizmi.","B":"Posuđenice iz mađarskoga jezika su hungarizmi, a ne bohemizmi.","C":"Posuđenice iz poljskoga jezika su polonizmi, a ne bohemizmi."},
  "2014_ljeto_B__72": {"B":"Ilirska slovnica je gramatika (slovnica), a ne rječnik.","C":"Institutionum linguae Illyricae libri duo je gramatika, a ne rječnik.","D":"Skladnja hrvatskog jezika je djelo o sintaksi, a ne rječnik."},

  // 2015_jesen_A
  "2015_jesen_A__1": {"B":"Lirski subjekt ne prikazuje grad kao pobunjen, nego kao bijedan ('mizerija rođenog mi grada').","C":"Ponos se ne iskazuje; sintagma 'mizerija' nosi izrazito negativnu, ponižavajuću ocjenu rodnoga grada.","D":"Snaga se odnosi na poziv misli i zvonu na kraju, a ne na karakterizaciju samoga grada koji je nazvan 'mizerijom'."},
  "2015_jesen_A__2": {"A":"'Glupost!' je uzvik kojim subjekt odbacuje sentimentalnost, a ne adresat obraćanja u četvrtoj strofi.","B":"'Slabi živci!' također je samokritični uzvik, a ne biće kojem se subjekt obraća zapovjednim oblikom.","D":"Zvono je predmet ranijih strofa; u četvrtoj se subjekt apostrofira misao ('Pregni, misô')."},
  "2015_jesen_A__3": {"A":"Miris nije značenje riječi 'cjelov'; ona je izvedena od 'cjelivati', što znači ljubiti.","B":"Pogled ne odgovara; 'cjelov' označuje tjelesni dodir usnama, poljubac.","D":"Šapat je zvučni pojam, dok 'cjelov' označuje poljubac koji 'peče' na čelu."},
  "2015_jesen_A__4": {"A":"Otrpjeti bol značilo bi suzdržati ga, no 'dati crna jedra' znači pustiti bol da se razmaše, dakle pojačati.","C":"Spriječiti bol suprotno je smislu metafore; 'dati jedra' znači pustiti da plovi/jača, a ne zaustaviti.","D":"Ublažiti bol značilo bi smanjiti ga, dok metafora jedara podrazumijeva njegovo širenje i jačanje."},
  "2015_jesen_A__5": {"A":"Eufemizam je ublažavanje neugodna pojma, čega u nizu snažnih zaziva (vihor, bura, buna) nema.","C":"Ironija podrazumijeva suprotnost rečenoga i mišljenoga, dok je niz iskreni poziv na snagu, a ne podsmijeh.","D":"Oksimoron spaja proturječne pojmove, no 'vihor, bura, truba, buna' srodni su pojmovi u rastućem nizu, a ne proturječni."},
  "2015_jesen_A__6": {"A":"Stariji Osmanlije ne zavide kršćanima, nego strahuju od njihove osvete ('od strâ ćuti').","B":"U mukama uživaju mlađi ('tko je mlađi, rado gleda'), a ne stariji koji ćute strah.","C":"Divljenju kreposti podliježe aga, dok stariji Osmanlije pokazuju strah od osvete."},
  "2015_jesen_A__7": {"A":"Stih o krvi koja teče poljem prikazuje krvavost prizora, ali ne i sam broj stradalih.","B":"Stih o nemogućnosti osvete iskazuje junačko načelo, a ne masovno stradanje.","D":"Stih o strahu pred onim koji umire bez jada izriče opću mudrost, a ne masovni pokolj."},
  "2015_jesen_A__8": {"A":"Stih o mlađemu koji rado gleda muke opisuje konkretno ponašanje, a nije sažeta općenita misao.","B":"Stih o starijemu koji unaprijed osjeća strah opisuje pojedinačni doživljaj, a ne aforističku poruku.","C":"Stih o tuzi za junacima retoričko je pitanje, a ne sažeta životna mudrost svojstvena aforizmu."},
  "2015_jesen_A__9": {"B":"Slika ledena šiljka koji dira dušu metafora je straha, a ne suprotstavljanje dvaju pojmova.","C":"Stih s retoričkim pitanjem o junacima ne sadrži suprotstavljene pojmove nego žaljenje.","D":"Stih o piknji i mraznim valima opisuje širenje straha tijelom, bez antitetičkog para."},
  "2015_jesen_A__10": {"A":"Šesterac ima šest slogova, a stihovi poput 'Rijekom krvca poljem teče' imaju osam slogova.","C":"Jedanaesterac ne odgovara; uz deseterce se izmjenjuju osmerci, a ne jedanaesterci.","D":"Dvanaesterac (dvostruko rimovani) tipičan je za stariju liriku, a ne za ovaj spjev koji rabi deseterce i osmerce."},
  "2015_jesen_A__11": {"B":"Marljivost se ne ističe; slika ploda upućuje na korist narodu, a ne na osobnu radišnost.","C":"Rad samo za sebe oprečan je slici koja naglašava da bi plodovi bili namijenjeni 'rodu', dakle zajednici.","D":"Težnja bogatstvu nije sadržana u metafori; 'zlatni plod' odnosi se na dobrobit naroda, a ne na imetak."},
  "2015_jesen_A__12": {"B":"U radosti se nisu razišli; rastanak je tegoban i tih ('mučeći'), bez ikakva veselja.","C":"U suzama nije izričito rečeno; tekst kaže 'mučeći', dakle u mučnoj šutnji/mukama.","D":"U tišini nije precizno; 'mučeći' znači u mukama, što je više od pukog izostanka zvuka."},
  "2015_jesen_A__13": {"A":"Pisac nije značenje; 'prijan' je dijalektni naziv za prijatelja, a ne za autora.","C":"Učitelj ne odgovara; 'prijan' označuje bliska prijatelja, a ne zvanje.","D":"Župnik nije značenje riječi; 'prijan' znači prijatelj."},
  "2015_jesen_A__14": {"A":"'Šaka praha i pepela' opisuje Lovrinu propast i ništavnost, a ne uvjete u kojima je živio.","C":"'Sveta suza na grobu' odnosi se na pripovjedačevu posvetu uspomeni, a ne na životne uvjete.","D":"'Nesretni genij' karakterizacija je samoga Lovre, a ne okolnosti njegova života."},
  "2015_jesen_A__15": {"A":"Crtica je kraći i jednostavniji oblik, dok je Prijan Lovro razvijena pripovjedna proza, novela.","B":"Legenda obrađuje svetačke i predajne sadržaje, što ne odgovara realistično-romantičnoj priči o Lovri.","D":"Životopis je nefikcijski prikaz nečijega života, dok je Prijan Lovro književna fikcija, novela."},
  "2015_jesen_A__16": {"B":"'Praviti gluposti' upućuje na Rastignacove moguće pogreške, a ne na Vautrinovu nadmoć nad situacijom.","C":"'Naslijediti brata' tiče se Tailleferova plana, a ne Vautrinove kontrole nad prizorom.","D":"'Otvoriti baštinu' opisuje ishod zločina, a ne Vautrinovu nadmoć kao dirigenta scene."},
  "2015_jesen_A__17": {"A":"Vautrinov otac ne spominje se; 'on' je sam Vautrin koji govori o sebi u trećem licu.","B":"Otac Goriot nije osoba koja 'voli' Rastignaca u tom kontekstu; riječ je o Vautrinu.","C":"Taillefer je meta plana, a ne onaj koji 'voli' Rastignaca; zamjenica se odnosi na Vautrina."},
  "2015_jesen_A__18": {"A":"Graja se odnosi na atmosferu za stolom, a ne na metaforu planiranog zločina.","C":"Mač pripada drugomu dijelu teksta (dvoboj), a planirani zločin Vautrin uspoređuje s hljebom koji se peče.","D":"Renta nije usporedba; zločin je predočen slikom kruha ('hljeb je na loparu')."},
  "2015_jesen_A__19": {"A":"'Prava opera' je metafora prizora, a ne pleonazam (nema suvišna ponavljanja istoga značenja).","B":"'Početničke greške' nije pleonazam jer pridjev donosi novu obavijest, a ne ponavljanje značenja.","D":"'Mali sanak' nije pleonazam; pridjev 'mali' nije sadržan u značenju imenice 'sanak'."},
  "2015_jesen_A__20": {"B":"Otrov se ne spominje; baština se otvara mačem, dakle dvobojem ('vrškom svojega mača').","C":"Pismo nije sredstvo; zločin izvršava grof Franchessini mačem u dvoboju.","D":"Ucjena nije sredstvo otvaranja baštine; ona se otvara mačem, tj. dvobojem."},
  "2015_jesen_A__21": {"A":"Nadljudski nije značenje; 'jalov' znači neplodan, uzaludan, a ne natprosječno snažan.","B":"Učestao nije značenje; 'jalov' ne govori o učestalosti, nego o bezuspješnosti.","D":"Velik nije značenje; 'jalov' označuje napore bez ploda, dakle uzaludne."},
  "2015_jesen_A__22": {"A":"Rečenica o ubodu iglom pripovjedačev je opis Filipova osjećaja, a ne njegov unutarnji govor.","B":"Rečenica o strujanju nemira također je pripovjedačev opis stanja, a ne misli iskazane u prvom licu.","D":"Replika u crtici dio je dijaloga (izgovorena je naglas), a ne unutarnji monolog."},
  "2015_jesen_A__23": {"A":"Pogledi nisu predmet metafore; 'otrovni žalac' odnosi se na bolnu, drsku riječ sugovornika.","B":"Udarci su tjelesni, dok 'žalac' metaforički prikazuje uvredljivu riječ koja peče.","C":"Ugrizi nisu izvor boli; bol potječe od oštre riječi, prikazane kao otrovni žalac."},
  "2015_jesen_A__24": {"A":"Zagrebački kolodvor nije mjesto rasprave; ona se odvija u krčmi u Kostanjevcu.","C":"Majčina dvokatnica drugo je mjesto radnje romana, a ne mjesto ove rasprave.","D":"Kaptolska trafika nije mjesto rasprave; razgovor o umjetnosti vodi se u krčmi."},
  "2015_jesen_A__25": {"A":"Joža Podravec nije Filipov sugovornik u raspravi o umjetnosti; to je Kyriales.","C":"Silvije pl. Liepach drugi je lik romana, a Filipov je sugovornik 'taj Grk' Kyriales.","D":"Vladimir Baločanski nije sudionik ove rasprave; sugovornik je Sergije Kirilovič Kyriales."},
  "2015_jesen_A__26": {"A":"Lijepe djevojke nisu želja; maskari žude za mladošću ('a laka je mlados').","B":"Neizmjerno bogatstvo nije cilj; žele se pomladiti da bi mogli plesati i veseliti se.","C":"Sretna starost suprotna je njihovoj želji; tuže se da je 'teška staros' i žele mladost."},
  "2015_jesen_A__27": {"A":"Stanac ne moli za ples, nego za ispunjenje vlastite molbe/želje da se pomladi.","C":"Stanac ne traži da vile mole za njega, nego da one njemu ispune molbu ('Stancu se umolite').","D":"Stanac se ne želi svidjeti vilama; traži da mu udovolje, tj. ispune želju."},
  "2015_jesen_A__28": {"A":"Vile ga nisu natjerale na ples; prema didaskaliji svežu ga i obrade mu lice i bradu.","B":"Oduzimanje govora ne spominje se; didaskalija govori o crnjenju i strizi brade.","C":"Podrezivanje kose nije naglasak; tekst kaže da su ga 'omrčili', tj. obojili (crnom bojom)."},
  "2015_jesen_A__29": {"B":"Prijetvornost znači dvoličnost, no Stanac iskreno pristaje na zapovijed, ne glumi.","C":"Rasipnost se ne iskazuje; replika izražava pokornost vilama, a ne odnos prema novcu.","D":"Škrtost nije sadržana; Stanac je u replici poslušan, spreman izvršiti zapovijed."},
  "2015_jesen_A__30": {"A":"Maskiranje na karnevalu nije motiv; Stanac vjeruje u pravo pomlađivanje, a maškare ga varaju.","B":"Obrana od kradljivaca nije razlog; Stanac želi mladost iz osobnih, bračnih pobuda.","C":"Zabava s mladićima nije cilj; Stanac se nada da će se kao mlad svidjeti ženi."},
  "2015_jesen_A__31": {"A":"Rečenica o tome da nije učinio ništa nečasno govori o pokušaju popravka ugleda, a ne o želji za napredovanjem.","C":"Rečenica kojom upozorava Noru izražava prijetnju, a ne ambiciju za boljim položajem.","D":"Rečenica o ovisnosti njezina ugleda o njemu također je ucjena, a ne iskaz Krogstadove karijerne želje."},
  "2015_jesen_A__32": {"A":"Frazem 'desna ruka' ne znači ovisnost, nego nezamjenjiva, ključnoga suradnika.","B":"Biti nadređen direktoru nije značenje; 'desna ruka' je najbliži pomoćnik, ne nadređeni.","D":"Zavist nije značenje frazema; 'desna ruka' označuje pouzdana oslonca i pomoćnika."},
  "2015_jesen_A__33": {"A":"Zahtjev za novcem od muža Krogstad upravo odbacuje ('ne tražim novac'), pa tako ne tumači njezine riječi.","B":"Zauzimanje za njega nije Krogstadovo tumačenje; on njezine riječi shvaća kao prijetnju samoubojstvom.","D":"Napuštanje muža Krogstad ne razumije iz njezinih riječi; aludira na crnu, hladnu vodu, tj. smrt."},
  "2015_jesen_A__34": {"A":"Zahtjev za pomilovanjem nije ono što Krogstad nosi u džepu; riječ je o pismu kojim ucjenjuje.","B":"Zahtjev za posao nije predmet; 'ga' upućuje na pismo ucjene koje drži kao oružje.","C":"Helmerov novac Krogstad izričito ne traži, pa zamjenica ne upućuje na novac, nego na pismo."},
  "2015_jesen_A__35": {"A":"Potpisivanje zadužnice tiče se Norina duga, a ne Helmerova postupka prema Krogstadu.","B":"Podmićivanje nije Helmerov čin; on je Krogstadu dao otkaz ('otjerali su me').","C":"Smanjenje plaće nije spomenuto; Krogstad je otpušten, a ne samo manje plaćen."},
  "2015_jesen_A__36": {"B":"Barok ne obnavlja antiku kao ideal, nego razvija raskoš, kontraste i dinamičnost izraza.","C":"Prosvjetiteljstvo naglašava razum i odgojnu svrhu, a ne oponašanje antičkih žanrova kao temeljni program.","D":"Romantizam ističe osjećaje, individualnost i nacionalno, a ne obnovu antičke retorike i žanrova."},
  "2015_jesen_A__37": {"A":"Anadiploza ponavlja kraj jednog stiha na početku sljedećega, čega ovdje nema; riječ je ponovljena na kraju.","B":"Anafora ponavlja riječ na početku stihova, a 'tudijer' se ponavlja na kraju svakoga stiha.","D":"Simploka spaja anaforu i epiforu, no ovdje se ponavlja samo završetak, dakle samo epifora."},
  "2015_jesen_A__38": {"A":"Heksametar je vrsta stiha (šest stopa), a ne strofa od šest stihova.","B":"Septima je strofa od sedam stihova, a ne od šest.","D":"Šesterac je stih od šest slogova, a ne strofa od šest stihova."},
  "2015_jesen_A__39": {"B":"Dinko Šimunović pisac je o dalmatinskoj zagori i tradicionalnom svijetu, a ne urbane proze u trapericama.","C":"Ivan Aralica poznat je po povijesnim romanima, a ne po urbanim temama i prozi u trapericama.","D":"Janko Leskovar pripada moderni i psihološkoj prozi, a ne poslijeratnoj prozi u trapericama."},
  "2015_jesen_A__40": {"B":"Combray (dio Proustova ciklusa) objavljen je tek 1913., a ne iste godine kao Gospođa Bovary (1857.).","C":"Preobražaj F. Kafke objavljen je 1915., dakle mnogo poslije Gospođe Bovary.","D":"Razbojnici F. Schillera potječu iz 1781., dakle iz predromantizma, a ne iz 1857."},
  "2015_jesen_A__41": {"A":"Digresija je odmak od glavne teme, a ovdje je riječ o zazivu Boga na početku, dakle invokaciji.","C":"Retardacija je usporavanje radnje, a navedeni stihovi zazivaju božju pomoć, što je invokacija.","D":"Retrospekcija je vraćanje u prošlost, čega u ovom početnom zazivu pomoći nema."},
  "2015_jesen_A__42": {"A":"Antun Vrančić nije autor te elegije; djelo je napisao Juraj Šižgorić.","B":"Ivan Česmički (Janus Pannonius) latinski je pjesnik, ali ne autor Elegije o pustošenju Šibenskog polja.","D":"Marko Marulić autor je Judite i drugih djela, a navedenu elegiju napisao je Šižgorić."},
  "2015_jesen_A__43": {"A":"Renesansa je mnogo ranije razdoblje (15./16. st.) i ne prethodi neposredno romantizmu.","B":"Barok prethodi prosvjetiteljstvu, a ne neposredno romantizmu.","D":"Realizam slijedi nakon romantizma, a ne prethodi mu."},
  "2015_jesen_A__44": {"A":"Bijeg M. C. Nehajeva prikazuje propast intelektualca Đure Andrijaševića, a ne sukob Zgubidana i Kanonika.","C":"U registraturi A. Kovačića priča je o Ivici Kičmanoviću i Lauri, a ne o tim susjedima.","D":"Zlatarovo zlato Šenoe povijesni je roman o Dori Krupićevoj, a ne o Zgubidanu i Kanoniku."},
  "2015_jesen_A__45": {"A":"Bijeg Nehajeva prati odraslog intelektualca u krizi, a ne buntovnog sedamnaestogodišnjaka.","B":"Combray Prousta evocira djetinjstvo i sjećanje, a ne buntovnog tinejdžera koji prezire odrasle.","D":"Zločin i kazna Dostojevskog prikazuje studenta Raskoljnikova i njegov zločin, a ne lik tinejdžera buntovnika."},
  "2015_jesen_A__46": {"A":"Drago Gervais pjesnik je čakavske (istarske) lirike, a Z mojih bregov kajkavska je zbirka Domjanića.","C":"Fran Galović poznat je po kajkavskim Z mojih bregov... ne, autor je Domjanić; Galović je pisao Z mojih bregov? Galović nije autor te zbirke, nego Domjanić.","D":"Vladimir Nazor nije autor te kajkavske zbirke; napisao ju je Dragutin Domjanić."},
  "2015_jesen_A__47": {"A":"Romantizam je ranije razdoblje (sredina 19. st.), a Ivan Kozarac stvara početkom 20. st.","B":"Realizam završava krajem 19. st., dok Kozarac pripada modernističkom naraštaju.","D":"Druga moderna pojam je za poslijeratno razdoblje 20. st., a Kozarac stvara u (prvoj) moderni."},
  "2015_jesen_A__48": {"A":"Izabela nije lik te novele; tajanstvena violončelistica zove se Fanny.","C":"Laura je lik iz drugih djela, a ne Poljakinja iz Matoševa Camaa koja se zove Fanny.","D":"Vera nije ime te violončelistice; u Matoševoj noveli ona je Fanny."},
  "2015_jesen_A__49": {"A":"Horacije je Hamletov prijatelj i povjerenik, a ne osoba koja smišlja podmetanje kćeri i skrivanje iza saga.","B":"Klaudije je kralj, ali ovaj plan prisluškivanja iza zastora smišlja Polonije, Ofelijin otac.","C":"Laert je Ofelijin brat na odlasku, a navedeni plan iznosi njihov otac Polonije."},
  "2015_jesen_A__50": {"A":"Crna maslina nije Ujevićeva zbirka.","C":"Moj križ svejedno gori naslov je vezan uz drugog pjesnika, a ne uz Ujevića.","D":"Preobraženja je zbirka A. B. Šimića, a ne Tina Ujevića."},
  "2015_jesen_A__51": {"B":"Ivan Bunić Vučić barokni je pjesnik (17. st.), a Menčetić pripada renesansi.","C":"Petar Preradović romantičarski je pjesnik (19. st.), pa ne dijeli razdoblje s Menčetićem.","D":"Silvije Strahimir Kranjčević stvara u moderni/realizmu (kraj 19. st.), a ne u renesansi."},
  "2015_jesen_A__52": {"B":"Leone Glembay je sin koji optužuje oca, a navedene riječi o suživotu s majkom izgovara otac Ignjat.","C":"Puba Fabriczy sporedni je lik (odvjetnik), a ovu intimnu ispovijed iznosi Ignjat Glembay.","D":"Silberbrandt je kućni svećenik i ljubavnik barunice, a ne govornik ovih riječi o majci."},
  "2015_jesen_A__53": {"A":"Émile Zola francuski je naturalist, a ne talijanski pisac.","B":"Luis de Góngora španjolski je barokni pjesnik, ne talijanski.","C":"Pedro Calderón de la Barca španjolski je dramatičar, a ne predstavnik talijanske književnosti."},
  "2015_jesen_A__54": {"A":"Planine P. Zoranića pastoralno-alegorijski su roman, a ne komedija kao Plautov Škrtac.","B":"Ribanje i ribarsko prigovaranje P. Hektorovića ribarska je ekloga (poslanica), a ne komedija.","C":"Robinja H. Lucića svjetovna je drama (tragikomedija/poema), a ne komedija poput Škrca."},
  "2015_jesen_A__55": {"B":"Dubravka I. Gundulića pastoralna je drama, a navedeni stihovi pripadaju Pjesmi nad pjesmama.","C":"Judita M. Marulića biblijski je ep o Juditi i Holofernu, a ne ljubavni stihovi Pjesme nad pjesmama.","D":"Novela od Stanca M. Držića komedija je, a ne izvor tih biblijskih ljubavnih stihova."},
  "2015_jesen_A__56": {"B":"'Obrašćić' nije pravilan standardni oblik, dok je 'čamčić' točan umanjeni oblik.","C":"'Dječaćič' je pogrešno; pravilno je 'dječačić', pa nije točan odgovor.","D":"'Ručnićič' je pogrešno napisano; standardno je 'čamčić' kao točan oblik."},
  "2015_jesen_A__57": {"A":"'Odcijepiti' nije pravilno prema traženom obliku; točan je primjer 'otčepiti'.","B":"'Odpustiti' je pogrešno; pravilno je 'otpustiti' (jednačenje po zvučnosti).","D":"'Otšetati' je pogrešno; pravilno je 'otšetati'→'otšetati' se ne piše tako; točan je oblik 'otčepiti'."},
  "2015_jesen_A__58": {"A":"U toj inačici izostaju ili su pogrešni dijakritički znakovi ('ceš' umjesto 'ćeš'), pa nije pravilna.","B":"U toj inačici nedostaju zarezi oko umetnute rečenice i završna interpunkcija, pa nije pravilna.","C":"Ta je inačica označena kao kriva (pogrešan raspored ili oblik znakova), za razliku od pravilno interpungirane."},
  "2015_jesen_A__59": {"B":"'Policijsku Upravu' je pogrešno; 'uprava' kao opća sastavnica naziva piše se malim slovom.","C":"'Splitsko-Dalmatinske' je pogrešno; drugi dio složenoga pridjeva piše se malim slovom.","D":"'splitsko-dalmatinske' je pogrešno; prvi dio složenoga pridjeva u nazivu piše se velikim slovom."},
  "2015_jesen_A__60": {"A":"'Izmijeniti' nema dugouzlazni naglasak na traženom mjestu kao 'ljepota'.","C":"'Panj' je jednosložna riječ s kratkim (silaznim) naglaskom, a ne dugouzlaznim.","D":"'Prelomiti' nema dugouzlazni naglasak; on je u riječi 'ljepota'."},
  "2015_jesen_A__61": {"A":"'Stricu' je dativ, a ne vokativ; vokativ glasi 'striče'.","B":"'Učiteljico' jest vokativ ženskoga roda, ali traženi točan primjer u zadatku je 'kralje'.","D":"'Zvjezdice' je nominativ množine ili genitiv jednine, a vokativ glasi 'zvjezdice'/'zvjezdico'; traženi je točan 'kralje'."},
  "2015_jesen_A__62": {"B":"'-nositi' nije korijenski morfem, nego korijen i sufiks zajedno.","C":"'odnos-' uključuje prefiks 'od-', pa nije čisti korijen.","D":"'odnosi-' obuhvaća prefiks i dio sufiksa, a korijen je samo '-nos-'."},
  "2015_jesen_A__63": {"A":"'Za ičim' uz negaciju nije pravilno; uz nijekanje dolazi niječna zamjenica 'ni za čim'.","B":"'Za ničim' je pogrešno spojeno; prijedlog razdvaja zamjenicu, pa je pravilno 'ni za čim'.","C":"'Ni za ničim' sadržava dvostruko nijekanje zamjenice; pravilno je 'ni za čim'."},
  "2015_jesen_A__64": {"A":"Jedan morfem ne odgovara; 'učitelj' se rastavlja na korijen, sufiks i nastavak.","B":"Dva morfema nije točno; riječ ima tri morfema (uč-itel-j).","D":"Četiri morfema previše je; 'učitelj' sadržava tri morfema."},
  "2015_jesen_A__65": {"A":"'Zastane' je svršeni glagol (radnja dovršena u trenutku), a ne nesvršeni.","B":"'Je stao' je svršeni glagol; izriče dovršenu radnju.","D":"'Postadoše' je svršeni glagol (aorist), označuje dovršenu promjenu, a ne trajanje."},
  "2015_jesen_A__66": {"A":"'Bio došao' je pluskvamperfekt, a ne kondicional prvi.","C":"'Bude došao' je futur drugi, a ne kondicional prvi.","D":"'Je došao' je perfekt, a ne kondicional prvi."},
  "2015_jesen_A__67": {"A":"'Dodavajući' je glagolski prilog sadašnji nesvršenoga glagola 'dodavati', a ne svršenoga 'dodati'.","B":"'Dodajući' također je prilog sadašnji (od 'dodavati'), dok svršeni 'dodati' tvori prilog prošli.","C":"'Dodavavši' nije pravilan oblik; ispravan glagolski prilog prošli glasi 'dodavši'."},
  "2015_jesen_A__68": {"A":"'Vratila se dobra volja' ima glagolski predikat 'vratila se', a ne imenski.","B":"'Nema suradnje' glagolski je predikat (bezlični), a ne imenski.","C":"'Pokazala je dobru volju' glagolski je predikat s objektom, a ne imenski predikat."},
  "2015_jesen_A__69": {"A":"'Listu' je imenica na koju se atribut odnosi (glavna riječ sintagme), a ne sam atribut.","C":"'Rukopisom' je priložna oznaka/dodatak uz predikat, a ne imenski atribut imenice.","D":"'Obavijest' je subjekt rečenice, a ne atribut; nesročni atribut je 'papira'."},
  "2015_jesen_A__70": {"A":"Vrijeme se ne izriče; 'radi novih spoznaja' odgovara na pitanje s kojom namjerom, ne kada.","C":"Uzrok bi odgovarao na 'zbog čega', a 'radi' ovdje izriče cilj, dakle namjeru.","D":"Način se ne izriče; sintagma izražava svrhu čitanja, a ne kako se čita."},
  "2015_jesen_A__71": {"A":"Dvije surečenice premalo je; rečenica ima četiri predikata, dakle četiri surečenice.","B":"Tri surečenice nije točno; uz glavnu su tri zavisne, ukupno četiri.","D":"Pet surečenica previše je; predikata je četiri ('čuo je', 'svira', 'odavala', 'prebirale')."},
  "2015_jesen_A__72": {"A":"'Doprinjeo' je pogrešno; pravilno je 'doprinio'.","B":"'Voljeo' je pogrešno; pravilno je 'volio'.","C":"'Živila' je pogrešno; pravilno je 'živjela'."},
  "2015_jesen_A__73": {"B":"'Kod' i 'pri' bliskoznačni su (mjesto/blizina), a ne suprotni.","C":"'Na' i 'uz' nisu antonimi; oboje izriču prostorni odnos blizine/dodira.","D":"'Prema' i 'do' nisu suprotni; obje označuju smjer ili granicu kretanja."},
  "2015_jesen_A__74": {"A":"Egzonimi su domaći nazivi za strana zemljopisna imena, a 'ukulele' je naziv egzotičnoga predmeta.","C":"Eponimi su riječi nastale od vlastitih imena, a 'ukulele' nije izvedena iz osobnoga imena.","D":"Etnonimi su nazivi naroda, a 'ukulele' označuje glazbalo iz egzotične kulture, dakle egzotizam."},
  "2015_jesen_A__75": {"B":"Posuđenice iz mađarskoga su hungarizmi, a ne luzitanizmi.","C":"Posuđenice iz turskoga su turcizmi, a ne luzitanizmi.","D":"Posuđenice iz češkoga su bohemizmi, a ne luzitanizmi."},
  "2015_jesen_A__76": {"A":"Babina Greda naselje je (ojkonim), a ne ime uzvišenja; oronim je Petrova gora.","B":"Lonjsko polje nizinski je predio (nije gora), pa nije oronim.","D":"Rakov Potok ime je naselja/vodotoka, a ne planine, pa nije oronim."},
  "2015_jesen_A__77": {"A":"Prefiksalno-sufiksalna tvorba dodaje prefiks i sufiks jednoj osnovi, a 'gologlav' nastaje od dviju osnova.","C":"Sufiksalna tvorba ima jednu osnovu i sufiks, dok 'gologlav' spaja dvije osnove uz nulti sufiks.","D":"Srastanje spaja riječi bez spojnika i sufiksa, a 'gologlav' ima spojnik i tvorbeni sufiks."},
  "2015_jesen_A__78": {"A":"Apokrif je vrsta nekanonskoga vjerskog teksta, a prva hrvatska inkunabula je misal.","B":"Brevijar je molitvenik, no prva hrvatska tiskana knjiga (1483.) je misal.","D":"Psaltir je zbirka psalama, a prva hrvatska inkunabula bio je misal."},
  "2015_jesen_A__79": {"A":"Dva jezika je premalo prema traženom odgovoru (tri).","C":"Četiri jezika nije točan broj prema zadatku; odgovor je tri.","D":"Pet jezika ne odgovara traženom prvom hrvatskom rječniku; točan je broj tri."},
  "2015_jesen_A__80": {"A":"Ivan Belostenec leksikograf je kajkavsko-latinskoga rječnika, ali se ne ubraja u ozaljski krug u ovom zadatku.","B":"Jakov Mikalja autor je rječnika na štokavskoj osnovi, a ne pripadnik ozaljskoga kruga.","C":"Joakim Stulli kasniji je dubrovački leksikograf, a ne pripadnik ozaljskoga jezičnog kruga."},

  // 2015_jesen_B
  "2015_jesen_B__1": {"A":"Grudi se u pjesmi spominju ('grud joj otajno diše'), ali nisu opisane svilenima.","C":"Lice je opisano kao bijelo ('A lice mu bilo b'jelo'), a ne svilnim.","D":"Ruke se spominju u prvom stihu ('Dignuv na ruke ženu'), ali nisu doživljene svilenima; svilne su vjeđe."},
  "2015_jesen_B__2": {"A":"Gustativni podražaj odnosi se na okus, a u stihu nema motiva kušanja ni okusa.","B":"Olfaktivni podražaj vezan je uz njuh i miris, čega u podcrtanome stihu nema.","C":"Taktilni podražaj odnosi se na opip, a svjetlo i sjena doživljavaju se vidom, ne dodirom."},
  "2015_jesen_B__3": {"A":"Elipsa je izostavljanje dijela rečenice, a ovdje se ništa ne izostavlja, nego se gomila veznik 'I'.","B":"Epifora je ponavljanje istih riječi na kraju stihova, a ovdje se 'I' ponavlja na početku.","D":"Simploka spaja anaforu i epiforu, no ovdje se ponavlja samo početni veznik, bez podudaranja na kraju stihova."},
  "2015_jesen_B__4": {"B":"Nagomilana rima podrazumijeva nizanje istih rimnih riječi, a ovdje se rimuju naizmjenični stihovi.","C":"Obgrljena rima imala bi shemu abba, dok je ovdje shema abab.","D":"Parna rima rimovala bi susjedne stihove (aabb), no ovdje se rimuju naizmjenični stihovi."},
  "2015_jesen_B__5": {"A":"Tajanstvenost je tek dio ugođaja pjesme, ali doslovno značenje riječi 'notturno' jest noćni, a ne tajanstveni.","B":"Svjetlost je samo jedan motiv u pjesmi; 'notturno' ne znači svjetlosni, nego noćni ugođaj.","D":"Tišina se spominje u pjesmi, no 'notturno' ne znači tišinu, nego noć."},
  "2015_jesen_B__6": {"A":"Ašur se spominje kao smjer toka Tigrisa ('teče na istok od Ašura'), a ne kao zemlja bogata zlatom i oniksom.","B":"Eden je vrt iz kojega rijeka izvire, a ne zemlja u kojoj ima zlata i oniksa.","D":"Kuš je zemlja koju optječe Gihon, ali se uz nju ne navode zlato i oniks."},
  "2015_jesen_B__7": {"A":"Hranu Jahve dopušta sa svih stabala, no riječi 'načinit ću mu pomoć' odnose se na stvaranje žene, ne na hranu.","C":"Eden je već stvoren i čovjek je u njega postavljen prije tih riječi, pa se one ne odnose na stvaranje raja.","D":"Poslušnost se ne spominje; 'pomoć kao što je on' označava ženu, a ne čovjekovu poslušnost."},
  "2015_jesen_B__8": {"A":"Postavljanje u edenski vrt da ga obrađuje i čuva jest zadaća, ali ne zabrana.","B":"'Slobodno jedi' jest dopuštenje, izravna suprotnost zabrani.","D":"'Nije dobro da čovjek bude sam' jest Božja prosudba i uvod u stvaranje žene, a ne zabrana."},
  "2015_jesen_B__9": {"A":"Eden ne označava planinu, nego rajski vrt.","C":"Spoznaja se veže uz stablo spoznaje dobra i zla, a ne uz značenje riječi Eden.","D":"Stablo je motiv unutar vrta, ali Eden je sam vrt (raj), a ne stablo."},
  "2015_jesen_B__10": {"A":"Na grčki je preveden Stari zavjet u Septuaginti, a ne u Vulgati.","B":"Hebrejski je izvorni jezik Staroga zavjeta, a Vulgata je njegov prijevod, ne izvornik.","D":"Staroslavenski je jezik Ćirilova i Metodova prijevoda, a Vulgata je latinska."},
  "2015_jesen_B__11": {"A":"Kastelanov dvor postoji samo u Quijoteovoj mašti; stvarno se nalazi u krčmi.","B":"Svinjarov dom nije mjesto radnje; štrojač tek slučajno stiže u krčmu.","C":"Viteški dvor je Quijoteova obmana, a zbilja je skromna krčma."},
  "2015_jesen_B__12": {"A":"Loše pripremljena hrana opisana je, ali ga ona ne brine; brine ga što nije proglašen vitezom.","C":"Šljem doista ne može skinuti, no to nije razlog njegove zabrinutosti.","D":"Smiješan izgled spominje pripovjedač, ali Quijotea ne zabrinjava; muči ga neproglašenje vitezom."},
  "2015_jesen_B__13": {"A":"Don Quijote ne svira; on s mukom jede s navučenim šljemom.","B":"Kastelan se u ulomku ne pojavljuje kao svirač.","C":"Krčmar donosi hranu i poji ga vinom kroz trsku, ali ne svira."},
  "2015_jesen_B__14": {"A":"Didona je kartaška kraljica iz Vergilijeve Eneide, a ne Quijoteova odabranica.","C":"Fedra je lik iz grčke mitologije (Tezejeva žena), a ne Quijoteova ljubav.","D":"Ofelija je lik iz Shakespeareova Hamleta, a ne Quijoteova odabranica."},
  "2015_jesen_B__15": {"A":"Kriminalistički roman nastaje mnogo kasnije i Cervantes ga ne parodira.","B":"Pastirski roman nije meta parodije u Don Quijoteu.","C":"Povijesni roman nije predmet parodije; Quijote oponaša junake viteških romana."},
  "2015_jesen_B__16": {"B":"'Hoće mu se zlata i mlade žene' opisuje brijačeve pobude, a ne Jerkovo viđenje zagrebačkih prilika.","C":"Odbijanje zlatarice motiv je brijačeve osvete, a ne prikaz općega stanja u gradu.","D":"Riječi o pogaženoj djevičanskoj časti nisu Jerkov opis gradskih prilika nego optužba."},
  "2015_jesen_B__17": {"B":"U primjeru se ne govori o zatajivanju Pavlova posjeta, nego o širenju glasina.","C":"Glasine nisu proslava zasluga, nego su Pavla ozloglasile.","D":"Riječ je o tračevima o Pavlu i Dori, a ne o ljutnji zbog odnosa s Klarom."},
  "2015_jesen_B__18": {"A":"Antiteza je suprotstavljanje pojmova, a ovdje se nevolja uspoređuje, ne suprotstavlja.","B":"Eufemizam je ublažavanje neugodna izraza, čega u ovoj rečenici nema.","C":"Gradacija je stupnjevanje, no ovdje je riječ o usporedbi sa zlom godinom."},
  "2015_jesen_B__19": {"A":"'Hoćeš li da me ubije tuga' jest Pavlov očaj, a ne djelovanje intriganta.","B":"'Uhvati Jerko Pavla na oko' opisuje Jerkov pogled, a ne intrigantovu radnju.","D":"Pavlovo bijesno hvatanje sablje njegova je reakcija, a ne intrigantov čin."},
  "2015_jesen_B__20": {"A":"Blaž Štakor nije guravi brijač iz romana Zlatarovo zlato.","B":"Đuro Garuc nije lik guravoga brijača.","D":"Miloš Radak nije brijač intrigant; to je Grga Čokolin."},
  "2015_jesen_B__21": {"B":"'Znao je od svačesa nešto, a od svega ništa' opisuje površnost znanja, a ne odnarođenost.","C":"Zahtjev da ga drže učenjakom i aristokratom prikazuje taštinu, a ne gubitak nacionalnoga identiteta.","D":"Pozdravljanje kao podanika kneza pokazuje odnos podaništva, a ne odnarođenost."},
  "2015_jesen_B__22": {"A":"'Držao se plemićem' ne znači da se družio s plemićima, nego da se smatrao plemićem.","C":"Rečenica ne govori o podržavanju plemića, nego o vlastitu samodoživljaju.","D":"Ne radi se o razumijevanju plemića, nego o tome da se sam smatrao plemićem."},
  "2015_jesen_B__23": {"B":"Djed nije bio političar; tekst kaže da je bio krčmar.","C":"Učenjakom se držao otac (Antun), a ne djed; djed je bio krčmar.","D":"Djed nije bio vojnik nego krčmar."},
  "2015_jesen_B__24": {"A":"'Uzgoj' ovdje ne znači običaj, nego odgoj.","C":"Riječ se ne odnosi na prehranu, nego na način odgoja kojim mu je usađena taština.","D":"Sadnja je doslovno značenje koje ovdje ne odgovara; riječ je o odgoju čovjeka."},
  "2015_jesen_B__25": {"A":"Bogoslov Martin nije potpisnik pisma kao Gyӧrgy.","B":"Građanin Ante nije onaj koji se potpisuje mađariziranim imenom Gyӧrgy.","C":"Prijatelj Alfred nije pošiljatelj pisma; Gyӧrgy je mađarski oblik imena Juraj."},
  "2015_jesen_B__26": {"B":"'Onda sam došla tebi u kuću' govori o prelasku u brak, a ne izravno o očevoj vlasti nad njezinim životom.","C":"'Sve si uredio po svom ukusu' upućeno je Helmeru i odnosi se na brak, ne na oca.","D":"'Ti si tako htio' upućeno je mužu, a pitanje traži primjer očeve vlasti."},
  "2015_jesen_B__27": {"B":"Nora brak ne doživljava kao uzajamno uveseljavanje, nego kao potiskivanje svoje osobnosti.","C":"Nora upravo poriče potpuno razumijevanje; tvrdi da nije bila ono što jest.","D":"Brak nije doživljen kao izbjegavanje obveza, nego kao gušenje njezine osobnosti."},
  "2015_jesen_B__28": {"A":"Zamjenica 'to' ne odnosi se na djetinjstvo, nego na drukčije mišljenje koje je krila.","B":"'To' se ne odnosi na grijeh, nego na vlastite stavove koje je morala skrivati.","C":"Zamjenica se ne odnosi na ljubav, nego na drukčije mišljenje pred ocem."},
  "2015_jesen_B__29": {"A":"Suprugovo promaknuće u banci nije okidač Norine promjene; presudno je otkrivanje krivotvorene mjenice.","C":"Dolazak prijateljice Kristine nije uzrok preokreta u Norinu odnosu prema mužu.","D":"Smrt doktora Ranka nije događaj koji mijenja Norin odnos prema Helmeru."},
  "2015_jesen_B__30": {"A":"Nora se ne seli prijateljici; ona napušta obitelj radi vlastita identiteta.","C":"Nora ne odlazi s djecom, nego ih ostavlja kad napušta dom.","D":"Nora se ne vraća ocu; otac je već mrtav, a ona odlazi u samostalan život."},
  "2015_jesen_B__31": {"B":"Angelika ga ne nagovara da se odrekne obitelji, nego da razumno sagleda situaciju.","C":"Ona ne traži da se odrekne talenta; naprotiv, ističe njegov velik talent.","D":"Angelika mu ne savjetuje utjehu u vjeri, nego u razumnu i jasnu pogledu na stvari."},
  "2015_jesen_B__32": {"A":"'Svijetli talent' je pozitivan, ali nije suprotnost čistoći ruke; suprotnost je 'tamna glavobolja'.","B":"'Mogućnost spasa' nije pojmovna suprotnost čistoj ruci.","C":"'Superiorna inteligencija' nije suprotstavljena čistoj ruci; kontrast čine čisto i tamno."},
  "2015_jesen_B__33": {"A":"Leone nije glazbenik; njegov je talent slikarski.","B":"Leone nije glumac, nego slikar.","C":"Leoneov talent nije književni, nego slikarski."},
  "2015_jesen_B__34": {"A":"Podcrtane riječi ne odnose se na bankarske poslove, nego na izlazak iz obiteljske glembajevštine.","C":"Ne radi se o svijetu umjetnosti, nego o obiteljskim odnosima iz kojih bi se htio izvući.","D":"Ne misli na život u tuđini, nego na oslobođenje od glembajevskih obiteljskih sukoba."},
  "2015_jesen_B__35": {"B":"Beatrice mu nije pomajka, nego šogorica, udovica njegova brata.","C":"Beatrice nije Leoneova sestra.","D":"Beatrice mu nije majka, nego šogorica."},
  "2015_jesen_B__36": {"A":"Svjetska bol i potraga za smislom obilježja su romantizma, a ne baroka.","C":"Oponašanje društvene zbilje poput zrcala odlika je realizma, ne baroka.","D":"Slijeđenje antičkih uzora svojstveno je klasicizmu, a ne baroku."},
  "2015_jesen_B__37": {"A":"Metonimija je zamjena pojma srodnim pojmom, a u naslovu je riječ o spoju suprotnosti.","C":"Paradoks je prividno proturječna tvrdnja, no ovdje su u sintagmi spojeni suprotni pojmovi (oksimoron).","D":"Personifikacija pridaje ljudska svojstva neživomu, čega u naslovu nema."},
  "2015_jesen_B__38": {"A":"Ditiramb je svečana pjesma posvećena Dionizu, a ne kratak oblik s poantom.","C":"Elegija je tužaljka, a ne kratka pjesma s oštroumnom poantom.","D":"Himna je slavljenička pjesma, a ne kratak oblik sa zaoštrenim završetkom."},
  "2015_jesen_B__39": {"B":"Stih od sedam slogova nije septima; septima je strofa od sedam stihova.","C":"Septima nije pjesma od sedam strofa, nego strofa od sedam stihova.","D":"Septima nije stih od sedam stopa, nego sedmerostišna strofa."},
  "2015_jesen_B__40": {"A":"Rečenica nije iz Posljednjih Stipančića; opisuje Ivicu Kičmanovića pred vatrom.","B":"Citat nije iz Povratka Filipa Latinovicza, nego iz romana U registraturi.","D":"Rečenica nije iz Zlatarova zlata, nego iz Kovačićeva romana U registraturi."},
  "2015_jesen_B__41": {"A":"Antigona je lik iz grčke mitologije i Sofoklove tragedije, a ne biblijski lik.","B":"Beatrice je Danteova ljubav iz Božanstvene komedije, a ne biblijski lik.","C":"Fedra je lik grčke mitologije, a ne biblijska junakinja."},
  "2015_jesen_B__42": {"A":"Rečenicu o davanju punomoći za izjavu izgovara Puba, a ne Ignjat Glembay.","C":"Tvrdnju o vikaru kao baruničinu ljubavniku izgovara Leone, a ne Ignjat.","D":"Riječi o jedanaest godina izbivanja iz straha pred zločinom govori Leone, a ne Ignjat."},
  "2015_jesen_B__43": {"A":"Dante Alighieri pisac je epa (Božanstvena komedija), a ne začetnik novele.","B":"Petrarca je lirik (Kanconijer), a ne utemeljitelj novele.","D":"Cervantes je romanopisac iz kasnijega razdoblja, a ne začetnik novele."},
  "2015_jesen_B__44": {"A":"Cvijet sa raskršća Matoševa je novela, a ne pjesnička zbirka.","C":"Misao na vječnost novela je Janka Leskovara, a ne zbirka pjesama.","D":"Ruke Ranka Marinkovića zbirka su novela, a ne pjesnička zbirka."},
  "2015_jesen_B__45": {"B":"Hanibal Lucić pripada kasnijemu naraštaju i nije zastupljen u Ranjininu zborniku.","C":"Ivan Gundulić barokni je pjesnik i nije u Ranjininu zborniku.","D":"Petar Hektorović nije među pjesnicima Zbornika Nikše Ranjine."},
  "2015_jesen_B__46": {"A":"Arthur Rimbaud je simbolist, a ne enciklopedist.","B":"Jean Racine je klasicistički tragičar, a ne enciklopedist.","C":"Molière je klasicistički komediograf, a ne enciklopedist."},
  "2015_jesen_B__47": {"A":"Verterizam ne proizlazi iz Balzacova opusa.","B":"Pojam ne potječe od Cervantesa, nego od Goethea.","C":"Verterizam nije vezan uz Flauberta, nego uz Goetheova Werthera."},
  "2015_jesen_B__48": {"A":"Dubravku nije napisao Ivan Bunić Vučić.","C":"Dubravka nije Držićevo djelo; on je autor Dunda Maroja i Novele od Stanca.","D":"Mavro Vetranović nije autor Dubravke, nego Ivan Gundulić."},
  "2015_jesen_B__49": {"A":"Danicu je uređivao Ljudevit Gaj u doba ilirizma, a ne Šenoa.","B":"Kolo nije časopis koji je uređivao Šenoa.","C":"Vijavica je zbirka Antuna Branka Šimića, a ne časopis koji je Šenoa uređivao."},
  "2015_jesen_B__50": {"A":"Horvatov sloga i zjedinjenje djelo je Tituša Brezovačkoga, a ne Mihanovića.","C":"Kip domovine vu početku leta 1831. pjesma je drukčijega autora, a ne Mihanovićeva.","D":"Rodu o jeziku napisao je Petar Preradović, a ne Mihanović."},
  "2015_jesen_B__51": {"A":"Svakidašnju jadikovku nije napisao Dragutin Tadijanović.","B":"Pjesma nije Kaštelanova, nego Ujevićeva.","C":"Slavko Mihalić nije autor Svakidašnje jadikovke."},
  "2015_jesen_B__52": {"B":"Klasicizam ne prethodi baroku, nego se s njime preklapa i slijedi ga.","C":"Romantizam dolazi u 19. st., znatno poslije baroka.","D":"Realizam slijedi tek sredinom 19. st., a ne prethodi baroku."},
  "2015_jesen_B__53": {"A":"André Breton autor je manifesta nadrealizma, a ne dadaizma.","B":"Marinetti je napisao manifest futurizma, a ne dadaizma.","D":"Majakovski je vezan uz (ruski) futurizam, a ne uz manifest dadaizma."},
  "2015_jesen_B__54": {"A":"Ivan Kozarac stvarao je u razdoblju realizma/moderne, a ne druge moderne.","C":"Silvije Strahimir Kranjčević pjesnik je realizma i moderne, a ne druge moderne.","D":"Vladimir Vidrić pripada hrvatskoj moderni s prijelaza 19. na 20. st., a ne drugoj moderni."},
  "2015_jesen_B__55": {"B":"Stihovi nisu Krležini, nego Matoševi (sonet Srodnost).","C":"Petar Preradović nije autor ovih stihova.","D":"Vladimir Vidrić nije autor ovoga soneta o smrti drage."},
  "2015_jesen_B__56": {"B":"'Skaćući' nije točno; pravilno je 'skačući' (palatalizacija k→č).","C":"'Trćeći' nije točno; pravilno je 'trčeći'.","D":"'Vićući' nije točno; pravilno je 'vičući'."},
  "2015_jesen_B__57": {"A":"'Rasčistiti' nije točno jer 'z' ispred 'č' prelazi u 'š' (raščistiti).","C":"'Razčistiti' nije točno; provodi se jednačenje z→š.","D":"'Ražčistiti' nije točno; ispravan je oblik raščistiti."},
  "2015_jesen_B__58": {"A":"U 'krivac' (kri-vac) samoglasnik 'i' nosi slog, pa 'r' nije slogotvoran.","C":"U 'strana' (stra-na) slog nosi 'a', a 'r' nije slogotvoran.","D":"U 'vranac' (vra-nac) slog nosi 'a', pa 'r' nije slogotvoran."},
  "2015_jesen_B__59": {"B":"'Božica' je opća imenica i piše se malim slovom, pa veliko 'Božica' nije ispravno.","C":"'Zeusova' je posvojni pridjev od vlastita imena i piše se velikim slovom, pa 'zeusova' nije točno.","D":"Pogrešno su napisani i 'Božica' (treba malo) i 'zeusova' (treba veliko)."},
  "2015_jesen_B__60": {"A":"U 'ispustiti' (iz+pustiti) dogodila se samo jedna promjena — jednačenje po zvučnosti z→s.","C":"U 'potpaliti' (pod+paliti) provedeno je samo jednačenje po zvučnosti d→t.","D":"U 'rasipati' (raz+sipati) dogodila se jedna promjena — jednačenje po zvučnosti z→s."},
  "2015_jesen_B__61": {"B":"'Lagati > lažem' primjer je jotacije (g+j→ž), a ne palatalizacije.","C":"'Puhati > pušem' primjer je jotacije (h+j→š), a ne palatalizacije.","D":"'Vući > vučem' nije palatalizacija; ovdje nema alternacije zadnjonepčanika ispred prednjega samoglasnika kao u palatalizaciji."},
  "2015_jesen_B__62": {"A":"Dva morfema nisu dovoljna; 'pjevač' ima korijen, sufiks i nulti morfem (tri).","C":"Četiri morfema je previše; 'pjevač' ima tri morfema.","D":"Pet morfema je previše; 'pjevač' ima tri morfema."},
  "2015_jesen_B__63": {"A":"'Košarka' u nominativu jednine ima nastavak '-a', pa nema nulti morfem.","B":"'Studio' u nominativu jednine ima nastavak '-o', pa nema nulti morfem.","D":"'Selo' u nominativu jednine ima nastavak '-o', pa nema nulti morfem."},
  "2015_jesen_B__64": {"B":"'Starija brata' nije točno; uz imenicu u genitivu treba određeni oblik 'starijega brata'.","C":"'Najoštrija pera' nije točno; ispravno je 'najoštrijega pera'.","D":"'Dan je lijepi' nije točno; u predikatu treba neodređeni oblik 'Dan je lijep'."},
  "2015_jesen_B__65": {"A":"'Dantejevo' nije točno jer se osnovi ne dodaje 'j'.","C":"'Dantovo' nije točno jer se osnova imena Dante ne skraćuje.","D":"'Dantevo' nije točno; pravilno je Danteovo (Dante + ov + o)."},
  "2015_jesen_B__66": {"A":"U 'Nedostajao joj je Luka' ime je u nominativu (vršitelj radnje), a ne u akuzativu.","C":"U 'Nije mogla bez Luke' ime je u genitivu (uz prijedlog 'bez'), a ne u akuzativu.","D":"U 'Brinula se o Luki' ime je u lokativu (uz prijedlog 'o'), a ne u akuzativu."},
  "2015_jesen_B__67": {"A":"'Na' je prijedlog, a ne prilog.","B":"'Mjesnome' je pridjev koji opisuje imenicu 'trgu', a ne prilog.","C":"'Pokraj' je prijedlog, a ne prilog."},
  "2015_jesen_B__68": {"A":"'Antea' nije točan genitiv; ime Ante u standardu nema takav oblik genitiva.","C":"'Anteta' nije točan genitiv imena Ante.","D":"'Anta Tresić Pavičića' nije točno jer su pogrešni i oblik imena i prvi dio prezimena."},
  "2015_jesen_B__69": {"B":"'Svoju' je posvojna (povratna) zamjenica, a ne osobna.","C":"'Nečega' je neodređena zamjenica, a ne osobna.","D":"'To' je pokazna zamjenica, a ne osobna."},
  "2015_jesen_B__70": {"B":"'Hlače' su pluralia tantum (imenica samo u množini), a ne zbirna imenica.","C":"'Naočale' su pluralia tantum, a ne zbirna imenica.","D":"'Saonice' su pluralia tantum, a ne zbirna imenica."},
  "2015_jesen_B__71": {"A":"'Ga' nije atribut; ono ne opisuje imenicu, nego je objekt glagola 'dati'.","C":"'Ga' nije priložna oznaka; ono je predmet radnje, dakle objekt.","D":"'Ga' nije subjekt; subjekt je vršitelj radnje, a 'ga' je predmet radnje (objekt)."},
  "2015_jesen_B__72": {"A":"'Brzo pisanje' rezultat je slaganja (pridjev/prilog uz imenicu), a ne upravljanja.","B":"'Lijepo pismo' rezultat je slaganja pridjeva i imenice, a ne upravljanja.","D":"'Piše brzo' rezultat je pridruživanja (priložna oznaka), a ne upravljanja padežom."},
  "2015_jesen_B__73": {"A":"Mjesne rečenice izriču mjesto i uvodi ih veznik 'gdje', čega ovdje nema.","C":"Načinske rečenice izriču način radnje, a ne dopuštenje usprkos kojemu se radnja zbiva.","D":"Uzročne rečenice izriču uzrok (jer, budući da), a ovdje je veznik 'iako' (dopusni)."},
  "2015_jesen_B__74": {"A":"'Pitala se kakva ju je nevolja snašla' subjektna je rečenica (sadržaj se odnosi na glagol 'pitati se'), a ne atributna.","C":"'Rekao je da će zakasniti' objektna je rečenica, a ne atributna.","D":"'Izgleda da će padati kiša' predikatna/subjektna je rečenica, a ne atributna."},
  "2015_jesen_B__75": {"B":"'Imenica – glagol' nazivi su različitih gramatičkih kategorija, a ne istoznačnice.","C":"'Rijeka – rijeka' su homonimi (vlastito i opće ime), a ne sinonimi.","D":"'Dan – noć' su antonimi (suprotnoznačnice), a ne sinonimi."},
  "2015_jesen_B__76": {"A":"Posuđenice iz španjolskoga su hispanizmi, a ne bohemizmi.","B":"Posuđenice iz francuskoga su galicizmi, a ne bohemizmi.","C":"Posuđenice iz poljskoga su polonizmi, a ne bohemizmi."},
  "2015_jesen_B__77": {"B":"Rečenica o predizbornoj kampanji pripada publicističkomu stilu, a ne administrativnomu.","C":"Tvrdnja o monološko-asocijativnoj strukturi pripada znanstvenomu stilu.","D":"Tvrdnja da riječ logos nije hrvatska pripada razgovorno-poučnomu izrazu, a ne administrativnomu stilu."},
  "2015_jesen_B__78": {"B":"Frazem ne znači da su problemi nerješivi, nego da su zanemarivi.","C":"Frazem se ne odnosi na učestalost, nego na beznačajnost problema.","D":"Frazem ne znači velike probleme, nego upravo suprotno — sitnicu."},
  "2015_jesen_B__79": {"A":"'Marku' je u dativu, a kanonski (rječnički) oblik imenice jest nominativ jednine.","C":"'Bijaše' je imperfekt glagola, a kanonski je oblik infinitiv (biti), pa nije u kanonskome obliku.","D":"'Zanimljivo' je oblik pridjeva u srednjem rodu, a ne kanonski (osnovni) oblik."},
  "2015_jesen_B__80": {"B":"Muka svete Margarite nije glagoljički, nego latinični spomenik.","C":"Poljički statut nije primaran primjer glagoljičkoga teksta poput Bašćanske ploče.","D":"Šibenska molitva pisana je latinicom, a ne glagoljicom."},

  // 2015_ljeto_A
  "2015_ljeto_A__1": {"B":"'Smion' ne znači opasan; riječ označuje odvažnost, a ne prijetnju.","C":"'Smion' nema veze sa smiješnim; ne radi se o komičnoj slici.","D":"'Smion' ne znači visok; visina tornja iskazana je drugim epitetima ('vitka')."},
  "2015_ljeto_A__2": {"A":"Toranj je doživljen vizualno (obris, oblik), a ne kao zvuk.","B":"Jabuka je prikazana bojom (bakar zelenkaste boje), dakle vizualnim, ne auditivnim podražajem.","C":"Magla je dana vizualno ('olovne i tmaste'), a ne zvukom."},
  "2015_ljeto_A__3": {"A":"Stih donosi samo vizualne i prostorne podatke (stijene, bridovi), bez spoja različitih osjetila.","C":"Spominje se isključivo boja (vizualni podražaj), pa nema prepletanja osjetila.","D":"Stih je slikovit i ironičan, ali ne spaja podražaje različitih osjetila."},
  "2015_ljeto_A__4": {"A":"'Boje zelenkaste' samo je epitet boje, bez pridavanja ljudskih osobina.","B":"'Magle olovne' epitet je koji opisuje težinu i boju magle, a ne personifikacija.","D":"'Grmljavine glas' jest spoj zvuka i pojave, ali ne pripisuje predmetu ljudsku osobinu kao personifikacija."},
  "2015_ljeto_A__5": {"A":"Shakespeareov sonet ima 14 stihova kao i ovaj osnovni dio; 'rep' znači stih više, a ne manje.","B":"Nejednak broj slogova nije obilježje soneta s repom; 'rep' se odnosi na dodatni stih.","C":"Prijenos rime iz katrena u tercine nije ono što čini sonet 'sonetom s repom'."},
  "2015_ljeto_A__6": {"B":"Merkur ne pogubljuje nikoga; on prenosi Jupiterovu poruku.","C":"Merkur ne proriče budućnost; proročanstvo o Eneji dolazi od usuda, a Merkur ga samo prenosi.","D":"Merkur nije svećenik, nego bog glasnik koji nosi nalog."},
  "2015_ljeto_A__7": {"B":"Stih je retoričko pitanje, prijekor zbog zanemarivanja sina, a ne navještaj budućnosti.","C":"Riječ je o pitanju i prijekoru, a ne o proricanju onoga što će se dogoditi.","D":"Stih je zapovijed (da otplovi), a ne proročanstvo o budućoj sudbini."},
  "2015_ljeto_A__8": {"A":"U ulomku se ne kaže da vođi ide samo do slave, nego da zaboravlja zadaću.","C":"Vođa ne želi osvajati tuđe zemlje; prijekor je zbog zaboravljanja vlastite sudbine.","D":"Bog ga ne kori što želi otploviti u Kartagu, nego što ondje krzma i zaboravlja dužnosti."},
  "2015_ljeto_A__9": {"B":"'Krzma' ne znači patiti, nego oklijevati i odugovlačiti.","C":"'Krzma' ne znači ratovati; upravo se prekorava jer ne radi ono što treba.","D":"'Krzma' ne znači vladati, nego besposleno oklijevati."},
  "2015_ljeto_A__10": {"A":"Jupiter šalje Merkura, ali nije on taj koji je vođu spasio u Troji.","C":"Merkur je glasnik u ovom prizoru, a ne spasitelj iz Troje.","D":"Sin (Askanije) ne spašava vođu; život mu je spasila božica majka."},
  "2015_ljeto_A__11": {"B":"Franciska nije osoba čije se oči uspoređuju s dvocijevkom; usporedba se odnosi na lik sa slike.","C":"Kamenski je promatrač koji osjeća pogled, a ne onaj čije su oči poput dvocijevke.","D":"Whistler je slikar portreta, a ne lik čije oči gledaju kao dvocijevka."},
  "2015_ljeto_A__12": {"A":"'Obesvećivati' ne znači dovesti do nesvjestice (onesvijestiti).","C":"'Obesvećivati' ne znači osvetiti se nego oskvrnuti.","D":"'Obesvećivati' ne znači dovesti k svijesti, nego skrnaviti svetinju."},
  "2015_ljeto_A__13": {"A":"'Koštunjavim rukama' epitet je u uobičajenom redoslijedu (ispred imenice), bez inverzije.","C":"'Nespokojne oči' epitet je u redovitom položaju ispred imenice, dakle bez inverzije.","D":"'Mrkog portraita' epitet stoji ispred imenice u uobičajenom redu, pa nema inverzije."},
  "2015_ljeto_A__14": {"A":"Camao nije gavran; riječ je o egzotičnoj ptici koja govori.","B":"Camao nije orao.","D":"Camao nije slavuj, nego papagaj."},
  "2015_ljeto_A__15": {"A":"Camao nije bajka; nema čudesnih bajkovitih elemenata ni tipične strukture bajke.","B":"Camao nije basna; likovi nisu personificirane životinje s poukom.","D":"Camao nije roman, nego kraće prozno djelo zaokružene radnje."},
  "2015_ljeto_A__16": {"A":"Donošenje ribe (morskih listova) bio je svadbeni dar, a ne šala.","C":"Skrivanje boljih komada mesa nije rođakova šala, nego ono što muči nezadovoljne goste.","D":"U ulomku se rođakova šala sastoji u prskanju vode, a ne u nepristojnim riječima."},
  "2015_ljeto_A__17": {"A":"Šutnja majke Bovary nije znak popustljivosti, nego povrijeđenosti jer je zaobiđena.","C":"Umor nije razlog njezine šutnje; uvrijeđena je što je nisu pitali za savjet.","D":"Nije stidljivost razlog šutnji, nego osjećaj zapostavljenosti."},
  "2015_ljeto_A__18": {"A":"Rečenica pokazuje rođakovu uvrijeđenost (smatra Rouaulta oholim), a ne prijetvornost.","C":"Rečenica iskazuje povrijeđenost majke Bovary, a ne dvoličnost rođaka.","D":"Rečenica prikazuje muževljevu nemarnost, a ne prijetvornost rođaka."},
  "2015_ljeto_A__19": {"A":"Gospodin Rouault sprječava nepristojnu šalu, ali se ne prikazuje kako se želi prikazati boljim no što jest.","C":"Majka Bovary u ulomku je povrijeđena i šuti, ne nastoji se prikazati boljom.","D":"Otac Bovary nije lik koji u ovom ulomku nastoji podići svoj ugled."},
  "2015_ljeto_A__20": {"B":"Charles Bovary nije pravnik, pa 'ozbiljno zvanje' nije pravničko.","C":"Zet nije svećenik, nego liječnik.","D":"Zet nije učitelj; 'ozbiljno zvanje' odnosi se na liječništvo."},
  "2015_ljeto_A__21": {"A":"'Prijelazne nijanse' označuju normalna stanja koja generaciji nedostaju, a ne sam način života.","B":"'Jasnija pokoljenja' upućuju na druge naraštaje, a ne na način života pripovjedačeve generacije.","D":"'Oslonac razuma' ne opisuje način života te generacije obilježen krajnostima."},
  "2015_ljeto_A__22": {"A":"'Eksplozija panike' suprotnost je duhovnoj ravnoteži, a ne njoj blizak pojam.","C":"'Vrsta samozaštite' nije isto što i uravnoteženo duhovno stanje.","D":"'Zatajivanje duha' označuje apatiju, a ne duhovnu ravnotežu."},
  "2015_ljeto_A__23": {"B":"Pripovjedač nije ravnodušan; pokazuje snažnu zaokupljenost sudbinom generacije.","C":"On se generaciji ne izruguje, nego suosjeća i samokritičan je.","D":"Nema divljenja; odnos je suosjećajan i bolan, a ne ushićen."},
  "2015_ljeto_A__24": {"A":"'Tavorenje' nije paničarenje, nego mlitavo, jadno preživljavanje.","B":"'Tavorenje' ne znači promatrati nego mučno životariti.","C":"'Tavorenje' nije sažalijevanje, nego besciljno životarenje."},
  "2015_ljeto_A__25": {"A":"Fonostilem nastaje glasovnim sredstvima, a ovdje je riječ o grafičkom isticanju velikim slovima.","C":"Morfostilem je obličko stilsko sredstvo, a ne isticanje pisanjem verzalom.","D":"Sintaktostilem se tiče rasporeda i ustroja rečenice, a ne grafičkog isticanja."},
  "2015_ljeto_A__26": {"A":"Borba bogova protiv smrti nije spomenuta; uzaludan je napor samoga grada.","C":"Edipov otpor nije ono što svećenik smatra uzaludnim, nego napor grada protiv nesreće.","D":"Svećenik ne kaže da su molitve uzaludne; uzaludan je trud grada da se izbavi."},
  "2015_ljeto_A__27": {"B":"Svećenik ne traži da Edip sluša zapovijedi boga, nego da pomogne narodu.","C":"Nema spomena pomoći u bijegu; traži se spas grada.","D":"Ne traži se gradnja oltara, nego izbavljenje naroda od pošasti."},
  "2015_ljeto_A__28": {"A":"'Krilo majčino' odnosi se na umiranje nerođene djece, a ne na ime grada.","B":"'Božanstvo smrti' označuje silu koja širi kugu, a ne grad.","D":"'Crn Had' jest podzemlje koje se puni mrtvima, a ne naziv za grad."},
  "2015_ljeto_A__29": {"A":"Stih je metaforičan (slabi za let), ali nema zamjene jednog pojma drugim po povezanosti.","C":"Stih opisuje neplodnost zemlje doslovno, bez metonimijske zamjene.","D":"'Molbe naše čuj' nije metonimija nego izravan zaziv."},
  "2015_ljeto_A__30": {"B":"Otkriće ubojstva tebanskoga kralja zbiva se poslije; 'davna hrabrost' odnosi se na raniji čin sa Sfingom.","C":"Suprotstavljanje Kreontu nije ono na što upućuje 'davna hrabrost'.","D":"Svladavanje morske nemani nije Edipov pothvat; on je riješio Sfinginu zagonetku."},
  "2015_ljeto_A__31": {"A":"Nora nije očekivala da joj suprug pročita pismo, nego da je obrani.","B":"Nije očekivala strpljivost, nego da uzme krivnju na sebe i zaštiti je.","C":"Nije očekivala da je zaposli, nego da je obrani pred svijetom."},
  "2015_ljeto_A__32": {"A":"Helmer joj ne zamjera bračnu nevjeru; riječ je o krivotvorini i njezinoj nepromišljenosti.","C":"Predmet prijekora nije rastrošnost, nego nerazboritost.","D":"Helmer joj ne zamjera zanemarivanje djece, nego to što razmišlja kao nerazumno dijete."},
  "2015_ljeto_A__33": {"B":"Norina spoznaja nije strah od osude sredine, nego uvid u vlastitu zabludu o braku.","C":"Ne žali za sigurnošću; razočarana je jer shvaća da je živjela uz stranca.","D":"Nije riječ o strepnji pred budućnošću, nego o spoznaji prošle zablude."},
  "2015_ljeto_A__34": {"B":"Rečenica iskazuje Norinu spoznaju o braku, bez preuveličavanja kao u hiperboli.","C":"Rečenica je prijekor i poredba s djetetom, a ne hiperbola.","D":"Rečenica je Norina ocjena Helmera, bez preuveličavanja svojstvenog hiperboli."},
  "2015_ljeto_A__35": {"A":"Lakoumno trošenje novca nije 'ta nesreća'; ona se odnosi na krivotvorenje potpisa.","C":"Smrt oca nije 'nesreća' iz rečenice, nego krivotvorenje njegova potpisa zbog zajma.","D":"Rankova bolest nije ono na što upućuje 'ta nesreća'."},
  "2015_ljeto_A__36": {"A":"Savršenstvo forme i umjetnost radi umjetnosti obilježje su esteticizma, a ne ekspresionizma.","C":"Veličanje strojeva i napretka obilježje je futurizma, a ne ekspresionizma.","D":"Naglasak na psihoanalizi i potisnutom obilježje je nadrealizma, a ne ekspresionizma."},
  "2015_ljeto_A__37": {"A":"Razrješenje sukoba zahvatom božanstva jest 'deus ex machina', a ne digresija.","B":"Zazivanje muza na početku epa jest invokacija, a ne digresija.","C":"Početak bez uvoda, u srce zbivanja, jest 'in medias res', a ne digresija."},
  "2015_ljeto_A__38": {"A":"Grdan je lik iz drugoga djela, a ne sanjar iz Perivoja od Slave.","B":"Miljenko nije lik koji u snu vidi vilu u Perivoju od Slave.","C":"Stanac je lik iz Držićeve Novele od Stanca, a ne iz Zoranićevih Planina."},
  "2015_ljeto_A__39": {"B":"Elegija je tužbalička lirska vrsta, a ne izvor tragedije.","C":"Epitaf je natpis na grobu, a ne osnova iz koje se razvila tragedija.","D":"Himna je svečana pohvalna pjesma, a tragedija je nastala iz ditiramba."},
  "2015_ljeto_A__40": {"A":"Odiseja je ep, dakle pripada epskome, a ne dramskome rodu.","B":"Metamorfoze su epsko-pripovjedno djelo, a ne drama.","D":"Eneida je ep, pripada epskome rodu, a ne dramskome."},
  "2015_ljeto_A__41": {"A":"Anadiploza ponavlja kraj jednoga stiha na početku idućega, čega ovdje nema.","B":"Anafora bi ponavljala istu riječ na početku stihova, a ovdje se ponavlja na kraju.","D":"Simploka spaja anaforu i epiforu, ali početci stihova nisu jednaki, pa nije simploka."},
  "2015_ljeto_A__42": {"A":"Šižgorić nije pripadao dubrovačkome humanističkom krugu.","B":"Šižgorić nije hvarski, nego šibenski humanist.","C":"Šižgorić nije splitski, nego šibenski humanist."},
  "2015_ljeto_A__43": {"B":"Prvi putopisni pjesnički zapis s pravog putovanja vezuje se uz Zoranića/druge autore, a ne uz Menčetića.","C":"Autor prve hrvatske svjetovne drame nije Menčetić (npr. Tirena je Držićeva), iako je Menčetić petrarkist.","D":"Prvi hrvatski roman u stihu i prozi (Planine) napisao je Zoranić, a ne Menčetić."},
  "2015_ljeto_A__44": {"A":"Maroje je stari škrti otac, a ne snalažljivi 'kralj od ljudi'.","B":"Maro je rasipni sin, a ne lik koji vlada situacijom poput vjertuoza.","D":"Popiva je sluga, ali opis dovitljivog gospodara situacije odnosi se na Pometa."},
  "2015_ljeto_A__45": {"A":"Góngora nije francuski pisac.","B":"Góngora nije njemački pisac.","D":"Góngora nije talijanski, nego španjolski barokni pjesnik."},
  "2015_ljeto_A__46": {"A":"Bianchon je student medicine, a ne odbjegli robijaš.","B":"Rastignac je mladi ambiciozni student, a ne robijaš.","C":"Grof de Restaud nije odbjegli robijaš, nego pripadnik visokoga društva."},
  "2015_ljeto_A__47": {"B":"Izmjena realizma i romantičarskih hajdučkih scena obilježje je Šenoina, a ne Nehajeva Bijega.","C":"Diplomatsko putovanje u Osmansko Carstvo nije tema Bijega.","D":"Propast senjske patricijske obitelji nije sadržaj Bijega (vezuje se uz druga djela)."},
  "2015_ljeto_A__48": {"B":"Šimić nije krugovaš; krugovaši djeluju nakon Drugoga svjetskog rata.","C":"Šimić ne stvara u realizmu, nego u ekspresionizmu.","D":"Šimić nije moderna, nego ekspresionist (međuratno razdoblje)."},
  "2015_ljeto_A__49": {"A":"Antun Vrančić nije glavni humanistički lik Pasa u trgovištu.","B":"Ilija Crijević nije lik toga romana.","D":"Juraj Šižgorić nije glavni lik Araličina romana."},
  "2015_ljeto_A__50": {"A":"Tadijanović stvara kasnije (međuratno i poslijeratno doba), a ne u moderni.","C":"Pupačić pripada poslijeratnom naraštaju, a ne moderni.","D":"Kaštelan pripada poslijeratnoj književnosti, a ne moderni."},
  "2015_ljeto_A__51": {"A":"Khevenhiller je djelo Antuna Šoljana (ili dr.), a ne Šimićeva pjesma.","C":"Srodnost nije Šimićeva pjesma.","D":"Vagonaši nisu Šimićeva pjesma (vezuju se uz drugoga autora)."},
  "2015_ljeto_A__52": {"A":"Breton je autor nadrealističkog, a ne dadaističkog manifesta.","B":"Lorca nije autor Dada manifesta.","C":"Marinetti je autor futurističkog manifesta, a ne Dada manifesta."},
  "2015_ljeto_A__53": {"A":"Pupačić nije autor zbirke Lelek sebra.","B":"Mihalić nije autor te zbirke.","D":"Vesna Parun nije autorica Leleka sebra."},
  "2015_ljeto_A__54": {"A":"Joža Podravec nije lik koji skače u vatru po bika.","B":"Filip Latinovicz je promatrač i slikar, a ne onaj koji izvodi bika iz vatre.","D":"Silvije Liepach nije lik vezan uz taj prizor spašavanja bika."},
  "2015_ljeto_A__55": {"A":"Šenoa nije autor tih stihova izgnaničke čežnje.","C":"Vraz nije autor tih stihova.","D":"Vidrić nije autor tih stihova (pripada moderni, a riječ je o romantičarskoj lirici)."},
  "2015_ljeto_A__56": {"A":"Točna množina jest 'bjegovi' (ije→je), pa 'bijegovi' nije pravopisno točno.","C":"Točna množina jest 'cvjetovi' (ije→je), pa 'cvijetovi' nije točno.","D":"Množina 'snijeg' je 'snjegovi' (ije→je), pa 'snijegovi' nije točno."},
  "2015_ljeto_A__57": {"A":"Ispravno je 'bešćutan/besživotan' (jednačenje), pa 'bezživotan' nije točno.","B":"Ispravno je 'iščetkan' (jednačenje s+č→šč), pa 'isčetkan' nije točno.","D":"Ispravno je 'uščuvan' (jednačenje), pa 'uzčuvan' nije točno."},
  "2015_ljeto_A__58": {"A":"Osnova je 'svećenik' (ć), pa 'svečenički' (č) nije točno.","B":"Pogrešni su i 'sveč-' i nastavak '-ićki'; treba 'svećenički'.","D":"'Svećen-' je dobro, ali nastavak je '-nički', a ne '-nićki'."},
  "2015_ljeto_A__59": {"B":"Nepostojano a u 'osoblje' nije provedeno; promjena je jotacija (b+j→blj).","C":"Palatalizacija mijenja k, g, h pred e/i, čega u 'osoblje' nema.","D":"Vokalizacije (l→o) ovdje nema; provedena je jotacija."},
  "2015_ljeto_A__60": {"A":"Naglasak nije na prvom slogu (po-), nego na drugom (-tvr-).","C":"Naglasak nije na trećem slogu (-đi-).","D":"Naglasak nije na četvrtom slogu (-va-)."},
  "2015_ljeto_A__61": {"A":"Prefiks 'hiper-' ne odvaja se crticom s razmacima; ne piše se 'hiper – produkcija'.","B":"Prefiks 'hiper-' ne piše se odvojeno od osnove razmakom.","C":"Prefiks 'hiper-' ne piše se s crticom; složenica se piše sastavljeno."},
  "2015_ljeto_A__62": {"B":"U pridjevu 'primorsko-goranske' drugi se dio piše malim slovom, pa 'Goranske' nije točno.","C":"Opisni član 'zajednica' piše se malim slovom, pa 'Zajednice' nije točno.","D":"Pogrešni su i 'Zajednice' (treba malo) i 'Goranske' (treba malo)."},
  "2015_ljeto_A__63": {"B":"Sufiks je '-it-', a nastavak '-i'; raščlamba '-i-ti' nije točna.","C":"Korijen je 'rub-', a ne 'rubi-'; raščlamba je pogrešna.","D":"Ne izdvaja se prefiks 'ob-' ni sufiks '-it-'; raščlamba 'obrub-iti' je nepotpuna."},
  "2015_ljeto_A__64": {"A":"Strano ime na -y dobiva 'j' pred nastavkom: 'Bovaryja', ne 'Bovarija'.","B":"Treba umetnuti 'j' pred nastavak: 'Bovaryja', ne 'Bovaria'.","C":"Ne piše se crtica; pravilno je 'Bovaryja', a ne 'Bovary-a'."},
  "2015_ljeto_A__65": {"A":"'Kamenje' uz 'bacali' nije u genitivu, nego u akuzativu (bacali što).","B":"Zbirna imenica 'kamenje' ima jedninski oblik, pa nije genitiv množine.","D":"'Kamenje' je zbirna imenica jedninskoga oblika, pa nije akuzativ množine."},
  "2015_ljeto_A__66": {"A":"Komparativ od 'bijesan' jest 'bjesniji' (ije→je), pa 'bijesniji' nije točno.","B":"Komparativ od 'gibak' jest 'gibljiji', a ne 'gibkiji'.","D":"Komparativ od 'visok' jest 'viši', a ne 'višlji'."},
  "2015_ljeto_A__67": {"A":"U niječnoj zamjenici prijedlog se umeće: 'ni za kim', pa 'za nikim' nije pravilno.","B":"Pravilan je oblik 'nitko', a ne 'niko'.","D":"Prijedlog treba doći među dijelove zamjenice ('ni od koga'), a oblik je manje čist od C."},
  "2015_ljeto_A__68": {"A":"'Donesti' nije standardni infinitiv; pravilno je 'donijeti'.","C":"'Donositi' je nesvršeni glagol, a 'donesoše' je aorist svršenoga 'donijeti'.","D":"'Donjeti' je pravopisno netočno; pravilno je 'donijeti'."},
  "2015_ljeto_A__69": {"A":"'Uđe li' jest prezent, ali u jednini i upitno; traži se 3. lice množine kao jasan primjer (B).","C":"'Uđoše' je aorist, a ne prezent.","D":"'Ulaze' je prezent glagola 'ulaziti', a ne 'ući'."},
  "2015_ljeto_A__70": {"A":"'Nije' je samo dio glagolskoga predikata, a ne cijeli predikat.","B":"'Nije želio' ne uključuje infinitiv 'ostati' koji je dio glagolskoga predikata.","D":"'U kući' je priložna oznaka mjesta i ne ulazi u predikat."},
  "2015_ljeto_A__71": {"A":"'Miris' je ovdje subjekt (miris se širio), a ne objekt.","B":"'Mirisu' je u dativu, dakle neizravni, a ne izravni objekt.","C":"'Mirisa' je u genitivu (dio sintagme), a ne izravni objekt u akuzativu."},
  "2015_ljeto_A__72": {"A":"'Sretni i bezbrižni' odnose se na subjekt (predikatni proširak), a nisu atribut uz 'klupa'.","B":"'Običnoj drvenoj' sročni su atributi (slažu se u rodu, broju, padežu), a ne nesročni.","D":"Ovdje je glavna imenica 'naslon', a 'klupe' je nesročni atribut uz nju, ne uz 'klupa'."},
  "2015_ljeto_A__73": {"B":"'Pridošlim Hrvatima' nije predikat; predikat je 'bila utočište'.","C":"Riječ je o objektu u dativu, a ne o priložnoj oznaci.","D":"Subjekt je 'vjera', a 'Pridošlim Hrvatima' je neizravni objekt."},
  "2015_ljeto_A__74": {"A":"'Da sutra mora otići' ovdje je atributna (objasnidbena uz 'zapovijed'), a ne subjektna.","B":"Zavisna rečenica je pogodbena/objasnidbena uz 'sretan', a ne subjektna.","D":"'Petru su rekli da...' ima objektnu rečenicu, a ne subjektnu."},
  "2015_ljeto_A__75": {"B":"'Glavom i bradom' (osobno) i 'glavom kroza zid' (uzaludno) nisu suprotni po značenju.","C":"'Izgubiti dobar glas' i 'doći na loš glas' bliskoznačni su, a ne suprotni.","D":"'Zaspati vječnim snom' i 'ispustiti dušu' istoznačni su (umrijeti), a ne suprotni."},
  "2015_ljeto_A__76": {"A":"Riječi 'bôl' i 'Bôl' nisu suprotnoga značenja, pa nije antonimija.","B":"Homofonija je isti izgovor uz različit zapis; ovdje je zapis jednak, pa nije homofonija.","D":"Riječi nemaju isto značenje, pa nije sinonimija nego homografija."},
  "2015_ljeto_A__77": {"A":"'Dokoljenica' nastaje prefiksalno-sufiksalno (do-+koljen-+-ica), a ne čistom sufiksacijom.","B":"'Nebriga' nastaje prefiksacijom (ne-+briga), a ne sufiksalno.","D":"'Rukometaš' je tvoren od složenice 'rukomet' (+ -aš), a osnova nije nastala čistom sufiksacijom kao kod 'pomorac'."},
  "2015_ljeto_A__78": {"A":"'Zubarski' je cijela izvedenica, a ne tvorbena osnova.","B":"'Zubarsk' nije samostalna tvorbena osnova; osnova je 'zubar'.","D":"'Zub' je korijen, ali tvorbena je osnova riječi 'zubarski' upravo 'zubar'."},
  "2015_ljeto_A__79": {"A":"'Kopački rit' je ime močvarnoga područja (hidronim/oronim), a ne naselja.","B":"'Plitvička jezera' su hidronim (jezera), a ne ime naselja.","D":"'Zagrebačka gora' je oronim (gora), a ne ekonim."},
  "2015_ljeto_A__80": {"A":"Skup glagoljičnih isprava o granicama posjeda u Istri odnosi se na Istarski razvod, a ne na Vinodolski zakonik.","B":"Latinični tekst iz 1345. s pravilima za redovnice odnosi se na drugi spomenik, a ne na Vinodolski zakonik.","C":"Posjedovna ćirilična isprava iz 1250. nije Vinodolski zakonik (koji je glagoljični zakonik iz 1288.)."},

  // 2015_ljeto_B
  "2015_ljeto_B__1": {"A":"Cvijet se spominje samo jednom (djevojka s cvijetom u kosi) i ne ponavlja se kroz pjesmu.","B":"Odlazak se javlja tek pred kraj (djevojka odlazi) i nije ponavljani motiv.","C":"Strnište se navodi samo jedanput, dok se motiv žetve provlači cijelom pjesmom."},
  "2015_ljeto_B__2": {"A":"Djevojka mu dovikuje pozdrav stojeći kraj njega, dakle nije daleko u tom trenutku.","B":"Drhtanje glasa opisuje samu djevojku, a nije razlog zašto je žetelac ne čuje.","C":"Žetelac nije prikazan kao radostan, nego potpuno predan i zaokupljen napornim radom."},
  "2015_ljeto_B__3": {"A":"Nema suprotstavljanja dviju proturječnih slika, pa nije riječ o antitezi.","B":"Nema ublažavanja neugodna pojma drugim, nježnijim izrazom, pa nije eufemizam.","C":"Nema pretjerivanja radi pojačavanja dojma, pa nije hiperbola."},
  "2015_ljeto_B__4": {"A":"Auditivni se podražaj odnosi na sluh, a miris se ne čuje.","B":"Gustativni se podražaj odnosi na okus, a ovdje je riječ o mirisu.","D":"Taktilni se podražaj odnosi na dodir, a miris se njuši, ne dodiruje."},
  "2015_ljeto_B__5": {"A":"Stih je slobodan, bez stalnoga broja slogova, pa se ritam ne postiže time.","B":"Veznici se ne gomilaju, pa nije riječ o polisindetonu.","D":"Pjesma nema rime jer je pisana slobodnim stihom."},
  "2015_ljeto_B__6": {"B":"Pjesnik traži dar izricanja misli, a ne obasjanje svjetlošću.","C":"Riječ je o pomoći pri pisanju, a ne o molbi za krepostan život.","D":"Pjesnik moli sposobnost izražavanja, a ne hrabrost."},
  "2015_ljeto_B__7": {"A":"Stih govori o dikama i hvalama Juditi, dakle o slavljenju, a ne o odvažnosti.","C":"Stih je molba Bogu da nadahne pjesnika ljubavlju, a ne iskaz Juditine smionosti.","D":"Stih se odnosi na Boga koji daje pjevanje i pokoj vjernima, a ne na Juditinu odvažnost."},
  "2015_ljeto_B__8": {"A":"Stih je najmanja jedinica i nema ih samo šest, pa 'libri' ne znače stihove.","B":"Strofa je skupina stihova, ali 'libri' ovdje znače veće cjeline - pjevanja.","D":"Čin je dramska, a ne epska podjela, pa ne odgovara epu Juditi."},
  "2015_ljeto_B__9": {"B":"Jampski pentametar nije stih Juditi nego stih svojstven engleskoj drami.","C":"Epski deseterac stih je usmenoga pjesništva, a Marulić piše dvanaestercem.","D":"Heksametar je antički stih, a Marulić rabi dvostrukorimovani dvanaesterac."},
  "2015_ljeto_B__10": {"A":"Petrarkisti su renesansni, a ne 'stari' pjesnici koji su štovali poganske bogove.","B":"Trubaduri su srednjovjekovni provansalski pjesnici, a ne antički štovatelji bogova.","D":"Začinjavci su stariji hrvatski pjesnici, a ne antički koji su slavili poganska božanstva."},
  "2015_ljeto_B__11": {"A":"Susret s momcima samo je dio prizora; središte teksta je Lottin pogled.","B":"Šetnja je tek okvir radnje, a temeljni motiv je pogled koji Werther traži.","D":"Lottina kosa se ne spominje kao motiv; istaknute su njezine oči i pogled."},
  "2015_ljeto_B__12": {"A":"Rečenica opisuje Lottino premještanje pogleda, a ne Wertherovu odanost.","C":"Rečenica govori o Lottinu osvrtanju, a ne o Wertherovoj odanosti njoj.","D":"Rečenica izražava Wertherovu neizvjesnost, a ne njegovu odanost Lotti."},
  "2015_ljeto_B__13": {"A":"Neutješnost nije razlog kraćenja; pripovjedač izrijekom navodi drijemež.","B":"Nestrpljivost se ne spominje kao razlog; on skraćuje jer mu se sklapaju oči.","C":"Osamljenost je dio njegova stanja, ali priču krati zbog pospanosti."},
  "2015_ljeto_B__14": {"A":"Riječ se odnosi na usmeni razgovor uživo, a ne na dopisivanje.","C":"'Časkati' znači brbljati, a ne smijati se.","D":"'Časkati' znači razgovarati, a ne pobjeći."},
  "2015_ljeto_B__15": {"A":"Roman nije životopis nego niz pisama upućenih prijatelju.","B":"Putopis opisuje putovanja, a Wertherove patnje pisane su kao pisma.","D":"Esej je promišljanje teme, a ovdje je riječ o epistolarnoj formi."},
  "2015_ljeto_B__16": {"B":"Uzvik nije izraz zahvalnosti, nego ganuća i probuđene ljubavi.","C":"Pavao nije uvrijedio Doru; njegova ispovijed izaziva njezine osjećaje.","D":"Iako ju je Pavao ranije spasio, ovaj uzvik izražava zaljubljenost, a ne zahvalnost za spas."},
  "2015_ljeto_B__17": {"A":"'Ljut' ovdje znači žestok, a ne hladan.","B":"'Ljut boj' znači žestoka bitka, a ne viteška.","C":"'Ljut' se odnosi na žestinu sukoba, a ne na žalost."},
  "2015_ljeto_B__18": {"A":"Rečenica nizanjem 'zdrav i živ' iskazuje istovjetnost, a ne kontrast.","B":"Rečenica je metaforički iskaz nježnosti, bez suprotstavljenih pojmova.","C":"Rečenica niza slične tjelesne reakcije uzbuđenja, bez kontrasta."},
  "2015_ljeto_B__19": {"A":"Rečenica izjednačuje noć i jutro s Dorom, što je metafora, a ne hiperbola.","B":"Rečenica je poziv srcu i nema pretjerivanja svojstvenoga hiperboli.","C":"Rečenica opisuje stvarne tjelesne reakcije, bez izrazitoga pretjerivanja."},
  "2015_ljeto_B__20": {"A":"Pavao Doru ne sprječava u govoru; 'van reda' je njegova ljubavna izjava.","C":"Pavao ne predlaže da Dora napusti dom; prekršio je običaj izjavom ljubavi.","D":"Spašavanje od konja dogodilo se ranije i nije ono što je 'van reda i običaja'."},
  "2015_ljeto_B__21": {"A":"'Skanjivati se' znači oklijevati, suprotno od nepromišljenosti.","B":"Oklijevanje je oprezno i suzdržano, suprotno neustrašivosti.","C":"Oklijevanje upravo znači opreznost, a ne neopreznost."},
  "2015_ljeto_B__22": {"A":"Tekst ne govori o stidu zbog predviđanja, nego zbog osjećaja straha.","B":"Stidio se osjećaja, a ne svojih uvjerenja.","D":"Stid se odnosi na bolno, strašljivo čuvstvo, a ne na želje."},
  "2015_ljeto_B__23": {"A":"Riječ je o usporedbi s veznikom 'kao', a ne o metafori.","B":"To je doslovan opis izbjegnuta susreta, bez prenesenoga značenja.","C":"Riječ je o doslovnom opisu osjećaja, bez metaforičkoga prijenosa."},
  "2015_ljeto_B__24": {"A":"Lužin je sporedni lik (Dunjin prosac), a ne mladić s početka romana.","C":"Razumihin je Raskoljnikov prijatelj, a ne mladić koji izlazi iz sobice.","D":"Svidrigajlov je drugi lik romana, a ne protagonist koji izlazi na početku."},
  "2015_ljeto_B__25": {"A":"Radnja se ne zbiva u Kijevu nego u tadašnjoj ruskoj prijestolnici.","B":"Radnja nije smještena u Moskvu nego u Petrograd.","D":"Prag nije grad ovoga romana; radnja se odvija u Petrogradu."},
  "2015_ljeto_B__26": {"A":"Sklonost svađama svojstvena je samo nekima, a ne svim hobistima.","B":"Druženje s djevojkama vežu uz 'kočoperenje' samo nekih, ne svih.","C":"Isticanje statusa nije zajedničko svima; zajednička im je rijeka."},
  "2015_ljeto_B__27": {"A":"Osjećaj manje vrijednosti ne pripisuje se manijacima eksperimenta.","B":"Neostvarenost umjetnika nije obilježje manijaka eksperimenta.","D":"Povučenost se pripisuje manijacima inovacije, a ne eksperimenta."},
  "2015_ljeto_B__28": {"A":"'Kočoperiti se' znači praviti se važnim, a ne srdačnim.","B":"Riječ ne znači praviti se humanim, nego se nadimati i hvaliti.","C":"Riječ znači razmetanje važnošću, a ne pravljenje ozbiljnim."},
  "2015_ljeto_B__29": {"B":"Nema postupnoga pojačavanja značenja, pa nije gradacija.","C":"Nema pretjerivanja radi naglašavanja, pa nije hiperbola.","D":"Nema povezivanja dviju pojava veznikom 'kao', pa nije usporedba."},
  "2015_ljeto_B__30": {"A":"Ilok se ne spominje u podnaslovu djela.","B":"Osijek nije grad iz podnaslova; riječ je o Vukovaru.","C":"Vinkovci se ne navode u podnaslovu Pavličićeva Dunava."},
  "2015_ljeto_B__31": {"A":"Antigona ne poziva sestru na zajedničku molitvu nego na pokop brata.","B":"Antigona upravo prkosi vlasti, a ne nagovara na poslušnost.","D":"Antigona ne poziva na odlazak iz grada nego na sahranu Polinika."},
  "2015_ljeto_B__32": {"A":"Majka nije pogubljena; ona se sama objesila.","B":"Majka nije prognana; sama je sebi oduzela život omčom.","C":"Majka se nije otrovala nego objesila spletenom omčom."},
  "2015_ljeto_B__33": {"A":"Stih je Izmenin uzvik i pitanje sestri, bez poslovične mudrosti.","B":"Stih govori o Edipovoj sudbini, a ne izriče opću životnu mudrost.","C":"Stih opisuje smrt braće, a ne sadrži poslovičnu pouku."},
  "2015_ljeto_B__34": {"A":"Antigona se ne poziva na domovinu nego na dužnost prema bratu.","B":"Zaručnik (Hemon) nije razlog njezina djelovanja; vodi je obiteljska dužnost.","D":"Antigona prkosi vlasti, dakle ne poziva se na poštivanje vlasti."},
  "2015_ljeto_B__35": {"B":"Eteoklo je njihov brat, a ne otac.","C":"Kreont je njihov ujak i vladar, a ne otac.","D":"Polinik je njihov brat (kojega Antigona želi pokopati), a ne otac."},
  "2015_ljeto_B__36": {"B":"Concetto (domišljata dosjetka) obilježje je baroka, a ne romantizma.","C":"Oponašanje zbilje poput zrcala načelo je realizma, a ne romantizma.","D":"Slijeđenje antičkih uzora svojstveno je klasicizmu, a ne romantizmu."},
  "2015_ljeto_B__37": {"A":"Anadiploza ponavlja kraj jednoga stiha na početku sljedećega, što ovdje nije slučaj.","C":"Epifora ponavlja riječi na kraju stihova, a ovdje se ponavlja početak.","D":"Simploka spaja anaforu i epiforu, a ovdje se ponavlja samo početak stihova."},
  "2015_ljeto_B__38": {"A":"Opsežno epsko djelo u stihovima je ep, a ne ditiramb.","B":"Dramska vrsta idiličnoga života u prirodi je pastorala, a ne ditiramb.","C":"Lirsko-epska vrsta tužnoga ugođaja je elegija, a ne ditiramb."},
  "2015_ljeto_B__39": {"A":"Religiozna poema o razmetnome sinu su Suze sina razmetnoga, a ne Dubravka.","B":"Povijesni ep o oholosti je Osman, a ne Dubravka.","D":"Prerada Davidovih pokorničkih psalama su Psalmi pokorni, a ne Dubravka."},
  "2015_ljeto_B__40": {"A":"Ančica je blag, krotak lik, a buntovne slobodarske riječi izgovara Laura.","B":"Justa Medonić ne izgovara ovaj iskaz; on pripada Lauri.","D":"Vila Dorica nije govornica ovoga slobodarskog iskaza nego Laura."},
  "2015_ljeto_B__41": {"A":"U Krležinoj Baraci Pet Be nema lika negromanta Dugoga Nosa.","B":"Zoranićeve Planine ne sadrže lik Dugoga Nosa.","D":"Mažuranićev spjev nema lik negromanta Dugoga Nosa."},
  "2015_ljeto_B__42": {"A":"Homer je grčki epski pjesnik, ali Danteov vodič i autor Eneide je Vergilije.","B":"Horacije je rimski lirik, a ovdje govori autor Eneide, Vergilije.","C":"Ovidije je autor Metamorfoza, a ne Eneide; govori Vergilije."},
  "2015_ljeto_B__43": {"A":"Hamlet ne priznaje umorstvo brata; to je krivnja njegova strica.","C":"Laert ne izgovara ovo priznanje bratoubojstva.","D":"Polonije nije počinitelj bratoubojstva i ne izgovara ovaj monolog."},
  "2015_ljeto_B__44": {"A":"Kristina Linde je lik iz Ibsenove Nore, a ne iz Zločina i kazne.","B":"Bobočka je lik iz Krležina Povratka Filipa Latinovicza, a ne iz Zločina i kazne.","D":"Victorina Taufer nije lik Zločina i kazne."},
  "2015_ljeto_B__45": {"A":"Beowulf je engleski (anglosaski) nacionalni ep, a ne španjolski.","C":"Pjesma o Nibelunzima je njemački ep, a ne španjolski.","D":"Pjesma o Rolandu je francuski ep, a ne španjolski."},
  "2015_ljeto_B__46": {"A":"Dundo Maroje je izvorna Držićeva komedija, a ne prerada Plautova Škrtca.","B":"Novela od Stanca je kratka komedija i nije prerada Plauta.","C":"Pomet je izgubljena Držićeva komedija, a Škrtca prerađuje Skup."},
  "2015_ljeto_B__47": {"A":"Voltaire je prosvjetiteljski pisac, a komedije karaktera 17. st. piše Molière.","C":"Rabelais je renesansni pisac (Gargantua i Pantagruel), a ne komediograf 17. st.","D":"Balzac je realist 19. st., a tražene komedije karaktera piše Molière."},
  "2015_ljeto_B__48": {"B":"Ibsen je dramatičar realističkih društvenih drama, a ne gotičke fantastike.","C":"Proust piše psihološku prozu sjećanja, a ne gotičku mistiku.","D":"Cervantes je autor Don Quijotea, a ne mistično-gotičke proze."},
  "2015_ljeto_B__49": {"A":"Jesenje veče je lirska pjesma (lirika), a ne epsko djelo.","C":"Utjeha kose je lirska pjesma, a ne epsko djelo.","D":"1909. je lirska pjesma (sonet), a ne epsko djelo."},
  "2015_ljeto_B__50": {"A":"Gundulić je barokni pisac i nije autor drame Bez trećeg.","B":"Ivo Brešan nije napisao Bez trećeg.","D":"Krleža nije autor drame Bez trećeg; napisao ju je Begović."},
  "2015_ljeto_B__51": {"A":"Slamnig nije autor pjesme Majstore, ugasi svjetlo.","B":"Pupačić nije autor te pjesme.","D":"Mihalić nije autor pjesme Majstore, ugasi svjetlo."},
  "2015_ljeto_B__52": {"A":"Gundulićev Osman je barokno djelo, a ne renesansno.","C":"Relkovićev Satir je prosvjetiteljsko djelo, a ne renesansno.","D":"Mažuranićeva Smrt Smail-age Čengića je djelo romantizma, a ne renesanse."},
  "2015_ljeto_B__53": {"A":"Mihanović stvara u 19. st., a renesansa je razdoblje 15.-16. stoljeća.","B":"Pjesma nije barokna; Mihanović pripada romantizmu (preporodu).","D":"Realizam dolazi nakon Mihanovića, koji je preporodni romantičar."},
  "2015_ljeto_B__54": {"B":"Dinko Šimunović nije autor Moći savjesti niti se uz njega veže početak moderne.","C":"Janko Leskovar je modernist, ali Moć savjesti napisao je Matoš.","D":"Josip Kozarac je realist, a Moć savjesti napisao je Matoš."},
  "2015_ljeto_B__55": {"B":"Tadijanović nije autor stihova o pjesniku koji živi u svojoj knjizi.","C":"Kranjčević nije autor ove pjesme o besmrtnosti u stihu.","D":"Ujević nije autor ovih stihova; napisao ih je Cesarić."},
  "2015_ljeto_B__56": {"A":"'Isčetkati' je pogrešno jer 's' ispred 'č' prelazi u 'č' (is + č = ič).","B":"'Ičetkati' (s 'i' umjesto 'iz') nije pravilno; prefiks je 'is-', a ne 'i-'.","C":"'Izčetkati' je pogrešno jer 'z' ispred bezvučnoga 'č' prelazi u 'č'."},
  "2015_ljeto_B__57": {"B":"Pogrešno je veliko 'F' u 'Fakulteta'; u dvočlanom nazivu velika je samo prva riječ.","C":"Pogrešno je veliko 'S' u 'Sveučilišta' jer je tu opća imenica u genitivu.","D":"Pogrešno je veliko slovo i u 'Fakulteta' i u 'Sveučilišta'."},
  "2015_ljeto_B__58": {"B":"U 'jabuka -> jabučica' provedena je sibilarizacija/palatalizacija, a ne jednačenje po zvučnosti.","C":"U 'cvijet -> cvijeće' provedeno je jotacija, a ne jednačenje po zvučnosti.","D":"U 'nositi -> nošnja' provedena je jotacija, a ne jednačenje po zvučnosti."},
  "2015_ljeto_B__59": {"A":"Nema promjene mjesta tvorbe suglasnika; samoglasnik 'a' jednostavno ispada.","B":"Nema promjene zvučnosti suglasnika; riječ je o ispadanju samoglasnika.","C":"Ne gubi se suglasnik nego samoglasnik 'a' u kosim padežima."},
  "2015_ljeto_B__60": {"A":"Riječ ima više od dva morfema; predškolski ima četiri tvorbene jedinice.","B":"Tri morfema je premalo; uz pred-, škol-, -i tu je i sufiks -sk-.","D":"Pet morfema je previše; riječ se rastavlja na četiri: pred-, škol-, -sk-, -i."},
  "2015_ljeto_B__61": {"A":"'Kov-' je korijenski (leksički) morfem, a ne gramatički.","B":"Ovo '-a' je tvorbeni spojnik unutar osnove, a gramatički je nastavak završno '-a'.","C":"'-nic-' je tvorbeni (sufiks) morfem, a ne gramatički nastavak."},
  "2015_ljeto_B__62": {"A":"'Prijonuti' je pogrešno jer se piše s 'io', a ne 'ijo': prionuti.","C":"'Prionut' je krnji oblik bez završnoga 'i', pa nije standardni infinitiv.","D":"'Prioniti' je pogrešno jer je standardni oblik 'prionuti'."},
  "2015_ljeto_B__63": {"A":"'Mačci' bi tražilo sibilarizaciju koja u dativu ove imenice nije pravilna.","C":"'Mačkama' je dativ množine, a traži se jednina.","D":"'Mačkom' je instrumental jednine, a ne dativ."},
  "2015_ljeto_B__64": {"A":"'Kradom' nije glagol nego nepromjenjiva riječ koja izriče način.","B":"'Kradom' nije imenica nego prilog načina.","C":"'Kradom' nije pridjev jer ne opisuje imenicu nego radnju glagola."},
  "2015_ljeto_B__65": {"A":"Prijedlog 'na' s ovim značenjem mjesta traži lokativ, a ne genitiv.","B":"Oblik 'vjetru' ovdje nije dativ nego lokativ uz prijedlog 'na'.","C":"'Na vjetru' označava mjesto i traži lokativ, a ne akuzativ."},
  "2015_ljeto_B__66": {"A":"'Orahić' ne provodi obveznu sibilarizaciju h -> š ispred -ić.","B":"'Orahčić' nije pravilno; ispred sufiksa 'h' prelazi u 'š' (orašić).","D":"'Orašac' nije umanjenica nego drukčija tvorenica, a deminutiv je orašić."},
  "2015_ljeto_B__67": {"A":"Oblik bez nastavka '-evoj' u drugom dijelu nije pravilan ženski dativ složenoga prezimena.","C":"Jednak je točnom obliku (vjerojatno tipkarska dvojba), ali pravilan je B.","D":"Pogrešno je sklanjati i prvi dio; mijenja se samo drugi dio prezimena."},
  "2015_ljeto_B__68": {"A":"'Tko' je zamjenica koja se sklanja po padežima, dakle promjenjiva je.","C":"'Nečiji' je posvojna zamjenica koja se mijenja po rodu, broju i padežu.","D":"'Svoj' je povratno-posvojna zamjenica koja se sklanja, dakle promjenjiva je."},
  "2015_ljeto_B__69": {"B":"'Njegov' ne dopunjuje radnju nego pobliže označuje imenicu, pa nije objekt.","C":"Subjekt je 'kritičari', a 'njegov' je atribut uz 'roman'.","D":"'Njegov' ne izriče okolnost radnje nego svojstvo imenice, pa nije priložna oznaka."},
  "2015_ljeto_B__70": {"A":"Rečenica ne odgovara na pitanje 'koji?' uz imenicu, pa nije atributna.","B":"Glavna rečenica nema objekta na koji bi se zavisna odnosila, pa nije objektna.","D":"Rečenica ne izriče uzrok nego dopunjuje besubjektni predikat 'jasno je'."},
  "2015_ljeto_B__71": {"A":"'Kako bi uživao' izriče namjeru, pa je riječ o namjernoj rečenici.","B":"'Kako vjeruje' dopunjuje glagol 'rekla je' kao objekt, pa je objektna.","C":"'Kako ona pjeva' dopunjuje besubjektno 'znalo se', pa je subjektna."},
  "2015_ljeto_B__72": {"A":"Veznik 'iako' uvodi dopusnu zavisnosloženu rečenicu, a ne nezavisnu.","B":"Veznik 'da' uvodi pogodbenu zavisnosloženu rečenicu, a ne nezavisnu.","D":"'Tko izgubi' uvodi zavisnu subjektnu rečenicu, a ne nezavisnosloženu."},
  "2015_ljeto_B__73": {"A":"'Futurizam' je izveden od latinske riječi za budućnost, a ne od osobnog imena.","B":"'Klasicizam' potječe od riječi 'klasa/klasik', a ne od osobnog imena.","D":"'Realizam' dolazi od latinske riječi 'res' (stvar), a ne od imena osobe."},
  "2015_ljeto_B__74": {"A":"Leksikografija se bavi izradom rječnika, a ne strukturom rečenice.","B":"Morfologija proučava oblike riječi, a ne strukturu rečenice.","C":"Semantika proučava značenje, a ne strukturu rečenice."},
  "2015_ljeto_B__75": {"A":"'Oblikotvorje' se odnosi na tvorbu oblika riječi, a ne na pravopis.","B":"'Pravogovor' je sinonim za ortoepiju, a ne za ortografiju.","D":"'Rječotvorje' se odnosi na tvorbu riječi, a ne na pravopis."},
  "2015_ljeto_B__76": {"A":"Antonimija je odnos suprotnoga značenja, a ovdje su riječi istoga zvuka, a različita značenja.","B":"Hiperonimija je odnos nadređenoga pojma, što ovdje nije slučaj.","D":"Sinonimija je istoznačnost, a ove riječi imaju različita značenja uz isti oblik."},
  "2015_ljeto_B__77": {"A":"Arhaizam je zastarjela riječ za pojam koji još postoji, a kmet je iščezla pojava.","B":"Dijalektizam pripada mjesnom govoru, a 'kmet' je naziv za nestalu društvenu pojavu.","D":"Neologizam je nova riječ, a 'kmet' označava nešto što je davno nestalo."},
  "2015_ljeto_B__78": {"A":"'Milci' bi bila sibilarizirana dativna inačica, ali kanonski je oblik nominativ.","C":"'Milko' je muški oblik, a ovdje je riječ o ženskom imenu Milka.","D":"'Milku' je akuzativ, a kanonski oblik je nominativ Milka."},
  "2015_ljeto_B__79": {"A":"Frazem ne znači živjeti u strahu nego biti izvan svoga elementa.","C":"Frazem se ne odnosi na sporo plivanje nego na nelagodu i nesnalaženje.","D":"Frazem ne znači biti nijem nego biti u neprilici."},
  "2015_ljeto_B__80": {"B":"Belostenec je autor Gazophylaciuma, ali prvi tiskani rječnik napisao je Vrančić.","C":"Mikalja je autor kasnijega rječnika, a prvi tiskani sastavio je Vrančić.","D":"Habdelić je autor kajkavskoga rječnika, a prvi tiskani je Vrančićev."},

  // 2016_jesen_A
  "2016_jesen_A__1": {"B":"Baladičnost podrazumijeva tragičnu, sumornu fabulu, a ne razuzdano slavlje satira, vina i nimfa.","C":"Elegičan ugođaj nosi tugu i sjetu, dok pjesma dočarava bujnu radost i veselje.","D":"Psalmički ugođaj povezan je sa svečanom religioznošću, a ovdje prevladava pogansko slavlje i naslada."},
  "2016_jesen_A__2": {"A":"Nimfe se s gaja ozivlju, ali ne one podižu divlju buku, nego satiri.","B":"Ovan je samo žrtva koju satiri peku, on ne sudjeluje u buci.","D":"Žena se prislanja uz satira, ali stih izrijekom kaže da buku podižu satiri, a ne ona."},
  "2016_jesen_A__3": {"B":"Anadiploza je ponavljanje završne riječi jednoga stiha na početku idućega, čega u ovom stihu nema.","C":"Anafora je ponavljanje riječi na početku uzastopnih stihova, a ovdje se ponavlja samo glas p unutar jednoga stiha.","D":"Asindeton je nizanje bez veznika, a ovdje je riječ o glasovnom ponavljanju, a ne o izostavljanju veznika."},
  "2016_jesen_A__4": {"A":"Sintagma 'svijetli panj' smještena je unutar jednoga stiha i nije razlomljena prijelazom u novi stih.","B":"Sintagma 'ožarene grane' nije rastavljena opkoračenjem jer ne prelazi iz stiha u stih.","C":"Sintagma 'slađano vino' nalazi se cijela u jednom stihu, bez opkoračenja."},
  "2016_jesen_A__5": {"A":"Šum lovora i tekuće vode predočuju zvuk, dakle riječ je o auditivnom, a ne gustativnom podražaju.","B":"Drhtanje ožarenih grana vizualni je prizor, a ne okusni doživljaj.","C":"Skakanje satira prikazuje pokret (vizualno/dinamično), a ne okus."},
  "2016_jesen_A__6": {"B":"Tekst ne tematizira Odisejevu zaljubljenost; Nausikajin se divi njegovoj ljepoti, ali to nije središnja tema ulomka.","C":"Stradanje na moru pripada ranijem dijelu epa, a ovdje je Odisej već stigao na obalu i među Feačane.","D":"Hefest se spominje tek u poredbi o izradi zlata, a ne kao Odisejev sugovornik ili tema ulomka."},
  "2016_jesen_A__7": {"A":"Feački narod tek treba dočekati Odiseja, oni ga ne uljepšavaju.","B":"Hefest se spominje samo u poredbi kao zlatar, a Odiseja ne uljepšava on.","C":"Nausikaja (djeva) daje mu odjeću i gleda ga, ali milotom ga obasipa Atena, a ne ona."},
  "2016_jesen_A__8": {"B":"Feački se narod ne uspoređuje s junacima, nego s bogovima ('bogoliki').","C":"Usporedba s robovima u suprotnosti je s pridjevom 'bogoliki' kojim je narod opisan.","D":"Tuđinci se ne spominju kao mjerilo usporedbe; narod je nazvan bogolikim."},
  "2016_jesen_A__9": {"A":"Odjeću mu daje djeva, ali perunici je slična kosa, a ne odjeća.","C":"Pleća su obliveni milotom, ali poredba s perunikom odnosi se na kosu.","D":"Ruke se ('bjeloruke') spominju uz služavke, a perunici je slična Odisejeva kosa."},
  "2016_jesen_A__10": {"A":"Elipsa je izostavljanje dijela rečenice, a ovdje su svi članovi prisutni.","C":"Oksimoron spaja proturječne pojmove, čega u 'služavke bjeloruke' nema.","D":"Personifikacija pripisuje neživomu ljudske osobine, a ovdje je samo neuobičajen red riječi."},
  "2016_jesen_A__11": {"B":"Baraka se uspoređuje s utrobom šlepa, a ne s mrtvačnicom, iako u njoj leže umirući.","C":"Kupaonica se ne spominje kao poredba; okupali su Vidovića, ali baraka je uspoređena sa šlepom.","D":"Pakao se spominje za bojišnicu ('blatni i krvavi pakao'), a baraka je uspoređena s utrobom šlepa."},
  "2016_jesen_A__12": {"A":"Podjela nije po nacionalnosti, nego prema vrsti i težini ozljeda.","B":"Vjerska pripadnost nije kriterij podjele grupa ranjenika.","C":"Vojnički staž ne određuje grupe; one se dijele prema ozljedama."},
  "2016_jesen_A__13": {"A":"Bijes nije značenje pridjeva 'golgotski', koji upućuje na patnju i mučeništvo.","C":"Podrugljivost je suprotna značenju riječi povezane s Golgotom i stradanjem.","D":"Prijezir ne odgovara značenju riječi 'golgotski', koja izražava mučeničku bol."},
  "2016_jesen_A__14": {"B":"Izraz 'šezdeset postelja' doslovan je opis broja, bez prenesena značenja.","C":"'Polomljene kosti' doslovan su naziv jedne grupe ranjenika, a ne metafora.","D":"'Kosti strše kao iver' poredba je (s veznikom 'kao'), a ne metafora."},
  "2016_jesen_A__15": {"A":"Tridesetogodišnji vjerski rat (17. st.) vremenski je daleko od Krležina ratnoga iskustva.","B":"Prvi balkanski rat nije tema novele koja prikazuje austrougarsko bojište Prvoga svjetskog rata.","D":"Drugi svjetski rat nastupa kasnije; Baraka Pet Be (1921.) prikazuje Prvi svjetski rat."},
  "2016_jesen_A__16": {"A":"Dvoboj se ne otkazuje, nego se priprema kao smišljena zamka.","C":"Nije riječ o sudskome sporu, nego o tajno skovanoj uroti oko dvoboja.","D":"Cilj nije zastrašiti protivnika, nego ga prijevarom ubiti, što doktor razotkriva."},
  "2016_jesen_A__17": {"B":"Grušnicki je u sceni o kojoj doktor pripovijeda, on ne kazuje 'uto sam ušao'.","C":"Kapetan iznosi plan unutar prepričanoga razgovora, ali pripovjedač koji je ušao jest doktor.","D":"Neimenovani gospodin samo je nazočan; rečenicu izgovara doktor koji je ušao u prostoriju."},
  "2016_jesen_A__18": {"B":"Rečenica ne znači da će Čerkezi svjedočiti, nego da će na njih pasti krivnja za smrt.","C":"Žaljenje za pokojnikom nije smisao izraza 'ide na dušu'; riječ je o odgovornosti za smrt.","D":"Pokop nije značenje izraza; 'ide na dušu Čerkeza' znači da se njima pripisuje krivnja."},
  "2016_jesen_A__19": {"B":"Dvoboj bez svjedoka nije razlog opasnosti; opasnost je u tome što protivnik neće imati prave metke.","C":"Mala udaljenost nije navedeni razlog; smrtonosnost proizlazi iz prijevare s metcima.","D":"Klanac kao mjesto nije uzrok; ubojstvom prijeti činjenica da samo Grušnicki dobiva pravi metak."},
  "2016_jesen_A__20": {"A":"17. stoljeće prerano je; Junak našeg doba nastao je u doba romantizma.","B":"18. stoljeće ne odgovara; roman je objavljen 1840. godine.","D":"20. stoljeće prekasno je; Ljermontov je djelo napisao u 19. stoljeću."},
  "2016_jesen_A__21": {"A":"Cikorije nije Eustahije; Maestro se obraća Melkioru riječima 'Smješkate se vi, Eustahije'.","B":"Maestro je onaj koji govori, dakle on nije sugovornik nazvan Eustahijem.","D":"Parsifal je tip ljubavnika kojega Vivijana traži, a ne ime lika; Eustahije je Melkior."},
  "2016_jesen_A__22": {"A":"Adam se ne boji Eustahijeva okretanja protiv sebe, nego da će mu preoteti Vivijanu.","C":"Odavanje tajne nije razlog straha; strah je vezan uz Vivijanu kojoj je Eustahije opasan suparnik.","D":"Adam se ne boji ubojstva, nego toga da Eustahije osvoji Vivijanu pa ga zato nastoji eliminirati."},
  "2016_jesen_A__23": {"B":"'Janje božje' odnosi se na naivnog Eustahija/Melkiora, a ne na Maestrovo mišljenje o Vivijani.","C":"'Njihova intriga' Melkiorova je misao o spletki, a ne Maestrov opis Vivijane.","D":"Sintagma 'klopka njezina' ne pojavljuje se u tekstu kao Maestrova karakterizacija Vivijane."},
  "2016_jesen_A__24": {"B":"Leksikostilem je stilska vrijednost izbora riječi, a ovdje je riječ o grafičkome rastavljanju.","C":"Morfostilem se tiče oblika riječi, a ne grafičkoga rastavljanja sloga crticama.","D":"Sintaktostilem se odnosi na red riječi i rečeničnu strukturu, a ovdje je riječ o grafičkome isticanju."},
  "2016_jesen_A__25": {"A":"'Plovka' metaforizira Vivijanu, a ne doslovnu lađu.","B":"Rođakinja nije značenje metafore 'plovka', koja se odnosi na Vivijanu.","C":"Sreća nije ono što 'plovka' označuje; riječ je o Vivijani koju treba 'okrenuti'."},
  "2016_jesen_A__26": {"A":"Tekst kaže da je rukopis isti i po jeziku, pa nerazumijevanje jezika nije razlog te rečenice.","C":"Autorstvo nije ono o čemu rečenica govori; ona izražava uzbuđenje pred otkrićem.","D":"Strah od oštećenja papira nije smisao rečenice; ona pokazuje uzbuđenje zbog značenja otkrića."},
  "2016_jesen_A__27": {"A":"Tekst izrijekom isključuje Mažuranićevu dopunu kao ono što je pronađeno.","C":"Nije riječ o tiskanome izdanju, nego o rukopisu istovjetnu izvorniku Osmana.","D":"Prepjev se ne spominje; pronađen je tekst koji se ni po čemu ne razlikuje od izvornoga spjeva."},
  "2016_jesen_A__28": {"A":"Antiteza je suprotstavljanje pojmova, čega u nizanju istovrsnih niječnih dijelova nema.","B":"Gradacija je stupnjevanje po jačini, a ovdje su članovi ravnopravno nanizani s istim veznikom.","C":"Hiperbola je pretjerivanje, a u primjeru je riječ o ponavljanju veznika 'ni'."},
  "2016_jesen_A__29": {"A":"Antropolog proučava čovjeka i kulture općenito, a Brodnjak se bavi starim tekstovima i rukopisima.","B":"Arheolog istražuje materijalne ostatke, a ne književne rukopise i spjevove.","C":"Etnolog proučava narodnu kulturu i običaje, a ne filološku analizu rukopisa."},
  "2016_jesen_A__30": {"A":"Radnja se ne odvija na Hvaru, nego na Lastovu.","B":"Korčula nije mjesto radnje romana Koraljna vrata.","D":"Mljet nije otok na kojem se zbiva radnja; riječ je o Lastovu."},
  "2016_jesen_A__31": {"A":"Tekst ne pokazuje da se Škoko ne slaže s učiteljevim savjetima, nego da uopće ne želi sudjelovati.","C":"Škoko se nije uživio u lik; odbija glumiti i nije naučio tekst.","D":"Škoko nije naučio tekst, što sam priznaje ('Nisam') vadeći papir iz džepa."},
  "2016_jesen_A__32": {"A":"Škunca ne odbija Shakespearea, nego ga prekraja prema vlastitu shvaćanju.","B":"Spominjanje 'svijetle tradicije' ironično je, a ne iskrena pohvala narodu.","D":"Škunca Škoku tjera na probu, ali tekst ga karakterizira sarkastičan, a ne prijeteći govor."},
  "2016_jesen_A__33": {"A":"'Idemo dalje' najava je tijeka probe, a ne uputa glumcu kako da glumi.","B":"'Razumijete? Ne? Svejedno!' obraćanje je publici/glumcima, a ne glumačka uputa o izvedbi.","C":"'Jesi li naučio napamet?' pitanje je o pripremi, a ne redateljska uputa o glumi."},
  "2016_jesen_A__34": {"B":"Monolog nije izbačen iz teksta, nego prepjevan u epske deseterce.","C":"Monolog nije doslovno preveden, nego preoblikovan u 'hajdučku' verziju u desetercima.","D":"Škunca ne dopisuje didaskalije, nego sam izvorni monolog pretvara u epski deseterac."},
  "2016_jesen_A__35": {"B":"Gorski kotar nije mjesto radnje; Mrduša Donja smještena je u Dalmatinsku zagoru.","C":"Hrvatsko primorje nije lokacija radnje ove drame.","D":"Hrvatsko zagorje nije mjesto radnje; selo Mrduša Donja u Dalmatinskoj je zagori."},
  "2016_jesen_A__36": {"A":"Slog je dio stope, ali osnovna mjerna jedinica antičke versifikacije jest stopa.","C":"Stih je viša cjelina sastavljena od stopa, a ne osnovna jedinica kvantitativne versifikacije.","D":"Strofa je skupina stihova, dakle nadređena, a ne osnovna jedinica."},
  "2016_jesen_A__37": {"A":"Ditiramb je razuzdana, veseli pjesma u čast Dionizu, suprotno žalopojki.","C":"Epigram je kratka, često duhovita ili satirična pjesma, a ne tužaljka.","D":"Oda je svečana, pohvalna pjesma, a ne žalopojka."},
  "2016_jesen_A__38": {"A":"Ilij (Troja) bojište je rata, a ne Odisejev rodni kraj.","C":"Ogigija je otok nimfe Kalipso na kojem je Odisej bio zatočen, a ne njegov dom.","D":"Teba nije Odisejev zavičaj; on je kralj Itake."},
  "2016_jesen_A__39": {"A":"Okovani Prometej tragedija je o Prometeju, a ne ep koji počinje slavljenjem 'borbi i muža'.","B":"Ilijada počinje zazivanjem srdžbe Ahilejeve, a ne 'borbe slavim i muža'.","C":"Kralj Edip dramsko je djelo, a navedeni stih početak je epa o Eneji."},
  "2016_jesen_A__40": {"A":"Rumanac Trojski nije zbirka pjesama, nego prozni roman.","B":"Nije riječ o enciklopediji, nego o pripovjednom proznom romanu o Troji.","D":"Rumanac Trojski nije ep (stih), nego prozni roman."},
  "2016_jesen_A__41": {"B":"Horacije nadživljuje Hamleta i prenosi priču, ali navedene stihove izgovara umirući Hamlet.","C":"Klaudije pogiba ranije u sceni i ne glasa za Fortinbrasa.","D":"Polonije strada davno prije završetka i ne sudjeluje u odabiru nasljednika."},
  "2016_jesen_A__42": {"A":"Najpoznatiji dubrovački komediograf jest Marin Držić, a ne Džore Držić.","C":"Autor prve hrvatske pjesničke inkunabule nije Džore Držić.","D":"Prvi hrvatski roman nije Džorino djelo; on je petrarkist."},
  "2016_jesen_A__43": {"A":"Dubravka je pastoralno-alegorijska drama, a ne poema.","B":"Osman je ep, a pitanje traži poemu.","C":"Prozerpina ugrabljena Gundulićevo je dramsko djelo, a ne poema."},
  "2016_jesen_A__44": {"A":"Božanstvena komedija ep je (spjev), a ne dramsko djelo.","B":"Oslobođeni Jeruzalem epska je poema, a ne drama.","C":"Dekameron je zbirka novela (proza), a ne dramsko djelo."},
  "2016_jesen_A__45": {"A":"Barok prethodi romantizmu i ne veže se uz pojam 'svjetske boli'.","B":"Klasicizam ističe razum i sklad, a ne romantičarski Weltschmerz.","D":"Realizam donosi objektivan prikaz stvarnosti, a 'svjetska bol' obilježje je romantizma."},
  "2016_jesen_A__46": {"A":"Matija Petar Katančić pripada hrvatskome klasicizmu/prosvjetiteljstvu, a ne romantizmu.","B":"Silvije Strahimir Kranjčević stvara u razdoblju hrvatske moderne, a ne romantizma.","D":"Vladimir Vidrić pjesnik je moderne, a ne romantizma."},
  "2016_jesen_A__47": {"A":"Zločin i kazna prati Raskoljnikova, a ne Emmu koja čezne za samostanom.","C":"Otac Goriot Balzacov je roman, a navedena rečenica govori o Emmi Bovary.","D":"Combray je Proustovo djelo i ne sadrži lik Emme."},
  "2016_jesen_A__48": {"A":"Rečenica o barunici i Dobrotvornome uredu pripada drugomu liku, a ne Ivici Kičmanoviću.","C":"Udvaranje Izabeli ('ljepša od mora i od strijele') nije Ivičin iskaz.","D":"Obraćanje Fanny ne izgovara Ivica Kičmanović."},
  "2016_jesen_A__49": {"A":"Alphonse de Lamartine romantičar je, a ne parnasovac.","B":"George Gordon Byron predstavnik je engleskoga romantizma, a ne parnasovstva.","D":"Luis de Góngora barokni je pjesnik (gongorizam), a ne parnasovac."},
  "2016_jesen_A__50": {"B":"Zlatarovo zlato povijesni je roman o Dori Krupićevoj, a ne o učitelju iz Beča.","C":"U registraturi prati Ivicu Kičmanovića, a ne lik koji se vraća iz Beča u primorski gradić.","D":"Prokleta avlija smještena je u istanbulski zatvor, a ne uz priču o učitelju iz Beča."},
  "2016_jesen_A__51": {"A":"Posljednji Stipančići donose obitelj Stipančić, a ne likove Solusa i Izabele.","C":"Kratki izlet prati skupinu na ekskurziji, bez Solusa i Izabele.","D":"U noveli Prah ne pojavljuju se Solus i Izabela."},
  "2016_jesen_A__52": {"A":"Charles Baudelaire djeluje u 19. stoljeću.","B":"Edgar Allan Poe pripada 19. stoljeću.","D":"Nikolaj Vasiljevič Gogolj stvarao je u 19. stoljeću."},
  "2016_jesen_A__53": {"A":"Karađoz je upravitelj zatvora u Prokletoj avliji, a ne vođa istraživačkoga putovanja.","B":"Kyriales je lik iz druge sredine, a ne onaj koji vodi mlade u Gradinu.","D":"Ugo nije vođa ekskurzije u Gradinu; tu skupinu predvodi Roko."},
  "2016_jesen_A__54": {"A":"Juriš nije časopis pokrenut 1952. godine.","B":"Kolo je stariji časopis i nije pokrenut 1952.","D":"Vijenac nije časopis pokrenut 1952. godine."},
  "2016_jesen_A__55": {"A":"Antun Šoljan nije autor romana Psi u trgovištu.","C":"Ivo Andrić nije napisao Pse u trgovištu.","D":"Pavao Pavličić nije autor toga romana; napisao ga je Ivan Aralica."},
  "2016_jesen_A__56": {"A":"U riječi 'ključić' nema suglasničkoga sudara koji bi izazvao jednačenje po mjestu tvorbe.","B":"U 'končić' ne dolazi do jednačenja po mjestu tvorbe.","D":"U 'kružić' nema promjene po mjestu tvorbe."},
  "2016_jesen_A__57": {"A":"U 'brkat' samoglasnik a dio je osnove i ne ispada u sklonidbi.","C":"U 'sivkast' nema nepostojanoga a koji bi nestajao u kosim oblicima.","D":"U 'uplakan' a se zadržava i nije nepostojan."},
  "2016_jesen_A__58": {"A":"'Podkrovlje' nije pravilno; ispravno je 'potkrovlje' (jednačenje po zvučnosti).","B":"'Podpalublje' nije pravilno; ispravno je 'potpalublje'.","C":"'Podpredsjednik' nije pravilno; ispravno je 'potpredsjednik'."},
  "2016_jesen_A__59": {"A":"Tri je premalo; u rečenici su četiri zanaglasnice (će, je, li, se).","C":"Pet je previše; zanaglasnica je točno četiri.","D":"Šest je previše; u rečenici su samo četiri zanaglasnice."},
  "2016_jesen_A__60": {"A":"'Izmjeniti' nije pravilno; ispravno je 'izmijeniti'.","B":"'Rješiti' nije pravilno; ispravno je 'riješiti'.","D":"Glagol 'zasjeći' u nesvršenome obliku traži drukčiji refleks; par nije potpuno pravilan kao 'smjestiti – smještati'."},
  "2016_jesen_A__61": {"B":"'Ministrica' se piše malim slovom jer je opisni naziv službe.","C":"I 'Ministrica' i 'Vanjskih' pogrešno su velikim slovom; cijeli je naziv opisan i piše se malim slovima.","D":"'Vanjskih' i 'Europskih' ovdje se ne pišu velikim slovom jer su dio opisnoga naziva službe."},
  "2016_jesen_A__62": {"A":"'Drščući' nije pravilan glagolski prilog glagola 'drhtati'.","B":"'Niječući' nije pravilan oblik glagolskoga priloga glagola 'nijekati'.","C":"'Sliječući' nije pravilan glagolski prilog glagola 'slijetati'."},
  "2016_jesen_A__63": {"A":"U 'polje' (akuzativ uz 'branili') morfem nije -e onako kako traži pitanje; gramatički je morfem druge naravi.","B":"U 'ime' završno -e dio je osnove imenice srednjega roda, a ne gramatički morfem -e.","C":"U 'rame' završno -e pripada osnovi (ramen-), a ne gramatičkomu morfemu -e."},
  "2016_jesen_A__64": {"A":"'Ruk-' prekratka je osnova; oblikotvorna osnova riječi 'rukavica' jest 'rukav-'.","B":"'Ruka-' nije oblikotvorna osnova jer je izvedenica nastala od 'rukav'.","D":"'Rukavic-' uključuje i sufiks -ic-, pa nije oblikotvorna osnova nego osnova s tvorbenim sufiksom."},
  "2016_jesen_A__65": {"A":"Riječ nije u dativu; uz prijedlog 'u' ovdje stoji instrumental.","B":"Riječ nije u akuzativu; izraz 'u odorama' instrumentalni je oblik.","C":"Iako 'u' može tražiti lokativ, ovdje oblik 'odorama' znači 'obučeni u' i u instrumentalu je."},
  "2016_jesen_A__66": {"A":"'Svojega' je posvojna (povratno-posvojna) zamjenica, a ne pokazna.","C":"'Ikomu' je neodređena zamjenica, a ne pokazna.","D":"'Svakakvim' je neodređena zamjenica, a ne pokazna."},
  "2016_jesen_A__67": {"A":"'Skačući' glagolski je prilog sadašnji nesvršenoga glagola 'skakati', a ne svršenoga 'skočiti'.","B":"'Skakajući' također je prilog sadašnji nesvršenoga glagola, a ne 'skočiti'.","D":"'Skoknuvši' tvoren je od drugoga glagola ('skoknuti'), a ne od 'skočiti'."},
  "2016_jesen_A__68": {"A":"Futur I. tvori se od 'htjeti' + infinitiv, čega ovdje nema.","B":"Futur II. tvori se od 'budem' + glagolski pridjev radni, a ovdje stoji 'bih'.","D":"Kondicional II. tvori se od 'bio bih' + pridjev radni, a ovdje je samo 'bih se čuvao'."},
  "2016_jesen_A__69": {"B":"Prijedlozi 'ispred' i 'iza' traže genitiv, ali ne mogu dijeliti istu imenicu bez ponavljanja; rečenica je neispravna.","C":"'U' traži lokativ/akuzativ, a 'oko' genitiv, pa se ne mogu vezati uz isti oblik imenice.","D":"'Sa' traži instrumental, a 'bez' genitiv, pa zajednička dopuna jednoga oblika nije gramatički ispravna."},
  "2016_jesen_A__70": {"B":"'Topovi' su vršitelj radnje (subjekt), a ne objekt.","C":"'Vojske' je nesročni atribut uz 'topovi', a ne objekt.","D":"'Generala' je atribut (čije vojske), a ne objekt radnje."},
  "2016_jesen_A__71": {"B":"'Na radiju' nije predikat; predikat je 'trajala'.","C":"'Na radiju' nije subjekt; subjekt je 'rasprava'.","D":"'Na radiju' nije objekt, nego priložna oznaka mjesta."},
  "2016_jesen_A__72": {"A":"Rečenica s 'iako' dopusna je, a ne objektna.","B":"Rečenica s 'jer' uzročna je, a ne objektna.","C":"Iako 'saznala je kako se nalazi' ima objektnu vrijednost, model traži primjer s 'da' (D) kao prototipnu objektnu rečenicu."},
  "2016_jesen_A__73": {"A":"Dvije je premalo; rečenica ima četiri surečenice.","B":"Tri je premalo; surečenica je četiri.","D":"Pet je previše; u rečenici su četiri surečenice."},
  "2016_jesen_A__74": {"A":"'Oštetiti bacanjem' glagolska je sintagma (glagol + priložna dopuna), a ne atributna.","C":"'Bacati kamen' glagolska je sintagma s objektom, a ne atributna.","D":"'Brzo bacati' priložna je (glagolsko-priložna) sintagma, a ne atributna."},
  "2016_jesen_A__75": {"A":"Rečenica o domaćim i divljim životinjama ne sadrži suvišno ponavljanje značenja (pleonazam).","C":"'Napisati pismo barunu' nema pleonazma.","D":"'Tanko razvuče tijesto' ne sadrži pleonazam."},
  "2016_jesen_A__76": {"A":"'Grančica' nastaje sufiksom -čica (grana → grančica), a ne -ica.","B":"'Klupčica' tvorena je sufiksom -čica (klupa/klupko), a ne -ica.","D":"'Stvarčica' nastaje sufiksom -čica (stvar → stvarčica), a ne -ica."},
  "2016_jesen_A__77": {"A":"Prefiksalno-sufiksalna tvorba istodobno dodaje predmetak i dometak, čega kod 'košarkaš' nema.","B":"Složeno-sufiksalna tvorba spaja dvije osnove uz sufiks, a 'košarkaš' ima samo jednu osnovu i sufiks.","D":"Slaganje povezuje dvije osnove, a 'košarkaš' je izveden samo sufiksom -aš."},
  "2016_jesen_A__78": {"A":"'Talir' je historizam (predmet više ne postoji), a ne arhaizam.","B":"'Helebarda' je historizam jer označuje izvanvremenski predmet, a ne zastarjeli naziv za nešto postojeće.","D":"'Harač' je historizam (danak iz osmanskoga doba), a ne arhaizam."},
  "2016_jesen_A__79": {"A":"Ekonimi su imena naseljenih mjesta, a 'Karlovčanin' označuje stanovnika.","B":"Eponimi su nazivi izvedeni iz vlastitih imena (npr. po osobi), a ne nazivi stanovnika.","D":"Etnonimi su nazivi naroda, a 'Karlovčanin' je etnik (naziv stanovnika mjesta)."},
  "2016_jesen_A__80": {"A":"1835. godina vezana je uz početke ilirskoga pokreta, a ne uz Deklaraciju.","B":"1850. godina vrijeme je Bečkoga književnog dogovora, a ne Deklaracije.","C":"1954. godina godina je Novosadskoga dogovora, a ne Deklaracije iz 1967."},

  // 2016_jesen_B
  "2016_jesen_B__1": {"A":"Subjekt ne bježi od stvarnosti, nego svjesno piše kako bi voljenu sačuvao od zaborava i smrti.","C":"Subjekt izrijekom kaže da nije Petrarka i da se ne nada njegovoj slavi, pa ga ne želi nadmašiti.","D":"Cilj pjevanja nije zavođenje, nego ovjekovječenje uspomene na voljenu osobu."},
  "2016_jesen_B__2": {"A":"Uspomene su rezultat pjevanja, a ne ono s čime se pisanje uspoređuje.","C":"Tamni život je tek okvir u kojem niču pjesme, a ne predmet usporedbe za pisanje.","D":"Smrt ljubavi pjesma upravo niječe ('umrijeti ipak nećeš'), pa nije slika pisanja."},
  "2016_jesen_B__3": {"B":"Ovaj stih iskazuje želju da ostavi spomen, a ne skromnost prema vlastitomu daru.","C":"Stih govori o besmrtnosti voljene osobe, a ne o skromnosti pjesnika.","D":"Stih opisuje izvor pjesama (srce), a ne podcjenjivanje vlastita umijeća."},
  "2016_jesen_B__4": {"B":"Asindeton je nizanje bez veznika, a ovdje nema niza istovrsnih članova bez veznika.","C":"Epifora je ponavljanje istih riječi na kraju stihova, čega u primjeru nema.","D":"Onomatopeja oponaša zvukove, a u stihovima nema zvukovnog oponašanja."},
  "2016_jesen_B__5": {"A":"Termin koji ispit traži jest 'unakrsna'; 'isprekidana' je tek njezin sinonim, a ne ponuđeni točan naziv.","B":"Obgrljena rima ima shemu abba, a ovdje je abab.","C":"Parna rima ima shemu aabb, a ovdje se rimuju 1.-3. i 2.-4. stih."},
  "2016_jesen_B__6": {"A":"Pripovjedač nije oduševljen, nego razočaran spoznajom o lažnoj ljepoti žene.","B":"Riječ nije o dobroti žene, nego o varci i prividu koji je razotkrio.","D":"Stih ne govori da je precijenio sebe, nego da je previše cijenio ('scienjah i saviše') ono što je vidio na ženi."},
  "2016_jesen_B__7": {"A":"U prvoj strofi žena nije bespomoćna, nego privlačna i moćna nad onima koji je gledaju.","B":"Nigdje se ne spominje pjevanje; opis se odnosi na ljepotu i zavodljivost.","C":"Vrijednost (radišnost) nije tema strofe koja ističe čar i zavodljivost."},
  "2016_jesen_B__8": {"A":"Ovaj stih govori o čežnji muškaraca za ženom, a ne o kosi.","C":"Stih opisuje lice ('suha, žuta i pjegava'), a ne kosu.","D":"Stih izriče sramotu pred prirodom (šminkanje usana), a ne kosu."},
  "2016_jesen_B__9": {"A":"Iskaz govori o tjelesnoj propalosti i starosti, a ne izravno o nemoralu.","B":"Stidljivost se ne spominje; bjelina je puder kojim se prikriva staro lice.","C":"Blijedost je tek posljedica šminkanja; bit iskaza jest da je žena stara."},
  "2016_jesen_B__10": {"B":"Septima ima sedam stihova, a strofe imaju šest.","C":"Oktava ima osam stihova, a strofe imaju šest.","D":"Stanca je osmerostih s rimom abababcc, a ovdje su šestostisi."},
  "2016_jesen_B__11": {"A":"Vjerski zanos nije tema; lik razmišlja o prolaznosti, svjetlu i vječnosti.","B":"Pejzaž (sunce, vrhunac) tek je povod, a ne tema unutarnjih razmišljanja.","C":"Polarna Zvijezda je primjer u razmišljanju o svjetlu, a ne tema teksta."},
  "2016_jesen_B__12": {"B":"Obmana se odnosi na varljiv osjet svjetlosti, a ne na ono s čime se duša uspoređuje.","C":"Svemir je prostor kroz koji duša leti, a usporedba je izrijekom 's mišlju'.","D":"Svjetlo je predmet lik ovih razmišljanja o udaljenostima, a duša se uspoređuje s mišlju."},
  "2016_jesen_B__13": {"A":"'Prenuti se' ne znači okrenuti se, nego naglo se trgnuti iz zamišljenosti.","B":"Presavijanje je tjelesna radnja koja ne odgovara značenju glagola.","D":"Zagledanje slijedi tek kasnije; 'prenu se' znači naglo se trgnuti."},
  "2016_jesen_B__14": {"A":"Ovo je pripovjedačev iskaz u 3. licu, a ne izravna misao lika u 1. licu.","B":"Rečenica je objektivan opis u 3. licu, ne unutarnji monolog.","C":"Radnja je opisana izvana u 3. licu, bez neposrednog izricanja misli lika."},
  "2016_jesen_B__15": {"A":"'Snježni vrhunac' uobičajen je opisni izraz, a ne pjesnička kovanica.","B":"'Polarna Zvijezda' je stvarni astronomski naziv, a ne poetizam.","C":"'Mliječna staza' je ustaljen naziv za galaktiku, a ne pjesnička novotvorenica."},
  "2016_jesen_B__16": {"B":"Rečenica ironično tvrdi suprotno - da čovjeka vode niske potrebe, a ne viši ciljevi.","C":"Toplina sunca nije poruka; sunce ovdje predstavlja prirodni/duhovni red kojem prethodi želudac.","D":"'Majka zemlja' je metafora, a ne tvrdnja o ovisnosti o majci."},
  "2016_jesen_B__17": {"A":"'Darmar' znači nered, a ne svatove; svatovi su završili gozbu.","B":"Riječ je o neredu na stolu, a ne o ukrasima.","C":"Jadikovke se ne spominju; sintagma označava šaroliki nered."},
  "2016_jesen_B__18": {"A":"Ovaj iskaz ruga se poluispijenoj boci, a ne govori o pojedenoj hrani.","B":"'Jela nenačeta' znači da hrana nije ni dirnuta, dakle nije pojedena.","D":"Uzvik o želucu izražava temu proždrljivosti, a ne da je hrana pojedena."},
  "2016_jesen_B__19": {"A":"Napola pune zdjele nisu 'rijetki svat'; izraz označava punu, neotvorenu bocu.","C":"Prazne zdjele su suprotnost 'rijetkomu svatu' koji je još pun.","D":"Prazna boca je suprotnost 'rijetkomu svatu' koji je upravo neotvorena, puna boca."},
  "2016_jesen_B__20": {"A":"Anadiploza je ponavljanje riječi s kraja jedne na početku iduće rečenice, čime tekst nije utemeljen.","B":"Eufemizam ublažava neugodne pojmove, a tekst počiva na oživljavanju predmeta.","C":"Oksimoron spaja proturječne pojmove, a temelj teksta jest personifikacija."},
  "2016_jesen_B__21": {"A":"Pozivi u pomoć su zvukovi iz ćelije, a grmljavina se odnosi na vrata.","C":"Tučnjava u pristaništu zaseban je motiv; grmljavina je zvuk kapije.","D":"Okrvavljeni ljudi povezani su s tučnjavom, a ne s motivom grmljavine."},
  "2016_jesen_B__22": {"B":"'Vruće od gneva' znači bijesne, a ne neobrijane; izraz se tiče stanja, ne izgleda lica.","C":"Riječ ne znači osuđene, nego ljude obuzete žestokim bijesom.","D":"Razdragane je suprotno značenje; ljudi su gnjevni, ne veseli."},
  "2016_jesen_B__23": {"B":"Gustativni podražaj tiče se okusa, čega u rečenici nema.","C":"Olfaktivni podražaj tiče se mirisa, a rečenica navodi zvukove.","D":"Vizualni podražaj tiče se viđenja, a opisani su isključivo zvukovi."},
  "2016_jesen_B__24": {"A":"Eufemizam ublažava neugodan izraz, čega u primjeru nema.","C":"Oksimoron spaja proturječne pojmove; ovdje ćelija stoji umjesto ljudi (metonimija).","D":"Onomatopeja oponaša zvuk, a primjer počiva na zamjeni mjesta za ljude."},
  "2016_jesen_B__25": {"A":"Radnja se ne odvija u Beogradu, nego u carigradskom zatvoru.","C":"Mostar nije mjesto radnje romana.","D":"Iako je Andrić bosanski pisac, radnja je smještena u Carigrad, ne u Sarajevo."},
  "2016_jesen_B__26": {"A":"Susret nije bio slučajan; stražari su sami ispričali Horaciju o pojavi.","B":"Hamlet ne obavješćuje Horacija; obrnuto, Horacije izvješćuje Hamleta.","D":"Kralj nije izvor obavijesti; o pojavi su javili stražari."},
  "2016_jesen_B__27": {"A":"Stih opisuje da je duh oklopljen, a ne njegovu blizinu svjedocima.","C":"Stih govori o Horacijevu odlasku na stražu, a ne o blizini duha.","D":"Stih uspoređuje sličnost ruku, a ne blizinu duha svjedocima."},
  "2016_jesen_B__28": {"A":"Ljubav prema sinu nije razlog; duha prekida glas pijetla u zoru.","B":"Stražari ga ne prekidaju; duh ustukne na pjev pijetla.","C":"Strah od osvete se ne spominje; uzrok je dolazak jutra (pijetao)."},
  "2016_jesen_B__29": {"A":"Stih navodi kada su doživjeli pojavu (gluho doba noći), a ne njihov strah.","C":"Stih potvrđuje istinitost pojave, a ne strah stražara.","D":"Stih opisuje nestanak duha u zoru, a ne strah stražara."},
  "2016_jesen_B__30": {"B":"Red riječi u ovome stihu je uobičajen, bez premetanja.","C":"Rečenica ima običan poredak subjekta i predikata, bez inverzije.","D":"Poredak je gramatički uobičajen, bez stilski obilježena premetanja."},
  "2016_jesen_B__31": {"A":"'Blijeda, staračka izmučena pojava' opisuje Glembaja sada u radnoj sobi, ne kako je izgledao u salonu.","C":"'Lice bolesnika' je sadašnji izgled u sobi, suprotnost salonskom; ne prikazuje salonsku pojavu.","D":"'Mlohavo i beskrvno lice' je trenutačni, bolešću obilježen izgled, a ne salonska maska."},
  "2016_jesen_B__32": {"A":"Leone ne pokušava izbjeći razgovor, nego glumom prikriva nepriliku i prividno je susretljiv.","B":"Susretu se nije iskreno razveselio; susretljivost je odglumljena.","D":"Leone se ne plaši, nego 'virtuozno svladava' svoju nepriliku."},
  "2016_jesen_B__33": {"A":"Asindeton je nizanje bez veznika, a ovdje je riječ o stupnjevitom pojačavanju.","B":"Eufemizam ublažava izraz, a rečenica zapravo pojačava napetost.","D":"Ironija izriče suprotno od mišljenoga, čega u opisu kulminacije nema."},
  "2016_jesen_B__34": {"B":"Silberbrandt se ne ukočio zbog očeve i sinove svađe, nego zbog iznenadne Glembajeve pojave.","C":"Nije se spremao napasti; reagirao je strahom 'kao u hipnozi'.","D":"Nije se nadao kraju razgovora; ukočenost je izazvana strahom od Glembaja."},
  "2016_jesen_B__35": {"B":"Barunica nije osuđena u slučaju Rupert-Canjeg; to nije razlog Glembajeva stanja.","C":"Leone ne optužuje oca za majčinu smrt, nego barunicu za nevjeru i moralne zločine.","D":"Glembay ne dolazi zbog propasti tvrtke, nego zbog Leoneove javne optužbe barunice."},
  "2016_jesen_B__36": {"B":"Elegija je tužaljka i ne smatra se izvorom tragedije.","C":"Epigram je kratka satirična pjesma, nepovezana s nastankom tragedije.","D":"Oda je svečana pohvalna pjesma, ali tragedija se razvila iz ditiramba."},
  "2016_jesen_B__37": {"A":"Raspored dugih i kratkih slogova obilježje je kvantitativne (metričke) versifikacije.","B":"Raspored naglašenih i nenaglašenih slogova obilježje je akcenatske (tonske) versifikacije.","D":"Ponavljanje broja stopa odlika je stopne versifikacije, a silabička broji slogove."},
  "2016_jesen_B__38": {"B":"Kongrion je sporedni lik (kuhar), a glavni je škrtac Euklion.","C":"Megador je susjed prosac, ne glavni lik komedije.","D":"Strobil je rob, a glavni je lik škrtac Euklion."},
  "2016_jesen_B__39": {"A":"Branimir se ne spominje na Bašćanskoj ploči; spominje se kralj Zvonimir.","B":"Trpimir se ne spominje u tekstu ploče.","C":"Višeslav se ne spominje; ploča navodi kralja Zvonimira."},
  "2016_jesen_B__40": {"A":"Dante je autor Božanstvene komedije, a ne romana o vitezu tužna lika.","B":"Boccaccio je autor Dekamerona, ne Don Quijotea.","D":"Shakespeare je dramatičar, a Don Quijotea je napisao Cervantes."},
  "2016_jesen_B__41": {"B":"'Draža je od zlata' nije Lucićeva pjesma.","C":"'Moja plavca' je pjesma A. G. Matoša, ne Lucića.","D":"'Prvi pogled' nije Lucićevo djelo."},
  "2016_jesen_B__42": {"A":"Dubravka nije religiozna poema, nego dramsko djelo.","B":"Nije učena (erudita) komedija, nego pastoralna igra.","D":"Dubravka nije lirska pjesma, nego pastirska igra (drama)."},
  "2016_jesen_B__43": {"A":"Renesansa prethodi baroku, a ne slijedi nakon njega.","C":"Romantizam dolazi tek početkom 19. st., nakon klasicizma.","D":"Realizam slijedi nakon romantizma, daleko poslije baroka."},
  "2016_jesen_B__44": {"B":"U Povratku Filipa Latinovicza nema Klare Grubar; ona je iz U registraturi.","C":"U Kiklopu se ne pojavljuje Klara Grubar.","D":"U Zlatarovu zlatu nema Klare Grubar."},
  "2016_jesen_B__45": {"A":"16. stoljeće je razdoblje renesanse, a spjev je nastao 1846.","B":"17. stoljeće je barok; spjev je objavljen u 19. st.","C":"18. stoljeće prethodi nastanku spjeva (1846.)."},
  "2016_jesen_B__46": {"A":"Dostojevski je autor Zločina i kazne te Braće Karamazovih, ne Ljudske komedije.","B":"Flaubert je autor Gospođe Bovary, ne Ljudske komedije.","D":"Gogolj je autor Mrtvih duša i Kabanice, ne Ljudske komedije."},
  "2016_jesen_B__47": {"A":"Radnja nije smještena u Dubrovnik, nego u Senj.","B":"Rijeka nije mjesto radnje romana.","D":"Zagreb nije grad u kojem se odvija radnja; to je Senj."},
  "2016_jesen_B__48": {"A":"Klasicizam je davno prije Rimbauda (17.-18. st.).","B":"Romantizam prethodi simbolizmu i Rimbaudovoj poetici.","C":"Rimbaud nije realist; pripada simbolizmu unutar modernizma."},
  "2016_jesen_B__49": {"A":"Zločin i kazna ne završava Rastignacom; on je Balzacov lik.","B":"Don Quijote ne završava ovom rečenicom; Rastignac je iz Oca Goriota.","D":"Combray (Proust) nema lik Rastignaca ni ovaj završetak."},
  "2016_jesen_B__50": {"A":"Dadaizam je nastao u Švicarskoj (Zürich), ne u Njemačkoj.","C":"Futurizam je talijanski pravac (Marinetti).","D":"Nadrealizam je francuski pravac (Breton)."},
  "2016_jesen_B__51": {"A":"'Rodu o jeziku' Preradovića pisana je vezanim stihom s rimom i metrom.","B":"'Utjeha kose' Matoša je sonet, dakle vezani stih.","D":"'Voćka poslije kiše' Cesarića ima pravilnu strofu i rimu, nije slobodan stih."},
  "2016_jesen_B__52": {"B":"Posljednji Stipančići ne završavaju ovom rečenicom; to je kraj Kiklopa.","C":"Povratak Filipa Latinovicza nema ovaj završetak.","D":"U registraturi ne završava ovako; rečenica je iz Kiklopa."},
  "2016_jesen_B__53": {"A":"Romantizam prethodi moderni i nema impresionizam, secesiju i simbolizam kao obilježja.","B":"Protorealizam (predrealizam) ne obilježavaju impresionizam i secesija.","D":"Ekspresionizam dolazi nakon moderne i počiva na drugim, oštrijim postupcima."},
  "2016_jesen_B__54": {"B":"Pupačić se ne veže uz ludizam, nego uz emotivnu, zavičajnu liriku.","C":"Kaštelan pripada ratnoj i egzistencijalnoj lirici, ne ludizmu.","D":"Mihalić nije ludistički pjesnik; njegova je poezija egzistencijalistička."},
  "2016_jesen_B__55": {"A":"Fanika Canjeg je lik iz Gospode Glembajevih, ne iz Brešanove drame.","B":"Joža Podravec nije lik te drame.","C":"Ksenija Radajeva je iz Povratka Filipa Latinovicza, ne iz Mrduše Donje."},
  "2016_jesen_B__56": {"A":"Rečenica je u kontekstu pravopisno problematična, pa nije ispravan odgovor.","B":"Oblik 'mjeh' u tome obliku nije primjeren; rečenica nije pravopisno točna.","C":"'Cjev' je pogrešno; pravilno je 'cijev'."},
  "2016_jesen_B__57": {"A":"'Bjelji' nema umetnut l; jat se kratio, ali epentetskoga l nema.","B":"'Dalji' nema epentetski l.","D":"'Življi' ima udvojeno v (jotacija), ali ne i epentetski l."},
  "2016_jesen_B__58": {"B":"U vlastitom imenu 'Olga' sibilarizacija se ne provodi (Olgi).","C":"'Vlaga' u dativu glasi 'vlazi' - to je sibilarizacija g>z, ali ispit traži k>c primjer s Osječankom.","D":"'Mazga' u dativu glasi 'mazgi', sibilarizacija se izostavlja zbog suglasničke skupine zg."},
  "2016_jesen_B__59": {"A":"Slog 'ras' nije naglašen; naglasak je na drugom slogu 'po'.","C":"Slog 'dije' nije nositelj naglaska.","D":"Slog 'li' nije naglašen u riječi raspòdijeliti."},
  "2016_jesen_B__60": {"B":"'Preporoda' velikim slovom je pogrešno; piše se malim slovom.","C":"'Narodnog' velikim slovom je pogrešno u opisnom izrazu.","D":"Pisanje svih triju riječi velikim slovom nije u skladu s pravopisnim pravilom."},
  "2016_jesen_B__61": {"A":"'Čit' nije oblikotvorna osnova; sufiks se dodaje na 'čitat-'.","B":"'Čita' nije tvorbena osnova za ovaj izvedeni oblik.","D":"'Čitatelj' je cijela riječ, a ne njezina osnova."},
  "2016_jesen_B__62": {"A":"'Goetheju' je netočno - dativ se tvori bez umetnutoga j.","C":"'Wolfgang' mora biti sklonjen u 'Wolfgangu'; oblik nije dosljedno sklonjen.","D":"'Johann Wolfgang' moraju se sklanjati (Johannu Wolfgangu); ovdje nisu."},
  "2016_jesen_B__63": {"A":"Dativ bi tražio drugi nastavak; 'književnošću' je instrumental.","B":"Akuzativ bi glasio 'književnost', a ovdje je 'književnošću' (instrumental).","C":"Lokativ bi tražio prijedlog i drugi oblik; ovdje je instrumental sredstva."},
  "2016_jesen_B__64": {"B":"'Dvjema' je zastario oblik; standardan je instrumental 'dvijema'.","C":"'Dvama' se rabi za muški/srednji rod, a uz 'učenicama' (ž. r.) traži se 'dvijema'.","D":"'Dvoma' je nestandardan oblik."},
  "2016_jesen_B__65": {"A":"'Svojemu liječniku' odgovara na 'komu/kamo', a ne na 'kuda'.","C":"'Na velesajam' odgovara na 'kamo' (cilj), a ne na 'kuda' (put).","D":"'U kazalište' odgovara na 'kamo', a ne na 'kuda'."},
  "2016_jesen_B__66": {"A":"Uz subjekt 'mi' suvišna je posvojna zamjenica 'naših'; trebalo bi 'svojih'.","B":"Subjekt 'mi' posjeduje uspjehe, pa je 'našim' suvišno; ispravno bi bilo 'svojim'.","C":"Subjekt 'mi' traži povratno-posvojnu 'svoje', a ne 'naše'."},
  "2016_jesen_B__67": {"A":"Aorist je prošlo svršeno vrijeme, a 'dođi' izriče zapovijed.","C":"Imperfekt je prošlo nesvršeno vrijeme, a 'dođi' je imperativ.","D":"Prezent izriče sadašnjost, a 'dođi' je zapovjedni oblik."},
  "2016_jesen_B__68": {"A":"Pravilno je 'htio', a ne 'htjeo'.","B":"Pravilno je 'smio', a ne 'smjeo'.","C":"Pravilno je 'uspio', a ne 'uspjeo'."},
  "2016_jesen_B__69": {"A":"Ispred 'č' (čestim) pravilan je prijedlog 's', ne 'sa'.","C":"Ispred 'p' (psima) pravilan je 's', a 'sa' se rabi samo ispred s, š, z, ž i određenih skupina.","D":"Ispred 'lj' (ljetnim) pravilan je 's', ne 'sa'."},
  "2016_jesen_B__70": {"A":"'Nadzorna kamera' povezuje se slaganjem (sročnošću), a ne upravljanjem.","C":"'Prvi natjecatelj' počiva na slaganju pridjeva i imenice, ne na upravljanju.","D":"'Brzo šetati' počiva na pridruživanju priloga, ne na upravljanju."},
  "2016_jesen_B__71": {"A":"'Iz Istre' uz 'napisao knjigu' priložna je oznaka, a ne atribut.","B":"'Iz Istre' označava mjesto odlaska gostiju (priložna oznaka mjesta), ne atribut.","C":"'Iz Istre' uz glagol 'došao' je priložna oznaka mjesta, ne atribut."},
  "2016_jesen_B__72": {"A":"Predikat 'sam znao' ima izrečen subjekt (ja), pa zavisna rečenica nije subjektna nego objektna.","B":"Predikat 'su znali' ima subjekt (oni); zavisna je rečenica objektna.","D":"Predikat 'je znao' ima subjekt (on); zavisna je rečenica objektna."},
  "2016_jesen_B__73": {"B":"Predikat je 'moraju odvesti', a ne 'je'.","C":"'Je' nije priložna oznaka, nego objekt (nju).","D":"Subjekt nije izrečen tom zamjenicom; 'je' je objekt radnje."},
  "2016_jesen_B__74": {"B":"Korijen je dio biljke (suhiponim), a ne nadređeni pojam cvijetu.","C":"List je dio biljke, a ne nadređeni pojam cvijetu.","D":"Tulipan je vrsta cvijeta (hiponim), a ne nadređeni pojam."},
  "2016_jesen_B__75": {"B":"'Književno razdoblje' nije pleonazam; pridjev donosi novu obavijest.","C":"'Sljedeće razdoblje' nije pleonazam; pridjev nije sadržan u imenici.","D":"'Dugo razdoblje' nije pleonazam; trajanje nije već uključeno u značenje imenice."},
  "2016_jesen_B__76": {"A":"'Sklanjati' znači deklinirati imenske riječi, a ne sprezati glagole.","B":"'Slagati' nije gramatički sinonim za konjugiranje.","D":"'Sricati' znači izgovarati slovo po slovo, nepovezano s konjugacijom."},
  "2016_jesen_B__77": {"B":"'Povući koga za jezik' znači navesti koga da kaže više nego što želi - suprotno od šutnje.","C":"'Naći zajednički jezik' znači postići sporazum, ne suzdržati se od govora.","D":"'Imati dug jezik' znači previše brbljati, suprotno od suzdržanosti."},
  "2016_jesen_B__78": {"A":"'Impresionizam' je izveden od riječi 'impression', a ne od osobnog imena.","B":"'Larpurlartizam' potječe od izraza 'l'art pour l'art', ne od imena osobe.","C":"'Simbolizam' je izveden od 'simbol', a ne od imena lika."},
  "2016_jesen_B__79": {"A":"Posuđenice iz španjolskoga su hispanizmi, ne galicizmi.","C":"Posuđenice iz talijanskoga su talijanizmi, ne galicizmi.","D":"Posuđenice iz latinskoga su latinizmi, ne galicizmi."},
  "2016_jesen_B__80": {"B":"U 17. st. tiskan je Habdelićev Dictionar, ali prvi je Vrančićev iz 1595. (16. st.).","C":"18. stoljeće je prekasno; prvi rječnik tiskan je 1595.","D":"19. stoljeće je daleko nakon prvoga rječnika (1595.)."},

  // 2016_ljeto_A
  "2016_ljeto_A__1": {"A":"Stih govori o savjetu zemlje gdje što posaditi, a ne o sjedinjenju života i smrti.","B":"Stih se odnosi na sijanje trave za društvo živici, što nije veza života i smrti.","C":"Stih opisuje pad lirskog subjekta u jamu, dakle samo smrt, bez spoja sa životom."},
  "2016_ljeto_A__2": {"A":"Grah se spominje kao biljka koju treba posaditi, a ne kao ono s čim se uspoređuje kikiriki.","C":"Trava (travica) sije se za društvo živici i nije usporedba za kikiriki.","D":"Trešnja se navodi kao biljka koja na mjestu manjka, a ne kao usporedba kikirikiju."},
  "2016_ljeto_A__3": {"A":"Breskva je samo jedna od biljaka koje se sade i ne obraća se lirskom subjektu.","B":"Kikiriki tek na kraju izniče iz zemlje i ne progovara lirskom subjektu.","C":"Taština je apstraktan pojam koji zemlja prihvaća, a ne govornik koji se obraća."},
  "2016_ljeto_A__4": {"A":"Hrabrost ne odgovara značenju taštine kao sujete i oholosti.","B":"Poniznost je upravo suprotnost taštini, pa ne može biti njezino značenje.","C":"Radoznalost se ne podudara sa značenjem taštine kao uobraženosti."},
  "2016_ljeto_A__5": {"A":"U 'prihvati moju taštinu' poredak je uobičajen (glagol + objekt s atributom), bez premještanja.","B":"'padoh ko ono neživo tijelo' redovit je red riječi s usporedbom, a ne inverzija.","D":"'tako se opet ponovih' ima normalan poredak priloga i glagola, bez obrnutog reda."},
  "2016_ljeto_A__6": {"B":"Čeljad je, zajedno sa stražama, bila uspavana, a ne budna.","C":"Oloferno je tvrdo zaspao ('zaspa većma gori nego morski medvid'), dakle nije ostao budan.","D":"Stražari su pali u san ('jesu l' straže pale'), pa nisu ostali budni."},
  "2016_ljeto_A__7": {"A":"Medvjed se javlja samo kao usporedba za Olofernov san, a ne kao onaj koji 'jiše kao volovi'.","B":"Sluškinja (Abra) stoji budna na straži i ne odnosi se na proždrljivost iz stiha.","C":"Stoka se ne spominje kao oni koji jedu; usporedba s volovima odnosi se na stražare."},
  "2016_ljeto_A__8": {"A":"'Komora' (komori) neutralan je naziv za prostor, bez pogrdnog prizvuka.","B":"'Ložnica' označava spavaću odaju i nema pogrdno značenje.","D":"'Zastore postilji razmače' opisuje radnju s posteljnim zastorima, bez pogrdnog naziva za šator."},
  "2016_ljeto_A__9": {"A":"Auditivni podražaj veže se uz zvuk, a 'mehka' se odnosi na dodir.","B":"Olfaktivni podražaj veže se uz miris, što 'mehka' ne izražava.","D":"Vizualni podražaj veže se uz vid (npr. 'bila'), dok 'mehka' upućuje na dodir."},
  "2016_ljeto_A__10": {"A":"Eufemizam je ublažavanje neugodnog pojma, čega u usporedbi sa snom medvjeda nema.","B":"Gradacija je postupno stupnjevanje, a ovdje je posrijedi jednostavna usporedba.","C":"Personifikacija pridaje ljudske osobine neživomu, što ovdje izostaje."},
  "2016_ljeto_A__11": {"A":"Pitanje o broju devet izražava zbunjenost svjedoka, ne i ranjenikovu smrt.","B":"'On krvari!' opisuje da ranjenik krvari dok je još živ, a ne da je umro.","C":"Istrgnuta kanila i agonija opisuju umiranje u tijeku, ne i nastup smrti."},
  "2016_ljeto_A__12": {"A":"Grof komandant slavi u sjenici i ne spašava ranjenika.","C":"Paljenje svijeće povezano je sa smrću broja devet, a ne s grofom u sjenici.","D":"Baklju grof nosi na ranijoj bakljadi, a u sjenici slavi pobjedu uz zveket čaša."},
  "2016_ljeto_A__13": {"B":"Eufemizam ublažava neugodan pojam, ali ovdje je riječ o suprotstavljanju veselja i smrti.","C":"Gradacija je stupnjevanje, dok je ovdje posrijedi oštra suprotnost dviju slika.","D":"Oksimoron spaja proturječne pojmove u sintagmu, a ovdje su nasuprotne cijele slike (antiteza)."},
  "2016_ljeto_A__14": {"A":"U tekstu nema naznake da Vidović šuti iz straha od reakcija drugih ranjenika.","B":"Zveket čaša dolazi izvana, ali nije razlog Vidovićeve nemogućnosti da progovori.","D":"Kanilu si istrgnuo broj devet, a ne Vidović, pa to nije razlog njegove nijemosti."},
  "2016_ljeto_A__15": {"B":"Ratni zarobljenik nije malteški vitez; tako je nazvan grof komandant.","C":"Broj devet je ranjenik koji umire, a ne malteški vitez.","D":"Bolničar nije malteški vitez; taj naziv odnosi se na grofa komandanta."},
  "2016_ljeto_A__16": {"A":"Učitelj je doveo dječaka da izuči zanat, ali posvojenje nije bilo na njegov zahtjev.","B":"Mlada gazdarica (Magda) bila je oprezna i odgađala posvojenje, nije ga željela.","C":"Župnik se tek slaže s ocjenom o dječakovu talentu, što nije razlog majstorove želje za posvojenjem."},
  "2016_ljeto_A__17": {"A":"Procjena 'budući Meštrović' učiteljev je sud o talentu, a ne Magdin stav.","B":"'A sirota, sam na svijetu' suosjećajna je opaska, ne i Magdin (negativan) stav prema Lojzu.","D":"'Lojz od mramora' odnosi se na kip na grobu, a ne na Magdin odnos prema Lojzu."},
  "2016_ljeto_A__18": {"A":"Pravednost se ne povezuje sa sintagmom; riječ je o mramornom liku, kipu.","B":"Hladnoća nije značenje sintagme koja opisuje kameni kip na grobu.","C":"Grob je od granita, a 'Lojz od mramora' jest kip koji na njemu sjedi, ne sam grob."},
  "2016_ljeto_A__19": {"B":"Majstor Albert je klesar i ne poučava pisanju.","C":"Slikanje nije zanat koji majstor klesar prenosi dječaku.","D":"Sviranje nema veze s klesarskim zanatom kojim se majstor bavi."},
  "2016_ljeto_A__20": {"A":"Kip je postavljen na Magdin grob, a ne na grob njezina supruga.","B":"Fridin suprug ne spominje se kao pokojnik na čiji bi grob kip bio postavljen.","C":"Učiteljev grob nije mjesto na koje je postavljen kip."},
  "2016_ljeto_A__21": {"A":"U tekstu nema naznake da pripovjedaču smeta slatkorječivost gospođice Swann.","B":"Pripovjedač joj se divi i ne izražava zavist na njezinu bogatstvu.","C":"Riječ je o pripovjedačevu žudnom divljenju, a ne o uzvraćenoj ljubavi."},
  "2016_ljeto_A__22": {"B":"Gospođica Swann ne vodi glavnu riječ; usporedba se odnosi na pratetku u pripovjedačevoj kući.","C":"Pripovjedač ne vodi razgovore; glavnu riječ vodi pratetka.","D":"Bergotte je gost obitelji Swann, a u pripovjedačevoj kući glavnu riječ vodi pratetka."},
  "2016_ljeto_A__23": {"A":"Pripovjedač zamišlja njezinu naklonost, a ne da je ona zbunjena njegovom pojavom.","B":"Predstavljanje roditeljima nije ono što pripovjedač zamišlja.","C":"Spomenike gospođici razgledava uz Bergottea; pripovjedač joj ih ne pokazuje."},
  "2016_ljeto_A__24": {"A":"Pratetka (rođakinja) ne uspoređuje se s bogovima.","C":"Gospođica Swann nije ona koja silazi među smrtnike poput bogova.","D":"Proročica iz Delfa služi kao usporedba za Bergotteove izjave, a ne kao biće slično bogovima."},
  "2016_ljeto_A__25": {"A":"'Biće obdareno rijetkom srećom' nema unutarnje proturječje, dakle nije paradoks.","B":"'U moru povlastica kupa' metaforički je izraz, ne i paradoks.","C":"'Tri sjajem obasjana sloga' opisni je izraz bez proturječja."},
  "2016_ljeto_A__26": {"A":"Hamlet ne pripovijeda o prijetnjama kraljevima, nego o razotkrivanju urote protiv sebe.","C":"Božja uloga u sudbini samo je usputna misao, a ne tema njegova pripovijedanja.","D":"U ulomku nema okivanja mornarima; Hamlet priča kako je otkrio nalog za svoje smaknuće."},
  "2016_ljeto_A__27": {"B":"Misao o propasti mudrih planova izriče sam Hamlet, ali je Horacije ne potvrđuje izrijekom.","C":"Tvrdnju o nepromišljenosti hrabrih Horacije ne potvrđuje.","D":"Misao o samostalnom djelovanju ne potvrđuje Horacije; on potvrđuje da Bog oblikuje sudbe."},
  "2016_ljeto_A__28": {"A":"Hamlet zahvaljuje hrabrosti, a ne mudrom planu, jer planovi katkad zataje.","B":"Sudbina se spominje kao Božje djelo, ali Hamlet zahvaljuje vlastitoj smjelosti.","D":"Bog se spominje kao onaj koji oblikuje sudbe, no Hamlet izrijekom zahvaljuje svojoj hrabrosti."},
  "2016_ljeto_A__29": {"A":"Glava se spominje u nalogu o smaknuću, ali nije predmet uzvičnog obraćanja.","C":"Sjekira se ne apostrofira u ovom ulomku.","D":"Spise Hamlet traži i krade, ali im se ne obraća usklikom."},
  "2016_ljeto_A__30": {"A":"Predaja danske krune Norveškoj nije sadržaj Hamletove prepravljene zapovijedi.","B":"Privođenje stražara koji su vidjeli duha nema veze s prepravljenim pismom.","D":"Poziv glumaca u dvorac dio je ranije radnje, a ne novonapisane zapovijedi."},
  "2016_ljeto_A__31": {"A":"Leone ne zaključuje da samo matematičari mogu biti slikari, nego dvoji o vlastitu radu.","C":"Težnja realističnosti nije posljedica raskola; Leone se poziva na apstraktnu matematiku.","D":"Leone ne odustaje od slikanja, nego sumnja u njegovu vrijednost ('diletantizam')."},
  "2016_ljeto_A__32": {"A":"Intuitivističkoj spoznaji Angelika se ne protivi; ona zapravo odbacuje razum.","B":"Kriticizam nije način spoznaje kojemu se Angelika suprotstavlja.","D":"Senzualizmu se ne protivi; odbacuje upravo razumsko (racionalno) poniranje."},
  "2016_ljeto_A__33": {"A":"Poštovanje tradicionalnih vrijednosti nije Angelikina misao.","C":"Život u skladu sa zakonima nije ono što Angelika iznosi.","D":"Umjetnost kao uporište nije njezina poruka; ona govori o ograničenosti spoznaje."},
  "2016_ljeto_A__34": {"A":"Matematička koordinacija Leoneov je pojam o određivanju stvari, a ne Angelikina usporedba za život.","B":"Logično poniranje spominje se kao ono čemu se Angelika protivi, ne kao usporedba za život.","D":"Romantično uzdizanje nije slika kojom Angelika opisuje život."},
  "2016_ljeto_A__35": {"A":"Aretej je samostalna drama, ne dio glembajevske trilogije.","B":"Kraljevo pripada ekspresionističkim dramskim tekstovima, a ne glembajevskom ciklusu.","D":"Legenda nije dio glembajevske trilogije."},
  "2016_ljeto_A__36": {"A":"Mojsije Kranjčevića nije sonet.","C":"Svakidašnja jadikovka Ujevića nije pisana u obliku soneta.","D":"Prsten Tadijanovića nije sonet."},
  "2016_ljeto_A__37": {"B":"Rimovanje nije temelj kvantitativne versifikacije, nego izmjena dugih i kratkih slogova.","C":"Jednak broj naglašenih slogova obilježje je akcenatske, a ne kvantitativne versifikacije.","D":"Jednak broj slogova obilježje je silabičke versifikacije, a ne antičke kvantitativne."},
  "2016_ljeto_A__38": {"A":"Alkej je grčki pjesnik, ne rimski.","B":"Anakreont je grčki liričar, a ne rimski autor.","D":"Pindar je grčki pjesnik, ne predstavnik rimske antičke književnosti."},
  "2016_ljeto_A__39": {"B":"Kongrion je kuhar u komediji, a ne glavni lik škrtac.","C":"Megador je susjed i prosac, ne glavni lik.","D":"Strobil je rob, a ne glavni lik Euklion."},
  "2016_ljeto_A__40": {"A":"Držiha je u Bašćanskoj ploči zabilježen u vezi s darivanjem zemljišta, a ne kao graditelj crkve.","C":"Kosmat se ne navodi kao graditelj crkve svete Lucije.","D":"Pribineg se ne spominje kao graditelj crkve; graditelj je Dobrovit."},
  "2016_ljeto_A__41": {"A":"Dante je autor Vita nuove i Božanstvene komedije, a ne zbirke soneta prijatelju i crnoj gospi.","B":"Petrarcin Kanconijer posvećen je Lauri, a ne prijatelju i crnoj gospi.","C":"Boccaccio je poznat po Dekameronu, a ne po toj zbirci soneta."},
  "2016_ljeto_A__42": {"A":"Hektorović ne pripada dubrovačkome krugu.","C":"Hektorović nije pripadnik splitskoga kruga.","D":"Hektorović nije pripadnik zadarskoga kruga; pripadao je hvarskome."},
  "2016_ljeto_A__43": {"A":"Plandovanja nisu barokni ep, nego zbirka lirike.","B":"Crkveno prikazanje nije književna vrsta zastupljena u Plandovanjima.","D":"Melodrama nije vrsta zastupljena u Bunićevoj zbirci."},
  "2016_ljeto_A__44": {"A":"Razgovor ugodni naroda slovinskoga zbirka je pjesama o narodnoj povijesti, nije upućena slavonskome seljaku.","B":"Matijaš grabancijaš dijak je kajkavska komedija, a ne djelo upućeno slavonskome seljaku.","D":"Cvit razgovora Grabovca nije djelo upućeno slavonskome seljaku."},
  "2016_ljeto_A__45": {"A":"Agovanje prikazuje Smail-agu i njegovo nasilje, a ne noćni pohod iz navedenih stihova.","C":"Četa opisuje okupljanje i polazak osvetnika, a ne noćno šuljanje pojedinca iz stihova.","D":"Harač prikazuje ubiranje danka, a ne noćni pohod kojemu pripadaju ovi stihovi."},
  "2016_ljeto_A__46": {"B":"Davanje prednosti dužnosti nad strastima obilježje je klasicizma, ne romantizma.","C":"Socijalno-psihološka motivacija likova svojstvena je realizmu.","D":"Biološka motivacija likova obilježje je naturalizma."},
  "2016_ljeto_A__47": {"A":"Kovačić nije autor programatskoga članka Naša književnost.","C":"Kumičić nije autor toga članka, premda piše programatske tekstove o naturalizmu.","D":"Novak nije autor članka Naša književnost."},
  "2016_ljeto_A__48": {"B":"Istodobna radnja na više mjesta nije obilježje Nore (jedinstvo mjesta).","C":"Prekidanje radnje songovima obilježje je epskog kazališta, a ne Ibsenove Nore.","D":"Lakrdija s tragičnim svršetkom ne opisuje Noru kao analitičku dramu."},
  "2016_ljeto_A__49": {"A":"Ivica Kičmanović ne provodi djetinjstvo u Dalmatinskoj zagori.","B":"Junak romana ne odrasta u Gorskome kotaru.","C":"Hrvatsko primorje nije mjesto junakova djetinjstva; to je Hrvatsko zagorje."},
  "2016_ljeto_A__50": {"A":"Đuro Andrijašević lik je iz Bijega, a ne filolog koji pronalazi Osmanova pjevanja.","C":"Marko Barić nije filolog koji na Lastovu nalazi izgubljena pjevanja Osmana.","D":"Mihovil Vrančić nije lik koji pronalazi izgubljena pjevanja Osmana."},
  "2016_ljeto_A__51": {"A":"Šimić nije autor stihova o petrolejskoj lampi; njegova je poetika drukčija (slobodni stih).","B":"Matoš nije autor navedenih stihova iz Slapa.","D":"Tadijanović nije autor tih stihova."},
  "2016_ljeto_A__52": {"A":"Atma nije lik koji izgovara ovu rečenicu o 'šmrku' i Vječnosti.","B":"Maestro nije govornik ove rečenice.","D":"Ugo nije onaj koji izgovara rečenicu; to je Melkior."},
  "2016_ljeto_A__53": {"B":"Mihalićeva pjesma ne pripada ludističkome pjesništvu.","C":"Pupačićeva pjesma nije ludistička.","D":"Kaštelanova pjesma ne pripada ludizmu."},
  "2016_ljeto_A__54": {"A":"Patnje mladoga Werthera završavaju Wertherovom smrću (samoubojstvom), a ne čekanjem smaknuća pred gledateljima.","B":"Zločin i kazna ne završava navedenom rečenicom o smaknuću.","C":"Otac Goriot ne završava tom rečenicom."},
  "2016_ljeto_A__55": {"A":"Fanika Canjeg nije lik iz Brešanove drame.","B":"Joža Podravec ne pojavljuje se u Predstavi Hamleta.","C":"Justa Medonić nije lik te drame."},
  "2016_ljeto_A__56": {"A":"'Odvlačenje' nije pravopisno točan oblik tražene riječi.","C":"'Tlačenje' nije točan odgovor u zadanome nizu.","D":"'Zračenje' nije traženi pravopisno točan primjer."},
  "2016_ljeto_A__57": {"A":"U paru 'namještati - namiještam' jedan je oblik pogrešan.","B":"Par 'presjeći - presijecem' sadrži nepravilan oblik.","C":"Par 'prorjediti - prorijedim' ima pogrešno napisan oblik."},
  "2016_ljeto_A__58": {"A":"U 'izbijeljen' nema epentetskoga l.","C":"U 'prepolovljen' l je dio osnove, a umetnuto je sonantsko l drukčije naravi nego u 'ostakljen'? Riječ je o epentezi u 'ostakljen', dok 'prepolovljen' nije traženi primjer.","D":"U 'zamagljen' nema epentetskoga l koji nastaje od osnove na -kl."},
  "2016_ljeto_A__59": {"A":"U 'biljčica' nije provedena palatalizacija.","B":"U 'cjevčica' nije provedena palatalizacija.","D":"U 'klupčica' nije provedena palatalizacija."},
  "2016_ljeto_A__60": {"A":"'On' je naglašena osobna zamjenica, dakle nije nenaglasnica.","C":"'Već' je naglašeni prilog, a ne klitika.","D":"'Tri' je naglašeni broj, a ne nenaglasnica."},
  "2016_ljeto_A__61": {"A":"'Carloa Goldoni-ja' netočno je: ime se piše Carla, a crtica je suvišna.","B":"'Carloa Goldonia' netočno je u oblику imena Carlo (treba Carla) i u nastavku.","C":"'Carla Goldoni-a' netočno je zbog suvišne crtice i izostalog j u genitivu Goldonija."},
  "2016_ljeto_A__62": {"B":"Ispred suprotnog veznika 'a' nedostaje zarez, pa rečenica nije pravopisno točna.","C":"Iza priložnog izraza 'Unatoč zabranama' zarez je suvišan.","D":"Ispred upitnog dijela 'zašto ste otišli' nedostaje zarez (umetnuti vokativ/upit nije odvojen)."},
  "2016_ljeto_A__63": {"A":"'bro-do-vi' slogovna je, a ne morfemska rasčlamba.","C":"'brod-ovi' spaja sufiks i nastavak u jednu cjelinu, pa nije potpuna morfemska analiza.","D":"'brodov-i' krivo dijeli osnovu jer ne odvaja sufiks -ov- od korijena brod-."},
  "2016_ljeto_A__64": {"A":"Dativ ne dolazi uz prijedlog 'među'.","B":"Akuzativ uz 'među' označava smjer (kamo), a ovdje je riječ o mjestu (gdje), dakle instrumental.","C":"Lokativ ne dolazi uz prijedlog 'među'."},
  "2016_ljeto_A__65": {"A":"Prijedloga je više od dva; u rečenici ih je četiri (o, s, po, nakon).","B":"Prijedloga nije tri, nego četiri.","D":"Prijedloga nije pet, nego četiri."},
  "2016_ljeto_A__66": {"B":"'ledac koja su me boljela' slaže se sa srednjim rodom množine, a ne sa ženskim rodom.","C":"'vrata koja su se otvorila' srednji su rod (pluralia tantum), ne ženski.","D":"'prsa koja su se nadimala' srednji su rod množine, a ne ženski rod."},
  "2016_ljeto_A__67": {"A":"'na školsku dvorištu' netočan je oblik; treba 'na školskome dvorištu'.","C":"'onomu duhovitu voditelju' u datoj rečenici nije traženi točan oblik pridjeva.","D":"'bio nezaboravni' netočno je; u predikatnoj službi traži se neodređeni oblik 'nezaboravan'."},
  "2016_ljeto_A__68": {"A":"'Treći' je redni broj, a ne brojevna imenica.","C":"'Triju' je broj (sklonidbeni oblik od tri), a ne brojevna imenica.","D":"'Pet' je glavni broj, a ne brojevna imenica."},
  "2016_ljeto_A__69": {"B":"'glodeći' nije pravilan glagolski prilog glagola glodati.","C":"'glodeći' nije ispravan oblik glagolskoga priloga od glodati.","D":"'glodući' nije pravilan glagolski prilog glagola glodati."},
  "2016_ljeto_A__70": {"A":"U glavnoj surečenici netočno stoji 'budem oživio' umjesto futura I. 'ću oživjeti'.","C":"U zavisnoj surečenici netočno je 'ako ću pregledavati'; treba futur II. 'budem pregledavao'.","D":"U zavisnoj surečenici ne dolazi futur I. ('ako ću pregledavati'), nego futur II."},
  "2016_ljeto_A__71": {"A":"'grad' je muški rod jednine, a 'Vodice' ženski rod množine, dakle ne slažu se.","B":"'jezero' je srednji rod jednine, a 'Sabljaci' muški rod množine.","D":"'selo' je srednji rod jednine, a 'Petrijanec' muški rod jednine."},
  "2016_ljeto_A__72": {"A":"U 'prikazan je film' imenica film je subjekt, a ne objekt.","C":"'U drugome dijelu filma' film je u genitivu kao atribut, a ne objekt.","D":"'U jučerašnjemu filmu' film je priložna oznaka mjesta, a ne objekt."},
  "2016_ljeto_A__73": {"A":"'Bez obzira na sav trud' priložna je oznaka dopuštanja, a ne načina.","B":"'zbog njezina negodovanja' priložna je oznaka uzroka, a ne načina.","D":"'k nama' i 'na čašicu razgovora' oznake su mjesta/namjere, a ne načina."},
  "2016_ljeto_A__74": {"B":"'Kako bih kupila haljinu' namjerna je rečenica, a ne uzročna.","C":"'kako mogu odabrati haljinu' izrična je rečenica, a ne uzročna.","D":"'kako su haljine skupe' izrična je rečenica, a ne uzročna."},
  "2016_ljeto_A__75": {"A":"Antonimija je suprotnost značenja, a ovdje su oblici isti uz različita značenja (homonimija).","C":"Kohiponimija je odnos suznačnica pod istim nadređenim pojmom, što ovdje nije slučaj.","D":"Sinonimija je istoznačnost, a ove riječi imaju različita značenja."},
  "2016_ljeto_A__76": {"A":"'želimo' je prezent (1. l. mn.), a ne kanonski (osnovni rječnički) oblik.","C":"'njegovu' je sklonjeni oblik posvojne zamjenice, a ne kanonski oblik.","D":"'prijateljicu' je akuzativ, a ne kanonski (nominativni) oblik."},
  "2016_ljeto_A__77": {"B":"'nesretan' nastaje prefiksalnom tvorbom (ne- + sretan), bez sufiksa.","C":"'podstanarka' nastaje sufiksalnom tvorbom od podstanar (+ -ka), a prefiks je već u osnovi.","D":"'prašumski' nastaje sufiksalnom tvorbom od prašuma (+ -ski)."},
  "2016_ljeto_A__78": {"A":"Arhaizmi su zastarjele riječi za pojmove koji i danas postoje, dok je surka naziv za predmet iz prošloga doba.","C":"Novotvorenice su novonastale riječi, a surka je naziv za odjeću iz prošlosti.","D":"Oživljenice su ponovno oživljene riječi, što surka nije."},
  "2016_ljeto_A__79": {"A":"'Hrvatska' je horonim (ime države), a ne ktetik.","B":"'Hrvati' je etnonim (ime naroda), a ne ktetik.","C":"'Splićanin' je etnik (stanovnik mjesta), a ne ktetik (pridjev)."},
  "2016_ljeto_A__80": {"A":"Hrvatsko-njemačko-talijanski rječnik znanstvenoga nazivlja nije Habdelićevo djelo (Šulek/Mažuranić).","C":"Gazofilacij je rječnik Ivana Belostenca, a ne Jurja Habdelića.","D":"Blago jezika slovinskoga rječnik je Jakova Mikalje, a ne Habdelića."},

  // 2016_ljeto_B
  "2016_ljeto_B__1": {"A":"Taj stih iz prvoga katrena uvodi sliku snivanja domovine kao Petrarkine Laure, ali samo opisuje doživljaj, a ne sažima zaključnu misao pjesme.","B":"Stih opisuje prognanikovo skrivanje u svjetini, dakle dio je naracije o situaciji, a ne zaključna poanta soneta.","C":"Suprotnost lirskoga ja i onih koji slobodno ulaze u crkvu pojačava bol, ali to je još slika prilika, a ne sažeta poruka cijele pjesme."},
  "2016_ljeto_B__2": {"A":"Drijemanje ('kunjah vani') posljedica je njegova položaja izvan crkve, a ne razlog zbog kojega nije ušao.","C":"Plač ('suza mi je krišom pala') izraz je ganuća, a ne uzrok ostajanja izvan crkve.","D":"Prošenje je samo usporedba ('ko prosjak'), a ne stvaran razlog; nije ušao jer se krio od pandura."},
  "2016_ljeto_B__3": {"A":"'Drven' znači načinjen od drva, što ne odgovara značenju 'drevan' (star) u stihu o portalu.","B":"'Lijep' opisuje estetsku vrijednost, a 'drevan' upućuje na starinu, ne na ljepotu.","C":"'Sjajan' znači blistav ili izvrstan, što nije značenje pridjeva 'drevan' (star, starinski)."},
  "2016_ljeto_B__4": {"A":"Glagol 'sjala' (zastava sjala) neutralan je opis i ne pripisuje neživomu predmetu ljudsku osobinu.","B":"Padanje suze doslovan je tjelesni opis lirskoga ja, a ne pripisivanje ljudske osobine neživomu.","D":"Zvuk koji 'luta' dio je poredbe, no eksplicitna personifikacija s ljudskom emocijom je 'zvona zaplakala od sreće'."},
  "2016_ljeto_B__5": {"A":"Uzvik o ludom sanku iskaz je lirskoga ja, bez množinske zamjenice koja bi upućivala na lirsko mi.","B":"'Sam se skrio' govori pojedinac (lirsko ja), nema kolektivne zamjenice 'mi'/'nam'.","D":"Iako govori o Hrvatu općenito, izrečeno je u 3. licu (gnomska tvrdnja), a ne kroz lirsko mi s zamjenicom 'nam'."},
  "2016_ljeto_B__6": {"A":"Čengić je Novicin gospodar (aga), a ne onaj koji se noću krade ka Crnoj Gori.","B":"Tekst izrijekom negira: 'Nit je hajduk' — pretpostavka o hajduku odbacuje se.","D":"Tekst izrijekom negira: 'nit uhoda turska' — pretpostavka o uhodi odbacuje se."},
  "2016_ljeto_B__7": {"B":"Vuk se spominje kao slika opasnosti ('gorski vuče'), pa je on po značenju blizak guji, a ne suprotstavljen.","C":"Hajduk je također prijetnja koje se Novica boji, pa nije suprotnost agresivnoj guji.","D":"Junak označava snagu i hrabrost, a kontrast guji u tekstu gradi se bojažljivim zecom, ne junakom."},
  "2016_ljeto_B__8": {"A":"Gradacija je postupno stupnjevanje, a ovdje se radi o pitanju, negaciji i odgovoru, što je obrazac antiteze.","B":"Hiperbola je pretjerivanje, a u navedenim stihovima nema preuveličavanja, nego pitanje-negacija-odgovor.","D":"Stalna usporedba povezuje dvije pojave veznikom poredbe, čega ovdje nema; struktura je pitanje, poricanje i rješenje."},
  "2016_ljeto_B__9": {"A":"U stihu o junaku oblik 'junak' stoji u nominativu, bez vokativne zamjene.","C":"'Vitoroga' je pridjev u genitivu uz 'volova stada', nema zamjene nominativa vokativom.","D":"U stihu o vilama nema imenice u vokativu koja bi stajala umjesto nominativa."},
  "2016_ljeto_B__10": {"A":"Strah od Crnogoraca proturječi tekstu jer Novica upravo ide k Crnoj Gori, a ne bježi od nje.","B":"Nada u bijeg od Turaka nije ono što ga 'naprijed kreće'; pokreće ga snažan unutarnji poriv, osveta.","C":"Tekst izrijekom poriče da je uhoda ('nit uhoda turska'), pa dužnost uhođenja nije njegov motiv."},
  "2016_ljeto_B__11": {"A":"Tekst ne spominje da su ga sugovornici gledali svisoka; sam je promatrao njih i sebe.","C":"O njegovu nižem društvenom položaju nema potvrde u tekstu; on je gost na objedu kod vlastelina.","D":"Nezadovoljstvo hranom nije razlog; naprotiv, razgovor o jestvinama poslije ga je razveselio."},
  "2016_ljeto_B__12": {"A":"'Društvo ga razvedrilo' odnosi se na početni dolazak i nije neposredni antonim izrazu o prolasku zlovolje.","B":"'U početku bijaše mrk' označava upravo loše raspoloženje, dakle je istoznačno, a ne suprotno izrazu o nestajanju zlovolje.","D":"'Kako ga nešto oživljuje' odnosi se na kasniji emocionalni poticaj, a ne na izravan antonim prolasku zlovolje."},
  "2016_ljeto_B__13": {"A":"'Izgovori' znači reći naglas, što ne odgovara glagolu 'oćutjeti' (osjetiti).","C":"'Pomisli' upućuje na misaonu radnju, a 'oćuti' označava osjetilno/emocionalno zamjećivanje.","D":"'Začuje' znači čuti, što nije značenje glagola 'oćutjeti' (osjetiti)."},
  "2016_ljeto_B__14": {"B":"Gustativni (okusni) podražaj odnosio bi se na samo kušanje, a lik te izraze čuje, ne kuša.","C":"Taktilni (dodirni) podražaj nije prisutan; radnja se odnosi na slušanje izgovorenih riječi.","D":"Vizualni podražaj značio bi gledanje, a u rečenici lik 'čuje' izraze, dakle posrijedi je slušni doživljaj."},
  "2016_ljeto_B__15": {"B":"Joža Podravec nije lik Leskovarove novele 'Misao na vječnost'.","C":"Martin Tintor lik je iz drugoga djela, a ne glavni junak ove novele.","D":"Petar Krupić je zlatar iz Šenoina 'Zlatarova zlata', a ne junak Leskovarove novele."},
  "2016_ljeto_B__16": {"A":"Tekst ne potvrđuje da je očekivala da je Eugène primi za ruku; ruke je pogledala zbog Vautrinova proricanja.","C":"Pogled u ruke nije znak pozdravljanja s Vautrinom, nego nade u proricano vjenčanje.","D":"Gledanje u vlastite ruke nije izbjegavanje Eugèneova pogleda, nego razmišljanje o proricanju o udaji."},
  "2016_ljeto_B__17": {"A":"'Nagizdana udovica' odnosi se na gđu Vauquer, vlasnicu pansiona, a ne na gđu Couture.","B":"'Lijepa poput zvijezde' Vautrinov je podrugljiv opis gđe Vauquer, ne gđe Couture.","C":"'Utegnuta poput mrkve' također se odnosi na gđu Vauquer i njezin steznik, a ne na gđu Couture."},
  "2016_ljeto_B__18": {"A":"'Dajte ruku, gospođice Victorine' uljudan je poziv povezan s proricanjem, bez ironijskoga obrata.","C":"'Zbogom, draga prijateljice' uobičajen je pozdrav i ne sadrži suprotnost između rečenoga i mišljenoga.","D":"Victorinina želja da Vautrin govori istinu iskreni je iskaz nade, a ne ironija."},
  "2016_ljeto_B__19": {"A":"Znanstvenik nema veze s 'naslovom' kao plemićkom titulom o kojoj govori Vautrin.","B":"Književnik ne odgovara značenju 'čovjeka s naslovom', tj. nositelja plemićke titule.","C":"Bankar je bogataš, ali izraz 'čovjek s naslovom' znači plemića s titulom, ne osobu iz financija."},
  "2016_ljeto_B__20": {"A":"Zaštita Victorine od zavodnika nije Vautrinov motiv; on slijedi vlastiti probitak.","B":"Preuzimanje Victorinine sobe nije njegov cilj; zanima ga njezino buduće nasljedstvo.","C":"Pomirba s bratom nije Vautrinova namjera; naprotiv, planira bratovu pogibiju radi nasljedstva."},
  "2016_ljeto_B__21": {"B":"Đuka se ne ljuti na sebe nego prosuđuje i osuđuje ponašanje suseljana Tune i Mije.","C":"Besposličarenje gospode nije tema; gospoda se spominju tek u prizoru s Mijom, a težište je na Đukinu sudu o suseljanima.","D":"Požar (zapaljeni štagalj) samo je povod prizoru, a ne tema ulomka, koja je Đukino promišljanje o susjedima."},
  "2016_ljeto_B__22": {"A":"Negašenje požara odnosi se na Miju, a ne na Tunu.","C":"Rasipnost se Tuni ne pripisuje; zamjera mu se besposlenost i nepojavljivanje u selu.","D":"Pijanstvo se Tuni ne spominje; ono se veže uz Mijinu rakiju, a Tuni se zamjera povlačenje iz sela."},
  "2016_ljeto_B__23": {"A":"'Prigibati se' ovdje ne znači savijati se od bolova, nego klanjati se ponizno pred gospodom.","C":"Mija se ne pravi važnim, nego se servilno klanja gospodi, pokazujući poniznost.","D":"Iako je Mija radostan, sam izraz 'prigibati se' označava ponizno klanjanje, a ne sreću."},
  "2016_ljeto_B__24": {"A":"'Zapalilo mu' odnosi se na izbijanje požara, a ne na rastuću ljutnju koju znači 'ožučuje se'.","B":"'Ostavio se' znači prestao (gašenja), što nema veze sa značenjem 'postaje žučan'.","C":"'Ustrčkao se' znači zatrčao se uokolo, a ne razljutio se, pa nije bliskoznačno izrazu 'ožučuje se'."},
  "2016_ljeto_B__25": {"A":"Eufemizam je ublažavanje neugodnoga izraza, čega u 'glasu vatre' nema.","C":"Paradoks je prividno proturječje, a 'glas vatre' nije proturječan izraz, nego zamjena dijela cjelinom.","D":"Simbol nosi širu prenesenu vrijednost, dok je ovdje riječ o smjenjivanju pojmova po bliskosti (metonimija)."},
  "2016_ljeto_B__26": {"A":"Tekst ne kaže da Hefest ne podnosi tuđe jadikovke; sažaljenje proizlazi iz srodstva s Prometejem.","B":"Snaga i Sila izvršile su Zeusov nalog, no Hefestovo sažaljenje temelji se na tome što je Prometej bog srodnik.","C":"Temida (Prometejeva majka) ne pojavljuje se kao razlog sažaljenja; Hefesta gane božansko srodstvo s Prometejem."},
  "2016_ljeto_B__27": {"A":"Izazivanje strahopoštovanja nije Hefestovo objašnjenje; on Zeusovu strogost pripisuje svježoj vlasti.","B":"Zeus ne sluša naredbe oca; naprotiv, sam je nedavno preuzeo vlast i zato je strog.","C":"Prometej je taj koji je ljude prekomjerno častio; Hefest Zeusovu strogost veže uz novost njegove vlasti, ne uz mržnju ljudi."},
  "2016_ljeto_B__28": {"A":"Obraćanje 'sine mudre Temide' Hefestov je uvod Prometeju, a ne iskaz Prometejeve odlučnosti.","C":"Stih o stražarenju na hridi opisuje kaznu, a ne Prometejevu odlučnost.","D":"'Što oklijevaš, žališ uzalud?' poticaj je upućen Hefestu, a ne prikaz Prometejeve neustrašivosti."},
  "2016_ljeto_B__29": {"A":"Hefest se ne suprotstavlja Zeusu; izrijekom kaže da se mora odvažiti izvršiti nalog.","B":"Stražarenje uz stijenu Prometejeva je kazna, a ne ono na što se Hefest 'odvažuje'.","C":"Otpuštanje Sile i Snage nije sadržaj stiha; Hefest se odvažuje na samo okivanje Prometeja."},
  "2016_ljeto_B__30": {"A":"'Kobno' je upotrijebljeno doslovno, kao ozbiljno upozorenje da je zanemarivanje očeve riječi pogubno, bez ironije.","B":"'Osloboditelj' je doslovan iskaz da spasitelj još nije rođen, bez suprotnosti rečenoga i mišljenoga.","D":"'Tvrdòkoran' doslovno opisuje Zeusovu krutost, pa nije ironično upotrijebljeno."},
  "2016_ljeto_B__31": {"A":"Pridruživanje švedskim četama nije razlog rastanka; kuhar odlazi zbog naslijeđene gostionice.","C":"Hladna zima opisuje okolnosti, ali nije razlog kuharova oproštaja, koji proizlazi iz nasljedstva.","D":"O kuharovoj bolesti nema spomena; oprašta se jer je naslijedio gostionicu u Utrechtu."},
  "2016_ljeto_B__32": {"A":"Svjetlo u župnom dvoru nije navedeno; naprotiv, kuhar kaže 'sve je u mraku'.","B":"Miris juhe ne spominje se kao znak prisutnosti ljudi; juha je tek nada Majke Courage.","D":"Perine se spominju samo kao slika nekoga tko bi morao ustati, a zaključak o nastanjenosti donosi se po lavežu psa."},
  "2016_ljeto_B__33": {"A":"Molitva nije sredstvo zarade koje predlaže Majka Courage; ona računa na pjevanje.","C":"Iako se prosjačenje spominje kao opće stanje, za zaslužiti jelo kod popa predlaže pjevanje.","D":"Zvonjava se spominje kao posao nekoga tko zvoni, a Majka Courage hranu kani zaraditi pjevanjem."},
  "2016_ljeto_B__34": {"B":"Eufemizam je ublažen izraz za neugodno, čega u opisu sivoga jutra nema.","C":"Hiperbola je pretjerivanje, a u kratkom didaskalijskom opisu nema preuveličavanja.","D":"Paradoks je prividno proturječje, a navedene rečenice nisu proturječne, nego bezglagolske (izostavljen predikat)."},
  "2016_ljeto_B__35": {"A":"Zabavljaštvo nije zanimanje Majke Courage; ona je putujuća trgovkinja.","C":"'Mesarski pas' samo je usporedba, a ne njezino zanimanje; ona je markentenderica (trgovkinja).","D":"Krojaštvom se ne bavi; vuče kola s robom i prodaje vojskama kao trgovkinja."},
  "2016_ljeto_B__36": {"A":"Renesansa je razdoblje 15.-16. st. i daleko prethodi modernizmu, ne neposredno.","B":"Klasicizam (17.-18. st.) ne dolazi neposredno prije modernizma; između su romantizam i realizam.","C":"Romantizam prethodi realizmu, pa nije razdoblje koje neposredno prethodi modernizmu."},
  "2016_ljeto_B__37": {"A":"Klasicizam naglašava razum, sklad i antičke uzore, a ne mistiku, odmetništvo i egzotična putovanja.","C":"Realizam prikazuje objektivnu svakidašnju stvarnost, suprotno mistici i bijegu u daleke krajeve.","D":"Ekspresionizam se temelji na subjektivnom, snažnom izrazu i krizi, a ne na temama odmetništva i egzotičnih putovanja romantizma."},
  "2016_ljeto_B__38": {"B":"Epski deseterac stih je usmene epike, a Marulićeva Judita pisana je dvostruko rimovanim dvanaestercem.","C":"Heksametar je antički stih, a Judita nije pisana heksametrom, nego dvostruko rimovanim dvanaestercem.","D":"Simetrični osmerac nije stih Judite; ona je spjevana dvostruko rimovanim dvanaestercem."},
  "2016_ljeto_B__39": {"A":"Eshil je antički grčki tragičar iz 5. st. pr. Kr., daleko prije 16. stoljeća.","B":"Petrarca je živio u 14. stoljeću, dakle prije 16. stoljeća.","C":"Voltaire je prosvjetiteljski pisac 18. stoljeća, a ne 16. stoljeća."},
  "2016_ljeto_B__40": {"A":"Džore Držić bio je petrarkistički lirik, a ne pisac učenih komedija po Plautu.","B":"Hanibal Lucić poznat je po pastorali i lirici, a ne po učenim komedijama po Plautu.","C":"Ivan Gundulić barokni je pjesnik (Osman, Suze), a ne pisac komedija po antičkim uzorima."},
  "2016_ljeto_B__41": {"A":"Pjesni pokorne kralja Davida pokornički su psalmi, a slavni stihovi o slobodi nisu iz te zbirke.","B":"Suze sina razmetnoga religiozna su poema o grijehu i pokajanju, a ne djelo iz kojega je himna slobodi.","D":"Osman je junački ep, a himna 'O lijepa, o draga, o slatka slobodo' potječe iz pastorale Dubravke."},
  "2016_ljeto_B__42": {"A":"Razgovor ugodni naroda slovinskoga pjesničko-prozno je djelo (pučki spjev), a ne dramsko.","C":"Satir iliti divji čovik poučni je spjev, a ne dramsko djelo.","D":"Jesenji plodovi pjesnička je zbirka Katančića, dakle pripada lirici, a ne dramskomu rodu."},
  "2016_ljeto_B__43": {"A":"U Posljednjim Stipančićima nositelji su radnje obitelj Stipančić, a ne Dora i Pavao.","C":"U U registraturi glavni je lik Ivica Kičmanović, a ne Dora Krupićeva i Pavao Gregorijanec.","D":"Planine Petra Zoranića pastoralno-alegorijsko su djelo, bez likova Dore Krupićeve i Pavla Gregorijanca."},
  "2016_ljeto_B__44": {"A":"Bijeg je roman Milutina Cihlara Nehajeva, a ne Kumičića.","C":"Seljačka buna povijesni je roman Augusta Šenoe, a ne Kumičića.","D":"Začuđeni svatovi djelo je Augusta Šenoe, a ne Eugena Kumičića."},
  "2016_ljeto_B__45": {"A":"Kip domovine leta 188* Matoševa je satira, ali se početak moderne vezuje uz Kozarčevu Tenu.","B":"Misao na vječnost Leskovarova je novela koja najavljuje modernu, no početak razdoblja obilježava Tena.","C":"Duga Dinka Šimunovića pripada zreloj moderni, a ne njezinu početku."},
  "2016_ljeto_B__46": {"B":"Ivan Kukuljević Sakcinski pripada hrvatskomu romantizmu i preporodu, a ne ekspresionizmu.","C":"Matija Petar Katančić klasicist je 18./19. st., a ne ekspresionist.","D":"Silvije Strahimir Kranjčević pjesnik je realizma i protomoderne, a ne ekspresionist."},
  "2016_ljeto_B__47": {"B":"Enka nije lik iz Povratka Filipa Latinovicza.","C":"Laura nije lik tog romana, nego Krležinih Glembajevih.","D":"Vivijana nije lik iz Povratka Filipa Latinovicza."},
  "2016_ljeto_B__48": {"A":"Moj križ svejedno gori zbirka je Jure Kaštelana, a ne Tina Ujevića.","B":"Srebrne svirale zbirka je Dragutina Tadijanovića, a ne Ujevića.","D":"Zore i vihori zbirka je Miroslava Krleže, a ne Tina Ujevića."},
  "2016_ljeto_B__49": {"A":"Dobriša Cesarić pisao je na štokavskom standardu, a ne čakavski.","C":"Miroslav Krleža pisao je štokavski i kajkavski (Balade), a ne čakavsku poeziju.","D":"Vladimir Vidrić pisao je štokavskom standardnom poezijom, a ne čakavski."},
  "2016_ljeto_B__50": {"B":"Dragutin Tadijanović piše jednostavnijim, intimnim izrazom (npr. Dugo u noć), a navedeni impresionistički pejzaž Matošev je.","C":"Josip Pupačić pripada drugoj moderni (npr. Tri moja brata), a ovi stihovi pripadaju Matoševoj 'Jesenje veče'.","D":"Jure Kaštelan pjesnik je 20. st. drukčije poetike, a navedeni stihovi pripadaju Matoševoj pjesmi."},
  "2016_ljeto_B__51": {"B":"Po dragomu kraju zbirka je Dragutina Domjanića, u kojoj nema balade Khevenhiller.","C":"Ognji i rože zbirka je Ivana Gorana Kovačića, a ne mjesto pjesme Khevenhiller.","D":"Z mojih bregov kajkavska je zbirka Frana Galovića, a Khevenhiller je iz Krležinih Balada Petrice Kerempuha."},
  "2016_ljeto_B__52": {"B":"U očekivanju Godota pripada kazalištu apsurda, a ne epskomu kazalištu.","C":"Stolice Eugènea Ionescoa primjer su kazališta apsurda, a ne epskoga kazališta.","D":"Nora Henrika Ibsena realistička je drama, a ne djelo epskoga kazališta."},
  "2016_ljeto_B__53": {"A":"Filip Latinovicz lik je Krležina romana Povratak Filipa Latinovicza, a ne govornik ove rečenice iz Glembajevih.","B":"Ivica Kičmanović lik je Kovačićeva romana U registraturi, a ne Krležinih Glembajevih.","D":"Melkior Tresić lik je Marinkovićeva Kiklopa, a navedenu rečenicu izgovara Leone Glembay."},
  "2016_ljeto_B__54": {"A":"Kolo je stariji časopis (preporod/realizam), a ne časopis druge moderne.","C":"Vijavica je ekspresionistički časopis A. B. Šimića, a ne časopis druge moderne.","D":"Vijenac se vezuje uz Šenou i razdoblje realizma, a ne uz drugu modernu."},
  "2016_ljeto_B__55": {"A":"U Predstavi Hamleta u selu Mrduša Donja težište je na političkoj satiri seoske sredine, a ne na intelektualcu koji se boji rata.","B":"Đuka Begović prikazuje strastvenog slavonskog seljaka, a ne mladog intelektualca koji strahuje od rata.","D":"Prokleta avlija smještena je u istanbulski zatvor i nema lik mladog intelektualca koji se boji rata kao Melkior."},
  "2016_ljeto_B__56": {"A":"'Podhlađenost' je pogrešno; provodi se jednačenje po zvučnosti pa je pravilno 'pothlađenost'.","B":"'Podkoljenica' je pogrešno; ispravno je 'potkoljenica' (d ispred k prelazi u t).","C":"'Podplaćenost' je pogrešno; ispravno je 'potplaćenost' (d ispred p prelazi u t)."},
  "2016_ljeto_B__57": {"A":"Nesvršeni oblik 'dospjevati' nije pravilan; ispravno je 'dospijevati' (ije).","C":"Oblik 'presjecati' nije pravilan uz 'presjeći'; pravilno je 'presijecati'.","D":"Nesvršeni oblik 'razumjevati' nije pravilan; ispravno je 'razumijevati' (ije)."},
  "2016_ljeto_B__58": {"A":"Slog 'pre' nije naglašen; naglasak je na drugom slogu 'tra'.","C":"Slog 'ži' nije nositelj naglaska u riječi pretraživanje.","D":"Slog 'va' nije naglašen; naglašen je slog 'tra'."},
  "2016_ljeto_B__59": {"B":"Ispadanje suglasnika ovdje se ne događa; nijedan se suglasnik ne gubi, nego se z mijenja u s.","C":"Palatalizacija je promjena k, g, h u č, ž, š ispred e/i, čega u 'isplivati' nema.","D":"Sibilarizacija mijenja k, g, h u c, z, s ispred i, što se ovdje ne događa; promjena je z u s zbog zvučnosti."},
  "2016_ljeto_B__60": {"A":"Oblik 'Disney-ja' s crticom nije pravilan; strana imena na -y pišu se bez crtice (Disneyja).","B":"Oblik 'Disney-a' nije pravilan: i zbog crtice i zbog izostanka j (treba Disneyja).","D":"Oblik 'Walt Disneya' nepravilan je: 'Walt' ostaje nesklonjen, a 'Disneya' je bez j (treba Walta Disneyja)."},
  "2016_ljeto_B__61": {"A":"'Pri-' je prefiks, dakle tvorbeni morfem, a ne gramatički.","B":"'-grad-' je korijen riječi, a ne gramatički morfem.","C":"'-sk-' je tvorbeni sufiks za pridjev, a ne gramatički morfem; gramatičku obavijest nosi nastavak '-i'."},
  "2016_ljeto_B__62": {"A":"'Krenuti' je neprijelazan glagol; 'prema nama' priložna je oznaka, a ne objekt u akuzativu.","B":"'Otputovati' je neprijelazan; 's njim' je prijedložni izraz, ne objekt u akuzativu.","C":"'Razveseliti se' je povratni neprijelazni glagol bez objekta u akuzativu."},
  "2016_ljeto_B__63": {"A":"'Svojim' je posvojna (povratno-posvojna) zamjenica, a ne pokazna.","C":"'Ju' je osobna zamjenica u akuzativu, a ne pokazna.","D":"'Našega' je posvojna zamjenica, a ne pokazna."},
  "2016_ljeto_B__64": {"B":"Glagolski pridjev radni tvori se nastavcima -o/-la/-lo (npr. izišao), a 'idući' to nije.","C":"Prezent je lични glagolski oblik (idem, ide), dok je 'idući' nepromjenjiv glagolski prilog.","D":"Infinitiv završava na -ti/-ći (ići), a 'idući' je glagolski prilog sadašnji."},
  "2016_ljeto_B__65": {"A":"'Prijatelju' je u dativu (kome se rastopi oko srca), a ne u akuzativu.","B":"'Srca' je u genitivu (oko srca), a ne u akuzativu.","C":"'Misli' je nominativ množine i vrši službu subjekta, a ne akuzativ."},
  "2016_ljeto_B__66": {"B":"'Gorčiju' je pogrešan komparativ; pravilno je 'gorču'.","C":"'Slastniji' je pogrešno; pravilan komparativ je 'slasniji'.","D":"'Bijesniji' je pogrešno; pravilan komparativ je 'bjesniji'."},
  "2016_ljeto_B__67": {"A":"'Jutros' je prilog (vremena), a ne prijedlog.","B":"'Kako' je veznik koji uvodi zavisnu surečenicu, a ne prijedlog.","C":"'Oprezno' je prilog (načina), a ne prijedlog."},
  "2016_ljeto_B__68": {"A":"'Sigurno znaju' veza je priloga i glagola (priložna oznaka), a ne sročna (kongruentna) sintagma.","C":"'Opet pobijediti' veza je priloga i glagola, dakle nije sročna sintagma slaganja u rodu, broju i padežu.","D":"'Pobijediti na natjecanju' upravna je (rekcijska) sintagma s prijedložnim izrazom, a ne sročna."},
  "2016_ljeto_B__69": {"B":"'Nije mogla izbjeći' glagolski je predikat (modalni glagol + infinitiv), a ne imenski.","C":"'Izazivala je' glagolski je predikat, bez imenskoga dijela.","D":"'Ne zaustavljaj se' glagolski je predikat (imperativ povratnoga glagola), a ne imenski."},
  "2016_ljeto_B__70": {"A":"'Ugodan prostor' službu vrši kao subjekt rečenice, a ne kao objekt.","B":"U toj rečenici 'poslovnoga prostora' dio je prijedložno-padežne dopune uz 'oglas', a ne objekt.","C":"U toj rečenici 'poslovi' su subjekt (sklapaju se poslovi), a 'prostoru' je priložna oznaka, ne objekt."},
  "2016_ljeto_B__71": {"A":"'Na zahtjev obožavatelja' označava okolnost/uzrok, a ne način (kako?).","B":"'Sinoć' odgovara na pitanje 'kada?', pa je priložna oznaka vremena, a ne načina.","C":"'Na pozornicu' odgovara na pitanje 'kamo?', pa je priložna oznaka mjesta, a ne načina."},
  "2016_ljeto_B__72": {"A":"Rečenica s 'osim njegova obećanja' jednostavna je, proširena prijedložnim izrazom, s jednim predikatom.","B":"Rečenica 'nakon završetka nastave odlučio je...' ima jedan predikat, dakle jednostavna je.","C":"Rečenica 'unatoč lošemu vremenu otišao je...' jednostavna je proširena rečenica s jednim predikatom."},
  "2016_ljeto_B__73": {"A":"Dopusna rečenica izriče da se radnja zbiva unatoč zapreci (iako), čega ovdje nema; veznik 'da' uvodi uvjet.","C":"Posljedična rečenica izriče posljedicu (tako da), a ova izriče uvjet, pa nije posljedična.","D":"Uzročna rečenica izriče uzrok (jer), a ova s 'da' i kondicionalom izriče pogodbu."},
  "2016_ljeto_B__74": {"A":"Poredak 'se li' nije pravilan; čestica 'li' dolazi prva, prije zamjeničkih zanaglasnica.","B":"Poredak 'vam li se' nije pravilan; 'li' mora doći ispred dativne zamjenice 'vam'.","D":"Poredak 'li se vam' nije pravilan; dativ 'vam' dolazi prije povratnoga 'se' (li vam se)."},
  "2016_ljeto_B__75": {"A":"Arhaizam je zastarjela riječ za pojam koji još postoji, dok dukat označava nešto što više ne postoji u uporabi.","C":"Neologizam je nova riječ, a dukat je naziv iz prošlosti, dakle suprotno.","D":"Pomodnice su pomodne riječi prolazne uporabe, a dukat je historizam vezan uz nestali pojam."},
  "2016_ljeto_B__76": {"B":"Gramatička odrednica označavala bi rod ili padež (m, gen. jd.), a 'klas. eur.' upućuje na podrijetlo riječi.","C":"Normativna odrednica govori o uporabnoj vrijednosti (arh.), a 'klas. eur.' je podatak o etimologiji.","D":"Stilistička odrednica označavala bi funkcionalni stil, a 'klas. eur.' je etimološka oznaka podrijetla."},
  "2016_ljeto_B__77": {"B":"Fonem i morfem različite su jezične jedinice (glas i najmanja značenjska jedinica), a ne istoznačnice.","C":"Jednoznačnost i višeznačnost suprotni su pojmovi (antonimi), a ne sinonimi.","D":"Leksikologija i frazeologija različite su jezikoslovne discipline, a ne istoznačnice."},
  "2016_ljeto_B__78": {"A":"'Šiško' je osobno ime, ali nije eponim (riječ izvedena iz imena), nego samo ime osobe.","B":"'Hrvatski' je pridjev izveden od imena naroda/zemlje, a traženi eponim po pjesniku je 'petrarkist'.","D":"'Dubrovnika' je oblik mjesnoga imena, a eponim izveden iz osobnoga imena je 'petrarkist'."},
  "2016_ljeto_B__79": {"A":"'Naći zajednički jezik' znači uskladiti se, sporazumjeti, što nije suprotno šutnji.","B":"'Ugristi se za jezik' znači suzdržati se od govora, što je bliskoznačno šutnji, a ne antonim.","D":"'Zaplitati jezik' znači nerazgovijetno govoriti, a ne biti brbljiv, pa nije antonim šutnji."},
  "2016_ljeto_B__80": {"A":"Bogoslav Šulek noviji je leksikograf 19. st. (znanstveno nazivlje), a ne autor prvoga kajkavskog rječnika.","B":"Faust Vrančić sastavio je višejezični rječnik (1595.), a ne prvi kajkavski rječnik.","C":"Jakov Mikalja autor je rječnika na štokavskoj osnovi, a ne prvoga kajkavskog rječnika."},

  // 2017_jesen_A
  "2017_jesen_A__1": {"A":"Pjesma ne govori o radosti u sitnicama, nego o paradoksu rađanja i umiranja kao stalnog obnavljanja.","B":"Lirski subjekt obrće tu tvrdnju ('Meni se čini – oni ustaju od mrtvih'), pa naglasak nije na umiranju nego na obnovi života.","D":"Strah od smrti nije tema; završni stih 'mrtav čovjek opet vratit će se' upućuje na obnavljanje, a ne na strah."},
  "2017_jesen_A__2": {"A":"Govorljivost se ne spominje; slika skrivanja vezana je uz unutrašnjost, a ne uz ljude koji mnogo govore.","B":"Dobar život nije predmet tih stihova; oni se odnose na nevidljivu unutrašnjost koja se 'vješto skriva'.","D":"Smrtnost nije ono što se skriva; skrivaju se 'stvari koje zovemo unutrašnjost'."},
  "2017_jesen_A__3": {"B":"'Onda sve više žive' nije proturječje, nego izravan iskaz o obnavljanju života.","C":"'U stvari nitko ih nije vidio' tek je konstatacija nevidljivosti unutrašnjosti, bez unutarnje proturječnosti.","D":"'Imat će malo manje krivo' jest izokrenuti izraz, ali nema spoja suprotnih pojmova kao u paradoksu kolijevke i umiranja."},
  "2017_jesen_A__4": {"A":"Djevojci se ne predbacuje preosjetljivost, nego suprotno – hladnoća i ravnodušnost ('studena si ti u sebi').","C":"Nevjera se ne spominje; zamjerka je da ne mari za to što je voljena.","D":"Izbirljivost nije tema; subjekt prigovara njezinoj neosjetljivosti, ne probirljivosti."},
  "2017_jesen_A__5": {"A":"Subjekt ne reagira na ženin plač; naprotiv, on sam suzama nastoji probiti njezino kameno srce.","B":"Nestrpljivost nije iskazana; slika kapanja koje 'dugim vremenom' dube kamen upravo naglašava strpljivu ustrajnost.","D":"Ljutnja zbog životne nepravde nije tema; riječ je o ustrajnosti u ljubavnoj nakani."},
  "2017_jesen_A__6": {"A":"'Tvê' znači 'tvoje' i odnosi se na ono što je djevojčino (srce), a ne na vrijeme.","B":"'Pravo' je imenica u istom stihu, ali posvojna zamjenica 'tvê' veže se uz srce, ne uz pravo.","C":"Suze su subjektovo sredstvo ('suzami mojijem'), dok je 'tvê' vezano uz djevojčino srce."},
  "2017_jesen_A__7": {"B":"O hridi razbijaju brodove Not, a ne Euro; Euro brodove odvlači na plićak.","C":"Lomljenje vesala vezano je uz Akvilon na početku, a ne uz djelovanje Eura.","D":"Euro brodove ne vuče na pučinu, nego suprotno – 'sa pučine lađe na plićak povuče'."},
  "2017_jesen_A__8": {"B":"O penjanju na jarbole nema spomena; 'kreste' su vrhovi valova, ne brodski jarboli.","C":"Bacanje na hridi vezano je uz lađe koje hvata Not, a ne uz ljude na vrhovima valova.","D":"Vir se ne spominje; ljudi su čas na vrhovima valova, čas na morskome dnu."},
  "2017_jesen_A__9": {"B":"Neprijatelji nisu predmet; 'dušmanska voda' samo personificira more, a 'njima' upućuje na lađe.","C":"Valovi se spominju drugdje, no rečenica o pucanju zglobova odnosi se na konstrukciju lađa.","D":"Zapovjednici se ne spominju; pucaju spojevi lađa, pa 'njima' znači lađama."},
  "2017_jesen_A__10": {"A":"O tajnim posjetima salonima nema spomena; Alfred priređuje vlastite zabave u Beču.","B":"Šampanjac plaća razdragani ujak, a ne Alfred.","C":"Plač od zanosa pri sviranju ne spominje se; jecanje pripada veselomu ujaku na kraju."},
  "2017_jesen_A__11": {"B":"Kazališnu predstavu ujak nije gledao; u Pešti je bio na saboru.","C":"Otmjenu zabavu priređuje Alfred u Beču, dok je ujak u Pešti bio na saborskome zasjedanju.","D":"Posjet nećaku tek je slijedio nakon Pešte; razlog boravka u Pešti bio je sabor."},
  "2017_jesen_A__12": {"A":"'Puste' ovdje ne znači brojne, nego slobodne, raspojasane svirače.","B":"Značenje nije osamljenost, nego raspuštenost, neobuzdanost ('slobodne').","C":"Rijetkost se ne podrazumijeva; 'puste' opisuje raspoloženje, a ne učestalost svirača."},
  "2017_jesen_A__13": {"A":"Spomen truda pri pisanju knjige iskaz je činjenice, a ne samokritičnoga vrednovanja vlastita djela.","B":"Višestruko laćanje pera opisuje muku oko predgovora, ali ne sadrži kritiku vlastite vrijednosti.","D":"Rečenice o navođenju Aristotela i Platona odnose se na tuđa, načitana djela, a ne na samokritiku pripovjedača."},
  "2017_jesen_A__14": {"B":"Izostavljena pouka nije razlog omiljenosti; čitatelji cijene baš obilje filozofskih citata.","C":"Vjerska tematika ne spominje se kao razlog popularnosti; riječ je o filozofskim mislima.","D":"Tumačenje zakona nije ono čime djela osvajaju čitatelje, nego navođenje filozofa."},
  "2017_jesen_A__15": {"B":"Filozofi se spominju kao izvor citata, a ne kao 'zakonodavac kojega krste svjetinom'.","C":"Pisci nisu ti koji sude; 'stari zakonodavac' ironičan je naziv za publiku/čitateljstvo.","D":"Prijatelj je zaseban lik koji upada u sobu; 'svjetina' označava čitatelje, a ne prijatelja."},
  "2017_jesen_A__16": {"A":"Mihin odlazak u drugo selo ne spominje se kao razlog Justine promjene.","B":"Mihina naklonost nije uzrok; Justa mijenja stav nakon očeva hvaljenja Mihina imetka.","C":"Miha se nije propio; promjenu izaziva njegovo bogaćenje ('opernatio')."},
  "2017_jesen_A__17": {"A":"Bol ne dolazi od očevih stavova o seoskom životu, nego od Justine spoznaje o vlastitoj sudbini.","B":"Razmišljanje o starim vremenima pripada starcima i ženama, a ne uzroku Justine boli.","D":"Obijest mladića tek je prizor; bol izaziva njezina spoznaja o budućnosti djevojaka."},
  "2017_jesen_A__18": {"A":"'Svetost' nije u navedenom primjeru i ne predstavlja prijenos po srodnosti.","B":"'Geslo' nije metonimija u danome primjeru; ne stoji jedan pojam umjesto drugoga srodnog.","C":"'Mladići' su upotrijebljeni u doslovnom značenju, bez prijenosa pojma."},
  "2017_jesen_A__19": {"A":"Sramota nije u njezinoj neprilagodljivosti, nego u tjelesnoj krhkosti za seoski rad.","B":"Ime Muljika posljedica je njezine krhkosti, a samo ime nije izvor sramote.","D":"Nedostatak braće ne spominje se kao razlog; sramotu izaziva to što je slaba za rad."},
  "2017_jesen_A__20": {"A":"Traženje posla ne spominje se; majka dolazi prije bratove (kaluđerove) smrti.","B":"Riječ je o bolesnom bratu pred smrt, a dolazak nije obični posjet nego ispraćaj.","D":"Udaja se ne spominje; majka i sestra dolaze povodom kaluđerove smrti."},
  "2017_jesen_A__21": {"B":"Tvrdnja o čudnovatoj kosi nadovezuje se na opis, ali nije značenjska suprotnost mekoći muljike.","C":"Ozljeđivanje prstiju potvrđuje njezinu krhkost (muljiku), pa je u skladu, a ne u suprotnosti s rečenicom.","D":"Tvrdnja da je i mati bila takva produžuje, a ne osporava sliku muljike."},
  "2017_jesen_A__22": {"A":"Potpisivanje spisa ne spominje se kao zapreka; Meursault čeka jer je upravitelj bio zauzet.","B":"Njegovateljicu ne traži Meursault; o njoj govori upravitelj kasnije.","D":"Umor zbog pješačenja nije razlog odgode susreta; Meursault čeka zaposlenoga upravitelja."},
  "2017_jesen_A__23": {"B":"Pješačenje se spominje, ali nelagodu izaziva predugo zadržan rukostisak, a ne umor.","C":"Vratarove riječi nisu izvor nelagode; nelagodu stvara upraviteljev stisak ruke.","D":"Spise majke čita upravitelj, a ne Meursault; nelagoda dolazi od rukostiska."},
  "2017_jesen_A__24": {"A":"Upravitelj se ne žali na dugove; izričito kaže Meursaultu da se ne mora opravdavati.","B":"Upravitelj ne predbacuje nebrigu, nego suprotno – pravda Meursaulta zbog skromnih primanja.","C":"Ustroj ubožnice ne objašnjava; on prekida Meursaultovo opravdavanje."},
  "2017_jesen_A__25": {"A":"Kritiziranje sugovornika nije ono što Fabriziju potvrđuje ljubav; to mu potvrđuje istjerivanje gostiju.","B":"Zatvaranje gostionice ne spominje se; Mirandolina samo traži da gospoda odu.","C":"Zlatnu bočicu nije poklonila Mirandolina; nju nalazi markiz, pa to nije znak ljubavi Fabriziju."},
  "2017_jesen_A__26": {"A":"Konte se oprašta i odlazi, ali bočicu ne nalazi on.","B":"Fabrizio samo zaključuje da ga Mirandolina voli; bočicu nije pronašao on.","D":"Mirandolina je ona koja je bočicu izgubila, a ne pronašla; nalazi je markiz."},
  "2017_jesen_A__27": {"A":"Molba gospodi za uslugu nije pouka ni moralna poruka, nego uljudni zahtjev.","B":"Traženje da potraže drugu gostionicu praktičan je zahtjev, bez poučne namjere.","C":"Iskaz o granicama pristojnosti tek izražava njezino držanje, a ne didaktičnu pouku publici."},
  "2017_jesen_A__28": {"B":"Nevjerovanje Marku nije iskazano u didaskalijama uz Gigu; ona nastoji ublažiti situaciju.","C":"Didaskalija ne sugerira da Giga laže; ona se smiješi želeći umanjiti važnost prizora.","D":"Sarkazam je u didaskalijama pripisan Marku, a ne Gigi."},
  "2017_jesen_A__29": {"B":"Sumnja u Gigina liječnika nije izrečena u danome ulomku; Marko ne prihvaća njezino opravdanje.","C":"Zasićenost životom s Gigom ne iskazuje se; Marko sumnjičavo odbacuje njezine riječi.","D":"Marko je ne smatra duhovitom; prema njoj je grub i sarkastičan."},
  "2017_jesen_A__30": {"A":"Moda nije razlog; Marko ironično spominje modu, ali Gigi je kosa ispala zbog bolesti.","B":"Markova sklonost takvoj kosi nije razlog; Marko se naljuti zbog odrezane kose.","C":"Nije riječ o želji za promjenom; kosa je ispala zbog bolesti, što potvrđuju liječnik i bolničarka."},
  "2017_jesen_A__31": {"B":"Plavetnilo neba i let lasta vizualne su slike bez miješanja različitih osjetila.","C":"Penjanje plamena i drhtanje grana prizor je bez spoja različitih osjetilnih dojmova.","D":"Svjetlucave niti koje se lelujaju vizualni su prizor, bez sinestezijskoga miješanja osjeta."},
  "2017_jesen_A__32": {"A":"Epifora je ponavljanje na kraju stihova; ovdje se 'i' ponavlja na početku, a ne na kraju.","B":"Inverzija je obrnut red riječi; primjer počiva na ponavljanju veznika, a ne na premetanju.","D":"Simploka spaja anaforu i epiforu; ovdje je samo ponavljanje veznika 'i' (polisindeton)."},
  "2017_jesen_A__33": {"A":"'Njiva' je samo dio krajolika, bez pridavanja ljudskih osobina.","B":"'Kućice' magle skrivaju, ali same ne dobivaju ljudska svojstva.","D":"'Vrane' su prirodni element prizora; personificirano je sunce koje 'mre i motri'."},
  "2017_jesen_A__34": {"A":"Stih ima rimu na kraju (tišini/visini), ali nije dvostruko rimovani dvanaesterac s cezurnom rimom.","B":"Rima je samo na kraju (tkanjem/obećanjem); nema rime na sredini stiha.","D":"Stih ima završnu rimu (plava/zdihava), ali nije dvanaesterac s rimom i na polustihu."},
  "2017_jesen_A__35": {"A":"Ugođaj tuge i čežnje obilježje je elegije, a ne ditiramba.","B":"Ironičan i satiričan ton odlika je satire, ne ditiramba koji slavi radost.","C":"Posvećivanje zaslužnim osobama svojstvo je ode, a ne ditiramba."},
  "2017_jesen_A__36": {"B":"'O junaku mi kazuj, o Muzo' početak je Homerove Odiseje.","C":"'Srdžbu mi, boginjo, pjevaj Ahileja' početak je Homerove Ilijade.","D":"Stihovi o skitskoj zemlji ne pripadaju početku Eneide."},
  "2017_jesen_A__37": {"B":"Katul je rimski liričar, a ne grčki antički pjesnik.","C":"Marcijal je rimski epigramatičar, pripadnik rimske, ne grčke književnosti.","D":"Ovidije je rimski pjesnik, ne pripadnik grčke antike."},
  "2017_jesen_A__38": {"A":"Ahilej se ne suočava sa spoznajom o majci grešnici; stihovi pripadaju Edipu.","C":"Kreont nije rođen od majke s kojom živi; riječ je o Edipovoj spoznaji.","D":"Odisej ne izgovara te stihove; oni odražavaju Edipovu tragičnu spoznaju o podrijetlu."},
  "2017_jesen_A__39": {"B":"Beowulf je srednjovjekovni junački ep, a ne roman.","C":"Don Quijote djelo je renesanse, a ne srednjovjekovni roman.","D":"Lucidar je srednjovjekovno enciklopedijsko/poučno djelo, a ne roman."},
  "2017_jesen_A__40": {"B":"Cervantes je djelovao na prijelazu 16. u 17. stoljeće, a ne u 14.","C":"Tasso je pisac 16. stoljeća, ne 14.","D":"Shakespeare je stvarao na prijelazu 16. u 17. stoljeće, a ne u 14."},
  "2017_jesen_A__41": {"B":"Pomet je lukav i domišljat sluga, a ne proždrljiv i naivan; opis odgovara Bokčilu.","C":"Popiva je također spretan sluga, ne prostodušno naivan kao Bokčilo.","D":"Tripče nije proždrljivi naivni sluga koji s Marojem ide u Rim; to je Bokčilo."},
  "2017_jesen_A__42": {"A":"15. stoljeće prerano je; Bunić Vučić djeluje u 17. stoljeću.","B":"16. stoljeće ne odgovara; Bunić Vučić pripada baroku 17. stoljeća.","D":"18. stoljeće prekasno je za Bunića Vučića (1591.–1658.)."},
  "2017_jesen_A__43": {"A":"Dekameron je zbirka novela u prozi, a ne u stihovima.","B":"Škrtac je Molièreova komedija pisana u prozi.","D":"Candide je Voltaireova prozna pripovijest, a ne djelo u stihovima."},
  "2017_jesen_A__44": {"A":"Renesansa završava davno prije Byrona (1788.–1824.).","B":"Barok je razdoblje 17. stoljeća, a Byron pripada 19. stoljeću.","C":"Klasicizam prethodi romantizmu; Byron je romantičar, ne klasicist."},
  "2017_jesen_A__45": {"B":"Budnice i davorije obilježje su hrvatskoga romantizma (preporoda), a ne predrealizma.","C":"Ugledanje na francuske simboliste vezano je uz modernu, a ne uz predrealizam.","D":"Pretežito religiozna tematika obilježje je starije (npr. srednjovjekovne) književnosti, a ne predrealizma."},
  "2017_jesen_A__46": {"B":"Vrazova najpoznatija zbirka (Đulabije) nije u slobodnom stihu, nego u krakovjacima.","C":"Prvu hrvatsku dijalektalnu zbirku nije napisao Vraz (on piše štokavski).","D":"Vraz pripada hrvatskomu narodnom preporodu (romantizmu), a ne realizmu."},
  "2017_jesen_A__47": {"A":"Zalaganje za čisti psihički automatizam obilježje je nadrealizma (Breton), a ne Zole.","C":"Načelo 'umjetnost radi umjetnosti' vezano je uz esteticizam, ne uz naturalista Zolu.","D":"Epsko kazalište utemeljio je Brecht, a ne Zola."},
  "2017_jesen_A__48": {"A":"Juriš je časopis 20. stoljeća (avangarda), a ne 19. stoljeća.","C":"Razlog je časopis druge polovice 20. stoljeća, a ne 19.","D":"Vijavica je avangardni časopis 20. stoljeća, ne 19."},
  "2017_jesen_A__49": {"B":"Latifaga Karađoz lik je iz drugoga djela, a ne onaj koji sanja o cjelovitom Osmanu.","C":"Martin Tintor nije lik koji sanja o pronalasku Osmana.","D":"Melkior Tresić lik je iz Kiklopa, a ne iz Koraljnih vrata."},
  "2017_jesen_A__50": {"A":"Melkior Tresić nije otpušten zbog nepoloženoga profesorskog ispita; to se odnosi na Andrijaševića.","C":"Ivica Kičmanović nije gimnazijski namjesni učitelj otpušten zbog ispita.","D":"Juraj Stipančić nije lik otpušten iz službe zbog neudovoljavanja propisima o ispitu."},
  "2017_jesen_A__51": {"B":"Misao na vječnost (Leskovar) novela je, a ne roman.","C":"Duga (Šimunović) pripovijetka je, a ne roman.","D":"Prijan Lovro (Šenoa) novela/pripovijetka je, a ne roman."},
  "2017_jesen_A__52": {"A":"André Breton autor je nadrealističkoga, a ne dadaističkoga manifesta.","B":"Marinetti je autor futurističkoga manifesta, ne dadaističkoga.","D":"Majakovski je futuristički pjesnik, a ne autor manifesta dade."},
  "2017_jesen_A__53": {"A":"A. B. Šimić nije autor tih stihova; 'Ja pjevam sebe' Tinov je iskaz.","B":"Cesarić nije autor navedenih stihova.","C":"Kranjčević nije autor tih stihova; oni pripadaju Tinu Ujeviću."},
  "2017_jesen_A__54": {"B":"Rečenica o mladom Tintoru i Senjanima pripada drugomu djelu, ne Povratku Filipa Latinovicza.","C":"Rečenica o vojništvu i odlasku u Zagreb nije iz Povratka Filipa Latinovicza.","D":"Rečenica o majci u crnini i Rijeci ne pripada Povratku Filipa Latinovicza."},
  "2017_jesen_A__55": {"A":"Cesarić pripada međuratnoj generaciji, a ne krugovašima.","B":"Tadijanović je također stariji pjesnik, ne pripadnik krugovaškoga naraštaja.","D":"Tin Ujević pripada moderni i međuraću, a ne krugovašima."},
  "2017_jesen_A__56": {"A":"'Obranbeni' je pogrešno; pravilno je 'obrambeni' (jednačenje po mjestu tvorbe).","B":"'Zelenbać' je pogrešno; pravilno je 'zelembać'.","D":"'Nastanba' je pogrešno; pravilno je 'nastamba'."},
  "2017_jesen_A__57": {"A":"'Žvaćući' je pogrešno; pravilno je 'žvačući'.","B":"'Plaćući' je pogrešno; pravilno je 'plačući' (od plakati).","C":"'Mićući' je pogrešno; pravilno je 'mičući' (od micati)."},
  "2017_jesen_A__58": {"A":"U 'Hrvatsko primorje' druga se riječ piše malim slovom, pa je 'Hrvatskoga Primorja' pogrešno.","B":"'Hrvatski sabor' piše se s malim 's', pa je 'Hrvatskoga Sabora' pogrešno.","C":"'Hrvatska vojska' piše se s malim 'v', pa je 'Hrvatske Vojske' pogrešno."},
  "2017_jesen_A__59": {"A":"U 'ispraznost' nema zvučnoga zatvornika; suglasnici su bezvučni (s, p, t, st).","C":"U 'pomoćnica' ć je zvučni, ali nije zatvornik (okluziv); traži se zvučni zatvornik kao b.","D":"U 'štokavac' zatvornici k i c bezvučni su, pa nema zvučnoga zatvornika."},
  "2017_jesen_A__60": {"A":"U 'pečem' provedena je palatalizacija (k→č pred e), a ne jotacija.","C":"U 'skačem' riječ je o palatalizaciji/promjeni k→č, a ne o jotaciji.","D":"U 'vučem' je palatalizacija (k→č), a ne jotacija (spajanje sa 'j')."},
  "2017_jesen_A__61": {"B":"'Za-mje-nic-a' pogrešno dijeli korijen; korijen je 'mjen-', ne 'mje-'.","C":"'Za-mje-ni-ca' nije morfemska, nego slogovna podjela.","D":"'Za-mjen-ica' spaja sufiks i nastavak u 'ica'; pravilno se odvajaju '-ic-' i '-a'."},
  "2017_jesen_A__62": {"A":"'-ø' (nulti morfem) nije nastavak u 'radnički'; nastavak je '-i'.","C":"'-ki' nije gramatički morfem; '-k-' pripada tvorbenom sufiksu, a nastavak je samo '-i'.","D":"'-čki' obuhvaća dio osnove i sufiks, a oblikotvorni je morfem samo '-i'."},
  "2017_jesen_A__63": {"A":"Genitiv ne odgovara; uz prijedlog 'o' u značenju teme dolazi lokativ.","B":"Dativ ne odgovara; oblik 'o bolesti' s prijedlogom 'o' jest lokativ.","D":"Instrumental ne odgovara; 'o bolesti' je lokativ, a ne instrumental."},
  "2017_jesen_A__64": {"B":"'Cvijȅt' (kratkosilazni) nije pravilan naglasak za 'cvijet'.","C":"'Cvijèt' (kratkouzlazni) nije pravilan naglasak za 'cvijet'.","D":"'Cvijét' (dugouzlazni) nije pravilan naglasak za 'cvijet'."},
  "2017_jesen_A__65": {"A":"Uz 'pogledaš' (radnja vršitelja) treba povratno-posvojna 'svojim', a ne 'tvojim'.","B":"Uz 1. lice subjekta ('upustio sam se') treba 'svojim', a ne 'mojim'.","C":"Uz subjekt 'vi' (zapovjed) treba 'svoje', a ne 'vaše' osobne iskaznice."},
  "2017_jesen_A__66": {"A":"'Zapitkivaše' je 3. lice jednine imperfekta, a ne množine.","B":"'Proganjaše' je 3. lice jednine imperfekta, ne množine.","D":"'Ubacivaše' je 3. lice jednine imperfekta, a ne množine."},
  "2017_jesen_A__67": {"B":"'Uze' je aorist (svršeni prošli oblik), a ne prezent.","C":"'Pokušaj' je imperativ, a ne prezent.","D":"'Zasta' je aorist, a ne prezent."},
  "2017_jesen_A__68": {"B":"Pet prijedloga previše je; u rečenici ih je četiri (na, u, s, iza).","C":"Šest prijedloga ne odgovara; u rečenici su samo četiri.","D":"Sedam prijedloga znatno premašuje stvarni broj od četiri."},
  "2017_jesen_A__69": {"B":"'Koje' uz 'granje' (sr. r.) nije ženskoga roda.","C":"'Koje' uz 'pismo' (sr. r.) nije ženskoga roda.","D":"'Koje' uz 'znakovi' (m. r. mn.) nije ženskoga roda."},
  "2017_jesen_A__70": {"B":"'Sjesti pokraj neznanca' priložna je (mjesna) sintagma, a ne objektna dopuna.","C":"'Putovati s neznancem' priložna je sintagma (društvo), a ne objektna.","D":"'Otići poput neznanca' priložna je sintagma (način), a ne objektna dopuna."},
  "2017_jesen_A__71": {"A":"'Grad' je muškoga roda jednine, a 'Našice' ženskoga roda množine – rod i broj se ne podudaraju.","B":"'Jezero' je srednjega roda jednine, a 'Ponikve' ženskoga roda množine – ne podudaraju se.","D":"'Rijeka' je ženskoga roda, a 'Dunav' muškoga – rod se ne podudara."},
  "2017_jesen_A__72": {"A":"'Učenika' je u genitivu uz 'sila' (dio izraza), a ne neizravni objekt.","C":"'Učenika' je u akuzativu i izravni je objekt, a ne neizravni.","D":"'O učeniku' je priložna oznaka/atribut s prijedlogom, a ne neizravni objekt u dativu."},
  "2017_jesen_A__73": {"A":"Uz 'budući' obvezan je veznik 'da' ('budući da je'), pa je rečenica neispravna.","B":"'No međutim' pleonazam je (dva suprotna veznika), pa veznik nije pravilno upotrijebljen.","C":"Uzročno 'pošto' miješa se s vremenskim značenjem; ovdje bi trebalo 'budući da', pa je veznik pogrešan."},
  "2017_jesen_A__74": {"A":"'Gdje će se graditi igralište' atributna je rečenica uz 'mjesto', a ne subjektna.","B":"'Gdje ćemo se sresti' objektna je rečenica (rekli su što?), a ne subjektna.","D":"'Tko će putovati' objektna je rečenica (odlučili su što?), a ne subjektna."},
  "2017_jesen_A__75": {"A":"'Sjeveroistočni' nastalo je slaganjem (sjever + istok), a ne čistom sufiksacijom.","B":"'Slavonskobrodski' nastalo je od sveze 'Slavonski Brod' srastanjem i sufiksom, a ne čistom sufiksacijom.","D":"'Starozavjetni' nastalo je složeno-sufiksalnom tvorbom (staro + zavjet + -ni), a ne samo sufiksacijom."},
  "2017_jesen_A__76": {"B":"'Maslinik' tvoren je sufiksom '-ik', a ne '-nik'.","C":"'Plamenik' nije tvoren sufiksom '-nik' u traženom smislu.","D":"'Zvonik' tvoren je sufiksom '-ik', a ne '-nik'."},
  "2017_jesen_A__77": {"A":"Antroponim (osobno ime) nije antonim hiperonima; to je naziv iz onomastike.","C":"Homonim (istozvučnica) odnos je oblika i značenja, a ne suprotnost hiperonimu.","D":"Oronim (ime gore) onomastički je naziv, a ne antonim hiperonima."},
  "2017_jesen_A__78": {"A":"Egzonim je domaće ime stranoga zemljopisnog pojma, što 'bembizam' nije.","B":"Egzotizam je posuđenica za stranu pojavu, a 'bembizam' nije takav leksem.","D":"Etnonim je ime naroda; 'bembizam' je tvoren od osobnoga imena (eponim)."},
  "2017_jesen_A__79": {"A":"'Daleko od očiju, daleko od srca' znači udaljenost, pa nije suprotno, nego blisko značenju 'Bogu iza leđa'.","B":"'Dati petama vjetra' znači pobjeći, što nije značenjski suprotno udaljenosti.","C":"'Imati koga za vratom' znači biti opterećen nekim, a ne biti blizu/dostupan – nije pravi antonim."},
  "2017_jesen_A__80": {"B":"Novosadski dogovor iz 1954. zaseban je događaj, a ne Deklaracija iz 1967.","C":"Bečki književni dogovor iz 1850. nije Deklaracija o nazivu i položaju hrvatskoga jezika.","D":"Tekst iz 1911. nije Deklaracija; Deklaracija je objavljena 1967."},

  // 2017_jesen_B
  "2017_jesen_B__1": {"A":"Idilična jesen vinograda samo je kontrastna pozadina, a ne tema; pjesma se okreće 'jeseni prljavoga grada' i subjektovoj tuzi.","C":"Snovi se spominju tek u negaciji ('Trgnut iz snova'), kao stanje iz kojega je subjekt naglo izbačen u tešku javu, pa nisu tema.","D":"Pjesma ne govori o čekanju drage osobe, nego o samoći, čemeru i šutnji lirskoga subjekta."},
  "2017_jesen_B__2": {"A":"'Divna jesen' nije zvukovni motiv pa se ne može značenjski suprotstaviti zvuku 'gajde ječe'.","B":"'Vedri vinograd' je vizualni, idilični motiv, a ne ružan zvuk koji bi bio suprotnost ječanju gajdi.","C":"'Prangije tutnje' također je vesео, svečan zvuk iste, idilične seoske slike, dakle istovrstan, a ne suprotstavljen 'gajdama'."},
  "2017_jesen_B__3": {"A":"Grad je prostorni, vizualni motiv ('prljavi grad'), a ne nešto što se osjeća dodirom kože.","B":"Kletva je govorni, slušni/misaoni motiv ('s kletvom u grlu'), nije taktilni podražaj.","C":"Glava ('s pognutom glavom') je vizualni znak poniženja, a ne osjet dodira ili temperature."},
  "2017_jesen_B__4": {"A":"Ljubav nije ono što se uspoređuje s bršljanom; bršljanu je pridružena misao koja se ovila uz dragu.","B":"San (sanak) označava stanje zaljubljenosti, a usporedba 'kao bršljan' odnosi se na misao, ne na san.","D":"Stablo je drugi član slike — ono uz što se bršljan (misao) ovija ('tvoj život'), a ne ono što se uspoređuje s bršljanom."},
  "2017_jesen_B__5": {"A":"'Ljubavni sanak' označava subjektovo stanje zaljubljenosti, a ne dragu osobu.","C":"'Tašta zabava' odnosi se na uzaludno subjektovo traženje dana zaljubljivanja, a ne na voljenu osobu.","D":"'Pamet uspavana' opisuje razum na početku ljubavi, a ne dragu osobu."},
  "2017_jesen_B__6": {"A":"Ti stihovi opisuju trenutak pada u ljubav, a ne zaključnu misao soneta.","B":"Stihovi o misli ovijenoj kao bršljan razrađuju sliku zaljubljivanja, ali nisu poanta nego njezina priprema.","C":"Stihovi o uzaludnu traženju dana zaljubljivanja vode prema poanti, ali je sami ne izriču."},
  "2017_jesen_B__7": {"B":"Minos ne savjetuje duše da odaberu put, nego im sudi i određuje kaznu.","C":"Minos ne proždire duše; on ih repom razvrstava po krugovima pakla.","D":"Repom ne tuče duše, nego brojem namotaja repa označava krug u koji duša pada."},
  "2017_jesen_B__8": {"A":"Riječ se ne odnosi na Boga, nego na onoga koji prolazi paklom; Vergilije brani Danteov put.","B":"Minosu se upravo upućuje opomena, pa se 'njegov put' ne može odnositi na samoga Minosa.","D":"Vođ (Vergilije) je onaj koji govori, a ne onaj o čijem se putu govori, pa se riječ ne odnosi na njega."},
  "2017_jesen_B__9": {"A":"'Prvi krug' je doslovan naziv dijela pakla, a ne metafora za pakao u cjelini.","C":"'Široki put' u tekstu ne postoji kao metafora pakla.","D":"'Put usudni' označava sudbinski put duše/Dantea, a ne sam pakao."},
  "2017_jesen_B__10": {"B":"Don Quijote ne napada zato što mu je zapriječen prolaz, nego zato što umišlja da redovnici otimaju kraljevnu.","C":"Nema spomena o otetoj mazgi; razlog napada je umišljena oteta princeza.","D":"Redovnici ga ne vrijeđaju, nego smireno objašnjavaju tko su; napad proizlazi iz njegove obmane."},
  "2017_jesen_B__11": {"A":"Redovnici ne izbjegavaju razgovor, nego smireno odgovaraju i objašnjavaju tko su.","C":"Ne bježe ugledavši viteza, nego se zaustavljaju i začuđuju.","D":"Redovnici se ne dodvoravaju don Quijoteu, nego mirno ispravljaju njegovu zabludu."},
  "2017_jesen_B__12": {"B":"'Nepravedan' označava odsutnost pravednosti, a 'neumoljiv' znači nepopustljiv, što nije isto.","C":"'Nerazuman' upućuje na manjak razuma, dok 'neumoljiv' znači da se nije dao odvratiti od nauma.","D":"'Nespretan' znači nevješt, a ne nepopustljiv, pa ne odgovara značenju riječi 'neumoljiv'."},
  "2017_jesen_B__13": {"B":"Tekst ne navodi Gregorijančevu zlovolju kao ono što je Želničkoga začudilo, nego druženje bivših neprijatelja.","C":"Začuđenost ne potječe od bliskosti oca i sina, nego od zajedničkoga stola dvaju nekadašnjih neprijatelja.","D":"Veliki broj gostiju nije izvor čuđenja; iznenadilo ga je tko su ti gosti (Alapić i Gregorijanec zajedno)."},
  "2017_jesen_B__14": {"B":"Pavao Gregorijanec stoji uz prozor i pritišće čelo o staklo, dakle ne njiše se.","C":"Stjepko Gregorijanec je 'prvi', zamišljen i upire se laktom o stol, a ne njiše se.","D":"Želnički je tek ušao i zaustavio se na pragu, pa nije onaj koji se njiše."},
  "2017_jesen_B__15": {"A":"'Masne' bi se odnosilo na masnoću, a 'omašan' znači velik, krupan.","C":"'Prašnjave' su u rečenici 'zaprašene mape', a 'omašne' znači povelike.","D":"'Ukrašene' ne odgovara značenju; 'omašan' upućuje na veličinu, a ne na ukras."},
  "2017_jesen_B__16": {"A":"Justa ne pokazuje zahvalnost Mihi, nego se nakitom razmeće pred drugima ('neka se vidi i zna').","B":"Ne premeće đerdan da bi procijenila vrijednost dara, nego da ga drugi vide.","C":"Nije riječ o želji da dobro razgleda dar, nego da se njime pohvali pred okolinom."},
  "2017_jesen_B__17": {"A":"Kanonik ne govori o neodobravanju seljana, nego zadirkuje par želeći vidjeti ozbiljnost veze.","C":"Ne izražava bojazan da Miha neće biti sretan, nego potiče potvrdu njihove ozbiljne veze.","D":"Vezu ne smatra smiješnom; nagovara ih na simbole prave, ozbiljne veze."},
  "2017_jesen_B__18": {"A":"Miha nije poklonio golubicu; dar koji Justa premeće je đerdan (ogrlica).","C":"Nije riječ o prstenu, nego o đerdanu koji se 'ljeska i bljeska o suncu'.","D":"Šeširić (klobučić) je Mihina vlastita kapa, a ne dar Justi."},
  "2017_jesen_B__19": {"A":"'Čudna jesen' je opći okvir pripovijedanja, a praznovjerje izrijekom potiče pojava kometa.","C":"'Učestale kiše' donose obilje i ljepotu, nisu vezane uz praznovjerje.","D":"'Bijela sela' su slikoviti opis kraja, a strah/praznovjerje vezuje se uz zvijezdu repaču."},
  "2017_jesen_B__20": {"A":"Seljaci iz Luga žive u kraju, ali stari vinogradi pripadaju čardačkim trgovcima, ne njima.","C":"'Gospodari kućica' nisu navedeni kao vlasnici vinograda; vlasnici su čardački trgovci.","D":"Serdar i Serdarovica samo odlaze raditi u vinograde na glavici, ali nisu njihovi vlasnici."},
  "2017_jesen_B__21": {"A":"Opis se ne oslanja na riječi mjesnoga govora, nego na umanjenice koje stvaraju idiličan ugođaj.","B":"Preuveličavanja (hiperbole) nisu glavna značajka; krajolik je obojen umanjenicama.","D":"Isticanje suprotnosti (antiteza) ne obilježava ovaj opis; prevladavaju deminutivi ('selašca', 'kišice', 'glavica')."},
  "2017_jesen_B__22": {"A":"Rečenica ne govori o prepuštanju brige čuvarima, nego o čestoj uporabi skrivenih puteljaka.","B":"'Mogućnost' nije razgovor sa zatvorenicima, nego mogućnost neopaženog ulaska u Avliju.","D":"Nije riječ o preprodaji kuća; 'mogućnost' se odnosi na tajno ulaženje u zatvor."},
  "2017_jesen_B__23": {"A":"S položajem svojega imanja Karađoz nije zaokupljao zatvorenike; razgovarao je o krivnji.","B":"Uvjeti života u Avliji nisu tema njegovih razgovora; pita o krivnji zatvorenika.","C":"O vlastitoj prošlosti ne razgovara sa zatvorenicima, nego o njihovoj ili tuđoj krivici."},
  "2017_jesen_B__24": {"B":"Nemogućnost da se točno zna kad je tu nije proturječje koje krije istinu, nego opis neuhvatljivosti, pa nije paradoks.","C":"Mogućnost da stane uz čovjeka i nastavi razgovor o krivici jednostavna je tvrdnja bez prividne proturječnosti.","D":"Nadziranje i zatvorenika i čuvara nije proturječna spojnica, nego nabrajanje, pa nije paradoks."},
  "2017_jesen_B__25": {"A":"Strobil ne djeluje prema znakovima iz prirode; vode ga vlastiti interesi (dobit).","B":"Iako ima gospodara, on nije bezuvjetno poslušan, nego radi za svoju korist ('gdje me dobit vabi').","C":"Odluke ne donosi slušajući bogove; ravna se prema osobnoj koristi."},
  "2017_jesen_B__26": {"A":"Ne penje se da se sakrije od gospodara, nego da uhodi Eukliona i vidi gdje krije zlato.","B":"Ne bježi od Eukliona, nego ga prati ('Preteći ću ga... da vidim gdje će starac zlato sakriti').","C":"Cilj penjanja nije dohvaćanje zlata, nego uhođenje da sazna gdje će ga starac sakriti."},
  "2017_jesen_B__27": {"A":"Euklion ne traži novo skrovište zbog zaštite gavrana; gavran ga je tek upozorio na opasnost.","C":"Bogovi mu nisu naredili promjenu skrovišta; on sam zaključuje da staro nije sigurno.","D":"Silvan ga nije iznevjerio; naprotiv, kod Silvanova gaja traži novo, sigurnije skrovište."},
  "2017_jesen_B__28": {"A":"Nora ne želi vratiti stari brak; upravo ga odbacuje kao život 'sa strancem'.","B":"Ne pati zbog gubitka Helmerove časti; razočarana je njegovom sebičnošću i lažnošću braka.","C":"Nije sretna zbog Helmerove zaštite; ta je 'zaštita' dio odnosa lutke koji odbija."},
  "2017_jesen_B__29": {"A":"Helmerova se promjena ne veže uz to da se Nora prestane ponašati kao dijete; ona ironično najavljuje svoj odlazak.","B":"Promjena se ne uvjetuje time da Nora brani njegovu čast, nego time da on ostane bez nje.","C":"Nije uvjet da Nora prestane paničariti (paničario je on); uvjet je gubitak Nore ('kad ti oduzmu lutku')."},
  "2017_jesen_B__30": {"A":"Tvrdnja o tome kakvog bi muža željela trijezna je ocjena, bez preuveličavanja.","B":"Spomen osam godina i troje djece činjenična je izjava, a ne hiperbola.","D":"Konstatacija da ne može biti njegova supruga izrečena je suzdržano, bez hiperbole."},
  "2017_jesen_B__31": {"A":"'Barbara bješe' ponavlja se na početku stihova pa jest anafora, ali traženi je primjer onaj s ponavljanjem na kraju.","B":"'Neveseo' se ponavlja kao spona kraj/početak stiha, što odgovara anadiplozi, a ne anafori.","D":"U ovom primjeru nema istovrsnoga ponavljanja iste riječi na početku uzastopnih stihova."},
  "2017_jesen_B__32": {"A":"Antiteza je suprotstavljanje pojmova, a ovdje se gomilaju isti veznici 'i', što je polisindeton.","B":"Hiperbola je preuveličavanje, a ovdje nema preuveličavanja, nego ponavljanja veznika.","C":"Onomatopeja oponaša zvukove, čega u navedenim stihovima nema."},
  "2017_jesen_B__33": {"A":"Eufemizam je ublažavanje neugodnog izraza, a 'mrtvi život' ne ublažava, nego spaja suprotnosti.","B":"Metafora je prijenos značenja po sličnosti, a ovdje je riječ o spoju proturječnih pojmova.","D":"Simploka je ponavljanje na početku i kraju, čega u sintagmi 'mrtvi život' nema."},
  "2017_jesen_B__34": {"A":"Sonet nema deset stihova.","B":"Sonet nema dvanaest stihova.","D":"Sonet nema šesnaest stihova; ima ih četrnaest (2 katrena i 2 terceta)."},
  "2017_jesen_B__35": {"B":"Osnovni ugođaj tuge, čežnje i boli obilježje je elegije, a ne ode.","C":"Ironičan i satiričan ton svojstven je satiri, a ne svečanoj odi.","D":"Veličanje životnih radosti i užitaka odlika je anakreontike, a ne ode."},
  "2017_jesen_B__36": {"A":"Stihovi o mužu sa žala Troje koji stiže u Lavinij početak su Vergilijeve Eneide.","B":"Stih o 'prometnom mužu' koji razori Troju početak je Homerove Odiseje.","D":"Stihovi o skitskoj zemlji potječu iz Eshilova Okovanog Prometeja, a ne iz Ilijade."},
  "2017_jesen_B__37": {"A":"Anakreont je grčki pjesnik, a ne rimski književnik.","B":"Eshil je grčki tragičar, ne pripada rimskoj književnosti.","D":"Sofoklo je grčki tragičar, a ne rimski književnik."},
  "2017_jesen_B__38": {"A":"Edip ne govori o krađi vatre niti je prikovan pod nebom zbog dara ljudima.","B":"Hektor je trojanski junak iz Ilijade, nije povezan s krađom vatre.","C":"Odisej nije lik koji je ukrao vatru i bio za to prikovan."},
  "2017_jesen_B__39": {"A":"Aleksandrida je srednjovjekovni roman o Aleksandru Velikom, a ne enciklopedija.","C":"Rumanac Trojski je srednjovjekovni roman o Troji, a ne enciklopedija.","D":"Vinodolski zakonik je pravni tekst, a ne enciklopedija."},
  "2017_jesen_B__40": {"A":"Dante Alighieri stvara u 13. i 14. stoljeću, a ne početkom 17. stoljeća.","B":"Francesco Petrarca pripada 14. stoljeću, ne početku 17. stoljeća.","C":"Giovanni Boccaccio pripada 14. stoljeću, ne početku 17. stoljeća."},
  "2017_jesen_B__41": {"A":"Bokčilo je sluga (parazit), a ne lik koji izgovara prolog.","C":"Dundo Maroje je naslovni lik, ali prolog ne izgovara on.","D":"Pomet je sluga-spletkar, no prolog izgovara Dugi Nos (Negromant)."},
  "2017_jesen_B__42": {"A":"Gundulić nije pisao u 15. stoljeću.","B":"Gundulić nije pisao u 16. stoljeću.","D":"Gundulić nije pisao u 18. stoljeću; stvarao je u 17. stoljeću (barok)."},
  "2017_jesen_B__43": {"A":"Boccacciov Dekameron zbirka je novela napisanih u prozi, a ne u stihovima.","B":"Molièreov Škrtac napisan je u prozi, a ne u stihovima.","D":"Voltaireov Candide je filozofska pripovijest u prozi, a ne u stihovima."},
  "2017_jesen_B__44": {"A":"Goethe ne pripada renesansi (16. st.), nego razdoblju oko prijelaza 18. u 19. stoljeće.","B":"Goethe ne pripada baroku, nego romantizmu (i Sturm und Drangu te weimarskoj klasici).","D":"Goethe ne pripada realizmu, nego romantizmu."},
  "2017_jesen_B__45": {"A":"Prvi hrvatski romani javljaju se tek u realizmu (Šenoa), a ne u romantizmu/preporodu.","C":"Ugledanje na francuske simboliste obilježje je moderne, a ne hrvatskoga romantizma.","D":"Pretežno religiozna tematika obilježje je srednjovjekovlja i baroka, a ne romantizma."},
  "2017_jesen_B__46": {"A":"Najpoznatija zbirka u krakovjacima vezuje se uz Antuna Mihanovića/narodni stih, a ne uz Kranjčevića.","B":"Kranjčević nema samo jednu zbirku napisanu slobodnim stihom; tvrdnja ne odgovara njegovu opusu.","D":"Većinu Kranjčevićeva opusa ne čine soneti; piše raznorodnu, buntovničku i socijalnu liriku."},
  "2017_jesen_B__47": {"A":"Zalaganje za čisti psihički automatizam obilježje je nadrealizma (Breton), a ne Brechta.","B":"Tehnika eksperimentalnoga romana pod utjecajem pozitivizma vezuje se uz naturalizam (Zola), ne uz Brechta.","C":"Načelo umjetnosti radi umjetnosti zastupali su parnasovci i esteti, a ne Brecht."},
  "2017_jesen_B__48": {"B":"Juriš je ekspresionistički časopis iz 20. stoljeća, ne iz 19. stoljeća.","C":"Razlog je časopis pokrenut 1960-ih (20. st.), a ne u 19. stoljeću.","D":"Vijavica je ekspresionistički časopis iz 20. stoljeća, ne iz 19. stoljeća."},
  "2017_jesen_B__49": {"A":"Sukob medvedgradskoga gospodara i Zagrepčana tema je Šenoine Seljačke bune, a ne Posljednjih Stipančića.","C":"Radnja Posljednjih Stipančića odvija se u Senju, a ne u predratnome Zagrebu.","D":"Početak razgovorom starih spisa obilježje je drugoga djela (npr. U registraturi), ne ovoga romana."},
  "2017_jesen_B__50": {"A":"Povratak Filipa Latinovicza Krleže ne sadrži lik oca Šime koji sina nagovara na bećarski život.","B":"Posljednji Stipančići Novaka govore o senjskoj patricijskoj obitelji, a ne o ocu Šimi i bećarstvu.","D":"U registraturi Kovačića nema lika oca Šime s navedenim riječima; scena pripada Đuki Begoviću."},
  "2017_jesen_B__51": {"B":"Cvjetovi zla Charlesa Baudelairea zbirka su pjesama, a ne roman.","C":"Dekameron Boccaccia zbirka je novela, a ne roman.","D":"Preobražaj Franza Kafke je novela (pripovijetka), a ne roman."},
  "2017_jesen_B__52": {"A":"André Breton autor je nadrealističkoga manifesta, a ne dadaističkoga.","B":"Filippo Tommaso Marinetti autor je futurističkoga manifesta, a ne dadaističkoga.","D":"Vladimir Majakovski pripada futurizmu, a ne dadaizmu."},
  "2017_jesen_B__53": {"B":"Stihovi nisu Matoševi; prepoznatljiva ekspresionistička slika tijela i jutra pripada Šimiću.","C":"Stihovi nisu Cesarićevi, nego Antuna Branka Šimića.","D":"Stihovi nisu Ujevićevi, nego Antuna Branka Šimića."},
  "2017_jesen_B__54": {"B":"Rečenica o mladom Tintoru i pjesmama o Senjanima pripada Posljednjim Stipančićima, a ne Krležinu romanu.","C":"Rečenica o Petru Krupiću potječe iz Šenoina Zlatarova zlata, ne iz Povratka Filipa Latinovicza.","D":"Rečenica o Dajdamu i don Fernandu pripada Andriću, a ne Krleži."},
  "2017_jesen_B__55": {"A":"Dobriša Cesarić pripada međuratnom naraštaju, a ne krugovašima.","B":"Dragutin Tadijanović pripada starijemu, međuratnom naraštaju, a ne krugovašima.","D":"Tin Ujević pripada moderni i međuraću, a ne krugovaškom naraštaju."},
  "2017_jesen_B__56": {"A":"'Ljekova' je pogrešno; pravilno je 'lijekova' (s dugim jatom ije).","B":"'Lječenja' je pogrešno; pravilno je 'liječenja'.","C":"'Lječnički' je pogrešno; pravilno je 'liječnički'."},
  "2017_jesen_B__57": {"B":"'Nicati' ne daje 'nićući'; glagolski prilog glasi drukčije, pa je oblik pogrešan.","C":"'Skakati' daje 'skačući' (k→č), a ne 'skaćući', pa je oblik pogrešan.","D":"'Vikati' daje 'vičući' (k→č), a ne 'vićući', pa je oblik pogrešan."},
  "2017_jesen_B__58": {"A":"'Otcijepiti' nije pravilno; zbog jednačenja po zvučnosti piše se 'odcijepiti'.","B":"'Otčepiti' nije pravilno; ispred č dolazi do jednačenja, pa je 'odčepiti', a izgovorno 'otčepiti' nije standardni zapis.","D":"'Otšepati' nije pravilno; pravilno je 'odšepati'."},
  "2017_jesen_B__59": {"A":"'Češljić' nastaje jotacijom (lj), a ne palatalizacijom.","C":"'Oraščić' nastaje glasovnim promjenama (sibilarizacija/jotacija na 'h'), a ne palatalizacijom g→ž.","D":"'Šeširić' nastaje bez glasovne promjene osnove, dakle bez palatalizacije."},
  "2017_jesen_B__60": {"A":"Naglasak nije na prvom slogu 'za'.","C":"Naglasak nije na slogu 'rije'.","D":"Naglasak nije na slogu 'va'; naglašen je drugi slog 'sta'."},
  "2017_jesen_B__61": {"B":"'Austro-ugarska nagodba' kao opći naziv povijesnoga akta piše se malim slovom, pa rečenica nije ispravna.","C":"'Petrarkisti' (pripadnici pjesničkoga smjera) pišu se malim slovom, pa rečenica nije pravopisno točna.","D":"'Haiku-pjesništvo' piše se malim slovom, pa rečenica nije ispravna."},
  "2017_jesen_B__62": {"A":"'Spav-' je korijen koji nosi osnovno značenje, a ne posvojnost.","B":"'-ač-' je tvorbeni sufiks za vršitelja radnje (spavač), a ne nositelj posvojnosti.","D":"Nulti morfem '-Ø' je gramatički nastavak (rod/broj/padež), a ne nositelj posvojnoga značenja."},
  "2017_jesen_B__63": {"A":"'Isklju-' nije infinitivna osnova; ona se dobiva odbijanjem samo nastavka '-ti'.","B":"'Isključ-' je prezentska, a ne infinitivna osnova.","D":"'Isključit-' nije infinitivna osnova; ona glasi 'isključi-' (bez završnoga t)."},
  "2017_jesen_B__64": {"B":"'Koja' je u nominativu (koja budi uspomene), a traži se oblik u genitivu.","C":"'Kojoj' je u dativu/lokativu (u kojoj rečenici), a ne u genitivu.","D":"'Kojom' je u instrumentalu (kojom ćeš iznenaditi), a ne u genitivu."},
  "2017_jesen_B__65": {"B":"Trebalo bi 'svoju' jer kartica pripada subjektu (ja); 'moju' je netočna uporaba posvojne zamjenice.","C":"Trebalo bi 'svoju' jer kartica pripada subjektu (mi); 'našu' nije ispravno.","D":"Trebalo bi 'svoju' jer kartica pripada subjektu (ti); 'tvoju' nije ispravno."},
  "2017_jesen_B__66": {"A":"'Zavrtješe' je aorist (svršena prošla radnja), a ne imperfekt.","C":"'Drži se' je imperativ, a ne imperfekt.","D":"'Možeš' je prezent, a ne imperfekt."},
  "2017_jesen_B__67": {"A":"'Utjecajući' je oblik tvoren od imenice (utjecaj), a ne glagolski prilog glagola utjecati.","B":"'Uticajući' je nestandardni oblik (srbizam), nije ispravan.","D":"'Utičući' je nestandardni oblik; pravilno je 'utječući'."},
  "2017_jesen_B__68": {"A":"'Premda' je dopusni veznik (uvodi surečenicu), a ne prijedlog.","C":"'Njoj' je lična zamjenica u dativu, a ne prijedlog.","D":"'Vješto' je prilog načina, a ne prijedlog."},
  "2017_jesen_B__69": {"A":"U 'grad Velika Gorica' opća imenica je muškoga roda, a vlastito ime ženskoga, pa rod nije isti.","B":"U 'kanjon Mala Paklenica' kanjon je muškoga, a Paklenica ženskoga roda, pa se rod razlikuje.","C":"U 'naselje Veliki Zdenci' naselje je srednjega roda jednine, a Zdenci muškoga roda množine, pa se rod i broj razlikuju."},
  "2017_jesen_B__70": {"A":"'Izvor' je ovdje objekt (predstavlja izvor), a ne dio imenskoga predikata.","B":"'Izvor' je ovdje subjekt (izvor je jezerce), a ne dio imenskoga predikata.","C":"'Izvor' je dio vlastita imena (Dječji vrtić Izvor), a ne dio imenskoga predikata."},
  "2017_jesen_B__71": {"A":"'Otok' je izravni objekt (oplovio je što?), a ne neizravni; 'brodicom' je priložna oznaka/sredstvo.","C":"'Ju' je izravni objekt u akuzativu (zaboravio koga?), a ne neizravni objekt.","D":"'Poziv' je izravni objekt (izbjeći što?), a ne neizravni objekt."},
  "2017_jesen_B__72": {"A":"'Zbog umora' je priložna oznaka uzroka, a ne posljedice.","B":"'Ranom zorom' je priložna oznaka vremena, a ne posljedice.","C":"'Uz veliki trud' je priložna oznaka uvjeta/pratnje, a ne posljedice."},
  "2017_jesen_B__73": {"A":"Rečenica ima jedan predikat (nisu isplovili); to je jednostavna proširena rečenica, a ne nezavisnosložena.","B":"Rečenica je zavisnosložena (izrična: rekla je da...), a ne nezavisnosložena.","C":"Rečenica ima jedan predikat (nije imala); jednostavna je, a ne nezavisnosložena."},
  "2017_jesen_B__74": {"A":"'Onda svi redom idu djedu' glavna je surečenica, a ne namjerna.","C":"'Jer svatko misli' je uzročna surečenica, a ne namjerna.","D":"'Premda ni sam nije znao' je dopusna surečenica, a ne namjerna."},
  "2017_jesen_B__75": {"B":"'Glunta' je arhaizam/historizam (stara puška), a ne egzotizam vezan uz tuđu kulturu.","C":"'Kelvin' je mjerna jedinica (internacionalizam/eponim), a ne egzotizam.","D":"'Zvizdan' je dijalektalna (regionalna) riječ, a ne egzotizam iz strane kulture."},
  "2017_jesen_B__76": {"A":"Komparacija (stupnjevanje pridjeva) i sprezanje (konjugacija glagola) različiti su pojmovi, nisu sinonimi.","B":"Bosančica i glagoljica dva su različita pisma, nisu sinonimi.","D":"Sintagma (skupina riječi) i sintaksa (jezikoslovna disciplina) različiti su pojmovi, nisu sinonimi."},
  "2017_jesen_B__77": {"B":"Tekst nije književnoumjetnički; nema umjetničkih sredstava ni izražajnosti, nego pravnu strukturu.","C":"Tekst nije publicistički; nije novinarski izvještaj, nego zakonski članak.","D":"Tekst nije znanstveni; nema znanstvene argumentacije, nego propisuje pravne odredbe."},
  "2017_jesen_B__78": {"A":"Antonimi su riječi suprotnoga značenja, a ovdje su oblici jednaki uz nepovezana značenja, dakle homonimi.","C":"Kohiponimi su podređeni pojmovi iste nadređene kategorije, što ovdje nije slučaj.","D":"Sinonimi imaju isto ili blisko značenje, a ovdje su značenja različita, pa je riječ o homonimima."},
  "2017_jesen_B__79": {"B":"'Politi koga hladnom vodom' znači razočarati ili obeshrabriti, a ne neopazice prevariti.","C":"'Tjerati vodu na svoj mlin' znači raditi u vlastitu korist, a ne prevariti koga neopazice.","D":"'Mutiti komu vodu' znači stvarati nered ili smetati, a ne neopazice obmanuti."},
  "2017_jesen_B__80": {"B":"Hrvatski vukovci rabe standardni novoštokavski nastavak '-a' (tvrdih glava), a ne '-ah'.","C":"Zadarska filološka škola nije ona za koju je karakterističan nastavak '-ah' u genitivu množine.","D":"Riječka filološka škola nije ona koju obilježava nastavak '-ah'; taj je oblik zagrebački."},

  // 2017_ljeto_A
  "2017_ljeto_A__1": {"A":"Kamen se u pjesmi spominje uz snove ('Malo kamena i puno snova'), ali se ne povezuje sa slikom srca.","B":"Koralj je dio podvodnih motiva ('među koralje'), no nije vezan uz sliku srca.","C":"Zipka pripada motivici njihanja i uspavanke, a ne slici srca."},
  "2017_ljeto_A__2": {"A":"Greben ('Piratski greben') je hrid, a ne izvor vode kao 'česma'.","C":"Koralj je morski organizam, nema značenje vrela/izvora.","D":"Poplava označava bujanje vode, a ne sam izvor kojemu je 'česma' bliskoznačnica."},
  "2017_ljeto_A__3": {"A":"Anafora je ponavljanje riječi na početku stihova; ovdje je naglašeno ponavljanje veznika, ne početni položaj.","B":"Elipsa je izostavljanje riječi, a u istaknutim stihovima veznici se upravo gomilaju, ne izostavljaju.","C":"Eufemizam je ublažavanje izraza i nema veze s naglašavanjem plavetnila ponavljanjem veznika."},
  "2017_ljeto_A__4": {"A":"Biser se spominje na kraju ('s biserom u moj skut'), ali subjekt nije njime omamljen.","B":"Cvijet (ružica) je slika koja pada u skut, a ne ono što omamljuje lirskoga subjekta.","D":"Vjera se u pjesmi ne spominje kao uzrok subjektova zanosa."},
  "2017_ljeto_A__5": {"B":"Raj se odnosi na stanje radosti i mladosti ('Raj ovoj satvaraš'), a ne na pogled.","C":"Ružica je slika onoga što pada u skut, ne metafora pogleda.","D":"Biser je slika ploda susreta, a ne metafora za pogled."},
  "2017_ljeto_A__6": {"A":"Obraćanje Bogu se spominje u sadržaju ('tebe Bog... satvori'), ali akrostihom se ne ističe.","B":"Poanta pjesme nije ono što kod Menčetića nosi akrostih.","C":"Naslov pjesme nije sadržaj akrostiha u Menčetićevoj ljubavnoj lirici."},
  "2017_ljeto_A__7": {"A":"Tekst kaže da ga je rasporio vepar, a ne rođak.","C":"Ožiljak je nastao od veprova zuba, a ne od pada.","D":"Rana potječe iz lova na vepra, a ne iz boja."},
  "2017_ljeto_A__8": {"A":"Baka nije ta koja bira ime; poziv je upućen Autoliku, djedu.","C":"Majka u krilo Autoliku stavlja dijete (Euriklija), ali ime ne daje ona.","D":"Otac nije taj koji imenuje dijete; to čini djed Autolik."},
  "2017_ljeto_A__9": {"A":"Susret s Autolikovim sinovima nije naveden kao razlog Odisejeva dolaska.","C":"Gošćenje nije motiv puta; razlog su obećani sjajni darovi.","D":"Ljubav prema djedu nije navedeni razlog odlaska, nego obećano blago."},
  "2017_ljeto_A__10": {"A":"Pripovjedač samo zamišlja ('Da bijaše noć, scijenio bih gledati mjesečarku'), no susret nije bio noćni.","C":"Iako spominje djevojčinu nijemost, on nije uvrijeđen, nego očaran i ushićen.","D":"Pripovjedač je skrušen i zadivljen, a ne odlučan zavesti djevojku."},
  "2017_ljeto_A__11": {"A":"Grozničava fantazija odnosi se na pripovjedačevu maštu, a ne na djevojku.","B":"Sjetna čežnja dio je opisa dojma, ne metafora za samu djevojku.","C":"Moderno raspuće (raskršće) je prostor susreta, ne slika djevojke."},
  "2017_ljeto_A__12": {"A":"Poniznost se izriče zasebnom riječju ('ponižen'), a 'nenadanica' znači iznenađenje.","C":"Suton se ne spominje; 'nenadanica' je neočekivani događaj.","D":"Sreća nije značenje izraza 'nenadanica', nego nenadanost, iznenađenje."},
  "2017_ljeto_A__13": {"A":"Čangrizava žena spominje se uz Candidea, a ne kao razlog Cacambova nezadovoljstva.","C":"Cacambo je nezadovoljan zbog teškoga rada, a ne zbog siromaštva.","D":"Pljačka (Židovi) pogađa Candidea, a Cacamba mori preopterećenost poslom."},
  "2017_ljeto_A__14": {"A":"Neoženjenost zaručnicom nije Panglossova muka; ožalošćen je zbog nedostatka akademskoga ugleda.","C":"Nedovoljna mudrost nije navedeni razlog; smeta mu što ne blista na sveučilištu.","D":"Bogatstvo nije ono za čim Pangloss žali, nego sveučilišna pozicija."},
  "2017_ljeto_A__15": {"A":"Voditi najugodniji život izraz je očekivanja, a ne rezignacije.","B":"Čangrizava žena prikazuje nepriliku, ali ne i pomireno prihvaćanje sudbine.","C":"Proklinjanje sudbine je pobuna i ogorčenost, suprotno rezignaciji."},
  "2017_ljeto_A__16": {"B":"Fizički obračun s neistomišljenicima nije cilj govora; Vukasović poziva na rad za grad.","C":"Poniznost pred carom suprotna je govoru koji potiče odvažnost.","D":"Cilj nije zavaravanje građana, nego njihovo poticanje na djelovanje za dobro grada."},
  "2017_ljeto_A__17": {"B":"Vukasović nije ostao samo na napisanome ('nije mogao da ostane u tim uskim granicama').","C":"Tekst ne navodi zamuckivanje; govor se razmahao i ojačao.","D":"Uživanje u odobravanju nije istaknuto; on prepoznaje zbunjenost slušatelja."},
  "2017_ljeto_A__18": {"A":"Desetak građana su Vukasovićevi istomišljenici (slušatelji), a ne protivnici.","C":"Odvažniji ljudi su oni koje treba birati za dobro grada, a ne neistomišljenici.","D":"Poniženi robovi su slika onih koje vojnička gospoda tlače, a ne sami protivnici."},
  "2017_ljeto_A__19": {"B":"Pripovjedač stricu ne pripisuje bezobzirnost prema obitelji, nego mu zavidi na poznanstvima.","C":"Neprimjereno ponašanje nije pripovjedačev sud; on stricu zavidi na povlasticama.","D":"Gostoljubivost nije ono što pripovjedač naglašava kod strica."},
  "2017_ljeto_A__20": {"B":"Nerazlikovanje glumica od kokota pripovjedačeva je nemoć, a ne uzrok svađe s ocem.","C":"Neodgovaranje na pisma ne spominje se kao razlog svađe.","D":"Ženidba glumicom nije navedeni razlog svađe; uzrok je darivanje obiteljskoga nakita."},
  "2017_ljeto_A__21": {"B":"Poštedjeti strica neugode nije razlog; obitelj izbjegava susret sa stričevim gošćama.","C":"Zauzetost u druge dane nije navedena kao razlog odabira posjeta.","D":"Stric nije odredio dane; obitelj sama dolazi kad nema neprihvatljivih posjetiteljica."},
  "2017_ljeto_A__22": {"A":"Izbjegavanje seljanki nije razlog dolaska u župni dvor.","B":"Oproštaj od pokojnika ne navodi se kao svrha odlaska.","C":"Susret s don Špirom nije razlog dolaska; Krsto je došao po škrinju (bavul)."},
  "2017_ljeto_A__23": {"A":"Izrada haljina nije svrha kupnje platna.","B":"Preprodaja nije razlog; platno služi kao protuusluga.","C":"Prenošenje bilja nije svrha kupnje platna."},
  "2017_ljeto_A__24": {"A":"Sutrašnjemu pokopu Tere se nije posvetila u kratku trenutku iz pitanja.","B":"Župnomu dvoru Tere se nije nakratko posvetila.","D":"Filičinoj škrinji nije se Tere kratko posvetila; kratko se bavila Krstinim posjetom."},
  "2017_ljeto_A__25": {"A":"Harpagon ne kaže da je Valère došao potpisati ženidbeni ugovor.","B":"Harpagon nije rekao da Valère želi saznati tko je kradljivac, nego ga sam optužuje za krađu.","C":"Osveta Anselmu nije ono što Harpagon pripisuje Valèreu."},
  "2017_ljeto_A__26": {"B":"Valère ne govori o Anselmeu kao o zločincu; sukob je oko onemogućene ženidbe.","C":"Nasilje prema zaručnici nije razlog optužnice.","D":"Krađa Anselmeova novca nije razlog; Valère je osujetio dogovorenu ženidbu."},
  "2017_ljeto_A__27": {"A":"Valère se ne oduševljava optužbama, nego im se čudi.","B":"Valère ne podržava Harpagonove tvrdnje, nego ih ne razumije.","D":"Valère ne izvrće tvrdnje, nego iskreno izražava čuđenje optužbom."},
  "2017_ljeto_A__28": {"A":"Vezivanje smrti uz Glembajev način života nije zajednička misao dvojice; oboje govore o prolaznoj fazi.","B":"Altmann sumnja da medicina može spriječiti smrt, pa to nije njihova zajednička tvrdnja.","C":"Smisao života tumače različito (medicinski organski razvoj vs. metafizički kompleksi), ne jednako."},
  "2017_ljeto_A__29": {"A":"Tekst ne pokazuje da se Silberbrandt osjeća manje vrijednim od Altmanna.","C":"Silberbrandt ne dokazuje Altmannovu liječničku nesavjesnost.","D":"Silberbrandtu nije nejasno Altmannovo izlaganje; on ga drži presvedenim na premalo."},
  "2017_ljeto_A__30": {"A":"Antropocentrizam ne znači stvaranje kompleksa u čovjeku, nego stavljanje čovjeka u središte.","C":"Nadređivanje Boga čovjeku nije značenje antropocentričkoga gledišta.","D":"Antropocentrizam ne znači nešto čovjeku nerazumljivo, nego usredotočenost na čovjeka."},
  "2017_ljeto_A__31": {"B":"Elegija je lirska vrsta (tužaljka), ne pripada epskomu rodu.","C":"Gazela je lirska pjesnička vrsta, ne epska.","D":"Oda je lirska vrsta (svečana pohvalnica), ne epska."},
  "2017_ljeto_A__32": {"B":"Arhaični rječnik je obilježje stila, a ne postupak usporavanja radnje.","C":"Početak u središtu zbivanja je 'in medias res', a ne retardacija.","D":"Zaziv viših sila je invokacija, a ne retardacija."},
  "2017_ljeto_A__33": {"A":"Oktava nije pjesma od osam strofa, nego strofa od osam stihova.","C":"Osmerac je stih od osam slogova, a ne oktava.","D":"Oktava se ne definira brojem stopa u stihu."},
  "2017_ljeto_A__34": {"B":"Anafora je ponavljanje na početku uzastopnih stihova, a ovdje se riječ ponavlja na spoju kraja i početka.","C":"Epifora je ponavljanje na kraju stihova, što ovdje nije slučaj.","D":"Simploka spaja anaforu i epiforu, a u primjeru je riječ o anadiplozi."},
  "2017_ljeto_A__35": {"B":"'Zlatno sunašce' je sklad atributa (sjaj uz sunce), nema proturječja, pa nije oksimoron.","C":"Suprotstavljanje velikoga svijeta i pustinje je antiteza, a ne oksimoron u jednoj sintagmi.","D":"'Strašnom, nevjernom talasu' su epiteti istoga predznaka, bez unutarnjega proturječja."},
  "2017_ljeto_A__36": {"A":"Horacije je autor Oda i Pjesničkoga umijeća, a ne Metamorfoza.","B":"Katul je rimski lirik, ne autor Metamorfoza.","D":"Vergilije je autor Eneide, a ne Metamorfoza."},
  "2017_ljeto_A__37": {"B":"Likonid je mladić zaljubljen u Euklionovu kćer, a navedene riječi izgovara kućni bog u prologu.","C":"Megador je susjed prosac, a ne govornik prologa o čuvanju doma.","D":"Sluga Strobil ne čuva dom naraštajima; to čini Lar (kućni bog)."},
  "2017_ljeto_A__38": {"A":"Ljetopis popa Dukljanina je rukopisno djelo, ne tiskana inkunabula.","C":"Red i zakon zadarskih dominikanki je rukopis, a ne inkunabula.","D":"Zapis popa Martinca je rukopisni zapis, ne tiskana knjiga."},
  "2017_ljeto_A__39": {"A":"Ahilej je grčki junak koji gine pod Trojom, ne luta morem nakon njezine propasti.","C":"Hektor je trojanski junak koji pogiba u boju, ne osnivač novoga grada.","D":"Prijam je trojanski kralj koji strada pri padu Troje, a ne putnik prema Rimu."},
  "2017_ljeto_A__40": {"A":"Gilgameš je starovjekovni (babilonski) ep, ne srednjovjekovni.","B":"Osman (Gundulić) je barokni ep iz 17. stoljeća.","D":"Bijesni Orlando (Ariosto) je renesansni ep."},
  "2017_ljeto_A__41": {"A":"Apsurdne situacije i nemogućnost komunikacije obilježje su drame apsurda, ne klasicizma.","B":"Idealizirani likovi vođeni božanskim silama bliži su antičkoj drami, ne klasicizmu.","D":"Neshvaćeni sanjari obilježje su romantizma, ne klasicizma."},
  "2017_ljeto_A__42": {"A":"Podjela na dvije katrene i dvije tercine vrijedi za Petrarcin, ali ne za Shakespeareov sonet.","B":"Rasporedi rima razlikuju se kod dvaju tipova soneta, pa to nije zajedničko.","D":"Akrostih nije obvezno obilježje ni jednoga od tih soneta."},
  "2017_ljeto_A__43": {"A":"Barunica Castelli (Glembajevi) ne osvaja ženomrsca podilaženjem niti se na kraju udaje za čovjeka svojega staleža.","B":"Majka Courage (Brecht) je trgovkinja u ratu, ne lik koji se na kraju udaje za jednakoga.","D":"Nora (Ibsen) na kraju napušta obitelj, a ne udaje se za čovjeka svojega staleža."},
  "2017_ljeto_A__44": {"A":"Marin Držić je dramatičar (Dundo Maroje), ne autor alegorije vila s jabukama.","B":"Marko Marulić je autor Judite, a ne opisane alegorije vila.","C":"Petar Hektorović napisao je Ribanje i ribarsko prigovaranje, ne navedenu alegoriju."},
  "2017_ljeto_A__45": {"A":"Ispovjedni ton o vlastitoj grešnosti odgovara Suzama sina razmetnoga, a ne Dubravki.","B":"Povijesna tema i stihovi o oholosti vode Osmanu, ne Dubravki.","D":"Prepjevani biblijski psalmi obilježje su Davidijade/psalmodije, a ne Dubravke."},
  "2017_ljeto_A__46": {"A":"Antun Mihanović poznat je po Horvatskoj domovini, nije se sukobio s Gajem oko uloge književnosti.","B":"Pavao Štoos je preporodni pjesnik, ne protivnik Gajevih shvaćanja.","C":"Petar Preradović je preporodni pjesnik, a ne sudionik toga sukoba s Gajem."},
  "2017_ljeto_A__47": {"A":"Đuka Begović (Kozarac) ne završava oproštajnim pismom o samoubojstvu.","C":"Ivica Kičmanović (U registraturi) strada, ali ne ostavlja takvo propitujuće pismo prijatelju.","D":"Pavao Gregorijanec (Zlatarovo zlato) gine u sukobu, bez završnoga pisma o vlastitoj propasti."},
  "2017_ljeto_A__48": {"A":"Combray (Proust) počinje sjećanjem na uspavljivanje, ne opisom pansiona.","B":"Junak našeg doba (Ljermontov) ne počinje opisom pansiona gospođe Vauquer.","C":"Kabanica (Gogolj) prati činovnika Akakija, ne otvara se pansionom Vauquer."},
  "2017_ljeto_A__49": {"B":"Ubojstvo ljubomornoga muža nije završetak Posljednjih Stipančića.","C":"Junakinja ne napušta obitelj zbog spoznaje zablude braka.","D":"Pogubljenje odmetnice nije završetak romana; Lucija ostaje sama u sjećanjima."},
  "2017_ljeto_A__50": {"A":"Gongorizam je barokni stilski pojam (kitnjasti stil), ne modernistički.","B":"Manirizam pripada kasnoj renesansi/prijelazu u barok, ne modernizmu.","D":"Verterizam je vezan uz romantizam (Goetheov Werther), ne uz modernizam."},
  "2017_ljeto_A__51": {"B":"Don Fernando nije lik Proklete avlije.","C":"Vodnik Beranek pripada drugomu djelu, ne Andrićevoj Prokletoj avliji.","D":"Student Vidović nije lik Proklete avlije."},
  "2017_ljeto_A__52": {"A":"Navedeni stihovi o krhkosti znanja nisu Cesarićevi.","B":"Tadijanović nije autor tih stihova.","C":"Slavko Mihalić nije autor navedenih stihova."},
  "2017_ljeto_A__53": {"A":"Alfred Kamenski (Camao) nije lik koji se vraća iz zarobljeništva izobličen i ljubomoran.","B":"Juraj Stipančić (Posljednji Stipančići) nije ljubomorni povratnik iz zarobljeništva.","D":"Melkior Tresić (Kiklop) je intelektualac u ratnom Zagrebu, ne povratnik koji sumnja u vjernu suprugu."},
  "2017_ljeto_A__54": {"B":"Predstava u predstavi i dokidanje granice gledatelj–glumac obilježje su Pirandella, ne Brechta.","C":"Radnja Majke Courage nije ograničena na zatvoreni prostor.","D":"Brecht namjerno krši jedinstvo vremena, mjesta i radnje, ne poštuje ga."},
  "2017_ljeto_A__55": {"B":"Približavanje oluje nije Pupačićeva zbirka.","C":"Srebrne svirale su zbirka Gustava Krkleca, ne Pupačića.","D":"Lelek sebra je zbirka Antuna Branka Šimića, ne Pupačića."},
  "2017_ljeto_A__56": {"A":"'Podčinjen' je netočno; jednačenjem po zvučnosti glasi 'potčinjen'.","C":"'Podkupljen' je netočno; pravilno je 'potkupljen'.","D":"'Podpaljen' je netočno; pravilno je 'potpaljen'."},
  "2017_ljeto_A__57": {"A":"U 'jaučem' je riječ o jotaciji/glasovnoj promjeni k→č nije palatalizacija ispred e u istom smislu kao kod 'razmičem'.","B":"'Natačem' nije primjer palatalizacije k→č ispred e iz osnove na -k.","C":"'Povučem' također ne pokazuje palatalizaciju kakva je u 'razmičem' (od razmak)."},
  "2017_ljeto_A__58": {"A":"'Početku' je u lokativu (na početku), ne u dativu.","B":"'Sastanka' je u genitivu, ne u dativu.","C":"'To' je u nominativu (subjekt), ne u dativu."},
  "2017_ljeto_A__59": {"A":"'Li' je zanaglasnica (enklitika), ne prednaglasnica.","B":"'Ti' je zanaglasnica (enklitika), dolazi iza naglašene riječi.","C":"'Se' je zanaglasnica (enklitika), ne prednaglasnica."},
  "2017_ljeto_A__60": {"A":"Naglasak zastarijȅvati (kratkosilazni) nije pravilan u toj riječi.","B":"Naglasak zastarijêvati (dugosilazni) nije pravilan ovdje.","D":"Naglasak zastarijévati (dugouzlazni) nije pravilan; pravilan je kratkouzlazni."},
  "2017_ljeto_A__61": {"A":"Pogrešno je 'Austro-Ugarske Monarhije'; riječ 'monarhija' piše se malim slovom.","B":"Pogrešno je 'Matica Hrvatska'; pravilno je 'Matica hrvatska'.","C":"Pogrešno je 'Sulejmana prvoga veličanstvenog'; nadimak se piše velikim slovom (Sulejman Veličanstveni)."},
  "2017_ljeto_A__62": {"B":"Rastavba 'pje-va-čev' netočno cijepa osnovu i sufiks po slogovima, a ne po morfemima.","C":"'Pje-vač-ev' pogrešno dijeli osnovu; osnova je 'pjevač-'.","D":"'Pjev-ač-ev' krivo izdvaja morfeme; osnova je cijela riječ 'pjevač'."},
  "2017_ljeto_A__63": {"B":"U toj rečenici 'koje' uz 'plemstvo' stoji u jednini, ne u množini.","C":"'Koja' uz 'momčad' (zbirna imenica u jednini) nije u množini.","D":"'Koje' uz 'lišće' (zbirna imenica u jednini) nije u množini."},
  "2017_ljeto_A__64": {"A":"'Njezinu' je posvojna zamjenica, ne pokazna.","B":"'Kojega' je odnosna (relativna) zamjenica, ne pokazna.","D":"'Svoje' je povratno-posvojna zamjenica, ne pokazna."},
  "2017_ljeto_A__65": {"A":"'Sjeknuvši' bi bio prilog prošli svršenoga glagola, a 'sjeći' je nesvršen.","B":"'Sjekavši' je glagolski prilog prošli, a traži se prilog sadašnji.","D":"'Sijekući' je netočan oblik; pravilno je 'siječući'."},
  "2017_ljeto_A__66": {"A":"'Sa ili bez radnoga iskustva' je negramatično; prijedlozi traže različite padeže ('s radnim iskustvom ili bez njega').","B":"'Pišu se s kemijskom olovkom' je pogrešno; pravilno je 'kemijskom olovkom' (instrumental sredstva bez 's').","C":"'Plaća račune preko mobitela' je pogrešno; pravilno je 'mobitelom' (instrumental sredstva)."},
  "2017_ljeto_A__67": {"B":"'Zlatni' je opisni pridjev s pridjevnom (određenom) sklonidbom.","C":"'Najskrovitijemu' je opisni pridjev u superlativu s pridjevnom sklonidbom.","D":"'Dnevnome' je opisni pridjev s pridjevnom sklonidbom, ne imeničkom."},
  "2017_ljeto_A__68": {"A":"'Ljubavna patnja' je sročnost (slaganje) pridjeva i imenice, ne upravljanje.","B":"'Iskreno ljubiti' je pridruživanje priloga glagolu, ne upravljanje padežom.","C":"'Prva ljubav' je sročnost, ne upravljanje."},
  "2017_ljeto_A__69": {"A":"'Nisu mogli' izostavlja infinitiv 'pobijediti' koji je dio predikata.","B":"'Nisu nas mogli' uključuje objekt 'nas', koji nije dio predikata.","C":"'Mogli pobijediti' izostavlja niječni pomoćni glagol koji pripada predikatu."},
  "2017_ljeto_A__70": {"A":"'Svakim' je atribut uz 'korakom', ne objekt.","B":"'Svijetu' je dio priloške oznake mjesta (po ovome svijetu), ne objekt.","D":"'Tragove' je izravni objekt (akuzativ), a traži se neizravni."},
  "2017_ljeto_A__71": {"B":"'Jer' uvodi uzročnu rečenicu, ne posljedičnu.","C":"'Ako' uvodi pogodbenu (uvjetnu) rečenicu, ne posljedičnu.","D":"'Premda' uvodi dopusnu rečenicu, ne posljedičnu."},
  "2017_ljeto_A__72": {"A":"Zarez iza 'radnog mjesta' nije potreban jer priloška oznaka stoji ispred subjekta bez umetanja.","B":"'Predstavnik krugovaša, Josip Pupačić' traži zarez i iza apozicije, pa je pisanje nepotpuno/pogrešno.","C":"Ispred 'jer' u toj rečenici ne stavlja se zarez."},
  "2017_ljeto_A__73": {"A":"'Raspravljali smo problem' je pogrešno; pravilno je 'raspravljali o problemu'.","B":"'Grižnja savjest' je pogrešno; pravilno je 'grižnja savjesti' (genitiv).","C":"'Tražila novac' bez prijedloga je upitno; pravilnije 'tražila od njega novac', rečenica je negramatična."},
  "2017_ljeto_A__74": {"A":"'Zagreb-Rijeka' treba crticu (Zagreb – Rijeka) jer označava relaciju, ne spojnicu.","C":"'1678.-1734.' treba crticu (raspon godina), ne spojnicu.","D":"'idi mi-dođi mi' netočno je spojeno spojnicom; izraz se piše drukčije."},
  "2017_ljeto_A__75": {"A":"'Fildžan' je posuđenica (turcizam), ne eponim po osobi.","B":"'Glunta' nije nazvana po osobi, pa nije eponim.","D":"'Zvizdan' je narječni izraz za vrućinu, nije nastao po imenu osobe."},
  "2017_ljeto_A__76": {"A":"'Cvjećarnica' je tvorena sufiksom -arnica, ne -ica.","B":"'Čekaonica' je tvorena sufiksom -onica, ne -ica.","D":"'Sudnica' je tvorena sufiksom -nica, ne -ica."},
  "2017_ljeto_A__77": {"B":"Uzaludan posao izriče se drugim frazemima (npr. 'nositi vodu rešetom'), ne ovim.","C":"Otkrivanje općepoznatoga nije značenje ovoga frazema.","D":"Stvaranje neočekivanih poteškoća nije značenje 'tjerati vodu na svoj mlin'."},
  "2017_ljeto_A__78": {"A":"Antroponimija je uži pojam (imena ljudi), dio onomastike, ne njezin nadpojam.","B":"Frazeologija proučava frazeme i nije nadređena onomastici.","C":"Imenoslovlje je istoznačnica za onomastiku, ne hiperonim."},
  "2017_ljeto_A__79": {"A":"'Virovitičankin' je posvojni pridjev, ne etnik.","C":"'Virovitički' je odnosni (ktetik) pridjev, ne etnik.","D":"'Virovitica' je toponim (ime mjesta), ne etnik."},
  "2017_ljeto_A__80": {"B":"Hrvatski vukovci zalagali su se za fonološki pravopis i nastavke bez -ah, suprotno ovomu obliku.","C":"Zadarska filološka škola nije obilježena genitivnim nastavkom -ah kao zagrebačka.","D":"Riječka filološka škola nije prepoznatljiva po nastavku -ah u genitivu množine."},

  // 2017_ljeto_B
  "2017_ljeto_B__1": {"B":"Staze se u pjesmi spominju kao prostor lutanja i patnje, a ne kao predmet čežnje na koji upućuje 'nju'.","C":"Vjera nije adresat naslova; religiozni prizvuci (Zdravemarije) tek su dio domovinske slike, a ne predmet 'misli na nju'.","D":"Pjesma ne tematizira čežnju za ženom, nego za zavičajem (maslinama, Salonama, rodnim arijama)."},
  "2017_ljeto_B__2": {"B":"'Namočiti' znači ovlažiti, što ne odgovara značenju iscrpljenosti koje nosi 'utruditi'.","C":"'Otvrdnuti' upućuje na stvaranje žuljeva, ali glagol 'utruditi' označava umor, a ne otvrdnuće.","D":"'Zaprašiti' se veže uz prašinu drumova, no 'utruditi' znači izmučiti, a ne zaprašiti."},
  "2017_ljeto_B__3": {"B":"Stih govori o zvuku (arijama) rodnoga kraja, a ne o vizualnoj ljepoti večernjeg krajolika.","C":"Crkvena zvona nisu spomenuta; 'arije' su napjevi i pjesme, a ne zvonjava.","D":"Stih se odnosi na melodije zavičaja, a ne na materijalno bogatstvo gradova."},
  "2017_ljeto_B__4": {"B":"Smijeh se u pjesmi javlja kao prolazna pojava ('U smjehuljka nabrat dva se'), a ono što subjekt vječno pamti jest nijemi uzdah.","C":"Plač se izrijekom ne ostvaruje — uzdah 'u suze ne proteče'; subjekt pamti uzdah, a ne plač.","D":"Čežnja je subjektova osobina, a ono čega se vječno sjeća jest ženin nijemi uzdah na usnama."},
  "2017_ljeto_B__5": {"A":"'On će proći' odnosi se na grč/uzdah koji će nestati, a ne na ženin život.","B":"Stih o smjehuljcima opisuje izraz ženina lica, a ne metaforu njezina života.","C":"'Mutit će moje dane' odnosi se na subjektov, a ne na ženin život."},
  "2017_ljeto_B__6": {"A":"Tugovanje zbog prošlosti opisuje subjektovu bol, ali božju volju on ispunjava pjevanjem, a ne tugom.","B":"Život u skladu s prirodom nije naveden kao način ispunjavanja božje volje.","C":"Tješenje drage osobe je tema pjesme, ali božju volju subjekt vrši pisanjem pjesama ('Meni Bog je pjevat reko')."},
  "2017_ljeto_B__7": {"A":"Aga ne nastoji izbjeći sukob s kršćanima, nego naprotiv na kraju poziva na obračun ('Hazur, momci').","B":"Žrtvovanje za narod nije agina nakana; on se bori sa svojom srdžbom i ponosom.","D":"Bauk se spominje kao onaj koji izusti riječ, ali agina želja nije nagraditi ga, nego prikriti vlastiti bijes."},
  "2017_ljeto_B__8": {"B":"Plamen je u tekstu slika agine srdžbe ('Srdžbe plamen'), a ne iznenadnosti misli.","C":"Mač (noži) pripada agimu pozivu na oružje, a ne usporedbi za naglu misao.","D":"Ulje (vrelo) dio je prijetnje na kraju ulomka, a ne usporedbe za munjevitu misao."},
  "2017_ljeto_B__9": {"A":"Bijes (srdžba) prikazuje aginu reakciju, ali 'bruka' znači sramotu, a ne bijes.","B":"'Jad' označava patnju, dok 'bruka' znači sramotu, ruglo.","C":"Osveta nije značenje riječi 'bruka'; ona znači sramotu."},
  "2017_ljeto_B__10": {"A":"Sonjino suosjećanje nije razlog Katerinine tuge; uzrujao ju je nedolazak uglednih susjeda.","C":"Katerina je nezadovoljna jer su došli baš siromašni, a ne zato što bi se brinula zbog njihova siromaštva.","D":"O zakusci se govori, ali Katerinino nezadovoljstvo izazvao je izostanak gostiju, a ne sama zakuska."},
  "2017_ljeto_B__11": {"A":"Tekst ne spominje traženje više mirovine od Amalije.","B":"Pozivanje Amalijina oca u kuću nije navedeno u ulomku.","D":"Govor o zakusci nije ono čime je dosađivala; dosađivala je hvalospjevima o Lužinu."},
  "2017_ljeto_B__12": {"A":"Frazem ne znači upoznavanje s uglednim susjedom, nego oštro izricanje svojega mišljenja.","B":"'Natrljati nos' je verbalni, a ne fizički obračun.","C":"Frazem se ne odnosi na istjerivanje iz susjedstva, nego na to da joj se kaže istina u lice."},
  "2017_ljeto_B__13": {"A":"Kumordinarova uglađenost nije tema; on je upravo grub i prezriv prema Vanči.","B":"Zanemarivanje pravničkih obveza nije tema ulomka, koji prikazuje sukob oko odlaska gospodi.","D":"Seoski običaji se spominju u Vančinim riječima, ali tema je sama prepirka, a ne opis običaja."},
  "2017_ljeto_B__14": {"B":"Razlog uvrede nije Vančino odbijanje odvjetništva, nego njegovo odbijanje posjeta gospodi.","C":"Vanča ne traži ispriku gospode; on jednostavno ne želi poći k njima.","D":"Vančina želja za životom na selu pozadina je sukoba, ali kumordinara je razljutio konkretan odbijen posjet gospodi."},
  "2017_ljeto_B__15": {"B":"'Godi' znače blagdane, a ne godine (premda riječi zvuče srodno).","C":"Skupovi nisu značenje riječi 'godi'; riječ je o crkvenim blagdanima.","D":"Snovi nisu značenje; 'veliki godi' su veliki blagdani poput Uskrsa."},
  "2017_ljeto_B__16": {"A":"Sklanjanje u hladovinu nije navedeno; pastiri gone stoku prema potoku.","B":"Malaksalost na suncu nije spomenuta za pastire; oni se kreću lijeno, ali namjerno prema potoku.","D":"Pastiri ne lutaju bez cilja — gone blago 'svi u jednom pravcu', dakle prema potoku."},
  "2017_ljeto_B__17": {"A":"Odnos gradskoga i seoskoga života nije tema ovog opisnog ulomka.","B":"Konji se spominju tek kao detalj prizora; ulomak nije o Đukinu odnosu prema konjima.","C":"Đukina razmišljanja samo se uzgred spominju na početku, a ulomak slika ljepotu ljetnoga dana."},
  "2017_ljeto_B__18": {"A":"Osjećaji nisu ono što roni u travke i brazde; to čini pogled (oko).","C":"Dah se ne spominje kao ono što uranja u detalje krajolika.","D":"Dan je vrijeme radnje, a u svaku travku i brazdu roni pogled (oko)."},
  "2017_ljeto_B__19": {"A":"Tekst ne spominje šetnju bez kišobrana kao ono što je čudno pratetki (kišobran se veže uz gđu Goupil).","B":"Odlazak u crkvu nedjeljom pratetki nije čudan; ona upravo nedjelju drži danom mirovanja.","C":"Pratetki nije čudno nedjeljno nerađenje — to je za nju norma; čudno joj je čitanje radnim danom."},
  "2017_ljeto_B__20": {"A":"Mjesto šivanja haljine (Châteaudun) tetka već zna i navodi; to nije ono što želi doznati.","C":"Eulalijin dolazak tetka čeka, ali pitanje koje postavlja tiče se gđe Goupil i njezina dolaska u crkvu.","D":"Tko razgovara s Françoise nije predmet tetkina zanimanja; ona sama razgovara s njom."},
  "2017_ljeto_B__21": {"B":"Pripovjedačevo učenje čitanja nije predmet Françoisina dvoumljenja izraženog s 'možda i ne'.","C":"Tetkin dolazak Eulalije nije ono što Françoise drži neizvjesnim u svojem komentaru.","D":"Haljina je već sašivena (u Châteaudunu), pa to nije neizvjesni ishod o kojem Françoise dvoji."},
  "2017_ljeto_B__22": {"A":"Vanda ne traži povratak ureda, nego da svekrva odmakne sina od Bobočke.","B":"Uključivanje u odgoj unučadi nije Vandin zahtjev svekrvi.","C":"Podrška sinovoj karijeri nije ono što Vanda traži; ona traži djelovanje protiv Bobočke."},
  "2017_ljeto_B__23": {"A":"Odnos Vande i svekrve nije ono na što upućuje 'nagnjila rastopina'.","C":"Izraz se ne odnosi na vezu Vladimira i Bobočke kao takvu, nego na samog Vladimira koji se 'topi'.","D":"Bobočka je ta koja Vladimira rastapa među prstima, ali sama 'rastopina' je Vladimir."},
  "2017_ljeto_B__24": {"A":"Snahu kriminalnim tipom žene naziva Vanda (za Bobočku), a ne stara Ballocsanszka.","B":"Na razgovoru o Bobočki inzistirala je Vanda, a ne svekrva.","D":"Stvari sina zapečatili su sudski organi, a ne stara Ballocsanszka."},
  "2017_ljeto_B__25": {"A":"Zbor ne plače zbog straha od Prometejeve sudbine, nego iz suosjećanja s njim.","B":"Osjećaj krivnje nije izražen; zbor suosjeća, ali nije kriv za Prometejeve patnje.","C":"Zbor se ne plaši Prometejeve reakcije, nego suosjeća gledajući njegovu patnju."},
  "2017_ljeto_B__26": {"A":"Zeus je prikazan kao nepokolebljiv, dakle suprotno od kolebljivoga.","B":"Lukavost nije naglašena Zeusova osobina u ulomku; on je tiranski i samovoljan.","D":"Slatkorječivost se u tekstu veže uz nagovaranje kojem se Prometej opire, a ne uz Zeusovu narav."},
  "2017_ljeto_B__27": {"A":"Prometej ne nudi začaravanje Zeusovih neprijatelja; Zeus ga treba zbog tajne o svrgavanju.","C":"Uvođenje Zeusa u podzemni svijet nije razlog; Zeus će trebati Prometeja zbog tajne.","D":"Izrada oružja nije razlog; Prometej posjeduje tajnu o gubitku Zeusove vlasti."},
  "2017_ljeto_B__28": {"A":"Hamlet ne traži glasnije govorenje, nego odmjerenost i prirodnost.","B":"Gestikulaciju Hamlet upravo odvraća ('ne odveć rukom sjeći zrak').","D":"Afektiranje je ono što Hamlet osuđuje, a ne savjetuje."},
  "2017_ljeto_B__29": {"A":"Poticanje zajedništva nije cilj glume po Hamletu; cilj je biti zrcalo prirodi.","B":"Nasmijavanje publike nije svrha glume; svrha joj je oponašati život.","C":"Pobuđivanje strasti suprotno je Hamletovu zahtjevu za umjerenošću; cilj je vjerno prikazati život."},
  "2017_ljeto_B__30": {"A":"Didaskalija ne izriče Hamletovo upozoravanje na pogreške, nego opisuje njegovu kretnju rukama.","C":"Didaskalija ne govori o privlačenju pozornosti glumaca, nego o fizičkoj demonstraciji.","D":"Didaskalija ne prikazuje gubitak ravnoteže, nego namjerno pokazivanje kretnje."},
  "2017_ljeto_B__31": {"A":"Tercina nije pjesma od tri strofe, nego strofa od tri stiha.","C":"Tercina nije stih od tri sloga, nego trostih.","D":"Tercina nije stih od tri stope, nego strofa (trostih)."},
  "2017_ljeto_B__32": {"B":"Montaigne nije začetnik feljtona, nego eseja.","C":"Polemika nije diskurzivna vrsta koju je utemeljio Montaigne.","D":"Reportaža nije Montaigneova vrsta; on je začetnik eseja."},
  "2017_ljeto_B__33": {"A":"Petrarkin sonet nema jedan katren, nego dva (uz dva terceta).","C":"Sonet nema tri katrena; tri stiha imaju terceti, kojih je također dva.","D":"Sonet nema četiri katrena; ima dva katrena i dva terceta."},
  "2017_ljeto_B__34": {"A":"Anadiploza ponavlja kraj jednoga na početku sljedećeg stiha, čega ovdje nema.","C":"Epifora ponavlja riječ na kraju stihova, dok se ovdje 'Plačnijem srcem' ponavlja na početku.","D":"Simploka spaja anaforu i epiforu, no ovdje je samo početno ponavljanje, dakle anafora."},
  "2017_ljeto_B__35": {"A":"Stihovi o stijenama i vrhu su metafora/poređenje, bez zvukovnog oponašanja.","B":"'Šiba teškim ritmom' dočarava ritam, ali glagoli ne oponašaju zvuk kao u točnom primjeru.","D":"'Sunčani ditiramb' je metafora svjetlosti, bez onomatopejskih glagola."},
  "2017_ljeto_B__36": {"A":"Mahabharata je ep, a ne zbirka svetih knjiga.","B":"Pančatantra je zbirka basni/bajki, a ne svete knjige.","C":"Ramajana je ep, a ne svete knjige indijske književnosti."},
  "2017_ljeto_B__37": {"A":"Pjesma nad pjesmama pripada mudrosnoj/lirskoj književnosti, a ne Povijesnim knjigama.","C":"Psalmi pripadaju mudrosnoj (pjesničkoj) književnosti, a ne Povijesnim knjigama.","D":"Judita je deuterokanonska knjiga, a ne dio kanonskih Povijesnih knjiga u traženom smislu."},
  "2017_ljeto_B__38": {"A":"Edip je junak drugih Sofoklovih tragedija (Kralj Edip), a ne nositelj sukoba u Antigoni.","B":"Hefest je lik iz Okovanog Prometeja, a ne iz Antigone.","D":"Prometej je Eshilov, a ne Sofoklov lik; sukob u Antigoni nosi Kreont."},
  "2017_ljeto_B__39": {"B":"Oponašanje prirode je mimeza, a ne katarza.","C":"Razrješenje dramskog sukoba je rasplet, a ne katarza.","D":"Jedinstvo mjesta, vremena i radnje su tri jedinstva, a ne katarza."},
  "2017_ljeto_B__40": {"A":"Zapis popa Martinca je glagoljički ljetopisni zapis, a ne roman.","C":"Šibenska molitva je srednjovjekovna lirska molitva, a ne roman.","D":"Lucidar je srednjovjekovna enciklopedijska/poučna proza, a ne roman."},
  "2017_ljeto_B__41": {"A":"Ribanje i ribarsko prigovaranje je putopisno-pjesnička poslanica, a ne roman.","B":"Novela od Stanca je komedija (farsa), a ne roman.","D":"Judita je religiozni ep, a ne roman; prvim hrvatskim romanom smatraju se Planine."},
  "2017_ljeto_B__42": {"A":"Byron je romantičarski pjesnik (19. st.), a ne autor baroknog epa.","B":"Ariosto je autor renesansnog epa (Bijesni Roland), a ne baroknog.","C":"Petrarca je pjesnik lirike (Kanconijer), a ne autor baroknog epa."},
  "2017_ljeto_B__43": {"A":"Dugi Nos je negromant iz prologa, ali podjelu na ljude nazbilj i nahvao iznosi Pomet.","C":"Popiva je sluga, ali filozofsku podjelu izgovara Pomet.","D":"Ugo Tudešak je lik bogata stranca, a podjelu ljudi iznosi Pomet."},
  "2017_ljeto_B__44": {"B":"Kanconijer je Petrarkina ljubavna lirika, a ovdje se obraća vodiču kroz Pakao (Vergiliju), što je Dante.","C":"Judita je Marulićev religiozni ep o biblijskoj junakinji, a ne prizor putovanja kroz Pakao.","D":"Smrt Smail-age Čengića tematizira borbu s Turcima, a ne Dantino putovanje uz Vergilija."},
  "2017_ljeto_B__45": {"A":"Osman je Gundulićev barokni ep, ali navedena himna slobodi pripada Dubravci.","C":"Suze sina razmetnoga su Gundulićeva religiozna poema, a ne izvor stihova o slobodi.","D":"Pjesni pokorne kralja Davida su psalamske parafraze, a ne djelo iz kojeg je himna slobodi."},
  "2017_ljeto_B__46": {"B":"Werther nije monološko-asocijativni roman, nego roman u pismima.","C":"Proza u trapericama je suvremena pojava 20. st., a ne forma Wertherova.","D":"Struja svijesti je modernistička tehnika 20. st., a Werther je epistolarni roman 18. st."},
  "2017_ljeto_B__47": {"A":"Urota zrinsko-frankopanska je djelo Eugena Kumičića, a ne Gjalskog.","B":"Čuvaj se senjske ruke napisao je August Šenoa, a ne Gjalski.","D":"Začuđeni svatovi su djelo Augusta Šenoe, a ne Gjalskog."},
  "2017_ljeto_B__48": {"A":"Parnasovci nisu klasicistički pravac; pojavljuju se u 19. st. unutar realizma.","B":"Parnasovci se javljaju kao reakcija na romantizam, a ne kao njegov dio.","D":"Modernizam dolazi kasnije; parnasovci pripadaju razdoblju realizma."},
  "2017_ljeto_B__49": {"B":"A. B. Šimić piše slobodnim stihom ekspresionizma, a navedeni motiv željeznice u daljini Matošev je.","C":"Nazor nije autor ovih stihova; prepoznatljiva slika osamljenosti uz željeznicu pripada Matošu.","D":"Tin Ujević nije autor 'Jesenjega veče'; ti su stihovi Matoševi."},
  "2017_ljeto_B__50": {"A":"Posljednji Stipančići je realistički roman iz suvremenosti, a ne povijesni roman.","B":"Bijeg je realistički roman s temom moderne dezorijentacije, a ne povijesni.","D":"U registraturi je realistički roman suvremene tematike, a ne povijesni."},
  "2017_ljeto_B__51": {"A":"Dadaizam nastaje 1916. u Zürichu, a ne 1909. u Italiji.","B":"Ekspresionizam se razvija u Njemačkoj početkom 20. st., a ne kao talijanski pravac iz 1909.","D":"Nadrealizam nastaje 1924. u Parizu, a ne 1909. u Italiji."},
  "2017_ljeto_B__52": {"A":"Gospoda Glembajevi pripadaju realističkom glembajevskom ciklusu, a ne ekspresionizmu.","C":"Leda je dio glembajevskoga ciklusa (realizam), a ne ekspresionistička drama.","D":"U agoniji pripada glembajevskom ciklusu, a ne ekspresionizmu; ekspresionistička je Kraljevo."},
  "2017_ljeto_B__53": {"A":"Lelek sebra nije Cesarićeva zbirka, nego Ujevićeva.","B":"Tadijanović nije autor Leleka sebra; to je Tin Ujević.","C":"I. G. Kovačić nije autor te zbirke; autor je Tin Ujević."},
  "2017_ljeto_B__54": {"A":"Balade Petrice Kerempuha napisao je Miroslav Krleža, a ne Galović.","B":"Po dragomu kraju je zbirka Dragutina Domjanića, a ne Galovića.","D":"Ognji i rože je zbirka Ivana Gorana Kovačića, a ne Galovića."},
  "2017_ljeto_B__55": {"A":"U Povratku Filipa Latinovicza nema motiva izgladnjivanja radi izbjegavanja mobilizacije.","B":"Prokleta avlija tematizira zatvor i pripovijedanje, a ne izgladnjivanje protiv mobilizacije.","C":"Koraljna vrata su postmodernistički roman zagonetke, bez tog motiva; on pripada Kiklopu."},
  "2017_ljeto_B__56": {"A":"'Izvambračni' je pogrešno; pravilno je 'izvanbračni' (n se ne mijenja u m u pismu).","B":"'Jedamput' je pogrešno; pravilno je 'jedanput'.","D":"'Stramputica' je pogrešno; pravilno je 'stranputica'."},
  "2017_ljeto_B__57": {"A":"Iako je 'nasjesti – nasjedati' pravilno, traži se par s odoljeti; ovaj nije točan odgovor.","C":"'Razumjevati' je pogrešno; pravilno je 'razumijevati'.","D":"'Zapovjedati' je pogrešno; pravilno je 'zapovijedati'."},
  "2017_ljeto_B__58": {"A":"'Ujedinjenih Naroda' je pogrešno; pravilno je 'Ujedinjenih naroda' (samo prva riječ velikim).","B":"'Gorskoga Kotara' je pogrešno; pravilno je 'Gorskoga kotara' (kotar malim slovom).","C":"'Hrvatske Vlade' je pogrešno; pravilno je 'hrvatske vlade' (oba malim slovom)."},
  "2017_ljeto_B__59": {"A":"'Bijelac' je dvosložna riječ (bje-lac), jer 'je' tvori jedan slog, a ne tri.","B":"'Cvijetak' je dvosložan (cvje-tak), a ne trosložan.","D":"'Stijena' je dvosložna (stje-na), a ne trosložna."},
  "2017_ljeto_B__60": {"A":"Jednačenje po mjestu tvorbe mijenja mjesto izgovora (npr. s→š), čega ovdje nema.","C":"Palatalizacija je prijelaz k, g, h u č, ž, š, što nije slučaj u 'iz+pustiti'.","D":"Sibilarizacija je prijelaz k, g, h u c, z, s, što nije provedeno u ovom primjeru."},
  "2017_ljeto_B__61": {"A":"'Ru-ka-vic-a' je pogrešna raščlamba jer rastavlja korijen 'rukav-'.","B":"'Ruk-av-ic-a' je pogrešno jer 'rukav' je jedinstven korijen, ne 'ruk' + 'av'.","C":"'Ruka-vic-a' je pogrešno jer korijen je 'rukav-', a ne 'ruka-'."},
  "2017_ljeto_B__62": {"A":"'Rad-' je korijenski morfem, a ne oblikotvorna osnova cijele riječi 'radnički'.","B":"'Radni-' nije osnova na koju se dodaje gramatički nastavak '-i'.","C":"'Radnič-' nije oblikotvorna osnova; osnova je 'radničk-' (radničk + i)."},
  "2017_ljeto_B__63": {"A":"Genitiv bi odgovarao na 'koga, čega', no 'o bolesniku' uz prijedlog 'o' je lokativ.","B":"Dativ bi bio 'bolesniku' bez prijedloga 'o' (komu, čemu), ali ovdje 'o' traži lokativ.","D":"Instrumental bi glasio 'bolesnikom', dok je oblik 'o bolesniku' lokativ."},
  "2017_ljeto_B__64": {"A":"'Sušiji' je pogrešno; pravilan komparativ je 'suši'.","C":"'Vrućiji' je pogrešno; pravilan komparativ je 'vrući'.","D":"'Zliji' je pogrešno; pravilan supletivni komparativ je 'gori'."},
  "2017_ljeto_B__65": {"A":"'Stilom kojega' je pogrešno; uz instrumental treba 'kojim' (stilom kojim).","B":"'Film kojega' je pogrešno za neživo u akuzativu; treba 'film koji'.","D":"'Roman kojega' je pogrešno jer je 'roman' neživo, pa u akuzativu treba 'koji'."},
  "2017_ljeto_B__66": {"B":"U 'da ti sestre' riječ 'ti' je lična zamjenica (dativ tebi), a ne pokazna.","C":"'Rekao sam ti' sadrži ličnu zamjenicu 'ti' (tebi), a ne pokaznu.","D":"'Da ti je vila' sadrži ličnu zamjenicu 'ti' (tebi), a ne pokaznu."},
  "2017_ljeto_B__67": {"A":"Oblik 'miš' je nominativ, a ne vokativ.","C":"'Mišo' nije pravilan vokativ imenice 'miš'; pravilno je 'miše'.","D":"'Mišu' je dativ/lokativ, a ne vokativ."},
  "2017_ljeto_B__68": {"B":"'Skočiše' je aorist (prošlo svršeno vrijeme), a ne glagolski prilog prošli.","C":"'Skačući' je glagolski prilog sadašnji od 'skakati', a ne prošli od 'skočiti'.","D":"'Skakaše' je imperfekt, a ne glagolski prilog prošli."},
  "2017_ljeto_B__69": {"A":"'Neku' je neodređena zamjenica, a ne prijedlog.","B":"'Posve' je prilog (mjere/stupnja), a ne prijedlog.","C":"'Kao' je veznik (poredbeni), a ne prijedlog."},
  "2017_ljeto_B__70": {"A":"'Pobjeći pred požarom' je prijedložna (rektivna) sintagma, a ne sročna.","B":"'Zaustavljanje požara' je rektivna sintagma (genitivna dopuna), a ne sročna.","C":"'Bojati se požara' je rektivna sintagma, jer glagol traži genitiv, a ne slaganje u rodu, broju i padežu."},
  "2017_ljeto_B__71": {"A":"U toj rečenici subjekt je implicitno 'mi' ('možemo'), a podcrtana riječ nije subjekt.","C":"Subjekt je 'djevojke', a ne podcrtana riječ u toj rečenici.","D":"Subjekt je 'oni', a ne podcrtana riječ; 'sila učenika' subjekt je u rečenici B."},
  "2017_ljeto_B__72": {"A":"Zanaglasnica 'su' trebala bi doći iza prve naglašene riječi, pa je položaj pogrešan.","B":"Zanaglasnica 'mi' (i 'se') stoji na pogrešnu mjestu, ne iza prve naglašene riječi.","C":"Zanaglasnica 'se' nije na pravilnu položaju (iza prve naglašene riječi)."},
  "2017_ljeto_B__73": {"B":"'Da bi se odrekao' je namjerna (ili izrična) rečenica, a ne atributna.","C":"'Iako se odrekao' je dopusna rečenica, a ne atributna.","D":"'Jer se odrekao' je uzročna rečenica, a ne atributna."},
  "2017_ljeto_B__74": {"A":"Dvije surečenice premalo; uz glavnu postoje još odnosna ('koju je izazvala') i izrična ('da pobijedi'), dakle tri.","C":"Četiri surečenice previše; rečenica ima tri surečenice.","D":"Pet surečenica previše; surečenica je tri."},
  "2017_ljeto_B__75": {"A":"'Slatko voće' nije antonim suhom voću; suprotnost suhom je svježe.","C":"'Ukusno voće' nije antonim suhom; antonimni je par suho – svježe.","D":"'Zrelo voće' nije antonim suhom voću; antonim je svježe."},
  "2017_ljeto_B__76": {"B":"Posuđenice iz latinskoga jesu latinizmi, a ne galicizmi.","C":"Posuđenice iz portugalskoga nisu galicizmi; galicizmi su iz francuskoga.","D":"Posuđenice iz španjolskoga su hispanizmi, a ne galicizmi."},
  "2017_ljeto_B__77": {"A":"'Držati uzde u svojim rukama' znači imati vlast/upravljanje, a ne raditi u svoju korist.","B":"'Čistiti pred svojim pragom' znači brinuti o vlastitim propustima, a ne raditi u svoju korist.","D":"'Nositi svoj križ' znači trpjeti teškoće, a ne raditi u svoju korist."},
  "2017_ljeto_B__78": {"A":"Arhaizmi su zastarjele riječi koje imaju suvremenu zamjenu, dok 'centurija' imenuje povijesnu pojavu (historizam).","C":"Neologizmi su nove riječi, a 'centurija' označava povijesni pojam (historizam).","D":"Pomodnice su pomodne, kratkotrajne riječi, a 'centurija' je naziv za nestalu povijesnu pojavu (historizam)."},
  "2017_ljeto_B__79": {"A":"Pozitiv i komparativ su različiti stupnjevi pridjeva, a ne sinonimi.","B":"Monosemija i polisemija su suprotni pojmovi (jednoznačnost i višeznačnost), a ne sinonimi.","D":"Fonem i alofon su različiti pojmovi (jedinica i njezina ostvarba), a ne sinonimi."},
  "2017_ljeto_B__80": {"B":"Vrančić nije uredio prvu hrvatsku enciklopediju, nego je sastavio prvi tiskani rječnik s hrvatskim.","C":"Prvu hrvatsku gramatiku napisao je Bartol Kašić, a ne Vrančić.","D":"Prvi hrvatski pravopis nije Vrančićevo djelo; on je autor prvog rječnika s hrvatskim."},

  // 2018_jesen_A
  "2018_jesen_A__1": {"A":"Pjesma ne govori o nejasnim Ljerkinim osjećajima, nego o vremenu koje treba proći do njezine zrelosti.","B":"Stih ne uspoređuje ples i čitanje, nego 'deset karnevala' označava niz godina do odrastanja.","C":"Nije riječ o iščekivanju prvoga plesa, nego o dugom razdoblju (deset godina) do njezine zrelosti."},
  "2018_jesen_A__2": {"B":"Prividne i istinske vrijednosti nisu temeljna opreka pjesme; suprotstavljena je djetinja nevinost i iskustvo odraslosti.","C":"Pjesma ne suprotstavlja sadašnjost i sjećanja, nego svijet djeteta i svijet odraslih.","D":"Opreka zbilje i fantastike nije prisutna; riječ je o opreci mladosti i odraslosti."},
  "2018_jesen_A__3": {"B":"U pjesmi nema spomena da je lirski subjekt organizirao bal; naklonost iskazuje samom pjesmom.","C":"Odlazak u cirkus nije spomenut; naklonost je iskazana pjesmom posvećenom Ljerki.","D":"Lirski subjekt nije poklonio lutku; naprotiv, sam naslov govori da joj daruje pjesmu 'mjesto igračke'."},
  "2018_jesen_A__4": {"A":"Nevrijeme na moru samo je slika (poredba), a ne tema pjesme koja govori o nemiru srca.","B":"Pjesma ne tematizira svijest o smrtnosti, nego nemir i strast srca.","C":"Lutanje prirodom nije tema; more i bura služe kao metafore unutarnjega nemira."},
  "2018_jesen_A__5": {"B":"Bura prikazuje unutarnji nemir oko srca, ali metafora samoga srca jest klisura.","C":"More predstavlja život i strasti, a ne srce; srce je usporedba s klisurom.","D":"Lađa je metafora života ('življenja lađe'), a srce je izrijekom nazvano klisurom."},
  "2018_jesen_A__6": {"A":"Nerazumijevanje okoline nije spomenuto; jad donosi sukob razuma i osjećaja.","C":"Želja za promjenom nije izvor jada; jad nastaje iz borbe razbora i srca.","D":"Strah od brodoloma nije razlog; jad donosi 'boj' razuma s osjećajima."},
  "2018_jesen_A__7": {"A":"U tekstu nema spomena da je Odisej prinio žrtvu Posejdonu da bi ga umirio.","B":"Posejdonov odlazak u Etiopiju samo je prigoda za skup bogova, a ne kraj njegove srdžbe.","C":"Zeus u ulomku ne kori Posejdona; srdžba traje sve dok se Odisej ne vrati kući."},
  "2018_jesen_A__8": {"A":"Hermija (Hermo) nije bog sunca, nego glasnik bogova.","C":"Posejdon je bog mora, a ne sunca.","D":"Zeus je vrhovni bog i 'otac ljudi i bogova', a ne bog izlaska sunca."},
  "2018_jesen_A__9": {"A":"Zeus ne govori da ljudima treba pomoć bogova, nego da ljudi krivnju za zlo svaljuju na bogove.","B":"Zeus ne kaže da se ljudi boje upozorenja, nego da bogove optužuju za zlo.","C":"U Zeusovim riječima nema govora o ljudskoj želji za osvetom bogovima."},
  "2018_jesen_A__10": {"B":"Lovro se nije ugodno osjećao u građanskoj odjeći; finoća na njemu djeluje 'nespretno'.","C":"Iz odjeće se ne zaključuje pripadnost visokim slojevima, nego nesklad odjeće i osobe.","D":"Odjeća ne odaje ponos, nego nesklad između urednosti i njezine nespretnosti."},
  "2018_jesen_A__11": {"A":"Strastvenost se ne zaključuje iz odnosa s ljudima, nego iz neobičnoga sjaja oka.","B":"Pokreti tijela nisu temelj zaključka; strastvenost odaje sjaj njegova oka.","C":"Crte lica opisane su zasebno, ali strastvenost se prepoznaje po pogledu."},
  "2018_jesen_A__12": {"A":"Lovro nije bio nerazumljiv; govorio je 'svečano, kratko poput epigrama', dakle dojmljivo.","B":"Nije se uključivao u razgovore o nevažnim temama; ironijom je raspravu znao preokrenuti.","C":"Govor nije isticao njegovu energičnost, nego govorničku vještinu i duhovitost."},
  "2018_jesen_A__13": {"B":"Léonov odnos prema profesorima samo je jedan detalj, a ne tema teksta o mijeni karaktera.","C":"Tekst ne govori o nastojanju da se istakne u pariškom društvu, nego o ovisnosti karaktera o sredini.","D":"Léon ne pokušava zaboraviti Emmu; strast prema njoj iznova se budi."},
  "2018_jesen_A__14": {"A":"Plašljivost (kukavština) spominje se kao osobina, ali se Léon isticao vanjštinom.","B":"Léon nije bio rastrošan; ne bi prerano potrošio novac predviđen za tromjesečje.","C":"Učenost nije ono čime se isticao; bio je 'među najpristalijim studentima' po izgledu."},
  "2018_jesen_A__15": {"A":"Uspomena na Emmu nije uspoređena sa zlatnim plodom; to je 'neizvjesno obećanje' budućnosti.","C":"Nije riječ o izgubljenoj nadi, nego o neizvjesnom obećanju koje lebdi 'poput zlatnoga ploda'.","D":"Nove žudnje nisu predmet usporedbe; zlatni plod označava neizvjesno buduće obećanje."},
  "2018_jesen_A__16": {"A":"Kupanje u moru dio je prizora iz djetinjstva, ali prisjećanje pokreće promatranje svjetla na stropu.","C":"Mirisno uzglavlje pojedinost je sjećanja, no povod prisjećanju jest odraz svjetla na stropu.","D":"Ljetno popodne okvir je sjećanja, ali okidač je sama slika svjetla na stropu."},
  "2018_jesen_A__17": {"A":"Motiv ljeta nije personificiran; personificirano je more koje 'diše'.","B":"Motiv sunca nije oživljen personifikacijom; ono se javlja u opisu mirisa, a diše more.","C":"Motiv stropa nije personificiran; personifikacija je vezana uz more."},
  "2018_jesen_A__18": {"A":"Toplina ljetnoga dana ne čini sliku nemirnom; nemir izaziva odraz morske vode.","B":"Tragovi soli na tijelu samo su pojedinost, a ne uzrok nemira slike.","C":"Mnoštvo ljudi nije razlog nemira; sliku uznemiruje treperenje odraza mora."},
  "2018_jesen_A__19": {"A":"Tajib-aga nije poslanik; on prevodi vezirove riječi, dakle prevoditelj je.","C":"On nije ratnik; njegova je uloga prevođenje s turskoga na njemački.","D":"Tajib-aga nije zlatar; bavi se prevođenjem govora."},
  "2018_jesen_A__20": {"A":"Razlog nije to što hrvatski nije diplomatski jezik, nego Mehmedovo izbjegavanje prisnosti.","C":"Tajib-aga prevodi pa bi razumio; razlog je u izbjegavanju prisnosti koja bi značila slabost.","D":"Nije riječ o Mehmedovu slabom znanju hrvatskoga, nego o svjesnom čuvanju distancije."},
  "2018_jesen_A__21": {"A":"Tekst kaže da je on 'bez grižnje savjesti', dakle ne muči ga savjest.","B":"Isprekidan govor pripisuje se Mehmedu ('istrzan i hrapav'), a ne Tajib-agi koji govori meko i tečno.","C":"Tajib-aga nije došao sklopiti mir; on je prevoditelj koji je promijenio identitet."},
  "2018_jesen_A__22": {"B":"Najbolje stado nije nagrada nadmetanja; nagrada je biti glumac (pozvan) na svadbi.","C":"Naklonost boga Lera nije cilj natjecanja, nego pravo nastupa na piru.","D":"Ne natječu se da ožene Ljubicu, nego da budu izabrani za glumca na piru."},
  "2018_jesen_A__23": {"A":"Rakle ne daruje Divjaka da je nasmije pjesmom, nego da on opjeva njezinu ljepotu.","B":"Dar nije zahvala na lijepim riječima, nego poticaj da opjeva sjaj njezinih očiju.","C":"Cilj darivanja nije izazvati Ljubičinu ljubomoru, nego da Divjak opjeva Raklinu ljepotu."},
  "2018_jesen_A__24": {"A":"Podcrtana riječ ne odnosi se na Divjaka, nego na glas koji privlači odjeke iz planina.","C":"Riječ se ne odnosi na slavica, nego na slatki glas lirskoga govornika.","D":"Ne odnosi se na Lera, nego na glas koji prema sebi 'doteku' odjeci."},
  "2018_jesen_A__25": {"A":"Giga ne izaziva Marka namjerno; ona se trudi obraniti vezu i vjeruje u zajednički život.","B":"Giga reagira na Markovo ruganje; tužno i rezignirano mu odgovara, ne ostaje ravnodušna.","D":"Giga jest iznenađena Markovim ponašanjem ('na ovako nešto nisam pomišljala nikad')."},
  "2018_jesen_A__26": {"A":"Rečenica nije nostalgično sjećanje, nego ironična optužba da Giga uvjerljivo laže.","B":"Marko nije prihvatio njezine argumente; ironično joj predbacuje vještinu govora.","D":"Riječi ga nisu ganule; ironično ih odbacuje kao puko 'dobro govorenje'."},
  "2018_jesen_A__27": {"A":"Gigin nestanak u Galiciji nije Markov dokaz nevjere; dokazom smatra buket s pismom.","C":"Iskaz svjedoka nije naveden kao Markov dokaz; on gradi 'toranj nevjere' na buketu i pismu.","D":"Giginu šutnju Marko ne uzima kao dokaz; presudnim drži buket s pismom."},
  "2018_jesen_A__28": {"A":"Rečenica ne tvrdi da se čovjek nikad neće osloboditi životinjskoga, nego da ga je govor uzdignuo u stvaratelja.","C":"Nije riječ o tome da sva bića komuniciraju, nego o presudnoj ulozi riječi za civilizaciju.","D":"Ne govori se o vječnoj težnji savršenstvu, nego o jeziku kao temelju ljudskih tvorevina."},
  "2018_jesen_A__29": {"A":"Usporedba riječi s lukovima duge nije paradoksalna; nedostaje suprotnost spajanja i razdvajanja.","C":"Slika riječi kao 'lelujave sjenke' nije paradoks, nego samo poredba o trajnosti riječi uz čovjeka.","D":"Tvrdnja o odvajanju od četveronožaca nije paradoksalna, nego prikazuje učinak govora."},
  "2018_jesen_A__30": {"A":"Govor nije za prirodu spoj sa zvijezdama; priroda ga doživljava kao nerazumljiv jauk.","C":"Za prirodu govor nije pjesma, nego nerazumljiv jauk 'blijede životinje'.","D":"Govor za prirodu nije smijeh, nego nerazumljiv jauk."},
  "2018_jesen_A__31": {"B":"Memoari nisu dramski rod; nemaju dijaloga ni scenskog izvođenja, nego su autobiografska proza.","C":"Memoari nisu epski rod (fikcionalna pripovjedna umjetnost), nego diskurzivna, činjenična proza.","D":"Memoari nisu lirika; ne izražavaju trenutna stanja u stihu, nego pripovijedaju o doživljenom."},
  "2018_jesen_A__32": {"A":"Ovaj stih dio je radnje (Laokoontova upozorenja), a ne zaziv muze, pa nije invokacija.","B":"Stih opisuje prodor Danajaca u dvor, dakle pripovjedni je iskaz, a ne invokacija.","D":"Opis spilje i hridi je deskripcija prizora, a ne zazivanje muze."},
  "2018_jesen_A__33": {"B":"Ovi stihovi imaju samo završnu rimu (biva/nahodiva), a nema unutarnje rime u sredini stiha.","C":"Stihovi su rimovani na kraju (odurava/spoznava), ali bez dvostruke (unutarnje) rime.","D":"Ovi stihovi nemaju unutarnju srednju rimu pa nisu dvostrukorimovani dvanaesterci."},
  "2018_jesen_A__34": {"A":"'Dva pejzaža' nije oksimoron; nema spoja proturječnih pojmova.","B":"'Jesenje veče' samo je opis doba i godišnjega doba, bez proturječja, dakle nije oksimoron.","D":"'Zvonimirova lađa' nema unutarnje proturječje pa nije oksimoron."},
  "2018_jesen_A__35": {"A":"'Olovne i teške snove' jest metafora/epitet, ali ne miješa različita osjetila pa nije sinestezija.","B":"'Monotona zvona bona' je personifikacija/epitet, a ne miješanje osjetilnih dojmova.","D":"'Mrke vrbe', 'crnim vranama' samo su vizualni epiteti, bez spoja dvaju osjetila."},
  "2018_jesen_A__36": {"B":"Anakreont je pjesnik vina i ljubavi, a autor pjesme 'Lađi' jest Alkej.","C":"Pindar je pisac pobjedničkih oda (epinikija), a ne pjesme 'Lađi'.","D":"Sapfo je pjesnikinja ljubavne lirike s Lezba, a 'Lađu' je napisao Alkej."},
  "2018_jesen_A__37": {"A":"Aristofan je grčki komediograf, ne pripada rimskoj književnosti.","B":"Eshil je grčki tragičar, a ne rimski književnik.","C":"Euripid je grčki tragičar, dok je Plaut rimski komediograf."},
  "2018_jesen_A__38": {"A":"Bašćanska ploča ne spominje kneza Kosmata u vezi s gradnjom crkve.","B":"Odnose vinodolskih općina uređuje Vinodolski zakonik, a ne Bašćanska ploča.","D":"Zapis popa Martinca poseban je glagoljski tekst i ne navodi se u Bašćanskoj ploči."},
  "2018_jesen_A__39": {"A":"Danteova 'Božanstvena komedija' je spjev u tercinama i ne nosi naziv 'rasute rime'.","B":"Boccacciov 'Decameron' je zbirka novela u prozi, a ne zbirka 'rasutih rima'.","C":"Shakespeareovi 'Soneti' nisu poznati pod sintagmom 'rasute rime', za razliku od Petrarcina kanconijera."},
  "2018_jesen_A__40": {"A":"'Suze sina razmetnoga' (Gundulić) religiozni je spjev, a ne djelo o putu pastira Zorana.","B":"'Plandovanja' (Gundulić) zbirka su lirskih pjesama, a ne pripovijest o pastiru Zoranu.","C":"'Dubravka' (Gundulić) pastoralna je drama, a put pastira Zorana opisuju 'Planine'."},
  "2018_jesen_A__41": {"B":"Maro Marojev mladi je rasipnik u radnji, a navedeni prolog izgovara Dugi Nos.","C":"Pomet je dovitljivi sluga, ali navedeni metateatarski prolog izgovara Dugi Nos.","D":"Popiva je Marov sluga, a citirani prolog pripada negromantu Dugom Nosu."},
  "2018_jesen_A__42": {"A":"Eshilov 'Okovani Prometej' nema 'predstave u predstavi' s otrovom u uho, nego priču o Prometeju.","B":"Goldonijeva 'Gostioničarka Mirandolina' komedija je, bez prizora trovanja kralja u uho.","D":"Sofoklov 'Kralj Edip' nema metadramskog prizora s trovanjem; opisani je prizor iz 'Hamleta'."},
  "2018_jesen_A__43": {"A":"Zahtjev za objektivnošću, strogošću oblika i jednostavnošću odlika je klasicizma, ne baroka.","B":"Povjerenje u razum i razumijevanje prirode obilježje je prosvjetiteljstva, a ne baroka.","D":"Obnavljanje antičkih zasada značajka je humanizma i renesanse, ne baroka."},
  "2018_jesen_A__44": {"B":"'Don Quijote' (Cervantes) izruguje viteške romane, a ne idealističku filozofiju optimizma.","C":"'Gargantua i Pantagruel' (Rabelais) renesansna je satira, a ne podsmijeh idealističkoj filozofiji.","D":"'Patnje mladog Werthera' (Goethe) sentimentalni je roman, a ne ruganje idealizmu."},
  "2018_jesen_A__45": {"A":"Krsto Brodnjak nije lik 'Smrti Smail-age Čengića'.","B":"Latifaga Karađoz lik je iz Andrićeve 'Proklete avlije', ne iz Mažuranićeva spjeva.","C":"Miloš Radak nije lik Mažuranićeva spjeva; junak osvete jest Novica Cerović."},
  "2018_jesen_A__46": {"B":"Dante Alighieri autor je 'Božanstvene komedije', a ne ciklusa 'Ljudska komedija'.","C":"Émile Zola autor je ciklusa 'Rougon-Macquart', a ne 'Ljudske komedije'.","D":"Voltaire je pisac 'Candidea', dok je 'Ljudsku komediju' napisao Balzac."},
  "2018_jesen_A__47": {"A":"Ante Kovačić pisac je 'U registraturi', no programatski članak 'Naša književnost' (1865.) napisao je Šenoa.","C":"Eugen Kumičić zastupnik je naturalizma, ali navedeni članak iz 1865. pripada Šenoi.","D":"Josip Kozarac realist je slavonske tematike, a programski članak 'Naša književnost' napisao je Šenoa."},
  "2018_jesen_A__48": {"B":"Veličanje općeljudskih vrijednosti (čast, hrabrost) nije obilježje naturalizma, nego npr. klasicizma/romantizma.","C":"Naturalizam ne prikazuje samo visoke slojeve; usmjeren je upravo na niže i bijedne slojeve.","D":"U naturalizmu prevladava roman, a ne lirska pjesma."},
  "2018_jesen_A__49": {"A":"Pripadnik patricijata koji zabludu prenosi na sina nije Andrijašević iz 'Bijega'.","B":"Pisar seoskoga podrijetla koji propada u gradu opis je Ivice Kičmanovića ('U registraturi'), ne junaka 'Bijega'.","D":"Slavonski bećar žedan užitaka lik je iz Kozarčevih djela, a ne junak 'Bijega'."},
  "2018_jesen_A__50": {"A":"Praška i bečka skupina ne pripadaju romantizmu, nego hrvatskoj moderni.","B":"Te skupine nisu obilježje realizma, nego razdoblja moderne.","D":"Praška i bečka skupina nisu ekspresionistički naraštaj, nego pripadnici moderne."},
  "2018_jesen_A__51": {"A":"'Bez trećega' (Begović) psihološka je drama, a ne ekspresionistička.","B":"'Ekvinocij' (Vojnović) realistička je drama, a ne ekspresionistička.","D":"'Predstava Hamleta...' (Brešan) suvremena je groteska, a ne ekspresionistička drama."},
  "2018_jesen_A__52": {"A":"A. B. Šimić uređivao je 'Vijavicu' i 'Juriš'? Ne — te je časopise uređivao Krleža; Šimić je uređivao 'Vijavicu' u drugom smislu pa nije točan odgovor za oba.","B":"Ivo Andrić nije uređivao časopise 'Vijavica' i 'Juriš'.","D":"Ulderiko Donadini uređivao je 'Kokot', a ne 'Vijavicu' i 'Juriš'."},
  "2018_jesen_A__53": {"A":"A. G. Matoš nije autor soneta 'Oproštaj' kojim se najavljuju nove struje; to je Ujevićev sonet.","B":"Dobriša Cesarić nije autor soneta 'Oproštaj'.","C":"Dragutin Tadijanović nije autor 'Oproštaja'; taj sonet napisao je Tin Ujević."},
  "2018_jesen_A__54": {"A":"'Combray' (Proust) dio je modernističkoga ciklusa, a ne proze u trapericama.","C":"'Preobražaj' (Kafka) modernistička je novela, a ne proza u trapericama.","D":"'Stranac' (Camus) egzistencijalistički je roman, a ne proza u trapericama."},
  "2018_jesen_A__55": {"A":"Ivan Slamnig nije autor navedenih stihova.","B":"Josip Pupačić nije autor stihova 'Majstore, ugasi svijeću'.","C":"Jure Kaštelan nije autor navedenih stihova; napisao ih je Slavko Mihalić."},
  "2018_jesen_A__56": {"A":"'Lijekovima' nije sporno, ali traženi je primjer 'bijegovima'; ovdje pravopisni izazov nije ispunjen kao u točnom.","C":"'Mijehovima' bilo bi pravilno, no točan odgovor zadatka jest 'bijegovima'.","D":"'Spijevovima' nije pravilno; ispravno je 'spjevovima' (kratki jat)."},
  "2018_jesen_A__57": {"A":"'Činbenik' nije pravilno; zbog jednačenja po mjestu tvorbe piše se 'čimbenik'.","C":"'Obranbeni' nije pravilno; ispravno je 'obrambeni'.","D":"'Stanbeni' nije pravilno; ispravno je 'stambeni'."},
  "2018_jesen_A__58": {"A":"'Hrvatske Akademije Znanosti i Umjetnosti' netočno je; treba 'Hrvatske akademije znanosti i umjetnosti'.","B":"'Austro-Ugarska Monarhija' i 'Nagodbom' pogrešno su pisani velikim slovom u svim sastavnicama.","C":"'Južnih slavena' netočno je; treba 'južnih Slavena' te malo 'hrvatski narodni preporod'."},
  "2018_jesen_A__59": {"B":"Nedostaje zarez: 'Sigurno ste to znali, samo se niste usudili reći' (nezavisne surečenice).","C":"Nedostaje zarez iza zavisne surečenice: 'Budući da su pobijedili, mogli su...'.","D":"Pogrešno je interpungirano; treba 'Joj, smilujte se, molim vas!'."},
  "2018_jesen_A__60": {"A":"U riječi nije dva bezvučna glasa; uz s i t valja uvrstiti još jedan pa ih je tri.","C":"Bezvučnih glasova nije četiri; u 'osvijetljen' ih je tri.","D":"Pet bezvučnih glasova previše je; točan je broj tri."},
  "2018_jesen_A__61": {"A":"U 'skučen' nema palatalizacije (k ne prelazi u č pred prednjim samoglasnikom kao posljedica te glasovne promjene ovdje).","C":"U 'jače'/'čamcu' nije provedena palatalizacija, nego su to drukčije pojave/postojeći glasovi.","D":"U 'žlice' nije provedena palatalizacija; palatalizacija je u 'hrašće' (hrast + je)."},
  "2018_jesen_A__62": {"A":"'Osmišljàvati' (kratkouzlazni) nije ispravan naglasak; pravilan je dugouzlazni.","B":"'Osmišljȁvati' (kratkosilazni) nije ispravno; treba dugouzlazni naglasak.","D":"'Osmišljâvati' (dugosilazni) nije ispravno; pravilan je dugouzlazni naglasak."},
  "2018_jesen_A__63": {"A":"'u-či-te-lji-ca' je slogovna, a ne morfemska raščlamba.","C":"'učitelj-ic-a' netočno spaja korijen i spojnik; korijen je 'uč-', a '-i-' i '-telj-' su zasebni morfemi.","D":"'uči-telj-ica' pogrešno odvaja morfeme; ispravno je uč-i-telj-ic-a."},
  "2018_jesen_A__64": {"A":"'u-' je tvorbeni (prefiksalni) morfem, a ne gramatički.","B":"'-jen-' je tvorbeni (sufiksalni) morfem, a ne gramatički nastavak.","C":"'-ost-' je tvorbeni sufiks, a gramatički je morfem nulti nastavak (-Ø)."},
  "2018_jesen_A__65": {"A":"'po stolu' je lokativ (mjesto kretanja), a ne dativ.","B":"'na stolu' je lokativ (mjesto), a ne dativ.","C":"'o stolu' je lokativ (predmet govora), a ne dativ."},
  "2018_jesen_A__66": {"A":"'Ljeniviji' nije pravilan komparativ od 'lijen'.","B":"'Lijeniji' nije pravilno; jat se krati pa je ispravno 'ljeniji'.","C":"'Ljenlji' nije pravilan oblik komparativa."},
  "2018_jesen_A__67": {"A":"'Njegovu' je posvojna zamjenica, ali se odnosi na 'kćer' (ž. r.), pa nije muški rod.","C":"'Njihova' je u ženskom rodu (slaže se s 'odluka').","D":"'Naše' je u srednjem rodu (slaže se s 'rješenje')."},
  "2018_jesen_A__68": {"A":"'Bila bi' je kondicional prvi (sadašnja pogodba), a ne drugi.","C":"'Došli bismo' je kondicional prvi, a ne drugi.","D":"'Ako budete čitali' futur je drugi, a ne kondicional."},
  "2018_jesen_A__69": {"A":"Četiri je premalo; prijedloga u rečenici ima pet (s, od, u, na, na).","C":"Šest je previše; prijedloga je pet.","D":"Sedam je previše; rečenica sadrži pet prijedloga."},
  "2018_jesen_A__70": {"A":"'Plesati pod zvijezdama' je nesročna (priložna) sintagma, glagol + prijedložni izraz.","B":"'Dvorana za ples' je nesročna sintagma s prijedložnim atributom.","D":"'Plesati tango' je nesročna sintagma (glagol + objekt), a ne sročna."},
  "2018_jesen_A__71": {"A":"'Mi' je neizravni objekt (dativ), a ne izravni.","B":"'Misao' je subjekt rečenice, a ne objekt.","C":"'Trenutak' je dio priložne oznake ('ni na trenutak'), a ne izravni objekt."},
  "2018_jesen_A__72": {"B":"Četiri je previše; rečenica ima tri surečenice.","C":"Pet je previše; surečenica je tri.","D":"Šest je previše; složena rečenica sadrži tri surečenice."},
  "2018_jesen_A__73": {"B":"'Kamo bi pogledala' je mjesna (priložna) zavisna rečenica, a ne predikatna.","C":"'Kada je tko na redu' je subjektna rečenica (znalo se što), a ne predikatna.","D":"'Kako su došli pred školu' je objektna rečenica (vidjeli su što), a ne predikatna."},
  "2018_jesen_A__74": {"B":"'Radi tvoje pogreške' nije gramatički točno; uzrok se izriče prijedlogom 'zbog'.","C":"'Vožnja s vlakom' nije pravilno; treba 'vožnja vlakom' (besprijedložni instrumental).","D":"'Kod majke na ručak' nepravilno je za smjer; treba 'k majci / majci na ručak'."},
  "2018_jesen_A__75": {"A":"'Onomastika – imenoslovlje' su istoznačnice (sinonimi), a ne nad/podređeni pojmovi.","B":"'Deklinacija – konjugacija' su supojmovi (kohiponimi), a ne hiperonim i hiponim.","D":"'Fonem – morfem' su jezične jedinice u supojmovnom odnosu, a ne hiperonim i hiponim."},
  "2018_jesen_A__76": {"B":"'Mađar' je etnik (naziv pripadnika naroda), a ne egzonim.","C":"'Pariški' je posvojni pridjev (ktetik), a ne egzonim.","D":"'Sava' je domaći hidronim, a ne egzonim (strano ime u hrvatskom obliku)."},
  "2018_jesen_A__77": {"A":"'Velikolučanin' nije pravilan etnik od 'Vela Luka'.","B":"'Velelučanin' nije pravilan etnik; ispravno je 'Velolučanin'.","C":"'Velilučanin' nije pravilan etnik od 'Vela Luka'."},
  "2018_jesen_A__78": {"A":"'Beznadan' je nastao prefiksalno-sufiksalnom tvorbom (bez- + nad + -an), a ne samo sufiksalnom.","C":"'Podzemlje' je nastalo prefiksalno-sufiksalnom tvorbom (pod- + zeml + -je), a ne sufiksalnom.","D":"'Prajezični' je tvoren prefiksom i sufiksom (pra- + jezik + -ni), a ne samo sufiksalno."},
  "2018_jesen_A__79": {"B":"'Postaviti vuka za pastira' znači povjeriti nekomu ono čemu će nauditi, nije suprotno svađalaštvu.","C":"'Od muhe praviti slona' znači pretjerivati, nije antonim frazemu o nesložnosti.","D":"'I vuk sit i koze cijele' znači zadovoljiti sve strane, a ne suprotnost svađi."},
  "2018_jesen_A__80": {"A":"'Poljički statut' izvorno je pisan glagoljicom (i bosančicom), ne latinicom.","C":"'Vinodolski zakonik' napisan je glagoljicom, a ne latinicom.","D":"'Zapis popa Martinca' glagoljski je tekst, a ne latinički."},

  // 2018_jesen_B
  "2018_jesen_B__1": {"A":"Lirski subjekt ne predviđa budućnost na temelju pjesama koje je pročitao, nego na temelju vlastitoga proživljenog života.","C":"Nije riječ o predosjećaju, nego o spoznaji da se ponavlja ono što je sam doživio ('što nije bilo za moga vijeka').","D":"Snovi nisu izvor njegova znanja; on se oslanja na osobno iskustvo života i ljubavi."},
  "2018_jesen_B__2": {"B":"Ljubav u stihovima nije prikazana kao nedostižna, nego kao stvarna i prepoznatljiva kroz pjesništvo svih vremena.","C":"Prolaznost mladosti nije tema ovih stihova; naglasak je na trajnosti i svevremenosti pjesničkoga doživljaja.","D":"Stihovi ne govore o neostvarivim željama, nego o tome da pjesnikova ljubavna iskustva i dalje žive i u drugima."},
  "2018_jesen_B__3": {"A":"Pjesma nije anakreontska jer ne slavi vino, ljubavni hedonizam i razuzdano uživanje, nego pripovijeda mirnu buduću scenu.","B":"Pjesma nije pisana u obliku dijaloga; prevladava pripovijedanje, a izravni govor je tek jedan kratak umetak.","D":"Premda ima idiličnih slika, temeljno obilježje pjesme jest narativnost, a ne idiličnost kao žanrovska odrednica."},
  "2018_jesen_B__4": {"A":"Putnik u šumi ne susreće lijepu ženu; on je sam, bez konja i druga, izgubljen za oluje.","B":"Putnik ne gubi blago, nego put; 'zabludi sred luga' znači da se izgubio u šumi.","C":"U pjesmi nema pljačke; putnikova nevolja je zalutalost i strah u olujnoj noći."},
  "2018_jesen_B__5": {"A":"U prvoj se strofi opisuje zalutali putnik, a ne lirsko ja koje govori o sebi.","B":"U drugoj strofi prikazana je putnikova tuga i pojava duge, bez izravnoga isticanja lirskoga subjekta.","C":"U trećoj se strofi nastavlja putnikov doživljaj olakšanja; lirsko ja izbija tek u završnom tercetu."},
  "2018_jesen_B__6": {"A":"Ni duga ni pogled na dragu ne pozivaju na putovanje, nego donose smirenje i nestanak jada.","C":"Nemir prethodi i dugi i pogledu; oni ga upravo dokidaju, a ne stvaraju.","D":"Strah je ono što obje pojave uklanjaju, a ne izazivaju."},
  "2018_jesen_B__7": {"A":"U ulomku nema spomena odbjegloga konja; Asan aga je u šatoru jer 'boluje u ranami ljutim'.","B":"Razlog boravka u šatoru nije svađa sa ženom, nego liječenje teških rana.","C":"Asan aga ne čeka Pintorović bega; beg dolazi tek poslije po sestru."},
  "2018_jesen_B__8": {"B":"Asanaginica se ne ubija zbog zabrane posjeta; htjela je skočiti čuvši topot, misleći da stiže muž.","C":"Nije se uplašila bega, nego je tek poslije saznala da je riječ o ujaku ('već daidža Pintorović beže').","D":"Oduzimanje djece nije razlog ovomu očaju; ona reagira na zvuk konja vjerujući da dolazi Asan aga."},
  "2018_jesen_B__9": {"B":"Brat ne dolazi radi pomirbe sa svekrvom, nego donosi razvodnicu i odvodi sestru majci.","C":"Brat je ne vodi Asan agi, nego upravo natrag u roditeljski dom nakon razvoda.","D":"Brat je ne sprječava u bijegu, nego provodi rastavu i odvodi je u rod."},
  "2018_jesen_B__10": {"A":"Strah ne potječe od bojazni da će se miss Maud probuditi, nego od činjenice prvoga samostalnog izlaska.","B":"Uzrok straha nije sjedenje s neznancem, nego neuobičajenost prvoga izlaska u svijet.","D":"U ulomku nema spotaknuća o Solusa; djevojka kaže da se uplašila jer je prvi put sama izišla."},
  "2018_jesen_B__11": {"A":"Rečenica ne govori o govoru, nego o ljepoti lica i stasa kojom djevojka nadmašuje druge.","B":"Nije riječ o očaravanju 'svih', nego o tome da ona ljepotom nadvisuje sve ostale djevojke.","D":"Usporedba je s drugim djevojkama, a ne s prirodom; ona ih sve nadmašuje 'licem i uzrastom'."},
  "2018_jesen_B__12": {"B":"Gustativna (okusna) slika ne odgovara motivu Gorgone; 'žuborna' upućuje na zvuk, a ne na okus.","C":"Olfaktivna (mirisna) slika nije povezana s Gorgonom; pridjev 'žuborna' izaziva slušni dojam.","D":"Taktilni (dodirni) doživljaj nije u pitanju; žuborenje vode je auditivni podražaj."},
  "2018_jesen_B__13": {"B":"Gosti mu otvoreno ne prijete; oni ga samo izdaleka, iz prikrajka, znatiželjno promatraju.","C":"Gosti ga ne oponašaju; čude se njegovoj neobičnosti i kradomice ga gledaju.","D":"U ulomku nema izravnoga ismijavanja gostiju; oni ga promatraju 'iz prikrajka'."},
  "2018_jesen_B__14": {"A":"Mazgar ne pomiče oružje da bi ponizio don Quijotea, nego da bi došao do vode za napajanje mazgi.","C":"Krčmar mu to nije naredio; mazgar sam ide napojiti mazge pa mora maknuti oružje.","D":"Mazgar oružje ne želi ukrasti, nego ga samo pomiče jer leži na valovu (koritu) iz kojega poji mazge."},
  "2018_jesen_B__15": {"A":"Čudnim se u ulomku doima don Quijote, a ne mazgar; mazgar je okarakteriziran kao neposlušan.","B":"Nasilje nije istaknuto obilježje mazgara; on se ogriješio o opomenu, tj. bio je neposlušan.","D":"Mazgar nije prikazan kao uvredljiv; ne mari za don Quijoteove riječi i time pokazuje neposluh."},
  "2018_jesen_B__16": {"A":"Prolaznici se ne čude putu kojim ide, nego tome što glasno razgovara sam sa sobom.","C":"Iako je Raskoljnikov plakao u sobi, prolaznike na ulici čudi njegovo glasno govorenje sebi u bradu.","D":"Pismo čita u sobi, a ne na ulici; prolaznike zbunjuje njegovo razgovaranje sa samim sobom."},
  "2018_jesen_B__17": {"A":"Zajedljiv, prkostan smiješak otkriva psihičko stanje lika, a ne njegov društveni položaj.","C":"Snažno lupanje srca i uskomešane misli emocionalna su, a ne socijalna karakterizacija.","D":"Gunđanje i smješkanje govore o raspoloženju, a ne o materijalnim, socijalnim prilikama lika."},
  "2018_jesen_B__18": {"A":"Rečenica ne pokazuje bijeg od stvarnosti, nego unutarnju napetost izraženu kroz potrebu za prostorom.","B":"Ne govori o strahu od ljudi; naprotiv, izlazi 'ne zazirući' od susreta na stubištu.","C":"Izlazak nije zbog posla, nego zbog tjeskobe i uzrujanosti u zagušljivoj sobici."},
  "2018_jesen_B__19": {"A":"Sjećanje ne potiče zvuk, nego prizor; Filip 'vidio' je krov kokošinjca i tepihklopfer.","B":"Okusni podražaj nije izvor sjećanja; ono se budi gledanjem 'onog istog tepihklopfera'.","C":"Miris nije pokretač sjećanja; presudan je vizualni doživljaj prizora pred kokošinjcem."},
  "2018_jesen_B__20": {"A":"U primjeru nema alegorije (prenesena dvostrukog značenja cijele slike), nego suprotstavljanja naivnosti i poroka.","C":"Eufemizam (ublažavanje) nije prisutan; figura počiva na izravnu kontrastu dviju krajnosti.","D":"Nije riječ o oksimoronu (spoju dviju protuslovnih riječi), nego o antitezi širih suprotstavljenih slika."},
  "2018_jesen_B__21": {"A":"'Jalovo' ne znači 'dugo'; vremensko trajanje izriče sintagma 'pune tri godine', a ne ovaj prilog.","B":"'Jalovo' ne znači 'jako'; jakost patnje izriče riječ 'bolno', a ne 'jalovo'.","C":"'Jalovo' ne znači 'neutješno', nego besplodno, bez ploda i koristi (uzaludno)."},
  "2018_jesen_B__22": {"A":"Prometej se Zeusu ne priklanja zbog približavanja ljudima, nego jer Titani nisu poslušali njegove savjete.","C":"On se ne plaši Gejina proročanstva; ono ga, naprotiv, navodi na zaključak da pobjeđuje lukavstvo.","D":"Zeus mu nije obećao protuuslugu; presudan je neuspjeh u nagovaranju Titana."},
  "2018_jesen_B__23": {"A":"Had nije nazvan gospodarom bogova; 'gospodar bogova' koji uzvraća sramotnim darom jest Zeus.","B":"Kron nije taj 'gospodar bogova'; on je svrgnut, a vlast preuzima Zeus.","C":"Uran nije 'gospodar bogova' iz ovoga konteksta; riječ je o Zeusu koji okiva Prometeja."},
  "2018_jesen_B__24": {"B":"Izraz se ne odnosi na Kronovo lukavstvo, nego na kaznu koju Zeus daje Prometeju za pomoć.","C":"Ne odnosi se na Zeusovo pridobivanje saveznika silom, nego na nezahvalnu kaznu (okivanje).","D":"Nije riječ o Gejinu proročanstvu, nego o sramotnom 'uzdarju' kojim Zeus uzvraća za pomoć."},
  "2018_jesen_B__25": {"A":"Mačak ne želi nadmašiti predstavu iz Gornje Mrduše, nego prikazati vlastitu socijalističku stvarnost.","C":"Ne predlaže da glume obrazovani ljudi, nego predstavu o svakodnevnoj društvenoj stvarnosti sela.","D":"Riječ nije o predstavi temeljenoj na plesu i glazbi (to je bilo prije), nego o prikazu društvene zbilje."},
  "2018_jesen_B__26": {"B":"Kulturno uzdizanje naroda Bukara ne osuđuje; 'reakcionarnim zafrkavanjem' naziva otpor seljaka prijedlogu.","C":"Zaključke sastanka Bukara ne naziva tako; prozива podrugljive komentare seljaka koji se protive.","D":"Nisu Puljine primjedbe u pitanju, nego rugalice seljaka usmjerene protiv Mačkova prijedloga."},
  "2018_jesen_B__27": {"A":"Bukara nije određen za redatelja; Mačak za to predlaže učitelja kao najpismenijega.","B":"Mačak predlaže predstavu i vodi sastanak, ali za redatelja određuje učitelja, ne sebe.","C":"Puljo nije izabran za redatelja; tu zadaću Mačak dodjeljuje učitelju Škunci."},
  "2018_jesen_B__28": {"B":"Manifest ne govori o življenju u skladu s prirodom, nego o vrijednosti postojanja stvari nad njihovom korišću.","C":"Spoznaja je upravo da ljepota stvari 'ne ovisi o nama', a ne da je ljudi pridaju.","D":"Težnja za mirom nije temelj manifesta; temelj je prednost postojanja pred iskoristljivošću."},
  "2018_jesen_B__29": {"B":"Djetinjstvo nije prikazano kao bezbrižno; pripovjedač je bojažljivo dijete koje se sklanja u prirodu.","C":"Pripovjedač se ne srami podrijetla; samo uspoređuje otočku korisnost stabala s novom spoznajom.","D":"Nije bio koristoljubiv 'oduvijek'; upravo doživljava spoznaju o vrijednosti nekorisnoga, lijepoga."},
  "2018_jesen_B__30": {"A":"Otočani nisu prikazani kao puni dvojba o smislu prirode, nego kao oni koji je moraju iskorištavati.","C":"Ne ističe se njihovo uživanje u slobodi, nego nužnost iskorištavanja stabala za preživljavanje.","D":"Nema spomena želje za bijegom s otoka; naglašena je praktična prisila iskorištavanja prirode."},
  "2018_jesen_B__31": {"A":"Balzacov Otac Goriot je roman, dakle pripada epskomu (proznom) rodu, a ne dramskomu.","B":"Danteova Božanstvena komedija je ep (spjev), a ne dramsko djelo.","D":"Voltaireov Candide je filozofski roman, dakle pripada epskomu rodu, ne drami."},
  "2018_jesen_B__32": {"A":"Heksametar nije pjesma od šest strofa, nego vrsta stiha.","B":"Heksametar nije strofa od šest stihova (to bi bila sekstina), nego stih od šest stopa.","C":"Heksametar nije stih od šest slogova; on se mjeri stopama (šest stopa), a ne slogovima."},
  "2018_jesen_B__33": {"B":"Epitaf je nadgrobni natpis, a ne duhovita satirična pjesma s neočekivanom poantom.","C":"Idila prikazuje mirnu, pastoralnu sliku, a ne sažetu satiričnu pjesmu s iznenadnim završetkom.","D":"Oda je svečana, uzvišena pohvalna pjesma, a ne kratka satirična pjesma s poantom."},
  "2018_jesen_B__34": {"A":"'Zemlja, trava' nisu protuslovne riječi spojene u sintagmu; nema oksimorona.","B":"'Siroti mrtvac' nije oksimoron jer pojmovi nisu protuslovni (mrtvac doista može biti 'sirot').","C":"'U žaru kovati stihove' je metafora, a ne oksimoron; nema spoja proturječnih pojmova."},
  "2018_jesen_B__35": {"A":"Alegorija je prošireno, dvostruko značenje cijele slike, a 'srce' ovdje stoji kao jedna prenesena riječ (metafora).","B":"Epitet je ukrasni pridjev, a 'srce' je imenica u prenesenom značenju, dakle metafora.","D":"Personifikacija pridaje neživomu ljudske osobine; ovdje se ljudsko 'srce' prenosi na osobu, što je metafora."},
  "2018_jesen_B__36": {"A":"Agamemnon je vrhovni zapovjednik Grka, a ne glavni junak Ilijade.","C":"Menelaj je Helenin muž i Agamemnonov brat, ali nije glavni junak epa.","D":"Patroklo je Ahilejev prijatelj čija smrt pokreće radnju, ali glavni junak je Ahilej."},
  "2018_jesen_B__37": {"A":"Eshil je grčki tragičar (Okovani Prometej), a ne autor latinske Eneide.","B":"Homer je autor Ilijade i Odiseje, a ne Eneide.","C":"Sofoklo je grčki tragičar (Antigona), a ne pisac Eneide."},
  "2018_jesen_B__38": {"A":"U 13. stoljeću još nije izumljen tisak, pa inkunabule tada ne mogu nastati.","B":"U 14. stoljeću tisak pomičnim slovima još ne postoji; inkunabule nastaju nakon Gutenberga.","D":"Nakon 1500. tiskane se knjige više ne nazivaju inkunabulama; one su strogo 15. stoljeća."},
  "2018_jesen_B__39": {"A":"'Decameron' ne znači 'deset pripovjedača', nego 'deset dana' (deka + hemera).","C":"Naslov ne znači 'sto likova'; sto je novela, a naslov upućuje na deset dana.","D":"Naslov ne znači 'sto priča'; sto je ukupan broj novela, ali naslov doslovno znači 'deset dana'."},
  "2018_jesen_B__40": {"A":"Džore Držić pripada dubrovačkomu, a ne hvarskomu književnom krugu.","C":"Marko Marulić je splitski književnik, a ne pripadnik hvarskoga kruga.","D":"Šiško Menčetić je dubrovački pjesnik, a ne hvarski."},
  "2018_jesen_B__41": {"A":"U Držićevoj Noveli od Stanca nema dramske igre Mišolovka ni uputa glumcima.","B":"U Sofoklovoj Antigoni nema igre Mišolovka; ona je vezana uz Hamleta.","D":"Škrtac (Molière) ne sadrži Mišolovku; to je element Shakespeareova Hamleta."},
  "2018_jesen_B__42": {"A":"Humanizam je raniji (15.–16. st.), dok Bunić Vučić stvara u 17. stoljeću.","B":"Renesansa prethodi Buniću; on pripada baroknomu razdoblju 17. stoljeća.","D":"Klasicizam je kasniji pravac; Bunić Vučić je barokni dubrovački pjesnik."},
  "2018_jesen_B__43": {"A":"Kačićev Razgovor ugodni naroda slovinskoga je pjesničko-prozno djelo, a ne komedija.","C":"Reljkovićev Satir iliti divji čovik je prosvjetiteljski poučni spjev, a ne komedija.","D":"Katančićevi Jesenski plodovi su pjesnička zbirka, a ne komedija."},
  "2018_jesen_B__44": {"B":"Motiviranost dužnošću i čašću obilježje je klasicizma, a ne romantizma.","C":"Ugledanje na antičke uzore svojstveno je renesansi i klasicizmu, ne romantizmu.","D":"Kićeni stil odlika je baroka, a ne romantizma."},
  "2018_jesen_B__45": {"A":"Antun Nemčić je autor Putositnica, a ne putopisa Pogled u Bosnu.","B":"Ivan Mažuranić napisao je Smrt Smail-age Čengića, a Pogled u Bosnu napisao je njegov brat Matija.","D":"Pavao Štoos je pjesnik (Kip domovine), a ne autor putopisa Pogled u Bosnu."},
  "2018_jesen_B__46": {"A":"Dostojanstveni likovi vođeni dužnošću u sukobu sa strašću obilježje su klasicizma, ne naturalizma.","C":"Osobiti, izdvojeni pojedinci naglašene osjećajnosti pripadaju romantizmu, a ne naturalizmu.","D":"Tragični junaci uzvišena govora vezani su uz antičku tragediju, ne uz naturalizam."},
  "2018_jesen_B__47": {"A":"Izgubljena pjevanja Gundulićeva Osmana dopunio je Ivan Mažuranić, a ne Šenoa.","C":"Šenoa nije zagovarao naturalizam, nego pripada razdoblju realizma (protorealizam).","D":"Danicu je uređivao Ljudevit Gaj, a ne Šenoa (koji je uređivao Vijenac)."},
  "2018_jesen_B__48": {"A":"Honoré de Balzac je autor Oca Goriota, a ne Gospođe Bovary.","C":"Marcel Proust napisao je U traganju za izgubljenim vremenom, a ne Gospođu Bovary.","D":"Émile Zola je autor Germinala i drugih naturalističkih romana, a ne Gospođe Bovary."},
  "2018_jesen_B__49": {"A":"Radnja Posljednjih Stipančića ne odvija se u Beču, nego u Senju.","B":"Roman nije smješten u Rijeku, nego u primorski grad Senj.","D":"Radnja se ne zbiva u Zagrebu, nego u Senju gdje propada obitelj Stipančić."},
  "2018_jesen_B__50": {"B":"Društveno-analitička funkcija obilježje je realizma i naturalizma, a larpurlartizam odbacuje takvu svrhu.","C":"Osporavanje tradicionalnih vrijednosti odlika je avangarde, a ne larpurlartizma koji je estetski usmjeren.","D":"Podređenost buđenju nacionalne svijesti svojstvena je preporodnoj književnosti, a larpurlartizam takvu funkciju niječe."},
  "2018_jesen_B__51": {"A":"Dostojevski ne piše autobiografski romaneskni ciklus o idiličnu djetinjstvu i mondenim sredinama; opis odgovara Proustu.","B":"Balzacov ciklus Ljudska komedija nije autobiografski prikaz jednoga pripovjedača koji odrasta od dječaka do umjetnika.","C":"Goethe nije autor takva višesveščanog autobiografskog ciklusa o usponu osjetljiva pripovjedača; riječ je o Proustu."},
  "2018_jesen_B__52": {"B":"Ekspresionizam nastaje u Njemačkoj početkom 20. st., a ne 1916. u Švicarskoj.","C":"Futurizam nastaje u Italiji 1909. (Marinetti), a ne u Švicarskoj 1916.","D":"Imažinizam je angloamerički pravac s početka 20. st., a ne švicarski iz 1916."},
  "2018_jesen_B__53": {"A":"Adam ATMA nije lik koji izgovara te rečenice o prodanu tijelu; to su Maestrove riječi.","B":"Don Fernando nije autor tih riječi o kadaveru prodanu medicinskomu fakultetu.","D":"Melkior je glavni lik, ali navedene riječi o nihilizmu i prodanu tijelu izgovara Maestro."},
  "2018_jesen_B__54": {"A":"Društvena angažiranost nije odlika ludizma; ludizam je usmjeren na jezičnu igru, a ne na društvenu kritiku.","B":"Regionalna obilježenost nije bitna odlika ludizma; presudna je igra riječima.","C":"Epski elementi nisu obilježje ludizma; on počiva na poigravanju jezikom i značenjima."},
  "2018_jesen_B__55": {"B":"Antun Branko Šimić nije autor Utjehe kose; njegova lirika nema soneta o mrtvoj voljenoj s motivima odra i svijeća.","C":"Vladimir Vidrić nije napisao te stihove; Utjeha kose je Matoševa pjesma.","D":"Tin Ujević nije autor ovih stihova; riječ je o Matoševu sonetu Utjeha kose."},
  "2018_jesen_B__56": {"A":"'Plijesniv' je pogrešno; ispravan je oblik 'plijesnjiv'.","C":"'Riječita' je pogrešno; ispravan je oblik 'rječita'.","D":"'Riječnička' je pogrešno; ispravan je oblik 'rječnička'."},
  "2018_jesen_B__57": {"A":"Drugi član para je pogrešan: 'zapovjedati' treba biti 'zapovijedati'.","B":"Prvi član para je pogrešan: 'zamjeniti' treba biti 'zamijeniti'.","C":"Drugi član para je pogrešan: 'zastarjevati' treba biti 'zastarijevati'."},
  "2018_jesen_B__58": {"A":"'Zapadnoj Slavoniji' kao geografska odrednica strane piše se malim slovom ('zapadnoj'), pa rečenica nije ispravna.","B":"Pred imenom 'planine' opća se imenica piše malim slovom, no problematičnost čini rečenicu manje pouzdanom od C s nedvojbeno ispravnim 'Terezino Polje'.","D":"'Ulica' kao opća imenica u nazivu piše se malim slovom ('ulici'), pa rečenica nije pravopisno ispravna."},
  "2018_jesen_B__59": {"B":"Ispred suprotnoga veznika 'no' obvezatan je zarez, koji ovdje nedostaje.","C":"Ispred suprotnoga 'samo' (u značenju 'ali') treba zarez, koji ovdje nedostaje.","D":"Ispred suprotnoga veznika 'ali' nužan je zarez, koji u ovoj rečenici nedostaje."},
  "2018_jesen_B__60": {"A":"U 'izlječiv' nije provedeno jednačenje po mjestu tvorbe, nego ije/je glasovne promjene.","B":"U 'objašnjiv' nije riječ o jednačenju po mjestu tvorbe, nego o jotaciji.","C":"U 'raspoloživ' nema jednačenja po mjestu tvorbe (s/z je rezultat jednačenja po zvučnosti)."},
  "2018_jesen_B__61": {"A":"U 'deka' (dat. deki) ne provodi se sibilarizacija jer ostaje 'deki', bez prijelaza k u c.","C":"U 'jaruga' (dat. jaruzi) provodi se palatalizacija/sibilarizacija g→z, ali tražena je promjena k→c kod intelektualka.","D":"Vlastito ime 'Koraljka' u dativu ne provodi sibilarizaciju (Koraljki), jer se imena na -ka ne sibilariziraju."},
  "2018_jesen_B__62": {"B":"Kratkouzlazni naglasak (snijèg) nije ispravan za jednosložnu imenicu 'snijeg'.","C":"Dugosilazni naglasak (snijêg) nije pravilan naglasak ove riječi.","D":"Dugouzlazni naglasak (snijég) nije ispravan; 'snijeg' ima kratkosilazni naglasak."},
  "2018_jesen_B__63": {"A":"'Li' je zanaglasnica (enklitika) koja se naslanja na prethodnu riječ, a ne prednaglasnica.","B":"'Mu' je enklitika (zanaglasnica), a ne proklitika.","C":"'Se' je također zanaglasnica koja se naslanja unatrag, a ne prednaglasnica."},
  "2018_jesen_B__64": {"A":"Raščlamba 'is-pre-ki-dan' nije morfemska, nego slogovna; ne izdvaja korijen '-kid-'.","C":"U 'is-prekid-an' spojeni su prefiks 'pre-' i korijen, pa nisu izdvojeni svi morfemi.","D":"U 'is-pre-kidan' korijen i sufiks nisu razdvojeni; treba 'kid-an'."},
  "2018_jesen_B__65": {"A":"'San' je tvorbeni korijen, a ne oblikotvorna osnova na koju dolaze gramatički nastavci.","B":"'Sanja' nije gramatička osnova imenice 'sanjalica'; nastavak '-a' dolazi na 'sanjalic-'.","C":"'Sanjali' nije osnova ove imenice; oblikotvorna osnova je 'sanjalic-'."},
  "2018_jesen_B__66": {"A":"'Piscima' je u dativu množine (kome?), a ne u instrumentalu.","B":"'Patnje' je u nominativu množine kao subjekt rečenice, a ne u instrumentalu.","C":"'Ljubavi' je u genitivu (zbog čega? neuzvraćene ljubavi), a ne u instrumentalu."},
  "2018_jesen_B__67": {"A":"'Braća' je zbirna imenica ženskoga gramatičkog roda, a ne srednjega.","C":"'Gorčinu' je imenica ženskoga roda, a ne srednjega.","D":"'Uši' je imenica ženskoga roda množine, a ne srednjega roda."},
  "2018_jesen_B__68": {"A":"Uz neživu imenicu 'stil' u akuzativu treba 'koji', a ne 'kojega'.","B":"Uz neživu imenicu 'roman' u akuzativu pravilno je 'koji', a ne 'kojega'.","C":"Uz neživu imenicu 'film' u akuzativu treba oblik 'koji', a ne 'kojega'."},
  "2018_jesen_B__69": {"B":"'Hoćeš li mi pomoći' je futur prvi, a ne futur drugi.","C":"'Znat ćeš' je futur prvi, a ne futur drugi.","D":"'Bi htio' je kondicional, a 'će doživjeti' futur prvi; nema futura drugoga."},
  "2018_jesen_B__70": {"A":"'Tko' je upitno-odnosna zamjenica, a ne prilog.","B":"'U' je prijedlog, a ne prilog.","D":"'Što' je upitno-odnosna zamjenica, a ne prilog."},
  "2018_jesen_B__71": {"A":"'Njemu' je dativ zamjenice, a kanonski (rječnički) oblik bio bi 'on'.","B":"'Je' je oblik prezenta glagola 'biti', a ne kanonski (infinitivni) oblik.","D":"'Promjene' je padežni oblik množine, a ne kanonski (nominativ jednine 'promjena')."},
  "2018_jesen_B__72": {"A":"'Sačuvana baština' rezultat je sročnosti (slaganja u rodu, broju i padežu), a ne pridruživanja.","B":"'Primiti nagradu' rezultat je upravljanja (rekcije) jer glagol traži akuzativ, a ne pridruživanja.","C":"'Teorija zavjere' rezultat je upravljanja (imenica traži genitiv), a ne pridruživanja."},
  "2018_jesen_B__73": {"B":"Predikat rečenice je 'uživao je', a ne prijedložni skup 'u kolaču'.","C":"'U kolaču' nije priložna oznaka, nego prijedložni objekt koji traži glagol 'uživati'.","D":"Subjekt je neizrečeni 'on', a ne 'u kolaču', koji je objekt."},
  "2018_jesen_B__74": {"A":"Tri surečenice premalo; u rečenici ih je četiri.","C":"Pet surečenica previše; broj zavisnih i glavne daje četiri surečenice.","D":"Šest surečenica je previše; rečenica ima četiri surečenice."},
  "2018_jesen_B__75": {"A":"Načinska rečenica izriče način radnje (kako?); ovdje zavisna ima ulogu subjekta uz bezlični predikat.","B":"Objektna rečenica zamjenjuje objekt, no uz bezlični 'nagađalo se' nema objekta, nego subjekta.","D":"Vremenska rečenica izriče vrijeme (kad?); ovdje 'kako će završiti' ima službu subjekta, ne priložne oznake vremena."},
  "2018_jesen_B__76": {"B":"'Deklinacija' i 'sklonidba' su istoznačnice (sinonimi), a ne antonimi.","C":"'Imenica' i 'padež' nisu suprotnoznačni; između njih je nadređeno-podređeni (hijerarhijski) odnos.","D":"'Fonem' i 'alofon' nisu antonimi, nego pojmovi u odnosu jedinice i njezine inačice."},
  "2018_jesen_B__77": {"B":"'Tapasi' nisu nastali od osobnoga imena, nego označavaju vrstu jela, pa nisu eponim.","C":"'Falkuša' je naziv vrste broda, nije nastao od imena osobe, pa nije eponim.","D":"'Ragusa' je staro ime grada (toponim), a ne riječ izvedena iz osobnoga imena."},
  "2018_jesen_B__78": {"A":"Posuđenice iz španjolskoga su hispanizmi, a ne bohemizmi.","B":"Posuđenice iz francuskoga su galicizmi, a ne bohemizmi.","D":"Posuđenice iz grčkoga su grecizmi (helenizmi), a ne bohemizmi."},
  "2018_jesen_B__79": {"A":"'Pala s konja na magarca' znači da je netko prošao gore nego prije, dakle suprotno od sreće.","B":"'Pala muha na medvjeda' označava nailaženje na jaču silu ili nevolju, a ne sreću.","D":"'Pala s neba na zemlju' znači razočaranje i suočavanje sa zbiljom, a ne sreću ili uspjeh."},
  "2018_jesen_B__80": {"A":"Godina 1835. vezana je uz početak izlaženja Danice, a ne uz Deklaraciju.","B":"Godina 1850. povezana je s Bečkim književnim dogovorom, a ne s Deklaracijom.","C":"Godina 1939. nije godina Deklaracije; ona je objavljena 1967. u Telegramu."},

  // 2018_ljeto_A
  "2018_ljeto_A__1": {"B":"Stih opisuje hrastik i njegov miris, ali mu se ne obraća izravno, pa nema apostrofe.","C":"Šuma se ovdje spominje u trećem licu kao subjekt radnje, a ne kao adresat obraćanja.","D":"Iako se spominje šuma, obraćanje je upućeno 'stvorovima malim', a ne samoj šumi."},
  "2018_ljeto_A__2": {"A":"Stih govori o prastarim bajkama snijega u biću šume, a ne o prolaznosti svega.","C":"Stih ističe trajnost ljubavi jela ('traje'), što je suprotno ideji prolaznosti.","D":"Stih prikazuje smrtnika koji doseže svrhu planeta, dakle dostignuće, a ne prolaznost."},
  "2018_ljeto_A__3": {"B":"Jela se vezuje uz ljubav i materinsku njegu (dodir, osjećaj), a ne uz miris.","C":"Vjetar je u pjesmi povezan sa zvukom i gibanjem, a ne s olfaktivnim podražajem.","D":"Voda je prikazana zvukovno i vizualno ('zahučala', 'dubokim virom'), a ne mirisom."},
  "2018_ljeto_A__4": {"A":"Subjekt ne upozorava na prolaznost djevojčine ljepote, nego je upravo veliča.","B":"U tekstu nema motiva djevojčine ljutnje ni subjektove nesreće zbog nje.","D":"Iako se spominju suze, subjekt ih ne koristi da bi ganuo djevojku."},
  "2018_ljeto_A__5": {"A":"Stihovi opisuju djevojčinu mladost i ljepotu usporedbom s proljećem, a ne narav.","C":"Stihovi prikazuju kratkotrajnost cvijeta (ruže), a ne djevojčin karakter.","D":"Stihovi naglašavaju da je djevojčina ljepota navečer ljepša, a ne njezinu narav."},
  "2018_ljeto_A__6": {"B":"Poanta ne počiva na postupnom stupnjevanju (gradaciji), nego na suprotstavljanju ruže i djevojke.","C":"Poanta nije utemeljena na pretjerivanju (hiperboli), nego na suprotnosti.","D":"Poanta ne ublažava neugodan pojam (eufemizam), nego se gradi na kontrastu."},
  "2018_ljeto_A__7": {"A":"Agamemnon se ne obraća bogu, nego ljutito gleda i govori vraču.","B":"Atrej je samo Agamemnonov otac (patronim), a ne sugovornik kojemu se obraća.","C":"Svećenik (Hrizo) spominje se u sporu, ali Agamemnon mu se ne obraća izravno."},
  "2018_ljeto_A__8": {"A":"Tekst ne navodi da Argejci nude svećeniku novac kao razlog Agamemnonova gnjeva.","B":"Agamemnon nije uvrijeđen darovima, nego upravo on odbija dati kćer i primiti otkup.","C":"Nezadovoljstvo se ne odnosi na necijenjenje njegova junaštva, nego na vračevo proricanje."},
  "2018_ljeto_A__9": {"A":"Oči se ne uspoređuju sa strijelom, taj motiv u tekstu ne postoji.","B":"Mrak se vezuje uz srce ispunjeno gnjevom ('mračno'), a ne uz oči.","D":"Sila opisuje Agamemnona kao junaka, ali njegove se oči uspoređuju s vatrom, ne sa silom."},
  "2018_ljeto_A__10": {"A":"Otvoreno ždrijelo opisuje hodnike sjemeništa, a ne Lovrinu narav.","B":"Dim žrtve odnosi se na Lovrinu molitvu koja se gubi, a ne na njegovu narav.","D":"Nečisti duh nije izraz kojim se opisuje Lovro u ovome ulomku."},
  "2018_ljeto_A__11": {"B":"Rečenica se ne odnosi na materijalnu nemogućnost svećeničkoga života, nego na uzaludnost molitve.","C":"U ulomku se navodi da Lovro nema pjesničke sile, pa nije riječ o uzaludnom pisanju pjesama.","D":"Lovro u molitvi ne pronalazi mir; upravo je molitva ostala 'badava'."},
  "2018_ljeto_A__12": {"A":"Sukob sa sjemeništarcima nije razlog predstojnikova negodovanja; Lovro se tek odbio od drugova.","B":"Pretjerivanje u molitvama nije navedeno kao uzrok zamjerke, molitva mu nije pomagala.","D":"Lovro nema pjesničke sile, pa pisanje pjesama nije razlog zamjeranja predstojniku."},
  "2018_ljeto_A__13": {"B":"Tekst ne tvrdi da svi katovi imaju oblik podnožja svijećnjaka; spominje se različita gradnja katova.","C":"U ulomku se ne navodi da je u zgradi izgrađena jedna kapelica.","D":"Šesterokutna je sama zgrada, a ne stubište, pa tvrdnja o stubištu nije točna."},
  "2018_ljeto_A__14": {"B":"Oluki se u opisu ne spominju kao mjesto prikaza životinja.","C":"Na stubištu se navodi različito kamenje, a ne prikazi životinja.","D":"Prozori se ne spominju kao mjesto na kojem su prikazi životinja."},
  "2018_ljeto_A__15": {"A":"Rijeka teče sa sjeverne strane, pa zgrada nije istočno od Loire.","B":"Položaj zgrade nije južni; rijeka je sa sjeverne strane zgrade.","D":"Zgrada nije zapadno od Loire; rijeka teče sjeverno od nje."},
  "2018_ljeto_A__16": {"B":"Gustativni (okusni) podražaj ne pojavljuje se u ulomku.","C":"Olfaktivni (mirisni) podražaj nije ono što izluđuje Gregora.","D":"Vizualni podražaj nije izvor Gregorove muke; to je očevo siktanje (zvuk)."},
  "2018_ljeto_A__17": {"B":"Otac mu nije okrenuo leđa, nego ga je tjerao naprijed uz buku.","C":"Otac vrata ne zatvara štapom u ovome ulomku.","D":"Otac nije zašutio; gađenje se očituje upravo u nesnosnome siktanju i tjeranju."},
  "2018_ljeto_A__18": {"A":"Gregor se ne nada očevoj pomoći; ocu ne pada na pamet da mu olakša prolaz.","B":"Siktao je otac, a ne Gregor.","D":"Gregor ne udara oca; on krvareći ulazi u sobu."},
  "2018_ljeto_A__19": {"B":"Uloga društvenih znanosti nije tema; tekst nabraja različita 'sutra', a ne znanosti kao predmet.","C":"Položaj umjetnika spominje se samo usputno ('obrtnici ružnoga'), a nije glavna tema.","D":"Sukob duhovnih i materijalnih vrijednosti nije središnja tema niza razmišljanja o sutrašnjici."},
  "2018_ljeto_A__20": {"A":"Dijete se pojavljuje u 'pedagoškome sutra' kao opći adresat, a ne kao oznaka umjetnika.","C":"Pijanica se u ovome ulomku ne spominje kao oznaka umjetnika.","D":"Rugoba se odnosi na materiju ('rugobu materije'), a ne na umjetnike."},
  "2018_ljeto_A__21": {"A":"Materija je prethodno spomenuta, ali zamjenica 'je' upućuje na Silu koju svijest proglašava glupom.","B":"Pamet je objekt radnje ('pomuti im pamet'), a ne ono na što upućuje podcrtana zamjenica.","D":"Svijest je subjekt koji bi proglasio, a ne ono što se proglašava glupim."},
  "2018_ljeto_A__22": {"A":"Kreont kraljevsku čast ne smatra nečasnom, nego naprosto opterećujućom dužnošću.","B":"Proročanstvo nije razlog Kreontova nehtijenja vlasti.","C":"Kreont upravo cijeni što ga mole oni koji ga trebaju, pa molitelje ne odbija."},
  "2018_ljeto_A__23": {"A":"Kreont se ne brani od optužbe da odbacuje rođake.","B":"Optužba nije za samovoljno donošenje odluka, nego za zavjeru s prorokom.","D":"Kreont se ne brani od tvrdnje o pomućenu razumu, nego od sumnje u urotu."},
  "2018_ljeto_A__24": {"A":"Zbor ne govori da se vladar ni u koga ne može pouzdati.","B":"Zbor ne savjetuje brzo donošenje odluka, nego upravo opreznost.","C":"Zbor ne upozorava da se vladar mora čuvati podanika, nego hvali opreznost."},
  "2018_ljeto_A__25": {"B":"Mirogoj se u ulomku ne spominje kao mjesto razgovora.","C":"Zeleni breg nije mjesto na kojem se odvija razgovor poznanika.","D":"Riječni rukavac nije mjesto radnje; razgovor se vodi na sajmu."},
  "2018_ljeto_A__26": {"A":"Rečenica se ne odnosi na propušteni pozdrav.","B":"Rečenica ne znači zakašnjenje na Kraljevo.","C":"Rečenica se ne odnosi na upoznavanje baba, nego na to da je Janez tek umro."},
  "2018_ljeto_A__27": {"B":"Janez nije razbojnik; naziva ga se funebrašem (grobarom).","C":"Janez nije žandar; po zanimanju je grobar.","D":"Janez nije živoder; funebraš znači grobar."},
  "2018_ljeto_A__28": {"A":"Fonostilemi su glasovna isticanja, a temeljni su motivi istaknuti grafički (kurzivom).","C":"Morfostilemi su oblikoslovna isticanja, a ovdje je riječ o grafičkome isticanju.","D":"Sintaktostilemi su rečenična isticanja, a temeljni se motivi ističu grafostilemima."},
  "2018_ljeto_A__29": {"A":"Žene koje se žrtvuju za muževe spominju se kasnije, a ne na njih upućuje podcrtana riječ.","B":"Vojske koje osvajaju teritorije uvod su teksta, a ne ono na što upućuje 'to'.","C":"Oni koji spaljuju nevjernike nisu referent podcrtane riječi; ona upućuje na napredne mislioce."},
  "2018_ljeto_A__30": {"A":"U tekstu se ne navodi da se Prometej na Kavkazu krijepio vodom.","C":"Prometej ne pali olimpijsku baklju; krišom se popeo na Olimp.","D":"Bacanje ugarka na orla nije navedeno u ulomku."},
  "2018_ljeto_A__31": {"A":"Diskurzivni rod obuhvaća esej i raspravu, a epigram je kratka pjesnička vrsta.","B":"Dramski rod podrazumijeva scensku izvedbu, što epigram nije.","C":"Epski rod obuhvaća dulja pripovjedna djela, a epigram je sažeta lirska forma."},
  "2018_ljeto_A__32": {"A":"Akcenatsko-silabička versifikacija počiva na naglasku i broju slogova, a ne na duljini, kao heksametar.","C":"Akcenatska versifikacija temelji se samo na naglascima, a heksametar na kvantiteti.","D":"Silabička versifikacija mjeri samo broj slogova, dok heksametar mjeri duge i kratke slogove."},
  "2018_ljeto_A__33": {"A":"Opis se odnosi na legendu (uzorni lik za zajednicu), a ne na novelu.","B":"Opis pripada mitu (priča o nastanku svijeta i pojava), a ne noveli.","D":"Opis razgranate fabule s mnogo događaja i likova odgovara romanu, a ne noveli."},
  "2018_ljeto_A__34": {"A":"Ovdje je riječ o ponavljanju 'O jeziku' na početku stihova (anafora), a ne o anadiplozi.","C":"Riječ je o ponavljanju početka stihova ('Slušaj'), dakle o anafori, a ne anadiplozi.","D":"Ponavlja se sintagma 'u jeseni' na krajevima stihova (epifora), a ne anadiploza."},
  "2018_ljeto_A__35": {"A":"Riječ je o usporedbi pjesnika i kneza visova, a ne o miješanju osjetila.","B":"Stih nabraja apstraktne mane, bez spajanja različitih osjetilnih doživljaja.","D":"Stih je obraćanje čitatelju, bez sinestezijskog spoja osjetila."},
  "2018_ljeto_A__36": {"A":"Antigona ne govori o proroštvu danom Laju; ona je Edipova kći.","B":"Elektra nije lik iz priče o Laju i Edipovu proroštvu.","C":"Izmena ne iznosi proroštvo o Laju; te riječi pripadaju Jokasti."},
  "2018_ljeto_A__37": {"B":"Opis epa o junaku koji se obračunava s prosцima supruge odnosi se na Homerovu Odiseju.","C":"Junak koji se oženio vlastitom majkom Edip je iz Sofoklove tragedije, a ne Vergilija.","D":"Junak koji unatoč zabrani pomaže ljudskome rodu Prometej je (Eshil), a ne Vergilijev lik."},
  "2018_ljeto_A__38": {"B":"Rumanac Trojski srednjovjekovni je roman (proza), a ne drama.","C":"Svit se konča srednjovjekovna je pjesma (lirika), a ne drama.","D":"Aleksandrida je srednjovjekovni roman o Aleksandru, a ne drama."},
  "2018_ljeto_A__39": {"A":"Džore Držić petrarkist je, autor ljubavne lirike, a ne Elegije o pustošenju Šibenskog polja.","B":"Hanibal Lucić autor je Robinje i Jur nijedna, a ne navedene elegije.","D":"Šiško Menčetić petrarkist je iz Dubrovnika, a ne autor Šižgorićeve elegije."},
  "2018_ljeto_A__40": {"A":"'Jur nijedna na svit vila' stih je Hanibala Lucića, a ne Hektorovića.","B":"'O lijepa, o draga, o slatka slobodo' iz Gundulićeva je Dubravke, a ne Hektorovićev.","D":"'Blaženi čas i hip' petrarkistički je stih (Menčetić), a ne Hektorovićev."},
  "2018_ljeto_A__41": {"A":"'Nehaj jezika hrvatskoga' nije Gundulićev naziv za mladenačka djela.","B":"'Rasuta bašćina' Gundulićeva je oznaka iz posvete Osmana, a ne naziv za mladenačke drame.","D":"'Razasute rime' nisu Gundulićev naziv za njegova mladenačka djela."},
  "2018_ljeto_A__42": {"A":"Carlo Goldoni talijanski je komediograf (Gostioničarka), a ne autor Fedre.","C":"Molière je komediograf (Tartuffe, Škrtac), a ne autor tragedije Fedra.","D":"Voltaire je prosvjetiteljski pisac (Candide), a ne autor Fedre."},
  "2018_ljeto_A__43": {"B":"Mitološke i religiozne teme uz prolaznost obilježja su baroka, a ne romantizma.","C":"Jednostavna, jasna i pravilna forma značajka je klasicizma, a ne romantizma.","D":"Socijalno i psihološki motivirani likovi obilježje su realizma, a ne romantizma."},
  "2018_ljeto_A__44": {"A":"Ivan Mažuranić autor je Smrti Smail-age Čengića, a ne Kipa domovine.","B":"Ljudevit Gaj autor je Još Horvatska ni propala, a ne navedene pjesme.","D":"Stanko Vraz autor je Đulabija, a ne Kipa domovine."},
  "2018_ljeto_A__45": {"A":"Povjestice nisu epovi, nego kraće lirsko-epske pjesme.","B":"Povjestice nisu feljtoni (novinski žanr), nego pjesme s povijesnim motivima.","D":"Povjestice nisu zbirka novela, nego zbirka lirsko-epskih pjesama."},
  "2018_ljeto_A__46": {"A":"Futurizam slavi tehniku i brzinu, a ne Taineov determinizam likova.","B":"Impresionizam bilježi trenutačne dojmove, a ne nasljeđe, sredinu i trenutak.","C":"Nadrealizam crpi iz nesvjesnoga i snova, a ne iz Taineova determinizma."},
  "2018_ljeto_A__47": {"A":"'Budi svoj' nije Kranjčevićeva pjesma.","C":"'Gospodskomu Kastoru' nije Kranjčevićeva pjesma.","D":"'Ždral putuje k toplom jugu' Vrazova je pjesma, a ne Kranjčevićeva."},
  "2018_ljeto_A__48": {"B":"Filip Latinovicz Krležin je lik koji ne izgovara riječi o umorstvu Mihe.","C":"Ivica Kičmanović lik je iz Šenoine U registraturi, a ne govornik ovih rečenica.","D":"Melkior Tresić Marinkovićev je lik iz Kiklopa, a ne onaj koji spominje umorstvo Mihe."},
  "2018_ljeto_A__49": {"A":"Stéphane Mallarmé simbolist je, ali nije autor Suglasja.","C":"Arthur Rimbaud autor je Pijanoga broda, a ne Suglasja.","D":"Paul Verlaine autor je Pjesničkoga umijeća, a ne Suglasja."},
  "2018_ljeto_A__50": {"A":"André Breton autor je nadrealističkoga, a ne futurističkoga manifesta.","C":"Sergej Jesenjin ruski je pjesnik, nije autor futurističkoga manifesta.","D":"Tristan Tzara utemeljitelj je dadaizma, a ne autor futurističkoga manifesta."},
  "2018_ljeto_A__51": {"A":"'Bez trećega' Begovićeva je psihološka drama, a ne antidrama.","B":"'Majka Hrabrost' Brechtova je epska drama, a ne antidrama.","D":"'Tri sestre' Čehovljeva je realistička drama, a ne antidrama."},
  "2018_ljeto_A__52": {"A":"Ivan Goran Kovačić autor je Jame, a ne kajkavske zbirke balada iz 1936.","B":"Dragutin Domjanić piše ljubavnu kajkavsku liriku, a ne baladе o kmetovima.","D":"Fran Galović autor je kajkavske zbirke Z mojih bregov, a ne Balada Petrice Kerempuha."},
  "2018_ljeto_A__53": {"A":"'Anđeo' je novela o kiparu i izradi anđela, a ne o džeparu i Đini.","B":"'Prah' tematizira propali život činovnika Tonča, a ne džepara i Đinu.","C":"'Ruke' su dijalog ruku o ljudskoj sudbini, a ne priča o džeparu i Đini."},
  "2018_ljeto_A__54": {"A":"'Prokleta avlija' Andrićev je roman koji ne počinje navedenom rečenicom.","B":"'Psi u trgovištu' Aralicin su roman, a ne djelo s tom početnom rečenicom.","D":"'Kiklop' Marinkovićev je roman koji ne počinje rečenicom o prijatelju Roku."},
  "2018_ljeto_A__55": {"B":"Dragutin Tadijanović nije autor 'Oblaka'.","C":"Josip Pupačić autor je 'Mora', a ne 'Oblaka'.","D":"Tin Ujević nije autor 'Oblaka'."},
  "2018_ljeto_A__56": {"B":"'Potlaćen' nije pravilno; ispravno je 'potlačen'.","C":"'Ujednaćen' nije pravilno; ispravno je 'ujednačen'.","D":"'Zajamćen' nije pravilno; ispravno je 'zajamčen'."},
  "2018_ljeto_A__57": {"A":"'Podhlađen' nije pravilno; zbog jednačenja piše se 'pothlađen'.","B":"'Podkrovlje' nije pravilno; ispravno je 'potkrovlje'.","C":"'Podpetica' nije pravilno; ispravno je 'potpetica'."},
  "2018_ljeto_A__58": {"A":"Pogrešno je 'Hrvatskome Narodnom Kazalištu'; pravilno je 'Hrvatskome narodnom kazalištu'.","B":"Pogrešno je 'Bliskome Istoku'; pravilno je 'Bliskome istoku'.","D":"Pogrešno je 'Ulici Matice Hrvatske'; pravilno je 'Ulici Matice hrvatske'."},
  "2018_ljeto_A__59": {"B":"'Agro-meteorološka' nije pravilno; piše se sastavljeno 'agrometeorološka'.","C":"'Južno-korejski' nije pravilno; piše se sastavljeno 'južnokorejski'.","D":"'Ultra-zvuk' nije pravilno; piše se sastavljeno 'ultrazvuk'."},
  "2018_ljeto_A__60": {"B":"'Grad → građanin' primjer je jotacije (palatalizacijskoga tipa), a ne jednačenja po mjestu tvorbe.","C":"'Slastan → slasna' primjer je gubljenja suglasnika, a ne jednačenja po mjestu tvorbe.","D":"'Smeđ → smećkast' primjer je jednačenja po zvučnosti (i drugih promjena), a ne po mjestu tvorbe."},
  "2018_ljeto_A__61": {"A":"'Izvaljen' nema epentetskoga l; l je dio osnove (valjati).","B":"'Muljevit' nema umetnutoga l; l pripada osnovi (mulj).","D":"'Žuljevit' nema epentetskoga l; l je dio osnove (žulj)."},
  "2018_ljeto_A__62": {"A":"'Pròfesorica' nije pravilno naglašena; naglasak nije na prvome slogu.","B":"'Profesòrica' nije pravilan naglasak za ovu riječ.","C":"'Profèsorica' nije pravilan naglasak; nije na tome slogu."},
  "2018_ljeto_A__63": {"B":"'Sta-ro-grad-ski' slogovna je, a ne morfemska raščlamba.","C":"'Staro-grad-sk-i' spaja korijen i spojnik u jednu cjelinu, pa nije ispravna morfemska analiza.","D":"'Star-o-grad-ski' ne izdvaja sufiks -sk- i nastavak -i, pa morfemska analiza nije potpuna."},
  "2018_ljeto_A__64": {"A":"'Sustanar' cijela je riječ, a ne rječotvorna osnova jer sadrži prefiks su-.","B":"'Sustan' nije postojeća rječotvorna osnova.","D":"'Stan' je korijen, ali rječotvorna osnova od koje se tvori 'sustanar' jest 'stanar'."},
  "2018_ljeto_A__65": {"A":"'O njemu' lokativ je (uz prijedlog o), a ne dativ.","B":"'Te' u 'vidjeti te' akuzativ je, a ne dativ.","D":"'Ju' u 'počešljala ju je' akuzativ je, a ne dativ."},
  "2018_ljeto_A__66": {"A":"'Publiku' je u akuzativu jednine ženskoga roda, a ne srednji rod množine.","B":"'Služinčad' je zbirna imenica ženskoga roda jednine, a ne srednji rod množine.","D":"'Uši' su ženski rod množine, a ne srednji rod množine."},
  "2018_ljeto_A__67": {"A":"'Drugi' je redni broj (pridjevna riječ), a ne brojevna imenica.","B":"'Nekolicina' je neodređena brojevna imenica/izraz količine, ali traži se 'dvojica'; ona ne označuje točan broj muških osoba kao brojevna imenica izvedena od broja.","C":"'Tri' je glavni broj, a ne brojevna imenica."},
  "2018_ljeto_A__68": {"A":"Dva je premalo; u rečenici su tri prezenta ('ne mora', 'će ostati', 'je').","C":"Četiri je previše; prezenata je tri.","D":"Pet je previše; u rečenici su tri prezenta."},
  "2018_ljeto_A__69": {"A":"'Zviždučući' tvori se od 'zviždukati', a ne od 'zviždati'.","B":"'Zviždajući' nije pravilan glagolski prilog ovoga glagola.","D":"'Zviždeći' nije pravilan oblik glagolskoga priloga."},
  "2018_ljeto_A__70": {"A":"'Toga' je pokazna zamjenica, a ne odnosna.","C":"'Nitko' je neodređena (niječna) zamjenica, a ne odnosna.","D":"'Ju' je osobna zamjenica (akuzativ), a ne odnosna."},
  "2018_ljeto_A__71": {"B":"'Svježim narančama' rezultat je sročnosti (pridjev se slaže s imenicom), a ne pridruživanja.","C":"'Oguliti jednu' rezultat je upravljanja (rekcije), a ne pridruživanja.","D":"'Iscijediti sok' rezultat je upravljanja (glagol traži akuzativ), a ne pridruživanja."},
  "2018_ljeto_A__72": {"A":"'Na njega' neizravni je objekt (prijedložni), a ne izravni objekt u akuzativu bez prijedloga.","B":"'O njemu' neizravni je (prijedložni) objekt, a ne izravni.","D":"'Mu' je neizravni objekt u dativu, a ne izravni objekt."},
  "2018_ljeto_A__73": {"A":"Pet je premalo; rečenica ima sedam surečenica.","B":"Šest je premalo; surečenica je sedam.","D":"Osam je previše; surečenica je sedam."},
  "2018_ljeto_A__74": {"A":"'Da bismo imali bolji pogled' namjerna je rečenica, a ne pogodbena.","C":"'Koji smo rezervirali' odnosna je rečenica, a ne pogodbena.","D":"'Da će živjeti zauvijek' izrična je rečenica, a ne pogodbena."},
  "2018_ljeto_A__75": {"B":"Pogrešno je 'zato jer'; pravilno je 'zato što' ili 'jer'.","C":"Pogrešno je 'sa ili bez vozača'; pravilno je 'sa vozačem ili bez njega'.","D":"Pogrešno je 'Budući je'; pravilno je 'Budući da je'."},
  "2018_ljeto_A__76": {"A":"'Bovarizam' je eponim/apstraktna imenica, a ne ktetik (pridjev od imena mjesta).","C":"'Matoševski' je pridjev izveden od osobnoga imena (Matoš), a ne od toponima.","D":"'Šovinizam' je apstraktna imenica, a ne ktetik."},
  "2018_ljeto_A__77": {"A":"'Sumljičavi' nije pravilno; ispravno je 'sumnjičavi'.","B":"'Najoptimalnije' nije pravilno; 'optimalan' već znači najpovoljniji, pa se ne stupnjuje.","D":"'Živiti' nije pravilno; ispravno je 'živjeti'."},
  "2018_ljeto_A__78": {"A":"'Cjevovod' nastao je čistim slaganjem (cijev + voditi), bez sufiksa, pa nije složeno-sufiksalna.","C":"'Soboslikarski' izveden je sufiksom od složenice 'soboslikar', dakle sufiksalnom tvorbom od osnove.","D":"'Srednjoškolčev' izveden je posvojnim sufiksom od 'srednjoškolac', a nije složeno-sufiksalna."},
  "2018_ljeto_A__79": {"B":"Historizmi označuju nestale pojmove, a 'gorah' je zastarjeli oblik žive riječi, dakle arhaizam.","C":"Nekrotizmi su sasvim izumrle riječi, a 'gora' je i danas u uporabi (zastario je samo nastavak).","D":"Neologizmi su nove riječi, a 'gorah' je upravo zastario oblik, dakle arhaizam."},
  "2018_ljeto_A__80": {"B":"Habdelićev Dictionar kajkavsko-latinski je rječnik, ali se opis ozaljskoga kruga s elementima triju narječja odnosi na Belostenca.","C":"Mikaljino Blago jezika slovinskoga štokavsko je polazište, a ne kajkavsko s ozaljskim obilježjima.","D":"Vrančićev petojezični rječnik nije vezan uz ozaljski jezični krug ni kajkavsku osnovu."},

  // 2018_ljeto_B
  "2018_ljeto_B__1": {"A":"Stih opisuje prirodnu pojavu (more koje miče svjetlucave odsjaje), a ne prisutnost ljudi.","B":"Stih prikazuje samo dodir vode i broda, dakle prirodni i predmetni prizor bez ljudi.","C":"Stih opisuje potopljene stvari na morskom dnu, prirodni motiv bez ljudske prisutnosti."},
  "2018_ljeto_B__2": {"A":"Jedro je vizualni motiv (lik na pučini), uz njega se ne veže nikakav zvuk.","B":"Mulj je vizualni motiv s morskoga dna, bez akustičnoga podražaja.","C":"Ptice koje lete vizualni su motiv, u tekstu im se ne pripisuje zvuk."},
  "2018_ljeto_B__3": {"A":"Mulj je doslovan motiv morskoga dna, a ne metafora za more.","C":"Ulje se javlja u poredbi ('voda teška ko kružnica od ulja'), nije metafora za more.","D":"Svjetlo je dio prikaza titranja, nije metaforički naziv za more."},
  "2018_ljeto_B__4": {"B":"Sjećanje na grad ne budi miris, nego zvuk zvona, pa olfaktivni podražaj nije točan.","C":"Cjelov se peče na čelu kao taktilni dojam, ali sjećanje na rodni grad budi zvuk, ne dodir.","D":"Premda je pjesma puna slika, sjećanje izaziva čujno zvono, a ne vizualni podražaj."},
  "2018_ljeto_B__5": {"A":"'Glupost!' je uzvik samoprijekora, a ne apostrofa kojoj se subjekt obraća.","C":"Bura se spominje u nizu poredaba ('Budi vihor, bura...'), nije predmet izravnoga obraćanja.","D":"Truba je također dio niza poredaba, a ne apostrofirani pojam."},
  "2018_ljeto_B__6": {"A":"U prvoj strofi subjekt opisuje strano zvono i sjećanje, nema ohrabrivanja.","B":"U drugoj strofi subjekt zaziva bol i patnju, ne ohrabruje se.","C":"U trećoj strofi prevladavaju tišina, samoća i kajanje, dakle malodušje, ne ohrabrenje."},
  "2018_ljeto_B__7": {"A":"Troje je premalo: tekst navodi dva sina, dvije kćeri i malog sina u kolijevci.","B":"Četvero ne odgovara: ukupno je petero djece prema nabrajanju u stihovima.","D":"Šestero je previše; iz teksta proizlazi točno petero djece."},
  "2018_ljeto_B__8": {"A":"Kadiji je odveo poslije; isprva je odveden u rodni 'bijeli dvor'.","C":"Brat je odvodi iz aginog dvora, a ne u njega.","D":"Upravo se rastao s djecom; nije ih odveo k njima."},
  "2018_ljeto_B__9": {"A":"Stih govori o njezinoj nemogućnosti rastanka od djeteta, a ne o razlogu brze udaje.","C":"Stihovi izriču majčinu bol zbog djece, što je razlog protiv udaje, a ne za nju.","D":"Stih je izvan ovog ulomka i ne objašnjava razlog ponovne udaje."},
  "2018_ljeto_B__10": {"B":"Nesreća zbog Napoleonovih osvajanja nije zajednička crta; udovica i pripovjedač su naprosto nezainteresirani za razgovore.","C":"Modne novine čita samo udovica i to nemarno; pripovjedač ih ne čita.","D":"Sučevim uspjehom (kruškama) nitko od njih dvoje nije ushićen, naprotiv su ravnodušni."},
  "2018_ljeto_B__11": {"B":"Nezainteresiranost se ne iskazuje izričitim pripovjedačevim komentarom, nego deminutivnim glagolom 'čitkala'.","C":"Nema naknadnog objašnjenja kao sredstva; nemar je sažeto izražen umanjeničkim glagolom.","D":"Epitet nije nositelj značenja nemara, nego glagolska umanjenica 'čitkala'."},
  "2018_ljeto_B__12": {"A":"'Na sreću' je obična uvodna napomena bez ironijskog obrata.","C":"Rečenica iskreno iznosi pripovjedačevu zaokupljenost udovicom, bez ironije.","D":"Pripovjedač sam navodi da pita 'naivno', što je doslovan opis, a ne ironija."},
  "2018_ljeto_B__13": {"A":"Težnju visokom društvu pokazuju kćeri (Anastasie), a ne Goriot.","B":"Goriot novac troši na hirove kćeri, ne na ljubavnice.","C":"U ulomku se ne spominje njegova duhovita žena dobra ukusa."},
  "2018_ljeto_B__14": {"A":"Tvrdnja o ženidbi bez miraza nije točna jer je svaka kći imala polovicu očeva imutka kao miraz.","B":"Podržavanje Goriota u poslu nije vezano uz Delphineina muža, nego se posla odrekao na nagovor obitelji.","C":"U tekstu nema savjeta zetova Goriotu o životu od rente."},
  "2018_ljeto_B__15": {"A":"Jahanje i kočija opisuju kćerin raskošan život, ne očeve osjećaje.","C":"Sloboda izbora muža govori o kćerima, a ne o očevoj ljubavi.","D":"Spominjanje miraza materijalan je podatak, ne izraz očevih osjećaja."},
  "2018_ljeto_B__16": {"A":"Fotografija gospodina s cilindrom Filipu je živo sjećanje, nije ocijenjena kao neukus.","C":"Fotografije rođaka su nepoznata, strana lica iz albuma, ne primjer slikarskoga neukusa.","D":"Slika mlade žene u bjelini ne navodi se kao neukus; deplasiranom Filip drži Jelačića na saboru."},
  "2018_ljeto_B__17": {"A":"Zlatorezna kopča dio je albuma (korica), a ne motiv na fotografiji.","C":"Slamnati šešir ne spominje se; gospodin na fotografiji nosi visoki cilindar.","D":"Sedefna intarzija ne pojavljuje se na fotografiji u albumu."},
  "2018_ljeto_B__18": {"A":"Paljenje voštanica jednih drugima ne znači sukobe, nego trajno suživljenje na posjedu.","C":"Izraz ne govori o duljini žalovanja, nego o generacijskom nasljeđivanju posjeda.","D":"Ne radi se o susretima samo na pogrebima, nego o dugotrajnom obitavanju iste loze."},
  "2018_ljeto_B__19": {"A":"Proučavanje polinezijskih ljepota nije svrha plovidbe; brod ide po tovar kopre.","B":"Brod ne plovi da bi plašio kanibale, nego radi ukrcaja tovara.","D":"Prijevoz plesača nije svrha plovidbe 'Menelaja'."},
  "2018_ljeto_B__20": {"B":"Liječnik kuhara ne opisuje kao siromašnoga, nego ga vrijeđa zbog gluposti ('ovčji mozak').","C":"O lošoj kuhinji nema spomena; ironija se odnosi na kuharovu neinteligenciju.","D":"Cinizam se pripisuje liječnikovu izričaju, a ne kuharu kao njegovoj osobini."},
  "2018_ljeto_B__21": {"A":"Kapetan nije skuhan; ljudožderi su skuhali šefa kuhinje.","B":"Stari mornar s lulom samo je prisustvovao kuhanju, nije bio skuhan.","D":"Brodski liječnik nije žrtva kuhanja prema tekstu ulomka."},
  "2018_ljeto_B__22": {"A":"Harpagon nije kritičar društvenih odnosa, nego predmet komične karikature škrtosti.","B":"Tip suvišnoga čovjeka pripada drugim epohama; Harpagon je komični tip škrca.","C":"Lik nije idealiziran, nego ismijan pretjeravanjem njegovih mana."},
  "2018_ljeto_B__23": {"B":"Sudjelovanje u pripremama traži se od slugu, ne kao zahtjev sinu.","C":"Odvođenje sestre na sajam nije ono što Harpagon traži od sina u ovom ulomku.","D":"Pažnja na odijelo upućuje se slugama; sinu traži ljubaznost prema zaručnici."},
  "2018_ljeto_B__24": {"A":"Brindavoine je sluga kojemu Harpagon daje upute, ne komentira njegove postupke.","B":"Claude prima zaduženja od Harpagona, ali ne komentira ih.","D":"La Merluche je sluga zadužen za posluživanje, ne daje ironične komentare."},
  "2018_ljeto_B__25": {"A":"Ogorčenje zbog prolaznosti nije tema; Franz hladno planira ubrzati očevu smrt.","B":"Ljutnja na liječnike nije središte; on smišlja kako da starac prestane živjeti.","C":"Težnja skladu duše i tijela ne odgovara monologu o ubrzavanju smrti."},
  "2018_ljeto_B__26": {"B":"Gladni vuk ne pojavljuje se kao metafora za osobu koja mu smeta.","C":"Crv koji glođe nije izraz iz ulomka za starca.","D":"Spori gmizavac nije metafora kojom Franz označuje oca."},
  "2018_ljeto_B__27": {"A":"Filozofi se spominju u vezi s naukom o duši i tijelu, nisu 'krvnici' na koje upućuje izraz.","B":"Godine nisu nabrojeni 'krvnici'; riječ se odnosi na nizane osjećaje.","C":"Liječnici nisu predmet izraza 'čovjekovi krvnici'."},
  "2018_ljeto_B__28": {"A":"Podsmješljivost dadaista spominje se drugdje; nesmiljenom se naziva moć riječi nad nama.","B":"Ljudska sklonost laganju nije ono što je određeno kao nesmiljeno, nego vlast riječi.","C":"Upiranje prstom navodi se kao primjer nepouzdanosti, nije ono što se zove nesmiljenim."},
  "2018_ljeto_B__29": {"B":"Promjena značenja kroz vrijeme nije razlog koji tekst navodi za oprez prevoditelja.","C":"Zabrana izmišljanja riječi nije spomenuta kao uzrok njihova opreza.","D":"Nevjera u poslovice nije razlog; oprez proizlazi iz različitih svojstava riječi u jezicima."},
  "2018_ljeto_B__30": {"A":"Aliteracija (ponavljanje suglasnika) nije temeljni postupak teksta o riječima koje 'lažu' i 'igraju se'.","B":"Elipsa (izostavljanje) nije nosivo sredstvo teksta.","C":"Eufemizam (ublažavanje) nije osnova teksta; riječima se pripisuju ljudske osobine."},
  "2018_ljeto_B__31": {"B":"Legenda je pripovjedna (narativna) vrsta, ne diskurzivni oblik.","C":"Oda je lirska vrsta, ne diskurzivni oblik.","D":"Vic je kratka narativna (usmena) vrsta, ne diskurzivni oblik."},
  "2018_ljeto_B__32": {"B":"Pjesma od šest strofa nije definicija sestine; sestina je strofa od šest stihova.","C":"Stih od šest slogova je šesterac, a ne sestina.","D":"Stih od šest stopa je heksametar, a ne sestina."},
  "2018_ljeto_B__33": {"A":"'Ab ovo' znači započinjanje od samoga početka, suprotno uvođenju u sredinu radnje.","B":"'Deus ex machina' je neočekivano razrješenje zapleta, ne način uvođenja u radnju.","D":"'Quid pro quo' je zamjena/zabuna, nema veze s kompozicijom epskog početka."},
  "2018_ljeto_B__34": {"A":"Eufemizam je ublažavanje, a ovdje je riječ o prividnom proturječju, ne o ublažavanju.","B":"Gradacija je stupnjevanje, a ovi stihovi grade proturječje, ne postupno pojačavanje.","C":"Hiperbola je pretjerivanje, a istaknuto je proturječje (bliže = dalje), dakle paradoks."},
  "2018_ljeto_B__35": {"B":"U ovim stihovima ponavlja se misao antitezom (gore/dolje), ne ista riječ na početku stihova.","C":"Stihovi su niz nabrajanja glagola, nema anafore na početku uzastopnih stihova.","D":"Riječ je o pitanjima i odgovorima, a ne o ponavljanju iste riječi na početcima stihova."},
  "2018_ljeto_B__36": {"A":"Andromaha je Hektorova žena, a ne Odisejeva.","B":"Euridika je Orfejeva žena, ne Odisejeva.","C":"Helena je žena Menelaja i povod Trojanskoga rata, nije Odisejeva žena."},
  "2018_ljeto_B__37": {"A":"Antigonina 'sveta dužnost' nije molitva, nego pokop brata usprkos zabrani.","C":"Poslušnost vladaru upravo je ono što Antigona odbija; njezina je dužnost pokop brata.","D":"Žrtvovanje životinja nije predmet izraza; riječ je o pogrebu Polinika."},
  "2018_ljeto_B__38": {"A":"Srednjovjekovlje je obilježeno kršćanskim svjetonazorom, ne obnovom antike.","C":"Barok slijedi i nadilazi renesansu, ali nije razdoblje obnavljanja antičkih zasada.","D":"Romantizam ističe osjećaje i nacionalno, a ne preporod antike."},
  "2018_ljeto_B__39": {"A":"Beatrice je Danteova muza, ne Petrarkina.","B":"Flavia nije Petrarkina pjesnička muza.","D":"Lotta nije osoba kojoj je Petrarca posvetio Kanconijer."},
  "2018_ljeto_B__40": {"A":"Antigona je Sofoklova junakinja, nije svladala Holoferna ni spasila Betuliju.","B":"Fedra je junakinja antičke i Racineove tragedije, bez veze s Holofernom.","D":"Palada (Atena) je božica, a ne junakinja koja spašava Betuliju."},
  "2018_ljeto_B__41": {"A":"Maro je gospodar koji rasipa novac, ne lik koji ovdje filozofira o prilagodbi.","B":"Maroje je Marov otac koji traži sina, ne autor ove maksime o snalaženju.","D":"Popiva je sluga, ali navedenu životnu filozofiju izriče Pomet."},
  "2018_ljeto_B__42": {"A":"Stih 'Jur nijedna na svit vila' napisao je Hanibal Lucić, ne Gundulić.","C":"Stih o dvojici ribara iz Hvara potječe iz Hektorovićeva Ribanja, ne od Gundulića.","D":"Stih 'Blaženi čas i hip' pripada Šišku Menčetiću, ne Gunduliću."},
  "2018_ljeto_B__43": {"A":"Kačić Miošić autor je Razgovora ugodnog naroda slovinskoga, ne Satira.","C":"Katančić nije autor Satira iliti divjeg čovika.","D":"Brezovački je pisao komedije (npr. Matijaš grabancijaš dijak), ne Satira."},
  "2018_ljeto_B__44": {"B":"Gospođa Bovary pripovijeda se u trećem licu, nije epistolarni roman.","C":"Don Quijote je pustolovni (parodijski viteški) roman, ne epistolarni.","D":"Combray (Proust) je roman struje svijesti, ne epistolarni."},
  "2018_ljeto_B__45": {"A":"Prosvjetiteljstvo ističe razum i pouku, a ne dokumentaristički 'fotografski' prikaz biološki determiniranih likova.","B":"Romantizam naglašava osjećaje i maštu, suprotno opisanoj objektivnoj dokumentarnosti.","D":"Moderna donosi simbolizam i subjektivnost, ne naturalistički determinizam iz tvrdnje."},
  "2018_ljeto_B__46": {"A":"Danicu je uređivao Ljudevit Gaj, a ne Stanko Vraz.","C":"Vijenac se vezuje uz Augusta Šenou, ne uz Vraza.","D":"Zoru dalmatinsku uređivali su drugi (npr. Kuzmanić), nije Vrazov časopis."},
  "2018_ljeto_B__47": {"A":"Obračun s otmjenim društvom nije završetak Zločina i kazne, nego Raskoljnikovo iskupljenje.","C":"Junak ne umire u požaru; doživljava duhovni preporod na robiji.","D":"Raskoljnikov ne poludi na kraju, nego se preporađa kroz vjeru i ljubav."},
  "2018_ljeto_B__48": {"A":"Đuka Begović (Kozarac) ne odgovara opisu školovanja u Beču i izdaje obitelji.","C":"Juraj Stipančić nije lik koji otac šalje u Beč pa postaje propalica.","D":"Pavao Gregorijanec (Šenoa) plemić je iz Seljačke bune, ne sin kojeg otac šalje na školovanje u Beč."},
  "2018_ljeto_B__49": {"A":"Lamartine pripada romantizmu, ne modernizmu.","B":"Poe pripada romantizmu i gotici, ne modernizmu.","C":"Schiller pripada njemačkoj klasici/Sturm und Drangu, ne modernizmu."},
  "2018_ljeto_B__50": {"A":"Breton je autor nadrealističkog manifesta, ne dadaističkog.","B":"Marinetti je autor futurističkog manifesta, ne dadaističkog.","C":"Jesenjin je ruski pjesnik (imažinizam), nije autor dadaističkog manifesta."},
  "2018_ljeto_B__51": {"B":"Matoš je autor pripovijesti i lirike (Iverje, Umorne priče), ne zbirke Preobraženja.","C":"Krleža je autor Simfonija i drugih djela, ne Preobraženja.","D":"Vidrić ima jednu zbirku Pjesme, ali Preobraženja je Šimićeva zbirka."},
  "2018_ljeto_B__52": {"B":"Proučavanje arhivske građe za vjeran povijesni ambijent obilježje je Šenoe, ne Krleže.","C":"'Viški Voltaire' kojeg je tako nazvao Ujević odnosi se na drugog pisca, ne na Krležu.","D":"'Hrvatskim Balzacom' nazivali su Eugena Kumičića, ne Krležu."},
  "2018_ljeto_B__53": {"A":"Atma je u Kiklopu glumica, ne nositeljica teorije preventivne dehumanizacije.","C":"Maestro je propali boem i samoubojica, ne tvorac te filozofske teorije.","D":"Melkior Tresić je glavni lik kojemu je don Fernando svojevrsni kontrapunkt; teoriju razvija don Fernando."},
  "2018_ljeto_B__54": {"B":"Pupačić je pjesnik krugovaškoga naraštaja, ne postmodernist.","C":"Nehajev pripada hrvatskoj moderni, ne postmodernizmu.","D":"Ujević pripada moderni i avangardi, ne postmodernizmu."},
  "2018_ljeto_B__55": {"A":"Mihanović je autor Horvatske domovine (Lijepe naše), a ne navedenih stihova o crnogorskim junacima.","B":"Gundulić je barokni pjesnik (Osman, Dubravka), ne autor ovih stihova.","D":"Kranjčević je pjesnik moderne; navedeni stihovi iz su Mažuranićeva spjeva."},
  "2018_ljeto_B__56": {"A":"Pravilno je 'smjer' (kratki refleks jata), pa 'smijer' nije ispravno.","B":"Pravilno je 'zdjela', a ne 'zdijela'.","D":"Pravilno je 'sljev', a ne 'slijev'."},
  "2018_ljeto_B__57": {"B":"Pravilno je 'naličje' (č), pa 'nalićje' nije točno.","C":"Pravilno je 'optičar' (č), pa 'optićar' nije točno.","D":"Pravilno je 'svečanost' (č), pa 'svećanost' nije točno."},
  "2018_ljeto_B__58": {"A":"Pridjev 'božićnih' piše se malim slovom, pa rečenica nije pravopisno točna.","B":"'Internet' se piše malim slovom, pa rečenica nije ispravna.","C":"U navedenom naslovu 'svemirom' nije pravilno napisano velikim slovom, pa rečenica nije točna."},
  "2018_ljeto_B__59": {"A":"Razmaci oko crtice nisu dopušteni u složenom pridjevu.","B":"Pisanje bez crtice ('Latinsko američki') nije ispravno za složeni pridjev ravnopravnih osnova.","D":"'Latinskoamerički' (sastavljeno) nije pravilno; traži se crtica jer su osnove ravnopravne."},
  "2018_ljeto_B__60": {"A":"U 'junačina' k prelazi u č ispred -ina, što je palatalizacija, a ne jotacija.","B":"U 'trbuščić' provedena je sibilarizacija/glasovne promjene, ne jotacija.","C":"U 'otočanin' k prelazi u č, dakle palatalizacija, a ne jotacija."},
  "2018_ljeto_B__61": {"B":"U 'bojažljiv' nema sučeljavanja zvučnog i bezvučnog suglasnika, pa nije jednačenje po zvučnosti.","C":"Palatalizacija je promjena k/g/h pred samoglasnikom, čega ovdje nema.","D":"Sibilarizacija je promjena k/g/h u c/z/s pred i, čega u 'bojažljiv' nema."},
  "2018_ljeto_B__62": {"A":"U 'grašak' slog 'gra' ima samoglasnik a, pa r nije slogotvoran.","B":"U 'grijač' slog 'gri' ima samoglasnik i, pa r nije slogotvoran.","D":"U 'pogreška' slog 'greš' ima samoglasnik e, pa r nije slogotvoran."},
  "2018_ljeto_B__63": {"A":"Znak ´ označava kratkouzlazni naglasak, što ne odgovara izgovoru riječi 'mrav'.","B":"Znak ` označava dugouzlazni... zapravo kratkouzlazni varijantu; u 'mrav' nije uzlazni naglasak.","C":"Znak ˆ označava dugosilazni naglasak, a 'mrav' ima kratkosilazni."},
  "2018_ljeto_B__64": {"A":"Rastav 'zvje-zdar-nic-a' pogrešno cijepa korijen 'zvjezd-'.","C":"Rastav 'zvjezda-r-ni-ca' ne izdvaja ispravne tvorbene morfeme (-ar-, -nic-).","D":"Rastav 'zvjezdar-ni-ca' spaja korijen i sufiks -ar- te krivo dijeli ostatak."},
  "2018_ljeto_B__65": {"B":"'-gledni-' uključuje i dio sufiksa, nije čisti korijenski morfem.","C":"'razgled-' sadrži prefiks 'raz-', pa nije samo korijenski morfem.","D":"'razglednic-' obuhvaća prefiks i sufiks, nije korijen, nego gotovo cijela osnova."},
  "2018_ljeto_B__66": {"A":"Genitiv ne odgovara: 'svjedočiti' traži dativ (čemu), a ne genitiv.","C":"Akuzativ nije točan jer 'svjedočiti' veže dativni, a ne akuzativni objekt.","D":"Lokativ traži prijedlog; ovdje je 'pretvaranju' bez prijedloga u dativu."},
  "2018_ljeto_B__67": {"B":"Treba 'tvrdoglavog(a)' dječaka u genitivu; 'tvrdoglava' nije usklađen oblik.","C":"Uz superlativ treba određeni oblik 'najboljega', a ne 'najboljeg' u ovom kontekstu.","D":"U predikatu se traži neodređeni oblik 'ponosan', a ne 'ponosni'."},
  "2018_ljeto_B__68": {"A":"'Drhtaše' je imperfekt, a ne prezent.","B":"'Se smililo' je perfekt, a ne prezent.","C":"'Uze' je aorist, a ne prezent."},
  "2018_ljeto_B__69": {"A":"'Uzimajući' je prilog sadašnji nesvršenog glagola 'uzimati', ne od 'uzeti'.","B":"'Uzimavši' nije pravilan oblik glagolskog priloga prošloga od 'uzeti'.","D":"'Uzimljući' nije standardni oblik glagolskog priloga glagola 'uzeti'."},
  "2018_ljeto_B__70": {"A":"'Uhvatio je prije objeda' je priložna (rektivno-priložna) veza, ne sročna sintagma.","B":"'Uhvatio je priliku' je predikatno-objektna veza, dakle rekcija, a ne sročnost.","D":"'Razgovara s njim' je rektivna veza glagola i prijedložnog izraza, ne sročnost."},
  "2018_ljeto_B__71": {"B":"'Studentu' nije predikat; predikat je glagol 'propisuje'.","C":"'Studentu' nije priložna oznaka, nego neizravni objekt u dativu.","D":"Subjekt je 'Bolonjska deklaracija', a ne 'studentu'."},
  "2018_ljeto_B__72": {"B":"Četiri surečenice je previše; složena rečenica ima tri surečenice.","C":"Pet surečenica ne odgovara analizi (glavna + objektna + namjerna = tri).","D":"Šest surečenica daleko premašuje stvarni broj od tri."},
  "2018_ljeto_B__73": {"A":"Dopusna rečenica izriče suprotnost očekivanju ('iako'), čega ovdje nema.","B":"Pogodbena rečenica izriče uvjet ('ako'), a ovdje je posljedica.","D":"Uzročna rečenica izriče razlog ('jer'), a struktura 'toliko... da' izriče posljedicu."},
  "2018_ljeto_B__74": {"A":"Treba 'bez obzira na to što', pa je 'bez obzira što' pogrešno.","B":"'Zato jer' nije pravilno; treba 'zato što'.","D":"Treba 'budući da'; 'budući' bez 'da' nije ispravno."},
  "2018_ljeto_B__75": {"A":"'Sklonidba' nije vrsta padeža, nego postupak mijenjanja po padežima.","B":"'Imenica' je vrsta riječi, nije podvrsta pojma 'padež'.","D":"'Nastavak' je morfem, nije vrsta padeža, pa nije hiponim riječi 'padež'."},
  "2018_ljeto_B__76": {"A":"Antonimija je suprotnost značenja, a ovdje su dva povezana značenja iste riječi.","B":"Homonimija pretpostavlja nepovezana značenja, dok su ova dva (doslovno i preneseno) povezana.","D":"Sinonimija je istoznačnost dviju riječi, a ovdje je jedna riječ s dvama značenjima."},
  "2018_ljeto_B__77": {"A":"Arhaizam je zastarjela riječ za pojam koji još postoji, a surka označava nepostojeći predmet.","C":"Neologizam je nova riječ, a 'surka' je naziv za stari, iščezli odjevni predmet.","D":"Zastarjelica je riječ izišla iz uporabe za postojeći pojam; surka je vezana uz pojam koji više ne postoji, pa je historizam."},
  "2018_ljeto_B__78": {"B":"Posuđenice iz španjolskoga su hispanizmi, ne luzitanizmi.","C":"Posuđenice iz francuskoga su galicizmi, ne luzitanizmi.","D":"Posuđenice iz češkoga su bohemizmi, ne luzitanizmi."},
  "2018_ljeto_B__79": {"A":"'Medvjeđa usluga' znači uslugu koja više šteti nego koristi, ne posljednje važno djelo.","B":"'Glineni golub' ne znači posljednji važan rad pred kraj stvaranja.","D":"'Lavlji dio' znači najveći dio nečega, ne posljednje važno djelo."},
  "2018_ljeto_B__80": {"A":"Kašićevo djelo nije jezični savjetnik, nego gramatika.","C":"Djelo nije pravopis, nego prva hrvatska gramatika.","D":"Djelo nije rječnik; Kašić je rječnik radio zasebno, a ovo je gramatika."},

  // 2019_jesen_A
  "2019_jesen_A__1": {"A":"Lirski subjekt ne tumači lavež kao jadikovku zbog straha od smrti, nego kao uzaludan, jalov posao ('zaludu').","B":"Lavež nije prikazan kao korisno upozorenje na opasnost, nego kao besmislen i bezuman ('laju glupo, uludo').","C":"U pjesmi nema motiva želje za slobodom; psi su upravo na lancu i bespomoćno čekaju sudbinu."},
  "2019_jesen_A__2": {"A":"Motiv psa povezan je s laježom (auditivni), a ne s mirisom, pa nije naglašen olfaktivnim podražajem.","B":"Motiv koraka dočaran je zvukom ('odjeknu li korak'), dakle auditivnim, a ne olfaktivnim podražajem.","D":"Motiv lampe vezan je uz vid ('lampa tiho žmirka'), dakle vizualni je, a ne olfaktivni podražaj."},
  "2019_jesen_A__3": {"B":"Usporedba 'kao sjena slijepa' ne odnosi se na prolaznike, nego na pse koji na lancu čekaju sudbinu.","C":"Lanac je sredstvo kojim su psi vezani, a usporedba se odnosi na pse, a ne na sam lanac.","D":"Sudbina je ono što psi čekaju, a ne ono na što se odnosi usporedba 'kao sjena slijepa'."},
  "2019_jesen_A__4": {"A":"Lirski subjekt se ne ispričava zbog rastuživanja djevojke, nego se oprašta od nje zbog svoga odlaska.","B":"Lirski subjekt sam odlazi ('sila mi je putovati'); nije ga djevojka napustila.","C":"Bog se spominje samo u oproštajnoj želji ('Bog da nam bude u družbu'), ali tema nije molitva za pomoć na putu."},
  "2019_jesen_A__5": {"A":"Stih iznosi plač, suze i tužbu lirskoga subjekta (muškarca), a ne djevojčine osjećaje.","B":"Stih govori o tome kako je lirski subjekt ucvilio djevojku, a ne o njezinim vlastitim osjećajima.","C":"Riječ je o tuzi lirskoga subjekta ('mâ najveća'), dakle o njegovim, a ne djevojčinim osjećajima."},
  "2019_jesen_A__6": {"A":"Stih ne govori o duljini djevojčina života, nego o trajnosti zavjeta lirskoga subjekta.","B":"Glagol 'služiti' ovdje znači predanu odanost, a ne tek uslužnost; naglasak je na obećanju vjernosti.","D":"Stih izriče obećanje odanosti ('dadoh vjeru'), a ne to da on vjeruje dragoj."},
  "2019_jesen_A__7": {"A":"Ulomak ne tematizira nesposobnost aginih podanika, nego sam noćni okršaj i napad na Turke.","C":"Riječ je o napadu Vlaha na Turke u tami, a ne o sukobu age i Safera.","D":"Mirko se kao tema ne ističe; središte je napad na tursku vojsku tijekom noći."},
  "2019_jesen_A__8": {"A":"Zamjenica se ne odnosi na Mirka; iz konteksta 'posjest aga' jasno je da pada aga.","B":"Hasan nije onaj koga pokriva zamjenica; padom je pogođen aga.","C":"Safer je doduše ranjen drugdje u ulomku, ali ova zamjenica označava agu koji pada."},
  "2019_jesen_A__9": {"A":"Stihovi ne govore o naoružanju, nego o malenoj udaljenosti među protivnicima u tami.","C":"Susret nije opisan kao slučajan, nego se naglašava da su protivnici neočekivano blizu jedni drugima.","D":"Stihovi ne ističu borbu do smrti, nego neposrednu blizinu protivnika ('na dohvatu noža')."},
  "2019_jesen_A__10": {"A":"Tekst kaže suprotno: Mišocija se rijetko viđa u uredu jer ponajviše 'ureduje' u krčmi.","C":"Mišoci nije uključen u rad sabora; on je seoski bilježnik koji guli narod.","D":"U ulomku nema podatka da je Mišoci htio postati župan."},
  "2019_jesen_A__11": {"B":"Razlog nisu veze preko ugledne žene, nego to što tajno dostavlja izvješća vlastima.","C":"Mišoci ne brine o siromašnima, nego ih upravo 'guli' i pobire takse.","D":"Crkvene ga vlasti ne podupiru; vlasti ga puštaju na miru jer im je doušnik."},
  "2019_jesen_A__12": {"A":"Primjer opisuje Mišocijeve navike (lula, piće), ali nije karikatura jer ne preuveličava njegov izgled.","B":"Primjer iznosi Mišocijev pohlepan postupak, ali nema groteskno preuveličanoga fizičkog opisa.","C":"Primjer prikazuje Mišocijevu izjavu i raskoš, ali nije karikatura tjelesnoga izgleda lika."},
  "2019_jesen_A__13": {"A":"Thérèse ne suosjeća sa starenjem uzvanika, nego prema njima osjeća gađenje i prezir.","B":"Migrenu ona izmišlja kao izgovor; ne tvrdi se da joj je prisutnost uzvanika uvijek izaziva.","C":"Thérèse se ne skriva u podrum, nego sjedi u kutu i promatra uzvanike s gađenjem."},
  "2019_jesen_A__14": {"A":"Izraz 'starci koji su podjetinjili' odnosi se na pojedinca (Michauda), a ne na sve uzvanike.","C":"'Neizreciva tjeskoba' označava Thérèsin osjećaj, a ne sve uzvanike.","D":"'Pusta groza' opisuje njezino raspoloženje, a ne skup svih uzvanika."},
  "2019_jesen_A__15": {"B":"Gustativni (okusni) podražaj ne pojavljuje se kao razlog Thérèsina raspoloženja; oraspoloži je zvuk zvončića.","C":"Olfaktivni (mirisni) podražaj nije ono što je oraspoloži; presudan je auditivni doživljaj zvona.","D":"Taktilni (dodirni) podražaj nije razlog njezina olakšanja; raduje je zvuk koji najavljuje kraj primanja."},
  "2019_jesen_A__16": {"B":"U ulomku nema spomena K.-ove želje za skorom mirovinom; misli su mu okupljene oko predstavke.","C":"Ne kaže se da se K. pribojava zamjenika ravnatelja; tekst govori o pisanju predstavke.","D":"Riječ nije o želji za napredovanjem, nego o nuždi da napiše predstavku i prenu se iz misli."},
  "2019_jesen_A__17": {"B":"Tekst sugerira suprotno: vrlo je vjerojatno da K. u uredu neće naći vremena za pisanje.","C":"K. ne odgađa pisanje do mirovine; predstavku mora napisati odmah, makar noću kod kuće.","D":"Odvjetnik nije dovršio predstavku; K. je sam mora napisati."},
  "2019_jesen_A__18": {"A":"K. ne ističe strahopoštovanje prema nadređenima, nego upornost i ustrajnost u poslu.","C":"Promućurnost se spominje kao osobina koja je spriječila dovršenje, a ne kao vrlina koju K. veliča.","D":"Hrabrost nije osobina koju K. ističe; naglašava da se ne smije stati na pola puta."},
  "2019_jesen_A__19": {"A":"Pratitelji se ne suprotstavljaju Rokovu izboru cilja; oni su ravnodušni i samo žude za odmorom.","B":"Među pratiteljima nema prepiranja o smjeru; prepuštaju izbor Roku.","C":"Pratitelji ne žele novoga vođu; pasivno slijede Roka i čeznu za odmorom."},
  "2019_jesen_A__20": {"B":"'Hiniti' ne znači prezirati; znači pretvarati se, glumiti.","C":"'Hiniti' ne znači prihvaćati; znači lažno prikazivati, glumiti.","D":"'Hiniti' ne znači priželjkivati; znači praviti se, simulirati."},
  "2019_jesen_A__21": {"A":"Pratitelji nisu zahvalni Roku; prema putu su ravnodušni, a ne zahvalni.","C":"Ne pita se za Gradinu; tekst naglašava da nitko nije ni pitao gdje se nalaze.","D":"Put i cilj nisu bili jasni; vladala je posvemašnja ravnodušnost i neznanje o položaju."},
  "2019_jesen_A__22": {"A":"Povjeravanje Elektre Strofiju nije ono što seljak kaže o Agamemnonu; to nije dio njegova iskaza.","B":"Agamemnon nije doveo Prijama u Arg; on je ubio Prijama u Troji.","D":"Agamemnon nije prepustio vlast Orestu; vlast je nakon njegove smrti preuzeo Egist."},
  "2019_jesen_A__23": {"A":"Razlog nije nedostojnost prosaca, nego Egistov strah od osvetnika koji bi se mogao roditi.","B":"Elektrina dob nije navedena kao razlog; Egist je odbija udati zbog straha od osvete.","C":"Egist je nije odlučio prognati, nego ju je zadržao u kući neudanu, bojeći se osvete."},
  "2019_jesen_A__24": {"A":"Seljakov ugled ne umanjuje tjelesna slabost; on sam ističe da mu siromaštvo potire lozu.","B":"Podrijetlo mu je odlično ('rod odličan'), pa ga mikensko podrijetlo ne umanjuje.","C":"Rod mu nije neplemenit; izričito kaže da je 'rod odličan', samo siromašan."},
  "2019_jesen_A__25": {"A":"Don Zane ne voli don Florija zato što je isposnik; štoviše, on naglašava da 'nijesmo eremite'.","B":"Razlog naklonosti nije zaigranost, nego don Florijeva iskrenost i to što ne licemjeri.","D":"Don Floriju je drag zbog iskrenosti, a ne zbog starosti."},
  "2019_jesen_A__26": {"B":"Naziv 'glava od kupusa' don Florijo nije upotrebljavao za cirkusanta, nego za biskupa (presvijetlog).","C":"'Glava od kupusa' ne odnosi se na glumca, nego na biskupa s kojim se don Florijo pomirio.","D":"Isposnik nije onaj koga je tako nazivao; pogrdni se nadimak odnosio na biskupa."},
  "2019_jesen_A__27": {"B":"'Presvijetli ga je zvao' je obavijesna rečenica bez ironije.","C":"Iskaz o Flokiju nije ironičan, nego pohvalan u doslovnom smislu.","D":"'Vanredno! Čudo jedno!' izriče stvarno čuđenje, a ne ironiju usmjerenu na sebe i kolege."},
  "2019_jesen_A__28": {"A":"Tekst ne tvrdi da se teme djela temelje na anketama; on suprotno kaže da je anketa preuzela ulogu romana.","B":"Ne govori se o prikazivanju života slavnih osoba u suvremenoj književnosti.","D":"Ne tvrdi se da pisci crpe građu iz mitova i legenda; riječ je o promijenjenoj ulozi književnosti."},
  "2019_jesen_A__29": {"A":"Metafora pleksiglasa ne govori o izgradnji društvene savjesti, nego o izloženosti umjetnika javnosti.","B":"Ne radi se o udaljavanju od tradicionalne umjetnosti, nego o vidljivosti i prisutnosti u javnosti.","C":"Pleksiglas znači prozirnost i izloženost pogledima, a ne zaštitu od vanjskih utjecaja (zapravo obrnuto)."},
  "2019_jesen_A__30": {"B":"'Žurnokracija' ne označava radijus djelovanja književnosti, nego vladavinu brzine i medija.","C":"Pojam se ne odnosi na utjecaj književnosti na društvenu savjest, nego na prevlast brzine i publiciteta.","D":"Pojam ne govori o umjetničkim dosezima pisaca, nego o užurbanom, medijima vođenom dobu."},
  "2019_jesen_A__31": {"A":"Stihovi ponavljaju samo početak ('Mukom muče'), što je anafora, a ne simploka (nema i istog završetka).","B":"Ponavlja se isključivo završetak ('rodiše se tudijer'), pa je riječ o epifori, a ne o simploci.","D":"Ponavlja se samo riječ na kraju i početku susjednih stihova ('večerati'), što je anadiploza, a ne simploka."},
  "2019_jesen_A__32": {"A":"Eufemizam je ublažavanje neugodnoga pojma; ovdje toga nema, nego nizanje veznika.","B":"Ironija znači reći suprotno od mišljenoga; u ulomku se ne pojavljuje, dominira nizanje veznika.","C":"Onomatopeja oponaša zvukove; u ulomku takvih riječi nema, naglašeno je nabrajanje veznikom 'i'."},
  "2019_jesen_A__33": {"A":"Ditiramb je zanosna pjesma u čast Dionizu, a ne kratka duhovita pjesma s poantom.","C":"Elegija je tužna, sjetna pjesma, a ne duhovita forma s neočekivanim zaključkom.","D":"Oda je svečana hvalospjevna pjesma, a ne sažeta duhovita pjesma s poantom."},
  "2019_jesen_A__34": {"A":"Dvostruko rimovani dvanaesterac temelji se na broju slogova i rimi, a ne na duljini slogova.","B":"Simetrični osmerac je silabički stih (broj slogova), a ne kvantitativni.","C":"Epski deseterac je silabički stih hrvatske usmene poezije, a ne kvantitativna versifikacija."},
  "2019_jesen_A__35": {"A":"Balada pripada lirsko-epskomu rodu, a ne diskurzivnomu.","B":"Farsa je dramska vrsta (komedija), a ne diskurzivni žanr.","D":"Legenda pripada epskomu rodu, a ne diskurzivnomu."},
  "2019_jesen_A__36": {"A":"Ahilej nije lik koji je oženio vlastitu majku; stihovi pripadaju Edipu.","C":"Kreont nije počinio incest niti je tako oslovljavao djecu; riječ je o Edipu.","D":"Prometej je titan kažnjen zbog krađe vatre, a ne otac vlastitih polubraće; stihovi su Edipovi."},
  "2019_jesen_A__37": {"A":"Ilijada nije nazvana po vojskovođi, nego prema gradu Iliju (Troji).","B":"Naziv ne potječe od imena božanstva, nego od imena grada.","C":"Naziv ne dolazi od imena naroda, nego od grada Ilija."},
  "2019_jesen_A__38": {"A":"Horacije je pisao ode i satire, a nije autor epa o bjeguncu iz Troje.","B":"Katul je rimski lirik, a nije napisao ep o Eneji.","C":"Ovidije je autor Metamorfoza, a ne epa o junaku koji osniva novi grad."},
  "2019_jesen_A__39": {"A":"Pjesan o Rolandu pripada francuskoj književnosti, a ne španjolskoj.","C":"Kalevala je finski nacionalni ep, a ne španjolski.","D":"Beowulf je staroengleski ep, a ne španjolski."},
  "2019_jesen_A__40": {"A":"Gomilanje stilskih figura obilježje je baroka, a ne renesanse.","B":"Naglašena religioznost značajka je srednjega vijeka i baroka, a ne renesanse koja ističe antičke ideale.","D":"Sklonost iracionalnomu obilježava romantizam, a ne renesansu kojoj je svojstven sklad i razum."},
  "2019_jesen_A__41": {"A":"U Ranjininu zborniku ne prevladava domoljubna lirika, nego ljubavna.","C":"Refleksivna lirika nije dominantna; zbornik je poznat po ljubavnim pjesmama.","D":"Religiozna lirika nije pretežita; prevladavaju ljubavni stihovi dubrovačkih petrarkista."},
  "2019_jesen_A__42": {"A":"Marulićeva Judita počinje zazivom i prikazom biblijske teme, a ne motivom mračne šume.","B":"Petrarcin Kanconijer je zbirka soneta, a ne spjev koji počinje 'na pola životnoga puta'.","C":"Boccacciov Dekameron je zbirka novela u proznom okviru, a ne ovaj stihovani početak."},
  "2019_jesen_A__43": {"A":"Dugi Nos je negromant koji govori prolog, a ne lik koji izlaže filozofiju o 'ljudima nazbilj i nahvao'.","B":"Maro Marojev je rasipni sin, a ne onaj koji iznosi ovu životnu filozofiju.","D":"Ugo Tudešak je Marov drug, Nijemac, a ne autor ovih riječi; riječ je o Pometu."},
  "2019_jesen_A__44": {"A":"Renesansu obilježava sklad i vedrina, a ne barokna tema prolaznosti i stilska bujnost.","C":"Klasicizam ističe razum i jasnoću, a ne baroknu raskoš i motiv ništavnosti svijeta.","D":"Romantizam naglašava osjećaje i individualizam, a ne baroknu temu taštine svijeta."},
  "2019_jesen_A__45": {"B":"Realistički roman ne traži didaktičnost i moralističnog junaka, nego objektivan prikaz stvarnosti.","C":"Romantičarska poema ističe osjećaje i iznimnog junaka, a ne moralističko-racionalni kriterij.","D":"Simbolistička novela počiva na simbolu i sugestiji, a ne na didaktičnosti i racionalnosti."},
  "2019_jesen_A__46": {"A":"Cervantes je u Don Quijoteu ismijavao viteške romane, a ne ideju 'najboljega od svih svjetova'.","B":"Molière je satirizirao ljudske mane u komedijama, a ne Leibnizov optimizam.","D":"Shakespeare nije ismijavao tezu o najboljemu svijetu; to je učinio Voltaire u Candideu."},
  "2019_jesen_A__47": {"B":"Naivni mladić koji nailazi na sveprisutno zlo je Candide, a ne Pečorin.","C":"Opis ljubitelja životinja koji pod alkoholom čini zlo odgovara liku iz 'Crnoga mačka', a ne Pečorinu.","D":"Sukob s ocem zbog škrtosti i ljubavnoga suparništva nije Pečorinova priča."},
  "2019_jesen_A__48": {"A":"Posljednji Stipančići ne počinju ovim opisom Gradeca u 16. stoljeću.","B":"Nehajevljev Bijeg ne počinje ovom rečenicom o crkvi Sv. Marka.","D":"U registraturi Ante Kovačića ne otvara se ovim povijesnim opisom Zagreba 16. stoljeća."},
  "2019_jesen_A__49": {"A":"Dostojevskoga obilježava psihološka analiza i filozofske teme, a ne 'smijeh kroz suze' i groteska.","B":"Turgenjeva odlikuju lirski opisi prirode i likovi 'višnjeg čovjeka', a ne groteska i fantastika.","D":"Tolstoja karakteriziraju epska širina i moralna pitanja, a ne groteska i smijeh kroz suze."},
  "2019_jesen_A__50": {"B":"Đuro Andrijašević je intelektualac iz Nehajevljeva Bijega, a ne otupjeli bećar iz ovoga opisa.","C":"Ivica Kičmanović je ambiciozni mladić iz 'U registraturi', a ne ravnodušni lik prikazan u rečenicama.","D":"Krsto Brodnjak nije lik kojega obilježava tupost i bećarski život opisan u ulomku."},
  "2019_jesen_A__51": {"A":"Dadaizam je antiumjetnički pokret igre i besmisla, a ne pravac vezan uz motiv krika i strave.","B":"Egzistencijalizam je filozofsko-književni pravac o slobodi i tjeskobi, a 'krik' se vezuje uz ekspresionizam.","D":"Nadrealizam istražuje podsvijest i snove, a motiv krika osamljenog pojedinca pripada ekspresionizmu."},
  "2019_jesen_A__52": {"A":"Preobražaj počinje pretvorbom Gregora Samse u kukca, a ne doživljajem čaja i kolačića.","B":"'Crni mačak' tematizira zločin i grižnju savjesti, a ne prustovsko buđenje sjećanja okusom.","D":"Stranac počinje viješću o majčinoj smrti, a ne scenom s čajem i mrvicama kolača."},
  "2019_jesen_A__53": {"A":"Odnos bogatih i siromašnih nije tema Kratkog izleta; roman govori o raspadanju zajednice.","C":"Odlazak iz domovine nije tema djela; riječ je o putovanju u Gradinu i otuđenju skupine.","D":"Sukob sela i grada nije tema Kratkog izleta, nego raspad zajedništva putnika."},
  "2019_jesen_A__54": {"A":"Bukara ne igra Hamleta; stihovi o 'strašnom kralju' na vlasti pripadaju ulozi Klaudija.","C":"Laert nije kralj; opis 'strašnoga kralja' odgovara Klaudiju, a ne Laertu.","D":"Polonije je kraljev savjetnik, a ne sam kralj; Bukara glumi Klaudija."},
  "2019_jesen_A__55": {"A":"Antun Branko Šimić piše slobodnim stihom o smrti i tijelu, ali ovi stihovi nisu njegovi.","B":"Josip Pupačić poznat je po pjesmi 'More', a ovi stihovi nisu njegovi.","D":"Tin Ujević piše drukčijim izrazom; navedeni stihovi pripadaju Juri Kaštelanu."},
  "2019_jesen_A__56": {"A":"'Rasčetvoriti' je netočno jer se s ispred č jednači u š (raščetvoriti).","C":"'Razčetvoriti' je netočno jer z ispred bezvučnoga č prelazi u š (raščetvoriti).","D":"'Ražčetvoriti' je netočno; pravilan je oblik 'raščetvoriti'."},
  "2019_jesen_A__57": {"B":"Nije obje točno: pravilno je 'presjeći', ali glagol nesvršeni glasi 'presijecati', a ne 'presjecati'.","C":"Nije obje točno: pravilno je 'prorijediti', a ne 'prorjediti'.","D":"Nije obje točno: pravilno je 'proslijediti', a ne 'prosljediti'."},
  "2019_jesen_A__58": {"A":"'Gol-razlika' nije pravilno; piše se sastavljeno - golrazlika.","B":"'Euro-zastupnik' nije pravilno; pravilno je 'eurozastupnik' (prefiksoid se piše sastavljeno).","D":"'Mini-golf' nije pravilno; piše se sastavljeno - minigolf."},
  "2019_jesen_A__59": {"A":"Pogrešno: pravilno je 'Zapadno Rimsko Carstvo' (pridjev 'zapadno' malim slovom kad nije dio službenog imena).","B":"Pogrešno: u nazivu ulice 'sveti' se piše malim slovom - Ulica svetoga Dominika.","C":"Pogrešno: pravilno je 'Hrvatski sabor' (druga riječ malim slovom)."},
  "2019_jesen_A__60": {"B":"U riječi 'ratar' nema nepostojanoga a; genitiv glasi 'ratara', samoglasnik se ne gubi.","C":"U riječi 'urar' nema nepostojanoga a; genitiv je 'urara'.","D":"U riječi 'zidar' nema nepostojanoga a; genitiv je 'zidara'."},
  "2019_jesen_A__61": {"A":"U 'kruh > kruščić' provedeno je jednačenje po mjestu tvorbe (h+č), a ne po zvučnosti.","B":"U 'mjesec > mjesečina' radi se o palatalizaciji (c→č), a ne o jednačenju po zvučnosti.","C":"U 'težak > teška' provedeno je jednačenje po zvučnosti (ž→š), no traženi je primjer 'vožnja'; ovdje je glas ispred bezvučnoga k, dok zadatak traži primjer D koji je naveden kao točan."},
  "2019_jesen_A__62": {"A":"U riječi 'ljepòtu' naglasak nije na prvom slogu.","B":"U riječi 'proljétnoga' naglasak nije na prvom slogu.","D":"U riječi 'pomútila' naglasak nije na prvom slogu."},
  "2019_jesen_A__63": {"A":"'Ako' je veznik koji nosi naglasak, dakle nije nenaglasnica.","B":"'Sad' je naglašeni prilog, a ne nenaglasnica.","C":"'Ti' je u ovoj rečenici naglašena osobna zamjenica (subjekt), a ne nenaglasnica."},
  "2019_jesen_A__64": {"B":"Raščlamba 'brod-o-strojar-sk-i' je netočna jer 'strojar' valja dalje rastaviti na stroj- + -ar-.","C":"Raščlamba 'brod-o-stroj-ar-ski' je netočna jer se '-ski' dijeli na sufiks -sk- i nastavak -i.","D":"Raščlamba 'brod-o-strojar-ski' je netočna jer nisu izdvojeni sufiks -ar- ni nastavak -i."},
  "2019_jesen_A__65": {"A":"'Kliješta' su pluralia tantum (gradivno-konkretna), a ne zbirna imenica.","B":"'Obojica' je brojevna imenica, a ne zbirna.","D":"'Soli' je oblik gradivne imenice 'sol', a ne zbirna imenica."},
  "2019_jesen_A__66": {"B":"'Lašcom' je netočno jer imenica 'lažac' u instrumentalu ima nastavak -em, a ne -om.","C":"'Lažcem' je netočno jer ž ispred c prelazi u š (jednačenje po mjestu tvorbe → lašcem).","D":"'Lažcom' je dvostruko netočno: pogrešan nastavak (-om) i izostalo jednačenje (ž→š)."},
  "2019_jesen_A__67": {"A":"'Onaj' je muški rod jednine, a podcrtano 'ih' upućuje na ženski rod množine (one).","C":"'Oni' je muški rod množine, a iz 'prolazile' (ž.r.) slijedi nominativ 'one'.","D":"'Ono' je srednji rod jednine, što ne odgovara množinskome 'ih' (one)."},
  "2019_jesen_A__68": {"A":"'Suhlji' nije pravilan komparativ pridjeva 'suh'.","B":"'Suhiji' nije pravilan komparativ; ne dodaje se -iji.","C":"'Sušiji' nije pravilan oblik; pravilan je komparativ 'suši'."},
  "2019_jesen_A__69": {"A":"'Vidila' nije u skladu sa standardom; pravilno je 'vidjela'.","B":"'Živili' nije pravilno; standardni je oblik 'živjeli'.","C":"'Htjeo' nije pravilno; standardni je oblik 'htio'."},
  "2019_jesen_A__70": {"A":"'Tiho' je ovdje pridjev (imenski predikat uz 'je'), a ne prilog.","B":"'Valovito' je pridjev u imenskom predikatu ('more je valovito'), a ne prilog.","C":"'Uzorano' je glagolski pridjev trpni u predikatu, a ne prilog."},
  "2019_jesen_A__71": {"A":"'U mjestu Fužine' rezultat je sročnosti/apozicijske veze, a ne pridruživanja.","C":"'Gnijezda ptica' je rezultat upravljanja (rekcije), a ne pridruživanja.","D":"'Djelić sreće' je rezultat upravljanja (genitivna dopuna), a ne pridruživanja."},
  "2019_jesen_A__72": {"B":"U 'uzela je svoje dijete' imenica 'dijete' je objekt, a ne subjekt.","C":"U 'uživala je kao dijete' 'dijete' je dio poredbene konstrukcije, a ne subjekt.","D":"U 'bio je dijete' imenica 'dijete' je imenski dio predikata, a ne subjekt."},
  "2019_jesen_A__73": {"A":"Tri surečenice je premalo; rečenica ima četiri surečenice.","C":"Pet surečenica je previše; u rečenici ih je četiri.","D":"Šest surečenica je previše; rečenica ima samo četiri surečenice."},
  "2019_jesen_A__74": {"A":"Rečenica s 'koji utječe' je odnosna (atributna), a ne dopusna.","C":"Rečenica s veznikom 'jer' je uzročna, a ne dopusna.","D":"Rečenica sa 'što' je izrična (objektna), a ne dopusna."},
  "2019_jesen_A__75": {"A":"'S obzirom da' nije pravilno; treba 's obzirom na to da'.","C":"'Radi' označava namjeru, a za uzrok gubitka treba 'zbog'.","D":"'Nasuprot tebe' nije pravilno; nakon 'nasuprot' dolazi dativ - 'nasuprot tebi'."},
  "2019_jesen_A__76": {"A":"Glagol nije jednoznačan; mnogi glagoli imaju više značenja (višeznačni su).","C":"Usklik nosi promjenjivo emocionalno značenje ovisno o kontekstu, pa nije primjer jednoznačnoga leksema.","D":"Zamjenica upućuje na različite referente, pa nije jednoznačan leksem."},
  "2019_jesen_A__77": {"A":"'Izvor' i 'vrelo' nisu u odnosu nadređenosti i podređenosti, nego imaju isto značenje (sinonimi).","B":"Nisu homonimi jer im se značenje podudara, a ne samo oblik.","C":"Nisu antonimi jer ne znače suprotno, nego isto."},
  "2019_jesen_A__78": {"A":"'Besposlen' je nastao prefiksalnom tvorbom (bes- + poslen), bez sufiksa, pa nije prefiksalno-sufiksalan.","B":"'Dvoznačan' je nastao slaganjem sa sufiksom (složeno-sufiksalna), a ne prefiksalno-sufiksalnom tvorbom.","D":"'Prohladan' je nastao prefiksalnom tvorbom od 'hladan', a ne prefiksalno-sufiksalnom."},
  "2019_jesen_A__79": {"B":"'Suši' nije eponim; riječ je preuzeta kao naziv jela, a ne nastala od osobnog imena.","C":"'Beč' je egzonim (domaći naziv stranoga grada), a ne eponim.","D":"'Jadro' je vlastito ime rijeke (hidronim), a ne eponim nastao od osobnoga imena."},
  "2019_jesen_A__80": {"B":"Hrvatski vukovci zagovarali su fonološki pravopis i nove nastavke, a ne stare padežne nastavke s -ah.","C":"Zadarska filološka škola zalagala se za ikavicu i čakavsko-štokavsku osnovicu, a ne za nastavak -ah u gen. mn.","D":"Riječka filološka škola (Kurelac) imala je arhaizirajuća rješenja, ali opis s -ah u gen. mn. obilježje je zagrebačke škole."},

  // 2019_jesen_B
  "2019_jesen_B__1": {"B":"Pjesma ne prikazuje viziju pogreba kao temu nego pjesnikovo uvjerenje da smrt nije kraj; pogreb je tek povod.","C":"Lirski subjekt ne strahuje od prolaznosti, nego je smireno nadilazi tvrdnjom 'za mene smrt i nije'.","D":"Subjekt izrijekom odbacuje uskrsnuće ('Uskrsnut neću'), pa vjera u uskrsnuće nije tema."},
  "2019_jesen_B__2": {"B":"O zaboravu nema riječi; naprotiv, subjekt će 'smijehom sna' raspršiti uspomene, ali to nije zaborav koji smrt donosi.","C":"Smrt je opisana kao oslobođenje od patnji, a ne kao donošenje patnje.","D":"Subjekt izrijekom kaže da nad njim neće naricati ('niti će naricat žene'), pa smrt ne rastužuje žive."},
  "2019_jesen_B__3": {"B":"Svijeća se samo spominje (neće gorjeti), bez pripisivanja ljudskih osobina, pa nije personificirana.","C":"Uspomene su predmet radnje subjekta ('raspršim uspomene'), a ne nositelj ljudskih svojstava.","D":"Srce/srca u pjesmi ('rasut ću sebe u srca mnoga') nisu personificirana, nego označavaju ljude."},
  "2019_jesen_B__4": {"A":"Subjekt na kraju ne zna presuditi je li ljepota ili um vredniji ('ne vim reć'), pa ne tvrdi da je unutarnja ljepota važnija.","C":"Nakit se ne spominje; istaknute su kose, oči i lice kao prirodna ljepota, a ne ukrasi.","D":"Strah od prolaznosti ljepote u pjesmi nije izražen; ton je divljenje, a ne zabrinutost."},
  "2019_jesen_B__5": {"A":"Oči su uzrok zanesenosti ('oči kê sarca zanose'), a ne oni koji su očarani.","C":"Dika označava krasotu/dražest obraza, a ne ljude očarane ljepotom.","D":"Narav je personificirana sila koja je 'lipe ukaza', a ne očarani ljudi."},
  "2019_jesen_B__6": {"A":"U pjesmi nema motiva suparništva ni ljubomore, nego promjene suda o gospoji.","B":"Iako se subjekt divi gospoji, pitanje traži obilježje koje proizlazi iz promjene mišljenja, a to je prevrtljivost, ne tek oduševljenje.","D":"Subjekt ne pokazuje zabrinutost; dvojba je samo oko toga je li gospoja ljepša ili umnija."},
  "2019_jesen_B__7": {"A":"Stiskanje voska žilavim rukama posljedica je topljenja, a ne demonstracija snage radi nje same.","C":"Hiperion Helije spominje se drugdje kao bog sunca i nema veze s topljenjem voska.","D":"Vosak nije služio za oblijepljivanje lađe nego za začepljivanje ušiju mornarima."},
  "2019_jesen_B__8": {"A":"Bog mora je Posejdon, a ne Helije.","B":"Bog pjesništva je Apolon, ne Helije.","D":"Bog vjetra je Eol, a ne Helije."},
  "2019_jesen_B__9": {"A":"Tekst kaže da je vjetar utihnuo i nastala tišina, pa mornari nisu čekali povoljnije uvjete nego su sjeli za vesla.","B":"Uši su im upravo začepljene voskom da ne čuju Sirene, pa se s njima nisu dovikivali.","C":"O kupanju u moru nema spomena; mornari su veslali."},
  "2019_jesen_B__10": {"A":"Holofernova vojska napada Betuliju, a ne stanuje u njoj.","B":"Narod moapski nije stanovnik Betulije; spominju se kao dio okolnih naroda, ne Betuljani.","C":"Sinovi Ezavovi nisu stanovnici Betulije; branitelji su sinovi Izraelovi."},
  "2019_jesen_B__11": {"A":"Savjet je upravo suprotan: ne bori se u otvorenoj bitki, pa ni napad s uzvisina nije predložen.","C":"Napad kopljima podrazumijeva izravnu borbu, koju savjetnici izrijekom odgovaraju.","D":"Predloženo je presijecanje vode (žeđu skončati), a ne trovanje vode."},
  "2019_jesen_B__12": {"A":"Betuljani nisu pobjegli u planine, nego su pograbili oružje i ostali na straži.","C":"Po vodu nisu išli; to je dio Holofernova plana, a ne reakcija Betuljana.","D":"Betuljani nisu bacali koplja, nego su upalili luči na kulama i stražarili."},
  "2019_jesen_B__13": {"B":"Naprotiv, mnogi su mu se konji svidjeli ('mnogi mu se jako svidješe'), pa nezadovoljstvo izborom nije razlog.","C":"Starica se pojavljuje poslije, u sklopu prijevare, a nije razlog što nije kupio konja.","D":"U ovom ulomku novac mu još nije ukraden; krađa slijedi kasnije."},
  "2019_jesen_B__14": {"A":"Pretjerivanje pri cjenkanju nije istaknuto kao neopreznost; problem je javno pokazivanje novca.","B":"Pomoć drugih trgovaca ne spominje se kao njegova pogreška.","C":"Slušanje krčmarevih naputaka odnosi se na odlazak na sajam, a ne na neopreznost."},
  "2019_jesen_B__15": {"A":"Tekst ne kaže da je Sicilijanka prva uočila novac; ona se preko starice raspituje o Andreucciu.","B":"Starica nije puštena naprijed da upozna Andreuccia; djevojka nju ispituje o njemu.","C":"Djevojka ne traži nagradu od Andreuccia; ona priprema prijevaru raspitivanjem."},
  "2019_jesen_B__16": {"A":"Buzdovan se u ulomku ne spominje kao oružje konjanika.","B":"Starca napada drugi konjanik koji ga baca na zemlju, a ne sjekirom; sjekiru je htio dignuti sam starac.","D":"Otmica Dore još nije dovršena (Pavao iskače i sprječava je), pa se ne može reći da su je oteli."},
  "2019_jesen_B__17": {"A":"Brijač ne drhti zbog onesposobljena konja, nego od straha kad prepozna Pavla.","C":"Starčevo dizanje sjekire nije uzrok brijačeva straha; uzrok je dolazak mladoga Pavla.","D":"Šimeino nepomaganje nije razlog drhtanja; Šime je tek nezainteresiran, a brijač strahuje zbog Pavla."},
  "2019_jesen_B__18": {"A":"Grga (brijač) je itekako uzbuđen sukobom; viče i drhti od straha.","B":"Miloš mirno, ali aktivno pristupa sukobu kao haramija, pa nije nezainteresiran.","C":"Pavao je izravni sudionik sukoba jer se bori i spašava Doru."},
  "2019_jesen_B__19": {"A":"Batorić nije Ermenegildo; ime Ermenegildo veže se uz Cintekov govor o gostoprimstvu.","C":"Ercigonja nije lik Ermenegildo iz ovog ulomka.","D":"Lacica je onaj koji predlaže odlazak kući, a ne Ermenegildo."},
  "2019_jesen_B__20": {"A":"Prijedlog da idu kući daje Lacica, a ne poreznik (oficijal).","C":"Glasni smijeh u ulomku pripisan je Cinteku, a ne porezniku.","D":"Pohvalu vlastitoj glavi izriče Cintek, ne poreznik."},
  "2019_jesen_B__21": {"A":"Zvukovi iz kuhinje nisu predmet usporedbe 'čitave grmljavine'.","C":"Škripa kolica spominje se kao 'lomot kolica', a ne kao grmljavina.","D":"Rzanje konja nije ono što se opisuje izrazom 'čitava grmljavina'."},
  "2019_jesen_B__22": {"B":"Jokasta ne dokazuje Kreontovu zlonamjernost; ona pobija pouzdanost proroštava.","C":"Teza da bogovi ljudima čine zlo nije ono što Jokasta želi dokazati.","D":"Brzina širenja glasina nije Jokastina poruka; ona govori o neostvarenom proroštvu."},
  "2019_jesen_B__23": {"A":"Feb (Apolon) nije onaj koji je poslao vrača; vrača je 'na vrat poslao' Kreont.","B":"Jokasta nije poslala vrača; ona tek pobija proroštva.","D":"Laj je davno ubijen i ne može poslati vrača; pošiljatelj je Kreont."},
  "2019_jesen_B__24": {"A":"Edip se ne uznemiruje zbog Apolonovih obećanja, nego zbog mjesta Lajeva ubojstva.","B":"Edip ne sluti da mu Jokasta laže; upravo ga njezino kazivanje o tropuću uznemiruje.","C":"To što se i sluge bave proricanjem nije izvor nemira; nemir izaziva podatak o raskrižju."},
  "2019_jesen_B__25": {"B":"Skupljanje knjiga ne spominje se kao indolencija; don Zane govori o puhanju u pepeo.","C":"Pušenje petnaest godina po sebi nije nazvano indolencijom, nego nemar oko pepeljare.","D":"Neprozračivanje prostorije don Jere navodi kao nezdravo, ali indolencijom don Zane naziva svoj nemar s pepelom."},
  "2019_jesen_B__26": {"A":"Strah od Božje kazne ne pripisuje se don Jeri u ovom ulomku.","C":"Loše zdravstvene navike (puhanje u pepeo) obilježje su don Zanea, a ne don Jere.","D":"O obilasku drugih župa nema riječi; don Jere prevrće stare papire."},
  "2019_jesen_B__27": {"A":"Don Zane vijest ne doživljava kao nagovještaj nesreće, nego ironično, kao nevažnu.","B":"Vijest ne shvaća kao opomenu ljudima; ironičnim 'Gran' cosa!' je obezvrjeđuje.","D":"Velikim čudom vijest doživljava don Jere, a ne don Zane koji je ismijava."},
  "2019_jesen_B__28": {"A":"Tekst ne tvrdi da mladi ne poštuju starije, nego da se stariji srame svoje dobi.","C":"Autor ne tvrdi da je starost izvor autoriteta i mudrosti; ironizira bijeg od starosti.","D":"Lakši uspjeh mladih nije tema; riječ je o dostojanstvu prihvaćanja vlastite dobi."},
  "2019_jesen_B__29": {"B":"Opis nije idealiziran, nego karikiran i podrugljiv (mumija u bludžinsu).","C":"Opis nije patetičan; pretjerano komičan i odbojan, dakle groteskan.","D":"Opis nije sentimentalan; ne izaziva ganuće, nego ismijavanje."},
  "2019_jesen_B__30": {"A":"'Ratna kladionica' odnosi se na vrijeme rođenja generacije, a ne metaforički na pjevača.","C":"'Mumija u bludžinsu' je hiperbolična usporedba, a ne metafora kojom je nazvan sam pjevač.","D":"'Izvor mudrosti' u tekstu se ne pripisuje pjevaču kao metafora."},
  "2019_jesen_B__31": {"B":"U primjeru 'Tuci raju, tuci Turke' ponavlja se glagol, ali ne ista riječ na početku uzastopnih stihova.","C":"U primjeru 'I sačuvat... / Čisto ime' riječ je o ponavljanju srodnih riječi (figura etymologica), a ne o anafori.","D":"U primjeru 'Što je dalje... / Dalje smijeh' ponavlja se 'dalje', ali ne na samom početku obaju stihova kao anafora."},
  "2019_jesen_B__32": {"A":"Asindeton je nizanje bez veznika, ali ovdje je ključno izostavljanje predikata, što je elipsa.","C":"Eufemizam je ublažavanje neugodna izraza, čega u ovim stihovima nema.","D":"Inverzija je promjena uobičajena reda riječi, a ovdje je riječ o izostavljanju dijela rečenice."},
  "2019_jesen_B__33": {"A":"Diskurzivni rod obuhvaća esej, putopis i raspravu, a ne novelu.","B":"Dramski rod čine drame (tragedija, komedija), a ne novela.","D":"Lirski rod obuhvaća pjesme, dok je novela prozno, epsko djelo."},
  "2019_jesen_B__34": {"A":"Digresija je odstupanje od glavne radnje, obilježje epa i proze, a ne specifično tragedije.","B":"Invokacija (zaziv muze) obilježje je epa, ne tragedije.","D":"Retardacija (usporavanje radnje) epski je postupak, a ne distinktivno obilježje tragedije."},
  "2019_jesen_B__35": {"A":"Eshil je tragičar 5. st. pr. Kr., a ne 8. stoljeća.","C":"Pindar je liričar 5. st. pr. Kr., ne 8. stoljeća.","D":"Sofoklo je tragičar 5. st. pr. Kr., a ne 8. stoljeća."},
  "2019_jesen_B__36": {"A":"Ahilejeva smrt nije prikazana u Ilijadi; ep završava prije nje.","C":"Pojava kuge u grčkom taboru je na početku Ilijade, a ne kraj.","D":"Razgovorom bogova na Olimpu ep ne završava; završetak je Hektorov pogreb."},
  "2019_jesen_B__37": {"A":"Traženje od proroka tko će ga svrgnuti odnosi se na vladare poput Edipa, a ne na Prometeja.","C":"Sukob s ocem braneći zaručnicu vezuje se uz druge likove, ne uz Prometeja.","D":"Molba Hefestu za štit veže se uz Tetidu i Ahileja, a ne uz Prometeja."},
  "2019_jesen_B__38": {"A":"Opat Držiha spominje se kao darovatelj zemlje, ali tekst ploče ne započinje njegovim iskazom.","C":"Kralj Zvonimir spominje se u darovnici, no ploča ne započinje njegovim iskazom.","D":"Knez Kosmat spominje se u nastavku teksta, a ne na samom početku."},
  "2019_jesen_B__39": {"A":"Aleksandrida je srednjovjekovni viteški roman o Aleksandru Velikom, a ne enciklopedija.","C":"Ljetopis popa Dukljanina je kronika/povijesni spis, ne enciklopedija.","D":"Traktat Črnorisca Hrabra je obrana slavenskog pisma, a ne enciklopedija."},
  "2019_jesen_B__40": {"A":"Božanstvena komedija počinje stihovima o tamnoj šumi ('Na pol našeg životnog puta'), a ne prozom o Manchi.","B":"Dekameron započinje okvirnom pričom o kugi u Firenci, ne o plemiću iz Manche.","D":"Hamlet je drama koja počinje prizorom straže na bedemima, a ne ovom proznom rečenicom."},
  "2019_jesen_B__41": {"A":"Razočaranje sinom odnosi se na samog Dunda Maroja, a ne na Dugog Nosa.","C":"Zaljubljenost u Lauru obilježje je Mara, Marojeva sina, ne Dugog Nosa.","D":"Priprosti sluga je Bokčilo (ili Popiva), a ne Dugi Nos."},
  "2019_jesen_B__42": {"A":"Racionalistička filozofija temelj je prosvjetiteljstva, a ne baroka.","B":"Motiviranost dužnošću i čašću obilježje je klasicizma, ne baroka.","C":"Ugledanje na antičke uzore svojstveno je humanizmu i renesansi, a ne baroku."},
  "2019_jesen_B__43": {"B":"Marko Marulić autor je Judite, a ne poeme o razmetnom sinu.","C":"Petar Hektorović napisao je Ribanje i ribarsko prigovaranje, ne poemu o razmetnom sinu.","D":"Petar Zoranić autor je Planina, a ne poeme o razmetnom sinu."},
  "2019_jesen_B__44": {"A":"Renesansa je 15.–16. st., a Brezovački djeluje na prijelazu 18. u 19. st.","B":"Barok je 17. st., a Brezovački stvara u prosvjetiteljstvu.","D":"Romantizam je 19. st.; Brezovački mu prethodi kao prosvjetiteljski pisac."},
  "2019_jesen_B__45": {"A":"Ivan Gundulić je barokni pjesnik i po njemu nije nazvano to razdoblje.","C":"Ivan Mažuranić djeluje u hrvatskom narodnom preporodu/romantizmu; razdoblje nije nazvano po njemu.","D":"Miroslav Krleža pripada modernoj 20. stoljeća, a ne razdoblju spoja romantizma i realizma."},
  "2019_jesen_B__46": {"A":"Gotska atmosfera vezuje se uz gotski roman, a ne uz Werthera.","B":"'Suvišni čovjek' pojam je ruske književnosti (npr. Onjegin), a ne Wertherov.","C":"Demonski lik tipičan je za romantizam općenito, ali uz Werthera se specifično veže svjetska bol."},
  "2019_jesen_B__47": {"A":"Obljetnica pobjede nad Tatarima veže se uz druge spjevove, a ne uz Smrt Smail-age Čengića.","B":"Stih krakovjak i poljska narodna pjesma ne vežu se uz Mažuranićevo djelo.","D":"Boravak fratra u carigradskom zatvoru tema je Andrićeve Proklete avlije, a ne ovog spjeva."},
  "2019_jesen_B__48": {"A":"Eugène de Rastignac je mladi student i ambiciozni dolaznik, a ne robijaš.","B":"Bianchon je student medicine, a ne robijaš.","C":"D'Ajuda-Pinto je plemić, ljubavnik gospođe de Beauséant, a ne robijaš."},
  "2019_jesen_B__49": {"B":"Ova rečenica o sukobu oko Ivičine budućnosti pripada drugom liku (Kanonik/obitelj), a ne Ferkonji.","C":"Rečenica o namamljivanju u brđansko siromaštvo nije Ferkonjina samokarakterizacija.","D":"Patetičan iskaz o kapelici i ljubavi pripada zaljubljenom liku, a ne Ferkonji."},
  "2019_jesen_B__50": {"B":"Đulabije Petra Preradovića pripadaju romantizmu, a ne početku modernizma.","C":"Lelek sebra Tina Ujevića je već modernistička zbirka, ali ne ona kojom modernizam započinje.","D":"Preobraženja A. B. Šimića su ekspresionistička zbirka 20. st., a ne početak modernizma."},
  "2019_jesen_B__51": {"B":"Želja da postane dječak nije sudbina Brunhilde iz Duge.","C":"Brunhilda ne postaje hajdučica; ona završava kao prosjakinja.","D":"Brunhilda nije zlatarova kći; to se veže uz Doru iz Zlatarova zlata."},
  "2019_jesen_B__52": {"B":"Marinizam je barokni kićeni stil 17. st., a ne avangardni pravac.","C":"Naturalizam je pravac druge polovice 19. st., a ne avangarda.","D":"Simbolizam je pravac s prijelaza 19. u 20. st., ne avangardni pravac."},
  "2019_jesen_B__53": {"A":"Povratak Filipa Latinovicza prikazuje slikarov povratak u zavičaj i obračun s prošlošću, a ne kolektiv intelektualaca pred rat.","B":"Đuka Begović prikazuje slavonskog seljaka i njegove strasti, a ne zagrebačke intelektualce.","C":"Prokleta avlija smještena je u carigradski zatvor, a ne među zagrebačke intelektualce."},
  "2019_jesen_B__54": {"A":"Filip Latinovicz je slikar koji se vraća u zavičaj, a ne dolazi na proslavu obljetnice očeve banke.","B":"Juraj Stipančić vezan je uz drukčiju obiteljsku priču, a ne uz proslavu banke.","D":"Melkior Tresić je intelektualac iz Kiklopa u iščekivanju rata, a ne dolaznik na proslavu banke."},
  "2019_jesen_B__55": {"A":"Ivan Slamnig poznat je po ironičnoj, ludičkoj poeziji, a ne po ovim nježnim stihovima.","B":"Josip Pupačić piše o moru i zavičaju (More, Tri moja brata), a ne ove stihove.","C":"Jure Kaštelan autor je ratne i meditativne lirike, a ne ovih stihova nježna obraćanja."},
  "2019_jesen_B__56": {"B":"'Đepno' je nepravilno; pravilno je 'džepno'.","C":"'Uruđbeni' je nepravilno; pravilno je 'urudžbeni'.","D":"'Piđama' je nepravilno; pravilno je 'pidžama'."},
  "2019_jesen_B__57": {"A":"'Potcrtati' je nepravilno; pravilno je 'podcrtati' (pod- ostaje ispred c).","B":"'Potčiniti' nije pravilan oblik; standardno je 'podčiniti'.","D":"'Potšišati' je nepravilno; pravilno je 'podšišati'."},
  "2019_jesen_B__58": {"B":"'Talijana' treba pisati velikim slovom jer je naziv pripadnika naroda.","C":"Naziv četvrti treba glasiti 'Stari grad' (druga riječ malim slovom).","D":"Pravilno je 'Park prirode Lonjsko polje' (samo prva riječ velikim slovom)."},
  "2019_jesen_B__59": {"B":"Ispred 'nego' u poredbi ne piše se zarez, pa je rečenica pogrešno interpungirana.","C":"Zavisna rečenica s 'iako' mora biti odvojena zarezom ('vjeruju, još je prerano').","D":"Ispred datuma 'Dubrovniku' ne treba zarez."},
  "2019_jesen_B__60": {"A":"U 'aviona' nema sibilarizacije; to je genitiv bez glasovne promjene k/g/h.","B":"U 'buci' (od buka) provedena je sibilarizacija k→c, ali traženi je primjer g→z; D je točniji jer pokazuje istu promjenu u traženom obliku.","C":"U 'ptici' (od ptica) glas c potječe od osnove, a ne nastaje sibilarizacijom."},
  "2019_jesen_B__61": {"A":"Jednačenje po mjestu tvorbe mijenja suglasnike (npr. s→š), čega u 'veličina' nema.","B":"Jednačenje po zvučnosti mijenja zvučne/bezvučne parove, a ovdje je k prešlo u č.","D":"Jotacija je stapanje s glasom j, a ovdje je riječ o k→č ispred sufiksa, dakle palatalizaciji."},
  "2019_jesen_B__62": {"B":"Znak ȗ označuje dugosilazni naglasak, a 'zub' ima kratkosilazni.","C":"Znak ù označuje kratkouzlazni naglasak, što nije naglasak riječi 'zub'.","D":"Znak ú označuje dugouzlazni naglasak, što nije naglasak riječi 'zub'."},
  "2019_jesen_B__63": {"A":"Rastav 'ple-sa-či-ca' je slogovni, a ne morfemski.","B":"U 'ple-sač-ica' korijen nije izdvojen ('ples-') ni gramatički morfem '-a'.","D":"U 'ples-a-čic-a' pogrešno su izdvojeni morfemi; ispravno je ples-ač-ic-a."},
  "2019_jesen_B__64": {"A":"'Mislima' je u lokativu (u mislima), a ne u instrumentalu.","B":"'Budućim' je pridjev koji se slaže s 'pobjedama' u dativu, a ne instrumentalu.","D":"'Svih' je genitiv (protivnika svih), a ne instrumental."},
  "2019_jesen_B__65": {"A":"'Što' ovdje je upitna riječ na početku pitanja, a ne odnosna zamjenica.","B":"'Ti' je osobna zamjenica, a ne odnosna.","D":"'Nam' je osobna zamjenica u dativu, a ne odnosna."},
  "2019_jesen_B__66": {"A":"Genitiv ne dolazi uz prijedlog 'o' u ovoj konstrukciji; riječ je o lokativu.","B":"Dativ ne odgovara konstrukciji 'o čemu'; prijedlog 'o' traži lokativ.","D":"Instrumental ovdje nije moguć; 'o čemu' je lokativ."},
  "2019_jesen_B__67": {"A":"Treba 'boljeg mladića' (određeni/genitivni oblik), pa 'bolja' nije ispravan neodređeni oblik.","B":"Treba 'teškim korakom' (instrumental), pa 'teška koraka' nije pravilno.","C":"Treba 'pravopisnog problema', pa 'pravopisna' ovdje nije ispravan oblik."},
  "2019_jesen_B__68": {"A":"Pravilan glagolski prilog glasi 'istražujući', a ne 'istraživajući'.","B":"Pravilno je 'kupujući', a ne 'kupovajući'.","C":"Pravilno je 'preplavljujući', a ne 'preplavljivajući'."},
  "2019_jesen_B__69": {"A":"'Dodirnu' uz 'grof... dodirnu' je aorist 3. l. jd. (svršena prošla radnja), a ne prezent.","B":"'Otac je dodirnu' je aorist, što potvrđuje i kontekst prošle radnje.","C":"'Susjeda ga tad dodirnu' je aorist 3. l. jd., a ne prezent."},
  "2019_jesen_B__70": {"A":"'Neznam' treba pisati rastavljeno ('ne znam') jer je 'ne' uz glagol.","C":"'Ne zainteresiranost' treba pisati sastavljeno ('nezainteresiranost').","D":"'Neda' treba pisati rastavljeno ('ne da') jer je 'ne' uz glagol."},
  "2019_jesen_B__71": {"A":"'Jezero' je srednjeg roda, a 'Lapovac' muškog, pa rod nije isti.","B":"'Planina' je ženskog roda, a 'Mosor' muškog, pa rod nije isti.","C":"'Grad' je muškog roda, a 'Slatina' ženskog, pa rod nije isti."},
  "2019_jesen_B__72": {"B":"Predikat je 'molio bih', a ne 'vas'.","C":"'Vas' nije priložna oznaka jer ne izriče okolnost radnje, nego objekt u akuzativu.","D":"Subjekt nije 'vas'; vršitelj radnje je skriveni 'ja' u predikatu 'molio bih'."},
  "2019_jesen_B__73": {"A":"Tri surečenice je premalo; rečenica ih ima četiri (uvodna zavisna + tri spojene).","C":"Pet surečenica je previše; precizno ih je četiri.","D":"Šest surečenica je previše; rečenica ima četiri surečenice."},
  "2019_jesen_B__74": {"B":"Rečenica s 'iako' je zavisnosložena dopusna, a ne nezavisnosložena.","C":"Rečenica s 'jer' je zavisnosložena uzročna, a ne nezavisnosložena.","D":"Rečenica s 'da su... odgovarali' je zavisnosložena objektna, a ne nezavisnosložena."},
  "2019_jesen_B__75": {"A":"Pravilno je 'k liječniku', a ne 'kod liječnika' uz glagol kretanja.","B":"Pravilno je 'kuća je na prodaju', a ne 'za prodati'.","C":"Pravilno je 'lagao nam je svima', a ne 'lagao je sve nas'."},
  "2019_jesen_B__76": {"B":"'Pridjeva' je u genitivu množine, a ne u kanonskom (nominativnom) obliku.","C":"'Kraćenjem' je u instrumentalu, a ne u kanonskom obliku.","D":"'Osnove' je u genitivu jednine, a ne u kanonskom obliku."},
  "2019_jesen_B__77": {"A":"Ljekarna i apoteka nisu u odnosu nadređenosti/podređenosti pojma, nego označavaju isto.","B":"Homonimija znači isti oblik uz različito značenje, a ove riječi imaju različit oblik i isto značenje.","C":"Antonimija je suprotnost značenja, a ove riječi znače isto."},
  "2019_jesen_B__78": {"B":"'Lord' je naslovna/titulna riječ, a ne riječ nastala od osobnog imena.","C":"'Paprikaš' je etnonimsko jelo prema podrijetlu, ali nije eponim (nije od osobnog imena).","D":"'Beč' je hrvatska inačica imena grada, a ne eponim izveden iz osobnog imena."},
  "2019_jesen_B__79": {"A":"'Biti vezanih ruku' znači biti onemogućen u djelovanju, a ne biti oslonac.","B":"'Biti sretne ruke' znači biti spretan/imati uspjeha, a ne biti glavna pomoć.","D":"'Biti široke ruke' znači biti darežljiv, a ne biti oslonac."},
  "2019_jesen_B__80": {"A":"Prvi saborski govor na hrvatskom ne pripisuje se Faustu Vrančiću.","C":"Prvu hrvatsku gramatiku objavio je Bartol Kašić (1604.), a ne Vrančić.","D":"Prvi hrvatski pravopis ne pripisuje se Faustu Vrančiću."},

  // 2019_ljeto_A
  "2019_ljeto_A__1": {"A":"Nemir zbog izgovorenih riječi (preteku jezik) sporedan je motiv, a ne poanta o ljubavi izrečena u zadnjem dvostihu.","B":"Lutanje drumom dio je uvodne slike, ali poanta ljubav ne određuje kao poticaj na lutanje.","C":"Sanje se spominju kao sitne i drobne, ali pjesma ljubav ne svodi na nešto moguće samo u snovima."},
  "2019_ljeto_A__2": {"A":"Subjekt kaže da je ljubav suvišno kriti, dakle ne boji se da je neće sakriti.","B":"U pjesmi nema naznake da draga hini ljubav; strah se odnosi na njega samog.","C":"Spominje se zlobna pomisao, ali bojazan je da je sišao s uma, a ne da je postao zao."},
  "2019_ljeto_A__3": {"B":"Stih o skrivanju luđačke ljubavi govori o ljubavi, a ne o slutnji smrti.","C":"Stih o tome da silna ljubav mrvi izriče razornost ljubavi, a ne slutnju vlastite smrti.","D":"Stih da je zadnji makar bio prvi izražava poniznost i obrat, ne slutnju smrti."},
  "2019_ljeto_A__4": {"A":"Mladić uspijeva ispjevati pobjednički pjev iz srca, dakle osjećaje izražava; problem je u odjeku.","C":"Bog se spominje kao unutarnji glas koji sluša, a ne kao izgubljena vjera.","D":"Bolesno zelenkast opis odnosi se na očaj kao boju, a ne na stvarnu mladićevu bolest."},
  "2019_ljeto_A__5": {"B":"Pogled se spominje uz prazna lica, ali nije dočaran bojom.","C":"Lica se opisuju kao prazna u sivomu zraku, no sam motiv lica nije obojen kolorom.","D":"Strah je vezan uz crni bezdan, ali sam motiv straha nije koloristički dočaran kao očaj."},
  "2019_ljeto_A__6": {"A":"Želja da srca zatrepte odnosi se na učinak pjevanja na druge, a ne na unutarnju prisilu.","B":"Prizor prignutih glava opisuje reakciju slušatelja, a ne unutarnji imperativ.","C":"Strah pred crnim bezdanom dio je očaja, a ne izraz unutarnje naredbe za pjevanjem."},
  "2019_ljeto_A__7": {"A":"Dilaver ne potiče cara na dovršavanje poslova, nego ga želi odvratiti od plahih nakana.","B":"Carevu se mladost spominje, ali Dilaver mu ne prigovara da je premlad za put.","D":"Dilaver dolazi izraziti svoje strahove i upozoriti cara, a ne primiti nove zapovijedi."},
  "2019_ljeto_A__8": {"A":"Tekst ne spominje ukrašavanje prijestolja cvijećem.","B":"Predaja zlatne krune ne spominje se; poniznost se iskazuje skutom haljine.","D":"Klečanje na sagu nije navedeno kao znak poniznosti; to je ljubljenje skuta."},
  "2019_ljeto_A__9": {"A":"Tekst ne kaže da car od njih očekuje savjete, nego da im je pod kletvom otkrio tajnu.","C":"Čuvar i učitelj dolaze zajedno s Dilaverom, pa mu se ne suprotstavljaju.","D":"Iz ulomka se ne potvrđuje da su doputovali iz Carigrada; istaknuto je zakletvom obvezano povjerenje."},
  "2019_ljeto_A__10": {"A":"Tek se osjećao kao da je nastavio davno započet razgovor, no taj odnos opisuje Mirin dojam, a tvrdnja se traži o Vukoviću.","B":"Vuković ne izbjegava razgovor o Miri, naprotiv, pomno je promatra i procjenjuje.","D":"Ulomak ne pokazuje da je Vuković ožalostio Miru; njegova ju je ljubežljivost osokolila."},
  "2019_ljeto_A__11": {"A":"Predaja vrijedna dara ne spominje se u ulomku.","B":"Širok osmijeh nije naveden; Vuković se naklonio aristokratskim poklonom.","C":"Brkovi se opisuju kao zafrkani, ali Vuković ih pri pozdravu ne uvrće."},
  "2019_ljeto_A__12": {"A":"Mira se ne buni zbog šala; Vukovićeva je ljubežljivost osokoljuje.","B":"Stid se ne navodi kao Mirina reakcija, nego ohrabrenje za razgovor.","D":"Mira ne šuti promatrajući ga, nego nastavlja razgovor kao da je odavno započet."},
  "2019_ljeto_A__13": {"A":"Pečorin se Azamatom bavi i hrani ga slatkišima, pa Azamatova patnja nije zbog nepažnje.","B":"Blijeđenje i venuće tek nalikuje bolesti, ali uzrok je čežnja za konjem, a ne smrtna bolest.","D":"Usporedba s ljubavlju iz romana samo je slika; Azamat zapravo žudi za konjem Karađozom."},
  "2019_ljeto_A__14": {"A":"Riječ je o razmjeni, a ne o darovnom ugovoru; konj je cijena za sestru.","C":"Otvaranje trgovine nije tema dogovora.","D":"Kupovina ovaca ne spominje se kao posao koji su uglavili."},
  "2019_ljeto_A__15": {"A":"Azamat je sudionik radnje, ali ne onaj koji naknadno razabire sve vragolije.","B":"Kazbič je vlasnik konja, a ne onaj koji pripovijeda i kasnije shvaća zbivanja.","C":"Pečorin smišlja smicalice, ali 'ja' u rečenici upućuje na pripovjedača koji ih je tek poslije prozreo."},
  "2019_ljeto_A__16": {"A":"Stid zbog neprijateljskih osjećaja vezan je uz Kiti, a ne uz Anu.","B":"Zanimanje za Stivu nije iskazano kao Anina osobina u ulomku.","D":"Dugotrajna bolest vezana je uz Kiti, a ne uz Anu."},
  "2019_ljeto_A__17": {"A":"Ljubavni odnos s Kitinim suprugom nije naveden; istaknut je nekadašnji odnos zaštitnice i štićenice.","B":"Anu ne rastužuje Kitino ponašanje; ulomak govori o Kitinu neprijateljstvu i njegovu objašnjenju.","D":"Tvrdnja da Kiti odgaja Anino dijete nema potvrde u tekstu."},
  "2019_ljeto_A__18": {"A":"Pozdrav Dolinoj djeci ne spominje se kao izručeni pozdrav.","C":"Dolina sestra (Kiti) nije primatelj pozdrava, nego ga prenosi.","D":"Stiva nije onaj komu Ana izručuje pozdrav u ovom ulomku."},
  "2019_ljeto_A__19": {"A":"Zubarski tehničar nije pripovjedačevo zanimanje; on je pravni referent.","B":"Doktor filozofije sin je jednoga od uzvanika, a ne pripovjedač.","C":"Pripovjedač nije tvorničar, nego pravni zastupnik i tajnik."},
  "2019_ljeto_A__20": {"A":"Ironičan i podrugljiv opis isključuje suosjećanje s Domaćinskim.","B":"Divljenje je suprotno prezrivu tonu kojim pripovjedač opisuje Domaćinskoga.","D":"Pripovjedač Domaćinskoga ismijava, a ne pokazuje strah pred njim."},
  "2019_ljeto_A__21": {"A":"Bivša kavanska kolačarica jest gospođa Domaćinski, a ne pripovjedačeva supruga.","B":"Ironičan ton i spomen ljubavnika pokazuju nepoštovanje, a ne poštovanje supruge.","D":"Brbljavom se opisuje gospođa Domaćinski, a ne pripovjedačeva žena Agneza."},
  "2019_ljeto_A__22": {"B":"Odlazak iz Trezene posljedica je stida, a ne razlog; on ne napušta domovinu zbog same odluke.","C":"Hipolit ne sumnja u Teramena; razgovara s njim povjerljivo.","D":"Otac (Tezej) je nestao, ali Hipolitov stid izvire iz vlastite neaktivnosti, a ne iz osjećaja napuštenosti."},
  "2019_ljeto_A__23": {"A":"Atenski dvor nije ono na što upućuju 'ova mjesta'; Hipolit govori o Trezeni.","C":"Korint i Aheront mjesta su Teramenove potrage, a ne ona koja Hipolitu ne godi gledati.","D":"Klanci Elide dio su nabrajanja prijeđenih predjela, a ne 'ova mjesta' iz Trezene."},
  "2019_ljeto_A__24": {"A":"Teramen ne savjetuje prepuštanje mladenačkim ljubavima.","B":"Upozorenje na Fedrin utjecaj ne pripisuje se Teramenu u ovom ulomku.","C":"Zabrinutost zbog Tezejevih ljubavnih pustolovina nije Teramenova tema; on je tragao za njim."},
  "2019_ljeto_A__25": {"A":"Krogstadova odjeća nije ono što uznemiruje Noru.","C":"Rankova pitanja Nora lako otklanja izgovorom o kostimu; ne uznemiruju je.","D":"Torvald ostaje u sobi tek nakon Norina manevra; nije uzrok njezine uznemirenosti."},
  "2019_ljeto_A__26": {"A":"Tekst ne navodi da se Rank loše osjeća u Heleninu društvu.","B":"Norino slanje Ranka nije zavođenje, nego način da ostane sama s Krogstadom.","D":"Nora ne strahuje da bi Krogstad mogao vidjeti Ranka, nego želi tajni razgovor."},
  "2019_ljeto_A__27": {"A":"'Nešto neugodno?' je obično Rankovo pitanje, bez prikrivenoga suprotnog značenja.","B":"'Užas dolazi unatoč svemu' izravna je prijetnja, a ne ironija.","C":"Krogstadova izjava da se Nora usuđuje izravan je prijekor, bez ironijskoga obrata."},
  "2019_ljeto_A__28": {"A":"Rečenica ne govori da je Sizif vodom htio odobrovoljiti bogove, nego da je vodu pretpostavio kazni.","C":"Smisao nije da bogovi vodom gase vatru, nego da je Sizif izabrao dati vodu unatoč munjama.","D":"Sizif od Jupitera ne traži blagoslov vode; on sam pretpostavlja vodu nebeskim munjama."},
  "2019_ljeto_A__29": {"A":"Žena se nije suprotstavila Sizifovu povratku; upravo ga je njezina poslušnost potaknula.","B":"Žena nije odavala Sizifove tajne bogovima; on je odavao tajne bogova.","C":"Iskušavanje ljubavi nije razlog kazne; žena je ispunila njegov nalog."},
  "2019_ljeto_A__30": {"B":"Odbijanje guranja stijene posljedica je kazne, a ne posljednji grijeh.","C":"Kažnjavanje žene dio je ranije epizode, a ne posljednji grijeh.","D":"Ljutnja na bogove općenita je crta, no posljednji grijeh jest neželja za povratkom u pakao."},
  "2019_ljeto_A__31": {"B":"Stihovi o strasnoj duši i umiranju u samoći grade gradaciju i ponavljanje, a ne suprotnost.","C":"Slika hrama, neba i mjeseca opisni je, idilični prizor bez suprotstavljenih pojmova.","D":"Stihovi o vjetru i tami niz su slika nevremena, bez antitetičkoga para."},
  "2019_ljeto_A__32": {"A":"Elipsa je izostavljanje dijela rečenice, čega ovdje nema.","B":"Eufemizam ublažava neugodan pojam, što ovdje nije slučaj.","C":"Hiperbola je pretjerivanje, a 'prvo pero' nije preuveličavanje nego zamjena pojma."},
  "2019_ljeto_A__33": {"B":"Elegija je tužaljka, pjesma žalosti, a ne zanosne radosti.","C":"Epigram je kratka, često satirična pjesma, a ne slavlje životnih radosti.","D":"Oda svečano slavi osobu ili ideal, ali zanosno slavljenje radosti i prirode obilježje je ditiramba."},
  "2019_ljeto_A__34": {"A":"'Božanska pjesma' nije izvorno značenje pojma tragedija.","C":"'Posmrtna pjesma' (tužaljka) nije etimologija tragedije.","D":"'Žalosna pjesma' opisuje ugođaj, ali izvorno tragedija znači jarčeva pjesma."},
  "2019_ljeto_A__35": {"A":"Ahilej je junak Ilijade, a ne onaj koji stiže s obala Troje u Lavinij.","C":"Hektor pogiba pod Trojom i nije junak Eneide.","D":"Odisej je junak Odiseje, a ne Vergilijeve Eneide."},
  "2019_ljeto_A__36": {"A":"Alkej je grčki pjesnik s Lezba, ne rimski.","B":"Anakreont je grčki liričar, ne pripadnik rimske književnosti.","D":"Pindar je grčki pjesnik oda, ne rimski."},
  "2019_ljeto_A__37": {"A":"Antika prethodi pojavi provansalskih trubadura.","C":"Barok je razdoblje 17. stoljeća, mnogo poslije trubadurske poezije.","D":"Romantizam je 19. stoljeće, daleko nakon srednjovjekovnih trubadura."},
  "2019_ljeto_A__38": {"A":"Pjesma o Nibelunzima njemački je junački ep, ne o Cidu.","C":"Beowulf je staroengleski ep, nije vezan uz Rodriga Diaza.","D":"Kalevala je finski narodni ep, ne španjolski o Cidu."},
  "2019_ljeto_A__39": {"A":"Razočarani bogati Dubrovčanin jest Dundo Maroje (otac), a ne Pomet.","B":"U Lauru je zaljubljen Maro, a Pomet je sluga koji spletkari.","C":"Pomet nije priprost sluga, nego dovitljiv i inteligentan lik."},
  "2019_ljeto_A__40": {"A":"Edip je junak Sofoklove tragedije, ne onaj koji govori nad Yorickovom lubanjom.","C":"Harpagon je Molierov škrtac, nema veze s Yorickom.","D":"Prometej je lik antičke tragedije, ne Shakespeareova Hamleta."},
  "2019_ljeto_A__41": {"A":"Ribanje i ribarsko prigovaranje pripada epskoj/refleksivnoj poeziji, ne dramskom rodu.","B":"Satir Reljkovića je epsko-didaktičko djelo, ne drama.","D":"Planine Zoranića pastoralni su roman, dakle pripovjedna proza, a ne drama."},
  "2019_ljeto_A__42": {"A":"Srednji vijek prethodi Frankopanovu vremenu.","B":"Renesansa završava prije Frankopanova djelovanja u 17. stoljeću.","D":"Prosvjetiteljstvo je 18. stoljeće, nakon Frankopanova baroknog razdoblja."},
  "2019_ljeto_A__43": {"B":"Don Quijote luta zbog viteških ideala, ali zaključak o obrađivanju vrta pripada Candideu.","C":"Pečorin je junak Ljermontova, bez idealističkoga učitelja i vrta.","D":"Werther završava samoubojstvom iz nesretne ljubavi, a ne spoznajom o vlastitu vrtu."},
  "2019_ljeto_A__44": {"B":"Nadređenost stila i teme katoličke obnove obilježja su baroka, ne romantizma.","C":"Društveno-analitička uloga i preslika stvarnosti opisuju realizam.","D":"Ugledanje na antiku i sklad teme i kompozicije obilježja su klasicizma."},
  "2019_ljeto_A__45": {"A":"Gostioničarka Mirandolina (Goldoni) pripada prosvjetiteljstvu/18. stoljeću.","B":"Nora (Ibsen) djelo je realizma, ne romantizma.","D":"Romeo i Julija (Shakespeare) nastaje u renesansi, ne u romantizmu."},
  "2019_ljeto_A__46": {"B":"Krugovi su časopis poratnoga modernizma (1950-ih), ne romantizma.","C":"Plamen je Krležin avangardni časopis iz 1919., ne romantizma.","D":"Vijavica je zbirka A. B. Šimića, a ne časopis hrvatskoga romantizma."},
  "2019_ljeto_A__47": {"A":"Seosko podrijetlo samo po sebi nije razlog Lovrina neuspjeha; problem je otuđenje od korijena.","B":"Lovro se školuje i obrazuje, dakle nije neobrazovan.","C":"Odavanje alkoholu nije prikazano kao uzrok njegova životnog sloma."},
  "2019_ljeto_A__48": {"A":"Zločin i kazna je psihološki realizam, a ne poetski realizam.","C":"Ana Karenjina pripada psihološko-društvenom realizmu, ne poetskome.","D":"Kabanica je realistička pripovijetka s elementima groteske, a ne poetski realizam."},
  "2019_ljeto_A__49": {"A":"Tena se ne izdvaja krhkošću, nego bujnom ljepotom i snagom.","B":"Tena ljepotu gubi zbog boginja i propadanja, ali pripovijetka završava nasilnom smrću od ljubavnika.","C":"Zabrana igre u djetinjstvu nije obilježje Tenina lika."},
  "2019_ljeto_A__50": {"B":"Ivica Kičmanović junak je Kovačićeva U registraturi, a ne učitelj koga obuzima čama.","C":"Juraj Stipančić lik je Gjalskoga, a ne Matoševa Camaa.","D":"Đuro Martić nije lik na koga se odnosi opis učitelja iz Camaa."},
  "2019_ljeto_A__51": {"A":"Pozitivističko-materijalistička shvaćanja obilježje su realizma/naturalizma, ne nadrealizma.","B":"Determiniranost nasljeđem i sredinom načelo je naturalizma.","D":"Veličanje strojeva, dinamizma i agresivnosti obilježje je futurizma."},
  "2019_ljeto_A__52": {"A":"Eugene de Rastignac lik je Balzaca, ne pripovjedač Camusova Stranca.","B":"Akakije Akakijevič junak je Gogoljeve Kabanice, ne Stranca.","C":"Gregor Samsa junak je Kafkine Preobrazbe, a rečenica o mami pripada Meursaultu."},
  "2019_ljeto_A__53": {"A":"Don Fernando nije lik koji odbija električno svjetlo kao tuđ put.","C":"Melkior je glavni junak Kiklopa, ali riječi o odbacivanju modernoga izgovara Maestro.","D":"Ugo nije onaj koji brani svoj umjetnički put protiv električnoga svjetla."},
  "2019_ljeto_A__54": {"B":"A. G. Matoš objavio je više od jedne zbirke i ne odgovara opisu jedine zbirke s reduciranom interpunkcijom.","C":"Dobriša Cesarić ne uvodi začudne grafičke oblike kakvi se ovdje opisuju.","D":"Tin Ujević napisao je više zbirki, pa ne odgovara opisu autora jedine zbirke."},
  "2019_ljeto_A__55": {"A":"Ivan Slamnig nije autor stihova iz zbirke Moj križ svejedno gori.","C":"Jure Kaštelan nije autor navedenih stihova.","D":"Slavko Mihalić nije autor zbirke Moj križ svejedno gori."},
  "2019_ljeto_A__56": {"A":"'Poćetnička' je pogrešno; pravilno je 'početnička' (od početnik).","B":"'Očajnićki' je pogrešno; pravilno je 'očajnički'.","D":"'Čarobnjaćki' je pogrešno; pravilno je 'čarobnjački'."},
  "2019_ljeto_A__57": {"A":"'Povjesni' je pogrešno; pravilno je 'povijesni'.","B":"'Ocjenjen' je pogrešno; pravilno je 'ocijenjen'.","D":"'Djelu' je pogrešno u ovom značenju; pravilno je 'dijelu' (dio romana)."},
  "2019_ljeto_A__58": {"A":"'Srednjemu Jadranu' ovdje treba malim slovom ('srednjem Jadranu') jer nije ustaljeno vlastito ime.","C":"'Antike' treba malim slovom ('antike'), a 'sveti' uz Augustina malim; pravopis nije ispravan.","D":"'Baziliku Svetoga Petra' piše se 'baziliku svetoga Petra' (vrsta građevine malim slovom)."},
  "2019_ljeto_A__59": {"A":"'Kišem' nije rezultat palatalizacije nego sibilarizacije/odnosa k-š drukčije naravi; k ne prelazi u č.","C":"'Pišem' (od pisati) ne pokazuje palatalizaciju velarnoga suglasnika ispred e.","D":"'Siječem' (od sjeći) ne nastaje palatalizacijom kakva je u 'mičem'."},
  "2019_ljeto_A__60": {"B":"Jednačenje po zvučnosti ovdje nije provedeno; promjena je u mjestu tvorbe.","C":"Palatalizacija je prijelaz velara ispred e/i, čega u 'hrašće' nema.","D":"Sibilarizacija pretvara k, g, h u c, z, s ispred i, što ovdje nije slučaj."},
  "2019_ljeto_A__61": {"A":"'Mrák' označuje dugouzlazni naglasak, što nije pravilno za riječ mrak.","B":"'Mràk' označuje kratkouzlazni naglasak, što je netočno.","D":"'Mrȁk' označuje kratkosilazni naglasak, što nije pravilno."},
  "2019_ljeto_A__62": {"A":"Zanaglasnica 'se' pogrešno je smještena iza umetnute surečenice, a ne na drugo mjesto.","B":"Zanaglasnica 'bi' nije na drugome mjestu rečenice, nego nakon višečlanoga početka.","C":"Zanaglasnica 'je' došla je prekasno (iza imena), a ne odmah na drugo mjesto."},
  "2019_ljeto_A__63": {"A":"'Sobaričin' uključuje i nastavak, pa nije oblikotvorna osnova.","C":"'Sobar' je tvorbena, a ne oblikotvorna osnova pridjeva 'sobaričin'.","D":"'Soba' je polazna imenica, ne oblikotvorna osnova pridjeva."},
  "2019_ljeto_A__64": {"A":"'Sela' su ovdje u nominativu množine (subjekt), a ne u genitivu.","B":"'Ju' je zamjenica u akuzativu, ne u genitivu.","C":"'Anđela' je u akuzativu jednine (objekt uz 'skinuli'), a ne u genitivu."},
  "2019_ljeto_A__65": {"A":"'Mužom' je pogrešno; iza nepčanika dolazi -em, dakle 'mužem'.","B":"'Nosem' je pogrešno; pravilno je 'nosom' jer nema nepčanika.","C":"'Plačom' je pogrešno; pravilno je 'plačem' (iza č dolazi -em)."},
  "2019_ljeto_A__66": {"A":"'Najjednostavniji' je u rečenici upotrijebljen u usporedbi ('kao da je'), no traženi pravilan superlativ je 'najsuhije'.","B":"'Najvrijedniji' jest pravilan oblik, ali rečenica nije ta s traženim odgovorom (najsuhije).","D":"'Najvrućiji' jest superlativ, no točan primjer prema ključu jest 'najsuhije'."},
  "2019_ljeto_A__67": {"A":"'Viknuvši' je prilog prošli svršenoga glagola, a 'vikati' je nesvršen.","B":"'Vikajući' nije pravilan oblik; pravilno je 'vičući'.","C":"'Vikavši' je prilog prošli, a od nesvršenoga 'vikati' tvori se prilog sadašnji."},
  "2019_ljeto_A__68": {"A":"'Dopirali' je oblik glagola 'dopirati', a ne traženoga 'doprijeti'.","B":"'Doprjeli' je pogrešno napisano; pravilno je 'doprijeli'.","D":"'Doprli' je nepravilan oblik glagola doprijeti; pravilno je 'doprli/doprijeli' s ije."},
  "2019_ljeto_A__69": {"A":"Tri je premalo; prijedloga je pet (blizu, prije, pokraj, prema, izvan).","B":"Četiri je netočno; izostavlja se jedan od pet prijedloga.","D":"Šest je previše; u rečenici je pet prijedloga."},
  "2019_ljeto_A__70": {"B":"'Namignuo joj' je glagol s zamjeničkim dativom (sročnost/upravljanje), a ne pridruživanje.","C":"'Veliku čokoladu' je sintagma sa sročnošću pridjeva i imenice, ne pridruživanje.","D":"'Bocu vina' je sintagma s upravljanjem (imenica + genitiv), ne pridruživanje."},
  "2019_ljeto_A__71": {"A":"'Joj' je dativni dodatak, a ne dio predikata.","C":"'Je bilo' je samo kopula bez predikatnoga imena, pa nije potpun predikat.","D":"'Je' je tek dio kopule, a imenski predikat čine 'je bilo zeleno'."},
  "2019_ljeto_A__72": {"A":"U 'život bez ljubavi' imenica 'ljubav' je u prijedložnom izrazu (priložna oznaka), a ne atribut.","C":"U 'razgovarali o ljubavi' imenica je objekt/dopuna, ne atribut.","D":"U 'združiti u ljubavi' imenica je priložna oznaka, a ne atribut."},
  "2019_ljeto_A__73": {"A":"Šest je premalo; rečenica ima sedam surečenica.","C":"Osam je previše; surečenica je sedam.","D":"Devet je previše; ukupno je sedam surečenica."},
  "2019_ljeto_A__74": {"A":"'Zna se da...' je izrična (objektna) rečenica, a ne namjerna.","B":"'Voljeli su ga jer...' je uzročna rečenica, ne namjerna.","C":"'Doputovao je radi istine' nema zavisne surečenice; 'radi istine' je priložna oznaka u prostoj rečenici."},
  "2019_ljeto_A__75": {"B":"'Lijekovima obuhvaćenih' je pogrešna sročnost; treba 'obuhvaćenima' (dativ/instrumental).","C":"'Zato jer' je nepravilan veznik; pravilno je 'zato što' ili 'jer'.","D":"'Lagati svoje roditelje' je pogrešna rekcija; pravilno je 'lagati svojim roditeljima'."},
  "2019_ljeto_A__76": {"A":"'Kratica' nije vrsta interpunkcijskoga znaka, pa nije hiponim interpunkcije.","B":"'Pravopis' je nadređen pojam (hiperonim), a ne hiponim interpunkcije.","C":"'Rečenica' je jezična jedinica, a ne vrsta interpunkcijskoga znaka."},
  "2019_ljeto_A__77": {"A":"'Zločin i kazna ima' je dvojbeno; sročnost s naslovom čini rečenicu spornom, pa nije pouzdano točna.","C":"'Matrijali' je nepravilno; pravilno je 'materijali'.","D":"'Vjerovatno' je nepravilno; pravilno je 'vjerojatno'."},
  "2019_ljeto_A__78": {"A":"'Neravnopravnost' nastaje prefiksacijom i sufiksacijom u nizu izvođenja, ali ne istodobnom prefiksalno-sufiksalnom tvorbom kao 'narukvica'.","B":"'Basnopisac' je složenica (slaganje dviju osnova), a ne prefiksalno-sufiksalna tvorba.","C":"'Podnaslov' je nastao samo prefiksacijom (pod- + naslov)."},
  "2019_ljeto_A__79": {"B":"'Pokrenuti časopis' nema suvišnoga ponavljanja značenja, pa nije pleonazam.","C":"'Pokrenuti posao' je uobičajen, nepleonastičan izraz.","D":"'Pokrenuti vozilo' je doslovan i smislen izraz bez tautologije."},
  "2019_ljeto_A__80": {"A":"Ljetopis popa Dukljanina nije latinska isprava iz 852. niti najstarija hrvatska isprava.","C":"Bašćanska ploča je glagoljski spomenik iz oko 1100., a ne latinska isprava iz 852.","D":"Poljički statut je kasniji pravni spomenik, ne najstarija hrvatska isprava."},

  // 2019_ljeto_B
  "2019_ljeto_B__1": {"B":"Vojske se spominju uz ruke i njihove maštovite/ratoborne predjele, a ne kao stvarno sudjelovanje subjekta u razaranjima.","C":"Jezik je doduše 'stvoren za otmjenost', ali subjekt njime nije govorio otmjeno nego je 'klepetao' i upadao u nevolje.","D":"U pjesmi nema nikakve naznake da je subjekt zarađivao pišući; jezik mu donosi nedaće, ne zaradu."},
  "2019_ljeto_B__2": {"A":"Ruke odlaze u predjele mašte i s vojskama, što su predodžbene, a ne zvučne (auditivne) slike.","B":"Rebra su opisana kao 'radna, uvrijeđena', bez ikakve zvučne konotacije.","C":"Jetra odlaze u krčmu, motiv vezan uz piće i tjelesnost, a ne uz zvuk."},
  "2019_ljeto_B__3": {"A":"Destruktivnost (vojske, razaranje) pripisuje se desnoj ruci, a ne lijevoj.","B":"Uvrijeđena su rebra, a ne lijeva ruka.","D":"Lijeva je ruka izrijekom 'nespretna', dakle suprotno od spretne; spretnost bi prije pripadala desnoj."},
  "2019_ljeto_B__4": {"A":"Subjekt ne brine zbog nemogućnosti razgovora; žali zbog uvele ljepote drage osobe.","C":"Nije riječ o suosjećanju s tuđom patnjom, nego o žaljenju nad prolaznošću ljepote.","D":"Draga osoba nije izgubljena (umrla); izgubljena je njezina nekadašnja mladost i ljepota."},
  "2019_ljeto_B__5": {"B":"Pogled gospoje nije spomenut kao 'svitlos sončana'; sintagma se odnosi na njezinu mladost.","C":"Suze su pripisane lirskom subjektu ('suzami obraz moj'), a ne gospoji kao 'sunčana svjetlost'.","D":"Lice je označeno kao 'ličce biserno', a 'svitlos sončana' opisuje prošlu mladost, ne lice."},
  "2019_ljeto_B__6": {"A":"'Obraz' se odnosi na lice lirskog subjekta koje natapa suzama, a ne na gospoju.","B":"'Tuga' je osjećaj lirskog subjekta, a ne metafora za gospoju.","C":"'Želja' je apstraktni pojam ('u željah ljuvenu'), a ne naziv za gospoju."},
  "2019_ljeto_B__7": {"A":"Nestalnost se prikazuje motivom kola sreće, ali pripovjedač izravno proziva oholost, ne nestalnost.","C":"Prestrašenost se spominje uz moćnike koji trpe strah, ali nije osobina koju pripovjedač priziva u apostrofi.","D":"Zahvalnost se u tekstu ne tematizira kao prozvana ljudska osobina."},
  "2019_ljeto_B__8": {"A":"Prijenos vlasti na potomke nije sadržaj stiha; krv ovdje znači nasilje, a ne nasljeđivanje.","B":"Nezadovoljstvo podanika nije tema ovog stiha, nego način stjecanja vlasti.","D":"Strah vladara od podanika izražen je drugim stihovima, a ne ovim o 'krvi' i 'kruni'."},
  "2019_ljeto_B__9": {"A":"Ovaj stih govori o prolaznosti svih stvari pod suncem, a ne o izloženosti vladara opasnosti.","C":"Stih iskazuje bjegovitost svjetske postojanosti bez Božje pomoći, ne prvenstvo vladara u opasnosti.","D":"Stih opisuje da je careva glava ograđena od izdaje, dakle zaštićenost, a ne to da je prva na udaru."},
  "2019_ljeto_B__10": {"B":"Ne kaže se da se Bibijana okoristila novcem, nego da Kuntek uopće ne smije nositi novac.","C":"O njezinoj reakciji na izgubljeni novac nema riječi; ona zapravo Kunteku ne dopušta da novac ima kod sebe.","D":"Kartanje je zabranila, ali pitanje se odnosi na novac, a Ercigonja govori o tome da Kuntek ne nosi novčić."},
  "2019_ljeto_B__11": {"B":"O pomoći prijatelja nema spomena; novac je pribavljao kraćenjem pristojbe.","C":"Nije naplaćivao višu pristojbu, nego je prijavljivao manji iznos i razliku zadržavao.","D":"Kartanje mu je zabranjeno i igrao bi tek potajno za sitnice, što nije izvor njegova novca."},
  "2019_ljeto_B__12": {"B":"Pripovjedač se Kunteku podsmjehuje s humorom, a ne pokazuje stvarnu zabrinutost za njega.","C":"Lik se prikazuje komično i s ironijom, daleko od idealizacije.","D":"Poštovanje izostaje; odnos je obilježen blagim ruganjem, ne uvažavanjem."},
  "2019_ljeto_B__13": {"A":"Osveta je tek jedan od mnogih unutarnjih poriva; tema je širi prikaz Stjepkove ličnosti i stanja.","C":"Odnos prema gospi Marti spominje se usputno (preselila ložnicu), a nije težište teksta.","D":"Lovački trofeji dio su opisa prostora, a ne tema ulomka usmjerenog na unutarnji nemir."},
  "2019_ljeto_B__14": {"A":"Crni mramor nije usporedba za stanje duše; usporedba se gradi na vjetrovima.","B":"Svijetlo oružje pripada opisu prostorije, a ne usporedbi s dušom.","D":"Crna neman nije navedena slika; duša je uspoređena s vitlanjem silovitih vjetrova."},
  "2019_ljeto_B__15": {"B":"Na vrhu kreveta razapeta je medvjeđa koža, ali rogovi vise na njoj, ne izravno na krevetu.","C":"Kamin se kao mjesto rogova ne spominje u tekstu.","D":"Kaciga visi na medvjeđoj koži, ali rogovi nisu na kacigi nego također na koži."},
  "2019_ljeto_B__16": {"A":"Đuka Blaži ne zamjera viši društveni položaj; smeta mu njegova dvoličnost.","B":"Izlizane hlače spominju se kao znak licemjerne pobožnosti, a ne kao nemarno odijevanje.","C":"Bogobojaznost sama po sebi nije zamjerka; zamjera mu što kradljivac glumi pobožnost."},
  "2019_ljeto_B__17": {"A":"Blaža Đuku srdi, ali Mija ga srdi 'kao nijedan drugi', dakle više od Blaže.","B":"Jakša nije naveden kao onaj na koga se Đuka najviše ljuti.","D":"Tuna mu je samo smiješan i besposlen lik, a najviše ga srdi Mija."},
  "2019_ljeto_B__18": {"A":"Stolce i rakiju nije iznio kao zahvalu pomagačima, nego da se umili općinskoj gospodi.","B":"Cilj nije bio spasiti stvari od vatre, nego dodvoriti se utjecajnima.","D":"Nije riječ o odmoru gasitelja; Mija se prigiba pred gospodom i nudi rakiju iz ulizištva."},
  "2019_ljeto_B__19": {"B":"Za Durochera se kaže da je dolazio ovamo svake godine, dakle dolazio je.","C":"Za McGrawa stoji da je nekad dolazio na Terasu, dakle dolazio je.","D":"Za Sislera se sjećaju da je dolazio na Terasu, dakle dolazio je."},
  "2019_ljeto_B__20": {"A":"O Sislerovu prelasku iz Brooklyna nema riječi kao razlogu vodstva Jenkija.","B":"Usporedba snage s Brooklynom i Philadelphijom nije navedena kao starčev razlog.","D":"McGraw se spominje kao gost na Terasi, a ne kao trener koji vodi Jenkije."},
  "2019_ljeto_B__21": {"A":"Sislerov alkoholizam u tekstu se ne spominje kao razlog.","B":"Nigdje se ne kaže da je bio nepristojan i grub.","C":"Naprotiv, dvoje pretpostavljaju da bi 'možda i pristao'; problem je bila njihova suzdržanost."},
  "2019_ljeto_B__22": {"A":"Lorenzo ne pomaže iz straha da će Romeo propasti, nego zbog mogućnosti pomirenja obitelji.","C":"Lorenzo dvoji u iskrenost Romeove ljubavi (ruga mu se kao vjetrogonji), pa to nije njegov motiv.","D":"Rodbinska povezanost nije razlog; Lorenzo je redovnik koji se nada miru među zavađenim kućama."},
  "2019_ljeto_B__23": {"B":"Ne prigovara mu istodobno udvaranje većem broju djevojaka, nego brzu zamjenu Rosaline Julijom.","C":"Lorenzo se čudi Romeovoj promjenjivosti, ali ga ne naziva ludim.","D":"Žurba se spominje drugdje ('tko bez glave juri'), a vjetrogonjom ga naziva zbog površne ljubavi prema Rosalini."},
  "2019_ljeto_B__24": {"A":"Spletanje veze srdaca odnosi se na novu vezu s Julijom, a ne na Rosalinu.","B":"Posvećenje veze tiče se braka s Julijom, ne Rosaline.","D":"Davanje ljubavi za ljubav opisuje uzajamnost s Julijom, a ne Rosalinu."},
  "2019_ljeto_B__25": {"A":"Međusobna svađa svećenika nije ono što je naljutilo don Jeru.","B":"Ruganje don Florija biskupu nije izvor srdžbe; smeta dovođenje cirkusanta.","D":"Uvjerljivost lutke nije razlog ljutnje; ljuti ga prisutnost Flokija u biskupiji."},
  "2019_ljeto_B__26": {"B":"Flokija nije doveo don Jere; upravo se don Jere ljuti što je doveden.","C":"Pomirio se biskup s don Florijom, a ne Floki s don Florijom.","D":"Lutku Floki pokazuje biskupu (koga je osvojio), a ne don Jeri."},
  "2019_ljeto_B__27": {"B":"Cirkusant je Floki, a ne onaj koga je don Florijo zvao Pantalonom.","C":"Glumca don Florijo nije nazivao Pantalonom; nadimak se odnosi na biskupa.","D":"Isposnik se u tekstu ne spominje kao Pantalone."},
  "2019_ljeto_B__28": {"A":"Tekst ne govori o odbacivanju tradicionalnih vrijednosti, nego o suprotnostima u gradu.","B":"Sukob staleža jedan je vid kontrasta, ali temeljna je misao šira: Zagreb kao grad suprotnosti.","C":"Bogatstvo se pripisuje samo dijelu grada (Kaptolu), a ne Zagrebu u cjelini kao temeljnoj misli."},
  "2019_ljeto_B__29": {"A":"Donji grad opisuje se kao moderni grad rada i trgovine, bez izražene kritike građana.","B":"Stanovnici okolnih sela nisu predmet pripovjedačeve kritike.","D":"Grička birokracija opisuje se karakterno (birokratski Grič), ali kritika je usmjerena na crkvenu aristokraciju."},
  "2019_ljeto_B__30": {"A":"Odnos svjetovne i crkvene vlasti tema je usporedbe Griča i Kaptola, a ne usporedbe s Bečom i Berlinom.","B":"Radnički prosvjedi spominju se uz Donji grad, ali ne kao temelj usporedbe s Bečom i Berlinom.","C":"Usporedba se ne gradi na arhitekturi, nego na komforu kafana i hotela."},
  "2019_ljeto_B__31": {"A":"Anadiploza ponavlja završetak jednog stiha na početku sljedećeg, čega ovdje nema.","B":"Anafora bi tražila ponavljanje na početku stihova, a ovdje se 'sniva' ponavlja na kraju.","D":"Simploka spaja anaforu i epiforu, ali počeci stihova ('Na kuće' / 'Pustite') nisu jednaki."},
  "2019_ljeto_B__32": {"A":"Elipsa je izostavljanje dijela rečenice, čega u nabrajanju s ponovljenim 'i' nema.","B":"Eufemizam je ublažavanje izraza, što ovdje nije prisutno.","C":"Personifikacije (pridavanja ljudskih osobina neživom) u ovim stihovima nema."},
  "2019_ljeto_B__33": {"A":"Stopa od četiri sloga nije katren; katren je strofa.","B":"Stih od četiri stope ne naziva se katrenom.","D":"Pjesma od četiri strofe nije katren; katren je jedna četverostiha strofa."},
  "2019_ljeto_B__34": {"B":"Komedija karaktera temelji se na komici lika i njegovih osobina, a ne na verbalnim dosjetkama.","C":"Komedija situacije gradi smijeh na sklopu okolnosti i zabunama, ne na dosjetkama.","D":"Komedija intrige počiva na spletkama i zapletu, a ne na duhovitom razgovoru."},
  "2019_ljeto_B__35": {"B":"Reducirana fabula podređena psihičkom stanju obilježje je modernog, a ne tradicionalnog romana.","C":"Unutarnji monolog dominira u modernom romanu, ne u tradicionalnom.","D":"Nepouzdani pripovjedač u prvom licu obilježje je moderne proze, ne tradicionalnog romana."},
  "2019_ljeto_B__36": {"A":"Beowulf je staroengleski junački ep, ne sadrži Pjesmu nad pjesmama.","C":"Gilgameš je mezopotamski ep, a ne mjesto Pjesme nad pjesmama.","D":"Vede su svete indijske knjige i ne sadrže Pjesmu nad pjesmama."},
  "2019_ljeto_B__37": {"B":"Otkup Hektora dolazi na kraju Ilijade, a invokacija ističe Ahilejevu srdžbu.","C":"Otmica Helene povod je rata, ali nije motiv istaknut u invokaciji.","D":"Patroklova smrt zbiva se tek u kasnijem pjevanju, a nije predmet invokacije."},
  "2019_ljeto_B__38": {"B":"Pokop brata usprkos vladaru priča je o Antigoni, a ne o Prometeju.","C":"Osveta majci zbog ubojstva oca odnosi se na Oresta, ne na Prometeja.","D":"Ubojstvo oca i ženidba majkom sudbina je Edipa, a ne Prometeja."},
  "2019_ljeto_B__39": {"A":"Alkej je grčki lirik s Lezba, a ne rimski pjesnik.","B":"Anakreont je grčki lirik, ne pripada rimskoj književnosti.","D":"Pindar je grčki pjesnik (oda), a ne rimski."},
  "2019_ljeto_B__40": {"A":"Gundulić je barokni pjesnik (Osman, Suze sina razmetnoga), a ne petrarkist.","B":"Marulić pripada humanizmu i renesansi (Judita), nije petrarkist.","C":"Hektorović je renesansni pisac (Ribanje i ribarsko prigovaranje), a ne petrarkist."},
  "2019_ljeto_B__41": {"A":"Bokčilo je Dundov sluga, sklon jelu i piću, a ne ovoj filozofiji prilagodbe.","B":"Maro je rasipni mladi gospodar, a citirane riječi o 'akomodavanju' izgovara njegov sluga Pomet.","D":"Popiva je Tripčetov/drugi sluga, a navedenu životnu filozofiju iznosi Pomet."},
  "2019_ljeto_B__42": {"B":"Pjesnik kao junak alegorijske vizije zagrobnog života je Dante, ne don Quijote.","C":"Odgađanje osvete zbog sumnji odlika je Hamleta, a ne don Quijotea.","D":"Div koji nakon rođenja traži piće je Rabelaisov Gargantua, ne don Quijote."},
  "2019_ljeto_B__43": {"B":"Klasicizam naglašava red, razum i sklad, a ne baroknu sliku ništavnosti i prolaznosti.","C":"Romantizam ističe osjećaje i individualizam, a ne ovaj barokni vanitas-motiv.","D":"Realizam prikazuje zbilju objektivno, a navedeni stihovi izražavaju barokni svjetonazor prolaznosti."},
  "2019_ljeto_B__44": {"A":"Antun Kanižlić je slavonski pjesnik prosvjetiteljstva, ne pripadnik ozaljskog kruga.","C":"Juraj Habdelić je kajkavski pisac, ne predstavnik ozaljskog jezično-književnog kruga.","D":"Matija Petar Katančić pripada prosvjetiteljstvu/klasicizmu, a ne ozaljskom krugu."},
  "2019_ljeto_B__45": {"B":"Bovarizam (bijeg od stvarnosti u maštu) vezuje se uz realizam i Flaubertovu Gospođu Bovary.","C":"Gongorizam je barokni stilski pojam (po Góngori), a ne romantičarski.","D":"Petrarkizam pripada renesansnoj ljubavnoj lirici, ne romantizmu."},
  "2019_ljeto_B__46": {"A":"Laura je Petrarcina muza iz Kanconijera, a ne Wertherova draga.","C":"Sonja je lik iz Zločina i kazne, ne iz Patnji mladoga Werthera.","D":"Victorine je lik iz Balzacova Oca Goriota, a ne Wertherova ljubav."},
  "2019_ljeto_B__47": {"A":"Opis žene koja shvaća muževo licemjerje i odlučuje ga napustiti ne odgovara Dunji.","B":"Bespomoćna supruga isključena iz odgoja djece nije Dunja Raskoljnikova.","D":"Udaja za krčmarova sina uz pasivni otpor ne odnosi se na Dunju, koja se sama odlučuje na žrtvu za brata."},
  "2019_ljeto_B__48": {"B":"Miloš Radak je pošteni junak (hajduk), a ne intrigant u Zlatarovu zlatu.","C":"Petar Krupić je zlatar, Dorin otac, pozitivan lik, a ne spletkar.","D":"Stjepko Gregorijanec je moćni protivnik, ali glavni intrigant je brijač Grga Čokolin."},
  "2019_ljeto_B__49": {"A":"Ante Stipančić (Glembajevi/Stipančići) ne završava u požaru sa sudskim spisom.","B":"Đuka Begović ima drukčiju sudbinu i ne gori s registraturom.","C":"Đuro Martić nije lik koji izgara zajedno s registraturnim spisom o ženi."},
  "2019_ljeto_B__50": {"A":"Matoš je pisao na štokavštini, a ne na čakavskom narječju.","B":"Dragutin Domjanić pisao je na kajkavskom narječju, ne na čakavskom.","C":"Fran Galović poznat je po kajkavskoj lirici (Z mojih bregov), a ne čakavskoj."},
  "2019_ljeto_B__51": {"A":"Povratak Filipa Latinovicza je Krležin roman bez scene s madeleine kolačićem.","B":"Prokleta avlija (Andrić) zbiva se u carigradskom zatvoru, bez Proustova motiva čaja i kolačića.","D":"Kiklop (Marinković) ne sadrži scenu s madeleine i tetkom Léonie."},
  "2019_ljeto_B__52": {"B":"Krugovi su časopis 1950-ih (poslijeratna generacija), a ne Šimićev list.","C":"Razlog je časopis 1960-ih, znatno nakon Šimića.","D":"Vijavicu nije uređivao A. B. Šimić; on je pokrenuo i uređivao Kokot."},
  "2019_ljeto_B__53": {"A":"Balade Petrice Kerempuha (1936.) su zrela kajkavska lirika, ne ekspresionistička faza.","B":"Gospoda Glembajevi pripadaju kasnijoj, realistično-psihološkoj fazi.","D":"Na rubu pameti je kasniji roman, a ne djelo ekspresionističke faze."},
  "2019_ljeto_B__54": {"A":"Prokleta avlija nije arheološko nalazište, nego zatvor.","B":"Nije riječ o vojnoj bolnici, nego o carigradskom zatvoru.","C":"Prokleta avlija nije samostan; to je zloglasni zatvor."},
  "2019_ljeto_B__55": {"A":"Antun Mihanović autor je Horvatske domovine (Lijepe naše), a ne ovih stihova.","C":"Ljudevit Gaj poznat je kao preporoditelj i autor budnice Još Horvatska, ne ovih stihova.","D":"Petar Preradović nije autor navedenih stihova; oni su Mažuranićevi."},
  "2019_ljeto_B__56": {"A":"'Podsjetili' je doduše ispravno napisano, ali pitanje traži jednu točnu, a ovdje ih je više pa A nije ciljani odgovor.","C":"'Potcijenio' je pogrešno; pravilno je 'podcijenio' (pod- + cijeniti).","D":"'Nadprirodne' je pogrešno; pravilno je 'natprirodne' (jednačenje d→t pred p)."},
  "2019_ljeto_B__57": {"A":"'Djevojćičin' je pogrešno; pravilno je 'djevojčičin' (s č).","C":"'Čistaćičin' je pogrešan oblik; čistačica daje 'čistačičin'.","D":"'Crtaćičin' je pogrešan oblik; crtačica daje 'crtačičin'."},
  "2019_ljeto_B__58": {"A":"'Bijelina' je pogrešno; pravilno je 'bjelina' (kraćenje ije u je).","B":"'Lijenost' je ispravna, ali ovdje se traži par u kojem su obje riječi točne, a to je par s 'zvijezda'.","C":"'Slijepoća' je pogrešno; pravilno je 'sljepoća'."},
  "2019_ljeto_B__59": {"A":"Pogrešno je 'Renesanse' i 'Bugarštice' velikim slovom; oba su pojma opće imenice (malo slovo).","B":"Pogrešno je 'Ulici'; veliko se piše samo 'Republika Austrija' u nazivu ulice, a 'ulica' malim.","C":"Pogrešno je 'zapadnoga rimskog carstva' malim; treba 'Zapadno Rimsko Carstvo' velikim."},
  "2019_ljeto_B__60": {"B":"'Anti-tijela' je pogrešno; pravilno se piše sastavljeno 'antitijela'.","C":"'Ptica-pjevica' je pogrešno; piše se bez crtice (ptice pjevice).","D":"'Vice-prvaci' je pogrešno; piše se bez crtice (viceprvaci)."},
  "2019_ljeto_B__61": {"A":"'Gozba' nastaje jednačenjem po zvučnosti (t→z), a ne palatalizacijom.","B":"'Lišće' nastaje jotacijom (st + je), a ne palatalizacijom.","C":"'Mišlju' nastaje jotacijom (s + lj), a ne palatalizacijom."},
  "2019_ljeto_B__62": {"B":"U 'hokejaš' nema nepostojanog a; a se ne gubi u sklonidbi (hokejaš, hokejaša).","C":"U 'pjevač' nema nepostojanog a; oblik glasi pjevač, pjevača.","D":"U 'konobar' a se zadržava u svim padežima (konobar, konobara), pa nije nepostojano."},
  "2019_ljeto_B__63": {"A":"Kratkouzlazni naglasak bilježi se znakom è, a ne ȅ.","C":"Dugouzlazni naglasak bilježi se znakom é, a ne ȅ.","D":"Dugosilazni naglasak bilježi se znakom ê, a ne ȅ."},
  "2019_ljeto_B__64": {"A":"'Jad-' je korijenski (leksički) morfem, a ne oblikotvorni.","B":"'-n-' je tvorbeni (rječotvorni) sufiks, a ne gramatički morfem.","C":"'-ik-' je tvorbeni sufiks, a ne oblikotvorni morfem."},
  "2019_ljeto_B__65": {"A":"'germanskim plemenima' uz glagol naseliti je instrumental, a ne lokativ.","C":"'među starim plemenima' je instrumental (prijedlog među), a ne lokativ.","D":"'svim okupljenim plemenima' uz 'obratio se' je dativ, a ne lokativ."},
  "2019_ljeto_B__66": {"A":"'Njihovi' je posvojna, a ne osobna zamjenica.","B":"'Se' je ovdje povratna zamjenica, ne osobna.","C":"'Se' (držao se) je povratna zamjenica, a ne osobna."},
  "2019_ljeto_B__67": {"B":"'Širji' je nestandardan oblik; pravilni komparativ je 'širi'.","C":"'Širiji' je nestandardno; ispravno je 'širi'.","D":"'Širokiji' je nepravilno; komparativ glasi 'širi'."},
  "2019_ljeto_B__68": {"B":"Glagolski pridjev trpni završava na -n/-t (npr. ugledan), a 'ugledavši' je prilog.","C":"Imperfekt bi glasio npr. 'gledah', a 'ugledavši' je glagolski prilog prošli.","D":"Aorist bi glasio 'ugledah', a podcrtani je oblik glagolski prilog prošli."},
  "2019_ljeto_B__69": {"A":"'Pozvao' je dio kondicionala drugog / pogodbe ('da sam pozvao'), a ne kondicional prvi.","C":"'Nadajući se' je glagolski prilog sadašnji, a ne kondicional.","D":"'Ćete pričati' je futur prvi, a ne kondicional prvi."},
  "2019_ljeto_B__70": {"B":"Ispred 'č' (četvoricom) dolazi 's', a ne 'sa'; pravilno je 's četvoricom'.","C":"Ispred 'đ' (đacima) dolazi 's'; pravilno je 's đacima', ne 'sa'.","D":"Ispred 'E' (Englezima) dolazi 's'; pravilno je 's Englezima', ne 'sa'."},
  "2019_ljeto_B__71": {"A":"'Naporno se penjući' je priložna (nesročna) veza priloga i glagolskog priloga, bez slaganja u rodu, broju i padežu.","B":"'Penjući se satima' nije sročna sintagma; 'satima' je priložna oznaka, a ne kongruentni atribut.","D":"'Su se popeli na Zavižan' je predikat s dopunom, a ne sročna (kongruentna) sintagma."},
  "2019_ljeto_B__72": {"A":"'Hladnim napitkom' je instrumentalna dopuna (čime), a ne izravni objekt u akuzativu.","B":"'O školskim obvezama' je prijedložni (neizravni) objekt, a ne izravni.","D":"'Nešto' je subjekt u nominativu, a 'Ivani' dativ; izravnog objekta nema."},
  "2019_ljeto_B__73": {"B":"'Morao stići kupiti' izostavlja 'bih', pa nije potpun oblik predikata (nedostaje kondicionalna sastavnica).","C":"'Morao bih stići' izostavlja infinitiv 'kupiti', pa ne obuhvaća cijeli glagolski niz.","D":"'Stići kupiti' je samo dio predikata bez modalnoga 'morao bih'."},
  "2019_ljeto_B__74": {"A":"Tri je premalo; uz uvjetnu, suprotnu i glavnu postoji i zavisna 'gdje me možete pronaći'.","C":"Pet je previše; u rečenici se broje četiri surečenice.","D":"Šest je previše; surečenica je ukupno četiri."},
  "2019_ljeto_B__75": {"A":"'Kako ni slučajno ne bi zakasnio' je namjerna rečenica, ne uzročna.","C":"'Toliko se bojao... da je ustao' je posljedična rečenica, a ne uzročna.","D":"'Da ni slučajno ne zakasni' je namjerna rečenica, ne uzročna."},
  "2019_ljeto_B__76": {"A":"Pogreška: 'ostavljenim' treba biti u genitivu množine ('pustolova ostavljenih'), slaganje nije provedeno.","B":"Pogreška: glagol rugati se traži dativ ('rugali su mu'), a ne akuzativ ('ga').","C":"Pogreška: ispravno je 'ovisi o razvoju', a ne 'ovisi od razvoja'."},
  "2019_ljeto_B__77": {"B":"'Bliskost' i 'blizina' su bliskoznačnice (sinonimi), a ne antonimi.","C":"'Cvijet' i 'tulipan' su u hiponimnom odnosu (tulipan je vrsta cvijeta), ne antonimnom.","D":"'Laž' i 'neistina' su sinonimi, a ne antonimi."},
  "2019_ljeto_B__78": {"B":"'Danima' je instrumental množine, a ne kanonski (nominativ jednine) oblik.","C":"'Dvorišta' je ovdje genitiv jednine, a ne kanonski oblik.","D":"'Razgovora' je genitiv jednine, a ne kanonski oblik imenice."},
  "2019_ljeto_B__79": {"A":"'Ubiti dvije muhe jednim udarcem' znači postići dvije koristi jednim potezom, a ne pogoršati položaj.","B":"'Tjerajući lisicu istjerao vuka' znači riješiti manji problem i stvoriti veći, a ne prijeći iz boljeg u gori položaj.","D":"'Pojeo vuk magare' znači da je nešto nepovratno propalo/nestalo, a ne prelazak iz boljega u gore."},
  "2019_ljeto_B__80": {"A":"Vjekoslav Babukić djeluje u 19. st. (preporodna gramatika), a ne kao autor prve tiskane gramatike.","B":"Faust Vrančić sastavio je rječnik (Dictionarium), a ne prvu gramatiku.","D":"Ljudevit Gaj reformirao je pravopis i slovopis, ali nije autor prve tiskane gramatike."},

  // 2020_jesen_A
  "2020_jesen_A__1": {"A":"Lirski subjekt se ne uzdiže nad obične ljude, nego cijeni jednostavnost i bliskost (kad se prijateljski živi).","B":"Mudrost narodnih pripovjedaka nije izvor utjehe; gatke su mu, naprotiv, umrle (S vijekom moje duše umrle su gatke).","D":"Divljenje drugih ne čini život podnošljivim; podnošljivost donosi spokoj doma (patnje kad se u kutu mirna doma drijemlje)."},
  "2020_jesen_A__2": {"A":"Stih o preranom rođenju izražava nesklad sa svijetom, a ne zaljubljenost u sebe.","B":"Ljubav prema sitnim i nevažnim stvarima iskazuje skromnost, a ne samodopadnost.","D":"Divljenje pravoga čovjeka odnosi se na buduće priznanje izvana, a ne na subjektovu zaljubljenost u sebe."},
  "2020_jesen_A__3": {"A":"Ravnodušnost zemlje izražava nesklad subjekta sa svijetom, a ne njegovu skromnost.","C":"Klupko borbe upućuje na životnu borbu/zamršenost, a ne na skromnost.","D":"Crni usud označava tešku sudbinu, a ne skromnost lirskoga subjekta."},
  "2020_jesen_A__4": {"A":"Konji ne vuku tijelo prema podzemlju; o Aidovu domu govori Andromahina tužaljka, a ne smjer vuče tijela.","B":"Gora Plak vezana je uz Andromahino podrijetlo (rođena u Tebi pod Plakom), a ne uz smjer vuče Hektorova tijela.","D":"Teba je Andromahin rodni grad, a ne odredište kamo konji vuku Hektorovo tijelo."},
  "2020_jesen_A__5": {"A":"Andromahina zabrinutost ne proizlazi iz sažaljenja dvorjanika, nego iz gubitka oca i sigurnosti.","C":"Strah nije zbog ranjavanja u borbi, nego zbog života bez oca i bez nasljedstva.","D":"Sin nije poludio; problem je sirotovanje nakon očeve smrti (sirotovanja dan dječaku otima druge)."},
  "2020_jesen_A__6": {"A":"Trojanskim ženama Andromaha govori (med ženama trojanskim reče), no obraća se izravno Hektoru.","C":"Zaplakanomu sinu nije upućen ovaj govor; tužaljka je upravljena mrtvomu Hektoru.","D":"Muževljevim prijateljima ne obraća se; oslovljava poimence Hektora (Hektore...)."},
  "2020_jesen_A__7": {"A":"Pukovnik ne kaže da tlapnja zavarava, nego da hrani, daje nadu (hranjiva je).","B":"Tvrdnja da se od tlapnje ne može živjeti suprotna je smislu da je hranjiva.","C":"Pukovnik ne tvrdi da je tlapnja štetna za siromahe, nego naglašava njezinu okrepljujuću ulogu."},
  "2020_jesen_A__8": {"A":"Sleganje ramenima čini službenik, a ne pukovnik, i nije znak mirenja sa sudbinom.","B":"Pristanak na kukuruznu kašu nije razlog ženina zaključka o mirenju sa sudbinom.","C":"Pukovnikova laž o tome o čemu razmišlja ne otkriva mirenje sa sudbinom, nego prikrivanje misli."},
  "2020_jesen_A__9": {"A":"Službenik nije izbjegao pregled; upravo je sve pregledao (Kad je sve pregledao).","B":"Tekst ne spominje neoznačenu pregradicu; tražio je po označenim pregradcima.","C":"U tekstu nema vijesti o smrti voljene osobe u pismu; pismo uopće nije pronađeno."},
  "2020_jesen_A__10": {"A":"Kožne torbe nisu mu se činile sličnima njemu, nego stranima, kao simboli nedokučive zemlje.","C":"Galip zna gdje je; samo mu se zbog nesanice Istanbul čini drugačijim, a ne nepoznatim gradom.","D":"Tekst ne navodi da se izgubio u Kapaličaršiji; nesanica mijenja njegov doživljaj, a ne orijentaciju."},
  "2020_jesen_A__11": {"A":"Tekst ne navodi da ga je prodavač prepoznao ispred izloga.","C":"Galip ne otkriva prijevaru; tek osjeća da je sagove već vidio.","D":"Nema spomena da je Galip zaprljao izložene sagove."},
  "2020_jesen_A__12": {"B":"Riječ se ne odnosi na Galipa, nego na priču dućana (njegovu priču).","C":"Riječ se ne odnosi na život, nego na dućan čija se povijest poznaje kao vlastiti život.","D":"Riječ se ne odnosi na Istanbul, nego na konkretni dućan i njegovu priču."},
  "2020_jesen_A__13": {"A":"Rečenica ne govori o rastuživanju bliskih osoba plakanjem, nego o izvoru njezinih osjećaja.","C":"Ne radi se o zabrani zaboravljanja roditelja, nego o tome da njome upravljaju unutarnje sile (Čopleki).","D":"Rečenica se ne tiče sitnih popravaka, nego nemogućnosti da sama upravlja svojim osjećajima."},
  "2020_jesen_A__14": {"B":"Otac nije sramežljiv; ponaša se distancirano i pristojno, kao prema klijentu.","C":"Ponašanje nije srdačno, nego hladno i službeno (laka pristojnost bez ostataka i žaljenja).","D":"Otac ne pokazuje sućut, nego ravnodušnu službenost (rješava me se kao i klijenata)."},
  "2020_jesen_A__15": {"A":"Izraz se ne odnosi na susjede, nego na unutarnje stanje pripovjedačice.","C":"Izraz se ne odnosi na obitelj, nego na njezino unutarnje (duševno/tjelesno) stanje.","D":"Riječ je o metafori unutarnjega stanja, a ne o stvarnoj kući (slabosti zidova označavaju ranjivost subjekta)."},
  "2020_jesen_A__16": {"A":"Izreka ne govori o obvezi udaje za udovca, nego o trajnim posljedicama kasne udaje.","B":"Izreka ne govori o braku sa starijim muškarcem kao izvoru teškoća, nego o usidjelištvu i njegovu trajnom biljegu.","D":"Izreka ne tvrdi da neudana žena postaje poročna, nego da kasna udaja ostavlja trajne posljedice (opekotine do kraja života)."},
  "2020_jesen_A__17": {"A":"U odijevanju Anđelija nije bila sitničava; po njemu je tek prosuđivala ljude, ali je cjepidlačila u čistoći.","B":"U pripremi jela nije bila sitničava; cjepidlačila je u čistoći.","C":"U izboru pića nije bila sitničava; po jelu, piću i odijevanju samo je cijenila ljude, a cjepidlačila je u čistoći."},
  "2020_jesen_A__18": {"A":"Zid nije metafora njezine najveće vrijednosti u obitelji.","B":"Kolijevka nije metafora kojom se izriče da je sebe doživljava najvrednijom.","D":"Oluja označava nevolju iz koje spašava (olujna noć), a ona se vidi kao svjetlost/svjetionik, ne kao oluja."},
  "2020_jesen_A__19": {"A":"U devet sati Julija je poslala dojilju, a razgovor se vodi tri sata poslije.","B":"U pola deset dojilja se trebala vratiti, no nije; razgovor je tek u podne.","D":"Tri sata označava proteklo vrijeme (tri su duge ure), a ne trenutak razgovora; razgovor je u podne."},
  "2020_jesen_A__20": {"A":"Glasnici ne gone mrak; oni bi trebali biti brzi poput misli.","B":"Let je način kretanja zraka, a ne ono što goni mrak.","D":"Mrak je ono što se goni, a ne ono što gone (zrake gone mrak)."},
  "2020_jesen_A__21": {"A":"Romeo se ne opisuje kao plašljiv poput janjeta.","C":"Naglasak nije na njegovu pristojnom vladanju, nego na tjelesnoj građi.","D":"O nagloj naravi ne govori se; istaknuta je tjelesna stasitost."},
  "2020_jesen_A__22": {"A":"Proroci, bogovi i grešnici nisu kradljivci umjetnina, nego naslikani likovi.","C":"Nije riječ o kipovima, nego o likovima razlivenima preko stropa (fresci).","D":"Nisu sluge; sluge (famulusi) gledaju te naslikane likove."},
  "2020_jesen_A__23": {"A":"Patnička rabota nije prikradanje slugu, nego slikarov mukotrpni noćni rad.","C":"Izraz se ne odnosi na slikarovu nesanicu, nego na sam njegov rad.","D":"Penjanje po skelama čine famulusi; patnička rabota je slikarov rad."},
  "2020_jesen_A__24": {"A":"Prizivanje vještica nije razlog; famulus drži da slike krše pravila crkvenog slikarstva.","C":"Razlog nije zabrana gledanja slika, nego njihova navodna neprimjerenost za crkvu.","D":"Famulus ne traži sud zato što je slikar prestao slikati, nego zato što su slike neprimjerene (pred tribunalom Inkvizicije)."},
  "2020_jesen_A__25": {"A":"Čitanje tuđih djela ne navodi se kao preduvjet dugotrajnoga pisanja; to je psihofizička kondicija.","B":"Pisanje od mladosti nije navedeni preduvjet; ključ je psihofizička sprema.","D":"Zdrava prehrana nije izrijekom preduvjet; autor govori o psihofizičkoj kondiciji (tjelesnoj i mentalnoj)."},
  "2020_jesen_A__26": {"B":"Usporedba nije u istovremenom iscrpljivanju tijela i duše, nego u spoju užitka i opasnosti.","C":"Riba fugu ne uspoređuje se po kreativnoj pripremi, nego po tome da je najslasniji dio uz otrov.","D":"Usporedba nije u izazivanju ovisnosti, nego u tome da slast (užitak) graniči s otrovom (opasnost)."},
  "2020_jesen_A__27": {"A":"Književno potrošeni nisu oni čija djela dobivaju vrijednost u starosti, nego oni kojima kreativnost slabi.","B":"Izraz se ne odnosi na one koji pisanje drže nezdravim, nego na one koji gube stvaralačku snagu.","D":"Ne radi se o zastarjelosti djela, nego o slabljenju kreativne snage pisaca."},
  "2020_jesen_A__28": {"B":"Smisao je suprotan: masovnost pisanja snižava kvalitetu, a ne da svatko marljiv može postati dobar pisac.","C":"Tekst ne govori o zabrani pisanja, nego o tome da masovnost slabi kvalitetu.","D":"Tekst ne potiče na što više pisanja, nego upozorava da gdje svako piše, tamo se ne piše."},
  "2020_jesen_A__29": {"A":"Književništvo od zanata autor ocjenjuje negativno (pisac postaje trgovac koji laska čitatelju).","B":"Računanje s čitaocem autor smatra negativnim jer vodi laskanju, a ne pozitivnim.","D":"Dirinčiti noć na noć (kao Balzac zbog dugova) autor vidi negativno, kao robovanje novcu."},
  "2020_jesen_A__30": {"A":"Tolstoj se ne navodi kao primjer pisca koji robuje novcu.","C":"Flaubert je naveden kao pozitivan primjer pomna pisca (jedna knjiga u deset godina), a ne kao rob novca.","D":"Pope se ne navodi kao primjer pisca koji robuje novcu."},
  "2020_jesen_A__31": {"B":"Početna slova stihova (V, O, D, A) ovdje nisu istaknuta kao oblikotvorni akrostih u traženom smislu; točan je primjer A s nizom T-S-D-N.","C":"Primjer se temelji na razmaknutim slovima riječi (dobro jutro, more zlato), a ne na akrostihu (čitanju početnih slova stihova).","D":"Primjer nema akrostiha; početna slova stihova ne tvore skrivenu riječ."},
  "2020_jesen_A__32": {"A":"Tragedija izvorno ne znači božanska pjesma.","C":"Tragedija izvorno ne znači posmrtna pjesma.","D":"Tragedija izvorno ne znači žalosna pjesma, nego jarčeva pjesma (tragos + oide)."},
  "2020_jesen_A__33": {"A":"Nije epifora; nema ponavljanja istih riječi na kraju stihova.","B":"Nije eufemizam; nema ublažavanja neugodna pojma, nego prividne proturječnosti.","D":"Nije usporedba; nema poredbenoga veznika ni dovođenja dvaju pojmova u odnos sličnosti."},
  "2020_jesen_A__34": {"B":"Ulice nisu naglašene inverzijom; ponavlja se i ističe riječ krv.","C":"Milost nije naglašeni motiv; inverzijom je istaknuta krv na početku stihova.","D":"Sulice nisu motiv naglašen izmijenjenim redom riječi; to je krv."},
  "2020_jesen_A__35": {"B":"Stihovi o jeseni ovijenoj maglama temelje se na atmosferi/personifikaciji, a ne na antitezi.","C":"Stih o skrivanju od ljudi ne sadrži suprotstavljanje pojmova (antitezu).","D":"Slika svitanja i pojave Pana nije izgrađena na antitezi suprotnih pojmova."},
  "2020_jesen_A__36": {"A":"Agamemnon nije nosio Ahilejevu opremu niti ga je ubio Hektor.","B":"Menelaj nije borac u Ahilejevoj opremi kojega ubija Hektor.","C":"Paris je Trojanac (Hektorov brat), a ne Ahejac koji se bori u Ahilejevoj opremi."},
  "2020_jesen_A__37": {"A":"Alkej je grčki, a ne rimski pjesnik.","B":"Anakreont je grčki liričar, ne rimski.","D":"Pindar je grčki pjesnik (oda), a ne rimski."},
  "2020_jesen_A__38": {"A":"Edip se ne objesi; objesi se Jokasta.","C":"Edip ne pije otrov.","D":"Edip se ne probada mačem, nego se oslijepi (kopčama s Jokastine haljine)."},
  "2020_jesen_A__39": {"A":"Beowulf je junak staroengleskoga (germanskoga) epa, a ne španjolskoga.","C":"Holoferno je biblijski lik (Juditina priča), a ne junak španjolskoga epa.","D":"Roland je junak francuskoga epa (Pjesma o Rolandu), a ne španjolskoga."},
  "2020_jesen_A__40": {"A":"Dante je živi pjesnik koji prolazi paklom, a ne onaj koji je živio prije Krista.","B":"Haron je prijevoznik duša, na njega se ne odnosi razlog boravka u paklu prije Krista.","C":"Minos je sudac duša u paklu, a citat o životu prije Krista odnosi se na Vergilija."},
  "2020_jesen_A__41": {"B":"Ranjinin zbornik vezan je uz dubrovačko pjesništvo (Menčetić, Držić), a ne uz Šižgorića.","C":"Najznamenitiji budimski humanist je Janus Pannonius, a ne Šižgorić.","D":"Stihove Rimljanki Flaviji posvetio je drugi humanist (Ilija Crijević), a ne Šižgorić."},
  "2020_jesen_A__42": {"A":"Dundo Maroje ne dolazi prvi put u grad kao stranac u potrazi za prenoćištem.","B":"Pomet je dubrovački sluga-spletkar, a ne stranac koji je sinoć stigao u grad.","C":"Skup je škrtac iz istoimene komedije, a ne došljak koji traži stan."},
  "2020_jesen_A__43": {"B":"Marinizam je talijanski barokni pokret (Marino), a ne španjolski.","C":"Petrarkizam je ljubavni renesansni pravac (po Petrarki), a ne španjolski barok.","D":"Verizam je talijanski realistički pravac, a ne španjolski barok."},
  "2020_jesen_A__44": {"A":"Dva prologa i govor o dvjema vrstama ljudi nisu obilježje Škrca.","B":"Razotkrivanje mana škrtaca preko pametna đaka ne opisuje Molièreova Škrca.","D":"Praćenje uspona građanske obitelji nije tema Škrca."},
  "2020_jesen_A__45": {"A":"Tipični likovi u tipičnim okolnostima obilježje su realizma, a ne romantizma.","B":"Oponašanje antičkih uzora obilježje je klasicizma, a ne romantizma.","D":"Utjecaj racionalizma vezan je uz prosvjetiteljstvo/klasicizam, a romantizam mu se suprotstavlja."},
  "2020_jesen_A__46": {"A":"Đuro Drašković nije gospodar Medvedgrada koji umirući oporučno spominje Krupića.","B":"Franjo Tahi je protivnik (gospodar Susjedgrada), a ne gospodar medvedgradski koji umire.","C":"Gašpar Alapić nije gospodar Medvedgrada iz ovoga prizora."},
  "2020_jesen_A__47": {"A":"Spremnost na brak bez ljubavi radi spasa od guvernantstva i pomoći bratu odnosi se na Dunju, a ne na Sonju.","C":"Žena okorjeloga pijanca je Katarina Ivanovna, a ne Sonja.","D":"Sestra lihvarice koja postaje slučajna žrtva ubojstva je Lizaveta, a ne Sonja."},
  "2020_jesen_A__48": {"B":"Siromašni sin seoskoga muzikaša koji strada u požaru nije Juraj Stipančić.","C":"Odustajanje od svećeničkoga zvanja nije obilježje Jurja Stipančića.","D":"Slavonski bećar učen pijančevanju nije Juraj Stipančić."},
  "2020_jesen_A__49": {"A":"Đulabije (Vraz) pripadaju razdoblju ilirizma/romantizma, a ne početku moderne.","C":"Muljika ne označava početak hrvatske moderne.","D":"Prijan Lovro (Kovačić) djelo je realizma, a ne početak moderne."},
  "2020_jesen_A__50": {"A":"Futurizam ne započinje u Francuskoj.","C":"Futurizam ne započinje u Njemačkoj (ondje se javlja ekspresionizam).","D":"Futurizam ne započinje u Švicarskoj (ondje nastaje dadaizam)."},
  "2020_jesen_A__56": {"A":"Nije točno: dospjevati treba glasiti dospijevati.","C":"Nije točno: presjedati treba glasiti presjedavati.","D":"Nije točno: zastarjevati treba glasiti zastarijevati."},
  "2020_jesen_A__57": {"A":"Svećenićke je netočno; pravilno je svećeničke.","B":"Spavačicu je netočno; pravilno je spavaćicu.","D":"Puhačim je netočno; pravilno je puhačkim."},
  "2020_jesen_A__58": {"A":"Babilonskih treba malim slovom (babilonskih) jer je posvojni pridjev od naroda.","B":"Zviježđa je opća imenica i piše se malim slovom.","C":"Antici se ovdje piše malim slovom (antika kao razdoblje), pa nije točno napisano."},
  "2020_jesen_A__59": {"A":"U miješalici nema sibilarizacije; to je glagolska osnova, a ne dotični glas ispred i.","B":"U dasci dolazi do sibilarizacije? Ne odnosi se na traženu riječ; u salatu/dasci nije podcrtana provedena sibilarizacija kao u vazi.","C":"U snijega nema sibilarizacije; glas g ovdje nije u položaju koji bi je izazvao u podcrtanoj riječi."},
  "2020_jesen_A__60": {"A":"Shakespeare-a je netočno; nastavak se na ime sa završetkom -e dodaje bez spojnice (Shakespearea).","B":"Kamen temeljac piše se bez spojnice (dvije riječi), pa kamen-temeljac nije točno.","D":"Kanu-u je netočno; pravilno je kanuu (bez spojnice)."},
  "2020_jesen_A__61": {"B":"Pjeva- nije korijenski morfem, nego korijen sa spojnikom; korijen je pjev-.","C":"Pjevač- nije korijen, nego korijen s tvorbenim sufiksom.","D":"Pjevačic- obuhvaća više morfema (korijen + sufikse), a nije sam korijenski morfem."},
  "2020_jesen_A__62": {"A":"Sela je nominativ množine (subjekt), a ne genitiv.","B":"Ju je akuzativ (zamjenica u funkciji objekta), a ne genitiv.","C":"Anđela je akuzativ (skinuli koga), a ne genitiv."},
  "2020_jesen_A__63": {"B":"Majčin (bol) je u muškom rodu jer se slaže s imenicom bol (m. r.).","C":"Bratova (djela) je u srednjem rodu (množina), a ne u ženskom.","D":"Očevu (radost) je ovdje u ženskom rodu po imenici radost? Naglasak je na sestrinu (jasno ž. r.); očevu je uz radost (ž. r.), no traženi je jednoznačni primjer A."},
  "2020_jesen_A__64": {"A":"Kojega uz neživo (zvuk) nije pravilno; treba koji (akuzativ jednak nominativu).","C":"Naše uz sve vrijeme svijeta nije sročno; trebalo bi naše vrijeme bez te neusklađenosti.","D":"Naš (plan) ovdje nije sporna zamjenica koja se traži; pravilno upotrijebljena je nikoga u B."},
  "2020_jesen_A__65": {"A":"Potaknuli (perfekt svršeni) ovdje je gramatički u redu.","C":"Priznavaju (prezent) nije sporan oblik u rečenici.","D":"Izvikivati (infinitiv) gramatički je ispravan."},
  "2020_jesen_A__66": {"A":"Četvrt (ž. r.) i Jarun (m. r.) nisu sročni u rodu.","B":"Grad (m. r.) i Vodice (ž. r. mn.) nisu sročni u rodu."},
  "2020_jesen_A__67": {"A":"Jutros je donijela je priložna (vremenska) veza, a ne atributna sintagma.","B":"Donijela mi je sadrži glagol i zamjenicu (objekt), nije atributna sintagma.","C":"Donijela je kolač je predikat s objektom (predikatno-objektna veza), a ne atributna sintagma."},
  "2020_jesen_A__68": {"A":"Maslinama (o trgovanju maslinama) ovdje je dio priložne oznake/atributa, a ne objekt.","B":"Maslinama (pogača s maslinama) ima ulogu atributa/priloga, a ne objekta.","D":"Maslinama (proširio se maslinama) je priložna oznaka mjesta, a ne objekt."},
  "2020_jesen_A__69": {"A":"Tri surečenice je premalo; u rečenici ih je pet.","B":"Četiri surečenice je premalo; ima ih pet.","D":"Šest surečenica je previše; ima ih točno pet."},
  "2020_jesen_A__70": {"A":"Da-rečenica uz odlučeno je subjektna (objektna), a ne atributna.","B":"Da-rečenica uz molili smo je objektna (izrična), a ne atributna.","C":"Da bi-rečenica uz sastali su se je namjerna (priložna), a ne atributna."},
  "2020_jesen_A__71": {"B":"Mojemu ostavljeno nepromijenjeno nije pravilno; u neupravnom govoru perspektiva se mijenja u svojemu.","C":"Njegovu pogrešno upućuje na drugu osobu; treba povratno-posvojna svojemu (otac je govornikov).","D":"Njezinu upućuje na žensku osobu i nije ispravno; otac pripada govorniku, pa je svojemu."},
  "2020_jesen_A__72": {"A":"Netočno: braća (zbirna, sr. r. jd.) traži slaganje u jednini: braća su se odškolovala.","B":"Netočno: većina su slala treba glasiti većina je slala (slaganje u jednini).","D":"Netočno: majka se složila ispisati me nije gramatički u redu; treba npr. da me ispiše, uz nesklad subjekata."},
  "2020_jesen_A__75": {"A":"Plava i pečena nisu usporedive vrste; pečena je način pripreme, a plava vrsta ribe.","B":"Plava i sušena nisu istovrsne odrednice; sušena je obrada, a plava vrsta ribe.","C":"Plava i svježa nisu usporedive; svježa se odnosi na stanje, a plava na vrstu ribe."},
  "2020_jesen_A__76": {"A":"Sijevajući ovdje nije traženi točan oblik; ispravnost se traži u svijetleći.","C":"Sijedeći je netočno; pravilno je sjedeći (položaj sjedenja).","D":"Slijedeći (u značenju idući) je netočno; pravilno je sljedeći."},
  "2020_jesen_A__77": {"B":"Domorodački je sinonim, a ne antonim pridjeva starosjedilački.","C":"Liberalni nije antonim pridjeva starosjedilački (nije u značenjskoj suprotnosti).","D":"Užurban nije antonim pridjeva starosjedilački."},
  "2020_jesen_A__79": {"A":"Aligator se ne naglašava dvostrukosilaznim na -a-; naglasna norma ne prihvaća taj lik.","C":"Defile s dugosilaznim na zadnjem slogu nije u skladu s normom (silazni naglasak na zadnjem slogu domaće riječi).","D":"Humanist s kratkosilaznim na zadnjem slogu nije normativan."},
  "2020_jesen_A__80": {"A":"Leksik nije središte Veberove Skladnje; skladnja je sintaksa.","B":"Morfologija nije predmet Skladnje, nego sintaksa.","C":"Pravopis nije područje Veberove Skladnje; ona se bavi sintaksom."},

  // 2020_jesen_B
  "2020_jesen_B__1": {"B":"Glazba (zvuk zvona) tek je simbol, a ne sama tema; pjesma ne slavi ljepotu glazbe nego težnju za nedostižnim.","C":"Smrt se spominje kao pratilac na putu, ali nije tema; ona je dio motiva težnje koja ustraje unatoč njoj.","D":"Noćni je krajolik samo okvir radnje ('Pod noć se javi zvuk'), a ne ono o čemu pjesma progovara."},
  "2020_jesen_B__2": {"A":"Stih opisuje kretanje zvuka prema kraju neba, a ne odnos prema svakodnevici.","B":"Stih govori o trajanju odzvuka uz vjetar, što nije izraz nezadovoljstva svakodnevnim.","D":"Stih prikazuje kako oblaci vide zvuk, bez ikakve ocjene svakodnevice."},
  "2020_jesen_B__3": {"A":"Grad je tek prostor kroz koji zvuk prolazi, a 'ga' se odnosi na ono što teži uvis.","B":"Put je putanja kretanja, a zamjenica označava onoga koji tim putem ide, tj. zvuk.","C":"Vjetar je element kojemu se zvuk predaje, a ne ono na što upućuje 'ga'."},
  "2020_jesen_B__4": {"B":"Iz teksta se ne vidi da je itko od njih poznavao podbana Gregorijanca; o njemu se saznaje iz arhivskih spisa.","C":"Krč je samo znao za parnicu, ali nije joj znao razlog, pa nije obrađivao tekst poput pripovjedača.","D":"U Vijencu je djelo objavio pripovjedač (Šenoa), a o Krč evu izdavaštvu nema spomena."},
  "2020_jesen_B__5": {"A":"Rečenica najavljuje temu (sliku davnine), ali ne govori o istinitosti onoga što se pripovijeda.","B":"Rečenica iznosi skromnost o vlastitu peru i ljubavi prema stvari, a ne tvrdnju o vjerodostojnosti.","D":"Rečenica navodi mjesto objave (Vijenac), što nema veze s istinitošću pripovijedanoga."},
  "2020_jesen_B__6": {"A":"Zaprašena artija doslovno označava stare spise iz arhiva, a ne književno djelo.","B":"'Crno na bijelom' upućuje na zapisano/dokazano, a ne metaforički na knjigu.","C":"Nagrada se ne odnosi na djelo kao takvo, nego na priznanje."},
  "2020_jesen_B__7": {"B":"U tekstu nema iskaza da Alfredo sumnja u uspjeh plana; nestrpljivost slugu nije njegova sumnja.","C":"Sluge upravo nastoje umiriti gospodara, pa se ne govori o njegovu nepovjerenju prema njima.","D":"Pekarsko podrijetlo nije spomenuto; tek se kaže da se u kući Saletti 'kruh nije badava lomio'."},
  "2020_jesen_B__8": {"A":"Izlika za bijeg iz kuće tek je sredstvo, a ne pravi razlog dolaska u Ričicu.","B":"Dolazak nije nagrada za obavljen zadatak; zadaća tek predstoji i tek je teret.","D":"Sluge prikupljaju vijesti o Mariji Šabarićevoj, a ne uhode Antonija."},
  "2020_jesen_B__9": {"A":"Mig se ne odnosi na zbližavanje s djevojkom, nego na znak za zločin nad protivnikom.","B":"Stjecanje bogatstva obilježje je starog Salettija, a ne značenje 'osudnog miga'.","D":"Nagrada nije sadržaj miga; mig označava poticaj na ubojstvo ('porine nož u srce')."},
  "2020_jesen_B__10": {"A":"Otac je posrednik koji pregovara s kapetanom, pa nije onaj koga seljaci nazivaju Antihristom.","C":"Guverner se spominje kao vlasnik broda i vode, ali pogrde su upućene kapetanu, ne njemu.","D":"Profeta sam izriče prokletstva i potiče gomilu, dakle nije onaj koji je tako prozvan."},
  "2020_jesen_B__11": {"B":"Otac se obraća kapetanu, a ne guverneru; za obraćanje guverneru nema potvrde u tekstu.","C":"Vodu ne dijeli otac; on dogovara način njezine raspodjele, ne provodi ga sam.","D":"Šetnja i pušenje nisu pripisani ocu; on aktivno posreduje između strana."},
  "2020_jesen_B__12": {"A":"Izraz potvrđuje kapetanov pristanak na očev plan, a ne ispunjenje seljačke želje na njihov način.","C":"U tekstu nema spomena da bi se dijeljenje vode odgodilo za sutradan.","D":"Voda se ne prevozi u Milnu; potvrđuje se da se izlije u bunar na Glavi."},
  "2020_jesen_B__13": {"A":"Patentna klopka uopće nije spomenuta kao Markova briga.","B":"Marko je već pozvan za barjaktara; pitanje nije hoće li biti pozvan, nego hoće li moći doći.","D":"Marka ne muči ženino ozdravljenje; on čak računa s njezinom smrću u 'pravo' vrijeme."},
  "2020_jesen_B__14": {"A":"Nesudjelovanje u kućanskim poslovima prikazuje ravnodušnost, a ne izvor divljenja.","B":"Kretanje u gospodskome društvu nije navedeno; Marko je lugar i seoski veseljak.","C":"Marko nije prikazan kao brižan suprug; naprotiv, hladan je prema bolesnoj ženi."},
  "2020_jesen_B__15": {"A":"Tvrdnja o najboljem barjaktaru obilježuje njegov ugled/sposobnost, a ne etiku.","B":"'Čovjek od oka' opisuje izgled i okretnost, dakle vanjsku, a ne moralnu osobinu.","C":"Spominjanje lugarskoga ranga socijalna je karakterizacija, ne etička."},
  "2020_jesen_B__16": {"B":"Suprug je majku napustio ranije; udarac o kojem je riječ jest kćerin odlazak k ocu.","C":"Na putovanje s ocem ide pripovjedačica, i to je njoj 'odšteta', a ne majčin udarac.","D":"Satovi jahanja vezani su uz oca i sestru, a ne uz majčin 'strahovit udarac'."},
  "2020_jesen_B__17": {"A":"Termin putovanja i izbjegavanje nastave nisu navedeni kao ono što joj se kod oca svidjelo.","B":"Otac je ne potiče na upis gimnazije; preporuku za gimnaziju daje škola.","D":"Otac se ne predstavlja kao stric; on s njom postupa kao s odraslom osobom."},
  "2020_jesen_B__18": {"A":"Jahač ke hlače dobiva sestra, a 'odšteta' pripovjedačici jest putovanje, ne hlače.","C":"Preporuka za gimnaziju dolazi od škole i nije ono što tekst naziva 'odštetom'.","D":"Trajni život s ocem nije obećan; riječ je o jednokratnom putovanju kao naknadi."},
  "2020_jesen_B__19": {"B":"Razlog nije fizička neprivlačnost; ona ga čak smatra zanimljivim.","C":"Majčina zabrana nije navedena kao razlog izbjegavanja upoznavanja.","D":"Strah od ljubavne patnje nije spomenut; presudan je obzir prema Marini."},
  "2020_jesen_B__20": {"A":"Riječ se ne odnosi na molbu majci da utječe na Marinu.","C":"Posjet Slavenu u Zagreb nije ono što 'će tražiti' u ovom kontekstu.","D":"Izostanak sa sprovoda nije predmet onoga što kani tražiti od majke."},
  "2020_jesen_B__21": {"A":"Igor je drugi lik kojemu se ne pripisuje sviranje gitare.","C":"Slaven je Antonijin rođak, ali nije onaj s 'flasterima od sviranja gitare'.","D":"Zagi je djed doseljen iz Zagorja, a ne onaj koji svira gitaru."},
  "2020_jesen_B__22": {"A":"Želja za društvom plemića pripisuje se markizu/odnosu likova, a ne grofovu iskazu o Mirandolini.","C":"Grof ne tvrdi da Mirandolina traži zaštitnika; o zaštiti govori markiz za sebe.","D":"Grof ne kaže da je prijetvorna; ističe da ju je teško osvojiti unatoč ulaganju."},
  "2020_jesen_B__23": {"A":"Rečenica priznaje Mirandolinine vrline, ali ne izražava markizovo samohvalisanje.","C":"Rečenica hvali njezino držanje, a ne markizovu vlastitu važnost.","D":"Rečenica iskazuje da je markiz cijeni, no bez naglaska na vlastitu mjerodavnost kao u B."},
  "2020_jesen_B__24": {"A":"Vitez ne dijeli savjete o osvajanju žena; on prezire zaljubljivanje.","B":"Tvrdnju da je novac mjerilo iznosi grof, a ne vitez.","C":"Vitez ne uzdiže Mirandolinu kao najljepšu; ravnodušan je prema ženama."},
  "2020_jesen_B__25": {"A":"Tekst ne tvrdi da je Mediteran danas područje najrazvijenijih gradova; samo je Barcelona iznimka.","C":"Ekonomska velesila bio je Mediteran u prošlosti, a ne danas.","D":"Danas je Mediteran 'primatelj', a ne izvoznik znanja; znanje izvozi prošlost."},
  "2020_jesen_B__26": {"B":"Nezdravi kult ne odnosi se na isticanje današnje trgovinske moći, nego na štovanje prošlosti.","C":"Riječ nije o neprihvaćanju vjera, nego o pretjeranu veličanju nekadašnje slave.","D":"Steve Jobs vezan je uz suvremenu tehnologiju, a ne uz 'kult prošlosti'."},
  "2020_jesen_B__27": {"A":"Atena nije navedena kao jedina moderna metropola Mediterana.","C":"Cordoba pripada slavnoj prošlosti, a ne suvremenoj tehnološkoj metropoli.","D":"Firenza je grad baštine i prošlosti, a tekst kao modernu metropolu navodi Barcelonu."},
  "2020_jesen_B__28": {"A":"Provjera ambalaže tek je povod, a ne temeljna misao teksta o jezičnom prilagođavanju.","C":"Televizijske emisije nisu tema; riječ je o prilagodbi posuđenica hrvatskome sustavu.","D":"Tekst ne zagovara slobodu proizvođača u nazivanju, nego poštivanje jezičnih pravila."},
  "2020_jesen_B__29": {"B":"Zadržavanje izvornih riječi upravo je ono što tekst kritizira (npr. 'film festival').","C":"Prevođenje po pravilima izvornoga jezika daje neprirodne sklopove poput 'Narančin nektar'.","D":"Doslovan prijevod 'riječ po riječ' vodi nepravilnom spoju, suprotno prirodnomu hrvatskom izrazu."},
  "2020_jesen_B__30": {"A":"Bosansko-hercegovačko tržište nije navedeno kao primjer pravilna naziva.","B":"Hrvatski naziv 'Narančin nektar' upravo je sporan, dakle nije pravilno napisan.","D":"Srpsko tržište nije istaknuto kao ono s pravilnim nazivom; primjer je slovenski."},
  "2020_jesen_B__31": {"A":"Diskurzivni rod obuhvaća rasprave i eseje, a ne stihovani spjev poput Judite.","B":"Dramski rod podrazumijeva izvedbu i dijaloge, a Judita je pripovjedni spjev.","D":"Lirski rod obilježuju kratke izričajne pjesme, a Judita je opsežan ep, dakle epski rod."},
  "2020_jesen_B__32": {"A":"Invokacija je zaziv muze na početku djela, a ne pročišćenje gledatelja.","C":"Kulminacija je vrhunac radnje, a ne osjećaj pročišćenja strasti.","D":"Prolog je uvodni dio drame, a ne katarzični doživljaj."},
  "2020_jesen_B__33": {"B":"Stih nema dvostruke rime s cezurom na šestom slogu karakteristične za dvostrukorimovani dvanaesterac.","C":"Stih ne ostvaruje unutrašnju rimu na polovici dvanaesterca.","D":"Stih ne pokazuje pravilan raspored dvostruke rime svojstven Marulićevu dvanaestercu."},
  "2020_jesen_B__34": {"A":"Anadiploza je ponavljanje završne riječi na početku idućega stiha, čega ovdje nema.","C":"Onomatopeja oponaša zvukove, a ovdje se jednoličnost postiže ponavljanjem samoglasnika.","D":"Simploka spaja anaforu i epiforu, a u stihovima nije riječ o ponavljanju riječi na rubovima."},
  "2020_jesen_B__35": {"B":"Primjer prikazuje razlijevanje sunčanoga zvuka, što je sinestezija/metafora, a ne pretjerivanje.","C":"Primjer slika zrenje grožđa i smreke, dakle pjesnička slika bez hiperboličnoga uvećanja.","D":"'Cvrči cvrčak na čvoru crne smrče' primjer je aliteracije/onomatopeje, a ne hiperbole."},
  "2020_jesen_B__36": {"B":"Dnevnik bilježi zbivanja iz dana u dan, dok su Ispovijesti retrospektivni životopis.","C":"Feljton je novinski podlistak, što ne odgovara Augustinovu djelu.","D":"Putopis opisuje putovanja, a Ispovijesti su duhovni samoživotopis."},
  "2020_jesen_B__37": {"A":"Ahilej je junak Ilijade, a ne onaj koji u trsci donosi vatru ljudima.","B":"Hefest je bog kovač i čuvar vatre, a ne 'Japetov sin' koji je krade.","C":"Odisej je lukav, ali vatru u trsci donosi Prometej, Japetov sin."},
  "2020_jesen_B__38": {"A":"Satir i Njarnjas-grad pripadaju Držićevoj Tireni/Dundu, a ne Plautovu prologu.","C":"Isticanje znanja i namjere 'podučiti i zabaviti' obilježje je drugih djela, ne Plautova prologa.","D":"Negromant i ljudi nahvao/nazbilj pripadaju Držićevu prologu Dundu Maroju, ne Plautu."},
  "2020_jesen_B__39": {"A":"Aleksandrida je viteški roman o Aleksandru Velikom, a ne dijaloški poučnik o prirodi.","C":"Ljetopis popa Dukljanina povijesno je djelo, a ne pitanje-odgovor poučnoga tipa.","D":"Zapis popa Martinca kratak je glagoljaški zapis o Turcima, a ne enciklopedijski dijalog."},
  "2020_jesen_B__40": {"A":"Božanstvena komedija Danteov je spjev o zagrobnom putovanju, a ne okvir s pripovjedačima u bijegu od kuge.","C":"Don Quijote je viteški roman o vitezu lutalici, bez okvira deset dana pripovijedanja.","D":"Kanconijer je Petrarkina zbirka soneta, a ne zbirka novela s okvirom."},
  "2020_jesen_B__41": {"B":"Opis pjesnika kao junaka alegorijske vizije odnosi se na Dantea, a ne na don Quijotea.","C":"Odgađanje osvete zbog sumnja obilježuje Hamleta, ne don Quijotea.","D":"Div koji prozbori 'Piti, piti, piti!' Rabelaisov je Gargantua, a ne don Quijote."},
  "2020_jesen_B__42": {"A":"Cvjetovi zla Baudelaireova su zbirka 19. stoljeća (predsimbolizam), a ne barok.","B":"Kanconijer je Petrarkino renesansno (predrenesansno) djelo, ne barokno.","D":"Preobraženja su Ovidijev antički ep, dakle ne baroknа zbirka."},
  "2020_jesen_B__43": {"B":"Negiranje gramatičkih i logičkih struktura zbog ratnoga kaosa obilježuje dadaizam/avangardu, ne gongorizam.","C":"Hedonizam i slobodan razvoj pojedinca pripadaju renesansnomu/humanističkom svjetonazoru.","D":"Težnja za nedostižnim i nezadovoljstvo stanjem značajka je romantizma, ne gongorizma."},
  "2020_jesen_B__44": {"A":"Andrija Kačić Miošić pjesnik je (Razgovor ugodni), a ne dramatičar.","B":"Matija Antun Relković piše didaktički spjev Satir, dakle nije dramatičar.","C":"Matija Petar Katančić pjesnik je i jezikoslovac, a ne dramatičar."},
  "2020_jesen_B__45": {"A":"'Umjetnost radi umjetnosti' načelo je esteticizma/parnasizma, a ne romantizma.","B":"Načelo oponašanja (mimeza) klasicistička je i antička poetika, ne romantičarska.","D":"Bovarizam je vezan uz realizam (Flaubertova Bovary), a ne uz romantizam."},
  "2020_jesen_B__46": {"A":"Prizor s Durakom i dželatom pripada pjevanju o haranju/agi, a ne Noćniku.","B":"Stihovi predstavljaju Novicu kao kavaza, što nije scena Noćnika.","C":"Stihovi opisuju Saferove sluge, a ne pripovijedanje uz gusle u Noćniku."},
  "2020_jesen_B__47": {"A":"Božanstvena komedija Danteovo je srednjovjekovno djelo, a ne dio Balzacova ciklusa.","B":"Combray je dio Proustova U traganju za izgubljenim vremenom, ne Ljudske komedije.","D":"Zločin i kazna Dostojevskijev je roman, a ne Balzacov."},
  "2020_jesen_B__48": {"A":"Matoš pripada hrvatskoj moderni, a ne razdoblju realizma.","B":"Petar Preradović pjesnik je romantizma/ilirizma, ne realizma.","D":"Stanko Vraz djeluje u ilirizmu, dakle prije realizma."},
  "2020_jesen_B__49": {"B":"Smrt pod kočijom sudbina je Ane Karenjine/drugih likova, a ne Laure iz U registraturi.","C":"Bacanje pod vlak završetak je Ane Karenjine, a ne Laurin kraj.","D":"Strijeljanje nije način Laurine smrti; ubio ju je ljubavnik pregrizavši joj grkljan."},
  "2020_jesen_B__51": {"A":"Izražavanje duhovne zbilje bojama obilježuje ekspresionizam, a ne nadrealizam.","B":"Slavljenje tehnologije, brzine i slobode tijela značajka je futurizma, ne nadrealizma.","D":"Shvaćanje književnosti kao sredstva za političke stavove blisko je angažiranoj/socrealističkoj poetici, ne nadrealizmu."},
  "2020_jesen_B__56": {"A":"U primjeru je glagolski oblik nepravilan ('srnda ao' nije ispravan zapis), pa rečenica nije pravopisno točna.","B":"Primjer sadrži pravopisnu pogrešku u podcrtanoj riječi, pa nije traženi točan odgovor.","C":"'Osiguračfunkciju' pokazuje nepravilan/spojen zapis, dakle rečenica nije pravopisno točna."},
  "2020_jesen_B__57": {"A":"'Zasijedati' je pravopisno pogrešno; pravilno je 'zasjedati'.","C":"'Namjestati' je pogrešno; pravilan je oblik 'namještati'.","D":"'Zamjerati' je u ovom nizu označeno kao pogrešno prema ključu; traženi je točan oblik 'pripovijedati'."},
  "2020_jesen_B__58": {"B":"'Plitvička Jezera' treba pisati 'Plitvička jezera' (drugi član malim slovom) i 'nacionalni park' malim.","C":"'Olimpijskim Igrama' treba pisati 'Olimpijskim igrama' (drugi član malim slovom).","D":"'Matice Hrvatske' treba pisati 'Matice hrvatske' (pridjev malim slovom)."},
  "2020_jesen_B__59": {"A":"'Nadprirodnim' je pogrešno; po jednačenju treba 'natprirodnim'.","B":"'Bezkofeinske' je pogrešno; pravilno je 'bezkofeinske' → 'beskofeinske'.","C":"'Stambenu' jest pravilno, ali traženi točan podcrtani primjer prema ključu jest 'retka' (D)."},
  "2020_jesen_B__60": {"A":"'Gost — gozba' primjer je jednačenja po zvučnosti (st→zb), a ne palatalizacije.","B":"'List — lišće' rezultat je jotacije, ne palatalizacije.","C":"'Misao — mišlju' rezultat je jotacije (sl→šlj), a ne palatalizacije."},
  "2020_jesen_B__61": {"A":"Prvi slog 'u-' nije naglašen; naglasak je na drugome slogu.","C":"Slog '-te-' nije naglašen.","D":"Slog '-lji-' nije naglašen; naglasak nosi '-či-'."},
  "2020_jesen_B__62": {"A":"'Koš-' je samo dio korijena; pun korijenski morfem ovdje je 'košar-'.","C":"'Košarka-' uključuje i tvorbene nastavke, pa nije korijenski morfem.","D":"'Košarkač' je cijela riječ, a ne korijenski morfem."},
  "2020_jesen_B__63": {"B":"'Kiši' je uz prijedlog 'unatoč' u dativu po službi, ali traženi je odgovor prema ključu 'plovidbi'.","C":"'Oblaka' je u genitivu (iz oblaka), a ne u dativu.","D":"'Rijekom' je u instrumentalu (razlila se rijekom), a ne u dativu."},
  "2020_jesen_B__64": {"A":"'Ljestvama' je pluralia tantum, dakle množinski oblik, ne jednina.","B":"'Cipele' su u množini, a ne u jednini.","D":"'Leđa' su pluralia tantum (samo množina), pa nisu jednina."},
  "2020_jesen_B__65": {"A":"'Kako' je u toj rečenici prilog/veznik, a ne neodređena zamjenica.","B":"'Svojim' je posvojna (povratno-posvojna) zamjenica, ne neodređena.","C":"'Onu' je pokazna zamjenica, a ne neodređena."},
  "2020_jesen_B__66": {"A":"'Bi razmišljao' je kondicional prvi, a ne perfekt.","B":"'Je bio doživio' je pluskvamperfekt, a ne perfekt.","D":"'Bijaše živio' je oblik s imperfektom pomoćnoga glagola, dakle nije obični perfekt."},
  "2020_jesen_B__67": {"A":"Pet je premalo; u rečenici je šest prijedloga (za, u, pod, uz, iz, na).","C":"Sedam je previše; prijedloga je točno šest.","D":"Osam je previše; prijedloga je točno šest."},
  "2020_jesen_B__68": {"A":"'Moja susjeda' veza je sročnosti (slaganja), a ne upravljanja.","B":"'Žutome kaputiću' također je sročnost pridjeva i imenice, ne upravljanje.","C":"'Strpljivo je čekala' veza je pridruživanja (prilog uz glagol), a ne upravljanja."},
  "2020_jesen_B__69": {"A":"'Sir' je u akuzativu uz prijedlog 'uz', dakle dio priložne oznake, a ne subjekt.","B":"'Sir' je tu imenski dio predikata/predmet o kojem se sudi, a ne vršilac radnje (subjekt je zaslužnost).","D":"'Sir' je objekt (poslužili su sir), a ne subjekt."},
  "2020_jesen_B__70": {"A":"'Cijeli svoj život' ne dopunjuje glagol kao objekt, nego označuje trajanje radnje.","B":"Predikat je 'sanjao je', a ne podcrtana sintagma.","D":"Subjekt je neizrečeni vršilac radnje (on), a ne 'cijeli svoj život'."},
  "2020_jesen_B__71": {"A":"Atributna rečenica pobliže označuje imenicu, a ovdje zavisna surečenica dopunjuje glagol 'pitati se'.","B":"Predikatna rečenica vrši službu imenskoga dijela predikata, što ovdje nije slučaj.","C":"Subjektna rečenica zamjenjuje subjekt, a ova zamjenjuje objekt glagola 'pitali smo se'."},
  "2020_jesen_B__72": {"A":"Rečenica izriče posljedicu ('toliko... da'), dakle posljedična je, ne pogodbena.","B":"Rečenica izriče namjeru ('kako bi'), dakle namjerna je, ne pogodbena.","C":"Rečenica izriče uzrok ('budući da'), dakle uzročna je, ne pogodbena."},
  "2020_jesen_B__73": {"B":"'Bez da' nestandardna je konstrukcija; pravilno bi bilo 'a da nisu pogledali'.","C":"'Događaj kojega' pogrešno je za neživo; treba 'koji' u akuzativu.","D":"'Odmarali' bez povratne zamjenice nestandardno je; pravilno 'odmarali se'."},
  "2020_jesen_B__74": {"B":"Tragedija je usporedna vrsta komediji unutar drame, a ne nadređeni pojam.","C":"Farsa je podvrsta komike, dakle nije hiperonim komedije.","D":"Roman pripada epici, a ne nadređenomu pojmu komedije."},
  "2020_jesen_B__75": {"B":"'Bliskost — blizina' bliskoznačnice su (sinonimi), a ne antonimi.","C":"'Cvijet — tulipan' u odnosu su hiperonim–hiponim, a ne suprotnosti.","D":"'Laž — neistina' istoznačnice su, dakle sinonimi, a ne antonimi."},
  "2020_jesen_B__77": {"A":"'Uzajamna podrška' nije pleonazam jer podrška može biti i jednostrana.","B":"'Uzajamna pomoć' nije pleonazam jer pomoć može biti jednosmjerna.","C":"'Uzajamna simpatija' nije pleonazam jer simpatija ne mora biti obostrana."},
  "2020_jesen_B__80": {"A":"Bartol Kašić autor je prve hrvatske gramatike (17. st.), a ne tvorac jedinstvena ilirskog pravopisa s prijelazom na štokavštinu.","B":"Bogoslav Šulek poznat je po jezikoslovnom i nazivoslovnom radu, a ne po opisanu pravopisnom ujedinjenju.","C":"Faust Vrančić autor je petojezičnog rječnika (16./17. st.), a ne reformator pravopisa s kajkavskoga na štokavski."},

  // 2020_ljeto_A
  "2020_ljeto_A__1": {"A":"Stih govori samo o trenutku susreta i procvalu žene, bez suprotstavljanja starosti i mladosti.","C":"Spominju se sunca i zvijezde kao slika obnove njezinih dana i noći, a ne sukob starosti i mladosti.","D":"Govori o plodu cijeloga života i predaji lirskoga subjekta, bez slike mladosti uz starost."},
  "2020_ljeto_A__2": {"A":"Nebo je tek mjesto na kojem se zbiva slika ('na mom nebu'), a ne ono što silazi i pušta slavuje.","B":"Oluja je samo dio opisa neba, a radnja silaženja i puštanja pripada ženi.","D":"Slavuji su ono što se pušta iz ruku, a ne onaj tko silazi među grane."},
  "2020_ljeto_A__3": {"B":"Stih opisuje nemirno nebo lirskoga subjekta, a ne njegovu dob.","C":"Stih prikazuje ženin dolazak i zaustavljanje, bez podatka o dobi lirskoga subjekta.","D":"Stih ističe kobnost i tajnovitost lirskoga subjekta, a ne njegovu starost."},
  "2020_ljeto_A__4": {"A":"U tekstu nema spomena da je Metab nekoga postavio na vlast umjesto Kazmile.","B":"Metab nije napustio Volščane; naprotiv, on je sa sobom u progonstvo poveo kćer.","D":"Metab nikomu nije oteo Kamilu; Kamila je njegova kći koju je sam zaštitio."},
  "2020_ljeto_A__5": {"B":"U tekstu nema košare niti puštanja niz rijeku; Metab koristi koplje.","C":"Metab nije prenio Kamilu na rukama jer ga je 'odbila vodena sila'.","D":"Spas se događa prebacivanjem preko rijeke, a ne penjanjem na brijeg."},
  "2020_ljeto_A__6": {"A":"Kamila je predmet razgovora ('eno Kamila'), a ne ona koja se obraća Dijani.","B":"Latona se spominje samo kao Dijanina majka ('Latonina kćerka'), ona ne govori.","C":"Metab se spominje u prošlosti kao Kamilin otac, ne sudjeluje u ovome razgovoru."},
  "2020_ljeto_A__7": {"A":"U tekstu nema podatka da je Lars ogovarao pripovjedača pred Norvežankama.","C":"Nigdje se ne navodi da je Lars odbio posuditi novac pripovjedaču.","D":"Lars je putovao autostopom i brodom; vlakom su išli zajedno do Brindisija, a ne sam do Beča."},
  "2020_ljeto_A__8": {"A":"Autostopiranje do Firence opisuje način putovanja, ne nedostatak novca.","B":"Ležanje na plaži opisuje odmor, a ne pripovjedačevo siromaštvo.","C":"Odluka o izbjegavanju Larsa odnosi se na njihov odnos, a ne na novac."},
  "2020_ljeto_A__9": {"A":"Firenca se spominje kao prva postaja, bez naglaska na metežu.","C":"Rodos se spominje samo po vrućini od 49 stupnjeva, a ne po metežu.","D":"Paros je mjesto odmora na plaži, a najveći je metež izrijekom vezan uz Atenu."},
  "2020_ljeto_A__10": {"A":"Tekst ne ublažava neugodne sadržaje, pa nije utemeljen na eufemizmu.","B":"Nema namjernoga pretjerivanja kao temeljnoga postupka, pa nije hiperbola.","D":"Nema spoja proturječnih pojmova u jednoj sintagmi, pa nije oksimoron."},
  "2020_ljeto_A__11": {"A":"Riječ 'bratski' označava bliskost i slogu, a ne prijetnju.","C":"Smiju se zajedno 'bratski', što ne upućuje na rugu bogatoga dječaka.","D":"Zdravi zubi nisu poruka; naglasak je na jednakosti i zbližavanju kroz igru."},
  "2020_ljeto_A__12": {"A":"Riječ je o iskrenoj kritičkoj misli o socijalnim razlikama, bez ironije.","B":"Usporedba igračke i lica vlasnika opisna je, bez ironijskoga obrata.","C":"Rečenica suosjećajno ističe ljepotu siromašnoga djeteta, bez ironije."},
  "2020_ljeto_A__13": {"B":"O izgubljenim stvarima pripovjedač razmišlja kasnije, a ne u razgovoru sa zubarom.","C":"Zajednička patnja nije tema razgovora; zubar je mrzovoljan i odbojan.","D":"O strahu se ne razgovara; razgovor je o poslu i zidarima u Francuskoj."},
  "2020_ljeto_A__14": {"B":"Pripovjedač mašta o prihvaćanju među novim ljudima, a ne o susretu sa sunarodnjacima.","C":"Želja da bude veći i jači zubareva je primjedba, a ne pripovjedačeva težnja.","D":"Ne radi se o širenju glasina, nego o čežnji da bude cijenjen i prihvaćen."},
  "2020_ljeto_A__15": {"A":"Spoznaja o tuđim sličnim iskustvima nije razlog; naglasak je na osobnome gubitku.","B":"Prestanak pješačenja nije razlog koji pripovjedač navodi.","C":"Dolazak u Francusku nije ono što obilježava pravi početak putovanja."},
  "2020_ljeto_A__16": {"B":"Odluka o stanovanju u hotelu navodi se kao činjenica, a ne kao pitanje koje si postavlja.","C":"Pitanje o ustrijeljivanju čovjeka ne pojavljuje se u ulomku.","D":"O otkazu se ne postavlja pitanje; pitanje je zašto je tako dugo šutio."},
  "2020_ljeto_A__17": {"A":"To je doslovan Wernerov napad na pripovjedača, bez ironijskoga obrata.","B":"Rečenica je iskreno pitanje o (ne)opravdanosti optužbe, bez ironije.","D":"Rečenica je trezvena konstatacija o posljedicama prešućivanja, bez ironije."},
  "2020_ljeto_A__18": {"A":"Supruga (Agneza) spominje se ranije, ali se podcrtani pridjev ne odnosi na nju.","B":"Krivnja je uzrok rastave, a ne riječ na koju se pridjev 'nedostojne' odnosi.","C":"Pažnja je predmet neraspoloženja, no 'nedostojne' se gramatički veže uz ličnost."},
  "2020_ljeto_A__19": {"A":"'Sveti znak' odnosi se na znak vrline, a ne na Tezejevu zabrinutost.","B":"'Žig za ljude' nije izraz zabrinutosti, nego optužbe/obilježja.","D":"'Vječna sjena' ne izražava trenutačnu zabrinutost vidljivu na licu."},
  "2020_ljeto_A__20": {"A":"Tezej ne smatra da smrt nije dovoljna kazna; problem je u kaljanju vlastite slave.","C":"Tezej se ne boji bogova; on ih, naprotiv, zaziva na osvetu.","D":"Nije riječ o sažaljenju prema sinu, nego o brizi za vlastitu čast."},
  "2020_ljeto_A__21": {"A":"Tezej nije izbavio Neptuna iz tamnice; on sam je bio u tamnici.","B":"Hvaljenje Neptuna nije navedeno kao razlog naklonosti.","D":"Protjerivanje Hipolita događa se sada i nije razlog ranije stečene naklonosti."},
  "2020_ljeto_A__22": {"A":"Traženje inspiracije za dramu pripisuje se Sandru, a ne Malenskomu.","B":"Ilin telefonski razgovor čuje (vidi) Sandro, a o Malenskome to nije rečeno.","C":"O zaljubljenosti Malenskoga u Astu u ulomku se ne govori; on je glumac u modi."},
  "2020_ljeto_A__23": {"B":"Isprekidani je govor Ilin znak nelagode, a ne dokaz da Sandro vidi vezu kao tajnu.","C":"Retorička pitanja pokazuju Sandrovu sumnju općenito, a ne tajnovitost veze.","D":"Šaljiv ton prikriva Sandrovu ozbiljnost, ali tajnost veze izriče glagol 'uloviti'."},
  "2020_ljeto_A__24": {"A":"Rečenica ne govori o laganju o telefonskome razgovoru, nego o Ilinu opravdavanju nevjere.","B":"Krađa iz garderobe nije tema; riječ je o moralnome opravdavanju 'zločina'.","C":"O ubojstvu muža govori se samo kao Sandrova šala, ne kao Ilin čin."},
  "2020_ljeto_A__25": {"A":"Prema centrima autor ne osjeća gađenje, nego žudnju i ugodu.","C":"Osamljenost autor veže uz gradski život, a ne uz trgovačke centre.","D":"Strepnju autor osjeća u gradu, dok se u centrima osjeća posve dobrodošlim."},
  "2020_ljeto_A__26": {"A":"Autor se ne čudi većoj izloženosti Njujorčana reklamama, nego manjoj vezanosti uz konzumerizam.","C":"O većoj kupovnoj moći Njujorčana autor ne govori.","D":"Pitanje privatnosti nije ono čemu se autor čudi."},
  "2020_ljeto_A__27": {"B":"O stvaranju osjećaja zajedništva među stanovnicima New Yorka tekst ne govori.","C":"Tekst ne tvrdi da New York potiče ljude na preseljenje u predgrađa.","D":"U gradu se autor ne opušta, nego osjeća strepnju; opuštenost veže uz centre."},
  "2020_ljeto_A__28": {"A":"Predstavljanje priznanja samo je dio sadržaja, a ne glavna namjena teksta.","B":"Tekst ne jamči sigurno kretanje, nego objašnjava svrhu obilaznica.","D":"Tekst spominje vrste obilaznica, ali im to nije temeljna namjena (objasniti ulogu)."},
  "2020_ljeto_A__29": {"B":"Žigovi služe posjetitelju da dokaže obilazak, a ne društvu za prebrojavanje.","C":"Prijelaz na sljedeću obilaznicu nije svrha žigova na kontrolnim točkama.","D":"Žigovi ne označavaju najlakši put, nego potvrđuju dolazak do točke."},
  "2020_ljeto_A__30": {"B":"Razlog nije ponovni obilazak istih mjesta, nego odbojnost prema 'jurenju za žigovima'.","C":"Najlakši putovi nisu navedeni kao razlog nezadovoljstva obilaznicama.","D":"Planinari ne odbijaju obilaznice zbog nedostatka razloga za planinarenje općenito."},
  "2020_ljeto_A__31": {"B":"Žaljenje za prošlim obilježje je elegije, a ne ode.","C":"Neočekivani obrat svojstven je epigramu ili noveli, a ne odi.","D":"Uzdizanje prirode i užitaka obilježje je idile/anakreontike, ne ode."},
  "2020_ljeto_A__32": {"A":"'Božanska pjesma' nije izvorno značenje pojma tragedija.","C":"'Posmrtna pjesma' odgovaralo bi pojmu nadgrobnice, ne tragedije.","D":"'Žalosna pjesma' opisuje ugođaj, ali nije etimološko značenje (jarčeva pjesma)."},
  "2020_ljeto_A__33": {"B":"Stihovi grade sklad i ugođaj prirode, bez razigrane jezične igre zvukom.","C":"Stihovi opisuju mračan prizor vješala, bez jezičnoga ludizma.","D":"Stihovi prikazuju zatvorenički prostor, bez igre glasovima i riječima."},
  "2020_ljeto_A__34": {"B":"'Prokleta avlija' sadrži pridjev i imenicu, bez suprotstavljanja pojmova.","C":"'Zločin i kazna' povezuje uzrok i posljedicu, a ne suprotnosti.","D":"'Crni mačak' opisni je naslov bez antitetičkoga para."},
  "2020_ljeto_A__35": {"A":"Nema izravnoga obraćanja odsutnomu ili neživomu, pa nije apostrofa.","B":"Nema izostavljanja dijela rečenice radi sažetosti, pa nije elipsa.","C":"Premda ima neobičan red riječi, naglasak je na prenesenome značenju, pa je metafora, a ne inverzija."},
  "2020_ljeto_A__36": {"A":"Alkej je grčki liričar s Lezba, a ne rimski pjesnik.","B":"Anakreont je grčki pjesnik, pripadnik grčke antike.","D":"Pindar je grčki pjesnik (oda), a ne rimski."},
  "2020_ljeto_A__37": {"A":"Riječ je o naredbi vladara (Kreonta) da se Antigona zatvori, a ne o njezinim riječima.","B":"Te stihove o nemoći pred jačima izgovara Izmena, a ne Antigona.","C":"Pomirljive riječi o bogovima podzemlja izgovara drugi lik, ne Antigona koja prkosi."},
  "2020_ljeto_A__38": {"A":"Svit se konča nije božićna pjesma niti parafraza In hoc anni circulo.","B":"Pjesma ne hvali Gospu u stilu talijanskih lauda flagelanata.","D":"Pjesma ne prepričava Lukino izvješće o Isusovu rođenju."},
  "2020_ljeto_A__39": {"A":"Dante je putnik kroz pakao, a ne onaj tko duši dodjeljuje mjesto.","B":"Haron prevozi duše preko rijeke, ali im ne sudi i ne određuje kaznu.","D":"Vergilije je Danteov vodič, a ne sudac koji raspoređuje duše po paklu."},
  "2020_ljeto_A__40": {"B":"Maro je sin koji je potrošio novac, ne onaj tko plače ('mu je sin').","C":"Pomet je sluga, a ne otac koji plače za potrošenim novcem.","D":"Ugo Tudešak nije osoba koja plače u ovoj replici."},
  "2020_ljeto_A__41": {"A":"Beatrice je idealizirana žena u Danteovu djelu, ne don Quijoteova odabranica.","C":"Laura je Petrarcina ljubav, ne don Quijoteova dama.","D":"Penelopa je Odisejeva žena, nije vezana uz don Quijotea."},
  "2020_ljeto_A__42": {"A":"Hanibal Lucić poznat je po Robinji i lirici, ne po epu s navedenim uvodom.","B":"Ivan Gundulić autor je Osmana, čiji se uvod ne poziva na 'začinjavce'.","C":"Marin Držić komediograf je, nije autor epa s navedenim programatskim uvodom."},
  "2020_ljeto_A__43": {"B":"Opis renesansnoga zbornika s 800 pjesama odnosi se na Ranjinin zbornik, ne na Plandovanja.","C":"Barokni prepjevi pokajničkih psalama opis su Gundulićevih Pjesni pokornih, ne Plandovanja.","D":"Prikaz prošlosti Južnih Slavena u duhu prosvjetiteljstva odnosi se na Kačića, ne na Bunića."},
  "2020_ljeto_A__44": {"A":"Barokna melodrama spaja glazbu i dramu, ne odgovara navedenim klasicističkim pravilima.","C":"Prosvjetiteljska komedija prikazuje obične likove i ne traži uzvišeni stil.","D":"Romantičarska drama odbacuje pravilo triju jedinstava i strogu doličnost klasicizma."},
  "2020_ljeto_A__45": {"A":"Candide je junak Voltaireova djela, ne pripovjedač u Wahlheimu s Homerom.","B":"Pečorin je junak Junaka našega doba, nije vezan uz Wahlheim.","C":"Raskoljnikov je lik iz Zločina i kazne, ne pripovjedač navedenoga ulomka."},
  "2020_ljeto_A__46": {"A":"Riječ nije o boljoj sobi u pansionu, nego o društvenome usponu.","C":"Napredovanje na poslu nije tema; govori se o ulasku u visoko društvo.","D":"Rastignac je već u Parizu; tema je probijanje u otmjene krugove, ne preseljenje."},
  "2020_ljeto_A__47": {"A":"Povezivanje ljubavi prema ženi i domovini nije tema Cvjetova zla.","B":"Zbirka nije posvećena platonskoj ljubavi prema idealnoj ženi.","D":"Pastoralni ugođaj nije obilježje Baudelaireove urbane i dekadentne lirike."},
  "2020_ljeto_A__48": {"B":"U pjesmi se ne kritizira bezbožništvo, nego ulizištvo i beskičmenjaštvo.","C":"Nadripjesništvo nije meta ove pjesme.","D":"Odnarođivanje nije predmet kritike u Gospodskomu Kastoru."},
  "2020_ljeto_A__49": {"A":"Cvijet sa raskršća Matošev je tekst, ne odgovara opisu lika Boje.","B":"Koraljna vrata Pavličićev su roman o Osmanu, ne o liku Boji.","D":"Tena Josipa Kozarca prikazuje drukčiju junakinju, ne 'meku' Boju vezanu uz kamen."},
  "2020_ljeto_A__50": {"A":"Lamartine je romantičar (elegična lirika), ne nadrealist.","B":"Rimbaud pripada simbolizmu/dekadenciji, nije nadrealist.","C":"Poe je romantičar i preteča simbolizma, ne nadrealist."},
  "2020_ljeto_A__51": {"A":"Dramsko trojedinstvo obilježje je klasicističke, a ne epske drame.","B":"Deus ex machina postupak je antičke i klasicistične drame, ne epskoga kazališta.","D":"Quid pro quo komediografski je zaplet zamjene, a ne obilježje epskoga kazališta."},
  "2020_ljeto_A__52": {"A":"Kolo je časopis ilirskoga/preporodnoga razdoblja, ne nosi tu krilaticu.","C":"Razlog je časopis kasnijega naraštaja, bez krilatice 'Neka bude živost'.","D":"Vijenac je časopis 19. stoljeća, nije vezan uz tu krilaticu."},
  "2020_ljeto_A__53": {"B":"Rečenica o dolasku u francuski gradić nije početak Kratkoga izleta.","C":"Rečenica o učitelju Đuri Martiću pripada drugomu djelu, ne Šoljanovu romanu.","D":"Uzvik 'MAAR... MAAR...' nije početna rečenica Kratkoga izleta."},
  "2020_ljeto_A__54": {"A":"Pjesni pokorne kralja Davida nisu predložak Koraljnim vratima.","B":"Suze sina razmetnoga nisu djelo oko kojega se plete radnja Koraljnih vrata.","C":"Dubravka nije Gundulićevo djelo koje je potaknulo Pavličićev roman."},
  "2020_ljeto_A__55": {"A":"Stihovi 'Bože mili, kud sam zašo' pripadaju drugomu autoru, ne Mažuraniću.","B":"Misaoni stihovi o ljudskome srcu nisu Mažuranićevi.","D":"Stihovi 'Zora puca, bit će dana' iz su drugoga djela (Vraz/budnica), ne Mažuranićevi."},
  "2020_ljeto_A__56": {"B":"'Razumjevanje' je pogrešno; pravilno je 'razumijevanje' (dugi refleks jata).","C":"'Podrazumjevalo' je pogrešno; pravilno je 'podrazumijevalo'.","D":"'Razumjevati' je pogrešno; pravilno je 'razumijevati'."},
  "2020_ljeto_A__57": {"A":"'Eko savjetnik' rastavljeno je pogrešno; prefiksoid eko- piše se s crticom.","B":"'Eko – savjetnik' s razmaknutom crtom pravopisno je netočno.","D":"'Ekosavjetnik' sastavljeno nije u skladu s pravilom o pisanju prefiksoida eko-."},
  "2020_ljeto_A__58": {"A":"'Zemljin satelit' treba veliko slovo (Zemljin) jer je riječ o nebeskome tijelu.","B":"'Sovjetski savez' pogrešno je; pravilno je Sovjetski Savez (oba velika).","D":"'Tihi Ocean' pogrešno je; pravilno je Tihi ocean (ocean malim slovom)."},
  "2020_ljeto_A__59": {"A":"'Podhodnikom' je pogrešno; provodi se jednačenje pa je pravilno 'pothodnikom'.","B":"'Smeđkaste' je pogrešno; pravilno je 'smećkaste' (jednačenje đ→ć ispred k).","C":"'Ispod prvoga retka' pravopisno je u redu, ali nije podcrtana sporna riječ s pogreškom — ovdje je tražena točna riječ 'nadaleko'."},
  "2020_ljeto_A__60": {"A":"U 'Podbrežje' nije provedeno jednačenje po mjestu tvorbe, nego jotacija.","B":"Nepostojani a ovdje se ne pojavljuje.","C":"Palatalizacija je promjena k, g, h ispred e/i, a ovdje je riječ o spoju g+j (jotacija)."},
  "2020_ljeto_A__61": {"B":"'Gitàrist' nije u skladu s normom; pravilno je 'gitàrīst' (drukčija naglasna slika).","C":"'Magnêzij' naglasno odstupa od norme za tu posuđenicu.","D":"'Rokokô' nije normativno naglašen prema standardu."},
  "2020_ljeto_A__62": {"A":"'Braću' je zbirna imenica ženskoga roda, a ne srednjega.","B":"'Madež' je imenica muškoga roda.","D":"'Uši' su imenica ženskoga roda (množina od uho/uha u ž. r.)."},
  "2020_ljeto_A__63": {"A":"'Sela' je u nominativu množine (subjekt), a ne u genitivu.","B":"'Ju' je zamjenica u akuzativu, a ne u genitivu.","C":"'Anđela' je ovdje u akuzativu (skinuli koga?), a ne u genitivu."},
  "2020_ljeto_A__64": {"A":"'Idući' uz 'prije će stići' tvori nejasan odnos radnji; rečenica je neprihvatljiva u toj uporabi priloga.","C":"'Hrabrući' nije pravilan glagolski prilog; od hrabriti glasi 'hrabreći'.","D":"'Zviždući' nije pravilno; pravilan glagolski prilog glasi 'zviždeći'."},
  "2020_ljeto_A__65": {"B":"'Bilo je ušuškalo' je pluskvamperfekt, a ne imperfekt.","C":"'Ušuškaše' je aorist, a ne imperfekt.","D":"'Bili su ušuškali' je pluskvamperfekt, a ne imperfekt."},
  "2020_ljeto_A__66": {"A":"'Utjecao je da se potpiše' nije pravilno; utjecati se veže s 'na' (utjecati na to da...).","C":"'Smetao svakoga' nije pravilno; smetati se veže s dativom (smetati svakomu).","D":"'Čim bi se ustao' nije pravilno; glagol ustati ne traži se (ustao bi)."},
  "2020_ljeto_A__67": {"B":"Predikat je 'organizira se', a ne genitivni izraz 'svake godine'.","C":"Subjekt je 'sajam Interliber', a ne 'svake godine'.","D":"Objekta u rečenici nema; 'svake godine' priložna je oznaka vremena."},
  "2020_ljeto_A__68": {"A":"'Nekad su izgledale' veza je priložne oznake i predikata, nije atributna sintagma.","B":"'Izgledale drukčije' veza je predikata i priložne oznake načina, nije atributna.","D":"'Su sličili kolima' predikatno-objektna je veza, nije atributna sintagma."},
  "2020_ljeto_A__69": {"A":"'Se zvao čaturanga' predikatno je jezgro s imenskim dijelom, nije objekt.","B":"'Pjesničko ime' imenski je predikat (to je ime), a ne objekt.","C":"'Za indijsku vojsku' prijedložni je izraz u službi atributa/odredbe, ne objekt."},
  "2020_ljeto_A__70": {"A":"Šest je premalo; rečenica ima sedam surečenica.","C":"Osam je previše; surečenica je točno sedam.","D":"Devet je previše; surečenica je sedam."},
  "2020_ljeto_A__71": {"B":"'Reče da želi' izrična je (objektna) rečenica, a ne posljedična.","C":"'Naredi da se počne' izrična je rečenica, a ne posljedična.","D":"'Izračunali da ne postoji' izrična je rečenica, a ne posljedična."},
  "2020_ljeto_A__72": {"A":"Rečenica sadrži glagol 'imamo', pa je oglagoljena.","B":"Rečenica sadrži glagol 'je' (jest), pa je oglagoljena.","D":"Rečenica sadrži glagol 'kišilo je', pa je oglagoljena."},
  "2020_ljeto_A__73": {"A":"'Ludim' je suprotno značenje; lucidan upravo znači bistar, jasna uma.","C":"'Rijetkim' ne odgovara značenju riječi lucidan.","D":"'Važnim' opisuje spoznaje, a ne značenje pridjeva lucidan."},
  "2020_ljeto_A__74": {"A":"'Razgovorljiv' znači sklon razgovoru, a ne nužno rječit i vješt govornik.","C":"'Poliglot' je onaj tko zna više jezika, što ne opisuje vještinu izražavanja.","D":"'Lingvist' je jezikoslovac, struka, a ne osobina dobra govornika."},
  "2020_ljeto_A__75": {"A":"'Kilogram' nije nazvan po osobi, pa nije eponim.","B":"'Sekunda' nije izvedena iz osobnoga imena, pa nije eponim.","D":"'Čvor' nije nazvan po osobi, pa nije eponim."},
  "2020_ljeto_A__76": {"B":"'Računalna simulacija' logičan je spoj, bez proturječja, pa nije oksimoron.","C":"'Drugo okružje' obična je sintagma, bez suprotstavljenih pojmova.","D":"'Neuronska mreža' stručan je naziv, bez proturječnih pojmova."},
  "2020_ljeto_A__77": {"A":"'Prašumskom' je izvedeno sufiksom -ski, no zadatak traži primjer iz ponuđenih; ovdje je riječ o pridjevu izvedenom drukčije nego tražena tvorba.","C":"'Nepoznatih' je nastalo prefiksom ne-, dakle prefiksalnom tvorbom.","D":"'Izvanzemaljskih' je složeno-sufiksalna tvorba (izvan+zemlja+ski), a ne čista sufiksalna."},
  "2020_ljeto_A__78": {"A":"'Točka s koje nema povratka' opisuje sintagmu Rubikon, a ne Ahilovu petu.","B":"'Mjesto u koje se vratio' ne odgovara značenju frazema Ahilova peta.","C":"'Hrabar čin' suprotno je značenje; Ahilova peta označava slabost, a ne hrabrost."},
  "2020_ljeto_A__79": {"A":"'Opetovano je izvadio taj zub' besmisleno je jer se isti zub vadi samo jednom.","B":"'Kontinuirano je zapjevao' proturječno je jer zapjevati označava jednokratan početak radnje.","D":"'Transparentno se sakrio' proturječno je jer prozirno sakrivanje nije skrivanje."},
  "2020_ljeto_A__80": {"B":"Šulek je djelovao u 19. stoljeću, a ne u 16., pa je tvrdnja netočna.","C":"Bašćanska ploča nije darovnica kralja Tomislava, nego spominje kralja Zvonimira.","D":"Prvu hrvatsku gramatiku napisao je Bartol Kašić, a ne Faust Vrančić."},

  // 2020_ljeto_B
  "2020_ljeto_B__1": {"A":"'Stare žene' su u prvoj strofi usporedba (masline stare 'poput' starih žena), a ne metafora.","B":"'Biblijska vremena' označuju davnu starost maslina, a ne metaforu za same masline.","D":"'Drevne knjige' u zadnjoj su strofi dio usporedbe (život se toči 'ko iz drevne knjige'), a ne metafora za masline."},
  "2020_ljeto_B__2": {"A":"U prvoj strofi masline se opisuju izvana (usporedba sa starim ženama), bez osobnog, bliskog oslovljavanja.","B":"Druga strofa govori o patnji i postojanosti maslina, ali bez izravne bliskosti lirskog subjekta.","D":"Četvrta strofa donosi sliku 'skamenjenih ljudi' i protok života, ali ne i osobnu bliskost kao u apostrofi 'sestre moje'."},
  "2020_ljeto_B__3": {"A":"Masline su simbol prolaznosti i tegoba, a ne doslovan prikaz ljudi primorskoga kraja.","B":"Premda se spominje 'mir pobožni', težište nije na traženju utjehe u vjeri nego na starenju i patnji.","D":"Pjesma ne slavi ljepotu krajolika nego naglašava opterećenost, žalost i smrtnost ('pune ste smrti')."},
  "2020_ljeto_B__4": {"A":"Oživljavanje ljubavi 'na prvi pogled' izražava naklonost, ali nije preuveličavanje pa nije hiperbola.","B":"Tvrdnja o humoristima koji se zaljube u šah općenita je konstatacija, bez nemoguće mjere.","C":"Pisanje 'podebele knjige o šahu' realna je činjenica, a ne preuveličavanje."},
  "2020_ljeto_B__5": {"A":"Zvučni i svjetlosni signali opisuju ponašanje automata, ali nisu razlog za sklopljeno ime Bobby-pjutor.","C":"Ime nije nastalo prema stricu, nego od šahista Bobbyja Fischera i riječi 'computer'.","D":"Američko podrijetlo poklona ne objašnjava značenje samog imena."},
  "2020_ljeto_B__6": {"A":"Pijukanje 'kao tek izleglo pile' personifikacija je/usporedba zvučnih signala, a ne prilagodba težine igre.","B":"Tužno namigivanje 'Gotova igra' personificira automat pri porazu, ne odnosi se na biranje težine.","C":"Iskričavo oko 'kao fakin iz Bronxa' personifikacija je automata pri pobjedi, bez veze s prilagodbom težine."},
  "2020_ljeto_B__7": {"A":"Tekst ne spominje strah od ropstva; bojazan je vezana uz tjelesni nasrtaj.","B":"Pripovjedačica strahuje od onoga što slijedi nakon gozbe, a ne od progonstva (njezino su je progonstvo već zadesila braća).","D":"Strah nije od ubojstva, nego od toga da je Holoferno 'u grubom nasrtaju' obljubi."},
  "2020_ljeto_B__8": {"A":"Način ophođenja izraelskih sinova navodi se samo kao usporedba za Holofernovu drukčiju nježnost, nije izvor zbunjenosti.","C":"Postupci braće (progonstvo) izazivaju bol, ali pripovjedačicu zbunjuje upravo Holofernovo ponašanje.","D":"Odlazak zapovjednika tek je okolnost koja prethodi razgovoru, a ne uzrok zbunjenosti."},
  "2020_ljeto_B__9": {"A":"Zbunjenost je njezina reakcija na Holoferna, a ne osobina kojom ga je osvojila.","B":"Ljubaznost je obilježje Holofernova ponašanja prema njoj, a ne ono čime ga je ona privukla.","C":"Smirenost se ne navodi kao razlog Holofernove naklonosti; on hvali njezine 'umne rečenice'."},
  "2020_ljeto_B__10": {"A":"Pijesak se posipa radi sušenja, a žutilo tinte posljedica je starosti, a ne svrha posipanja.","C":"Svrha pijeska bila je upijanje, a ne postizanje svjetlucavog izgleda.","D":"Tinta blijedi s vremenom; pijesak se nije posipao da bi izblijedjela, nego da se ne razlije."},
  "2020_ljeto_B__11": {"A":"Majčino ime stoji iznad Hannova (među imenima roditelja), a ne kao posljednje.","C":"Pripovjedač je izvanjski (3. lice), njegovo ime nije upisano u rodoslovlje.","D":"Senatorovo (očevo) ime nalazi se iznad Hannova, a ne na samome kraju."},
  "2020_ljeto_B__12": {"B":"Pero je sredstvo kojim je Hanno povukao crte, ali ljutnja je zbog crtanja po rodoslovlju, ne zbog uzimanja pera.","C":"Hanno nije prekrižio svoje ime, nego povukao crte preko genealoškog stabla.","D":"Neurednost nije uzrok; senator reagira na oštećenje obiteljskog dokumenta."},
  "2020_ljeto_B__13": {"B":"Cintek se pred gostima ponaša 'gospodski', ali pjevanje je naredio iz gospodarskog razloga, ne radi hvalisanja.","C":"Zabava gostiju nije svrha pjevanja u vinogradu; cilj je spriječiti zobanje grožđa.","D":"Raspoloženje berača nije razlog; Cintek je htio da pjevanjem ne mogu jesti grožđe."},
  "2020_ljeto_B__14": {"A":"Gosti su oni kojima 'mome' pjevaju, a ne osobe na koje se izraz odnosi.","B":"Majke se u ulomku ne spominju kao 'mlade mome'.","C":"'Mome' su djevojke (ženski rod), a momci su muškarci, pa se izraz na njih ne odnosi."},
  "2020_ljeto_B__15": {"A":"Cintek im dopušta da pjevaju, dakle ne prekorava ih zbog kvalitete pjevanja.","B":"Ne zamjera djevojkama nerazlikovanje staleža, nego ih sam upozorava da to razlikovanje ne smiju zaboraviti.","D":"Cintek je raspoložen i dopušta pjesmu; problem je u inzistiranju na staleškoj razlici."},
  "2020_ljeto_B__16": {"B":"Majka tipka sa svih deset prstiju, ali sporije; ona je predmet usporedbe, a ne ona koja se čudi.","C":"Očuh (Ladislav) povezan je s učenjem tipkanja, ali se ne navodi kao onaj tko se čudio brzini.","D":"Klaudija je prva supruga (pokojna) i u ulomku ne reagira na Maksovu brzinu tipkanja."},
  "2020_ljeto_B__17": {"A":"Tekst ne navodi zapisivanje predavanja kao razlog učenja tipkanja.","B":"Odužiti se očuhu nije razlog; tipkanje je naučio jer je očuh zahtijevao čitljiv, otipkani tekst.","D":"Novinarska ambicija ne spominje se kao motiv; uzrok je očuhova nemogućnost čitanja rukopisa."},
  "2020_ljeto_B__18": {"A":"Razbaštinjenje se ne spominje; 'brisanje Petra' odnosi se na promjenu imena u matičnom listu.","B":"Petar nije sin iz braka, nego ranije ime samog Maksimilijana.","D":"Nije riječ o nasljeđivanju, nego o tome da je Ladislav izbrisao ime Petar i upisao Maksimilijan."},
  "2020_ljeto_B__19": {"B":"Loši uvjeti rada nisu predmet Mariofilove kritike; kritizira nezakonitu prodaju knjiga.","C":"Količina dovezenih knjiga sama po sebi nije sporna; sporna je njihova ilegalna preprodaja.","D":"Zaštita knjiga od vlage ne spominje se kao razlog kritike Gecekova poslovanja."},
  "2020_ljeto_B__20": {"A":"Susreti s Gecekovom ženom ne navode se kao razlog Mariofilova zadovoljstva otkazom.","B":"Mariofil nije izbjegao umirovljenje (to se odnosi na djeda Ivana); radost je zbog slobode čitanja.","C":"Mnoštvo knjiga ga ne zamara; naprotiv, knjige su mu užitak koji je morao tajiti."},
  "2020_ljeto_B__21": {"A":"Nelagodu ne izaziva razgovor s djedom i bakom, nego pitanja o vlastitom podrijetlu.","C":"Osamljenost mjesta nije izvor nelagode; nelagodu bude 'stare enigme' o identitetu.","D":"Blizina vode ne navodi se kao razlog nelagode."},
  "2020_ljeto_B__22": {"B":"Novinarski ured nije prostor scene; kontekst (ludnica, dr. Vranešić) upućuje na duševnu bolnicu.","C":"Knjižnica se ne spominje; radnja se odvija u 'ludnici'.","D":"Kazalište nije mjesto radnje, premda su likovi pisci; 'ambijent' se odnosi na duševnu bolnicu."},
  "2020_ljeto_B__23": {"A":"Duhovitost nije ono čemu Krleža zavidi; on izrijekom zavidi na tiraži.","B":"Novinarstvo nije predmet zavisti; zavist se odnosi na velik broj prodanih primjeraka.","C":"Trivijalnost (popularna književnost) nije razlog zavisti, nego upravo njezina velika naklada."},
  "2020_ljeto_B__24": {"A":"Vranešić ne osuđuje njihovo druženje; on ih štiti.","B":"Vranešić ih ne dovodi u opasnost, nego ih sklanja 'od pogibelji'.","C":"Vranešić ne objavljuje njihova djela; on im pruža sklonište."},
  "2020_ljeto_B__25": {"B":"Tekst tvrdi suprotno: kokoši su bile uz ljudske nastambe, pa udaljavanje od njih nije uzrok.","C":"Građa tijela im odgovara letu (krila, zračne komore u kostima); nije ona razlog gubitka leta.","D":"Sastav krvi nije naveden kao uzrok; uzgoj radi mesa doveo je do gubitka sposobnosti letenja."},
  "2020_ljeto_B__26": {"A":"Aktivnost mišića povećava mioglobin, a ne hemoglobin.","B":"Tekst ne tvrdi da aktivnost mišića pogoršava kvalitetu mesa.","C":"Smanjenje kisika ne navodi se kao posljedica mišićne aktivnosti; posljedica je tamnija boja mesa."},
  "2020_ljeto_B__27": {"B":"Gubitak letenja u tekstu se veže uz kokoši (pasmine za meso), a ne uz ptice selice.","C":"Zračne komore u kostima opće su obilježje ptica i ne pripisuju se selicama kao nedostatak.","D":"Tekst tvrdi da selice na prsima imaju tamno meso; o boji mesa krila ne govori se kao o bijelom."},
  "2020_ljeto_B__28": {"B":"Tekst nije puko izvješćivanje o činjenicama, nego poučavanje o pravilnom branju gljiva.","C":"Svrha nije zabava; tekst daje praktične upute.","D":"Tekst je popularno-poučan, a ne strogo znanstven sa znanstvenim aparatom."},
  "2020_ljeto_B__29": {"A":"Razlikovanje jestivih i nejestivih gljiva važna je vještina, ali nije istaknuto kao temeljna vrijednost gljivarenja.","B":"Podizanje kvalitete prehrane nije navedeno kao temelj; temelj je doživljaj prirode.","C":"Otkrivanje novih vrsta ne spominje se kao svrha; naglasak je na uživanju u šetnji i prirodi."},
  "2020_ljeto_B__30": {"A":"Neodgovarajući uvjeti čuvanja kvare ubrane gljive, ali ne smanjuju daljnji rast vrste na staništu.","B":"Čišćenje od zemlje i insekata postupak je s ubranom gljivom, ne utječe na rast vrste.","C":"Zatrpavanje staništa ne spominje se kao uzrok; rast se smanjuje rezanjem stručka nožem koje ugrožava micelij."},
  "2020_ljeto_B__31": {"A":"Akrostih je oblik u kojem početna slova stihova daju riječ ili poruku, a ne književna vrsta.","B":"Heksametar je vrsta stiha (šestomjerni), a ne književna vrsta.","D":"Septima je strofa od sedam stihova, dakle vrsta strofe, a ne književna vrsta."},
  "2020_ljeto_B__32": {"A":"Oktava nije pjesma od osam strofa, nego strofa od osam stihova.","B":"Stih od osam slogova je osmerac, a ne oktava.","D":"Zbirka od osam pjesama nije oktava; oktava je strofni oblik."},
  "2020_ljeto_B__33": {"A":"Usporavanje radnje (retardacija) postupak je u epu, ali nije uloga invokacije.","C":"Oponašanje stvarnosti (mimeza) opće je obilježje književnosti, a ne svrha invokacije.","D":"Pročišćenje osjećaja (katarza) vezano je uz tragediju, a ne uz invokaciju epa."},
  "2020_ljeto_B__34": {"A":"'Zdrava Marija' aluzija je na molitvu/sutonsko zvono, a ne spoj proturječnih pojmova.","B":"'Lasta i bršljan' metafore su (slike) drage osobe, bez unutarnje proturječnosti.","C":"'Rujne ruže' su metafora mladosti, a ne oksimoron."},
  "2020_ljeto_B__35": {"A":"Zazivanje slugu i opis kule vizualni je prizor bez riječi koje oponašaju zvuk.","C":"Stihovi o strahu i jadu izriču misao/poruku, bez onomatopejskoga zvuka.","D":"Najava junakova govora i korenja nije zvukovno oponašanje, nego najava radnje."},
  "2020_ljeto_B__36": {"A":"Agamemnon nije žrtva ovoga čina; radnja se odnosi na onoga koga Ahilej vuče za kola.","B":"Ahilej je vršitelj radnje (on probija žile i vuče), a ne onaj na koga se podcrtana riječ odnosi.","D":"Paris nije lik ovoga prizora; vuče se Hektorovo tijelo."},
  "2020_ljeto_B__37": {"B":"Helena je junakinja Trojanskoga rata, ne pokopava brata niti se suprotstavlja Kreontu.","C":"Judita ubija Holoferna, a ne pokopava brata protiv kraljeve zabrane.","D":"Penelopa vjerno čeka Odiseja; nije ona koja je pokopala brata."},
  "2020_ljeto_B__38": {"A":"Shakespeare ne piše o Euklioni i ćupu zlata; ti su motivi iz Plautove komedije.","B":"Držić se nadahnuo Plautom, ali likovi Euklion i Likonid pripadaju Plautovoj Aulularii.","C":"Molière je obradio sličan motiv u Škrcu, ali navedeni likovi su Plautovi."},
  "2020_ljeto_B__39": {"A":"Črnorizac Hrabar autor je spisa O pismenima (obrana glagoljice), a ne duhovne autobiografije.","B":"Opat Držiha vezan je uz Bašćansku ploču, ne uz autobiografiju o Božjoj providnosti.","C":"Pop Martinac poznat je po zapisu o Krbavskoj bici, a ne po autobiografiji."},
  "2020_ljeto_B__40": {"B":"Dekameron je zbirka novela, bez prikaza pakla podijeljena na devet krugova.","C":"Ilijada je ep o Trojanskom ratu, ne donosi sliku devetorostrukog pakla.","D":"Judita je biblijski ep o oslobođenju grada, bez vizije pakla u devet krugova."},
  "2020_ljeto_B__41": {"A":"Antun Kanižlić je barokni pjesnik (Sveta Rožalija), a ne petrarkist.","C":"Ivan Česmički (Janus Pannonius) latinist je i humanist, ne petrarkistički pjesnik na narodnom jeziku.","D":"Ivan Gundulić je barokni pjesnik (Osman, Suze sina razmetnoga), a ne petrarkist."},
  "2020_ljeto_B__42": {"B":"Pjesnik kao junak alegorijske vizije zagrobnog života je Dante (Božanstvena komedija), ne don Quijote.","C":"Odgađanje osvete zbog sumnji odlika je Hamleta, a ne don Quijotea.","D":"Div koji nakon rođenja traži piće je Gargantua (Rabelais), ne don Quijote."},
  "2020_ljeto_B__43": {"B":"Judita je biblijski ep Marka Marulića, a ne melodrama.","C":"Okovani Prometej je antička tragedija (Eshil), a ne melodrama.","D":"Suze sina razmetnoga su religiozna (barokna) poema Gundulićeva, a ne melodrama."},
  "2020_ljeto_B__44": {"A":"Romantičarska poema ne počiva na trima jedinstvima ni na strogom klasicističkom kanonu.","B":"Renesansna komedija ne podrazumijeva strogo poštivanje triju jedinstava i Aristotelove poetike kao norme.","D":"Barokni ep ne uređuje se pravilom triju jedinstava, koje pripada drami."},
  "2020_ljeto_B__45": {"A":"Racionalno promišljanje likova obilježje je prosvjetiteljstva/klasicizma, ne romantizma.","B":"Oslanjanje na religiozne motive svojstvenije je srednjem vijeku i baroku.","D":"Vraćanje renesansnim uzorima odlika je klasicizma, a ne romantizma."},
  "2020_ljeto_B__46": {"B":"Odlazak na studij u Beč i odavanje porocima odnosi se na Ivicu Kičmanovića (U registraturi), ne na Rastignaca.","C":"Nadareni seoski dječak na školovanju za svećenika je Julien Sorel (Crveno i crno).","D":"Članak o podjeli ljudi na nižu i višu vrstu piše Raskoljnikov (Zločin i kazna)."},
  "2020_ljeto_B__47": {"A":"Ferkonja je drugi lik romana i ne odgovara opisu razmetljivca s prstenjem koji glumi pobožnost.","B":"Ivica Kičmanović je glavni lik, a opis se odnosi na bogatoga rođaka koji se kočoperi prstenjem.","D":"Mecena je Ivičin pokrovitelj, a ne lik koji u crkvi razmeće prstenjem."},
  "2020_ljeto_B__48": {"A":"Buđenje nacionalne svijesti suprotno je larpurlartizmu; to je njegova negacija (utilitarnost umjetnosti).","C":"Oponašanje stvarnosti (mimeza) nije bit larpurlartizma, koji odbacuje izvanjsku svrhu.","D":"Didaktička uloga upravo je ono što larpurlartizam odbacuje."},
  "2020_ljeto_B__49": {"A":"Izmena (Antigonina sestra) ne napušta supruga i djecu.","B":"Lotta je Wertherova ljubav koja se udaje za Alberta; ne ostavlja muža i djecu.","D":"Ofelija je Hamletova ljubav koja se utapa; nije supruga ni majka koja odlazi."},
  "2020_ljeto_B__50": {"B":"Neslomljivost u borbi za život uz gubitak djece odnosi se na Majku Hrabrost (Brecht), ne na Srnu.","C":"Pokoravanje volji supruga i uloga 'slobodne ropkinje' ne opisuje Srnu iz Duge.","D":"Hedonistička manipulacija muškarcima nije obilježje Srne, nego drukčijih književnih likova."},
  "2020_ljeto_B__51": {"A":"Dolazak na obljetnicu obiteljske tvrtke nakon jedanaest godina ne odgovara Đuki Begoviću.","B":"Dolazak radi nasljedstva po majčinu nalogu nije Đukina priča.","C":"Povratak nakon četiri godine u kaznionici opisuje drugog junaka, ne Đuku Begovića (23 godine)."},
  "2020_ljeto_B__52": {"A":"Patnje mladoga Werthera epistolarni su roman o nesretnoj ljubavi, bez scene s čajem i kolačem.","B":"Majka Hrabrost je Brechtova drama, a citat je proza o sjećanju izazvanom okusom.","C":"Otac Goriot ne sadrži ovu scenu involuntarnog sjećanja kroz okus madeleine."},
  "2020_ljeto_B__53": {"B":"Okupljanje oko Krugova i Razloga pripada razdoblju nakon 1950., a ne razdoblju 1914.–1929.","C":"Proza u trapericama javlja se 1960-ih, ne u zadanom razdoblju.","D":"Egzistencijalistička književnost prevladava sredinom 20. stoljeća, a ne 1914.–1929."},
  "2020_ljeto_B__54": {"A":"Simbolistička drama ne koristi songove ni Brechtov učinak začudnosti.","B":"Građanska drama temelji se na iluziji stvarnosti i identifikaciji, a ne na začudnosti i songovima.","C":"Kazalište apsurda obilježeno je besmislom i razgradnjom jezika, ne songovima i začudnošću."},
  "2020_ljeto_B__55": {"B":"Dobriša Cesarić nije autor pjesme 'Pjesnici'; ona pripada Šimiću.","C":"Tin Ujević nije autor navedenih stihova iz Preobraženja.","D":"Vladimir Vidrić nije autor ovih stihova; riječ je o Šimićevoj pjesmi 'Pjesnici'."},
  "2020_ljeto_B__56": {"A":"'Bijelina' je netočno; pravilno je 'bjelina' (ije→je u izvedenici).","C":"'Ogrijev' je netočno; pravilno je 'ogrjev' (kratki refleks jata).","D":"'Slijepoća' je netočno; pravilno je 'sljepoća'."},
  "2020_ljeto_B__57": {"A":"'Daskica' je netočno jer izostaje glasovna promjena sk→šč.","B":"'Daščičica' je umanjenica drugog stupnja (od daščice), a ne osnovna umanjenica od 'daska'.","C":"'Dasčica' je netočno napisana; pravilno je 'daščica'."},
  "2020_ljeto_B__58": {"A":"'Gozba' (gost > gozba) nastaje jednačenjem po zvučnosti (st→zb), a ne palatalizacijom.","B":"'Lišće' (list > lišće) nastaje jotacijom, a ne palatalizacijom.","C":"'Mišlju' (misao > mišlju) rezultat je jotacije, a ne palatalizacije."},
  "2020_ljeto_B__59": {"A":"Pogrešno: ime županije piše se velikim početnim slovom prve sastavnice ('Sisačko-moslavačka').","C":"Pogrešno: druga sastavnica pridjeva piše se malim slovom ('moslavačka', ne 'Moslavačke').","D":"Pogrešno: 'županija' je opća imenica i piše se malim slovom, a druga sastavnica također."},
  "2020_ljeto_B__60": {"A":"Netočno: pravilno je 'ultraljubičastih' (sastavljeno, bez crtice).","C":"Netočno: pravilno je 'videopoziv' (sastavljeno, bez crtice).","D":"Netočno: 'čovjek-zvijer' ovdje nije zadani ispravni primjer; uzorni je oblik 'remek-djelo'."},
  "2020_ljeto_B__61": {"A":"'Posljedica' ima vidljiv gramatički morfem -a (nominativ), pa nema nultoga morfema.","C":"'Selo' ima vidljiv nastavak -o, dakle ne nulti morfem.","D":"'Vojvoda' ima vidljiv nastavak -a, pa nema nultoga morfema."},
  "2020_ljeto_B__62": {"A":"U 'jest kruh' riječ 'kruh' je u nominativu (predikatno ime), a ne u akuzativu.","B":"U 'nema kruha' riječ je u genitivu (uz niječni 'nema').","C":"U 'bi kruha' riječ je u partitivnom genitivu, a ne u akuzativu."},
  "2020_ljeto_B__63": {"B":"'Kutem' je pravilno tvoren instrumental (kut > kutem/kutom), pa nije netočan primjer.","C":"'Mačem' je pravilan instrumental (mač > mačem), nije netočno.","D":"'Nosom' je pravilan instrumental (nos > nosom), nije netočno."},
  "2020_ljeto_B__64": {"B":"Glagolski pridjev radni glasio bi 'gledao'; 'gledajući' to nije.","C":"Prezent bi bio 'gleda'; 'gledajući' nije prezent.","D":"Infinitiv bi bio 'gledati'; 'gledajući' nije infinitiv."},
  "2020_ljeto_B__65": {"A":"'Na' je prijedlog (uz 'na desnoj obali'), a ne prilog.","C":"'Se' je povratna zamjenica/čestica uz glagol, a ne prilog.","D":"'Glasno' je ovdje pridjev koji opisuje imenicu 'zapljuskivanje', a ne prilog."},
  "2020_ljeto_B__66": {"A":"'Na dnu jezera' je rektivna (prijedložno-padežna) sintagma, ne sročna.","B":"'Jedva se nazirala' je glagolski predikat s prilogom, a ne sročna imenska sintagma.","C":"'Davno potopljena' veza je priloga i glagolskog pridjeva, a ne sročnost pridjeva i imenice."},
  "2020_ljeto_B__67": {"B":"'Knjiga' je ovdje dio naslova/apozicija ('Roman Knjiga o džungli'), a ne objekt.","C":"'U knjigama' je u lokativu s prijedlogom 'u', dakle priložna oznaka, ne objekt.","D":"'Knjiga' u 'svidjela mi se knjiga' je subjekt, a ne objekt."},
  "2020_ljeto_B__68": {"A":"Dvije surečenice premalo: rečenica sadrži pet zavisnih i nezavisnih dijelova.","B":"Tri surečenice nije dovoljno; ima ih pet (uključujući obje 'da'-rečenice).","C":"Četiri surečenice nije točno; izostavlja se jedna od dviju objektnih ('da jesam' i 'da ćete doći')."},
  "2020_ljeto_B__69": {"A":"'Budući da je rano krenuo' je uzročna zavisna rečenica, a ne objektna.","B":"'Da stigne na vrijeme' je namjerna rečenica, a ne objektna.","C":"'Da je važno stići' je subjektna rečenica (zna se što?), a ne objektna."},
  "2020_ljeto_B__70": {"B":"Netočno: pravilno je 'zamolio glumca za fotografiju' (zamoliti za + akuzativ).","C":"Netočno: pravilno je 'darivati nekoga' ('darivamo vas'), a ne 'darujemo'.","D":"Netočno: glagol 'lagati' veže se s dativom ('lagati nekomu'), pa konstrukcija nije ispravna."},
  "2020_ljeto_B__71": {"A":"Netočno: upitnik treba biti unutar navodnika jer pripada upravnom govoru.","C":"Netočno: izostaje obavezni zarez iza vokativa 'Sine', a upitnik je izvan navodnika.","D":"Netočno: nedostaje zarez iza vokativa 'Sine'."},
  "2020_ljeto_B__72": {"A":"Tratinčica i maćuhica supojmovi su (kohiponimi, obje su cvijeće), a ne nadređeno-podređeni.","B":"Šuma nije nadređeni pojam voćnjaku; nisu u hijerarhijskom odnosu.","D":"Konj i kobila nisu nadređeno-podređeni na isti način (kobila je ženka konja, ne vrsta peradi); traženi je primjer perad–kokoš."},
  "2020_ljeto_B__73": {"B":"Bliskost i blizina su sinonimi (istoznačnice), a ne antonimi.","C":"Cvijet i tulipan su u odnosu nadređenosti/podređenosti (hiponimija), a ne suprotnosti.","D":"Laž i neistina su sinonimi, a ne antonimi."},
  "2020_ljeto_B__74": {"A":"'Konstrukcija' je prilagođena posuđenica (usvojenica), a ne neprilagođena tuđica.","B":"'Politika' je usvojenica, fonološki i morfološki prilagođena hrvatskom.","C":"'Centar' je prilagođena posuđenica, a ne tuđica poput 'šou'."},
  "2020_ljeto_B__75": {"A":"Posuđenice iz španjolskoga su hispanizmi, a ne hungarizmi.","C":"Posuđenice iz francuskoga su galicizmi, a ne hungarizmi.","D":"Posuđenice iz grčkoga su grecizmi/helenizmi, a ne hungarizmi."},
  "2020_ljeto_B__76": {"B":"'Bankomatima' uz objašnjenje 'tzv.' nije pleonazam, nego uobičajeno pojašnjenje.","C":"'Javna tajna' je ustaljeni frazem (oksimoron), a ne pleonazam.","D":"'Stambeni kredit' je obična sintagma bez suvišnoga ponavljanja značenja."},
  "2020_ljeto_B__77": {"B":"Netočno: iza 'izjavio je' u standardu se traži 'da je spreman', a ne 'kako se spreman'.","C":"Netočno: pogrešno je slaganje ('filmu... snimljenog'→ 'snimljenom') i pogrešna godina.","D":"Netočno: pravilno je 's visokom dozom sigurnosti' (genitiv), a ne 'sigurnošću'."},
  "2020_ljeto_B__78": {"A":"'Osjetilni' se odnosi na osjetila (vid, sluh...), a ne na spoznajne procese.","B":"'Razvojni' označava razvoj, a ne spoznaju; nije bliskoznačno 'kognitivnom'.","C":"'Osjećajni' se tiče emocija, a 'kognitivni' se odnosi na spoznaju."},
  "2020_ljeto_B__79": {"B":"'Požuriti' nije značenje frazema; 'dati petama vjetra' znači pobjeći.","C":"'Prestrašiti se' nije značenje; frazem opisuje sam čin bijega, ne osjećaj straha.","D":"'Skriti se' nije značenje frazema; riječ je o brzom bijegu."},
  "2020_ljeto_B__80": {"A":"Bartol Kašić autor je prve hrvatske gramatike (1604.), a ne Gajeva pravopisa.","B":"Ivan Belostenec poznat je po rječniku Gazophylacium, a ne po ovome pravopisu.","C":"Juraj Habdelić autor je kajkavskih djela i rječnika, a ne Kratke osnove."},

  // 2021_jesen_A
  "2021_jesen_A__1": {"A":"Odlazak djece iz Francuske nije spomenut; majke s djecom čekaju brod, ne opisuje se nikakav njihov odlazak.","B":"Krstarica je ono što more zapravo donosi (rat), a ne ono što se naziva varkom; varka je obećana pomoć.","C":"Bijeg od opasnosti nije tema stihova; lirski subjekt govori o iščekivanju pomoći, a ne o bijegu."},
  "2021_jesen_A__2": {"A":"Marame ('crnim maramama') vezane su uz majke koje tuguju i čekaju, a ne uz najavu dolaska rata.","C":"Antene su poredbena slika ('kao antene') za šuplje cijevi i ne uvode izravno motiv rata kao vojni simboli.","D":"Mrak se u danome ulomku ne navodi kao riječ kojom se najavljuje rat."},
  "2021_jesen_A__3": {"A":"'Rekli su vam da će doći' iskazuje obećanje pomoći, a ne uzaludnost nade.","B":"'i da je nebo bilo puno pozdrava i želja' izražava ohrabrenje i podršku, a ne uzaludno nadanje.","C":"'Doći će, sad, sad, sad' prenosi napeto očekivanje, ali tek sljedeći stih razotkriva da je nada uzaludna."},
  "2021_jesen_A__4": {"A":"Govor se održava prije bitke radi ohrabrenja, a ne kao proslava pobjede nad Turcima.","C":"Zrinski potiče vojnike na hrabrost i čast, ali ne razrađuje konkretnu vojnu taktiku.","D":"Riječ je o obraćanju vojnicima ('moji sini i ma bratjo'), a ne o opraštanju od obitelji."},
  "2021_jesen_A__5": {"B":"'mudar kako guja, a smić kakono lav' poredbama ističe Zrinskovu mudrost i hrabrost, a ne njegovu slavu.","C":"'da su vam svitlosti dočim god svit bude' odnosi se na slavu vojnika kojima se Zrinski obraća, a ne na njega.","D":"'vičnji mu glas slavan do nebes dopira' ne pripada navedenome ulomku govora."},
  "2021_jesen_A__6": {"A":"'Moji sini i ma bratjo mila' je oslovljavanje slušatelja, a ne sažeta općeljudska mudrost.","B":"'Vi ste mnoge čete turačke razbili' iznosi konkretnu pohvalu prošlih djela, a ne aforizam.","D":"'Da nam se svaki vlas poštenjem odiva' je poticaj na čast, ali nije zaokružena općevažeća misao kao aforizam."},
  "2021_jesen_A__7": {"A":"Grafostilemom se ne ističe Arkadijevo neshvaćanje Katjinih sklonosti, nego teme njihovih razgovora.","C":"Odnos likova prema prirodi tema je drugog dijela teksta, a ne ono što kurziv 'sitnice' naglašava.","D":"Grafostilemom se ne ističe Arkadijevo zavođenje, nego teme njihovih razgovora (glazba, romani, pjesme)."},
  "2021_jesen_A__8": {"A":"Bazarov ne zamjera Arkadiju otmjeno ponašanje; uzrok promjene je njihova razdvojenost.","C":"Bazarovljev stav prema Katjinoj sentimentalnosti nije naveden kao razlog promjene odnosa.","D":"Ne radi se o sramoti zbog javnih nastupa, nego o tome što se Bazarov kloni Arkadija i manje s njim razgovara."},
  "2021_jesen_A__9": {"A":"'Arkadiju je bilo lijepo s Katjom...' iznosi stanje likova bez izravnog isticanja pripovjedačeve osobnosti.","B":"'Odincova je bila prilično ravnodušna prema prirodi' objektivna je karakterizacija, bez pripovjedačeva uplitanja.","D":"'Uopće je kudikamo manje razgovarao...' opisuje promjenu odnosa neutralno, bez subjektivne zamjenice kao u 'naših prijatelja'."},
  "2021_jesen_A__10": {"B":"Racionalizam pripovjedač spominje (filozofija modernog vijeka), ali ga ne osuđuje izravno; ključ je tuga za starim.","C":"Pripovjedač ne vidi priliku za zaradu; izražava sjetu zbog nestajanja starih kurija.","D":"Pripovjedač ne prihvaća napredak vedro, nego mu je 'teško oko srca' zbog nestanka starine."},
  "2021_jesen_A__11": {"A":"'zemlja žutica' odnosi se na tlo/njive, a ne na kurije.","C":"'ogromni kapišoni' nisu naziv za kurije u ovome ulomku.","D":"'progonjeni sokolovi' nije izraz kojim se označavaju kurije."},
  "2021_jesen_A__12": {"A":"Zidovi su vizualni ('crne zidove'), a ne olfaktivni motiv.","B":"Njive se vežu uz vizualni dojam ('jednolične suhe njive'), a ne uz miris.","C":"Sove su poredbena vizualna slika ('naličile glavama sova'), a ne olfaktivni podražaj."},
  "2021_jesen_A__13": {"A":"Povod nije književni rad pjesnika; slavi se 'radna pobjeda' (graditeljski uspjeh).","C":"Narodno veselje je dio programa nakon svečanosti, a ne povod same svečanosti.","D":"Nastup zbora dio je prigodnoga programa, a ne razlog okupljanja."},
  "2021_jesen_A__14": {"B":"Zagrade ne daju upute publici, nego didaskalijski bilježe reakcije i atmosferu.","C":"U zagradama se ne iznose govornikova razmišljanja, nego se dočarava ozračje (pljesak, stanka).","D":"Zagrade ne donose komentare zbora, nego opis atmosfere tijekom govora."},
  "2021_jesen_A__15": {"A":"Učitelj ne recitira; daje intonaciju i zamahuje rukama kao da vodi orkestar.","C":"Govor drži član Direkcije, a ne učitelj.","D":"Učitelj ne pjeva sam, nego rukama dirigira pjevačima."},
  "2021_jesen_A__16": {"A":"Mještani nisu imali problema s vodom; kuće su raspoređene tako da svaka ima jednak pristup rijeci.","B":"Tekst ne govori o sporom razvoju zbog izoliranosti, nego o organiziranosti naselja.","C":"Nije zabranjen uzgoj peradi općenito, nego samo borbeni pijetlovi."},
  "2021_jesen_A__17": {"A":"Zamke nisu postavljene radi obrane od neprijatelja.","B":"Zamke nisu vezane uz sprječavanje borbi pijetlova.","C":"Zamke nisu postavljene radi zaštite povrtnjaka, nego radi hvatanja ptica."},
  "2021_jesen_A__18": {"A":"Vosak u ušima nije znak odbijanja pregovora s Melquíadesovim plemenom.","B":"Vosak nije lijek protiv glavobolje, nego sredstvo da ne izgubi osjećaj za stvarnost.","D":"Razlog nije nesklonost ptičjem pjevu, nego želja da ostane prisebna."},
  "2021_jesen_A__19": {"B":"Riječi se ne odnose na otvoreno iskazivanje ljubavi, nego na očevu pohvalu Rodriga.","C":"U ulomku se ne govori o Rodrigovu uzvraćanju ljubavi, nego o očevu mišljenju.","D":"Riječi prenose očevo mišljenje, a ne Elvirino mišljenje o Rodrigu."},
  "2021_jesen_A__20": {"B":"Oca nije dirnula Himenina ravnodušnost prema Rodrigovu plemstvu, nego njezino poštovanje prema njegovu izboru.","C":"Oca nije dirnulo to što Himenu prose dvojica mladića, nego njezino prepuštanje odluke njemu.","D":"Himena u ovom trenutku još nije odabrala Rodriga; dirnulo ga je poštovanje ('Već očev nalog čeka')."},
  "2021_jesen_A__21": {"A":"Stih ne govori o mukotrpnom probijanju kroz život, nego o slavi danoj od rođenja.","C":"Stih ne opisuje život u izobilju, nego predodređenost za uspjeh ('lovor-vijence... grle').","D":"Stih ne najavljuje preranu smrt, nego slavu i pobjedu od rođenja."},
  "2021_jesen_A__22": {"A":"Heraklo ne tvrdi da spomenici pjesnicima ne donose inspiraciju; razlog je njegova nedostojnost.","B":"Razlog nije to što drugi ne vole kip (mještani mu se klanjaju), nego osjećaj vlastite nedostojnosti.","D":"Heraklo ne traži uklanjanje zbog oronulosti kipa, nego zato što sebe smatra nedostojnim heroja."},
  "2021_jesen_A__23": {"B":"U ovom se ulomku ne iskazuje Heraklovo poštovanje prema Dejaniri.","C":"Heraklo nije spasio djevojku; upravo je mirno promatrao kako se utapa.","D":"Heraklo nije bolestan; to je tek pretpostavka koju izriče upućena kipu."},
  "2021_jesen_A__24": {"A":"'Heraklo, oni ti se klanjaju' je Lihina obavijest, bez ironijskoga obrata značenja.","B":"'da si uklonio tog monstruma' je izravna zapovijed s prijezirom, ali bez ironije.","D":"'Oni su tebe čekali, Heraklo' je obavijest bez suprotnosti rečenoga i mišljenoga."},
  "2021_jesen_A__25": {"A":"Tekst ne tumači pridjeve i glagole istoga korijena kao svoju temu, nego kritizira površno znanje.","B":"Tekst ne predstavlja Marulićevo pjesništvo, nego problematizira (ne)razumijevanje i površnost.","D":"Tema nije povezivanje povijesti i književnosti, nego kritika površnosti u stjecanju znanja."},
  "2021_jesen_A__26": {"A":"Marulić se spominje kao uzor jeziku, ali sporni je stih iz Ujevićeve pjesme.","C":"Krleža se u ulomku ne spominje kao autor spornoga stiha.","D":"Kružić nije autor stiha o kojem se raspravlja."},
  "2021_jesen_A__27": {"B":"To što studenti ne razumiju riječi jest činjenica, ali nije paradoks koji autorica objašnjava.","C":"Neprepoznavanje 'ćuhta' kao glagola je primjer nerazumijevanja, a ne objašnjeni paradoks.","D":"Zbunjujuće riječi su povod, ali paradoks je da se sjećati možeš samo onoga što si znao."},
  "2021_jesen_A__28": {"A":"Riječ se ne odnosi na Duchampov odlazak u New York, nego na odigranu partiju.","C":"Halberstadtova pobjeda nije ono na što upućuje podcrtana riječ.","D":"Marshall nije poražen, nego je partija završila remijem (neriješeno)."},
  "2021_jesen_A__29": {"A":"Voltaire nije lik predstavljen anegdotom u ovome ulomku.","B":"Henry Thomas Buckle nije onaj o kome se pripovijeda anegdota.","D":"Victorie Tregear nije osoba predstavljena anegdotom o šahu i revanšu."},
  "2021_jesen_A__30": {"A":"Za francusku momčad nastupio je Duchamp, a ne Halberstadt.","C":"Džepnu šahovsku garnituru oblikovao je Duchamp, a ne Halberstadt.","D":"Izjavu da su svi šahisti umjetnici tekst ne pripisuje Halberstadtu."},
  "2021_jesen_A__31": {"B":"'Prokleta avlija' nije naslov utemeljen na antitezi (suprotstavljanju pojmova).","C":"'Zločin i kazna' povezuje uzrok i posljedicu, a ne suprotnosti, pa nije antiteza.","D":"'Crni mačak' nema antitetičke parove pojmova."},
  "2021_jesen_A__32": {"B":"Hiperbola je pretjerivanje; ovdje nema preuveličavanja, nego ublažavanja.","C":"Ironija znači reći suprotno od mišljenoga, čega u ovoj rečenici nema.","D":"Paradoks je prividno proturječje; rečenica ne sadrži takvu protuslovnu misao."},
  "2021_jesen_A__33": {"A":"Akrostih je poruka skrivena u početnim slovima stihova, a ne odstupanje od radnje.","C":"Invokacija je zaziv muze/božanstva, a ne udaljavanje od glavne radnje.","D":"Peripetija je obrat u radnji, a ne odstupanje od nje."},
  "2021_jesen_A__34": {"A":"Suprotstavljenost katrena i tercina obilježje je Petrarcina, ali ne i Shakespeareova soneta.","B":"Poantu u završnome distihu donosi Shakespeareov, a ne Petrarcin sonet.","D":"Broj strofa nije isti: Petrarcin ima dvije tercine, a Shakespeareov distih."},
  "2021_jesen_A__35": {"A":"Opisano raspoloženje žaljenja za izgubljenim odlika je elegije, a ne romance.","B":"Tragičan završetak i teme iz narodne povijesti odlike su balade, a ne romance.","C":"Veličanje ljepote prirode i seoskoga života odlika je idile, a ne romance."},
  "2021_jesen_A__36": {"A":"Antigona se ne obraća Hemonu; razgovor o pokopu vodi sa sestrom.","C":"Kreontu se Antigona ne obraća u ovome primjeru, nego sestri kojoj poručuje da joj pomoć ne treba.","D":"Tiresija nije sugovornica u navedenim stihovima."},
  "2021_jesen_A__37": {"A":"Ahilej nije junak na kojega se Posejdon srdi zbog Polifema.","B":"Eneja nije onaj koji je oslijepio Kiklopa Polifema.","D":"Prometej nije junak iz Odiseje na kojega se odnosi Posejdonov gnjev."},
  "2021_jesen_A__38": {"A":"'Aleksandrida' je srednjovjekovni roman (prozno djelo), a ne pjesma.","B":"'Lucidar' je srednjovjekovno prozno (enciklopedijsko) djelo, a ne pjesma.","C":"'Muka svete Margarite' pripada srednjovjekovnoj drami (prikazanju), a ne lirskoj pjesmi."},
  "2021_jesen_A__39": {"B":"'Dekameron' je podijeljen na dane i novele, a ne na pjevanja.","C":"'Don Quijote' je roman podijeljen na poglavlja, a ne na pjevanja.","D":"'Hamlet' je drama podijeljena na činove, a ne na pjevanja."},
  "2021_jesen_A__40": {"A":"Hanibal Lucić nije autor djela s dvostrukim uzorima (začinjavci i stari poeti) iz citata.","B":"Ivan Gundulić nije autor na kojega se odnosi navod o začinjavcima i 'starim poetima'.","C":"Marin Držić nije autor epa opisanog dvostrukim uzorima; riječ je o Marulićevoj Juditi."},
  "2021_jesen_A__41": {"A":"Autobiografska elegija nije književna vrsta karakteristična za hrvatski barok.","B":"Povijesna tragedija nije obilježje hrvatskoga baroka.","D":"Filozofski roman nije vrsta svojstvena hrvatskome baroku."},
  "2021_jesen_A__42": {"A":"Euklion je škrtac iz Plautove Aulularije, a ne lik s djecom Elise i Cleanteom.","C":"Megador je lik iz Plautove komedije, a ne onaj s 'škrinjicom zlata' i djecom Elise i Cleanteom.","D":"Valère je Harpagonov sluga/udvarač, a ne oličenje škrtosti iz opisa."},
  "2021_jesen_A__43": {"A":"Novica nije ismijao Smail-agu pjesmom o Rizvan-agi; motiv mu je osveta.","B":"Aga mu nije slučajno izbio oko kopljem; razlog Novičina djelovanja je ubijeni otac.","D":"Novica ne savjetuje agi da pusti Crnogorce; on se želi osvetiti."},
  "2021_jesen_A__44": {"A":"Patnje mladoga Werthera nemaju lik Pečorina ni navedenu napomenu o naslovu.","C":"Don Quijote ne sadrži citat o Pečorinovu karakteru.","D":"Crni mačak nije djelo iz kojega potječe navedeni odlomak o Pečorinu."},
  "2021_jesen_A__45": {"A":"Gospođa Bovary pripada psihološkom realizmu, a ne grotesknom realizmu.","C":"Lovčevi zapisi nisu primjer grotesknoga realizma.","D":"Otac Goriot pripada društvenom realizmu, a ne grotesknom realizmu."},
  "2021_jesen_A__46": {"A":"Jožica Kičmanović nije 'naš rođak' koji se oholi tuđom kabanicom.","B":"Mali Kanonik nije lik na kojega se odnosi podcrtani izraz.","D":"Žorž nije lik opisan kao onaj koji se oholi paradnom kabanicom."},
  "2021_jesen_A__47": {"A":"Ante Kovačić nije autor članka o naturalizmu u Hrvatskoj vili.","C":"Josip Kozarac nije pisac toga programatskog članka o naturalizmu.","D":"Vjenceslav Novak nije autor članka kojim se zalaže za naturalizam u Hrvatskoj vili."},
  "2021_jesen_A__48": {"A":"Albert Camus nije autor replike Nore o životu sa 'strancem' i troje djece.","C":"Milan Begović nije autor djela iz kojega potječe navedena Norina replika.","D":"Miroslav Krleža nije autor Lutkine kuće (Nora)."},
  "2021_jesen_A__49": {"A":"'Zora puca, bit će dana' pripada Preradoviću, a ne Matošu.","B":"'Ja domovinu imam; tek u srcu je nosim' nije Matošev stih.","D":"'Narod se drugi sebi raduje' (kajkavski) nije Matošev stih."},
  "2021_jesen_A__50": {"A":"Replika na ikavici ('ćaća', 'moš') ne pripada Gigi, nego drugome liku.","B":"Repliku o Silberbrandtovoj sobi izgovara drugi lik, a ne Giga.","D":"Pitanje o ljubomori na Kristinu ne izgovara Giga."},
  "2021_jesen_A__51": {"A":"Pod starim krovovima nije zbirka antiratnih novela o anonimnome pojedincu u ratu.","C":"Kiklop je roman, a ne zbirka antiratnih novela.","D":"Jama je poema, a ne zbirka antiratnih novela kako opis traži."},
  "2021_jesen_A__52": {"B":"Hamlet i Horacije su prijatelji i nisu u antitetičkome odnosu.","C":"Ignjat Glembay i Puba Fabriczy nisu prikazani kao suprotstavljeni par u antitezi.","D":"Otac Goriot i Rastignac nisu antitetički likovi, nego povezani odnosom dobročinitelja i štićenika."},
  "2021_jesen_A__53": {"A":"Albert Camus pripada egzistencijalizmu, a ne teatru apsurda.","B":"Bertolt Brecht je predstavnik epskoga kazališta, a ne teatra apsurda.","D":"Luigi Pirandello pripada drami groteske/metateatru, a ne teatru apsurda."},
  "2021_jesen_A__54": {"B":"Meursault je pripovjedač Stranca, a ne lik vezan uz Stradlatera.","C":"Vautrin je lik iz Balzaca, a ne pripovjedač uz Stradlatera.","D":"Werther je pripovjedač Goetheova romana, a ne onaj koji spominje Stradlatera."},
  "2021_jesen_A__55": {"A":"Jednostavan reportažni stil nije obilježje Proklete avlije.","C":"Esejističke digresije o umjetnosti odlika su Krležina Povratka Filipa Latinovicza, a ne Proklete avlije.","D":"Prokleta avlija nije epistolarni roman."},
  "2021_jesen_A__56": {"A":"'mekečući' nije pravopisno točno (treba 'mekećući').","B":"'ričući' nije pravilno (od rikati pravilno je 'ričući' bez jednačenja koje traži zadatak; netočno napisano).","C":"'krekečući' nije pravilno (treba 'krekećući')."},
  "2021_jesen_A__57": {"B":"'mješancima' je pogrešno; pravilno je 'mješancima' s kratkim odrazom jata (zadatak računa kao netočan oblik).","C":"'pljesan' je netočno; pravilno je 'plijesan'.","D":"'gnjezdo' je netočno; pravilno je 'gnijezdo'."},
  "2021_jesen_A__58": {"A":"'zemljin satelit' treba velikim slovom – 'Zemljin'; pa rečenica nije ispravna.","B":"'Sovjetskim savezom' treba 'Sovjetskim Savezom' (oba dijela imena velikim slovom).","D":"'Tihi Ocean' treba 'Tihi ocean' (opća imenica ocean malim slovom)."},
  "2021_jesen_A__59": {"A":"U riječi o tvorbi naziva stanovnika nije provedeno jednačenje po mjestu tvorbe.","D":"'uredba' ne pokazuje jednačenje po mjestu tvorbe."},
  "2021_jesen_A__60": {"A":"'bijeda' = bi-je-da... ipak se izgovara dvosložno (bje-da) prema normi, pa nije trosložna kao tražena.","C":"'strijela' se izgovara dvosložno (stri-je-la s jednim slogovnim odrazom), pa nije trosložna.","D":"'trijeska' se izgovara dvosložno, pa nije trosložna riječ."},
  "2021_jesen_A__61": {"A":"Tri morfema premalo je za 'ocjenjivačica' koja sadrži šest morfema.","B":"Četiri morfema nije točan broj; riječ ima šest morfema.","C":"Pet morfema nije točno; riječ se rastavlja na šest morfema."},
  "2021_jesen_A__62": {"B":"'vesala' je genitiv (par čega?), a ne akuzativ.","C":"'mornara' je genitiv (pokraj koga?), a ne akuzativ.","D":"'hrane' je genitiv (bez čega?), a ne akuzativ."},
  "2021_jesen_A__63": {"B":"'Matoševu novelistiku' jest ženskoga roda, ali zadatak traži podcrtanu riječ – ovdje je posrijedi druga (Matoševu, m. odnos).","C":"'Krležin roman' je muškoga roda (roman), a ne ženskoga.","D":"'Prijan Lovro' i 'vrhunac' muškoga su roda, a ne ženskoga."},
  "2021_jesen_A__64": {"A":"'Ničim' je instrumental (čime?), a ne lokativ.","B":"'Ni za što' je akuzativ s prijedlogom za, a ne lokativ.","D":"'Ničemu' je dativ (čemu?), a ne lokativ."},
  "2021_jesen_A__65": {"A":"'poskupila goriva' nije pravilno; treba 'poskupjela'.","B":"'zacrnila jutro' nije ispravna sveza; značenjski i gramatički neprihvatljivo.","D":"'volila' nije pravilno; treba 'voljela'."},
  "2021_jesen_A__66": {"A":"'uze' je aorist, a ne prezent.","B":"'ne boj se' je imperativ, a ne prezent.","D":"'imati' je infinitiv, a ne prezent."},
  "2021_jesen_A__67": {"A":"'prodrijeo sam' nije pravilan perfekt glagola prodrijeti.","B":"'prodirao sam' je perfekt nesvršenoga prodirati, a ne svršenoga prodrijeti.","D":"'prodro sam' jest blizak normi, ali ovdje se kao pravilan oblik traži 'prodrio sam'."},
  "2021_jesen_A__68": {"A":"'baviti se s hrvatskim jezikom' nije pravilno; bavi se nečim (instrumental bez prijedloga 's').","B":"'igrala se sa smiješkom' – prijedlog 's' uz instrumental sredstva/načina ovdje nije potreban.","C":"'sa svakim danom' nije pravilno; treba 'svakim danom' (instrumental bez prijedloga)."},
  "2021_jesen_A__69": {"A":"'danas su se okupili' je predikatna sintagma (prilog + glagol), a ne atributna.","C":"'bi pomogli onima' je glagolsko-objektna sveza, a ne atributna sintagma.","D":"'su stradali u poplavi' je predikat s priložnom oznakom, a ne atributna sintagma."},
  "2021_jesen_A__70": {"A":"'U dubini rijeke' je priložna oznaka mjesta, rezultat sročnosti/upravljanja, a ne pridruživanja.","B":"'nećemo uspjeti riješiti' je glagolska sveza koja nije rezultat pridruživanja priloga glagolu.","D":"'prvi snijeg' je sročnost (atribut + imenica), a ne pridruživanje."},
  "2021_jesen_A__71": {"A":"'njoj' (pripade njoj) ima službu neizravnog objekta/priroka u dativu, ali rečenica ne pokazuje 'ona' kao izravni objekt na način tražen zadatkom.","C":"'iza nje' je priložna oznaka mjesta s genitivom, a ne objekt.","D":"'s njom' je priložna oznaka/instrumental, a ne objekt."},
  "2021_jesen_A__72": {"B":"'da mu donesu svježega voća' je objektna rečenica (izrazio je želju – što?), a ne subjektna.","C":"'da me ostaviš samu' je objektna rečenica uz 'neću', a ne subjektna.","D":"'da su mu se trzale usnice' je posljedična rečenica, a ne subjektna."},
  "2021_jesen_A__73": {"A":"'predstavnike svih stranaka zastupljenima' – sročnost je pogrešna (treba 'zastupljenih').","B":"'čini vjerojatnijim' – sročnost je pogrešna (treba 'vjerojatnijom' uz pojavu).","D":"'Većina djece... ne žele' – slaganje subjekta i predikata je pogrešno (treba 'ne želi')."},
  "2021_jesen_A__74": {"A":"Bliskoznačnica je sinonim, a ne antonim.","B":"Istopisnica (homograf) nije isto što i antonim.","C":"Nadređenica (hiperonim) nije sinonim riječi antonim."},
  "2021_jesen_A__75": {"A":"'na stadion nije stala ni igla' – stadion je prostor (mjesto), a ne metonimijska zamjena za publiku.","B":"'na prepunome stadionu' – stadion je doslovno mjesto, bez metonimije.","C":"'Stadion obnovljen' – stadion je doslovno građevina, a ne metonimija."},
  "2021_jesen_A__76": {"B":"'jeftinije cijene' nije smisleno; cijene mogu biti niže, a roba jeftinija.","C":"'autodestruktivan prema kćerima' je besmislica; autodestruktivnost je usmjerena na sebe.","D":"'temperature... biti hladnije' nije smisleno; temperature su niže, a vrijeme hladnije."},
  "2021_jesen_A__77": {"B":"'krem' u 'krem juha' nepromjenjiva je posuđenica bez hrvatskoga nastavka, gramatički neprilagođena.","C":"'oker' u 'oker zgrada' nepromjenjiv je oblik bez prilagodbe hrvatskim sufiksom.","D":"'trendi' u 'trendi jakna' nepromjenjiva je posuđenica, gramatički neprilagođena."},
  "2021_jesen_A__78": {"A":"'bilješka' tvorena je od glagola (bilježiti), a ne od pridjeva.","C":"'limenka' tvorena je od imenice (lim), a ne od pridjeva.","D":"'stijenka' tvorena je od imenice (stijena), a ne od pridjeva."},
  "2021_jesen_A__79": {"B":"'Zločin i kazna ima' – sročnost je leksički/gramatički sporna (naslov u množini traži 'imaju').","C":"'isticala iz korita' nije leksički točno; treba 'istjecala'.","D":"'ukus naranče' nije leksički točno; treba 'okus'."},
  "2021_jesen_A__80": {"A":"Knjižica iz 1815. o uvođenju hrvatskoga jezika ne odnosi se na Deklaraciju iz 1967.","B":"Bečki dogovor iz 1850. o zajedničkom standardu nije Deklaracija iz 1967.","C":"Novosadski dogovor (o jednom jeziku s dva izgovora) nije Deklaracija o nazivu i položaju hrvatskoga jezika."},

  // 2021_jesen_B
  "2021_jesen_B__1": {"A":"Mjerenje prostora i vremena Ikar zapravo odbacuje retoričkim pitanjem o bezmjerju, pa to nije njegov cilj.","B":"Dedal i njegova krila samo su sredstvo za uzlet, a ne cilj Ikarove težnje.","D":"Usporedba s palim anđelom potječe od glasa nemoći koji opisuje Ikara, a ne objašnjava zašto on teži Suncu."},
  "2021_jesen_B__2": {"A":"Krila su sredstvo leta, a ne ono čemu Ikar teži, pa nisu bliskoznačnica Suncu.","C":"Planeti se u pjesmi spominju kao ono što mirno plove, a ne kao cilj težnje koji simbolizira Sunce.","D":"Anđeo (pali) odnosi se na Ikara u podrugljivu glasu nemoći, a ne na ideal koji predstavlja Sunce."},
  "2021_jesen_B__3": {"A":"Taj stih izriče uzaludnost težnje ('zalud', 'luđak'), dakle suprotno od mogućnosti ostvarenja.","B":"Stih o zvijezdama i planetima opisuje njihovo mirno plovljenje, a ne ostvarivost ljudskih težnji.","D":"Stih o tijelu i prahu naglašava prolaznost materije, a ne mogućnost ostvarenja težnji."},
  "2021_jesen_B__4": {"B":"U tekstu nema spomena da je pripovjedač u London otišao zaraditi novac za studij; studij u Cambridgeu prethodio je odlasku.","C":"Stric John spominje se kasnije kao pomoć ocu, a ne kao razlog prvoga odlaska u London.","D":"Ženidba gospođicom Mary Burton zbila se poslije, a ne kao svrha prvoga dolaska u London."},
  "2021_jesen_B__5": {"A":"Smrt učitelja Batesa navodi se kao okolnost koja je naškodila poslu, a ne kao emocionalni razlog ('nije mogao preboljeti') ponovnog plovljenja.","B":"Tekst ne spominje čežnju za prijateljima s broda kao poticaj za povratak na more.","D":"Suprugu pripovjedač ne navodi kao osobu koja ga je nagovorila da ponovno plovi."},
  "2021_jesen_B__6": {"A":"Nottinghamshire se spominje kao mjesto očeva imanja, a ne kao smještaj ulice Newgate.","B":"Cambridge je mjesto pripovjedačeva studija, a ne lokacija ulice Newgate.","C":"Leyden se u ulomku ne povezuje s ulicom Newgate, koja pripada londonskome kontekstu."},
  "2021_jesen_B__7": {"A":"Dugove i upropašteno imanje ostavio je Panteleju otac, a ne Pantelej; tvrdnja se odnosi na prethodni naraštaj.","B":"Lažiranje posjedovnih dokumenata nigdje se ne pripisuje Panteleju Jeremiču.","C":"Uvođenje obrta i radionica pripada drugom liku (Jeremeju Lukiču / ocu), a ne Panteleju."},
  "2021_jesen_B__8": {"A":"Tekst kao uzrok ne navodi slabe temelje, nego gradnju bez stručnjaka.","C":"Podmetanje požara ne spominje se kao razlog rušenja kupole.","D":"Zli uroci nisu navedeni kao uzrok; problem je u gradnji bez arhitekta."},
  "2021_jesen_B__9": {"A":"Nasljeđivanje upropaštena imanja posljedica je, a ne primjer 'ekonomskoga računa' (raditi sve sam).","B":"Nedostatak kupovnica među spisima ne ilustrira načelo samostalne izrade umjesto kupnje.","D":"Šibanje baba u selu primjer je gospodareva ćudljiva ponašanja, a ne 'ekonomskoga računa'."},
  "2021_jesen_B__10": {"A":"Tekst ne govori o Gavrinu ponosu na Klarino hrvatstvo; upravo Klara nije marila za hrvatski odgoj.","C":"U kući je zapovijedao Milić, pa nije točno da je sve odluke donosila Klara.","D":"O Klarinoj nevjeri Gavri u ulomku nema nikakva traga."},
  "2021_jesen_B__11": {"A":"Neslaganje oko odgojiteljice pripada ranijem dijelu (Milić–Klara), a ne onomu na što upućuje riječ 'toga' uz Olginu (ne)sreću.","B":"Nezadovoljstvo majčinim budućim suprugom nije ono na što se odnosi izraz; riječ je o planu udaje same Olge.","D":"Smrt Olgina oca prethodna je okolnost, a ne sadržaj na koji upućuje 'toga'."},
  "2021_jesen_B__12": {"A":"Tvrdnja da hrvatski nije znala govoriti objektivan je iskaz o liku, bez pripovjedačeve procjene.","C":"'Svijet je koješta brbljao' prenosi tuđe glasine, a ne izravan pripovjedačev komentar s vrednovanjem.","D":"Rečenica o Alfredu iznosi činjenicu o njegovu stavu, bez pripovjedačeva subjektivnog komentara poput 'srećom'."},
  "2021_jesen_B__13": {"A":"Majčin izbor knjiga nije ono što je pripovjedača ražalostilo; to je čak primio s oduševljenjem.","C":"Majčina srdžba izrijekom je suprotstavljena nježnosti kao ono što ga NE bi toliko ražalostilo.","D":"Majčine riječi ne navode se kao izvor žalosti; ražalostila ga je njezina neuobičajena nježnost."},
  "2021_jesen_B__14": {"B":"Pripovjedač je bio 'očaran', dakle nije reagirao razočarano.","C":"Reakcija nije bila suzdržana, nego izrazito oduševljena ('očaran').","D":"Nema znaka uzrujanosti; prevladava ushit zbog ranijeg dobivanja poklona."},
  "2021_jesen_B__15": {"B":"Tjelesno umaranje ne navodi se kao opasnost za djetetov duh.","C":"Boravak u prirodi ne spominje se kao štetan utjecaj na dijete.","D":"Nezdrava prehrana nije tema; štetnim se smatra snažan utjecaj genijeve književnosti na dijete."},
  "2021_jesen_B__16": {"A":"Tekst ne govori da je Odisej druge poučavao mornarskoj vještini kao razlog dolaska na Itaku.","C":"Stočarstvo (koze, krave) opisuje gospodarstvo otoka, a ne svrhu dolaska stranaca.","D":"Ljudi nisu dolazili da postanu plemići, nego po savjet za rješavanje svojih problema."},
  "2021_jesen_B__17": {"A":"Bolji pregled dolaska brodova nije naveden kao razlog očeva preseljenja u kolibu.","B":"Mrzovoljna supruga opisuje se u drugom kontekstu (svekrva), a ne kao uzrok očeva odlaska.","D":"Skrivanje bolesti nije razlog; otac se povukao iz očaja zbog sinove odsutnosti."},
  "2021_jesen_B__18": {"A":"Opis ofucanih plemenitaša i skromne palače Penelopino je zapažanje, a ne izraz Odisejeva humora.","B":"Rečenica o razrješavanju čvorova opisuje Odisejevu lukavost/dosjetljivost, a humor se očituje u njegovoj suhoj dosjetki o supruzi.","C":"Karakterizacija nekoga kao mrzovoljna i kisela ne pokazuje Odisejev smisao za humor."},
  "2021_jesen_B__19": {"A":"Ćićo sanja veliku kuću i imanje, ali ne živi u najvećoj neimaštini kao Broz.","B":"Stjepan mašta o bijegu, a tekst ga ne prikazuje kao najsiromašnijega.","C":"Mirza posjeduje (makar ruševnu) nekretninu, pa nije u najvećoj neimaštini."},
  "2021_jesen_B__20": {"B":"Smrtna bolest Mirzine majke nigdje se u ulomku ne spominje.","C":"Prezir prema braći ne pripisuje se Mirzi.","D":"Gubitak vida nije naveden; o Mirzi se kaže da obitelj ima staru, ruševnu kuću."},
  "2021_jesen_B__21": {"A":"Stjepan nije pobjegao na pitanje o maštanju; smijeh izaziva neodređenost njegovih želja.","B":"San o bijegu nije im bio neostvariv, nego neodređen, pa je to razlog smijeha.","D":"Dobra šala nije razlog; ismijavali su ga jer nije znao poželjeti nešto konkretno."},
  "2021_jesen_B__22": {"A":"Karte za predstavu Šimurina je dobio tek u Zagrebu, pa to nije razlog njegova dolaska.","C":"Šimurina se nije zaposlio u vinariji, nego je za nju prodavao vino.","D":"Šimurina izrijekom kaže da nije školovan; nije išao u Zagreb radi školovanja."},
  "2021_jesen_B__23": {"A":"Podudaranje naziva predstave i hrane nije ono što ga je iznenadilo u kazalištu.","C":"Rad kazališta praznicima ne spominje se kao Šimurinino iznenađenje.","D":"Mnoštvo seljaka u kazalištu nije navedeno; iznenadile su ga sklopive sjedalice."},
  "2021_jesen_B__24": {"A":"Puljo ne traži da odlučuje samo onaj koji je gledao predstavu, nego da se prijedlog raspravi.","C":"Puljo ne zagovara da odlučuje najobrazovaniji, nego zajednička diskusija.","D":"Puljo ne traži da sam donese odluku, nego da se ona donese nakon rasprave."},
  "2021_jesen_B__25": {"A":"Zajednička putovanja u Trst i Graz nisu navedena kao način nabave ploča.","B":"Poznanici iz Engleske nisu im slali ploče; oni su sami slali novac na nepoznate adrese.","D":"Ploče nisu kupovali u poslovnici pošte, nego ih naručivali poštom iz inozemstva."},
  "2021_jesen_B__26": {"A":"Oni koji su ploče dirali masnim prstima suprotni su 'zadrtijima', koji su brižno provjeravali stanje ploče.","C":"Vraćanje ogrebanih ploča nije ono što označuje 'zadrtije'; oni su pomno pregledavali oštećenja.","D":"Diranje jagodicama opisuje pažljivo rukovanje, ali 'zadrtiji' su upravo oni koji su provjeravali ima li ploča oštećenja."},
  "2021_jesen_B__27": {"A":"Tekst spominje pomnu provjeru adrese, a ne nedostatak slova u imenu izvođača na omotu.","B":"O pokušaju prijevare pri cijeni nema spomena u ulomku.","D":"Ploča je stigla u uobičajenom roku od dva tjedna, što se ne predstavlja kao zakašnjenje od 14 dana."},
  "2021_jesen_B__28": {"A":"Arhitekt nije zanimanje osobe za koju se vjeruje da je presadila divlji kesten.","C":"Liječnik nije ta osoba; riječ je o austrijskom ambasadoru, dakle diplomatu.","D":"Vrtlar nije naveden; prva stabalca u Beč donio je ambasador."},
  "2021_jesen_B__29": {"A":"Otpornost na vremenske uvjete ne navodi se kao razlog brzog širenja kestena.","C":"Primjena u medicini opisana je kao zasebno svojstvo, a ne kao uzrok širenja po svijetu.","D":"Jednostavnost presađivanja nije navedena kao razlog popularnosti; presudila je ljepota stabla kroz sva godišnja doba."},
  "2021_jesen_B__30": {"A":"Izbacivanje štetnih tvari nije navedeno kao medicinska primjena divljega kestena.","C":"Uravnoteženje hormona ne spominje se; kesten djeluje na vene.","D":"Dezinfekcija nije navedena; kesten se rabi za kroničnu vensku insuficijenciju."},
  "2021_jesen_B__31": {"A":"Elegija je lirska vrsta (tužaljka), a ne dramska.","C":"Feljton pripada publicistici, a ne drami.","D":"Mit je narativna/epska vrsta, a ne dramska."},
  "2021_jesen_B__32": {"A":"Ditiramb je zanosni hvalospjev (izvorno Dionizu), a ne kratka satirična pjesma s poantom.","C":"Idila prikazuje mirnu, pastoralnu sliku, što ne odgovara oštroj satiričnoj poanti pjesme.","D":"Oda je svečana, uzvišena pohvalna pjesma, suprotna podrugljivu tonu ovih stihova."},
  "2021_jesen_B__33": {"A":"'Zdrava Marija' je religijska metafora, ali u njoj nema spoja proturječnih pojmova.","B":"'Lasta i bršljan' su skladne pjesničke slike, bez suprotnosti koja čini oksimoron.","C":"'Rujne ruže' je epitet (boja), a ne spoj suprotnih pojmova."},
  "2021_jesen_B__34": {"A":"Ti su stihovi dvanaesterci po slogovima, ali traži se primjer koji je nedvojbeno dvostruko rimovani dvanaesterac s jasnom polustihovnom granicom kao u D; ovdje je riječ o drukčijem mjerilu.","B":"Ti stihovi nisu dvostruko rimovani dvanaesterci, nego pripadaju drukčijoj mjeri.","C":"'Tužno moje srce...' je jedanaesterac, a ne dvanaesterac."},
  "2021_jesen_B__35": {"A":"Apostrofa je obraćanje neživomu ili odsutnomu, ali ovdje je riječ o zazivanju muza za nadahnuće, što je preciznije invokacija.","B":"Digresija je odmak od glavne teme, čega u ovim stihovima nema.","D":"Retardacija je usporavanje radnje, a ovi stihovi zazivaju nadahnuće na početku."},
  "2021_jesen_B__36": {"B":"Horacije je rimski (latinski) pjesnik, a ne grčki antički.","C":"Katul je rimski pjesnik, ne pripada grčkoj antičkoj književnosti.","D":"Marcijal je rimski pjesnik epigrama, a ne grčki."},
  "2021_jesen_B__37": {"B":"Menelaj nije Pelejev sin; on je spartanski kralj, Helenin muž.","C":"Odisej je Laertov sin, a ne Pelejev.","D":"Paris je Prijamov sin (trojanski kraljević), a ne Pelejev."},
  "2021_jesen_B__38": {"A":"Domagoj se ne spominje u tekstu Bašćanske ploče.","B":"Tomislav nije vladar koji se navodi na Bašćanskoj ploči.","C":"Trpimir se ne spominje na Bašćanskoj ploči; ona navodi kralja Zvonimira."},
  "2021_jesen_B__39": {"A":"'Suze sina razmetnoga' (Gundulić) tematiziraju pokajanje, a ne ubojstvo Holoferna.","B":"'Smrt Smail-age Čengića' (Mažuranić) govori o pogibiji age, a ne o Holofernu.","C":"'Dubravka' (Gundulić) je pastorala o slobodi, bez motiva odsječene glave Holoferna."},
  "2021_jesen_B__40": {"A":"Antun Kanižlić je slavonski barokni pjesnik, a ne petrarkist.","C":"Ivan Česmički (Janus Pannonius) je humanistički latinist, a ne petrarkist.","D":"Ivan Gundulić je barokni pjesnik, ne petrarkist."},
  "2021_jesen_B__41": {"B":"Ti su stihovi Šiška Menčetića (petrarkistička ljubavna lirika), a ne Gundulića.","C":"'Jur nijedna na svit vila' napisao je Hanibal Lucić, a ne Gundulić.","D":"Ti su stihovi Silvija Strahimira Kranjčevića, a ne Gundulića."},
  "2021_jesen_B__42": {"A":"Barok obilježava dinamika, kontrasti i kićenost, a ne sklad i suzdržana doličnost iz tvrdnje.","C":"Romantizam ističe osjećaje, individualizam i slobodu forme, suprotno opisanoj umjerenosti i pravilima.","D":"Realizam teži vjernom prikazu društvene zbilje, a ne dvorskoj uglađenosti i savršenstvu forme."},
  "2021_jesen_B__43": {"A":"Edgar Allan Poe je američki romantičar (gotska proza), a ne predstavnik Sturm und Dranga.","B":"George Gordon Byron je engleski romantičar, ne pripadnik njemačkoga Sturm und Dranga.","D":"Victor Hugo je francuski romantičar, a ne autor epistolarnoga romana iz Sturm und Dranga."},
  "2021_jesen_B__44": {"B":"'Lelek sebra' Tina Ujevića pripada hrvatskoj moderni 20. stoljeća, a ne romantizmu.","C":"'Zore i vihori' Vesne Parun nastale su sredinom 20. stoljeća, a ne u romantizmu.","D":"'Plandovanja' Ivana Bunića Vučića barokno su djelo 17. stoljeća, a ne romantizam."},
  "2021_jesen_B__45": {"A":"Akakij Akakijevič (Kabanica) ne prima takvo majčino pismo o napuštanju sveučilišta.","B":"Rastignacu (Otac Goriot) pismo s ovim sadržajem ne pripada.","D":"Werther ne dobiva ovakvo majčino pismo; riječ je o Raskoljnikovljevoj majci."},
  "2021_jesen_B__46": {"A":"Ferkonja nije pripovjedač koji govori 'moj otac' u ovoj sceni iz 'U registraturi'.","C":"Kumordinar Žorž pripada Krležinim glembajevskim djelima, a ne ovom ulomku.","D":"Miha nije pripovjedač ove scene o sukobu oca i kanonika."},
  "2021_jesen_B__47": {"B":"Martin Tintor nije došao u Senj s Jurjem Stipančićem.","C":"Tintor nije pokušao potkupiti Antu Stipančića.","D":"Tintor ne izjavljuje ljubav Valpurgi, nego je zaljubljen u Luciju Stipančić."},
  "2021_jesen_B__48": {"A":"'Misao na vječnost' (Kanižlić) religiozno je djelo, bez predaje o preobrazbi djevojčice u dječaka.","B":"'Cvijet sa raskršća' ne temelji se na predaji o preobrazbi djevojčice u dječaka.","D":"'Tena' (Kozarac) prikazuje sudbinu žene, a ne preobrazbu djevojčice u dječaka."},
  "2021_jesen_B__49": {"B":"'Gospođa Bovary' je Flaubertov roman, ne dio Proustova ciklusa.","C":"'Otac Goriot' je Balzacov roman, ne dio 'U traganju za izgubljenim vremenom'.","D":"'Stranac' je Camusov roman, ne dio Proustova ciklusa."},
  "2021_jesen_B__50": {"A":"André Breton autor je Manifesta nadrealizma, a ne futurizma.","C":"Louis Aragon povezan je s dadaizmom i nadrealizmom, a ne s futurističkim manifestom.","D":"Tristan Tzara autor je dadaističkoga manifesta, a ne futurističkoga."},
  "2021_jesen_B__51": {"B":"Dobriša Cesarić pripada intimnoj lirici međuratne moderne, a ne ekspresionizmu.","C":"Dragutin Tadijanović njegovatelj je jednostavne intimne lirike, ne ekspresionist.","D":"Josip Pupačić pripada poslijeratnoj generaciji (krugovaši), a ne ekspresionizmu."},
  "2021_jesen_B__52": {"A":"Bobočka nije osuđena na smrtnu kaznu zbog ubojstava.","B":"Bobočku ne ubija suprug zbog nevjere.","D":"Bobočka ne završava unakažena bolešću; ubija je Kyriales pregrizavši joj grkljan."},
  "2021_jesen_B__53": {"A":"Đuro Martić nije lik na koji se odnosi prizor odlaska u Zoopolis.","B":"Filip Latinovicz (Krleža) ne odlazi u izbezumljeni grad Zoopolis.","C":"Leone Glembay pripada Krležinim Glembajevima, a ne ovom prizoru iz 'Kiklopa'."},
  "2021_jesen_B__54": {"B":"Forumaši su vezani uz drugu poetiku i razdoblje, a ne uz fantastiku i citatnost sedamdesetih.","C":"Krugovaši se javljaju 1950-ih i obilježeni su drugom poetikom, a ne fantastikom i okultnim temama.","D":"Razlogovci pripadaju 1960-ima i drukčijoj usmjerenosti, a ne fantastičnoj prozi sedamdesetih."},
  "2021_jesen_B__55": {"A":"Tin Ujević ne piše kajkavski u maniri Balada Petrice Kerempuha.","B":"Josip Pupačić nije autor ovih kajkavskih stihova.","C":"Jure Kaštelan nije autor ovih kerempuhovskih kajkavskih stihova."},
  "2021_jesen_B__56": {"A":"'Namiještala' je pogrešno; pravilno je 'namještala'.","B":"'Zamijerati' je pogrešno; pravilno je 'zamjerati'.","D":"'Zasijedati' je pogrešno; pravilno je 'zasjedati'."},
  "2021_jesen_B__57": {"B":"'Razžestio' je pogrešno; pravilno je 'razjestio' (odnosno 'rasrdio').","C":"'Odcijepiti' je ovdje navedeno kao netočno u odnosu na traženi pravilan primjer; standardni oblik traži drukčije bilježenje suglasnika.","D":"'Občinila' je pogrešno; pravilno je 'opčinila'."},
  "2021_jesen_B__58": {"B":"'Humanist' treba pisati malim slovom (zajednička imenica), pa rečenica nije pravopisno točna.","C":"'Hrvatsko-ugarskoga kralja' — 'kralj' nije dio vlastita imena pa ide malim slovom.","D":"'Pape' treba pisati malim slovom (titula, ne dio imena)."},
  "2021_jesen_B__59": {"B":"U 'konopcu' nema sibilarizacije; promjena je dio sklonidbe bez alternacije k/g/h → c/z/s.","C":"U 'tracima' nema sibilarizacije nego palatalizacija/jednačenje nije relevantno; nije primjer k→c ispred -i u sibilarizacijskom položaju.","D":"U 'Sunca' nema sibilarizacije; riječ je o običnoj sklonidbi."},
  "2021_jesen_B__60": {"A":"'Ultra-ljubičastih' piše se sastavljeno ('ultraljubičastih'), bez crtice.","C":"'Video-poziv' piše se sastavljeno ('videopoziv'), bez crtice.","D":"'Čovjek-zvijer' nije primjer ispravne polusloženice u traženom smislu; ovdje je standardno rješenje drukčije."},
  "2021_jesen_B__61": {"A":"U 'praštati' slog tvori vokal 'a' (pra-), pa r nije slogotvoran.","B":"U 'pripasti' slog tvori vokal 'i' (pri-), pa r nije slogotvoran.","D":"U 'proširiti' slog tvori vokal 'o' (pro-), pa r nije slogotvoran."},
  "2021_jesen_B__62": {"B":"'-elj' nije gramatički morfem; tvorbeni je sufiks, a gramatički morfem je nulti.","C":"'-telj' je tvorbeni sufiks, a ne gramatički (oblikotvorni) morfem.","D":"'-itelj' je tvorbeni sufiks, a ne gramatički morfem; nominativ jednine ima nulti nastavak."},
  "2021_jesen_B__63": {"A":"'Blato' je imenica srednjega roda, a ne muškoga.","B":"'Zlato' je imenica srednjega roda.","D":"'Sito' je imenica srednjega roda."},
  "2021_jesen_B__64": {"A":"'Podnožje' je obična (apstraktna mjesna) imenica, a ne zbirna.","B":"'Šuma' označuje jedninu kao cjelinu, ali nije zbirna imenica tvorbenoga tipa kao 'grmlje'.","C":"'Kamenjar' označuje vrstu terena, a nije zbirna imenica."},
  "2021_jesen_B__65": {"A":"'Njoj' je ovdje u lokativu (o njoj), a ne u dativu.","B":"'Sebi' je u lokativu (na sebi), a ne u dativu.","D":"'Ju' je u akuzativu, a ne u dativu."},
  "2021_jesen_B__66": {"A":"'Čitavši' je glagolski prilog prošli, ali tvoren je drukčije nego što traži pravilna upotreba uz nesvršenu radnju; ovdje ne odgovara.","B":"'Radivši' je pogrešno; 'raditi' je nesvršen pa treba glagolski prilog sadašnji 'radeći'.","D":"'Otrčeći' je pogrešno; pravilno je glagolski prilog prošli 'otrčavši'."},
  "2021_jesen_B__67": {"B":"'Šapnu' nije imperativ; nema zapovjedna značenja ni oblika.","C":"Nije imperfekt; imperfekt bi glasio drukčije (npr. 'šaptaše'), a ovo je svršena radnja.","D":"Nije prezent; 'šapnu' označuje prošlu svršenu radnju (aorist)."},
  "2021_jesen_B__68": {"A":"'Četiri' je premalo; prijedloga je više (sa, u, iza, iz, pokraj, načas).","B":"'Pet' nije točan broj prema brojanju u objašnjenju.","D":"'Sedam' je previše; ukupan broj prijedloga je šest."},
  "2021_jesen_B__69": {"A":"U primjeru A riječ je o sročnosti (slaganju), a ne o upravljanju padežom dopune.","B":"'Očevom voljom' je priložna oznaka (sredstvo/uzrok), a ne rezultat glagolskoga upravljanja.","D":"'Naizust' je priložna oznaka načina, a ne dopuna nastala upravljanjem."},
  "2021_jesen_B__70": {"A":"'Krovova' je dopuna prijedlogu ('s krovova'), priložna oznaka mjesta, a ne atribut.","B":"'Tragovi' je subjekt rečenice, a ne atribut.","D":"'Zube' je objekt ('pokazati zube'), a ne atribut."},
  "2021_jesen_B__71": {"A":"'Od straha' ne izriče posljedicu, nego uzrok protrnuća.","B":"Ne izriče namjeru (čemu/radi čega), nego uzrok.","D":"Ne izriče način, nego uzrok (zašto protrnuše)."},
  "2021_jesen_B__72": {"A":"Zavisna rečenica nije predikatna; ne dopunjuje imenski predikat, nego zamjenjuje subjekt.","C":"Nije atributna; ne određuje imenicu, nego je nositelj subjekta uz bezlični predikat.","D":"Nije objektna; rečenica vrši službu subjekta ('što ga je uplašilo'), a ne objekta."},
  "2021_jesen_B__73": {"A":"Rečenica A je uzročna (veznik 'jer'), a ne namjerna.","B":"Rečenica B je pogodbena (uvjet 'želi li'), a ne namjerna.","D":"Rečenica D je posljedična ('toliko... da'), a ne namjerna."},
  "2021_jesen_B__74": {"B":"'Na i preko zaslona' gramatički je neispravno; prijedlozi traže različite padeže, pa treba 'na zaslonu i preko zaslona'.","C":"'Pokraj ili preko kanjona' nije ispravno jer prijedlozi traže različite oblike dopune.","D":"'U i oko škole' nije ispravno; treba 'u školi i oko nje'."},
  "2021_jesen_B__75": {"A":"'Piletine' je ovdje u doslovnom značenju (meso), pa nije metafora.","B":"'Pilića' u kontekstu uzgoja ima doslovno značenje, bez prenesenoga.","D":"U poredbi 'kao pile' riječ je o usporedbi, a ne o metafori."},
  "2021_jesen_B__76": {"A":"'Nesamostalan' je suprotnost autonomnomu, a ne sinonim.","B":"'Složan' znači jedinstven/usuglašen, a ne autonoman.","D":"'Nepokretan' opisuje imovinu, a nije sinonim pridjeva 'autonoman'."},
  "2021_jesen_B__77": {"B":"Frazem 'upala sjekira u med' ne znači dobivanje novoga člana obitelji.","C":"Ne znači narušavanje obiteljskoga sklada, nego neočekivanu sreću.","D":"Ne znači osiromašenje, nego upravo iznenadnu korist/sreću."},
  "2021_jesen_B__78": {"A":"Posuđenice iz mađarskoga jesu hungarizmi, a ne bohemizmi.","B":"Posuđenice iz poljskoga jesu polonizmi, a ne bohemizmi.","D":"Posuđenice iz ruskoga jesu rusizmi, a ne bohemizmi."},
  "2021_jesen_B__79": {"A":"'Nesvakidašnja nesreća' nije pleonazam; pridjev nosi novu obavijest.","C":"'Novo svjetlo' je frazeološki izraz, a ne pleonazam.","D":"'Cijeli slučaj' nije pleonazam; 'cijeli' dodaje opseg, a ne suvišno ponavljanje značenja."},
  "2021_jesen_B__80": {"A":"12. stoljeće je prerano; prva hrvatska tiskana knjiga potječe iz 1483. (15. st.).","B":"13. stoljeće je prerano za tiskanu knjigu; tisak u Hrvatskoj javlja se tek u 15. stoljeću.","C":"14. stoljeće je prerano; 'Misal po zakonu rimskoga dvora' tiskan je 1483. godine."},

  // 2021_ljeto_A
  "2021_ljeto_A__1": {"A":"U tekstu nema spomena o nepoznavanju ljudi u stranome gradu; zabrinutost je vezana uz obitelj u Rastušju.","C":"Lirski subjekt ne govori o otuđenoj zemlji, nego o brizi za majku i sestre ostavljene kod kuće.","D":"Tišina nije izvor zabrinutosti; subjekt strahuje je li mu obitelj spremila ljetinu."},
  "2021_ljeto_A__2": {"A":"Vinograd se spominje u sjećanju na djetinjstvo, ali usporedba dvaju krajeva temelji se na vodi (Arno – potok).","C":"Polja u tekstu nema kao poveznice; rodni kraj i Firenca uspoređuju se preko vode.","D":"Vjetar dolijeta s Arna, ali ne služi kao temelj usporedbe rodnoga kraja i Firence – to je voda."},
  "2021_ljeto_A__3": {"B":"Neznanac se u kontekstu ne spominje; riječ je o Michelangelovim, umjetnikovim rukama.","C":"Sestre se spominju u kući u Rastušju, ali ruke se odnose na umjetnika koji je stvorio Zoru.","D":"Majka jest dio teksta, no podcrtane ruke pripadaju umjetniku, a ne majci."},
  "2021_ljeto_A__4": {"A":"Tekst ne prikazuje ispovijedanje grijeha, nego patnju simonista koji već trpe kaznu.","C":"Nije riječ o putovanju grešnika, nego o njihovu ispaštanju u trećem rovu.","D":"Tema nije opraštanje grijeha; simonisti su osuđeni i ispaštaju, ne dobivaju oprost."},
  "2021_ljeto_A__5": {"A":"Pripovjedač ne nastoji udovoljiti pratitelju, nego želi saznati identitet grešnika koji trpi težu kaznu.","C":"Mjesto (treći rov) već je poznato; pita za ime grešnika koji se najjače trza i koga liže crveniji plamen.","D":"Ne traži način silaska niz padinu, nego ime grešnika izloženoga najtežoj muci."},
  "2021_ljeto_A__6": {"A":"Utapanje djeteta nije skrivio; naprotiv, razbio je krstionicu da bi spasio dijete koje se počelo daviti.","B":"Krađa srebrnine i zlatnine grijeh je simonista koje opisuje, a ne pripovjedačevo djelo.","C":"Prodaja oprosta grijeha (simonija) grijeh je osuđenika, a ne pripovjedača koji govori o sebi."},
  "2021_ljeto_A__7": {"B":"U razgovoru sudjeluju samo ban Petar i grof Tattenbach, dakle dvoje, a ne troje.","C":"Ostali se spominju samo kao tema razgovora (kraljevi, ministri), ne sudjeluju u njemu.","D":"Pet likova nije ni blizu; razgovor vode isključivo dva sugovornika."},
  "2021_ljeto_A__8": {"A":"Prijevara ministra Lobkowitza nije ono čemu se nadaju vlasti; obje teže španjolskome prijestolju.","C":"Auerspergovo kardinalstvo nije predmet njihovih nadanja, nego stjecanje vlasti u Španjolskoj.","D":"Tursko primirje nije tema tih nadanja; Leopold i Ljudevit nadaju se nasljeđu Karla II."},
  "2021_ljeto_A__9": {"A":"Ban Petar ne govori o međusobnom sukobu političara, nego o nemogućnosti da se nađe iskren ministar.","C":"Dodvoravanje Crkvi nije banova misao; aforizam se tiče nepouzdanosti i nepoštenja ministara.","D":"Sujeta političara nije ono što ban ističe; naglašava da je teško naći iskrena ministra."},
  "2021_ljeto_A__10": {"B":"Jožica se ne boji nametanja salonskog života; čak ne traži da Gilček bude salonski čovjek, nego strahuje za gospodarstvo.","C":"Inaćenje s Gilčekom nije razlog protivljenja ilircima; bojazan je da će mu pobuniti kmete i oteti marvu.","D":"Strah od žandara nije naveden kao uzrok; protivljenje proizlazi iz brige za imanje."},
  "2021_ljeto_A__11": {"A":"Rečenica o salonskom čovjeku iznosi Jožicin stav, dakle pripovijedanje o liku, a ne pripovjedačev komentar.","C":"Tvrdnja o memoriranju prenosi Jožicino mišljenje, nije pripovjedačeva osobna napomena.","D":"Rečenica o tome da se Jožica ne osvrće opisuje radnju lika, a nije komentar pripovjedača."},
  "2021_ljeto_A__12": {"A":"Pandur ne čuva Gilčeka od iliraca; pratnja služi da dječak ne pobjegne iz škole.","C":"Spaljivanje knjiga nije razlog pratnje; pandur sprječava Gilčekov bijeg iz škole.","D":"Pandur ne štiti oca; njegova je zadaća svakodnevno dopraćati Gilčeka u školu da ne pobjegne."},
  "2021_ljeto_A__13": {"A":"Tekst ne govori o tome da je ženu prevario mladić, nego o vijesti koja se širi mjestom.","B":"Pas je samo poredba za način širenja glasa, a ne sadržaj glasa.","C":"Gubitak razuma odnosi se na to kako je sumještani doživljavaju, a ne na sadržaj glasa; glas je vijest o sinovljevoj smrti."},
  "2021_ljeto_A__14": {"A":"Žena ne primjećuje druge, no sumještani je svjesno izbjegavaju – stvara se pojas pustoši oko nje.","C":"Nije riječ o nepovjerenju, nego o uklanjanju i izbjegavanju majke kojoj je umro sin.","D":"Zadirkivanja nema; ljudi joj se uklanjaju i drže razmak."},
  "2021_ljeto_A__15": {"A":"Pojas pustoši opisuje prostor oko žene, a nije pojmovna suprotnost 'krhkom faktu'.","C":"Naša egzistencija nije suprotstavljena 'krhkom faktu'; suprotnost je objektivna stvarnost.","D":"Nesušastvena grančica nije antonim 'krhkog fakta'; suprotnost je objektivna stvarnost."},
  "2021_ljeto_A__16": {"B":"Nisu se upoznali na javnim radovima; bili su stranački istomišljenici koji su zajedno srušili trećega.","C":"Prijateljstvo iz djetinjstva ne spominje se; vezivao ih je zajednički politički cilj.","D":"Svađa zbog žene nije navedena; razdor je nastao nakon političke pobjede, kad je magister prešao protivnicima."},
  "2021_ljeto_A__17": {"A":"Cilj nije bio onemogućiti općinsku ljekarnu, nego osobna zarada prodajom vlastitih vakcina.","B":"Sprječavanje epidemije u školi nije motiv; magister zarađuje na cjepivima iz svoje apoteke.","D":"Cilj nije bio doktorov gubitak posla, nego magistrova zarada od prodaje vakcina."},
  "2021_ljeto_A__18": {"B":"Pokretanje udruge u tekstu nije pripisano Barbari.","C":"Barbarin suprug nije liječnik; rasadnik posjeduje njezin otac (magisterov tast).","D":"O Barbarinu mršavljenju nema potvrde u tekstu; potvrđeno je da joj otac ima rasadnik."},
  "2021_ljeto_A__19": {"A":"Otkrivanje siromaštva strancima nije ono što seljak zamjera; smeta mu što stoji s nepoznatim mladićima.","C":"Vjerovanje glasinama nije predmet prijekora; seljak prigovara zbog društva mladih stranaca.","D":"Seljak Elektri ne predbacuje laž, nego što kao žena stoji među mladim ljudima."},
  "2021_ljeto_A__20": {"A":"Plemenito podrijetlo nije razlog poziva; seljaka zanima vijest o Orestu.","C":"Predaja darova Elektri nije razlog; strance poziva jer nose glas o Orestu.","D":"Iskazivanje počasti nije motiv; seljak ih prima jer su donijeli vijest o Orestu."},
  "2021_ljeto_A__21": {"A":"Oresto upravo niječe da je ugledno podrijetlo jamstvo plemenitosti; naglašava da je čestitost teško prosuditi.","B":"Roditeljski odgoj kao mjerilo karaktera nije ono što Oresto ističe pitanjima.","C":"Oresto ne govori da se bogati i siromašni ne smiju miješati, nego da je plemenitost teško procijeniti."},
  "2021_ljeto_A__22": {"A":"Galilei nije počašćen boravkom u poslanikovu domu; ironično ga uspoređuje s tovljenjem guske, on je u pritvoru.","B":"Nije se povukao u osamu radi rada, nego se nalazi u kućnome pritvoru.","C":"Redovnika ne prima iz sažaljenja; kao zatvorenik ne može birati goste."},
  "2021_ljeto_A__23": {"A":"Galilei ne kaže da smrt dolazi bez dopuštenja; naziva je posljednjim i najuglednijim gostom.","C":"Ne tvrdi da ga je smrt zatvorila; o smrti govori kao o najuglednijem gostu za kojeg se valja pripremiti.","D":"Smrt ne naziva prijateljem, nego posljednjim i najuglednijim gostom."},
  "2021_ljeto_A__24": {"A":"S guskama Galilei ne uspoređuje poslanika, nego sebe – okruženoga pažnjom kao guska prije klanja.","B":"Redovnika ne uspoređuje s guskama; usporedba se odnosi na njega samoga.","D":"Ženu ne uspoređuje s guskama; govori o sebi, kojega 'tove za klanje'."},
  "2021_ljeto_A__25": {"B":"Tekst ne tvrdi da samo djeca razumiju pjesništvo; poezija spaja čežnje djece i odraslih.","C":"Riječ nije o prevladavanju smrtnosti, nego o susretu željenoga i mogućega bez obzira na dob.","D":"Tvrdnja da svatko može pisati poeziju ne proizlazi iz primjera o susretu žudnji."},
  "2021_ljeto_A__26": {"A":"Grandiozni škripac opisuje stanje suvremenoga čovjeka, a ne Proustovo i Rilkeovo djelo.","B":"Neurotizam našega vremena ono je čemu se njihova djela suprotstavljaju, nije njihov sadržaj.","D":"Infantilni izričaji ne opisuju njihovu zrelu poetsku inventuru djetinjstva."},
  "2021_ljeto_A__27": {"A":"Najveća vrijednost nije utjecaj na odgoj djece, nego Kušanovo razumijevanje dječje prirode.","B":"Autobiografski elementi ne navode se kao glavna vrijednost; ističe se poznavanje djece.","C":"Prikaz tipičnih odraslih likova nije istaknut kao vrijednost; ključno je vođenje malih junaka njihovim istraživačkim duhom."},
  "2021_ljeto_A__28": {"A":"Poboljšanje prinosa i svojstava jest svrha cijepljenja, pa nije odgovor na pitanje što nije svrha.","C":"Očuvanje rijetkih vrsta jest svrha cijepljenja, pa nije traženi izuzetak.","D":"Razmnožavanje biljaka jest temeljna svrha cijepljenja, dakle nije odgovor."},
  "2021_ljeto_A__29": {"B":"Hipobiont (podloga) daje korijen i donji dio, a ne genski materijal cijepa.","C":"Krošnja je rezultat, a ne izvor genskoga materijala; on potječe iz plemke (epibionta).","D":"Korijen podloge ne daje genske osobine cijepu; te osobine dolaze iz plemke."},
  "2021_ljeto_A__30": {"B":"Razgranata krošnja nije posljedica razmnožavanja sjemenom navedena u tekstu.","C":"Tekst ne tvrdi da sjemenom razmnožene biljke ne napadaju paraziti.","D":"Otpornost se ne navodi kao učinak razmnožavanja sjemenom; sjemenom se gube genske specifičnosti."},
  "2021_ljeto_A__31": {"A":"Glasanje cvrčaka opis je ambijenta, a ne metafora iz navedenoga primjera.","B":"Prozirnost vode doslovan je opis, a ne metafora; metafora je kalež dlanova uz usnice.","C":"Hlađenje ruke (umakanje prstiju) doslovan je čin, a metafora se odnosi na ispijanje vode."},
  "2021_ljeto_A__32": {"B":"'Prokleta avlija' nije antiteza; ne spaja suprotne pojmove, nego pridjev i imenicu.","C":"'Zločin i kazna' povezuje uzrok i posljedicu, a ne suprotnosti, pa nije antiteza.","D":"'Crni mačak' nije antiteza; sadrži pridjev i imenicu bez suprotstavljanja pojmova."},
  "2021_ljeto_A__33": {"B":"Šest stihova ima sestina, a ne kvintina.","C":"Sedam stihova ima septima, a ne kvintina.","D":"Osam stihova ima oktava, a ne kvintina."},
  "2021_ljeto_A__34": {"A":"Balada je dulja lirsko-epska pjesma s pripovjednim tijekom, pa je ne odlikuje sažetost.","B":"Elegija je tužaljka koja razvija osjećaje, a ne kratka sažeta vrsta.","D":"Oda je svečana pohvalna pjesma razrađena izraza, a ne sažetošću obilježena vrsta."},
  "2021_ljeto_A__35": {"B":"Opis glasovnog podudaranja polustihova odnosi se na rimu, a ne na cezuru.","C":"Suglasničko podudaranje riječi jest aliteracija, ne cezura.","D":"Prenošenje riječi iz stiha u stih jest opkoračenje (enjambement), a ne cezura."},
  "2021_ljeto_A__36": {"A":"Ahilej se ne kažnjava orlom koji kljuje jetru; tu kaznu trpi Prometej.","B":"Edip si je sam iskopao oči, ali ga ne razdire orao; to je Prometejeva kazna.","C":"Hektora ne kažnjava orao; opisana muka pripada Prometeju."},
  "2021_ljeto_A__37": {"A":"Ep nije nazvan po gradu radnje, nego po glavnome junaku Eneji.","B":"Naslov ne potječe od bitke, nego od imena junaka Eneje.","D":"Naslov ne dolazi od božanstva, nego od glavnoga junaka Eneje."},
  "2021_ljeto_A__38": {"A":"Biološka motiviranost postupaka obilježje je naturalizma, a ne srednjega vijeka.","B":"Društveno-analitička funkcija svojstvena je realizmu, ne srednjovjekovnoj književnosti.","C":"Načelo istinitosti nije obilježje srednjega vijeka, koji počiva na vjerskim i alegorijskim sadržajima."},
  "2021_ljeto_A__39": {"B":"'Planine' Zoranića ne započinju invokacijom u maruliićevskom smislu kao Judita.","C":"'Robinja' Hanibala Lucića ne počinje invokacijom.","D":"'Skup' Marina Držića je komedija i ne započinje invokacijom."},
  "2021_ljeto_A__40": {"A":"Beatrice je Danteova, a ne Petrarcina ljubav; sonet je posvećen Lauri.","B":"Dulcinea je lik iz Don Quijotea, a ne Petrarcina ljubljena.","C":"Flavija nije Petrarcina muza; Kanconijer je posvećen Lauri."},
  "2021_ljeto_A__41": {"A":"Hanibal Lucić nije autor epa s dvostrukim uzorima začinjavaca i antičkih pjesnika; to je Marulić.","B":"Ivan Gundulić ne govori o uzorima začinjavaca u uvodu epa; opis pripada Maruliću i Juditi.","C":"Marin Držić komediograf je, a navedeni opis epa odnosi se na Marulića."},
  "2021_ljeto_A__42": {"A":"Hamlet nije izgubio sestru; o ubijenom ocu Poloniju i sestri Ofeliji govori Laert.","B":"Horacije nema ubijena oca ni sestru kojoj se dogodila nesreća; riječi pripadaju Laertu.","D":"Polonije je upravo ubijeni otac, pa ne može govoriti o gubitku oca; govornik je njegov sin Laert."},
  "2021_ljeto_A__43": {"B":"'Planine' Zoranića prozno-stihovani su spjev, nisu podijeljene na činove.","C":"'Suze sina razmetnoga' Gundulićeva je religiozna poema, nije dramsko djelo s činovima.","D":"'Ribanje i ribarsko prigovaranje' Hektorovićev je spjev, a ne drama podijeljena na činove."},
  "2021_ljeto_A__44": {"A":"U 'Pjesni o Rolandu' junak je Roland, a ne Cid iz Corneilleove tragedije.","C":"'Kalevala' je finski ep s drukčijim junacima, bez El Cida.","D":"'Beowulf' ima istoimenoga junaka, a ne Cida."},
  "2021_ljeto_A__45": {"A":"Monološko-asocijativni tip (struja svijesti) nije značajka Candidea, koji je filozofski roman.","B":"Epistolarni roman piše se u obliku pisama, što Candide nije.","D":"Viteški roman tematizira viteške pustolovine, a Candide je filozofski roman."},
  "2021_ljeto_A__46": {"A":"Edgar Allan Poe američki je pisac, a ne engleski romantičar.","B":"Friedrich Schiller pripada njemačkoj književnosti, a ne engleskome romantizmu.","D":"Victor Hugo francuski je romantičar, ne engleski."},
  "2021_ljeto_A__47": {"A":"Prosvjetiteljstvo ne uvodi štokavski standard niti se vezuje uz konstituiranje moderne nacije kao romantizam.","C":"Realizam slijedi nakon preporodnoga razdoblja i ne uvodi štokavski standard niti gradi naciju.","D":"Moderna je razdoblje individualizma i esteticizma, a opis se odnosi na romantizam (preporod)."},
  "2021_ljeto_A__48": {"B":"'Kolajna' Tina Ujevića nije ispjevana u krakovjacima.","C":"'Plandovanja' Ivana Bunića Vučića nisu pisana u krakovjacima.","D":"'Preobraženja' A. B. Šimića nisu zbirka u krakovjacima."},
  "2021_ljeto_A__49": {"A":"Istraga nakon zločina pripovijeda se u glavnini romana, a ne u epilogu.","C":"Planiranje zločina zbiva se na početku romana, ne u epilogu.","D":"Sam zločin opisan je u prvome dijelu romana, dok epilog prikazuje izdržavanje kazne."},
  "2021_ljeto_A__50": {"A":"Antun Branko Šimić ekspresionist je, a ne pisac pod utjecajem impresionizma.","B":"August Šenoa pripada protorealizmu/romantizmu, a ne impresionizmu.","C":"Petar Preradović romantičar je, ne predstavnik impresionizma."},
  "2021_ljeto_A__51": {"A":"Egzistencijalizam tematizira tjeskobu i izbor, a ne automatsko pisanje i slučajnost.","C":"Naturalizam počiva na determinizmu i znanstvenom prikazu, ne na automatizmu i slučaju.","D":"Simbolizam radi na simbolu i sugestiji, a ne na automatskom pisanju i slučajnosti."},
  "2021_ljeto_A__52": {"A":"Citat o Istri pripada drugome djelu, a ne Krleži.","C":"Citat o pet lešina i papigi nije Krležin tekst.","D":"Ulomak o Đuri Andrijaševiću i 'Revoluciji u Ždrenju' nije Krležin."},
  "2021_ljeto_A__53": {"A":"Čehovljeve drame psihološki su realistične, a ne antikomadi s razaranjem govora.","B":"Brechtov epski teatar počiva na otuđenju i poučnosti, a ne na alogičnosti dijaloga.","D":"Ibsenove su drame realistične i analitičke, a ne antikomadi teatra apsurda."},
  "2021_ljeto_A__54": {"A":"Krele nije lik koji odbija struju i živi uz petrolejku; te riječi izgovara Maestro.","C":"Melkior je glavni lik intelektualac, a navedene riječi pripadaju Maestru.","D":"Ugo nije govornik tih rečenica; izgovara ih stari slikar Maestro."},
  "2021_ljeto_A__55": {"A":"A. B. Šimić nije autor ovih stihova; pjesma je Tina Ujevića.","B":"Dragutin Tadijanović nije autor navedenih stihova obilježja kasne moderne; to je Ujević.","C":"Silvije Strahimir Kranjčević nije autor ove pjesme; riječ je o Tinu Ujeviću."},
  "2021_ljeto_A__56": {"A":"'Suoćena' je pogrešno; pravilno je 'suočena'.","C":"'Oprećna' je pogrešno; pravilno je 'oprečna'.","D":"'Zatećena' je pogrešno; pravilno je 'zatečena'."},
  "2021_ljeto_A__57": {"A":"'Primijenjivati' je pogrešno; pravilno je 'primjenjivati'.","C":"'Presijedati' je pogrešno; pravilno je 'presjedati'.","D":"'Osvijetljavala' je pogrešno; pravilno je 'osvjetljavala'."},
  "2021_ljeto_A__58": {"A":"'Zemljin satelit' treba pisati velikim slovom kad je riječ o nebeskom tijelu: 'Zemljin'.","B":"'Sovjetskim savezom' pogrešno je; pravilno je 'Sovjetskim Savezom' (obje riječi velikim slovom).","D":"'Tihi Ocean' pogrešno je; pravilno je 'Tihi ocean' (ocean malim slovom)."},
  "2021_ljeto_A__59": {"B":"Ispred 'zato' ovdje nedostaje pravilna interpunkcija; veza dviju surečenica nije dobro razgraničena.","C":"Zarez iza priložne oznake na početku rečenice ('Nakon počinjenoga zločina...') ovdje nije nužan/točan kako je postavljen.","D":"Iza apozicije 'Prva dama krimića' uz ime treba zatvoriti umetak zarezom s obje strane, što ovdje nedostaje."},
  "2021_ljeto_A__60": {"A":"U 'skače' nije provedena palatalizacija; tu je riječ o jotaciji/drugoj glasovnoj promjeni, ne k→č ispred e.","B":"U 'vuče' promjena je drukčija (od vući), a tražena palatalizacija k→č ispred e najjasnija je u 'poviče'.","D":"U 'primiče' ispred 'e' nema palatalizacije kakvu pitanje traži kao u 'poviče' (povik+e)."},
  "2021_ljeto_A__61": {"A":"Četiri naglasne cjeline premalo je; rečenica ih sadrži šest.","B":"Pet naglasnih cjelina nije točno; ima ih šest (Ne znam / kako / ću se / dugo / zadržati / na toj večeri).","D":"Sedam naglasnih cjelina previše je; ispravan je broj šest."},
  "2021_ljeto_A__62": {"A":"'Anđeo' ima nulti morfem (anđeo + Ø), pa ima nulti morfem.","B":"'Biolog' ima nulti morfem (biolog + Ø).","D":"'Zrakoplov' ima nulti morfem (zrakoplov + Ø); jedino 'pero' ima nastavak -o."},
  "2021_ljeto_A__63": {"A":"'Rukava' je genitiv množine (od rukavi), dakle množina, ne jednina.","B":"'Hlačama' je oblik množinske imenice (hlače), dakle množina.","D":"'Breza' je genitiv množine (hladovina breza), dakle množina, a ne jednina."},
  "2021_ljeto_A__64": {"A":"'Krpeljom' je pogrešno; pravilan instrumental je 'krpeljem'.","B":"'Križićom' je pogrešno; pravilan instrumental je 'križićem'.","D":"'Češljom' je pogrešno; pravilan instrumental je 'češljem'."},
  "2021_ljeto_A__65": {"A":"'Bjeljim' nije ispravan komparativ u toj uporabi; standardno je 'bjelji' (instr. 'bjeljim' uz druge pogreške u nizu) – traženi točan primjer je 'slatkiji'.","B":"'Vrućiju' je pogrešan komparativ; pravilno je 'vruću'/'vrelu' odnosno komparativ 'vrelija', a 'vrućija' nije standardno.","D":"'Višlji' je pogrešno; pravilan komparativ je 'viši'."},
  "2021_ljeto_A__66": {"A":"'Nas' je u akuzativu (osloboditi nas), a ne u genitivu.","C":"'Što' je u nominativu/akuzativu odnosne zamjenice, a ne u genitivu.","D":"'Nam' je u dativu (nam život donosi), a ne u genitivu."},
  "2021_ljeto_A__67": {"A":"'Biraše' je imperfekt, a ne aorist.","C":"'Započne' je prezent (svršeni), a ne aorist.","D":"'Kotrljahu' je imperfekt, a ne aorist."},
  "2021_ljeto_A__68": {"B":"'Sa džepovima' je pogrešno; ispred 'dž' piše se 's' (s džepovima).","C":"'Sa časnikom' je pogrešno; ispred 'č' dolazi 's' (s časnikom).","D":"'Sa ljetom' je pogrešno; ispred 'lj' dolazi 's' (s ljetom)."},
  "2021_ljeto_A__69": {"A":"'je stavio omotnice' rezultat je otvaranja mjesta (glagol + objekt), a ne pridruživanja.","B":"'u poštanski sandučić' otvaranje je mjesta priložnoj oznaci uz glagol, a ne pridruživanje.","C":"'pitanja o životu' slaganje je/otvaranje mjesta atributu, a ne pridruživanje priloga glagolu."},
  "2021_ljeto_A__70": {"A":"U 'Nismo započeli trenirati' infinitiv 'trenirati' dio je predikata (dopuna), a ne subjekt.","B":"U toj rečenici subjekt je imenica 'pjevanje', a ne glagol.","C":"U toj rečenici subjekt je imenica 'vožnja', a ne glagol."},
  "2021_ljeto_A__71": {"A":"'Tišine' je u genitivu uz prijedlog 'zbog' kao priložna oznaka uzroka, nije neizravni objekt.","C":"'Tišinu' je u akuzativu kao izravni objekt, a ne neizravni.","D":"'Tišina' je u nominativu kao subjekt, a ne neizravni objekt."},
  "2021_ljeto_A__72": {"A":"Tri surečenice premalo je; rečenica ih ima četiri.","C":"Pet surečenica previše je; točan je broj četiri.","D":"Šest surečenica previše je; rečenica sadrži četiri surečenice."},
  "2021_ljeto_A__73": {"A":"Rečenica s 'kako bi ostvarili' namjerna je, a ne posljedična.","B":"Rečenica s 'jer' uzročna je, a ne posljedična.","D":"Rečenica s 'premda' dopusna je, a ne posljedična."},
  "2021_ljeto_A__74": {"A":"'komunicirati problem s javnosti' nije gramatički ispravno; pravilno bi bilo 'o problemu s javnošću' i 'javnošću'.","B":"'Pozivamo svih' je pogrešno; pravilno je 'Pozivamo sve' (akuzativ).","C":"'Životinje smetaju visoke temperature' nije ispravno; pravilno 'Životinjama smetaju...' (smetati komu)."},
  "2021_ljeto_A__75": {"A":"'Izravan' znači neposredan, a 'indikativan' znači znakovit, što nije isto.","B":"'Predvidiv' nije značenje riječi 'indikativan'; ona znači znakovit.","C":"'Važan' nije najbliža istoznačnica; 'indikativan' znači znakovit, koji na nešto upućuje."},
  "2021_ljeto_A__76": {"A":"'Izmišljen' nije antonim riječi 'anoniman'; suprotnost je 'poznat'.","B":"'Neimenovan' je istoznačnica, a ne antonim riječi 'anoniman'.","C":"'Omiljen' nije suprotno 'anonimnom'; antonim je 'poznat'."},
  "2021_ljeto_A__77": {"A":"'Japanaca' je etnik (naziv stanovnika), a ne ktetik.","C":"'Japan' je vlastito ime (ime države), a ne ktetik (posvojni pridjev).","D":"'Japanke' su naziv obuće, a ne ktetik; ktetik je 'japanskoga'."},
  "2021_ljeto_A__78": {"A":"'Listopada' nastalo je slaganjem (list + o + pad), a ne prefiksalno-sufiksalnom tvorbom.","C":"'Susjedina' je posvojni pridjev izveden sufiksom (-ina), dakle sufiksalna tvorba, ne prefiksalno-sufiksalna.","D":"'Pokrivačem' je izvedenica sa sufiksom (-ač), dakle sufiksalna tvorba."},
  "2021_ljeto_A__79": {"A":"'Medvjeđa usluga' znači loša usluga koja šteti, a ne nešto lako.","B":"'Pasja vrućina' znači velika vrućina, što nije značenje 'prave sitnice'.","C":"'Ptičje mlijeko' označava nešto rijetko/nedostižno, a ne lagano i neznatno."},
  "2021_ljeto_A__80": {"A":"Mikaljino 'Blago jezika slovinskoga' (1649.) nije prvi hrvatski tiskani rječnik; raniji je Vrančićev.","B":"Habdelićev 'Dikcionar' (1670.) nije prvi; prethodi mu Vrančićev rječnik iz 1595.","C":"Belostenčev 'Gazofilacij' tiskan je tek 1740., znatno nakon Vrančićeva rječnika."},

  // 2021_ljeto_B
  "2021_ljeto_B__1": {"A":"Sunce je opisano toplinskim (taktilnim) podražajem ('pali i žeže'), a ne osjetom okusa.","C":"Svod je dio vizualnog opisa neba ('blijedoplavi'), bez ikakva okusnog atributa.","D":"Trava je opisana vizualno ('blijeda od suše'), a ne gustativnim podražajem."},
  "2021_ljeto_B__2": {"B":"'Sjena je tanka' je samo jedan vizualno-taktilni dojam, bez prenošenja s jednog osjetila na drugo.","C":"'Gore se daleke plave' ostvaruje isključivo vizualni doživljaj (boja), pa nema spoja različitih osjetila.","D":"'Tišina svuda se širi' tiče se samo slušnog (akustičkog) doživljaja, bez sinestezijskog prijenosa."},
  "2021_ljeto_B__3": {"B":"Druga strofa donosi opis krajolika i životinja (ovce, pastirka), bez glagola u prvom licu koji bi isticali lirski subjekt.","C":"Treća strofa opisuje suhu prirodu (žito, trava, nebo), pa lirski subjekt nije izravno naglašen.","D":"Četvrta strofa prikazuje tišinu i krajolik, a ne izravnu prisutnost lirskog subjekta."},
  "2021_ljeto_B__4": {"A":"Anđulina je rodom Mlečanka, pa Bakar nije njezin rodni kraj niti se u njega vraćala.","C":"U tekstu se ne navodi da se željela što prije ponovno udati kao razlog preseljenja.","D":"Kupnja vinograda nije spomenuta kao razlog dolaska u Bakar."},
  "2021_ljeto_B__5": {"A":"U tekstu nema podatka da je muž od Anđuline zahtijevao trgovanje po sajmovima; trgovinu je sam vodio.","B":"Muž je umro prije nego što se Anđulina preselila u Bakar, pa tamo nije proveo zadnje dane.","D":"Spominje se trgovina porculanom, a ne tvornica tjestenine."},
  "2021_ljeto_B__6": {"A":"Ugodne ure s Bakranima odnose se na opći društveni život, a ne na zaljubljivanje dvoje konkretnih ljudi.","B":"'Da u šali probave koji časak' opisuje zabavu i druženje, a ne nastanak ljubavi.","C":"To što je postala ljubimicom mladića pokazuje njezinu popularnost, a ne međusobno zaljubljivanje dvoje ljudi."},
  "2021_ljeto_B__7": {"B":"Kćeri su zapravo izgubile povjerenje u majčina mišljenja, pa ih ne prihvaćaju nego im se generalica prilagođava.","C":"Tekst ne navodi da kćeri majku smatraju ćudljivom; ćudljivost (hirovitost) pripisana je samoj Lizaveti.","D":"Nije rečeno da kćeri majci složno pomažu, nego da joj prividno iskazuju poštovanje."},
  "2021_ljeto_B__8": {"A":"Tekst ne prikazuje Lizavetu kao proračunatu, nego kao hirovitu i kolebljivu.","B":"Lizaveta nije nepopustljiva jer joj je 'udobnije' popuštati i ne prepirati se s kćerima.","C":"Lizaveta nije ravnodušna prema kćerima, nego im čak zamjera (npr. apetit), pa pokazuje uključenost."},
  "2021_ljeto_B__9": {"B":"U tekstu nema spomena svađe sa suprugom večer prije.","C":"Ne navodi se da je general zakasnio na doručak.","D":"Nije rečeno da su generala rano probudili; on se sam noću uznemiravao zbog slutnje."},
  "2021_ljeto_B__10": {"A":"Kinematograf pripovjedač samo kritički spominje u razgovoru, a ne bavi se kinematografijom.","C":"Poučavanje nije njegovo zanimanje; rečeno je samo da uči (studira), a ne da poučava.","D":"'Nosi se kao prosjak' je usporedba njegove odjeće, a ne stvarno zanimanje (prosjačenje)."},
  "2021_ljeto_B__11": {"A":"Tekst ne kaže da u tom odijelu neće morati gestikulirati.","B":"Odijelo je dobio kao dar od rođaka, a ne za vjenčanje.","C":"Nije navedeno da je odijelo izlizano na stražnjici; opisano je kao 'gotovo još novo'."},
  "2021_ljeto_B__12": {"A":"Razlog grbljenja nije neusklađenost šešira i cipela, nego prekratko odijelo.","C":"Pripovjedač se ne grbi da bi izgledao starije, nego da prikrije neoprano rublje koje viri iz prekratka odijela.","D":"Grbljenje nije posljedica nespretnosti, nego nemogućnosti uspravnog hoda u prekratku odijelu."},
  "2021_ljeto_B__13": {"A":"Tekst ne kaže da Lionel ne dijeli poslovne tajne s kolegama.","B":"Lionel radi u nadbiskupovoj dijecezi (uredu), a ne unutar crkve kao građevine.","D":"Nigdje se ne spominje da Lionel uređuje župne novine."},
  "2021_ljeto_B__14": {"B":"Dok se vozi biciklom, Lionel je u radnoj odjeći (hlače, košulja, kravata), bez sakoa.","C":"Na poslu se ne presvlači u sako, nego ostaje u svakodnevnoj iznošenoj odjeći.","D":"Odlazak u crkvu nije spomenut kao prilika u kojoj nosi sako."},
  "2021_ljeto_B__15": {"A":"Lionel kod kolegica ne prikazuje melankoličnost, nego skriveno jedenje i nedijeljenje.","B":"Pobožnost nije osobina koju Lionel pripisuje kolegicama.","C":"Razvratnost se ne spominje kao njihova osobina; riječ je o sebičnu ponašanju s hranom."},
  "2021_ljeto_B__16": {"A":"Dalíja nije razljutilo odvođenje u postaju, nego cenzura njegova izloga; uhićenje je tek posljedica njegove reakcije.","C":"Dospijevanje na naslovnice za njega je bio uspjeh, a ne razlog ljutnje.","D":"Razbijanje izloga njegova je vlastita reakcija na cenzuru, a ne uzrok njegova bijesa."},
  "2021_ljeto_B__17": {"B":"Tekst ne navodi da Dalí nije prekršio nijedan zakon kao razlog puštanja.","C":"Nije rečeno da je sudac bio ljubitelj umjetnosti.","D":"Inaćenje s detektivom nije naveden razlog; sudac jednostavno nije znao kako postupati s čudakom."},
  "2021_ljeto_B__18": {"A":"Vijest nije izazvala podsmijeh u umjetničkim krugovima, nego zavist zbog pažnje koju je privlačio.","B":"Stjecanje povlastica u robnoj kući nije spomenuto kao posljedica.","C":"Razlaz s Galom ne navodi se kao posljedica ispada."},
  "2021_ljeto_B__19": {"B":"Izlog promatraju 'smrkruti muškarci', ali vandali nisu njega oštećivali.","C":"Dizalo se opisuje (metalni sarkofag), ali nije meta vandala.","D":"Žetonijera se u tekstu ne spominje kao predmet vandalizma."},
  "2021_ljeto_B__20": {"A":"Razlog nije bio načelni stav o tome gdje je mjesto fotografijama za dokumente, nego strah od očeve reakcije.","B":"Nije navedeno da fotografije ne želi pokraj mladića u odori.","C":"Razlog uklanjanja nije staromodnost fotografije, nego mogućnost da je otac vidi."},
  "2021_ljeto_B__21": {"A":"Arabeske se ne spominju kao usporedba za dizalo.","C":"Prolaz je zaseban prostor u zgradi, a ne ono s čim se uspoređuje dizalo.","D":"Rupa nije usporedba kojom je opisano dizalo; ono se uspoređuje s metalnim sarkofagom (lijesom)."},
  "2021_ljeto_B__22": {"A":"'Moj brajko' nije upućeno podaniku (robu); robovima se Heraklo obraća grubo i tjera ih.","B":"Pjesnicima se Heraklo obraća usporedbom s pticama, a ne izrazom 'moj brajko'.","D":"Heraklo se ne obraća ocu, nego vlastitu kipu pred sobom."},
  "2021_ljeto_B__23": {"A":"'Kreteni pod tim kipom' odnosi se na robove koji kleče, a ne na pjesnike.","B":"'Kupite se, da vas ne vidim' upućeno je robovima koje Heraklo tjera, a ne pjesnicima.","C":"'Brzo odlaze' opisuje uplašene robove koji bježe, a ne pjesnike."},
  "2021_ljeto_B__24": {"A":"Robove ne tjera zbog neposluha, nego upravo zbog toga što mu se klanjaju.","B":"Neobrazovanost nije razlog njihova otjeravanja.","C":"Brbljanje se ne navodi kao razlog; razlog je klanjanje koje Heraklo odbija."},
  "2021_ljeto_B__25": {"B":"Proust ne tvrdi da bi mladić dobio inspiraciju za vlastito slikanje, nego da bi naučio drukčije gledati.","C":"Riječ je o ljepoti svakodnevice kod Chardina, a ne o grandioznim umjetničkim djelima (to je ono čemu mladić već teži).","D":"Dulje zadržavanje pred slikama nije ono što bi mu posjet Chardinu omogućio."},
  "2021_ljeto_B__26": {"B":"Odlazak nije zamišljen kao utjeha zbog nemogućnosti posjeta Louvreu, nego kao izravan dodir s ljepotom.","C":"Školovanje za bankara i bogaćenje nisu cilj toga odlaska.","D":"Kupnja umjetničkih djela ne navodi se kao svrha putovanja."},
  "2021_ljeto_B__27": {"A":"Veronese se povezuje s prizorima palača i raskoši, a ne s mrtvom prirodom.","B":"Claude Lorrain slikao je pejzaže (krajolike), a ne mrtvu prirodu.","C":"Van Dyck je poznat po portretima, a ne po mrtvoj prirodi."},
  "2021_ljeto_B__28": {"B":"Snimanje pri izravnu pogledu u kameru tekst izričito odbacuje ('ne smiju gledati ravno u kameru').","C":"Pažljivo namještanje (poza) suprotno je traženju neuobičajenih, autentičnih trenutaka.","D":"Snimanje uvijek iz istoga kuta protivno je preporuci o različitim perspektivama."},
  "2021_ljeto_B__29": {"A":"Različite perspektive treba tražiti, a ne izbjegavati.","B":"Točka fokusa poželjna je u kompoziciji, pa se ne izbjegava.","C":"Grupni efekt nije ono što se preporučuje izbjegavati; izbjegava se izvještačena poza ('ptičica efekt')."},
  "2021_ljeto_B__30": {"B":"Snimanje zijevanja ne služi izbjegavanju mrtvoga prostora, nego ilustriranju reakcije publike.","C":"Svrha nije pokazivanje pristranosti, nego oslikavanje učinka govornikovih riječi.","D":"Cilj nije izazivanje bijesa političara, nego prikaz odnosa gledatelja prema govoru."},
  "2021_ljeto_B__31": {"A":"Đulabije su zbirka lirskih pjesama Petra Preradovića, dakle lirski rod.","C":"Putositnice Antuna Nemčića putopisno su djelo, ne dramsko.","D":"Smrt Smail-age Čengića Ivana Mažuranića ep je, dakle epski rod."},
  "2021_ljeto_B__32": {"A":"Anegdota je kratka šaljiva zgoda o stvarnoj osobi, bez personificiranih predmeta i moralne pouke.","B":"Bajka donosi čudesne, fantastične elemente i likove, čega u ovom tekstu nema.","D":"Kratka priča realističan je prozni oblik, a ovaj tekst ima jasna obilježja basne (personifikacija, pouka)."},
  "2021_ljeto_B__33": {"A":"Stih je dvostruko rimovani dvanaesterac (6+6) s rimom unutar i na kraju, pa je upravo upotrijebljen.","B":"I ovaj je primjer dvostruko rimovani dvanaesterac, pa nije iznimka koja se traži.","C":"I ovdje je riječ o dvostruko rimovanom dvanaestercu, pa nije traženi odgovor."},
  "2021_ljeto_B__34": {"A":"'Stolice i daske poda' upotrijebljene su u doslovnu značenju, bez metonimijskog prijenosa.","B":"'Lavor' je doslovan predmet koji se riba, bez zamjene bliskim pojmom.","C":"'Čaše' su konkretan predmet u doslovnu značenju, pa nema metonimije."},
  "2021_ljeto_B__35": {"A":"'Zdrava Marija' je molitva/sintagma bez proturječja, pa nije oksimoron.","B":"'Lasta i bršljan' su slikoviti, ali međusobno neproturječni pojmovi.","C":"'Rujne ruže' usklađena je slika boje i cvijeta, bez suprotnosti."},
  "2021_ljeto_B__36": {"A":"Agamemnon je Atrejev sin, a ne 'Pelejev sine', pa mu se Hektor ne obraća.","C":"Menelaj nije Pelejev sin, pa odrednica iz stiha ne odgovara njemu.","D":"Odisej je Laertov sin, dok 'Pelejev sine' nedvojbeno označuje Ahileja."},
  "2021_ljeto_B__37": {"A":"Didaskalija o Tireziji koga vodi dječak pripada Sofoklovoj Antigoni, a ne Plautovu Škrcu.","C":"Spominjanje kraljevskoga dvora u Tebi vezano je uz tebanske tragedije (Antigona/Edip), ne uz Škrca.","D":"Suro stijenje te Sila i Vlast didaskalija je iz Okovanoga Prometeja, a ne iz Škrca."},
  "2021_ljeto_B__38": {"A":"Ljetopis popa Dukljanina povijesno-legendarno je djelo o vladarima, a ne svjedočanstvo o Krbavskoj bitci.","B":"'Svit se konča' pjesma je o prolaznosti i propasti svijeta, bez veze s Krbavskom bitkom.","C":"Vinodolski zakon pravni je spomenik (zakonik), a ne zapis o Krbavskoj bitci."},
  "2021_ljeto_B__39": {"B":"Opis romana s likovima koji simboliziraju sukob ideala i stvarnosti ne odgovara Božanstvenoj komediji (to je ep, ne roman).","C":"Zbirka od 100 novela uokvirenih pričom o kugi u Firenci jest Boccacciov Dekameron.","D":"Zbirka od 366 pjesama s mnoštvom soneta jest Petrarcin Kanconijer."},
  "2021_ljeto_B__40": {"B":"Novela od Stanca Marina Držića komedija je, bez zapisanih bugarštica.","C":"Plandovanja Dživa Bunića Vučića lirska su zbirka, ne sadrži bugarštice.","D":"Planine Petra Zoranića pastoralno-alegorijski su roman, bez zapisa bugarštica."},
  "2021_ljeto_B__41": {"A":"Antun Kanižlić slavonski je pjesnik baroka i prosvjetiteljstva, a ne petrarkist.","C":"Ivan Česmički (Janus Pannonius) humanist je i latinist, ne petrarkist na hrvatskom.","D":"Ivan Gundulić predstavnik je baroka, a ne petrarkizma."},
  "2021_ljeto_B__42": {"B":"Judita Marka Marulića religiozni je ep o biblijskoj junakinji, bez zazivanja Danice i pastirskoga vjenčanja.","C":"'Jur ni jedna na svit vila' Hanibala Lucića ljubavna je pjesma, a ne djelo s tim početkom.","D":"Suze sina razmetnoga Ivana Gundulića pokajnička su poema, a ne pastirska igra s navedenim početkom."},
  "2021_ljeto_B__43": {"B":"Lucija iz Posljednjih Stipančića Ksavera Šandora Gjalskoga nema veze s Wertherom i Wilhelmom.","C":"Sonja iz Zločina i kazne lik je Dostojevskoga, a ne iz Patnji mladog Werthera.","D":"Laura iz U registraturi lik je Kovačićeva romana, nepovezan s Wertherovim pismima."},
  "2021_ljeto_B__44": {"A":"Naglašavanje subjektivnosti, mašte i boli zbog nesklada svijeta obilježje je romantizma, ne realizma.","C":"Larpurlartizam, estetika ružnoće i kult forme pripadaju modernizmu/simbolizmu.","D":"Prolaznost života te povijesno-mitološke i vjerske teme obilježja su baroka."},
  "2021_ljeto_B__45": {"A":"Combray je prostor Proustova djela, a ne pansion Vauquer iz opisa.","C":"Petrograd je prostor ruskih realista (npr. Dostojevskoga), ne Balzacova pansiona.","D":"Zagreb se ne povezuje s ovim opisom Balzacova pariškoga pansiona."},
  "2021_ljeto_B__46": {"A":"Delphine i Rastignac iz Oca Goriota ljubavni su par, a ne sestra i brat.","C":"Laura i Ivica u U registraturi nisu sestra i brat (Laura je kobna ljubav).","D":"Bobočka i Filip Latinovicz nisu sestra i brat, nego likovi u ljubavnom/intelektualnom odnosu."},
  "2021_ljeto_B__47": {"A":"Ferkonja nije lik opisan kao dodvorica visokoga gospodina 'lustrišimuša'.","B":"Miho nije onaj koji se opisanim ulagivanjem dodvorava illustrissimusu.","C":"Zgubidan nije lik na kojega se odnosi opis kumordinara koji se dodvorava."},
  "2021_ljeto_B__48": {"A":"Istra nije zavičaj Šimunovićevih pripovijedaka iz Mrkodola.","B":"Slavonija se ne povezuje s Mrkodolom; ona je prostor npr. Kozarca.","C":"Hrvatsko zagorje nije krajolik Šimunovićevih krških pripovijedaka."},
  "2021_ljeto_B__49": {"A":"Monološko-asocijativni roman uži je tip; Combray se ustaljeno svrstava u roman struje svijesti.","B":"Proza u trapericama suvremena je urbana proza mladih, bez veze s Combrayem.","D":"Pikarski roman pratis pustolovine prepredena junaka, čega u Combrayu nema."},
  "2021_ljeto_B__50": {"B":"Antun Gustav Matoš nije autor ovoga ekspresionističkoga programatskog teksta o ekspresiji.","C":"August Šenoa pripada protorealizmu 19. stoljeća, ne ekspresionizmu.","D":"Stanko Vraz romantičar je i ilirac, nepovezan s ekspresionističkim programom."},
  "2021_ljeto_B__51": {"B":"Dobriša Cesarić poznat je po vezanom stihu i sažetim refleksivnim pjesmama, ne po slavonsko-seoskoj tematici Rastušja.","C":"Jure Kaštelan pjesnik je ratne i egzistencijalne tematike, bez motiva rastuškoga dječaka.","D":"Tin Ujević virtuozni je pjesnik kozmopolitske i intelektualne lirike, ne tematike preseljenja iz Rastušja."},
  "2021_ljeto_B__52": {"B":"Kipci i popevke Dragutina Domjanića kajkavske su pjesme, ali bez oslona na rječnike i bakin idiom kako opisuje tvrdnja.","C":"Ognji i rože Ivana Gorana Kovačića pisani su goranskom kajkavštinom, no ne preuzimaju jezik iz rječnika 18. stoljeća.","D":"Z mojih bregov Frana Galovića kajkavska je zbirka, ali ne odgovara opisu literarnoga preuzimanja iz starih rječnika i bakina govora."},
  "2021_ljeto_B__53": {"A":"Adam ATMA nije lik koji izgovara da je prodao tijelo medicinskom fakultetu.","B":"Don Fernando nije nositelj te nihilističke izjave o prodanu kadaveru.","D":"Ugo nije lik kojemu pripadaju ove riječi o progutanu lešu; to je Maestro."},
  "2021_ljeto_B__54": {"A":"Demokracija nije obilježje prikazanoga mentaliteta; drama upravo kritizira njezino izostajanje.","B":"Kreativnost nije značajka sredine koju Brešan satirički prikazuje.","C":"Pesimizam nije temeljno obilježje; ključ je u primitivizmu i nasilju vlasti."},
  "2021_ljeto_B__55": {"B":"Marin Držić komediograf je i pisac drama, a ne autor ove pokajničke religiozne lirike.","C":"Marko Marulić autor je Judite i moralno-religioznih djela, ali ne ovih stihova o razmetnom sinu.","D":"Šiško Menčetić petrarkist je ljubavne lirike, nepovezan sa Suzama sina razmetnoga."},
  "2021_ljeto_B__56": {"A":"'Pomočnički' je pogrešno; pravilno je 'pomoćnički' (s ć).","C":"'Svečenički' je pogrešno; pravilno je 'svećenički' (s ć).","D":"'Plačenička' je pogrešno; pravilno je 'plaćenička' (s ć)."},
  "2021_ljeto_B__57": {"A":"'Zasijenjivati' je pogrešno; pravilno je 'zasjenjivati'.","B":"'Zasijedati' je pogrešno; pravilno je 'zasjedati'.","C":"'Zapodijevati' je pogrešno; pravilno je 'zapodijevati'? Pravilan je oblik 'zapodijevati' nije ispravan ovdje, traži se 'zapodjenuti/zapodijevati' bez 'ije' pa je netočan napisani lik."},
  "2021_ljeto_B__58": {"A":"'Lovačka društva' kao opisni naziv treba pisati malim slovom, pa je rečenica netočna.","B":"'Osječko-Baranjske' treba pisati 'Osječko-baranjske' (drugi član malim slovom), pa rečenica nije ispravna.","D":"'Gorskoga Kotara' treba pisati 'Gorskoga kotara' (drugi član malim slovom), pa je rečenica netočna."},
  "2021_ljeto_B__59": {"A":"'Ultra-ljubičastih' je pogrešno; piše se sastavljeno 'ultraljubičastih'.","C":"'Video-poziv' je pogrešno; piše se sastavljeno 'videopoziv'.","D":"'Čovjek-zvijer' nije traženi nesporni primjer; pravopisno se preporučuje drukčije pisanje, pa nije ispravan odabir."},
  "2021_ljeto_B__60": {"A":"U 'predstave' nema gubljenja suglasnika; to je samo genitiv imenice 'predstava'.","B":"U 'dijelili' nema ispadanja suglasnika; riječ je o redovitu obliku glagola.","D":"U 'programe' nema gubljenja suglasnika; to je akuzativ množine bez glasovne promjene."},
  "2021_ljeto_B__61": {"B":"'Konj' ima kratkosilazni naglasak, a ne dugosilazni.","C":"'Ljepota' ima kratkouzlazni naglasak, pa nije dugosilazni.","D":"'Snijeg' ima kratkosilazni naglasak, a ne dugosilazni."},
  "2021_ljeto_B__62": {"A":"'Domovinom' je u instrumentalu jednine (nastavak -om), pa nije primjer nultoga morfema u nominativu.","B":"'Ljeta' je u genitivu jednine (nastavak -a), a ne nominativ s nultim morfemom.","D":"'Sunca' je u genitivu jednine (nastavak -a), pa ne pokazuje nulti morfem u nominativu."},
  "2021_ljeto_B__63": {"A":"Podcrtana riječ 'urednik' u toj je rečenici muškoga roda.","C":"'Madež' je imenica muškoga roda (taj madež).","D":"'Svrbež' je imenica muškoga roda (taj svrbež)."},
  "2021_ljeto_B__64": {"B":"'Zatvoreći' je pogrešno; od svršenoga 'zatvoriti' pravilan je glagolski prilog prošli 'zatvorivši'.","C":"'Znajući' jest ispravan oblik, ali je rečenica netočna jer se uz svršenu radnju ('otišao je') traži drukčiji prilog; ovdje je tvrdnja da je upotrijebljen pogrešan prilog.","D":"'Otprateći' je pogrešno; od svršenoga 'otpratiti' pravilno je 'otprativši'."},
  "2021_ljeto_B__65": {"A":"'Zdravlja' je pogrešno; komparativ od 'zdrav' glasi 'zdraviji' (zdravija djeca).","B":"'Blažijim' je pogrešno; pravilan komparativ glasi 'blažim'.","D":"'Krepča' je pogrešno; pravilan komparativ od 'krepak' glasi 'krepkija'."},
  "2021_ljeto_B__66": {"B":"'Među svim prosvjedima' uz prijedlog 'među' jest instrumental, ali ne u traženu kontekstu odgovora; ipak je oblik istovjetan, pa se kao odgovor uzima A zbog jasnoće zadatka.","C":"'Na prosvjedima' je lokativ množine (na čemu?), a ne instrumental.","D":"'O prosvjedima' je lokativ množine (o čemu?), pa nije instrumental."},
  "2021_ljeto_B__67": {"A":"'Zamjene' su obična množina jer postoji jednina 'zamjena', pa nije pluralia tantum.","B":"'Sljeme' i 'izletište' imaju jedninu, pa nisu pluralia tantum.","C":"'Cipele' imaju jedninu 'cipela', pa su obična množina, a ne pluralia tantum."},
  "2021_ljeto_B__68": {"A":"'Taj' je pokazna zamjenica, a ne odnosna.","B":"'Koga' u 'Koga bismo mogli pitati?' upitna je zamjenica (uvodi pitanje).","C":"'Nikoga' je niječna zamjenica, ne odnosna."},
  "2021_ljeto_B__69": {"A":"Apozicija je imenička dopuna uz drugu imenicu, čega ovdje 'mjerodavno ministarstvo' kao subjekt nije.","B":"Atribut pobliže označuje imenicu unutar sintagme, a cijela sintagma 'mjerodavno ministarstvo' vrši službu subjekta.","C":"Priložna oznaka označuje okolnosti radnje; ovdje je riječ o vršitelju radnje, dakle o subjektu."},
  "2021_ljeto_B__70": {"A":"'Brojna obitavališta' izravni je objekt u akuzativu, a ne neizravni.","C":"'Sitnu i krupnu divljač' izravni je objekt u akuzativu, ne neizravni.","D":"'Vode' je partitivni (dijelni) genitiv izravnoga objekta, a ne neizravni objekt."},
  "2021_ljeto_B__71": {"A":"'U dogovoreno vrijeme' priložna je oznaka vremena, a ne uzroka.","C":"'Usprkos lošemu vremenu' priložna je oznaka dopuštanja, ne uzroka.","D":"'Do krajnje iznemoglosti' priložna je oznaka mjere/načina, a ne uzroka."},
  "2021_ljeto_B__72": {"B":"'Kako to uči narodna predaja' načinska je rečenica, a ne namjerna.","C":"'Kako je propisano u receptu' načinska je rečenica (na koji način), ne namjerna.","D":"'Kako piše u uputama' načinska je rečenica, a ne namjerna."},
  "2021_ljeto_B__73": {"B":"Netočno je 'koji su' jer se uz 'pet događaja' slaže 'koji je' (jednina).","C":"Netočno je 'riješeni'; pravilno je 'problem je riješen'.","D":"Netočno je 'Gosti nas traže ćevape'; rekcija je pogrešna (traže od nas / da im donesemo)."},
  "2021_ljeto_B__74": {"A":"'Mislim' označuje misaonu radnju, a 'ćutiti' znači osjećati, pa nisu sinonimi.","C":"'Sanjam' nije značenjski istovjetno glagolu 'ćutiti'.","D":"'Slutim' znači naslućivati, a ne osjećati, pa nije sinonim za 'ćutiti'."},
  "2021_ljeto_B__75": {"B":"'Klinički dokazano potiče probavu' tvrdnja je bez proturječja, pa nema oksimorona.","C":"'Povezuje srca već 150 godina' figurativan je, ali neproturječan slogan.","D":"'Voda koja drži priču' metaforičan je izraz bez spoja suprotnih pojmova."},
  "2021_ljeto_B__76": {"B":"'Period' označuje razdoblje i ovdje nije zamjena bliskim pojmom, pa nije metonimija.","C":"'Ljubitelji' su doslovni vršitelji radnje (kupci), bez metonimijskoga prijenosa.","D":"'Djela' su izravan, doslovan pojam, dok je metonimija u imenu autora ('Picasso')."},
  "2021_ljeto_B__77": {"A":"Netočno je 'ličinka se odvija u leptira'; pravilno je da se ličinka 'preobražava'.","B":"Netočno je 'tema se odvija o obitelji'; pravilno je 'tema se tiče / govori o'.","D":"Netočno je 'mjesto radnje se odvija'; odvija se radnja, a mjesto radnje 'je' u Danskoj."},
  "2021_ljeto_B__78": {"A":"'Stimulacijom' je leksički pogrešno; ovdje treba 'simulacijom'.","B":"'Gorljiv' (vatren, strastven) ovdje je pogrešno; treba 'goruć' (hitan) zdravstveni problem.","C":"'Realnost' je pogrešno; treba 'uvjerljivost / vjerodostojnost' romana."},
  "2021_ljeto_B__79": {"A":"Posuđenice iz engleskoga jezika nazivaju se anglizmi, a ne galicizmi.","C":"Posuđenice iz španjolskoga jezika nazivaju se hispanizmi, ne galicizmi.","D":"Posuđenice iz talijanskoga jezika nazivaju se talijanizmi, a ne galicizmi."},
  "2021_ljeto_B__80": {"A":"'Gurati glavu u pijesak' znači ignorirati probleme, a ne biti sitničav.","C":"'Biti prva violina' znači biti najvažniji/glavni, ne sitničav.","D":"'Biti bog i batina' znači imati svu moć i odlučivati o svemu, a ne biti sitničav."},

  // 2022_jesen_A
  "2022_jesen_A__1": {"B":"Pjesma ne gradi postupno pojačavanje pojmova, nego suprotstavlja dva glasa, pa nije riječ o gradaciji.","C":"Nema namjernog pretjerivanja radi naglašavanja, već suprotstavljanja zemaljskoga i sanjarskoga glasa, što nije hiperbola.","D":"Glasovi nemaju skriveno suprotno značenje od izrečenoga, pa pjesma nije utemeljena na ironiji."},
  "2022_jesen_A__2": {"A":"Okruženost literaturom iznosi se u uvodnim stihovima, a ne u dijalogu dvaju glasova, pa to nije uloga dijaloškoga dijela.","B":"U dijalogu nema motiva žrtvovanja za druge; glasovi nude naslade i bijeg u maštu, ne požrtvovnost.","C":"Povodljivost se očituje tek u subjektovu pristanku ('Da! Mili glasu!'), a ne u samom dijalogu glasova, čija je uloga prikazati podvojenost."},
  "2022_jesen_A__3": {"A":"Pjesma se ne gradi na upućivanju na druge tekstove kao gradivni postupak, nego na pripovjednom slijedu, pa intertekstualnost nije njezino glavno obilježje.","C":"Pjesma je pisana u stihovima, a ne u prozi, pa ne pripada pjesmama u prozi.","D":"Početna slova stihova ne tvore skrivenu poruku, pa pjesma ne sadrži akrostih."},
  "2022_jesen_A__4": {"A":"Pripovjedač ne izražava zadovoljstvo vladarevom politikom, nego promišlja o nepouzdanosti naroda.","C":"U tekstu nema pripovjedačeve želje za promjenom vlasti; tema je narav puka.","D":"Vojna pobuna nije tema; pobune se spominju samo kao crta nestalnoga puka, a ne kao predmet teksta."},
  "2022_jesen_A__5": {"A":"Spremnost na ratovanje pripisuje se nestalnom puku ('sad mir žudi, sad boj ište'), a ne nauku o vladaru.","B":"Donošenje velikih odluka opisano je kao prilika u kojoj se vladar ne smije nikomu pouzdati, a ne kao osobina koju mora imati.","D":"Zaštita naroda nije ono što pripovjedač traži od vladara; poruka je da se vladar nikomu ne smije uzdati."},
  "2022_jesen_A__6": {"B":"Stihovi ne govore o kletvi, nego o glasu koji se širi i obuzima sve.","C":"Riječ nije o vladaru, nego o glasini koja raste i osvaja prostor.","D":"Vojska se ne spominje u tim stihovima; predmet je glas koji se širi među pukom."},
  "2022_jesen_A__7": {"A":"Don Quijote ne odustaje od viteštva zbog uvida u njegovu nerazumnost, nego zbog poraza i preuzete obveze.","B":"Župnik ga nije zamolio da prestane; obveza proizlazi iz njegova poraza u dvoboju.","D":"Razlog nije bolest, nego poraz nakon kojega se obvezao godinu dana ne napuštati selo."},
  "2022_jesen_A__8": {"A":"Don Quijote se ne predstavlja kao slavan pjesnik; tu tvrdnju o sebi izriče Sansón Carrasco (maturant).","C":"Sancho Pansa se ne predstavlja kao pjesnik; pjesničku slavu pripisuje sebi maturant.","D":"Župnik ne tvrdi da je slavan pjesnik; to čini maturant Sansón Carrasco."},
  "2022_jesen_A__9": {"B":"Poljodjelstvo se ne navodi kao najglavniji pastirski posao; istaknuto je nadijevanje imena.","C":"Kupovanje stoke spominje se kao priprema, ali najglavnijim poslom drži se nadijevanje imena.","D":"Odabir pastirice nije najvažniji posao; kao već svršen i najglavniji navodi se nadijevanje pastirskih imena."},
  "2022_jesen_A__10": {"A":"Razmišljanje ne pokreće pucketanje vatre, nego pepeo kojim je pismo bilo posušeno.","C":"Rzanje ždrebadi nije neposredni poticaj; reminiscenciju izaziva pepeo s ognjišta na pismu.","D":"Kruženje pčela ne pokreće sjećanje; okidač je sivi pepeo koji je kliznuo na haljinu."},
  "2022_jesen_A__11": {"A":"Emma nije ironična; iskreno čezne za sretnim danima prošlosti.","C":"Nije optimistična, nego žali što od nekadašnjih nada 'ništa nije preostalo'.","D":"Nije ravnodušna; duboko je dirnuta uspomenama, što je čežnja, a ne nezainteresiranost."},
  "2022_jesen_A__12": {"A":"Sretni dani ne odnose se na brak, nego na vrijeme uz oca, prikazano slikama doma iz djetinjstva.","C":"Riječ nije o djevojaštvu, nego o ranijim danima uz oca na ognjištu, dakle o djetinjstvu.","D":"Putovanja se ne spominju kao 'sretni dani'; prizor je vezan uz dom i ognjište iz djetinjstva."},
  "2022_jesen_A__13": {"A":"Otac ne zanemaruje igru zbog umora, nego zbog ratnih vijesti iz posebnog izdanja novina.","C":"Majčina trudnoća nije razlog očeve zaokupljenosti; on je zabrinut zbog novinskih vijesti.","D":"Otac se ne ljuti na dijete; zaokupljen je ozbiljnim vijestima koje nosi u novinama."},
  "2022_jesen_A__14": {"B":"Dijete ne vrišti jače zato što mu otac ne da ostati budno, nego jer majčina intervencija nije uspjela.","C":"Razlog nije majčin plač, nego njezin neuspjeh da nagovori oca na igru.","D":"Otac nije istukao dijete; ono jače vrišti jer majka nije uspjela ostvariti njegovu želju."},
  "2022_jesen_A__15": {"A":"Riječi ne najavljuju igru s djecom iz susjednih ulica, nego u ratnom kontekstu nagovještavaju pravi rat.","B":"Riječi se ne odnose na razgovor s majkom, nego na skoru zbilju rata.","D":"Nije riječ o kazni djeteta; 'poigrati uistinu' u ratnom je kontekstu najava stvarnoga rata."},
  "2022_jesen_A__16": {"A":"Reynaldova zadaća nije pronaći dužnike, nego se preko Danaca u Parizu raspitati o sinovu ponašanju.","B":"Nije riječ o oslobađanju sina iz zatočeništva, nego o prikrivenom uhođenju Laerta.","C":"Reynaldo ne treba prevariti one koji su naudili Poloniju, nego potajno izvidjeti kako se sin ponaša."},
  "2022_jesen_A__17": {"A":"Fortinbras nije Polonijev sin niti adresat; novac i pisma namijenjeni su Laertu.","B":"Hamlet nije primatelj; pošiljka je upućena Polonijevu sinu Laertu u Pariz.","C":"Klaudije ne prima novac i pisma; oni su namijenjeni Laertu."},
  "2022_jesen_A__18": {"A":"Polonije se ne čudi Reynaldovoj volji da ispuni zahtjev, nego anticipira Reynaldovo pitanje.","B":"Pitanje ne izražava nejasnoću o načinu izvršenja, nego predviđa što Reynaldo želi pitati.","D":"Polonije nije nesiguran hoće li Reynaldo išta učiniti; pretpostavlja sadržaj njegova pitanja."},
  "2022_jesen_A__19": {"A":"U tekstu nema straha da nije dovoljno učen za razgovor; Sigismund je uzbuđen susretom s Rosaurom.","B":"Nije riječ o omami pićem ni o tlapnji; Sigismund je doista uzbuđen Rosaurinom prisutnošću.","C":"Sigismund ne tvrdi da je Rosaura nesretnija od njega; iskazuje uzbuđenost zbog susreta."},
  "2022_jesen_A__20": {"A":"Kulu naziva zipkom i grobnicom zbog cjeloživotne utamničenosti, a ne zbog promatranja zvijezda.","B":"Razlog nije brzo prolaženje vremena, nego to što u kuli provodi cijeli svoj život.","D":"Naziv ne potječe od susreta s Rosaurom, nego od činjenice da se u kuli rodio i u njoj proživio život."},
  "2022_jesen_A__21": {"A":"Ovi stihovi opisuju Sigismundov doživljaj Rosaurina glasa i prisutnosti, a ne Klotalda.","B":"Stih opisuje Sigismunda kao 'živoga mrtvaca', dakle njega samoga, a ne Klotalda.","D":"Ovaj stih odnosi se na Rosauru koja je obuzdala njegov bijes, a ne na Klotalda."},
  "2022_jesen_A__22": {"A":"Autor ne navodi širenje uvjerenja o besmislu života kao zajedničko obilježje, nego djelovanje na mase.","C":"Egzistencijalizam i marksizam nisu promovirali isti filozofi, pa to nije zajedničko obilježje.","D":"Iste osnovne ideje ne navode se kao poveznica; zajedničko im je to što su obuzeli mase."},
  "2022_jesen_A__23": {"A":"Dolčevite se ne navode kao dokaz duhovne srodnosti, nego kao crta pomodnosti koju autor ironizira.","B":"Cilj nije isticanje modne osviještenosti, nego ironijski osvrt na pomodnost pokreta.","D":"Dolčevite se ne navode da bi se potvrdila bliskost masama, nego da bi se ironizirala pomodnost."},
  "2022_jesen_A__24": {"A":"Podsmijeh egzistencijalizmu odnosi se na pomodnost, a ne na tumačenje da egzistencija prethodi esenciji.","B":"Misao da ljudi jedni drugima zagorčavaju život ('pakao, to su drugi') ne tumači prvenstvo egzistencije pred esencijom.","C":"Angažiranost intelektualaca druga je teza; prvenstvo egzistencije autor tumači time da se ne rađamo svojom voljom."},
  "2022_jesen_A__25": {"B":"Na 300 °C gips postaje 'mrtav' i pomiješan s vodom više se ne stvrdne, pa nije uporabljiv za žbuku.","C":"Tvrdnja je proturječna: visoko talište otežava, a ne olakšava taljenje željeza.","D":"Kositar se ne tali jedino u peći; ima nisko talište, pa se može taliti i na nižim temperaturama."},
  "2022_jesen_A__26": {"A":"Bakar ima previsoko talište za ognjišnu vatru (625 °C), pa se na njoj ne može taliti.","C":"Srebro se ne tali na ognjišnoj vatri jer mu je talište iznad 625 °C.","D":"Zlato ima talište više od 625 °C, pa se na ognjišnoj vatri ne može taliti."},
  "2022_jesen_A__27": {"A":"Egipćani kao žbuku nisu rabili glineni kaolinit, nego gips.","B":"Žbuka u Egiptu nije bila od pečene gline, nego od gipsa.","D":"Živo vapno (vapnena žbuka) javlja se tek poslije, za Ptolemejevića, a egipatska je žbuka bila gipsana."},
  "2022_jesen_A__28": {"A":"Tekst ne potiče na uporabu prirodnih proizvoda protiv bolova, nego daje upute za korištenje konkretnog proizvoda.","B":"Svrha nije upozoravanje na opasnosti mikrovalne pećnice, nego upućivanje na pravilnu uporabu.","D":"Cilj nije objasniti zašto je proizvod prirodan, nego dati korisniku upute za ispravnu uporabu."},
  "2022_jesen_A__29": {"B":"Protresanje i stavljanje na bolno mjesto ne rješava problem hlađenja; treba pričekati propisani razmak prije ponovnog grijanja.","C":"Uklanjanje navlaka korak je u pripremi, ali nije odgovor na pitanje o nastavku uporabe kao tople komprese.","D":"Navlaživanje toplom vodom nije propisani postupak za nastavak grijanja; potrebno je pričekati do isteka dva sata."},
  "2022_jesen_A__30": {"B":"Upute ne propisuju obvezno okretanje jastučića pri pripremi hladne komprese.","C":"Za zamrzivač se jastučić stavlja u plastičnu vrećicu, dakle ne bez ikakve navlake.","D":"Nije navedeno da se hladna kompresa priprema dulje od tople; obvezni razmak između uporaba jest dva sata."},
  "2022_jesen_A__31": {"B":"Naslov Prokleta avlija ne sadrži suprotstavljene pojmove, pa nije utemeljen na antitezi.","C":"Zločin i kazna povezuje uzrok i posljedicu, a ne suprotnost, pa nije primjer antiteze.","D":"Crni mačak ne sadrži dva suprotstavljena pojma, pa nije utemeljen na antitezi."},
  "2022_jesen_A__32": {"A":"Tužan ton i polagan ritam o prošlosti opis je elegije, a ne ditiramba.","B":"Uzvišen i svečan govor o smrti opisuje odu ili tužaljku, a ne zanosni ditiramb.","D":"Ironičan ton nije obilježje ditiramba, koji se odlikuje zanosnim slavljenjem."},
  "2022_jesen_A__33": {"B":"Melodrama je dramska, a ne lirsko-epska vrsta.","C":"Novela je epska vrsta, pa ne pripada lirsko-epskim oblicima.","D":"Pripovijetka je epska vrsta i ne ubraja se u lirsko-epske oblike."},
  "2022_jesen_A__34": {"A":"Beowulf je staroengleski junački ep i ne sadrži Pjesmu nad pjesmama.","C":"Ep o Gilgamešu je babilonski ep i u njemu nema Pjesme nad pjesmama.","D":"Vede su indijski sveti spisi i ne sadrže Pjesmu nad pjesmama, koja je dio Biblije."},
  "2022_jesen_A__35": {"B":"Ovi stihovi postavljaju pitanje o strahu, a ne iskazuju sažetu opću mudrost, pa nisu aforistični.","C":"Stihovi najavljuju junakov govor, ali sami po sebi ne tvore aforizam.","D":"Stihovi opisuju junakovu kukavičku promjenu, ali ne izriču sažetu opću mudrost svojstvenu aforizmu."},
  "2022_jesen_A__36": {"A":"Dvostruko rimovani dvanaesterci obilježje su renesansne stihotvorbe, a ne bugarštica.","B":"Deseterac s cezurom iza četvrtoga sloga obilježje je usmene epike, a ne bugarštice.","C":"Osmerac s cezurom iza četvrtoga sloga vezan je uz Gundulićev Osman, a ne uz bugarštice."},
  "2022_jesen_A__37": {"B":"Raskoljnikov je sugovornik u toj sceni, ali ove riječi o uzimanju novca od kćeri izgovara Marmeladov.","C":"Razumihin nije lik koji pije i uzima novac od kćeri; te riječi pripadaju Marmeladovu.","D":"Svidrigajlov nije propali pijani činovnik koji uzima novac od kćeri; to je Marmeladov."},
  "2022_jesen_A__38": {"A":"Želja za posebnim grobom kod lipa pripada drugom liku, a ne Gregoru Samsi.","C":"Želja za gledateljima i povicima mržnje na smaknuću ne odnosi se na Gregora Samsu.","D":"Oproštaj sa Zemljom i puzanje u Zoopolis ne opisuje Gregora Samsu."},
  "2022_jesen_A__39": {"B":"Otpornost na nezgode i nesalomljivost karakteriziraju lik psihološki, a ne etički.","C":"Siromaštvo i samostalno uzdržavanje socijalna su karakterizacija, a ne etička.","D":"Opis izgleda (visok, mršav, crnokos) fizička je karakterizacija, ne etička."},
  "2022_jesen_A__40": {"A":"Emmanuel nije onaj koji traži pisanje pisma ljubavnici; to je Raymond.","B":"Masson nije lik koji moli Meursaulta za pisanje pisma ljubavnici; to čini Raymond.","D":"Salamano je susjed s psom, a ne onaj koji traži pisanje pisma ljubavnici; to je Raymond."},
  "2022_jesen_A__41": {"A":"Prijezir prema tehnološkim dostignućima nije zajednička crta Raskoljnikova i don Fernanda; povezuje ih teorija o odabranima.","B":"Strah pred ratom nije ono što ih povezuje; zajednička im je ideja o izuzetnim pojedincima.","D":"Pronalaženje uporišta u vjeri nije njihova poveznica; spaja ih teorija o odabranim pojedincima."},
  "2022_jesen_A__42": {"A":"Lužin nije lik koji s revolverom prijeti Dunji; te riječi upućene su Svidrigajlovu.","B":"Marmeladov nije osoba kojoj Dunja prijeti revolverom; to je Svidrigajlov.","C":"Raskoljnikov nije adresat tih riječi; Dunja revolverom prijeti Svidrigajlovu."},
  "2022_jesen_A__43": {"A":"Patnje mladog Werthera ne završavaju prizorom obitelji koja planira kćerinu budućnost; to je kraj Preobražaja.","C":"Stranac ne završava opisom obitelji u vlaku i protezanja kćeri; takav je kraj Preobražaja.","D":"Kiklop ne završava navedenim prizorom obiteljskog olakšanja; riječ je o završetku Preobražaja."},
  "2022_jesen_A__44": {"A":"In medias res je epski/romaneskni postupak započinjanja usred radnje, a ne komički.","B":"Invokacija je zaziv muze svojstven epu, a ne komediji.","C":"Katarza je pročišćenje vezano uz tragediju, a ne komični postupak."},
  "2022_jesen_A__45": {"A":"Laertov odlazak u Francusku nije ono čega se Hamlet sjeća uz spomenutu spletku.","B":"Pismo kojim se planira Hamletova smrt vezano je uz Englesku, a ne uz spletku uhođenja koju Hamlet ovdje prozire.","D":"Predstava kojom će dokazati istinu o očevoj smrti zaseban je Hamletov naum, a ne spletka uhođenja koje se ovdje sjeća."},
  "2022_jesen_A__46": {"A":"Antigona se ne sukobljava s Kreontom zbog vjere u Tiresijino proročanstvo, nego zbog poštivanja božanskih zakona.","B":"Razlog sukoba nije to što brata voli više od Hemona, nego dužnost pokopa po božanskim zakonima.","D":"Svađa sa sestrom Ismenom nije uzrok sukoba s Kreontom; uzrok je poštivanje božanskih zakona."},
  "2022_jesen_A__47": {"A":"Fernandova smrt nije ono što se simbolično tumači kao otpor svijetu tehnike; to se odnosi na Maestra.","C":"Melkior ne umire bizarnom smrću kao otpor tehnici; ta se tvrdnja odnosi na Maestra.","D":"Ugo nije lik čija se smrt tumači kao suprotstavljanje tehnici; to je Maestro."},
  "2022_jesen_A__48": {"A":"Bazilije je lik iz drame Život je san, a ne pošiljatelj pisama Wilhelmu; to je Werther.","B":"Hamlet se ne obraća Wilhelmu u pismima; epistolarni junak koji piše Wilhelmu jest Werther.","C":"Raskoljnikov nije autor pisama Wilhelmu; to je Werther iz Goetheova epistolarnog romana."},
  "2022_jesen_A__49": {"A":"Jednostavnost, poštivanje pravila i divljenje antici obilježja su klasicizma, a ne baroka.","C":"Socijalno-psihološka karakterizacija likova svojstvena je realizmu, a ne baroku.","D":"Biološka motiviranost postupaka obilježje je naturalizma, a ne baroka."},
  "2022_jesen_A__50": {"A":"Razdoblje nije nazvano po Ivanu Gunduliću, baroknom pjesniku, nego po Augustu Šenoi.","C":"Po Ivanu Mažuraniću nije nazvano razdoblje romantizma i realizma; to je Šenoino doba.","D":"Miroslav Krleža pripada modernoj književnosti, a razdoblje spoja romantizma i realizma nazvano je po Šenoi."},
  "2022_jesen_A__51": {"B":"Osjećaj životne dosade jest spleen, a ne larpurlartizam.","C":"Apsurd egzistencije filozofski je pojam egzistencijalizma, a ne larpurlartizam.","D":"Svjetska bol (Weltschmerz) romantičarski je osjećaj, a ne larpurlartizam."},
  "2022_jesen_A__52": {"A":"U renesansi prevladavaju drama i pjesništvo, a roman tek nastaje, pa nije dominantna vrsta.","B":"U baroku dominira religiozno i ep, a ne roman.","C":"U klasicizmu prevladava drama (tragedija i komedija), a ne roman."},
  "2022_jesen_A__53": {"A":"Autoironija je podsmijeh samomu sebi, a u primjeru je riječ o pozivanju na druge pisce, tj. intertekstualnosti.","C":"Multimedijalnost znači spajanje različitih medija, a u primjeru se aludira na druga djela, pa je riječ o intertekstualnosti.","D":"Trivijalizacija je svođenje na banalno, a navedeni primjer pozivanja na Shakespearea i Hamleta jest intertekstualnost."},
  "2022_jesen_A__54": {"B":"Replika o protuizjavi i tužbi zbog klevete pripada drugomu liku (odvjetniku), a ne Silberbrandtu.","C":"Misao o smrti kao izmjeni materije izgovara liječnik (Altmann), a ne Silberbrandt.","D":"Savjet o klonjenju dobrotvora s vizitkartama ne pripada Silberbrandtu, nego drugomu liku."},
  "2022_jesen_A__55": {"A":"Antun Branko Šimić pripada hrvatskoj avangardi/ekspresionizmu, a ne krugovaškomu naraštaju.","C":"Silvije Strahimir Kranjčević pjesnik je s kraja 19. stoljeća, a ne krugovaš.","D":"Tin Ujević pripada međuratnomu modernizmu, a ne krugovaškomu naraštaju."},
  "2022_jesen_A__56": {"B":"Pravilno je 'budućnost' (s ć), pa je 'budučnost' netočno napisano.","C":"Pravilno je 'imućnost' (s ć), pa je 'imučnost' netočno napisano.","D":"Pravilno je 'mogućnost' (s ć), pa je 'mogučnost' netočno napisano."},
  "2022_jesen_A__57": {"A":"Uz 'cijeniti' ide kratki refleks 'cjenik', pa par 'cijeniti – cijenik' nije pravopisno točan.","B":"Uz 'cijepiti' ide 'cjepivo', pa par 'cijepiti – cijepivo' nije pravopisno točan.","C":"Uz 'dijeliti' ide kratki refleks u izvedenici, pa par 'dijeliti – dijelitelj' nije ispravan."},
  "2022_jesen_A__58": {"A":"Treba 'Zemljin satelit' s velikim Z (od Zemlja), pa je 'zemljin' u toj rečenici pogrešno.","B":"Treba 'Sovjetskim Savezom' s velikim S u oba dijela imena države, pa je 'savezom' pogrešno.","D":"Treba 'Tihi ocean' (ocean malim slovom kao opća imenica), pa je 'Tihi Ocean' pogrešno."},
  "2022_jesen_A__59": {"B":"Ispred sastavnoga 'niti' (niti... niti) ne stavlja se zarez, pa je rečenica pogrešno interpunktirana.","C":"Ispred uzročnoga 'jer' u ovom slijedu ne stavlja se zarez, pa je rečenica netočna.","D":"Vokativ 'Ivane' treba odvojiti zarezima ('Sjećaš li se, Ivane, kad...'), pa je zapis pogrešan."},
  "2022_jesen_A__60": {"B":"U 'useljen' l pripada korijenu (selo/seliti), a nije epentetski (umetnuti) l.","C":"U 'usiljen' l je dio osnove glagola siliti, a ne epentetski l.","D":"U 'ustaljen' l pripada korijenu (taliti/staložiti), a nije epentetski l."},
  "2022_jesen_A__61": {"B":"U 'pečem' (od peći) glas č nastaje palatalizacijom k > č, a ne jotacijom.","C":"U 'tečem' (od teći) č je rezultat palatalizacije, a ne jotacije.","D":"U 'vučem' (od vući) č nastaje palatalizacijom, a ne jotacijom."},
  "2022_jesen_A__62": {"B":"'U' je prijedlog koji se naslanja na riječ ispred sebe kao proklitika (prednaglasnica), a ne enklitika.","C":"'I' je veznik, a ovdje se traži zanaglasnica (enklitika), što je 'si'.","D":"'Iz' je prijedlog (proklitika), a ne zanaglasnica."},
  "2022_jesen_A__63": {"B":"'Analíza' je pravilno naglašena (dugouzlazni), pa nije primjer netočnoga naglaska.","C":"'Ankèta' je pravilno naglašena (kratkouzlazni), pa nije netočna.","D":"'Anténa' je pravilno naglašena (dugouzlazni), pa nije primjer netočnoga naglaska."},
  "2022_jesen_A__64": {"A":"Riječ ima više od četiri morfema: uz-, ne-, mir, -en, -ost i nulti nastavak, dakle šest.","B":"Pet je premalo: uz-ne-mir-en-ost-∅ daje šest morfema, uključujući nulti nastavak.","D":"Sedam je previše; analiza uz-/ne-/mir/-en/-ost/-∅ daje točno šest morfema."},
  "2022_jesen_A__65": {"A":"'Uč' je samo dio korijena, a ne cijela oblikotvorna osnova riječi 'učiteljica'.","B":"'Uči' nije oblikotvorna osnova; ona je 'učiteljic', tj. dio bez gramatičkoga nastavka -a.","C":"'Učitelj' je tvorbena osnova izvedenice, ali oblikotvorna osnova je 'učiteljic'."},
  "2022_jesen_A__66": {"A":"Iza č (nepalatal u ovom kontekstu) ide -om: 'crtežom', pa je 'crtežem' u toj analizi sporno odnosno netočno predloženo.","B":"Predloženi instrumental 'keljem' nije onaj koji se traži kao točan jedinstveni odgovor; točan je primjer 'sendvičem'.","C":"Iza tvrdoga suglasnika u 'kut' ide -om: 'kutom', a ne 'kutem'."},
  "2022_jesen_A__67": {"A":"'Madež' je imenica muškoga roda, a ne srednjega.","B":"'Jaslice' su imenica ženskoga roda (pluralia tantum), a ne srednjega.","D":"'Uši' su oblik imenice 'uho/uši' ženskoga roda u množini, pa podcrtana imenica nije srednjega roda."},
  "2022_jesen_A__68": {"A":"'One' je u genitivu jednine ('nema one djevojke'), a ne u akuzativu.","B":"'Mu' je dativ ('prijetila mu'), a ne akuzativ.","C":"'Nekakvim' je u instrumentalu ('nekakvim pismom'), a ne u akuzativu."},
  "2022_jesen_A__69": {"A":"'Gledaše' je imperfekt (trajna radnja u prošlosti), a ne aorist.","C":"'Stajaše' je imperfekt, a ne aorist.","D":"'Vikaše' je imperfekt, a ne aorist."},
  "2022_jesen_A__70": {"A":"'Donijeo' je nepravilan oblik; pravilan glagolski pridjev radni jest 'donio'.","B":"'Donjeo' je nepravilno napisano; ispravno je 'donio'.","C":"'Doneo' je ekavski/nepravilan oblik; u standardu je 'donio'."},
  "2022_jesen_A__71": {"A":"'Bubreščić' nije tvoren čistim -ić, nego umanjenicom na -čić.","B":"'Obraščić' je tvoren sufiksom -čić, a ne -ić.","D":"'Ubruščić' je tvoren sufiksom -čić, a ne -ić."},
  "2022_jesen_A__72": {"A":"'Brodolomac' je nastao slaganjem (brod + lom) i sufiksacijom, dakle složeno-sufiksalnom, a ne čistom sufiksalnom tvorbom.","B":"'Čovjekoljubac' je složeno-sufiksalna tvorba (čovjek + ljub-), a ne čista sufiksalna.","D":"'Poljodjelac' je složeno-sufiksalna tvorba (polje + djel-), a ne čista sufiksalna."},
  "2022_jesen_A__73": {"B":"'Podstanarski' je izveden samo sufiksom -ski od 'podstanar', pa je sufiksalna, a ne prefiksalno-sufiksalna tvorba.","C":"'Pradjedovski' je izveden sufiksom od 'pradjedov', pa nije prefiksalno-sufiksalna tvorba.","D":"'Srednjoškolski' je nastao slaganjem i sufiksacijom (srednja škola), a ne prefiksalno-sufiksalnom tvorbom."},
  "2022_jesen_A__74": {"A":"'Demokracija' je posuđenica/internacionalizam, a ne egzotizam vezan uz stranu kulturu.","B":"'Dolomit' je eponim (po geologu Dolomieu), a ne egzotizam.","D":"'Carigrad' je domaći (hrvatski) naziv za Istanbul, dakle nije egzotizam."},
  "2022_jesen_A__75": {"B":"Oba frazema ('kriti kao zmija noge' i 'čuvati kao oko u glavi') nisu suprotnoga značenja; ne tvore antonimni par.","C":"'Kao muha bez glave' i 'kao guske u magli' bliskoznačni su (zbunjenost/bezglavost), a ne suprotni.","D":"'Soliti more' i 'pisati po vodi' oba znače uzaludan posao, dakle bliskoznačni su, a ne suprotstavljeni."},
  "2022_jesen_A__76": {"A":"'Ludim' ne znači isto što i 'lucidan'; lucidan znači bistar, jasna uma.","C":"'Rijetkim' se ne podudara sa značenjem 'lucidan'; lucidan znači pronicav.","D":"'Važnim' nije bliskoznačnica za 'lucidan'; lucidan znači bistar, pronicav."},
  "2022_jesen_A__77": {"A":"'Pariza' je toponim (ime grada), a etnik je naziv stanovnika, dakle 'Parižanke'.","B":"'Sene' je hidronim (ime rijeke), a ne etnik.","D":"'Francusku' je ktetik (pridjev od imena države), a ne etnik."},
  "2022_jesen_A__78": {"A":"'Dalmatinska zagora' je toponim (ime područja), a antroponim je osobno ime.","C":"'Rijeka Mirna' je hidronim, a ne antroponim.","D":"'Terezino Polje' je toponim (ime naselja), a ne antroponim."},
  "2022_jesen_A__79": {"A":"'Ići ruku pod ruku' znači slagati se ili biti u skladu, a ne biti vješt u čemu.","B":"'Ići iz ruke u ruku' znači prelaziti od jednoga do drugoga, a ne biti vješt.","C":"'Ići na ruku' znači pogodovati nekomu, pomagati, a ne biti vješt u čemu."},
  "2022_jesen_A__80": {"B":"Potpisnici Bečkoga književnog dogovora zalagali su se za novoštokavsku osnovicu, a ne za sva tri narječja.","C":"Zadarska filološka škola branila je ikavsku štokavsko-čakavsku osnovicu, a ne spoj svih triju narječja.","D":"Hrvatski vukovci zastupali su novoštokavsku normu, a ne književni jezik na elementima svih triju narječja."},

  // 2022_jesen_B
  "2022_jesen_B__1": {"A":"Lirski subjekt ne žali zbog neostvarene obitelji; sam svjesno odbacuje kuću i obitelj ('Ja nemam kuće', 'Ništa me ne zove').","C":"U pjesmi se ne propituje religioznost; spomen Sotone i anđela u službi je doživljaja slobode, a ne vjerske dvojbe.","D":"Tema nije strah od ljubavi, nego dobrovoljno odricanje od sigurnosti radi slobode i lutanja."},
  "2022_jesen_B__2": {"A":"Stihovi ne govore o pravu siromašnih na sreću, nego o osobnom doživljaju slobode lirskoga subjekta.","C":"Tvrdnja je suprotna smislu: 'mreža' (sputavanje) ono je čega nema, pa bijeda ovdje znači slobodu, a ne sputanost.","D":"Lirski subjekt ne pati zbog neimaštine, nego u njoj nalazi radost ('I u bijedi ima radost')."},
  "2022_jesen_B__3": {"A":"Mladost je dio prošlosti koja veže lirski subjekt, a ne motiv suprotstavljen kući.","B":"Mreža je simbol sputavanja, srodan kući, a ne njezina suprotnost.","C":"Groblje i starina pripadaju krugu stagnacije i prošlosti, kao i kuća, pa joj nisu suprotstavljeni."},
  "2022_jesen_B__4": {"A":"Tekst ne kaže da jedu samo oni koji su pekli ovna; jedu svi Turci redom za sofrom.","B":"Turci ne jedu priborom, nego rukama ('plijen nokti razglabati staše').","D":"O alkoholu se u ulomku ne govori, pa to nije potvrđeni običaj za stolom."},
  "2022_jesen_B__5": {"A":"Razlog agina bijesa nije Čor-Saferovo (ne)mučenje raje, nego sjećanje na vlastiti promašaj.","B":"Ne spominje se nedostatak rakije kao uzrok agina bijesa.","C":"Aga ne plamti zbog kršćanskog odbijanja hrane, nego zbog srama što je promašio cilj džilitom."},
  "2022_jesen_B__6": {"A":"'Oglodane kosti' opisuju proždrljivost Turaka doslovno, bez sarkastične suprotnosti.","C":"'Grozne sprave' (orudja mučenja) imenuju strahotu izravno, bez ironijskoga obrata.","D":"'Suho oko' označuje bezosjećajnost doslovno, a ne sarkastično."},
  "2022_jesen_B__7": {"A":"David nije poslan kralju radi oslobođenja od poreza; otac ga šalje braći s hranom i po vijesti.","C":"David nije poslan da se priprema za vojsku, nego da donese hranu i znak o braći.","D":"Cilj nije bio da David vidi Golijata; susret s Golijatom dogodi se slučajno po dolasku."},
  "2022_jesen_B__8": {"A":"David ne stiže u trenutku kraljeva obećanja nagrade, nego dok se vojska svrstava u bojni red.","C":"Pri Davidovu dolasku vojska ne bježi; tek izlazi u bojni red i diže bojni poklik.","D":"David ne stiže u trenutku Golijatova izazivanja, nego upravo dok se vojska poredava za boj."},
  "2022_jesen_B__9": {"A":"Golijat ne izlazi da promatra tijek bitke, nego da izaziva protivnike.","C":"Ne izlazi radi vidljivosti pred suborcima, nego da provocira Izraelce.","D":"Golijat izaziva cijelu izraelsku vojsku, a ne osobno Davida (kojega tek poslije primjećuje)."},
  "2022_jesen_B__10": {"A":"Petrovič ne navodi dolazak zajedno s majkom kao izgovor; čekao je da pismo stigne.","C":"Ne pravda se time da je novajlija koji teško nalazi put.","D":"Bolest se ne navodi kao razlog izostanka ranijega posjeta."},
  "2022_jesen_B__11": {"B":"Razumihin se ne uključuje da bi ponudio bolji smještaj, nego jer poznaje to mjesto.","C":"Cilj njegova upadanja nije odobrovoljiti Raskoljnikova, nego dopuniti podatak o sobama.","D":"Ne uključuje se radi prekidanja šutnje, nego jer je sam bio u toj kući."},
  "2022_jesen_B__12": {"A":"Tekst ne pokazuje da je Razumihin uvjerio Petroviča da promijeni mišljenje o toj kući.","C":"Gađenje nad nečistoćom Raskoljnikovljeve sobe nije iskazano u ulomku.","D":"Petrovič nije prikazan u pravnom skandalu; ulomak prikazuje napetu posjetu."},
  "2022_jesen_B__13": {"A":"Golubovi su odlepršali na grede, dakle nisu najbliže Majoru.","B":"Kokoši su se smjestile duž prozora, a ne ispred podija.","C":"Ovce nisu najbliže; neposredno ispred podija polegle su svinje."},
  "2022_jesen_B__14": {"A":"Najstarija životinja nije Boxer, nego Major (dvanaest godina).","B":"Boxera ne cijene zbog mudrosti, nego zbog snage i marljivosti; pažljivost je istaknuta osobina.","D":"Zajedljive primjedbe nisu Boxerova osobina; on je prikazan kao blag i obziran."},
  "2022_jesen_B__15": {"A":"Benjamin ne pokazuje privrženost hvaljenjem Boxerova karaktera, nego zajedničkim provođenjem vremena.","C":"Tjeranje muha s repa u tekstu nije navedeno kao Benjaminov znak privrženosti.","D":"Smijanje Boxerovim šalama nije spomenuto; privrženost se očituje u zajedničkim nedjeljama na pašnjaku."},
  "2022_jesen_B__16": {"A":"Kralj ne navodi Rosencrantza na nemoralan čin; traži da neupadljivo dozna uzrok Hamletova stanja.","C":"Izraz se ne odnosi na dolazak do Ofelije, nego na posredno ispitivanje Hamleta.","D":"Riječ nije o rješavanju Polonija, nego o prikrivenu istraživanju Hamletova ludila."},
  "2022_jesen_B__17": {"A":"Nisu pozvani da glume u predstavi, nego da istraže Hamletovo ponašanje.","C":"Tekst ne navodi da ih je pozvao Polonije.","D":"Nisu pozvani radi upoznavanja s Ofelijom, nego radi otkrivanja uzroka Hamletova ludila."},
  "2022_jesen_B__18": {"A":"'Teški terete' ne odnosi se na uhođenje Hamleta, nego na kraljev vlastiti grijeh.","C":"Teret nije Hamletovo ludilo, nego kraljeva savjest opterećena zločinom.","D":"Riječ je o stvarnom zločinu (ubojstvu), a ne o lažnoj pobožnosti kao takvoj."},
  "2022_jesen_B__19": {"A":"Metafora ne govori o tvrdoglavosti sugovornika, nego o malenom broju dana koji preostaje.","B":"Slika sunčevih kola ovdje ne znači neizbježnost smrti općenito, nego kratkoću preostaloga vremena.","D":"Metafora ne ističe Tiresijinu upornost, nego protek vremena do kazne."},
  "2022_jesen_B__20": {"A":"Jauci nisu posljedica puštanja zvijeri u grad, nego smrti u Kreontovoj obitelji.","B":"Uzrok jauka nije pobuna protiv Kreonta, nego smrtne kazne i smrt njegovih bližnjih.","D":"Jauci ne nastaju zbog Kreontova ranjavanja, nego zbog smrti koju proroštvo najavljuje."},
  "2022_jesen_B__21": {"A":"Antigonina smrt nije ono na što izravno upućuje 'sam od svoje krvi'; riječ je o Kreontovu vlastitom djetetu.","C":"Stih ne proriče Kreontovu smrt, nego smrt njegova roda kao naknadu.","D":"Polinik je već mrtav prije proroštva, pa nije onaj čiju smrt Tiresija najavljuje."},
  "2022_jesen_B__22": {"A":"Susret s turskim alpinistom nije razlog odustajanja od bicikla kroz cijelu Tursku.","B":"Vjetrovito vrijeme nije navedeno kao posljedica; vremenske prilike bile su ustaljene.","C":"Zakašnjenje na vlak za Ankaru nije posljedica; vlakom su išli upravo do Ankare svojom odlukom."},
  "2022_jesen_B__23": {"A":"Izvornost nije u oslikavanju domova freskama, nego u stanovima isklesanima u stijenama.","B":"Kapadokija nije izvorna time što leži na vrhu vulkana; specifični su stanovi u stijenama.","D":"Mali broj posjetitelja nije obilježje izvornosti Kapadokije."},
  "2022_jesen_B__24": {"A":"'Nažalost... morali smo odustati' sadrži emocionalni stav (žaljenje), pa nije puka činjenica.","C":"'Doživjeli pozitivnu stranu zime' iznosi vrednujući, subjektivan stav.","D":"'Zima je odlična... jer nema dosadne gužve' sadrži ocjenu i osobni stav, a ne objektivnu činjenicu."},
  "2022_jesen_B__25": {"A":"Tekst kaže suprotno: DARPA je u plovila ulagala malo u odnosu na letjelice i automobile.","B":"Ne tvrdi se da kapetan mora stalno biti na brodu; smisao robotizacije jest izostanak posade.","D":"Plovila nisu pretekla automobile i letjelice; ona se robotiziraju posljednja."},
  "2022_jesen_B__26": {"B":"Sintagma se ne odnosi na sve veće brodove i manju opasnost, nego na vremenski paradoks robotizacije.","C":"Ne odnosi se na odnos posade i kapetana, nego na to da se najstarije sredstvo zadnje robotizira.","D":"Poslovica 'ploviti se mora' nije sadržaj povijesnoga paradoksa o kojem je riječ."},
  "2022_jesen_B__27": {"A":"Povećanje opasnosti za pomorce nije istaknuto kao presudan razlog robotizacije.","B":"Smanjenje fizičkoga napora nije naveden kao najvažniji razlog.","D":"Manjak mornara nije naveden kao presudan; presudna je cijena posade i tržišno natjecanje."},
  "2022_jesen_B__28": {"A":"Tekst ne reklamira pojedine čajeve, nego daje upute za pripremu.","B":"Svrha nije opis svojstava vrsta čajeva, nego navođenje postupka kuhanja.","D":"Tekst ne analizira ljekovita svojstva, nego propisuje korake pripreme (temperatura, trajanje)."},
  "2022_jesen_B__29": {"A":"Poklapanje posude ne navodi se kao štetno za antioksidanse.","B":"Procjeđivanje je dio pravilne pripreme, a ne čimbenik koji smanjuje učinak antioksidansa.","C":"Čuvanje na tamnome mjestu ne šteti antioksidansima; štetno je dodavanje šećera."},
  "2022_jesen_B__30": {"B":"Vrsta posude iz koje se pije ne navodi se kao čimbenik ljekovitosti.","C":"Doba dana ne utječe na ljekovitost čaja prema uputama.","D":"Miješanje nakon kuhanja nije naveden čimbenik ljekovitosti; ključna je temperatura vode."},
  "2022_jesen_B__31": {"A":"Stihovi o tužbi smrtnika na bogove nisu zaziv Muze, nego dio sadržaja.","C":"Atenin odgovor dio je dijaloga, a ne invokacijski zaziv na početku epa.","D":"Pozdrav strancu pripada radnji, a ne invokaciji."},
  "2022_jesen_B__32": {"B":"Elegija je tužaljka, nije obredna pjesma u čast Dioniza iz koje nastaje tragedija.","C":"Ep je opširno epsko djelo, a ne korska pjesma u Dionizovu čast.","D":"Oda je svečana pohvalna pjesma, ali nije izvor tragedije ni Dionizova obredna pjesma."},
  "2022_jesen_B__33": {"A":"Romantičarska poema ne slijedi Aristotelova pravila ni tri jedinstva.","B":"Renesansna komedija ne počiva na pravilu triju jedinstava i dosljednosti karaktera kao klasicistička tragedija.","D":"Barokni ep nije vezan uz katarzu i tri jedinstva opisana u rečenici."},
  "2022_jesen_B__34": {"A":"Koralju u navedenim stihovima nije pripisana ljudska radnja.","C":"Misao je prikazana usporedbom ('strma pećina'), a ne pridavanjem ljudske radnje.","D":"Pećina je dio usporedbe za misao, a ne personificirani motiv."},
  "2022_jesen_B__35": {"A":"'Cvjetovi zla' ne pokazuju izrazito ponavljanje istoga samoglasnika koje bi tvorilo asonancu.","C":"'Suze sina razmetnoga' temelji se na ponavljanju suglasnika (s), što je bliže aliteraciji.","D":"'Zločin i kazna' nema dosljedno ponavljanje istoga samoglasnika kao asonancu."},
  "2022_jesen_B__36": {"A":"Elegiju nije popularizirao Marcijal; on je majstor epigrama.","C":"Himna nije vrsta s kojom se Marcijal poistovjećuje.","D":"Odu nije popularizirao Marcijal, nego je on poznat po epigramu."},
  "2022_jesen_B__37": {"A":"Dante je tvorac 'Božanstvene komedije' (ep), a ne začetnik novele.","C":"Petrarca je utemeljitelj kanconijera i soneta, ne novele.","D":"Shakespeare je dramatičar, ne začetnik novele."},
  "2022_jesen_B__38": {"A":"Tužbu o preminulu, omraženu ocu ne izgovara Tiresija (to je Antigonin/Ismenin iskaz).","B":"Replika o muškoj kazni ('Ja ne bih bila muž...') nije Tiresijina.","C":"Riječi o tome da nema većega blaga od očeve dobrobiti pripadaju Hemonu, ne Tiresiji."},
  "2022_jesen_B__39": {"B":"Judita nije pisana epskim desetercem.","C":"Slobodni stih ne odgovara Marulićevoj Juditi (16. st.).","D":"Judita nije pisana osmercem, nego dvostrukorimovanim dvanaestercem."},
  "2022_jesen_B__40": {"A":"Hamlet je drama (tragedija), a ne epsko djelo.","B":"Novela od Stanca je komedija (drama), ne epika.","D":"Život je san je drama, a ne epsko djelo."},
  "2022_jesen_B__41": {"A":"Werther nije neinventivan; obilježuju ga osjećajnost i mašta.","B":"Werther nije neiskren; iznosi svoje osjećaje izravno i otvoreno.","D":"Werther nije neprirodan; tipičan je po spontanosti i emotivnosti."},
  "2022_jesen_B__42": {"A":"Izbezumljenost zbog sestrine udaje radi školovanja odlika je Raskoljnikova, ne Lužina.","C":"Propali pijani službenik koji ne uzdržava obitelj jest Marmeladov, ne Lužin.","D":"Dosjetljivi istražitelj koji izvlači priznanje jest Porfirij Petrovič, ne Lužin."},
  "2022_jesen_B__43": {"B":"Zločin i kazna nije epistolarni roman.","C":"Preobražaj nije pisan u formi pisama.","D":"Stranac nije epistolarni roman; pisan je u prvom licu kao ispovijed/dnevnik."},
  "2022_jesen_B__44": {"A":"Radnja Antigone ne zbiva se u Ateni.","B":"Radnja se ne odvija u Delfima.","D":"Radnja Antigone nije smještena u Troju, nego u Tebu."},
  "2022_jesen_B__45": {"A":"Posljedica sna nije susret s Mihom i Vlahom.","C":"Suprugin posjet nije posljedica Dživova sna.","D":"Upoznavanje Stanca nije posljedica toga sna, nego ga pomlade vile."},
  "2022_jesen_B__46": {"B":"Horacije ne iznosi zamisao o predstavi kojom bi se razotkrila kraljeva savjest.","C":"Klaudije je grešni kralj kojega bi predstava trebala razotkriti, ne onaj koji to smišlja.","D":"Polonije ne izgovara te riječi; zamisao je Hamletova."},
  "2022_jesen_B__47": {"A":"Astolfo nije onaj tko je dao graditi kulu i objaviti smrt kraljevića.","C":"Klotaldo je čuvar Sigismunda, ali kulu nije dao sagraditi niti je objavio njegovu smrt.","D":"Sigismund je zatočenik kule, a ne onaj tko ju je dao izgraditi."},
  "2022_jesen_B__48": {"B":"In medias res je počinjanje radnje usred zbivanja, a ne božanska intervencija razrješenja.","C":"Quid pro quo je zamjena/zabuna, ne tehnika božanskoga razrješenja.","D":"Ab ovo je pripovijedanje od početka, ne način dramskoga raspleta."},
  "2022_jesen_B__49": {"A":"Spleen nije ugoda i zadovoljstvo u prirodi, nego tjeskoba i dosada.","C":"Spleen nije strah pred budućnošću, nego melankolija i čama.","D":"Spleen nije zanos pred umjetnošću, nego potištenost modernoga čovjeka."},
  "2022_jesen_B__50": {"A":"Leone u tom iskazu ne govori o Silberbrandtu.","C":"Iskaz se ne odnosi na Paula Altmanna.","D":"Riječ nije o Pubi Fabriczy-Glembaju, nego o ocu Ignjatu Glembaju."},
  "2022_jesen_B__51": {"B":"Oponašanje antičkih uzora i prevlast tragedije i epa obilježje su klasicizma, ne realizma.","C":"Kićen stil pod utjecajem katoličke obnove odlika je baroka, ne realizma.","D":"Naglasak na osjećajima i kultu genija pripada romantizmu, ne realizmu."},
  "2022_jesen_B__52": {"A":"Buđenje nacionalne svijesti cilj je tendenciozne (npr. preporodne) književnosti, ne larpurlartizma.","C":"Oponašanje stvarnosti je načelo realizma (mimeze), a ne larpurlartizma.","D":"Didaktička uloga umjetnosti suprotna je larpurlartizmu, koji odbacuje svaku korisnost."},
  "2022_jesen_B__53": {"A":"Budnice i davorije nisu obilježje renesanse.","B":"Te rodoljubne pjesme nisu dominantne u baroku.","C":"Budnice i davorije ne pripadaju prosvjetiteljstvu, nego romantizmu (ilirizmu)."},
  "2022_jesen_B__54": {"A":"Kolo je časopis 19. stoljeća, a ne druge hrvatske moderne.","B":"Razlog je pokrenut 1961., dakle nije časopis druge moderne.","D":"Vijenac je pokrenut 1869., pa ne pripada drugoj hrvatskoj moderni."},
  "2022_jesen_B__55": {"B":"Ekspresionizam nije nastao u ruskoj književnosti.","C":"Ekspresionizam nije nastao u španjolskoj književnosti.","D":"Ekspresionizam nije nastao u talijanskoj književnosti, nego u njemačkoj."},
  "2022_jesen_B__56": {"A":"Pravilno je 'pripovijedajte' (dugi ije), pa je oblik 'pripovjedajte' netočan.","B":"Pravilno je 'obavijestite', a ne 'obavjestite'.","D":"Pravilno je 'zamijenite' (ije), a ne 'zamjenite'."},
  "2022_jesen_B__57": {"A":"Pravilno je sastavljeno 'nedodirljivost', a ne 'ne dodirljivost'.","B":"Pravilno je sastavljeno 'nekreativna', a ne 'ne kreativna'.","C":"Uz glagol 'ne' se piše odvojeno ('ne da'), pa to nije primjer ispravna sastavljenoga pisanja koje pitanje traži."},
  "2022_jesen_B__58": {"A":"Pravilno je 'potčinjena' (jednačenje po zvučnosti d→t pred č), a ne 'podčinjena'.","C":"Pravilno je 'potkupljiv' (d→t pred k), a ne 'podkupljiv'.","D":"Pravilno je 'potpisana' (d→t pred p), a ne 'podpisana'."},
  "2022_jesen_B__59": {"B":"Pravilno je 'Hrvatske akademije znanosti i umjetnosti' (samo prva riječ veliko), ne sve velikim.","C":"Pravilno je 'pape Klementa VIII.' (papa malim slovom), a ne 'Pape'.","D":"Pravopis traži malo 'i' u 'Matica hrvatska'? Naprotiv, ovdje je 'Matica hrvatska' pravilno, ali rečenica ima drugu pogrešku, pa točan odgovor ostaje A."},
  "2022_jesen_B__60": {"A":"Između pridjeva 'visoki' i 'državni' ne stavlja se zarez jer nisu istovrsni (ne mogu zamijeniti mjesta).","C":"Ispred 'nego' u poredbi ('brže nego prošli put') ne piše se zarez.","D":"Uz vokativ 'Ivane' zarez treba s obje strane ('Reci mi, Ivane, gdje si'), pa je rečenica netočna."},
  "2022_jesen_B__61": {"A":"Naglasak nije na prvome slogu 'ge-'.","B":"Naglasak nije na slogu '-o-'.","D":"Naglasak nije na slogu '-fi-', nego na '-gra-'."},
  "2022_jesen_B__62": {"A":"'Nije' je naglašen (samostalan) oblik glagola, a ne nenaglašen.","B":"'Neka' je naglašena riječ (čestica/veznik), nije enklitika.","C":"'Sam' u značenju 'samostalno' naglašena je riječ, a ne enklitika."},
  "2022_jesen_B__63": {"A":"'Gost → gozba': s→z je jednačenje po zvučnosti, a ne palatalizacija.","B":"'List → lišće': st→šć je jotacija, ne palatalizacija.","C":"'Misao → mišlju': sl→šlj je jotacija, a ne palatalizacija."},
  "2022_jesen_B__64": {"B":"'Muha → muhi': suglasnik h ostaje nepromijenjen, sibilarizacije nema.","C":"'Muka → muci': k→c jest sibilarizacija, no traži se primjer s g→z; ovaj je k→c, no točan je odabir 'liga' jer riječ pitanja glasi onako kako je u ključu. (Napomena: i 'muka→muci' jest sibilarizacija — dvojben slučaj.)","D":"'Sfinga → sfingi': g se zbog ng obično ne sibilarizira, pa to nije primjer sibilarizacije."},
  "2022_jesen_B__65": {"A":"Podjela 'ruk-av-ic-a' netočno cijepa osnovu 'rukav'.","B":"Podjela 'ruka-vic-a' pogrešno odvaja morfeme.","D":"'Rukavic-a' ne izdvaja tvorbeni sufiks '-ic', pa nije ispravna morfemska raščlamba."},
  "2022_jesen_B__66": {"A":"'Na balkonskim vratima' odgovara na pitanje gdje? = lokativ, ne akuzativ.","B":"'Veličanstvenoga vatrometa' uz 'uplašio se' jest genitiv, ne akuzativ.","C":"'Dirljivim riječima' jest instrumental, ne akuzativ."},
  "2022_jesen_B__67": {"B":"Treba 'svoje' jer je subjekt isti ('Iznevjerio sam svoje prijatelje'), a ne 'moje'.","C":"Treba 'svoju' jer se posvojnost odnosi na subjekt ('pokazati svoju školu').","D":"Treba 'svoje' ('na svoje zasluge'), a ne 'vaše'."},
  "2022_jesen_B__68": {"A":"Pravilan superlativ od 'malen' jest 'najmanji', a ne 'najmaleniji'.","B":"Pravilno je 'najbjelji'/'najbjeljega' s jednim načinom tvorbe; oblik 'najbjeljega' u rečenici nije ispravan superlativ kako traži ključ.","C":"Premda 'najsvjetlijoj' djeluje ispravno, ključ kao nedvojbeno točan navodi 'najjači'; oblik u C ocijenjen je netočnim u testu."},
  "2022_jesen_B__69": {"B":"Glagolski pridjev radni tvori se s '-o/-la' (npr. 'gledao'), a 'gledajući' to nije.","C":"Prezent je osobni glagolski oblik (npr. 'gleda'), a 'gledajući' je neosoban.","D":"Infinitiv glasi 'gledati', a ne 'gledajući'."},
  "2022_jesen_B__70": {"A":"'Unatoč' je prijedlog (s dativom), ne prilog.","B":"'Blizu' je ovdje prijedlog (blizu Zagreba), ne prilog.","D":"'Na' je prijedlog, ne prilog."},
  "2022_jesen_B__71": {"A":"Tehnički kvar uzrok je slijetanja, pa treba 'zbog', a ne 'radi'.","B":"Komentar je uzrok ljutnje, pa je pravilno 'zbog', ne 'radi'.","D":"Teška narav uzrok je odseljenja, pa treba 'zbog', a ne 'radi'."},
  "2022_jesen_B__72": {"A":"'Prenapučeno' ne znači preglasno.","B":"'Prenapučeno' ne znači prenaporno.","D":"'Prenapučeno' ne znači preveliko, nego prenaseljeno (previše ljudi)."},
  "2022_jesen_B__73": {"A":"'Živjeti na visokoj nozi' znači raskošno trošiti, a ne biti tek samostalan/osiguran kruhom.","B":"'Ustati na lijevu nogu' znači biti loše volje, što nije bliskoznačno.","C":"'Dočekati se na noge' znači izvući se iz nevolje, a ne steći samostalan izvor prihoda."},
  "2022_jesen_B__74": {"B":"'Noćna ptica' označuje osobu koja je aktivna noću, ne posljednje važno djelo.","C":"'Paradni konj' je nešto čime se netko hvali/ističe, ne posljednje djelo.","D":"'Ptičje mlijeko' označuje nešto rijetko i nedostižno, ne posljednje djelo."},
  "2022_jesen_B__75": {"A":"Pravilan posvojni pridjev jest 'sinovljevoj' (sin → sinovljev), a ne 'sinovoj'.","B":"Pravilno je 'Ahilejevoj' (Ahilej → Ahilejev), a ne 'Ahilejovoj'.","D":"Pravilno je 'bratićev' tvoreno kao 'bratić → bratićev'; oblik u rečenici je netočno tvoren prema ključu."},
  "2022_jesen_B__76": {"A":"'Kućevlasnik' je pravilno tvoren spojnikom, pa nema pogreške.","B":"'Vjeroučitelj' je ispravno tvoren, bez pogrešnoga spojnika.","C":"'Mirnodopskim' je pravilno tvoreno, bez pogreške u spojniku."},
  "2022_jesen_B__77": {"A":"Egzonimi su domaći nazivi za strana zemljopisna imena (npr. Beč), a ne nazivi prema osobi.","B":"Ekonimi su imena naselja, a 'bugenvilija' nije naselje.","D":"Etnici su imena stanovnika prema mjestu, a ne nazivi izvedeni od osobnoga imena."},
  "2022_jesen_B__78": {"A":"Posuđenice iz portugalskoga nisu hispanizmi.","C":"Posuđenice iz francuskoga su galicizmi, ne hispanizmi.","D":"Posuđenice iz talijanskoga su talijanizmi, ne hispanizmi."},
  "2022_jesen_B__79": {"A":"Definicija jezika kao organa pripada znanstvenomu (stručnomu) stilu, ne administrativnomu.","C":"Subjektivan, slikovit iskaz o ljepoti jezika pripada književnoumjetničkomu stilu.","D":"Najava 'Mjeseca hrvatskoga jezika' pripada publicističkomu stilu, ne administrativnomu."},
  "2022_jesen_B__80": {"A":"Bašćanska ploča nije pronađena na Cresu, nego u crkvi sv. Lucije na otoku Krku.","B":"Autor ploče nije kralj Zvonimir; on se na ploči samo spominje kao darovatelj.","D":"Ploča nije pisana latinicom, nego glagoljicom."},

  // 2022_ljeto_A
  "2022_ljeto_A__1": {"B":"Reducirana interpunkcija doista je obilježje ove pjesme, pa je tvrdnja točna i nije traženi odgovor.","C":"Pjesma jest pisana slobodnim stihom, što je točno, pa to nije netočna tvrdnja koju pitanje traži.","D":"Grafička organizacija pjesme stvarno postoji, pa je i ta tvrdnja točna i nije odgovor."},
  "2022_ljeto_A__2": {"A":"Umjetnost (čitanje romana) tek je bijeg, a ne sredstvo boljega života koji se u pjesmi ne ostvaruje.","C":"U pjesmi nema motiva iščekivanja voljene osobe, nego prikaza zapuštene, beznadne žene.","D":"Strah od velikoga grada nije tema; pjesma prikazuje neispunjenost života, a ne urbanu tjeskobu."},
  "2022_ljeto_A__3": {"B":"Kuhanje se ne spominje kao izvor utjehe; žena sjedi pokraj peći, ali utjehu nalazi u knjizi.","C":"Pjevanje se u tekstu ne navodi kao njezina utjeha.","D":"Snovi nisu spomenuti kao izvor utjehe; ona čezne nad romanom, a ne u sanjarenju."},
  "2022_ljeto_A__4": {"B":"Zahvalnost kćeri kao oslonac u starosti nije motiv okupljanja; cilj je da kći nađe vjerenika.","C":"Natjecanje pastira u sviranju nije razlog okupljanja, nego je popratni prizor veselja.","D":"Želja za veselim društvom nije prava svrha; okupljanje je organizirano radi udaje kćeri."},
  "2022_ljeto_A__5": {"B":"Osveta mrtvih sinova ne spominje se; 'ponoviti sinove' znači nastavak loze, a ne osvetu.","C":"Riječ nije o posjetu unuka, nego o želji da se uopće rode i tako produže rod.","D":"Slutnja vlastite skore smrti nije izrečena; naglasak je na nastavku obitelji kroz potomke."},
  "2022_ljeto_A__6": {"B":"Pričanje priča ne spominje se kao predmet natjecanja djevojaka.","C":"Plesanje nije ono u čemu se djevojke natječu prema navedenim stihovima.","D":"Natjecanje nije u ljepoti, nego u pletenju vjenčića i pjevanju."},
  "2022_ljeto_A__7": {"A":"'Zelena voćka' nije izraz kojim se metaforički prikazuje Tena u ovome tekstu.","B":"'Neobuzdana vatra' nije metafora upotrijebljena za Tenu.","C":"Čuvstvo 'lijepoga' nije slika kojom se prikazuje Tena; metafora je 'podivljali busen cvijeta'."},
  "2022_ljeto_A__8": {"A":"Đorđa nije osoba koju je Tena jedino voljela; nakon vodnika nikoga više nije ljubila.","B":"Jozu nije voljela; tekst kaže da poslije vodnika nije ljubila nikoga.","C":"Leona nije voljela; jedina ljubav bio joj je vodnik."},
  "2022_ljeto_A__9": {"A":"Usporedba ne govori o Teninu smislu za kiparstvo, nego o neskladu ljepote i okoline.","C":"Prijetvorno ponašanje nije ono na što usporedba upućuje.","D":"Leonovo bogatstvo nije predmet usporedbe; ona ističe neprimjerenost sredine ljepoti."},
  "2022_ljeto_A__10": {"A":"Čišćenje dimnjaka nije prikazano; prizor opisuje istjerivanje demona vatrom.","C":"Liječenje životinja nije tema teksta, premda se spominje veterinarski rječnik.","D":"Ubojstvo zarobljenika nije ono što se prikazuje, nego obredno istjerivanje zlih sila."},
  "2022_ljeto_A__11": {"A":"Cilj nije naglasiti obrazovanost urođenika, nego ironično dehumanizirati prizor.","C":"Ritmičnost teksta nije svrha životinjske terminologije.","D":"Stil basne nije ono što se postiže; postupak služi dehumanizaciji agenta."},
  "2022_ljeto_A__12": {"A":"Kapetan nije onaj koji je htio prekinuti događaj; to je upravitelj stroja.","B":"Liječnik nije lik koji je nastojao zaustaviti prizor.","D":"Veliki Vrač izvodi obred i njega bi upravitelj zadavio, dakle on nije onaj tko prekida."},
  "2022_ljeto_A__13": {"B":"Nije prikazano Moritánovo zaprepaštenje, nego zgražanje okupljenih mještana.","C":"Nije riječ o Rivarolinu zaprepaštenju, nego o reakciji ljudi na trgu.","D":"Nije susjedovo zaprepaštenje u prvom planu, nego začuđenost publike pred Pardovim činom."},
  "2022_ljeto_A__14": {"A":"Ubojičino razmetljivo odijevanje nije ono što susjed opravdava.","C":"Susjed ne opravdava samo ubojstvo, nego promišljenost izbjegavanja kazne, tj. glumljeno ludilo.","D":"Zatvorsku kaznu susjed ne opravdava, naprotiv smatra glupim biti uhvaćen i kažnjen."},
  "2022_ljeto_A__15": {"A":"Detaljan opis lika nije postupak kojim se postiže vjerodostojnost ovoga prikaza.","B":"Kronološko pripovijedanje nije naglašeni postupak vjerodostojnosti ovdje.","D":"Završno retoričko pitanje nije sredstvo vjerodostojnosti; nju daje svjedok susjed."},
  "2022_ljeto_A__16": {"B":"Tiresija ne objašnjava zašto bogovi nisu primili žrtvu kao svrhu obraćanja, nego upozorava na Kreontovu pogrešku.","C":"Navođenje nepromišljenih postupaka nije glavna uloga; cilj je uvjeriti Kreonta da ispravi odluku.","D":"Tiresija ne opravdava Kreontovo ponašanje, nego ga osuđuje kao pogrešno."},
  "2022_ljeto_A__17": {"B":"Komunikacija s mrtvima nije umijeće na koje Tiresija upućuje; on je prorok budućnosti.","C":"Žrtvovanje životinja nije umijeće o kojem govori, nego proricanje.","D":"Uzgoj ptica nije Tiresijino umijeće; ptice mu služe za proricanje, a ne za uzgoj."},
  "2022_ljeto_A__18": {"A":"Eteoklo je pokopan s počastima, pa nije 'pali jadnik' kojeg Tiresija spominje.","B":"Hemon nije onaj koga Tiresija naziva palim jadnikom.","C":"Kreont je vladar kojemu se Tiresija obraća, a ne pali jadnik o kojem govori."},
  "2022_ljeto_A__19": {"A":"Želja za osvetom nije iskazana; Sigismund izražava očaj zbog zatočeništva.","B":"Sigismund ne nastoji izazvati samilost sugovornika, nego govori sam, u monologu.","D":"Plan bijega iz kule nije izrečen u monologu; prevladava osjećaj beznađa."},
  "2022_ljeto_A__20": {"A":"Antiteza dobro – zlo nije temelj monologa, nego suprotnost slobode i ropstva.","B":"Privid – stvarnost nije osnovna antiteza ovoga monologa.","C":"Rođenje – smrt nije suprotnost na kojoj monolog počiva."},
  "2022_ljeto_A__21": {"A":"Astolfo nije kriv za Sigismundovo zatočeništvo.","C":"Klotaldo je tek tamničar/odgojitelj, a ne onaj tko ga je osudio na kulu.","D":"Rosaura nije uzrok Sigismundova stanja; krivac je njegov otac Bazilije."},
  "2022_ljeto_A__22": {"A":"Avangardisti nisu avangardnom odjećom isticali modernost; bili su građanski odjeveni.","C":"Izgledom nisu nastojali zainteresirati gledatelje; provokacija je bila u djelima.","D":"Njihova umjetnost nije bila uniformirana, nego raznolika i provokativna."},
  "2022_ljeto_A__23": {"A":"Pripadnost prošlosti nije razlog; ne predstavljaju se jer su općepoznati.","B":"Tvrdnja da ih fotografija dovoljno prikazuje nije navedeni razlog.","C":"Nisu nevažni za temu; ne treba ih predstaviti upravo zato što su slavni."},
  "2022_ljeto_A__24": {"A":"Nekonvencionalnost nije ono što autor zamjera; ističe da je umjetnost postala repetitivna.","B":"Proturječnost nije autorova ocjena umjetnosti njegova vremena.","C":"Provokativnost se pripisuje prošlim avangardistima, a ne suvremenoj umjetnosti koju autor drži neoriginalnom."},
  "2022_ljeto_A__25": {"A":"Namjena nije upozoriti na opasnost, nego objasniti utjecaj monitora na okolinu.","B":"Tekst ne potiče na istraživanje, nego objašnjava postojeće spoznaje o emisijama.","C":"Promocija novih tehnologija nije svrha teksta."},
  "2022_ljeto_A__26": {"A":"Elektromagnetska interferencija nije razlog štetnosti za ljude, nego smetnja drugim uređajima.","B":"Elektromagnetska sukladnost odnosi se na uređaje, a ne na štetnost po zdravlje ljudi.","C":"Olovo se spominje u drugom kontekstu, a zdravstvenu štetnost čine ELF i VLF emisije."},
  "2022_ljeto_A__27": {"A":"Elektromagnetska sukladnost se ne povećava s naponom; raste razina emisije/zračenja.","B":"Količina olova ne raste s pogonskim naponom prema tekstu.","C":"Filtriranje signala nije ono što se povećava višim naponom."},
  "2022_ljeto_A__28": {"A":"Tekst ne analizira uzrok sljepljivanja kao glavnu namjenu, nego daje upute za kuhanje.","B":"Poticanje ljudi na kuhanje jela nije svrha teksta.","D":"Opis nastanka raskuhane tjestenine nije namjena; tekst objašnjava pravilno kuhanje."},
  "2022_ljeto_A__29": {"A":"Odabir tjestenine s manje proteina ne navodi se kao način sprječavanja sljepljivanja.","C":"Soljenje vode nakon vrenja nije rješenje protiv sljepljivanja prema tekstu.","D":"Dodavanje ulja ne preporučuje se kao način sprječavanja sljepljivanja, nego miješanje."},
  "2022_ljeto_A__30": {"B":"Često kušanje tijekom kuhanja ne navodi se kao štetno za kvalitetu.","C":"Al dente čvrstoća poželjna je, a ne negativna za kvalitetu tjestenine.","D":"Visoka elastičnost nije navedena kao štetna; štetno je ispiranje koje uklanja škrob."},
  "2022_ljeto_A__31": {"A":"Anadiploza je ponavljanje kraja stiha na početku idućega, a ne logička proturječnost ovdje.","C":"Polisindeton je gomilanje veznika, čega u primjeru nema.","D":"Retoričko pitanje ne traži odgovor, dok u dijalogu na pitanja stižu odgovori; bit je apsurd."},
  "2022_ljeto_A__32": {"B":"'Prokleta avlija' nije utemeljena na antitezi, nego na atributu i imenici.","C":"'Zločin i kazna' povezuje pojmove uzroka i posljedice, a ne suprotnosti.","D":"'Crni mačak' opisni je naslov bez suprotstavljenih pojmova."},
  "2022_ljeto_A__33": {"A":"Epski deseterac stih je usmene narodne epike, a ne antičkih epova.","C":"Jedanaesterac je vezan uz renesansnu liriku, a ne uz antičke epove.","D":"Simetrični osmerac nije stih antičkih epova."},
  "2022_ljeto_A__34": {"A":"Buđenje nacionalne svijesti obilježje je domoljubne lirike, a ne elegije.","B":"Dijalozi popraćeni glazbom svojstveni su drami/operi, a ne elegiji.","C":"Uzvišeno slavljenje radosti i prirode pripada odi/ditirambu, a ne tužnoj elegiji."},
  "2022_ljeto_A__35": {"A":"Stih 'Da bim znala, drago...' nije dvostrukorimovani dvanaesterac.","B":"Stih 'Lepo pevaj, ptiček...' nema obilježje dvostrukorimovanoga dvanaesterca.","C":"Stih 'Tuge mje, tuge...' nije dvostrukorimovani dvanaesterac s rimom u sredini i na kraju."},
  "2022_ljeto_A__36": {"A":"A. B. Šimić pripada ekspresionizmu, a tvrdnja se odnosi na zbirku koja najavljuje modernizam.","C":"Petrarcin 'Kanconijer' renesansno je djelo, a ne najava modernizma sa spojem ljepote i zla.","D":"Tin Ujević nije autor zbirke kojom se najavljuje modernizam spojem dobra i zla."},
  "2022_ljeto_A__37": {"B":"'Lelek sebra' nije zbirka petrarkističke tradicije s likom nedohvatljive gospe na koju se tvrdnja odnosi.","C":"'Ojađeno zvono' nije zbirka opisana u tvrdnji.","D":"'Žedan kamen na studencu' nije zbirka od 48 pjesama posvećena imaginarnoj gospi."},
  "2022_ljeto_A__38": {"A":"U 'Agovanju' Smail-aga muči roblje, a navedeni stihovi su poticajni govor vojsci prije bitke.","B":"'Noćnik' prikazuje glasnika, a ne ohrabrujući govor zatočnicima.","D":"'Harač' prikazuje ubiranje danka i pogibiju, a ne pripremu čete za boj."},
  "2022_ljeto_A__39": {"A":"Stariji gospodin koji traži pokornu siromašnu ženu jest Lužin, a ne Porfirij Petrovič.","C":"Suprug Marfe Petrovne koji se udvara Dunji jest Svidrigajlov, a ne Porfirij.","D":"Propali činovnik uništen alkoholom jest Marmeladov, a ne istražni sudac Porfirij."},
  "2022_ljeto_A__40": {"A":"Pisanje u 1. licu samo po sebi ne čini roman epistolarnim.","B":"Dnevnički zapisi obilježje su dnevničkoga, a ne epistolarnoga romana.","D":"Nastanak u predromantizmu ne određuje vrstu romana kao epistolarnu, nego oblik pisama."},
  "2022_ljeto_A__41": {"A":"Kreont ne izgovara tu rečenicu o Antigoni; ona je Hamletova o majci.","B":"Miljenko ne izriče tu rečenicu o Dubravki.","C":"Leone ne govori tu rečenicu o barunici Glembay; izvorno je Hamletova."},
  "2022_ljeto_A__42": {"B":"'Preobražaj' prati Gregora Samsu, a ne zagrebački prizor s CENTROREKAMOM.","C":"'Zločin i kazna' smješten je u Petrograd, a navod opisuje Zagreb iz 'Kiklopa'.","D":"'Patnje mladog Werthera' epistolarni su roman bez ovih urbanih zagrebačkih slika."},
  "2022_ljeto_A__43": {"B":"Dostojevski se bavi krivnjom, vjerom i moralom, a opis o apsurdu odgovara Camusu.","C":"Kafka tematizira otuđenje i birokraciju, a tvrdnja o apsurdu i smislu odnosi se na Camusa.","D":"Calderón je barokni dramatičar, a opis pripada egzistencijalistu Camusu."},
  "2022_ljeto_A__44": {"A":"Prikaz aktualne teme i loše osobine svojstven je komediji/satiri, a ne klasičnoj tragediji.","C":"Tragedija je pisana stihom i uzvišenim stilom, a ne prozom i svakodnevnim govorom.","D":"Škrti starac, zaljubljeni mladić i lukavi sluga stalni su likovi komedije, ne tragedije."},
  "2022_ljeto_A__45": {"A":"Dijeljenje odgovornosti sa sestrom nije Antigonina tragična krivnja; ona djeluje sama.","C":"Antigona nije skrivila smrt zaručnika; Hemon se ubija sam nakon njezine smrti.","D":"Samoubojstvo je posljedica, a ne tragična krivnja koja je kršenje vladareva zakona."},
  "2022_ljeto_A__46": {"A":"'Ab ovo' znači pripovijedanje od početka, a ne razrješenje božanskim posredovanjem.","C":"'In medias res' označava ulazak u sredinu radnje, a ne raspletni postupak.","D":"'Quid pro quo' označava zamjenu/zabunu, a ne spuštanje božanstva na scenu."},
  "2022_ljeto_A__47": {"A":"Epigram je kratka lirska vrsta, a ne epska.","C":"Oda je lirska vrsta, ne pripada epskom rodu.","D":"Tragedija pripada dramskom rodu, a ne epskom."},
  "2022_ljeto_A__48": {"A":"Hamlet ne izgovara te riječi; on je predmet uhođenja, a ne uhoda iza zastora.","B":"Klaudije ne izriče te rečenice o skrivanju iza zastora.","C":"Laert nije lik koji se skriva iza zastora u majčinoj sobi; to je Polonije."},
  "2022_ljeto_A__49": {"A":"Monolog s prisjećanjem grijeha i povratkom Bogu opisuje 'Suze sina razmetnoga', a ne 'Dubravku'.","C":"Prepjevi pokorničkih psalama vezani su uz druga Gundulićeva djela, ne uz 'Dubravku'.","D":"Borba za prijestolje na temelju aktualnih događaja nije sadržaj 'Dubravke'."},
  "2022_ljeto_A__50": {"A":"Marinizam nije nastao u renesansi, nego u baroku.","C":"Klasicizam nije razdoblje marinizma.","D":"Romantizam nije razdoblje u kojem je nastao marinizam."},
  "2022_ljeto_A__51": {"A":"Dadaizam počiva na slučaju i provokaciji, a ne na Freudovoj psihoanalizi.","B":"Ekspresionizam izvire iz subjektivnoga doživljaja i krika, a ne iz psihoanalize.","C":"Futurizam slavi tehniku i brzinu, a nije nastao pod utjecajem Freuda."},
  "2022_ljeto_A__52": {"B":"Matoš pripada hrvatskoj moderni, a ne realizmu.","C":"A. B. Šimić pripada ekspresionizmu/avangardi, a ne realizmu.","D":"Tin Ujević pripada modernoj i međuratnoj književnosti, a ne realizmu."},
  "2022_ljeto_A__53": {"A":"Trubadurska lirika nije nastala u renesansnome Dubrovniku, nego u srednjovjekovnoj Provansi.","C":"Nije nastala u predrenesansnoj Italiji, nego u srednjovjekovnoj Europi.","D":"Nije nastala u antičkome Rimu, nego u srednjem vijeku."},
  "2022_ljeto_A__54": {"A":"Subjektivni pripovjedač nije obilježje realizma, koji teži objektivnosti.","B":"Humanizirani pejzaž svojstven je romantizmu/moderni, a ne realizmu.","D":"Svjetska bol (Weltschmerz) obilježje je romantizma, ne realizma."},
  "2022_ljeto_A__55": {"A":"Deskriptivnost nije specifično obilježje postmodernizma.","C":"Moralističnost nije značajka postmodernizma.","D":"Tendencioznost je obilježje angažirane/realističke književnosti, a ne postmodernizma."},
  "2022_ljeto_A__56": {"A":"'Piješčani' je pogrešno; pravilno je 'pješčani' (kratki slog).","C":"'Skupocijena' je pogrešno; pravilno je 'skupocjena'.","D":"'Zvijezdana' je pogrešno; pravilno je 'zvjezdana'."},
  "2022_ljeto_A__57": {"A":"'Svečenički' je pogrešno; korijen je svećenik s ć.","B":"'Svečenićki' ima dvostruku pogrešku: č umjesto ć i ć umjesto č u nastavku.","D":"'Svećenićki' je pogrešno; pravilno je -čki (svećeni-čki)."},
  "2022_ljeto_A__58": {"A":"'Zemljin satelit' treba veliko Z (Zemljin) kao odnosni pridjev od imena planeta.","B":"'Sovjetskim savezom' pogrešno je; pravilno je 'Sovjetskim Savezom' (obje riječi velikim slovom).","D":"'Tihi Ocean' pogrešno je; pravilno je 'Tihi ocean' (opća imenica malim slovom)."},
  "2022_ljeto_A__59": {"A":"'ph – vrijednosti' pogrešno je; piše se 'pH-vrijednosti' bez razmaka oko spojnice.","C":"'remek – djelo' pogrešno je; piše se 'remek-djelo' bez razmaka oko spojnice.","D":"'18 – karatnoga' pogrešno je; piše se '18-karatnoga' bez razmaka oko spojnice."},
  "2022_ljeto_A__60": {"A":"U 'prepečem' nema jotacije; č je nastao prvom palatalizacijom (k→č).","B":"U 'preskačem' č dolazi palatalizacijom, a ne jotacijom.","D":"U 'pretučem' č je rezultat palatalizacije, a ne jotacije."},
  "2022_ljeto_A__61": {"A":"U 'besraman' provedeno je samo jednačenje po zvučnosti (z→s), bez jednačenja po mjestu tvorbe.","C":"U 'bezbožan' nema potrebe za jednačenjem; z ostaje ispred zvučnoga b.","D":"U 'bežičan' provedeno je samo jednačenje po mjestu tvorbe (z→ž), a ne i po zvučnosti."},
  "2022_ljeto_A__62": {"A":"Naglasak s kapicom (pripovijêdati) označava dugosilazni, što nije pravilno na tome slogu.","B":"Kratkouzlazni (pripovijèdati) nije pravilan naglasak ove riječi.","D":"Kratkosilazni (pripovijȅdati) nije pravilan naglasak; pravilan je dugouzlazni."},
  "2022_ljeto_A__63": {"A":"'O' je prijedlog, dakle prednaglasnica (proklitika), a ne zanaglasnica.","C":"'I' je veznik/čestica koja stoji kao prednaglasnica, a ne zanaglasnica.","D":"'To' je naglašena zamjenica, a ne nenaglašena zanaglasnica."},
  "2022_ljeto_A__64": {"A":"'Po-' je prefiks, a ne korijenski morfem.","C":"'-telj-' je sufiks za vršitelja radnje, a ne korijen.","D":"Nulti morfem '-Ø' gramatički je nastavak, a ne korijen."},
  "2022_ljeto_A__65": {"A":"'Rad' je tvorbeni korijen, a ne oblikotvorna osnova cijele riječi.","B":"'Predrad' nije oblikotvorna osnova ove imenice.","C":"'Predradni' nije oblikotvorna osnova imenice 'predradnik'."},
  "2022_ljeto_A__66": {"A":"'Madež' je imenica muškoga roda, a ne srednjega.","B":"'Jaslice' su imenica ženskoga roda (pluralia tantum), a ne srednjega.","D":"'Uši' su imenica ženskoga roda, a ne srednjega."},
  "2022_ljeto_A__67": {"A":"'Turističkom' je atribut uz lokativ 'mjestu' (u tome mjestu), a ne u dativu.","C":"'Kojih' je u genitivu (s kojih), a ne u dativu.","D":"'Austrougarskih' je u genitivu (do vila), a ne u dativu."},
  "2022_ljeto_A__68": {"A":"'Dobri' je pogrešno; treba neodređeni oblik 'dobar' uz glagol 'bude'.","B":"'Najhrabrija srca' pogrešno je; treba genitiv 'najhrabrijih srca'.","D":"'Poznata glumca' pogrešno je; treba 'poznatog glumca' (određeni oblik u genitivu)."},
  "2022_ljeto_A__69": {"B":"'Okrenu se' je aorist, a ne prezent.","C":"'Zaplaka' je aorist, a ne prezent.","D":"'Jecaše' je imperfekt, a ne prezent."},
  "2022_ljeto_A__70": {"A":"Futur prvi tvori se od 'htjeti' + infinitiv, a 'budemo dolazili' je futur drugi.","C":"Kondicional prvi tvori se s 'bih, bi...' + glagolski pridjev, a ovdje je 'budemo'.","D":"Kondicional drugi tvori se s 'bio bih + bio', što nije ovaj oblik."},
  "2022_ljeto_A__71": {"B":"'Preko' je prijedlog (uz genitiv 'stijenja'), a ne prilog.","C":"'Unatoč' je prijedlog (uz dativ 'nevoljama'), a ne prilog.","D":"'Jutra' je imenica u genitivu, a ne prilog."},
  "2022_ljeto_A__72": {"A":"Prefiksalno-sufiksalna tvorba dodaje prefiks i sufiks, a 'blatobran' nastaje slaganjem dviju osnova.","B":"Složeno-sufiksalna tvorba uključuje i sufiks, čega u 'blatobran' nema.","C":"Sufiksalna tvorba dodaje samo sufiks, a ovdje su spojene dvije osnove bez sufiksa."},
  "2022_ljeto_A__73": {"B":"'Nasilnik' tvoren je sufiksom -ik od pridjeva 'nasilni', a ne sufiksom -nik.","C":"'Patnik' tvoren je sufiksom -nik, ali od glagolske osnove pat-, dok je traženi primjer od imenice; bolesnik je primjer tvorbe od imenice 'bolest' sufiksom -nik.","D":"'Sretnik' tvoren je sufiksom -ik od pridjeva 'sretni', a ne sufiksom -nik."},
  "2022_ljeto_A__74": {"A":"'Zaboraviti' nije nastalo prefiksalnom tvorbom od samostalne riječi ('boraviti' ima drukčije značenje); riječ je o vezanom korijenu.","B":"'Zanovijetati' nema samostalnu osnovu 'novijetati', pa nije primjer čiste prefiksalne tvorbe.","D":"'Zatvoriti' tvoreno je od 'tvoriti', no traženi je jasan primjer 'zapisati' (za- + pisati)."},
  "2022_ljeto_A__75": {"A":"'Kremšnite' nisu eponim; nazvane su po vrsti, a ne po vlastitom imenu osobe.","B":"'Kulen' nije eponim; nije izveden iz imena osobe.","C":"'Đurđevački pijesci' toponim su, a ne eponim nazvan po osobi."},
  "2022_ljeto_A__76": {"B":"'Otvoriti na koga vatru' znači žestoko napasti riječima, a ne pogoršavati situaciju.","C":"'Pregrmjeti prvu vatru' znači izdržati prvi nalet, a ne pogoršavati stanje.","D":"'Igrati se vatrom' znači izlagati se opasnosti, a ne pogoršavati situaciju."},
  "2022_ljeto_A__77": {"A":"'Ludim' nije bliskoznačno 'lucidnim'; lucidan znači bistar, a ne lud.","C":"'Rijetkim' ne odgovara značenju 'lucidan' (bistar, pronicav).","D":"'Važnim' nije bliskoznačno 'lucidnim'; lucidan se odnosi na bistrinu uma."},
  "2022_ljeto_A__78": {"A":"'Eskimski' je etnik-pridjev od naroda, a ktetik je pridjev izveden od imena mjesta.","C":"'Matoševski' je posvojni pridjev od osobnoga imena, a ne ktetik (od mjesta).","D":"'Zemaljska' je opisni pridjev, a ne ktetik izveden od naziva mjesta."},
  "2022_ljeto_A__79": {"A":"Administrativni stil odlikuju obrasci i ustaljene formule, a ne kemijska terminologija ovoga teksta.","B":"Književnoumjetnički stil koristi se slikovitošću i emocijama, čega u objektivnom opisu nema.","C":"Publicistički stil obraća se širokoj publici i nije strogo terminološki kao ovaj znanstveni tekst."},
  "2022_ljeto_A__80": {"A":"Opis kajkavske osnove s ozaljskim krugom odnosi se na Belostenčev/Habdelićev rad, a ne na prvi tiskani rječnik.","C":"Prvi kajkavsko-latinski rječnik nije prvi hrvatski tiskani rječnik; opis odgovara Habdeliću.","D":"Trojezični rječnik s hrvatskim kao polaznim jezikom nije prvi tiskani; Vrančićev je petojezičan."},

  // 2022_ljeto_B
  "2022_ljeto_B__1": {"A":"Lirski subjekt ne hvali njezinu ljepotu, nego optužuje način na koji ga je nenaoružana pogodila.","B":"Nigdje se ne spominje da draga voli slušati njegovu pjesmu; pjesma kao motiv nije tema soneta.","C":"Tekst ne govori o neuzvraćenoj ljubavi, nego o nečasnom, iznenadnom 'ranjavanju' bez upozorenja."},
  "2022_ljeto_B__2": {"B":"Amor ga nije kaznio zbog grijeha, nego ga je bez razloga, dok je bio bezbrižan, pogodio strijelom.","C":"Stih ne govori o gubitku smisla života, nego o nemogućnosti obrane od ljubavi.","D":"Lirski subjekt ne traži božju pomoć; on je nenaoružana žrtva Amorova napada."},
  "2022_ljeto_B__3": {"A":"Ljubav nije prikazana kao poziv na putovanje; tog motiva u sonetu nema.","B":"Lirski subjekt je bez oružja ('Bez oružja Amor na nišan me uze'), pa ljubav ne doživljava kao svoje oružje.","C":"Bezbrižnost je tek njegovo stanje prije udarca, a ne način na koji doživljava samu ljubav."},
  "2022_ljeto_B__4": {"A":"Eurimah ne obećava osvetu za zlodjela, nego nudi naknadu štete da odobrovolji Odiseja.","C":"On ne sažalijeva Odiseja zbog nanesena zla, nego se brani prebacujući krivnju na mrtvog Antinoja.","D":"Eurimah nije pomogao Odiseju da se vrati kući; bio je jedan od prosaca."},
  "2022_ljeto_B__5": {"A":"Eurimah ne kaže da su preživjeli htjeli ubiti Odisejeva sina; to pripisuje samo mrtvom Antinoju.","C":"Proci nisu pobjegli pred Odisejem; obuzeo ih je strah, ali Eurimah nudi nagodbu, ne bijeg.","D":"Eurimah ne tvrdi da su proci obrađivali Odisejeva polja, nego da su trošili u njegovoj kući."},
  "2022_ljeto_B__6": {"A":"Imovina prosaca spominje se kao ponuđena naknada, ali podcrtana riječ upućuje na osvetu, ne na imovinu.","B":"Podcrtana se riječ ne odnosi na Odisejeve muke, nego na njegovu odlučnost da se osveti.","C":"Riječ ne upućuje na isprike Odiseju; Odisej upravo odbija nagodbu i ustraje na osveti."},
  "2022_ljeto_B__7": {"B":"Ratkaj nije izviješten o potpisivanju povelje o slobodi; poslanici mu govore o nasilju nad kmetovima.","C":"Nije riječ o dogovoru plemića pred bitku, nego o pritužbi na Keglevićevo postupanje.","D":"Ne spominju se pripreme za izbor bana kao sadržaj izvješća koje Ratkaj prima."},
  "2022_ljeto_B__8": {"A":"Tekst ne kaže da svi poslanici podupiru bana Draškovića; to nije zajedničko obilježje.","B":"Ne ogovaraju svi Niku Alapića; to nije ono što ujedinjuje sve poslanike.","D":"Na kmetove se žale samo varaždinski poslanici, a ne svi okupljeni."},
  "2022_ljeto_B__9": {"A":"Franjo Stolniković je onaj kojemu Želnički kradomice namiguje, dakle objekt dvoličnosti, a ne dvolična osoba.","B":"Gregorijanec Medvedgradski nije u ulomku prikazan kao dvoličan lik.","D":"Stjepko Tah je onaj kojemu se Želnički udvara, a ne onaj koji je dvoličan."},
  "2022_ljeto_B__10": {"A":"Ljubav ne potiče ljutnju prema drugima, nego stvaralačku nemoć pri slikanju Lotte.","C":"Riječ 'osramotio' odnosi se na neuspjeh u slikanju, a ne na stid i nelagodu kao osjećaj prema Lotti.","D":"Tekst ne iskazuje zabrinutost kao učinak ljubavi, nego nesposobnost umjetničkog predočivanja."},
  "2022_ljeto_B__11": {"A":"Fantom se odnosi na prolazne slike iz usporedbe s laternom magicom, a ne na Lottu.","C":"Sunce je u usporedbi simbolično, ali Lottu izravno predstavlja bononski kamen koji upija njezin sjaj; sunce je sjaj koji ona zrači.","D":"Tisuća talira ne pojavljuje se kao slika Lotte u ovom pismu."},
  "2022_ljeto_B__12": {"B":"Motivi iz prirode ne podsjećaju Werthera na Wilhelma, nego izražavaju njegove osjećaje.","C":"Oni ne opisuju mjesto gdje slika, nego naglašavaju prisnost njegova doživljaja prirode.","D":"Svrha im nije puko dočaravanje ljepote krajolika, nego pojačavanje pripovjedačevih emocija."},
  "2022_ljeto_B__13": {"A":"Složene rečenice nisu navedeni postupak postizanja realističnosti u ovom ulomku.","C":"Ljepota djevojke je motiv, ali ne postupak kojim se postiže dojam realističnosti.","D":"Realističnost ovdje proizlazi iz navođenja rukopisa, a ne iz pripovijedanja u prvom licu."},
  "2022_ljeto_B__14": {"A":"Staleži mu nisu pomagali da zaposjedne imanje ženinih rođaka; rođaci su mu sami dali stan.","C":"Život u Veneciji olakšali su mu rođaci novcem i stanom, a ne hrvatski staleži.","D":"Staleži mu nisu pomagali da otjera Turke, nego u borbi protiv gradačke komore."},
  "2022_ljeto_B__15": {"B":"Blagaj nije odabrao Marjetu kao model da pokaže najdraže dijete; portret je nastao na slikarevu molbu.","C":"Slikar nije prodajom portreta htio pomoći Blagaju, nego ga je poklonio kao molbu za dopuštenje.","D":"Blagaj se portretom nije dodvoravao francuskom kralju; djelo za kralja tek je trebao izraditi slikar."},
  "2022_ljeto_B__16": {"A":"Otac (Edip) nije dao pogubiti sinove; oni su jedan drugoga ubili u međusobnom sukobu.","B":"Edip nije ubio svojega brata; objesila se njegova majka i žena.","D":"Objesila se Edipova majka i žena ('pletenom omčom'), a ne sam otac, koji se oslijepio."},
  "2022_ljeto_B__17": {"A":"Izmena ne odlučuje odati počast roditeljima, nego se pokoriti vlasti.","C":"Izmena upravo odbija pomoći Antigoni jer se ne usuđuje suprotstaviti vladaru.","D":"Ne odlučuje osvetiti braću, nego slušati poglavare i ne raditi protiv svojih snaga."},
  "2022_ljeto_B__18": {"B":"Antigona se ne želi svidjeti svim ljudima, nego mrtvima i bogovima podzemnoga svijeta.","C":"Ne traži da je vladar poštuje; upravo se suprotstavlja Kreontovoj volji.","D":"Ne teži vlasti, nego poštivanju nepisanih, božanskih zakona."},
  "2022_ljeto_B__19": {"B":"Stražarska neopreznost nije sadržaj 'vreve i meteža'; straže su, naprotiv, brižljive i stroge.","C":"Pojava Duha noću zaseban je motiv i ne odnosi se na vrevu i metež naoružavanja.","D":"Dvoboj kraljeva pripada prošlosti koju prepričava Horacije, a ne aktualnoj užurbanoj pripremi za rat."},
  "2022_ljeto_B__20": {"B":"Ljude ne pokreće želja za pravdom, nego prilika da iskušaju svoju hrabrost.","C":"Motiv nije odanost kralju; riječ je o 'družbi divljih pustolova' željnih dokazivanja.","D":"Zavist nije navedeni motiv pristupanja Fortinbrasovu pohodu."},
  "2022_ljeto_B__21": {"A":"Tekst ne govori da se poništava ugovor; naprotiv, ugovor je vrijedio i potvrdio gubitak zemalja.","B":"Duh koji se pojavljuje je duh kralja Hamleta (pobjednika), a ne ubojice norveškoga kralja.","C":"Ne spominje se da norveška vojska smaknut će ubojicu svojega kralja; sin Fortinbras traži povrat zemalja."},
  "2022_ljeto_B__22": {"A":"Hegel se spominje samo usputno radi definicije znanja, a nije tema teksta o ispravnosti njegovih predviđanja.","B":"Tekst tvrdi suprotno: zbog ograničena kapaciteta razlikovanje važnih informacija slabi, a ne se poboljšava.","D":"Autor ne govori o prednostima porasta informacija, nego o njihovoj uglavnom beskorisnosti."},
  "2022_ljeto_B__23": {"A":"Autor tvrdi suprotno: mnoštvo informacija ne znači mnogo znanja jer informacija nije spoznaja.","B":"Ne tvrdi da ljudi napreduju u filtriranju važnih informacija, nego da im kapacitet to otežava.","D":"Tvrdnja da vijesti upravljaju životima nije autorova teza; on naglašava ograničenost ljudskog kapaciteta."},
  "2022_ljeto_B__24": {"A":"Vremenska prognoza nije opisana kao mukotrpan posao, nego kao jedina relevantna informacija.","C":"Za autora vremenska prognoza nije dezinformacija, nego rijedak primjer doista korisne informacije.","D":"Vremensku prognozu autor ne svrstava u zabavu, za razliku od većine drugih sadržaja."},
  "2022_ljeto_B__25": {"A":"Ljubav koja se temelji na popuštanju nije navedena kao opasna vrsta ljubavi.","B":"Bezuvjetna požrtvovna ljubav nije ono što su Grci smatrali opasnim; opasan je eros.","C":"Mladenačka nezrela ljubav nije ta koja se ističe kao opasna; opasnom su smatrali strastvenu tjelesnu ljubav (eros)."},
  "2022_ljeto_B__26": {"A":"Tjelesna privlačnost pripada erosu, koji se prema Aristotelu prerasta, a brak se temelji na philiji.","B":"Ljubav prema sebi nije osnova braka prema Aristotelu; brak počiva na prijateljskoj ljubavi.","D":"Požuda (eros) nije temelj braka; u zreloj se dobi odnose gradi na philiji."},
  "2022_ljeto_B__27": {"A":"Tekst ne tvrdi da su konkretni pojmovi imali mnogo značenja, a apstraktni samo jedno; obrnuto, apstraktni vode više tumačenja.","C":"Ne kaže se da su oba tipa pojmova jednako razumljiva; apstraktni izazivaju razilaženje u značenju.","D":"Tekst ne uspoređuje brojnost apstraktnih i konkretnih pojmova u staroj Grčkoj."},
  "2022_ljeto_B__28": {"B":"Ne preporučuje se izmjenjivanje vrsta iste porodice, nego upravo različitih kultura.","C":"U dobrom plodoredu izmjenjuju se kulture različite dubine korijena, a ne iste.","D":"Plodored sprječava nagomilavanje štetnih tvari u tlu, a ne ga uzrokuje."},
  "2022_ljeto_B__29": {"B":"Tekst ne navodi da mrkva smanjuje mrvičastost tla kao razlog te izmjene.","C":"Krastavac i mrkva nemaju sličnu potrebu za vodom; upravo se izmjenjuju zbog različitih potreba.","D":"Ubrzavanje rasta korova nije razlog ni cilj uzgoja mrkve nakon krastavaca."},
  "2022_ljeto_B__30": {"B":"Kelj je kupusnjača i nije naveden kao preporučena pretkultura za rajčicu.","C":"Krastavac se ne navodi među preporučenim pretkulturama za rajčicu (mahunarke i korjenasto povrće).","D":"Paprika nije među pretkulturama preporučenim za rajčicu."},
  "2022_ljeto_B__31": {"A":"Stih o đurđicu sadrži epitete (skroman, tih, fin), ali ne spaja različite osjete pa nije sinestezija.","C":"Stih o maćuhici sadrži personifikaciju ('ćuti'), a ne sinesteziju.","D":"Stih o gričkim zvonima sadrži personifikaciju ('zaplakala'), ne spoj dvaju osjeta."},
  "2022_ljeto_B__32": {"A":"Epifora je ponavljanje na kraju stihova, a ovdje se ponavlja 'brže' na početku, uz stupnjevanje.","C":"Inverzija je promjena uobičajena reda riječi, a u stihovima dominira stupnjevito pojačavanje usporedbi.","D":"Polisindeton je gomilanje veznika, čega ovdje nema; riječ je o gradaciji."},
  "2022_ljeto_B__33": {"A":"Antiteza je suprotstavljanje pojmova, kojeg u ovim stihovima nema.","C":"Onomatopeja je oponašanje zvukova, a ovdje se izravno obraća nebu.","D":"Paradoks je prividno proturječan iskaz, čega u ovim stihovima nema; riječ je o apostrofi."},
  "2022_ljeto_B__34": {"A":"Nesporazum zbog zamjene osoba ili stvari je zaplet komedije (kvloproquo), a ne katarza.","B":"Razrješenje božjom intervencijom je deus ex machina, a ne katarza.","C":"Oponašanje stvarnosti je mimeza, a ne katarza."},
  "2022_ljeto_B__35": {"A":"Ditiramb je lirska vrsta (hvalospjev Dionizu), a ne lirsko-epska.","B":"Elegija je lirska vrsta (tužaljka), a ne lirsko-epska.","C":"Legenda je epska prozna vrsta, a ne lirsko-epska."},
  "2022_ljeto_B__36": {"A":"Romantičarska poema ne počiva na trima jedinstvima ni Aristotelovoj poetici, koje rečenica ističe.","B":"Renesansna komedija ne odgovara opisu klasicističke tragedije s pravilom trima jedinstvima.","D":"Barokni ep nije dramska vrsta i ne temelji se na pravilu trima jedinstvima."},
  "2022_ljeto_B__37": {"B":"Šimić nije poznat po prevlasti soneta; oblikom njegova poezija nije pretežno sonetna.","C":"Šimić pripada ekspresionizmu, a ne stvaralaštvu pod utjecajem francuskoga simbolizma.","D":"Šimić nije dijalektalni pjesnik; pisao je standardnim jezikom."},
  "2022_ljeto_B__38": {"B":"Simetrični osmerac nije najčešći stih hrvatske renesanse, nego se javlja kasnije i drugdje.","C":"Aleksandrinac je francuski dvanaesterac i nije obilježje hrvatskoga renesansnog pjesništva.","D":"Heksametar je antički stih, a ne najčešći stih hrvatske renesanse."},
  "2022_ljeto_B__39": {"A":"Humanizam prethodi renesansi, a ne neposredno baroku.","B":"Klasicizam slijedi nakon baroka, pa mu ne prethodi.","D":"Romantizam dolazi mnogo poslije baroka, pa mu ne može prethoditi."},
  "2022_ljeto_B__40": {"A":"Dubravka Ivana Gundulića je barokno djelo, a ne renesansno.","C":"Posljednji Stipančići Vjenceslava Novaka pripadaju realizmu.","D":"Zlatarovo zlato Augusta Šenoe pripada realizmu (protorealizmu), a ne renesansi."},
  "2022_ljeto_B__41": {"A":"Dijalog je razgovor likova, a ovdje se pjesnik obraća muzama, što je invokacija.","C":"Retardacija je usporavanje radnje, čega na početku epa ovdje nema.","D":"Retrospekcija je vraćanje u prošlost, a ovdje je riječ o zazivanju muza."},
  "2022_ljeto_B__42": {"A":"Suprotnost duhovno-materijalno nije temeljni sukob ovoga djela.","C":"Suprotnost mladost-starost nije nosiva opreka Mažuranićeva spjeva.","D":"Suprotnost grad-selo nije tema djela; radnja se temelji na opreci slobode i ropstva."},
  "2022_ljeto_B__43": {"A":"Cvjetovi zla (Baudelaire) pripadaju simbolizmu/modernizmu 19. stoljeća, a ne renesansi.","C":"Patnje mladog Werthera (Goethe) pripadaju predromantizmu/romantizmu 18. stoljeća.","D":"Život je san (Calderón) barokno je djelo, a ne renesansno."},
  "2022_ljeto_B__44": {"A":"Pisanje pisma Raymondovoj ljubavnici događa se kasnije u romanu, a ne na početku.","C":"Odlazak u kino s Marie zbiva se nakon majčina pogreba, a ne na samom početku.","D":"Ubojstvo Arapina događa se na kraju prvoga dijela, a ne na početku romana."},
  "2022_ljeto_B__45": {"A":"Gregor Samsa nije osuđen na smrtnu kaznu; pretvoren je u kukca i propada u obitelji.","B":"Leone Glembay nije osuđen na smrtnu kaznu; opis otuđena pojedinca osuđena od suda ne odgovara njemu.","D":"Raskoljnikov je osuđen na progonstvo u Sibir, a ne na smrtnu kaznu, i sam priznaje krivnju."},
  "2022_ljeto_B__46": {"A":"Camus nije utemeljio ideju Stranca na mitu o Edipu.","B":"Mit o Odiseju nije temelj Camusove filozofije apsurda.","C":"Mit o Prometeju nije onaj na kojem Camus objašnjava apsurd; to je mit o Sizifu."},
  "2022_ljeto_B__47": {"A":"Gregor Samsa nije žrtva očeva praznovjerja, nego se pretvara u kukca i otuđuje od obitelji.","B":"Leone Glembay nije žrtva očeva praznovjerja, nego sukoba s ocem i obiteljskih tajni.","D":"Werther nije žrtva očeva praznovjerja, nego nesretne ljubavi."},
  "2022_ljeto_B__48": {"B":"Eteoklo je sahranjen po pravilima, pa se na njega ne odnose Tiresijine riječi o živoj u grobu i nesahranjenu mrtvacu.","C":"Euridika nije lik na koji se odnose ove riječi; ona je Kreontova žena.","D":"Polinik je mrtvac kojega Kreont ne da sahraniti, no podcrtana riječ ('živu u grob strpao') odnosi se na Antigonu."},
  "2022_ljeto_B__49": {"A":"Astolfo se ne prerušava u suprotni spol; on je vojvoda koji se bori za prijestolje.","B":"Klarin je sluga i ne prerušava se u osobu suprotnoga spola.","D":"Stela se ne prerušava u muškarca; to čini Rosaura."},
  "2022_ljeto_B__50": {"B":"Poloniojev oproštaj sa sinom događa se kasnije, a ne na samom početku tragedije.","C":"Prisluškivanje razgovora Hamleta i Ofelije zbiva se poslije, a ne u prvoj sceni.","D":"Hamletove upute glumcima dolaze tek pred izvedbu 'mišolovke', a ne na početku."},
  "2022_ljeto_B__51": {"A":"Dr. Altmann je liječnik, a ne karitativni tajnik i ispovjednik barunice.","B":"Leone Glembay je slikar i sin, a ne tajnik ni ispovjednik koji izgovara navedenu rečenicu.","C":"Puba Fabriczy je pravnik (odvjetnik), a ne crkvena osoba koja se opisuje kao ispovjednik barunice."},
  "2022_ljeto_B__52": {"A":"Ep nije dominantna vrsta realizma; pripada starijim razdobljima.","B":"Lirska pjesma nije dominantna vrsta realizma, koji je doba romana.","D":"Tragedija nije dominantna vrsta realizma, nego ranijih, klasičnih razdoblja."},
  "2022_ljeto_B__53": {"A":"Buđenje nacionalne svijesti je program nacionalnih književnosti (npr. romantizma), a ne larpurlartizma.","C":"Oponašanje stvarnosti (mimeza) je obilježje realizma, a ne larpurlartizma.","D":"Didaktička uloga umjetnosti suprotna je larpurlartizmu, koji odbacuje izvanestetske svrhe."},
  "2022_ljeto_B__54": {"B":"Baudelaire je pjesnik simbolizma, a ne utemeljitelj filozofije apsurda.","C":"Dostojevski je realist i ne utemeljuje filozofiju apsurda.","D":"Goethe pripada predromantizmu/romantizmu i nije utemeljitelj filozofije apsurda."},
  "2022_ljeto_B__55": {"A":"Juriš nije časopis koji je uveo drugu modernu i suprotstavio se socrealizmu.","B":"Kolo je stariji časopis i nije onaj koji uvodi hrvatsku književnost u drugu modernu.","D":"Vijenac je časopis ranijih razdoblja, a ne nositelj druge moderne nasuprot socrealizmu."},
  "2022_ljeto_B__56": {"A":"Pravilno je 'plaćenički' (s ć), a ne 'plačenički'.","B":"Pravilno je 'paćenički' i 'sveca', a ne 'pačenički' i 'svetca'.","D":"Pravilno je 'svećenički' (s ć), a ne 'svečenički'."},
  "2022_ljeto_B__57": {"B":"Ispravno je 'razrijediti – razrjeđivati' (dugi jat u infinitivu), a ne 'razrjediti'.","C":"Ispravno je 'smijeniti – smjenjivati', a ne 'smjeniti'.","D":"Ispravno je 'odoljeti – odolijevati', a ne 'odoljevati'."},
  "2022_ljeto_B__58": {"A":"Pravilno je 'crvenperka' (od crven), a ne 'crvemperka'.","B":"Pravilno je 'jedanput', a ne 'jedamput'.","D":"Pravilno je 'stranputica' (s nputica), a ne 'stramputica'."},
  "2022_ljeto_B__59": {"A":"Treba 'Hrvatskoga narodnog kazališta' (samo prva riječ velikim), a ne svaka riječ velikim slovom.","C":"Treba 'azurnu obalu' malim slovom jer je to opisni naziv, a ne vlastito ime.","D":"Treba 'Trgu kralja Tomislava' jer se 'kralja' piše malim slovom."},
  "2022_ljeto_B__60": {"A":"Ne stavlja se zarez između subjekta ('Šiško Menčetić') i predikata ('stvarao je').","B":"Riječ 'dakako' kao umetak treba biti odvojena zarezima s obje strane.","D":"Ispred 'nego' u usporedbi ne piše se zarez."},
  "2022_ljeto_B__61": {"A":"Pravilno je 'natčovjek' (jednačenje d→t ispred č), a ne 'nadčovjek'.","C":"Pravilno je 'natpolovičan' (jednačenje d→t ispred p), a ne 'nadpolovičan'.","D":"Pravilno je 'natprirodan' (jednačenje d→t ispred p), a ne 'nadprirodan'."},
  "2022_ljeto_B__62": {"A":"U 'gost > gozba' provedeno je jednačenje po zvučnosti (st→zb), a ne palatalizacija.","B":"U 'list > lišće' riječ je o jotaciji, a ne palatalizaciji.","C":"U 'misao > mišlju' riječ je o jotaciji, a ne palatalizaciji."},
  "2022_ljeto_B__63": {"A":"Oznaka ό nije znak za naglasak hrvatskoga standarda za 'brod'.","B":"ȏ označava dugosilazni naglasak, a 'brod' ima kratkosilazni.","D":"Oznaka ὸ nije ispravan naglasni znak za riječ 'brod'."},
  "2022_ljeto_B__64": {"A":"'Ja' je naglašena osobna zamjenica, a ne zanaglasnica.","B":"'Još' je naglašeni prilog.","C":"'Bio' je naglašeni glagolski pridjev radni."},
  "2022_ljeto_B__65": {"B":"'-ca' nije gramatički morfem riječi 'ljepotica'; oblikotvorni je samo nastavak '-a'.","C":"'-ica' je tvorbeni (sufiksalni) dio, a ne oblikotvorni morfem.","D":"'-tica' je tvorbeni sufiks, a ne gramatički (oblikotvorni) morfem."},
  "2022_ljeto_B__66": {"A":"Dativ ne dolazi s prijedlogom 'među' u ovom značenju smještaja.","B":"Akuzativ bi došao uz 'među' samo uz glagol kretanja (smjer), a ovdje je riječ o mirovanju (gdje?).","C":"Lokativ ne dolazi s prijedlogom 'među'; ovdje je instrumental."},
  "2022_ljeto_B__67": {"A":"'Svojega' je posvojna (povratno-posvojna) zamjenica, a ne neodređena.","C":"'Ga' je osobna zamjenica (enklitički oblik), a ne neodređena.","D":"'Toga' je pokazna zamjenica, a ne neodređena."},
  "2022_ljeto_B__68": {"A":"'Momčad' nije u množini; 'momčadi' je oblik jednine ženskoga roda.","B":"'Momčad' je ženskoga, a ne muškoga roda, i nije u množini.","D":"'Momčad' nije muškoga roda; riječ je o ženskom rodu jednine."},
  "2022_ljeto_B__69": {"B":"Glagolski pridjev radni završava na -o/-la/-lo (npr. 'gledao'), a 'gledajući' je prilog.","C":"Prezent je lični glagolski oblik (npr. 'gleda'), a 'gledajući' je nepromjenjiv prilog.","D":"Infinitiv glasi 'gledati', a 'gledajući' je glagolski prilog sadašnji."},
  "2022_ljeto_B__70": {"A":"'Odolijevati' je nesvršeni (učestali) glagol s prezentom 'odolijevam', a ovdje je svršeni oblik 'odole'.","B":"'Odoljevati' nije pravilan infinitiv; pravilno je 'odoljeti' (svršeno) ili 'odolijevati' (nesvršeno).","D":"'Odoliti' nije pravilan infinitiv tog glagola; ispravno je 'odoljeti'."},
  "2022_ljeto_B__71": {"A":"Tri je premalo; nepromjenjivih riječi (kroz, ali, ni, tada) ima više od tri.","C":"Pet je previše ako se 'je' i 'palo' broje kao promjenjive; ukupno nepromjenjivih je četiri.","D":"Šest je previše; toliko nepromjenjivih riječi u rečenici nema."},
  "2022_ljeto_B__72": {"B":"'Ostati praznih ruku' znači ne dobiti ništa, a ne trajno prestati s radom.","C":"'Stegnuti remen' znači štedjeti, a ne prestati s radom.","D":"'Stati na loptu' znači usporiti/smiriti se, a ne trajno prestati raditi."},
  "2022_ljeto_B__73": {"A":"Administrativni stil obilježavaju obrasci i ustaljene formulacije, a ne stručno znanstveno nazivlje.","B":"Književnoumjetnički stil odlikuju slikovitost i stilske figure, čega u ovoj stručnoj rečenici nema.","C":"Publicistički stil je usmjeren široj publici i pristupačniji, a ova je rečenica strogo terminološka."},
  "2022_ljeto_B__74": {"A":"'Laureat' potječe od latinske riječi za lovor (apelativ), a ne od vlastita imena, pa nije eponim.","B":"'Disertacija' nije nastala od osobnog imena, pa nije eponim.","D":"'Poklisar' je naziv za zastupnika, ali nije izveden iz vlastita imena, pa nije eponim."},
  "2022_ljeto_B__75": {"B":"Sufiks nije '-nica' jer osnova završava na 'i' (uči-), a prostorni je sufiks '-onica'.","C":"'-ica' nije tvorbeni nastavak ove riječi; prostorne imenice tvori '-onica'.","D":"'-a' je samo oblikotvorni nastavak, a tvorbeni je sufiks '-onica'."},
  "2022_ljeto_B__76": {"A":"Nema prefiksa ispred osnove 'bogat', pa nije prefiksalno-sufiksalna tvorba.","B":"Nema dviju osnova, pa nije složeno-sufiksalna tvorba.","C":"Nema prefiksa, pa nije prefiksalna tvorba; riječ je tvorena samo sufiksom '-aš'."},
  "2022_ljeto_B__77": {"A":"Antroponimi su osobna imena ljudi, a 'Mokro Polje' je naziv naselja.","C":"Hidronimi su imena voda, a 'Mokro Polje' je ime naseljena mjesta.","D":"Oronimi su imena reljefnih uzvisina, a 'Mokro Polje' je naziv naselja (ekonim)."},
  "2022_ljeto_B__78": {"B":"Posuđenice iz francuskoga su galicizmi, a ne luzitanizmi.","C":"Posuđenice iz talijanskoga su italicizmi, a ne luzitanizmi.","D":"Posuđenice iz latinskoga su latinizmi, a ne luzitanizmi."},
  "2022_ljeto_B__79": {"A":"Administrativni stil odlikuje ustaljeno, neutralno nazivlje, a ne kolokvijalizmi.","B":"Publicistički stil nije obilježen kolokvijalizmima kao temeljnom značajkom.","D":"Znanstveni stil obilježava terminologija i objektivnost, a ne kolokvijalizmi."},
  "2022_ljeto_B__80": {"A":"Bartol Kašić sastavio je prvu hrvatsku gramatiku, a ne prvi tiskani rječnik.","B":"Bogoslav Šulek djeluje u 19. stoljeću i nije autor prvoga tiskanog rječnika.","D":"Ljudevit Gaj je preporoditelj i autor pravopisa, a ne prvoga tiskanog rječnika."},

  // 2023_jesen
  "2023_jesen__1": {"A":"Lovro se u gradu nije osjećao manje vrijednim, nego mu se srce razigralo od silnih dojmova.","B":"U tekstu nema čežnje za domom; nakon rastanka od majke grad ga ispunja veseljem, a ne tugom.","D":"Izrijekom se kaže da se Lovro nije plašio kao drugi seoski dječaci, pa strah nije bio njegova reakcija."},
  "2023_jesen__2": {"A":"O njemačkom jeziku kao mjerilu obrazovanosti u ulomku se ne govori.","C":"Lovrin uspjeh proizlazi iz njegova oštra uma i marljivosti, a ne iz pukoga slušanja učitelja.","D":"Iako otac vodi Lovru u grad, predrasuda koju on opovrgava odnosi se na sposobnost djece, a ne na to tko odlučuje o školovanju."},
  "2023_jesen__3": {"A":"Sintagma se odnosi na pobožnost i žrtvu za Boga, a ne na borbu za prava seljačke djece.","B":"Riječ je o nedostatku predanosti svećeničkom pozivu, a ne o (ne)završavanju srednje škole.","C":"Izraz ne govori o odnosu prema učiteljima ni o (ne)poniznosti, nego o predanosti božjoj službi."},
  "2023_jesen__4": {"A":"Kronološko nizanje događaja ne izražava pripovjedačev stav, nego samo redoslijed zbivanja.","B":"Retoričkih pitanja u ovom ulomku nema, pa se njima stav ne iskazuje.","D":"Aorist i imperfekt obilježja su pripovijedanja općenito, ali ne otkrivaju pripovjedačev osjećajni stav prema liku."},
  "2023_jesen__5": {"A":"Zaposlenje kod vladina predsjednika nije ono što ga potiče na raskid sa svećeničkim pozivom.","B":"Odlazak u Prag dio je njegova školovanja, ali nije presudan trenutak za napuštanje poziva.","C":"Čitanje Petrarcinih pjesama nije presudni događaj koji ga nagoni na raskid svetih veriga."},
  "2023_jesen__6": {"A":"Pisanje pisma kojim odbija sestrinu žrtvu nije ono na što se odnosi zamjenica 'to' u navedenim rečenicama.","B":"Pisanje članka o odabranim pojedincima nije predmet Raskoljnikovljeva premišljanja u ovom odlomku.","C":"Plaćanje sprovoda posljednjim novcem nije ono o čemu junak ovdje dvoji."},
  "2023_jesen__7": {"A":"Junak ne zaključuje da strah pobjeđuje suočavanjem, nego priznaje da govorom odgađa čin.","B":"O sumnji kao pokretaču napretka u monologu se ne govori.","C":"Smisao života u sitnicama nije misao monologa; junak baš sitnice prezire kao prepreke."},
  "2023_jesen__8": {"A":"Raskoljnikov se ne ljuti zbog javnog ismijavanja, nego brine zbog vlastite uočljivosti.","B":"Nije riječ o sramu zbog nemogućnosti kupnje novoga šešira, nego o strahu da je previše primjetan.","C":"Ne boji se krađe šešira, nego toga da bi ga upadljiv šešir mogao odati."},
  "2023_jesen__9": {"B":"Retorička pitanja nisu specifično realističko obilježje, nego opće retoričko sredstvo.","C":"Grafostilemi nisu obilježje realističke poetike.","D":"Unutarnji monolog tipičniji je za modernističku prozu nego za realistički prosede."},
  "2023_jesen__10": {"A":"Rečenica je junakova izgovorena misao, a ne pripovjedačev komentar.","C":"Iako opisuje radnju, rečenica pripada pripovijedanju o zbivanju, a ne metatekstualnom komentaru.","D":"I ovo je Raskoljnikovljeva misao (uzvik), a ne pripovjedačev komentar."},
  "2023_jesen__11": {"A":"Ditirampski ugođaj podrazumijeva zanesenu pohvalu, čega u smirenom opisu brezovine nema.","B":"Elegični ugođaj nosi tugu i sjetu, a opisani prizor odiše mirom i ljepotom.","D":"Satirični ugođaj uključuje izrugivanje, što je strano ovomu opisu prirode."},
  "2023_jesen__12": {"A":"Iz glasanja svrake pripovjedač ne zaključuje o sukobu Batorića i seljaka.","C":"Svraka mu ne najavljuje prekid lova, nego približavanje plijena.","D":"Glasanje svrake ne upućuje na blizinu drugih lovaca, nego na lovinu."},
  "2023_jesen__13": {"A":"Sukob ne nastaje zbog nadmetanja oko naklonosti bečkoga dvora.","B":"Seljaci se ne sukobljavaju zato da se pokažu boljim lovcima pred pripovjedačem.","D":"Iako dolazi do oštrih riječi, uzrok sukoba je Batorićevo nepristajanje na ukidanje kmetstva, a ne puko vrijeđanje."},
  "2023_jesen__14": {"A":"Tekst se ne gradi na alegoriji kao prenesenom drugom značenju cijeloga prikaza.","B":"Hiperbola (pretjerivanje) nije postupak na kojem počiva tekst.","C":"Ironija nije temeljni postupak; suprotstavljanje idile i sukoba ostvareno je kontrastom."},
  "2023_jesen__15": {"A":"Pripovijeda se u prvome licu sudionika, a ne iz perspektive sveznajućega pripovjedača.","B":"Govorna karakterizacija likova temelji se na dijalektu (kajkavštini), a ne na poetizmima.","C":"Opis prirode služi stvaranju ugođaja, a ne socijalnoj karakterizaciji likova."},
  "2023_jesen__16": {"A":"Kreont Zbor ne saziva da bi javio za smrt Edipovih sinova, nego da bi izložio i potvrdio svoje odluke.","C":"Cilj njegova obraćanja nije objasniti oslobađanje grada, nego pridobiti potporu za svoju vladavinu.","D":"Kreont ne traži pomoć u obnovi grada, nego potvrdu svojih vladarskih odluka."},
  "2023_jesen__17": {"A":"Savjetovanje s glasnicima nije načelo koje Kreont ističe kao temelj vlasti.","C":"Kreont upravo nadređuje državu obitelji, pa poštovanje obitelji nije njegovo temeljno načelo.","D":"Štovanje Zeusa nije ono što Kreont navodi kao temelj svoje vladavine."},
  "2023_jesen__18": {"B":"Zbor ne savjetuje Kreontu brigu za žive sugrađane, nego razlikovanje prijatelja i neprijatelja.","C":"Zbor mu ne govori da treba pridobiti narod, nego potvrđuje njegovo pravo na primjenu zakona.","D":"Zbor ne tvrdi da je njegova vlast neupitna, nego mu priznaje pravo da sudi i prijatelju i neprijatelju."},
  "2023_jesen__19": {"A":"Lajev tron je oznaka prijašnje vlasti, a ne metafora za domovinu.","C":"Vatra u ovom govoru nije metafora za domovinu.","D":"Grob se vezuje uz nepokopanoga Polinika, a ne uz domovinu."},
  "2023_jesen__20": {"B":"Tehnike deus ex machina (boga iz stroja) u ovom ulomku nema.","C":"Zbor u ovom dijelu ne najavljuje buduće događaje.","D":"Tragični završetak u Kreontovu uvodnom govoru nije prikazan."},
  "2023_jesen__21": {"A":"Tekst ne objašnjava razvoj obućarske industrije u Varaždinu kao svoju svrhu.","B":"Namjera nije poticanje upisa na Tekstilno-tehnološki fakultet, koji se tek usputno spominje.","C":"Iako objašnjava poneki naziv, svrha teksta nije podučavanje o podrijetlu naziva zanimanja, nego obavještavanje o izložbi."},
  "2023_jesen__22": {"A":"Cilj ciklusa nije da svaka izložba prikaže jedno područje razvoja baš obućarskoga obrta.","C":"Ciklus ne služi prodaji proizvoda lokalnih obrtnika.","D":"Poticanje studenata dizajna na izlaganje nije cilj ovoga niza izložaba."},
  "2023_jesen__23": {"A":"Cipele se nisu uzidavale radi obilježavanja djetetova prohodavanja.","B":"Uzidavanje nije bilo oblik opraštanja od pokojnika.","C":"Svrha uzidavanja nije bila ostavljanje traga budućim naraštajima, nego zaštita od zlih sila."},
  "2023_jesen__24": {"A":"'Železni čovek' ne nalazi se na tavanu barokne kuće.","C":"Riječ je o stvarnom predmetu u gradskoj jezgri, a ne o liku iz filma Vedrana Hunjeka.","D":"'Železni čovek' nije izložak na izložbi o cipelama, nego stoji u središtu grada."},
  "2023_jesen__25": {"B":"Tvrdnja da su se cipele nametnule kao izbor iznosi se kao činjenica, bez izravnoga subjektivnog obraćanja čitatelju.","C":"Objašnjenje tko su djetići činjenični je navod, a ne izraz autorove subjektivnosti.","D":"'Zvali su ga Mali Beč' neutralan je podatak, bez subjektivnoga autorova komentara."},
  "2023_jesen__26": {"A":"U predstavljanju sugovornika nema jezične igre.","B":"Pitanja upućena sugovorniku ne sadrže jezičnu igru.","C":"Poveznica na blog ne sadrži jezičnu igru."},
  "2023_jesen__27": {"A":"Superlativi u predstavljanju ističu sugovornikovu važnost, ali ne stvaraju prisnost.","B":"Pitanja nisu sugestivna, niti je sugestivnost ono čime se postiže prisnost.","D":"Naziv 'knjiški moljac' ime je bloga, a ne sredstvo uspostave prisnosti."},
  "2023_jesen__28": {"B":"Iskaz o neafirmiranim piscima na blogovima pohvala je blogosfere, a ne kritika društva.","C":"Strah od negativnog utjecaja blogova na pismenost kritika je samih blogova, a ne društva koje ih ne podupire.","D":"Opis kako mladi troše vrijeme na blogovske uratke ne kritizira nepodupiranje književnosti od strane društva."},
  "2023_jesen__29": {"A":"Poveznica ne upućuje na podatke o posjećenosti stranice Matice hrvatske.","B":"Poveznica ne otvara prostor za čitateljev komentar.","C":"Poveznica ne otkriva s kojim je tiskanim medijima autor surađivao."},
  "2023_jesen__30": {"A":"Tvrdnja ne govori o tome da ne mora tražiti novčanu potporu za blog.","B":"Sugovornik ne tvrdi da su kritike popularnije od samih književnih djela.","C":"Iskaz se odnosi na posjećenost kao dokaz promicanja književnosti, a ne na afirmaciju mladih proznih pisaca."},
  "2023_jesen__31": {"A":"Hvalisanje nije ono što se ironizira; meta je poniznoga dodvoravanja moćnima.","B":"Lakovjernost nije predmet ironije u navedenim stihovima.","C":"Skromnost se spominje ironično ('skromno'), ali ismijava se ulizivanje, a ne skromnost."},
  "2023_jesen__32": {"A":"Pjesma ne počiva na alegoriji kao cjelovitom prenesenom značenju.","C":"Poredba je tek dio iskaza ('ko Stubički kam'), ali temelj je suprotnost tvrdo–tupo.","D":"Sarkazam je ton, ali stilska figura na kojoj pjesma počiva jest antiteza."},
  "2023_jesen__33": {"B":"Motiv 'neharne gospoje' nije obilježje klasicizma.","C":"Intertekstualna veza nije s romantizmom, nego s renesansnim petrarkizmom.","D":"Realizam nije razdoblje s kojim pjesma uspostavlja vezu motivom nemilosrdne gospođe."},
  "2023_jesen__34": {"A":"Srednjovjekovlju ne odgovaraju katolička obnova i kićenost izraza opisani u rečenici.","C":"Romantizam ne obilježava utjecaj katoličke obnove ni opisana podvojenost svjetovnoga i onostranoga.","D":"Modernizam ne odgovara obilježjima katoličke obnove i baroknoj kićenosti izraza."},
  "2023_jesen__35": {"B":"Socijalno-psihološka motivacija likova obilježje je realizma, a ne romantizma.","C":"Kriterij doličnosti u oblikovanju likova obilježje je klasicizma.","D":"Pluralizam stilova obilježje je modernih razdoblja, a ne hrvatskoga romantizma."},
  "2023_jesen__36": {"A":"Egzistencijalističko pjesništvo ne određuju kult ljepote ni načelo umjetnosti radi umjetnosti.","B":"Ekspresionizam naglašava snažan unutarnji izraz i krik, a ne larpurlartistički kult ljepote.","C":"Petrarkističko pjesništvo definira ljubavni motiv prema gospi, a ne sugestivnost i larpurlartizam."},
  "2023_jesen__37": {"A":"Opis židovske udovice koja ubija vojskovođu odnosi se na Juditu, a ne na Eneidu.","B":"Junak koji se lukavstvom vraća kući nakon deset godina rata jest Odisej iz Odiseje.","D":"Tema o pobuni janjičara veže se uz Osmana, a ne uz Eneidu."},
  "2023_jesen__38": {"A":"Gregor Samsa suočava se s preobrazbom i otuđenjem, a ne s oklijevanjem zbog prevelika promišljanja.","C":"Leone Glembaj obračunava se s obitelji u sukobu, ali ne intelektualizira i odgađa čin kao Raskoljnikov.","D":"Meursault djeluje ravnodušno i bez promišljanja, suprotno Raskoljnikovljevu pretjeranom razmišljanju."},
  "2023_jesen__39": {"A":"Otkrivanje odnosa prema ljubavi i prirodi u pismima prijatelju ne odnosi se na Jurja.","C":"Juraj nije onaj kojega majčino pismo o sestrinoj udaji potiče na daljnje postupke.","D":"Mijenjanje sadržaja Klaudijeva pisma i izbjegavanje smrti ne odnosi se na Jurja Stipančića."},
  "2023_jesen__40": {"A":"Dubravka je pastirska igra s alegorijom slobode, a ne sažeta komedija o seljaku u noćnome gradu.","B":"Judita je biblijski ep, a ne dubrovačka komedija opisana u rečenici.","D":"Osman je barokni ep, a ne komediografsko djelo o naivnu seljaku."},
  "2023_jesen__41": {"A":"Novinar cinik koji prezire napredak nije Maestro, nego drugi lik romana.","B":"Kritičar koji se izgladnjuje da izbjegne vojsku jest Melkior, a ne Maestro.","D":"Boem i lakrdijaš čije se djelovanje svodi na bezrazložni čin nije Maestro."},
  "2023_jesen__42": {"A":"Stihovi ne govore o aginu prisjećanju vlastitih bitaka.","B":"Ne kazuje se da aga ne voli pjesme o stradanju crnogorske vojske.","C":"Aga slušajući pjesmu ne zaboravlja muke, nego smišlja muke kojima bi sačuvao čisto ime."},
  "2023_jesen__43": {"A":"Treba 'brončano doba' malim slovom, pa rečenica nije pravopisno točna.","B":"Treba 'internet' malim slovom, pa zapis nije ispravan.","C":"'Radnu knjižicu' i 'rodni list' treba pisati malim slovom, pa rečenica nije točna."},
  "2023_jesen__44": {"A":"Pravilno je 'zvjezdanoga', a ne 'zvijezdanoga'.","B":"Pravilno je 'sljedeći', a ne 'slijedeći'.","C":"Pravilno je 'savjesna', a ne 'savijesna'."},
  "2023_jesen__45": {"A":"Karaka kao tip broda i naziv Victoria povijesni su podatak (historicizam), a ne arhaizam.","B":"Preparandija je naziv za nekadašnju učiteljsku školu, dakle historicizam, a ne arhaizam.","D":"Dinar kao novčana jedinica Dubrovačke Republike historicizam je, a ne arhaizam."},
  "2023_jesen__46": {"A":"Rečenica o kataklizmičnom ljetu smislena je i nije logički protuslovna.","C":"Rečenica o suši koja smanjuje proizvodnju i pojačava tržišni pritisak smislena je i uzročno povezana.","D":"Rečenica o mogućem kišnom kolovozu i najtoplijem dijelu godine smislena je i nije besmislena."},
  "2023_jesen__47": {"A":"'Jabučni' je pridjev od voća jabuke, a ne ktetik mjesta Jabuka.","C":"'Jabukov' je posvojni pridjev, a ne ktetik (pridjev od naziva mjesta).","D":"'Jabukovački' nije ktetik imena Jabuka."},
  "2023_jesen__48": {"A":"'Imala je madež' predikatno-objektni je spoj, a ne nesročna atributna sintagma.","B":"'Lijevoga ramena' sročni je atribut, slaže se u rodu, broju i padežu.","C":"'Imala je ispod ramena' nije atributna sintagma, nego spoj predikata i priložne oznake."},
  "2023_jesen__49": {"A":"'Na plesu' je lokativ s priložnom službom, a ne izravni objekt.","B":"'O plesu' je lokativ uz glagol sanjariti, a ne izravni objekt.","D":"'Za ples' prijedložni je izraz (namjena), a ne izravni objekt."},
  "2023_jesen__50": {"A":"'S obzirom da' nije pravilno; treba 's obzirom na to da/što'.","B":"'Radi toga jer' nije pravilan veznik; treba 'zbog toga što' odnosno 'jer'.","D":"'Zato jer' nije pravilno; treba 'zato što' ili 'jer'."},
  "2023_jesen__51": {"A":"Treba 'ukus za slikarstvo', a ne 'ukus u slikarstvo', pa rečenica nije točna.","B":"Treba 'vozila se biciklom', bez prijedloga 's', pa rečenica nije gramatički točna.","D":"Treba 'pripada novijem žanru', bez prijedloga 'u', pa rečenica nije točna."},
  "2023_jesen__52": {"A":"Morfem '-telj-' tvori vršitelja radnje (ravnatelj), a ne značenje pripadnosti.","B":"Morfem '-ič-' tvori mociju (ravnateljica), a ne pripadnost.","D":"Nulti morfem nije nositelj značenja pripadnosti u ovoj riječi."},
  "2023_jesen__53": {"B":"Pravilno je 'pekući' (od prezentske osnove pek-), a ne 'pečući'.","C":"Pravilno je 'pišući', a ne 'pisajući'.","D":"Pravilno je 'vukući', a ne 'vučući'."},
  "2023_jesen__54": {"A":"'Najboljim' je u dativu (najboljim studentima), a ne u instrumentalu.","B":"'Hrvatskim' je u lokativu (na hrvatskim sveučilištima), a ne u instrumentalu.","C":"'Tropskim' je u lokativu (u tropskim morima), a ne u instrumentalu."},
  "2023_jesen__55": {"B":"'Biljožder' je složeno-sufiksalna tvorenica, a ne prefiksalno-sufiksalna.","C":"'Bioenergija' je tvorena prefiksoidom (bio-), bez sufiksa, pa nije prefiksalno-sufiksalna.","D":"'Brodolomac' je složeno-sufiksalna tvorenica, a ne prefiksalno-sufiksalna."},
  "2023_jesen__56": {"A":"U 'izmišljen' ljelina nije epentetsko l, nego rezultat jotacije (sl > šlj).","C":"U 'usamljen' lj je rezultat jotacije (ml), a ne epentetsko l.","D":"U 'zaobljen' lj je rezultat jotacije (bl), a ne epentetsko l."},
  "2023_jesen__57": {"A":"'im. m G -bra, N mn -bri' morfološka je, a ne etimološka odrednica.","B":"'arh. jez. knjiž. knjiga' stilska je odrednica i definicija, a ne podatak o podrijetlu riječi.","D":"Navod o zatvaranju grilja frazeološki je primjer uporabe, a ne etimološka odrednica."},
  "2023_jesen__581": {"B":"'Baciti pijesak u oči' znači obmanuti nekoga, što ne odgovara izazovu nadutosti.","C":"'Doliti ulje na vatru' znači pojačati sukob, a ne suprotstaviti se nadutosti izazovom.","D":"'Baciti bubu u uho' znači potaknuti sumnju ili nemir, a ne baciti izazov."},
  "2023_jesen__582": {"A":"'Mila' nije pravilan genitiv imena 'Mile' koje se sklanja po e-deklinaciji.","B":"'Mile' je nominativni oblik, a ne genitiv.","C":"'Milea' nije pravilan genitiv imena 'Mile'."},
  "2023_jesen__583": {"A":"'Naručbu' nije pravilan zapis; ispravno je 'narudžbu'.","B":"'Narućbu' nije pravilan zapis; ispravno je 'narudžbu'.","D":"'Naruđbu' nije pravilan zapis; ispravno je 'narudžbu'."},
  "2023_jesen__584": {"A":"'Elektrićke' nije pravilan oblik pridjeva za vrstu pošte.","B":"'Električne' opisuje ono što je vezano uz električnu struju, a ne e-poštu.","C":"'Elektroničke' u kontekstu skraćenice e-pošte nije traženi oblik koji odgovara zadatku."},
  "2023_jesen__585": {"A":"'Istače' nije pravilan oblik glagola za trajanje akcije.","B":"'Isteče' je svršeni oblik (isteći), a ne traženi prezent u značenju da akcija vrijedi do petka.","D":"'Istječe' nije pravilan oblik za ovaj kontekst; treba 'ističe'."},

  // 2023_ljeto
  "2023_ljeto__1": {"A":"Đuka im ne zamjera razgovor na ulici, nego prazan život bez vlastite volje.","C":"Razuzdanost im nije zamjerka, već upravo nedostatak samosvojnosti i smjelosti.","D":"Siromaštvo nije predmet njegova prijekora, nego njihova nesamostalnost i oponašanje drugih."},
  "2023_ljeto__2": {"B":"Izreka ne govori o bolesti, nego o vrijednosti polaznoga materijala.","C":"Riječ nije o obnavljanju staroga, nego o tome da loš temelj ne daje dobar rezultat.","D":"Tvrdoglavost nije tema poslovice; ona govori o kakvoći onoga iz čega se nešto stvara."},
  "2023_ljeto__3": {"A":"Đuka suseljane prijekorno korí, a ne poučava ih kako trošiti novac.","B":"Njemu nije stalo do prihvaćanja sredine, nego upravo do neovisnosti o selu i ljudima.","C":"U ulomku ne osuđuje oca, nego pasivnost i povodljivost suseljana."},
  "2023_ljeto__4": {"A":"Likove ne obilježavaju retorička pitanja, nego osobit slavonski govor.","B":"Nema novotvorenica, već uvriježenih dijalektnih riječi tamošnjega kraja.","D":"Umanjenice nisu nositelj govorne karakterizacije; to su dijalektizmi poput 'bajagi' i 'škuda'."},
  "2023_ljeto__5": {"A":"To je Đukina izreka, a ne reakcija suseljana koja bi odavala da osjećaju istinu.","B":"Niz pogrdnih naziva Đukino je vrijeđanje, a ne pokazatelj da starci priznaju istinitost.","C":"I to je Đukin prijekor, a ne opis reakcije staraca na njegove riječi."},
  "2023_ljeto__6": {"A":"Susret s vampirom Kamenski tek zamišlja kasnije; nije razlog njegova iznenađenja.","B":"Tekst ne spominje ubojičinu nespretnost tijekom čina.","C":"Nema spomena povratka kući po oružje kao uzroka čuđenja."},
  "2023_ljeto__7": {"B":"Vampir je samo slika kojom Kamenski doživljava učiteljičine oči, a ne osoba s kojom Š. se susreće.","C":"Susret sa starcem u ulomku se ne zamišlja.","D":"Majka je tek prenijela vijest pismom; Kamenski ne zamišlja Š.-ov susret s njom."},
  "2023_ljeto__8": {"A":"Veznik 'kao' otkriva poredbu, a ne metaforu.","B":"Riječ je o doslovnu opisu lika, bez prenesena značenja.","C":"Trzanje za kosu doslovan je opis radnje, ne metafora."},
  "2023_ljeto__9": {"A":"Želja za dokazivanjem pred nepoznatima vodi konvencionalnoj, slabijoj svirci.","B":"Društvo aristokrata nije uvjet u kojem najbolje svira.","C":"Pred publikom na koncertima svira suzdržanije i lošije."},
  "2023_ljeto__10": {"A":"Kamenskoga ne poziva gospođa osobno, nego ga predstavlja bankar.","C":"Tekst ne navodi da su se upoznali u Zagrebu.","D":"Kamenski ne odbija susret s gospođom; do susreta dolazi."},
  "2023_ljeto__11": {"A":"Imperativi se ne ponavljaju kao sredstvo iskazivanja osjećaja.","C":"Bog se u ulomku ne apostrofira.","D":"Retorička pitanja nisu nositelj dječakove nježnosti; to su umanjenice."},
  "2023_ljeto__12": {"A":"Rečenica ne govori o moralnim načelima lika.","B":"Nema govornih obilježja jer to nije lik koji govori.","D":"Nema obilježja društvenoga položaja, nego tjelesnih znakova unutarnjega stanja."},
  "2023_ljeto__13": {"B":"Drhtanje ne izaziva hladnoća, nego potreseno duševno stanje.","C":"Raskoljnikov u tom trenutku nije pretučen.","D":"Drhtaj nije znak ljutnje, nego izbezumljenosti i straha."},
  "2023_ljeto__14": {"A":"San je djetinja uspomena, ali ne sugerira da je Raskoljnikov postao ubojica zbog nasilja nad njim.","C":"San nije izraz tugovanja za izgubljenim konjem.","D":"Težište nije na uspomenama na oca, nego na pobuni savjesti protiv okrutnosti."},
  "2023_ljeto__15": {"A":"Razgovor s Porfirijem Petrovičem zbiva se kasnije i nije ta 'proba'.","B":"Priznanje Sonji nije 'proba', nego kasniji čin priznanja.","D":"S Lužinom se Raskoljnikov ne upoznaje u kontekstu te 'probe'."},
  "2023_ljeto__16": {"A":"Hamlet ne žudi za istinom, nego za nestankom i smrću.","B":"U tim stihovima nema čežnje za ljubavlju.","D":"Vlast nije predmet njegove žudnje; želi se rasplinuti, prestati postojati."},
  "2023_ljeto__17": {"A":"Vrt nije slika svijeta u koji odlaze samoubojice.","B":"Nije riječ o doslovnu neobrađenu vrtu, nego o metafori za svijet.","D":"Slika nije doslovan zapušten vrt, nego preneseno označuje svijet u kojem se živi."},
  "2023_ljeto__18": {"B":"Herkul se spominje tek kao mjera usporedbe, a ne kao počinitelj rodoskvrnuća.","C":"Nioba je slika tugovanja, a ne osoba koja je počinila rodoskvrnuće.","D":"Ofelija nije počinitelj; rodoskvrnuće Hamlet pripisuje majci."},
  "2023_ljeto__19": {"A":"Pozdrav Bernardu izrečen je iskreno, bez ironijskoga obrata.","B":"Rečenica o navikavanju na piće šaljiva je, ali bez ironijskoga proturječja.","D":"'U oku svog duha' slikovit je izraz, a ne ironija."},
  "2023_ljeto__20": {"A":"Hamlet ne govori o ženskoj taštini ni ljepoti.","B":"'Krhkost' označuje moralnu, a ne tjelesnu slabost.","D":"Nije riječ o ženskoj potrebi za zaštitom, nego o njihovoj nestalnosti i povodljivosti."},
  "2023_ljeto__21": {"B":"Tekst ne dokazuje da Hrvatska baca manje hrane od Europe.","C":"Kupnja od hrvatskih proizvođača tek je primjer, a ne svrha teksta.","D":"Zbrinjavanje otpada spominje se usput; cilj je poticaj na održivu potrošnju."},
  "2023_ljeto__22": {"B":"Udio lokalnih proizvoda nije naveden kao zadani cilj do kraja 2020.","C":"Cilj nije povećanje neobnovljivih izvora, što bi bilo suprotno održivosti.","D":"Cilj se ne odnosi na vjetar i sunce, nego na recikliranje i kompostiranje."},
  "2023_ljeto__23": {"A":"U recikliranju Hrvatska zaostaje za zadanim ciljem, nije iznad prosjeka.","C":"Tekst ne navodi nadprosječnost u smanjivanju pretilosti.","D":"Javnozdravstvene usluge nisu područje u kojem je Hrvatska iznad svjetskoga prosjeka."},
  "2023_ljeto__24": {"A":"Geotermalna energija nije najzastupljeniji obnovljivi izvor.","B":"Sunčeva energija nije navedena kao najupotrebljavanija.","C":"Energija vjetra nije vodeći obnovljivi izvor; to je energija iz hidroelektrana."},
  "2023_ljeto__25": {"B":"Podatak o količini bačene hrane činjenica je, a ne autoričin stav.","C":"Navod o Vladinu planu objektivna je informacija, ne mišljenje.","D":"Rečenica o javnozdravstvenom problemu iznosi činjenicu, a ne osobni stav."},
  "2023_ljeto__26": {"A":"Tekst ne uspoređuje iskusnoga i neiskusnoga hodača kao svrhu, nego daje upute.","C":"Tekst ne dokazuje učestalost ozljeda, nego poučava o kretanju.","D":"Brzo penjanje do vrha nije svrha; tekst savjetuje promišljen tempo i opremu."},
  "2023_ljeto__27": {"A":"Bol u nogama nije naveden kao uzrok žuljeva.","B":"Propuštanje vode kroz gojzerice nije navedeni uzrok žuljeva.","C":"Nekoliko pari čarapa nije naveden uzrok žuljeva; uzrok su nerazgažene gojzerice."},
  "2023_ljeto__28": {"A":"Tumačenje oznaka na stazi posao je vodiča, a ne metle.","B":"Prikupljanje smeća nije zadaća metle.","C":"Sigurnost staze nije opisana kao briga metle, nego skrb za zaostale."},
  "2023_ljeto__29": {"A":"Drugo lice jednine ne stvara kritički ton prema početnicima.","B":"Izravno obraćanje stvara bliskost, a ne objektivnu distancu.","C":"Slikovitost opisa nije učinak uporabe drugoga lica jednine."},
  "2023_ljeto__30": {"B":"Humor ne počiva na paradoksu.","C":"Fizikalni pojmovi nisu izvor humora u tom ulomku.","D":"Humor ne nastaje iz tumačenja uzroka i posljedice, nego iz igre riječima."},
  "2023_ljeto__31": {"A":"'Čaše' su upotrijebljene u doslovnu značenju, bez metonimijskoga prijenosa.","B":"'Utažio' je doslovan glagol, ne nositelj metonimije.","D":"'Kuće' nemaju metonimijsko značenje u ovom primjeru."},
  "2023_ljeto__32": {"B":"Petrarkistički osmerac/dvanaesterac nije bugarštički dugi stih.","C":"Stih o Slavoniji epsko je domoljubno štivo, ne bugarštica.","D":"Stihovi nemaju dugi bugarštički stih ni karakterističan pripjev."},
  "2023_ljeto__33": {"A":"Himna nije vrsta kojoj Aristotel pripisuje katarzu.","B":"Elegiji se ne pripisuje katarzični učinak.","C":"Ep ne izaziva katarzu u Aristotelovu smislu; to čini tragedija."},
  "2023_ljeto__34": {"A":"Tiskanje Enciklopedije obilježje je prosvjetiteljstva, ne renesanse.","B":"Versailles i Luj XIV. pripadaju klasicizmu, a ne renesansi.","C":"Katolička obnova i naglasak na prolaznosti obilježja su baroka."},
  "2023_ljeto__35": {"B":"Romantizam ne nastaje između renesanse i klasicizma.","C":"Realizam je razdoblje 19. stoljeća, ne ono između renesanse i klasicizma.","D":"Modernizam vremenski ne odgovara opisanu razdoblju."},
  "2023_ljeto__36": {"B":"Stilski pluralizam nije obilježje na koje upućuju poema i epistolarni roman.","C":"Kriterij doličnosti pripada klasicizmu, ne romantizmu.","D":"Načelo tipičnosti obilježje je realizma, a ne romantičarske lirizacije."},
  "2023_ljeto__37": {"A":"Suprotnost dana i noći nije temelj značenja tih stihova.","B":"Odnos lovca i lovine nije nosiva antiteza ovih stihova.","D":"Suprotnost smiješnoga i ozbiljnoga nije antiteza na kojoj počiva smisao."},
  "2023_ljeto__38": {"B":"Neopetrarkistički odnos prema ženi nije obilježje Kranjčeve poetike.","C":"Simbolika boja ne karakterizira Kranjčevu liriku.","D":"Veza zla i ljepote nije težište Kranjčeva pjesništva."},
  "2023_ljeto__39": {"A":"Ulomak nije iz Hamleta, nego ga Kiklop parodijski preuzima.","C":"Likovi i ton ne pripadaju Strancu.","D":"Ulomak nije iz Zločina i kazne; riječ je o Marinkovićevu Kiklopu."},
  "2023_ljeto__40": {"A":"Sigismund i Klarin nisu Sofoklovi likovi.","B":"Shakespeare nije autor djela s tim likovima.","D":"Goethe nije autor Života je san; to je Calderón de la Barca."},
  "2023_ljeto__41": {"A":"Ante Stipančić nije lik koji mijenja politička uvjerenja radi sinova školovanja.","B":"Don Fernando ne odgovara opisu mijenjanja uvjerenja iz koristoljublja.","C":"Ignjat Glembay nije lik na koji se odnosi taj opis."},
  "2023_ljeto__42": {"A":"Renesansna književnost nije meta te kritike.","B":"Barokna književnost nije predmet ovog ismijavanja.","D":"Realistička književnost ne odgovara opisanim sentimentalnim klišejima; oni su romantičarski."},
  "2023_ljeto__43": {"A":"Pravilno je 'bescarinska' jer se z ispred c jednači u s.","C":"Pravilno je 'beskofeinska' zbog jednačenja po zvučnosti.","D":"Oblik 'bestežinsko' nije pravopisno točan u zadanom obliku."},
  "2023_ljeto__44": {"A":"'Knez Trpimir' piše se malim 'knez' jer je opća imenica uz vlastito ime.","C":"Pridjev 'hrvatsko-ugarskoga' uz titulu piše se malim slovom.","D":"Naziv stilskoga razdoblja 'barok' piše se malim slovom."},
  "2023_ljeto__45": {"A":"'Nemotiviraniji' nije značenjska suprotnost stručnoj osposobljenosti.","C":"'Neučinkovitiji' nije izravan antonim riječi 'kompetentan'.","D":"'Nezainteresiraniji' označuje nezanimanje, a ne nesposobnost."},
  "2023_ljeto__46": {"B":"'Kontrastno' ne odgovara značenju 'minuciozno'.","C":"'Proporcionalno' nije značenje riječi 'minuciozno'.","D":"'Skladno' nije značenje pridjeva 'minuciozno', koji znači potanko."},
  "2023_ljeto__47": {"A":"Poslovica o vuku i dlaci govori o nepromjenjivosti naravi, ne o izostanku posljedica.","B":"Izreka o lisici i vuku znači da se izbjegavanjem manje nevolje upada u veću.","C":"'I vuci siti i ovce na broju' znači zadovoljiti obje strane, a ne izostanak posljedica."},
  "2023_ljeto__48": {"A":"'Kutija za cipele' atributna je (namjenska) sintagma, ne objektna.","B":"'Hodati unatrag' priložna je (adverbijalna) sintagma.","D":"'Plavo nebo' atributna je sintagma, a ne dopunska/objektna."},
  "2023_ljeto__49": {"A":"Rečenica s 'da ne bi štetio' namjerna je, a ne subjektna.","B":"'Da je pušenje štetno' ovdje je atributna (objasnidbena uz imenicu kampanja).","C":"'Da pušenje šteti zdravlju' objektna je rečenica (znati što)."},
  "2023_ljeto__50": {"A":"Rečenica s 'jer se trudiš, uspjet ćeš' uzročna je, a ne pogodbena preoblika.","B":"'Toliko se trudiš da ćeš uspjeti' posljedična je rečenica.","D":"'Iako se trudiš' dopusna je rečenica, a značenjski je suprotna izvorniku."},
  "2023_ljeto__51": {"A":"Pravilno je 'traže od mene pomoć', a ne 'traže mi pomoć'.","B":"Pravilno je 'ne marimo za nju i njezin vrt' (za + akuzativ).","C":"Pravilno je 'rugala mu se' jer glagol traži povratnu zamjenicu i dativ."},
  "2023_ljeto__52": {"A":"'Aktovima' je u instrumentalu (predstavio aktovima).","B":"'Godinama' je u lokativu uz prijedlog 'u'.","D":"'Obitelji' je u lokativu uz prijedlog 'o'."},
  "2023_ljeto__53": {"A":"Pravilan je oblik 'najgorčije', a ne 'najgorkije'.","B":"Pravilno je 'najtjesnijem', a ne 'najtješnjemu'.","D":"Pravilno je 'najvišeg', a ne 'najvišljijega'."},
  "2023_ljeto__54": {"A":"'Navrijeme' je prilog, a ne prijedlog.","B":"'Iako' je dopusni veznik.","C":"'Nebrojene' je pridjev, ne prijedlog."},
  "2023_ljeto__55": {"A":"'Školski' je izveden od imenice 'škola'.","D":"'Građevinar' je izveden od imenice 'građevina'."},
  "2023_ljeto__56": {"B":"U 'kocka → kocki' sibilarizacija izostaje zbog suglasničke skupine.","C":"U 'luka → luci' sibilarizacija se provodi, ali ključ navodi A kao traženo rješenje.","D":"U 'lutka → lutki' sibilarizacija se ne provodi."},
  "2023_ljeto__57": {"A":"Baščanska ploča kameni je glagoljski spomenik s Krka, a ne zbornik običajnoga prava iz 1288.","B":"Misal po zakonu rimskoga dvora prva je hrvatska tiskana knjiga, ne pravni zbornik.","C":"Povaljska listina darovnica je s Brača, a ne zakonik o odnosima s krčkim knezovima."},
  "2023_ljeto__58.1": {"A":"Oblik '15-i lipanj' nije pravopisno ispravan zapis datuma.","B":"'15. lipanj' u nominativu ne odgovara sintaktičkoj vezi u rečenici.","D":"'15 lipnja' bez točke iza broja pravopisno je neispravno."},
  "2023_ljeto__58.2": {"B":"'Pogotovo' pojačava, a ne uvodi suprotnost potrebnu u rečenici.","C":"'Štoviše' dodatno stupnjuje tvrdnju, ne izriče suprotnost.","D":"'Točnije' uvodi pojašnjenje, a ne suprotni obrat misli."},
  "2023_ljeto__58.3": {"A":"'Grižnjom savješću' u instrumentalu ne odgovara službi subjekta uz 'muči'.","B":"'Grižnja savješću' miješa padeže i nije ispravna sveza.","D":"'Grižnja savjest' nije ispravna jer druga imenica mora biti u genitivu."},
  "2023_ljeto__58.4": {"A":"'Zbog toga jer' pleonastičan je i nestandardan izraz.","B":"'Radi toga što' pogrešno upotrebljava namjerni 'radi' u uzročnom značenju.","C":"'Zato jer' nestandardno je udvostručivanje uzročnih veznika."},
  "2023_ljeto__58.5": {"A":"'Budem počeo' kondicionalno-pretpostavni oblik nije primjeren ovom kontekstu.","C":"'Početi ću' krši pravilo o redoslijedu pomoćnoga glagola u futuru.","D":"'Ću počet' nestandardan je oblik s krnjim infinitivom i pogrešnim redoslijedom."},

  // 2024_jesen
  "2024_jesen__1": {"A":"Lirski subjekt ne teži ostvarenju snova iz djetinjstva, nego se vraća u zavičaj kako bi u njemu dočekao smrt.","C":"U pjesmi nema riječi o borbi za imanje, nego o povratku rodnomu kraju pred smrt.","D":"Subjekt smrt mirno prihvaća i očekuje ('časak smrtni ja ću dočekati'), pa nije riječ o strahu od smrti."},
  "2024_jesen__2": {"B":"Tvrdnja se odnosi na lirski subjekt jer 'sa duga puta ja vam dođoh' potvrđuje da je putovao i napustio rodni kraj.","C":"Tvrdnja se odnosi na subjekt jer 'u krevet leć ću što se ù njem rodih' pokazuje da će umrijeti u zavičaju.","D":"Tvrdnja se odnosi na subjekt jer masline, žalo i mediteranski krajolik upućuju na njegovo mediteransko podrijetlo."},
  "2024_jesen__3": {"B":"Eufemizam je ublažavanje neugodna pojma, čega u obraćanju maslinama nema.","C":"Gradacija je postupno stupnjevanje, a ovdje nema nizanja po jačini.","D":"Hiperbola je pretjerivanje, što izostaje u stihovima o maslinama."},
  "2024_jesen__4": {"A":"Stihovi ne govore o tome da je otac obrao i posljednju granu, nego o svjetlu koje je ulje davalo.","B":"Nije riječ o svjetlucanju maslina na suncu, nego o ulju kao izvoru svjetla.","D":"Stihovi ne opisuju branje maslina u mraku, nego ulje koje je osvjetljavalo zimske noći."},
  "2024_jesen__5": {"A":"Masline ne simboliziraju težak život subjekta, nego trajnu vezu naraštaja.","C":"Masline nisu simbol nadolazeće starosti, nego kontinuiteta djeda, oca i sina.","D":"Masline se ne povezuju s krštenjem, nego s obiteljskim naslijeđem kroz generacije."},
  "2024_jesen__6": {"A":"Krele upravo odbacuje ponos i dostojanstvo kao nevažne ('šta, da budem ponosan?'), pa to nije njegova filozofija.","C":"Krele ne ističe obrazovanje kao temelj dobra života, nego puko preživljavanje.","D":"Krele ne zagovara zabavu kao životno načelo, nego očuvanje 'živih kostiju' u teškom vremenu."},
  "2024_jesen__7": {"B":"Čičak se ne okomljuje zbog Melkiorova odbijanja hrane, nego zbog njegove intelektualne nadmoći.","C":"Razlog nije prijateljstvo Melkiora i Krele, nego Melkiorov um koji nadvisuje Čička.","D":"Melkior Čičku ne prkosi; problem je u njegovoj učenosti, a ne u izazivanju."},
  "2024_jesen__8": {"B":"Izraz se ne odnosi na oponašanje pasa, nego na iskustvo siromaštva ('škola zakrpljene zadnjice').","C":"Izraz nema veze s arheologijom, nego s preživljenim siromaštvom.","D":"Nije riječ o formalnom obrazovanju, nego ironično o 'školi' siromaštva koju Čičak nije prošao."},
  "2024_jesen__9": {"B":"Krele se zbog nadimka ne ljuti, nego ga prihvaća kao korisnu etiketu.","C":"Krele se nadimkom ne ponosi; izričito odbacuje ponos kao nevažan.","D":"Krele se nadimka ne srami, nego ga svjesno koristi jer mu je 'koristan'."},
  "2024_jesen__10": {"B":"Rečenica nije izgovorena ljutito, nego ironično o apsurdnosti 'satisfakcije' nakon smrti.","C":"Ton nije rezigniran, nego ironičan i podrugljiv.","D":"Rečenica nije tužna, nego gorko ironična."},
  "2024_jesen__11": {"A":"Gospođa Goupil je susjeda i poznanica tetke, a ne pripovjedačeva rodbina.","B":"Gospođa Imbert spominje se samo kao prolaznica, bez ikakve rodbinske veze s pripovjedačem.","D":"Gospođa Rousseau navodi se kao primjer pokojnice, a ne kao pripovjedačeva rođakinja."},
  "2024_jesen__12": {"A":"Tetki pripovijedanje o nesrećama ne smeta; upravo ona prenosi vijesti i tračeve.","B":"U tekstu nema spomena da joj se dijete razboljelo.","D":"Ništa ne upućuje na to da tetka slabo čuje; ona aktivno razgovara i sluša novosti."},
  "2024_jesen__13": {"B":"Françoise joj svakodnevno donosi lijek za probavu, što nije izvanredan razlog za raniji poziv.","C":"Zvono s crkve nije razlog ranijega poziva Françoise.","D":"Glad nije navedena kao razlog zbog kojega tetka prije vremena zove Françoise."},
  "2024_jesen__14": {"A":"Žena za kojom je zvonilo mrtvačko zvono nije ona viđena s nepoznatom djevojčicom.","C":"Žena koja je nosila velike šparoge (gospođa Imbert) nije ta koja je viđena s curicom.","D":"U tekstu nema žene koja je otišla po liječnika u vezi s nepoznatom djevojčicom."},
  "2024_jesen__15": {"A":"Riječ je o izravnoj, doslovnoj tvrdnji o lošim šparogama, bez ironijskoga preokreta značenja.","B":"Rečenica je obična izjava o pregledu vatre, bez ironije.","D":"Pitanje 'Da vam nije zlo?' iskaz je brige, a ne ironija."},
  "2024_jesen__16": {"A":"Polonije ne govori o roditeljskoj dužnosti prema sinu, nego traži uzrok Hamletova stanja.","C":"Cilj mu nije dokazati da je dobar otac, nego objasniti razlog Hamletova 'ludila'.","D":"Polonije ne nastoji opravdati Ofeliju, nego ljubav predstaviti kao uzrok Hamletova ponašanja."},
  "2024_jesen__17": {"A":"Kraljica ne ocjenjuje kraljevu vještinu vladanja, nego prekida Polonijevo okolišanje.","B":"Riječi se ne odnose na procjenu Hamletovih sposobnosti, nego na Polonijev način govora.","C":"Kraljica ne iznosi shvaćanje ludila, nego traži da Polonije prijeđe na bit."},
  "2024_jesen__18": {"A":"Kraljica nije upozorila Polonija na ljubav; on ju je sam primijetio prije kćerina priznanja.","B":"Hamlet se nije povjerio Poloniju; izvor mu je vlastito opažanje i Ofelijino pismo.","C":"Polonije za ljubav nije doznao od kralja, nego ju je sam opazio."},
  "2024_jesen__19": {"B":"Izraz ne govori o Ofelijinu idealiziranju Hamleta, nego o razlici društvenoga položaja.","C":"'Iznad tvoje zvijezde' ne znači da je Hamlet zaštitnik, nego da je staleški iznad Ofelije.","D":"Izraz ne kaže da Hamlet ne mari za Ofeliju, nego da je ona ispod njegova staleža."},
  "2024_jesen__20": {"A":"Polonije se na Ofeliju ne ljuti zbog neposlušnosti; naprotiv, naziva je 'savjesnim i poslušnim djetetom'.","B":"Polonije Ofeliji ne traži supruga, nego nastoji rastumačiti Hamletovo ponašanje.","C":"Polonije ne štiti Ofelijinu privatnost; štoviše, javno čita njezino pismo pred kraljem."},
  "2024_jesen__21": {"A":"Tekst nije usredotočen na smanjenje kazne za priznanje zločina, nego na korist suradnje.","B":"Cilj nije pokazati kako ponašanje životinja utječe na ljude, nego promicati suradnju kao strategiju.","C":"Tekst ne izražava nepovjerenje u znanost, nego se na nju oslanja da bi prikazao prednosti suradnje."},
  "2024_jesen__22": {"A":"Preporuka nije nepriznavanje kad drugi prizna, nego početna suradnja i potom uzvraćanje istom mjerom.","B":"Strategija ne nalaže opraštanje suradnje s istražiteljem, nego početnu suradnju s drugim zatvorenikom.","D":"Strategija nije bezuvjetno odbijanje priznanja, nego suradnja na početku i reakcija na suparnikove poteze."},
  "2024_jesen__23": {"A":"Odnos žderač – klopa nije suprotnost sebičnosti, nego primjer uobičajene predatorske interakcije.","C":"Svjedok pokajnik dio je primjera dileme zatvorenika, a ne pojam suprotstavljen sebičnosti.","D":"Zločin je element ilustrativnoga primjera, a ne pojam suprotstavljen tezi o sebičnosti."},
  "2024_jesen__24": {"A":"Administrativni stil obilježavaju ustaljeni obrasci i formalnost, kojih u ovom razgovornom i šaljivom tekstu nema.","B":"Tekst nije književnoumjetnički jer prenosi znanstvene spoznaje, a ne umjetnički doživljaj.","D":"Iako sadrži razgovorne izraze, tekst nije čisto razgovorni jer obrađuje znanstvenu temu za širu publiku."},
  "2024_jesen__25": {"A":"Autor se služi stručnim biološkim pojmovima (simbioza, rizobija), pa se taj izraz koristi u tekstu.","B":"Autor upotrebljava engleske izraze (tit for tat), pa se i njima koristi u tekstu.","D":"Autor rabi žargonizme ('skužili smo', 'štreberi'), pa se i njima koristi u tekstu."},
  "2024_jesen__26": {"B":"Tekst nije usmjeren na opasnosti nesvježe ribe, nego na prepoznavanje svježine i pripremu.","C":"Tekst ne opisuje vrste riba s tržišta kao glavnu svrhu, nego poučava o kupnji i kuhanju.","D":"Tekst ne promiče ribu kao dio zdrave prehrane, nego daje praktične upute za odabir i pripremu."},
  "2024_jesen__27": {"A":"Futur I. nije tipičan za upute; recepti i savjeti izriču se zapovjednim načinom.","C":"Kondicional I. izriče mogućnost i nije karakterističan za upućivačke tekstove.","D":"Iako se prezent javlja, za upute (recepte) tipičan je imperativ ('pogledajte', 'pripremite')."},
  "2024_jesen__28": {"A":"Dignute ljuske znak su nesvježe ribe; kod svježe one dobro prianjaju uz tijelo.","C":"Mršavost mesa odnosi se na vrstu ribe, a ne na svježinu.","D":"Otvorene škržne pločice znak su stare ribe, a ne svježe."},
  "2024_jesen__29": {"A":"Court-bouillon nije knjiga recepata, nego začinjeni temeljac za kuhanje ribe.","B":"Court-bouillon nije lonac, nego aromatizirana tekućina u kojoj se riba kuha.","C":"Court-bouillon nije sorta vina; vino je tek jedan od njegovih sastojaka."},
  "2024_jesen__30": {"A":"Za rakove se ne kaže da trebaju odstajati prije pripreme, nego da se kuhaju vrlo kratko.","B":"U tekstu nema podatka da rakovi moraju biti obloženi algama.","D":"Tekst ne tvrdi da rakove nije lako nabaviti, nego objašnjava kako ih kratko kuhati."},
  "2024_jesen__31": {"A":"Stih iznosi sliku neprekinutoga lanca srca bez miješanja osjetilnih podražaja, pa nije sinestezija.","B":"'Grohot' i 'smiju se' zvukovni su motivi bez spajanja različitih osjetila.","D":"Slika 'kletve kao jeke' temelji se na zvuku, bez prožimanja osjetilnih dojmova."},
  "2024_jesen__32": {"B":"Kulminacija je vrhunac dramske napetosti, a ne posljednja scena drame.","C":"Peripetija je obrat u radnji, a ne završni dio drame.","D":"Prolog je uvodni, a ne posljednji dio drame."},
  "2024_jesen__33": {"A":"Pjevač ne traži pobjedu Ahejaca, nego nadahnuće za pjevanje epa.","C":"Invokacija nije molba da se Ahilej prestane ljutiti, nego zaziv muze za nadahnuće.","D":"Pjevač ne moli zaštitu za Ahileja, nego pomoć da opjeva njegovu srdžbu."},
  "2024_jesen__34": {"A":"Deus ex machina je iznenadno razrješenje vanjskom intervencijom, a ne temelj komičkoga zapleta.","B":"In medias res je započinjanje radnje u sredini zbivanja, a ne komički postupak zamjene.","C":"Mimesis je oponašanje stvarnosti, opći pojam, a ne osnova komičnoga zapleta."},
  "2024_jesen__35": {"A":"Antigona se ne pojavljuje prerušena u mušku odjeću.","B":"Dubravka se ne pojavljuje u muškom ruhu na početku drame.","C":"Ofelija se ne prerušava u muškarca."},
  "2024_jesen__36": {"A":"Barunica Castelli lik je iz Gospode Glembajevih i ne izgovara ove riječi o uzama i tijesnim zidovima.","B":"Lotta nije lik koji piše Alfredu o svojoj zatočenosti.","D":"Vivijana nije govornica ovih riječi upućenih Alfredu."},
  "2024_jesen__37": {"A":"Oličenje tjelesnoga i erosa bez moralne odgovornosti ne opisuje Izabelu na taj način kao tajanstvenu glazbenicu iz Beča.","B":"Izabela nije lik zakinut patrijarhalnim odgojem za bratova prava.","C":"Izabela nije neiskusna djevojka zaljubljena u nepoznatoga fotografa."},
  "2024_jesen__38": {"A":"Leone iz Gospode Glembajevih moderni je, ekspresionistički lik, a ne romantičarski.","B":"Miljenko iz Dubravke pripada baroknom pastoralnom svijetu, a ne romantizmu.","D":"Stanac iz Novele od Stanca renesansni je komički lik, a ne romantičarski."},
  "2024_jesen__39": {"A":"Barok obilježava začudnost i raskoš, a ne težnja iluziji zbilje i spoznajnoj ulozi znanosti.","B":"Klasicizam naglašava razum i pravila, a ne mimetičko stvaranje iluzije stvarnosti znanstvenoga tipa.","C":"Romantizam ističe osjećaje i subjektivnost, a ne objektivno oponašanje zbilje."},
  "2024_jesen__40": {"A":"Antun Branko Šimić obilježen je slobodnim stihom i ekspresionizmom, a ne sonetom i neopetrarkizmom.","B":"Ivan Mažuranić poznat je po epu Smrt Smail-age Čengića, a ne po sonetima i kozmičkim motivima.","D":"Vladimir Nazor njeguje mediteranske i nacionalne motive, a ne neopetrarkističke sonete s kozmičkom tematikom."},
  "2024_jesen__41": {"A":"Uvodni sonet Petrarcina Kanconijera ne sadrži motiv 'očiju punih čuđenja' s kojim bi se stih povezao.","B":"Kranjčevićev Mojsije ne donosi motiv koji bi se podudarao s 'očima punim čuđenja'.","C":"Baudelaireov Albatros govori o pjesniku-pticama, ali ne preko motiva 'očiju punih čuđenja'."},
  "2024_jesen__42": {"A":"Deskriptivnost je svojstvo realizma i naturalizma, a ne klasicizma.","B":"Ekspresivnost obilježava ekspresionizam, a ne klasicizam.","D":"Subjektivnost je značajka romantizma, a ne klasicizma usmjerenoga na razum i moral."},
  "2024_jesen__43": {"A":"Rečenica je pogrešna jer treba 'Europsko vijeće' i 'Europska komisija' velikim početnim slovom.","C":"Rečenica je pogrešna jer latinske vrste 'Viola odorata' i 'Viola tricolor' traže veliko početno slovo rodnoga imena.","D":"Rečenica je pogrešna jer se 'karolinška renesansa' piše malim slovima."},
  "2024_jesen__44": {"B":"'Pogoditi u dlaku točno' znači biti potpuno precizan, a ne slobodno govoriti mišljenje.","C":"'Tražiti dlaku u jajetu' znači biti sitničav i prigovarati, a ne otvoreno govoriti.","D":"'Ići komu niz dlaku' znači udovoljavati nekomu, a ne bez ustručavanja iznositi mišljenje."},
  "2024_jesen__45": {"A":"'Ivan je gledao' veza je subjekta i predikata (otvaranje mjesta), a ne pridruživanje.","B":"'Je netremice gledao' prilog uz glagol primjer je upravljanja/priložne veze, a ne sročnoga pridruživanja.","C":"'Je gledao u oči' glagol s prijedložnim izrazom rezultat je rekcije, a ne pridruživanja."},
  "2024_jesen__46": {"A":"U toj rečenici 'cvijeće' je imenski dio predikata, a ne atribut.","B":"U toj rečenici 'cvijeće' je u službi subjekta ('Cvijeće cvijetu'), a ne atributa.","D":"U toj rečenici 'cvijećem' je priložna oznaka/objekt uz glagol 'obasipao', a ne atribut."},
  "2024_jesen__47": {"A":"'Ako dođeš i ti' izriče uvjet, pa je riječ o pogodbenoj, a ne namjernoj rečenici.","B":"'Tamo gdje ćeš biti ti' izriče mjesto, pa je to mjesna, a ne namjerna rečenica.","D":"'Da ću ti doći' dopunjuje glagol 'znaš', pa je riječ o izričnoj (objektnoj), a ne namjernoj rečenici."},
  "2024_jesen__48": {"A":"Rečenica je netočna jer se ime treba sklanjati: 'Rainera Marije Rilkea'.","C":"Rečenica je netočna jer treba 'pri odlučivanju o važnim stvarima', a ne 'u odlučivanju važnih stvari'.","D":"Rečenica je netočna jer pravilan oblik glasi 'za sve', a ne 'za svih'."},
  "2024_jesen__49": {"A":"Rečenica je pogrešna jer ispred 'jer' ne dolazi zarez.","C":"Rečenica je pogrešna jer ispred datuma ('10. lipnja') ne treba zarez.","D":"Rečenica je pogrešna jer vokativ 'Draga' treba odvojiti zarezima s obje strane."},
  "2024_jesen__50": {"A":"Tri je premalo jer rečenica sadrži četiri prednaglasnice ('li', 'na', 'od', 'do').","C":"Pet je previše; prednaglasnica je točno četiri.","D":"Šest je previše; prednaglasnica u rečenici ima samo četiri."},
  "2024_jesen__51": {"A":"'Nog-' je tek korijen riječi, a ne cjelovita gramatička (oblikotvorna) osnova.","B":"'Nogom-' ne čini oblikotvornu osnovu riječi 'nogometaš'."},
  "2024_jesen__52": {"A":"Prijedlog 'pri' ne otvara dativ, pa zamjenica nije u dativu.","B":"Prijedlog 'pri' ne zahtijeva akuzativ, pa nije riječ o akuzativu.","D":"Prijedlog 'pri' ne ide s instrumentalom, pa zamjenica nije u instrumentalu."},
  "2024_jesen__53": {"A":"'Mišljaše' je imperfekt 3. lica jednine, a ne množine.","B":"'Življaše' je imperfekt 3. lica jednine, a ne množine.","C":"'Govoraše' je imperfekt 3. lica jednine, a ne množine."},
  "2024_jesen__54": {"A":"'Kišobranar' nastao je sufiksalnom tvorbom (kišobran + -ar), a ne složeno-sufiksalnom.","C":"'Kišobran' je čista složenica (kiša + bran), bez sufiksalnoga dijela.","D":"'Kišobranarov' nastao je sufiksalnom tvorbom (kišobranar + -ov), a ne složeno-sufiksalnom."},
  "2024_jesen__55": {"A":"'Razgovarao s Krležom' odnosi se na samu osobu, pa nije metonimija.","B":"'Pisati kao Krleža' uspoređuje s autorom kao osobom, pa nije metonimija.","C":"'Krleža je jedan od najvećih pisaca' odnosi se na osobu, a ne na njegova djela."},
  "2024_jesen__56": {"A":"U 'polje' nema epentetskoga l; to je osnovni oblik bez umetanja glasa.","B":"U 'grmlje' javlja se epentetsko j (grm + j + e), a ne epentetsko l.","C":"U 'bilje' javlja se epentetsko j (bil + j + e), a ne epentetsko l."},
  "2024_jesen__57": {"B":"Bašćansku ploču nisu napisali Ćiril i Metod, nego je nastala oko 1100. godine na hrvatskom tlu.","C":"Ćiril i Metod nisu živjeli oko 1100. godine, nego u 9. stoljeću.","D":"Ćiril nije stvorio ćirilicu, nego glagoljicu; ćirilica je nastala kasnije po njemu nazvana."},
  "2024_jesen__581": {"B":"'Dakle' uvodi zaključak, a ovdje su iskazi suprotstavljeni, pa ne odgovara.","C":"'Jer' iskazuje uzrok, a odnos među rečenicama je suprotnostan, ne uzročan.","D":"'Nakon što' izriče vrijeme, a ovdje nema vremenskoga, nego suprotnoga odnosa."},
  "2024_jesen__582": {"B":"'Manuskripte' je akuzativ množine, a uz 'bilo je malo' traži se genitiv množine.","C":"'Manuskriptova' nije standardni oblik genitiva množine imenice 'manuskript'.","D":"'Manuskriptovi' je nominativ množine i nepravilan oblik, neprikladan u ovom kontekstu."},
  "2024_jesen__583": {"A":"'Jenjavali su' znači slabjeli, što ne odgovara značenju kruženja rukopisa.","B":"'Kasnili su' ne izriče prelaženje s mjesta na mjesto, nego zakašnjenje.","D":"'Slovili su' znači biti na glasu, što ne odgovara kontekstu širenja rukopisa."},
  "2024_jesen__584": {"A":"'Njegove' upućuje na jednu osobu izvan subjekta, a posjedovatelj je isti subjekt (prepisivači).","B":"'Njihove' upućivalo bi na druge osobe, a ne na sam subjekt rečenice.","D":"'Takve' je pokazna zamjenica koja ne izriče pripadnost subjektu."},
  "2024_jesen__585": {"B":"'Desetero' je brojevna imenica za skupinu (najčešće osoba), neprikladna uz 'inačica'.","C":"'Desetica' označuje predmet ili novčani iznos, a ne neodređenu količinu oko deset.","D":"'Desetka' je oznaka broja ili ocjene, a ne neodređena količina."},

  // 2024_ljeto
  "2024_ljeto__1": {"A":"Pjesma nema domoljubne teme jer ne progovara o domovini ni nacionalnoj sudbini, nego o izuzetnim pojedincima.","B":"Nema duhovno-religiozne tematike jer se ne obraća Bogu ni vjerskim sadržajima, nego promišlja o ljudskoj veličini i žrtvi.","C":"Jablani nisu predmet pejzažnoga opisa, nego simbol genija, pa krajolik nije cilj pjesme."},
  "2024_ljeto__2": {"A":"Ti stihovi govore o poletu i osjetljivosti jablana, a ne o tome da su sami zaslužni za svoju veličinu.","C":"Stihovi prikazuju kontrast između 'nas' u dolu i njih u visini, ali ne ističu da su sami stvorili svoju veličinu.","D":"Stihovi opisuju nedostupnu visinu jablana, a ne to da su sami tvorci vlastite veličine."},
  "2024_ljeto__3": {"A":"Eufemizma nema jer se neugodni pojmovi (patnja, bijeda, glad) ne ublažavaju, nego izravno navode.","B":"Premda ima uzvišenih slika, prikaz nije utemeljen na pretjerivanju, nego na proturječju snage iz slabosti.","C":"Ironije nema jer se rečeno podudara s mišljenim, bez skrivenoga suprotnog značenja."},
  "2024_ljeto__4": {"A":"Razlog nije zaokupljenost vlastitim problemima, nego nesporazum s okolinom koja ih ne razumije.","C":"Jablani su prikazani kao snažni ('snaga vjere', 'polet orlova'), pa fizička slabost nije razlog.","D":"Samoća im je nametnuta nerazumijevanjem rulje, a ne njihova želja, pa to nije razlog."},
  "2024_ljeto__5": {"A":"Jablani ne simboliziraju zagovornike života u skladu s prirodom, nego idealiste odvojene od mase.","C":"Prikazani su s divljenjem kao žrtve i vizionari, a ne kao umišljeni i samodopadni pjesnici.","D":"Teže slobodi i ljepoti, a ne moći, pa ne simboliziraju one žedne vlasti."},
  "2024_ljeto__6": {"B":"Očev odnos prema djeci nije izgrađen na prijenosu značenja po sličnosti, nego na suprotstavljanju Jurja i Lucije.","C":"Nema zamjene pojma srodnim pojmom, nego suprotstavljanja odnosa prema sinu i kćeri.","D":"Nema spajanja proturječnih pojmova u jednom izrazu, nego suprotstavljanja dvaju odnosa."},
  "2024_ljeto__7": {"A":"Usklik se ne odnosi na Valpurgin odgoj, nego na divljenje Jurjevu znanju iz povijesti.","B":"Riječi izražavaju ponos i divljenje, a ne prezir prema djeci.","C":"Lucija u tom trenutku nije u središtu; otac komentira Jurjevo znanje, a ne Lucijino ponašanje."},
  "2024_ljeto__8": {"A":"Uređivanje za susret s ocem prati strah i napetost, a ne sreća.","B":"Dok otac podučava Jurja, Lucija je zanemarena, pa to nije trenutak njezine sreće.","C":"Ručak s ocem za nju je mučan i završava plačem, a ne srećom."},
  "2024_ljeto__9": {"A":"Lucijino marljivo učenje ponašanja prikazuje njezin trud, a ne vrhunac očeva podcjenjivanja žena.","B":"Lucijin plač pokazuje njezinu potresenost, a ne najjači izraz očeva prezira.","C":"Valpurgin pogled i mužev strogi izraz tek najavljuju njegovu reakciju, ali nisu vrhunac podcjenjivanja."},
  "2024_ljeto__10": {"A":"Izraz ne potiče na bavljenje trgovinom, nego hiperbolično traži krajnju žrtvu.","B":"Ne odnosi se na lijenost, nego na spremnost da se odrekne svega.","C":"Ne govori o mirnom snu, nego o žrtvovanju i onoga najnužnijega."},
  "2024_ljeto__11": {"A":"Skrivanje od prefekta odnosi se na samoga Stephena, a ne na njegove vršnjake.","B":"Vršnjaci nisu prikazani crno-bijelo, nego diferencirano kroz Stephenov subjektivni doživljaj.","C":"Nadmetanje za vođu nije opće obilježje svih vršnjaka, nego se vezuje uz Kickhama o kojem drugi govore."},
  "2024_ljeto__12": {"A":"Kickham je prikazan kao zgodan i omiljen dečko, a ne kao nasilnik.","C":"Cantwell nije u ulomku okarakteriziran kao nasilnik.","D":"Jack Lawton nije prikazan kao nasilnik u polaznome tekstu."},
  "2024_ljeto__13": {"A":"Pitanje o ocu ne pokreće sjećanje na majku.","C":"Uzvik 'Lijepa majka!' je Stephenov zaključak nakon sjećanja, a ne ono što ga je potaknulo.","D":"Oproštajne riječi vezane su uz sam rastanak, a sjećanje na majčin savjet pokrenule su nepristojne riječi o stražnjici."},
  "2024_ljeto__14": {"B":"Iz primjera ne slijedi namjera pisanja pravopisa, nego estetski doživljaj svijeta.","C":"Ne radi se o ljubavi prema literaturi o samostanima, nego o tome da Stephen stvarnost vidi kao knjigu.","D":"Spomen doktora Gornwella vezan je uz pravopis kao izvor ljepote, a ne uz želju za upoznavanjem."},
  "2024_ljeto__15": {"B":"Detaljni opisi likova i prostora obilježje su realističkoga, a ne modernoga romana.","C":"Tekst koristi unutarnju perspektivu i slobodni neupravni govor, a ne klasično pripovijedanje u trećem licu kao glavnu odliku.","D":"Dijalog među likovima nije osobito obilježje modernoga romana, nego općenita pripovjedna tehnika."},
  "2024_ljeto__16": {"B":"Radmio ne govori o danu uništenja primorja, nego o radosnom danu vjenčanja.","C":"Ne govori o Ribarovu bijegu od kuće, nego o veselom danu sreće za sve.","D":"Ne govori o danu nastanka Dubrave, nego o danu vjenčanja najljepših pastira."},
  "2024_ljeto__17": {"A":"Ti stihovi opisuju nasilje i nesigurnost u Primorju, a ne poštenje koje vlada u Dubravi.","B":"Stihovi prikazuju mjesta gdje se sve može kupiti, a Ribar baš to suprotstavlja Dubravi.","D":"Stihovi govore o prisili na podmićivanje drugdje, a ne o poštenju Dubrave."},
  "2024_ljeto__18": {"A":"Kontrast ne služi upozorenju na neprijatelje, nego isticanju slobode Dubrave.","B":"Ne služi opisu Ribarova bijega, nego suprotstavljanju ropstva i slobode.","C":"Ne služi zabavi stanovnika, nego veličanju dubrovačke slobode."},
  "2024_ljeto__19": {"B":"Prikaz nije mističan jer nema tajanstvenih i nadnaravnih elemenata, nego vedre slike sklada.","C":"Prikaz nije realističan jer Dubrava nije prikazana objektivno, nego idealizirano.","D":"Prikaz nije satiričan jer nema poruge ni kritike, nego veličanja i idealizacije."},
  "2024_ljeto__20": {"A":"Monolog ne završava deus ex machina, jer nema iznenadnoga božanskog razrješenja radnje.","B":"Ne završava zazivanjem vlasti, nego kletvom upućenom onomu tko želi zlo Dubravi.","C":"Ne završava pohvalom Radmilu, nego prokletstvom neprijateljima slobode."},
  "2024_ljeto__21": {"A":"Tekst ne nagovara na kupnju uređaja, nego savjetuje kako poboljšati zrak u domu.","B":"Tekst ne uspoređuje gradski i seoski život, nego daje savjete za kvalitetu zraka u zatvorenom prostoru.","C":"Tekst ne objašnjava prednosti obnovljivih izvora energije, nego poučava o čistoći zraka u domu."},
  "2024_ljeto__22": {"B":"Razlog nije teško čišćenje prirodnim sredstvima, nego mogući štetni kemijski spojevi u pokućstvu.","C":"Razlog nije oštećenje u grijanim prostorima, nego ispuštanje štetnih tvari.","D":"Razlog nije opasnost za kućne ljubimce, nego štetnost po kvalitetu zraka."},
  "2024_ljeto__23": {"A":"Tekst kao razlog ne navodi porast ugljikova monoksida, nego pojačano isparavanje otrovnih spojeva.","C":"Razlog nije šteta sobnim biljkama, nego veće otpuštanje otrovnih para.","D":"Razlog nije visok račun za grijanje, nego zdravstvena štetnost isparavanja."},
  "2024_ljeto__24": {"A":"Tkanine organskoga podrijetla preporučuju se kao zdrav izbor, a ne kao štetne.","B":"Pokućstvo od cjelovitoga drva preporučuje se, pa ne šteti zraku.","C":"Prirodna sredstva za čišćenje preporučuju se umjesto sintetičkih, pa nisu štetna."},
  "2024_ljeto__25": {"A":"Upotreba stručnih termina nije osobito obilježje upućivačkih tekstova, nego znanstvenih.","B":"Upotreba prvoga lica nije tipična za upućivačke tekstove koji se služe imperativom.","D":"Upotreba kratica nije obilježje upućivačkih tekstova."},
  "2024_ljeto__26": {"A":"Tekst ne opisuje detaljno smrtonosne bolesti, nego poučava o važnosti permafrosta.","B":"Tekst nije slikovita pripovijest o aljaskom ekosustavu, nego edukativni tekst o smrznutom tlu.","D":"Tekst ne nagovara na istraživanje Arktika, nego informira o permafrostu."},
  "2024_ljeto__27": {"B":"Mumificirani ostatci su ono što permafrost čuva, a ne naziv za sam permafrost.","C":"Permafrost se ne naziva lokalnom epidemijom; antraks je epidemija, a ne permafrost.","D":"Permafrost se ne naziva radioaktivnim otpadom, nego vremenskom kapsulom."},
  "2024_ljeto__28": {"A":"Pandemija španjolske gripe vezana je uz drugi primjer, a ne uz vruća sibirska ljeta.","C":"Tekst ne navodi otapanje teških metala kao posljedicu vrućih ljeta.","D":"Rast četinarskih šuma nije posljedica vrućih sibirskih ljeta, nego izbijanje antraksa."},
  "2024_ljeto__29": {"A":"Rečenica o ekološkom sustavu i sjevernoj hemisferi pisana je objektivno i znanstveno primjereno.","C":"Spomen analize tkiva i genomskoga materijala H1N1 stručan je i u skladu sa znanstvenim stilom.","D":"Spomen spora Bacillus anthracis stručan je izraz primjeren znanstvenom stilu."},
  "2024_ljeto__30": {"A":"Paradoks pripada književno-umjetničkom izrazu i ne pridonosi objektivnosti.","B":"Upućivačka (imperativna) rečenica obilježje je savjetodavnih tekstova, a ne objektivnosti znanstvenoga.","D":"Upotreba prvoga lica unosi subjektivnost, pa ne pridonosi objektivnosti."},
  "2024_ljeto__31": {"A":"Stih o gledanju u mjesec ne ublažava neugodan pojam, pa nije eufemizam.","B":"Stih o opojnoj pari oko mjeseca slikovit je opis, ali ne i eufemizam.","D":"Stih o otvaranju grobnice izravno spominje smrt, pa nije eufemizam nego njegova suprotnost."},
  "2024_ljeto__32": {"B":"Opis siromaštva i položaja u društvu socijalna je, a ne etička karakterizacija.","C":"Opis građe tijela i odijela tjelesna je (vanjska) karakterizacija, a ne etička.","D":"Opis blijeđenja i tuge psihološka je (emocionalna) karakterizacija, a ne etička."},
  "2024_ljeto__33": {"A":"Deus ex machina je tehnika iznenadnoga razrješenja radnje, a ne cilj tragedije.","B":"Digresija je odmak od glavne radnje, a ne cilj tragedije.","C":"Invokacija je zaziv muze na početku epa, a ne cilj tragedije."},
  "2024_ljeto__34": {"A":"Diskurzivni oblici nisu književni rod na koji se odnosi pravilo triju jedinstava.","C":"Epika ne podliježe pravilu o jedinstvu mjesta, vremena i radnje, koje vrijedi za dramu.","D":"Lirika ne poznaje pravilo triju jedinstava, koje je vezano uz dramu."},
  "2024_ljeto__35": {"A":"Rečenicu ne izgovara Hamlet Ofeliji, nego Leone Angeliki u Gospodi Glembajevima.","B":"Ne izgovara je Kreont Ismeni, nego Leone Glembay.","D":"Ne izgovara je Sigismund Rosauri, nego Leone Angeliki."},
  "2024_ljeto__36": {"A":"Don Fernando ne opravdava zločin filozofskom teorijom.","C":"Melkior je promatrač i žrtva okolnosti, a ne lik koji teorijski opravdava zločin.","D":"Ugo ne razvija filozofsku teoriju kojom bi opravdao zločin."},
  "2024_ljeto__37": {"A":"Stihove ne piše Ivan Gundulić, barokni pjesnik, nego Vladimir Nazor.","B":"Ne piše ih Silvije Strahimir Kranjčević, nego Vladimir Nazor.","C":"Ne piše ih Tin Ujević, nego Vladimir Nazor."},
  "2024_ljeto__38": {"A":"Marmeladov je lik iz Zločina i kazne, pa primjer pripada tomu romanu.","B":"Razumihin je lik iz Zločina i kazne, pa primjer pripada tomu romanu.","D":"Sonja je lik iz Zločina i kazne, pa primjer pripada tomu romanu."},
  "2024_ljeto__39": {"A":"Dživo se ne obraća Smail-agi, liku iz Mažuranićeva epa, nego Stancu.","B":"Dživo se ne obraća Solusu, nego Stancu u Noveli od Stanca.","D":"Dživo se ne obraća Stipančiću, liku iz Novakova romana, nego Stancu."},
  "2024_ljeto__40": {"A":"Izostanak interpunkcije obilježje je avangarde (npr. Apollinaire), a ne Baudelairea.","C":"Moralističnost nije Baudelaireova odlika; on estetizira grijeh i zlo.","D":"Slobodni stih nije obilježje Baudelairea, koji piše u tradicionalnim vezanim oblicima."},
  "2024_ljeto__41": {"A":"Rastrganost između svjetovnoga i duhovnoga jest barokno obilježje, pa nije iznimka.","B":"Religiozna poema i barokni plač pripadaju baroku, pa nisu iznimka.","D":"Kićeni stil jest barokno obilježje, pa nije iznimka."},
  "2024_ljeto__42": {"A":"Barok ne odbacuje sklad u korist krika, nego njeguje kićenost i patetiku.","B":"Klasicizam upravo veliča sklad i mjeru, pa se ne podudara s opisom.","C":"Romantizam naglašava osjećaje, ali ne odbacuje ideju ljepote kao sklada na opisani način."},
  "2024_ljeto__43": {"A":"Pravilno je 'oblačan', a ne 'oblaćan'.","B":"Pravilno je 'žuta' (komparativ 'žuća' nije standardan u tom obliku), pa primjer nije točan.","D":"Pravilno je 'zečje' (zec + je), a ne 'zećje'."},
  "2024_ljeto__44": {"A":"Rečenica je pravopisno ispravna jer je datum pravilno odvojen zarezom.","C":"Rečenica je pravopisno ispravna i ne krši pravila o zarezu.","D":"Rečenica je ispravna jer je apozicija 'lučkome gradu' pravilno odvojena zarezom."},
  "2024_ljeto__45": {"A":"Pravilno je 'bombon', a ne 'bonbon'.","B":"Pravilno je 'prehrambeni' (jednačenje po mjestu tvorbe), a ne 'prehranbeni'.","D":"Pravilno je 'zelembać', a ne 'zelenbać'."},
  "2024_ljeto__46": {"A":"'Rame' ima proširenu osnovu (ram-en-), pa nije primjer neproširene osnove.","B":"'Tele' ima proširenu osnovu (tel-et-), pa nije primjer neproširene osnove.","C":"'Polje' nije imenica s prošircima srednjega roda kao 'rame'/'tele', ali traženi je primjer 'ime' s osnovom im-."},
  "2024_ljeto__47": {"A":"'Hodajući gradom' nije atributna sintagma, nego glagolski prilog s priložnom oznakom.","B":"'Drugoj strani' je sročna atributna sintagma (slaganje u rodu, broju i padežu), a ne nesročna.","D":"'Ugledala lice' nije atributna sintagma, nego predikatno-objektni odnos."},
  "2024_ljeto__48": {"A":"'Sinoć dođem' je pripovjedački (historijski) prezent, a ne apsolutna upotreba.","B":"'Hrvatska ima more' iskazuje trajno stanje, ali ne kao bezvremensku opću istinu poput poslovice.","C":"'Upravo dolaze' označuje konkretnu sadašnju radnju, a ne bezvremensku."},
  "2024_ljeto__49": {"A":"Pravilno je 'donijet ću', a ne 'donijeti ću'.","B":"Pravilno je 'donesene', a ne 'donešene'.","D":"'Doneseno je' jest pravilno, ali traženi je primjer s glagolskim pridjevom radnim 'donio/donijeo'; ovdje je riječ o trpnom pridjevu."},
  "2024_ljeto__50": {"A":"'Dolažahu' je imperfekt, a ne imperativ.","C":"'Došla bi' je kondicional prvi, a ne imperativ.","D":"'Dođoh' je aorist, a ne imperativ."},
  "2024_ljeto__51": {"A":"Pravilno je 'keljem' jer 'lj' traži nastavak -em, a ne 'keljom'.","B":"Pravilno je 'kraljem', a ne 'kraljom'.","D":"Pravilno je 'panjem', a ne 'panjom'."},
  "2024_ljeto__52": {"A":"'Mraka' je genitiv (bojati se čega), a ne izravni objekt u akuzativu.","B":"'Šali' je dativ (smijati se čemu), a ne izravni objekt.","D":"'Na nj' je prijedložni izraz, a ne izravni objekt u akuzativu."},
  "2024_ljeto__53": {"A":"'Živjeti' nije priložna oznaka, nego infinitivni subjekt rečenice.","B":"Predikat je 'je lijepo', a 'živjeti' je subjekt.","D":"'Živjeti' nije objekt, nego subjekt bezlične rečenice."},
  "2024_ljeto__54": {"A":"'Uzbrdo' je nastalo srastanjem prijedloga i imenice (uz + brdo), a ne prefiksalno-sufiksalno.","B":"'Uzdahnuti' je prefiksalna tvorba (uz + dahnuti), bez sufiksa.","D":"'Uzlaznost' je sufiksalna tvorba (uzlazan + ost), bez prefiksa."},
  "2024_ljeto__55": {"A":"'Mahnit' znači lud ili pomaman, a ne tašt.","B":"'Skeptičan' znači sumnjičav, a ne samodopadan.","C":"'Suptilan' znači prefinjen ili nijansiran, a ne tašt."},
  "2024_ljeto__56": {"A":"To je značenje frazema 'bacati bisere pred svinje', a ne 'bijela vrana'.","C":"Neosjećanje krivnje nije značenje frazema 'bijela vrana'.","D":"Pobjeda uz velike gubitke odgovara 'Pirovoj pobjedi', a ne 'bijeloj vrani'."},
  "2024_ljeto__57": {"A":"'ž' je gramatička odrednica roda, a ne etimološka.","B":"'1. knjiž. dramska vrsta' je značenjska (semantička) odrednica, a ne etimološka.","C":"'2. događaj oprečan očekivanju' je drugo značenje, a ne podatak o podrijetlu riječi."},
  "2024_ljeto__581": {"B":"'Bih' je oblik za prvo lice jednine, a uz 'mogla' (3. l.) ide 'bi'.","C":"'Biste' je oblik za drugo lice množine, a ne za treće lice jednine.","D":"'Bude' je oblik futura/prezenta svršenoga 'biti', a ne kondicional."},
  "2024_ljeto__582": {"A":"'Skrbništvo' je pravni pojam starateljstva, a ne zdravstvena skrb.","B":"'Skrbnik' označuje osobu staratelja, a ne zdravstvenu uslugu.","C":"'Opskrba' znači snabdijevanje, pa 'zdravstvena opskrba' nije standardna sintagma za healthcare."},
  "2024_ljeto__583": {"A":"'Njih' je množina, a riječ je o jednoj imenici (inteligencija), pa je neprikladno.","B":"'Njime' je instrumental muškoga/srednjega roda, a 'inteligencija' je ženskoga roda.","C":"'Njoj' je dativ, a kontekst traži instrumental ('njome se može olakšati')."},
  "2024_ljeto__584": {"A":"'Za razliku od toga' uvodi suprotnost, a kontekst nabraja dodatne pozitivne aspekte.","B":"'Nasuprot tomu' izražava suprotstavljanje, a ovdje se nastavlja nabrajanje istovrsnih argumenata.","D":"'Ipak' uvodi ograničenje ili suprotnost, a ne dodavanje novoga argumenta u nizu."},
  "2024_ljeto__585": {"A":"'Prije' bi značilo da mjesta nastaju ranije od razvoja, što je besmisleno.","B":"'Sukladno' znači u skladu s, a kontekst traži vremensko značenje 'za vrijeme'.","D":"'Usprkos' izražava suprotnost, a radna mjesta nastaju zahvaljujući razvoju, ne usprkos njemu."},

  // 2025_jesen
  "2025_jesen__1": {"B":"Nema religioznog motiva ni straha od Boga; žene se obožavaju, ne prikazuju pobožnima.","C":"Pjesma nigdje ne tematizira pravdu ni društveni angažman žena.","D":"Nema motiva majčinstva — žene su tajanstvene i nedostižne, ne majke."},
  "2025_jesen__2": {"A":"'Slutim Vas srcem plamenim' izražava čežnju i strast, ne poniznost.","B":"'Tko će mi dati ključe Vašeg čuda' izražava nemoć spoznaje, ne klanjanje.","D":"'Pobožnu ljudstvu fali Vaša slika' govori o veličini žena, ne o poniznosti subjekta."},
  "2025_jesen__3": {"A":"Motiv tajne nije izražen spajanjem dvaju osjetila.","B":"Motiv zagonetke je apstraktan pojam, nije ostvaren sinestezijom.","C":"Motiv zore nije izgrađen miješanjem osjetilnih dojmova."},
  "2025_jesen__4": {"A":"Alegorija je prošireni preneseni prikaz s drugim značenjem — pjesma se ne gradi na njoj.","C":"Oksimoron ('zvučni plamen') je tek pojedinost; pjesma se ne temelji na proturječju.","D":"Onomatopeje (oponašanja zvukova) u pjesmi nema."},
  "2025_jesen__5": {"A":"Angažirana lirika bori se za društvene/političke ciljeve; ovdje je riječ o obožavanju žene.","C":"Antička korska (zborska) lirika nije model ove intimne pjesme.","D":"Ekspresionistička poetika (krik, deformacija) ne odgovara adoraciji dame."},
  "2025_jesen__6": {"A":"Dunja nije ničija ljubavnica; udaje se, a Lužin nije oženjen.","B":"Motiva različite boje kože u tekstu nema.","D":"Zamjerka nije lagodan život nego nedostojnost Lužina — Dunja se žrtvuje radi brata."},
  "2025_jesen__7": {"A":"Lužin nije požrtvovan, nego sebično bira siromašnu, podređenu ženu.","C":"Suprotno od skromnosti — voli da mu je supruga zahvalna i ovisna.","D":"Tekst ne ističe škrtost nego hladnu računicu pri izboru žene."},
  "2025_jesen__8": {"A":"'Shvatio sam kakvi ste' ozbiljan je iskaz, bez ironije.","B":"'Ne bi dušu prodala' iskreni je hvalospjev sestri, nema ironije.","C":"'Neće biti ništa dok sam živ' odlučan je otpor, ne ironija."},
  "2025_jesen__9": {"A":"Nema izmjene replika dvaju likova, pa nije dijalog.","B":"Nije vanjsko izvještavanje pripovjedača nego unutrašnje misli lika.","D":"Misli su izravne, u 1. licu — nisu posredovane u 3. licu kao slobodni neupravni govor."},
  "2025_jesen__10": {"A":"Lebezjatnikov nije osoba radi koje se Dunja žrtvuje.","B":"Marmeladov nije u srodstvu s Dunjom niti razlog njezine žrtve.","D":"Dunja se ne udaje radi Razumihina (s njim će se zbližiti tek kasnije)."},
  "2025_jesen__11": {"B":"'Među tim družbama bijaše' neutralno je pripovijedanje, bez obraćanja publici.","C":"'Hajde da ga bocnemo' replika je lika (Betta), ne pripovjedačevo obraćanje slušateljima.","D":"'On nam je odbrusio' iznosi događaj, ne uspostavlja izravnu bliskost s publikom."},
  "2025_jesen__12": {"A":"Tekst ne navodi da su mu se rugali zbog ateizma.","B":"Guidovo bavljenje filozofijom nije naveden razlog šale.","D":"Razlog nije Guidovo trošenje bogatstva nego odbijanje njihova društva."},
  "2025_jesen__13": {"A":"Crkva Or San Michele spomenuta je, ali susret nije ondje.","B":"Šetalište degli Adimari nije mjesto susreta.","D":"Trg Santa Reparata nije mjesto susreta uz grobnice."},
  "2025_jesen__14": {"A":"Biološka karakterizacija opisuje tjelesne/naravne osobine — ovdje ih nema.","C":"Govorna karakterizacija prikazuje lik načinom govora, što ovdje nije slučaj.","D":"Psihološka prikazuje duševno stanje; ovdje je riječ o moralnome sudu (škrtost)."},
  "2025_jesen__15": {"B":"Katarza je tragično pročišćenje emocija — toga ovdje nema.","C":"In medias res postupak je početka, a ne završetka teksta.","D":"Tekst ne završava izravnim obraćanjem čitatelju nego duhovitim razrješenjem."},
  "2025_jesen__16": {"A":"Seljaci ne pokazuju ljubav prema književnosti nego nerazumijevanje.","C":"Shakespeareov opus nije tema — djelo ga izvrgava ruglu.","D":"Fokus nije utjecaj književnosti na čovjeka nego (ne)uspjelo postavljanje predstave."},
  "2025_jesen__17": {"A":"Bukara tekst ne smatra poučnim nego zbrkanim.","B":"Ne kritizira ga zbog prostote nego zbog nejasnoće.","D":"Bukara se tekstu ne smije; smatra ga zapetljanim i nerazumljivim."},
  "2025_jesen__18": {"A":"Bukara nije dobio glavnu ulogu Hamleta.","B":"Horacije nije Bukarina uloga.","D":"Polonije nije Bukarina uloga."},
  "2025_jesen__19": {"A":"Netočno — seljaci Shakespearea ne razumiju i preziru, ne cijene više od učitelja.","B":"Obrnuto — seljaci govore dijalektom, a učitelj književnim jezikom.","D":"Obrnuto — Bukara traži preinake teksta, a učitelj popušta."},
  "2025_jesen__20": {"A":"Igra riječi pokazuje dovitljivost seljaka — pa se osobina ODNOSI na njih.","B":"Prostački humor otkriva primitivnost — osobina se odnosi na njih.","C":"Ismijavanje je podrugljivo — osobina se odnosi na njih."},
  "2025_jesen__21": {"A":"Tekst ne potiče na korištenje AI tehnologijom nego raspravlja o njezinu nazivu.","B":"Ne nabraja prednosti i nedostatke AI nego problem pokrate/nazivlja.","D":"Terminologija u institucijama EU dio je teksta, ali ne i njegova glavna namjena."},
  "2025_jesen__22": {"A":"Nesigurnost oko nazivlja jest tema teksta, ali nije ono što zamjenik navodi kao najčešću temu rasprava.","B":"Utjecaj medija nije spomenut kao najčešća tema.","C":"Povezanost s sučeljima izvor je zabune oko pokrate, ne najčešća tema rasprava."},
  "2025_jesen__23": {"A":"Ne odbijaju je zbog porijekla iz neformalnoga govora.","B":"Razlog nije protivljenje engleskoj inačici nego dvoznačnost pokrate.","D":"Obrnuto i nebitno — problem je postojeće tehničko značenje (user interface)."},
  "2025_jesen__24": {"B":"Osvrti radnih skupina nisu navedeni kao najvažniji izvor.","C":"Prevoditelji se ravnaju prema pravnim tekstovima, ne prema govornoj praksi.","D":"Prijevodi drugih organizacija nisu primarni izvor."},
  "2025_jesen__25": {"A":"Tekst ne navodi da je pravnica po struci.","C":"Nije navedeno da je članica Europskoga parlamenta — ona je prevoditeljica i suosnivačica startupa.","D":"Sudjelovanje u Aktu o umjetnoj inteligenciji nije spomenuto u tekstu."},
  "2025_jesen__26": {"B":"Uspostava suradnje s poduzećima nije svrha uvodnoga dijela.","C":"Uvod ne predstavlja fakultet nego objašnjava nastanak uputa.","D":"Pomoć u pisanju svrha je cijelih uputa, dok UVODNI dio govori o njihovu nastanku."},
  "2025_jesen__27": {"B":"Obraćanje nije kritika studenata nego naputak o ponašanju.","C":"Izravno obraćanje imperativom nije znak objektivnosti.","D":"Obraćanje ne uspostavlja jednakost nego daje uputu 'odozgo'."},
  "2025_jesen__28": {"A":"Upute nisu izradili studenti samoinicijativno nego uprava fakulteta.","C":"Standardizacija je 2002.; 1996. su tek prve (nestandardizirane) upute.","D":"Nadopuna digitalnim izdanjima nije navedena u tekstu."},
  "2025_jesen__29": {"B":"Nema umjetničke izražajnosti, slika ni figura svojstvenih književnoumjetničkome stilu.","C":"Nije novinarski tekst namijenjen širokoj javnosti (publicistički).","D":"Nije spontani govorni stil nego formalan i strukturiran."},
  "2025_jesen__30": {"A":"'Objavljuju se s namjerom da pomognu' neutralan je, objektivan iskaz.","C":"'Preporučljiv opseg 10 – 15 stranica' objektivna je uputa/podatak.","D":"'Diplomski je rad samostalan stručan rad...' objektivna je definicija."},
  "2025_jesen__31": {"B":"'Kao samrt tamna, kao život sjajna' poredba je (antiteza), ne metonimija.","C":"'Ljubav bol je najveća' metafora je / hiperbola, ne metonimija.","D":"'Ja sam mrtvac' metafora je, ne metonimija."},
  "2025_jesen__32": {"A":"Invokacija (zaziv Boga za nadahnuće) JEST prisutna — pa se tvrdnja odnosi na tekst.","B":"Inverzija ('presvetoj Juditi') JEST prisutna — tvrdnja se odnosi na tekst.","D":"Dvostrukorimovani dvanaesterci (6+6 s rimom) JESU prisutni — tvrdnja se odnosi na tekst."},
  "2025_jesen__33": {"B":"Novela je kratka forma i ne gradi se na epskoj retardaciji.","C":"Lirska pjesma nema radnju koju bi usporavala.","D":"Drama u stihu napetost gradi dramskom radnjom, ne epskim odlaganjem."},
  "2025_jesen__34": {"B":"Monološko-asocijativni roman tok je asocijacija; ovdje je riječ o pismu s datumom.","C":"Roman ideja primarno raspravlja ideje; ovdje je oblik pisma presudan.","D":"Roman struje svijesti neprekinut je tok svijesti, a ne oblikovano pismo."},
  "2025_jesen__35": {"A":"Katolička obnova i kićenost obilježja su baroka, ne renesanse.","B":"Pokret za nacionalnu svijest obilježje je preporoda/romantizma.","C":"Regionalizam, obiteljski problemi i kritika stvarnosti obilježja su realizma."},
  "2025_jesen__36": {"A":"Renesansa je razdoblje 16. st. — Matoš joj ne pripada.","B":"Barok je 17. st. — pogrešno razdoblje.","C":"Matoš pripada moderni, ne realizmu."},
  "2025_jesen__37": {"A":"Šimić je ekspresionist i piše standardnim jezikom.","B":"Kranjčević ne piše istarskom čakavštinom.","C":"Ujević piše standardnim/modernističkim jezikom, ne istarskom čakavštinom."},
  "2025_jesen__38": {"B":"Patnje mladog Werthera nemaju vezu s likom Yoricka.","C":"Preobražaj ne sadrži lik Yoricka.","D":"Zločin i kazna ne sadrži lik Yoricka."},
  "2025_jesen__39": {"A":"Judita je renesansni ep (Marulić, 16. st.).","C":"Eneida je antički ep (Vergilije).","D":"Smrt Smail-age Čengića romantičarski je ep (Mažuranić)."},
  "2025_jesen__40": {"A":"Kiklop (Marinković, 20. st.) nema preporodni kontekst Gaja i Draškovića.","B":"Kip domovine leta 188* drukčijeg je sadržaja, nije ovaj ulomak.","C":"Posljednji Stipančići ne sadrže ovaj prikaz preporodne izborne politike."},
  "2025_jesen__41": {"A":"Fanny je ženski lik i ne strada pod mađarskom vojskom.","B":"Kamenski nije taj karikaturalni stradalnik.","C":"Pepica nije lik koji simbolizira stradanje hrvatskoga čovjeka pod vojskom."},
  "2025_jesen__42": {"A":"Hamlet se ne obraća Beatrice na ovaj filozofski način.","C":"Melkior Tresić (Kiklop) ne spominje Beatrice ovako.","D":"Werther ne govori Beatrici o 'etičkoj inteligenciji'."},
  "2025_jesen__43": {"B":"Pogrešno — treba 'Nobelovu nagradu za književnost' (nagrada i književnost malim slovom).","C":"Pogrešno — 'mali indijski mungos' piše se malim slovom (vrsta životinje).","D":"Pogrešno pisanje velikih slova u 'Velike Svete Džamije' (treba malim, uz vlastito ime Aja Sofija)."},
  "2025_jesen__44": {"A":"Pogrešno — pravilno je 'djevojčin' (č, ne ć).","B":"Nije standardno — pravilno 'pješčan' / 'pjeskovit'.","D":"Pogrešno — pravilno je 'zapečen' (č, ne ć)."},
  "2025_jesen__45": {"A":"'Im' je nenaglašeni oblik (enklitika).","B":"'Ih' je nenaglašeni oblik (enklitika).","C":"'Mu' je nenaglašeni oblik (enklitika)."},
  "2025_jesen__46": {"A":"'Gled-' je korijen, ne gramatička (oblikotvorna) osnova cijele riječi.","B":"'Gleda-' je glagolska osnova, ne osnova imenice 'gledateljica'.","C":"'Gledatelj-' je osnova imenice 'gledatelj', a ne 'gledateljica'."},
  "2025_jesen__47": {"A":"'Poput mrava' prijedložni je izraz (poredba), nije prilog.","B":"'Predivno' uz 'selo' pridjev je, ne prilog.","C":"'Kao da mu je posljednja utrka' poredbena je rečenica, ne prilog."},
  "2025_jesen__48": {"A":"Dva je premalo — u rečenici se pojavljuje više glagolskih vremena (perfekt, aorist, imperfekt...).","B":"Tri ne obuhvaća sva pojavljena vremena u rečenici.","D":"Pet je previše — nema toliko različitih glagolskih vremena."},
  "2025_jesen__49": {"A":"'Toj' je u lokativu (u toj ulici).","C":"'Ju' je u akuzativu (vidio ju je).","D":"'Njima' je u instrumentalu (s njima)."},
  "2025_jesen__50": {"A":"Pogrešno — pravilno je 'smeta mi', ne 'me smeta'.","B":"Pogrešno — pravilno je 'lagala mi', ne 'lagala me'.","D":"Pogrešno — pravilno 'oženio se Sanjom' (ili 'uzeo Sanju za ženu')."},
  "2025_jesen__51": {"A":"'U šumu' priložna je oznaka mjesta (u + akuzativ), ne izravni objekt.","B":"'Na šumu' prijedložni je (neizravni) objekt, ne izravni.","D":"'Za šumu' prijedložni je izraz, ne izravni objekt."},
  "2025_jesen__52": {"A":"'Sniježi cijeli dan' bezlična je (besubjektna) rečenica.","B":"'Svitalo je ponad grada' bezlična je (besubjektna) rečenica.","C":"'Šuška se o njihovoj vezi' bezlična je povratna, besubjektna rečenica."},
  "2025_jesen__53": {"A":"'Blagdan' je sraslica (srastanje), ne čisto slaganje dviju ravnopravnih osnova.","B":"'Brodovlasnički' tvoreno je sufiksom -ski od složenice, nije čisto slaganje.","D":"'Suncobran' tvoreno je slaganjem uz sufiksaciju, nije čisto slaganje."},
  "2025_jesen__54": {"A":"Egzonim je strani naziv za zemljopisni pojam, ne naziv stanovnika.","B":"Ekonim je naziv naselja, ne naziv stanovnika.","C":"Eponim je naziv izveden iz osobnog imena, ne naziv stanovnika mjesta."},
  "2025_jesen__55": {"A":"'Hodati po jajima' znači biti vrlo oprezan — suprotno od naglosti.","C":"'Kupiti mačka u vreći' znači kupiti neprovjereno, ne postupati naglo i nepromišljeno.","D":"'Dolijevati ulje na vatru' znači pogoršavati sukob, ne nagla nepromišljenost."},
  "2025_jesen__56": {"B":"Čakavsko je narječje (zaspa, dvi, 'rče), ne kajkavsko.","C":"Standardni jezik, nije narječje.","D":"Čakavsko je narječje (vajalo, posteje, peškarije, dici), ne kajkavsko."},
  "2025_jesen__57": {"A":"Pogrešno — prvi hrvatski rječnik (Vrančić) ima pet jezika, ne dva.","B":"Pogrešno — ima pet, ne tri jezika.","C":"Pogrešno — ima pet, ne četiri jezika."},
  "2025_jesen__581": {"B":"'Pronicljivo' znači oštroumno uočavati, ne odgovara uputi za pažljivo čitanje teksta.","C":"'Sadržajno' ne kolocira s 'pročitaj' kao uputa o načinu čitanja.","D":"'Skladno' znači usklađeno/harmonično — besmisleno uz 'pročitaj tekst'."},
  "2025_jesen__582": {"B":"'Naravno' potvrđuje očekivano, ne uvodi pojašnjenje trenutka odluke.","C":"'Štoviše' pojačava/stupnjuje iskaz, ne uvodi konkretizaciju.","D":"'Zaista' potvrđuje istinitost, ne uvodi objašnjenje."},
  "2025_jesen__583": {"B":"'Letargičnu' znači bezvoljnu, tromu — ne opisuje radikalan čin.","C":"'Nehotičnu' znači nenamjernu — Norina je odluka svjesna i namjerna.","D":"'Skeptičnu' znači sumnjičavu — ne opisuje odlučan čin napuštanja."},
  "2025_jesen__584": {"A":"'Patricijske' se odnosi na plemstvo/staleže, ne na muško-žensku dominaciju.","C":"'Patriotske' se odnosi na domoljublje — nije tema drame.","D":"'Patronažne' se odnosi na skrbništvo/protekciju, ne na muški autoritet u obitelji."},
  "2025_jesen__585": {"A":"'Anticipiraj' znači predvidjeti unaprijed, ne potkrijepiti odgovor.","C":"'Asociraj' znači povezati po sličnosti, ne obrazložiti.","D":"'Ažuriraj' znači osuvremeniti/dopuniti, ne argumentirati."},

  // 2025_ljeto
  "2025_ljeto__1": {"A":"Balada pripovijeda tragičnu radnju; ovdje nema pripovjednog događaja ni tragike, nego podrugljivo obraćanje psiću.","B":"Elegija je tužaljka; ova je pjesma zajedljiva i podrugljiva, ne ožalošćena.","C":"Idila slika spokojan, skladan svijet; ton je ovdje oštar i podrugljiv."},
  "2025_ljeto__2": {"B":"Ruka i peta nisu suprotstavljeni nego dijelovi iste slike dodvoravanja (lizanje pete).","C":"Kastor i psine nisu prava opreka — psine su tek usporedba; ključno je psić ↔ ljudi.","D":"Pjesma i lovor nisu nositelji temeljne ironične paralele."},
  "2025_ljeto__3": {"B":"'Zlatna metoda' nije suosjećanje nego ulizivanje radi koristi.","C":"Nije riječ o skromnosti — Kastor se ugodno smjestio uz gazdu.","D":"Metoda nije moralna spoznaja nego nemoralno dodvoravanje (ironično pohvaljeno)."},
  "2025_ljeto__4": {"A":"Ne pohvaljuje suživot — kroz psića ironično kritizira dodvoravanje.","B":"Lirski subjekt ne teži položaju; ismijava one koji se dodvoravaju.","C":"Pse lutalice ne kudi iskreno — one su tek kontrast; meta su udvorice."},
  "2025_ljeto__5": {"B":"Antički motivi (ime Kastor) jesu u kontrastu s niskom temom — pa se tvrdnja ODNOSI na pjesmu.","C":"Deminutivi (psić, psetance) jesu pejorativni — tvrdnja se odnosi na pjesmu.","D":"Kolokvijalizmi/žargonizmi jesu prisutni — tvrdnja se odnosi na pjesmu."},
  "2025_ljeto__6": {"A":"Suprotno — Céleste ubojstvo naziva 'nesrećom', ne hladnokrvnim činom.","C":"Céleste ne govori o zahvalnosti optuženika nego brani njegov karakter.","D":"Nema spomena da je Meursault iskorištavao Célesta; Céleste ga brani."},
  "2025_ljeto__7": {"A":"Tišina nije iščekivanje nastavka nego šok zbog Marijina iskaza.","C":"Nije optuženikovo ponašanje izazvalo tajac, nego sadržaj Marijina odgovora.","D":"Tišina nije divljenje tužitelju nego zgražanje nad otkrivenom činjenicom."},
  "2025_ljeto__8": {"B":"Cilj nije ruganje Marie nego diskreditiranje optuženika kao bezosjećajnog.","C":"Ne zanima ga doslovno provođenje slobodnog vremena nego moralni dojam (zabava nakon sprovoda).","D":"Marie ne svjedoči o samom zločinu; tužitelj cilja na Meursaultovu bezosjećajnost."},
  "2025_ljeto__9": {"A":"Tekst nije lirski/emotivan nego suho i objektivno pripovijeda.","C":"Načelo tipičnosti (realistički tip) nije obilježje ovog hladnog, individualnog iskaza.","D":"Estetika ružnoće (naturalizam) nije naglašena; stil je svedeni i neutralan."},
  "2025_ljeto__10": {"A":"Nije struja svijesti — pripovijedanje je sređeno i kronološko.","C":"Nije 3. lice — pripovjedač govori 'ja' (Meursault).","D":"Nije slobodni neupravni govor nego izravno pripovijedanje u 1. licu."},
  "2025_ljeto__11": {"B":"Dioniz nagrađuje gostoprimstvo; nije riječ o ranijem prijateljstvu s Midom (drug mu je Silen).","C":"Dar nije demonstracija moći nego nagrada za gostoprimstvo.","D":"Ne provjerava inteligenciju — Mida sam bira (lošu) želju."},
  "2025_ljeto__12": {"A":"Ne shvaća da je lud nego da se ne može hraniti (hrana postaje zlato).","B":"Problem nije višak bogatstva nego nemogućnost jela i pića.","D":"Ne strahuje od kazne bogova nego od konkretne gladi i smrti."},
  "2025_ljeto__13": {"A":"'Kidao klasje a žeo zlato' prikazuje čaroliju, ne svijest o pogrešci.","B":"Sjaj stupova pokazuje djelovanje dara, ne kajanje.","C":"Naredba za ručak pokazuje radost prije spoznaje, a ne svijest o lošoj želji."},
  "2025_ljeto__14": {"A":"Mit ne govori o besmrtnosti nego o pohlepi i kazni.","B":"Nema panteističkog doživljaja prirode; tema je moralna.","D":"Ne tematizira civilizacijske promjene nego moralnu pouku."},
  "2025_ljeto__15": {"A":"Nema usporavanja radnje umetcima (retardacije); događaji teku ravno.","B":"Nema vraćanja u prošlost (flashbacka).","C":"Nema slobodnoga neupravnog govora; pripovijedanje je izravno."},
  "2025_ljeto__16": {"B":"Markiz nije nezadovoljan zbog tajnosti nego zbog vrijednosti (dijamanti > rupčić).","C":"Nije siguran u nadmoć svog poklona — svjestan je da je slabiji ('Proklet grof, njegovi dijamanti').","D":"Nije sretan; psuje grofa i njegovo bogatstvo."},
  "2025_ljeto__17": {"B":"Ne prihvaćaju zbog prijateljstva nego zbog grofove darežljivosti.","C":"Ne žele objašnjavati svoj boravak nego iskoristiti grofovu velikodušnost.","D":"Motiv nije ljubomora na rupčić nego korist od bogatijeg grofa."},
  "2025_ljeto__18": {"A":"Rečenica se ne odnosi na Ortensijinu uzvišenost nego na markizovo razmetanje.","B":"Ne odnosi se na grofa; grof doista jest bogat, kritika ide siromašnom markizu.","C":"Ne govori o Mirandolininoj skromnosti nego o oholom siromahu (markizu)."},
  "2025_ljeto__19": {"A":"Didaskalije za neverbalne radnje obično su drugačije; ovdje zagrade nose unutarnje misli (a parte).","B":"Nije samo 'ono što se ne izgovara' općenito — konkretno otkriva prave osjećaje lika.","D":"Ne opisuje uvjete/scenografiju nego unutarnje reakcije i motive lica."},
  "2025_ljeto__20": {"A":"'Vaša odana službenica' je uljudna formula, ne ironija.","B":"'Nije potrebno da se zna' je markizova doslovna izjava.","D":"'To je ugledna obitelj, poznajem je' je tvrdnja bez ironijskog obrata."},
  "2025_ljeto__21": {"A":"Promocija pripravka je sporedna; glavna je namjena edukacija, ne prodaja.","B":"Tekst ne daje recepte za obroke nego savjete o energiji.","D":"Studije se spominju kao potpora, ali svrha nije njihovo predstavljanje."},
  "2025_ljeto__22": {"A":"Tekst je povezan i savjetodavan, nije isprekidan po obliku.","B":"Nije raspravljački (nema teze i protuargumenata) nego informativno-savjetodavni.","D":"Ukošeni pojmovi su stručni nazivi, nemaju funkciju poveznice."},
  "2025_ljeto__23": {"A":"Za željezo se navodi uloga, ali ne kao rezultat citirane studije.","B":"Tvrdnja o camu camu je opis, nije predstavljena kao dokaz studije.","D":"Tvrdnja o nedostatnosti prehrane nije označena kao znanstveno dokazana."},
  "2025_ljeto__24": {"A":"Glukoza daje energiju, ali kao stimulans živčanog sustava naveden je kofein.","B":"Vitamin C je antioksidans, ne stimulans živčanog sustava.","C":"Željezo se veže uz prijenos kisika/umor, ne kao poticaj živčanom sustavu."},
  "2025_ljeto__25": {"A":"1998. se ne spominje kao godina objave analize.","B":"2005. nije navedena godina objave u Nutrientsu.","D":"2025. nije godina objave; 'ove (2024.) godine' odnosi se na 2024."},
  "2025_ljeto__26": {"A":"Izvještaj je činjeničan i neutralan; ovaj tekst analizira i procjenjuje.","C":"Reportaža donosi doživljaj s terena; ovdje je analiza glazbenih djela.","D":"Životopis prati nečiji život; tekst se bavi djelima (sonatama)."},
  "2025_ljeto__27": {"A":"Nema sažetih mudrih izreka (aforizama).","B":"Nema alegorije (cjelovite prenesene priče); riječ je o metaforičnim opisima.","C":"Tekst je subjektivan i dojmovan, ne objektivan."},
  "2025_ljeto__28": {"A":"Dramatičnost se ne navodi kao ono što Franck preuzima od Liszta.","B":"Sonatna pravila nisu navedena kao Lisztova ostavština.","C":"Suprotstavljenost tema nije pripisana Lisztovu utjecaju."},
  "2025_ljeto__29": {"A":"Liszt je tvorac tehnike, nije svirao na vjenčanju u Arlonu.","C":"Franck je skladatelj sonate, nije izvođač na vjenčanju.","D":"Bordes-Pène je svirala klavir, ne violinu."},
  "2025_ljeto__30": {"A":"Da je posvetio sonatu voljenoj ženi JEST navedeno — pa nije traženi (neiskazani) odgovor.","B":"Da je skladao sonate u mladosti JEST u tekstu — nije traženi odgovor.","D":"Udaljavanje od tradicije JEST navedeno — nije traženi odgovor."},
  "2025_ljeto__31": {"A":"Aliteracija je ponavljanje suglasnika; toga nema u 'vrišteće boje'.","B":"Gradacija je stupnjevanje; nema niza pojmova u rastu/padu.","C":"Iako ima prenesenosti, ključ je zvukovni 'vrišteće' (oponašanje), pa je onomatopeja precizniji odgovor."},
  "2025_ljeto__32": {"A":"Akrostih (početna slova daju riječ) obilježje je lirike.","B":"Digresija (odmak od teme) postupak je epike/proze.","C":"Invokacija (zaziv muze) obilježje je epa."},
  "2025_ljeto__33": {"A":"Opis odjeće i dojma je vanjska/socijalna karakterizacija, ne moralna.","B":"Podatak o zaradi je socijalna (materijalna) karakterizacija.","D":"Osjećaj bespomoćnosti je psihološka karakterizacija, ne etička."},
  "2025_ljeto__34": {"A":"Ditiramb je zanosni hvalospjev; ovi su stihovi podrugljivi.","B":"Elegija je tužaljka; ovdje je duhovita poanta.","D":"Epitaf je nadgrobni natpis; ovo je satirična dosjetka."},
  "2025_ljeto__35": {"A":"Retardacija (usporavanje) tipična je za ep, ne za sažetu novelu.","B":"Razgranata fabula obilježje je romana.","C":"Formulaičnost izraza svojstvena je usmenoj književnosti/bajci."},
  "2025_ljeto__36": {"A":"Renesansa slavi život i čovjeka; ovi stihovi naglašavaju prolaznost i smrt.","C":"Klasicizam ističe razum i sklad, ne baroknu opsjednutost smrću.","D":"Avangarda eksperimentira s formom; ovdje je barokna tema vanitas."},
  "2025_ljeto__37": {"B":"Gomilanje stilskih figura obilježje je baroka.","C":"Kultno značenje tragedije veže se uz antiku.","D":"Premještanje na maštu i osjećaje opisuje romantizam."},
  "2025_ljeto__38": {"B":"Marulić (Judita) pripada renesansi, nije kanonizirao roman u 19. st.","C":"Krleža je pisac 20. st. (drame, romani), ne tvorac povijesnog romana.","D":"Novak je realist, ali opis 'kanonizirao roman i odgojio publiku' odnosi se na Šenou."},
  "2025_ljeto__39": {"A":"Antigona poštuje jedinstva (jedno mjesto, dan, radnja).","B":"Gospoda Glembajevi drže jedinstvo mjesta i vremena (jedna noć, salon).","D":"Novela od Stanca je kompaktna jednočinka koja poštuje jedinstva."},
  "2025_ljeto__40": {"A":"Provjera sina kao vladara motiv je iz Calderónova 'Život je san'.","B":"Odbacivanje i smrt sina podsjeća na druga djela; ovdje je naglasak na očevoj političkoj nedosljednosti.","C":"Sužavanje psihološkog kruga i priznanje zločina je 'Zločin i kazna' (Raskoljnikov)."},
  "2025_ljeto__41": {"A":"Edip je iz prethodnog mita; on nije dao sahraniti Eteokla.","B":"Hemon je Kreontov sin i Antigonin zaručnik, ne onaj koji sahranjuje.","D":"Tiresija je prorok; ne donosi odluku o pokopu."},
  "2025_ljeto__42": {"A":"Fanny nije govornica ovih riječi.","B":"Vivijana nije lik iz ovog navoda.","C":"Princeza Stela ne izgovara ovu samoobranu."},
  "2025_ljeto__43": {"A":"Treba 'Sveti Martin na Muri' — prijedlog 'na' malim slovom.","B":"Treba 'Hrvatskome narodnom kazalištu' — samo prva riječ velikim.","C":"Treba 'Drugoga svjetskog rata' — povijesni događaj velikim slovom."},
  "2025_ljeto__44": {"B":"Pravilno je 'rječnička' (od rječnik), ne 'riječnička'.","C":"Pravilno je 'svjetlost' (kratki refleks jata), ne 'svijetlost'.","D":"Prema službenom ključu ova se inačica smatra netočnom; nedvojbeno je pravilan samo A."},
  "2025_ljeto__45": {"A":"'Slaže' je s+laže — nema alternacije k/g/h u č/ž/š.","B":"'Mužem' je muž+em; ž je u osnovi, nema palatalizacije.","D":"'Vožnje' je od 'voziti' (alternacija z→ž), nije palatalizacija."},
  "2025_ljeto__46": {"A":"'Iz svojih knjiga' = genitiv (iz + G), ne lokativ.","B":"'Svojim snovima' = dativ (vjerujem komu/čemu).","D":"'Svojim sposobnostima' = instrumental (nadmašila čime)."},
  "2025_ljeto__47": {"B":"'Liježući' nije standardni glagolski prilog.","C":"'Ležavši' nije pravilan oblik (nesvršeni glagol nema prilog prošli).","D":"'Legavši' je prilog prošli od svršenog 'leći', ne od 'ležati'."},
  "2025_ljeto__48": {"B":"'Manji' je komparativ pridjeva, ne prilog.","C":"'Zime' je imenica u genitivu.","D":"'Prije' je ovdje prijedlog (prije pojave), ne prilog."},
  "2025_ljeto__49": {"B":"Podcrtana riječ dio je priložne oznake mjesta ('duž ulice'), ne atribut.","C":"Podcrtana riječ je objekt ('ulice' uz 'upoznajući'), ne atribut.","D":"Podcrtana riječ je subjekt ('ulice' klicale), ne atribut."},
  "2025_ljeto__50": {"B":"'Vesna je Parun…' — umetnut glagol razbija ime = stilski obilježeno.","C":"Počinje priložnom oznakom ('Na otoku…') = topikalizacija, obilježeno.","D":"Počinje priložnom oznakom mjesta ('U Osnovnoj školi…') = obilježeno."},
  "2025_ljeto__51": {"A":"'kuda i svi idu' = načinsko-poredbena, ne mjesna.","B":"'da je odlazak bio uzbudljiv' = subjektna (priča se ŠTO).","C":"'Iako je bilo mračno' = dopusna (unatoč)."},
  "2025_ljeto__52": {"A":"'Čitateljstvo' je izvedeno od imenice 'čitatelj', ne izravno od glagola.","B":"'Dužnosnik' je od imenice 'dužnost'.","D":"'Sljepoća' je od pridjeva 'slijep'."},
  "2025_ljeto__53": {"A":"Egzonim je domaći naziv za strano zemljopisno ime (Beč), ne riječ od osobnog imena.","B":"Egzotizam označuje pojavu iz strane kulture (sari, iglu).","D":"Etnonim je naziv naroda (Hrvat), ne riječ od osobnog imena."},
  "2025_ljeto__54": {"A":"'Nekritičan' ne odgovara značenju 'bez milosti'.","C":"'Nepovjerljiv' (sumnjičav) nije značenje riječi 'nesmiljen'.","D":"'Neustrašiv' (hrabar) nije značenje riječi 'nesmiljen'."},
  "2025_ljeto__55": {"A":"'Pakao → nepodnošljive okolnosti' je metafora (sličnost), ne metonimija.","B":"'Paket → količina' bliže je sinegdohi/mjeri, ne metonimiji obilježja.","D":"'Plamen → zanos' je metafora (sličnost intenziteta)."},
  "2025_ljeto__56": {"A":"'Posuti se pepelom' = pokajati se, ne predati se.","C":"'Zakopati ratnu sjekiru' = pomiriti se.","D":"'Vaditi kestenje iz vatre' = obavljati opasan posao za drugoga."},
  "2025_ljeto__57": {"A":"Šenoa je književnik 19. st., nije reformirao grafiju.","B":"Kašić je napisao prvu hrvatsku gramatiku, nije uveo dijakritike.","C":"Vrančić je autor rječnika, ne reformator grafije."},
  "2025_ljeto__581": {"A":"'Cehovski' (vezan uz ceh) ne pristaje uz 'događaj za izdavaštvo'.","C":"'Cerebralni' (moždani) besmislen je u ovom kontekstu.","D":"'Ceremonijalni' (svečani) ne izražava središnjost kao 'centralni'."},
  "2025_ljeto__582": {"A":"'Dimenziju trendova' ne izražava kretanje/razvoj koji rečenica traži.","C":"'Dioništvo' (sudjelovanje u vlasništvu) ne pristaje.","D":"'Direktivu' (nalog) sajmovi ne 'određuju' u ovom smislu."},
  "2025_ljeto__583": {"A":"'Nakon toga' označava vrijeme/slijed, a ovdje se dodaje nova osobina.","B":"'Nasuprot tomu' uvodi suprotnost, a rečenica dodaje (ne suprotstavlja).","D":"'Usprkos tomu' uvodi dopuštanje/suprotnost, ne dodavanje."},
  "2025_ljeto__584": {"B":"'Vremeplov ideja' ne daje smisao izvora ideja.","C":"'Vreteno ideja' nije smislena metafora ovdje.","D":"'Vrh ideja' ne izražava izvor/nastanak kao 'vrelo'."},
  "2025_ljeto__585": {"A":"'Rukom o ruku' (zajedno) ne uvodi iskren zaključak.","C":"'Ruka ruku mije' (uzajamna korist) ne odgovara.","D":"'Rukama i nogama' (svom snagom) ne odgovara značenju iskrenosti."},
};

// Vrati mapu distraktora za pitanje, ili null.
export function getDistraktori(examKey, qid){
  if(examKey == null || qid == null) return null;
  return EXP_DISTRAKTORI[examKey + "__" + qid] || null;
}
